window.HSK_DATA["7-9-p1"] = [{"id":"变幻","hanzi":"变幻","pinyin":"biànhuàn","meaning_vi":"biến hóa khôn lường","explanation":"变 (đổi) + 幻 (ảo ảnh).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌪️","examples":[{"type":"basic","zh":"山里的天气变幻无常。","pinyin":"Shān lǐ de tiānqì biànhuàn wúcháng.","vi":"Thời tiết trên núi thay đổi thất thường."},{"type":"simple","zh":"傍晚的云彩在夕阳下变幻出各种颜色。","pinyin":"Bàngwǎn de yúncai zài xīyáng xià biànhuàn chū gèzhǒng yánsè.","vi":"Mây chiều biến hóa ra đủ mọi màu sắc dưới ánh hoàng hôn."},{"type":"compound","zh":"虽然市场行情变幻莫测，但是他始终坚持长期投资。","pinyin":"Suīrán shìchǎng hángqíng biànhuànmòcè, dànshì tā shǐzhōng jiānchí chángqī tóuzī.","vi":"Tuy tình hình thị trường biến hóa khôn lường nhưng anh ấy vẫn luôn kiên trì đầu tư dài hạn."}],"related":[{"hanzi":"变化","pinyin":"biànhuà","vi":"biến đổi"},{"hanzi":"变幻莫测","pinyin":"biànhuànmòcè","vi":"biến hóa khó lường"},{"hanzi":"风云变幻","pinyin":"fēngyúnbiànhuàn","vi":"thời cuộc biến động"},{"hanzi":"千变万化","pinyin":"qiānbiànwànhuà","vi":"thiên biến vạn hóa"}],"traditional":"變幻"},{"id":"遍及","hanzi":"遍及","pinyin":"biànjí","meaning_vi":"lan khắp, trải rộng tới","explanation":"遍 (khắp) + 及 (tới).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌐","examples":[{"type":"basic","zh":"他的足迹遍及全国。","pinyin":"Tā de zújì biànjí quánguó.","vi":"Dấu chân của anh ấy trải khắp cả nước."},{"type":"simple","zh":"这家连锁药店的分店已经遍及全省各个县城。","pinyin":"Zhè jiā liánsuǒ yàodiàn de fēndiàn yǐjīng biànjí quánshěng gègè xiànchéng.","vi":"Các chi nhánh của chuỗi nhà thuốc này đã phủ khắp mọi huyện lỵ trong tỉnh."},{"type":"compound","zh":"因为这场寒潮的影响遍及南北，所以很多航班都取消了。","pinyin":"Yīnwèi zhè cháng háncháo de yǐngxiǎng biànjí nánběi, suǒyǐ hěn duō hángbān dōu qǔxiāo le.","vi":"Vì ảnh hưởng của đợt rét này lan khắp cả nam lẫn bắc nên nhiều chuyến bay đã bị hủy."}],"related":[{"hanzi":"遍布","pinyin":"biànbù","vi":"phân bố khắp"},{"hanzi":"普及","pinyin":"pǔjí","vi":"phổ cập"},{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan đến"},{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"}]},{"id":"便民","hanzi":"便民","pinyin":"biànmín","meaning_vi":"tiện ích phục vụ người dân","explanation":"便 (thuận tiện) + 民 (dân). Cụm: 便民服务.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"社区开了一家便民超市。","pinyin":"Shèqū kāile yìjiā biànmín chāoshì.","vi":"Khu dân cư đã mở một siêu thị tiện ích phục vụ người dân."},{"type":"simple","zh":"街道在路口设了一个免费修伞的便民服务点。","pinyin":"Jiēdào zài lùkǒu shèle yí gè miǎnfèi xiū sǎn de biànmín fúwù diǎn.","vi":"Phường đã đặt ở ngã tư một điểm phục vụ người dân sửa ô miễn phí."},{"type":"compound","zh":"如果政府多推出这样的便民措施，老人办事就方便多了。","pinyin":"Rúguǒ zhèngfǔ duō tuīchū zhèyàng de biànmín cuòshī, lǎorén bànshì jiù fāngbiàn duō le.","vi":"Nếu chính quyền đưa ra thêm những biện pháp tiện dân như thế này thì người già đi làm thủ tục sẽ thuận tiện hơn nhiều."}],"related":[{"hanzi":"方便","pinyin":"fāngbiàn","vi":"tiện lợi"},{"hanzi":"便民服务","pinyin":"biànmínfúwù","vi":"dịch vụ tiện ích cho dân"},{"hanzi":"惠民","pinyin":"huìmín","vi":"làm lợi cho dân"},{"hanzi":"便利店","pinyin":"biànlìdiàn","vi":"cửa hàng tiện lợi"}]},{"id":"辨明","hanzi":"辨明","pinyin":"biànmíng","meaning_vi":"phân biệt rõ ràng (đúng sai)","explanation":"辨 (phân biệt) + 明 (rõ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"我们要辨明是非。","pinyin":"Wǒmen yào biànmíng shìfēi.","vi":"Chúng ta phải phân rõ đúng sai."},{"type":"simple","zh":"法官反复查看录像来辨明事故的责任方。","pinyin":"Fǎguān fǎnfù chákàn lùxiàng lái biànmíng shìgù de zérèn fāng.","vi":"Thẩm phán xem đi xem lại đoạn video để xác định rõ bên chịu trách nhiệm trong vụ tai nạn."},{"type":"compound","zh":"只要先辨明方向，我们就不会在森林里迷路。","pinyin":"Zhǐyào xiān biànmíng fāngxiàng, wǒmen jiù bú huì zài sēnlín lǐ mílù.","vi":"Chỉ cần xác định rõ phương hướng trước thì chúng ta sẽ không bị lạc trong rừng."}],"related":[{"hanzi":"辨别","pinyin":"biànbié","vi":"phân biệt"},{"hanzi":"分辨","pinyin":"fēnbiàn","vi":"phân biện"},{"hanzi":"明辨是非","pinyin":"míngbiànshìfēi","vi":"phân rõ phải trái"},{"hanzi":"识别","pinyin":"shíbié","vi":"nhận biết"}]},{"id":"变通","hanzi":"变通","pinyin":"biàntōng","meaning_vi":"linh hoạt ứng biến, không cứng nhắc","explanation":"变 + 通 (thông suốt).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"🔄","examples":[{"type":"basic","zh":"做事要懂得变通。","pinyin":"Zuòshì yào dǒngde biàntōng.","vi":"Làm việc phải biết linh hoạt."},{"type":"simple","zh":"经理同意变通一下，让我下周再交报告。","pinyin":"Jīnglǐ tóngyì biàntōng yíxià, ràng wǒ xiàzhōu zài jiāo bàogào.","vi":"Giám đốc đồng ý linh động một chút, cho tôi tuần sau mới nộp báo cáo."},{"type":"compound","zh":"规定虽然很严格，但是遇到特殊情况也可以适当变通。","pinyin":"Guīdìng suīrán hěn yángé, dànshì yùdào tèshū qíngkuàng yě kěyǐ shìdàng biàntōng.","vi":"Quy định tuy rất nghiêm nhưng gặp trường hợp đặc biệt cũng có thể linh động cho phù hợp."}],"related":[{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"通融","pinyin":"tōngróng","vi":"châm chước"},{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"死板","pinyin":"sǐbǎn","vi":"cứng nhắc"}],"traditional":"變通"},{"id":"辩证法","hanzi":"辩证法","pinyin":"biànzhèngfǎ","meaning_vi":"phép biện chứng (triết học)","explanation":"辩证 + 法 (phương pháp).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","khoa-hoc"],"image":"🧠","examples":[{"type":"basic","zh":"他在大学研究辩证法。","pinyin":"Tā zài dàxué yánjiū biànzhèngfǎ.","vi":"Anh ấy nghiên cứu phép biện chứng ở trường đại học."},{"type":"simple","zh":"老师用塞翁失马的故事给我们讲解辩证法。","pinyin":"Lǎoshī yòng sàiwēngshīmǎ de gùshi gěi wǒmen jiǎngjiě biànzhèngfǎ.","vi":"Thầy giáo dùng câu chuyện \"Tái ông mất ngựa\" để giảng cho chúng tôi về phép biện chứng."},{"type":"compound","zh":"如果懂一点辩证法，你就会明白坏事有时也能变成好事。","pinyin":"Rúguǒ dǒng yìdiǎn biànzhèngfǎ, nǐ jiù huì míngbai huàishì yǒushí yě néng biànchéng hǎoshì.","vi":"Nếu hiểu một chút phép biện chứng, bạn sẽ hiểu rằng chuyện xấu đôi khi cũng có thể thành chuyện tốt."}],"related":[{"hanzi":"唯物主义","pinyin":"wéiwùzhǔyì","vi":"chủ nghĩa duy vật"},{"hanzi":"哲学","pinyin":"zhéxué","vi":"triết học"},{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"辩证","pinyin":"biànzhèng","vi":"biện chứng"}],"traditional":"辯證法"},{"id":"别具匠心","hanzi":"别具匠心","pinyin":"biéjù-jiàngxīn","meaning_vi":"có sự sáng tạo tinh xảo độc đáo","explanation":"别具匠心: riêng (别) có (具) cái tâm của người thợ (匠心) → có sự sáng tạo khéo léo, độc đáo trong nghệ thuật hay thiết kế.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"这座花园的设计别具匠心。","pinyin":"Zhè zuò huāyuán de shèjì biéjùjiàngxīn.","vi":"Thiết kế của khu vườn này thật tinh xảo, độc đáo."},{"type":"simple","zh":"设计师别具匠心地把旧厂房改造成了书店。","pinyin":"Shèjìshī biéjùjiàngxīn de bǎ jiù chǎngfáng gǎizào chéngle shūdiàn.","vi":"Nhà thiết kế đã khéo léo, sáng tạo cải tạo nhà xưởng cũ thành một hiệu sách."},{"type":"compound","zh":"这本相册不但封面别具匠心，而且每一页都有手写的留言。","pinyin":"Zhè běn xiàngcè búdàn fēngmiàn biéjùjiàngxīn, érqiě měi yí yè dōu yǒu shǒuxiě de liúyán.","vi":"Cuốn album này không chỉ có bìa được thiết kế độc đáo mà mỗi trang còn có lời nhắn viết tay."}],"related":[{"hanzi":"独具匠心","pinyin":"dújùjiàngxīn","vi":"có ý tưởng độc đáo"},{"hanzi":"匠心独运","pinyin":"jiàngxīndúyùn","vi":"khéo léo sáng tạo"},{"hanzi":"别出心裁","pinyin":"biéchūxīncái","vi":"độc đáo khác người"},{"hanzi":"精巧","pinyin":"jīngqiǎo","vi":"tinh xảo"}],"traditional":"別具匠心"},{"id":"别开生面","hanzi":"别开生面","pinyin":"biékāi-shēngmiàn","meaning_vi":"mở ra một phong cách mới mẻ độc đáo","explanation":"别开生面: riêng (别) mở ra (开) một bộ mặt (面) mới mẻ (生) → mở ra phong cách, hình thức mới lạ, khác hẳn trước đây. Ví dụ: 别开生面的晚会.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎨","examples":[{"type":"basic","zh":"这场婚礼别开生面。","pinyin":"Zhè chǎng hūnlǐ biékāishēngmiàn.","vi":"Đám cưới này thật mới mẻ, độc đáo."},{"type":"simple","zh":"学校举办了一次别开生面的户外数学课。","pinyin":"Xuéxiào jǔbànle yí cì biékāishēngmiàn de hùwài shùxué kè.","vi":"Nhà trường tổ chức một buổi học toán ngoài trời đầy mới lạ."},{"type":"compound","zh":"因为这次发布会别开生面，所以吸引了大批年轻观众。","pinyin":"Yīnwèi zhè cì fābùhuì biékāishēngmiàn, suǒyǐ xīyǐnle dàpī niánqīng guānzhòng.","vi":"Vì buổi ra mắt lần này rất mới mẻ, độc đáo nên đã thu hút đông đảo khán giả trẻ."}],"related":[{"hanzi":"别出心裁","pinyin":"biéchūxīncái","vi":"độc đáo khác người"},{"hanzi":"新颖","pinyin":"xīnyǐng","vi":"mới lạ"},{"hanzi":"独树一帜","pinyin":"dúshùyízhì","vi":"tạo phong cách riêng"},{"hanzi":"千篇一律","pinyin":"qiānpiānyílǜ","vi":"rập khuôn"}],"traditional":"別開生面"},{"id":"别无选择","hanzi":"别无选择","pinyin":"biéwú-xuǎnzé","meaning_vi":"không còn lựa chọn nào khác","explanation":"别 (biệt – khác) 无 (vô – không có) 选择 (tuyển trạch – lựa chọn) → không còn lựa chọn nào khác, buộc phải làm vậy.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤷","examples":[{"type":"basic","zh":"我们已经别无选择。","pinyin":"Wǒmen yǐjīng biéwúxuǎnzé.","vi":"Chúng ta đã không còn lựa chọn nào khác."},{"type":"simple","zh":"面对洪水，村民们别无选择地撤离了家园。","pinyin":"Miànduì hóngshuǐ, cūnmínmen biéwúxuǎnzé de chèlíle jiāyuán.","vi":"Trước cơn lũ, dân làng buộc phải rời bỏ nhà cửa vì không còn lựa chọn nào khác."},{"type":"compound","zh":"既然公司已经倒闭了，他就别无选择，只能重新找工作。","pinyin":"Jìrán gōngsī yǐjīng dǎobì le, tā jiù biéwúxuǎnzé, zhǐnéng chóngxīn zhǎogōngzuò.","vi":"Vì công ty đã phá sản nên anh ấy không còn lựa chọn nào khác, chỉ có thể tìm việc mới."}],"related":[{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"đành chịu"},{"hanzi":"迫不得已","pinyin":"pòbùdéyǐ","vi":"bất đắc dĩ"},{"hanzi":"别无他法","pinyin":"biéwútāfǎ","vi":"không còn cách nào"},{"hanzi":"选择","pinyin":"xuǎnzé","vi":"lựa chọn"}],"traditional":"別無選擇"},{"id":"编导","hanzi":"编导","pinyin":"biāndǎo","meaning_vi":"biên đạo, đạo diễn chương trình","explanation":"编 (biên – biên soạn) + 导 (đạo – chỉ đạo, đạo diễn) → vừa biên kịch vừa đạo diễn; người biên đạo múa, kịch, chương trình.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","giai-tri"],"image":"🎥","examples":[{"type":"basic","zh":"她是这部舞剧的编导。","pinyin":"Tā shì zhè bù wǔjù de biāndǎo.","vi":"Cô ấy là biên đạo của vở vũ kịch này."},{"type":"simple","zh":"这位编导花了三个月筹备春节晚会的开场节目。","pinyin":"Zhè wèi biāndǎo huāle sān gèyuè chóubèi Chūnjié wǎnhuì de kāichǎng jiémù.","vi":"Vị biên đạo này đã mất ba tháng chuẩn bị tiết mục mở màn cho đêm hội mừng xuân."},{"type":"compound","zh":"虽然他是第一次担任编导，但是作品获得了观众的好评。","pinyin":"Suīrán tā shì dìyīcì dānrèn biāndǎo, dànshì zuòpǐn huòdéle guānzhòng de hǎopíng.","vi":"Tuy là lần đầu đảm nhận vai trò biên đạo nhưng tác phẩm của anh ấy đã được khán giả khen ngợi."}],"related":[{"hanzi":"导演","pinyin":"dǎoyǎn","vi":"đạo diễn"},{"hanzi":"编剧","pinyin":"biānjù","vi":"biên kịch"},{"hanzi":"编排","pinyin":"biānpái","vi":"dàn dựng"},{"hanzi":"舞蹈","pinyin":"wǔdǎo","vi":"múa"}],"traditional":"編導"},{"id":"边际","hanzi":"边际","pinyin":"biānjì","meaning_vi":"ranh giới, bờ bến, cận biên (kinh tế học)","explanation":"边 (bên rìa) + 际 (giới hạn). Cụm: 边际效应.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"📊","examples":[{"type":"basic","zh":"他说话总是不着边际。","pinyin":"Tā shuōhuà zǒngshì bùzhuó biānjì.","vi":"Anh ta nói chuyện lúc nào cũng chẳng đâu vào đâu."},{"type":"simple","zh":"经济学课上老师讲解了边际成本的概念。","pinyin":"Jīngjìxué kè shàng lǎoshī jiǎngjiěle biānjì chéngběn de gàiniàn.","vi":"Trong giờ kinh tế học, thầy giáo giảng giải khái niệm chi phí cận biên."},{"type":"compound","zh":"当产量超过一定规模时，边际收益就会开始下降。","pinyin":"Dāng chǎnliàng chāoguò yídìng guīmó shí, biānjì shōuyì jiù huì kāishǐ xiàjiàng.","vi":"Khi sản lượng vượt quá một quy mô nhất định, lợi ích cận biên sẽ bắt đầu giảm."}],"related":[{"hanzi":"无边无际","pinyin":"wúbiānwújì","vi":"mênh mông vô tận"},{"hanzi":"边界","pinyin":"biānjiè","vi":"biên giới"},{"hanzi":"边际效应","pinyin":"biānjìxiàoyìng","vi":"hiệu ứng cận biên"},{"hanzi":"不着边际","pinyin":"bùzhuóbiānjì","vi":"chẳng ăn nhập gì"}],"traditional":"邊際"},{"id":"编剧","hanzi":"编剧","pinyin":"biānjù","meaning_vi":"biên kịch","explanation":"编 (编) + 剧 (kịch/dữ dội).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"他是一名电视剧编剧。","pinyin":"Tā shì yì míng diànshìjù biānjù.","vi":"Anh ấy là một biên kịch phim truyền hình."},{"type":"simple","zh":"这部电影的编剧亲自到渔村生活了半年。","pinyin":"Zhè bù diànyǐng de biānjù qīnzì dào yú cūn shēnghuóle bàn nián.","vi":"Biên kịch của bộ phim này đã đích thân đến sống ở làng chài nửa năm."},{"type":"compound","zh":"如果编剧不了解医院的工作，就很难写好医疗剧。","pinyin":"Rúguǒ biānjù bù liǎojiě yīyuàn de gōngzuò, jiù hěn nán xiě hǎo yīliáo jù.","vi":"Nếu biên kịch không hiểu công việc ở bệnh viện thì rất khó viết tốt phim đề tài y khoa."}],"related":[{"hanzi":"剧本","pinyin":"jùběn","vi":"kịch bản"},{"hanzi":"导演","pinyin":"dǎoyǎn","vi":"đạo diễn"},{"hanzi":"编导","pinyin":"biāndǎo","vi":"biên đạo"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"}],"traditional":"編劇"},{"id":"鞭炮声","hanzi":"鞭炮声","pinyin":"biānpàoshēng","meaning_vi":"tiếng pháo nổ","explanation":"鞭炮 (tiên pháo – pháo dây, dài như roi) + 声 (thanh – tiếng) → tiếng pháo nổ, gắn với Tết, cưới hỏi, khai trương.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧨","examples":[{"type":"basic","zh":"窗外鞭炮声不断。","pinyin":"Chuāng wài biānpàoshēng búduàn.","vi":"Ngoài cửa sổ tiếng pháo nổ không ngớt."},{"type":"simple","zh":"除夕夜十二点，整个小镇响起了鞭炮声。","pinyin":"Chúxīyè shí'èr diǎn, zhěnggè xiǎozhèn xiǎngqǐle biānpàoshēng.","vi":"Đúng mười hai giờ đêm giao thừa, cả thị trấn nhỏ vang lên tiếng pháo."},{"type":"compound","zh":"一听到鞭炮声，小狗就吓得躲到了床底下。","pinyin":"Yì tīngdào biānpàoshēng, xiǎogǒu jiù xià de duǒ dàole chuáng dǐxia.","vi":"Vừa nghe tiếng pháo, chú chó nhỏ đã sợ hãi trốn xuống gầm giường."}],"related":[{"hanzi":"鞭炮","pinyin":"biānpào","vi":"pháo"},{"hanzi":"放鞭炮","pinyin":"fàngbiānpào","vi":"đốt pháo"},{"hanzi":"烟花","pinyin":"yānhuā","vi":"pháo hoa"},{"hanzi":"爆竹","pinyin":"bàozhú","vi":"pháo trúc"}],"traditional":"鞭炮聲"},{"id":"编排","hanzi":"编排","pinyin":"biānpái","meaning_vi":"dàn dựng, biên đạo, sắp xếp chương trình","explanation":"编 (soạn) + 排 (xếp).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"节目编排得很紧凑。","pinyin":"Jiémù biānpái de hěn jǐncòu.","vi":"Chương trình được sắp xếp rất chặt chẽ."},{"type":"simple","zh":"舞蹈老师为孩子们编排了一支茶艺主题的舞蹈。","pinyin":"Wǔdǎo lǎoshī wèi háizimen biānpáile yì zhī cháyì zhǔtí de wǔdǎo.","vi":"Cô giáo dạy múa đã dàn dựng cho các em một điệu múa chủ đề trà nghệ."},{"type":"compound","zh":"只要节目编排合理，三个小时的晚会也不会让人觉得累。","pinyin":"Zhǐyào jiémù biānpái hélǐ, sān gè xiǎoshí de wǎnhuì yě bú huì ràng rén juéde lèi.","vi":"Chỉ cần các tiết mục được sắp xếp hợp lý thì đêm diễn ba tiếng cũng không khiến người xem thấy mệt."}],"related":[{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"},{"hanzi":"编导","pinyin":"biāndǎo","vi":"biên đạo"},{"hanzi":"排练","pinyin":"páiliàn","vi":"tập dượt"},{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập"}],"traditional":"編排"},{"id":"编写","hanzi":"编写","pinyin":"biānxiě","meaning_vi":"biên soạn, viết (sách giáo khoa/chương trình)","explanation":"编 (biên – sắp xếp, soạn) + 写 (tả – viết) → biên soạn, viết sách, giáo trình, chương trình máy tính. Cụm: 编写教材.","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"他编写了一本教材。","pinyin":"Tā biānxiěle yì běn jiàocái.","vi":"Ông ấy đã biên soạn một cuốn giáo trình."},{"type":"simple","zh":"程序员用了一个周末编写这个记账小程序。","pinyin":"Chéngxùyuán yòngle yí gè zhōumò biānxiě zhè ge jìzhàng xiǎo chéngxù.","vi":"Lập trình viên dùng một cuối tuần để viết ứng dụng ghi chép chi tiêu nhỏ này."},{"type":"compound","zh":"因为教材是一线老师编写的，所以例子都很贴近课堂。","pinyin":"Yīnwèi jiàocái shì yíxiàn lǎoshī biānxiě de, suǒyǐ lìzi dōu hěn tiējìn kètáng.","vi":"Vì giáo trình do các giáo viên đứng lớp biên soạn nên các ví dụ đều rất sát với lớp học."}],"related":[{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập"},{"hanzi":"编纂","pinyin":"biānzuǎn","vi":"biên soạn"},{"hanzi":"撰写","pinyin":"zhuànxiě","vi":"viết soạn"},{"hanzi":"教材","pinyin":"jiàocái","vi":"giáo trình"}],"traditional":"編寫"},{"id":"边缘化","hanzi":"边缘化","pinyin":"biānyuánhuà","meaning_vi":"đẩy ra bên lề, làm mất vai trò","explanation":"边 (bên) + 缘 (duyên phận/nguyên cớ) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📐","examples":[{"type":"basic","zh":"他在公司被边缘化了。","pinyin":"Tā zài gōngsī bèi biānyuánhuà le.","vi":"Anh ấy bị gạt ra rìa trong công ty."},{"type":"simple","zh":"很多传统手艺正在被现代生活逐渐边缘化。","pinyin":"Hěn duō chuántǒng shǒuyì zhèngzài bèi xiàndài shēnghuó zhújiàn biānyuánhuà.","vi":"Nhiều nghề thủ công truyền thống đang dần bị cuộc sống hiện đại đẩy ra bên lề."},{"type":"compound","zh":"如果老年人不会用智能手机，就容易在数字时代被边缘化。","pinyin":"Rúguǒ lǎoniánrén bú huì yòng zhìnéng shǒujī, jiù róngyì zài shùzì shídài bèi biānyuánhuà.","vi":"Nếu người cao tuổi không biết dùng điện thoại thông minh thì dễ bị gạt ra lề trong thời đại số."}],"related":[{"hanzi":"边缘","pinyin":"biānyuán","vi":"bên lề"},{"hanzi":"排斥","pinyin":"páichì","vi":"bài xích"},{"hanzi":"孤立","pinyin":"gūlì","vi":"cô lập"},{"hanzi":"主流","pinyin":"zhǔliú","vi":"dòng chính"}],"traditional":"邊緣化"},{"id":"编译","hanzi":"编译","pinyin":"biānyì","meaning_vi":"biên dịch (mã nguồn); biên dịch, dịch và biên tập (tài liệu)","explanation":"编 (biên – biên tập) + 译 (dịch) → biên tập kèm dịch thuật; trong tin học là dịch mã nguồn. Cụm: 编译器 (trình biên dịch).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"代码编译成功了。","pinyin":"Dàimǎ biānyì chénggōng le.","vi":"Mã nguồn đã biên dịch thành công."},{"type":"simple","zh":"新电脑编译这个大型项目只需要两分钟。","pinyin":"Xīn diànnǎo biānyì zhè ge dàxíng xiàngmù zhǐ xūyào liǎng fēnzhōng.","vi":"Máy tính mới biên dịch dự án lớn này chỉ mất hai phút."},{"type":"compound","zh":"一旦编译时出现错误，程序就无法正常运行。","pinyin":"Yídàn biānyì shí chūxiàn cuòwù, chéngxù jiù wúfǎ zhèngcháng yùnxíng.","vi":"Một khi xảy ra lỗi lúc biên dịch thì chương trình sẽ không thể chạy bình thường."}],"related":[{"hanzi":"翻译","pinyin":"fānyì","vi":"dịch thuật"},{"hanzi":"编程","pinyin":"biānchéng","vi":"lập trình"},{"hanzi":"编译器","pinyin":"biānyìqì","vi":"trình biên dịch"},{"hanzi":"代码","pinyin":"dàimǎ","vi":"mã nguồn"}],"traditional":"編譯"},{"id":"编纂","hanzi":"编纂","pinyin":"biānzuǎn","meaning_vi":"biên soạn (từ điển/sử sách)","explanation":"编 (编) + 纂 (biên soạn).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他们正在编纂县志。","pinyin":"Tāmen zhèngzài biānzuǎn xiànzhì.","vi":"Họ đang biên soạn địa chí của huyện."},{"type":"simple","zh":"清朝学者花了十几年编纂四库全书。","pinyin":"Qīngcháo xuézhě huāle shíjǐ nián biānzuǎn Sìkùquánshū.","vi":"Các học giả triều Thanh đã mất hơn mười năm để biên soạn bộ Tứ khố toàn thư."},{"type":"compound","zh":"编纂一部大词典不仅需要大量人力，而且要花上几十年。","pinyin":"Biānzuǎn yí bù dà cídiǎn bùjǐn xūyào dàliàng rénlì, érqiě yào huā shàng jǐ shí nián.","vi":"Biên soạn một bộ đại từ điển không chỉ cần nhiều nhân lực mà còn phải mất mấy chục năm."}],"related":[{"hanzi":"编写","pinyin":"biānxiě","vi":"biên soạn"},{"hanzi":"词典","pinyin":"cídiǎn","vi":"từ điển"},{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập"},{"hanzi":"修订","pinyin":"xiūdìng","vi":"sửa đổi"}],"traditional":"編纂"},{"id":"标榜","hanzi":"标榜","pinyin":"biāobǎng","meaning_vi":"tự đề cao, khoe khoang danh hiệu","explanation":"标 + 榜 (bảng vàng).","hsk_level":"7-9","tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"他总爱标榜自己。","pinyin":"Tā zǒng ài biāobǎng zìjǐ.","vi":"Anh ta luôn thích tự đề cao bản thân."},{"type":"simple","zh":"这家餐厅标榜所有食材都来自有机农场。","pinyin":"Zhè jiā cāntīng biāobǎng suǒyǒu shícái dōu láizì yǒujī nóngchǎng.","vi":"Nhà hàng này rêu rao rằng mọi nguyên liệu đều đến từ trang trại hữu cơ."},{"type":"compound","zh":"虽然这款产品标榜纯天然，但是成分表里有很多添加剂。","pinyin":"Suīrán zhè kuǎn chǎnpǐn biāobǎng chúntiānrán, dànshì chéngfèn biǎolǐ yǒu hěn duō tiānjiājì.","vi":"Tuy sản phẩm này tự quảng cáo là hoàn toàn tự nhiên nhưng bảng thành phần lại có rất nhiều chất phụ gia."}],"related":[{"hanzi":"吹嘘","pinyin":"chuīxū","vi":"khoác lác"},{"hanzi":"自我标榜","pinyin":"zìwǒbiāobǎng","vi":"tự đề cao mình"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"},{"hanzi":"宣扬","pinyin":"xuānyáng","vi":"tuyên truyền"}],"traditional":"標榜"},{"id":"标配","hanzi":"标配","pinyin":"biāopèi","meaning_vi":"cấu hình tiêu chuẩn, trang bị mặc định","explanation":"标 (tiêu chuẩn) + 配 (phối hợp).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"⚙️","examples":[{"type":"basic","zh":"这款车标配天窗。","pinyin":"Zhè kuǎn chē biāopèi tiānchuāng.","vi":"Mẫu xe này có cửa sổ trời là trang bị tiêu chuẩn."},{"type":"simple","zh":"如今快充功能几乎成了智能手机的标配。","pinyin":"Rújīn kuàichōng gōngnéng jīhū chéngle zhìnéng shǒujī de biāopèi.","vi":"Ngày nay sạc nhanh gần như đã trở thành trang bị tiêu chuẩn của điện thoại thông minh."},{"type":"compound","zh":"如果倒车影像不是标配，就要多花钱另外加装。","pinyin":"Rúguǒ dàochē yǐngxiàng bú shì biāopèi, jiùyào duō huāqián lìng wàijiā zhuāng.","vi":"Nếu camera lùi không phải trang bị tiêu chuẩn thì phải tốn thêm tiền lắp riêng."}],"related":[{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"配置","pinyin":"pèizhì","vi":"cấu hình"},{"hanzi":"高配","pinyin":"gāopèi","vi":"cấu hình cao"},{"hanzi":"选配","pinyin":"xuǎnpèi","vi":"trang bị tùy chọn"}],"traditional":"標配"},{"id":"憋屈","hanzi":"憋屈","pinyin":"biēqu","meaning_vi":"ấm ức, ngột ngạt khó chịu","explanation":"憋 (nén) + 屈 (khuất tất).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😣","examples":[{"type":"basic","zh":"他心里特别憋屈。","pinyin":"Tā xīnlǐ tèbié biēqu.","vi":"Trong lòng anh ấy vô cùng ấm ức."},{"type":"simple","zh":"被抢了功劳的她憋屈了好几天。","pinyin":"Bèi qiǎngle gōngláo de tā biēqule hǎo jǐtiān.","vi":"Bị người khác cướp công, cô ấy ấm ức mấy ngày liền."},{"type":"compound","zh":"与其一个人憋屈着，不如找朋友把话说出来。","pinyin":"Yǔqí yígèrén biēqu zhe, bùrú zhǎo péngyou bǎ huàshuō chūlái.","vi":"Thay vì một mình ôm nỗi ấm ức, chi bằng tìm bạn bè nói hết ra."}],"related":[{"hanzi":"委屈","pinyin":"wěiqu","vi":"tủi thân"},{"hanzi":"窝囊","pinyin":"wōnang","vi":"bực bội ấm ức"},{"hanzi":"憋气","pinyin":"biēqì","vi":"nín thở ấm ức"},{"hanzi":"郁闷","pinyin":"yùmèn","vi":"buồn bực"}]},{"id":"表述","hanzi":"表述","pinyin":"biǎoshù","meaning_vi":"diễn đạt, trình bày","explanation":"表 (bày tỏ) + 述 (kể).","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"他的表述很清楚。","pinyin":"Tā de biǎoshù hěn qīngchu.","vi":"Cách trình bày của anh ấy rất rõ ràng."},{"type":"simple","zh":"律师建议他修改合同里含糊的表述。","pinyin":"Lǜshī jiànyì tā xiūgǎi hétong lǐ hánhu de biǎoshù.","vi":"Luật sư khuyên anh ấy sửa những cách diễn đạt mơ hồ trong hợp đồng."},{"type":"compound","zh":"虽然他的观点没错，但是表述方式容易引起误会。","pinyin":"Suīrán tā de guāndiǎn méicuò, dànshì biǎoshù fāngshì róngyì yǐnqǐ wùhuì.","vi":"Tuy quan điểm của anh ấy không sai nhưng cách diễn đạt lại dễ gây hiểu lầm."}],"related":[{"hanzi":"表达","pinyin":"biǎodá","vi":"biểu đạt"},{"hanzi":"陈述","pinyin":"chénshù","vi":"trình bày"},{"hanzi":"叙述","pinyin":"xùshù","vi":"tường thuật"},{"hanzi":"描述","pinyin":"miáoshù","vi":"miêu tả"}]},{"id":"表象","hanzi":"表象","pinyin":"biǎoxiàng","meaning_vi":"hiện tượng bề ngoài, biểu tượng tâm lý","explanation":"表 (bề ngoài) + 象 (hình ảnh).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🪞","examples":[{"type":"basic","zh":"不要被表象迷惑。","pinyin":"Bú yào bèi biǎoxiàng míhuò.","vi":"Đừng để vẻ bề ngoài đánh lừa."},{"type":"simple","zh":"医生透过发烧的表象找到了真正的病因。","pinyin":"Yīshēng tòuguò fāshāo de biǎoxiàng zhǎodàole zhēnzhèng de bìngyīn.","vi":"Bác sĩ nhìn xuyên qua biểu hiện sốt bên ngoài để tìm ra nguyên nhân gây bệnh thực sự."},{"type":"compound","zh":"虽然他笑得很轻松，但是那只是表象而已。","pinyin":"Suīrán tā xiào de hěn qīngsōng, dànshì nà zhǐshì biǎoxiàng éryǐ.","vi":"Tuy anh ấy cười rất thoải mái nhưng đó chỉ là vẻ bề ngoài mà thôi."}],"related":[{"hanzi":"现象","pinyin":"xiànxiàng","vi":"hiện tượng"},{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"假象","pinyin":"jiǎxiàng","vi":"giả tượng"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"}]},{"id":"拜师","hanzi":"拜师","pinyin":"bàishī","meaning_vi":"bái sư, nhận thầy học nghề","explanation":"拜 (lạy) + 师 (thầy). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","van-hoa","hoc-tap"],"image":"🙇","examples":[{"type":"basic","zh":"他拜师学京剧。","pinyin":"Tā bàishī xué Jīngjù.","vi":"Anh ấy bái sư học kinh kịch."},{"type":"simple","zh":"十五岁那年她去苏州拜师学刺绣。","pinyin":"Shíwǔ suì nà nián tā qù Sūzhōu bàishī xué cìxiù.","vi":"Năm mười lăm tuổi, cô ấy đến Tô Châu bái sư học thêu."},{"type":"compound","zh":"只要真心拜师学艺，老师傅就会把手艺传给你。","pinyin":"Zhǐyào zhēnxīn bàishī xuéyì, lǎo shīfu jiù huì bǎ shǒuyì chuángěi nǐ.","vi":"Chỉ cần thật lòng bái sư học nghề thì người thầy già sẽ truyền tay nghề cho bạn."}],"related":[{"hanzi":"师傅","pinyin":"shīfu","vi":"sư phụ"},{"hanzi":"徒弟","pinyin":"túdì","vi":"đồ đệ"},{"hanzi":"学艺","pinyin":"xuéyì","vi":"học nghề"},{"hanzi":"出师","pinyin":"chūshī","vi":"ra nghề"}],"traditional":"拜師"},{"id":"半壁江山","hanzi":"半壁江山","pinyin":"bànbì-jiāngshān","meaning_vi":"một nửa giang sơn, một nửa thị phần/lực lượng","explanation":"半壁 (bán bích – một nửa) + 江山 (giang sơn) → nửa đất nước; nay chỉ một nửa thị phần, lực lượng. Cụm: 占据半壁江山.","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🗺️","examples":[{"type":"basic","zh":"新能源车占了半壁江山。","pinyin":"Xīnnéngyuán chē zhànle bànbìjiāngshān.","vi":"Xe năng lượng mới đã chiếm một nửa thị trường."},{"type":"simple","zh":"这家公司在国内市场已经占据了半壁江山。","pinyin":"Zhè jiā gōngsī zài guónèi shìchǎng yǐjīng zhànjùle bànbìjiāngshān.","vi":"Công ty này đã chiếm một nửa thị phần trong nước."},{"type":"compound","zh":"两名主力一受伤，球队的半壁江山就没了。","pinyin":"Liǎng míng zhǔlì yí shòushāng, qiúduì de bànbìjiāngshān jiù méile.","vi":"Hai cầu thủ chủ lực vừa bị thương, đội bóng liền mất đi một nửa lực lượng."}],"related":[{"hanzi":"江山","pinyin":"jiāngshān","vi":"giang sơn"},{"hanzi":"一半","pinyin":"yíbàn","vi":"một nửa"},{"hanzi":"份额","pinyin":"fèn'é","vi":"thị phần"},{"hanzi":"天下","pinyin":"tiānxià","vi":"thiên hạ"}]},{"id":"半导体","hanzi":"半导体","pinyin":"bàndǎotǐ","meaning_vi":"chất bán dẫn","explanation":"半 (một nửa) + 导 (导) + 体 (thể hiện/hệ thống).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"手机芯片离不开半导体。","pinyin":"Shǒujī xīnpiàn líbukāi bàndǎotǐ.","vi":"Chip điện thoại không thể thiếu chất bán dẫn."},{"type":"simple","zh":"他毕业后进了一家半导体工厂做工程师。","pinyin":"Tā bìyè hòujìnle yìjiā bàndǎotǐ gōngchǎng zuò gōngchéngshī.","vi":"Sau khi tốt nghiệp, anh ấy vào làm kỹ sư ở một nhà máy bán dẫn."},{"type":"compound","zh":"因为全球半导体供应紧张，所以汽车交货时间推迟了。","pinyin":"Yīnwèi quánqiú bàndǎotǐ gōngyìng jǐnzhāng, suǒyǐ qìchē jiāohuò shíjiān tuīchí le.","vi":"Vì nguồn cung chất bán dẫn toàn cầu khan hiếm nên thời gian giao xe ô tô bị lùi lại."}],"related":[{"hanzi":"导体","pinyin":"dǎotǐ","vi":"chất dẫn điện"},{"hanzi":"芯片","pinyin":"xīnpiàn","vi":"chip"},{"hanzi":"电子","pinyin":"diànzǐ","vi":"điện tử"},{"hanzi":"绝缘体","pinyin":"juéyuántǐ","vi":"chất cách điện"}],"traditional":"半導體"},{"id":"半斤八两","hanzi":"半斤八两","pinyin":"bànjīn-bāliǎng","meaning_vi":"kẻ tám lạng người nửa cân (ngang nhau)","explanation":"半斤 (nửa cân = 8 lạng) + 八两. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他们俩的棋艺半斤八两。","pinyin":"Tāmen liǎ de qíyì bànjīnbāliǎng.","vi":"Tài đánh cờ của hai người họ ngang nhau."},{"type":"simple","zh":"这两家外卖店的服务态度半斤八两。","pinyin":"Zhè liǎng jiā wàimài diàn de fúwù tàidu bànjīnbāliǎng.","vi":"Thái độ phục vụ của hai quán đồ ăn mang đi này cũng chẳng hơn kém gì nhau."},{"type":"compound","zh":"你别笑话他了，你们俩的英语水平其实半斤八两。","pinyin":"Nǐ bié xiàohua tā le, nǐmen liǎ de Yīngyǔ shuǐpíng qíshí bànjīnbāliǎng.","vi":"Cậu đừng chê cười cậu ấy nữa, trình độ tiếng Anh của hai cậu thật ra kẻ tám lạng người nửa cân."}],"related":[{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang ngửa nhau"},{"hanzi":"旗鼓相当","pinyin":"qígǔxiāngdāng","vi":"ngang tài ngang sức"},{"hanzi":"差不多","pinyin":"chàbuduō","vi":"xấp xỉ"},{"hanzi":"天壤之别","pinyin":"tiānrǎngzhībié","vi":"khác nhau một trời một vực"}],"traditional":"半斤八兩"},{"id":"半晌","hanzi":"半晌","pinyin":"bànshǎng","meaning_vi":"nửa buổi, một lúc lâu","explanation":"半 (một nửa) + 晌 (buổi/khoảng thời gian).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"他愣了半晌才回答。","pinyin":"Tā lèngle bànshǎng cái huídá.","vi":"Anh ấy ngẩn người một lúc lâu mới trả lời."},{"type":"simple","zh":"老人站在旧房子门前看了半晌。","pinyin":"Lǎorén zhàn zài jiù fángzi ménqián kànle bànshǎng.","vi":"Ông lão đứng trước cửa ngôi nhà cũ nhìn hồi lâu."},{"type":"compound","zh":"她拿着那封信沉默了半晌，然后才慢慢开口说话。","pinyin":"Tā názhe nà fēng xìn chénmòle bànshǎng, ránhòu cái mànmàn kāikǒu shuōhuà.","vi":"Cô ấy cầm lá thư im lặng hồi lâu, rồi mới từ từ cất lời."}],"related":[{"hanzi":"半天","pinyin":"bàntiān","vi":"nửa ngày"},{"hanzi":"好半天","pinyin":"hǎobàntiān","vi":"một lúc lâu"},{"hanzi":"片刻","pinyin":"piànkè","vi":"chốc lát"},{"hanzi":"许久","pinyin":"xǔjiǔ","vi":"rất lâu"}]},{"id":"半推半就","hanzi":"半推半就","pinyin":"bàntuī-bànjiù","meaning_vi":"nửa đẩy nửa đưa, nửa từ chối nửa nhận lời","explanation":"半推 (nửa đẩy ra) + 半就 (nửa tiến tới nhận) → ngoài miệng từ chối nhưng trong lòng muốn nhận; làm bộ miễn cưỡng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤭","examples":[{"type":"basic","zh":"她半推半就地收下了红包。","pinyin":"Tā bàntuībànjiù de shōuxiàle hóngbāo.","vi":"Cô ấy nửa từ chối nửa đồng ý nhận lấy bao lì xì."},{"type":"simple","zh":"在朋友的劝说下，他半推半就地上台唱了一首歌。","pinyin":"Zài péngyou de quànshuō xià, tā bàntuībànjiù deshàng tái chàngle yìshǒugē.","vi":"Dưới sự thuyết phục của bạn bè, anh ấy nửa đẩy nửa đưa lên sân khấu hát một bài."},{"type":"compound","zh":"虽然嘴上说不想去，但是她最后还是半推半就地跟着来了。","pinyin":"Suīrán zuǐ shang shuō bù xiǎng qù, dànshì tā zuìhòu háishi bàntuībànjiù de gēnzhe lái le.","vi":"Tuy ngoài miệng nói không muốn đi nhưng cuối cùng cô ấy vẫn nửa đẩy nửa đưa đi theo."}],"related":[{"hanzi":"欲拒还迎","pinyin":"yùjùhuányíng","vi":"muốn chối mà vẫn nhận"},{"hanzi":"勉强","pinyin":"miǎnqiǎng","vi":"miễn cưỡng"},{"hanzi":"犹豫","pinyin":"yóuyù","vi":"do dự"},{"hanzi":"推辞","pinyin":"tuīcí","vi":"từ chối"}]},{"id":"傍","hanzi":"傍","pinyin":"bàng","meaning_vi":"kề bên, dựa vào; gần tới (thời gian, như chập tối)","explanation":"Cụm: 依山傍水 (tựa núi kề sông).","hsk_level":"7-9","tags":["dong-tu","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"这个小镇依山傍水。","pinyin":"Zhè ge xiǎozhèn yī shān bàng shuǐ.","vi":"Thị trấn nhỏ này tựa núi kề sông."},{"type":"simple","zh":"他们的房子傍着一条小河而建。","pinyin":"Tāmen de fángzi bàngzhe yì tiáo xiǎohé ér jiàn.","vi":"Ngôi nhà của họ được xây sát bên một con sông nhỏ."},{"type":"compound","zh":"渔船一到傍晚就陆续回到港口，码头上热闹起来。","pinyin":"Yúchuán yí dào bàngwǎn jiù lùxù huídào gǎngkǒu, mǎtóu shang rènao qǐlái.","vi":"Hễ đến chiều tối, các thuyền đánh cá lần lượt trở về cảng, bến tàu trở nên náo nhiệt."}],"related":[{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chiều tối"},{"hanzi":"依傍","pinyin":"yībàng","vi":"dựa vào"},{"hanzi":"依山傍水","pinyin":"yīshānbàngshuǐ","vi":"tựa núi kề sông"},{"hanzi":"靠","pinyin":"kào","vi":"dựa"}]},{"id":"暴跌","hanzi":"暴跌","pinyin":"bàodiē","meaning_vi":"giảm mạnh đột ngột (cổ phiếu/giá cả)","explanation":"暴 (bạo – đột ngột, dữ dội) + 跌 (điệt – ngã, rơi) → giảm mạnh đột ngột. Cụm: 股价暴跌; trái nghĩa 暴涨.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"昨天股价暴跌了。","pinyin":"Zuótiān gǔjià bàodiē le.","vi":"Hôm qua giá cổ phiếu đã lao dốc."},{"type":"simple","zh":"受暴雨影响，本地西瓜的收购价暴跌了一半。","pinyin":"Shòu bàoyǔ yǐngxiǎng, běndì xīguā de shōugòu jià bàodiēle yíbàn.","vi":"Do ảnh hưởng của mưa lớn, giá thu mua dưa hấu địa phương giảm mạnh mất một nửa."},{"type":"compound","zh":"一旦出现负面新闻，这家公司的股价就会暴跌。","pinyin":"Yídàn chūxiàn fùmiàn xīnwén, zhè jiā gōngsī de gǔjià jiù huì bàodiē.","vi":"Một khi xuất hiện tin tức tiêu cực, giá cổ phiếu của công ty này sẽ lao dốc."}],"related":[{"hanzi":"暴涨","pinyin":"bàozhǎng","vi":"tăng vọt"},{"hanzi":"下跌","pinyin":"xiàdiē","vi":"giảm xuống"},{"hanzi":"股市","pinyin":"gǔshì","vi":"thị trường chứng khoán"},{"hanzi":"狂跌","pinyin":"kuángdiē","vi":"lao dốc"}]},{"id":"暴风雪","hanzi":"暴风雪","pinyin":"bàofēngxuě","meaning_vi":"bão tuyết","explanation":"暴风 (gió bão) + 雪 (tuyết).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","thien-nhien"],"image":"🌨️","examples":[{"type":"basic","zh":"暴风雪封住了山路。","pinyin":"Bàofēngxuě fēng zhùle shānlù.","vi":"Bão tuyết đã chặn kín đường núi."},{"type":"simple","zh":"一场突如其来的暴风雪让登山队困在了营地。","pinyin":"Yì cháng tūrúqílái de bàofēngxuě ràng dēngshān duì kùn zài le yíngdì.","vi":"Một trận bão tuyết bất ngờ khiến đội leo núi bị mắc kẹt ở khu trại."},{"type":"compound","zh":"因为暴风雪还没停，所以机场所有航班都延误了。","pinyin":"Yīnwèi bàofēngxuě hái méi tíng, suǒyǐ jīchǎng suǒyǒu hángbān dōu yánwù le.","vi":"Vì bão tuyết vẫn chưa ngừng nên mọi chuyến bay ở sân bay đều bị trễ."}],"related":[{"hanzi":"暴风雨","pinyin":"bàofēngyǔ","vi":"bão tố"},{"hanzi":"雪灾","pinyin":"xuězāi","vi":"tuyết tai"},{"hanzi":"冰天雪地","pinyin":"bīngtiānxuědì","vi":"trời băng đất tuyết"},{"hanzi":"寒潮","pinyin":"háncháo","vi":"đợt rét"}],"traditional":"暴風雪"},{"id":"报刊杂志","hanzi":"报刊杂志","pinyin":"bàokānzázhì","meaning_vi":"báo chí và tạp chí","explanation":"报刊 (báo san – báo và ấn phẩm định kỳ) + 杂志 (tạp chí) → các loại báo chí, tạp chí nói chung.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📰","examples":[{"type":"basic","zh":"阅览室里有很多报刊杂志。","pinyin":"Yuèlǎnshì lǐ yǒu hěn duō bàokānzázhì.","vi":"Trong phòng đọc có rất nhiều báo chí và tạp chí."},{"type":"simple","zh":"爷爷每天早上都要去图书馆翻看报刊杂志。","pinyin":"Yéye měitiān zǎo Shangdōu yào qù túshūguǎn fānkàn bàokānzázhì.","vi":"Sáng nào ông nội cũng đến thư viện lật xem báo chí và tạp chí."},{"type":"compound","zh":"自从有了手机新闻，订阅报刊杂志的人就越来越少了。","pinyin":"Zìcóng yǒule shǒujī xīnwén, dìngyuè bàokānzázhì de rén jiù yuèláiyuè shǎo le.","vi":"Từ khi có tin tức trên điện thoại, người đặt mua báo chí và tạp chí ngày càng ít đi."}],"related":[{"hanzi":"报纸","pinyin":"bàozhǐ","vi":"báo"},{"hanzi":"杂志","pinyin":"zázhì","vi":"tạp chí"},{"hanzi":"期刊","pinyin":"qīkān","vi":"tập san"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"}],"traditional":"報刊雜誌"},{"id":"爆满","hanzi":"爆满","pinyin":"bàomǎn","meaning_vi":"chật kín chỗ, cháy vé (rạp hát/nhà hàng)","explanation":"爆 (nổ tung) + 满 (đầy).","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🏟️","examples":[{"type":"basic","zh":"今晚的电影院爆满。","pinyin":"Jīnwǎn de diànyǐngyuàn bàomǎn.","vi":"Rạp chiếu phim tối nay chật kín chỗ."},{"type":"simple","zh":"国庆期间各大景区的停车场全都爆满了。","pinyin":"Guóqìng qījiān gè dà jǐngqū de tíngchēchǎng quándōu bàomǎn le.","vi":"Trong dịp Quốc khánh, bãi đỗ xe ở các khu du lịch lớn đều chật kín."},{"type":"compound","zh":"这家小面馆不但价格便宜，而且每天中午都爆满。","pinyin":"Zhè jiā xiǎo miànguǎn búdàn jiàgé piányi, érqiě měitiān zhōngwǔ dōu bàomǎn.","vi":"Quán mì nhỏ này không chỉ giá rẻ mà trưa nào cũng chật kín khách."}],"related":[{"hanzi":"满座","pinyin":"mǎnzuò","vi":"kín chỗ"},{"hanzi":"拥挤","pinyin":"yōngjǐ","vi":"đông đúc"},{"hanzi":"座无虚席","pinyin":"zuòwúxūxí","vi":"không còn chỗ trống"},{"hanzi":"冷清","pinyin":"lěngqing","vi":"vắng vẻ"}],"traditional":"爆滿"},{"id":"暴跳如雷","hanzi":"暴跳如雷","pinyin":"bàotiào-rúléi","meaning_vi":"giận dữ nhảy dựng lên như sấm nổ","explanation":"暴跳 (bạo khiêu – nhảy dựng lên) + 如雷 (như lôi – như sấm) → giận dữ nhảy dựng, quát tháo như sấm.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😡","examples":[{"type":"basic","zh":"父亲气得暴跳如雷。","pinyin":"Fùqīn qì de bàotiàorúléi.","vi":"Cha tức giận đến mức nổi trận lôi đình."},{"type":"simple","zh":"老板看到报表后暴跳如雷地拍了桌子。","pinyin":"Lǎobǎn kàndào bàobiǎo hòu bàotiàorúléi de pāile zhuōzi.","vi":"Sau khi xem bảng báo cáo, ông chủ giận dữ nhảy dựng lên đập bàn."},{"type":"compound","zh":"他一听说儿子又逃课了，就气得暴跳如雷。","pinyin":"Tā yì tīngshuō érzi yòu táokè le, jiù qì de bàotiàorúléi.","vi":"Vừa nghe tin con trai lại trốn học, ông ấy liền tức giận nhảy dựng lên."}],"related":[{"hanzi":"大发雷霆","pinyin":"dàfāléitíng","vi":"nổi trận lôi đình"},{"hanzi":"怒发冲冠","pinyin":"nùfàchōngguān","vi":"giận dựng tóc gáy"},{"hanzi":"火冒三丈","pinyin":"huǒmàosānzhàng","vi":"giận sôi máu"},{"hanzi":"心平气和","pinyin":"xīnpíngqìhé","vi":"bình tâm hòa nhã"}]},{"id":"抱团","hanzi":"抱团","pinyin":"bàotuán","meaning_vi":"tụ họp thành nhóm, liên kết cùng nhau","explanation":"抱 (ôm) + 团 (đoàn/nhóm). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"小商户们决定抱团。","pinyin":"Xiǎo shānghùmen juédìng bàotuán.","vi":"Các tiểu thương quyết định liên kết với nhau."},{"type":"simple","zh":"几家民宿抱团推出了周末联票。","pinyin":"Jǐ jiā mínsù bàotuán tuīchūle zhōumò lián piào.","vi":"Mấy nhà nghỉ homestay liên kết với nhau tung ra vé combo cuối tuần."},{"type":"compound","zh":"只要大家抱团取暖，就能一起度过这段困难时期。","pinyin":"Zhǐyào dàjiā bàotuán qǔnuǎn, jiù néng yìqǐ dùguò zhè duàn kùnnan shíqī.","vi":"Chỉ cần mọi người đoàn kết nương tựa vào nhau thì có thể cùng vượt qua giai đoạn khó khăn này."}],"related":[{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"},{"hanzi":"抱团取暖","pinyin":"bàotuánqǔnuǎn","vi":"nương tựa vào nhau"},{"hanzi":"联合","pinyin":"liánhé","vi":"liên hợp"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"}],"traditional":"抱團"},{"id":"暴涨","hanzi":"暴涨","pinyin":"bàozhǎng","meaning_vi":"tăng vọt đột ngột (giá cả/nước lũ)","explanation":"暴 (bạo – dữ dội, đột ngột) + 涨 (trướng – dâng lên) → tăng vọt đột ngột. Dùng cho giá cả, cổ phiếu, mực nước: 房价暴涨, 河水暴涨; trái nghĩa 暴跌.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"河水一夜之间暴涨。","pinyin":"Héshuǐ yí yè zhījiān bàozhǎng.","vi":"Nước sông dâng vọt chỉ sau một đêm."},{"type":"simple","zh":"台风过后，市场上的青菜价格暴涨了三倍。","pinyin":"Táifēng guòhòu, shìchǎng shang de qīngcài jiàgé bàozhǎngle sānbèi.","vi":"Sau cơn bão, giá rau xanh ngoài chợ tăng vọt gấp ba lần."},{"type":"compound","zh":"因为上游连降暴雨，所以下游水位暴涨。","pinyin":"Yīnwèi shàngyóu lián jiàng bàoyǔ, suǒyǐ xiàyóu shuǐwèi bàozhǎng.","vi":"Vì thượng nguồn mưa lớn liên tục nên mực nước ở hạ lưu tăng vọt."}],"related":[{"hanzi":"暴跌","pinyin":"bàodiē","vi":"giảm mạnh"},{"hanzi":"上涨","pinyin":"shàngzhǎng","vi":"tăng lên"},{"hanzi":"飙升","pinyin":"biāoshēng","vi":"tăng vọt"},{"hanzi":"物价","pinyin":"wùjià","vi":"giá cả"}],"traditional":"暴漲"},{"id":"拔苗助长","hanzi":"拔苗助长","pinyin":"bámiáo-zhùzhǎng","meaning_vi":"nhổ mạ giúp lúa mọc nhanh (nóng vội làm hỏng việc)","explanation":"拔苗助长: nhổ cây mạ lên cho nhanh lớn (truyện người nước Tống trong sách Mạnh Tử, mạ héo chết hết) → ví nóng vội, làm trái quy luật nên hỏng việc.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌾","examples":[{"type":"basic","zh":"教育孩子不能拔苗助长。","pinyin":"Jiàoyù háizi bù néng bámiáozhùzhǎng.","vi":"Dạy con không được nóng vội đốt cháy giai đoạn."},{"type":"simple","zh":"让三岁孩子背乘法表简直是拔苗助长。","pinyin":"Ràng sān suì háizi bèi chéngfǎbiǎo jiǎnzhí shì bámiáozhùzhǎng.","vi":"Bắt đứa trẻ ba tuổi học thuộc bảng cửu chương đúng là nhổ mạ cho lúa mau lớn."},{"type":"compound","zh":"如果训练强度增加得太快，就等于拔苗助长，反而容易受伤。","pinyin":"Rúguǒ xùnliàn qiángdù zēngjiā de tài kuài, jiù děngyú bámiáozhùzhǎng, fǎn'ér róngyì shòushāng.","vi":"Nếu tăng cường độ tập luyện quá nhanh thì chẳng khác gì nóng vội làm hỏng việc, ngược lại còn dễ chấn thương."}],"related":[{"hanzi":"揠苗助长","pinyin":"yàmiáozhùzhǎng","vi":"nóng vội hỏng việc"},{"hanzi":"急于求成","pinyin":"jíyúqiúchéng","vi":"nóng vội cầu thành"},{"hanzi":"欲速则不达","pinyin":"yù sù zé bù dá","vi":"dục tốc bất đạt"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến lên"}],"traditional":"拔苗助長"},{"id":"跋山涉水","hanzi":"跋山涉水","pinyin":"báshān-shèshuǐ","meaning_vi":"trèo đèo lội suối, vượt qua muôn trùng gian khổ","explanation":"跋 (bạt – trèo, vượt) 山 (núi) + 涉 (thiệp – lội) 水 (nước) → trèo núi lội sông; ví hành trình xa xôi, vất vả gian khổ.","hsk_level":"7-9","tags":["thanh-ngu","du-lich"],"image":"⛰️","examples":[{"type":"basic","zh":"医疗队跋山涉水进了山村。","pinyin":"Yīliáo duì báshānshèshuǐ jìnle shāncūn.","vi":"Đội y tế trèo đèo lội suối vào bản làng vùng núi."},{"type":"simple","zh":"邮递员每周都跋山涉水给牧民送信。","pinyin":"Yóudìyuán měizhōu dōu báshānshèshuǐ gěi mùmín sòngxìn.","vi":"Tuần nào người đưa thư cũng trèo đèo lội suối mang thư đến cho dân du mục."},{"type":"compound","zh":"虽然一路跋山涉水，但是考察队员们没有一个人叫苦。","pinyin":"Suīrán yílù báshānshèshuǐ, dànshì kǎochá duìyuánmen méiyǒu yígèrén jiàokǔ.","vi":"Tuy suốt chặng đường phải trèo đèo lội suối nhưng không một thành viên nào trong đoàn khảo sát kêu khổ."}],"related":[{"hanzi":"翻山越岭","pinyin":"fānshānyuèlǐng","vi":"trèo đèo vượt núi"},{"hanzi":"长途跋涉","pinyin":"chángtúbáshè","vi":"bôn ba đường xa"},{"hanzi":"千辛万苦","pinyin":"qiānxīnwànkǔ","vi":"muôn vàn gian khổ"},{"hanzi":"风餐露宿","pinyin":"fēngcānlùsù","vi":"dãi gió dầm sương"}]},{"id":"白话文","hanzi":"白话文","pinyin":"báihuàwén","meaning_vi":"văn bạch thoại (tiếng Hán hiện đại)","explanation":"白 (màu trắng) + 话 (话) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","van-hoa"],"image":"📖","examples":[{"type":"basic","zh":"鲁迅用白话文写小说。","pinyin":"Lǔxùn yòng báihuàwén xiě xiǎoshuō.","vi":"Lỗ Tấn dùng văn bạch thoại để viết tiểu thuyết."},{"type":"simple","zh":"老师让我们把这段古文翻译成白话文。","pinyin":"Lǎoshī ràng wǒmen bǎ zhè duàn gǔwén fānyì chéng báihuàwén.","vi":"Thầy giáo bảo chúng tôi dịch đoạn cổ văn này sang văn bạch thoại."},{"type":"compound","zh":"自从白话文得到推广，普通人读书写字就容易多了。","pinyin":"Zìcóng báihuàwén dédào tuīguǎng, pǔtōngrén dúshū xiězì jiù róngyì duō le.","vi":"Từ khi văn bạch thoại được phổ biến, người bình thường đọc sách viết chữ dễ dàng hơn nhiều."}],"related":[{"hanzi":"文言文","pinyin":"wényánwén","vi":"văn ngôn"},{"hanzi":"白话","pinyin":"báihuà","vi":"bạch thoại"},{"hanzi":"现代汉语","pinyin":"xiàndàihànyǔ","vi":"tiếng Hán hiện đại"},{"hanzi":"古文","pinyin":"gǔwén","vi":"văn cổ"}],"traditional":"白話文"},{"id":"白热化","hanzi":"白热化","pinyin":"báirèhuà","meaning_vi":"giai đoạn gay cấn ác liệt nhất (cạnh tranh)","explanation":"白 (màu trắng) + 热 (nóng) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🔥","examples":[{"type":"basic","zh":"比赛进入了白热化。","pinyin":"Bǐsài jìnrùle báirèhuà.","vi":"Trận đấu đã bước vào giai đoạn gay cấn nhất."},{"type":"simple","zh":"两家外卖平台的价格战已经白热化了。","pinyin":"Liǎng jiā wàimài píngtái de jiàgézhàn yǐjīng báirèhuà le.","vi":"Cuộc chiến giá cả giữa hai nền tảng giao đồ ăn đã lên đến đỉnh điểm."},{"type":"compound","zh":"当竞争进入白热化阶段时，任何一个小失误都可能致命。","pinyin":"Dāng jìngzhēng jìnrù báirèhuà jiēduàn shí, rènhé yí gè xiǎo shīwù dōu kěnéng zhìmìng.","vi":"Khi cạnh tranh bước vào giai đoạn khốc liệt nhất, bất kỳ sai sót nhỏ nào cũng có thể là chí mạng."}],"related":[{"hanzi":"激烈","pinyin":"jīliè","vi":"kịch liệt"},{"hanzi":"高潮","pinyin":"gāocháo","vi":"cao trào"},{"hanzi":"尖锐","pinyin":"jiānruì","vi":"gay gắt"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"}],"traditional":"白熱化"},{"id":"白手起家","hanzi":"白手起家","pinyin":"báishǒu-qǐjiā","meaning_vi":"lập nghiệp từ hai bàn tay trắng","explanation":"白手 (tay trắng) + 起家 (gây dựng cơ nghiệp). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"他是白手起家的老板。","pinyin":"Tā shì báishǒuqǐjiā de lǎobǎn.","vi":"Anh ấy là ông chủ đi lên từ hai bàn tay trắng."},{"type":"simple","zh":"她靠卖手工饺子白手起家开了三家店。","pinyin":"Tā kào mài shǒugōng jiǎozi báishǒuqǐjiā kāile sān jiā diàn.","vi":"Cô ấy tay trắng lập nghiệp nhờ bán sủi cảo làm tay, đã mở được ba cửa hàng."},{"type":"compound","zh":"虽然他是白手起家，但是从来不忘记帮助刚创业的年轻人。","pinyin":"Suīrán tā shì báishǒuqǐjiā, dànshì cóngláibú wàngjì bāngzhù gāng chuàngyè de niánqīngrén.","vi":"Tuy đi lên từ hai bàn tay trắng nhưng ông ấy chưa bao giờ quên giúp đỡ những người trẻ mới khởi nghiệp."}],"related":[{"hanzi":"自力更生","pinyin":"zìlìgēngshēng","vi":"tự lực cánh sinh"},{"hanzi":"艰苦创业","pinyin":"jiānkǔchuàngyè","vi":"lập nghiệp gian khổ"},{"hanzi":"创业","pinyin":"chuàngyè","vi":"khởi nghiệp"},{"hanzi":"富二代","pinyin":"fù'èrdài","vi":"con nhà giàu"}]},{"id":"背井离乡","hanzi":"背井离乡","pinyin":"bèijǐng-líxiāng","meaning_vi":"rời bỏ quê hương xứ sở","explanation":"背井 (rời giếng nước) + 离乡 (xa làng quê). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧳","examples":[{"type":"basic","zh":"他背井离乡去南方打工。","pinyin":"Tā bèijǐnglíxiāng qù nánfāng dǎgōng.","vi":"Anh ấy rời bỏ quê hương vào miền Nam làm thuê."},{"type":"simple","zh":"战争迫使成千上万的家庭背井离乡。","pinyin":"Zhànzhēng pòshǐ chéngqiānshàngwàn de jiātíng bèijǐnglíxiāng.","vi":"Chiến tranh buộc hàng ngàn hàng vạn gia đình phải rời bỏ quê hương."},{"type":"compound","zh":"虽然背井离乡二十年，但是他说话还带着浓浓的家乡口音。","pinyin":"Suīrán bèijǐnglíxiāng èrshí nián, dànshì tā shuōhuà hái dàizhe nóng nóng de jiāxiāng kǒuyīn.","vi":"Tuy đã xa quê hai mươi năm nhưng ông ấy nói chuyện vẫn còn đậm giọng quê nhà."}],"related":[{"hanzi":"离乡背井","pinyin":"líxiāngbèijǐng","vi":"xa quê hương"},{"hanzi":"远走他乡","pinyin":"yuǎnzǒutāxiāng","vi":"tha hương"},{"hanzi":"思乡","pinyin":"sīxiāng","vi":"nhớ quê"},{"hanzi":"落叶归根","pinyin":"luòyèguīgēn","vi":"lá rụng về cội"}],"traditional":"背井離鄉"},{"id":"备课","hanzi":"备课","pinyin":"bèikè","meaning_vi":"soạn bài giảng","explanation":"备 (备) + 课 (bài học).","hsk_level":"7-9","tags":["dong-tu","hoc-tap","cong-viec"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"老师正在备课。","pinyin":"Lǎoshī zhèngzài bèikè.","vi":"Cô giáo đang soạn bài."},{"type":"simple","zh":"王老师每天晚上都在书房备课到十一点。","pinyin":"Wáng lǎoshī měitiān wǎnshang dōu zài shūfáng bèikè dào shíyī diǎn.","vi":"Tối nào thầy Vương cũng soạn bài trong phòng đọc sách đến mười một giờ."},{"type":"compound","zh":"如果课前没有认真备课，上课时就很容易讲乱。","pinyin":"Rúguǒ kè qián méiyǒu rènzhēn bèikè, shàngkè shí jiù hěn róngyì jiǎng luàn.","vi":"Nếu trước giờ học không soạn bài kỹ thì khi lên lớp rất dễ giảng lộn xộn."}],"related":[{"hanzi":"上课","pinyin":"shàngkè","vi":"lên lớp"},{"hanzi":"教案","pinyin":"jiào'àn","vi":"giáo án"},{"hanzi":"讲课","pinyin":"jiǎngkè","vi":"giảng bài"},{"hanzi":"预习","pinyin":"yùxí","vi":"chuẩn bị bài"}],"traditional":"備課"},{"id":"悖论","hanzi":"悖论","pinyin":"bèilùn","meaning_vi":"nghịch lý","explanation":"悖 (trái ngược) + 论 (lý luận).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"这是一个著名的悖论。","pinyin":"Zhè shì yí gè zhùmíng de bèilùn.","vi":"Đây là một nghịch lý nổi tiếng."},{"type":"simple","zh":"哲学课上大家讨论了说谎者悖论。","pinyin":"Zhéxué kè shàng dàjiā tǎolùnle shuōhuǎngzhě bèilùn.","vi":"Trong giờ triết học, mọi người thảo luận về nghịch lý kẻ nói dối."},{"type":"compound","zh":"越想节省时间，反而越浪费时间，这真是一个悖论。","pinyin":"Yuè xiǎng jiéshěng shíjiān, fǎn'ér yuè làngfèi shíjiān, zhè zhēn shì yí gè bèilùn.","vi":"Càng muốn tiết kiệm thời gian lại càng lãng phí thời gian, đây thật là một nghịch lý."}],"related":[{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"自相矛盾","pinyin":"zìxiāngmáodùn","vi":"tự mâu thuẫn"},{"hanzi":"逻辑","pinyin":"luójí","vi":"logic"},{"hanzi":"谬论","pinyin":"miùlùn","vi":"luận điệu sai trái"}],"traditional":"悖論"},{"id":"备受","hanzi":"备受","pinyin":"bèishòu","meaning_vi":"rất được (hoan nghênh/chú ý)","explanation":"备 (备) + 受 (chịu đựng/tiếp nhận).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"这部电影备受好评。","pinyin":"Zhè bù diànyǐng bèishòu hǎopíng.","vi":"Bộ phim này rất được khen ngợi."},{"type":"simple","zh":"这位乡村医生几十年来备受村民尊敬。","pinyin":"Zhè wèi xiāngcūn yīshēng jǐ shí niánlái bèishòu cūnmín zūnjìng.","vi":"Mấy chục năm nay, vị bác sĩ nông thôn này rất được dân làng kính trọng."},{"type":"compound","zh":"他因为腰伤备受折磨，所以不得不提前退役。","pinyin":"Tā yīnwèi yāo shāng bèishòu zhémó, suǒyǐ bùdébù tíqián tuìyì.","vi":"Vì bị chấn thương lưng hành hạ dữ dội nên anh ấy buộc phải giải nghệ sớm."}],"related":[{"hanzi":"受到","pinyin":"shòudào","vi":"nhận được"},{"hanzi":"备受关注","pinyin":"bèishòuguānzhù","vi":"được đặc biệt quan tâm"},{"hanzi":"倍受","pinyin":"bèishòu","vi":"chịu nhiều"},{"hanzi":"广受","pinyin":"guǎngshòu","vi":"được rộng rãi"}],"traditional":"備受"},{"id":"倍增","hanzi":"倍增","pinyin":"bèizēng","meaning_vi":"tăng gấp bội","explanation":"倍 (lần (gấp bội)) + 增 (tăng thêm).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"游客人数倍增。","pinyin":"Yóukè rénshù bèizēng.","vi":"Số lượng du khách tăng gấp bội."},{"type":"simple","zh":"开通高铁后，这个小县城的商机倍增。","pinyin":"Kāitōng gāotiě hòu, zhè ge xiǎo xiànchéng de shāngjī bèizēng.","vi":"Sau khi tuyến đường sắt cao tốc thông xe, cơ hội kinh doanh của huyện lỵ nhỏ này tăng gấp bội."},{"type":"compound","zh":"一听到观众的掌声，队员们就信心倍增。","pinyin":"Yì tīngdào guānzhòng de zhǎngshēng, duìyuánmen jiù xìnxīn bèizēng.","vi":"Vừa nghe tiếng vỗ tay của khán giả, các cầu thủ liền tự tin hơn gấp bội."}],"related":[{"hanzi":"翻番","pinyin":"fānfān","vi":"tăng gấp đôi"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"tăng thêm"},{"hanzi":"成倍","pinyin":"chéngbèi","vi":"gấp bội"},{"hanzi":"递减","pinyin":"dìjiǎn","vi":"giảm dần"}]},{"id":"碧波","hanzi":"碧波","pinyin":"bìbō","meaning_vi":"sóng nước xanh biếc","explanation":"碧 (xanh ngọc) + 波 (sóng).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"湖面碧波荡漾。","pinyin":"Húmiàn bìbō dàngyàng.","vi":"Mặt hồ sóng xanh lăn tăn."},{"type":"simple","zh":"几艘小船在碧波之上缓缓前行。","pinyin":"Jǐ sōu xiǎochuán zài bìbō zhīshàng huǎnhuǎn qiánxíng.","vi":"Vài chiếc thuyền nhỏ chầm chậm lướt trên làn sóng xanh biếc."},{"type":"compound","zh":"站在山顶望去，碧波万顷的大海让人心旷神怡。","pinyin":"Zhàn zài shāndǐng wàng qù, bìbō wànqǐng de dàhǎi ràng rén xīnkuàngshényí.","vi":"Đứng trên đỉnh núi nhìn ra, biển cả mênh mông sóng biếc khiến lòng người khoan khoái."}],"related":[{"hanzi":"波浪","pinyin":"bōlàng","vi":"sóng"},{"hanzi":"碧绿","pinyin":"bìlǜ","vi":"xanh biếc"},{"hanzi":"波涛","pinyin":"bōtāo","vi":"sóng lớn"},{"hanzi":"湖面","pinyin":"húmiàn","vi":"mặt hồ"}]},{"id":"壁画","hanzi":"壁画","pinyin":"bìhuà","meaning_vi":"bích họa, tranh tường","explanation":"壁 (tường) + 画 (tranh).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"敦煌壁画非常有名。","pinyin":"Dūnhuáng bìhuà fēicháng yǒumíng.","vi":"Bích họa Đôn Hoàng vô cùng nổi tiếng."},{"type":"simple","zh":"修复专家用了两年时间修补这幅唐代壁画。","pinyin":"Xiūfù zhuān jiāyòngle liǎng nián shíjiān xiūbǔ zhè fú Tángdài bìhuà.","vi":"Các chuyên gia phục chế đã mất hai năm để tu bổ bức bích họa thời Đường này."},{"type":"compound","zh":"为了保护壁画，石窟里不但禁止拍照，而且限制参观人数。","pinyin":"Wèile bǎohù bìhuà, shíkū lǐ búdàn jìnzhǐ pāizhào, érqiě xiànzhì cānguān rénshù.","vi":"Để bảo vệ các bức bích họa, trong hang đá không chỉ cấm chụp ảnh mà còn hạn chế số lượng khách tham quan."}],"related":[{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"墙壁","pinyin":"qiángbì","vi":"bức tường"},{"hanzi":"敦煌","pinyin":"Dūnhuáng","vi":"Đôn Hoàng"},{"hanzi":"石窟","pinyin":"shíkū","vi":"hang đá"}],"traditional":"壁畫"},{"id":"避讳","hanzi":"避讳","pinyin":"bìhuì","meaning_vi":"kiêng kỵ, tránh nhắc tới điều nhạy cảm","explanation":"避 (tránh) + 讳 (kiêng).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🤫","examples":[{"type":"basic","zh":"他说话从不避讳。","pinyin":"Tā shuōhuà cóng bú bìhuì.","vi":"Anh ấy nói năng chẳng bao giờ kiêng kỵ gì."},{"type":"simple","zh":"很多老人避讳在病房里谈论死亡。","pinyin":"Hěn duō lǎorén bìhuì zài bìngfáng lǐ tánlùn sǐwáng.","vi":"Nhiều người già kiêng nhắc đến cái chết trong phòng bệnh."},{"type":"compound","zh":"因为有些地方避讳数字四，所以楼层里没有四楼。","pinyin":"Yīnwèi yǒuxiē dìfang bìhuì shùzì sì, suǒyǐ lóucéng lǐ méiyǒu sì lóu.","vi":"Vì một số nơi kiêng số bốn nên tòa nhà không có tầng bốn."}],"related":[{"hanzi":"忌讳","pinyin":"jìhuì","vi":"kiêng kỵ"},{"hanzi":"禁忌","pinyin":"jìnjì","vi":"điều cấm kỵ"},{"hanzi":"回避","pinyin":"huíbì","vi":"né tránh"},{"hanzi":"敏感","pinyin":"mǐngǎn","vi":"nhạy cảm"}],"traditional":"避諱"},{"id":"必经之路","hanzi":"必经之路","pinyin":"bìjīngzhīlù","meaning_vi":"con đường bắt buộc phải đi qua","explanation":"必 (tất – nhất định) 经 (kinh – đi qua) + 之路 (con đường) → con đường nhất định phải đi qua; nghĩa bóng: bước bắt buộc để đạt mục tiêu. VD: 成功的必经之路.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"这座桥是进城的必经之路。","pinyin":"Zhè zuò qiáo shì jìnchéng de bìjīngzhīlù.","vi":"Cây cầu này là con đường bắt buộc phải đi qua để vào thành phố."},{"type":"simple","zh":"失败几乎是每个创业者的必经之路。","pinyin":"Shībài jīhū shì měi gè chuàngyèzhě de bìjīngzhīlù.","vi":"Thất bại gần như là con đường ai khởi nghiệp cũng phải trải qua."},{"type":"compound","zh":"既然实习是成为医生的必经之路，你就别再抱怨辛苦了。","pinyin":"Jìrán shíxí shì chéngwéi yīshēng de bìjīngzhīlù, nǐ jiù bié zài bàoyuàn xīnkǔ le.","vi":"Đã là con đường bắt buộc để trở thành bác sĩ thì bạn đừng than vất vả nữa."}],"related":[{"hanzi":"必由之路","pinyin":"bìyóuzhīlù","vi":"con đường tất yếu"},{"hanzi":"道路","pinyin":"dàolù","vi":"con đường"},{"hanzi":"途径","pinyin":"tújìng","vi":"con đường cách thức"},{"hanzi":"必然","pinyin":"bìrán","vi":"tất nhiên"}],"traditional":"必經之路"},{"id":"闭幕","hanzi":"闭幕","pinyin":"bìmù","meaning_vi":"bế mạc, hạ màn","explanation":"闭 (闭) + 幕 (màn hình/hậu trường).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"运动会今天闭幕。","pinyin":"Yùndònghuì jīntiān bìmù.","vi":"Đại hội thể thao bế mạc hôm nay."},{"type":"simple","zh":"为期十天的国际电影节在掌声中闭幕。","pinyin":"Wéiqī shí tiān de Guójì diànyǐngjié zài zhǎngshēng zhōng bìmù.","vi":"Liên hoan phim quốc tế kéo dài mười ngày đã bế mạc trong tiếng vỗ tay."},{"type":"compound","zh":"展览一闭幕，工作人员就连夜把展品打包运走了。","pinyin":"Zhǎnlǎn yí bìmù, gōngzuò rényuán jiù liányè bǎ zhǎnpǐn dǎbāo yùn zǒu le.","vi":"Triển lãm vừa bế mạc, nhân viên đã suốt đêm đóng gói chở các hiện vật đi."}],"related":[{"hanzi":"开幕","pinyin":"kāimù","vi":"khai mạc"},{"hanzi":"闭幕式","pinyin":"bìmùshì","vi":"lễ bế mạc"},{"hanzi":"落幕","pinyin":"luòmù","vi":"hạ màn"},{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"}],"traditional":"閉幕"},{"id":"闭幕式","hanzi":"闭幕式","pinyin":"bìmùshì","meaning_vi":"lễ bế mạc","explanation":"闭幕 (hạ màn) + 式 (nghi lễ). Đối ứng với 开幕式.","hsk_level":"7-9","tags":["danh-tu","van-hoa","the-thao"],"image":"🎊","examples":[{"type":"basic","zh":"闭幕式非常精彩。","pinyin":"Bìmùshì fēicháng jīngcǎi.","vi":"Lễ bế mạc vô cùng đặc sắc."},{"type":"simple","zh":"各国运动员在闭幕式上一起跳起了舞。","pinyin":"Gèguó yùndòngyuán zài bìmùshì shang yìqǐ tiào qǐle wǔ.","vi":"Vận động viên các nước cùng nhau nhảy múa tại lễ bế mạc."},{"type":"compound","zh":"虽然没能拿到奖牌，但是她在闭幕式上笑得很开心。","pinyin":"Suīrán méi néng nádào jiǎngpái, dànshì tā zài bìmùshì shang xiào de hěn kāixīn.","vi":"Tuy không giành được huy chương nhưng cô ấy cười rất vui vẻ trong lễ bế mạc."}],"related":[{"hanzi":"开幕式","pinyin":"kāimùshì","vi":"lễ khai mạc"},{"hanzi":"闭幕","pinyin":"bìmù","vi":"bế mạc"},{"hanzi":"典礼","pinyin":"diǎnlǐ","vi":"buổi lễ"},{"hanzi":"仪式","pinyin":"yíshì","vi":"nghi thức"}],"traditional":"閉幕式"},{"id":"闭目塞听","hanzi":"闭目塞听","pinyin":"bìmù-sètīng","meaning_vi":"nhắm mắt bịt tai (tự cô lập không tiếp thu cái mới)","explanation":"闭目塞听: nhắm (闭) mắt (目), bịt (塞) tai không nghe (听) → tự cô lập, không chịu tiếp xúc với thực tế bên ngoài.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🙈","examples":[{"type":"basic","zh":"做研究不能闭目塞听。","pinyin":"Zuò yánjiū bù néng bìmùsètīng.","vi":"Làm nghiên cứu không thể nhắm mắt bịt tai."},{"type":"simple","zh":"这家老厂多年闭目塞听，错过了技术升级的机会。","pinyin":"Zhè jiālǎo chǎng duōnián bìmùsètīng, cuòguòle jìshù shēngjí de jīhuì.","vi":"Nhà máy lâu đời này nhiều năm tự cô lập, bỏ lỡ cơ hội nâng cấp công nghệ."},{"type":"compound","zh":"如果管理者闭目塞听，企业就很难跟上市场的变化。","pinyin":"Rúguǒ guǎnlǐ zhě bìmùsètīng, qǐyè jiù hěn nán gēnshang shìchǎng de biànhuà.","vi":"Nếu nhà quản lý nhắm mắt bịt tai thì doanh nghiệp rất khó theo kịp sự thay đổi của thị trường."}],"related":[{"hanzi":"闭关自守","pinyin":"bìguānzìshǒu","vi":"đóng cửa tự cô lập"},{"hanzi":"孤陋寡闻","pinyin":"gūlòuguǎwén","vi":"kiến thức nông cạn"},{"hanzi":"坐井观天","pinyin":"zuòjǐngguāntiān","vi":"ếch ngồi đáy giếng"},{"hanzi":"耳聪目明","pinyin":"ěrcōngmùmíng","vi":"tai thính mắt tinh"}],"traditional":"閉目塞聽"},{"id":"必然性","hanzi":"必然性","pinyin":"bìránxìng","meaning_vi":"tính tất yếu","explanation":"必 (tất yếu/chắc chắn) + 然 (然) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"❗","examples":[{"type":"basic","zh":"历史发展有其必然性。","pinyin":"Lìshǐ fāzhǎn yǒu qí bìránxìng.","vi":"Sự phát triển của lịch sử có tính tất yếu của nó."},{"type":"simple","zh":"专家分析了这次金融危机爆发的必然性。","pinyin":"Zhuānjiā fēnxīle zhè cì jīnróngwēijī bàofā de bìránxìng.","vi":"Các chuyên gia đã phân tích tính tất yếu của sự bùng nổ cuộc khủng hoảng tài chính lần này."},{"type":"compound","zh":"虽然胜利看似偶然，但是背后有它的必然性。","pinyin":"Suīrán shènglì kànsì ǒurán, dànshì bèihòu yǒu tā de bìránxìng.","vi":"Tuy chiến thắng trông có vẻ ngẫu nhiên nhưng đằng sau nó có tính tất yếu."}],"related":[{"hanzi":"偶然性","pinyin":"ǒuránxìng","vi":"tính ngẫu nhiên"},{"hanzi":"必然","pinyin":"bìrán","vi":"tất nhiên"},{"hanzi":"规律","pinyin":"guīlǜ","vi":"quy luật"},{"hanzi":"可能性","pinyin":"kěnéngxìng","vi":"khả năng"}]},{"id":"必胜","hanzi":"必胜","pinyin":"bìshèng","meaning_vi":"tất thắng, chắc chắn thắng","explanation":"必 (必) + 胜 (thắng lợi/vượt trội).","hsk_level":"7-9","tags":["tinh-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"我们有必胜的信心。","pinyin":"Wǒmen yǒu bìshèng de xìnxīn.","vi":"Chúng ta có niềm tin tất thắng."},{"type":"simple","zh":"看台上的球迷举着写有必胜两个字的横幅。","pinyin":"Kàntái shang de qiúmí jǔzhe xiě yǒu bìshèng liǎng gè zì de héngfú.","vi":"Cổ động viên trên khán đài giơ băng rôn viết hai chữ \"tất thắng\"."},{"type":"compound","zh":"只要全队团结一心，这场比赛我们就必胜无疑。","pinyin":"Zhǐyào quán duì tuánjié yìxīn, zhè chǎng bǐsài wǒmen jiù bìshèng wúyí.","vi":"Chỉ cần cả đội đồng lòng thì trận đấu này chúng ta chắc chắn sẽ thắng."}],"related":[{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"必败","pinyin":"bìbài","vi":"tất bại"},{"hanzi":"稳操胜券","pinyin":"wěncāoshèngquàn","vi":"nắm chắc phần thắng"},{"hanzi":"信心","pinyin":"xìnxīn","vi":"niềm tin"}],"traditional":"必勝"},{"id":"避重就轻","hanzi":"避重就轻","pinyin":"bìzhòng-jiùqīng","meaning_vi":"tránh nặng tìm nhẹ (né tránh vấn đề cốt lõi)","explanation":"避 (tị – tránh) 重 (nặng) + 就 (tựu – tìm đến) 轻 (nhẹ) → tránh cái nặng, chọn cái nhẹ; ví né tránh vấn đề chính, chỉ nói/làm phần dễ, không quan trọng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他回答问题总是避重就轻。","pinyin":"Tā huídá wèntí zǒngshì bìzhòngjiùqīng.","vi":"Anh ta trả lời câu hỏi lúc nào cũng tránh nặng tìm nhẹ."},{"type":"simple","zh":"厂家在道歉声明里避重就轻地谈到了质量问题。","pinyin":"Chǎngjiā zài dàoqiàn shēngmíng lǐ bìzhòngjiùqīng de tándàole zhìliàng wèntí.","vi":"Trong tuyên bố xin lỗi, nhà sản xuất chỉ nhắc qua loa, né tránh trọng tâm vấn đề chất lượng."},{"type":"compound","zh":"如果总结报告避重就轻，同样的错误就还会再犯。","pinyin":"Rúguǒ zǒngjié bàogào bìzhòngjiùqīng, tóngyàng de cuòwù jiù hái huì zài fàn.","vi":"Nếu báo cáo tổng kết né tránh vấn đề cốt lõi thì những sai lầm tương tự sẽ còn tái phạm."}],"related":[{"hanzi":"避实就虚","pinyin":"bìshíjiùxū","vi":"tránh thực tìm hư"},{"hanzi":"敷衍","pinyin":"fūyǎn","vi":"qua loa"},{"hanzi":"回避","pinyin":"huíbì","vi":"né tránh"},{"hanzi":"直面","pinyin":"zhímiàn","vi":"đối mặt trực tiếp"}],"traditional":"避重就輕"},{"id":"病床","hanzi":"病床","pinyin":"bìngchuáng","meaning_vi":"giường bệnh","explanation":"病 (bệnh) + 床 (sàng – giường) → giường bệnh trong bệnh viện. Cũng dùng chỉ số giường: 医院有五百张病床.","hsk_level":"7-9","tags":["danh-tu","suc-khoe","do-vat"],"image":"🛏️","examples":[{"type":"basic","zh":"病床上躺着一位老人。","pinyin":"Bìngchuáng shang tǎngzhe yí wèi lǎorén.","vi":"Trên giường bệnh có một cụ già đang nằm."},{"type":"simple","zh":"护士每两个小时就来帮他翻一次身，整理病床。","pinyin":"Hùshi měi liǎng gè xiǎoshí jiù lái bāng tā fān yí cì shēn, zhěnglǐ bìngchuáng.","vi":"Cứ hai tiếng y tá lại đến giúp ông trở mình một lần và dọn giường bệnh."},{"type":"compound","zh":"因为流感病人太多，所以医院的病床一下子不够用了。","pinyin":"Yīnwèi liúgǎn bìngrén tài duō, suǒyǐ yīyuàn de bìngchuáng yíxiàzi bú gòuyòng le.","vi":"Vì bệnh nhân cúm quá đông nên giường bệnh của bệnh viện bỗng chốc không đủ dùng."}],"related":[{"hanzi":"病房","pinyin":"bìngfáng","vi":"phòng bệnh"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"bệnh viện"},{"hanzi":"床位","pinyin":"chuángwèi","vi":"giường"},{"hanzi":"病人","pinyin":"bìngrén","vi":"bệnh nhân"}]},{"id":"病房","hanzi":"病房","pinyin":"bìngfáng","meaning_vi":"phòng bệnh","explanation":"病 (bệnh) + 房 (phòng) → phòng bệnh, buồng bệnh nhân nằm điều trị trong bệnh viện. VD: 住在三号病房.","hsk_level":"7-9","tags":["danh-tu","suc-khoe","dia-diem"],"image":"🏥","examples":[{"type":"basic","zh":"病房里很安静。","pinyin":"Bìngfáng lǐ hěn ānjìng.","vi":"Trong phòng bệnh rất yên tĩnh."},{"type":"simple","zh":"探视时间一到，家属们就陆续走进了病房。","pinyin":"Tànshì shíjiān yí dào, jiāshǔmen jiù lùxù zǒujìnle bìngfáng.","vi":"Giờ thăm bệnh vừa đến, người nhà bệnh nhân lần lượt bước vào phòng bệnh."},{"type":"compound","zh":"虽然病房条件很简陋，但是护士们照顾得非常周到。","pinyin":"Suīrán bìngfáng tiáojiàn hěn jiǎnlòu, dànshì hùshimen zhàogù de fēicháng zhōudào.","vi":"Tuy điều kiện phòng bệnh khá sơ sài nhưng các y tá chăm sóc vô cùng chu đáo."}],"related":[{"hanzi":"病床","pinyin":"bìngchuáng","vi":"giường bệnh"},{"hanzi":"病人","pinyin":"bìngrén","vi":"bệnh nhân"},{"hanzi":"护士","pinyin":"hùshi","vi":"y tá"},{"hanzi":"住院","pinyin":"zhùyuàn","vi":"nằm viện"}]},{"id":"并发症","hanzi":"并发症","pinyin":"bìngfāzhèng","meaning_vi":"biến chứng (y học)","explanation":"并 (并) + 发 (发) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他出现了并发症。","pinyin":"Tā chūxiànle bìngfāzhèng.","vi":"Ông ấy đã xuất hiện biến chứng."},{"type":"simple","zh":"长期高血糖容易引起眼睛和肾脏的并发症。","pinyin":"Chángqī gāoxuètáng róngyì yǐnqǐ yǎnjing hé shènzàng de bìngfāzhèng.","vi":"Đường huyết cao kéo dài dễ gây ra biến chứng ở mắt và thận."},{"type":"compound","zh":"如果手术后不注意休息，就可能出现严重的并发症。","pinyin":"Rúguǒ shǒushù hòu bú zhùyì xiūxi, jiù kěnéng chūxiàn yánzhòng de bìngfāzhèng.","vi":"Nếu sau phẫu thuật không chú ý nghỉ ngơi thì có thể xuất hiện biến chứng nghiêm trọng."}],"related":[{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"},{"hanzi":"后遗症","pinyin":"hòuyízhèng","vi":"di chứng"},{"hanzi":"病情","pinyin":"bìngqíng","vi":"tình trạng bệnh"},{"hanzi":"感染","pinyin":"gǎnrǎn","vi":"nhiễm trùng"}],"traditional":"並發症"},{"id":"并购","hanzi":"并购","pinyin":"bìnggòu","meaning_vi":"sáp nhập và mua lại (M&A)","explanation":"并 (hợp nhất) + 购 (mua lại).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"两家银行宣布并购。","pinyin":"Liǎng jiā yínháng xuānbù bìnggòu.","vi":"Hai ngân hàng tuyên bố sáp nhập."},{"type":"simple","zh":"这家科技公司去年并购了三家小型初创企业。","pinyin":"Zhè jiā kējì gōngsī qùnián bìnggòule sān jiā xiǎoxíng chūchuàng qǐyè.","vi":"Năm ngoái, công ty công nghệ này đã thâu tóm ba doanh nghiệp khởi nghiệp nhỏ."},{"type":"compound","zh":"虽然并购谈判持续了半年，但是双方最终没能达成协议。","pinyin":"Suīrán bìnggòu tánpàn chíxùle bàn nián, dànshì shuāngfāng zuìzhōng méi néng dáchéng xiéyì.","vi":"Tuy cuộc đàm phán sáp nhập kéo dài nửa năm nhưng cuối cùng hai bên vẫn không đạt được thỏa thuận."}],"related":[{"hanzi":"收购","pinyin":"shōugòu","vi":"thu mua"},{"hanzi":"合并","pinyin":"hébìng","vi":"sáp nhập"},{"hanzi":"兼并","pinyin":"jiānbìng","vi":"thôn tính"},{"hanzi":"企业","pinyin":"qǐyè","vi":"doanh nghiệp"}],"traditional":"並購"},{"id":"病菌","hanzi":"病菌","pinyin":"bìngjūn","meaning_vi":"vi khuẩn gây bệnh","explanation":"病 (病) + 菌 (vi khuẩn/nấm).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","khoa-hoc"],"image":"🦠","examples":[{"type":"basic","zh":"手上有很多病菌。","pinyin":"Shǒushang yǒu hěn duō bìngjūn.","vi":"Trên tay có rất nhiều vi khuẩn gây bệnh."},{"type":"simple","zh":"夏天的剩饭放在室温下很容易滋生病菌。","pinyin":"Xiàtiān de shèngfàn fàng zài shìwēn xià hěn róngyì zīshēng bìngjūn.","vi":"Cơm thừa mùa hè để ở nhiệt độ phòng rất dễ sinh vi khuẩn gây bệnh."},{"type":"compound","zh":"只要饭前认真洗手，就能挡住大部分病菌。","pinyin":"Zhǐyào fàn qián rènzhēn xǐshǒu, jiù néng dǎngzhù dàbùfen bìngjūn.","vi":"Chỉ cần rửa tay kỹ trước khi ăn là có thể ngăn được phần lớn vi khuẩn gây bệnh."}],"related":[{"hanzi":"细菌","pinyin":"xìjūn","vi":"vi khuẩn"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"传染","pinyin":"chuánrǎn","vi":"lây nhiễm"},{"hanzi":"消毒","pinyin":"xiāodú","vi":"khử trùng"}]},{"id":"病历","hanzi":"病历","pinyin":"bìnglì","meaning_vi":"bệnh án","explanation":"病 (病) + 历 (lịch sử/trải qua).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"📋","examples":[{"type":"basic","zh":"请带好你的病历。","pinyin":"Qǐng dài hǎo nǐ de bìnglì.","vi":"Xin hãy mang theo bệnh án của bạn."},{"type":"simple","zh":"医生翻看了她过去五年的病历才开药。","pinyin":"Yīshēng fānkànle tā guòqù wǔ nián de bìnglì cái kāiyào.","vi":"Bác sĩ xem lại bệnh án năm năm qua của cô ấy rồi mới kê đơn."},{"type":"compound","zh":"自从医院用了电子病历，病人就不用再带厚厚的本子了。","pinyin":"Zìcóng yīyuàn yòngle diànzǐ bìnglì, bìngrén jiù bú yòng zài dài hòu hòu de běnzi le.","vi":"Từ khi bệnh viện dùng bệnh án điện tử, bệnh nhân không cần mang theo những cuốn sổ dày cộp nữa."}],"related":[{"hanzi":"病情","pinyin":"bìngqíng","vi":"tình trạng bệnh"},{"hanzi":"诊断","pinyin":"zhěnduàn","vi":"chẩn đoán"},{"hanzi":"处方","pinyin":"chǔfāng","vi":"đơn thuốc"},{"hanzi":"档案","pinyin":"dàng'àn","vi":"hồ sơ"}],"traditional":"病歷"},{"id":"病情","hanzi":"病情","pinyin":"bìngqíng","meaning_vi":"tình trạng bệnh","explanation":"病 (病) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他的病情好转了。","pinyin":"Tā de bìngqíng hǎozhuǎn le.","vi":"Bệnh tình của ông ấy đã chuyển biến tốt."},{"type":"simple","zh":"医生每天早上都向家属通报病人的病情。","pinyin":"Yīshēng měitiān zǎo Shangdōu xiàng jiāshǔ tōngbào bìngrén de bìngqíng.","vi":"Sáng nào bác sĩ cũng thông báo tình trạng bệnh của bệnh nhân cho người nhà."},{"type":"compound","zh":"一旦病情出现变化，护士就会马上通知值班医生。","pinyin":"Yídàn bìngqíng chūxiàn biànhuà, hùshi jiù huì mǎshàng tōngzhī zhíbān yīshēng.","vi":"Một khi bệnh tình có thay đổi, y tá sẽ lập tức báo cho bác sĩ trực."}],"related":[{"hanzi":"病历","pinyin":"bìnglì","vi":"bệnh án"},{"hanzi":"病因","pinyin":"bìngyīn","vi":"nguyên nhân bệnh"},{"hanzi":"恶化","pinyin":"èhuà","vi":"chuyển biến xấu"},{"hanzi":"好转","pinyin":"hǎozhuǎn","vi":"chuyển biến tốt"}]},{"id":"病因","hanzi":"病因","pinyin":"bìngyīn","meaning_vi":"nguyên nhân gây bệnh","explanation":"病 (病) + 因 (nguyên nhân/nhân tố).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"病因还不清楚。","pinyin":"Bìngyīn hái bù qīngchu.","vi":"Nguyên nhân gây bệnh vẫn chưa rõ."},{"type":"simple","zh":"专家组花了一个月才查明这种怪病的病因。","pinyin":"Zhuānjiā zǔ huāle yí gèyuè cái chámíng zhè zhǒng guài bìng de bìngyīn.","vi":"Tổ chuyên gia mất một tháng mới tìm ra nguyên nhân của căn bệnh lạ này."},{"type":"compound","zh":"只有找到真正的病因，治疗才能对症下药。","pinyin":"Zhǐyǒu zhǎodào zhēnzhèng de bìngyīn, zhìliáo cáinéng duìzhèngxiàyào.","vi":"Chỉ khi tìm ra nguyên nhân gây bệnh thực sự thì việc điều trị mới có thể đúng bệnh đúng thuốc."}],"related":[{"hanzi":"病情","pinyin":"bìngqíng","vi":"tình trạng bệnh"},{"hanzi":"原因","pinyin":"yuányīn","vi":"nguyên nhân"},{"hanzi":"病症","pinyin":"bìngzhèng","vi":"chứng bệnh"},{"hanzi":"诊断","pinyin":"zhěnduàn","vi":"chẩn đoán"}]},{"id":"病症","hanzi":"病症","pinyin":"bìngzhèng","meaning_vi":"chứng bệnh, bệnh tật","explanation":"病 + 症 (triệu chứng).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"这种病症很少见。","pinyin":"Zhè zhǒng bìngzhèng hěn shǎojiàn.","vi":"Chứng bệnh này rất hiếm gặp."},{"type":"simple","zh":"中医通过把脉来判断病人的病症。","pinyin":"Zhōngyī tōngguò bǎ mài lái pànduàn bìngrén de bìngzhèng.","vi":"Đông y bắt mạch để chẩn đoán chứng bệnh của người bệnh."},{"type":"compound","zh":"虽然两种病症看起来很像，但是治疗方法完全不同。","pinyin":"Suīrán liǎng zhǒng bìngzhèng kànqǐlái hěn xiàng, dànshì zhìliáo fāngfǎ wánquán bùtóng.","vi":"Tuy hai chứng bệnh trông rất giống nhau nhưng phương pháp điều trị hoàn toàn khác."}],"related":[{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"},{"hanzi":"疾病","pinyin":"jíbìng","vi":"bệnh tật"},{"hanzi":"病因","pinyin":"bìngyīn","vi":"nguyên nhân bệnh"},{"hanzi":"并发症","pinyin":"bìngfāzhèng","vi":"biến chứng"}]},{"id":"并重","hanzi":"并重","pinyin":"bìngzhòng","meaning_vi":"coi trọng ngang nhau","explanation":"并 (cùng) + 重 (coi trọng).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"学习和锻炼要并重。","pinyin":"Xuéxí hé duànliàn yào bìngzhòng.","vi":"Học tập và rèn luyện thân thể phải được coi trọng như nhau."},{"type":"simple","zh":"这所职业学校一直坚持理论与实践并重。","pinyin":"Zhè suǒ zhíyè xuéxiào yìzhí jiānchí lǐlùn yǔ shíjiàn bìngzhòng.","vi":"Ngôi trường dạy nghề này luôn kiên trì coi trọng ngang nhau cả lý thuyết lẫn thực hành."},{"type":"compound","zh":"如果发展经济和保护环境不能并重，子孙后代就要付出代价。","pinyin":"Rúguǒ fāzhǎn jīngjì hé bǎohù huánjìng bù néng bìngzhòng, zǐsūn hòudài jiùyào fùchū dàijià.","vi":"Nếu không coi trọng ngang nhau phát triển kinh tế và bảo vệ môi trường thì con cháu đời sau sẽ phải trả giá."}],"related":[{"hanzi":"兼顾","pinyin":"jiāngù","vi":"chăm lo cả hai"},{"hanzi":"并举","pinyin":"bìngjǔ","vi":"tiến hành song song"},{"hanzi":"重视","pinyin":"zhòngshì","vi":"coi trọng"},{"hanzi":"同等","pinyin":"tóngděng","vi":"ngang nhau"}],"traditional":"並重"},{"id":"伯父","hanzi":"伯父","pinyin":"bófù","meaning_vi":"bác trai (anh trai bố)","explanation":"伯 (bá – anh cả, bác) + 父 (phụ – cha) → bác trai, anh của cha. Văn nói thường gọi 伯伯 hoặc 大伯; vợ của bác là 伯母.","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"👨","examples":[{"type":"basic","zh":"伯父住在乡下。","pinyin":"Bófù zhùzài xiāngxia.","vi":"Bác trai tôi sống ở quê."},{"type":"simple","zh":"每年春节我们全家都去伯父家吃团圆饭。","pinyin":"Měinián Chūnjié wǒmen quánjiā dōu qù bófù jiā chī tuányuánfàn.","vi":"Tết năm nào cả nhà tôi cũng đến nhà bác trai ăn bữa cơm đoàn viên."},{"type":"compound","zh":"伯父虽然比爸爸大十岁，但是身体比爸爸还好。","pinyin":"Bófù suīrán bǐ bàba dà shí suì, dànshì shēntǐ bǐ bàba hái hǎo.","vi":"Bác trai tuy lớn hơn bố mười tuổi nhưng sức khỏe còn tốt hơn bố."}],"related":[{"hanzi":"伯母","pinyin":"bómǔ","vi":"bác gái"},{"hanzi":"叔叔","pinyin":"shūshu","vi":"chú"},{"hanzi":"舅舅","pinyin":"jiùjiu","vi":"cậu"},{"hanzi":"姑姑","pinyin":"gūgu","vi":"cô"}]},{"id":"薄利多销","hanzi":"薄利多销","pinyin":"bólì-duōxiāo","meaning_vi":"lãi ít bán nhiều (chiến lược kinh doanh)","explanation":"薄利 + 多销. Thành ngữ kinh doanh.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"🛍️","examples":[{"type":"basic","zh":"这家店薄利多销。","pinyin":"Zhè jiā diàn bólìduōxiāo.","vi":"Cửa hàng này lãi ít bán nhiều."},{"type":"simple","zh":"社区超市靠薄利多销留住了很多老顾客。","pinyin":"Shèqū chāoshì kào bólìduōxiāo liúzhùle hěn duō lǎo gùkè.","vi":"Siêu thị trong khu dân cư giữ chân được nhiều khách quen nhờ lãi ít bán nhiều."},{"type":"compound","zh":"虽然每件衣服只赚几块钱，但是薄利多销让他一年赚了不少。","pinyin":"Suīrán měi jiàn yīfu zhǐ zhuàn jǐ kuài qián, dànshì bólìduōxiāo ràng tā yì nián zhuànle bùshǎo.","vi":"Tuy mỗi bộ quần áo chỉ lãi vài đồng nhưng nhờ lãi ít bán nhiều mà một năm anh ấy kiếm được kha khá."}],"related":[{"hanzi":"薄利","pinyin":"bólì","vi":"lãi mỏng"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"促销","pinyin":"cùxiāo","vi":"khuyến mãi"},{"hanzi":"暴利","pinyin":"bàolì","vi":"lãi khủng"}],"traditional":"薄利多銷"},{"id":"博览群书","hanzi":"博览群书","pinyin":"bólǎn-qúnshū","meaning_vi":"đọc rộng biết nhiều sách vở","explanation":"博 (博) + 览 (duyệt xem/triển lãm) + 群 (đàn) + 书 (sách).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他从小博览群书。","pinyin":"Tā cóngxiǎo bólǎnqúnshū.","vi":"Từ nhỏ anh ấy đã đọc rộng biết nhiều."},{"type":"simple","zh":"这位博览群书的老教授能背出很多古诗。","pinyin":"Zhè wèi bólǎnqúnshū de lǎo jiàoshòu néng bèi chū hěn duō gǔshī.","vi":"Vị giáo sư già đọc rộng biết nhiều này có thể đọc thuộc lòng rất nhiều bài thơ cổ."},{"type":"compound","zh":"只有博览群书，写文章时才能做到旁征博引。","pinyin":"Zhǐyǒu bólǎnqúnshū, xiě wénzhāng shí cáinéng zuòdào páng zhēng bó yǐn.","vi":"Chỉ khi đọc nhiều sách thì lúc viết văn mới có thể dẫn chứng phong phú."}],"related":[{"hanzi":"学富五车","pinyin":"xuéfùwǔchē","vi":"học rộng tài cao"},{"hanzi":"博学多才","pinyin":"bóxuéduōcái","vi":"học rộng nhiều tài"},{"hanzi":"读书","pinyin":"dúshū","vi":"đọc sách"},{"hanzi":"不学无术","pinyin":"bùxuéwúshù","vi":"dốt nát vô dụng"}],"traditional":"博覽群書"},{"id":"博弈","hanzi":"博弈","pinyin":"bóyì","meaning_vi":"đánh cờ; đấu trí, cuộc đọ sức (giữa các bên)","explanation":"博 + 弈 (đánh cờ). Cụm: 博弈论.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-viec"],"image":"♟️","examples":[{"type":"basic","zh":"这是一场长期博弈。","pinyin":"Zhè shì yì chǎng chángqī bóyì.","vi":"Đây là một cuộc đấu trí lâu dài."},{"type":"simple","zh":"买卖双方在价格上进行了几轮博弈。","pinyin":"Mǎimài shuāngfāng zài jiàgé shang jìnxíngle jǐ lún bóyì.","vi":"Bên mua và bên bán đã đấu trí mấy vòng về giá cả."},{"type":"compound","zh":"如果双方都只顾自己的利益，这场博弈就没有赢家。","pinyin":"Rúguǒ shuāngfāng dōu zhǐgù zìjǐ de lìyì, zhè chǎng bóyì jiù méiyǒu yíngjiā.","vi":"Nếu cả hai bên đều chỉ lo lợi ích của mình thì cuộc đấu trí này sẽ không có người thắng."}],"related":[{"hanzi":"博弈论","pinyin":"bóyìlùn","vi":"lý thuyết trò chơi"},{"hanzi":"较量","pinyin":"jiàoliàng","vi":"đọ sức"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"下棋","pinyin":"xiàqí","vi":"đánh cờ"}]},{"id":"伯仲","hanzi":"伯仲","pinyin":"bózhòng","meaning_vi":"anh em, ngang tài ngang sức (不分伯仲)","explanation":"伯 (anh cả) + 仲 (anh hai).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"⚖️","examples":[{"type":"basic","zh":"两人实力不分伯仲。","pinyin":"Liǎng rén shílì bùfēn bózhòng.","vi":"Thực lực của hai người ngang tài ngang sức."},{"type":"simple","zh":"这两位小提琴手的技巧难分伯仲。","pinyin":"Zhè liǎng wèi xiǎotíqín shǒu de jìqiǎo nán fēn bózhòng.","vi":"Kỹ thuật của hai nghệ sĩ vĩ cầm này khó phân cao thấp."},{"type":"compound","zh":"虽然两队的比分咬得很紧，但是实力其实在伯仲之间。","pinyin":"Suīrán liǎng duì de bǐfēn yǎo de hěn jǐn, dànshì shílì qí shízài bózhòngzhījiān.","vi":"Tuy tỷ số của hai đội bám đuổi sát nút nhưng thực lực thật ra là ngang ngửa nhau."}],"related":[{"hanzi":"不分伯仲","pinyin":"bùfēnbózhòng","vi":"ngang tài ngang sức"},{"hanzi":"伯仲之间","pinyin":"bózhòngzhījiān","vi":"sàn sàn nhau"},{"hanzi":"不相上下","pinyin":"bùxiāngshàngxià","vi":"ngang ngửa"},{"hanzi":"兄弟","pinyin":"xiōngdì","vi":"anh em"}]},{"id":"不耻下问","hanzi":"不耻下问","pinyin":"bùchǐ-xiàwèn","meaning_vi":"không xấu hổ khi học hỏi người dưới mình","explanation":"Danh ngôn Khổng Tử. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🙇","examples":[{"type":"basic","zh":"学习要不耻下问。","pinyin":"Xuéxí yàobù chǐ xià wèn.","vi":"Học tập phải không ngại hỏi người dưới mình."},{"type":"simple","zh":"这位老专家不耻下问，常向年轻同事请教电脑问题。","pinyin":"Zhè wèi lǎo zhuānjiā bù chǐ xià wèn, cháng xiàng niánqīng tóngshì qǐngjiào diànnǎo wèntí.","vi":"Vị chuyên gia lớn tuổi này không ngại học hỏi, thường hỏi đồng nghiệp trẻ về máy tính."},{"type":"compound","zh":"因为他总是不耻下问，所以进步得特别快。","pinyin":"Yīnwèi tā zǒngshì bù chǐ xià wèn, suǒyǐ jìnbù de tèbié kuài.","vi":"Vì anh ấy luôn không ngại hỏi người dưới mình nên tiến bộ rất nhanh."}],"related":[{"hanzi":"虚心","pinyin":"xūxīn","vi":"khiêm tốn"},{"hanzi":"请教","pinyin":"qǐngjiào","vi":"thỉnh giáo"},{"hanzi":"好学","pinyin":"hàoxué","vi":"ham học"},{"hanzi":"自以为是","pinyin":"zìyǐwéishì","vi":"tự cho là đúng"}],"traditional":"不恥下問"},{"id":"不欢而散","hanzi":"不欢而散","pinyin":"bùhuān-érsàn","meaning_vi":"chia tay trong không khí không vui (cuộc họp/hẹn)","explanation":"不欢而散: không (不) vui (欢) mà (而) tan (散) → cuộc họp, buổi gặp kết thúc trong không khí không vui vì bất đồng.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"😒","examples":[{"type":"basic","zh":"会议不欢而散。","pinyin":"Huìyì bù huān ér sàn.","vi":"Cuộc họp kết thúc trong không khí không vui."},{"type":"simple","zh":"因为一句玩笑，同学聚会最后不欢而散。","pinyin":"Yīnwèi yíjù wánxiào, tóngxué jùhuì zuìhòu bù huān ér sàn.","vi":"Chỉ vì một câu đùa mà buổi họp lớp cuối cùng tan trong không vui."},{"type":"compound","zh":"双方一谈到价格就吵了起来，最后不欢而散。","pinyin":"Shuāngfāng yì tándào jiàgé jiù chǎole qǐlái, zuìhòu bù huān ér sàn.","vi":"Hai bên vừa bàn đến giá cả đã cãi nhau, cuối cùng chia tay trong không vui."}],"related":[{"hanzi":"闹翻","pinyin":"nàofān","vi":"cãi nhau trở mặt"},{"hanzi":"散会","pinyin":"sànhuì","vi":"tan họp"},{"hanzi":"尽兴而归","pinyin":"jìnxìng'érguī","vi":"vui hết mình mới về"},{"hanzi":"争吵","pinyin":"zhēngchǎo","vi":"cãi vã"}],"traditional":"不歡而散"},{"id":"不寒而栗","hanzi":"不寒而栗","pinyin":"bùhán-érlì","meaning_vi":"không lạnh mà run (sợ hãi rùng mình)","explanation":"不寒而栗: không (不) lạnh (寒) mà (而) run (栗) → sợ hãi đến rùng mình. Ví dụ: 令人不寒而栗.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"想起那晚我就不寒而栗。","pinyin":"Xiǎngqǐ nà wǎn wǒ jiù bù hán ér lì.","vi":"Nhớ lại đêm hôm đó tôi vẫn rùng mình."},{"type":"simple","zh":"悬崖边的玻璃栈道让游客不寒而栗。","pinyin":"Xuányá biān de bōli zhàndào ràng yóukè bù hán ér lì.","vi":"Cây cầu kính bên vách núi khiến du khách sợ đến rùng mình."},{"type":"compound","zh":"一看到监控里那个陌生人的脸，她就不寒而栗。","pinyin":"Yí kàndào jiānkòng lǐ nà ge mòshēngrén de liǎn, tā jiù bù hán ér lì.","vi":"Vừa nhìn thấy khuôn mặt người lạ trong camera giám sát, cô ấy liền rùng mình sợ hãi."}],"related":[{"hanzi":"毛骨悚然","pinyin":"máogǔsǒngrán","vi":"sởn tóc gáy"},{"hanzi":"胆战心惊","pinyin":"dǎnzhànxīnjīng","vi":"kinh hồn bạt vía"},{"hanzi":"害怕","pinyin":"hàipà","vi":"sợ hãi"},{"hanzi":"发抖","pinyin":"fādǒu","vi":"run rẩy"}],"traditional":"不寒而慄"},{"id":"不合时宜","hanzi":"不合时宜","pinyin":"bùhé-shíyí","meaning_vi":"không hợp thời, lỗi thời","explanation":"不合 (không hợp) + 时宜 (thời nghi – điều phù hợp với thời thế) → không hợp thời; chỉ lời nói, việc làm không đúng lúc, lỗi thời hoặc lạc lõng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕰️","examples":[{"type":"basic","zh":"这套西装不合时宜。","pinyin":"Zhè tào xīzhuāng bùhé shíyí.","vi":"Bộ com-lê này không hợp thời."},{"type":"simple","zh":"他在葬礼上开了一个不合时宜的玩笑。","pinyin":"Tā zài zànglǐ shang kāile yí gè bùhé shíyí de wánxiào.","vi":"Anh ta đã nói một câu đùa không đúng lúc trong đám tang."},{"type":"compound","zh":"虽然这些老规矩已经不合时宜，但是村里的老人还在坚持。","pinyin":"Suīrán zhèxiē lǎo guīju yǐjīng bùhé shíyí, dànshì cūnlǐ de lǎorén hái zài jiānchí.","vi":"Tuy những lệ cũ này đã lỗi thời nhưng các cụ già trong làng vẫn giữ."}],"related":[{"hanzi":"过时","pinyin":"guòshí","vi":"lỗi thời"},{"hanzi":"落伍","pinyin":"luòwǔ","vi":"tụt hậu"},{"hanzi":"不合适","pinyin":"bùhéshì","vi":"không phù hợp"},{"hanzi":"与时俱进","pinyin":"yǔshíjùjìn","vi":"theo kịp thời đại"}],"traditional":"不合時宜"},{"id":"部件","hanzi":"部件","pinyin":"bùjiàn","meaning_vi":"linh kiện, bộ phận máy móc","explanation":"部 (phần) + 件 (vật).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","do-vat"],"image":"🔩","examples":[{"type":"basic","zh":"这个部件坏了。","pinyin":"Zhè ge bùjiàn huàile.","vi":"Linh kiện này hỏng rồi."},{"type":"simple","zh":"工程师把发动机拆成了几百个部件。","pinyin":"Gōngchéngshī bǎ fādòngjī chāi chéngle jǐ bǎi gè bùjiàn.","vi":"Kỹ sư đã tháo động cơ ra thành mấy trăm bộ phận."},{"type":"compound","zh":"如果关键部件要从国外进口，维修时间就会拖得很长。","pinyin":"Rúguǒ guānjiàn bùjiàn yào cóng guówài jìnkǒu, wéixiū shíjiān jiù huì tuō de hěn cháng.","vi":"Nếu linh kiện then chốt phải nhập khẩu từ nước ngoài thì thời gian sửa chữa sẽ kéo dài."}],"related":[{"hanzi":"零件","pinyin":"língjiàn","vi":"linh kiện"},{"hanzi":"配件","pinyin":"pèijiàn","vi":"phụ kiện"},{"hanzi":"组件","pinyin":"zǔjiàn","vi":"bộ phận"},{"hanzi":"机器","pinyin":"jīqì","vi":"máy móc"}]},{"id":"不解之缘","hanzi":"不解之缘","pinyin":"bùjiě-zhīyuán","meaning_vi":"mối duyên không thể tách rời","explanation":"不解 (bất giải – không gỡ ra được) + 之缘 (duyên) → mối duyên không gỡ ra được; ví sự gắn bó sâu sắc lâu dài. VD: 与音乐结下了不解之缘.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"他与京剧结下了不解之缘。","pinyin":"Tā yǔ Jīngjù jié xiàle bùjiě zhī yuán.","vi":"Ông ấy đã gắn bó keo sơn với kinh kịch."},{"type":"simple","zh":"这位老船长一辈子都和大海有着不解之缘。","pinyin":"Zhè wèi lǎo chuánzhǎng yíbèizi dōu hé dàhǎi yǒuzhe bùjiě zhī yuán.","vi":"Cả đời vị thuyền trưởng già này gắn bó không rời với biển cả."},{"type":"compound","zh":"自从十岁那年读了第一本武侠小说，他就和写作结下了不解之缘。","pinyin":"Zìcóng shí suì nà nián dúle dìyī běn wǔxiáxiǎoshuō, tā jiù hé xiězuò jié xiàle bùjiě zhī yuán.","vi":"Từ năm mười tuổi đọc cuốn tiểu thuyết võ hiệp đầu tiên, anh ấy đã gắn bó keo sơn với nghề viết."}],"related":[{"hanzi":"缘分","pinyin":"yuánfèn","vi":"duyên phận"},{"hanzi":"情缘","pinyin":"qíngyuán","vi":"tình duyên"},{"hanzi":"结缘","pinyin":"jiéyuán","vi":"kết duyên"},{"hanzi":"渊源","pinyin":"yuānyuán","vi":"nguồn gốc sâu xa"}],"traditional":"不解之緣"},{"id":"不堪一击","hanzi":"不堪一击","pinyin":"bùkān-yìjī","meaning_vi":"yếu ớt không chịu nổi một đòn","explanation":"不堪一击: không (不) chịu nổi (堪) một (一) đòn (击) → quá yếu ớt, một đòn là sụp đổ. Thường dùng cho quân đội, lý lẽ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🥀","examples":[{"type":"basic","zh":"敌军不堪一击。","pinyin":"Díjūn bùkān yì jī.","vi":"Quân địch yếu ớt không chịu nổi một đòn."},{"type":"simple","zh":"这支球队的防线在对手面前显得不堪一击。","pinyin":"Zhè zhī qiúduì de fángxiàn zài duìshǒu miànqián xiǎnde bùkān yì jī.","vi":"Hàng phòng ngự của đội bóng này tỏ ra yếu ớt trước đối thủ."},{"type":"compound","zh":"别看他平时很自信，一遇到批评就不堪一击。","pinyin":"Biékàn tā píngshí hěn zìxìn, yí yùdào pīpíng jiù bùkān yì jī.","vi":"Đừng thấy bình thường anh ta tự tin, hễ gặp lời phê bình là gục ngay."}],"related":[{"hanzi":"一触即溃","pinyin":"yíchùjíkuì","vi":"chạm vào là đổ"},{"hanzi":"脆弱","pinyin":"cuìruò","vi":"yếu ớt"},{"hanzi":"弱不禁风","pinyin":"ruòbùjīnfēng","vi":"yếu đuối mong manh"},{"hanzi":"坚不可摧","pinyin":"jiānbùkěcuī","vi":"không thể phá vỡ"}],"traditional":"不堪一擊"},{"id":"不可估量","hanzi":"不可估量","pinyin":"bùkě-gūliàng","meaning_vi":"không thể đo đếm được (tổn thất/giá trị to lớn)","explanation":"不可估量: không (不) thể (可) ước lượng (估量) được → to lớn đến mức không đo đếm được. Ví dụ: 损失不可估量, 不可估量的价值.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"♾️","examples":[{"type":"basic","zh":"损失不可估量。","pinyin":"Sǔnshī bùkě gūliàng.","vi":"Tổn thất không thể đo đếm được."},{"type":"simple","zh":"这项新技术对农业的影响不可估量。","pinyin":"Zhè xiàng xīnjìshù duì nóngyè de yǐngxiǎng bùkě gūliàng.","vi":"Ảnh hưởng của công nghệ mới này đối với nông nghiệp là không thể đo lường."},{"type":"compound","zh":"如果这批古籍被大火烧毁，损失将不可估量。","pinyin":"Rúguǒ zhè pī gǔjí bèi dàhuǒ shāohuǐ, sǔnshī jiāng bùkě gūliàng.","vi":"Nếu lô sách cổ này bị lửa thiêu rụi thì tổn thất sẽ không thể đo đếm."}],"related":[{"hanzi":"无法估量","pinyin":"wúfǎgūliàng","vi":"không thể ước lượng"},{"hanzi":"巨大","pinyin":"jùdà","vi":"to lớn"},{"hanzi":"估量","pinyin":"gūliàng","vi":"ước lượng"},{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"không đếm xuể"}]},{"id":"不可开交","hanzi":"不可开交","pinyin":"bùkě-kāijiāo","meaning_vi":"bận tối tăm mặt mũi; (cãi nhau) không dứt ra được","explanation":"Dùng sau 得 (忙得不可开交).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💼","examples":[{"type":"basic","zh":"最近忙得不可开交。","pinyin":"Zuìjìn máng de bùkě kāijiāo.","vi":"Dạo này bận tối tăm mặt mũi."},{"type":"simple","zh":"两个孩子为了一个玩具吵得不可开交。","pinyin":"Liǎng gè háizi wèile yí gè wánjù chǎo de bùkě kāijiāo.","vi":"Hai đứa trẻ cãi nhau không dứt chỉ vì một món đồ chơi."},{"type":"compound","zh":"一到年底，财务部就忙得不可开交，天天加班。","pinyin":"Yí dào niándǐ, cáiwùbù jiù máng de bùkě kāijiāo, tiāntiān jiābān.","vi":"Hễ đến cuối năm, phòng tài vụ lại bận tối mắt, ngày nào cũng tăng ca."}],"related":[{"hanzi":"忙碌","pinyin":"mánglù","vi":"bận rộn"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống tay chân"},{"hanzi":"争吵","pinyin":"zhēngchǎo","vi":"cãi vã"},{"hanzi":"忙得不可开交","pinyin":"máng de bùkě kāijiāo","vi":"bận tối mắt"}],"traditional":"不可開交"},{"id":"步履","hanzi":"步履","pinyin":"bùlǚ","meaning_vi":"bước chân (văn viết)","explanation":"步 (bước) + 履 (giày/bước đi).","hsk_level":"7-9","tags":["danh-tu"],"image":"👣","examples":[{"type":"basic","zh":"老人步履蹒跚。","pinyin":"Lǎorén bùlǚ pánshān.","vi":"Cụ già bước đi tập tễnh."},{"type":"simple","zh":"受伤的士兵步履艰难地走回了营地。","pinyin":"Shòushāng de shìbīng bùlǚ jiānnán de zǒu huíle yíngdì.","vi":"Người lính bị thương lê bước khó nhọc trở về doanh trại."},{"type":"compound","zh":"虽然已经九十岁了，但是爷爷的步履依然十分稳健。","pinyin":"Suīrán yǐjīng jiǔshí suì le, dànshì yéye de bùlǚ yīrán shífēn wěnjiàn.","vi":"Tuy đã chín mươi tuổi nhưng bước chân của ông vẫn rất vững vàng."}],"related":[{"hanzi":"步伐","pinyin":"bùfá","vi":"bước chân"},{"hanzi":"脚步","pinyin":"jiǎobù","vi":"bước chân"},{"hanzi":"步履蹒跚","pinyin":"bùlǚpánshān","vi":"bước đi tập tễnh"},{"hanzi":"步履维艰","pinyin":"bùlǚwéijiān","vi":"bước đi khó nhọc"}]},{"id":"不屈","hanzi":"不屈","pinyin":"bùqū","meaning_vi":"bất khuất, không khuất phục","explanation":"不 + 屈 (cúi đầu).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✊","examples":[{"type":"basic","zh":"他有一颗不屈的心。","pinyin":"Tā yǒu yì kē bùqū de xīn.","vi":"Anh ấy có một trái tim bất khuất."},{"type":"simple","zh":"这位老战士在敌人的监狱里始终坚强不屈。","pinyin":"Zhè wèi lǎo zhànshì zài dírén de jiānyù lǐ shǐzhōng jiānqiáng bùqū.","vi":"Người chiến sĩ già này luôn kiên cường bất khuất trong nhà tù của kẻ thù."},{"type":"compound","zh":"即使连续三次创业失败，她也凭着一股不屈的劲头重新站了起来。","pinyin":"Jíshǐ liánxù sāncì chuàngyè shībài, tā yě píngzhe yì gǔ bùqū de jìntóu chóngxīn zhànle qǐlái.","vi":"Dù khởi nghiệp thất bại ba lần liên tiếp, cô ấy vẫn nhờ ý chí bất khuất mà đứng dậy lần nữa."}],"related":[{"hanzi":"不屈不挠","pinyin":"bùqūbùnáo","vi":"kiên cường bất khuất"},{"hanzi":"坚强","pinyin":"jiānqiáng","vi":"kiên cường"},{"hanzi":"屈服","pinyin":"qūfú","vi":"khuất phục"},{"hanzi":"宁死不屈","pinyin":"nìngsǐbùqū","vi":"thà chết không khuất phục"}]},{"id":"不失时机","hanzi":"不失时机","pinyin":"bùshī-shíjī","meaning_vi":"không bỏ lỡ thời cơ","explanation":"不失 (không để mất) + 时机 (thời cơ) → không bỏ lỡ thời cơ, nắm bắt đúng lúc mà hành động. Thường đi với 地: 不失时机地推出新产品.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"他不失时机地提出了建议。","pinyin":"Tā bùshī shíjī de tíchūle jiànyì.","vi":"Anh ấy đã kịp thời đưa ra đề xuất."},{"type":"simple","zh":"厂家不失时机地推出了夏季清凉新品。","pinyin":"Chǎngjiā bùshī shíjī de tuīchūle xiàjì qīngliáng xīnpǐn.","vi":"Nhà sản xuất không bỏ lỡ thời cơ, tung ra sản phẩm mát lạnh mới cho mùa hè."},{"type":"compound","zh":"对方一露出破绽，他就不失时机地发起了进攻。","pinyin":"Duìfāng yí lùchū pòzhàn, tā jiù bùshī shíjī de fāqǐle jìngōng.","vi":"Đối phương vừa để lộ sơ hở, anh ấy liền chớp thời cơ tấn công."}],"related":[{"hanzi":"抓住机会","pinyin":"zhuāzhùjīhuì","vi":"nắm bắt cơ hội"},{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"},{"hanzi":"把握时机","pinyin":"bǎwòshíjī","vi":"nắm thời cơ"},{"hanzi":"错失良机","pinyin":"cuòshīliángjī","vi":"bỏ lỡ thời cơ"}],"traditional":"不失時機"},{"id":"部首","hanzi":"部首","pinyin":"bùshǒu","meaning_vi":"bộ thủ (chữ Hán)","explanation":"部 (部) + 首 (bài (lượng từ thơ/ca khúc)).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🈷️","examples":[{"type":"basic","zh":"这个字的部首是水。","pinyin":"Zhè ge zì de bùshǒu shì shuǐ.","vi":"Bộ thủ của chữ này là bộ Thủy."},{"type":"simple","zh":"查字典时可以先按部首找到这个字。","pinyin":"Chá zìdiǎn shí kěyǐ xiān àn bùshǒu zhǎodào zhè ge zì.","vi":"Khi tra từ điển có thể tìm chữ này theo bộ thủ trước."},{"type":"compound","zh":"只要记住常用部首的意思，就能大概猜出生字的意思。","pinyin":"Zhǐyào jìzhù chángyòng bùshǒu de yìsi, jiù néng dàgài cāi chū shēngzì de yìsi.","vi":"Chỉ cần nhớ nghĩa của các bộ thủ thường dùng là có thể đoán đại khái nghĩa của chữ mới."}],"related":[{"hanzi":"偏旁","pinyin":"piānpáng","vi":"bộ thủ"},{"hanzi":"笔画","pinyin":"bǐhuà","vi":"nét chữ"},{"hanzi":"汉字","pinyin":"hànzì","vi":"chữ Hán"},{"hanzi":"字典","pinyin":"zìdiǎn","vi":"tự điển"}]},{"id":"部委","hanzi":"部委","pinyin":"bùwěi","meaning_vi":"các bộ và ủy ban (cơ quan chính phủ)","explanation":"部 (部) + 委 (ủy thác/ấm ức).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"多个部委联合发文。","pinyin":"Duōgè bùwěi liánhé fāwén.","vi":"Nhiều bộ ngành cùng ra văn bản liên tịch."},{"type":"simple","zh":"国务院有关部委正在研究新的住房补贴政策。","pinyin":"Guówùyuàn yǒuguān bùwěi zhèngzài yánjiū xīn de zhùfáng bǔtiē zhèngcè.","vi":"Các bộ ngành liên quan của Quốc vụ viện đang nghiên cứu chính sách trợ cấp nhà ở mới."},{"type":"compound","zh":"因为这个项目涉及多个部委，所以审批时间比较长。","pinyin":"Yīnwèi zhè ge xiàngmù shèjí duōgè bùwěi, suǒyǐ shěnpī shíjiān bǐjiào cháng.","vi":"Vì dự án này liên quan đến nhiều bộ ngành nên thời gian phê duyệt khá dài."}],"related":[{"hanzi":"部门","pinyin":"bùmén","vi":"ban ngành"},{"hanzi":"国务院","pinyin":"Guówùyuàn","vi":"Quốc vụ viện"},{"hanzi":"委员会","pinyin":"wěiyuánhuì","vi":"ủy ban"},{"hanzi":"政府","pinyin":"zhèngfǔ","vi":"chính phủ"}]},{"id":"不知不觉","hanzi":"不知不觉","pinyin":"bùzhī-bùjué","meaning_vi":"vô tình, lúc nào không hay biết","explanation":"不知 (không biết) + 不觉 (không nhận ra) → không hay không biết; chỉ việc xảy ra lúc nào không để ý. VD: 不知不觉天就黑了.","hsk_level":"7-9","tags":["thanh-ngu","pho-tu"],"image":"⏳","examples":[{"type":"basic","zh":"不知不觉天黑了。","pinyin":"Bùzhī bùjué tiānhēi le.","vi":"Trời tối lúc nào không hay."},{"type":"simple","zh":"我们在咖啡馆里不知不觉聊了三个小时。","pinyin":"Wǒmen zài kāfēiguǎn lǐ bùzhī bùjué liáole sān gè xiǎoshí.","vi":"Chúng tôi ngồi trong quán cà phê trò chuyện ba tiếng lúc nào không hay."},{"type":"compound","zh":"虽然每天只存十块钱，但是不知不觉已经存了一万多。","pinyin":"Suīrán měitiān zhǐ cún shí kuài qián, dànshì bùzhī bùjué yǐjīng cúnle yī wàn duō.","vi":"Tuy mỗi ngày chỉ tiết kiệm mười tệ nhưng lúc nào không hay đã để dành được hơn một vạn."}],"related":[{"hanzi":"无意中","pinyin":"wúyìzhōng","vi":"vô tình"},{"hanzi":"潜移默化","pinyin":"qiányímòhuà","vi":"thay đổi âm thầm"},{"hanzi":"不由自主","pinyin":"bùyóuzìzhǔ","vi":"không tự chủ được"},{"hanzi":"转眼","pinyin":"zhuǎnyǎn","vi":"chớp mắt"}],"traditional":"不知不覺"},{"id":"不测","hanzi":"不测","pinyin":"búcè","meaning_vi":"bất trắc, tai họa khó lường","explanation":"不 (bất – không) + 测 (trắc – đo lường, đoán) → không thể lường trước; chỉ tai họa bất ngờ, thường nói về tính mạng: 遭遇不测, 以防不测.","hsk_level":"7-9","tags":["danh-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"以防不测，带上手电。","pinyin":"Yǐfáng búcè, dàishang shǒudiàn.","vi":"Mang theo đèn pin để phòng bất trắc."},{"type":"simple","zh":"出海前渔民们都会检查救生衣以防不测。","pinyin":"Chūhǎi qián yúmínmen dōuhuì jiǎnchá jiùshēngyī yǐfáng búcè.","vi":"Trước khi ra khơi, ngư dân đều kiểm tra áo phao để phòng bất trắc."},{"type":"compound","zh":"万一他遭遇不测，这个家就失去了顶梁柱。","pinyin":"Wànyī tā zāoyù búcè, zhè ge jiā jiù shīqùle dǐngliángzhù.","vi":"Lỡ anh ấy gặp chuyện chẳng lành thì gia đình này sẽ mất đi trụ cột."}],"related":[{"hanzi":"意外","pinyin":"yìwài","vi":"bất ngờ"},{"hanzi":"风云不测","pinyin":"fēngyúnbúcè","vi":"chuyện khó lường"},{"hanzi":"灾祸","pinyin":"zāihuò","vi":"tai họa"},{"hanzi":"万一","pinyin":"wànyī","vi":"lỡ như"}],"traditional":"不測"},{"id":"不动产","hanzi":"不动产","pinyin":"búdòngchǎn","meaning_vi":"bất động sản","explanation":"不动 + 产 (tài sản).","hsk_level":"7-9","tags":["danh-tu","nha-cua","phap-luat"],"image":"🏢","examples":[{"type":"basic","zh":"房子属于不动产。","pinyin":"Fángzi shǔyú búdòngchǎn.","vi":"Nhà ở thuộc loại bất động sản."},{"type":"simple","zh":"他在市中心拥有好几处不动产。","pinyin":"Tā zài shìzhōngxīn yōngyǒu hǎojǐ chù búdòngchǎn.","vi":"Ông ấy sở hữu mấy bất động sản ở trung tâm thành phố."},{"type":"compound","zh":"如果要卖掉这处不动产，就必须先去登记中心办过户。","pinyin":"Rúguǒ yào màidiào zhè chù búdòngchǎn, jiù bìxū xiān qù dēngjì zhōngxīn bàn guòhù.","vi":"Nếu muốn bán bất động sản này thì phải đến trung tâm đăng ký làm thủ tục sang tên trước."}],"related":[{"hanzi":"房地产","pinyin":"fángdìchǎn","vi":"bất động sản"},{"hanzi":"动产","pinyin":"dòngchǎn","vi":"động sản"},{"hanzi":"财产","pinyin":"cáichǎn","vi":"tài sản"},{"hanzi":"房产","pinyin":"fángchǎn","vi":"nhà cửa"}],"traditional":"不動產"},{"id":"不负众望","hanzi":"不负众望","pinyin":"búfù-zhòngwàng","meaning_vi":"không phụ lòng mong đợi của mọi người","explanation":"不负 (bất phụ – không phụ) + 众望 (chúng vọng – kỳ vọng của mọi người) → không phụ lòng mong đợi của mọi người, làm được như ai cũng kỳ vọng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏆","examples":[{"type":"basic","zh":"他果然不负众望。","pinyin":"Tā guǒrán búfù zhòngwàng.","vi":"Anh ấy quả nhiên không phụ lòng mong đợi của mọi người."},{"type":"simple","zh":"这位年轻的门将不负众望地扑出了点球。","pinyin":"Zhè wèi niánqīng de ménjiàng búfù zhòngwàng de pū chūle diǎnqiú.","vi":"Thủ môn trẻ này đã không phụ kỳ vọng, cản phá thành công quả phạt đền."},{"type":"compound","zh":"她不但不负众望考上了医学院，而且拿到了全额奖学金。","pinyin":"Tā búdàn búfù zhòngwàng kǎoshàngle yīxuéyuàn, érqiě nádàole quán'é jiǎngxuéjīn.","vi":"Cô ấy không những không phụ lòng mọi người khi đỗ vào trường y mà còn giành được học bổng toàn phần."}],"related":[{"hanzi":"众望所归","pinyin":"zhòngwàngsuǒguī","vi":"lòng dân hướng về"},{"hanzi":"不辜负","pinyin":"bùgūfù","vi":"không phụ lòng"},{"hanzi":"期望","pinyin":"qīwàng","vi":"kỳ vọng"},{"hanzi":"辜负","pinyin":"gūfù","vi":"phụ lòng"}],"traditional":"不負眾望"},{"id":"不轨","hanzi":"不轨","pinyin":"bùguǐ","meaning_vi":"bất chính, phạm pháp","explanation":"不 (không) + 轨 (đường ray/quỹ đạo).","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"此人图谋不轨。","pinyin":"Cǐ rén túmóu bùguǐ.","vi":"Người này mưu đồ làm điều bất chính."},{"type":"simple","zh":"警察发现几个人在银行门口行为不轨。","pinyin":"Jǐngchá fāxiàn jǐ gè rén zài yínháng ménkǒu xíngwéi bùguǐ.","vi":"Cảnh sát phát hiện mấy người có hành vi mờ ám trước cửa ngân hàng."},{"type":"compound","zh":"一旦有人图谋不轨，监控系统就会立即报警。","pinyin":"Yídàn yǒurén túmóu bùguǐ, jiānkòng xìtǒng jiù huì lìjí bàojǐng.","vi":"Một khi có kẻ mưu đồ bất chính, hệ thống giám sát sẽ lập tức báo động."}],"related":[{"hanzi":"图谋不轨","pinyin":"túmóubùguǐ","vi":"mưu đồ bất chính"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"},{"hanzi":"越轨","pinyin":"yuèguǐ","vi":"vượt khuôn phép"},{"hanzi":"不法","pinyin":"bùfǎ","vi":"phi pháp"}],"traditional":"不軌"},{"id":"不公","hanzi":"不公","pinyin":"bùgōng","meaning_vi":"bất công","explanation":"不 (bất – không) + 公 (công – công bằng) → bất công, không công bằng. VD: 受到不公待遇; tương đương 不公平.","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"这个判决很不公。","pinyin":"Zhè ge pànjué hěn bùgōng.","vi":"Phán quyết này rất bất công."},{"type":"simple","zh":"她在网上讲述了自己在公司受到的不公待遇。","pinyin":"Tā zài wǎngshang jiǎngshùle zìjǐ zài gōngsī shòudào de bùgōng dàiyù.","vi":"Cô ấy kể trên mạng về sự đối xử bất công mà mình phải chịu ở công ty."},{"type":"compound","zh":"虽然比赛结果有些不公，但是他还是向对手表示了祝贺。","pinyin":"Suīrán bǐsài jiéguǒ yǒuxiē bùgōng, dànshì tā háishi xiàng duìshǒu biǎoshìle zhùhè.","vi":"Tuy kết quả trận đấu có phần bất công nhưng anh ấy vẫn chúc mừng đối thủ."}],"related":[{"hanzi":"不公平","pinyin":"bùgōngpíng","vi":"không công bằng"},{"hanzi":"公平","pinyin":"gōngpíng","vi":"công bằng"},{"hanzi":"不平","pinyin":"bùpíng","vi":"bất bình"},{"hanzi":"委屈","pinyin":"wěiqu","vi":"tủi thân"}]},{"id":"不计后果","hanzi":"不计后果","pinyin":"bújìhòuguǒ","meaning_vi":"bất chấp hậu quả","explanation":"不计 (bất kế – không tính đến) + 后果 (hậu quả) → bất chấp hậu quả, làm mà không tính đến kết quả xấu có thể xảy ra.","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他做事不计后果。","pinyin":"Tā zuòshì bújì hòuguǒ.","vi":"Anh ta làm việc bất chấp hậu quả."},{"type":"simple","zh":"那个司机为了赶时间不计后果地闯了红灯。","pinyin":"Nà ge sījī wèile gǎnshíjiān bújì hòuguǒ de chuǎngle hóngdēng.","vi":"Người tài xế đó vì vội mà bất chấp hậu quả vượt đèn đỏ."},{"type":"compound","zh":"年轻人一冲动就容易不计后果，事后才后悔。","pinyin":"Niánqīngrén yì chōngdòng jiù róngyì bújì hòuguǒ, shìhòu cái hòuhuǐ.","vi":"Người trẻ hễ bốc đồng là dễ bất chấp hậu quả, xong việc mới hối hận."}],"related":[{"hanzi":"不顾一切","pinyin":"búgùyíqiè","vi":"bất chấp tất cả"},{"hanzi":"鲁莽","pinyin":"lǔmǎng","vi":"lỗ mãng"},{"hanzi":"后果","pinyin":"hòuguǒ","vi":"hậu quả"},{"hanzi":"三思而后行","pinyin":"sānsī érhòu xíng","vi":"nghĩ kỹ rồi làm"}],"traditional":"不計後果"},{"id":"不胫而走","hanzi":"不胫而走","pinyin":"bújìng-érzǒu","meaning_vi":"không chân mà chạy (tin tức lan truyền cực nhanh)","explanation":"不胫而走: không (不) có chân (胫 – cẳng chân) mà (而) chạy (走) → tin tức lan truyền rất nhanh dù không ai cố ý truyền.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"消息不胫而走。","pinyin":"Xiāoxi bú jìng ér zǒu.","vi":"Tin tức lan truyền rất nhanh."},{"type":"simple","zh":"球星要转会的传闻在球迷中不胫而走。","pinyin":"Qiúxīng yào zhuǎnhuì de chuánwén zài qiúmí zhōng bú jìng ér zǒu.","vi":"Tin đồn ngôi sao bóng đá sắp chuyển nhượng lan nhanh trong giới cổ động viên."},{"type":"compound","zh":"校长辞职的消息还没正式公布，就已经在校园里不胫而走了。","pinyin":"Xiàozhǎng cízhí de xiāoxi hái méi zhèngshì gōngbù, jiù yǐjīng zài xiàoyuán lǐ bú jìng ér zǒu le.","vi":"Tin hiệu trưởng từ chức chưa được công bố chính thức mà đã lan khắp trường."}],"related":[{"hanzi":"传播","pinyin":"chuánbō","vi":"truyền bá"},{"hanzi":"一传十十传百","pinyin":"yì chuán shí shí chuán bǎi","vi":"một đồn mười mười đồn trăm"},{"hanzi":"流传","pinyin":"liúchuán","vi":"lưu truyền"},{"hanzi":"家喻户晓","pinyin":"jiāyùhùxiǎo","vi":"nhà nhà đều biết"}],"traditional":"不脛而走"},{"id":"不及物动词","hanzi":"不及物动词","pinyin":"bù jíwùdòngcí","meaning_vi":"nội động từ (ngữ pháp)","explanation":"不 (không) + 及 (kịp thời/đạt tới) + 物 (vật chất/sự vật) + 动 (动) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"游泳是不及物动词。","pinyin":"Yóuyǒng shì bù jíwùdòngcí.","vi":"\"Bơi\" là nội động từ."},{"type":"simple","zh":"不及物动词后面一般不能直接带宾语。","pinyin":"Bù jíwùdòngcí hòumiàn yìbān bù néng zhíjiē dài bīnyǔ.","vi":"Sau nội động từ thường không thể trực tiếp mang tân ngữ."},{"type":"compound","zh":"因为见面是不及物动词，所以不能说见面朋友。","pinyin":"Yīnwèi jiànmiàn shì bù jíwùdòngcí, suǒyǐ bù néng shuō jiànmiàn péngyou.","vi":"Vì \"gặp mặt\" là nội động từ nên không thể nói \"gặp mặt bạn bè\"."}],"related":[{"hanzi":"及物动词","pinyin":"jíwùdòngcí","vi":"ngoại động từ"},{"hanzi":"动词","pinyin":"dòngcí","vi":"động từ"},{"hanzi":"宾语","pinyin":"bīnyǔ","vi":"tân ngữ"},{"hanzi":"语法","pinyin":"yǔfǎ","vi":"ngữ pháp"}],"traditional":"不及物動詞"},{"id":"不可再生资源","hanzi":"不可再生资源","pinyin":"bù kězàishēngzīyuán","meaning_vi":"tài nguyên không tái tạo","explanation":"不 (không) + 可 (可) + 再 (tiếp tục/lặp lại) + 生 (sinh tồn/sinh động) + 资 (tài nguyên/tư bản) + 源 (nguồn gốc).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🛢️","examples":[{"type":"basic","zh":"石油是不可再生资源。","pinyin":"Shíyóu shì bù kězàishēngzīyuán.","vi":"Dầu mỏ là tài nguyên không tái tạo."},{"type":"simple","zh":"煤炭等不可再生资源总有一天会被用完。","pinyin":"Méitàn děng bù kězàishēngzīyuán zǒngyǒu yì tiān huì bèi yòngwán.","vi":"Than đá và các tài nguyên không tái tạo khác rồi sẽ có ngày bị dùng hết."},{"type":"compound","zh":"既然天然气是不可再生资源，我们就更应该节约使用。","pinyin":"Jìrán tiānránqì shì bù kězàishēngzīyuán, wǒmen jiù gèng yīnggāi jiéyuē shǐyòng.","vi":"Vì khí đốt thiên nhiên là tài nguyên không tái tạo nên chúng ta càng phải sử dụng tiết kiệm."}],"related":[{"hanzi":"可再生资源","pinyin":"kězàishēng zīyuán","vi":"tài nguyên tái tạo"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"石油","pinyin":"shíyóu","vi":"dầu mỏ"},{"hanzi":"煤炭","pinyin":"méitàn","vi":"than đá"}],"traditional":"不可再生資源"},{"id":"不忘初心","hanzi":"不忘初心","pinyin":"búwàng-chūxīn","meaning_vi":"không quên tâm nguyện ban đầu","explanation":"不 (không) + 忘 (quên) + 初 (初) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💖","examples":[{"type":"basic","zh":"做人要不忘初心。","pinyin":"Zuòrén yàobú wàng chūxīn.","vi":"Làm người phải không quên tâm nguyện ban đầu."},{"type":"simple","zh":"这位老医生行医四十年始终不忘初心。","pinyin":"Zhè wèi lǎo yīshēng xíngyī sìshí nián shǐzhōng bú wàng chūxīn.","vi":"Vị bác sĩ già hành nghề bốn mươi năm vẫn luôn giữ trọn tâm nguyện ban đầu."},{"type":"compound","zh":"即使公司做得再大，他也提醒自己不忘初心。","pinyin":"Jíshǐ gōngsī zuò de zài dà, tā yě tíxǐng zìjǐ bú wàng chūxīn.","vi":"Dù công ty có lớn đến đâu, anh ấy vẫn nhắc mình không quên tâm nguyện ban đầu."}],"related":[{"hanzi":"初心","pinyin":"chūxīn","vi":"tâm nguyện ban đầu"},{"hanzi":"牢记使命","pinyin":"láojìshǐmìng","vi":"ghi nhớ sứ mệnh"},{"hanzi":"初衷","pinyin":"chūzhōng","vi":"ý định ban đầu"},{"hanzi":"一如既往","pinyin":"yìrújìwǎng","vi":"trước sau như một"}]},{"id":"不懈","hanzi":"不懈","pinyin":"búxiè","meaning_vi":"không mệt mỏi, không ngừng nghỉ","explanation":"不 (bất – không) + 懈 (giải – lơi lỏng, lười) → không lơi lỏng, kiên trì bền bỉ. Thường gặp: 坚持不懈, 不懈努力.","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"💪","examples":[{"type":"basic","zh":"他们不懈地努力着。","pinyin":"Tāmen búxiè de nǔlì zhe.","vi":"Họ không ngừng nỗ lực."},{"type":"simple","zh":"经过十年不懈的研究，他终于找到了治疗方法。","pinyin":"Jīngguò shí nián búxiè de yánjiū, tā zhōngyú zhǎodàole zhìliáo fāngfǎ.","vi":"Sau mười năm nghiên cứu không mệt mỏi, ông ấy cuối cùng đã tìm ra phương pháp điều trị."},{"type":"compound","zh":"只要坚持不懈地练习，你的发音就一定会越来越标准。","pinyin":"Zhǐyào jiānchíbúxiè de liànxí, nǐ de fāyīn jiù yídìng huì yuèláiyuè biāozhǔn.","vi":"Chỉ cần kiên trì luyện tập không ngừng thì phát âm của bạn nhất định sẽ ngày càng chuẩn."}],"related":[{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì không mệt mỏi"},{"hanzi":"不懈努力","pinyin":"búxiènǔlì","vi":"nỗ lực không ngừng"},{"hanzi":"松懈","pinyin":"sōngxiè","vi":"lơ là"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"}]},{"id":"不屑","hanzi":"不屑","pinyin":"búxiè","meaning_vi":"khinh thường, không thèm","explanation":"不 (không) + 屑 (mảnh vụn).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"😒","examples":[{"type":"basic","zh":"她对此不屑一顾。","pinyin":"Tā duì cǐ búxiè yí gù.","vi":"Cô ấy chẳng thèm đoái hoài đến chuyện này."},{"type":"simple","zh":"他不屑地看了一眼对方递过来的名片。","pinyin":"Tā búxiè de kànle yìyǎn duìfāng dì guòlái de míngpiàn.","vi":"Anh ta liếc nhìn tấm danh thiếp đối phương đưa tới với vẻ khinh khỉnh."},{"type":"compound","zh":"虽然他嘴上表示不屑，但是心里其实很羡慕。","pinyin":"Suīrán tā zuǐ shang biǎoshì búxiè, dànshì xīnlǐ qíshí hěn xiànmù.","vi":"Tuy ngoài miệng tỏ vẻ khinh thường nhưng trong lòng anh ấy thật ra rất ngưỡng mộ."}],"related":[{"hanzi":"不屑一顾","pinyin":"búxièyígù","vi":"chẳng thèm ngó"},{"hanzi":"轻视","pinyin":"qīngshì","vi":"coi thường"},{"hanzi":"鄙视","pinyin":"bǐshì","vi":"khinh bỉ"},{"hanzi":"瞧不起","pinyin":"qiáobuqǐ","vi":"xem thường"}]},{"id":"不朽","hanzi":"不朽","pinyin":"bùxiǔ","meaning_vi":"bất hủ, trường tồn mãi mãi","explanation":"不 (bất – không) + 朽 (hủ – mục nát) → không mục nát, bất hủ; chỉ tinh thần, tác phẩm, công lao trường tồn. VD: 不朽的作品.","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"这是一部不朽之作。","pinyin":"Zhè shì yí bù bùxiǔ zhī zuò.","vi":"Đây là một tác phẩm bất hủ."},{"type":"simple","zh":"英雄们的名字刻在了不朽的纪念碑上。","pinyin":"Yīngxióngmen de míngzi kè zài le bùxiǔ de jìniànbēi shang.","vi":"Tên của các anh hùng được khắc trên tấm bia tưởng niệm trường tồn."},{"type":"compound","zh":"虽然作者早已去世，但是他的诗歌永远不朽。","pinyin":"Suīrán zuòzhě zǎoyǐ qùshì, dànshì tā de shīgē yǒngyuǎn bùxiǔ.","vi":"Tuy tác giả đã qua đời từ lâu nhưng thơ ca của ông mãi mãi bất hủ."}],"related":[{"hanzi":"永垂不朽","pinyin":"yǒngchuíbùxiǔ","vi":"đời đời bất diệt"},{"hanzi":"永恒","pinyin":"yǒnghéng","vi":"vĩnh hằng"},{"hanzi":"腐朽","pinyin":"fǔxiǔ","vi":"mục nát"},{"hanzi":"流芳百世","pinyin":"liúfāngbǎishì","vi":"lưu danh muôn đời"}]},{"id":"不雅","hanzi":"不雅","pinyin":"bùyǎ","meaning_vi":"thiếu tao nhã, thô tục","explanation":"不 (không) + 雅 (tao nhã/văn nhã).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🙈","examples":[{"type":"basic","zh":"这个动作很不雅。","pinyin":"Zhè ge dòngzuò hěn bùyǎ.","vi":"Động tác này rất thiếu tao nhã."},{"type":"simple","zh":"景区禁止游客在古迹上刻写不雅文字。","pinyin":"Jǐngqū jìnzhǐ yóukè zài gǔjì shang kèxiě bùyǎ wénzì.","vi":"Khu du lịch cấm du khách khắc viết chữ thô tục lên di tích."},{"type":"compound","zh":"如果在公共场合说不雅的话，就会让别人觉得你没有教养。","pinyin":"Rúguǒ zài gōnggòng chǎnghé shuō bùyǎ dehuà, jiù huì ràng biérén juéde nǐ méiyǒu jiàoyǎng.","vi":"Nếu nói lời thô tục nơi công cộng thì người khác sẽ thấy bạn thiếu giáo dục."}],"related":[{"hanzi":"粗俗","pinyin":"cūsú","vi":"thô tục"},{"hanzi":"文雅","pinyin":"wényǎ","vi":"tao nhã"},{"hanzi":"低俗","pinyin":"dīsú","vi":"thấp kém"},{"hanzi":"有伤风化","pinyin":"yǒushāngfēnghuà","vi":"trái thuần phong mỹ tục"}]},{"id":"不予","hanzi":"不予","pinyin":"bùyǔ","meaning_vi":"không cấp, không chấp thuận (văn bản hành chính)","explanation":"不 (bất – không) + 予 (dữ – cho, cấp) → không cho, không chấp thuận; dùng trong văn bản hành chính, pháp lý: 不予批准, 不予受理.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"❌","examples":[{"type":"basic","zh":"申请不予批准。","pinyin":"Shēnqǐng bùyǔ pīzhǔn.","vi":"Đơn xin không được phê duyệt."},{"type":"simple","zh":"逾期提交的材料一律不予受理。","pinyin":"Yúqī tíjiāo de cáiliào yílǜ bùyǔ shòulǐ.","vi":"Hồ sơ nộp quá hạn đều không được tiếp nhận."},{"type":"compound","zh":"因为发票上的信息不完整，所以财务部门不予报销。","pinyin":"Yīnwèi fāpiào shang de xìnxī bù wánzhěng, suǒyǐ cáiwù bùmén bùyǔ bàoxiāo.","vi":"Vì thông tin trên hóa đơn không đầy đủ nên phòng tài vụ không chấp thuận thanh toán."}],"related":[{"hanzi":"给予","pinyin":"jǐyǔ","vi":"cấp cho"},{"hanzi":"不予批准","pinyin":"bùyǔpīzhǔn","vi":"không phê duyệt"},{"hanzi":"拒绝","pinyin":"jùjué","vi":"từ chối"},{"hanzi":"准予","pinyin":"zhǔnyǔ","vi":"chấp thuận"}]},{"id":"不置可否","hanzi":"不置可否","pinyin":"búzhì-kěfǒu","meaning_vi":"không tỏ thái độ đồng ý hay phản đối (mập mờ)","explanation":"不置可否: không (不) đặt (置) ra là được (可) hay không (否) → không tỏ thái độ tán thành hay phản đối, lảng tránh.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤐","examples":[{"type":"basic","zh":"经理不置可否。","pinyin":"Jīnglǐ bú zhì kěfǒu.","vi":"Giám đốc không tỏ thái độ đồng ý hay phản đối."},{"type":"simple","zh":"听完我的方案，老板只是不置可否地点了点头。","pinyin":"Tīng wán wǒ de fāng'àn, lǎobǎn zhǐshì bú zhì kěfǒu dediǎnle diǎntóu.","vi":"Nghe xong phương án của tôi, ông chủ chỉ gật gù chẳng ra đồng ý cũng chẳng ra phản đối."},{"type":"compound","zh":"记者追问了好几次，但是发言人始终不置可否。","pinyin":"Jìzhě zhuīwènle hǎojǐ cì, dànshì fāyánrén shǐzhōng bú zhì kěfǒu.","vi":"Phóng viên truy hỏi mấy lần nhưng người phát ngôn vẫn trước sau không tỏ thái độ rõ ràng."}],"related":[{"hanzi":"模棱两可","pinyin":"móléngliǎngkě","vi":"nước đôi"},{"hanzi":"含糊其辞","pinyin":"hánhúqící","vi":"nói mập mờ"},{"hanzi":"表态","pinyin":"biǎotài","vi":"tỏ thái độ"},{"hanzi":"不置一词","pinyin":"búzhìyìcí","vi":"không nói một lời"}]},{"id":"八面玲珑","hanzi":"八面玲珑","pinyin":"bāmiàn-línglóng","meaning_vi":"khéo léo ứng xử vẹn toàn mọi phía","explanation":"八面 (tám mặt) + 玲珑 (linh lung – sáng sủa, tinh xảo) → vốn chỉ căn phòng sáng sủa thông thoáng mọi phía; nay ví người khéo léo đối nhân xử thế, làm vừa lòng mọi phía.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"💎","examples":[{"type":"basic","zh":"她为人八面玲珑。","pinyin":"Tā wéirén bāmiànlínglóng.","vi":"Cô ấy là người khéo léo, ứng xử vẹn toàn."},{"type":"simple","zh":"八面玲珑的店长把每位客人都照顾得很周到。","pinyin":"Bāmiànlínglóng de diànzhǎng bǎ měi wèi kèrén dōu zhàogù de hěn zhōudào.","vi":"Cửa hàng trưởng khéo léo chăm sóc khách hàng nào cũng chu đáo."},{"type":"compound","zh":"他虽然八面玲珑，但是真正知心的朋友并不多。","pinyin":"Tā suīrán bāmiànlínglóng, dànshì zhēnzhèng zhīxīn de péngyou bìngbù duō.","vi":"Anh ấy tuy khéo léo ứng xử với mọi người nhưng bạn tri kỷ thực sự lại không nhiều."}],"related":[{"hanzi":"圆滑","pinyin":"yuánhuá","vi":"khéo léo lươn lẹo"},{"hanzi":"左右逢源","pinyin":"zuǒyòuféngyuán","vi":"đâu cũng thuận lợi"},{"hanzi":"面面俱到","pinyin":"miànmiànjùdào","vi":"chu toàn mọi mặt"},{"hanzi":"处世","pinyin":"chǔshì","vi":"xử thế"}],"traditional":"八面玲瓏"},{"id":"颁奖典礼","hanzi":"颁奖典礼","pinyin":"bānjiǎngdiǎnlǐ","meaning_vi":"lễ trao giải thưởng","explanation":"颁奖 (ban tưởng – trao giải) + 典礼 (điển lễ – nghi lễ trang trọng) → lễ trao giải. VD: 奥斯卡颁奖典礼.","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🏆","examples":[{"type":"basic","zh":"颁奖典礼八点开始。","pinyin":"Bānjiǎngdiǎnlǐ bā diǎn kāishǐ.","vi":"Lễ trao giải bắt đầu lúc tám giờ."},{"type":"simple","zh":"她穿着一条红裙子出席了电影节的颁奖典礼。","pinyin":"Tā chuānzhe yì tiáo hóng qúnzi chūxíle diànyǐngjié de bānjiǎngdiǎnlǐ.","vi":"Cô ấy mặc một chiếc váy đỏ dự lễ trao giải của liên hoan phim."},{"type":"compound","zh":"颁奖典礼一结束，记者们就围住了最佳导演。","pinyin":"Bānjiǎngdiǎnlǐ yì jiéshù, jìzhěmen jiù wéizhùle zuì jiā dǎoyǎn.","vi":"Lễ trao giải vừa kết thúc, các phóng viên liền vây quanh đạo diễn xuất sắc nhất."}],"related":[{"hanzi":"颁奖","pinyin":"bānjiǎng","vi":"trao giải"},{"hanzi":"典礼","pinyin":"diǎnlǐ","vi":"lễ"},{"hanzi":"奖杯","pinyin":"jiǎngbēi","vi":"cúp"},{"hanzi":"获奖","pinyin":"huòjiǎng","vi":"đoạt giải"}],"traditional":"頒獎典禮"},{"id":"班门弄斧","hanzi":"班门弄斧","pinyin":"bānmén-nòngfǔ","meaning_vi":"múa rìu qua mắt thợ (khoe tài trước bậc thầy)","explanation":"Điển tích Lỗ Ban. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🪓","examples":[{"type":"basic","zh":"我这是班门弄斧了。","pinyin":"Wǒ zhè shì Bānménnòngfǔ le.","vi":"Tôi đây đúng là múa rìu qua mắt thợ rồi."},{"type":"simple","zh":"在书法大师面前写字，他觉得自己是在班门弄斧。","pinyin":"Zài shūfǎ dàshī miànqián xiězì, tā juéde zìjǐ shì zài Bānménnòngfǔ.","vi":"Viết chữ trước mặt bậc thầy thư pháp, anh ấy thấy mình đang múa rìu qua mắt thợ."},{"type":"compound","zh":"既然各位都是专家，那我就不班门弄斧了，只简单说两句。","pinyin":"Jìrán gèwèi dōu shì zhuānjiā, nà wǒ jiù bù Bānménnòngfǔ le, zhǐ jiǎndān shuō liǎngjù.","vi":"Các vị đều là chuyên gia nên tôi không dám múa rìu qua mắt thợ, chỉ nói đôi câu thôi."}],"related":[{"hanzi":"自不量力","pinyin":"zìbúliànglì","vi":"không biết lượng sức"},{"hanzi":"关公面前耍大刀","pinyin":"Guāngōng Miànqián Shuǎ Dàdāo","vi":"múa đao trước mặt Quan Công"},{"hanzi":"献丑","pinyin":"xiànchǒu","vi":"bêu xấu"},{"hanzi":"炫耀","pinyin":"xuànyào","vi":"khoe khoang"}],"traditional":"班門弄斧"},{"id":"斑马","hanzi":"斑马","pinyin":"bānmǎ","meaning_vi":"ngựa vằn","explanation":"斑 (vằn) + 马 (ngựa).","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🦓","examples":[{"type":"basic","zh":"斑马在草原上奔跑。","pinyin":"Bānmǎ zài cǎoyuán shang bēnpǎo.","vi":"Ngựa vằn chạy trên thảo nguyên."},{"type":"simple","zh":"动物园新来的小斑马吸引了很多孩子。","pinyin":"Dòngwùyuán xīn lái de xiǎo bānmǎ xīyǐnle hěn duō háizi.","vi":"Chú ngựa vằn con mới về sở thú đã thu hút rất nhiều trẻ em."},{"type":"compound","zh":"斑马身上的条纹不但很漂亮，而且能帮助它们躲避蚊虫。","pinyin":"Bānmǎ shēnshang de tiáowén búdàn hěn piàoliang, érqiě néng bāngzhù tāmen duǒbì wénchóng.","vi":"Những sọc vằn trên mình ngựa vằn không chỉ đẹp mà còn giúp chúng tránh muỗi và côn trùng."}],"related":[{"hanzi":"斑马线","pinyin":"bānmǎxiàn","vi":"vạch qua đường"},{"hanzi":"马","pinyin":"mǎ","vi":"ngựa"},{"hanzi":"长颈鹿","pinyin":"chángjǐnglù","vi":"hươu cao cổ"},{"hanzi":"条纹","pinyin":"tiáowén","vi":"sọc vằn"}],"traditional":"斑馬"},{"id":"搬弄是非","hanzi":"搬弄是非","pinyin":"bānnòng-shìfēi","meaning_vi":"đơm đặt chuyện thị phi, chia rẽ","explanation":"搬弄 (bày đặt, khua môi) + 是非 (thị phi – chuyện đúng sai) → đơm đặt, đặt điều chuyện thị phi để gây mâu thuẫn, chia rẽ người khác.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"她爱搬弄是非。","pinyin":"Tā ài bānnòngshìfēi.","vi":"Cô ta thích đơm đặt chuyện thị phi."},{"type":"simple","zh":"有人在办公室里搬弄是非，害得两位同事互不说话。","pinyin":"Yǒurén zài bàngōngshì lǐ bānnòngshìfēi, hàide liǎng wèi tóngshì hù bù shuōhuà.","vi":"Có người đơm đặt chuyện thị phi trong văn phòng khiến hai đồng nghiệp không thèm nói chuyện với nhau."},{"type":"compound","zh":"如果有人总在你面前搬弄是非，你就该离他远一点。","pinyin":"Rúguǒ yǒurén zǒng zài nǐ miànqián bānnòngshìfēi, nǐ jiù gāi lí tā yuǎn yìdiǎn.","vi":"Nếu có ai đó lúc nào cũng đơm đặt chuyện thị phi trước mặt bạn thì bạn nên tránh xa người đó."}],"related":[{"hanzi":"挑拨离间","pinyin":"tiǎobōlíjiàn","vi":"châm ngòi ly gián"},{"hanzi":"是非","pinyin":"shìfēi","vi":"thị phi"},{"hanzi":"说长道短","pinyin":"shuōchángdàoduǎn","vi":"nói ra nói vào"},{"hanzi":"造谣","pinyin":"zàoyáo","vi":"bịa chuyện"}]},{"id":"褒贬","hanzi":"褒贬","pinyin":"bāobiǎn","meaning_vi":"khen chê, bình phẩm","explanation":"褒 (khen ngợi) + 贬 (chê bai).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他从不褒贬别人。","pinyin":"Tā cóng bù bāobiǎn biérén.","vi":"Anh ấy chưa bao giờ khen chê người khác."},{"type":"simple","zh":"这部新电影上映后观众的褒贬不一。","pinyin":"Zhè bù xīn diànyǐng shàngyìng hòu guānzhòng de bāobiǎn bù yī.","vi":"Sau khi bộ phim mới này công chiếu, khán giả khen chê lẫn lộn."},{"type":"compound","zh":"虽然网上对这项改革褒贬不一，但是政府还是决定试行。","pinyin":"Suīrán wǎngshang duì zhè xiàng gǎigé bāobiǎn bù yī, dànshì zhèngfǔ háishi juédìng shìxíng.","vi":"Tuy trên mạng có nhiều ý kiến khen chê khác nhau về cải cách này nhưng chính phủ vẫn quyết định thí điểm."}],"related":[{"hanzi":"褒义","pinyin":"bāoyì","vi":"nghĩa khen"},{"hanzi":"贬义","pinyin":"biǎnyì","vi":"nghĩa chê"},{"hanzi":"评价","pinyin":"píngjià","vi":"đánh giá"},{"hanzi":"褒贬不一","pinyin":"bāobiǎnbùyī","vi":"khen chê lẫn lộn"}],"traditional":"褒貶"},{"id":"包涵","hanzi":"包涵","pinyin":"bāohan","meaning_vi":"thông cảm, thứ lỗi (kính ngữ)","explanation":"包 (cái túi) + 涵 (涵).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"招待不周，请多包涵。","pinyin":"Zhāodài bùzhōu, qǐng duō bāohan.","vi":"Tiếp đãi không chu đáo, mong mọi người thông cảm."},{"type":"simple","zh":"第一次登台演出，唱得不好还请大家包涵。","pinyin":"Dìyīcì dēng tái yǎnchū, chàng de bù hǎo hái qǐng dàjiā bāohan.","vi":"Lần đầu lên sân khấu biểu diễn, hát không hay mong mọi người thứ lỗi."},{"type":"compound","zh":"如果有什么说得不对的地方，就请各位多多包涵。","pinyin":"Rúguǒ yǒu shénme shuō de bú duì de dìfang, jiù qǐng gèwèi duōduō bāohan.","vi":"Nếu có chỗ nào nói chưa đúng, xin các vị lượng thứ cho."}],"related":[{"hanzi":"原谅","pinyin":"yuánliàng","vi":"tha thứ"},{"hanzi":"谅解","pinyin":"liàngjiě","vi":"thông cảm"},{"hanzi":"多多包涵","pinyin":"duōduōbāohan","vi":"mong được thông cảm"},{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"}]},{"id":"包罗","hanzi":"包罗","pinyin":"bāoluó","meaning_vi":"bao gồm, thu gom tất cả","explanation":"包 (bọc) + 罗 (lưới thu gom).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌐","examples":[{"type":"basic","zh":"这本书包罗万象。","pinyin":"Zhè běn shū bāoluówànxiàng.","vi":"Cuốn sách này bao quát mọi thứ."},{"type":"simple","zh":"这家博物馆的藏品包罗了各个朝代的瓷器。","pinyin":"Zhè jiā bówùguǎn de cángpǐn bāoluóle gègè cháodài de cíqì.","vi":"Bộ sưu tập của bảo tàng này bao gồm đồ sứ của mọi triều đại."},{"type":"compound","zh":"这份旅游手册不但包罗了景点介绍，而且附有详细地图。","pinyin":"Zhè fèn lǚyóu shǒucè búdàn bāoluóle jǐngdiǎn jièshào, érqiě fù yǒu xiángxì dìtú.","vi":"Cuốn cẩm nang du lịch này không chỉ bao gồm phần giới thiệu điểm tham quan mà còn kèm bản đồ chi tiết."}],"related":[{"hanzi":"包罗万象","pinyin":"bāoluówànxiàng","vi":"bao quát mọi thứ"},{"hanzi":"包括","pinyin":"bāokuò","vi":"bao gồm"},{"hanzi":"包含","pinyin":"bāohán","vi":"chứa đựng"},{"hanzi":"囊括","pinyin":"nángkuò","vi":"thâu tóm"}],"traditional":"包羅"},{"id":"褒义词","hanzi":"褒义词","pinyin":"bāoyìcí","meaning_vi":"từ mang nghĩa khen ngợi/tích cực","explanation":"褒义 + 词 (từ ngữ). Đối ứng với 贬义词.","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"👍","examples":[{"type":"basic","zh":"勇敢是褒义词。","pinyin":"Yǒnggǎn shì bāoyìcí.","vi":"\"Dũng cảm\" là từ mang nghĩa tích cực."},{"type":"simple","zh":"老师让我们在作文里多用一些褒义词描写人物。","pinyin":"Lǎoshī ràng wǒmen zài zuòwén lǐ duōyòng yìxiē bāoyìcí miáoxiě rénwù.","vi":"Cô giáo bảo chúng tôi dùng nhiều từ mang nghĩa khen ngợi hơn khi miêu tả nhân vật trong bài văn."},{"type":"compound","zh":"虽然聪明是褒义词，但是用在这里却带有讽刺的意味。","pinyin":"Suīrán cōngming shì bāoyìcí, dànshì yòng zài zhèlǐ què dàiyǒu fěngcì de yìwèi.","vi":"Tuy \"thông minh\" là từ mang nghĩa tích cực nhưng dùng ở đây lại mang ý mỉa mai."}],"related":[{"hanzi":"贬义词","pinyin":"biǎnyìcí","vi":"từ nghĩa xấu"},{"hanzi":"中性词","pinyin":"zhōngxìngcí","vi":"từ trung tính"},{"hanzi":"褒贬","pinyin":"bāobiǎn","vi":"khen chê"},{"hanzi":"词义","pinyin":"cíyì","vi":"nghĩa của từ"}],"traditional":"褒義詞"},{"id":"碑","hanzi":"碑","pinyin":"bēi","meaning_vi":"tấm bia đá, đài kỷ niệm","explanation":"Bộ thạch 石 + 卑. Ví dụ: 纪念碑 (đài tưởng niệm).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🗿","examples":[{"type":"basic","zh":"山顶立着一块碑。","pinyin":"Shāndǐng lìzhe yíkuài bēi.","vi":"Trên đỉnh núi dựng một tấm bia đá."},{"type":"simple","zh":"村民们为修路的老支书立了一块功德碑。","pinyin":"Cūnmínmen wèi xiūlù de lǎo zhī shūlìle yíkuài gōngdé bēi.","vi":"Dân làng dựng một tấm bia công đức cho vị bí thư chi bộ già đã làm đường."},{"type":"compound","zh":"虽然碑上的字已经模糊了，但是还能认出一个唐字。","pinyin":"Suīrán bēi shang de zì yǐjīng móhu le, dànshì hái néng rènchū yí gè táng zì.","vi":"Tuy chữ trên bia đã mờ nhưng vẫn còn nhận ra được một chữ \"Đường\"."}],"related":[{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"đài kỷ niệm"},{"hanzi":"石碑","pinyin":"shíbēi","vi":"bia đá"},{"hanzi":"墓碑","pinyin":"mùbēi","vi":"bia mộ"},{"hanzi":"碑文","pinyin":"bēiwén","vi":"văn bia"}]},{"id":"悲愤","hanzi":"悲愤","pinyin":"bēifèn","meaning_vi":"đau buồn và phẫn nộ","explanation":"悲 (悲) + 愤 (phẫn nộ).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😡","examples":[{"type":"basic","zh":"他感到十分悲愤。","pinyin":"Tā gǎndào shífēn bēifèn.","vi":"Anh ấy cảm thấy vô cùng đau buồn và phẫn nộ."},{"type":"simple","zh":"遇难者家属悲愤地要求查明事故真相。","pinyin":"Yùnànzhě jiāshǔ bēifèn de yāoqiú chámíng shìgù zhēnxiàng.","vi":"Thân nhân các nạn nhân đau đớn phẫn uất yêu cầu làm rõ sự thật về vụ tai nạn."},{"type":"compound","zh":"看到森林被大片砍伐，他既悲愤又无奈。","pinyin":"Kàndào sēnlín bèi dàpiàn kǎnfá, tā jì bēifèn yòu wúnài.","vi":"Nhìn thấy rừng bị chặt phá trên diện rộng, ông ấy vừa đau xót phẫn nộ vừa bất lực."}],"related":[{"hanzi":"悲伤","pinyin":"bēishāng","vi":"đau buồn"},{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"义愤","pinyin":"yìfèn","vi":"phẫn nộ chính nghĩa"},{"hanzi":"悲痛","pinyin":"bēitòng","vi":"bi thương"}],"traditional":"悲憤"},{"id":"背黑锅","hanzi":"背黑锅","pinyin":"bēihēiguō","meaning_vi":"chịu oan, gánh tội thay người khác","explanation":"背 (cõng) + 黑锅 (nồi đen). Thành ngữ khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍳","examples":[{"type":"basic","zh":"我不想背黑锅。","pinyin":"Wǒ bù xiǎng bēihēiguō.","vi":"Tôi không muốn gánh tội thay người khác."},{"type":"simple","zh":"项目出了问题，最后却让实习生背黑锅。","pinyin":"Xiàngmù chūle wèntí, zuìhòu què ràng shíxíshēng bēihēiguō.","vi":"Dự án gặp sự cố, cuối cùng lại bắt thực tập sinh chịu oan."},{"type":"compound","zh":"因为他不敢承认错误，所以同事只好替他背黑锅。","pinyin":"Yīnwèi tā bù gǎn chéngrèn cuòwù, suǒyǐ tóngshì zhǐhǎo tì tā bēihēiguō.","vi":"Vì anh ta không dám nhận lỗi nên đồng nghiệp đành phải gánh tội thay anh ta."}],"related":[{"hanzi":"冤枉","pinyin":"yuānwang","vi":"oan uổng"},{"hanzi":"替罪羊","pinyin":"tìzuìyáng","vi":"con dê tế thần"},{"hanzi":"顶罪","pinyin":"dǐngzuì","vi":"chịu tội thay"},{"hanzi":"甩锅","pinyin":"shuǎiguō","vi":"đổ lỗi cho người khác"}],"traditional":"背黑鍋"},{"id":"卑劣","hanzi":"卑劣","pinyin":"bēiliè","meaning_vi":"đê hèn, xấu xa","explanation":"卑 (thấp kém) + 劣 (xấu).","hsk_level":"7-9","tags":["tinh-tu"],"image":"👎","examples":[{"type":"basic","zh":"这种手段太卑劣了。","pinyin":"Zhè zhǒng shǒuduàn tài bēiliè le.","vi":"Thủ đoạn này quá đê hèn."},{"type":"simple","zh":"他用卑劣的方法偷走了同事的设计方案。","pinyin":"Tāyòng bēiliè de fāngfǎ tōu zǒule tóngshì de shèjì fāng'àn.","vi":"Hắn dùng cách đê tiện để đánh cắp phương án thiết kế của đồng nghiệp."},{"type":"compound","zh":"即使比赛输了，我们也不能用卑劣的方式报复对手。","pinyin":"Jíshǐ bǐsài shū le, wǒmen yě bù néng yòng bēiliè de fāngshì bàofù duìshǒu.","vi":"Dù thua trận, chúng ta cũng không được dùng cách hèn hạ để trả thù đối thủ."}],"related":[{"hanzi":"卑鄙","pinyin":"bēibǐ","vi":"đê tiện"},{"hanzi":"无耻","pinyin":"wúchǐ","vi":"vô liêm sỉ"},{"hanzi":"恶劣","pinyin":"èliè","vi":"tồi tệ"},{"hanzi":"高尚","pinyin":"gāoshàng","vi":"cao thượng"}]},{"id":"悲悯","hanzi":"悲悯","pinyin":"bēimǐn","meaning_vi":"thương xót, lòng trắc ẩn","explanation":"悲 (bi – buồn thương) + 悯 (mẫn – thương xót) → thương xót, lòng trắc ẩn trước nỗi khổ của người khác. VD: 悲悯之心, 悲悯情怀.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"他心怀悲悯。","pinyin":"Tā xīnhuái bēimǐn.","vi":"Ông ấy mang lòng trắc ẩn."},{"type":"simple","zh":"老画家的作品里充满了对穷苦百姓的悲悯。","pinyin":"Lǎo huàjiā de zuòpǐn lǐ chōngmǎnle duì qióngkǔ bǎixìng de bēimǐn.","vi":"Tác phẩm của người họa sĩ già tràn đầy lòng thương xót đối với dân nghèo khổ."},{"type":"compound","zh":"因为作者有一颗悲悯之心，所以小说里的小人物都写得很动人。","pinyin":"Yīnwèi zuòzhě yǒu yì kē bēimǐn zhī xīn, suǒyǐ xiǎoshuō lǐ de xiǎorénwù dōu xiě de hěn dòngrén.","vi":"Vì tác giả có lòng trắc ẩn nên những nhân vật nhỏ bé trong tiểu thuyết đều được viết rất cảm động."}],"related":[{"hanzi":"怜悯","pinyin":"liánmǐn","vi":"thương xót"},{"hanzi":"同情","pinyin":"tóngqíng","vi":"đồng cảm"},{"hanzi":"慈悲","pinyin":"cíbēi","vi":"từ bi"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"}],"traditional":"悲憫"},{"id":"背诵课文","hanzi":"背诵课文","pinyin":"bèisòngkèwén","meaning_vi":"học thuộc lòng bài khóa","explanation":"背 (cõng) + 诵 (đọc thuộc/ca ngợi) + 课 (bài học) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我们在背诵课文。","pinyin":"Wǒmen zài bèisòngkèwén.","vi":"Chúng tôi đang học thuộc lòng bài khóa."},{"type":"simple","zh":"妈妈每天晚上都听女儿背诵课文。","pinyin":"Māma měitiān wǎnshang dōu tīng nǚ'ér bèisòngkèwén.","vi":"Tối nào mẹ cũng nghe con gái đọc thuộc lòng bài khóa."},{"type":"compound","zh":"只要每天早上背诵课文，你的语感就会慢慢提高。","pinyin":"Zhǐyào měitiān zǎoshang bèisòngkèwén, nǐ de yǔgǎn jiù huì mànmàn tígāo.","vi":"Chỉ cần mỗi sáng học thuộc lòng bài khóa thì cảm nhận ngôn ngữ của bạn sẽ dần dần được nâng cao."}],"related":[{"hanzi":"背诵","pinyin":"bèisòng","vi":"học thuộc lòng"},{"hanzi":"课文","pinyin":"kèwén","vi":"bài khóa"},{"hanzi":"朗读","pinyin":"lǎngdú","vi":"đọc to"},{"hanzi":"默写","pinyin":"mòxiě","vi":"viết chính tả theo trí nhớ"}],"traditional":"背誦課文"},{"id":"悲壮","hanzi":"悲壮","pinyin":"bēizhuàng","meaning_vi":"bi tráng, hào hùng và cảm động","explanation":"悲 (bi thương) + 壮 (hùng tráng).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🎖️","examples":[{"type":"basic","zh":"这首歌很悲壮。","pinyin":"Zhè shǒu gē hěn bēizhuàng.","vi":"Bài hát này thật bi tráng."},{"type":"simple","zh":"电影最后一幕再现了将士们悲壮的牺牲。","pinyin":"Diànyǐng zuìhòu yí mù zàixiànle jiàngshìmen bēizhuàng de xīshēng.","vi":"Cảnh cuối của bộ phim tái hiện sự hy sinh bi tráng của các tướng sĩ."},{"type":"compound","zh":"虽然这场战役失败了，但是那段悲壮的历史一直被人们铭记。","pinyin":"Suīrán zhè chǎng zhànyì shībài le, dànshì nà duàn bēizhuàng de lìshǐ yìzhí bèi rénmen míngjì.","vi":"Tuy chiến dịch này thất bại nhưng đoạn lịch sử bi tráng ấy vẫn luôn được người đời ghi nhớ."}],"related":[{"hanzi":"壮烈","pinyin":"zhuàngliè","vi":"oanh liệt"},{"hanzi":"悲惨","pinyin":"bēicǎn","vi":"bi thảm"},{"hanzi":"豪迈","pinyin":"háomài","vi":"hào hùng"},{"hanzi":"慷慨悲歌","pinyin":"kāngkǎibēigē","vi":"khảng khái bi ca"}],"traditional":"悲壯"},{"id":"奔流","hanzi":"奔流","pinyin":"bēnliú","meaning_vi":"chảy xiết, cuồn cuộn chảy","explanation":"奔 (chạy nhanh) + 流 (dòng chảy).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"江水奔流不息。","pinyin":"Jiāngshuǐ bēnliú bùxī.","vi":"Nước sông cuồn cuộn chảy không ngừng."},{"type":"simple","zh":"黄河从高原上奔流而下，冲进了峡谷。","pinyin":"Huánghé cóng gāoyuán shang bēnliú ér xià, chōngjìnle xiágǔ.","vi":"Hoàng Hà từ trên cao nguyên cuồn cuộn đổ xuống, lao vào hẻm núi."},{"type":"compound","zh":"雪山的冰一融化，河水就奔流着冲向下游的村庄。","pinyin":"Xuěshān de bīng yì rónghuà, héshuǐ jiù bēnliúzhe chōngxiàng xiàyóu de cūnzhuāng.","vi":"Băng trên núi tuyết vừa tan, nước sông liền cuồn cuộn đổ về các thôn làng ở hạ lưu."}],"related":[{"hanzi":"奔腾","pinyin":"bēnténg","vi":"cuồn cuộn"},{"hanzi":"流淌","pinyin":"liútǎng","vi":"chảy"},{"hanzi":"汹涌","pinyin":"xiōngyǒng","vi":"dữ dội"},{"hanzi":"奔流不息","pinyin":"bēnliúbùxī","vi":"chảy không ngừng"}]},{"id":"北冰洋","hanzi":"北冰洋","pinyin":"Běibīngyáng","meaning_vi":"Bắc Băng Dương","explanation":"北 (hướng Bắc) + 冰 (băng giá) + 洋 (đại dương/nước ngoài).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🧊","examples":[{"type":"basic","zh":"北冰洋非常寒冷。","pinyin":"Běibīngyáng fēicháng hánlěng.","vi":"Bắc Băng Dương vô cùng lạnh giá."},{"type":"simple","zh":"科考船在北冰洋上航行了整整一个月。","pinyin":"Kēkǎo chuán zài Běibīngyáng shang hángxíngle zhěngzhěng yī gèyuè.","vi":"Tàu khảo sát khoa học đã đi trên Bắc Băng Dương suốt một tháng."},{"type":"compound","zh":"如果北冰洋的海冰继续减少，北极熊就会失去捕猎的地方。","pinyin":"Rúguǒ Běibīngyáng de hǎibīng jìxù jiǎnshǎo, běijíxióng jiù huì shīqù bǔliè de dìfang.","vi":"Nếu băng biển ở Bắc Băng Dương tiếp tục giảm thì gấu Bắc Cực sẽ mất nơi săn mồi."}],"related":[{"hanzi":"太平洋","pinyin":"Tàipíngyáng","vi":"Thái Bình Dương"},{"hanzi":"大西洋","pinyin":"Dàxīyáng","vi":"Đại Tây Dương"},{"hanzi":"印度洋","pinyin":"Yìndùyáng","vi":"Ấn Độ Dương"},{"hanzi":"北极","pinyin":"Běijí","vi":"Bắc Cực"}]},{"id":"北回归线","hanzi":"北回归线","pinyin":"Běihuíguīxiàn","meaning_vi":"chí tuyến Bắc","explanation":"北 + 回归线 (đường chí tuyến).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌐","examples":[{"type":"basic","zh":"广州靠近北回归线。","pinyin":"Guǎngzhōu kàojìn Běihuíguīxiàn.","vi":"Quảng Châu nằm gần chí tuyến Bắc."},{"type":"simple","zh":"夏至那天中午，太阳直射在北回归线上。","pinyin":"Xiàzhì nà tiān zhōngwǔ, tàiyáng zhíshè zài Běihuíguīxiàn shang.","vi":"Trưa ngày Hạ chí, mặt trời chiếu thẳng góc xuống chí tuyến Bắc."},{"type":"compound","zh":"因为这座城市正好位于北回归线上，所以这里建了一座标志塔。","pinyin":"Yīnwèi zhè zuò chéngshì zhènghǎo wèiyú Běihuíguīxiàn shang, suǒyǐ zhèlǐ jiànle yí zuò biāozhì tǎ.","vi":"Vì thành phố này nằm đúng trên chí tuyến Bắc nên ở đây có xây một tháp mốc."}],"related":[{"hanzi":"南回归线","pinyin":"Nánhuíguīxiàn","vi":"chí tuyến Nam"},{"hanzi":"赤道","pinyin":"Chìdào","vi":"xích đạo"},{"hanzi":"纬线","pinyin":"Wěixiàn","vi":"vĩ tuyến"},{"hanzi":"热带","pinyin":"rèdài","vi":"nhiệt đới"}],"traditional":"北回歸線"},{"id":"本源","hanzi":"本源","pinyin":"běnyuán","meaning_vi":"cội nguồn, bản nguyên","explanation":"本 (bản – gốc) + 源 (nguyên – nguồn) → cội nguồn, căn nguyên của sự vật; văn viết, sắc thái triết học. VD: 生命的本源.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌱","examples":[{"type":"basic","zh":"我们要追溯本源。","pinyin":"Wǒmen yào zhuīsù běnyuán.","vi":"Chúng ta phải truy tìm cội nguồn."},{"type":"simple","zh":"这位学者一生都在探索汉字的本源。","pinyin":"Zhè wèi xuézhě yìshēng dōu zài tànsuǒ hànzì de běnyuán.","vi":"Vị học giả này cả đời tìm tòi cội nguồn của chữ Hán."},{"type":"compound","zh":"如果不弄清问题的本源，就只能治标不治本。","pinyin":"Rúguǒ bú nòngqīng wèntí de běnyuán, jiù zhǐnéng zhìbiāo bú zhìběn.","vi":"Nếu không làm rõ cội nguồn của vấn đề thì chỉ có thể chữa ngọn không chữa gốc."}],"related":[{"hanzi":"根源","pinyin":"gēnyuán","vi":"cội rễ"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"},{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"}]},{"id":"本意","hanzi":"本意","pinyin":"běnyì","meaning_vi":"ý định ban đầu, ý thật; nghĩa gốc","explanation":"本 (gốc) + 意 (ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"📖","examples":[{"type":"basic","zh":"这不是我的本意。","pinyin":"Zhèbú shì wǒ de běnyì.","vi":"Đây không phải là ý định ban đầu của tôi."},{"type":"simple","zh":"她的本意是帮忙，没想到反而添了麻烦。","pinyin":"Tā de běnyì shì bāngmáng, méi xiǎngdào fǎn'ér tiānle máfan.","vi":"Ý định ban đầu của cô ấy là giúp đỡ, không ngờ lại gây thêm phiền phức."},{"type":"compound","zh":"虽然他的话说得很重，但是本意是希望你能进步。","pinyin":"Suīrán tā de huàshuō de hěn zhòng, dànshì běnyì shì xīwàng nǐ néng jìnbù.","vi":"Tuy anh ấy nói nặng lời nhưng ý định thật là mong bạn tiến bộ."}],"related":[{"hanzi":"本义","pinyin":"běnyì","vi":"nghĩa gốc"},{"hanzi":"初衷","pinyin":"chūzhōng","vi":"ý định ban đầu"},{"hanzi":"用意","pinyin":"yòngyì","vi":"dụng ý"},{"hanzi":"原意","pinyin":"yuányì","vi":"ý ban đầu"}]},{"id":"本义","hanzi":"本义","pinyin":"běnyì","meaning_vi":"nghĩa gốc của từ","explanation":"本 (quyển) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"走的本义是跑。","pinyin":"Zǒu de běnyì shì pǎo.","vi":"Nghĩa gốc của chữ \"tẩu\" là chạy."},{"type":"simple","zh":"查古汉语字典可以了解一个字的本义。","pinyin":"Chá gǔhànyǔ zìdiǎn kěyǐ liǎojiě yí gè zì de běnyì.","vi":"Tra từ điển Hán ngữ cổ có thể biết được nghĩa gốc của một chữ."},{"type":"compound","zh":"如果不知道这个词的本义，就很难理解它后来的引申义。","pinyin":"Rúguǒ bù zhīdào zhè ge cí de běnyì, jiù hěn nán lǐjiě tā hòulái de yǐnshēnyì.","vi":"Nếu không biết nghĩa gốc của từ này thì rất khó hiểu được nghĩa mở rộng về sau của nó."}],"related":[{"hanzi":"引申义","pinyin":"yǐnshēnyì","vi":"nghĩa mở rộng"},{"hanzi":"比喻义","pinyin":"bǐyùyì","vi":"nghĩa ẩn dụ"},{"hanzi":"词义","pinyin":"cíyì","vi":"nghĩa của từ"},{"hanzi":"本意","pinyin":"běnyì","vi":"ý định ban đầu"}],"traditional":"本義"},{"id":"濒危","hanzi":"濒危","pinyin":"bīnwēi","meaning_vi":"có nguy cơ tuyệt chủng (động thực vật)","explanation":"濒 (sát bờ) + 危 (nguy hiểm). Cụm: 濒危物种.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🐼","examples":[{"type":"basic","zh":"大熊猫曾是濒危动物。","pinyin":"Dàxióngmāo céng shì bīnwēi dòngwù.","vi":"Gấu trúc từng là loài động vật có nguy cơ tuyệt chủng."},{"type":"simple","zh":"这个保护区专门救助受伤的濒危鸟类。","pinyin":"Zhè ge bǎohùqū zhuānmén jiùzhù shòushāng de bīnwēi niǎolèi.","vi":"Khu bảo tồn này chuyên cứu hộ các loài chim quý hiếm bị thương có nguy cơ tuyệt chủng."},{"type":"compound","zh":"如果人们继续捕杀穿山甲，这种濒危动物就会彻底消失。","pinyin":"Rúguǒ rénmen jìxù bǔshā chuānshānjiǎ, zhè zhǒng bīnwēi dòngwù jiù huì chèdǐ xiāoshī.","vi":"Nếu con người tiếp tục săn bắt tê tê thì loài động vật đang có nguy cơ tuyệt chủng này sẽ biến mất hoàn toàn."}],"related":[{"hanzi":"濒临","pinyin":"bīnlín","vi":"kề sát bờ"},{"hanzi":"灭绝","pinyin":"mièjué","vi":"tuyệt chủng"},{"hanzi":"珍稀","pinyin":"zhēnxī","vi":"quý hiếm"},{"hanzi":"濒危动物","pinyin":"bīnwēidòngwù","vi":"động vật nguy cấp"}],"traditional":"瀕危"},{"id":"冰川","hanzi":"冰川","pinyin":"bīngchuān","meaning_vi":"sông băng","explanation":"冰 (băng) + 川 (xuyên – sông) → sông băng, khối băng lớn trôi chậm trên núi cao hoặc vùng cực. VD: 冰川融化.","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🏔️","examples":[{"type":"basic","zh":"冰川正在融化。","pinyin":"Bīngchuān zhèngzài rónghuà.","vi":"Sông băng đang tan chảy."},{"type":"simple","zh":"我们坐直升机飞过了阿拉斯加的冰川。","pinyin":"Wǒmen zuò zhíshēngjī fēiguòle Ālāsījiā de bīngchuān.","vi":"Chúng tôi ngồi trực thăng bay qua những dòng sông băng ở Alaska."},{"type":"compound","zh":"因为全球气温不断升高，所以很多冰川都在快速后退。","pinyin":"Yīnwèi quánqiú qìwēn búduàn shēnggāo, suǒyǐ hěn duō bīngchuān dōu zài kuàisù hòutuì.","vi":"Vì nhiệt độ toàn cầu không ngừng tăng nên nhiều sông băng đang rút lui nhanh chóng."}],"related":[{"hanzi":"冰山","pinyin":"bīngshān","vi":"núi băng"},{"hanzi":"冰河","pinyin":"bīnghé","vi":"sông băng"},{"hanzi":"冰雪","pinyin":"bīngxuě","vi":"băng tuyết"},{"hanzi":"融化","pinyin":"rónghuà","vi":"tan chảy"}]},{"id":"冰雕","hanzi":"冰雕","pinyin":"bīngdiāo","meaning_vi":"tượng băng, điêu khắc băng","explanation":"冰 (冰) + 雕 (điêu khắc).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🧊","examples":[{"type":"basic","zh":"这座冰雕很逼真。","pinyin":"Zhè zuò bīngdiāo hěn bīzhēn.","vi":"Bức điêu khắc băng này rất sống động như thật."},{"type":"simple","zh":"哈尔滨的冰雪大世界里有上千座冰雕。","pinyin":"Hā'ěrbīn de bīngxuě dà shìjiè lǐ yǒu shàng qiān zuò bīngdiāo.","vi":"Trong Thế giới Băng Tuyết ở Cáp Nhĩ Tân có hàng nghìn tác phẩm điêu khắc băng."},{"type":"compound","zh":"到了晚上，五彩的灯光一亮，冰雕就像水晶宫殿一样。","pinyin":"Dàole wǎnshang, wǔcǎi de dēngguāng yí liàng, bīngdiāo jiù xiàng shuǐjīng gōngdiàn yíyàng.","vi":"Đến tối, ánh đèn ngũ sắc vừa bật lên, các tác phẩm điêu khắc băng trông như cung điện pha lê."}],"related":[{"hanzi":"雕刻","pinyin":"diāokè","vi":"điêu khắc"},{"hanzi":"雪雕","pinyin":"xuědiāo","vi":"điêu khắc tuyết"},{"hanzi":"冰灯","pinyin":"bīngdēng","vi":"đèn băng"},{"hanzi":"哈尔滨","pinyin":"Hā'ěrbīn","vi":"Cáp Nhĩ Tân"}]},{"id":"兵马俑","hanzi":"兵马俑","pinyin":"bīngmǎyǒng","meaning_vi":"đội quân đất nung (Tần Thủy Hoàng - Tây An)","explanation":"兵 (lính) + 马 (ngựa) + 俑 (tượng chôn theo).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🗿","examples":[{"type":"basic","zh":"兵马俑在西安。","pinyin":"Bīngmǎyǒng zài Xī'ān.","vi":"Tượng binh mã ở Tây An."},{"type":"simple","zh":"每个兵马俑的脸都有不同的表情。","pinyin":"Měi gè bīngmǎyǒng de liǎn dōu yǒu bùtóng de biǎoqíng.","vi":"Khuôn mặt mỗi tượng binh mã đều có biểu cảm khác nhau."},{"type":"compound","zh":"如果你去西安旅游，就一定要去看看兵马俑。","pinyin":"Rúguǒ nǐ qù Xī'ān lǚyóu, jiù yídìngyào qù kànkan bīngmǎyǒng.","vi":"Nếu bạn đi du lịch Tây An thì nhất định phải đi xem tượng binh mã."}],"related":[{"hanzi":"秦始皇","pinyin":"Qínshǐhuáng","vi":"Tần Thủy Hoàng"},{"hanzi":"西安","pinyin":"Xī'ān","vi":"Tây An"},{"hanzi":"文物","pinyin":"wénwù","vi":"cổ vật"},{"hanzi":"陶俑","pinyin":"táoyǒng","vi":"tượng gốm"}],"traditional":"兵馬俑"},{"id":"冰天雪地","hanzi":"冰天雪地","pinyin":"bīngtiān-xuědì","meaning_vi":"trời băng đất tuyết (cảnh mùa đông giá rét)","explanation":"冰天雪地: trời băng (冰天) đất tuyết (雪地) → cảnh băng tuyết phủ kín, giá rét khắc nghiệt. Thường tả vùng phương Bắc mùa đông.","hsk_level":"7-9","tags":["thanh-ngu","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"外面冰天雪地。","pinyin":"Wàimiàn bīngtiānxuědì.","vi":"Bên ngoài trời băng đất tuyết."},{"type":"simple","zh":"边防战士在冰天雪地里巡逻了整整一夜。","pinyin":"Biānfáng zhànshì zài bīngtiānxuědì lǐ xúnluóle zhěngzhěng yī yè.","vi":"Các chiến sĩ biên phòng tuần tra suốt đêm giữa trời băng đất tuyết."},{"type":"compound","zh":"虽然外面冰天雪地，但是屋里烧着炉子，暖和极了。","pinyin":"Suīrán wàimiàn bīngtiānxuědì, dànshì wū lǐ shāozhe lúzi, nuǎnhuo jíle.","vi":"Tuy bên ngoài băng tuyết giá lạnh nhưng trong nhà đốt lò sưởi nên ấm áp vô cùng."}],"related":[{"hanzi":"天寒地冻","pinyin":"tiānhándìdòng","vi":"trời rét đất buốt"},{"hanzi":"严寒","pinyin":"yánhán","vi":"giá rét"},{"hanzi":"白雪皑皑","pinyin":"báixuě'ái'ái","vi":"tuyết trắng xóa"},{"hanzi":"冰雪","pinyin":"bīngxuě","vi":"băng tuyết"}]},{"id":"拨乱反正","hanzi":"拨乱反正","pinyin":"bōluàn-fǎnzhèng","meaning_vi":"dẹp loạn lập lại trật tự đúng đắn","explanation":"拨乱反正: dẹp (拨) loạn (乱) đưa trở về (反) lẽ chính (正) → dẹp yên hỗn loạn, khôi phục trật tự đúng đắn.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"他们决心拨乱反正。","pinyin":"Tāmen juéxīn bōluànfǎnzhèng.","vi":"Họ quyết tâm dẹp loạn, lập lại trật tự."},{"type":"simple","zh":"新校长上任后对混乱的招生制度拨乱反正。","pinyin":"Xīn xiàozhǎng shàngrèn hòu duì hùnluàn de zhāoshēng zhìdù bōluànfǎnzhèng.","vi":"Sau khi nhậm chức, hiệu trưởng mới đã chấn chỉnh lại chế độ tuyển sinh hỗn loạn."},{"type":"compound","zh":"只有及时拨乱反正，这个行业才能重新赢得消费者的信任。","pinyin":"Zhǐyǒu jíshí bōluànfǎnzhèng, zhè ge hángyè cáinéng chóngxīn yíngdé xiāofèizhě de xìnrèn.","vi":"Chỉ khi kịp thời chấn chỉnh, lập lại trật tự thì ngành này mới có thể giành lại lòng tin của người tiêu dùng."}],"related":[{"hanzi":"整顿","pinyin":"zhěngdùn","vi":"chấn chỉnh"},{"hanzi":"纠正","pinyin":"jiūzhèng","vi":"sửa sai"},{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"},{"hanzi":"恢复秩序","pinyin":"huīfùzhìxù","vi":"khôi phục trật tự"}],"traditional":"撥亂反正"},{"id":"波澜","hanzi":"波澜","pinyin":"bōlán","meaning_vi":"sóng lớn; biến cố, thăng trầm","explanation":"Cả hai chữ đều có bộ thủy 氵.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"湖面不起波澜。","pinyin":"Húmiàn bù qǐ bōlán.","vi":"Mặt hồ không gợn sóng."},{"type":"simple","zh":"他平静的生活因为一封信掀起了波澜。","pinyin":"Tā píngjìng de shēnghuó yīnwèi yì fēng xìn xiānqǐle bōlán.","vi":"Cuộc sống bình lặng của anh ấy bị khuấy động chỉ vì một lá thư."},{"type":"compound","zh":"虽然她表面上很平静，但是内心早已波澜起伏。","pinyin":"Suīrán tā biǎomiànshang hěn píngjìng, dànshì nèixīn zǎoyǐ bōlán qǐfú.","vi":"Tuy bề ngoài cô ấy rất bình thản nhưng trong lòng đã sớm dậy sóng."}],"related":[{"hanzi":"波澜壮阔","pinyin":"bōlánzhuàngkuò","vi":"hùng tráng sóng gió"},{"hanzi":"波折","pinyin":"bōzhé","vi":"trắc trở"},{"hanzi":"风波","pinyin":"fēngbō","vi":"sóng gió"},{"hanzi":"波浪","pinyin":"bōlàng","vi":"sóng"}],"traditional":"波瀾"},{"id":"百川归海","hanzi":"百川归海","pinyin":"bǎichuān-guīhǎi","meaning_vi":"trăm sông đổ về biển lớn (đồng lòng quy tụ)","explanation":"百川 (trăm sông) + 归海 (đổ về biển) → trăm sông đổ về biển; ví lòng người, mọi thứ cùng quy tụ về một nơi, một mục tiêu.","hsk_level":"7-9","tags":["thanh-ngu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"百川归海，人心所向。","pinyin":"Bǎichuānguīhǎi, rénxīn suǒ xiàng.","vi":"Trăm sông đổ về biển, lòng người đều hướng về một mối."},{"type":"simple","zh":"各地的捐款百川归海般汇集到了灾区。","pinyin":"Gèdì de juānkuǎn bǎichuānguīhǎi bān huìjí dàole zāiqū.","vi":"Tiền quyên góp từ khắp nơi như trăm sông đổ về biển, đổ dồn về vùng thiên tai."},{"type":"compound","zh":"既然大家的意见最终百川归海，我们就按这个方案执行吧。","pinyin":"Jìrán dàjiā de yìjiàn zuìzhōng bǎichuānguīhǎi, wǒmen jiù àn zhè ge fāng'àn zhíxíng ba.","vi":"Vì ý kiến của mọi người cuối cùng đã quy về một mối, chúng ta hãy làm theo phương án này."}],"related":[{"hanzi":"殊途同归","pinyin":"shūtútóngguī","vi":"khác đường cùng đích"},{"hanzi":"众望所归","pinyin":"zhòngwàngsuǒguī","vi":"lòng người hướng về"},{"hanzi":"汇聚","pinyin":"huìjù","vi":"hội tụ"},{"hanzi":"万众一心","pinyin":"wànzhòngyìxīn","vi":"vạn người như một"}],"traditional":"百川歸海"},{"id":"百废待兴","hanzi":"百废待兴","pinyin":"bǎifèi-dàixīng","meaning_vi":"trăm việc ngổn ngang chờ khôi phục phát triển","explanation":"百废 (trăm việc bị bỏ phế) + 待兴 (chờ chấn hưng) → mọi việc đổ nát đang chờ khôi phục; thường nói về tình cảnh sau chiến tranh, thiên tai.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🏗️","examples":[{"type":"basic","zh":"战后百废待兴。","pinyin":"Zhànhòu bǎifèidàixīng.","vi":"Sau chiến tranh, trăm việc ngổn ngang chờ khôi phục."},{"type":"simple","zh":"地震过后，这座小城百废待兴，到处都在重建。","pinyin":"Dìzhèn guòhòu, zhè zuò xiǎochéng bǎifèidàixīng, dàochù dōu zài chóngjiàn.","vi":"Sau trận động đất, thị trấn nhỏ này trăm bề ngổn ngang, khắp nơi đều đang tái thiết."},{"type":"compound","zh":"虽然当时国家百废待兴，但是政府仍然拿出钱来办学校。","pinyin":"Suīrán dāngshí guójiā bǎifèidàixīng, dànshì zhèngfǔ réngrán ná chūqián lái bàn xuéxiào.","vi":"Tuy lúc ấy đất nước còn trăm việc ngổn ngang nhưng chính phủ vẫn bỏ tiền ra mở trường học."}],"related":[{"hanzi":"百废俱兴","pinyin":"bǎifèijùxīng","vi":"trăm việc đều hưng"},{"hanzi":"重建","pinyin":"chóngjiàn","vi":"tái thiết"},{"hanzi":"恢复","pinyin":"huīfù","vi":"khôi phục"},{"hanzi":"一片废墟","pinyin":"yípiànfèixū","vi":"một bãi hoang tàn"}],"traditional":"百廢待興"},{"id":"百年大计","hanzi":"百年大计","pinyin":"bǎinián-dàjì","meaning_vi":"kế sách lớn trăm năm (giáo dục/quốc gia)","explanation":"百年 (trăm năm) + 大计 (đại kế – kế sách lớn) → kế hoạch lớn mang tính lâu dài, quyết định tương lai. Câu quen thuộc: 教育是百年大计.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"教育是百年大计。","pinyin":"Jiàoyù shì bǎiniándàjì.","vi":"Giáo dục là kế sách lớn trăm năm."},{"type":"simple","zh":"修建这座水库是关系全省发展的百年大计。","pinyin":"Xiūjiàn zhè zuò shuǐkù shì guānxì quánshěng fāzhǎn de bǎiniándàjì.","vi":"Xây dựng hồ chứa nước này là kế sách lâu dài liên quan đến sự phát triển của cả tỉnh."},{"type":"compound","zh":"既然这是百年大计，我们就不能只看眼前的利益。","pinyin":"Jìrán zhè shì bǎiniándàjì, wǒmen jiù bù néng zhǐ kàn yǎnqián de lìyì.","vi":"Vì đây là kế sách lâu dài, chúng ta không thể chỉ nhìn vào lợi ích trước mắt."}],"related":[{"hanzi":"长远","pinyin":"chángyuǎn","vi":"lâu dài"},{"hanzi":"大计","pinyin":"dàjì","vi":"kế lớn"},{"hanzi":"规划","pinyin":"guīhuà","vi":"quy hoạch"},{"hanzi":"十年树木百年树人","pinyin":"shí nián shùmù bǎiniánshùrén","vi":"mười năm trồng cây trăm năm trồng người"}],"traditional":"百年大計"},{"id":"百思不解","hanzi":"百思不解","pinyin":"bǎisī-bùjiě","meaning_vi":"nghĩ mãi không ra, vắt óc không hiểu","explanation":"百思 (nghĩ trăm lần) + 不解 (không hiểu) → nghĩ mãi vẫn không hiểu nổi. Cũng nói 百思不得其解.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"我对此百思不解。","pinyin":"Wǒ duì cǐ bǎisībùjiě.","vi":"Tôi nghĩ mãi vẫn không hiểu chuyện này."},{"type":"simple","zh":"大家都百思不解他为什么突然辞职了。","pinyin":"Dàjiā dōu bǎisībùjiě tā wèishénme tūrán cízhí le.","vi":"Mọi người nghĩ mãi không hiểu tại sao anh ấy đột nhiên nghỉ việc."},{"type":"compound","zh":"门窗都锁得好好的，可是钱包却不见了，这让她百思不解。","pinyin":"Ménchuāng dōu suǒ de hǎohǎo de, kěshì qiánbāo què bújiàn le, zhè ràng tā bǎisībùjiě.","vi":"Cửa nẻo đều khóa cẩn thận mà ví tiền lại biến mất, điều này khiến cô ấy nghĩ mãi không ra."}],"related":[{"hanzi":"百思不得其解","pinyin":"bǎi sī bùdé qí jiě","vi":"nghĩ mãi không ra"},{"hanzi":"莫名其妙","pinyin":"mòmíngqímiào","vi":"khó hiểu"},{"hanzi":"困惑","pinyin":"kùnhuò","vi":"bối rối"},{"hanzi":"恍然大悟","pinyin":"huǎngrándàwù","vi":"bỗng nhiên tỉnh ngộ"}]},{"id":"版面","hanzi":"版面","pinyin":"bǎnmiàn","meaning_vi":"trang báo, bố cục trang in/giao diện","explanation":"版 (bản in) + 面 (bề mặt).","hsk_level":"7-9","tags":["danh-tu","cong-viec","cong-nghe"],"image":"📰","examples":[{"type":"basic","zh":"这份报纸版面清新。","pinyin":"Zhè fèn bàozhǐ bǎnmiàn qīngxīn.","vi":"Tờ báo này có cách trình bày trang thoáng đẹp."},{"type":"simple","zh":"编辑把这篇报道安排在了头版最显眼的版面。","pinyin":"Biānjí bǎ zhè piān bàodào ānpái zài le tóubǎn zuì xiǎnyǎn de bǎnmiàn.","vi":"Biên tập viên đã xếp bài phóng sự này vào vị trí nổi bật nhất trên trang nhất."},{"type":"compound","zh":"因为广告占了太多版面，所以新闻只能删减一些。","pinyin":"Yīnwèi guǎnggào zhànle tài duō bǎnmiàn, suǒyǐ xīnwén zhǐnéng shānjiǎn yìxiē.","vi":"Vì quảng cáo chiếm quá nhiều diện tích trang báo nên tin tức đành phải cắt bớt."}],"related":[{"hanzi":"排版","pinyin":"páibǎn","vi":"dàn trang"},{"hanzi":"版式","pinyin":"bǎnshì","vi":"định dạng trang"},{"hanzi":"头版","pinyin":"tóubǎn","vi":"trang nhất"},{"hanzi":"页面","pinyin":"yèmiàn","vi":"trang"}]},{"id":"饱含","hanzi":"饱含","pinyin":"bǎohán","meaning_vi":"chứa đựng đầy ắp (tình cảm/ý nghĩa)","explanation":"饱 (no/đầy) + 含 (chứa).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"她眼里饱含泪水。","pinyin":"Tā yǎn lǐ bǎohán lèishuǐ.","vi":"Mắt cô ấy đẫm lệ."},{"type":"simple","zh":"这封家书饱含着母亲对远方儿子的思念。","pinyin":"Zhè fēng jiāshū bǎohánzhe mǔqīn duì yuǎnfāng érzi de sīniàn.","vi":"Lá thư nhà này chứa chan nỗi nhớ của người mẹ dành cho đứa con nơi phương xa."},{"type":"compound","zh":"虽然他的歌声并不完美，但是饱含真情，打动了所有人。","pinyin":"Suīrán tā de gēshēng bìngbù wánměi, dànshì bǎohán zhēnqíng, dǎdòngle suǒyǒurén.","vi":"Tuy giọng hát của anh ấy không hoàn hảo nhưng chứa chan tình cảm chân thật nên đã lay động tất cả mọi người."}],"related":[{"hanzi":"包含","pinyin":"bāohán","vi":"bao hàm"},{"hanzi":"充满","pinyin":"chōngmǎn","vi":"tràn đầy"},{"hanzi":"饱含深情","pinyin":"bǎohánshēnqíng","vi":"chan chứa tình cảm"},{"hanzi":"蕴含","pinyin":"yùnhán","vi":"hàm chứa"}],"traditional":"飽含"},{"id":"宝库","hanzi":"宝库","pinyin":"bǎokù","meaning_vi":"kho báu, kho tàng tri thức/văn hóa","explanation":"宝 (báu vật) + 库 (kho chứa).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"图书馆是知识的宝库。","pinyin":"Túshūguǎn shì zhīshi de bǎokù.","vi":"Thư viện là kho báu của tri thức."},{"type":"simple","zh":"敦煌石窟被称为世界佛教艺术的宝库。","pinyin":"Dūnhuángshíkū bèi chēngwéi shìjiè Fójiào yìshù de bǎokù.","vi":"Hang đá Đôn Hoàng được mệnh danh là kho tàng nghệ thuật Phật giáo của thế giới."},{"type":"compound","zh":"民间故事不但有趣，而且是一座研究古代生活的宝库。","pinyin":"Mínjiān gùshi búdàn yǒuqù, érqiě shì yí zuò yánjiū gǔdài shēnghuó de bǎokù.","vi":"Truyện dân gian không chỉ thú vị mà còn là một kho tàng để nghiên cứu đời sống cổ xưa."}],"related":[{"hanzi":"宝藏","pinyin":"bǎozàng","vi":"kho báu"},{"hanzi":"宝贝","pinyin":"bǎobèi","vi":"báu vật"},{"hanzi":"知识宝库","pinyin":"zhīshibǎokù","vi":"kho tàng tri thức"},{"hanzi":"仓库","pinyin":"cāngkù","vi":"nhà kho"}],"traditional":"寶庫"},{"id":"保重身体","hanzi":"保重身体","pinyin":"bǎozhòngshēntǐ","meaning_vi":"giữ gìn sức khỏe","explanation":"保 (保) + 重 (nặng) + 身 (thân phận/tự thân) + 体 (thể hiện/hệ thống).","hsk_level":"7-9","tags":["dong-tu","giao-tiep","suc-khoe"],"image":"💐","examples":[{"type":"basic","zh":"请您保重身体。","pinyin":"Qǐng nín bǎozhòngshēntǐ.","vi":"Xin ông hãy giữ gìn sức khỏe."},{"type":"simple","zh":"临走时，奶奶一再叮嘱我在外面要保重身体。","pinyin":"Lín zǒushí, nǎinai yízài dīngzhǔ wǒ zài wàimiàn yào bǎozhòngshēntǐ.","vi":"Lúc tôi sắp đi, bà nội dặn đi dặn lại rằng ở ngoài phải giữ gìn sức khỏe."},{"type":"compound","zh":"工作再忙也要保重身体，否则累垮了就什么都做不成了。","pinyin":"Gōngzuò zài máng yě yào bǎozhòngshēntǐ, fǒuzé lèikuǎle jiù shénme dōu zuò bu chéngle.","vi":"Công việc bận đến đâu cũng phải giữ gìn sức khỏe, nếu không kiệt sức rồi thì chẳng làm được gì nữa."}],"related":[{"hanzi":"保重","pinyin":"bǎozhòng","vi":"bảo trọng"},{"hanzi":"注意身体","pinyin":"zhùyìshēntǐ","vi":"giữ gìn sức khỏe"},{"hanzi":"珍重","pinyin":"zhēnzhòng","vi":"giữ gìn"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"khỏe mạnh"}],"traditional":"保重身體"},{"id":"比比","hanzi":"比比","pinyin":"bǐbǐ","meaning_vi":"khắp nơi, đâu đâu cũng","explanation":"Lặp lại chữ 比.","hsk_level":"7-9","tags":["pho-tu"],"image":"🌐","examples":[{"type":"basic","zh":"这样的例子比比皆是。","pinyin":"Zhèyàng de lìzi bǐbǐjiēshì.","vi":"Những ví dụ như thế này đâu đâu cũng có."},{"type":"simple","zh":"在这条老街上，百年老字号比比皆是。","pinyin":"Zài zhè tiáo lǎo jiēshang, bǎinián lǎozìhao bǐbǐjiēshì.","vi":"Trên con phố cổ này, những cửa hiệu trăm năm tuổi có ở khắp nơi."},{"type":"compound","zh":"虽然这类骗局比比皆是，但是每年仍有很多老人上当。","pinyin":"Suīrán zhèlèi piànjú bǐbǐjiēshì, dànshì měinián réng yǒu hěn duō lǎorén shàngdàng.","vi":"Tuy những trò lừa đảo kiểu này nhan nhản khắp nơi nhưng năm nào vẫn có nhiều người già mắc bẫy."}],"related":[{"hanzi":"比比皆是","pinyin":"bǐbǐjiēshì","vi":"đâu đâu cũng có"},{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"处处","pinyin":"chùchù","vi":"mọi nơi"},{"hanzi":"屡见不鲜","pinyin":"lǚjiànbùxiān","vi":"thường thấy chẳng lạ"}]},{"id":"比划","hanzi":"比划","pinyin":"bǐhua","meaning_vi":"ra hiệu bằng tay chân, múa may","explanation":"比 (tỉ – so, ra dấu) + 划 (hoạch – vạch, khua) → khua tay ra hiệu, diễn tả bằng động tác; khẩu ngữ, cũng viết 比画. VD: 用手比划了一下.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤟","examples":[{"type":"basic","zh":"他用手比划着说话。","pinyin":"Tāyòng shǒu bǐhuazhe shuōhuà.","vi":"Anh ấy vừa nói vừa khoa tay múa chân."},{"type":"simple","zh":"外国游客对着菜单比划了半天才点好菜。","pinyin":"Wàiguó yóukè duìzhe càidān bǐhuale bàn tiāncái diǎn hǎo cài.","vi":"Du khách nước ngoài chỉ trỏ vào thực đơn ra hiệu cả buổi mới gọi xong món."},{"type":"compound","zh":"因为语言不通，所以他们只能靠比划来交流。","pinyin":"Yīnwèi yǔyán bùtōng, suǒyǐ tāmen zhǐnéng kào bǐhua lái jiāoliú.","vi":"Vì bất đồng ngôn ngữ nên họ chỉ có thể giao tiếp bằng cách ra hiệu bằng tay."}],"related":[{"hanzi":"手势","pinyin":"shǒushì","vi":"cử chỉ tay"},{"hanzi":"比画","pinyin":"bǐhua","vi":"ra hiệu"},{"hanzi":"打手势","pinyin":"dǎshǒushì","vi":"ra dấu tay"},{"hanzi":"指手画脚","pinyin":"zhǐshǒuhuàjiǎo","vi":"khoa chân múa tay"}],"traditional":"比劃"},{"id":"笔迹","hanzi":"笔迹","pinyin":"bǐjì","meaning_vi":"nét chữ, bút tích","explanation":"笔 (bút) + 迹 (tích – dấu vết) → nét chữ, bút tích riêng của mỗi người. VD: 笔迹鉴定 (giám định chữ viết).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"这是谁的笔迹？","pinyin":"Zhè shì shéi de bǐjì?","vi":"Đây là nét chữ của ai?"},{"type":"simple","zh":"专家正在鉴定这份遗嘱上的笔迹。","pinyin":"Zhuānjiā zhèngzài jiàndìng zhè fèn yízhǔ shang de bǐjì.","vi":"Chuyên gia đang giám định nét chữ trên bản di chúc này."},{"type":"compound","zh":"一看到信封上熟悉的笔迹，她就知道是外婆写来的。","pinyin":"Yí kàndào xìnfēng shang shúxī de bǐjì, tā jiù zhīdào shì wàipó xiě lái de.","vi":"Vừa nhìn thấy nét chữ quen thuộc trên phong bì, cô ấy đã biết là thư bà ngoại gửi."}],"related":[{"hanzi":"字迹","pinyin":"zìjì","vi":"nét chữ"},{"hanzi":"手迹","pinyin":"shǒujì","vi":"bút tích"},{"hanzi":"签名","pinyin":"qiānmíng","vi":"chữ ký"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"}],"traditional":"筆跡"},{"id":"笔名","hanzi":"笔名","pinyin":"bǐmíng","meaning_vi":"bút danh","explanation":"笔 (bút) + 名 (danh tiếng/nổi tiếng).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🖋️","examples":[{"type":"basic","zh":"鲁迅是他的笔名。","pinyin":"Lǔxùn shì tā de bǐmíng.","vi":"Lỗ Tấn là bút danh của ông ấy."},{"type":"simple","zh":"她用一个男性笔名发表了第一部小说。","pinyin":"Tā yòng yí gè nánxìng bǐmíng fābiǎole dìyī bù xiǎoshuō.","vi":"Bà ấy dùng một bút danh nam giới để xuất bản cuốn tiểu thuyết đầu tiên."},{"type":"compound","zh":"因为他一直用笔名写作，所以很少有读者知道他的真名。","pinyin":"Yīnwèi tā yìzhí yòng bǐmíng xiězuò, suǒyǐ hěn shǎoyǒu dúzhě zhīdào tā de zhēn míng.","vi":"Vì ông ấy luôn viết dưới bút danh nên rất ít độc giả biết tên thật của ông."}],"related":[{"hanzi":"真名","pinyin":"zhēnmíng","vi":"tên thật"},{"hanzi":"艺名","pinyin":"yìmíng","vi":"nghệ danh"},{"hanzi":"化名","pinyin":"huàmíng","vi":"tên giả"},{"hanzi":"作家","pinyin":"zuòjiā","vi":"nhà văn"}],"traditional":"筆名"},{"id":"鄙视","hanzi":"鄙视","pinyin":"bǐshì","meaning_vi":"khinh bỉ, coi thường","explanation":"鄙 (thô bỉ/thấp kém) + 视 (nhìn).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"我鄙视这种人。","pinyin":"Wǒ bǐshì zhè zhǒng rén.","vi":"Tôi khinh bỉ loại người này."},{"type":"simple","zh":"他从不鄙视做体力劳动的人。","pinyin":"Tā cóng bù bǐshì zuò tǐlìláodòng de rén.","vi":"Anh ấy chưa bao giờ coi thường những người làm lao động chân tay."},{"type":"compound","zh":"即使对方说了很难听的话，你也不该用鄙视的眼神看他。","pinyin":"Jíshǐ duìfāng shuōle hěn nántīng dehuà, nǐ yě bùgāi yòng bǐshì de yǎnshén kàn tā.","vi":"Dù đối phương nói những lời rất khó nghe, bạn cũng không nên nhìn anh ta bằng ánh mắt khinh bỉ."}],"related":[{"hanzi":"轻视","pinyin":"qīngshì","vi":"coi thường"},{"hanzi":"蔑视","pinyin":"mièshì","vi":"miệt thị"},{"hanzi":"瞧不起","pinyin":"qiáobuqǐ","vi":"xem thường"},{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"}],"traditional":"鄙視"},{"id":"比喻义","hanzi":"比喻义","pinyin":"bǐyùyì","meaning_vi":"nghĩa ẩn dụ","explanation":"比 (so với) + 喻 (ví von/hiểu rõ) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🎨","examples":[{"type":"basic","zh":"这个词有比喻义。","pinyin":"Zhè ge cí yǒu bǐyùyì.","vi":"Từ này có nghĩa ẩn dụ."},{"type":"simple","zh":"铁饭碗的比喻义是指稳定的工作。","pinyin":"Tiěfànwǎn de bǐyùyì shì zhǐ wěndìng de gōngzuò.","vi":"Nghĩa ẩn dụ của \"bát cơm sắt\" là chỉ công việc ổn định."},{"type":"compound","zh":"如果只看字面意思而忽略比喻义，就会误解这句话。","pinyin":"Rúguǒ zhǐ kàn zìmiàn yìsi ér hūlüè bǐyùyì, jiù huì wùjiě zhè jù huà.","vi":"Nếu chỉ nhìn nghĩa đen mà bỏ qua nghĩa ẩn dụ thì sẽ hiểu sai câu này."}],"related":[{"hanzi":"本义","pinyin":"běnyì","vi":"nghĩa gốc"},{"hanzi":"引申义","pinyin":"yǐnshēnyì","vi":"nghĩa mở rộng"},{"hanzi":"比喻","pinyin":"bǐyù","vi":"ẩn dụ so sánh"},{"hanzi":"修辞","pinyin":"xiūcí","vi":"tu từ"}],"traditional":"比喻義"},{"id":"比重","hanzi":"比重","pinyin":"bǐzhòng","meaning_vi":"tỷ trọng","explanation":"比 + 重 (trọng lượng).","hsk_level":"7-9","tags":["danh-tu","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"服务业比重上升了。","pinyin":"Fúwùyè bǐzhòng shàngshēng le.","vi":"Tỷ trọng ngành dịch vụ đã tăng lên."},{"type":"simple","zh":"网上购物在家庭消费中所占的比重越来越大。","pinyin":"Wǎngshàng gòuwù zài jiātíng xiāofèi zhōng suǒ zhàn de bǐzhòng yuèláiyuè dà.","vi":"Tỷ trọng mua sắm trực tuyến trong chi tiêu gia đình ngày càng lớn."},{"type":"compound","zh":"因为蔬菜在饮食中的比重提高了，所以他的血脂下降了。","pinyin":"Yīnwèi shūcài zài yǐnshí zhōng de bǐzhòng tígāo le, suǒyǐ tā de xuèzhī xiàjiàng le.","vi":"Vì tỷ trọng rau xanh trong bữa ăn tăng lên nên mỡ máu của anh ấy đã giảm."}],"related":[{"hanzi":"比例","pinyin":"bǐlì","vi":"tỷ lệ"},{"hanzi":"占比","pinyin":"zhànbǐ","vi":"tỷ trọng chiếm"},{"hanzi":"份额","pinyin":"fèn'é","vi":"phần"},{"hanzi":"百分比","pinyin":"bǎifēnbǐ","vi":"phần trăm"}]},{"id":"秉性","hanzi":"秉性","pinyin":"bǐngxìng","meaning_vi":"bản tính trời sinh","explanation":"秉 (nắm giữ) + 性 (tính tình).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"他秉性善良。","pinyin":"Tā bǐngxìng shànliáng.","vi":"Anh ấy bản tính lương thiện."},{"type":"simple","zh":"姐妹俩虽是双胞胎，秉性却完全不同。","pinyin":"Jiěmèi liǎ suīshì shuāngbāotāi, bǐngxìng què wánquán bùtóng.","vi":"Hai chị em tuy là sinh đôi nhưng bản tính lại hoàn toàn khác nhau."},{"type":"compound","zh":"江山易改，秉性难移，所以别指望他一下子改掉坏脾气。","pinyin":"Jiāngshān yì gǎi, bǐngxìng nán yí, suǒyǐ bié zhǐwàng tā yíxiàzi gǎidiào huàipíqi.","vi":"Giang sơn dễ đổi, bản tính khó dời, nên đừng mong anh ta bỏ được tính nóng nảy ngay một lúc."}],"related":[{"hanzi":"本性","pinyin":"běnxìng","vi":"bản tính"},{"hanzi":"性格","pinyin":"xìnggé","vi":"tính cách"},{"hanzi":"天性","pinyin":"tiānxìng","vi":"thiên tính"},{"hanzi":"禀性","pinyin":"bǐngxìng","vi":"bẩm tính"}]},{"id":"捕风捉影","hanzi":"捕风捉影","pinyin":"bǔfēng-zhuōyǐng","meaning_vi":"bắt gió bắt bóng (suy đoán vô căn cứ)","explanation":"捕风捉影: bắt (捕) gió (风), chụp (捉) bóng (影) → nói, làm dựa trên điều mơ hồ, suy đoán không có căn cứ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌬️","examples":[{"type":"basic","zh":"别捕风捉影。","pinyin":"Bié bǔfēngzhuōyǐng.","vi":"Đừng bắt gió bắt bóng."},{"type":"simple","zh":"那篇报道捕风捉影地猜测明星的私生活。","pinyin":"Nà piān bàodào bǔfēngzhuōyǐng de cāicè míngxīng de sīshēnghuó.","vi":"Bài báo đó suy đoán vô căn cứ về đời tư của ngôi sao."},{"type":"compound","zh":"如果没有确凿证据，就不要捕风捉影地怀疑同事。","pinyin":"Rúguǒ méiyǒu quèzáo zhèngjù, jiù bú yào bǔfēngzhuōyǐng de huáiyí tóngshì.","vi":"Nếu không có bằng chứng xác thực thì đừng nghi ngờ đồng nghiệp một cách vô căn cứ."}],"related":[{"hanzi":"无中生有","pinyin":"wúzhōngshēngyǒu","vi":"bịa đặt"},{"hanzi":"道听途说","pinyin":"dàotīngtúshuō","vi":"nghe hơi nồi chõ"},{"hanzi":"毫无根据","pinyin":"háowúgēnjù","vi":"không căn cứ"},{"hanzi":"有凭有据","pinyin":"yǒupíngyǒujù","vi":"có bằng chứng"}],"traditional":"捕風捉影"},{"id":"创举","hanzi":"创举","pinyin":"chuàngjǔ","meaning_vi":"sáng kiến vĩ đại, việc làm tiên phong chưa từng có","explanation":"创 (sáng tạo) + 举 (hành động).","hsk_level":"7-9","tags":["danh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"这是一项伟大的创举。","pinyin":"Zhè shì yí xiàng wěidà de chuàngjǔ.","vi":"Đây là một sáng kiến vĩ đại chưa từng có."},{"type":"simple","zh":"在沙漠里种出水稻被称为农业史上的创举。","pinyin":"Zài shāmò lǐ zhòng chū shuǐdào bèi chēngwéi nóngyè shǐshang de chuàngjǔ.","vi":"Trồng được lúa nước trên sa mạc được coi là một kỳ tích tiên phong trong lịch sử nông nghiệp."},{"type":"compound","zh":"因为免费夜校在当时是个创举，所以吸引了很多报纸前来报道。","pinyin":"Yīnwèi miǎnfèi yèxiào zài dāngshí shì gè chuàngjǔ, suǒyǐ xīyǐnle hěn duō bàozhǐ qiánlái bàodào.","vi":"Vì lớp học ban đêm miễn phí khi đó là một việc làm tiên phong nên đã thu hút nhiều tờ báo đến đưa tin."}],"related":[{"hanzi":"壮举","pinyin":"zhuàngjǔ","vi":"kỳ tích"},{"hanzi":"首创","pinyin":"shǒuchuàng","vi":"sáng tạo đầu tiên"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"đổi mới"},{"hanzi":"开创","pinyin":"kāichuàng","vi":"mở ra"}],"traditional":"創舉"},{"id":"传感器","hanzi":"传感器","pinyin":"chuángǎnqì","meaning_vi":"cảm biến","explanation":"传 (传) + 感 (感) + 器 (thiết bị/cơ quan).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","do-vat"],"image":"📟","examples":[{"type":"basic","zh":"这个传感器很灵敏。","pinyin":"Zhè ge chuángǎnqì hěn língmǐn.","vi":"Cảm biến này rất nhạy."},{"type":"simple","zh":"楼道里的灯装了声控传感器，一拍手就亮。","pinyin":"Lóu Dàolǐ de dēng zhuāngle shēng kòng chuángǎnqì, yì pāishǒu jiù liàng.","vi":"Đèn ở hành lang được lắp cảm biến âm thanh, vỗ tay một cái là sáng."},{"type":"compound","zh":"只要传感器检测到烟雾，报警器就会立刻响起来。","pinyin":"Zhǐyào chuángǎnqì jiǎncè dào yānwù, bàojǐngqì jiù huì lìkè xiǎng qǐlái.","vi":"Chỉ cần cảm biến phát hiện khói thì chuông báo động sẽ lập tức reo lên."}],"related":[{"hanzi":"感应","pinyin":"gǎnyìng","vi":"cảm ứng"},{"hanzi":"探测器","pinyin":"tàncèqì","vi":"thiết bị dò"},{"hanzi":"芯片","pinyin":"xīnpiàn","vi":"chip"},{"hanzi":"智能","pinyin":"zhìnéng","vi":"thông minh"}],"traditional":"傳感器"},{"id":"传家宝","hanzi":"传家宝","pinyin":"chuánjiābǎo","meaning_vi":"vật gia truyền","explanation":"传 (truyền) + 家 (gia – nhà) + 宝 (bảo – báu vật) → báu vật truyền đời trong gia đình, vật gia truyền; nghĩa bóng: truyền thống quý được lưu giữ.","hsk_level":"7-9","tags":["danh-tu","gia-dinh","van-hoa"],"image":"💎","examples":[{"type":"basic","zh":"这块玉是传家宝。","pinyin":"Zhè kuài yù shì chuánjiābǎo.","vi":"Miếng ngọc này là vật gia truyền."},{"type":"simple","zh":"奶奶把一只银手镯当作传家宝留给了我。","pinyin":"Nǎinai bǎ yì zhī yínshǒuzhuó dàngzuò chuánjiābǎo liúgěile wǒ.","vi":"Bà nội để lại cho tôi một chiếc vòng bạc làm vật gia truyền."},{"type":"compound","zh":"虽然这把旧茶壶不值钱，但是它是我们家的传家宝。","pinyin":"Suīrán zhè bǎ jiù cháhú bù zhíqián, dànshì tā shì wǒmen jiā de chuánjiābǎo.","vi":"Tuy chiếc ấm trà cũ này không đáng tiền nhưng nó là vật gia truyền của nhà chúng tôi."}],"related":[{"hanzi":"祖传","pinyin":"zǔchuán","vi":"gia truyền"},{"hanzi":"宝贝","pinyin":"bǎobèi","vi":"báu vật"},{"hanzi":"遗产","pinyin":"yíchǎn","vi":"di sản"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"}],"traditional":"傳家寶"},{"id":"传染源","hanzi":"传染源","pinyin":"chuánrǎnyuán","meaning_vi":"nguồn lây nhiễm","explanation":"传 (传) + 染 (nhuộm (tóc/vải)) + 源 (nguồn gốc).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","khoa-hoc"],"image":"🦠","examples":[{"type":"basic","zh":"必须控制传染源。","pinyin":"Bìxū kòngzhì chuánrǎnyuán.","vi":"Phải kiểm soát nguồn lây nhiễm."},{"type":"simple","zh":"疾控人员终于找到了这次流感疫情的传染源。","pinyin":"Jí kòng rényuán zhōngyú zhǎodàole zhè cì liúgǎn yìqíng de chuánrǎnyuán.","vi":"Nhân viên kiểm soát dịch bệnh cuối cùng đã tìm ra nguồn lây nhiễm của đợt dịch cúm lần này."},{"type":"compound","zh":"只要及时隔离传染源，疫情就不会大范围扩散。","pinyin":"Zhǐyào jíshí gélí chuánrǎnyuán, yìqíng jiù bú huì dàfànwéi kuòsàn.","vi":"Chỉ cần kịp thời cách ly nguồn lây nhiễm thì dịch bệnh sẽ không lây lan trên diện rộng."}],"related":[{"hanzi":"传染病","pinyin":"chuánrǎnbìng","vi":"bệnh truyền nhiễm"},{"hanzi":"传染","pinyin":"chuánrǎn","vi":"lây nhiễm"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"隔离","pinyin":"gélí","vi":"cách ly"}],"traditional":"傳染源"},{"id":"传神","hanzi":"传神","pinyin":"chuánshén","meaning_vi":"truyền thần, sống động có hồn (bức vẽ/miêu tả)","explanation":"传 + 神 (thần thái).","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"这幅画画得很传神。","pinyin":"Zhè fú huàhuà de hěn chuánshén.","vi":"Bức tranh này vẽ rất có hồn."},{"type":"simple","zh":"他的翻译非常传神，保留了原诗的韵味。","pinyin":"Tā de fānyì fēicháng chuánshén, bǎoliúle yuán shī de yùnwèi.","vi":"Bản dịch của anh ấy rất truyền thần, giữ được phong vị của bài thơ gốc."},{"type":"compound","zh":"画家只用了几笔，就把小猫顽皮的样子画得十分传神。","pinyin":"Huàjiā zhǐ yòngle jǐ bǐ, jiù bǎ xiǎomāo wánpí de yàngzi huà de shífēn chuánshén.","vi":"Họa sĩ chỉ dùng vài nét bút đã vẽ dáng vẻ tinh nghịch của chú mèo con vô cùng sống động."}],"related":[{"hanzi":"逼真","pinyin":"bīzhēn","vi":"giống như thật"},{"hanzi":"栩栩如生","pinyin":"xǔxǔrúshēng","vi":"sống động như thật"},{"hanzi":"生动","pinyin":"shēngdòng","vi":"sinh động"},{"hanzi":"呆板","pinyin":"dāibǎn","vi":"cứng nhắc"}],"traditional":"傳神"},{"id":"穿插","hanzi":"穿插","pinyin":"chuānchā","meaning_vi":"đan xen, lồng ghép","explanation":"穿 (mặc) + 插 (cắm).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔀","examples":[{"type":"basic","zh":"节目中穿插了抽奖。","pinyin":"Jiémù zhōng chuānchāle chōujiǎng.","vi":"Trong chương trình có xen kẽ phần bốc thăm trúng thưởng."},{"type":"simple","zh":"老师在讲课时穿插了很多有趣的历史故事。","pinyin":"Lǎoshī zài jiǎng kèshí chuānchāle hěn duō yǒuqù de lìshǐ gùshi.","vi":"Khi giảng bài, thầy giáo lồng ghép rất nhiều câu chuyện lịch sử thú vị."},{"type":"compound","zh":"如果在长篇报告里穿插一些图表，听众就不容易走神。","pinyin":"Rúguǒ zài chángpiān bàogào lǐ chuānchā yìxiē túbiǎo, tīngzhòng jiù bù róngyì zǒushén.","vi":"Nếu lồng ghép một số biểu đồ vào bản báo cáo dài thì người nghe sẽ không dễ mất tập trung."}],"related":[{"hanzi":"交叉","pinyin":"jiāochā","vi":"đan chéo"},{"hanzi":"插入","pinyin":"chārù","vi":"chèn vào"},{"hanzi":"交错","pinyin":"jiāocuò","vi":"đan xen"},{"hanzi":"夹杂","pinyin":"jiāzá","vi":"xen lẫn"}]},{"id":"穿流","hanzi":"穿流","pinyin":"chuānliú","meaning_vi":"chảy xuyên qua","explanation":"穿 (xuyên – xuyên qua) + 流 (lưu – chảy) → chảy xuyên qua (sông chảy qua thành phố...). Lưu ý: từ hiếm, dễ nhầm với 川流 trong 川流不息 (dòng người, xe tấp nập không ngớt).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"小溪从村中穿流而过。","pinyin":"Xiǎoxī cóng cūn zhōng chuānliú ér guò.","vi":"Con suối nhỏ chảy xuyên qua giữa làng."},{"type":"simple","zh":"一条清澈的小河穿流过整个古镇。","pinyin":"Yì tiáo qīngchè de xiǎohé chuānliúguò zhěnggè gǔzhèn.","vi":"Một con sông nhỏ trong vắt chảy xuyên qua cả thị trấn cổ."},{"type":"compound","zh":"因为河水穿流过城区，所以这座城市有很多石桥。","pinyin":"Yīnwèi héshuǐ chuānliúguò chéngqū, suǒyǐ zhè zuò chéngshì yǒu hěn duō shí qiáo.","vi":"Vì dòng sông chảy xuyên qua nội thành nên thành phố này có rất nhiều cầu đá."}],"related":[{"hanzi":"穿过","pinyin":"chuānguò","vi":"xuyên qua"},{"hanzi":"流淌","pinyin":"liútǎng","vi":"chảy"},{"hanzi":"川流不息","pinyin":"chuānliúbùxī","vi":"nườm nượp không ngớt"},{"hanzi":"流经","pinyin":"liújīng","vi":"chảy qua"}]},{"id":"吹灰之力","hanzi":"吹灰之力","pinyin":"chuīhuī-zhīlì","meaning_vi":"sức thổi hạt bụi (việc cực kỳ dễ dàng)","explanation":"Cụm: 不费吹灰之力 (dễ như trở bàn tay).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💨","examples":[{"type":"basic","zh":"他不费吹灰之力就赢了。","pinyin":"Tā bú fèi chuīhuīzhīlì jiù yíng le.","vi":"Anh ấy thắng mà chẳng tốn chút sức nào."},{"type":"simple","zh":"小李不费吹灰之力就修好了打印机。","pinyin":"Xiǎo Lǐ bú fèi chuīhuīzhīlì jiù xiūhǎole dǎyìnjī.","vi":"Tiểu Lý sửa xong máy in dễ như trở bàn tay."},{"type":"compound","zh":"别看他解这道题不费吹灰之力，其实他练了好几年。","pinyin":"Biékàn tā jiě zhè dào tí bú fèi chuīhuīzhīlì, qíshí tā liànle hǎojǐnián.","vi":"Đừng thấy cậu ấy giải bài này dễ như không, thật ra cậu ấy đã luyện mấy năm trời."}],"related":[{"hanzi":"不费吹灰之力","pinyin":"bú fèi chuīhuīzhīlì","vi":"chẳng tốn chút sức"},{"hanzi":"轻而易举","pinyin":"qīng'éryìjǔ","vi":"dễ như trở bàn tay"},{"hanzi":"易如反掌","pinyin":"yìrúfǎnzhǎng","vi":"dễ như lật bàn tay"},{"hanzi":"九牛二虎之力","pinyin":"jiǔ niú èr hǔ zhī lì","vi":"sức chín trâu hai hổ"}]},{"id":"忏悔","hanzi":"忏悔","pinyin":"chànhuǐ","meaning_vi":"sám hối, ăn năn hối lỗi","explanation":"Cả hai chữ đều có bộ tâm đứng 忄.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙏","examples":[{"type":"basic","zh":"他在信中忏悔。","pinyin":"Tā zài xìn zhōng chànhuǐ.","vi":"Anh ấy sám hối trong thư."},{"type":"simple","zh":"老人临终前向家人忏悔了年轻时犯下的错。","pinyin":"Lǎorén línzhōng qián xiàng jiārén chànhuǐle niánqīng shí fàn xià de cuò.","vi":"Trước lúc lâm chung, ông lão đã sám hối với gia đình về lỗi lầm thời trẻ."},{"type":"compound","zh":"即使他现在真心忏悔，受害者受到的伤害也无法弥补了。","pinyin":"Jíshǐ tā xiànzài zhēnxīn chànhuǐ, shòuhàizhě shòudào de shānghài yě wúfǎ míbǔ le.","vi":"Dù bây giờ hắn thật lòng sám hối thì tổn thương mà nạn nhân phải chịu cũng không thể bù đắp được nữa."}],"related":[{"hanzi":"悔过","pinyin":"huǐguò","vi":"hối lỗi"},{"hanzi":"后悔","pinyin":"hòuhuǐ","vi":"hối hận"},{"hanzi":"悔改","pinyin":"huǐgǎi","vi":"hối cải"},{"hanzi":"反省","pinyin":"fǎnxǐng","vi":"tự kiểm điểm"}],"traditional":"懺悔"},{"id":"畅销书","hanzi":"畅销书","pinyin":"chàngxiāoshū","meaning_vi":"sách bán chạy (bestseller)","explanation":"畅销 (sướng tiêu – bán chạy) + 书 (thư – sách) → sách bán chạy, bestseller. VD: 畅销书排行榜.","hsk_level":"7-9","tags":["danh-tu","hoc-tap","mua-sam"],"image":"📚","examples":[{"type":"basic","zh":"这本书是畅销书。","pinyin":"Zhè běn shū shì chàngxiāoshū.","vi":"Cuốn sách này là sách bán chạy."},{"type":"simple","zh":"机场书店的门口摆满了今年的畅销书。","pinyin":"Jīchǎng shūdiàn de ménkǒu bǎimǎnle jīnnián de chàngxiāoshū.","vi":"Trước cửa hiệu sách ở sân bay bày đầy sách bán chạy của năm nay."},{"type":"compound","zh":"虽然这本小说成了畅销书，但是评论家对它评价不高。","pinyin":"Suīrán zhè běn xiǎoshuō chéngle chàngxiāoshū, dànshì pínglùnjiā duì tā píngjià bù gāo.","vi":"Tuy cuốn tiểu thuyết này đã trở thành sách bán chạy nhưng giới phê bình đánh giá không cao."}],"related":[{"hanzi":"畅销","pinyin":"chàngxiāo","vi":"bán chạy"},{"hanzi":"滞销","pinyin":"zhìxiāo","vi":"ế ẩm"},{"hanzi":"销量","pinyin":"xiāoliàng","vi":"doanh số"},{"hanzi":"出版","pinyin":"chūbǎn","vi":"xuất bản"}],"traditional":"暢銷書"},{"id":"查处","hanzi":"查处","pinyin":"cháchǔ","meaning_vi":"điều tra và xử lý","explanation":"查 (tra – điều tra) + 处 (xử – xử lý) → điều tra và xử lý vi phạm; dùng cho cơ quan chức năng: 依法查处, 查处腐败案件.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚔","examples":[{"type":"basic","zh":"此案已被查处。","pinyin":"Cǐ àn yǐ bèi cháchǔ.","vi":"Vụ án này đã bị điều tra và xử lý."},{"type":"simple","zh":"市场监管部门查处了一批销售假药的网店。","pinyin":"Shìchǎng jiānguǎn bùmén cháchǔle yìpī xiāoshòu jiǎyào de wǎngdiàn.","vi":"Cơ quan quản lý thị trường đã điều tra xử lý một loạt cửa hàng trực tuyến bán thuốc giả."},{"type":"compound","zh":"一旦发现餐厅使用过期食材，卫生部门就会依法查处。","pinyin":"Yídàn fāxiàn cāntīng shǐyòng guòqī shícái, wèishēng bùmén jiù huì yīfǎ cháchǔ.","vi":"Một khi phát hiện nhà hàng dùng nguyên liệu quá hạn, cơ quan y tế sẽ điều tra xử lý theo pháp luật."}],"related":[{"hanzi":"查办","pinyin":"chábàn","vi":"điều tra xử lý"},{"hanzi":"处罚","pinyin":"chǔfá","vi":"xử phạt"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"严肃查处","pinyin":"yánsùcháchǔ","vi":"xử lý nghiêm"}],"traditional":"查處"},{"id":"茶道","hanzi":"茶道","pinyin":"chádào","meaning_vi":"trà đạo","explanation":"茶 (trà) + 道 (đạo lý).","hsk_level":"7-9","tags":["danh-tu","van-hoa","an-uong"],"image":"🍵","examples":[{"type":"basic","zh":"她在学习日本茶道。","pinyin":"Tā zài xuéxí Rìběn chádào.","vi":"Cô ấy đang học trà đạo Nhật Bản."},{"type":"simple","zh":"茶道老师示范了从温杯到奉茶的每一个步骤。","pinyin":"Chádào lǎoshī shìfànle cóng wēn bēi dào fèng chá de měi yí gè bùzhòu.","vi":"Cô giáo trà đạo làm mẫu từng bước từ tráng chén đến dâng trà."},{"type":"compound","zh":"茶道不但讲究泡茶的技巧，而且注重心境的平和。","pinyin":"Chádào búdàn jiǎngjiu pàochá de jìqiǎo, érqiě zhùzhòng xīnjìng de pínghé.","vi":"Trà đạo không chỉ chú trọng kỹ thuật pha trà mà còn coi trọng sự an hòa của tâm hồn."}],"related":[{"hanzi":"茶艺","pinyin":"cháyì","vi":"nghệ thuật pha trà"},{"hanzi":"品茶","pinyin":"pǐnchá","vi":"thưởng trà"},{"hanzi":"茶叶","pinyin":"cháyè","vi":"lá trà"},{"hanzi":"茶具","pinyin":"chájù","vi":"bộ ấm trà"}]},{"id":"查封","hanzi":"查封","pinyin":"cháfēng","meaning_vi":"niêm phong, phong tỏa (tài sản)","explanation":"查 (tra – kiểm tra) + 封 (phong – niêm phong) → kiểm tra rồi niêm phong, phong tỏa tài sản, cơ sở vi phạm theo pháp luật. VD: 查封财产.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔒","examples":[{"type":"basic","zh":"这家工厂被查封了。","pinyin":"Zhè jiā gōngchǎng bèi cháfēng le.","vi":"Nhà máy này đã bị niêm phong."},{"type":"simple","zh":"法院依法查封了他名下的两套房产。","pinyin":"Fǎyuàn yīfǎ cháfēngle tā míngxià de liǎng tào fángchǎn.","vi":"Tòa án đã niêm phong theo pháp luật hai căn nhà đứng tên ông ta."},{"type":"compound","zh":"如果他到期还不还债，银行就会申请查封他的公司。","pinyin":"Rúguǒ tā dàoqī hái bu huán zhài, yínháng jiù huì shēnqǐng cháfēng tā de gōngsī.","vi":"Nếu đến hạn mà ông ấy vẫn không trả nợ thì ngân hàng sẽ yêu cầu niêm phong công ty của ông ấy."}],"related":[{"hanzi":"封存","pinyin":"fēngcún","vi":"niêm cất"},{"hanzi":"没收","pinyin":"mòshōu","vi":"tịch thu"},{"hanzi":"冻结","pinyin":"dòngjié","vi":"phong tỏa"},{"hanzi":"扣押","pinyin":"kòuyā","vi":"tạm giữ"}]},{"id":"查证","hanzi":"查证","pinyin":"cházhèng","meaning_vi":"điều tra xác minh","explanation":"查 (tra) + 证 (chứng minh/chứng cứ).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔍","examples":[{"type":"basic","zh":"消息尚待查证。","pinyin":"Xiāoxi shàngdài cházhèng.","vi":"Tin tức vẫn còn chờ xác minh."},{"type":"simple","zh":"记者花了一周时间查证这条爆料的真实性。","pinyin":"Jìzhě huāle yìzhōu shíjiān cházhèng zhè tiáo bàoliào de zhēnshí xìng.","vi":"Phóng viên mất một tuần để xác minh tính xác thực của tin tố giác này."},{"type":"compound","zh":"网上的消息只有经过查证，才能写进新闻报道。","pinyin":"Wǎngshàng de xiāoxi zhǐyǒu jīngguò cházhèng, cáinéng xiě jìn xīnwén bàodào.","vi":"Tin tức trên mạng chỉ khi đã được xác minh mới có thể đưa vào bản tin."}],"related":[{"hanzi":"核实","pinyin":"héshí","vi":"xác minh"},{"hanzi":"验证","pinyin":"yànzhèng","vi":"kiểm chứng"},{"hanzi":"证实","pinyin":"zhèngshí","vi":"chứng thực"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"}],"traditional":"查證"},{"id":"蝉联","hanzi":"蝉联","pinyin":"chánlián","meaning_vi":"bảo vệ thành công chức vô địch liên tiếp","explanation":"蝉 (ve sầu lột xác nối tiếp) + 联 (liên tiếp).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"她蝉联了冠军。","pinyin":"Tā chánliánle guànjūn.","vi":"Cô ấy đã liên tiếp giữ ngôi vô địch."},{"type":"simple","zh":"这家餐厅连续五年蝉联本市最受欢迎餐厅。","pinyin":"Zhè jiā cāntīng liánxù wǔ nián chánlián běnshì zuì shòuhuānyíng cāntīng.","vi":"Nhà hàng này năm năm liền giữ danh hiệu nhà hàng được yêu thích nhất thành phố."},{"type":"compound","zh":"如果这次再赢，他就能三届蝉联世界冠军。","pinyin":"Rúguǒ zhè cì zài yíng, tā jiù néng sān jiè chánlián shìjiè guànjūn.","vi":"Nếu lần này thắng nữa, anh ấy sẽ ba kỳ liên tiếp giữ ngôi vô địch thế giới."}],"related":[{"hanzi":"连任","pinyin":"liánrèn","vi":"tái nhiệm"},{"hanzi":"卫冕","pinyin":"wèimiǎn","vi":"bảo vệ ngôi vương"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"quán quân"},{"hanzi":"连续","pinyin":"liánxù","vi":"liên tục"}],"traditional":"蟬聯"},{"id":"常备不懈","hanzi":"常备不懈","pinyin":"chángbèi-búxiè","meaning_vi":"luôn cảnh giác sẵn sàng không lơ là","explanation":"常备 (thường bị – luôn chuẩn bị) + 不懈 (không lơ là) → luôn sẵn sàng, cảnh giác không chút lơi lỏng; hay dùng trong quốc phòng, phòng chống thiên tai.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🛡️","examples":[{"type":"basic","zh":"防汛工作要常备不懈。","pinyin":"Fángxùn gōngzuò yào chángbèibúxiè.","vi":"Công tác phòng lũ phải luôn sẵn sàng, không được lơ là."},{"type":"simple","zh":"消防队员一年四季都保持着常备不懈的状态。","pinyin":"Xiāofáng duìyuán yì nián sìjì dōu bǎochízhe chángbèibúxiè de zhuàngtài.","vi":"Lính cứu hỏa quanh năm suốt tháng luôn giữ trạng thái sẵn sàng, không lơ là."},{"type":"compound","zh":"即使最近没有发生地震，救援队也要常备不懈。","pinyin":"Jíshǐ zuìjìn méiyǒu fāshēng dìzhèn, jiùyuánduì yě yào chángbèibúxiè.","vi":"Dù gần đây không xảy ra động đất, đội cứu hộ vẫn phải luôn cảnh giác sẵn sàng."}],"related":[{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"},{"hanzi":"有备无患","pinyin":"yǒubèiwúhuàn","vi":"có chuẩn bị không lo"},{"hanzi":"防患未然","pinyin":"fánghuànwèirán","vi":"phòng bệnh hơn chữa"},{"hanzi":"麻痹大意","pinyin":"mábìdàyì","vi":"chủ quan lơ là"}],"traditional":"常備不懈"},{"id":"常规","hanzi":"常规","pinyin":"chángguī","meaning_vi":"thông thường, quy tắc thông lệ","explanation":"常 (thường) + 规 (quy – quy tắc) → quy tắc thông thường, lệ thường; làm tính từ: thông thường. VD: 常规检查, 打破常规.","hsk_level":"7-9","tags":["danh-tu","tinh-tu"],"image":"📋","examples":[{"type":"basic","zh":"这是常规检查。","pinyin":"Zhè shì chángguī jiǎnchá.","vi":"Đây là kiểm tra thông thường."},{"type":"simple","zh":"医生建议她每年做一次血常规检查。","pinyin":"Yīshēng jiànyì tā měinián zuò yí cì xuèchángguī jiǎnchá.","vi":"Bác sĩ khuyên cô ấy mỗi năm làm xét nghiệm máu tổng quát một lần."},{"type":"compound","zh":"如果一直按常规办事，公司就很难有新的突破。","pinyin":"Rúguǒ yìzhí àn chángguī bànshì, gōngsī jiù hěn nán yǒu xīn de tūpò.","vi":"Nếu cứ làm việc theo lối thông thường thì công ty rất khó có đột phá mới."}],"related":[{"hanzi":"惯例","pinyin":"guànlì","vi":"thông lệ"},{"hanzi":"常规武器","pinyin":"chángguīwǔqì","vi":"vũ khí thông thường"},{"hanzi":"规则","pinyin":"guīzé","vi":"quy tắc"},{"hanzi":"破格","pinyin":"pògé","vi":"phá lệ"}],"traditional":"常規"},{"id":"偿命","hanzi":"偿命","pinyin":"chángmìng","meaning_vi":"đền mạng","explanation":"偿 (đền bù) + 命 (mạng sống).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"杀人要偿命。","pinyin":"Shārén yào chángmìng.","vi":"Giết người phải đền mạng."},{"type":"simple","zh":"古时候的法律规定故意杀人者必须偿命。","pinyin":"Gǔshíhou de fǎlǜ guīdìng gùyì shārén zhě bìxū chángmìng.","vi":"Luật pháp thời xưa quy định kẻ cố ý giết người phải đền mạng."},{"type":"compound","zh":"虽然凶手不用偿命，但是他将在监狱里度过余生。","pinyin":"Suīrán xiōngshǒu bú yòng chángmìng, dànshì tā jiāng zài jiānyù lǐ dùguò yúshēng.","vi":"Tuy hung thủ không phải đền mạng nhưng hắn sẽ phải sống nốt phần đời còn lại trong tù."}],"related":[{"hanzi":"抵命","pinyin":"dǐmìng","vi":"đền mạng"},{"hanzi":"杀人偿命","pinyin":"shārénchángmìng","vi":"giết người đền mạng"},{"hanzi":"偿还","pinyin":"chánghuán","vi":"hoàn trả"},{"hanzi":"赔偿","pinyin":"péicháng","vi":"bồi thường"}],"traditional":"償命"},{"id":"长篇大论","hanzi":"长篇大论","pinyin":"chángpiān-dàlùn","meaning_vi":"bài diễn thuyết/bài viết dài dòng","explanation":"长篇 (bài dài) + 大论 (luận lớn) → bài viết, bài nói dài dòng; thường mang ý chê dài mà nhạt, lan man.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"📜","examples":[{"type":"basic","zh":"他又在长篇大论。","pinyin":"Tā yòu zài chángpiāndàlùn.","vi":"Ông ta lại đang diễn thuyết dài dòng."},{"type":"simple","zh":"开会时领导一讲就是一个小时的长篇大论。","pinyin":"Kāihuì shí lǐngdǎo yì jiǎng jiùshì yí gè xiǎoshí de chángpiāndàlùn.","vi":"Lúc họp, lãnh đạo hễ nói là thao thao bất tuyệt cả tiếng đồng hồ."},{"type":"compound","zh":"与其写长篇大论，不如用三句话把重点说清楚。","pinyin":"Yǔqí xiě chángpiāndàlùn, bùrú yòng sān jù huà bǎ zhòngdiǎn shuō qīngchu.","vi":"Thay vì viết tràng giang đại hải, chi bằng dùng ba câu nói rõ trọng điểm."}],"related":[{"hanzi":"长篇累牍","pinyin":"chángpiānlěidú","vi":"dài dòng văn tự"},{"hanzi":"滔滔不绝","pinyin":"tāotāobùjué","vi":"thao thao bất tuyệt"},{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"lải nhải"},{"hanzi":"言简意赅","pinyin":"yánjiǎnyìgāi","vi":"ngắn gọn súc tích"}],"traditional":"長篇大論"},{"id":"常青树","hanzi":"常青树","pinyin":"chángqīngshù","meaning_vi":"cây thường xanh (người/tác phẩm có sức sống bền bỉ)","explanation":"常 (常) + 青 (màu xanh (xanh lá/xanh da trời/đen)) + 树 (xây dựng/cây cối).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","van-hoa"],"image":"🌲","examples":[{"type":"basic","zh":"他是乐坛常青树。","pinyin":"Tā shì yuètán chángqīngshù.","vi":"Ông ấy là cây đại thụ bền bỉ của làng nhạc."},{"type":"simple","zh":"这位六十岁的老演员被称为影坛常青树。","pinyin":"Zhè wèi liùshí suì de lǎo yǎnyuán bèi chēngwéi yǐngtán chángqīngshù.","vi":"Nam diễn viên sáu mươi tuổi này được mệnh danh là cây thường xanh của làng điện ảnh."},{"type":"compound","zh":"因为这首老歌旋律优美，所以几十年来一直是晚会上的常青树。","pinyin":"Yīnwèi zhè shǒu lǎogē xuánlǜ yōuměi, suǒyǐ jǐ shí niánlái yìzhí shì wǎnhuì shang de chángqīngshù.","vi":"Vì giai điệu đẹp nên mấy chục năm nay bài hát cũ này vẫn luôn là \"cây thường xanh\" trong các đêm diễn."}],"related":[{"hanzi":"长青","pinyin":"chángqīng","vi":"xanh mãi"},{"hanzi":"松柏","pinyin":"sōngbǎi","vi":"tùng bách"},{"hanzi":"万古长青","pinyin":"wàngǔchángqīng","vi":"trường tồn"},{"hanzi":"老将","pinyin":"lǎojiàng","vi":"lão tướng"}],"traditional":"常青樹"},{"id":"长盛不衰","hanzi":"长盛不衰","pinyin":"chángshèng-bùshuāi","meaning_vi":"hưng thịnh bền vững không suy tàn","explanation":"长盛 (thịnh vượng lâu dài) + 不衰 (không suy) → hưng thịnh mãi không suy tàn. VD: 这个品牌长盛不衰.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"这家老字号长盛不衰。","pinyin":"Zhè jiālǎo zìhao chángshèngbùshuāi.","vi":"Cửa hiệu lâu đời này hưng thịnh bền vững không suy."},{"type":"simple","zh":"京剧在这座城市里两百年来长盛不衰。","pinyin":"Jīngjù zài zhè zuò chéngshì lǐ liǎng bǎinián lái chángshèngbùshuāi.","vi":"Hai trăm năm nay kinh kịch vẫn thịnh hành không suy tàn ở thành phố này."},{"type":"compound","zh":"一个品牌只有不断创新，才能长盛不衰。","pinyin":"Yí gè pǐnpái zhǐyǒu búduàn chuàngxīn, cáinéng chángshèngbùshuāi.","vi":"Một thương hiệu chỉ khi không ngừng đổi mới thì mới có thể hưng thịnh bền lâu."}],"related":[{"hanzi":"经久不衰","pinyin":"jīngjiǔbùshuāi","vi":"bền lâu không suy"},{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"hưng thịnh"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"}],"traditional":"長盛不衰"},{"id":"长寿","hanzi":"长寿","pinyin":"chángshòu","meaning_vi":"sống lâu, trường thọ","explanation":"长 (dài) + 寿 (tuổi thọ).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🎂","examples":[{"type":"basic","zh":"祝您健康长寿。","pinyin":"Zhù nín jiànkāng chángshòu.","vi":"Chúc ông mạnh khỏe sống lâu."},{"type":"simple","zh":"这个海岛上的居民普遍长寿，百岁老人很多。","pinyin":"Zhè ge hǎidǎo shang de jūmín pǔbiàn chángshòu, bǎi suì lǎorén hěn duō.","vi":"Cư dân trên hòn đảo này phần lớn đều sống thọ, có rất nhiều cụ trăm tuổi."},{"type":"compound","zh":"如果能坚持清淡饮食和适量运动，就更有可能长寿。","pinyin":"Rúguǒ néng jiānchí qīngdàn yǐnshí hé shìliàng yùndòng, jiù gèng yǒukěnéng chángshòu.","vi":"Nếu có thể kiên trì ăn uống thanh đạm và vận động vừa phải thì càng có khả năng sống thọ."}],"related":[{"hanzi":"寿命","pinyin":"shòumìng","vi":"tuổi thọ"},{"hanzi":"长命百岁","pinyin":"chángmìngbǎisuì","vi":"sống lâu trăm tuổi"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"khỏe mạnh"},{"hanzi":"短命","pinyin":"duǎnmìng","vi":"chết yểu"}],"traditional":"長壽"},{"id":"常态化","hanzi":"常态化","pinyin":"chángtàihuà","meaning_vi":"bình thường hóa, duy trì thường xuyên","explanation":"常 (常) + 态 (trạng thái/thái độ) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🔄","examples":[{"type":"basic","zh":"检查已经常态化。","pinyin":"Jiǎnchá yǐjīng chángtàihuà.","vi":"Việc kiểm tra đã trở thành thường xuyên."},{"type":"simple","zh":"学校把消防演练常态化，每个月都练一次。","pinyin":"Xuéxiào bǎ xiāofáng yǎnliàn chángtàihuà, měi gèyuè dōu liàn yí cì.","vi":"Nhà trường duy trì diễn tập phòng cháy thường xuyên, tháng nào cũng tập một lần."},{"type":"compound","zh":"只有把垃圾分类常态化，环境才能得到真正改善。","pinyin":"Zhǐyǒu bǎ lājīfēnlèi chángtàihuà, huánjìng cáinéng dédào zhēnzhèng gǎishàn.","vi":"Chỉ khi phân loại rác trở thành việc làm thường xuyên thì môi trường mới thực sự được cải thiện."}],"related":[{"hanzi":"常态","pinyin":"chángtài","vi":"trạng thái bình thường"},{"hanzi":"制度化","pinyin":"zhìdùhuà","vi":"chế độ hóa"},{"hanzi":"日常","pinyin":"rìcháng","vi":"thường ngày"},{"hanzi":"正常化","pinyin":"zhèngchánghuà","vi":"bình thường hóa"}],"traditional":"常態化"},{"id":"长征","hanzi":"长征","pinyin":"chángzhēng","meaning_vi":"Trường Chinh (hành trình vĩ đại)","explanation":"长 (dài) + 征 (chinh phục/đặc trưng).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🚩","examples":[{"type":"basic","zh":"红军完成了长征。","pinyin":"Hóngjūn wánchéngle chángzhēng.","vi":"Hồng quân đã hoàn thành cuộc Trường chinh."},{"type":"simple","zh":"博物馆里展出了红军长征时穿过的草鞋。","pinyin":"Bówùguǎn lǐ zhǎnchūle Hóngjūn chángzhēng shí chuānguò de cǎoxié.","vi":"Trong bảo tàng trưng bày đôi dép cỏ Hồng quân từng đi trong cuộc Trường chinh."},{"type":"compound","zh":"虽然新药研发成功了，但是这只是万里长征的第一步。","pinyin":"Suīrán xīn yào yánfā chénggōng le, dànshì zhè zhǐshì wànlǐ chángzhēng de dìyībù.","vi":"Tuy đã nghiên cứu thành công thuốc mới nhưng đây mới chỉ là bước đầu tiên của chặng đường dài."}],"related":[{"hanzi":"红军","pinyin":"Hóngjūn","vi":"Hồng quân"},{"hanzi":"征程","pinyin":"zhēngchéng","vi":"chặng đường"},{"hanzi":"远征","pinyin":"yuǎnzhēng","vi":"viễn chinh"},{"hanzi":"万里长征","pinyin":"wànlǐchángzhēng","vi":"vạn lý trường chinh"}],"traditional":"長征"},{"id":"朝圣","hanzi":"朝圣","pinyin":"cháoshèng","meaning_vi":"hành hương","explanation":"朝 (hướng về) + 圣 (圣).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🕌","examples":[{"type":"basic","zh":"他们去西藏朝圣。","pinyin":"Tāmen qù Xīzàng cháoshèng.","vi":"Họ đi hành hương đến Tây Tạng."},{"type":"simple","zh":"每年都有成千上万的信徒徒步去拉萨朝圣。","pinyin":"Měinián dōu yǒu chéngqiānshàngwàn de xìntú túbù qù Lāsà cháoshèng.","vi":"Mỗi năm có hàng ngàn hàng vạn tín đồ đi bộ hành hương đến Lhasa."},{"type":"compound","zh":"对很多球迷来说，一到伦敦就要去这座球场朝圣。","pinyin":"Duì hěn duō qiúmí lái shuō, yí dào Lúndūn jiùyào qù zhè zuò qiúchǎng cháoshèng.","vi":"Với nhiều cổ động viên, hễ đến London là phải tới sân vận động này \"hành hương\"."}],"related":[{"hanzi":"朝拜","pinyin":"cháobài","vi":"triều bái"},{"hanzi":"圣地","pinyin":"shèngdì","vi":"thánh địa"},{"hanzi":"信徒","pinyin":"xìntú","vi":"tín đồ"},{"hanzi":"宗教","pinyin":"zōngjiào","vi":"tôn giáo"}],"traditional":"朝聖"},{"id":"彻头彻尾","hanzi":"彻头彻尾","pinyin":"chètóu-chèwěi","meaning_vi":"từ đầu đến cuối, hoàn toàn triệt để","explanation":"彻 (triệt – suốt) 头 (đầu) + 彻 尾 (vĩ – đuôi) → từ đầu đến đuôi; nghĩa: hoàn toàn, triệt để, thường mang nghĩa xấu: 彻头彻尾的骗局.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💯","examples":[{"type":"basic","zh":"这是彻头彻尾的谎言。","pinyin":"Zhè shì chètóuchèwěi de huǎngyán.","vi":"Đây là một lời nói dối hoàn toàn từ đầu đến cuối."},{"type":"simple","zh":"那份所谓的中奖通知是一场彻头彻尾的骗局。","pinyin":"Nà fèn suǒwèi de zhòngjiǎng tōngzhī shì yì chǎng chètóuchèwěi de piànjú.","vi":"Cái gọi là thông báo trúng thưởng đó là một trò lừa đảo trắng trợn từ đầu đến cuối."},{"type":"compound","zh":"虽然计划写得很漂亮，但是执行起来却是彻头彻尾的失败。","pinyin":"Suīrán jìhuà xiě de hěn piàoliang, dànshì zhíxíng qǐlái quèshì chètóuchèwěi de shībài.","vi":"Tuy kế hoạch được viết rất đẹp nhưng khi thực hiện lại là một thất bại hoàn toàn."}],"related":[{"hanzi":"彻底","pinyin":"chèdǐ","vi":"triệt để"},{"hanzi":"完全","pinyin":"wánquán","vi":"hoàn toàn"},{"hanzi":"十足","pinyin":"shízú","vi":"hoàn toàn mười phần"},{"hanzi":"从头到尾","pinyin":"cóngtóudàowěi","vi":"từ đầu đến cuối"}],"traditional":"徹頭徹尾"},{"id":"沉浮","hanzi":"沉浮","pinyin":"chénfú","meaning_vi":"chìm nổi, thăng trầm cuộc đời","explanation":"沉 (chìm) + 浮 (nổi).","hsk_level":"7-9","tags":["danh-tu","dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"他在商海沉浮多年。","pinyin":"Tā zài shāng hǎi chénfú duōnián.","vi":"Ông ấy đã chìm nổi trên thương trường nhiều năm."},{"type":"simple","zh":"这部小说讲述了一个家族百年的沉浮。","pinyin":"Zhè bù xiǎoshuō jiǎngshùle yí gè jiāzú bǎinián de chénfú.","vi":"Cuốn tiểu thuyết này kể về trăm năm thăng trầm của một gia tộc."},{"type":"compound","zh":"虽然这些年几经沉浮，但是他对音乐的热爱从来没有变过。","pinyin":"Suīrán zhèxiē nián jǐjīng chénfú, dànshì tā duì yīnyuè de rè'ài cónglái méiyǒu biàn guò.","vi":"Tuy mấy năm nay trải qua bao thăng trầm nhưng tình yêu âm nhạc của anh ấy chưa bao giờ thay đổi."}],"related":[{"hanzi":"起伏","pinyin":"qǐfú","vi":"lên xuống"},{"hanzi":"浮沉","pinyin":"fúchén","vi":"chìm nổi"},{"hanzi":"坎坷","pinyin":"kǎnkě","vi":"gập ghềnh"},{"hanzi":"风风雨雨","pinyin":"fēngfēngyǔyǔ","vi":"sóng gió"}]},{"id":"陈规陋习","hanzi":"陈规陋习","pinyin":"chénguī-lòuxí","meaning_vi":"hủ tục lạc hậu lỗi thời","explanation":"陈规 (quy tắc cũ) + 陋习 (thói quen xấu). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🚫","examples":[{"type":"basic","zh":"要破除陈规陋习。","pinyin":"Yào pòchú chénguīlòuxí.","vi":"Phải xóa bỏ những hủ tục lạc hậu."},{"type":"simple","zh":"村里废除了婚礼上大摆宴席的陈规陋习。","pinyin":"Cūnlǐ fèichúle hūnlǐ shang dà bǎi yànxí de chénguīlòuxí.","vi":"Làng đã bãi bỏ hủ tục bày tiệc linh đình trong đám cưới."},{"type":"compound","zh":"如果不改变这些陈规陋习，女孩子就很难有上学的机会。","pinyin":"Rúguǒ bù gǎibiàn zhèxiē chénguīlòuxí, nǚháizi jiù hěn nán yǒu shàngxué de jīhuì.","vi":"Nếu không thay đổi những hủ tục lỗi thời này thì các bé gái rất khó có cơ hội đi học."}],"related":[{"hanzi":"陋习","pinyin":"lòuxí","vi":"hủ tục"},{"hanzi":"陈腐","pinyin":"chénfǔ","vi":"cũ kỹ hủ bại"},{"hanzi":"恶习","pinyin":"èxí","vi":"thói xấu"},{"hanzi":"移风易俗","pinyin":"yífēngyìsú","vi":"thay đổi phong tục"}],"traditional":"陳規陋習"},{"id":"尘世","hanzi":"尘世","pinyin":"chénshì","meaning_vi":"trần thế, cõi đời","explanation":"尘 (bụi bặm) + 世 (thế giới/thế hệ).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🌍","examples":[{"type":"basic","zh":"他看破了尘世。","pinyin":"Tā kànpòle chénshì.","vi":"Ông ấy đã nhìn thấu cõi trần."},{"type":"simple","zh":"山顶的寺庙远离尘世的喧嚣。","pinyin":"Shāndǐng de sìmiào yuǎnlí chénshì de xuānxiāo.","vi":"Ngôi chùa trên đỉnh núi xa rời chốn ồn ào trần thế."},{"type":"compound","zh":"虽然他隐居深山，但是仍然关心着尘世间的冷暖。","pinyin":"Suīrán tā yǐnjū shēnshān, dànshì réngrán guānxīnzhe chénshì jiān de lěngnuǎn.","vi":"Tuy ẩn cư nơi núi sâu nhưng ông ấy vẫn quan tâm đến ấm lạnh của cõi đời."}],"related":[{"hanzi":"人间","pinyin":"rénjiān","vi":"nhân gian"},{"hanzi":"红尘","pinyin":"hóngchén","vi":"hồng trần"},{"hanzi":"世俗","pinyin":"shìsú","vi":"thế tục"},{"hanzi":"天堂","pinyin":"tiāntáng","vi":"thiên đường"}],"traditional":"塵世"},{"id":"沉痛","hanzi":"沉痛","pinyin":"chéntòng","meaning_vi":"đau xót sâu sắc","explanation":"沉 (chìm lắng) + 痛 (đau xót/quyết tâm).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"我们感到无比沉痛。","pinyin":"Wǒmen gǎndào wúbǐ chéntòng.","vi":"Chúng tôi vô cùng đau xót."},{"type":"simple","zh":"学校沉痛悼念在救火中牺牲的老校友。","pinyin":"Xuéxiào chéntòng dàoniàn zài jiùhuǒ zhōng xīshēng de lǎo xiàoyǒu.","vi":"Nhà trường bày tỏ niềm thương tiếc sâu sắc người cựu học sinh đã hy sinh khi chữa cháy."},{"type":"compound","zh":"这次事故虽然已经过去了，但是教训十分沉痛。","pinyin":"Zhè cì shìgù suīrán yǐjīng guòqù le, dànshì jiàoxùn shífēn chéntòng.","vi":"Vụ tai nạn này tuy đã qua nhưng bài học để lại vô cùng đau xót."}],"related":[{"hanzi":"悲痛","pinyin":"bēitòng","vi":"bi thương"},{"hanzi":"沉重","pinyin":"chénzhòng","vi":"nặng nề"},{"hanzi":"深切","pinyin":"shēnqiè","vi":"sâu sắc"},{"hanzi":"沉痛悼念","pinyin":"chéntòngdàoniàn","vi":"tưởng niệm đau xót"}]},{"id":"沉冤","hanzi":"沉冤","pinyin":"chényuān","meaning_vi":"nỗi oan khuất sâu nặng lâu năm","explanation":"沉 + 冤 (oan ức).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"沉冤终于昭雪。","pinyin":"Chényuān zhōngyú zhāoxuě.","vi":"Nỗi oan khuất bao năm cuối cùng đã được rửa sạch."},{"type":"simple","zh":"在狱中关了二十年后，他的沉冤才得以洗清。","pinyin":"Zài yù zhōng guānle èrshí nián hòu, tā de chényuān cái déyǐ xǐ qīng.","vi":"Sau hai mươi năm ngồi tù, nỗi oan sâu nặng của ông ấy mới được rửa sạch."},{"type":"compound","zh":"因为新证据出现了，所以这桩多年的沉冤终于得到了平反。","pinyin":"Yīnwèi xīn zhèngjù chūxiàn le, suǒyǐ zhè zhuāng duōnián de chényuān zhōngyú dédàole píngfǎn.","vi":"Vì có bằng chứng mới xuất hiện nên vụ oan khuất nhiều năm này cuối cùng đã được minh oan."}],"related":[{"hanzi":"冤屈","pinyin":"yuānqū","vi":"oan khuất"},{"hanzi":"昭雪","pinyin":"zhāoxuě","vi":"rửa oan"},{"hanzi":"冤案","pinyin":"yuān'àn","vi":"án oan"},{"hanzi":"冤枉","pinyin":"yuānwang","vi":"oan uổng"}]},{"id":"沉醉","hanzi":"沉醉","pinyin":"chénzuì","meaning_vi":"say đắm, đắm chìm","explanation":"沉 (chìm lắng) + 醉 (醉).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥰","examples":[{"type":"basic","zh":"游客沉醉于美景。","pinyin":"Yóukè chénzuì yú měijǐng.","vi":"Du khách say đắm trước cảnh đẹp."},{"type":"simple","zh":"台下的观众完全沉醉在她的琴声里。","pinyin":"Táixià de guānzhòng wánquán chénzuì zài tā de qín shēng lǐ.","vi":"Khán giả bên dưới hoàn toàn đắm chìm trong tiếng đàn của cô ấy."},{"type":"compound","zh":"他一沉醉在游戏里，就连饭都忘了吃。","pinyin":"Tā yì chénzuì zài yóuxì lǐ, jiù lián fàn dōu wàngle chī.","vi":"Hễ đắm chìm vào trò chơi là cậu ấy quên cả ăn cơm."}],"related":[{"hanzi":"陶醉","pinyin":"táozuì","vi":"say sưa"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"mê đắm"},{"hanzi":"沉浸","pinyin":"chénjìn","vi":"đắm chìm"},{"hanzi":"清醒","pinyin":"qīngxǐng","vi":"tỉnh táo"}]},{"id":"惩罚","hanzi":"惩罚","pinyin":"chéngfá","meaning_vi":"trừng phạt","explanation":"惩 (trừng – răn trị) + 罚 (phạt) → trừng phạt, xử phạt người có lỗi. VD: 受到惩罚; trái nghĩa 奖励.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他受到了惩罚。","pinyin":"Tā shòudàole chéngfá.","vi":"Anh ta đã bị trừng phạt."},{"type":"simple","zh":"法院对污染河流的工厂进行了严厉的惩罚。","pinyin":"Fǎyuàn duì wūrǎn héliú de gōngchǎng jìnxíngle yánlì de chéngfá.","vi":"Tòa án đã trừng phạt nghiêm khắc nhà máy gây ô nhiễm sông ngòi."},{"type":"compound","zh":"与其一味惩罚孩子，不如耐心告诉他错在哪里。","pinyin":"Yǔqí yíwèi chéngfá háizi, bùrú nàixīn gàosu tā cuò zài nǎlǐ.","vi":"Thay vì chỉ biết phạt con, chi bằng kiên nhẫn chỉ cho con biết sai ở đâu."}],"related":[{"hanzi":"处罚","pinyin":"chǔfá","vi":"xử phạt"},{"hanzi":"惩处","pinyin":"chéngchǔ","vi":"trừng trị"},{"hanzi":"奖励","pinyin":"jiǎnglì","vi":"khen thưởng"},{"hanzi":"惩戒","pinyin":"chéngjiè","vi":"răn đe trừng phạt"}],"traditional":"懲罰"},{"id":"成见","hanzi":"成见","pinyin":"chéngjiàn","meaning_vi":"thành kiến","explanation":"成 (thành – đã định hình) + 见 (kiến – cách nhìn) → cách nhìn đã định sẵn, thành kiến. VD: 对他有成见, 消除成见.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"他对我有成见。","pinyin":"Tā duì wǒ yǒu chéngjiàn.","vi":"Anh ta có thành kiến với tôi."},{"type":"simple","zh":"很多人对外卖员存在不公平的成见。","pinyin":"Hěn duō rén duì wàimàiyuán cúnzài bù gōngpíng de chéngjiàn.","vi":"Nhiều người có thành kiến không công bằng với nhân viên giao đồ ăn."},{"type":"compound","zh":"只要你放下成见，就会发现他其实是个很热心的人。","pinyin":"Zhǐyào nǐ fàngxià chéngjiàn, jiù huì fāxiàn tā qíshí shì gè hěn rèxīn de rén.","vi":"Chỉ cần bạn gác lại thành kiến thì sẽ thấy anh ấy thật ra là người rất nhiệt tình."}],"related":[{"hanzi":"偏见","pinyin":"piānjiàn","vi":"định kiến"},{"hanzi":"先入为主","pinyin":"xiānrùwéizhǔ","vi":"định kiến có sẵn"},{"hanzi":"看法","pinyin":"kànfǎ","vi":"quan điểm"},{"hanzi":"固执己见","pinyin":"gùzhíjǐjiàn","vi":"khư khư ý mình"}],"traditional":"成見"},{"id":"成就感","hanzi":"成就感","pinyin":"chéngjiùgǎn","meaning_vi":"cảm giác thành tựu","explanation":"成就 (thành tựu) + 感 (cảm – cảm giác) → cảm giác thành tựu, thỏa mãn khi làm được việc. VD: 很有成就感.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🏆","examples":[{"type":"basic","zh":"这份工作很有成就感。","pinyin":"Zhè fèn gōngzuò hěn yǒu chéngjiùgǎn.","vi":"Công việc này mang lại nhiều cảm giác thành tựu."},{"type":"simple","zh":"亲手做完一张书桌让他很有成就感。","pinyin":"Qīnshǒu zuòwán yì zhāng shūzhuō ràng tā hěn yǒu chéngjiùgǎn.","vi":"Tự tay đóng xong một chiếc bàn học khiến anh ấy rất có cảm giác thành tựu."},{"type":"compound","zh":"每当看到学生考上理想的大学，她就有一种强烈的成就感。","pinyin":"Měidāng kàndào xuésheng kǎoshàng lǐxiǎng de dàxué, tā jiù yǒu yì zhǒng qiángliè de chéngjiùgǎn.","vi":"Mỗi khi thấy học sinh đỗ vào trường đại học mơ ước, cô ấy lại có cảm giác thành tựu mạnh mẽ."}],"related":[{"hanzi":"成就","pinyin":"chéngjiù","vi":"thành tựu"},{"hanzi":"满足感","pinyin":"mǎnzúgǎn","vi":"cảm giác thỏa mãn"},{"hanzi":"自豪","pinyin":"zìháo","vi":"tự hào"},{"hanzi":"挫败感","pinyin":"cuòbàigǎn","vi":"cảm giác thất bại"}]},{"id":"承接","hanzi":"承接","pinyin":"chéngjiē","meaning_vi":"nhận (thầu, đặt hàng); nối tiếp (phần trước)","explanation":"承 (thừa – nhận, tiếp) + 接 (tiếp – đón, nối) → tiếp nhận (công trình, đơn hàng) hoặc nối tiếp phần trước. VD: 承接工程, 承上启下.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"本店承接婚宴。","pinyin":"Běn diàn chéngjiē hūnyàn.","vi":"Nhà hàng chúng tôi nhận đặt tiệc cưới."},{"type":"simple","zh":"这家装修公司专门承接老房子的翻新工程。","pinyin":"Zhè jiā zhuāngxiū gōngsī zhuānmén chéngjiē lǎo fángzi de fānxīn gōngchéng.","vi":"Công ty sửa chữa nhà này chuyên nhận công trình cải tạo nhà cũ."},{"type":"compound","zh":"这一段既承接了上文，又为后面的结局埋下了伏笔。","pinyin":"Zhè yí duàn jì chéngjiēle shàngwén, yòu wèi hòumiàn de jiéjú mái xiàle fúbǐ.","vi":"Đoạn này vừa nối tiếp phần trên, vừa cài cắm ẩn ý cho kết cục phía sau."}],"related":[{"hanzi":"接手","pinyin":"jiēshǒu","vi":"tiếp nhận"},{"hanzi":"承包","pinyin":"chéngbāo","vi":"nhận thầu"},{"hanzi":"衔接","pinyin":"xiánjiē","vi":"nối tiếp"},{"hanzi":"承上启下","pinyin":"chéngshàngqǐxià","vi":"nối trên tiếp dưới"}]},{"id":"承蒙","hanzi":"承蒙","pinyin":"chéngméng","meaning_vi":"nhờ có, đội ơn (kính ngữ)","explanation":"承 + 蒙 (nhận ơn). Cụm: 承蒙关照.","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"承蒙您的关照。","pinyin":"Chéngméng nín de guānzhào.","vi":"Nhờ có sự quan tâm giúp đỡ của ông."},{"type":"simple","zh":"承蒙各位老师多年指导，我才顺利完成了论文。","pinyin":"Chéngméng gèwèi lǎoshī duōnián zhǐdǎo, wǒ cái shùnlì wánchéngle lùnwén.","vi":"Nhờ ơn các thầy cô nhiều năm chỉ dẫn, tôi mới hoàn thành luận văn thuận lợi."},{"type":"compound","zh":"承蒙贵公司信任，我们一定会按时把货物送到。","pinyin":"Chéngméng guìgōngsī xìnrèn, wǒmen yídìng huì ànshí bǎ huòwù sòng dào.","vi":"Được quý công ty tin tưởng, chúng tôi nhất định sẽ giao hàng đúng hạn."}],"related":[{"hanzi":"承蒙关照","pinyin":"chéngméngguānzhào","vi":"được quan tâm giúp đỡ"},{"hanzi":"蒙","pinyin":"méng","vi":"được nhờ"},{"hanzi":"多谢","pinyin":"duōxiè","vi":"đa tạ"},{"hanzi":"感激","pinyin":"gǎnjī","vi":"cảm kích"}]},{"id":"成群结队","hanzi":"成群结队","pinyin":"chéngqún-jiéduì","meaning_vi":"từng đàn từng lũ, tụ tập thành nhóm đông","explanation":"成群 (thành bầy) + 结队 (kết đội – họp thành đội) → tụ tập thành đàn, thành từng tốp đông. VD: 游客成群结队.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👥","examples":[{"type":"basic","zh":"孩子们成群结队地放学回家。","pinyin":"Háizimen chéngqúnjiéduì de fàngxué huíjiā.","vi":"Bọn trẻ tan học kéo nhau từng tốp về nhà."},{"type":"simple","zh":"秋天一到，大雁成群结队地飞往南方。","pinyin":"Qiūtiān yí dào, dàyàn chéngqúnjiéduì de fēiwǎng nánfāng.","vi":"Mùa thu vừa đến, những đàn ngỗng trời từng bầy bay về phương nam."},{"type":"compound","zh":"一到周末，年轻人就成群结队地去郊外露营。","pinyin":"Yí dào zhōumò, niánqīngrén jiù chéngqúnjiéduì de qù jiāowài lùyíng.","vi":"Hễ đến cuối tuần, người trẻ lại kéo nhau từng nhóm ra ngoại ô cắm trại."}],"related":[{"hanzi":"三五成群","pinyin":"sānwǔchéngqún","vi":"tụm năm tụm ba"},{"hanzi":"结伴","pinyin":"jiébàn","vi":"kết bạn đồng hành"},{"hanzi":"成群","pinyin":"chéngqún","vi":"thành đàn"},{"hanzi":"单枪匹马","pinyin":"dānqiāngpǐmǎ","vi":"đơn thương độc mã"}],"traditional":"成群結隊"},{"id":"成瘾","hanzi":"成瘾","pinyin":"chéngyǐn","meaning_vi":"gây nghiện","explanation":"成 (thành – trở thành) + 瘾 (ẩn – nghiện) → thành nghiện, gây nghiện. VD: 玩游戏成瘾, 吸烟成瘾.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"⚠️","examples":[{"type":"basic","zh":"吸烟容易成瘾。","pinyin":"Xīyān róngyì chéngyǐn.","vi":"Hút thuốc dễ gây nghiện."},{"type":"simple","zh":"不少中学生对短视频已经成瘾了。","pinyin":"Bùshǎo zhōngxuéshēng duì duǎnshìpín yǐjīng chéngyǐn le.","vi":"Không ít học sinh trung học đã nghiện video ngắn."},{"type":"compound","zh":"一旦对止痛药成瘾，想要戒掉就非常困难。","pinyin":"Yídàn duì zhǐtòngyào chéngyǐn, xiǎngyào jièdiào jiù fēicháng kùnnan.","vi":"Một khi đã nghiện thuốc giảm đau thì muốn cai là vô cùng khó."}],"related":[{"hanzi":"上瘾","pinyin":"shàngyǐn","vi":"nghiện"},{"hanzi":"网瘾","pinyin":"wǎngyǐn","vi":"nghiện mạng"},{"hanzi":"戒瘾","pinyin":"jièyǐn","vi":"cai nghiện"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"mê mải"}],"traditional":"成癮"},{"id":"城镇化","hanzi":"城镇化","pinyin":"chéngzhènhuà","meaning_vi":"đô thị hóa","explanation":"城镇 (thành trấn – thành phố, thị trấn) + 化 (hóa – trở thành) → đô thị hóa, quá trình nông thôn chuyển thành đô thị. VD: 城镇化进程.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"城镇化发展很快。","pinyin":"Chéngzhènhuà fāzhǎn hěn kuài.","vi":"Đô thị hóa phát triển rất nhanh."},{"type":"simple","zh":"城镇化让很多农民搬进了县城的新楼房。","pinyin":"Chéngzhènhuà ràng hěn duō nóngmín bān jìnle xiànchéng de xīn lóufáng.","vi":"Đô thị hóa khiến nhiều nông dân chuyển vào sống trong những tòa nhà mới ở huyện lỵ."},{"type":"compound","zh":"随着城镇化加快，农村里留下的大多是老人和孩子。","pinyin":"Suízhe chéngzhènhuà jiākuài, nóngcūn lǐ liúxià de dàduō shì lǎorén hé háizi.","vi":"Cùng với tốc độ đô thị hóa tăng nhanh, những người ở lại nông thôn phần lớn là người già và trẻ em."}],"related":[{"hanzi":"城市化","pinyin":"chéngshìhuà","vi":"đô thị hóa"},{"hanzi":"城镇","pinyin":"chéngzhèn","vi":"thị trấn"},{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"现代化","pinyin":"xiàndàihuà","vi":"hiện đại hóa"}],"traditional":"城鎮化"},{"id":"赤诚","hanzi":"赤诚","pinyin":"chìchéng","meaning_vi":"chân thành tha thiết","explanation":"赤 (xích – đỏ, trần trụi, thuần khiết) + 诚 (thành – thành thật) → lòng chân thành trọn vẹn, son sắt. VD: 一片赤诚, 赤诚之心.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"他对朋友很赤诚。","pinyin":"Tā duì péngyou hěn chìchéng.","vi":"Anh ấy rất chân thành với bạn bè."},{"type":"simple","zh":"信里的每一句话都透着一片赤诚。","pinyin":"Xìn lǐ de měi yíjùhuà dōu tòuzhe yípiàn chìchéng.","vi":"Từng câu chữ trong thư đều toát lên tấm lòng son sắt chân thành."},{"type":"compound","zh":"虽然他不善言辞，但是那颗赤诚之心让大家很感动。","pinyin":"Suīrán tā búshàn yáncí, dànshì nà kē chìchéng zhī xīn ràng dàjiā hěn gǎndòng.","vi":"Tuy anh ấy không khéo ăn nói nhưng tấm lòng chân thành tha thiết ấy khiến mọi người rất cảm động."}],"related":[{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"赤胆忠心","pinyin":"chìdǎnzhōngxīn","vi":"trung thành son sắt"},{"hanzi":"赤子之心","pinyin":"chìzǐzhīxīn","vi":"tấm lòng son trẻ"},{"hanzi":"诚恳","pinyin":"chéngkěn","vi":"thành khẩn"}],"traditional":"赤誠"},{"id":"叱咤风云","hanzi":"叱咤风云","pinyin":"chìzhà-fēngyún","meaning_vi":"hô mưa gọi gió, làm chủ thời cuộc","explanation":"叱咤风云: một tiếng quát (叱咤) làm thay đổi cả gió mây (风云) → uy thế lớn, có sức ảnh hưởng xoay chuyển thời cuộc. Thường khen anh hùng, lãnh tụ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌪️","examples":[{"type":"basic","zh":"他曾叱咤风云。","pinyin":"Tā céng chìzhàfēngyún.","vi":"Ông ấy từng hô mưa gọi gió."},{"type":"simple","zh":"这位叱咤风云的商界大佬晚年过得很低调。","pinyin":"Zhè wèi chìzhàfēngyún de shāngjiè dàlǎo wǎnnián guòde hěn dīdiào.","vi":"Vị đại gia từng hô mưa gọi gió trên thương trường này về già sống rất kín tiếng."},{"type":"compound","zh":"虽然他当年在球场上叱咤风云，但是现在只是一名普通教练。","pinyin":"Suīrán tā dāngnián zài qiúchǎng shang chìzhàfēngyún, dànshì xiànzài zhǐshì yì míng pǔtōng jiàoliàn.","vi":"Tuy năm xưa anh ấy từng làm mưa làm gió trên sân bóng nhưng giờ chỉ là một huấn luyện viên bình thường."}],"related":[{"hanzi":"呼风唤雨","pinyin":"hūfēnghuànyǔ","vi":"hô mưa gọi gió"},{"hanzi":"威风凛凛","pinyin":"wēifēnglǐnlǐn","vi":"oai phong lẫm liệt"},{"hanzi":"风云人物","pinyin":"fēngyúnrénwù","vi":"nhân vật nổi bật"},{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"}],"traditional":"叱咤風雲"},{"id":"驰名","hanzi":"驰名","pinyin":"chímíng","meaning_vi":"nổi tiếng vang danh","explanation":"驰 (phi nhanh/vang danh) + 名 (danh tiếng/nổi tiếng).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"这里的瓷器驰名天下。","pinyin":"Zhèlǐ de cíqì chímíng tiānxià.","vi":"Đồ sứ nơi đây nổi tiếng khắp thiên hạ."},{"type":"simple","zh":"景德镇以出产精美的青花瓷而驰名。","pinyin":"Jǐngdézhèn yǐ chūchǎn jīngměi de qīnghuācí ér chímíng.","vi":"Cảnh Đức Trấn nổi tiếng nhờ sản xuất đồ sứ men lam tinh xảo."},{"type":"compound","zh":"因为这家烤鸭店驰名全城，所以每天门口都排着长队。","pinyin":"Yīnwèi zhè jiā kǎoyā diàn chímíng quánchéng, suǒyǐ měitiān ménkǒu dōu páizhe chángduì.","vi":"Vì tiệm vịt quay này nổi tiếng khắp thành phố nên ngày nào trước cửa cũng xếp hàng dài."}],"related":[{"hanzi":"闻名","pinyin":"wénmíng","vi":"nổi tiếng"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"trứ danh"},{"hanzi":"驰名中外","pinyin":"chímíngzhōngwài","vi":"nổi tiếng trong ngoài nước"},{"hanzi":"名扬四海","pinyin":"míngyángsìhǎi","vi":"danh tiếng khắp nơi"}],"traditional":"馳名"},{"id":"驰名中外","hanzi":"驰名中外","pinyin":"chímíng-zhōngwài","meaning_vi":"nổi tiếng trong và ngoài nước","explanation":"驰名 (vang danh) + 中外. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"西湖驰名中外。","pinyin":"Xīhú chímíngzhōngwài.","vi":"Tây Hồ nổi tiếng trong và ngoài nước."},{"type":"simple","zh":"这家驰名中外的老字号已经有三百年历史了。","pinyin":"Zhè jiā chímíngzhōngwài de lǎozìhao yǐjīng yǒu sān bǎinián lìshǐ le.","vi":"Cửa hiệu lâu đời nổi tiếng trong và ngoài nước này đã có lịch sử ba trăm năm."},{"type":"compound","zh":"龙井茶不但驰名中外，而且是招待外宾的首选礼物。","pinyin":"Lóngjǐngchá búdàn chímíngzhōngwài, érqiě shì zhāodài wàibīn de shǒuxuǎn lǐwù.","vi":"Trà Long Tỉnh không chỉ nổi tiếng trong và ngoài nước mà còn là món quà hàng đầu để tiếp đãi khách nước ngoài."}],"related":[{"hanzi":"闻名世界","pinyin":"wénmíngshìjiè","vi":"nổi tiếng thế giới"},{"hanzi":"驰名","pinyin":"chímíng","vi":"nổi tiếng"},{"hanzi":"举世闻名","pinyin":"jǔshìwénmíng","vi":"nổi tiếng khắp thế giới"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"}],"traditional":"馳名中外"},{"id":"臭氧层","hanzi":"臭氧层","pinyin":"chòuyǎngcéng","meaning_vi":"tầng ô-zôn","explanation":"臭氧 (xú dưỡng – khí ô-zôn, oxy có mùi hắc) + 层 (tầng) → tầng ô-zôn bảo vệ Trái Đất khỏi tia cực tím. VD: 臭氧层空洞.","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🛡️","examples":[{"type":"basic","zh":"臭氧层能挡住紫外线。","pinyin":"Chòuyǎngcéng néng dǎngzhù zǐwàixiàn.","vi":"Tầng ô-zôn có thể chắn tia tử ngoại."},{"type":"simple","zh":"科学家发现南极上空的臭氧层空洞正在缩小。","pinyin":"Kēxuéjiā fāxiàn nánjí shàngkōng de chòuyǎngcéng kōngdòng zhèngzài suōxiǎo.","vi":"Các nhà khoa học phát hiện lỗ thủng tầng ô-zôn trên bầu trời Nam Cực đang thu hẹp."},{"type":"compound","zh":"如果臭氧层遭到破坏，患皮肤癌的人就会增多。","pinyin":"Rúguǒ chòuyǎngcéng zāodào pòhuài, huàn pífū'ái de rén jiù huì zēngduō.","vi":"Nếu tầng ô-zôn bị phá hủy thì số người mắc ung thư da sẽ tăng lên."}],"related":[{"hanzi":"大气层","pinyin":"dàqìcéng","vi":"tầng khí quyển"},{"hanzi":"紫外线","pinyin":"zǐwàixiàn","vi":"tia cực tím"},{"hanzi":"臭氧","pinyin":"chòuyǎng","vi":"ô-zôn"},{"hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","vi":"hiệu ứng nhà kính"}],"traditional":"臭氧層"},{"id":"崇尚","hanzi":"崇尚","pinyin":"chóngshàng","meaning_vi":"tôn sùng, đề cao (giá trị/tinh thần)","explanation":"崇 (tôn sùng/cao cả) + 尚 (尚).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🌟","examples":[{"type":"basic","zh":"他崇尚简朴生活。","pinyin":"Tā chóngshàng jiǎnpǔ shēnghuó.","vi":"Anh ấy đề cao lối sống giản dị."},{"type":"simple","zh":"古代文人崇尚梅兰竹菊的高洁品格。","pinyin":"Gǔdài wénrén chóngshàng méi lán zhú jú de gāojié pǐngé.","vi":"Văn nhân thời xưa tôn sùng phẩm cách thanh cao của mai, lan, trúc, cúc."},{"type":"compound","zh":"因为这所学校崇尚自由探索，所以学生可以自己选择研究课题。","pinyin":"Yīnwèi zhè suǒ xuéxiào chóngshàng zìyóu tànsuǒ, suǒyǐ xuésheng kěyǐ zìjǐ xuǎnzé yánjiū kètí.","vi":"Vì ngôi trường này đề cao tinh thần tự do khám phá nên học sinh có thể tự chọn đề tài nghiên cứu."}],"related":[{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"推崇","pinyin":"tuīchóng","vi":"tôn sùng"},{"hanzi":"提倡","pinyin":"tíchàng","vi":"đề xướng"},{"hanzi":"尊崇","pinyin":"zūnchóng","vi":"tôn trọng"}]},{"id":"崇洋媚外","hanzi":"崇洋媚外","pinyin":"chóngyáng-mèiwài","meaning_vi":"sính ngoại, nịnh bợ nước ngoài","explanation":"崇 (sùng – tôn sùng) 洋 (dương – ngoại quốc) + 媚 (mị – nịnh) 外 (ngoại – nước ngoài) → sùng bái và xu nịnh nước ngoài, sính ngoại; nghĩa chê.","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"😒","examples":[{"type":"basic","zh":"不要崇洋媚外。","pinyin":"Bú yào chóngyángmèiwài.","vi":"Đừng sính ngoại."},{"type":"simple","zh":"有些商家故意起个洋名字来迎合崇洋媚外的心理。","pinyin":"Yǒuxiē shāngjiā gùyì qǐ gè yáng míngzi lái yínghé chóngyángmèiwài de xīnlǐ.","vi":"Một số cửa hàng cố tình đặt tên nước ngoài để chiều theo tâm lý sính ngoại."},{"type":"compound","zh":"学习外国的长处是好事，但是不能因此变得崇洋媚外。","pinyin":"Xuéxí wàiguó de chángchù shì hǎoshì, dànshì bù néng yīncǐ biànde chóngyángmèiwài.","vi":"Học hỏi điểm mạnh của nước ngoài là điều tốt nhưng không thể vì thế mà trở nên sính ngoại."}],"related":[{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"盲目","pinyin":"mángmù","vi":"mù quáng"},{"hanzi":"自卑","pinyin":"zìbēi","vi":"tự ti"},{"hanzi":"民族自豪感","pinyin":"mínzú zìháogǎn","vi":"lòng tự hào dân tộc"}]},{"id":"踌躇满志","hanzi":"踌躇满志","pinyin":"chóuchú-mǎnzhì","meaning_vi":"đắc ý hài lòng với thành tựu đạt được","explanation":"踌躇满志: đắc ý (踌躇 – vẻ thong dong tự đắc) và thỏa chí (满志) (từ Trang Tử) → rất hài lòng, đắc ý với thành công của mình.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😎","examples":[{"type":"basic","zh":"他显得踌躇满志。","pinyin":"Tā xiǎnde chóuchúmǎnzhì.","vi":"Anh ấy tỏ ra đầy tự tin và đắc ý."},{"type":"simple","zh":"新赛季开始前，年轻的主教练踌躇满志地接受了采访。","pinyin":"Xīn sàijì kāishǐ qián, niánqīng de zhǔ jiàoliàn chóuchúmǎnzhì de jiēshòule cǎifǎng.","vi":"Trước khi mùa giải mới bắt đầu, vị huấn luyện viên trưởng trẻ tuổi trả lời phỏng vấn với vẻ đầy tự tin."},{"type":"compound","zh":"刚拿到投资时他踌躇满志，可是半年后公司就陷入了困境。","pinyin":"Gāng nádào tóuzī shí tā chóuchúmǎnzhì, kěshì bàn nián hòu gōngsī jiù xiànrùle kùnjìng.","vi":"Lúc mới nhận được vốn đầu tư anh ấy đầy đắc ý, nhưng nửa năm sau công ty đã lâm vào khó khăn."}],"related":[{"hanzi":"得意洋洋","pinyin":"déyìyángyáng","vi":"đắc ý vênh váo"},{"hanzi":"意气风发","pinyin":"yìqìfēngfā","vi":"hăng hái phấn chấn"},{"hanzi":"志得意满","pinyin":"zhìdéyìmǎn","vi":"thỏa chí mãn nguyện"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"}],"traditional":"躊躇滿志"},{"id":"筹款","hanzi":"筹款","pinyin":"chóukuǎn","meaning_vi":"gây quỹ, quyên góp tiền","explanation":"筹 (trù bị/tính toán) + 款 (tiền/kiểu dáng/tiếp đãi).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"💰","examples":[{"type":"basic","zh":"他们在为灾区筹款。","pinyin":"Tāmen zài wèi zāiqū chóukuǎn.","vi":"Họ đang gây quỹ cho vùng thiên tai."},{"type":"simple","zh":"学生们通过义卖二手书为山区学校筹款。","pinyin":"Xuéshengmen tōngguò yìmài èr shǒushū wèi shānqū xuéxiào chóukuǎn.","vi":"Học sinh gây quỹ cho trường học vùng núi bằng cách bán sách cũ từ thiện."},{"type":"compound","zh":"只要筹款顺利，新图书馆明年春天就能开工。","pinyin":"Zhǐyào chóukuǎn shùnlì, xīn túshūguǎn míngnián chūntiān jiù néng kāigōng.","vi":"Chỉ cần gây quỹ thuận lợi thì thư viện mới có thể khởi công vào mùa xuân năm sau."}],"related":[{"hanzi":"筹资","pinyin":"chóuzī","vi":"huy động vốn"},{"hanzi":"募捐","pinyin":"mùjuān","vi":"quyên góp"},{"hanzi":"捐款","pinyin":"juānkuǎn","vi":"quyên tiền"},{"hanzi":"众筹","pinyin":"zhòngchóu","vi":"gọi vốn cộng đồng"}],"traditional":"籌款"},{"id":"触动","hanzi":"触动","pinyin":"chùdòng","meaning_vi":"chạm tới, làm xúc động","explanation":"触 (tiếp xúc/chạm) + 动 (动).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"这件事触动了我。","pinyin":"Zhè jiàn shì chùdòngle wǒ.","vi":"Chuyện này đã làm tôi xúc động."},{"type":"simple","zh":"老兵的一番话深深触动了在场的每一位学生。","pinyin":"Lǎobīng de yìfān huà shēnshēn chùdòngle zài chǎng de měi yí wèi xuésheng.","vi":"Lời nói của người cựu binh đã chạm sâu vào lòng từng học sinh có mặt."},{"type":"compound","zh":"因为这项改革触动了一些人的利益，所以推行起来阻力很大。","pinyin":"Yīnwèi zhè xiàng gǎigé chùdòngle yìxiē rén de lìyì, suǒyǐ tuīxíng qǐlái zǔlì hěn dà.","vi":"Vì cải cách này động chạm đến lợi ích của một số người nên khi triển khai gặp rất nhiều trở ngại."}],"related":[{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"打动","pinyin":"dǎdòng","vi":"lay động"},{"hanzi":"触及","pinyin":"chùjí","vi":"chạm tới"},{"hanzi":"震撼","pinyin":"zhènhàn","vi":"chấn động"}],"traditional":"觸動"},{"id":"触觉","hanzi":"触觉","pinyin":"chùjué","meaning_vi":"xúc giác","explanation":"触 (tiếp xúc/chạm) + 觉 (giác ngộ/cảm nhận).","hsk_level":"7-9","tags":["danh-tu","co-the","khoa-hoc"],"image":"🤚","examples":[{"type":"basic","zh":"盲人的触觉很灵敏。","pinyin":"Mángrén de chùjué hěn língmǐn.","vi":"Xúc giác của người khiếm thị rất nhạy."},{"type":"simple","zh":"婴儿主要通过触觉来认识周围的世界。","pinyin":"Yīng'ér zhǔyào tōngguò chùjué lái rènshi zhōuwéi de shìjiè.","vi":"Trẻ sơ sinh chủ yếu nhận biết thế giới xung quanh thông qua xúc giác."},{"type":"compound","zh":"虽然这只机器人没有眼睛，但是它的触觉传感器非常发达。","pinyin":"Suīrán zhè zhī jīqìrén méiyǒu yǎnjing, dànshì tā de chùjué chuángǎnqì fēicháng fādá.","vi":"Tuy con robot này không có mắt nhưng cảm biến xúc giác của nó rất phát triển."}],"related":[{"hanzi":"视觉","pinyin":"shìjué","vi":"thị giác"},{"hanzi":"听觉","pinyin":"tīngjué","vi":"thính giác"},{"hanzi":"嗅觉","pinyin":"xiùjué","vi":"khứu giác"},{"hanzi":"感觉","pinyin":"gǎnjué","vi":"cảm giác"}],"traditional":"觸覺"},{"id":"除暴安良","hanzi":"除暴安良","pinyin":"chúbào-ānliáng","meaning_vi":"trừ gian diệt bạo bảo vệ dân lành","explanation":"除暴安良: trừ (除) kẻ hung bạo (暴), làm yên (安) người lương thiện (良) → diệt kẻ ác, bảo vệ dân lành. Thường tả hiệp sĩ, quan thanh liêm.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦸","examples":[{"type":"basic","zh":"他一心想除暴安良。","pinyin":"Tā yìxīn xiǎng chúbào'ānliáng.","vi":"Anh ấy một lòng muốn trừ bạo an dân."},{"type":"simple","zh":"小说里的侠客总是四处除暴安良。","pinyin":"Xiǎoshuō lǐ de xiákè zǒngshì sìchù chúbào'ānliáng.","vi":"Hiệp khách trong tiểu thuyết luôn đi khắp nơi trừ gian diệt bạo, bảo vệ dân lành."},{"type":"compound","zh":"虽然他只是个小警察，但是一直把除暴安良当作人生目标。","pinyin":"Suīrán tā zhǐshì gè xiǎo jǐngchá, dànshì yìzhí bǎ chúbào'ānliáng dàngzuò rénshēng mùbiāo.","vi":"Tuy anh ấy chỉ là một cảnh sát nhỏ, nhưng luôn coi việc trừ bạo an dân là mục tiêu cuộc đời."}],"related":[{"hanzi":"惩恶扬善","pinyin":"chéng'èyángshàn","vi":"trừng ác dương thiện"},{"hanzi":"行侠仗义","pinyin":"xíngxiázhàngyì","vi":"hành hiệp trượng nghĩa"},{"hanzi":"正义","pinyin":"zhèngyì","vi":"chính nghĩa"},{"hanzi":"恶霸","pinyin":"èbà","vi":"cường hào ác bá"}]},{"id":"除夕夜","hanzi":"除夕夜","pinyin":"chúxīyè","meaning_vi":"đêm giao thừa","explanation":"除 (trừ đi) + 夕 (夕) + 夜 (ban đêm).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🧨","examples":[{"type":"basic","zh":"除夕夜全家团圆。","pinyin":"Chúxīyè quánjiā tuányuán.","vi":"Đêm giao thừa cả nhà đoàn tụ."},{"type":"simple","zh":"除夕夜我们围在桌边包了三百个饺子。","pinyin":"Chúxīyè wǒmen wéi zài zhuō biān bāole sān bǎi gè jiǎozi.","vi":"Đêm giao thừa chúng tôi quây quanh bàn gói ba trăm cái sủi cảo."},{"type":"compound","zh":"因为今年要在国外加班，所以他只能在视频里陪父母过除夕夜。","pinyin":"Yīnwèi jīnnián yào zài guówài jiābān, suǒyǐ tā zhǐnéng zài shìpín lǐ péi fùmǔguò chúxīyè.","vi":"Vì năm nay phải tăng ca ở nước ngoài nên anh ấy chỉ có thể đón đêm giao thừa cùng bố mẹ qua video."}],"related":[{"hanzi":"除夕","pinyin":"Chúxī","vi":"giao thừa"},{"hanzi":"年夜饭","pinyin":"niányèfàn","vi":"bữa cơm tất niên"},{"hanzi":"守岁","pinyin":"shǒusuì","vi":"đón giao thừa"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết"}]},{"id":"纯朴","hanzi":"纯朴","pinyin":"chúnpǔ","meaning_vi":"thuần phác, mộc mạc chân chất","explanation":"纯 (thuần khiết) + 朴 (chất phác/giản dị).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"山里人很纯朴。","pinyin":"Shān lǐrén hěn chúnpǔ.","vi":"Người miền núi rất chân chất."},{"type":"simple","zh":"这个小渔村保留着纯朴的民风。","pinyin":"Zhè ge xiǎo yú cūn bǎoliúzhe chúnpǔ de mínfēng.","vi":"Làng chài nhỏ này vẫn giữ được phong tục chân chất mộc mạc."},{"type":"compound","zh":"虽然村民们并不富裕，但是他们纯朴热情，让游客感到很温暖。","pinyin":"Suīrán cūnmínmen bìngbú fùyù, dànshì tāmen chúnpǔ rèqíng, ràng yóukè gǎndào hěn wēnnuǎn.","vi":"Tuy dân làng không hề giàu có nhưng họ chân chất, nhiệt tình, khiến du khách cảm thấy rất ấm áp."}],"related":[{"hanzi":"朴实","pinyin":"pǔshí","vi":"chất phác"},{"hanzi":"淳朴","pinyin":"chúnpǔ","vi":"thuần hậu"},{"hanzi":"质朴","pinyin":"zhìpǔ","vi":"mộc mạc"},{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"}],"traditional":"純樸"},{"id":"唇枪舌剑","hanzi":"唇枪舌剑","pinyin":"chúnqiāng-shéjiàn","meaning_vi":"khẩu chiến sắc bén như gươm đao","explanation":"唇 (thần – môi) 枪 (thương – giáo) + 舌 (thiệt – lưỡi) 剑 (kiếm) → môi như giáo, lưỡi như gươm; ví tranh luận gay gắt, khẩu chiến sắc bén.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"⚔️","examples":[{"type":"basic","zh":"双方唇枪舌剑，互不相让。","pinyin":"Shuāngfāng chúnqiāngshéjiàn, hù bù xiāng ràng.","vi":"Hai bên đấu khẩu gay gắt, không ai nhường ai."},{"type":"simple","zh":"辩论赛上两位选手唇枪舌剑地争论了半个小时。","pinyin":"Biànlùnsài shàng liǎng wèi xuǎnshǒu chúnqiāngshéjiàn de zhēnglùnle bàn gè xiǎoshí.","vi":"Tại cuộc thi hùng biện, hai thí sinh đã khẩu chiến nảy lửa suốt nửa tiếng."},{"type":"compound","zh":"会上两人唇枪舌剑，可是散会后又一起去吃了午饭。","pinyin":"Huì shàng liǎng rén chúnqiāngshéjiàn, kěshì sànhuì hòu yòu yìqǐ qù chīle wǔfàn.","vi":"Trong cuộc họp hai người khẩu chiến kịch liệt, nhưng tan họp lại cùng nhau đi ăn trưa."}],"related":[{"hanzi":"针锋相对","pinyin":"zhēnfēngxiāngduì","vi":"ăn miếng trả miếng"},{"hanzi":"争论","pinyin":"zhēnglùn","vi":"tranh luận"},{"hanzi":"辩论","pinyin":"biànlùn","vi":"tranh biện"},{"hanzi":"舌战","pinyin":"shézhàn","vi":"khẩu chiến"}],"traditional":"唇槍舌劍"},{"id":"纯真","hanzi":"纯真","pinyin":"chúnzhēn","meaning_vi":"thuần khiết ngây thơ","explanation":"纯 (thuần khiết) + 真 (thật).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🌸","examples":[{"type":"basic","zh":"孩子的笑容很纯真。","pinyin":"Háizi de xiàoróng hěn chúnzhēn.","vi":"Nụ cười của đứa trẻ rất ngây thơ trong sáng."},{"type":"simple","zh":"这本日记记录了她纯真的少女时代。","pinyin":"Zhè běn rìjì jìlùle tā chúnzhēn de shàonǚ shídài.","vi":"Cuốn nhật ký này ghi lại thời thiếu nữ ngây thơ trong sáng của cô ấy."},{"type":"compound","zh":"即使经历了许多挫折，他依然保持着一颗纯真的心。","pinyin":"Jíshǐ jīnglìle xǔduō cuòzhé, tā yīrán bǎochízhe yì kē chúnzhēn de xīn.","vi":"Dù đã trải qua nhiều thất bại, anh ấy vẫn giữ được một trái tim thuần khiết."}],"related":[{"hanzi":"天真","pinyin":"tiānzhēn","vi":"ngây thơ"},{"hanzi":"纯洁","pinyin":"chúnjié","vi":"trong sáng"},{"hanzi":"单纯","pinyin":"dānchún","vi":"đơn thuần"},{"hanzi":"世故","pinyin":"shìgù","vi":"từng trải khôn đời"}],"traditional":"純真"},{"id":"拆迁","hanzi":"拆迁","pinyin":"chāiqiān","meaning_vi":"giải tỏa, di dời nhà cửa để xây dựng","explanation":"拆 (phá dỡ) + 迁 (di dời).","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏗️","examples":[{"type":"basic","zh":"这条老街要拆迁了。","pinyin":"Zhè tiáo lǎojiē yào chāiqiān le.","vi":"Con phố cũ này sắp bị giải tỏa rồi."},{"type":"simple","zh":"政府给每户拆迁居民发放了补偿款。","pinyin":"Zhèngfǔ gěi měi hù chāiqiān jūmín fāfàngle bǔcháng kuǎn.","vi":"Chính phủ đã phát tiền bồi thường cho từng hộ dân bị giải tỏa."},{"type":"compound","zh":"如果拆迁补偿不合理，居民就很难同意搬走。","pinyin":"Rúguǒ chāiqiān bǔcháng bù hélǐ, jūmín jiù hěn nán tóngyì bānzǒu.","vi":"Nếu tiền bồi thường giải tỏa không hợp lý thì người dân sẽ khó đồng ý dọn đi."}],"related":[{"hanzi":"拆除","pinyin":"chāichú","vi":"dỡ bỏ"},{"hanzi":"搬迁","pinyin":"bānqiān","vi":"di dời"},{"hanzi":"钉子户","pinyin":"dìngzihù","vi":"hộ bám trụ"},{"hanzi":"补偿","pinyin":"bǔcháng","vi":"đền bù"}],"traditional":"拆遷"},{"id":"超负荷","hanzi":"超负荷","pinyin":"chāofùhè","meaning_vi":"quá tải","explanation":"超 (超) + 负 (负) + 荷 (gánh vác/hoa sen).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"⚠️","examples":[{"type":"basic","zh":"机器超负荷运转。","pinyin":"Jīqì chāofùhè yùnzhuǎn.","vi":"Máy móc vận hành quá tải."},{"type":"simple","zh":"春运期间铁路系统一直处于超负荷状态。","pinyin":"Chūnyùn qījiān tiělù xìtǒng yīzhí chǔyú chāofùhè zhuàngtài.","vi":"Trong mùa cao điểm đi lại dịp Tết, hệ thống đường sắt luôn ở trạng thái quá tải."},{"type":"compound","zh":"因为他连续一个月超负荷工作，所以最后累得住进了医院。","pinyin":"Yīnwèi tā liánxù yí gèyuè chāofùhè gōngzuò, suǒyǐ zuìhòu lèi de zhù jìnle yīyuàn.","vi":"Vì làm việc quá sức suốt một tháng liền nên cuối cùng anh ấy kiệt sức phải nhập viện."}],"related":[{"hanzi":"负荷","pinyin":"fùhè","vi":"tải trọng"},{"hanzi":"超载","pinyin":"chāozài","vi":"quá tải"},{"hanzi":"疲劳","pinyin":"píláo","vi":"mệt mỏi"},{"hanzi":"负担","pinyin":"fùdān","vi":"gánh nặng"}],"traditional":"超負荷"},{"id":"超脱","hanzi":"超脱","pinyin":"chāotuō","meaning_vi":"siêu thoát, thoát tục, không vướng bận lợi danh","explanation":"超 (vượt) + 脱 (thoát khỏi).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"他的心态很超脱。","pinyin":"Tā de xīntài hěn chāotuō.","vi":"Tâm thế của anh ấy rất siêu thoát."},{"type":"simple","zh":"退休后的爷爷对名利看得越来越超脱。","pinyin":"Tuìxiū hòu de yéye duì mínglì kàn de yuèláiyuè chāotuō.","vi":"Sau khi nghỉ hưu, ông nội ngày càng coi nhẹ danh lợi."},{"type":"compound","zh":"与其为小事斤斤计较，不如超脱一点，过得轻松些。","pinyin":"Yǔqí wèi xiǎoshì jīnjīnjìjiào, bùrú chāotuō yìdiǎn, guòde qīngsōng xiē.","vi":"Thay vì so đo tính toán vì chuyện nhỏ, chi bằng thoáng ra một chút để sống nhẹ nhàng hơn."}],"related":[{"hanzi":"洒脱","pinyin":"sǎtuō","vi":"phóng khoáng"},{"hanzi":"淡泊名利","pinyin":"dànbómínglì","vi":"xem nhẹ danh lợi"},{"hanzi":"超然","pinyin":"chāorán","vi":"siêu nhiên thoát tục"},{"hanzi":"世俗","pinyin":"shìsú","vi":"thế tục"}],"traditional":"超脫"},{"id":"超自然","hanzi":"超自然","pinyin":"chāozìrán","meaning_vi":"siêu nhiên","explanation":"超 (超) + 自 (tự chủ/tự hào) + 然 (然).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🔮","examples":[{"type":"basic","zh":"他不相信超自然力量。","pinyin":"Tā bù xiāngxìn chāozìrán lìliàng.","vi":"Anh ấy không tin vào sức mạnh siêu nhiên."},{"type":"simple","zh":"这部电影讲述了一个超自然的古堡故事。","pinyin":"Zhè bù diànyǐng jiǎngshùle yí gè chāozìrán de gǔbǎo gùshi.","vi":"Bộ phim này kể một câu chuyện siêu nhiên về tòa lâu đài cổ."},{"type":"compound","zh":"古人看到日食会感到恐慌，因为他们以为那是超自然现象。","pinyin":"Gǔrén kàndào rìshí huì gǎndào kǒnghuāng, yīnwèi tāmen yǐwéi nàshì chāozìrán xiànxiàng.","vi":"Người xưa thấy nhật thực thì hoảng sợ, vì họ tưởng đó là hiện tượng siêu nhiên."}],"related":[{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"},{"hanzi":"灵异","pinyin":"língyì","vi":"linh dị"},{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"鬼神","pinyin":"guǐshén","vi":"quỷ thần"}]},{"id":"称道","hanzi":"称道","pinyin":"chēngdào","meaning_vi":"ca ngợi, khen ngợi","explanation":"称 (khen) + 道 (nói).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"他的人品值得称道。","pinyin":"Tā de rénpǐn zhíde chēngdào.","vi":"Nhân phẩm của anh ấy đáng được ca ngợi."},{"type":"simple","zh":"这家医院的服务态度一直为患者所称道。","pinyin":"Zhè jiā yīyuàn de fúwù tàidù yìzhí wéi huànzhě suǒ chēngdào.","vi":"Thái độ phục vụ của bệnh viện này luôn được bệnh nhân khen ngợi."},{"type":"compound","zh":"他不但医术高明，而且从不收红包，这一点尤其令人称道。","pinyin":"Tā búdàn yīshù gāomíng, érqiě cóng bù shōu hóngbāo, zhè yìdiǎn yóuqí lìngrén chēngdào.","vi":"Ông ấy không những y thuật cao minh mà còn chưa bao giờ nhận phong bì, điểm này đặc biệt đáng khen ngợi."}],"related":[{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"赞扬","pinyin":"zànyáng","vi":"tán dương"},{"hanzi":"夸奖","pinyin":"kuājiǎng","vi":"khen"},{"hanzi":"值得称道","pinyin":"zhídechēngdào","vi":"đáng khen ngợi"}],"traditional":"稱道"},{"id":"称职","hanzi":"称职","pinyin":"chènzhí","meaning_vi":"xứng đáng với chức vụ, làm tròn trách nhiệm","explanation":"称 (gọi là) + 职 (chức vụ/nghề nghiệp).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"她是个称职的老师。","pinyin":"Tā shì gè chènzhí de lǎoshī.","vi":"Cô ấy là một giáo viên làm tròn trách nhiệm."},{"type":"simple","zh":"新来的经理在半年内就证明了自己很称职。","pinyin":"Xīn lái de jīnglǐ zài bàn niánnèi jiù zhèngmíngle zìjǐ hěn chènzhí.","vi":"Người quản lý mới chỉ trong nửa năm đã chứng minh mình rất xứng đáng với chức vụ."},{"type":"compound","zh":"如果连基本的数据都算不清，他就算不上称职的会计。","pinyin":"Rúguǒ lián jīběn de shùjù dōu suàn buqīng, tā jiù suànbushàng chènzhí de kuàijì.","vi":"Nếu đến số liệu cơ bản cũng tính không rõ thì anh ta chẳng thể coi là một kế toán xứng chức."}],"related":[{"hanzi":"胜任","pinyin":"shèngrèn","vi":"đảm đương được"},{"hanzi":"尽职","pinyin":"jìnzhí","vi":"tận chức"},{"hanzi":"不称职","pinyin":"búchènzhí","vi":"không xứng chức"},{"hanzi":"合格","pinyin":"hégé","vi":"đạt chuẩn"}],"traditional":"稱職"},{"id":"吃荤","hanzi":"吃荤","pinyin":"chīhūn","meaning_vi":"ăn mặn (có thịt cá)","explanation":"吃 (ăn) + 荤 (đồ ăn mặn).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍖","examples":[{"type":"basic","zh":"奶奶从不吃荤。","pinyin":"Nǎinai cóng bù chīhūn.","vi":"Bà nội chưa bao giờ ăn mặn."},{"type":"simple","zh":"寺庙里的僧人平时一律不吃荤。","pinyin":"Sìmiào lǐ de sēngrén píngshí yílǜ bù chīhūn.","vi":"Các nhà sư trong chùa thường ngày đều không ăn mặn."},{"type":"compound","zh":"他平时吃素，只有过年的时候才吃荤。","pinyin":"Tā píngshí chīsù, zhǐyǒu guònián de shíhou cái chīhūn.","vi":"Bình thường anh ấy ăn chay, chỉ đến Tết mới ăn mặn."}],"related":[{"hanzi":"吃素","pinyin":"chīsù","vi":"ăn chay"},{"hanzi":"荤菜","pinyin":"hūncài","vi":"món mặn"},{"hanzi":"肉","pinyin":"ròu","vi":"thịt"},{"hanzi":"素食","pinyin":"sùshí","vi":"đồ chay"}],"traditional":"吃葷"},{"id":"吃里扒外","hanzi":"吃里扒外","pinyin":"chīlǐ-páwài","meaning_vi":"ăn cây táo rào cây sung (phản bội tập thể mình)","explanation":"吃里扒外: ăn (吃) của bên trong (里), vơ vét (扒) cho bên ngoài (外) → hưởng lợi của tập thể mình mà lại làm lợi cho người ngoài; tương đương \"ăn cây táo rào cây sung\".","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐍","examples":[{"type":"basic","zh":"他竟然吃里扒外！","pinyin":"Tā jìngrán chīlǐpáwài!","vi":"Hắn lại dám ăn cây táo rào cây sung!"},{"type":"simple","zh":"那个员工吃里扒外，把客户名单卖给了对手公司。","pinyin":"Nà ge yuángōng chīlǐpáwài, bǎ kèhù míngdān mài gěile duìshǒu gōngsī.","vi":"Nhân viên đó ăn cây táo rào cây sung, bán danh sách khách hàng cho công ty đối thủ."},{"type":"compound","zh":"虽然老板一向待他不薄，但是他却吃里扒外，偷偷泄露机密。","pinyin":"Suīrán lǎobǎn yíxiàng dài tā bù báo, dànshì tā què chīlǐpáwài, tōutōu xièlòu jīmì.","vi":"Tuy ông chủ luôn đối xử tốt với anh ta, nhưng anh ta lại ăn cây táo rào cây sung, lén tiết lộ bí mật."}],"related":[{"hanzi":"背叛","pinyin":"bèipàn","vi":"phản bội"},{"hanzi":"内奸","pinyin":"nèijiān","vi":"nội gián"},{"hanzi":"出卖","pinyin":"chūmài","vi":"bán đứng"},{"hanzi":"忘恩负义","pinyin":"wàng'ēnfùyì","vi":"vong ơn bội nghĩa"}],"traditional":"吃裡扒外"},{"id":"吃素","hanzi":"吃素","pinyin":"chīsù","meaning_vi":"ăn chay","explanation":"吃 (ăn) + 素 (tố chất/vốn dĩ).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🥗","examples":[{"type":"basic","zh":"我妈妈每月初一吃素。","pinyin":"Wǒ māma měiyuè chūyī chīsù.","vi":"Mẹ tôi ăn chay vào mùng một hằng tháng."},{"type":"simple","zh":"越来越多的年轻人为了健康选择吃素。","pinyin":"Yuèláiyuè duō de niánqīngrén wèile jiànkāng xuǎnzé chīsù.","vi":"Ngày càng nhiều người trẻ chọn ăn chay vì sức khỏe."},{"type":"compound","zh":"虽然他已经吃素三年了，但是偶尔还是会想念红烧肉。","pinyin":"Suīrán tā yǐjīng chīsù sān nián le, dànshì ǒu'ěr háishì huì xiǎngniàn hóngshāoròu.","vi":"Tuy đã ăn chay ba năm rồi, nhưng thỉnh thoảng anh ấy vẫn nhớ món thịt kho tàu."}],"related":[{"hanzi":"吃荤","pinyin":"chīhūn","vi":"ăn mặn"},{"hanzi":"素食","pinyin":"sùshí","vi":"đồ chay"},{"hanzi":"素食者","pinyin":"sùshízhě","vi":"người ăn chay"},{"hanzi":"斋戒","pinyin":"zhāijiè","vi":"trai giới"}]},{"id":"冲动消费","hanzi":"冲动消费","pinyin":"chōngdòngxiāofèi","meaning_vi":"mua sắm bốc đồng","explanation":"冲动 (xung động – bốc đồng) + 消费 (tiêu phí – tiêu dùng) → mua sắm theo cảm hứng nhất thời, không có kế hoạch; trái với 理性消费.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"💳","examples":[{"type":"basic","zh":"别再冲动消费了。","pinyin":"Bié zài chōngdòngxiāofèi le.","vi":"Đừng mua sắm bốc đồng nữa."},{"type":"simple","zh":"双十一的打折广告很容易引发冲动消费。","pinyin":"Shuāngshíyī de dǎzhé guǎnggào hěn róngyì yǐnfā chōngdòngxiāofèi.","vi":"Quảng cáo giảm giá ngày 11 tháng 11 rất dễ gây ra mua sắm bốc đồng."},{"type":"compound","zh":"只要把购物车里的东西放一晚再决定，就能减少冲动消费。","pinyin":"Zhǐyào bǎ gòuwùchē lǐ de dōngxi fàng yì wǎn zài juédìng, jiù néng jiǎnshǎo chōngdòngxiāofèi.","vi":"Chỉ cần để đồ trong giỏ hàng qua một đêm rồi mới quyết định là có thể giảm bớt mua sắm bốc đồng."}],"related":[{"hanzi":"冲动","pinyin":"chōngdòng","vi":"bốc đồng"},{"hanzi":"理性消费","pinyin":"lǐxìngxiāofèi","vi":"tiêu dùng lý trí"},{"hanzi":"剁手","pinyin":"duòshǒu","vi":"nghiện mua sắm"},{"hanzi":"购物","pinyin":"gòuwù","vi":"mua sắm"}],"traditional":"衝動消費"},{"id":"冲刷","hanzi":"冲刷","pinyin":"chōngshuā","meaning_vi":"xói mòn, rửa trôi","explanation":"冲 (xông lên) + 刷 (刷).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"海浪冲刷着礁石。","pinyin":"Hǎilàng chōngshuāzhe jiāoshí.","vi":"Sóng biển xói mòn những tảng đá ngầm."},{"type":"simple","zh":"连日暴雨把山坡上的泥土冲刷得干干净净。","pinyin":"Liánrì bàoyǔ bǎ shānpō shàng de nítǔ chōngshuā de gān gānjìng jìng.","vi":"Mưa lớn liên tiếp đã rửa trôi sạch đất trên sườn núi."},{"type":"compound","zh":"如果河岸不种树，泥沙就会被河水不断冲刷下去。","pinyin":"Rúguǒ hé'àn bú zhòngshù, níshā jiù huì bèi héshuǐ búduàn chōngshuā xiàqù.","vi":"Nếu bờ sông không trồng cây thì bùn cát sẽ liên tục bị nước sông xói trôi đi."}],"related":[{"hanzi":"冲洗","pinyin":"chōngxǐ","vi":"rửa trôi"},{"hanzi":"侵蚀","pinyin":"qīnshí","vi":"xói mòn"},{"hanzi":"冲击","pinyin":"chōngjī","vi":"va đập"},{"hanzi":"水土流失","pinyin":"shuǐtǔliúshī","vi":"xói mòn đất"}],"traditional":"沖刷"},{"id":"抽签","hanzi":"抽签","pinyin":"chōuqiān","meaning_vi":"bốc thăm; xin xăm","explanation":"抽 (抽) + 签 (ký (tên)).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🎫","examples":[{"type":"basic","zh":"我们抽签决定顺序。","pinyin":"Wǒmen chōuqiān juédìng shùnxù.","vi":"Chúng tôi bốc thăm quyết định thứ tự."},{"type":"simple","zh":"世界杯小组赛的抽签仪式将在周五举行。","pinyin":"Shìjièbēi xiǎozǔsài de chōuqiān yíshì jiāng zài Zhōuwǔ jǔxíng.","vi":"Lễ bốc thăm vòng bảng World Cup sẽ được tổ chức vào thứ Sáu."},{"type":"compound","zh":"因为两个人都想去出差，所以经理让他们抽签决定。","pinyin":"Yīnwèi liǎng gè rén dōu xiǎng qù chūchāi, suǒyǐ jīnglǐ ràng tāmen chōuqiān juédìng.","vi":"Vì cả hai người đều muốn đi công tác nên quản lý bảo họ bốc thăm quyết định."}],"related":[{"hanzi":"抓阄","pinyin":"zhuājiū","vi":"rút thăm"},{"hanzi":"签","pinyin":"qiān","vi":"thẻ thăm"},{"hanzi":"抽奖","pinyin":"chōujiǎng","vi":"bốc thăm trúng thưởng"},{"hanzi":"求签","pinyin":"qiúqiān","vi":"xin xăm"}],"traditional":"抽簽"},{"id":"抽丝剥茧","hanzi":"抽丝剥茧","pinyin":"chōusī-bōjiǎn","meaning_vi":"rút tơ bóc kén (phân tích tỉ mỉ từng lớp vấn đề)","explanation":"抽丝剥茧: rút (抽) tơ (丝), bóc (剥) kén (茧) → phân tích tỉ mỉ, từng bước từng lớp để tìm ra chân tướng. Hay dùng khi phá án, giải quyết vấn đề.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"🔍","examples":[{"type":"basic","zh":"警探抽丝剥茧，找到了真相。","pinyin":"Jǐngtàn chōusībōjiǎn, zhǎodàole zhēnxiàng.","vi":"Thám tử phân tích tỉ mỉ từng lớp và đã tìm ra sự thật."},{"type":"simple","zh":"老师抽丝剥茧地把这道难题讲得清清楚楚。","pinyin":"Lǎoshī chōusībōjiǎn de bǎ zhè dào nántí jiǎng de qīng qīngchǔ chǔ.","vi":"Thầy giáo phân tích từng lớp, giảng bài toán khó này thật rõ ràng."},{"type":"compound","zh":"只要我们抽丝剥茧地分析数据，就能找出销量下滑的原因。","pinyin":"Zhǐyào wǒmen chōusībōjiǎn de fēnxī shùjù, jiù néng zhǎochū xiāoliàng xiàhuá de yuányīn.","vi":"Chỉ cần chúng ta phân tích dữ liệu tỉ mỉ từng lớp là có thể tìm ra nguyên nhân doanh số sụt giảm."}],"related":[{"hanzi":"层层深入","pinyin":"céngcéngshēnrù","vi":"đi sâu từng lớp"},{"hanzi":"细致","pinyin":"xìzhì","vi":"tỉ mỉ"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự tiến lên"}],"traditional":"抽絲剝繭"},{"id":"抽样调查","hanzi":"抽样调查","pinyin":"chōuyàngdiàochá","meaning_vi":"điều tra chọn mẫu","explanation":"抽 (抽) + 样 (mẫu mã/kiểu dáng) + 调 (điều chỉnh/hòa giải) + 查 (tra).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-viec"],"image":"🔍","examples":[{"type":"basic","zh":"我们做了抽样调查。","pinyin":"Wǒmen zuòle chōuyàngdiàochá.","vi":"Chúng tôi đã làm điều tra chọn mẫu."},{"type":"simple","zh":"统计局对五千户家庭进行了抽样调查。","pinyin":"Tǒngjìjú duì wǔ qiān hù jiātíng jìnxíngle chōuyàngdiàochá.","vi":"Cục Thống kê đã tiến hành điều tra chọn mẫu đối với năm nghìn hộ gia đình."},{"type":"compound","zh":"既然不可能询问每一位顾客，就只能采用抽样调查的方法。","pinyin":"Jìrán bù kěnéng xúnwèn měi yí wèi gùkè, jiù zhǐnéng cǎiyòng chōuyàngdiàochá de fāngfǎ.","vi":"Đã không thể hỏi từng khách hàng một thì chỉ có thể dùng phương pháp điều tra chọn mẫu."}],"related":[{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"样本","pinyin":"yàngběn","vi":"mẫu"},{"hanzi":"抽样","pinyin":"chōuyàng","vi":"chọn mẫu"},{"hanzi":"问卷","pinyin":"wènjuàn","vi":"bảng hỏi"}],"traditional":"抽樣調查"},{"id":"初出茅庐","hanzi":"初出茅庐","pinyin":"chūchū-máolú","meaning_vi":"mới bước chân vào đời (còn non kinh nghiệm)","explanation":"Điển tích Gia Cát Lượng. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌱","examples":[{"type":"basic","zh":"他还是初出茅庐的新人。","pinyin":"Tā háishì chūchūmáolú de xīnrén.","vi":"Anh ấy vẫn còn là người mới chân ướt chân ráo."},{"type":"simple","zh":"这位初出茅庐的导演竟然拿下了最佳新人奖。","pinyin":"Zhè wèi chūchūmáolú de dǎoyǎn jìngrán náxiàle zuì jiā xīnrén jiǎng.","vi":"Vị đạo diễn mới vào nghề này lại giành được giải Người mới xuất sắc nhất."},{"type":"compound","zh":"虽然她初出茅庐，但是处理客户投诉时一点也不慌。","pinyin":"Suīrán tā chūchūmáolú, dànshì chǔlǐ kèhù tóusù shí yìdiǎn yě bù huāng.","vi":"Tuy mới bước chân vào nghề, nhưng khi xử lý khiếu nại của khách hàng cô ấy chẳng hề lúng túng."}],"related":[{"hanzi":"新手","pinyin":"xīnshǒu","vi":"người mới"},{"hanzi":"初来乍到","pinyin":"chūláizhàdào","vi":"mới đến"},{"hanzi":"乳臭未干","pinyin":"rǔxiùwèigān","vi":"hôi sữa"},{"hanzi":"老练","pinyin":"lǎoliàn","vi":"lão luyện"}],"traditional":"初出茅廬"},{"id":"出境","hanzi":"出境","pinyin":"chūjìng","meaning_vi":"xuất cảnh","explanation":"出 (ra) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🛫","examples":[{"type":"basic","zh":"他明天出境旅游。","pinyin":"Tā míngtiān chūjìng lǚyóu.","vi":"Ngày mai anh ấy xuất cảnh đi du lịch."},{"type":"simple","zh":"旅客出境时必须出示有效护照。","pinyin":"Lǚkè chūjìng shí bìxū chūshì yǒuxiào hùzhào.","vi":"Hành khách khi xuất cảnh phải xuất trình hộ chiếu còn hiệu lực."},{"type":"compound","zh":"一旦签证过期，你就没法顺利出境了。","pinyin":"Yídàn qiānzhèng guòqī, nǐ jiù méifǎ shùnlì chūjìng le.","vi":"Một khi thị thực hết hạn, bạn sẽ không thể xuất cảnh suôn sẻ được nữa."}],"related":[{"hanzi":"入境","pinyin":"rùjìng","vi":"nhập cảnh"},{"hanzi":"出国","pinyin":"chūguó","vi":"xuất ngoại"},{"hanzi":"护照","pinyin":"hùzhào","vi":"hộ chiếu"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"thị thực"}]},{"id":"出奇制胜","hanzi":"出奇制胜","pinyin":"chūqí-zhìshèng","meaning_vi":"dùng mưu lạ bất ngờ giành chiến thắng","explanation":"Binh pháp / Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"♟️","examples":[{"type":"basic","zh":"这支球队善于出奇制胜。","pinyin":"Zhè zhī qiúduì shànyú chūqízhìshèng.","vi":"Đội bóng này giỏi dùng chiêu bất ngờ để giành chiến thắng."},{"type":"simple","zh":"教练在最后十分钟换上新人，出奇制胜。","pinyin":"Jiàoliàn zài zuìhòu shí fēnzhōng huàn shàng xīnrén, chūqízhìshèng.","vi":"Huấn luyện viên tung cầu thủ mới vào sân ở mười phút cuối, bất ngờ giành chiến thắng."},{"type":"compound","zh":"因为小公司资金有限，所以只能靠创意出奇制胜。","pinyin":"Yīnwèi xiǎo gōngsī zījīn yǒuxiàn, suǒyǐ zhǐnéng kào chuàngyì chūqízhìshèng.","vi":"Vì công ty nhỏ có nguồn vốn hạn chế nên chỉ có thể dựa vào sáng tạo để thắng bằng chiêu lạ."}],"related":[{"hanzi":"出其不意","pinyin":"chūqíbúyì","vi":"bất ngờ"},{"hanzi":"奇招","pinyin":"qízhāo","vi":"chiêu lạ"},{"hanzi":"战术","pinyin":"zhànshù","vi":"chiến thuật"},{"hanzi":"克敌制胜","pinyin":"kèdízhìshèng","vi":"đánh bại kẻ thù"}],"traditional":"出奇制勝"},{"id":"出师","hanzi":"出师","pinyin":"chūshī","meaning_vi":"học xong nghề, ra nghề; xuất quân","explanation":"出 (ra) + 师 (thầy giáo/sư phụ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🎓","examples":[{"type":"basic","zh":"他学了三年才出师。","pinyin":"Tā xuéle sān nián cái chūshī.","vi":"Anh ấy học ba năm mới xong nghề."},{"type":"simple","zh":"这位木匠十八岁就出师自己开了店。","pinyin":"Zhè wèi mùjiang shíbā suì jiù chūshī zìjǐ kāile diàn.","vi":"Người thợ mộc này mười tám tuổi đã học xong nghề và tự mở tiệm."},{"type":"compound","zh":"只要你把这门手艺练熟了，师傅就会让你出师。","pinyin":"Zhǐyào nǐ bǎ zhè mén shǒuyì liàn shú le, shīfu jiù huì ràng nǐ chūshī.","vi":"Chỉ cần con luyện thạo tay nghề này, sư phụ sẽ cho con ra nghề."}],"related":[{"hanzi":"拜师","pinyin":"bàishī","vi":"bái sư"},{"hanzi":"徒弟","pinyin":"túdì","vi":"đồ đệ"},{"hanzi":"出师不利","pinyin":"chūshībúlì","vi":"ra quân bất lợi"},{"hanzi":"毕业","pinyin":"bìyè","vi":"tốt nghiệp"}],"traditional":"出師"},{"id":"出洋相","hanzi":"出洋相","pinyin":"chūyángxiàng","meaning_vi":"làm trò cười, bẽ mặt","explanation":"出 + 洋相 (trò hề).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤡","examples":[{"type":"basic","zh":"我在台上出洋相了。","pinyin":"Wǒ zài tái shàng chūyángxiàng le.","vi":"Tôi đã làm trò cười trên sân khấu."},{"type":"simple","zh":"我可不想在客户面前出洋相。","pinyin":"Wǒ kěbù xiǎng zài kèhù miànqián chūyángxiàng.","vi":"Tôi không muốn bị bẽ mặt trước khách hàng đâu."},{"type":"compound","zh":"如果不提前排练，明天的演讲就很可能出洋相。","pinyin":"Rúguǒ bù tíqián páiliàn, míngtiān de yǎnjiǎng jiù hěn kěnéng chūyángxiàng.","vi":"Nếu không tập dượt trước thì bài diễn thuyết ngày mai rất có thể sẽ thành trò cười."}],"related":[{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"},{"hanzi":"出丑","pinyin":"chūchǒu","vi":"bêu xấu"},{"hanzi":"难堪","pinyin":"nánkān","vi":"khó xử"},{"hanzi":"笑话","pinyin":"xiàohua","vi":"trò cười"}]},{"id":"出众","hanzi":"出众","pinyin":"chūzhòng","meaning_vi":"xuất chúng, nổi bật hơn người","explanation":"出 (ra) + 众 (quần chúng/đông đảo).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"她的气质很出众。","pinyin":"Tā de qìzhì hěn chūzhòng.","vi":"Khí chất của cô ấy rất nổi bật."},{"type":"simple","zh":"他凭借出众的口才赢得了这场比赛。","pinyin":"Tā píngjiè chūzhòng de kǒucái yíng déle zhè chǎng bǐsài.","vi":"Anh ấy giành chiến thắng cuộc thi này nhờ tài ăn nói xuất chúng."},{"type":"compound","zh":"她不但成绩出众，而且非常乐于帮助同学。","pinyin":"Tā búdàn chéngjì chūzhòng, érqiě fēicháng lèyú bāngzhù tóngxué.","vi":"Cô ấy không những thành tích nổi bật mà còn rất vui lòng giúp đỡ bạn học."}],"related":[{"hanzi":"出类拔萃","pinyin":"chūlèibácuì","vi":"xuất chúng"},{"hanzi":"超群","pinyin":"chāoqún","vi":"vượt trội"},{"hanzi":"突出","pinyin":"tūchū","vi":"nổi bật"},{"hanzi":"平庸","pinyin":"píngyōng","vi":"tầm thường"}],"traditional":"出眾"},{"id":"出尔反尔","hanzi":"出尔反尔","pinyin":"chū'ěr-fǎn'ěr","meaning_vi":"tiền hậu bất nhất, nói trước quên sau lật lọng","explanation":"出尔反尔: điều từ ngươi (尔) đi ra (出) sẽ quay lại (反) với ngươi (Mạnh Tử) → nay chỉ người nói rồi lại nuốt lời, trước sau bất nhất.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤥","examples":[{"type":"basic","zh":"你不能出尔反尔。","pinyin":"Nǐ bù néng chū'ěrfǎn'ěr.","vi":"Anh không thể nói một đằng làm một nẻo."},{"type":"simple","zh":"房东出尔反尔，突然要涨两成房租。","pinyin":"Fángdōng chū'ěrfǎn'ěr, tūrán yào zhǎng liǎng chéng fángzū.","vi":"Chủ nhà tiền hậu bất nhất, đột nhiên đòi tăng tiền thuê thêm hai mươi phần trăm."},{"type":"compound","zh":"如果一个人总是出尔反尔，就没有人愿意和他合作。","pinyin":"Rúguǒ yígèrén zǒngshì chū'ěrfǎn'ěr, jiù méiyǒu rén yuànyì hé tā hézuò.","vi":"Nếu một người luôn tiền hậu bất nhất thì sẽ chẳng ai muốn hợp tác với anh ta."}],"related":[{"hanzi":"言而无信","pinyin":"yán'érwúxìn","vi":"nói không giữ lời"},{"hanzi":"反复无常","pinyin":"fǎnfùwúcháng","vi":"thất thường"},{"hanzi":"食言","pinyin":"shíyán","vi":"nuốt lời"},{"hanzi":"言而有信","pinyin":"yán'éryǒuxìn","vi":"giữ lời"}],"traditional":"出爾反爾"},{"id":"春华秋实","hanzi":"春华秋实","pinyin":"chūnhuá-qiūshí","meaning_vi":"xuân nở hoa thu kết trái (công sức bỏ ra sẽ gặt hái thành quả)","explanation":"春华秋实: mùa xuân (春) ra hoa (华), mùa thu (秋) kết quả (实) → có gieo trồng, nỗ lực thì mới có thành quả; cũng ví văn hay và đức tốt.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🍎","examples":[{"type":"basic","zh":"春华秋实，付出总有回报。","pinyin":"Chūnhuáqiūshí, fùchū zǒngyǒu huíbào.","vi":"Xuân nở hoa thu kết trái, bỏ công sức ắt có đền đáp."},{"type":"simple","zh":"校长在毕业典礼上用春华秋实四个字勉励大家。","pinyin":"Xiàozhǎng zài bìyè diǎnlǐ shàng yòng chūnhuáqiūshí sì gè zì miǎnlì dàjiā.","vi":"Hiệu trưởng dùng bốn chữ xuân hoa thu thực để khích lệ mọi người tại lễ tốt nghiệp."},{"type":"compound","zh":"只要你肯脚踏实地地努力，就一定会迎来春华秋实的那一天。","pinyin":"Zhǐyào nǐ kěn jiǎotàshídì de nǔlì, jiù yídìng huì yínglái chūnhuáqiūshí de nà yì tiān.","vi":"Chỉ cần bạn chịu nỗ lực chắc chắn từng bước, nhất định sẽ đón được ngày gặt hái thành quả."}],"related":[{"hanzi":"一分耕耘一分收获","pinyin":"yì fēn gēngyún yì fēn shōuhuò","vi":"gieo gì gặt nấy"},{"hanzi":"收获","pinyin":"shōuhuò","vi":"thu hoạch"},{"hanzi":"硕果累累","pinyin":"shuòguǒléiléi","vi":"thành quả dồi dào"},{"hanzi":"耕耘","pinyin":"gēngyún","vi":"cày cấy vun trồng"}],"traditional":"春華秋實"},{"id":"春联","hanzi":"春联","pinyin":"chūnlián","meaning_vi":"câu đối Tết","explanation":"春 (mùa xuân) + 联 (câu đối).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🧧","examples":[{"type":"basic","zh":"门上贴着春联。","pinyin":"Mén shàng tiēzhe chūnlián.","vi":"Trên cửa dán câu đối Tết."},{"type":"simple","zh":"爷爷每年都亲手给邻居们写春联。","pinyin":"Yéye měinián dōu qīnshǒu gěi línjūmen xiě chūnlián.","vi":"Năm nào ông nội cũng tự tay viết câu đối Tết cho hàng xóm."},{"type":"compound","zh":"春联一贴上大门，过年的气氛就出来了。","pinyin":"Chūnlián yì tiē shàng dàmén, guònián de qìfēn jiù chūlái le.","vi":"Câu đối Tết vừa dán lên cổng là không khí Tết liền tràn ngập."}],"related":[{"hanzi":"对联","pinyin":"duìlián","vi":"câu đối"},{"hanzi":"福字","pinyin":"fúzì","vi":"chữ Phúc"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết"},{"hanzi":"贴春联","pinyin":"tiēchūnlián","vi":"dán câu đối Tết"}],"traditional":"春聯"},{"id":"产卵","hanzi":"产卵","pinyin":"chǎnluǎn","meaning_vi":"đẻ trứng","explanation":"产 (sản – sinh ra) + 卵 (noãn – trứng) → đẻ trứng; dùng cho cá, côn trùng, chim, bò sát. VD: 鲑鱼逆流而上产卵.","hsk_level":"7-9","tags":["dong-tu","dong-vat"],"image":"🥚","examples":[{"type":"basic","zh":"海龟上岸产卵。","pinyin":"Hǎiguī shàng'àn chǎnluǎn.","vi":"Rùa biển lên bờ đẻ trứng."},{"type":"simple","zh":"每年春天鲑鱼都会逆流而上回到出生地产卵。","pinyin":"Měinián chūntiān guīyú dōuhuì nìliú ér shàng huídào chūshēngdì chǎnluǎn.","vi":"Mùa xuân hằng năm, cá hồi đều bơi ngược dòng về nơi sinh ra để đẻ trứng."},{"type":"compound","zh":"因为蚊子喜欢在积水里产卵，所以花盆里的水要经常倒掉。","pinyin":"Yīnwèi wénzi xǐhuan zài jīshuǐ lǐ chǎnluǎn, suǒyǐ huāpén lǐ de shuǐ yào jīngcháng dào diào.","vi":"Vì muỗi thích đẻ trứng trong nước đọng nên nước trong chậu hoa phải thường xuyên đổ đi."}],"related":[{"hanzi":"下蛋","pinyin":"xiàdàn","vi":"đẻ trứng"},{"hanzi":"孵化","pinyin":"fūhuà","vi":"ấp nở"},{"hanzi":"鱼卵","pinyin":"yúluǎn","vi":"trứng cá"},{"hanzi":"繁殖","pinyin":"fánzhí","vi":"sinh sản"}],"traditional":"產卵"},{"id":"产区","hanzi":"产区","pinyin":"chǎnqū","meaning_vi":"vùng sản xuất","explanation":"产 (sản – sản xuất) + 区 (khu – vùng) → vùng sản xuất, vùng trồng/nuôi một sản phẩm. VD: 茶叶产区, 葡萄酒产区.","hsk_level":"7-9","tags":["danh-tu","dia-diem","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这里是著名茶叶产区。","pinyin":"Zhèlǐ shì zhùmíng cháyè chǎnqū.","vi":"Đây là vùng sản xuất chè nổi tiếng."},{"type":"simple","zh":"今年主要产区的苹果产量明显下降。","pinyin":"Jīnnián zhǔyào chǎnqū de píngguǒ chǎnliàng míngxiǎn xiàjiàng.","vi":"Năm nay sản lượng táo ở các vùng sản xuất chính giảm rõ rệt."},{"type":"compound","zh":"虽然这两款咖啡豆来自同一个产区，但是味道差别很大。","pinyin":"Suīrán zhè liǎng kuǎn kāfēidòu láizì tóngyī gè chǎnqū, dànshì wèidào chābié hěn dà.","vi":"Tuy hai loại hạt cà phê này đến từ cùng một vùng sản xuất nhưng hương vị khác nhau rất nhiều."}],"related":[{"hanzi":"产地","pinyin":"chǎndì","vi":"nơi sản xuất"},{"hanzi":"产量","pinyin":"chǎnliàng","vi":"sản lượng"},{"hanzi":"原产地","pinyin":"yuánchǎndì","vi":"xuất xứ"},{"hanzi":"茶区","pinyin":"cháqū","vi":"vùng chè"}],"traditional":"產區"},{"id":"产物","hanzi":"产物","pinyin":"chǎnwù","meaning_vi":"sản phẩm, kết quả của một quá trình","explanation":"产 (产) + 物 (vật chất/sự vật).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"汉字是历史的产物。","pinyin":"Hànzì shì lìshǐ de chǎnwù.","vi":"Chữ Hán là sản phẩm của lịch sử."},{"type":"simple","zh":"共享单车是移动互联网时代的产物。","pinyin":"Gòngxiǎng dānchē shì yídòng Hùliánwǎng shídài de chǎnwù.","vi":"Xe đạp chia sẻ là sản phẩm của thời đại Internet di động."},{"type":"compound","zh":"这项发明并不是偶然的，而是他十年研究的产物。","pinyin":"Zhè xiàng fāmíng bìngbú shì ǒurán de, érshì tā shí nián yánjiū de chǎnwù.","vi":"Phát minh này không phải ngẫu nhiên, mà là kết quả của mười năm nghiên cứu của ông ấy."}],"related":[{"hanzi":"产品","pinyin":"chǎnpǐn","vi":"sản phẩm"},{"hanzi":"结果","pinyin":"jiéguǒ","vi":"kết quả"},{"hanzi":"副产品","pinyin":"fùchǎnpǐn","vi":"sản phẩm phụ"},{"hanzi":"成果","pinyin":"chéngguǒ","vi":"thành quả"}],"traditional":"產物"},{"id":"产业结构","hanzi":"产业结构","pinyin":"chǎnyèjiégòu","meaning_vi":"cơ cấu ngành kinh tế","explanation":"产业 (sản nghiệp – ngành kinh tế) + 结构 (kết cấu – cơ cấu) → cơ cấu ngành kinh tế. VD: 调整产业结构, 优化产业结构.","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🏗️","examples":[{"type":"basic","zh":"产业结构正在调整。","pinyin":"Chǎnyèjiégòu zhèngzài tiáozhěng.","vi":"Cơ cấu ngành kinh tế đang được điều chỉnh."},{"type":"simple","zh":"这座煤炭城市的产业结构过于单一。","pinyin":"Zhè zuò méitàn chéngshì de chǎnyèjiégòu guòyú dānyī.","vi":"Cơ cấu ngành kinh tế của thành phố than đá này quá đơn điệu."},{"type":"compound","zh":"如果不优化产业结构，这个地区的经济就很难持续增长。","pinyin":"Rúguǒ bù yōuhuà chǎnyèjiégòu, zhè ge dìqū de jīngjì jiù hěn nán chíxù zēngzhǎng.","vi":"Nếu không tối ưu hóa cơ cấu ngành kinh tế, kinh tế khu vực này sẽ khó tăng trưởng bền vững."}],"related":[{"hanzi":"产业","pinyin":"chǎnyè","vi":"ngành nghề"},{"hanzi":"第三产业","pinyin":"dìsānchǎnyè","vi":"ngành dịch vụ"},{"hanzi":"产业升级","pinyin":"chǎnyèshēngjí","vi":"nâng cấp ngành"},{"hanzi":"经济结构","pinyin":"jīngjìjiégòu","vi":"cơ cấu kinh tế"}],"traditional":"產業結構"},{"id":"产业链","hanzi":"产业链","pinyin":"chǎnyèliàn","meaning_vi":"chuỗi ngành hàng, chuỗi công nghiệp","explanation":"产业 (sản nghiệp – ngành) + 链 (liên – chuỗi xích) → chuỗi công nghiệp từ nguyên liệu, sản xuất đến tiêu thụ. VD: 完善产业链, 产业链上下游.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这条产业链很完整。","pinyin":"Zhè tiáo chǎnyèliàn hěn wánzhěng.","vi":"Chuỗi công nghiệp này rất hoàn chỉnh."},{"type":"simple","zh":"当地已经形成了从种植到加工的茶叶产业链。","pinyin":"Dāngdì yǐjīng xíng chéngle cóng zhòngzhí dào jiāgōng de cháyè chǎnyèliàn.","vi":"Địa phương đã hình thành chuỗi ngành chè từ trồng trọt đến chế biến."},{"type":"compound","zh":"一旦芯片供应中断，整个汽车产业链就会受到冲击。","pinyin":"Yídàn xīnpiàn gōngyìng zhōngduàn, zhěnggè qìchē chǎnyèliàn jiù huì shòudào chōngjī.","vi":"Một khi nguồn cung chip bị gián đoạn, toàn bộ chuỗi công nghiệp ô tô sẽ bị ảnh hưởng."}],"related":[{"hanzi":"供应链","pinyin":"gōngyìngliàn","vi":"chuỗi cung ứng"},{"hanzi":"产业","pinyin":"chǎnyè","vi":"ngành nghề"},{"hanzi":"上下游","pinyin":"shàngxiàyóu","vi":"thượng hạ nguồn"},{"hanzi":"价值链","pinyin":"jiàzhíliàn","vi":"chuỗi giá trị"}],"traditional":"產業鏈"},{"id":"尺短寸长","hanzi":"尺短寸长","pinyin":"chǐduǎn-cùncháng","meaning_vi":"ai cũng có ưu điểm và khuyết điểm riêng","explanation":"尺短寸长: do câu 尺有所短，寸有所长 (Sở Từ) — thước có khi ngắn, tấc có khi dài → ai, cái gì cũng có ưu điểm và khuyết điểm riêng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"📏","examples":[{"type":"basic","zh":"尺短寸长，各有所长。","pinyin":"Chǐduǎncùncháng, gè yǒu suǒcháng.","vi":"Thước có khi ngắn, tấc có khi dài, ai cũng có sở trường riêng."},{"type":"simple","zh":"经理用人时很懂得尺短寸长的道理。","pinyin":"Jīnglǐ yòngrén shí hěn dǒngde chǐduǎncùncháng de dàolǐ.","vi":"Giám đốc khi dùng người rất hiểu đạo lý ai cũng có sở trường sở đoản."},{"type":"compound","zh":"既然尺短寸长，我们就不必拿自己的短处去比别人的长处。","pinyin":"Jìrán chǐduǎncùncháng, wǒmen jiù búbì ná zìjǐ de duǎnchù qù bǐ biérén de chángchù.","vi":"Đã ai cũng có sở trường sở đoản thì chúng ta không cần lấy điểm yếu của mình so với điểm mạnh của người khác."}],"related":[{"hanzi":"尺有所短寸有所长","pinyin":"chǐyǒusuǒduǎn cùn yǒu suǒcháng","vi":"thước có lúc ngắn tấc có lúc dài"},{"hanzi":"各有所长","pinyin":"gèyǒusuǒcháng","vi":"mỗi người một sở trường"},{"hanzi":"取长补短","pinyin":"qǔchángbǔduǎn","vi":"lấy dài bù ngắn"},{"hanzi":"优缺点","pinyin":"yōuquēdiǎn","vi":"ưu nhược điểm"}],"traditional":"尺短寸長"},{"id":"丑化","hanzi":"丑化","pinyin":"chǒuhuà","meaning_vi":"bôi nhọ, làm xấu hình ảnh","explanation":"丑 (xú – xấu) + 化 (hóa – làm cho) → làm cho xấu đi, bôi nhọ, bóp méo hình ảnh. VD: 丑化形象; trái nghĩa 美化.","hsk_level":"7-9","tags":["dong-tu"],"image":"👎","examples":[{"type":"basic","zh":"不要丑化别人。","pinyin":"Bú yào chǒuhuà biérén.","vi":"Đừng bôi nhọ người khác."},{"type":"simple","zh":"这部动画片故意丑化了反派角色的外貌。","pinyin":"Zhè bù dònghuàpiàn gùyì chǒuhuàle fǎnpài juésè de wàimào.","vi":"Bộ phim hoạt hình này cố tình làm xấu ngoại hình của nhân vật phản diện."},{"type":"compound","zh":"虽然他们是竞争对手，但是在广告里丑化对方是违法的。","pinyin":"Suīrán tāmen shì jìngzhēng duìshǒu, dànshì zài guǎnggào lǐ chǒuhuà duìfāng shì wéifǎ de.","vi":"Tuy họ là đối thủ cạnh tranh nhưng bôi nhọ đối phương trong quảng cáo là phạm pháp."}],"related":[{"hanzi":"美化","pinyin":"měihuà","vi":"tô đẹp"},{"hanzi":"歪曲","pinyin":"wāiqū","vi":"xuyên tạc"},{"hanzi":"抹黑","pinyin":"mǒhēi","vi":"bôi đen"},{"hanzi":"诋毁","pinyin":"dǐhuǐ","vi":"gièm pha"}],"traditional":"醜化"},{"id":"处变不惊","hanzi":"处变不惊","pinyin":"chǔbiàn-bùjīng","meaning_vi":"đứng trước biến cố vẫn bình tĩnh không hoảng loạn","explanation":"处变不惊: đứng trước (处) biến cố (变) mà không (不) hoảng sợ (惊) → bình tĩnh, vững vàng khi gặp tình huống bất ngờ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧘","examples":[{"type":"basic","zh":"他总能处变不惊。","pinyin":"Tā zǒngnéng chǔbiànbùjīng.","vi":"Anh ấy luôn bình tĩnh trước biến cố."},{"type":"simple","zh":"机长处变不惊地让飞机安全迫降在河面上。","pinyin":"Jīzhǎng chǔbiànbùjīng de ràng fēijī ānquán pòjiàng zài hémiàn shàng.","vi":"Cơ trưởng bình tĩnh trước biến cố, cho máy bay hạ cánh khẩn cấp an toàn trên mặt sông."},{"type":"compound","zh":"即使股市突然暴跌，这位老投资人也处变不惊。","pinyin":"Jíshǐ gǔshì tūrán bàodiē, zhè wèi lǎo tóuzīrén yě chǔbiànbùjīng.","vi":"Dù thị trường chứng khoán đột ngột lao dốc, nhà đầu tư lão luyện này vẫn điềm tĩnh không hoảng."}],"related":[{"hanzi":"临危不乱","pinyin":"línwēibúluàn","vi":"gặp nguy không loạn"},{"hanzi":"泰然自若","pinyin":"tàiránzìruò","vi":"điềm nhiên tự tại"},{"hanzi":"镇定","pinyin":"zhèndìng","vi":"bình tĩnh"},{"hanzi":"惊慌失措","pinyin":"jīnghuāngshīcuò","vi":"hoảng hốt luống cuống"}],"traditional":"處變不驚"},{"id":"处方药","hanzi":"处方药","pinyin":"chǔfāngyào","meaning_vi":"thuốc kê đơn","explanation":"处 (处) + 方 (vuông) + 药 (thuốc).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"📋","examples":[{"type":"basic","zh":"抗生素属于处方药。","pinyin":"Kàngshēngsù shǔyú chǔfāngyào.","vi":"Thuốc kháng sinh thuộc loại thuốc kê đơn."},{"type":"simple","zh":"药店不能在没有医生处方的情况下出售处方药。","pinyin":"Yàodiàn bù néng zài méiyǒu yīshēng chǔfāng de qíngkuàng xià chūshòu chǔfāngyào.","vi":"Hiệu thuốc không được bán thuốc kê đơn khi không có đơn của bác sĩ."},{"type":"compound","zh":"处方药虽然效果明显，但是必须按照医嘱服用。","pinyin":"Chǔfāngyào suīrán xiàoguǒ míngxiǎn, dànshì bìxū ànzhào yīzhǔ fúyòng.","vi":"Thuốc kê đơn tuy hiệu quả rõ rệt nhưng phải dùng theo chỉ định của bác sĩ."}],"related":[{"hanzi":"非处方药","pinyin":"fēichǔfāngyào","vi":"thuốc không kê đơn"},{"hanzi":"处方","pinyin":"chǔfāng","vi":"đơn thuốc"},{"hanzi":"药店","pinyin":"yàodiàn","vi":"hiệu thuốc"},{"hanzi":"医生","pinyin":"yīshēng","vi":"bác sĩ"}],"traditional":"處方藥"},{"id":"处世","hanzi":"处世","pinyin":"chǔshì","meaning_vi":"đối nhân xử thế","explanation":"处 (处) + 世 (thế giới/thế hệ).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"他处世很圆滑。","pinyin":"Tā chǔshì hěn yuánhuá.","vi":"Anh ấy đối nhân xử thế rất khéo léo."},{"type":"simple","zh":"父亲常教导我做人处世要先学会宽容。","pinyin":"Fùqīn cháng jiàodǎo wǒ zuòrén chǔshì yào xiān xuéhuì kuānróng.","vi":"Cha thường dạy tôi làm người và đối nhân xử thế trước hết phải học cách bao dung."},{"type":"compound","zh":"他不但能力强，而且为人处世很低调，所以人缘特别好。","pinyin":"Tā búdàn nénglì qiáng, érqiě wéirénchǔshì hěn dīdiào, suǒyǐ rényuán tèbié hǎo.","vi":"Anh ấy không những năng lực giỏi mà cách đối nhân xử thế còn khiêm tốn, nên rất được lòng mọi người."}],"related":[{"hanzi":"为人处世","pinyin":"wéirénchǔshì","vi":"đối nhân xử thế"},{"hanzi":"待人接物","pinyin":"dàirénjiēwù","vi":"cách đối xử với người"},{"hanzi":"处世之道","pinyin":"chǔshìzhīdào","vi":"đạo xử thế"},{"hanzi":"人情世故","pinyin":"rénqíngshìgù","vi":"nhân tình thế thái"}],"traditional":"處世"},{"id":"寸土必争","hanzi":"寸土必争","pinyin":"cùntǔ-bìzhēng","meaning_vi":"tấc đất cũng phải giữ","explanation":"寸 (寸) + 土 (đất đai/bản địa) + 必 (必) + 争 (tranh đấu/tranh thủ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🛡️","examples":[{"type":"basic","zh":"两军寸土必争。","pinyin":"Liǎng jūn cùntǔbìzhēng.","vi":"Hai quân tranh giành từng tấc đất."},{"type":"simple","zh":"在保卫边疆的问题上我们寸土必争。","pinyin":"Zài bǎowèi biānjiāng de wèntí shàng wǒmen cùntǔbìzhēng.","vi":"Trong vấn đề bảo vệ biên cương, chúng ta không nhường một tấc đất."},{"type":"compound","zh":"虽然只是一场友谊赛，但是双方在球场上依然寸土必争。","pinyin":"Suīrán zhǐshì yì chǎng yǒuyìsài, dànshì shuāngfāng zài qiúchǎng shàng yīrán cùntǔbìzhēng.","vi":"Tuy chỉ là trận giao hữu, nhưng hai bên trên sân vẫn giành giật từng tấc đất."}],"related":[{"hanzi":"寸步不让","pinyin":"cùnbùbúràng","vi":"không nhường nửa bước"},{"hanzi":"寸土","pinyin":"cùntǔ","vi":"tấc đất"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"针锋相对","pinyin":"zhēnfēngxiāngduì","vi":"ăn miếng trả miếng"}],"traditional":"寸土必爭"},{"id":"措手不及","hanzi":"措手不及","pinyin":"cuòshǒu-bùjí","meaning_vi":"trở tay không kịp","explanation":"措手 (thố thủ – đặt tay, xử trí) + 不及 (không kịp) → không kịp ra tay xử trí, trở tay không kịp. VD: 打得敌人措手不及.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"大雨来得让人措手不及。","pinyin":"Dàyǔ láide ràng rén cuòshǒubùjí.","vi":"Cơn mưa lớn đến khiến người ta trở tay không kịp."},{"type":"simple","zh":"突然的裁员通知让全体员工措手不及。","pinyin":"Tūrán de cáiyuán tōngzhī ràng quántǐ yuángōng cuòshǒubùjí.","vi":"Thông báo cắt giảm nhân sự đột ngột khiến toàn thể nhân viên trở tay không kịp."},{"type":"compound","zh":"如果平时不做好应急准备，一旦出事就会措手不及。","pinyin":"Rúguǒ píngshí bú zuò hǎo yìngjí zhǔnbèi, yídàn chūshì jiù huì cuòshǒubùjí.","vi":"Nếu bình thường không chuẩn bị ứng phó khẩn cấp thì một khi xảy ra chuyện sẽ trở tay không kịp."}],"related":[{"hanzi":"猝不及防","pinyin":"cùbùjífáng","vi":"không kịp phòng bị"},{"hanzi":"手忙脚乱","pinyin":"shǒumángjiǎoluàn","vi":"luống cuống tay chân"},{"hanzi":"防不胜防","pinyin":"fángbúshèngfáng","vi":"khó lòng phòng bị"},{"hanzi":"从容不迫","pinyin":"cóngróngbúpò","vi":"ung dung thong thả"}]},{"id":"催眠","hanzi":"催眠","pinyin":"cuīmián","meaning_vi":"thôi miên, ru ngủ","explanation":"催 (thúc giục) + 眠 (眠).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😴","examples":[{"type":"basic","zh":"这首曲子能催眠。","pinyin":"Zhè shǒu qǔzi néng cuīmián.","vi":"Bản nhạc này có thể ru ngủ."},{"type":"simple","zh":"心理医生用催眠的方法帮他回忆起童年往事。","pinyin":"Xīnlǐ yīshēng yòng cuīmián de fāngfǎ bāng tā huíyì qǐ tóngnián wǎngshì.","vi":"Bác sĩ tâm lý dùng phương pháp thôi miên giúp anh ấy nhớ lại chuyện thời thơ ấu."},{"type":"compound","zh":"这位教授的声音太平稳了，一开口就像在催眠。","pinyin":"Zhè wèi jiàoshòu de shēngyīn tàipíng wěn le, yì kāikǒu jiù xiàng zài cuīmián.","vi":"Giọng giáo sư này đều đều quá, vừa mở miệng đã như đang ru ngủ."}],"related":[{"hanzi":"催眠曲","pinyin":"cuīmiánqǔ","vi":"bài hát ru"},{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"睡眠","pinyin":"shuìmián","vi":"giấc ngủ"},{"hanzi":"安眠药","pinyin":"ānmiányào","vi":"thuốc ngủ"}]},{"id":"催人泪下","hanzi":"催人泪下","pinyin":"cuīrén-lèixià","meaning_vi":"cảm động rơi nước mắt","explanation":"催人 (thôi – giục người) + 泪下 (lệ hạ – rơi nước mắt) → khiến người ta rơi lệ; tả câu chuyện, cảnh tượng vô cùng cảm động.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"这个故事催人泪下。","pinyin":"Zhè ge gùshi cuīrénlèixià.","vi":"Câu chuyện này khiến người ta rơi lệ."},{"type":"simple","zh":"母亲在毕业典礼上的发言催人泪下。","pinyin":"Mǔqīn zài bìyè diǎnlǐ shàng de fāyán cuīrénlèixià.","vi":"Bài phát biểu của người mẹ tại lễ tốt nghiệp khiến ai nấy rơi nước mắt."},{"type":"compound","zh":"这部纪录片虽然没有华丽的特效，但是情节真实得催人泪下。","pinyin":"Zhè bù jìlùpiàn suīrán méiyǒu huálì de tèxiào, dànshì qíngjié zhēnshí de cuīrénlèixià.","vi":"Bộ phim tài liệu này tuy không có kỹ xảo hoa mỹ, nhưng tình tiết chân thực đến mức lấy đi nước mắt người xem."}],"related":[{"hanzi":"感人肺腑","pinyin":"gǎnrénfèifǔ","vi":"cảm động lòng người"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"热泪盈眶","pinyin":"rèlèiyíngkuàng","vi":"rưng rưng nước mắt"},{"hanzi":"动人","pinyin":"dòngrén","vi":"xúc động"}],"traditional":"催人淚下"},{"id":"灿若星辰","hanzi":"灿若星辰","pinyin":"cànruò-xīngchén","meaning_vi":"rực rỡ như muôn ngàn vì sao","explanation":"灿若星辰: rực rỡ (灿) như (若) các vì sao (星辰) → sáng chói, nổi bật; thường dùng để khen đôi mắt, tài năng hay thành tựu.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"她的双眼灿若星辰。","pinyin":"Tā de shuāngyǎn cànruòxīngchén.","vi":"Đôi mắt cô ấy sáng như sao trời."},{"type":"simple","zh":"夜幕下，城市的灯火灿若星辰。","pinyin":"Yèmù xià, chéngshì de dēnghuǒ cànruòxīngchén.","vi":"Dưới màn đêm, ánh đèn thành phố rực rỡ như muôn vì sao."},{"type":"compound","zh":"唐代不但国力强盛，而且诗人辈出，灿若星辰。","pinyin":"Tángdài búdàn guólì qiángshèng, érqiě shīrén bèichū, cànruòxīngchén.","vi":"Thời Đường không những quốc lực hùng mạnh, mà thi nhân còn xuất hiện lớp lớp, rực rỡ như sao trời."}],"related":[{"hanzi":"灿烂","pinyin":"cànlàn","vi":"rực rỡ"},{"hanzi":"星辰","pinyin":"xīngchén","vi":"tinh tú"},{"hanzi":"光辉灿烂","pinyin":"guānghuīcànlàn","vi":"chói lọi huy hoàng"},{"hanzi":"繁星","pinyin":"fánxīng","vi":"muôn vì sao"}],"traditional":"燦若星辰"},{"id":"裁定","hanzi":"裁定","pinyin":"cáidìng","meaning_vi":"phán quyết, quyết định của tòa án","explanation":"裁 + 定 (xác định).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"法院裁定合同无效。","pinyin":"Fǎyuàn cáidìng hétong wúxiào.","vi":"Tòa án phán quyết hợp đồng vô hiệu."},{"type":"simple","zh":"仲裁委员会裁定该公司赔偿员工十万元。","pinyin":"Zhòngcái wěiyuánhuì cáidìng gāi gōngsī péicháng yuángōng shíwàn yuán.","vi":"Hội đồng trọng tài phán quyết công ty đó bồi thường cho nhân viên một trăm nghìn tệ."},{"type":"compound","zh":"如果对一审裁定不服，当事人就可以在十日内提出上诉。","pinyin":"Rúguǒ duì yìshěn cáidìng bùfú, dāngshìrén jiù kěyǐ zài shí rìnèi tíchū shàngsù.","vi":"Nếu không phục quyết định sơ thẩm, đương sự có thể kháng cáo trong vòng mười ngày."}],"related":[{"hanzi":"裁决","pinyin":"cáijué","vi":"phán quyết"},{"hanzi":"判决","pinyin":"pànjué","vi":"tuyên án"},{"hanzi":"裁判","pinyin":"cáipàn","vi":"trọng tài"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"}]},{"id":"裁军","hanzi":"裁军","pinyin":"cáijūn","meaning_vi":"cắt giảm quân bị","explanation":"裁 (cắt/phán quyết) + 军 (quân đội).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"两国同意裁军。","pinyin":"Liǎngguó tóngyì cáijūn.","vi":"Hai nước đồng ý cắt giảm quân bị."},{"type":"simple","zh":"这次国际会议的核心议题是核裁军。","pinyin":"Zhè cì Guójì huìyì de héxīn yìtí shì hécáijūn.","vi":"Chủ đề cốt lõi của hội nghị quốc tế lần này là giải trừ vũ khí hạt nhân."},{"type":"compound","zh":"只要双方都愿意裁军，地区紧张局势就能缓和。","pinyin":"Zhǐyào shuāngfāng dōu yuànyì cáijūn, dìqū jǐnzhāng júshì jiù néng huǎnhé.","vi":"Chỉ cần hai bên đều sẵn lòng cắt giảm quân bị thì tình hình căng thẳng khu vực sẽ dịu đi."}],"related":[{"hanzi":"军备","pinyin":"jūnbèi","vi":"quân bị"},{"hanzi":"裁员","pinyin":"cáiyuán","vi":"cắt giảm nhân sự"},{"hanzi":"扩军","pinyin":"kuòjūn","vi":"mở rộng quân đội"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"}],"traditional":"裁軍"},{"id":"财力","hanzi":"财力","pinyin":"cáilì","meaning_vi":"tiềm lực tài chính","explanation":"财 (财) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"我们财力有限。","pinyin":"Wǒmen cáilì yǒuxiàn.","vi":"Tiềm lực tài chính của chúng tôi có hạn."},{"type":"simple","zh":"这家企业投入了大量财力研发新能源汽车。","pinyin":"Zhè jiā qǐyè tóurùle dàliàng cáilì yánfā xīnnéngyuánqìchē.","vi":"Doanh nghiệp này đã đầu tư nguồn tài chính lớn để nghiên cứu phát triển xe năng lượng mới."},{"type":"compound","zh":"因为学校财力不足，所以新图书馆的建设只好推迟。","pinyin":"Yīnwèi xuéxiào cáilì bùzú, suǒyǐ xīn túshūguǎn de jiànshè zhǐhǎo tuīchí.","vi":"Vì nhà trường không đủ tài chính nên việc xây thư viện mới đành phải hoãn lại."}],"related":[{"hanzi":"物力","pinyin":"wùlì","vi":"vật lực"},{"hanzi":"人力","pinyin":"rénlì","vi":"nhân lực"},{"hanzi":"实力","pinyin":"shílì","vi":"thực lực"},{"hanzi":"资金","pinyin":"zījīn","vi":"tiền vốn"}],"traditional":"財力"},{"id":"才思敏捷","hanzi":"才思敏捷","pinyin":"cáisī-mǐnjié","meaning_vi":"tư duy nhạy bén sắc sảo","explanation":"才思 (tài tư – tài năng suy nghĩ) + 敏捷 (mẫn tiệp – nhanh nhạy) → tư duy, văn tứ nhanh nhạy sắc sảo; thường khen người giỏi văn, đối đáp.","hsk_level":"7-9","tags":["thanh-ngu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"她才思敏捷，出口成章。","pinyin":"Tā cái sī mǐnjié, chūkǒuchéngzhāng.","vi":"Cô ấy tư duy nhạy bén, mở miệng là thành văn."},{"type":"simple","zh":"这位才思敏捷的主持人化解了现场的尴尬。","pinyin":"Zhè wèi cái sī mǐnjié de zhǔchírén huàjiěle xiànchǎng de gāngà.","vi":"Người dẫn chương trình nhanh trí này đã hóa giải sự ngượng ngùng tại hiện trường."},{"type":"compound","zh":"他虽然才思敏捷，但是写文章时总是不够细心。","pinyin":"Tā suīrán cái sī mǐnjié, dànshì xiě wénzhāng shí zǒngshì búgòu xìxīn.","vi":"Anh ấy tuy tư duy nhạy bén nhưng khi viết bài luôn thiếu cẩn thận."}],"related":[{"hanzi":"思维敏捷","pinyin":"sīwéimǐnjié","vi":"tư duy nhanh nhạy"},{"hanzi":"才华横溢","pinyin":"cáihuáhéngyì","vi":"tài hoa xuất chúng"},{"hanzi":"敏捷","pinyin":"mǐnjié","vi":"nhanh nhạy"},{"hanzi":"迟钝","pinyin":"chídùn","vi":"chậm chạp"}]},{"id":"财团","hanzi":"财团","pinyin":"cáituán","meaning_vi":"tập đoàn tài chính","explanation":"财 (tài – tiền của) + 团 (đoàn – nhóm, khối) → tập đoàn tài chính, nhóm tư bản lớn kiểm soát nhiều doanh nghiệp. VD: 日本财团.","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"这家银行属于大财团。","pinyin":"Zhè jiā yínháng shǔyú dà cáituán.","vi":"Ngân hàng này thuộc một tập đoàn tài chính lớn."},{"type":"simple","zh":"一家日本财团收购了这座城市最高的酒店。","pinyin":"Yìjiā Rìběn cáituán shōugòule zhè zuò chéngshì zuì gāo de jiǔdiàn.","vi":"Một tập đoàn tài chính Nhật Bản đã mua lại khách sạn cao nhất thành phố này."},{"type":"compound","zh":"如果没有财团的资金支持，这个机场项目就无法启动。","pinyin":"Rúguǒ méiyǒu cáituán de zījīn zhīchí, zhè ge jīchǎng xiàngmù jiù wúfǎ qǐdòng.","vi":"Nếu không có sự hỗ trợ vốn của tập đoàn tài chính thì dự án sân bay này không thể khởi động."}],"related":[{"hanzi":"财阀","pinyin":"cáifá","vi":"tài phiệt"},{"hanzi":"集团","pinyin":"jítuán","vi":"tập đoàn"},{"hanzi":"企业","pinyin":"qǐyè","vi":"doanh nghiệp"},{"hanzi":"银行","pinyin":"yínháng","vi":"ngân hàng"}],"traditional":"財團"},{"id":"残存","hanzi":"残存","pinyin":"cáncún","meaning_vi":"còn sót lại","explanation":"残 (残) + 存 (gửi (tiền)).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"墙上残存着旧标语。","pinyin":"Qiáng shàng cáncúnzhe jiù biāoyǔ.","vi":"Trên tường còn sót lại khẩu hiệu cũ."},{"type":"simple","zh":"大火过后，仓库里只残存了几箱货物。","pinyin":"Dàhuǒ guòhòu, cāngkù lǐ zhǐ cáncúnle jǐ xiāng huòwù.","vi":"Sau trận hỏa hoạn, trong kho chỉ còn sót lại vài thùng hàng."},{"type":"compound","zh":"虽然战争已经结束多年，但是城墙上仍残存着弹孔。","pinyin":"Suīrán zhànzhēng yǐjīng jiéshù duōnián, dànshì chéngqiáng shàng réng cáncúnzhe dànkǒng.","vi":"Tuy chiến tranh đã kết thúc nhiều năm, nhưng trên tường thành vẫn còn sót lại vết đạn."}],"related":[{"hanzi":"残留","pinyin":"cánliú","vi":"sót lại"},{"hanzi":"遗留","pinyin":"yíliú","vi":"để lại"},{"hanzi":"幸存","pinyin":"xìngcún","vi":"sống sót"},{"hanzi":"残余","pinyin":"cányú","vi":"tàn dư"}],"traditional":"殘存"},{"id":"残局","hanzi":"残局","pinyin":"cánjú","meaning_vi":"tàn cuộc, cục diện rối ren sau biến cố","explanation":"残 (sót lại) + 局 (vấn cờ/cục diện).","hsk_level":"7-9","tags":["danh-tu"],"image":"♟️","examples":[{"type":"basic","zh":"谁来收拾残局？","pinyin":"Shéi lái shōushi cánjú?","vi":"Ai sẽ đến dọn dẹp tàn cuộc?"},{"type":"simple","zh":"新市长上任后接手了前任留下的残局。","pinyin":"Xīn shìzhǎng shàngrèn hòu jiēshǒule qiánrèn liúxià de cánjú.","vi":"Tân thị trưởng sau khi nhậm chức đã tiếp quản cục diện rối ren mà người tiền nhiệm để lại."},{"type":"compound","zh":"这盘棋到了残局，他虽然少一个车，但是仍然有机会翻盘。","pinyin":"Zhè pán qí dàole cánjú, tā suīrán shǎo yí gè jū, dànshì réngrán yǒujī huì fānpán.","vi":"Ván cờ này đã đến tàn cuộc, anh ấy tuy thiếu một quân xe nhưng vẫn có cơ hội lật ngược thế cờ."}],"related":[{"hanzi":"收拾残局","pinyin":"shōushicánjú","vi":"dọn dẹp hậu quả"},{"hanzi":"烂摊子","pinyin":"làntānzi","vi":"mớ hỗn độn"},{"hanzi":"局面","pinyin":"júmiàn","vi":"cục diện"},{"hanzi":"结局","pinyin":"jiéjú","vi":"kết cục"}],"traditional":"殘局"},{"id":"残缺不全","hanzi":"残缺不全","pinyin":"cánquē-bùquán","meaning_vi":"sứt mẻ không trọn vẹn","explanation":"残缺 (tàn khuyết – sứt mẻ, thiếu) + 不全 (không đầy đủ) → sứt mẻ, thiếu sót không còn nguyên vẹn; dùng cho tài liệu, đồ vật, di tích.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧩","examples":[{"type":"basic","zh":"这本古书残缺不全。","pinyin":"Zhè běn gǔshū cánquēbùquán.","vi":"Cuốn sách cổ này rách nát không đầy đủ."},{"type":"simple","zh":"警方只找到了一段残缺不全的监控录像。","pinyin":"Jǐngfāng zhǐ zhǎodàole yí duàn cánquēbùquán de jiānkòng lùxiàng.","vi":"Cảnh sát chỉ tìm được một đoạn video giám sát chắp vá không đầy đủ."},{"type":"compound","zh":"因为档案资料残缺不全，所以这段历史很难考证清楚。","pinyin":"Yīnwèi dàng'àn zīliào cánquēbùquán, suǒyǐ zhè duàn lìshǐ hěn nán kǎozhèng qīngchu.","vi":"Vì tư liệu lưu trữ không đầy đủ nên đoạn lịch sử này rất khó khảo chứng rõ ràng."}],"related":[{"hanzi":"残缺","pinyin":"cánquē","vi":"sứt mẻ"},{"hanzi":"支离破碎","pinyin":"zhīlípòsuì","vi":"rời rạc tan nát"},{"hanzi":"完整无缺","pinyin":"wánzhěngwúquē","vi":"nguyên vẹn đầy đủ"},{"hanzi":"不完整","pinyin":"bùwánzhěng","vi":"không hoàn chỉnh"}],"traditional":"殘缺不全"},{"id":"侧目","hanzi":"侧目","pinyin":"cèmù","meaning_vi":"liếc nhìn (với vẻ kính nể hoặc bất bình)","explanation":"侧 (nghiêng) + 目 (mắt).","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"他的言行令人侧目。","pinyin":"Tā de yánxíng lìngrén cèmù.","vi":"Lời nói việc làm của anh ta khiến người ta phải liếc nhìn."},{"type":"simple","zh":"这家新公司的快速崛起令同行侧目。","pinyin":"Zhè jiā xīn gōngsī de kuàisù juéqǐ lìng tóngháng cèmù.","vi":"Sự trỗi dậy nhanh chóng của công ty mới này khiến các đối thủ cùng ngành phải dè chừng."},{"type":"compound","zh":"他一在餐厅里大声打电话，周围的客人就纷纷侧目。","pinyin":"Tā yí zài cāntīng lǐ dàshēng dǎdiànhuà, zhōuwéi de kèrén jiù fēnfēn cèmù.","vi":"Anh ta vừa lớn tiếng gọi điện trong nhà hàng, khách xung quanh liền liếc nhìn với vẻ khó chịu."}],"related":[{"hanzi":"刮目相看","pinyin":"guāmùxiāngkàn","vi":"nhìn với con mắt khác"},{"hanzi":"侧目而视","pinyin":"cèmù'érshì","vi":"liếc nhìn"},{"hanzi":"瞩目","pinyin":"zhǔmù","vi":"chú ý"},{"hanzi":"注视","pinyin":"zhùshì","vi":"nhìn chăm chú"}],"traditional":"側目"},{"id":"测算","hanzi":"测算","pinyin":"cèsuàn","meaning_vi":"tính toán dự báo","explanation":"测 (测) + 算 (tính toán).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🧮","examples":[{"type":"basic","zh":"专家测算了成本。","pinyin":"Zhuānjiā cè suànle chéngběn.","vi":"Chuyên gia đã tính toán chi phí."},{"type":"simple","zh":"据测算，这座大桥每年可节省运输费用两亿元。","pinyin":"Jù cèsuàn, zhè zuò Dàqiáo měinián kě jiéshěng yùnshū fèiyòng liǎng yì yuán.","vi":"Theo tính toán, cây cầu lớn này mỗi năm có thể tiết kiệm hai trăm triệu tệ chi phí vận tải."},{"type":"compound","zh":"只要把用电数据输进去，系统就能自动测算出下月电费。","pinyin":"Zhǐyào bǎ yòng diàn shùjù shū jìnqù, xìtǒng jiù néng zìdòng cèsuàn chū xiàyuè diànfèi.","vi":"Chỉ cần nhập dữ liệu dùng điện vào, hệ thống sẽ tự động tính ra tiền điện tháng sau."}],"related":[{"hanzi":"计算","pinyin":"jìsuàn","vi":"tính toán"},{"hanzi":"估算","pinyin":"gūsuàn","vi":"ước tính"},{"hanzi":"预测","pinyin":"yùcè","vi":"dự báo"},{"hanzi":"测量","pinyin":"cèliáng","vi":"đo lường"}],"traditional":"測算"},{"id":"层出","hanzi":"层出","pinyin":"céngchū","meaning_vi":"xuất hiện liên tiếp","explanation":"层 (tầng – lớp lớp) + 出 (xuất – xuất hiện) → xuất hiện lớp này nối lớp khác, liên tiếp. Thường gặp trong 层出不穷 (nhiều vô kể, không ngớt).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"新花样层出不穷。","pinyin":"Xīn huāyàng céngchūbùqióng.","vi":"Những kiểu mới liên tục xuất hiện."},{"type":"simple","zh":"近年来各种网络诈骗手段层出不穷。","pinyin":"Jìnniánlái gèzhǒng wǎngluòzhàpiàn shǒuduàn céngchūbùqióng.","vi":"Những năm gần đây, các thủ đoạn lừa đảo trên mạng liên tục xuất hiện."},{"type":"compound","zh":"虽然困难层出不穷，但是团队始终没有放弃。","pinyin":"Suīrán kùnnan céngchūbùqióng, dànshì tuánduì shǐzhōng méiyǒu fàngqì.","vi":"Tuy khó khăn liên tiếp nảy sinh nhưng cả đội vẫn không bỏ cuộc."}],"related":[{"hanzi":"层出不穷","pinyin":"céngchūbùqióng","vi":"liên tục xuất hiện"},{"hanzi":"涌现","pinyin":"yǒngxiàn","vi":"xuất hiện hàng loạt"},{"hanzi":"接连","pinyin":"jiēlián","vi":"liên tiếp"},{"hanzi":"频繁","pinyin":"pínfán","vi":"thường xuyên"}],"traditional":"層出"},{"id":"磁场","hanzi":"磁场","pinyin":"cíchǎng","meaning_vi":"từ trường","explanation":"磁 (từ tính/gốm sứ) + 场 (trận).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🧲","examples":[{"type":"basic","zh":"地球有磁场。","pinyin":"Dìqiú yǒu cíchǎng.","vi":"Trái Đất có từ trường."},{"type":"simple","zh":"候鸟能够借助地球磁场辨别飞行方向。","pinyin":"Hòuniǎo nénggòu jièzhù dìqiú cíchǎng biànbié fēixíng fāngxiàng.","vi":"Chim di cư có thể nhờ từ trường Trái Đất để định hướng bay."},{"type":"compound","zh":"如果把手机放在强磁场附近，指南针功能就会失灵。","pinyin":"Rúguǒ bǎshǒu jī fàng zài qiáng cíchǎng fùjìn, zhǐnánzhēn gōngnéng jiù huì shīlíng.","vi":"Nếu đặt điện thoại gần từ trường mạnh, chức năng la bàn sẽ bị hỏng."}],"related":[{"hanzi":"磁铁","pinyin":"cítiě","vi":"nam châm"},{"hanzi":"电场","pinyin":"diànchǎng","vi":"điện trường"},{"hanzi":"磁力","pinyin":"cílì","vi":"lực từ"},{"hanzi":"地磁","pinyin":"dìcí","vi":"từ trường trái đất"}],"traditional":"磁場"},{"id":"词穷","hanzi":"词穷","pinyin":"cíqióng","meaning_vi":"cạn lời, bí từ không cãi lại được","explanation":"词 (từ ngữ) + 穷 (cạn kiệt).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤐","examples":[{"type":"basic","zh":"他被问得词穷了。","pinyin":"Tā bèi wèn de cíqióng le.","vi":"Anh ta bị hỏi đến cạn lời."},{"type":"simple","zh":"面对如此美景，我竟然一时词穷。","pinyin":"Miànduì rúcǐ měijǐng, wǒ jìngrán yìshí cíqióng.","vi":"Trước cảnh đẹp như vậy, tôi bỗng chốc chẳng biết nói gì."},{"type":"compound","zh":"对方一拿出证据，他就词穷理屈，只好认错。","pinyin":"Duìfāng yì náchū zhèngjù, tā jiù cíqióng lǐ qū, zhǐhǎo rèncuò.","vi":"Đối phương vừa đưa ra bằng chứng, anh ta liền cạn lời đuối lý, đành phải nhận sai."}],"related":[{"hanzi":"无言以对","pinyin":"wúyányǐduì","vi":"không còn gì để nói"},{"hanzi":"哑口无言","pinyin":"yǎkǒuwúyán","vi":"câm như hến"},{"hanzi":"理屈词穷","pinyin":"lǐqūcíqióng","vi":"đuối lý cạn lời"},{"hanzi":"语塞","pinyin":"yǔsè","vi":"nghẹn lời"}],"traditional":"詞窮"},{"id":"词性","hanzi":"词性","pinyin":"cíxìng","meaning_vi":"từ loại (danh từ, động từ, tính từ...)","explanation":"词 (词) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🔤","examples":[{"type":"basic","zh":"这个词的词性是什么？","pinyin":"Zhè ge cí de cíxìng shì shénme?","vi":"Từ loại của từ này là gì?"},{"type":"simple","zh":"汉语里很多词的词性会随着语境发生变化。","pinyin":"Hànyǔ lǐ hěn duō cí de cíxìng huì suízhe yǔjìng fāshēng biànhuà.","vi":"Trong tiếng Hán, từ loại của nhiều từ thay đổi theo ngữ cảnh."},{"type":"compound","zh":"只要先判断出词性，就能更快地分析句子结构。","pinyin":"Zhǐyào xiān pànduàn chū cíxìng, jiù néng gèng kuài de fēnxī jùzi jiégòu.","vi":"Chỉ cần xác định từ loại trước là có thể phân tích cấu trúc câu nhanh hơn."}],"related":[{"hanzi":"名词","pinyin":"míngcí","vi":"danh từ"},{"hanzi":"动词","pinyin":"dòngcí","vi":"động từ"},{"hanzi":"形容词","pinyin":"xíngróngcí","vi":"tính từ"},{"hanzi":"词类","pinyin":"cílèi","vi":"từ loại"}],"traditional":"詞性"},{"id":"词义","hanzi":"词义","pinyin":"cíyì","meaning_vi":"nghĩa của từ","explanation":"词 (词) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"查词典弄懂词义。","pinyin":"Chá cídiǎn nòngdǒng cíyì.","vi":"Tra từ điển để hiểu nghĩa của từ."},{"type":"simple","zh":"古汉语中有些词义和现代汉语完全不同。","pinyin":"Gǔhànyǔ zhōng yǒuxiē cíyì hé xiàndài Hànyǔ wánquán bùtóng.","vi":"Trong tiếng Hán cổ, có những nghĩa từ hoàn toàn khác với tiếng Hán hiện đại."},{"type":"compound","zh":"即使认识每一个汉字，也不一定能准确理解词义。","pinyin":"Jíshǐ rènshi měi yí gè hànzì, yě bù yídìng néng zhǔnquè lǐjiě cíyì.","vi":"Dù biết từng chữ Hán, cũng chưa chắc đã hiểu chính xác nghĩa của từ."}],"related":[{"hanzi":"意思","pinyin":"yìsi","vi":"ý nghĩa"},{"hanzi":"本义","pinyin":"běnyì","vi":"nghĩa gốc"},{"hanzi":"引申义","pinyin":"yǐnshēnyì","vi":"nghĩa mở rộng"},{"hanzi":"近义词","pinyin":"jìnyìcí","vi":"từ gần nghĩa"}],"traditional":"詞義"},{"id":"词组","hanzi":"词组","pinyin":"cízǔ","meaning_vi":"cụm từ","explanation":"词 (词) + 组 (tổ chức/tổ hợp).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"请用这个词组造句。","pinyin":"Qǐng yòng zhè ge cízǔ zàojù.","vi":"Hãy đặt câu với cụm từ này."},{"type":"simple","zh":"老师让我们把课文里的固定词组抄在本子上。","pinyin":"Lǎoshī ràng wǒmen bǎ kèwén lǐ de gùdìng cízǔ chāo zài běnzi shàng.","vi":"Cô giáo bảo chúng tôi chép các cụm từ cố định trong bài khóa vào vở."},{"type":"compound","zh":"与其一个个地背单词，不如按词组来记。","pinyin":"Yǔqí yígègè de bèi dāncí, bùrú àn cízǔ lái jì.","vi":"Thay vì học thuộc từng từ đơn, chi bằng ghi nhớ theo cụm từ."}],"related":[{"hanzi":"短语","pinyin":"duǎnyǔ","vi":"cụm từ"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"từ ngữ"},{"hanzi":"句子","pinyin":"jùzi","vi":"câu"},{"hanzi":"搭配","pinyin":"dāpèi","vi":"kết hợp từ"}],"traditional":"詞組"},{"id":"从善如流","hanzi":"从善如流","pinyin":"cóngshàn-rúliú","meaning_vi":"tiếp thu ý kiến đúng đắn nhanh như nước chảy","explanation":"从善如流: theo (从) điều tốt (善) như (如) nước chảy (流) xuống chỗ thấp (Tả Truyện) → sẵn sàng, nhanh chóng tiếp thu ý kiến đúng đắn.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"好领导要从善如流。","pinyin":"Hǎo lǐngdǎo yào cóng shàn rú liú.","vi":"Người lãnh đạo giỏi phải biết tiếp thu ý kiến đúng."},{"type":"simple","zh":"校长从善如流，采纳了学生关于食堂的建议。","pinyin":"Xiàozhǎng cóng shàn rú liú, cǎinàle xuésheng guānyú shítáng de jiànyì.","vi":"Hiệu trưởng sẵn sàng tiếp thu, đã chấp nhận đề xuất của học sinh về nhà ăn."},{"type":"compound","zh":"只要管理者从善如流，员工就愿意提出真实想法。","pinyin":"Zhǐyào guǎnlǐ zhě cóng shàn rú liú, yuángōng jiù yuànyì tíchū zhēnshí xiǎngfǎ.","vi":"Chỉ cần người quản lý biết tiếp thu ý kiến đúng, nhân viên sẽ sẵn lòng nêu suy nghĩ thật."}],"related":[{"hanzi":"虚心","pinyin":"xūxīn","vi":"khiêm tốn"},{"hanzi":"虚怀若谷","pinyin":"xūhuáiruògǔ","vi":"khiêm nhường rộng lượng"},{"hanzi":"采纳","pinyin":"cǎinà","vi":"tiếp thu"},{"hanzi":"刚愎自用","pinyin":"gāngbìzìyòng","vi":"bảo thủ cố chấp"}],"traditional":"從善如流"},{"id":"从众心理","hanzi":"从众心理","pinyin":"cóngzhòngxīnlǐ","meaning_vi":"tâm lý đám đông","explanation":"从 (từ (thời gian/địa điểm)) + 众 (quần chúng/đông đảo) + 心 (tâm lý/tâm huyết) + 理 (lý luận/quản lý).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","nhan-thuc"],"image":"👥","examples":[{"type":"basic","zh":"这是从众心理在作怪。","pinyin":"Zhè shì cóng zhòng xīnlǐ zài zuòguài.","vi":"Đây là do tâm lý đám đông gây ra."},{"type":"simple","zh":"很多人排队买网红奶茶完全是出于从众心理。","pinyin":"Hěn duō rén páiduì mǎi wǎnghóng nǎichá wánquán shì chūyú cóng zhòng xīnlǐ.","vi":"Nhiều người xếp hàng mua trà sữa nổi tiếng trên mạng hoàn toàn vì tâm lý đám đông."},{"type":"compound","zh":"因为存在从众心理，所以股市一跌，很多散户就跟着抛售。","pinyin":"Yīnwèi cúnzài cóng zhòng xīnlǐ, suǒyǐ gǔshì yì diē, hěn duō sǎnhù jiù gēnzhe pāoshòu.","vi":"Vì có tâm lý đám đông nên chứng khoán vừa giảm là nhiều nhà đầu tư nhỏ lẻ liền bán tháo theo."}],"related":[{"hanzi":"随大流","pinyin":"suídàliú","vi":"chạy theo số đông"},{"hanzi":"盲从","pinyin":"mángcóng","vi":"mù quáng theo"},{"hanzi":"随波逐流","pinyin":"suíbōzhúliú","vi":"trôi theo dòng"},{"hanzi":"心理","pinyin":"xīnlǐ","vi":"tâm lý"}],"traditional":"從眾心理"},{"id":"促成","hanzi":"促成","pinyin":"cùchéng","meaning_vi":"thúc đẩy thành công","explanation":"促 (xúc – thúc đẩy) + 成 (thành – hoàn thành) → thúc đẩy cho việc thành công. VD: 促成合作, 促成双方达成协议.","hsk_level":"7-9","tags":["dong-tu"],"image":"🤝","examples":[{"type":"basic","zh":"他促成了这笔交易。","pinyin":"Tā cùchéngle zhè bǐ jiāoyì.","vi":"Anh ấy đã thúc đẩy thương vụ này thành công."},{"type":"simple","zh":"两国领导人的会晤促成了新贸易协定的签署。","pinyin":"Liǎngguó lǐngdǎorén de huìwù cùchéngle xīn màoyì xiédìng de qiānshǔ.","vi":"Cuộc hội đàm giữa lãnh đạo hai nước đã thúc đẩy việc ký kết hiệp định thương mại mới."},{"type":"compound","zh":"如果不是王阿姨热心介绍，就不会促成他们这段婚姻。","pinyin":"Rúguǒ bú shì Wáng āyí rèxīn jièshào, jiù bú huì cùchéng tāmen zhè duàn hūnyīn.","vi":"Nếu không nhờ dì Vương nhiệt tình giới thiệu thì đã không thành cuộc hôn nhân này của họ."}],"related":[{"hanzi":"促进","pinyin":"cùjìn","vi":"thúc đẩy"},{"hanzi":"成全","pinyin":"chéngquán","vi":"giúp thành"},{"hanzi":"推动","pinyin":"tuīdòng","vi":"đẩy mạnh"},{"hanzi":"达成","pinyin":"dáchéng","vi":"đạt được"}]},{"id":"簇新","hanzi":"簇新","pinyin":"cùxīn","meaning_vi":"mới tinh tươm","explanation":"簇 (thốc – cụm, rất) + 新 (tân – mới) → mới tinh, mới toanh; thường nói về quần áo, đồ vật: 一身簇新的衣服.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🆕","examples":[{"type":"basic","zh":"他穿着簇新的西装。","pinyin":"Tā chuānzhe cùxīn de xīzhuāng.","vi":"Anh ấy mặc bộ vest mới tinh."},{"type":"simple","zh":"过年时孩子们都换上了簇新的棉袄。","pinyin":"Guònián shí háizimen dōu huàn shàngle cùxīn de mián'ǎo.","vi":"Dịp Tết bọn trẻ đều thay áo bông mới tinh."},{"type":"compound","zh":"这辆车虽然买了五年，但是保养得像簇新的一样。","pinyin":"Zhè liàng chē suīrán mǎile wǔ nián, dànshì bǎoyǎng de xiàng cùxīn de yíyàng.","vi":"Chiếc xe này tuy mua đã năm năm nhưng được giữ gìn như mới tinh."}],"related":[{"hanzi":"崭新","pinyin":"zhǎnxīn","vi":"mới tinh"},{"hanzi":"全新","pinyin":"quánxīn","vi":"hoàn toàn mới"},{"hanzi":"新颖","pinyin":"xīnyǐng","vi":"mới lạ"},{"hanzi":"破旧","pinyin":"pòjiù","vi":"cũ nát"}]},{"id":"寸步不离","hanzi":"寸步不离","pinyin":"cùnbù-bùlí","meaning_vi":"theo sát không rời nửa bước","explanation":"寸步 (thốn bộ – bước ngắn một tấc) + 不离 (không rời) → không rời nửa bước; luôn theo sát bên cạnh. VD: 寸步不离地照顾.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👣","examples":[{"type":"basic","zh":"小狗寸步不离地跟着他。","pinyin":"Xiǎogǒu cùnbùbùlí de gēnzhe tā.","vi":"Chú chó con theo sát anh ấy không rời nửa bước."},{"type":"simple","zh":"妈妈在病床边寸步不离地守了三天三夜。","pinyin":"Māma zài bìngchuáng biān cùnbùbùlí de shǒule sān tiān sān yè.","vi":"Mẹ túc trực bên giường bệnh suốt ba ngày ba đêm không rời nửa bước."},{"type":"compound","zh":"因为孩子第一次来商场，所以他寸步不离地拉着爸爸的手。","pinyin":"Yīnwèi háizi dìyīcì lái shāngchǎng, suǒyǐ tā cùnbùbùlí de lāzhe bàba de shǒu.","vi":"Vì lần đầu đến trung tâm thương mại nên đứa bé nắm chặt tay bố không rời nửa bước."}],"related":[{"hanzi":"形影不离","pinyin":"xíngyǐngbùlí","vi":"như hình với bóng"},{"hanzi":"寸步不让","pinyin":"cùnbùbúràng","vi":"không nhường nửa bước"},{"hanzi":"紧跟","pinyin":"jǐngēn","vi":"bám sát"},{"hanzi":"朝夕相处","pinyin":"zhāoxīxiāngchǔ","vi":"sớm tối bên nhau"}],"traditional":"寸步不離"},{"id":"存折","hanzi":"存折","pinyin":"cúnzhé","meaning_vi":"sổ tiết kiệm","explanation":"存 (gửi (tiền)) + 折 (gấp giấy).","hsk_level":"7-9","tags":["danh-tu","tien-te","do-vat"],"image":"📘","examples":[{"type":"basic","zh":"存折放在抽屉里。","pinyin":"Cúnzhé fàng zài chōuti lǐ.","vi":"Sổ tiết kiệm để trong ngăn kéo."},{"type":"simple","zh":"奶奶拿着存折去银行取了养老金。","pinyin":"Nǎinai názhe cúnzhé qù yínháng qǔle yǎnglǎojīn.","vi":"Bà nội cầm sổ tiết kiệm đến ngân hàng rút lương hưu."},{"type":"compound","zh":"如果存折丢了，你就得带身份证去银行挂失。","pinyin":"Rúguǒ cúnzhé diū le, nǐ jiù děi dài shēnfènzhèng qù yínháng guàshī.","vi":"Nếu mất sổ tiết kiệm, bạn phải mang căn cước đến ngân hàng báo mất."}],"related":[{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"},{"hanzi":"银行卡","pinyin":"yínhángkǎ","vi":"thẻ ngân hàng"},{"hanzi":"储蓄","pinyin":"chǔxù","vi":"tiết kiệm"},{"hanzi":"银行","pinyin":"yínháng","vi":"ngân hàng"}],"traditional":"存摺"},{"id":"参半","hanzi":"参半","pinyin":"cānbàn","meaning_vi":"một nửa, ngang nhau (vui buồn lẫn lộn)","explanation":"参 (参) + 半 (một nửa).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"网友评价褒贬参半。","pinyin":"Wǎngyǒu píngjià bāobiǎn cānbàn.","vi":"Đánh giá của cư dân mạng khen chê lẫn lộn."},{"type":"simple","zh":"这部新片上映后口碑好坏参半。","pinyin":"Zhè bù xīn piàn shàngyìng hòu kǒubēi hǎohuài cānbàn.","vi":"Bộ phim mới này sau khi công chiếu nhận được đánh giá khen chê lẫn lộn."},{"type":"compound","zh":"虽然儿子考上了外地的大学，但是母亲心里喜忧参半。","pinyin":"Suīrán érzi kǎoshàngle wàidì de dàxué, dànshì mǔqīn xīnlǐ xǐ yōu cānbàn.","vi":"Tuy con trai đỗ đại học ở tỉnh khác, nhưng trong lòng mẹ vừa mừng vừa lo."}],"related":[{"hanzi":"喜忧参半","pinyin":"xǐyōucānbàn","vi":"vừa mừng vừa lo"},{"hanzi":"一半","pinyin":"yíbàn","vi":"một nửa"},{"hanzi":"褒贬参半","pinyin":"bāobiǎncānbàn","vi":"khen chê lẫn lộn"},{"hanzi":"各半","pinyin":"gèbàn","vi":"mỗi bên một nửa"}],"traditional":"參半"},{"id":"参考文献","hanzi":"参考文献","pinyin":"cānkǎowénxiàn","meaning_vi":"tài liệu tham khảo","explanation":"参 (参) + 考 (khảo sát/thi cử) + 文 (văn hóa/văn minh) + 献 (cống hiến).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"论文要列出参考文献。","pinyin":"Lùnwén yào lièchū cānkǎowénxiàn.","vi":"Luận văn phải liệt kê tài liệu tham khảo."},{"type":"simple","zh":"他的毕业论文引用了六十多篇参考文献。","pinyin":"Tā de bìyèlùnwén yǐnyòngle liùshí duō piān cānkǎowénxiàn.","vi":"Luận văn tốt nghiệp của anh ấy trích dẫn hơn sáu mươi tài liệu tham khảo."},{"type":"compound","zh":"如果参考文献格式不规范，论文就可能被退回修改。","pinyin":"Rúguǒ cānkǎowénxiàn géshì bù guīfàn, lùnwén jiù kěnéng bèi tuìhuí xiūgǎi.","vi":"Nếu định dạng tài liệu tham khảo không chuẩn, luận văn có thể bị trả lại để sửa."}],"related":[{"hanzi":"参考","pinyin":"cānkǎo","vi":"tham khảo"},{"hanzi":"文献","pinyin":"wénxiàn","vi":"văn liệu"},{"hanzi":"论文","pinyin":"lùnwén","vi":"luận văn"},{"hanzi":"引用","pinyin":"yǐnyòng","vi":"trích dẫn"}],"traditional":"參考文獻"},{"id":"参谋长","hanzi":"参谋长","pinyin":"cānmóuzhǎng","meaning_vi":"tham mưu trưởng","explanation":"参 (参) + 谋 (mưu cầu/âm mưu) + 长 (dài).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","xa-hoi"],"image":"🎖️","examples":[{"type":"basic","zh":"参谋长下达了命令。","pinyin":"Cānmóuzhǎng xiàdále mìnglìng.","vi":"Tham mưu trưởng đã ra lệnh."},{"type":"simple","zh":"参谋长连夜召集军官们研究作战方案。","pinyin":"Cānmóuzhǎng liányè zhàojí jūnguānmen yánjiū zuòzhàn fāng'àn.","vi":"Tham mưu trưởng triệu tập các sĩ quan suốt đêm để nghiên cứu phương án tác chiến."},{"type":"compound","zh":"他虽然只是从普通士兵做起，但是最终当上了参谋长。","pinyin":"Tā suīrán zhǐshì cóng pǔtōng shìbīng zuò qǐ, dànshì zuìzhōng dāngshàngle cānmóuzhǎng.","vi":"Tuy chỉ bắt đầu từ một người lính bình thường, nhưng cuối cùng ông ấy đã trở thành tham mưu trưởng."}],"related":[{"hanzi":"参谋","pinyin":"cānmóu","vi":"tham mưu"},{"hanzi":"司令","pinyin":"sīlìng","vi":"tư lệnh"},{"hanzi":"军官","pinyin":"jūnguān","vi":"sĩ quan"},{"hanzi":"指挥","pinyin":"zhǐhuī","vi":"chỉ huy"}],"traditional":"參謀長"},{"id":"参赛","hanzi":"参赛","pinyin":"cānsài","meaning_vi":"tham gia thi đấu","explanation":"参 (参) + 赛 (thi đấu).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"他报名参赛了。","pinyin":"Tā bàomíng cānsài le.","vi":"Anh ấy đã đăng ký thi đấu."},{"type":"simple","zh":"本届马拉松共有三万名选手参赛。","pinyin":"Běnjiè mǎlāsōng gòngyǒu sān wànmíng xuǎnshǒu cānsài.","vi":"Giải marathon lần này có tổng cộng ba mươi nghìn vận động viên tham gia."},{"type":"compound","zh":"因为脚踝受了伤，所以她只好放弃参赛。","pinyin":"Yīnwèi jiǎohuái shòule shāng, suǒyǐ tā zhǐhǎo fàngqì cānsài.","vi":"Vì bị thương ở mắt cá chân nên cô ấy đành từ bỏ thi đấu."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"参加","pinyin":"cānjiā","vi":"tham gia"},{"hanzi":"选手","pinyin":"xuǎnshǒu","vi":"tuyển thủ"},{"hanzi":"报名","pinyin":"bàomíng","vi":"đăng ký"}],"traditional":"參賽"},{"id":"参天","hanzi":"参天","pinyin":"cāntiān","meaning_vi":"cao chọc trời (cây cổ thụ)","explanation":"Cụm: 参天大树 (cây cổ thụ cao chọc trời).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"山上古树参天。","pinyin":"Shān shàng gǔshù cāntiān.","vi":"Trên núi cây cổ thụ cao chọc trời."},{"type":"simple","zh":"寺庙门前有两棵参天的银杏树。","pinyin":"Sìmiào ménqián yǒu liǎng kē cāntiān de yín xìngshù.","vi":"Trước cổng chùa có hai cây bạch quả cao vút tận trời."},{"type":"compound","zh":"只要给小树苗足够的时间，它就能长成参天大树。","pinyin":"Zhǐyào gěi xiǎo shùmiáo zúgòu de shíjiān, tā jiù néng zhǎngchéng cāntiān dà shù.","vi":"Chỉ cần cho cây non đủ thời gian, nó sẽ lớn thành cây đại thụ cao chọc trời."}],"related":[{"hanzi":"参天大树","pinyin":"cāntiāndàshù","vi":"cây cổ thụ chọc trời"},{"hanzi":"高耸","pinyin":"gāosǒng","vi":"cao vút"},{"hanzi":"耸立","pinyin":"sǒnglì","vi":"sừng sững"},{"hanzi":"高大","pinyin":"gāodà","vi":"cao lớn"}],"traditional":"參天"},{"id":"参政","hanzi":"参政","pinyin":"cānzhèng","meaning_vi":"tham gia chính trị","explanation":"参 (参) + 政 (chính sách/chính trị).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"妇女有权参政。","pinyin":"Fùnǚ yǒuquán cānzhèng.","vi":"Phụ nữ có quyền tham gia chính trị."},{"type":"simple","zh":"这个国家的女性直到上世纪才获得参政权利。","pinyin":"Zhè ge guójiā de nǚxìng zhídào shàng shìjì cái huòdé cānzhèng quánlì.","vi":"Phụ nữ nước này mãi đến thế kỷ trước mới có quyền tham chính."},{"type":"compound","zh":"只有让更多年轻人参政议政，政策才能反映他们的需求。","pinyin":"Zhǐyǒu ràng gèng duō niánqīngrén cānzhèng yìzhèng, zhèngcè cáinéng fǎnyìng tāmen de xūqiú.","vi":"Chỉ khi để nhiều người trẻ hơn tham gia bàn bạc chính sự, chính sách mới phản ánh được nhu cầu của họ."}],"related":[{"hanzi":"参政议政","pinyin":"cānzhèngyìzhèng","vi":"tham chính nghị chính"},{"hanzi":"政治","pinyin":"zhèngzhì","vi":"chính trị"},{"hanzi":"执政","pinyin":"zhízhèng","vi":"cầm quyền"},{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"}],"traditional":"參政"},{"id":"参展","hanzi":"参展","pinyin":"cānzhǎn","meaning_vi":"tham gia triển lãm","explanation":"参 (参) + 展 (triển lãm/phát triển).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🖼️","examples":[{"type":"basic","zh":"我们公司明年参展。","pinyin":"Wǒmen gōngsī míngnián cānzhǎn.","vi":"Công ty chúng tôi sang năm tham gia triển lãm."},{"type":"simple","zh":"本届车展吸引了两百多家企业参展。","pinyin":"Běnjiè chēzhǎn xīyǐnle liǎng bǎi duō jiā qǐyè cānzhǎn.","vi":"Triển lãm ô tô lần này thu hút hơn hai trăm doanh nghiệp tham gia."},{"type":"compound","zh":"如果样品不能按时完成，我们就只好取消参展计划。","pinyin":"Rúguǒ yàngpǐn bù néng ànshí wánchéng, wǒmen jiù zhǐhǎo qǔxiāo cānzhǎn jìhuà.","vi":"Nếu hàng mẫu không hoàn thành kịp, chúng tôi đành hủy kế hoạch tham gia triển lãm."}],"related":[{"hanzi":"展览","pinyin":"zhǎnlǎn","vi":"triển lãm"},{"hanzi":"展会","pinyin":"zhǎnhuì","vi":"hội chợ triển lãm"},{"hanzi":"参展商","pinyin":"cānzhǎnshāng","vi":"nhà triển lãm"},{"hanzi":"展品","pinyin":"zhǎnpǐn","vi":"vật trưng bày"}],"traditional":"參展"},{"id":"苍翠","hanzi":"苍翠","pinyin":"cāngcuì","meaning_vi":"xanh tươi mướt (cây cối/núi rừng)","explanation":"苍 (苍) + 翠 (xanh biếc/ngọc bích).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"远山一片苍翠。","pinyin":"Yuǎn shān yípiàn cāngcuì.","vi":"Núi xa một màu xanh biếc."},{"type":"simple","zh":"雨后的竹林显得格外苍翠。","pinyin":"Yǔ hòu de zhúlín xiǎnde géwài cāngcuì.","vi":"Rừng trúc sau mưa trông đặc biệt xanh mướt."},{"type":"compound","zh":"虽然已经到了深冬，但是山上的松柏依旧苍翠。","pinyin":"Suīrán yǐjīng dàole shēn dōng, dànshì shān shàng de sōngbǎi yījiù cāngcuì.","vi":"Tuy đã vào giữa mùa đông nhưng tùng bách trên núi vẫn xanh tươi."}],"related":[{"hanzi":"翠绿","pinyin":"cuìlǜ","vi":"xanh biếc"},{"hanzi":"青翠","pinyin":"qīngcuì","vi":"xanh tươi"},{"hanzi":"郁郁葱葱","pinyin":"yùyùcōngcōng","vi":"xanh um tươi tốt"},{"hanzi":"枯黄","pinyin":"kūhuáng","vi":"úa vàng"}],"traditional":"蒼翠"},{"id":"沧海一粟","hanzi":"沧海一粟","pinyin":"cānghǎi-yísù","meaning_vi":"hạt thóc giữa biển khơi (vô cùng nhỏ bé)","explanation":"Cụm từ Tô Thức (Tiền Xích Bích Phú). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"个人不过沧海一粟。","pinyin":"Gèrén búguò cānghǎiyísù.","vi":"Cá nhân chẳng qua chỉ là hạt thóc giữa biển khơi."},{"type":"simple","zh":"我掌握的知识在浩瀚的学问面前只是沧海一粟。","pinyin":"Wǒ zhǎngwò de zhīshi zài hàohàn de xuéwèn miànqián zhǐshì cānghǎiyísù.","vi":"Kiến thức tôi nắm được trước biển học mênh mông chỉ là hạt thóc giữa biển khơi."},{"type":"compound","zh":"与宇宙相比，地球不过是沧海一粟，所以人类更应保护它。","pinyin":"Yǔ yǔzhòu xiāngbǐ, dìqiú búguò shì cānghǎiyísù, suǒyǐ rénlèi gèng yīng bǎohù tā.","vi":"So với vũ trụ, Trái Đất chỉ như hạt thóc giữa biển khơi, vì vậy loài người càng nên bảo vệ nó."}],"related":[{"hanzi":"九牛一毛","pinyin":"jiǔniúyìmáo","vi":"chín trâu một sợi lông"},{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"không đáng kể"},{"hanzi":"渺小","pinyin":"miǎoxiǎo","vi":"nhỏ bé"},{"hanzi":"微乎其微","pinyin":"wēihūqíwēi","vi":"vô cùng nhỏ bé"}],"traditional":"滄海一粟"},{"id":"苍老","hanzi":"苍老","pinyin":"cānglǎo","meaning_vi":"già nua, tiều tụy","explanation":"苍 (thương – xanh xám, bạc) + 老 (lão – già) → già nua, tiều tụy (vẻ ngoài, giọng nói). VD: 他看起来苍老了许多.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"父亲苍老了许多。","pinyin":"Fùqīn cānglǎole xǔduō.","vi":"Cha đã già đi nhiều."},{"type":"simple","zh":"电话那头传来外婆苍老的声音。","pinyin":"Diànhuà nà tóu chuánlái wàipó cānglǎo de shēngyīn.","vi":"Đầu dây bên kia vọng lại giọng nói già nua của bà ngoại."},{"type":"compound","zh":"他才四十岁，可是因为常年操劳，看上去十分苍老。","pinyin":"Tā cái sìshí suì, kěshì yīnwèi chángnián cāoláo, kànshàngqù shífēn cānglǎo.","vi":"Anh ấy mới bốn mươi tuổi, nhưng vì quanh năm vất vả nên trông rất già nua."}],"related":[{"hanzi":"衰老","pinyin":"shuāilǎo","vi":"già yếu"},{"hanzi":"老态龙钟","pinyin":"lǎotàilóngzhōng","vi":"già lụ khụ"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"trẻ trung"},{"hanzi":"憔悴","pinyin":"qiáocuì","vi":"tiều tụy"}],"traditional":"蒼老"},{"id":"苍茫","hanzi":"苍茫","pinyin":"cāngmáng","meaning_vi":"mênh mông mịt mù","explanation":"苍 (苍) + 茫 (mênh mông/mờ mịt).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌫️","examples":[{"type":"basic","zh":"窗外暮色苍茫。","pinyin":"Chuāng wài mùsè cāngmáng.","vi":"Ngoài cửa sổ hoàng hôn mịt mù."},{"type":"simple","zh":"我们站在山顶眺望苍茫的大海。","pinyin":"Wǒmen zhàn zài shāndǐng tiàowàng cāngmáng de dàhǎi.","vi":"Chúng tôi đứng trên đỉnh núi nhìn ra biển cả mênh mông."},{"type":"compound","zh":"船一驶出港口，四周就只剩下苍茫的海水。","pinyin":"Chuán yì shǐchū gǎngkǒu, sìzhōu jiù zhǐ shèngxià cāngmáng de hǎishuǐ.","vi":"Thuyền vừa rời cảng, bốn bề chỉ còn lại làn nước biển mênh mông."}],"related":[{"hanzi":"茫茫","pinyin":"mángmáng","vi":"mênh mông"},{"hanzi":"辽阔","pinyin":"liáokuò","vi":"bao la"},{"hanzi":"渺茫","pinyin":"miǎománg","vi":"mờ mịt"},{"hanzi":"苍天","pinyin":"cāngtiān","vi":"trời xanh"}],"traditional":"蒼茫"},{"id":"操守","hanzi":"操守","pinyin":"cāoshǒu","meaning_vi":"phẩm hạnh, tiết tháo, đạo đức nghề nghiệp","explanation":"操 + 守 (giữ gìn).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"⚖️","examples":[{"type":"basic","zh":"他的操守令人敬佩。","pinyin":"Tā de cāoshǒu lìngrén jìngpèi.","vi":"Phẩm hạnh của ông ấy khiến người ta kính phục."},{"type":"simple","zh":"记者应当坚守新闻职业操守。","pinyin":"Jìzhě yīngdāng jiānshǒu xīnwén zhíyè cāoshǒu.","vi":"Phóng viên cần giữ vững đạo đức nghề báo."},{"type":"compound","zh":"即使面对巨额贿赂，这位法官也没有丢掉自己的操守。","pinyin":"Jíshǐ miànduì jù'é huìlù, zhè wèi fǎguān yě méiyǒu diūdiào zìjǐ de cāoshǒu.","vi":"Dù đối mặt với khoản hối lộ khổng lồ, vị thẩm phán này vẫn không đánh mất tiết tháo của mình."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"节操","pinyin":"jiécāo","vi":"tiết tháo"},{"hanzi":"职业道德","pinyin":"zhíyèdàodé","vi":"đạo đức nghề nghiệp"},{"hanzi":"品行","pinyin":"pǐnxíng","vi":"phẩm hạnh"}]},{"id":"操作系统","hanzi":"操作系统","pinyin":"cāozuòxìtǒng","meaning_vi":"hệ điều hành (OS)","explanation":"操作 (thao tác – vận hành) + 系统 (hệ thống) → hệ điều hành máy tính, điện thoại. VD: 安卓操作系统.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"电脑的操作系统要更新了。","pinyin":"Diànnǎo de cāozuòxìtǒng yào gēngxīn le.","vi":"Hệ điều hành của máy tính cần cập nhật rồi."},{"type":"simple","zh":"这款手机搭载了公司自主研发的操作系统。","pinyin":"Zhè kuǎn shǒujī dāzàile gōngsī zìzhǔ yánfā de cāozuòxìtǒng.","vi":"Mẫu điện thoại này chạy hệ điều hành do công ty tự nghiên cứu phát triển."},{"type":"compound","zh":"如果操作系统版本太旧，这个软件就无法安装。","pinyin":"Rúguǒ cāozuòxìtǒng bǎnběn tài jiù, zhè ge ruǎnjiàn jiù wúfǎ ānzhuāng.","vi":"Nếu phiên bản hệ điều hành quá cũ thì phần mềm này không thể cài đặt."}],"related":[{"hanzi":"系统","pinyin":"xìtǒng","vi":"hệ thống"},{"hanzi":"软件","pinyin":"ruǎnjiàn","vi":"phần mềm"},{"hanzi":"电脑","pinyin":"diànnǎo","vi":"máy tính"},{"hanzi":"操作","pinyin":"cāozuò","vi":"thao tác"}],"traditional":"操作系統"},{"id":"粗制滥造","hanzi":"粗制滥造","pinyin":"cūzhì-lànzào","meaning_vi":"sản xuất ẩu tả kém chất lượng chạy theo số lượng","explanation":"粗制滥造: làm (制) cẩu thả (粗), chế tạo (造) bừa bãi (滥) → sản xuất ẩu, chạy theo số lượng mà không chú ý chất lượng.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"⚠️","examples":[{"type":"basic","zh":"这批家具粗制滥造。","pinyin":"Zhè pī jiājù cūzhìlànzào.","vi":"Lô đồ nội thất này làm ẩu tả."},{"type":"simple","zh":"市场上粗制滥造的玩具存在严重安全隐患。","pinyin":"Shìchǎng shàng cūzhìlànzào de wánjù cúnzài yánzhòng ānquán yǐnhuàn.","vi":"Đồ chơi làm ẩu tả trên thị trường tiềm ẩn nguy cơ mất an toàn nghiêm trọng."},{"type":"compound","zh":"一旦企业为了赶工期而粗制滥造，就会失去顾客的信任。","pinyin":"Yídàn qǐyè wèile gǎn gōngqī ér cūzhìlànzào, jiù huì shīqù gùkè de xìnrèn.","vi":"Một khi doanh nghiệp làm ẩu để kịp tiến độ thì sẽ mất lòng tin của khách hàng."}],"related":[{"hanzi":"偷工减料","pinyin":"tōugōngjiǎnliào","vi":"ăn bớt vật liệu"},{"hanzi":"粗糙","pinyin":"cūcāo","vi":"thô ráp kém"},{"hanzi":"精益求精","pinyin":"jīngyìqiújīng","vi":"tinh càng thêm tinh"},{"hanzi":"精雕细琢","pinyin":"jīngdiāoxìzhuó","vi":"chạm trổ tỉ mỉ"}],"traditional":"粗製濫造"},{"id":"采风","hanzi":"采风","pinyin":"cǎifēng","meaning_vi":"đi thực tế sưu tầm văn hóa dân gian / sáng tác","explanation":"采 (thu hái) + 风 (phong tục).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📸","examples":[{"type":"basic","zh":"画家们下乡采风。","pinyin":"Huàjiāmen xiàxiāng cǎifēng.","vi":"Các họa sĩ về nông thôn đi thực tế sáng tác."},{"type":"simple","zh":"作曲家专程到云南少数民族村寨采风。","pinyin":"Zuòqǔjiā zhuānchéng dào Yúnnán shǎoshù mínzú cūnzhài cǎifēng.","vi":"Nhà soạn nhạc đến tận các bản làng dân tộc thiểu số ở Vân Nam để sưu tầm dân ca."},{"type":"compound","zh":"只有深入农村采风，作家才能写出有泥土气息的作品。","pinyin":"Zhǐyǒu shēnrù nóngcūn cǎifēng, zuòjiā cáinéng xiě chū yǒu nítǔ qìxī de zuòpǐn.","vi":"Chỉ khi đi sâu vào nông thôn thực tế, nhà văn mới viết được tác phẩm mang hơi thở đồng quê."}],"related":[{"hanzi":"采访","pinyin":"cǎifǎng","vi":"phỏng vấn"},{"hanzi":"民歌","pinyin":"míngē","vi":"dân ca"},{"hanzi":"写生","pinyin":"xiěshēng","vi":"vẽ ký họa"},{"hanzi":"民俗","pinyin":"mínsú","vi":"phong tục dân gian"}],"traditional":"採風"},{"id":"惨不忍睹","hanzi":"惨不忍睹","pinyin":"cǎnbù-rěndǔ","meaning_vi":"thảm thương không nỡ nhìn","explanation":"惨 (thảm – thê thảm) + 不忍 (không nỡ) 睹 (đổ – nhìn) → thảm đến mức không nỡ nhìn; tả cảnh tai nạn, tàn phá thê lương.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😢","examples":[{"type":"basic","zh":"车祸现场惨不忍睹。","pinyin":"Chēhuò xiànchǎng cǎnbùrěndǔ.","vi":"Hiện trường tai nạn thảm khốc không nỡ nhìn."},{"type":"simple","zh":"地震过后整个小镇惨不忍睹。","pinyin":"Dìzhèn guòhòu zhěnggè xiǎozhèn cǎnbùrěndǔ.","vi":"Sau trận động đất, cả thị trấn nhỏ tan hoang không nỡ nhìn."},{"type":"compound","zh":"因为他第一次自己剪头发，所以剪得惨不忍睹。","pinyin":"Yīnwèi tā dìyīcì zìjǐ jiǎntóufa, suǒyǐ jiǎn de cǎnbùrěndǔ.","vi":"Vì lần đầu tự cắt tóc nên anh ấy cắt thảm họa đến mức không dám nhìn."}],"related":[{"hanzi":"目不忍睹","pinyin":"mùbùrěndǔ","vi":"không nỡ nhìn"},{"hanzi":"惨烈","pinyin":"cǎnliè","vi":"thảm khốc"},{"hanzi":"悲惨","pinyin":"bēicǎn","vi":"bi thảm"},{"hanzi":"触目惊心","pinyin":"chùmùjīngxīn","vi":"nhìn mà kinh hãi"}],"traditional":"慘不忍睹"},{"id":"惨剧","hanzi":"惨剧","pinyin":"cǎnjù","meaning_vi":"thảm kịch","explanation":"惨 (惨) + 剧 (kịch/dữ dội).","hsk_level":"7-9","tags":["danh-tu"],"image":"😢","examples":[{"type":"basic","zh":"这是一场惨剧。","pinyin":"Zhè shì yì chǎng cǎnjù.","vi":"Đây là một thảm kịch."},{"type":"simple","zh":"酒后驾车最终酿成了一家三口遇难的惨剧。","pinyin":"Jiǔhòu jiàchē zuìzhōng niàngchéngle yìjiā sān kǒu yùnàn de cǎnjù.","vi":"Lái xe sau khi uống rượu cuối cùng đã gây ra thảm kịch cả gia đình ba người tử nạn."},{"type":"compound","zh":"如果工厂早点安装消防设备，这场惨剧就不会发生。","pinyin":"Rúguǒ gōngchǎng zǎodiǎn ānzhuāng xiāofáng shèbèi, zhè chǎng cǎnjù jiù bú huì fāshēng.","vi":"Nếu nhà máy lắp thiết bị phòng cháy sớm hơn thì thảm kịch này đã không xảy ra."}],"related":[{"hanzi":"悲剧","pinyin":"bēijù","vi":"bi kịch"},{"hanzi":"惨案","pinyin":"cǎn'àn","vi":"thảm án"},{"hanzi":"喜剧","pinyin":"xǐjù","vi":"hài kịch"},{"hanzi":"灾难","pinyin":"zāinàn","vi":"tai họa"}],"traditional":"慘劇"},{"id":"惨烈","hanzi":"惨烈","pinyin":"cǎnliè","meaning_vi":"thảm khốc, ác liệt","explanation":"惨 (惨) + 烈 (mãnh liệt/anh liệt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"战斗十分惨烈。","pinyin":"Zhàndòu shífēn cǎnliè.","vi":"Trận chiến vô cùng ác liệt."},{"type":"simple","zh":"这场惨烈的车祸造成了六人死亡。","pinyin":"Zhè chǎng cǎnliè de chēhuò zào chéngle liù rén sǐwáng.","vi":"Vụ tai nạn thảm khốc này đã khiến sáu người chết."},{"type":"compound","zh":"虽然最后赢了比赛，但是球队付出的代价相当惨烈。","pinyin":"Suīrán zuìhòu yíngle bǐsài, dànshì qiúduì fùchū de dàijià xiāngdāng cǎnliè.","vi":"Tuy cuối cùng thắng trận, nhưng cái giá đội bóng phải trả khá thảm khốc."}],"related":[{"hanzi":"惨重","pinyin":"cǎnzhòng","vi":"nặng nề thảm hại"},{"hanzi":"激烈","pinyin":"jīliè","vi":"kịch liệt"},{"hanzi":"悲壮","pinyin":"bēizhuàng","vi":"bi tráng"},{"hanzi":"残酷","pinyin":"cánkù","vi":"tàn khốc"}],"traditional":"慘烈"},{"id":"草菅人命","hanzi":"草菅人命","pinyin":"cǎojiān-rénmìng","meaning_vi":"coi mạng người như cỏ rác","explanation":"草菅人命: coi mạng người (人命) như cỏ dại (草菅) → tùy tiện giết người, xem nhẹ sinh mạng. Thường dùng để lên án quan lại tàn ác.","hsk_level":"7-9","tags":["thanh-ngu","phap-luat"],"image":"⚠️","examples":[{"type":"basic","zh":"他们竟然草菅人命！","pinyin":"Tāmen jìngrán cǎojiānrénmìng!","vi":"Bọn họ lại dám coi mạng người như cỏ rác!"},{"type":"simple","zh":"这家黑诊所草菅人命，终于被警方查封了。","pinyin":"Zhè jiā hēi zhěnsuǒ cǎojiānrénmìng, zhōngyú bèi jǐngfāng cháfēng le.","vi":"Phòng khám chui coi mạng người như cỏ rác này cuối cùng đã bị cảnh sát niêm phong."},{"type":"compound","zh":"如果矿主为了利润而草菅人命，就必须受到法律严惩。","pinyin":"Rúguǒ kuàngzhǔ wèile lìrùn ér cǎojiānrénmìng, jiù bìxū shòudào fǎlǜ yánchéng.","vi":"Nếu chủ mỏ vì lợi nhuận mà coi mạng người như cỏ rác thì phải bị pháp luật trừng trị nghiêm khắc."}],"related":[{"hanzi":"滥杀无辜","pinyin":"lànshāwúgū","vi":"giết hại vô tội"},{"hanzi":"残暴","pinyin":"cánbào","vi":"tàn bạo"},{"hanzi":"人命关天","pinyin":"rénmìngguāntiān","vi":"mạng người hệ trọng"},{"hanzi":"冷血","pinyin":"lěngxuè","vi":"máu lạnh"}]},{"id":"草坪","hanzi":"草坪","pinyin":"cǎopíng","meaning_vi":"bãi cỏ","explanation":"草 (草) + 坪 (bãi đất bằng).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌿","examples":[{"type":"basic","zh":"请勿践踏草坪。","pinyin":"Qǐngwù jiàntà cǎopíng.","vi":"Xin đừng giẫm lên bãi cỏ."},{"type":"simple","zh":"周末很多家庭在公园草坪上野餐。","pinyin":"Zhōumò hěn duō jiātíng zài gōngyuán cǎopíng shàng yěcān.","vi":"Cuối tuần nhiều gia đình đi dã ngoại trên bãi cỏ công viên."},{"type":"compound","zh":"只要连续几天不下雨，球场的草坪就会变得干黄。","pinyin":"Zhǐyào liánxù jǐtiān bú xiàyǔ, qiúchǎng de cǎopíng jiù huì biànde gān huáng.","vi":"Chỉ cần mấy ngày liền không mưa, bãi cỏ sân bóng sẽ trở nên khô vàng."}],"related":[{"hanzi":"草地","pinyin":"cǎodì","vi":"bãi cỏ"},{"hanzi":"草原","pinyin":"cǎoyuán","vi":"thảo nguyên"},{"hanzi":"绿地","pinyin":"lǜdì","vi":"bãi cỏ xanh"},{"hanzi":"割草机","pinyin":"gēcǎojī","vi":"máy cắt cỏ"}]},{"id":"草药","hanzi":"草药","pinyin":"cǎoyào","meaning_vi":"thảo dược, thuốc nam","explanation":"草 (thảo – cỏ, cây) + 药 (dược – thuốc) → thảo dược, thuốc làm từ cây cỏ (dùng trong Đông y). VD: 中草药.","hsk_level":"7-9","tags":["danh-tu","suc-khoe","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"奶奶熬了草药。","pinyin":"Nǎinai áole cǎoyào.","vi":"Bà nội đã sắc thuốc nam."},{"type":"simple","zh":"这位老中医上山采了一筐治咳嗽的草药。","pinyin":"Zhè wèi lǎo zhōngyī shàngshān cǎile yì kuāng zhì késou de cǎoyào.","vi":"Vị lương y già lên núi hái một giỏ thảo dược trị ho."},{"type":"compound","zh":"草药虽然是天然的，但是乱吃也会伤身体。","pinyin":"Cǎoyào suīrán shì tiānrán de, dànshì luàn chī yě huì shāng shēntǐ.","vi":"Thảo dược tuy là tự nhiên nhưng dùng bừa cũng hại sức khỏe."}],"related":[{"hanzi":"中药","pinyin":"zhōngyào","vi":"thuốc Bắc"},{"hanzi":"药材","pinyin":"yàocái","vi":"dược liệu"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"},{"hanzi":"西药","pinyin":"xīyào","vi":"thuốc Tây"}],"traditional":"草藥"},{"id":"草案","hanzi":"草案","pinyin":"cǎo'àn","meaning_vi":"dự thảo, bản thảo","explanation":"草 (sơ thảo) + 案 (văn kiện).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📄","examples":[{"type":"basic","zh":"草案已经提交了。","pinyin":"Cǎo'àn yǐjīng tíjiāo le.","vi":"Bản dự thảo đã được nộp."},{"type":"simple","zh":"人大常委会正在审议这部法律草案。","pinyin":"Réndà chángwěihuì zhèngzài shěnyì zhè bù fǎlǜ cǎo'àn.","vi":"Ủy ban Thường vụ Đại hội đại biểu nhân dân đang thẩm định dự thảo luật này."},{"type":"compound","zh":"草案一公布，就收到了上万条公众意见。","pinyin":"Cǎo'àn yì gōngbù, jiù shōudàole shàngwàn tiáo gōngzhòng yìjiàn.","vi":"Bản dự thảo vừa công bố đã nhận được hàng vạn ý kiến của công chúng."}],"related":[{"hanzi":"草稿","pinyin":"cǎogǎo","vi":"bản nháp"},{"hanzi":"方案","pinyin":"fāng'àn","vi":"phương án"},{"hanzi":"法案","pinyin":"fǎ'àn","vi":"dự luật"},{"hanzi":"定稿","pinyin":"dìnggǎo","vi":"bản chính thức"}]},{"id":"此地无银三百两","hanzi":"此地无银三百两","pinyin":"cǐdì wú yín sān bǎi liǎng","meaning_vi":"lạy ông tôi ở bụi này (càng giấu càng lộ)","explanation":"Truyện cười dân gian / Ngạn ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💰","examples":[{"type":"basic","zh":"这真是此地无银三百两。","pinyin":"Zhè zhēn shì cǐdìwúyínsānbǎiliǎng.","vi":"Đây đúng là lạy ông tôi ở bụi này."},{"type":"simple","zh":"他一再声明自己没偷看，反而像是此地无银三百两。","pinyin":"Tā yízài shēngmíng zìjǐ méi tōukàn, fǎn'ér xiàng shì cǐdìwúyínsānbǎiliǎng.","vi":"Anh ta liên tục khẳng định mình không nhìn trộm, ngược lại càng giống lạy ông tôi ở bụi này."},{"type":"compound","zh":"你越是急着解释，别人就越觉得你此地无银三百两。","pinyin":"Nǐ yuè shì jízhe jiěshì, biérén jiù yuè juéde nǐ cǐdìwúyínsānbǎiliǎng.","vi":"Bạn càng vội vàng giải thích, người khác càng thấy bạn có tật giật mình."}],"related":[{"hanzi":"欲盖弥彰","pinyin":"yùgàimízhāng","vi":"càng giấu càng lộ"},{"hanzi":"不打自招","pinyin":"bùdǎzìzhāo","vi":"chưa khảo đã xưng"},{"hanzi":"自欺欺人","pinyin":"zìqīqīrén","vi":"dối mình dối người"},{"hanzi":"掩耳盗铃","pinyin":"yǎn'ěrdàolíng","vi":"bịt tai trộm chuông"}],"traditional":"此地無銀三百兩"},{"id":"道德观","hanzi":"道德观","pinyin":"dàodéguān","meaning_vi":"quan niệm đạo đức","explanation":"道德 (đạo đức) + 观 (quan – quan điểm) → quan niệm đạo đức, cách nhìn về đúng sai, thiện ác. VD: 树立正确的道德观.","hsk_level":"7-9","tags":["danh-tu","van-hoa","nhan-thuc"],"image":"⚖️","examples":[{"type":"basic","zh":"他的道德观很传统。","pinyin":"Tā de dàodéguān hěn chuántǒng.","vi":"Quan niệm đạo đức của ông ấy rất truyền thống."},{"type":"simple","zh":"父母的言传身教深刻影响着孩子的道德观。","pinyin":"Fùmǔ de yánchuánshēnjiào shēnkè yǐngxiǎngzhe háizi de dàodéguān.","vi":"Lời dạy và tấm gương của cha mẹ ảnh hưởng sâu sắc đến quan niệm đạo đức của con cái."},{"type":"compound","zh":"虽然两代人的道德观不同，但是彼此可以互相理解。","pinyin":"Suīrán liǎngdàirén de dàodéguān bùtóng, dànshì bǐcǐ kěyǐ hùxiāng lǐjiě.","vi":"Tuy quan niệm đạo đức của hai thế hệ khác nhau nhưng vẫn có thể hiểu nhau."}],"related":[{"hanzi":"价值观","pinyin":"jiàzhíguān","vi":"giá trị quan"},{"hanzi":"世界观","pinyin":"shìjièguān","vi":"thế giới quan"},{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"人生观","pinyin":"rénshēngguān","vi":"nhân sinh quan"}],"traditional":"道德觀"},{"id":"得失","hanzi":"得失","pinyin":"déshī","meaning_vi":"được và mất, lợi hại","explanation":"得 (phải) + 失 (mất đi/sai sót).","hsk_level":"7-9","tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"不要太计较得失。","pinyin":"Bú yào tài jìjiào déshī.","vi":"Đừng quá so đo được mất."},{"type":"simple","zh":"做重大决定前要仔细权衡利弊得失。","pinyin":"Zuò zhòngdà juédìng qián yào zǐxì quánhéng lìbì déshī.","vi":"Trước khi đưa ra quyết định quan trọng cần cân nhắc kỹ lợi hại được mất."},{"type":"compound","zh":"只要尽了全力，就不必在意一时的得失。","pinyin":"Zhǐyào jìnle quánlì, jiù búbì zàiyì yìshí de déshī.","vi":"Chỉ cần đã dốc hết sức thì không cần bận tâm đến được mất nhất thời."}],"related":[{"hanzi":"利弊","pinyin":"lìbì","vi":"lợi hại"},{"hanzi":"患得患失","pinyin":"huàndéhuànshī","vi":"lo được lo mất"},{"hanzi":"得不偿失","pinyin":"débùchángshī","vi":"được không bù mất"},{"hanzi":"成败","pinyin":"chéngbài","vi":"thành bại"}]},{"id":"电报","hanzi":"电报","pinyin":"diànbào","meaning_vi":"điện báo","explanation":"电 (điện) + 报 (báo – báo tin) → điện báo, bức điện tín (phương thức liên lạc cũ). VD: 发电报.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📠","examples":[{"type":"basic","zh":"他发了一封电报。","pinyin":"Tā fāle yì fēng diànbào.","vi":"Anh ấy đã gửi một bức điện báo."},{"type":"simple","zh":"爷爷还保存着当年部队寄来的那份电报。","pinyin":"Yéye hái bǎocúnzhe dāngnián bùduì jì lái de nà fèn diànbào.","vi":"Ông nội vẫn còn giữ bức điện báo mà đơn vị gửi về năm ấy."},{"type":"compound","zh":"因为以前电报按字收费，所以人们写得非常简短。","pinyin":"Yīnwèi yǐqián diànbào àn zì shōufèi, suǒyǐ rénmen xiě de fēicháng jiǎnduǎn.","vi":"Vì trước đây điện báo tính phí theo chữ nên người ta viết rất ngắn gọn."}],"related":[{"hanzi":"电话","pinyin":"diànhuà","vi":"điện thoại"},{"hanzi":"电讯","pinyin":"diànxùn","vi":"điện tín"},{"hanzi":"发电报","pinyin":"fādiànbào","vi":"gửi điện báo"},{"hanzi":"信件","pinyin":"xìnjiàn","vi":"thư từ"}],"traditional":"電報"},{"id":"电磁波","hanzi":"电磁波","pinyin":"diàncíbō","meaning_vi":"sóng điện từ","explanation":"电 (电) + 磁 (từ tính/gốm sứ) + 波 (波).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"📡","examples":[{"type":"basic","zh":"手机靠电磁波通信。","pinyin":"Shǒujī kào diàncíbō tōngxìn.","vi":"Điện thoại liên lạc nhờ sóng điện từ."},{"type":"simple","zh":"微波炉利用电磁波使食物中的水分子振动发热。","pinyin":"Wēibōlú lìyòng diàncíbō shǐ shíwù zhōng de shuǐ fēnzǐ zhèndòng fārè.","vi":"Lò vi sóng dùng sóng điện từ làm phân tử nước trong thức ăn dao động sinh nhiệt."},{"type":"compound","zh":"电磁波虽然看不见，但是它在生活中无处不在。","pinyin":"Diàncíbō suīrán kànbujiàn, dànshì tā zài shēnghuó zhōng wúchù bú zài.","vi":"Sóng điện từ tuy không nhìn thấy nhưng có mặt khắp nơi trong cuộc sống."}],"related":[{"hanzi":"电磁","pinyin":"diàncí","vi":"điện từ"},{"hanzi":"辐射","pinyin":"fúshè","vi":"bức xạ"},{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"},{"hanzi":"频率","pinyin":"pínlǜ","vi":"tần số"}],"traditional":"電磁波"},{"id":"电影节","hanzi":"电影节","pinyin":"diànyǐngjié","meaning_vi":"liên hoan phim","explanation":"电 (电) + 影 (ảnh hưởng/hình ảnh) + 节 (节).","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🎬","examples":[{"type":"basic","zh":"电影节明天开幕。","pinyin":"Diànyǐngjié míngtiān kāimù.","vi":"Liên hoan phim khai mạc vào ngày mai."},{"type":"simple","zh":"这部小成本电影在戛纳电影节上获得了大奖。","pinyin":"Zhè bù xiǎo chéngběn diànyǐng zài Jiánà diànyǐngjié shàng huòdéle dàjiǎng.","vi":"Bộ phim kinh phí thấp này đã giành giải lớn tại Liên hoan phim Cannes."},{"type":"compound","zh":"电影节一开幕，城里的酒店就一房难求。","pinyin":"Diànyǐngjié yì kāimù, chénglǐ de jiǔdiàn jiù yì fáng nán qiú.","vi":"Liên hoan phim vừa khai mạc, khách sạn trong thành phố đã cháy phòng."}],"related":[{"hanzi":"电影","pinyin":"diànyǐng","vi":"phim điện ảnh"},{"hanzi":"颁奖典礼","pinyin":"bānjiǎngdiǎnlǐ","vi":"lễ trao giải"},{"hanzi":"影展","pinyin":"yǐngzhǎn","vi":"liên hoan phim"},{"hanzi":"红毯","pinyin":"hóngtǎn","vi":"thảm đỏ"}],"traditional":"電影節"},{"id":"电子商务","hanzi":"电子商务","pinyin":"diànzǐshāngwù","meaning_vi":"thương mại điện tử (E-commerce)","explanation":"电子 (điện tử) + 商务 (thương vụ – hoạt động thương mại) → thương mại điện tử, mua bán qua mạng; viết tắt 电商.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"他在学电子商务。","pinyin":"Tā zài xué diànzǐshāngwù.","vi":"Anh ấy đang học thương mại điện tử."},{"type":"simple","zh":"电子商务让偏远山区的水果卖到了全国各地。","pinyin":"Diànzǐshāngwù ràng piānyuǎn shānqū de shuǐguǒ mài dàole quánguó gèdì.","vi":"Thương mại điện tử giúp trái cây vùng núi xa xôi bán được khắp cả nước."},{"type":"compound","zh":"因为电子商务发展迅速，所以很多实体店不得不转型。","pinyin":"Yīnwèi diànzǐshāngwù fāzhǎn xùnsù, suǒyǐ hěn duō shítǐdiàn bùdébù zhuǎnxíng.","vi":"Vì thương mại điện tử phát triển nhanh nên nhiều cửa hàng truyền thống buộc phải chuyển đổi."}],"related":[{"hanzi":"电商","pinyin":"diànshāng","vi":"thương mại điện tử"},{"hanzi":"网购","pinyin":"wǎnggòu","vi":"mua sắm online"},{"hanzi":"网店","pinyin":"wǎngdiàn","vi":"cửa hàng online"},{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"}],"traditional":"電子商務"},{"id":"点睛之笔","hanzi":"点睛之笔","pinyin":"diǎnjīng-zhībǐ","meaning_vi":"nét chấm phá đắt giá nhất","explanation":"点 (giờ (đồng hồ)) + 睛 (睛) + 之 (của (trợ từ văn viết)) + 笔 (bút).","hsk_level":"7-9","tags":["thanh-ngu","van-hoa","giai-tri"],"image":"🐉","examples":[{"type":"basic","zh":"这句话是点睛之笔。","pinyin":"Zhè jù huà shì diǎnjīngzhībǐ.","vi":"Câu nói này là nét chấm phá đắt giá nhất."},{"type":"simple","zh":"结尾那段钢琴独奏堪称整部电影的点睛之笔。","pinyin":"Jiéwěi nà duàn gāngqín dúzòu kānchēng zhěng bù diànyǐng de diǎnjīngzhībǐ.","vi":"Đoạn độc tấu piano ở cuối có thể nói là điểm nhấn đắt giá của cả bộ phim."},{"type":"compound","zh":"客厅虽然装修简单，但是那幅山水画成了点睛之笔。","pinyin":"Kètīng suīrán zhuāngxiū jiǎndān, dànshì nà fú shānshuǐhuà chéngle diǎnjīngzhībǐ.","vi":"Phòng khách tuy trang trí đơn giản nhưng bức tranh sơn thủy kia đã trở thành điểm nhấn đắt giá."}],"related":[{"hanzi":"画龙点睛","pinyin":"huàlóngdiǎnjīng","vi":"vẽ rồng điểm mắt"},{"hanzi":"亮点","pinyin":"liàngdiǎn","vi":"điểm sáng"},{"hanzi":"神来之笔","pinyin":"shénláizhībǐ","vi":"nét bút thần"},{"hanzi":"画蛇添足","pinyin":"huàshétiānzú","vi":"vẽ rắn thêm chân"}],"traditional":"點睛之筆"},{"id":"点赞","hanzi":"点赞","pinyin":"diǎnzàn","meaning_vi":"thả tim, nhấn thích (like)","explanation":"点 (nhấn) + 赞 (khen ngợi). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"👍","examples":[{"type":"basic","zh":"谢谢你给我点赞。","pinyin":"Xièxie nǐ gěi wǒ diǎnzàn.","vi":"Cảm ơn bạn đã thả tim cho mình."},{"type":"simple","zh":"她发的旅行照片一晚上收到了五百多个点赞。","pinyin":"Tā fā de lǚxíng zhàopiàn yì wǎnshang shōudàole wǔ bǎi duōgè diǎnzàn.","vi":"Ảnh du lịch cô ấy đăng nhận được hơn năm trăm lượt thích chỉ trong một buổi tối."},{"type":"compound","zh":"他一发朋友圈，远在老家的妈妈就第一个点赞。","pinyin":"Tā yìfā péngyouquān, yuǎn zài lǎojiā de māma jiù dìyī gè diǎnzàn.","vi":"Anh ấy vừa đăng bài lên WeChat là người mẹ ở quê liền thả tim đầu tiên."}],"related":[{"hanzi":"朋友圈","pinyin":"péngyouquān","vi":"vòng bạn bè WeChat"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"},{"hanzi":"转发","pinyin":"zhuǎnfā","vi":"chia sẻ"},{"hanzi":"粉丝","pinyin":"fěnsī","vi":"người hâm mộ"}],"traditional":"點讚"},{"id":"点赞之交","hanzi":"点赞之交","pinyin":"diǎnzànzhījiāo","meaning_vi":"mối quan hệ xã giao chỉ tương tác like trên mạng xã hội","explanation":"点赞 (nhấn like) + 之交 (mối giao tình) → mối quan hệ chỉ dừng ở bấm like trên mạng xã hội; từ mới, mô phỏng lối nói 君子之交, 一面之交.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","giao-tiep"],"image":"👍","examples":[{"type":"basic","zh":"我们只是点赞之交。","pinyin":"Wǒmen zhǐshì diǎnzànzhījiāo.","vi":"Chúng tôi chỉ là bạn bè thả like xã giao."},{"type":"simple","zh":"很多大学同学毕业后都成了点赞之交。","pinyin":"Hěn duō dàxué tóngxué bìyè hòu dōu chéngle diǎnzànzhījiāo.","vi":"Nhiều bạn đại học sau khi tốt nghiệp chỉ còn là quan hệ thả like xã giao."},{"type":"compound","zh":"虽然我们在网上是点赞之交，但是现实中从没说过一句话。","pinyin":"Suīrán wǒmen zài wǎngshàng shì diǎnzànzhījiāo, dànshì xiànshí zhōng cóng méi shuōguo yíjùhuà.","vi":"Tuy trên mạng chúng tôi hay thả like cho nhau, nhưng ngoài đời chưa từng nói với nhau câu nào."}],"related":[{"hanzi":"点赞","pinyin":"diǎnzàn","vi":"thả tim"},{"hanzi":"泛泛之交","pinyin":"fànfànzhījiāo","vi":"quen sơ sơ"},{"hanzi":"社交","pinyin":"shèjiāo","vi":"giao tiếp xã hội"},{"hanzi":"知己","pinyin":"zhījǐ","vi":"tri kỷ"}],"traditional":"點讚之交"},{"id":"断层","hanzi":"断层","pinyin":"duàncéng","meaning_vi":"đứt gãy (địa chất); sự đứt quãng, hẫng hụt (thế hệ)","explanation":"断 (đoạn – đứt) + 层 (tầng – lớp) → đứt gãy địa chất; nghĩa bóng: sự đứt quãng, hụt thế hệ. VD: 人才断层.","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⛰️","examples":[{"type":"basic","zh":"这里有一条断层。","pinyin":"Zhèlǐ yǒu yì tiáo duàncéng.","vi":"Ở đây có một đường đứt gãy."},{"type":"simple","zh":"这次地震发生在一条活动断层附近。","pinyin":"Zhè cì dìzhèn fāshēng zài yì tiáo huódòng duàncéng fùjìn.","vi":"Trận động đất lần này xảy ra gần một đứt gãy đang hoạt động."},{"type":"compound","zh":"如果老师傅退休后没人接班，这门手艺就会出现断层。","pinyin":"Rúguǒ lǎo shīfu tuìxiū hòu méi rén jiēbān, zhè mén shǒuyì jiù huì chūxiàn duàncéng.","vi":"Nếu các thợ cả nghỉ hưu mà không có người kế tục thì nghề này sẽ bị đứt gãy thế hệ."}],"related":[{"hanzi":"断裂","pinyin":"duànliè","vi":"đứt gãy"},{"hanzi":"地震","pinyin":"dìzhèn","vi":"động đất"},{"hanzi":"代沟","pinyin":"dàigōu","vi":"khoảng cách thế hệ"},{"hanzi":"断档","pinyin":"duàndàng","vi":"đứt quãng"}],"traditional":"斷層"},{"id":"对白","hanzi":"对白","pinyin":"duìbái","meaning_vi":"lời thoại (phim/kịch)","explanation":"对 (đúng) + 白 (màu trắng).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"这段对白很幽默。","pinyin":"Zhè duàn duìbái hěn yōumò.","vi":"Đoạn thoại này rất hài hước."},{"type":"simple","zh":"演员们正在片场反复练习明天要拍的对白。","pinyin":"Yǎnyuánmen zhèngzài piànchǎng fǎnfù liànxí míngtiān yào pāi de duìbái.","vi":"Các diễn viên đang luyện đi luyện lại lời thoại cho cảnh quay ngày mai ở trường quay."},{"type":"compound","zh":"这部电影虽然对白不多，但是每一句都耐人寻味。","pinyin":"Zhè bù diànyǐng suīrán duìbái bù duō, dànshì měi yíjù dōu nàirénxúnwèi.","vi":"Bộ phim này tuy ít lời thoại nhưng câu nào cũng đáng suy ngẫm."}],"related":[{"hanzi":"台词","pinyin":"táicí","vi":"lời thoại"},{"hanzi":"对话","pinyin":"duìhuà","vi":"đối thoại"},{"hanzi":"独白","pinyin":"dúbái","vi":"độc thoại"},{"hanzi":"旁白","pinyin":"pángbái","vi":"lời dẫn"}],"traditional":"對白"},{"id":"对等","hanzi":"对等","pinyin":"duìděng","meaning_vi":"ngang hàng, tương xứng","explanation":"对 (đúng) + 等 (đợi).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"双方地位对等。","pinyin":"Shuāngfāng dìwèi duìděng.","vi":"Địa vị hai bên ngang hàng."},{"type":"simple","zh":"两国在对等原则基础上开展了这次谈判。","pinyin":"Liǎngguó zài duìděng yuánzé jīchǔ shàng kāizhǎnle zhè cì tánpàn.","vi":"Hai nước tiến hành cuộc đàm phán này trên cơ sở nguyên tắc bình đẳng."},{"type":"compound","zh":"如果付出和回报长期不对等，员工就会失去积极性。","pinyin":"Rúguǒ fùchū hé huíbào chángqī bú duìděng, yuángōng jiù huì shīqù jījíxìng.","vi":"Nếu công sức bỏ ra và sự đền đáp lâu dài không tương xứng, nhân viên sẽ mất động lực."}],"related":[{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"对称","pinyin":"duìchèn","vi":"đối xứng"},{"hanzi":"相等","pinyin":"xiāngděng","vi":"bằng nhau"},{"hanzi":"互惠","pinyin":"hùhuì","vi":"cùng có lợi"}],"traditional":"對等"},{"id":"对口","hanzi":"对口","pinyin":"duìkǒu","meaning_vi":"đúng chuyên ngành, tương thích","explanation":"对 (đối – khớp, đúng) + 口 (khẩu – đầu mối) → khớp nhau, đúng chuyên ngành; tương ứng hai bên. VD: 专业对口, 对口支援.","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"他的工作很对口。","pinyin":"Tā de gōngzuò hěn duìkǒu.","vi":"Công việc của anh ấy rất đúng chuyên ngành."},{"type":"simple","zh":"她毕业后找到了一份专业对口的翻译工作。","pinyin":"Tā bìyè hòu zhǎodàole yí fèn zhuānyè duìkǒu de fānyì gōngzuò.","vi":"Sau khi tốt nghiệp, cô ấy tìm được công việc phiên dịch đúng chuyên ngành."},{"type":"compound","zh":"虽然这份工作专业不对口，但是工资待遇非常好。","pinyin":"Suīrán zhè fèn gōngzuò zhuānyè bú duìkǒu, dànshì gōngzī dàiyù fēicháng hǎo.","vi":"Tuy công việc này không đúng chuyên ngành, nhưng lương bổng đãi ngộ rất tốt."}],"related":[{"hanzi":"专业对口","pinyin":"zhuānyèduìkǒu","vi":"đúng chuyên ngành"},{"hanzi":"对口支援","pinyin":"duìkǒuzhīyuán","vi":"hỗ trợ theo cặp"},{"hanzi":"对应","pinyin":"duìyìng","vi":"tương ứng"},{"hanzi":"匹配","pinyin":"pǐpèi","vi":"phù hợp"}],"traditional":"對口"},{"id":"端倪","hanzi":"端倪","pinyin":"duānní","meaning_vi":"đầu mối, manh mối (看出端倪)","explanation":"端 (bưng) + 倪 (manh mối/đầu mối).","hsk_level":"7-9","tags":["danh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"问题已初露端倪。","pinyin":"Wèntí yǐ chūlù duānní.","vi":"Vấn đề đã bắt đầu lộ manh mối."},{"type":"simple","zh":"细心的会计从账目中看出了端倪。","pinyin":"Xìxīn de kuàijì cóng zhàngmù zhōng kànchūle duānní.","vi":"Người kế toán tỉ mỉ đã nhận ra manh mối từ sổ sách."},{"type":"compound","zh":"虽然两人表面上很客气，但是明眼人早已看出端倪。","pinyin":"Suīrán liǎng rén biǎomiànshàng hěn kèqi, dànshì míngyǎnrén zǎoyǐ kànchū duānní.","vi":"Tuy hai người bề ngoài rất khách sáo, nhưng người tinh ý đã sớm nhận ra manh mối."}],"related":[{"hanzi":"头绪","pinyin":"tóuxù","vi":"đầu mối"},{"hanzi":"迹象","pinyin":"jìxiàng","vi":"dấu hiệu"},{"hanzi":"苗头","pinyin":"miáotou","vi":"manh nha"},{"hanzi":"线索","pinyin":"xiànsuǒ","vi":"manh mối"}]},{"id":"多边","hanzi":"多边","pinyin":"duōbiān","meaning_vi":"đa phương","explanation":"多 (nhiều) + 边 (bên).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"这是一次多边会谈。","pinyin":"Zhè shì yí cì duōbiān huìtán.","vi":"Đây là một cuộc hội đàm đa phương."},{"type":"simple","zh":"越南积极参与亚太地区的多边贸易机制。","pinyin":"Yuènán jījí cānyù Yàtàidìqū de duōbiānmàoyì jīzhì.","vi":"Việt Nam tích cực tham gia các cơ chế thương mại đa phương khu vực châu Á Thái Bình Dương."},{"type":"compound","zh":"如果双边谈判陷入僵局，各国就可以在多边框架下寻求解决。","pinyin":"Rúguǒ shuāngbiān tánpàn xiànrù jiāngjú, gèguó jiù kěyǐ zài duōbiān kuàngjià xià xúnqiú jiějué.","vi":"Nếu đàm phán song phương rơi vào bế tắc, các nước có thể tìm giải pháp trong khuôn khổ đa phương."}],"related":[{"hanzi":"双边","pinyin":"shuāngbiān","vi":"song phương"},{"hanzi":"单边","pinyin":"dānbiān","vi":"đơn phương"},{"hanzi":"多边合作","pinyin":"duōbiānhézuò","vi":"hợp tác đa phương"},{"hanzi":"多边贸易","pinyin":"duōbiānmàoyì","vi":"thương mại đa phương"}],"traditional":"多邊"},{"id":"多边合作","hanzi":"多边合作","pinyin":"duōbiānhézuò","meaning_vi":"hợp tác đa phương","explanation":"多边 (nhiều bên) + 合作.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"🌐","examples":[{"type":"basic","zh":"多边合作很重要。","pinyin":"Duōbiānhézuò hěn zhòngyào.","vi":"Hợp tác đa phương rất quan trọng."},{"type":"simple","zh":"五国在湄公河治理方面开展了多边合作。","pinyin":"Wǔ guó zài Méigōnghé zhìlǐ fāngmiàn kāizhǎnle duōbiānhézuò.","vi":"Năm nước đã triển khai hợp tác đa phương trong quản lý sông Mê Kông."},{"type":"compound","zh":"气候变化是全球问题，所以只有加强多边合作才能应对。","pinyin":"Qìhòu biànhuà shì quánqiú wèntí, suǒyǐ zhǐyǒu jiāqiáng duōbiānhézuò cáinéng yìngduì.","vi":"Biến đổi khí hậu là vấn đề toàn cầu, nên chỉ có tăng cường hợp tác đa phương mới ứng phó được."}],"related":[{"hanzi":"双边合作","pinyin":"shuāngbiānhézuò","vi":"hợp tác song phương"},{"hanzi":"国际合作","pinyin":"guójìhézuò","vi":"hợp tác quốc tế"},{"hanzi":"多边主义","pinyin":"duōbiānzhǔyì","vi":"chủ nghĩa đa phương"},{"hanzi":"共赢","pinyin":"gòngyíng","vi":"cùng thắng"}],"traditional":"多邊合作"},{"id":"多边主义","hanzi":"多边主义","pinyin":"duōbiānzhǔyì","meaning_vi":"chủ nghĩa đa phương","explanation":"多 (nhiều) + 边 (bên) + 主 (chủ động/chủ quyền) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"我们坚持多边主义。","pinyin":"Wǒmen jiānchí duōbiānzhǔyì.","vi":"Chúng tôi kiên trì chủ nghĩa đa phương."},{"type":"simple","zh":"外长在联合国大会上呼吁各国维护多边主义。","pinyin":"Wàizhǎng zài Liánhéguódàhuì shàng hūyù gèguó wéihù duōbiānzhǔyì.","vi":"Bộ trưởng Ngoại giao kêu gọi các nước bảo vệ chủ nghĩa đa phương tại Đại hội đồng Liên Hợp Quốc."},{"type":"compound","zh":"与其各自为政，不如回到多边主义的轨道上来。","pinyin":"Yǔqí gèzìwéizhèng, bùrú huídào duōbiānzhǔyì de guǐdào shànglái.","vi":"Thay vì mỗi nước làm một kiểu, chi bằng quay lại quỹ đạo của chủ nghĩa đa phương."}],"related":[{"hanzi":"单边主义","pinyin":"dānbiānzhǔyì","vi":"chủ nghĩa đơn phương"},{"hanzi":"多边","pinyin":"duōbiān","vi":"đa phương"},{"hanzi":"保护主义","pinyin":"bǎohùzhǔyì","vi":"chủ nghĩa bảo hộ"},{"hanzi":"全球化","pinyin":"quánqiúhuà","vi":"toàn cầu hóa"}],"traditional":"多邊主義"},{"id":"多管齐下","hanzi":"多管齐下","pinyin":"duōguǎn-qíxià","meaning_vi":"tiến hành đồng bộ nhiều biện pháp","explanation":"多 (nhiều) + 管 (管) + 齐 (đồng lòng/đầy đủ) + 下 (dưới).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🛠️","examples":[{"type":"basic","zh":"治污要多管齐下。","pinyin":"Zhì wū yào duōguǎnqíxià.","vi":"Xử lý ô nhiễm phải triển khai đồng bộ nhiều biện pháp."},{"type":"simple","zh":"学校多管齐下地帮助学生缓解考试压力。","pinyin":"Xuéxiào duōguǎnqíxià de bāngzhù xuésheng huǎnjiě kǎoshì yālì.","vi":"Nhà trường dùng nhiều biện pháp đồng thời để giúp học sinh giảm áp lực thi cử."},{"type":"compound","zh":"只要饮食、运动和睡眠多管齐下，减肥就会更有效。","pinyin":"Zhǐyào yǐnshí, yùndòng hé shuìmián duōguǎnqíxià, jiǎnféi jiù huì gèng yǒuxiào.","vi":"Chỉ cần kết hợp đồng thời ăn uống, vận động và giấc ngủ, việc giảm cân sẽ hiệu quả hơn."}],"related":[{"hanzi":"齐头并进","pinyin":"qítóubìngjìn","vi":"tiến song song"},{"hanzi":"双管齐下","pinyin":"shuāngguǎnqíxià","vi":"làm hai việc cùng lúc"},{"hanzi":"综合治理","pinyin":"zōnghézhìlǐ","vi":"quản lý tổng hợp"},{"hanzi":"全方位","pinyin":"quánfāngwèi","vi":"toàn diện"}],"traditional":"多管齊下"},{"id":"多米诺骨牌","hanzi":"多米诺骨牌","pinyin":"duōmǐnuò gǔpái","meaning_vi":"quân cờ domino (多米诺骨牌效应 - hiệu ứng domino)","explanation":"多 (nhiều) + 米 (米) + 诺 (cam kết/lời hứa) + 骨 (骨) + 牌 (牌).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🀄","examples":[{"type":"basic","zh":"孩子们在摆多米诺骨牌。","pinyin":"Háizimen zài bǎi duōmǐnuògǔpái.","vi":"Bọn trẻ đang xếp quân cờ domino."},{"type":"simple","zh":"一家银行的倒闭引发了多米诺骨牌效应。","pinyin":"Yìjiā yínháng de dǎobì yǐnfāle duōmǐnuògǔpái xiàoyìng.","vi":"Sự sụp đổ của một ngân hàng đã gây ra hiệu ứng domino."},{"type":"compound","zh":"只要第一块倒下，后面的多米诺骨牌就会接连倒下。","pinyin":"Zhǐyào dì yīkuài dǎoxià, hòumiàn de duōmǐnuògǔpái jiù huì jiēlián dǎoxià.","vi":"Chỉ cần quân đầu tiên đổ, những quân domino phía sau sẽ lần lượt đổ theo."}],"related":[{"hanzi":"连锁反应","pinyin":"liánsuǒfǎnyìng","vi":"phản ứng dây chuyền"},{"hanzi":"骨牌","pinyin":"gǔpái","vi":"quân bài domino"},{"hanzi":"牵一发而动全身","pinyin":"qiān yífà ér dòng quánshēn","vi":"động một sợi tóc cả thân lay"},{"hanzi":"效应","pinyin":"xiàoyìng","vi":"hiệu ứng"}],"traditional":"多米諾骨牌"},{"id":"多元化","hanzi":"多元化","pinyin":"duōyuánhuà","meaning_vi":"đa dạng hóa","explanation":"多 (nhiều) + 元 (đồng (Nhân dân tệ)) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌈","examples":[{"type":"basic","zh":"文化日益多元化。","pinyin":"Wénhuà rìyì duōyuánhuà.","vi":"Văn hóa ngày càng đa dạng hóa."},{"type":"simple","zh":"这家公司正在推动产品线的多元化。","pinyin":"Zhè jiā gōngsī zhèngzài tuīdòng chǎnpǐn xiàn de duōyuánhuà.","vi":"Công ty này đang thúc đẩy đa dạng hóa dòng sản phẩm."},{"type":"compound","zh":"如果投资不够多元化，一旦行情变化就会损失惨重。","pinyin":"Rúguǒ tóuzī búgòu duōyuánhuà, yídàn hángqíng biànhuà jiù huì sǔnshī cǎnzhòng.","vi":"Nếu đầu tư không đủ đa dạng hóa, một khi thị trường biến động sẽ thiệt hại nặng nề."}],"related":[{"hanzi":"多样化","pinyin":"duōyànghuà","vi":"đa dạng hóa"},{"hanzi":"单一","pinyin":"dānyī","vi":"đơn nhất"},{"hanzi":"多元","pinyin":"duōyuán","vi":"đa nguyên"},{"hanzi":"一体化","pinyin":"yìtǐhuà","vi":"nhất thể hóa"}]},{"id":"多音字","hanzi":"多音字","pinyin":"duōyīnzì","meaning_vi":"chữ đa âm","explanation":"多 (nhiều) + 音 (âm thanh/tin tức) + 字 (chữ).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🔤","examples":[{"type":"basic","zh":"汉语里多音字很多。","pinyin":"Hànyǔ lǐ duōyīnzì hěn duō.","vi":"Trong tiếng Hán có rất nhiều chữ đa âm."},{"type":"simple","zh":"外国学生常常读错课文里的多音字。","pinyin":"Wàiguó xuésheng chángcháng dú cuò kèwén lǐ de duōyīnzì.","vi":"Học sinh nước ngoài thường đọc sai các chữ đa âm trong bài khóa."},{"type":"compound","zh":"遇到多音字时，只要结合上下文，就能判断正确读音。","pinyin":"Yùdào duōyīnzì shí, zhǐyào jiéhé shàngxiàwén, jiù néng pànduàn zhèngquè dúyīn.","vi":"Khi gặp chữ đa âm, chỉ cần kết hợp ngữ cảnh là có thể xác định cách đọc đúng."}],"related":[{"hanzi":"多义词","pinyin":"duōyìcí","vi":"từ đa nghĩa"},{"hanzi":"同音字","pinyin":"tóngyīnzì","vi":"chữ đồng âm"},{"hanzi":"读音","pinyin":"dúyīn","vi":"cách đọc"},{"hanzi":"拼音","pinyin":"pīnyīn","vi":"phiên âm"}]},{"id":"大局观","hanzi":"大局观","pinyin":"dàjúguān","meaning_vi":"tầm nhìn đại cục","explanation":"大 (to) + 局 (cục diện/cơ quan) + 观 (观).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc","cong-viec"],"image":"🌐","examples":[{"type":"basic","zh":"他很有大局观。","pinyin":"Tā hěn yǒu dàjúguān.","vi":"Anh ấy rất có tầm nhìn đại cục."},{"type":"simple","zh":"这位中场球员凭借出色的大局观掌控着比赛节奏。","pinyin":"Zhè wèi zhōngchǎng qiúyuán píngjiè chūsè de dàjúguān zhǎngkòngzhe bǐsài jiézòu.","vi":"Cầu thủ tiền vệ này nhờ tầm nhìn bao quát xuất sắc mà kiểm soát nhịp độ trận đấu."},{"type":"compound","zh":"管理者如果缺乏大局观，就容易因小失大。","pinyin":"Guǎnlǐ zhě rúguǒ quēfá dàjúguān, jiù róngyì yīn xiǎo shī dà.","vi":"Người quản lý nếu thiếu tầm nhìn đại cục sẽ dễ vì cái nhỏ mà mất cái lớn."}],"related":[{"hanzi":"大局","pinyin":"dàjú","vi":"đại cục"},{"hanzi":"顾全大局","pinyin":"gùquándàjú","vi":"chú ý toàn cục"},{"hanzi":"全局","pinyin":"quánjú","vi":"toàn cục"},{"hanzi":"远见","pinyin":"yuǎnjiàn","vi":"tầm nhìn xa"}],"traditional":"大局觀"},{"id":"大数据","hanzi":"大数据","pinyin":"dàshùjù","meaning_vi":"dữ liệu lớn (Big Data)","explanation":"大 + 数据 (dữ liệu).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📊","examples":[{"type":"basic","zh":"大数据改变了生活。","pinyin":"Dàshùjù gǎibiànle shēnghuó.","vi":"Dữ liệu lớn đã thay đổi cuộc sống."},{"type":"simple","zh":"购物网站利用大数据给用户推荐商品。","pinyin":"Gòuwù wǎngzhàn lìyòng dàshùjù gěi yònghù tuījiàn shāngpǐn.","vi":"Các trang mua sắm dùng dữ liệu lớn để gợi ý sản phẩm cho người dùng."},{"type":"compound","zh":"虽然大数据带来了便利，但是也引发了隐私泄露的担忧。","pinyin":"Suīrán dàshùjù dàiláile biànlì, dànshì yě yǐnfāle yǐnsī xièlòu de dānyōu.","vi":"Tuy dữ liệu lớn mang lại sự tiện lợi, nhưng cũng gây lo ngại về rò rỉ quyền riêng tư."}],"related":[{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"},{"hanzi":"云计算","pinyin":"yúnjìsuàn","vi":"điện toán đám mây"},{"hanzi":"数据分析","pinyin":"shùjùfēnxī","vi":"phân tích dữ liệu"}],"traditional":"大數據"},{"id":"大师","hanzi":"大师","pinyin":"dàshī","meaning_vi":"bậc thầy, đại sư","explanation":"大 (to) + 师 (thầy giáo/sư phụ).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"👑","examples":[{"type":"basic","zh":"他是书法大师。","pinyin":"Tā shì shūfǎ dàshī.","vi":"Ông ấy là bậc thầy thư pháp."},{"type":"simple","zh":"这位京剧大师八十岁时仍然坚持登台演出。","pinyin":"Zhè wèi Jīngjù dàshī bāshí suìshí réngrán jiānchí dēng tái yǎnchū.","vi":"Bậc thầy Kinh kịch này ở tuổi tám mươi vẫn kiên trì lên sân khấu biểu diễn."},{"type":"compound","zh":"即使已经成了围棋大师，他也每天坚持复盘。","pinyin":"Jíshǐ yǐjīng chéngle wéiqí dàshī, tā yě měitiān jiānchí fùpán.","vi":"Dù đã trở thành bậc thầy cờ vây, ông ấy vẫn ngày nào cũng kiên trì phân tích lại ván cờ."}],"related":[{"hanzi":"大家","pinyin":"dàjiā","vi":"bậc thầy"},{"hanzi":"宗师","pinyin":"zōngshī","vi":"tông sư"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"},{"hanzi":"大师级","pinyin":"dàshījí","vi":"đẳng cấp bậc thầy"}],"traditional":"大師"},{"id":"大使馆","hanzi":"大使馆","pinyin":"dàshǐguǎn","meaning_vi":"đại sứ quán","explanation":"大使 (đại sứ) + 馆 (cơ quan).","hsk_level":"7-9","tags":["danh-tu","du-lich","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"我去大使馆办签证。","pinyin":"Wǒqù dàshǐguǎn bàn qiānzhèng.","vi":"Tôi đến đại sứ quán làm thị thực."},{"type":"simple","zh":"中国驻越南大使馆位于河内巴亭郡。","pinyin":"Zhōngguó zhù Yuènán dàshǐguǎn wèiyú Hénèi bā tíng jùn.","vi":"Đại sứ quán Trung Quốc tại Việt Nam nằm ở quận Ba Đình, Hà Nội."},{"type":"compound","zh":"如果在国外丢了护照，你就应该马上联系大使馆。","pinyin":"Rúguǒ zài guówài diūle hùzhào, nǐ jiù yīnggāi mǎshàng liánxì dàshǐguǎn.","vi":"Nếu mất hộ chiếu ở nước ngoài, bạn nên liên hệ ngay với đại sứ quán."}],"related":[{"hanzi":"大使","pinyin":"dàshǐ","vi":"đại sứ"},{"hanzi":"领事馆","pinyin":"lǐngshìguǎn","vi":"lãnh sự quán"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"thị thực"},{"hanzi":"外交","pinyin":"wàijiāo","vi":"ngoại giao"}],"traditional":"大使館"},{"id":"大熊猫","hanzi":"大熊猫","pinyin":"dàxióngmāo","meaning_vi":"gấu trúc lớn","explanation":"大 (to) + 熊 (con gấu) + 猫 (con mèo).","hsk_level":"7-9","tags":["danh-tu","dong-vat","van-hoa"],"image":"🐼","examples":[{"type":"basic","zh":"大熊猫爱吃竹子。","pinyin":"Dàxióngmāo ài chī zhúzi.","vi":"Gấu trúc lớn thích ăn tre."},{"type":"simple","zh":"成都的大熊猫基地每天都吸引大批游客。","pinyin":"Chéngdū de dàxióngmāo jīdì měitiān dōu xīyǐn dàpī yóukè.","vi":"Trung tâm gấu trúc Thành Đô ngày nào cũng thu hút đông đảo du khách."},{"type":"compound","zh":"因为栖息地不断缩小，所以大熊猫曾一度濒临灭绝。","pinyin":"Yīnwèi qīxīdì búduàn suōxiǎo, suǒyǐ dàxióngmāo céng yídù bīnlín mièjué.","vi":"Vì môi trường sống liên tục bị thu hẹp nên gấu trúc lớn từng có lúc đứng trước nguy cơ tuyệt chủng."}],"related":[{"hanzi":"熊猫","pinyin":"xióngmāo","vi":"gấu trúc"},{"hanzi":"国宝","pinyin":"guóbǎo","vi":"quốc bảo"},{"hanzi":"竹子","pinyin":"zhúzi","vi":"cây tre"},{"hanzi":"四川","pinyin":"Sìchuān","vi":"Tứ Xuyên"}],"traditional":"大熊貓"},{"id":"大西洋","hanzi":"大西洋","pinyin":"Dàxīyáng","meaning_vi":"Đại Tây Dương","explanation":"大 (to) + 西 (hướng Tây) + 洋 (đại dương/nước ngoài).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"船驶入了大西洋。","pinyin":"Chuán shǐrùle Dàxīyáng.","vi":"Con tàu đã tiến vào Đại Tây Dương."},{"type":"simple","zh":"这位航海家花了四十天独自横渡大西洋。","pinyin":"Zhè wèi hánghǎijiā huāle sìshí tiān dúzì héngdù Dàxīyáng.","vi":"Nhà hàng hải này mất bốn mươi ngày một mình vượt Đại Tây Dương."},{"type":"compound","zh":"每年一到秋季，大西洋上就会形成多个飓风。","pinyin":"Měinián yí dào qiūjì, Dàxīyáng shàng jiù huì xíngchéng duōgè jùfēng.","vi":"Hằng năm cứ đến mùa thu, trên Đại Tây Dương lại hình thành nhiều cơn bão."}],"related":[{"hanzi":"太平洋","pinyin":"Tàipíngyáng","vi":"Thái Bình Dương"},{"hanzi":"印度洋","pinyin":"Yìndùyáng","vi":"Ấn Độ Dương"},{"hanzi":"北冰洋","pinyin":"Běibīngyáng","vi":"Bắc Băng Dương"},{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"}]},{"id":"代购","hanzi":"代购","pinyin":"dàigòu","meaning_vi":"mua hộ hàng nước ngoài","explanation":"代 (đại – thay thế) + 购 (cấu – mua) → mua hộ, đặc biệt mua hàng nước ngoài hộ người khác; cũng chỉ người làm nghề này. VD: 海外代购.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"她在做海外代购。","pinyin":"Tā zài zuò hǎiwài dàigòu.","vi":"Cô ấy đang làm dịch vụ mua hộ hàng nước ngoài."},{"type":"simple","zh":"我托朋友从日本代购了两盒感冒药。","pinyin":"Wǒ tuō péngyou cóng Rìběn dàigòule liǎng hé gǎnmàoyào.","vi":"Tôi nhờ bạn mua hộ hai hộp thuốc cảm từ Nhật Bản."},{"type":"compound","zh":"如果找不靠谱的代购，你就可能买到假货。","pinyin":"Rúguǒ zhǎo bú kàopǔ de dàigòu, nǐ jiù kěnéng mǎi dào jiǎhuò.","vi":"Nếu tìm người mua hộ không đáng tin cậy, bạn có thể mua phải hàng giả."}],"related":[{"hanzi":"海淘","pinyin":"hǎitáo","vi":"mua hàng nước ngoài online"},{"hanzi":"网购","pinyin":"wǎnggòu","vi":"mua sắm online"},{"hanzi":"代理","pinyin":"dàilǐ","vi":"đại lý"},{"hanzi":"购买","pinyin":"gòumǎi","vi":"mua"}],"traditional":"代購"},{"id":"代名词","hanzi":"代名词","pinyin":"dàimíngcí","meaning_vi":"từ đồng nghĩa, biểu tượng (của cái gì); đại từ","explanation":"代 (代) + 名 (danh tiếng/nổi tiếng) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu"],"image":"🏷️","examples":[{"type":"basic","zh":"他是勇敢的代名词。","pinyin":"Tā shì yǒnggǎn de dàimíngcí.","vi":"Anh ấy là biểu tượng của lòng dũng cảm."},{"type":"simple","zh":"在很多人心中，茅台已经成了高档白酒的代名词。","pinyin":"Zài hěn duō rén xīnzhōng, máotái yǐjīng chéngle gāodàng báijiǔ de dàimíngcí.","vi":"Trong lòng nhiều người, Mao Đài đã trở thành từ đồng nghĩa với rượu trắng cao cấp."},{"type":"compound","zh":"虽然这座小城过去是贫穷的代名词，但如今已成了旅游胜地。","pinyin":"Suīrán zhè zuò xiǎochéng guòqù shì pínqióng de dàimíngcí, dàn rújīn yǐ chéngle lǚyóu shèngdì.","vi":"Tuy thị trấn nhỏ này trước kia là biểu tượng của nghèo khó, nhưng nay đã thành điểm du lịch nổi tiếng."}],"related":[{"hanzi":"同义词","pinyin":"tóngyìcí","vi":"từ đồng nghĩa"},{"hanzi":"象征","pinyin":"xiàngzhēng","vi":"tượng trưng"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại diện"},{"hanzi":"代词","pinyin":"dàicí","vi":"đại từ"}],"traditional":"代名詞"},{"id":"代入感","hanzi":"代入感","pinyin":"dàirùgǎn","meaning_vi":"cảm giác nhập vai, đồng cảm sâu sắc","explanation":"代 (代) + 入 (nhập vào/sâu sắc) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","giai-tri","cam-xuc"],"image":"🎬","examples":[{"type":"basic","zh":"这本小说代入感很强。","pinyin":"Zhè běn xiǎoshuō dàirùgǎn hěn qiáng.","vi":"Cuốn tiểu thuyết này có cảm giác nhập vai rất mạnh."},{"type":"simple","zh":"第一人称视角的游戏能给玩家带来强烈的代入感。","pinyin":"Dìyī rénchēng shìjiǎo de yóuxì néng gěi wánjiā dàilái qiángliè de dàirùgǎn.","vi":"Trò chơi góc nhìn thứ nhất mang lại cho người chơi cảm giác nhập vai mạnh mẽ."},{"type":"compound","zh":"因为主角的经历和我很像，所以看这部剧时代入感特别强。","pinyin":"Yīnwèi zhǔjué de jīnglì hé wǒ hěn xiàng, suǒyǐ kàn zhè bù jù shí dàirùgǎn tèbié qiáng.","vi":"Vì trải nghiệm của nhân vật chính rất giống tôi nên khi xem bộ phim này tôi nhập tâm đặc biệt."}],"related":[{"hanzi":"共鸣","pinyin":"gòngmíng","vi":"đồng cảm cộng hưởng"},{"hanzi":"沉浸感","pinyin":"chénjìngǎn","vi":"cảm giác đắm chìm"},{"hanzi":"身临其境","pinyin":"shēnlínqíjìng","vi":"như đang ở đó"},{"hanzi":"同理心","pinyin":"tónglǐxīn","vi":"sự đồng cảm"}]},{"id":"带头","hanzi":"带头","pinyin":"dàitóu","meaning_vi":"dẫn đầu, làm gương đi trước","explanation":"带 (mang theo) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚩","examples":[{"type":"basic","zh":"班长带头鼓掌。","pinyin":"Bānzhǎng dàitóu gǔzhǎng.","vi":"Lớp trưởng dẫn đầu vỗ tay."},{"type":"simple","zh":"村支书带头捐出了自己一年的工资。","pinyin":"Cūn zhīshū dàitóu juān chūle zìjǐ yì nián de gōngzī.","vi":"Bí thư chi bộ thôn đi đầu quyên góp một năm lương của mình."},{"type":"compound","zh":"只要领导带头遵守规定，员工就不会有怨言。","pinyin":"Zhǐyào lǐngdǎo dàitóu zūnshǒu guīdìng, yuángōng jiù bú huì yǒu yuànyán.","vi":"Chỉ cần lãnh đạo làm gương tuân thủ quy định thì nhân viên sẽ không có lời oán thán."}],"related":[{"hanzi":"领头","pinyin":"lǐngtóu","vi":"dẫn đầu"},{"hanzi":"带领","pinyin":"dàilǐng","vi":"dẫn dắt"},{"hanzi":"以身作则","pinyin":"yǐshēnzuòzé","vi":"lấy mình làm gương"},{"hanzi":"带头人","pinyin":"dàitóurén","vi":"người đi đầu"}],"traditional":"帶頭"},{"id":"带薪休假","hanzi":"带薪休假","pinyin":"dàixīnxiūjià","meaning_vi":"nghỉ phép có hưởng lương","explanation":"带薪 (có lương) + 休假 (nghỉ phép).","hsk_level":"7-9","tags":["danh-tu","cong-viec","thoi-gian"],"image":"🏖️","examples":[{"type":"basic","zh":"我想申请带薪休假。","pinyin":"Wǒ xiǎng shēnqǐng dàixīnxiūjià.","vi":"Tôi muốn xin nghỉ phép có lương."},{"type":"simple","zh":"公司规定员工每年享有十五天带薪休假。","pinyin":"Gōngsī guīdìng yuángōng měinián xiǎngyǒu shíwǔ tiān dàixīnxiūjià.","vi":"Công ty quy định nhân viên mỗi năm được hưởng mười lăm ngày nghỉ phép có lương."},{"type":"compound","zh":"虽然有带薪休假，但是很多人因为工作太忙而不敢请。","pinyin":"Suīrán yǒu dàixīnxiūjià, dànshì hěn duō rén yīnwèi gōngzuò tài máng ér bù gǎn qǐng.","vi":"Tuy có nghỉ phép hưởng lương, nhưng nhiều người vì công việc quá bận mà không dám xin."}],"related":[{"hanzi":"休假","pinyin":"xiūjià","vi":"nghỉ phép"},{"hanzi":"年假","pinyin":"niánjià","vi":"phép năm"},{"hanzi":"请假","pinyin":"qǐngjià","vi":"xin nghỉ"},{"hanzi":"病假","pinyin":"bìngjià","vi":"nghỉ ốm"}],"traditional":"帶薪休假"},{"id":"淡化","hanzi":"淡化","pinyin":"dànhuà","meaning_vi":"làm phai nhạt, giảm nhẹ tầm quan trọng","explanation":"淡 (nhạt (màu sắc/mùi vị)) + 化 (化).","hsk_level":"7-9","tags":["dong-tu"],"image":"💧","examples":[{"type":"basic","zh":"时间淡化了伤痛。","pinyin":"Shíjiān dànhuàle shāngtòng.","vi":"Thời gian đã làm phai nhạt nỗi đau."},{"type":"simple","zh":"这篇报道刻意淡化了事故的严重性。","pinyin":"Zhè piān bàodào kèyì dànhuàle shìgù de yánzhòngxìng.","vi":"Bài báo này cố tình giảm nhẹ mức độ nghiêm trọng của sự cố."},{"type":"compound","zh":"如果父母一味淡化孩子的错误，孩子就很难学会承担责任。","pinyin":"Rúguǒ fùmǔ yíwèi dànhuà háizi de cuòwù, háizi jiù hěn nán xuéhuì chéngdān zérèn.","vi":"Nếu cha mẹ cứ xem nhẹ lỗi lầm của con thì đứa trẻ sẽ khó học được cách chịu trách nhiệm."}],"related":[{"hanzi":"弱化","pinyin":"ruòhuà","vi":"làm yếu đi"},{"hanzi":"冲淡","pinyin":"chōngdàn","vi":"pha loãng"},{"hanzi":"强化","pinyin":"qiánghuà","vi":"tăng cường"},{"hanzi":"淡忘","pinyin":"dànwàng","vi":"phai nhòa quên lãng"}]},{"id":"得意洋洋","hanzi":"得意洋洋","pinyin":"déyì-yángyáng","meaning_vi":"đắc ý vênh váo","explanation":"得意 (đắc ý – hài lòng) + 洋洋 (dương dương – vẻ phơi phới) → đắc ý ra mặt, vênh váo tự mãn. VD: 他得意洋洋地走了.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😎","examples":[{"type":"basic","zh":"他得意洋洋地笑了。","pinyin":"Tā déyìyángyáng de xiào le.","vi":"Anh ta cười đắc ý."},{"type":"simple","zh":"弟弟拿着满分试卷得意洋洋地走进家门。","pinyin":"Dìdi názhe mǎnfēn shìjuàn déyìyángyáng de zǒujìn jiāmén.","vi":"Em trai cầm bài kiểm tra điểm tuyệt đối đắc ý bước vào nhà."},{"type":"compound","zh":"他刚赢了一局就得意洋洋，结果后面连输三局。","pinyin":"Tā gāng yíngle yì jú jiù déyìyángyáng, jiéguǒ hòumiàn lián shū sān jú.","vi":"Anh ta vừa thắng một ván đã vênh váo đắc ý, kết quả sau đó thua liền ba ván."}],"related":[{"hanzi":"得意忘形","pinyin":"déyìwàngxíng","vi":"đắc ý quên mình"},{"hanzi":"扬扬得意","pinyin":"yángyángdéyì","vi":"dương dương tự đắc"},{"hanzi":"沾沾自喜","pinyin":"zhānzhānzìxǐ","vi":"tự mãn"},{"hanzi":"垂头丧气","pinyin":"chuítóusàngqì","vi":"ủ rũ chán nản"}]},{"id":"地标","hanzi":"地标","pinyin":"dìbiāo","meaning_vi":"công trình biểu tượng địa phương (landmark)","explanation":"地 (地) + 标 (tiêu chuẩn/ký hiệu).","hsk_level":"7-9","tags":["danh-tu","dia-diem","van-hoa"],"image":"🗼","examples":[{"type":"basic","zh":"这座塔是城市地标。","pinyin":"Zhè zuò tǎ shì chéngshì dìbiāo.","vi":"Tòa tháp này là công trình biểu tượng của thành phố."},{"type":"simple","zh":"游客们纷纷在外滩的地标建筑前拍照留念。","pinyin":"Yóukèmen fēnfēn zài Wàitān de dìbiāo jiànzhù qián pāizhào liúniàn.","vi":"Du khách lần lượt chụp ảnh lưu niệm trước các công trình biểu tượng ở Bến Thượng Hải."},{"type":"compound","zh":"一看到埃菲尔铁塔这个地标，大家就知道到了巴黎。","pinyin":"Yí kàndào Āifēi'ěrtiětǎ zhè ge dìbiāo, dàjiā jiù zhīdào dàole Bālí.","vi":"Vừa thấy biểu tượng tháp Eiffel, mọi người liền biết đã đến Paris."}],"related":[{"hanzi":"标志","pinyin":"biāozhì","vi":"biểu tượng"},{"hanzi":"地标建筑","pinyin":"dìbiāojiànzhù","vi":"công trình biểu tượng"},{"hanzi":"名胜","pinyin":"míngshèng","vi":"danh thắng"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"}],"traditional":"地標"},{"id":"地缘政治","hanzi":"地缘政治","pinyin":"Dìyuánzhèngzhì","meaning_vi":"địa chính trị","explanation":"地 (地) + 缘 (duyên phận/nguyên cớ) + 政 (chính sách/chính trị) + 治 (quản lý/điều trị).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"地缘政治局势紧张。","pinyin":"Dìyuánzhèngzhì júshì jǐnzhāng.","vi":"Tình hình địa chính trị căng thẳng."},{"type":"simple","zh":"地缘政治冲突导致国际油价大幅上涨。","pinyin":"Dìyuánzhèngzhì chōngtū dǎozhì Guójì yóujià dàfú shàngzhǎng.","vi":"Xung đột địa chính trị khiến giá dầu thế giới tăng mạnh."},{"type":"compound","zh":"因为这个海峡地缘政治地位重要，所以大国都十分关注。","pinyin":"Yīnwèi zhè ge Hǎixiá Dìyuánzhèngzhì dìwèi zhòngyào, suǒyǐ dà guódōu shífēn guānzhù.","vi":"Vì eo biển này có vị trí địa chính trị quan trọng nên các nước lớn đều rất quan tâm."}],"related":[{"hanzi":"政治","pinyin":"zhèngzhì","vi":"chính trị"},{"hanzi":"地理","pinyin":"dìlǐ","vi":"địa lý"},{"hanzi":"国际关系","pinyin":"guójìguānxì","vi":"quan hệ quốc tế"},{"hanzi":"地区冲突","pinyin":"dìqūchōngtū","vi":"xung đột khu vực"}],"traditional":"地緣政治"},{"id":"第一印象","hanzi":"第一印象","pinyin":"dìyīyìnxiàng","meaning_vi":"ấn tượng đầu tiên","explanation":"第 (thứ tự) + 一 (số 1) + 印 (ấn tượng/in ấn) + 象 (hiện tượng/tượng trưng).","hsk_level":"7-9","tags":["danh-tu","giao-tiep","nhan-thuc"],"image":"👀","examples":[{"type":"basic","zh":"第一印象很重要。","pinyin":"Dìyīyìnxiàng hěn zhòngyào.","vi":"Ấn tượng đầu tiên rất quan trọng."},{"type":"simple","zh":"面试官对这位穿着得体的应聘者第一印象很好。","pinyin":"Miànshìguān duì zhè wèi chuānzhuó détǐ de yìngpìnzhě dìyīyìnxiàng hěn hǎo.","vi":"Người phỏng vấn có ấn tượng đầu tiên rất tốt về ứng viên ăn mặc chỉn chu này."},{"type":"compound","zh":"虽然他给我的第一印象很冷淡，但是相处久了发现他很热心。","pinyin":"Suīrán tā gěi wǒ de dìyīyìnxiàng hěn lěngdàn, dànshì xiāngchǔ jiǔle fāxiàn tā hěn rèxīn.","vi":"Tuy ấn tượng đầu tiên anh ấy để lại cho tôi là lạnh lùng, nhưng tiếp xúc lâu mới thấy anh rất nhiệt tình."}],"related":[{"hanzi":"印象","pinyin":"yìnxiàng","vi":"ấn tượng"},{"hanzi":"先入为主","pinyin":"xiānrùwéizhǔ","vi":"định kiến có sẵn"},{"hanzi":"一见钟情","pinyin":"yíjiànzhōngqíng","vi":"tình yêu sét đánh"},{"hanzi":"形象","pinyin":"xíngxiàng","vi":"hình ảnh"}]},{"id":"第二故乡","hanzi":"第二故乡","pinyin":"dì'èrgùxiāng","meaning_vi":"quê hương thứ hai","explanation":"第 (thứ tự) + 二 (số 2) + 故 (故) + 乡 (quê hương).","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-diem"],"image":"🏡","examples":[{"type":"basic","zh":"河内是我的第二故乡。","pinyin":"Hénèi shì wǒ de dì'èrgùxiāng.","vi":"Hà Nội là quê hương thứ hai của tôi."},{"type":"simple","zh":"在北京工作三十年的他早已把这里当成第二故乡。","pinyin":"Zài Běijīng gōngzuò sānshí nián de tā zǎoyǐ bǎ zhèlǐ dàngchéng dì'èrgùxiāng.","vi":"Đã làm việc ở Bắc Kinh ba mươi năm, anh ấy từ lâu đã coi nơi đây là quê hương thứ hai."},{"type":"compound","zh":"虽然她出生在法国，但是越南早已成了她的第二故乡。","pinyin":"Suīrán tā chūshēng zài Fǎguó, dànshì Yuènán zǎoyǐ chéngle tā de dì'èrgùxiāng.","vi":"Tuy cô ấy sinh ra ở Pháp, nhưng Việt Nam từ lâu đã trở thành quê hương thứ hai của cô."}],"related":[{"hanzi":"故乡","pinyin":"gùxiāng","vi":"quê hương"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê nhà"},{"hanzi":"他乡","pinyin":"tāxiāng","vi":"quê người"},{"hanzi":"定居","pinyin":"dìngjū","vi":"định cư"}],"traditional":"第二故鄉"},{"id":"定居","hanzi":"定居","pinyin":"dìngjū","meaning_vi":"định cư","explanation":"定 (定) + 居 (cư trú).","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"他们在澳洲定居了。","pinyin":"Tāmen zài Àozhōu dìngjū le.","vi":"Họ đã định cư ở Úc."},{"type":"simple","zh":"退休后老两口回到了家乡的小镇定居。","pinyin":"Tuìxiū hòu lǎoliǎngkǒu huídàole jiāxiāng de xiǎozhèn dìngjū.","vi":"Sau khi nghỉ hưu, hai ông bà trở về thị trấn quê nhà định cư."},{"type":"compound","zh":"如果你打算在这里长期定居，就最好先学会本地话。","pinyin":"Rúguǒ nǐ dǎsuàn zài zhèlǐ chángqī dìngjū, jiù zuìhǎo xiān xuéhuì běndì huà.","vi":"Nếu bạn định định cư lâu dài ở đây thì tốt nhất nên học tiếng địa phương trước."}],"related":[{"hanzi":"移民","pinyin":"yímín","vi":"di dân"},{"hanzi":"安家","pinyin":"ānjiā","vi":"an cư"},{"hanzi":"居住","pinyin":"jūzhù","vi":"cư trú"},{"hanzi":"落户","pinyin":"luòhù","vi":"nhập hộ khẩu"}]},{"id":"定量分析","hanzi":"定量分析","pinyin":"dìngliàngfēnxī","meaning_vi":"phân tích định lượng","explanation":"定 (定) + 量 (đo lường/số lượng) + 分 (phút) + 析 (phân tích).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"📈","examples":[{"type":"basic","zh":"这份报告缺少定量分析。","pinyin":"Zhè fèn bàogào quēshǎo dìngliàngfēnxī.","vi":"Bản báo cáo này thiếu phân tích định lượng."},{"type":"simple","zh":"研究人员用问卷数据对消费习惯进行了定量分析。","pinyin":"Yánjiū rényuán yòng wènjuàn shùjù duì xiāofèi xíguàn jìnxíngle dìngliàngfēnxī.","vi":"Các nhà nghiên cứu dùng dữ liệu bảng hỏi để phân tích định lượng thói quen tiêu dùng."},{"type":"compound","zh":"只有把定性描述和定量分析结合起来，结论才更可靠。","pinyin":"Zhǐyǒu bǎ dìngxìng miáoshù hé dìngliàngfēnxī jiéhé qǐlái, jiélùn cái gèng kěkào.","vi":"Chỉ khi kết hợp mô tả định tính với phân tích định lượng, kết luận mới đáng tin cậy hơn."}],"related":[{"hanzi":"定性分析","pinyin":"dìngxìngfēnxī","vi":"phân tích định tính"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"}]},{"id":"定力","hanzi":"定力","pinyin":"dìnglì","meaning_vi":"bản lĩnh vững vàng, định lực","explanation":"定 (定) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧘","examples":[{"type":"basic","zh":"他很有定力。","pinyin":"Tā hěn yǒu dìnglì.","vi":"Anh ấy rất có bản lĩnh vững vàng."},{"type":"simple","zh":"面对高薪诱惑，这位科学家表现出了惊人的定力。","pinyin":"Miànduì gāoxīn yòuhuò, zhè wèi kēxuéjiā biǎoxiàn chūle jīngrén de dìnglì.","vi":"Trước sự cám dỗ của mức lương cao, nhà khoa học này đã thể hiện bản lĩnh đáng kinh ngạc."},{"type":"compound","zh":"如果没有足够的定力，你就很容易被手机分散注意力。","pinyin":"Rúguǒ méiyǒu zúgòu de dìnglì, nǐ jiù hěn róngyì bèi shǒujī fēnsàn zhùyìlì.","vi":"Nếu không đủ định lực, bạn sẽ rất dễ bị điện thoại làm phân tán sự chú ý."}],"related":[{"hanzi":"意志","pinyin":"yìzhì","vi":"ý chí"},{"hanzi":"自制力","pinyin":"zìzhìlì","vi":"khả năng tự chủ"},{"hanzi":"毅力","pinyin":"yìlì","vi":"nghị lực"},{"hanzi":"沉着","pinyin":"chénzhuó","vi":"trầm tĩnh"}]},{"id":"定向","hanzi":"定向","pinyin":"dìngxiàng","meaning_vi":"định hướng, theo hướng xác định","explanation":"定 (定) + 向 (hướng về).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🧭","examples":[{"type":"basic","zh":"学校定向招生。","pinyin":"Xuéxiào dìngxiàng zhāoshēng.","vi":"Trường tuyển sinh theo diện định hướng."},{"type":"simple","zh":"这批医学生毕业后将定向分配到农村卫生院。","pinyin":"Zhè pī yī xuéshēng bìyè hòu jiāng dìngxiàng fēnpèi dào nóngcūn wèishēng yuàn.","vi":"Lứa sinh viên y này sau khi tốt nghiệp sẽ được phân công theo diện định hướng về trạm y tế nông thôn."},{"type":"compound","zh":"因为这种麦克风是定向收音的，所以背景噪音很小。","pinyin":"Yīnwèi zhè zhǒng màikèfēng shì dìngxiàng shōuyīn de, suǒyǐ bèijǐng zàoyīn hěn xiǎo.","vi":"Vì loại micro này thu âm có định hướng nên tiếng ồn nền rất nhỏ."}],"related":[{"hanzi":"方向","pinyin":"fāngxiàng","vi":"phương hướng"},{"hanzi":"定向培养","pinyin":"dìngxiàngpéiyǎng","vi":"đào tạo theo địa chỉ"},{"hanzi":"导向","pinyin":"dǎoxiàng","vi":"định hướng"},{"hanzi":"定位","pinyin":"dìngwèi","vi":"định vị"}]},{"id":"定性分析","hanzi":"定性分析","pinyin":"dìngxìngfēnxī","meaning_vi":"phân tích định tính","explanation":"定 (定) + 性 (tính chất/tính cách) + 分 (phút) + 析 (phân tích).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"先做定性分析吧。","pinyin":"Xiān zuò dìngxìngfēnxī ba.","vi":"Hãy làm phân tích định tính trước đi."},{"type":"simple","zh":"化学课上我们用试剂对溶液做了定性分析。","pinyin":"Huàxué kè shàng wǒmen yòng shìjì duì róngyè zuòle dìngxìngfēnxī.","vi":"Trong giờ hóa học, chúng tôi dùng thuốc thử để phân tích định tính dung dịch."},{"type":"compound","zh":"虽然样本数量很少，但是仍然可以进行定性分析。","pinyin":"Suīrán yàngběn shùliàng hěn shǎo, dànshì réngrán kěyǐ jìnxíng dìngxìngfēnxī.","vi":"Tuy số lượng mẫu rất ít nhưng vẫn có thể tiến hành phân tích định tính."}],"related":[{"hanzi":"定量分析","pinyin":"dìngliàngfēnxī","vi":"phân tích định lượng"},{"hanzi":"性质","pinyin":"xìngzhì","vi":"tính chất"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"定性","pinyin":"dìngxìng","vi":"xác định tính chất"}]},{"id":"动感","hanzi":"动感","pinyin":"dònggǎn","meaning_vi":"cảm giác sôi động mạnh mẽ","explanation":"动 (động – chuyển động) + 感 (cảm – cảm giác) → cảm giác chuyển động, sống động, có nhịp điệu; dùng cho âm nhạc, thiết kế, hình ảnh: 动感音乐.","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🔥","examples":[{"type":"basic","zh":"这首歌很有动感。","pinyin":"Zhè shǒu gē hěn yǒu dònggǎn.","vi":"Bài hát này rất sôi động."},{"type":"simple","zh":"健身房里播放着节奏强烈的动感音乐。","pinyin":"Jiànshēnfáng lǐ bōfàngzhe jiézòu qiángliè de dònggǎn yīnyuè.","vi":"Phòng tập đang phát nhạc sôi động với nhịp điệu mạnh."},{"type":"compound","zh":"这辆跑车不但线条充满动感，而且加速性能极强。","pinyin":"Zhè liàng pǎochē búdàn xiàntiáo chōngmǎn dònggǎn, érqiě jiāsù xìngnéng jí qiáng.","vi":"Chiếc xe thể thao này không những có đường nét đầy năng động mà khả năng tăng tốc còn cực mạnh."}],"related":[{"hanzi":"动感十足","pinyin":"dònggǎnshízú","vi":"đầy sôi động"},{"hanzi":"节奏感","pinyin":"jiézòugǎn","vi":"cảm giác nhịp điệu"},{"hanzi":"活力","pinyin":"huólì","vi":"sức sống"},{"hanzi":"静态","pinyin":"jìngtài","vi":"trạng thái tĩnh"}],"traditional":"動感"},{"id":"动向","hanzi":"动向","pinyin":"dòngxiàng","meaning_vi":"xu hướng biến động, động thái","explanation":"动 (动) + 向 (hướng về).","hsk_level":"7-9","tags":["danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"密切关注敌人动向。","pinyin":"Mìqiè guānzhù dírén dòngxiàng.","vi":"Theo dõi sát động thái của địch."},{"type":"simple","zh":"投资者都在观察央行的政策动向。","pinyin":"Tóuzīzhě dōu zài guānchá yāngháng de zhèngcè dòngxiàng.","vi":"Các nhà đầu tư đều đang quan sát động thái chính sách của ngân hàng trung ương."},{"type":"compound","zh":"只要掌握了竞争对手的动向，我们就能提前做好应对。","pinyin":"Zhǐyào zhǎngwòle jìngzhēng duìshǒu de dòngxiàng, wǒmen jiù néng tíqián zuò hǎo yìngduì.","vi":"Chỉ cần nắm được động thái của đối thủ cạnh tranh, chúng ta có thể chuẩn bị ứng phó trước."}],"related":[{"hanzi":"动态","pinyin":"dòngtài","vi":"động thái"},{"hanzi":"趋势","pinyin":"qūshì","vi":"xu thế"},{"hanzi":"走向","pinyin":"zǒuxiàng","vi":"chiều hướng"},{"hanzi":"动静","pinyin":"dòngjing","vi":"động tĩnh"}],"traditional":"動向"},{"id":"独创","hanzi":"独创","pinyin":"dúchuàng","meaning_vi":"sáng tạo độc đáo riêng","explanation":"独 (独) + 创 (sáng tạo).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"这是他独创的菜。","pinyin":"Zhè shì tā dúchuàng de cài.","vi":"Đây là món ăn do anh ấy sáng tạo riêng."},{"type":"simple","zh":"这位老师独创了一套快速记忆汉字的方法。","pinyin":"Zhè wèi lǎoshī dúchuàngle yítào kuàisù jìyì hànzì de fāngfǎ.","vi":"Thầy giáo này đã sáng tạo ra một phương pháp ghi nhớ chữ Hán nhanh độc đáo."},{"type":"compound","zh":"这种针法虽然是她独创的，但是她愿意免费教给村里人。","pinyin":"Zhè zhǒng zhēnfǎ suīrán shì tā dúchuàng de, dànshì tā yuànyì miǎnfèi jiāo gěi cūn lǐrén.","vi":"Kiểu thêu này tuy do bà ấy tự sáng tạo nhưng bà sẵn lòng dạy miễn phí cho người trong làng."}],"related":[{"hanzi":"首创","pinyin":"shǒuchuàng","vi":"sáng tạo đầu tiên"},{"hanzi":"原创","pinyin":"yuánchuàng","vi":"nguyên tác"},{"hanzi":"独创性","pinyin":"dúchuàngxìng","vi":"tính độc đáo"},{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"}],"traditional":"獨創"},{"id":"独立自主","hanzi":"独立自主","pinyin":"dúlì-zìzhǔ","meaning_vi":"độc lập tự chủ","explanation":"独 (独) + 立 (lập trường/thiết lập) + 自 (tự chủ/tự hào) + 主 (chủ động/chủ quyền).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🗽","examples":[{"type":"basic","zh":"她从小就独立自主。","pinyin":"Tā cóngxiǎo jiù dúlìzìzhǔ.","vi":"Cô ấy từ nhỏ đã độc lập tự chủ."},{"type":"simple","zh":"这个国家始终奉行独立自主的和平外交政策。","pinyin":"Zhè ge guójiā shǐzhōng fèngxíng dúlìzìzhǔ de hépíng wàijiāo zhèngcè.","vi":"Quốc gia này luôn theo đuổi chính sách đối ngoại hòa bình, độc lập tự chủ."},{"type":"compound","zh":"如果核心技术掌握在别人手里，企业就谈不上独立自主。","pinyin":"Rúguǒ héxīnjìshù zhǎngwò zài biérén shǒulǐ, qǐyè jiù tánbushàng dúlìzìzhǔ.","vi":"Nếu công nghệ cốt lõi nằm trong tay người khác thì doanh nghiệp không thể nói đến độc lập tự chủ."}],"related":[{"hanzi":"自力更生","pinyin":"zìlìgēngshēng","vi":"tự lực cánh sinh"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"自主","pinyin":"zìzhǔ","vi":"tự chủ"},{"hanzi":"依赖","pinyin":"yīlài","vi":"ỷ lại"}],"traditional":"獨立自主"},{"id":"独树一帜","hanzi":"独树一帜","pinyin":"dúshù-yízhì","meaning_vi":"tạo dựng phong cách riêng biệt độc đáo","explanation":"独 (独) + 树 (xây dựng/cây cối) + 一 (số 1) + 帜 (帜).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🚩","examples":[{"type":"basic","zh":"他的画风独树一帜。","pinyin":"Tā de huàfēng dúshùyízhì.","vi":"Phong cách vẽ của anh ấy độc đáo riêng biệt."},{"type":"simple","zh":"这家书店以独树一帜的装修风格吸引了大批年轻人。","pinyin":"Zhè jiāshū diàn yǐ dúshùyízhì de zhuāngxiū fēnggé xīyǐnle dàpī niánqīngrén.","vi":"Hiệu sách này thu hút rất nhiều người trẻ nhờ phong cách trang trí độc đáo riêng biệt."},{"type":"compound","zh":"虽然市场上同类产品很多，但是这款设计依然独树一帜。","pinyin":"Suīrán shìchǎng shàng tónglèi chǎnpǐn hěn duō, dànshì zhè kuǎn shèjì yīrán dúshùyízhì.","vi":"Tuy thị trường có rất nhiều sản phẩm cùng loại, nhưng thiết kế này vẫn nổi bật một phong cách riêng."}],"related":[{"hanzi":"别具一格","pinyin":"biéjùyìgé","vi":"có phong cách riêng"},{"hanzi":"与众不同","pinyin":"yǔzhòngbùtóng","vi":"khác biệt"},{"hanzi":"标新立异","pinyin":"biāoxīnlìyì","vi":"lập dị đổi mới"},{"hanzi":"千篇一律","pinyin":"qiānpiānyílǜ","vi":"rập khuôn"}],"traditional":"獨樹一幟"},{"id":"读书人","hanzi":"读书人","pinyin":"dúshūrén","meaning_vi":"người đọc sách, trí thức","explanation":"读 (đọc (thành tiếng)) + 书 (sách) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他是个读书人。","pinyin":"Tā shì gè dúshūrén.","vi":"Ông ấy là một người trí thức."},{"type":"simple","zh":"古代读书人大多希望通过科举考试做官。","pinyin":"Gǔdài dúshūrén dàduō xīwàng tōngguò kējǔ kǎoshì zuòguān.","vi":"Người đọc sách thời xưa phần lớn mong đỗ khoa cử để làm quan."},{"type":"compound","zh":"他虽然是个读书人，但是干起农活来一点也不含糊。","pinyin":"Tā suīrán shì gè dúshūrén, dànshì gàn qǐ nónghuó lái yìdiǎn yě bù hánhu.","vi":"Anh ấy tuy là người trí thức, nhưng làm việc đồng áng chẳng hề kém cỏi."}],"related":[{"hanzi":"知识分子","pinyin":"zhīshifènzǐ","vi":"trí thức"},{"hanzi":"书生","pinyin":"shūshēng","vi":"thư sinh"},{"hanzi":"文人","pinyin":"wénrén","vi":"văn nhân"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"}],"traditional":"讀書人"},{"id":"单边主义","hanzi":"单边主义","pinyin":"dānbiānzhǔyì","meaning_vi":"chủ nghĩa đơn phương","explanation":"单 (单) + 边 (bên) + 主 (chủ động/chủ quyền) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"我们反对单边主义。","pinyin":"Wǒmen fǎnduì dānbiānzhǔyì.","vi":"Chúng tôi phản đối chủ nghĩa đơn phương."},{"type":"simple","zh":"单边主义的贸易政策损害了全球供应链。","pinyin":"Dānbiānzhǔyì de màoyì zhèngcè sǔnhàile quánqiú gōngyìngliàn.","vi":"Chính sách thương mại theo chủ nghĩa đơn phương đã gây tổn hại cho chuỗi cung ứng toàn cầu."},{"type":"compound","zh":"一旦大国奉行单边主义，国际规则就会失去约束力。","pinyin":"Yídàn dàguó fèngxíng dānbiānzhǔyì, Guójì guīzé jiù huì shīqù yuēshùlì.","vi":"Một khi nước lớn theo đuổi chủ nghĩa đơn phương, các quy tắc quốc tế sẽ mất đi tính ràng buộc."}],"related":[{"hanzi":"多边主义","pinyin":"duōbiānzhǔyì","vi":"chủ nghĩa đa phương"},{"hanzi":"单边","pinyin":"dānbiān","vi":"đơn phương"},{"hanzi":"霸权主义","pinyin":"bàquánzhǔyì","vi":"chủ nghĩa bá quyền"},{"hanzi":"保护主义","pinyin":"bǎohùzhǔyì","vi":"chủ nghĩa bảo hộ"}],"traditional":"單邊主義"},{"id":"担保人","hanzi":"担保人","pinyin":"dānbǎorén","meaning_vi":"người bảo lãnh","explanation":"担保 (đảm bảo – bảo lãnh) + 人 (nhân – người) → người đứng ra bảo lãnh (cho khoản vay, hợp đồng). VD: 做担保人.","hsk_level":"7-9","tags":["danh-tu","phap-luat","con-nguoi"],"image":"✍️","examples":[{"type":"basic","zh":"我愿意做你的担保人。","pinyin":"Wǒ yuànyì zuò nǐ de dānbǎorén.","vi":"Tôi sẵn lòng làm người bảo lãnh cho bạn."},{"type":"simple","zh":"申请这笔贷款需要提供一名有稳定收入的担保人。","pinyin":"Shēnqǐng zhè bǐ dàikuǎn xūyào tígōng yì míng yǒu wěndìng shōurù de dānbǎorén.","vi":"Xin khoản vay này cần có một người bảo lãnh có thu nhập ổn định."},{"type":"compound","zh":"如果借款人到期不还钱，担保人就要承担还款责任。","pinyin":"Rúguǒ jièkuǎnrén dàoqī bù huán qián, dānbǎorén jiùyào chéngdān huánkuǎn zérèn.","vi":"Nếu người vay đến hạn không trả tiền thì người bảo lãnh phải chịu trách nhiệm trả nợ."}],"related":[{"hanzi":"担保","pinyin":"dānbǎo","vi":"bảo lãnh"},{"hanzi":"保证人","pinyin":"bǎozhèngrén","vi":"người bảo đảm"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"khoản vay"},{"hanzi":"抵押","pinyin":"dǐyā","vi":"thế chấp"}],"traditional":"擔保人"},{"id":"当家","hanzi":"当家","pinyin":"dāngjiā","meaning_vi":"làm chủ gia đình","explanation":"当 (đương – đảm nhận) + 家 (gia – nhà) → làm chủ gia đình, quản việc nhà; nghĩa bóng: làm chủ. VD: 当家作主.","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"我家是妈妈当家。","pinyin":"Wǒ jiā shì māma dāngjiā.","vi":"Nhà tôi là mẹ làm chủ."},{"type":"simple","zh":"父亲去世后，十八岁的大哥开始当家。","pinyin":"Fùqīn qùshì hòu, shíbā suì de dàgē kāishǐ dāngjiā.","vi":"Sau khi cha mất, anh cả mười tám tuổi bắt đầu gánh vác gia đình."},{"type":"compound","zh":"不当家不知柴米贵，自己一当家，我就开始记账了。","pinyin":"Bù dāngjiā bùzhī chái mǐ guì, zìjǐ yì dāngjiā, wǒ jiù kāishǐ jìzhàng le.","vi":"Không làm chủ nhà thì không biết củi gạo đắt, tự mình vừa quản lý gia đình là tôi bắt đầu ghi chép chi tiêu."}],"related":[{"hanzi":"当家作主","pinyin":"dāngjiāzuòzhǔ","vi":"làm chủ gia đình"},{"hanzi":"主人","pinyin":"zhǔrén","vi":"chủ nhân"},{"hanzi":"持家","pinyin":"chíjiā","vi":"quán xuyến gia đình"},{"hanzi":"当家人","pinyin":"dāngjiārén","vi":"người chủ gia đình"}],"traditional":"當家"},{"id":"登月","hanzi":"登月","pinyin":"dēngyuè","meaning_vi":"đổ bộ lên Mặt Trăng","explanation":"登 (đăng – leo lên) + 月 (nguyệt – mặt trăng) → lên Mặt Trăng, đổ bộ Mặt Trăng. VD: 登月计划, 人类首次登月.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🌕","examples":[{"type":"basic","zh":"人类首次登月成功。","pinyin":"Rénlèi shǒucì dēngyuè chénggōng.","vi":"Loài người lần đầu đổ bộ lên Mặt Trăng thành công."},{"type":"simple","zh":"阿姆斯特朗是第一个登月的宇航员。","pinyin":"Āmǔsītèlǎng shì dìyī gè dēngyuè de yǔhángyuán.","vi":"Armstrong là phi hành gia đầu tiên đặt chân lên Mặt Trăng."},{"type":"compound","zh":"虽然登月已经过去半个多世纪，但是人们对月球的兴趣从未减退。","pinyin":"Suīrán dēngyuè yǐjīng guòqù bàn gè duō shìjì, dànshì rénmen duì yuèqiú de xìngqù cóngwèi jiǎntuì.","vi":"Tuy cuộc đổ bộ Mặt Trăng đã qua hơn nửa thế kỷ, nhưng sự quan tâm của con người đối với Mặt Trăng chưa bao giờ giảm."}],"related":[{"hanzi":"宇航员","pinyin":"yǔhángyuán","vi":"phi hành gia"},{"hanzi":"月球","pinyin":"yuèqiú","vi":"mặt trăng"},{"hanzi":"航天","pinyin":"hángtiān","vi":"hàng không vũ trụ"},{"hanzi":"嫦娥","pinyin":"Cháng'é","vi":"Hằng Nga"}]},{"id":"低谷期","hanzi":"低谷期","pinyin":"dīgǔqī","meaning_vi":"giai đoạn khó khăn, thời kỳ sa sút","explanation":"低 (thấp (mức độ/nhiệt độ/giá cả)) + 谷 (谷) + 期 (期).","hsk_level":"7-9","tags":["danh-tu","thoi-gian","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"他正处于低谷期。","pinyin":"Tā zhèng chǔyú dīgǔqī.","vi":"Anh ấy đang ở giai đoạn khó khăn."},{"type":"simple","zh":"公司在疫情期间经历了创业以来最长的低谷期。","pinyin":"Gōngsī zài yìqíng qījiān jīnglìle chuàngyè yǐlái zuì cháng de dīgǔqī.","vi":"Trong thời kỳ dịch bệnh, công ty đã trải qua giai đoạn khó khăn dài nhất kể từ khi khởi nghiệp."},{"type":"compound","zh":"只要熬过这段低谷期，你的事业就会迎来转机。","pinyin":"Zhǐyào áoguò zhè duàn dīgǔqī, nǐ de shìyè jiù huì yínglái zhuǎnjī.","vi":"Chỉ cần vượt qua giai đoạn khó khăn này, sự nghiệp của bạn sẽ đón bước ngoặt."}],"related":[{"hanzi":"低谷","pinyin":"dīgǔ","vi":"đáy vực"},{"hanzi":"高峰期","pinyin":"gāofēngqī","vi":"thời kỳ đỉnh cao"},{"hanzi":"瓶颈期","pinyin":"píngjǐngqī","vi":"giai đoạn bế tắc"},{"hanzi":"困境","pinyin":"kùnjìng","vi":"cảnh khó khăn"}]},{"id":"低收入","hanzi":"低收入","pinyin":"dīshōurù","meaning_vi":"thu nhập thấp","explanation":"低 (thấp (mức độ/nhiệt độ/giá cả)) + 收 (nhận) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["tinh-tu","tien-te","xa-hoi"],"image":"💵","examples":[{"type":"basic","zh":"他属于低收入人群。","pinyin":"Tā shǔyú dīshōurù rénqún.","vi":"Anh ấy thuộc nhóm người thu nhập thấp."},{"type":"simple","zh":"市政府为低收入家庭提供了廉租房。","pinyin":"Shìzhèngfǔ wèi dīshōurù jiātíng tígōngle liánzūfáng.","vi":"Chính quyền thành phố cung cấp nhà cho thuê giá rẻ cho các gia đình thu nhập thấp."},{"type":"compound","zh":"因为物价上涨太快，所以低收入群体的生活压力越来越大。","pinyin":"Yīnwèi wùjià shàngzhǎng tài kuài, suǒyǐ dīshōurù qúntǐ de shēnghuó yālì yuèláiyuè dà.","vi":"Vì giá cả tăng quá nhanh nên áp lực sinh hoạt của nhóm thu nhập thấp ngày càng lớn."}],"related":[{"hanzi":"高收入","pinyin":"gāoshōurù","vi":"thu nhập cao"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"},{"hanzi":"中等收入","pinyin":"zhōngděngshōurù","vi":"thu nhập trung bình"}]},{"id":"低碳环保","hanzi":"低碳环保","pinyin":"dītànhuánbǎo","meaning_vi":"cacbon thấp bảo vệ môi trường","explanation":"低碳 (đê thán – ít khí carbon) + 环保 (hoàn bảo – bảo vệ môi trường) → lối sống, sản xuất ít phát thải carbon và thân thiện môi trường.","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌍","examples":[{"type":"basic","zh":"骑车出行低碳环保。","pinyin":"Qíchē chūxíng dītànhuánbǎo.","vi":"Đi xe đạp vừa ít khí thải carbon vừa bảo vệ môi trường."},{"type":"simple","zh":"这栋办公楼采用了低碳环保的太阳能供电系统。","pinyin":"Zhè dòng bàngōnglóu cǎiyòngle dītànhuánbǎo de tàiyángnéng gōngdiàn xìtǒng.","vi":"Tòa văn phòng này sử dụng hệ thống cấp điện mặt trời ít carbon, thân thiện môi trường."},{"type":"compound","zh":"既然大家都提倡低碳环保，我们就从少用塑料袋做起。","pinyin":"Jìrán dàjiā dōu tíchàng dītànhuánbǎo, wǒmen jiù cóng shǎo yòng sùliàodài zuò qǐ.","vi":"Đã mọi người đều khuyến khích lối sống ít carbon bảo vệ môi trường thì chúng ta hãy bắt đầu từ việc dùng ít túi nilon."}],"related":[{"hanzi":"低碳","pinyin":"dītàn","vi":"cacbon thấp"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"},{"hanzi":"节能减排","pinyin":"jiénéngjiǎnpái","vi":"tiết kiệm năng lượng giảm thải"},{"hanzi":"绿色出行","pinyin":"lǜsèchūxíng","vi":"đi lại xanh"}],"traditional":"低碳環保"},{"id":"东半球","hanzi":"东半球","pinyin":"Dōngbànqiú","meaning_vi":"bán cầu Đông","explanation":"东 (hướng Đông) + 半 (một nửa) + 球 (球).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"中国位于东半球。","pinyin":"Zhōngguó wèiyú Dōngbànqiú.","vi":"Trung Quốc nằm ở bán cầu Đông."},{"type":"simple","zh":"地理老师在地球仪上给我们指出了东半球的范围。","pinyin":"Dìlǐ lǎoshī zài dìqiúyí shàng gěi wǒmen zhǐchūle Dōngbànqiú de fànwéi.","vi":"Thầy địa lý chỉ cho chúng tôi phạm vi bán cầu Đông trên quả địa cầu."},{"type":"compound","zh":"因为处在东半球，所以亚洲比美洲更早迎来新年。","pinyin":"Yīnwèi chǔzài Dōngbànqiú, suǒyǐ Yàzhōu bǐ Měizhōu gèng zǎo yínglái xīnnián.","vi":"Vì nằm ở bán cầu Đông nên châu Á đón năm mới sớm hơn châu Mỹ."}],"related":[{"hanzi":"西半球","pinyin":"Xībànqiú","vi":"bán cầu Tây"},{"hanzi":"北半球","pinyin":"Běibànqiú","vi":"bán cầu Bắc"},{"hanzi":"南半球","pinyin":"Nánbànqiú","vi":"bán cầu Nam"},{"hanzi":"地球","pinyin":"dìqiú","vi":"trái đất"}],"traditional":"東半球"},{"id":"东道国","hanzi":"东道国","pinyin":"Dōngdàoguó","meaning_vi":"nước chủ nhà đăng cai","explanation":"东 (hướng Đông) + 道 (道) + 国 (nước).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-danh"],"image":"🏟️","examples":[{"type":"basic","zh":"越南是本届东道国。","pinyin":"Yuènán shì běnjiè Dōngdàoguó.","vi":"Việt Nam là nước chủ nhà của kỳ này."},{"type":"simple","zh":"东道国为各国代表团安排了丰富的文化活动。","pinyin":"Dōngdàoguó wèi gèguó dàibiǎotuán ānpáile fēngfù de wénhuà huódòng.","vi":"Nước chủ nhà đã sắp xếp nhiều hoạt động văn hóa phong phú cho đoàn đại biểu các nước."},{"type":"compound","zh":"作为东道国，我们不但要办好比赛，而且要展示好国家形象。","pinyin":"Zuòwéi Dōngdàoguó, wǒmen búdàn yào bànhǎo bǐsài, érqiě yào zhǎnshì hǎo guójiā xíngxiàng.","vi":"Là nước chủ nhà, chúng ta không những phải tổ chức tốt cuộc thi mà còn phải thể hiện tốt hình ảnh quốc gia."}],"related":[{"hanzi":"东道主","pinyin":"dōngdàozhǔ","vi":"chủ nhà"},{"hanzi":"主办","pinyin":"zhǔbàn","vi":"đăng cai"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"tổ chức"},{"hanzi":"东道主队","pinyin":"dōngdàozhǔduì","vi":"đội chủ nhà"}],"traditional":"東道國"},{"id":"冬奥会","hanzi":"冬奥会","pinyin":"Dōng'àohuì","meaning_vi":"Thế vận hội Mùa đông","explanation":"冬 (冬) + 奥 (sâu xa/huyền bí) + 会 (biết (kỹ năng)).","hsk_level":"7-9","tags":["danh-tu","the-thao","van-hoa"],"image":"⛷️","examples":[{"type":"basic","zh":"我在看冬奥会直播。","pinyin":"Wǒ zài kàn Dōng'àohuì zhíbō.","vi":"Tôi đang xem trực tiếp Thế vận hội Mùa đông."},{"type":"simple","zh":"这名滑雪运动员在冬奥会上夺得了金牌。","pinyin":"Zhè míng huáxuě yùndòngyuán zài Dōng'àohuì shàng duó déle jīnpái.","vi":"Vận động viên trượt tuyết này đã giành huy chương vàng tại Thế vận hội Mùa đông."},{"type":"compound","zh":"北京既举办过夏奥会，又举办过冬奥会。","pinyin":"Běijīng jì jǔbànguo Xià'àohuì, yòu jǔbàn guodōng Àohuì.","vi":"Bắc Kinh vừa từng tổ chức Thế vận hội Mùa hè, vừa từng tổ chức Thế vận hội Mùa đông."}],"related":[{"hanzi":"奥运会","pinyin":"Àoyùnhuì","vi":"Thế vận hội"},{"hanzi":"冬季","pinyin":"dōngjì","vi":"mùa đông"},{"hanzi":"滑雪","pinyin":"huáxuě","vi":"trượt tuyết"},{"hanzi":"残奥会","pinyin":"Cán'àohuì","vi":"Paralympic"}],"traditional":"冬奧會"},{"id":"敦促","hanzi":"敦促","pinyin":"dūncù","meaning_vi":"đôn đốc, thúc giục (ngoại giao)","explanation":"敦 (chân thành/đôn đốc) + 促 (thúc đẩy/gấp gáp).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"联合国敦促双方停火。","pinyin":"Liánhéguó dūncù shuāngfāng tínghuǒ.","vi":"Liên Hợp Quốc hối thúc hai bên ngừng bắn."},{"type":"simple","zh":"外交部敦促该国立即释放被扣押的渔民。","pinyin":"Wàijiāobù dūncù gāi guó lìjí shìfàng bèi kòuyā de yúmín.","vi":"Bộ Ngoại giao hối thúc nước đó lập tức thả những ngư dân bị bắt giữ."},{"type":"compound","zh":"如果对方继续拖延，我们就将再次敦促其履行协议。","pinyin":"Rúguǒ duìfāng jìxù tuōyán, wǒmen jiù jiāng zàicì dūncù qí lǚxíng xiéyì.","vi":"Nếu đối phương tiếp tục trì hoãn, chúng tôi sẽ lại hối thúc họ thực hiện thỏa thuận."}],"related":[{"hanzi":"督促","pinyin":"dūcù","vi":"đôn đốc"},{"hanzi":"催促","pinyin":"cuīcù","vi":"thúc giục"},{"hanzi":"呼吁","pinyin":"hūyù","vi":"kêu gọi"},{"hanzi":"要求","pinyin":"yāoqiú","vi":"yêu cầu"}]},{"id":"敦煌莫高窟","hanzi":"敦煌莫高窟","pinyin":"Dūnhuáng Mògāokū","meaning_vi":"hang đá Mạc Cao Đôn Hoàng","explanation":"Di sản văn hóa thế giới ở Cam Túc.","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏛️","examples":[{"type":"basic","zh":"我参观了敦煌莫高窟。","pinyin":"Wǒ cānguānle dūnhuángmògāokū.","vi":"Tôi đã tham quan hang đá Mạc Cao Đôn Hoàng."},{"type":"simple","zh":"敦煌莫高窟保存着大量精美的古代壁画。","pinyin":"Dūnhuángmògāokū bǎocúnzhe dàliàng jīngměi de gǔdài bìhuà.","vi":"Hang đá Mạc Cao Đôn Hoàng lưu giữ rất nhiều bích họa cổ tinh xảo."},{"type":"compound","zh":"因为壁画十分脆弱，所以敦煌莫高窟每天限量接待游客。","pinyin":"Yīnwèi bìhuà shífēn cuìruò, suǒyǐ dūnhuángmògāokū měitiān xiànliàng jiēdài yóukè.","vi":"Vì các bích họa rất dễ hư hại nên hang Mạc Cao Đôn Hoàng mỗi ngày chỉ đón số lượng khách giới hạn."}],"related":[{"hanzi":"敦煌","pinyin":"Dūnhuáng","vi":"Đôn Hoàng"},{"hanzi":"石窟","pinyin":"shíkū","vi":"hang đá"},{"hanzi":"壁画","pinyin":"bìhuà","vi":"bích họa"},{"hanzi":"丝绸之路","pinyin":"Sīchóuzhīlù","vi":"Con đường Tơ lụa"}]},{"id":"打假","hanzi":"打假","pinyin":"dǎjiǎ","meaning_vi":"chống hàng giả","explanation":"打 (đánh) + 假 (giả mạo/giả sử).","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🚫","examples":[{"type":"basic","zh":"市场监管局在打假。","pinyin":"Shìchǎng jiānguǎn jú zài dǎjiǎ.","vi":"Cục Quản lý thị trường đang chống hàng giả."},{"type":"simple","zh":"这位网红专门在视频里帮消费者打假。","pinyin":"Zhè wèi wǎnghóng zhuānmén zài shìpín lǐ bāng xiāofèizhě dǎjiǎ.","vi":"Người nổi tiếng trên mạng này chuyên giúp người tiêu dùng vạch trần hàng giả qua video."},{"type":"compound","zh":"只要各部门联合打假，假冒名牌就没有生存空间。","pinyin":"Zhǐyào gè bùmén liánhé dǎjiǎ, jiǎmào míngpái jiù méiyǒu shēngcún kōngjiān.","vi":"Chỉ cần các ngành phối hợp chống hàng giả thì hàng nhái thương hiệu sẽ không còn chỗ đứng."}],"related":[{"hanzi":"假货","pinyin":"jiǎhuò","vi":"hàng giả"},{"hanzi":"冒牌","pinyin":"màopái","vi":"nhái thương hiệu"},{"hanzi":"维权","pinyin":"wéiquán","vi":"bảo vệ quyền lợi"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"}]},{"id":"打卡","hanzi":"打卡","pinyin":"dǎkǎ","meaning_vi":"chấm công; check-in (địa điểm du lịch, quán nổi tiếng)","explanation":"打 (đả – đánh, làm) + 卡 (thẻ) → quẹt thẻ chấm công; nghĩa mới: check-in, ghé chụp ảnh tại địa điểm nổi tiếng. VD: 网红打卡地.","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"📸","examples":[{"type":"basic","zh":"上班别忘了打卡。","pinyin":"Shàngbān bié wàngle dǎkǎ.","vi":"Đi làm đừng quên chấm công."},{"type":"simple","zh":"周末很多游客专门来这家网红咖啡馆打卡。","pinyin":"Zhōumò hěn duō yóukè zhuānmén lái zhè jiā wǎnghóng kāfēiguǎn dǎkǎ.","vi":"Cuối tuần nhiều du khách đến quán cà phê nổi tiếng này để check-in."},{"type":"compound","zh":"如果早上八点半以后才打卡，就算迟到。","pinyin":"Rúguǒ zǎoshang bā diǎn bàn yǐhòu cái dǎkǎ, jiùsuàn chídào.","vi":"Nếu sau tám giờ rưỡi sáng mới chấm công thì tính là đi muộn."}],"related":[{"hanzi":"签到","pinyin":"qiāndào","vi":"điểm danh"},{"hanzi":"网红","pinyin":"wǎnghóng","vi":"người nổi tiếng mạng"},{"hanzi":"上班","pinyin":"shàngbān","vi":"đi làm"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"}]},{"id":"倒计时","hanzi":"倒计时","pinyin":"dàojìshí","meaning_vi":"đếm ngược thời gian","explanation":"倒 (đổ) + 计 (kế hoạch/tính toán) + 时 (thời đại/thời cơ).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏱️","examples":[{"type":"basic","zh":"高考进入倒计时。","pinyin":"Gāokǎo jìnrù dàojìshí.","vi":"Kỳ thi đại học đã bước vào giai đoạn đếm ngược."},{"type":"simple","zh":"新年钟声响起前，广场上的人们一起大声倒计时。","pinyin":"Xīnnián zhōngshēng xiǎngqǐ qián, guǎngchǎng shàng de rénmen yìqǐ dàshēng dàojìshí.","vi":"Trước khi chuông năm mới vang lên, mọi người trên quảng trường cùng hô to đếm ngược."},{"type":"compound","zh":"倒计时一结束，巨大的火箭就点火升空了。","pinyin":"Dàojìshí yì jiéshù, jùdà de huǒjiàn jiù diǎnhuǒ shēngkōng le.","vi":"Đếm ngược vừa kết thúc, tên lửa khổng lồ liền đánh lửa bay lên."}],"related":[{"hanzi":"计时","pinyin":"jìshí","vi":"tính giờ"},{"hanzi":"倒数","pinyin":"dàoshǔ","vi":"đếm ngược"},{"hanzi":"期限","pinyin":"qīxiàn","vi":"thời hạn"},{"hanzi":"秒表","pinyin":"miǎobiǎo","vi":"đồng hồ bấm giờ"}],"traditional":"倒計時"},{"id":"砥砺前行","hanzi":"砥砺前行","pinyin":"dǐlì-qiánxíng","meaning_vi":"vững bước tiến lên vượt qua gian khó","explanation":"砥 (đá mài/rèn giũa) + 砺 (mài giũa/rèn luyện) + 前 (trước) + 行 (được).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🚀","examples":[{"type":"basic","zh":"我们要砥砺前行。","pinyin":"Wǒmen yào dǐlìqiánxíng.","vi":"Chúng ta phải vững bước tiến lên."},{"type":"simple","zh":"这支年轻的科研团队在失败中砥砺前行。","pinyin":"Zhè zhī niánqīng de kēyán tuánduì zài shībài zhōng dǐlìqiánxíng.","vi":"Đội nghiên cứu trẻ này rèn luyện bản thân trong thất bại và vững bước tiến lên."},{"type":"compound","zh":"即使前路充满荆棘，我们也要不忘初心、砥砺前行。","pinyin":"Jíshǐ qiánlù chōngmǎn jīngjí, wǒmen yě yàobú wàng chūxīn, dǐlìqiánxíng.","vi":"Dù con đường phía trước đầy chông gai, chúng ta vẫn phải giữ vững ý nguyện ban đầu, kiên cường tiến bước."}],"related":[{"hanzi":"奋勇前进","pinyin":"fènyǒngqiánjìn","vi":"dũng cảm tiến lên"},{"hanzi":"迎难而上","pinyin":"yíngnán'érshàng","vi":"đón khó mà lên"},{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì không mệt mỏi"},{"hanzi":"砥砺","pinyin":"dǐlì","vi":"rèn luyện"}],"traditional":"砥礪前行"},{"id":"夫唱妇随","hanzi":"夫唱妇随","pinyin":"fūchàng-fùsuí","meaning_vi":"chồng xướng vợ họa (vợ chồng hòa thuận)","explanation":"夫 (夫) + 唱 (hát) + 妇 (妇) + 随 (tùy ý/đi theo).","hsk_level":"7-9","tags":["thanh-ngu","gia-dinh"],"image":"💑","examples":[{"type":"basic","zh":"老两口夫唱妇随。","pinyin":"Lǎoliǎngkǒu fūchàngfùsuí.","vi":"Hai ông bà chồng xướng vợ họa."},{"type":"simple","zh":"这对夫妻夫唱妇随，一起经营着一家小面馆。","pinyin":"Zhè duì fūqī fūchàngfùsuí, yìqǐ jīngyíngzhe yìjiā xiǎo miànguǎn.","vi":"Đôi vợ chồng này chồng xướng vợ họa, cùng kinh doanh một quán mì nhỏ."},{"type":"compound","zh":"他一说要去支教，妻子就夫唱妇随地跟着去了山区。","pinyin":"Tā yìshuō yào qù zhījiào, qīzi jiù fūchàngfùsuí de gēnzhe qùle shānqū.","vi":"Anh ấy vừa nói muốn đi dạy tình nguyện, vợ liền đồng lòng theo chồng lên vùng núi."}],"related":[{"hanzi":"相敬如宾","pinyin":"xiāngjìngrúbīn","vi":"tương kính như tân"},{"hanzi":"白头偕老","pinyin":"báitóuxiélǎo","vi":"bách niên giai lão"},{"hanzi":"夫妻","pinyin":"fūqī","vi":"vợ chồng"},{"hanzi":"举案齐眉","pinyin":"jǔ'ànqíméi","vi":"vợ chồng kính trọng nhau"}],"traditional":"夫唱婦隨"},{"id":"服务业","hanzi":"服务业","pinyin":"fúwùyè","meaning_vi":"ngành dịch vụ","explanation":"服 (服) + 务 (nhiệm vụ/thiết thực) + 业 (sự nghiệp/ngành nghề).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏨","examples":[{"type":"basic","zh":"服务业发展很快。","pinyin":"Fúwùyè fāzhǎn hěn kuài.","vi":"Ngành dịch vụ phát triển rất nhanh."},{"type":"simple","zh":"这座旅游城市一半以上的人口从事服务业。","pinyin":"Zhè zuò lǚyóu chéngshì yíbàn yǐshàng de rénkǒu cóngshì fúwùyè.","vi":"Hơn một nửa dân số thành phố du lịch này làm việc trong ngành dịch vụ."},{"type":"compound","zh":"一旦游客数量减少，当地的服务业就会首先受到影响。","pinyin":"Yídàn yóukè shùliàng jiǎnshǎo, dāngdì de fúwùyè jiù huì shǒuxiān shòudào yǐngxiǎng.","vi":"Một khi lượng du khách giảm, ngành dịch vụ địa phương sẽ bị ảnh hưởng đầu tiên."}],"related":[{"hanzi":"第三产业","pinyin":"dìsānchǎnyè","vi":"ngành dịch vụ"},{"hanzi":"制造业","pinyin":"zhìzàoyè","vi":"ngành chế tạo"},{"hanzi":"农业","pinyin":"nóngyè","vi":"nông nghiệp"},{"hanzi":"服务员","pinyin":"fúwùyuán","vi":"nhân viên phục vụ"}],"traditional":"服務業"},{"id":"范例","hanzi":"范例","pinyin":"fànlì","meaning_vi":"ví dụ mẫu mực, điển hình","explanation":"范 (范) + 例 (ví dụ/thông lệ).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"这是一个好范例。","pinyin":"Zhè shì yí gè hǎo fànlì.","vi":"Đây là một ví dụ mẫu mực."},{"type":"simple","zh":"老师把她的作文当作范例读给全班听。","pinyin":"Lǎoshī bǎ tā de zuòwén dàngzuò fànlì dú gěi quánbān tīng.","vi":"Cô giáo lấy bài văn của cô ấy làm bài mẫu đọc cho cả lớp nghe."},{"type":"compound","zh":"这个旧厂房改造项目不但保留了历史，而且成了城市更新的范例。","pinyin":"Zhè Gejiù chǎngfáng gǎizào xiàngmù búdàn bǎoliúle lìshǐ, érqiě chéngle chéngshì gēngxīn de fànlì.","vi":"Dự án cải tạo nhà xưởng cũ này không những giữ lại được lịch sử mà còn trở thành điển hình của việc tái thiết đô thị."}],"related":[{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"},{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"例子","pinyin":"lìzi","vi":"ví dụ"},{"hanzi":"样板","pinyin":"yàngbǎn","vi":"hình mẫu"}],"traditional":"範例"},{"id":"犯罪","hanzi":"犯罪","pinyin":"fànzuì","meaning_vi":"phạm tội","explanation":"犯 + 罪 (tội). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚔","examples":[{"type":"basic","zh":"他没有犯罪记录。","pinyin":"Tā méiyǒu fànzuì jìlù.","vi":"Anh ấy không có tiền án."},{"type":"simple","zh":"警方利用人脸识别技术抓获了一名犯罪嫌疑人。","pinyin":"Jǐngfāng lìyòng rénliǎnshíbié jìshù zhuāhuòle yì míng fànzuì xiányírén.","vi":"Cảnh sát dùng công nghệ nhận diện khuôn mặt bắt được một nghi phạm."},{"type":"compound","zh":"即使是未成年人，故意犯罪也要承担相应的法律责任。","pinyin":"Jíshǐ shì wèichéngniánrén, gùyì fànzuì yě yào chéngdān xiāngyìng de fǎlǜ zérèn.","vi":"Dù là người chưa thành niên, cố ý phạm tội cũng phải chịu trách nhiệm pháp lý tương ứng."}],"related":[{"hanzi":"罪犯","pinyin":"zuìfàn","vi":"tội phạm"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"},{"hanzi":"犯罪嫌疑人","pinyin":"fànzuì xiányírén","vi":"nghi phạm"},{"hanzi":"罪行","pinyin":"zuìxíng","vi":"tội ác"}]},{"id":"放眼","hanzi":"放眼","pinyin":"fàngyǎn","meaning_vi":"phóng tầm mắt nhìn rộng ra","explanation":"放 (đặt) + 眼 (ánh mắt/tầm nhìn).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔭","examples":[{"type":"basic","zh":"放眼望去，满是花海。","pinyin":"Fàngyǎn wàng qù, mǎnshì huāhǎi.","vi":"Phóng tầm mắt nhìn ra, khắp nơi là biển hoa."},{"type":"simple","zh":"我们站在长城上放眼远眺连绵的群山。","pinyin":"Wǒmen zhàn zài Chángchéng shàng fàngyǎn yuǎntiào liánmián de qúnshān.","vi":"Chúng tôi đứng trên Vạn Lý Trường Thành phóng tầm mắt nhìn những dãy núi trùng điệp."},{"type":"compound","zh":"企业如果只盯着眼前利益，而不放眼长远，就很难做大。","pinyin":"Qǐyè rúguǒ zhǐ dīngzhe yǎnqián lìyì, ér bú fàngyǎn chángyuǎn, jiù hěn nán zuòdà.","vi":"Doanh nghiệp nếu chỉ chăm chăm vào lợi ích trước mắt mà không nhìn xa trông rộng thì khó lớn mạnh được."}],"related":[{"hanzi":"放眼世界","pinyin":"fàngyǎnshìjiè","vi":"phóng tầm mắt ra thế giới"},{"hanzi":"眺望","pinyin":"tiàowàng","vi":"nhìn xa"},{"hanzi":"展望","pinyin":"zhǎnwàng","vi":"triển vọng"},{"hanzi":"着眼","pinyin":"zhuóyǎn","vi":"chú ý đến"}]},{"id":"凡人","hanzi":"凡人","pinyin":"fánrén","meaning_vi":"người phàm, người bình thường","explanation":"凡 (phàm – tầm thường) + 人 (nhân – người) → người phàm, người bình thường (đối lập với thần tiên, vĩ nhân). VD: 我只是个凡人.","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"👤","examples":[{"type":"basic","zh":"我只是个凡人。","pinyin":"Wǒ zhǐshì gè fánrén.","vi":"Tôi chỉ là một người phàm."},{"type":"simple","zh":"神话里的仙女爱上了一个普通的凡人。","pinyin":"Shénhuà lǐ de xiānnǚ àishàngle yí gè pǔtōng de fánrén.","vi":"Nàng tiên trong thần thoại đã yêu một người phàm bình thường."},{"type":"compound","zh":"既然大家都是凡人，就难免会有犯错的时候。","pinyin":"Jìrán dàjiā dōu shì fánrén, jiù nánmiǎn huì yǒu fàncuò de shíhou.","vi":"Đã là người phàm thì ai cũng khó tránh khỏi lúc mắc sai lầm."}],"related":[{"hanzi":"普通人","pinyin":"pǔtōngrén","vi":"người bình thường"},{"hanzi":"平凡","pinyin":"píngfán","vi":"bình thường"},{"hanzi":"神仙","pinyin":"shénxiān","vi":"thần tiên"},{"hanzi":"凡夫俗子","pinyin":"fánfūsúzǐ","vi":"người phàm tục"}]},{"id":"繁衍","hanzi":"繁衍","pinyin":"fányǎn","meaning_vi":"sinh sôi nảy nở, duy trì nòi giống","explanation":"繁 (phồn hoa/nhiều) + 衍 (衍).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🐾","examples":[{"type":"basic","zh":"野兔繁衍得很快。","pinyin":"Yětù fányǎn de hěn kuài.","vi":"Thỏ rừng sinh sôi rất nhanh."},{"type":"simple","zh":"这个家族在这片土地上已经繁衍了二十多代。","pinyin":"Zhè ge jiāzú zài zhè piàn tǔdì shàng yǐjīng fányǎnle èrshíduō dài.","vi":"Dòng họ này đã sinh sôi nảy nở trên mảnh đất này hơn hai mươi đời."},{"type":"compound","zh":"如果湿地继续被破坏，候鸟就无法在这里繁衍后代。","pinyin":"Rúguǒ shīdì jìxù bèi pòhuài, hòuniǎo jiù wúfǎ zài zhèlǐ fányǎn hòudài.","vi":"Nếu vùng đất ngập nước tiếp tục bị phá hoại, chim di cư sẽ không thể sinh sản ở đây."}],"related":[{"hanzi":"繁殖","pinyin":"fánzhí","vi":"sinh sôi"},{"hanzi":"生息","pinyin":"shēngxī","vi":"sinh sống"},{"hanzi":"后代","pinyin":"hòudài","vi":"đời sau"},{"hanzi":"繁衍生息","pinyin":"fányǎnshēngxī","vi":"sinh sôi nảy nở"}]},{"id":"房地产","hanzi":"房地产","pinyin":"fángdìchǎn","meaning_vi":"nhà đất, bất động sản","explanation":"房 (nhà) + 地 (đất) + 产.","hsk_level":"7-9","tags":["danh-tu","nha-cua","cong-viec"],"image":"🏙️","examples":[{"type":"basic","zh":"他在做房地产生意。","pinyin":"Tā zài zuò fángdìchǎn shēngyi.","vi":"Ông ấy đang kinh doanh bất động sản."},{"type":"simple","zh":"这座城市的房地产价格三年内上涨了一倍。","pinyin":"Zhè zuò chéngshì de fángdìchǎn jiàgé sān niánnèi shàngzhǎngle yí bèi.","vi":"Giá bất động sản ở thành phố này đã tăng gấp đôi trong ba năm."},{"type":"compound","zh":"虽然房地产市场有所降温，但是市中心的房子依然抢手。","pinyin":"Suīrán fángdìchǎn shìchǎng yǒusuǒ jiàngwēn, dànshì shìzhōngxīn de fángzi yīrán qiǎngshǒu.","vi":"Tuy thị trường bất động sản đã hạ nhiệt phần nào nhưng nhà ở trung tâm thành phố vẫn đắt hàng."}],"related":[{"hanzi":"不动产","pinyin":"búdòngchǎn","vi":"bất động sản"},{"hanzi":"房价","pinyin":"fángjià","vi":"giá nhà"},{"hanzi":"楼盘","pinyin":"lóupán","vi":"dự án nhà ở"},{"hanzi":"开发商","pinyin":"kāifāshāng","vi":"nhà phát triển"}],"traditional":"房地產"},{"id":"防范","hanzi":"防范","pinyin":"fángfàn","meaning_vi":"phòng ngừa, đề phòng","explanation":"防 (phòng – ngăn ngừa) + 范 (phạm – khuôn phép, đề phòng) → phòng ngừa, đề phòng rủi ro, gian lận. VD: 防范风险, 防范意识.","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"要防范电信诈骗。","pinyin":"Yào fángfàn diànxìn zhàpiàn.","vi":"Phải đề phòng lừa đảo viễn thông."},{"type":"simple","zh":"银行提醒老年人提高对陌生来电的防范意识。","pinyin":"Yínháng tíxǐng lǎoniánrén tígāo duì mòshēng láidiàn de fángfàn yìshí.","vi":"Ngân hàng nhắc người cao tuổi nâng cao ý thức đề phòng các cuộc gọi lạ."},{"type":"compound","zh":"只要提前做好防范，台风来了损失就能降到最低。","pinyin":"Zhǐyào tíqián zuò hǎo fángfàn, táifēng láile sǔnshī jiù néng jiàng dào zuì dī.","vi":"Chỉ cần chủ động phòng ngừa trước, khi bão đến thiệt hại sẽ giảm đến mức thấp nhất."}],"related":[{"hanzi":"防备","pinyin":"fángbèi","vi":"phòng bị"},{"hanzi":"预防","pinyin":"yùfáng","vi":"dự phòng"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"},{"hanzi":"防范措施","pinyin":"fángfàncuòshī","vi":"biện pháp phòng ngừa"}],"traditional":"防範"},{"id":"防控","hanzi":"防控","pinyin":"fángkòng","meaning_vi":"phòng ngừa và kiểm soát","explanation":"防 (防) + 控 (khống chế/kiểm soát).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😷","examples":[{"type":"basic","zh":"疫情防控不能放松。","pinyin":"Yìqíng fángkòng bù néng fàngsōng.","vi":"Không được lơ là phòng chống dịch bệnh."},{"type":"simple","zh":"学校在食堂门口设置了体温检测点加强防控。","pinyin":"Xuéxiào zài shítáng ménkǒu shèzhìle tǐwēn jiǎncè diǎn jiāqiáng fángkòng.","vi":"Nhà trường đặt điểm đo thân nhiệt trước cửa nhà ăn để tăng cường phòng chống."},{"type":"compound","zh":"一旦发现病例，社区就会立即启动防控措施。","pinyin":"Yídàn fāxiàn bìnglì, shèqū jiù huì lìjí qǐdòng fángkòng cuòshī.","vi":"Một khi phát hiện ca bệnh, khu dân cư sẽ lập tức khởi động biện pháp phòng chống."}],"related":[{"hanzi":"防治","pinyin":"fángzhì","vi":"phòng chống"},{"hanzi":"疫情","pinyin":"yìqíng","vi":"dịch bệnh"},{"hanzi":"控制","pinyin":"kòngzhì","vi":"kiểm soát"},{"hanzi":"防疫","pinyin":"fángyì","vi":"phòng dịch"}]},{"id":"防线","hanzi":"防线","pinyin":"fángxiàn","meaning_vi":"phòng tuyến","explanation":"防 (防) + 线 (manh mối/đường nét).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🛡️","examples":[{"type":"basic","zh":"敌军突破了防线。","pinyin":"Díjūn tūpòle fángxiàn.","vi":"Quân địch đã chọc thủng phòng tuyến."},{"type":"simple","zh":"这位中后卫是球队最后一道防线的核心。","pinyin":"Zhè wèi zhōng hòuwèi shì qiúduì zuìhòu yídào fángxiàn de héxīn.","vi":"Trung vệ này là trụ cột của tuyến phòng ngự cuối cùng của đội bóng."},{"type":"compound","zh":"一旦心理防线崩溃，嫌疑人就交代了全部罪行。","pinyin":"Yídàn xīnlǐ fángxiàn bēngkuì, xiányírén jiù jiāodàile quánbù zuìxíng.","vi":"Một khi phòng tuyến tâm lý sụp đổ, nghi phạm liền khai ra toàn bộ tội trạng."}],"related":[{"hanzi":"防御","pinyin":"fángyù","vi":"phòng ngự"},{"hanzi":"阵地","pinyin":"zhèndì","vi":"trận địa"},{"hanzi":"心理防线","pinyin":"xīnlǐfángxiàn","vi":"phòng tuyến tâm lý"},{"hanzi":"铜墙铁壁","pinyin":"tóngqiángtiěbì","vi":"tường đồng vách sắt"}],"traditional":"防線"},{"id":"防灾减灾","hanzi":"防灾减灾","pinyin":"fángzāijiǎnzāi","meaning_vi":"phòng chống và giảm nhẹ thiên tai","explanation":"防 (防) + 灾 (thiên tai/thảm họa) + 减 (减) + 灾 (thiên tai/thảm họa).","hsk_level":"7-9","tags":["dong-tu","thien-nhien","xa-hoi"],"image":"🛡️","examples":[{"type":"basic","zh":"今天是防灾减灾日。","pinyin":"Jīntiān shì fángzāijiǎnzāi rì.","vi":"Hôm nay là ngày phòng chống và giảm nhẹ thiên tai."},{"type":"simple","zh":"社区组织居民学习防灾减灾的基本知识。","pinyin":"Shèqū zǔzhī jūmín xuéxí fángzāijiǎnzāi de jīběn zhīshi.","vi":"Khu dân cư tổ chức cho người dân học kiến thức cơ bản về phòng chống giảm nhẹ thiên tai."},{"type":"compound","zh":"因为这里地震频发，所以防灾减灾教育要从小学抓起。","pinyin":"Yīnwèi zhèlǐ dìzhèn pínfā, suǒyǐ fángzāijiǎnzāi jiàoyù yào cóng xiǎoxué zhuā qǐ.","vi":"Vì nơi đây thường xuyên động đất nên giáo dục phòng chống thiên tai phải bắt đầu từ tiểu học."}],"related":[{"hanzi":"防灾","pinyin":"fángzāi","vi":"phòng chống thiên tai"},{"hanzi":"减灾","pinyin":"jiǎnzāi","vi":"giảm nhẹ thiên tai"},{"hanzi":"自然灾害","pinyin":"zìránzāihài","vi":"thiên tai"},{"hanzi":"救灾","pinyin":"jiùzāi","vi":"cứu trợ thiên tai"}],"traditional":"防災減災"},{"id":"奋发图强","hanzi":"奋发图强","pinyin":"fènfā-túqiáng","meaning_vi":"phấn đấu vươn lên mạnh mẽ","explanation":"奋 (奋) + 发 (发) + 图 (mưu đồ/bản đồ) + 强 (cường đại/nhấn mạnh).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"他决心奋发图强。","pinyin":"Tā juéxīn fènfātúqiáng.","vi":"Anh ấy quyết tâm phấn đấu vươn lên."},{"type":"simple","zh":"落榜后的他奋发图强地复读了一整年。","pinyin":"Luòbǎng hòu de tā fènfātúqiáng de fùdúle yì zhěng nián.","vi":"Sau khi thi trượt, anh ấy nỗ lực vươn lên ôn thi lại suốt một năm."},{"type":"compound","zh":"这个小山村虽然条件艰苦，但是村民们奋发图强，终于脱了贫。","pinyin":"Zhè ge xiǎo shāncūn suīrán tiáojiàn jiānkǔ, dànshì cūnmínmen fènfātúqiáng, zhōngyú tuōle pín.","vi":"Ngôi làng miền núi này tuy điều kiện gian khổ, nhưng dân làng nỗ lực vươn lên, cuối cùng đã thoát nghèo."}],"related":[{"hanzi":"发愤图强","pinyin":"fāfèntúqiáng","vi":"quyết chí tự cường"},{"hanzi":"自强不息","pinyin":"zìqiángbùxī","vi":"tự cường không ngừng"},{"hanzi":"奋斗","pinyin":"fèndòu","vi":"phấn đấu"},{"hanzi":"自暴自弃","pinyin":"zìbàozìqì","vi":"tự buông xuôi"}],"traditional":"奮發圖強"},{"id":"奉行","hanzi":"奉行","pinyin":"fèngxíng","meaning_vi":"thi hành, theo đuổi (chính sách/nguyên tắc)","explanation":"奉 (cống hiến/dâng) + 行 (được).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"他奉行节俭原则。","pinyin":"Tā fèngxíng jiéjiǎn yuánzé.","vi":"Ông ấy theo đuổi nguyên tắc tiết kiệm."},{"type":"simple","zh":"这家老字号一直奉行童叟无欺的经营理念。","pinyin":"Zhè jiālǎo zìhào yìzhí fèngxíng tóng sǒu wú qī de jīngyíng lǐniàn.","vi":"Cửa hàng lâu đời này luôn theo đuổi triết lý kinh doanh không lừa già dối trẻ."},{"type":"compound","zh":"如果一个国家奉行和平外交，就更容易赢得国际信任。","pinyin":"Rúguǒ yí gè guójiā fèngxíng hépíng wàijiāo, jiù gèng róngyì yíngdé Guójì xìnrèn.","vi":"Nếu một quốc gia theo đuổi chính sách ngoại giao hòa bình thì sẽ dễ giành được lòng tin quốc tế hơn."}],"related":[{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hiện"},{"hanzi":"遵循","pinyin":"zūnxún","vi":"tuân theo"},{"hanzi":"推行","pinyin":"tuīxíng","vi":"thúc đẩy thực hiện"},{"hanzi":"奉行政策","pinyin":"fèngxíngzhèngcè","vi":"thi hành chính sách"}]},{"id":"佛系","hanzi":"佛系","pinyin":"fóxì","meaning_vi":"sống tùy duyên, điềm nhiên không tranh giành","explanation":"佛 (Phật) + 系 (hệ/phong cách).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🧘","examples":[{"type":"basic","zh":"他最近很佛系。","pinyin":"Tā zuìjìn hěn fóxì.","vi":"Dạo này anh ấy sống rất tùy duyên."},{"type":"simple","zh":"这位佛系店主从不在意每天卖出多少杯咖啡。","pinyin":"Zhè wèi fóxì diàn zhǔcóng bú zàiyì měitiān màichū duōshǎo bēi kāfēi.","vi":"Ông chủ quán sống tùy duyên này chẳng bao giờ bận tâm mỗi ngày bán được bao nhiêu ly cà phê."},{"type":"compound","zh":"与其焦虑地追求完美，不如用佛系的心态面对考试。","pinyin":"Yǔqí jiāolǜ de zhuīqiú wánměi, bùrú yòng fóxì de xīntài miànduì kǎoshì.","vi":"Thay vì lo âu theo đuổi sự hoàn hảo, chi bằng đối mặt kỳ thi với tâm thế an nhiên tùy duyên."}],"related":[{"hanzi":"随缘","pinyin":"suíyuán","vi":"tùy duyên"},{"hanzi":"躺平","pinyin":"tǎngpíng","vi":"nằm thẳng buông xuôi"},{"hanzi":"淡定","pinyin":"dàndìng","vi":"bình thản"},{"hanzi":"内卷","pinyin":"nèijuǎn","vi":"cạnh tranh khốc liệt"}]},{"id":"附录","hanzi":"附录","pinyin":"fùlù","meaning_vi":"phụ lục","explanation":"附 (附) + 录 (ghi chép/tuyển dụng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📎","examples":[{"type":"basic","zh":"答案在书后附录里。","pinyin":"Dá'àn zài shū hòu fùlù lǐ.","vi":"Đáp án nằm trong phụ lục cuối sách."},{"type":"simple","zh":"这本词典在附录中列出了常用量词表。","pinyin":"Zhè běn cídiǎn zài fùlù zhōng lièchūle chángyòng liàngcí biǎo.","vi":"Cuốn từ điển này liệt kê bảng lượng từ thường dùng trong phần phụ lục."},{"type":"compound","zh":"因为原始数据太多，所以作者把它们放进了附录。","pinyin":"Yīnwèi yuánshǐ shùjù tài duō, suǒyǐ zuòzhě bǎ tāmen fàngjìnle fùlù.","vi":"Vì dữ liệu gốc quá nhiều nên tác giả đã đưa chúng vào phần phụ lục."}],"related":[{"hanzi":"附件","pinyin":"fùjiàn","vi":"tài liệu đính kèm"},{"hanzi":"目录","pinyin":"mùlù","vi":"mục lục"},{"hanzi":"正文","pinyin":"zhèngwén","vi":"phần chính"},{"hanzi":"索引","pinyin":"suǒyǐn","vi":"chỉ mục"}],"traditional":"附錄"},{"id":"富强","hanzi":"富强","pinyin":"fùqiáng","meaning_vi":"giàu mạnh (quốc gia)","explanation":"富 (giàu) + 强 (cường đại/nhấn mạnh).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🌟","examples":[{"type":"basic","zh":"祝愿祖国繁荣富强。","pinyin":"Zhùyuàn zǔguó fánróng fùqiáng.","vi":"Chúc Tổ quốc phồn vinh giàu mạnh."},{"type":"simple","zh":"几代人为了建设一个富强的国家而不懈奋斗。","pinyin":"Jǐdàirén wèile jiànshè yí gè fùqiáng de guójiā ér búxiè fèndòu.","vi":"Bao thế hệ đã không ngừng phấn đấu để xây dựng một đất nước giàu mạnh."},{"type":"compound","zh":"只有经济和科技都发展起来，国家才能真正富强。","pinyin":"Zhǐyǒu jīngjì hé kējì dōu fāzhǎn qǐlái, guójiā cáinéng zhēnzhèng fùqiáng.","vi":"Chỉ khi cả kinh tế lẫn khoa học công nghệ đều phát triển, đất nước mới thực sự giàu mạnh."}],"related":[{"hanzi":"繁荣富强","pinyin":"fánróngfùqiáng","vi":"phồn vinh giàu mạnh"},{"hanzi":"强大","pinyin":"qiángdà","vi":"mạnh mẽ"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"},{"hanzi":"贫弱","pinyin":"pínruò","vi":"nghèo yếu"}],"traditional":"富強"},{"id":"复杂化","hanzi":"复杂化","pinyin":"fùzáhuà","meaning_vi":"phức tạp hóa","explanation":"复 (复) + 杂 (phức tạp/tạp chí) + 化 (化).","hsk_level":"7-9","tags":["dong-tu"],"image":"🕸️","examples":[{"type":"basic","zh":"别把事情复杂化。","pinyin":"Bié bǎ shìqing fùzáhuà.","vi":"Đừng làm phức tạp hóa vấn đề."},{"type":"simple","zh":"双方律师的介入反而让离婚谈判复杂化了。","pinyin":"Shuāngfāng lǜshī de jièrù fǎn'ér ràng líhūn tánpàn fùzáhuà le.","vi":"Sự tham gia của luật sư hai bên lại khiến cuộc đàm phán ly hôn trở nên phức tạp hơn."},{"type":"compound","zh":"如果你当时直接道歉，问题就不会这样复杂化。","pinyin":"Rúguǒ nǐ dāngshí zhíjiē dàoqiàn, wèntí jiù bú huì zhèyàng fùzáhuà.","vi":"Nếu lúc đó bạn xin lỗi ngay thì vấn đề đã không bị phức tạp hóa như thế này."}],"related":[{"hanzi":"简单化","pinyin":"jiǎndānhuà","vi":"đơn giản hóa"},{"hanzi":"复杂","pinyin":"fùzá","vi":"phức tạp"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"简化","pinyin":"jiǎnhuà","vi":"đơn giản hóa"}],"traditional":"複雜化"},{"id":"福地","hanzi":"福地","pinyin":"fúdì","meaning_vi":"vùng đất phúc lành","explanation":"福 (phúc) + 地 (địa – đất) → vùng đất phúc lành, nơi mang lại may mắn, thịnh vượng. VD: 洞天福地.","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"这里真是块福地。","pinyin":"Zhèlǐ zhēn shì kuài fúdì.","vi":"Nơi đây đúng là vùng đất phúc."},{"type":"simple","zh":"老人们都说这座山是风水极好的福地。","pinyin":"Lǎo rénmen dōu shuō zhè zuò shān shì fēngshuǐ jíhǎo de fúdì.","vi":"Các cụ già đều nói ngọn núi này là vùng đất phúc có phong thủy cực tốt."},{"type":"compound","zh":"他在这座城市既找到了工作，又遇到了爱人，真是他的福地。","pinyin":"Tā zài zhè zuò chéngshì jì zhǎodàole gōngzuò, yòu yùdàole àirén, zhēn shì tā de fúdì.","vi":"Ở thành phố này anh ấy vừa tìm được việc làm vừa gặp được người yêu, đúng là vùng đất phúc của anh."}],"related":[{"hanzi":"宝地","pinyin":"bǎodì","vi":"đất quý"},{"hanzi":"风水宝地","pinyin":"fēngshuǐbǎodì","vi":"đất phong thủy tốt"},{"hanzi":"福气","pinyin":"fúqi","vi":"phúc khí"},{"hanzi":"圣地","pinyin":"shèngdì","vi":"thánh địa"}]},{"id":"辐射面","hanzi":"辐射面","pinyin":"fúshèmiàn","meaning_vi":"phạm vi ảnh hưởng lan tỏa","explanation":"辐 (bức xạ/nan hoa) + 射 (射) + 面 (diện mạo/bề mặt).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"📡","examples":[{"type":"basic","zh":"这项政策辐射面很广。","pinyin":"Zhè xiàng zhèngcè fúshèmiàn hěn guǎng.","vi":"Chính sách này có phạm vi ảnh hưởng rất rộng."},{"type":"simple","zh":"新建的物流中心辐射面覆盖了周边五个省份。","pinyin":"Xīnjiàn de wùliú zhōngxīn fúshèmiàn fùgàile zhōubiān wǔ gè shěngfèn.","vi":"Phạm vi phục vụ của trung tâm logistics mới xây bao trùm năm tỉnh lân cận."},{"type":"compound","zh":"如果把展会搬到线上，它的辐射面就会扩大好几倍。","pinyin":"Rúguǒ bǎ zhǎnhuì bān dào xiànshàng, tā de fúshèmiàn jiù huì kuòdà hǎo jǐbèi.","vi":"Nếu chuyển hội chợ lên trực tuyến, phạm vi lan tỏa của nó sẽ mở rộng gấp mấy lần."}],"related":[{"hanzi":"辐射","pinyin":"fúshè","vi":"bức xạ lan tỏa"},{"hanzi":"覆盖面","pinyin":"fùgàimiàn","vi":"phạm vi bao phủ"},{"hanzi":"影响力","pinyin":"yǐngxiǎnglì","vi":"sức ảnh hưởng"},{"hanzi":"范围","pinyin":"fànwéi","vi":"phạm vi"}],"traditional":"輻射面"},{"id":"发源","hanzi":"发源","pinyin":"fāyuán","meaning_vi":"bắt nguồn","explanation":"发 (发) + 源 (nguồn gốc).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"黄河发源于青海。","pinyin":"Huánghé fā yuányú Qīnghǎi.","vi":"Sông Hoàng Hà bắt nguồn từ Thanh Hải."},{"type":"simple","zh":"湄公河发源于中国的青藏高原。","pinyin":"Méigōnghé fā yuányú Zhōngguó de Qīngzànggāoyuán.","vi":"Sông Mê Kông bắt nguồn từ cao nguyên Thanh Tạng của Trung Quốc."},{"type":"compound","zh":"虽然现代足球发源于英国，但是如今已风靡全世界。","pinyin":"Suīrán xiàndài zúqiú fā yuányú Yīngguó, dànshì rújīn yǐ fēngmǐ quánshìjiè.","vi":"Tuy bóng đá hiện đại bắt nguồn từ Anh nhưng nay đã thịnh hành khắp thế giới."}],"related":[{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"发源地","pinyin":"fāyuándì","vi":"nơi bắt nguồn"},{"hanzi":"源头","pinyin":"yuántóu","vi":"đầu nguồn"},{"hanzi":"来源","pinyin":"láiyuán","vi":"nguồn gốc"}],"traditional":"發源"},{"id":"发言人","hanzi":"发言人","pinyin":"fāyánrén","meaning_vi":"người phát ngôn","explanation":"发言 (phát ngôn – phát biểu) + 人 (người) → người phát ngôn của cơ quan, tổ chức. VD: 外交部发言人.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","xa-hoi"],"image":"🎤","examples":[{"type":"basic","zh":"发言人拒绝回答。","pinyin":"Fāyánrén jùjué huídá.","vi":"Người phát ngôn từ chối trả lời."},{"type":"simple","zh":"外交部发言人在例行记者会上回应了这一问题。","pinyin":"Wàijiāobù fāyánrén zài lìxíng jìzhěhuì shàng huíyìngle zhè yí wèntí.","vi":"Người phát ngôn Bộ Ngoại giao đã phản hồi vấn đề này tại cuộc họp báo thường kỳ."},{"type":"compound","zh":"公司发言人一表态，股价就开始回升。","pinyin":"Gōngsī fāyánrén yì biǎotài, gǔjià jiù kāishǐ huíshēng.","vi":"Người phát ngôn công ty vừa lên tiếng bày tỏ thái độ, giá cổ phiếu liền bắt đầu phục hồi."}],"related":[{"hanzi":"发言","pinyin":"fāyán","vi":"phát biểu"},{"hanzi":"新闻发布会","pinyin":"xīnwén fābùhuì","vi":"họp báo"},{"hanzi":"代言人","pinyin":"dàiyánrén","vi":"người đại diện"},{"hanzi":"外交部","pinyin":"Wàijiāobù","vi":"Bộ Ngoại giao"}],"traditional":"發言人"},{"id":"翻番","hanzi":"翻番","pinyin":"fānfān","meaning_vi":"tăng gấp đôi","explanation":"翻 (lật) + 番 (lần).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"今年销量翻番了。","pinyin":"Jīnnián xiāoliàng fānfān le.","vi":"Năm nay doanh số đã tăng gấp đôi."},{"type":"simple","zh":"这家网店的营业额在一年之内实现了翻番。","pinyin":"Zhè jiā wǎngdiàn de yíngyè'é zài yì nián zhīnèi shíxiànle fānfān.","vi":"Doanh thu của cửa hàng trực tuyến này đã tăng gấp đôi chỉ trong một năm."},{"type":"compound","zh":"如果明年出口量再翻番，工厂就得扩建新车间。","pinyin":"Rúguǒ míngnián chūkǒu liàng zài fānfān, gōngchǎng jiù děi kuòjiàn xīn chējiān.","vi":"Nếu năm sau lượng xuất khẩu lại tăng gấp đôi, nhà máy sẽ phải xây thêm phân xưởng mới."}],"related":[{"hanzi":"翻一番","pinyin":"fānyìfān","vi":"tăng gấp đôi"},{"hanzi":"倍增","pinyin":"bèizēng","vi":"tăng gấp bội"},{"hanzi":"增长","pinyin":"zēngzhǎng","vi":"tăng trưởng"},{"hanzi":"减半","pinyin":"jiǎnbàn","vi":"giảm một nửa"}]},{"id":"非处方药","hanzi":"非处方药","pinyin":"fēichǔfāngyào","meaning_vi":"thuốc không kê đơn (OTC)","explanation":"非 (không) + 处 (处) + 方 (vuông) + 药 (thuốc).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"这款感冒药是非处方药。","pinyin":"Zhè kuǎn gǎnmàoyào shìfēi chǔfāngyào.","vi":"Loại thuốc cảm này là thuốc không kê đơn."},{"type":"simple","zh":"顾客在药店可以直接购买非处方药。","pinyin":"Gùkè zài yàodiàn kěyǐ zhíjiē gòumǎi fēichǔfāngyào.","vi":"Khách hàng có thể mua trực tiếp thuốc không kê đơn tại hiệu thuốc."},{"type":"compound","zh":"非处方药虽然不需要医生开方，但是也不能长期随意服用。","pinyin":"Fēichǔfāngyào suīrán bù xūyào yīshēng kāifāng, dànshì yě bù néng chángqī suíyì fúyòng.","vi":"Thuốc không kê đơn tuy không cần bác sĩ kê đơn, nhưng cũng không được tùy tiện dùng lâu dài."}],"related":[{"hanzi":"处方药","pinyin":"chǔfāngyào","vi":"thuốc kê đơn"},{"hanzi":"药店","pinyin":"yàodiàn","vi":"hiệu thuốc"},{"hanzi":"感冒药","pinyin":"gǎnmàoyào","vi":"thuốc cảm"},{"hanzi":"药品","pinyin":"yàopǐn","vi":"dược phẩm"}],"traditional":"非處方藥"},{"id":"非物质文化遗产","hanzi":"非物质文化遗产","pinyin":"fēi wùzhì wénhuà yíchǎn","meaning_vi":"di sản văn hóa phi vật thể","explanation":"非 (không) + 物 (vật chất/sự vật) + 质 (chất lượng/bản chất) + 文 (văn hóa/văn minh) + 化 (化) + 遗 (di sản/để lại) + 产 (产).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"昆曲是非物质文化遗产。","pinyin":"Kūnqǔ shì fēiwùzhìwénhuàyíchǎn.","vi":"Côn khúc là di sản văn hóa phi vật thể."},{"type":"simple","zh":"越南的水上木偶戏被列为国家级非物质文化遗产。","pinyin":"Yuènán de shuǐshàng mù'ǒuxì bèi lièwéi guójiājí fēiwùzhìwénhuàyíchǎn.","vi":"Múa rối nước Việt Nam được xếp hạng là di sản văn hóa phi vật thể cấp quốc gia."},{"type":"compound","zh":"如果没有年轻人传承，很多非物质文化遗产就会消失。","pinyin":"Rúguǒ méiyǒu niánqīngrén chuánchéng, hěn duō fēiwùzhìwénhuàyíchǎn jiù huì xiāoshī.","vi":"Nếu không có người trẻ kế thừa, nhiều di sản văn hóa phi vật thể sẽ biến mất."}],"related":[{"hanzi":"非遗","pinyin":"fēiyí","vi":"di sản phi vật thể"},{"hanzi":"文化遗产","pinyin":"wénhuàyíchǎn","vi":"di sản văn hóa"},{"hanzi":"传承人","pinyin":"chuánchéngrén","vi":"người truyền nghề"},{"hanzi":"世界遗产","pinyin":"shìjièyíchǎn","vi":"di sản thế giới"}],"traditional":"非物質文化遺產"},{"id":"飞跃发展","hanzi":"飞跃发展","pinyin":"fēiyuèfāzhǎn","meaning_vi":"phát triển nhảy vọt","explanation":"飞 (飞) + 跃 (nhảy vọt) + 发 (发) + 展 (triển lãm/phát triển).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚀","examples":[{"type":"basic","zh":"经济实现了飞跃发展。","pinyin":"Jīngjì shíxiànle fēiyuèfāzhǎn.","vi":"Kinh tế đã đạt được sự phát triển nhảy vọt."},{"type":"simple","zh":"近二十年来中国高铁取得了飞跃发展。","pinyin":"Jìn èrshí niánlái Zhōngguó gāotiě qǔ déle fēiyuèfāzhǎn.","vi":"Hai mươi năm gần đây, đường sắt cao tốc Trung Quốc đã phát triển vượt bậc."},{"type":"compound","zh":"因为引进了新技术，所以这个小镇的纺织业实现了飞跃发展。","pinyin":"Yīnwèi yǐnjìnle xīnjìshù, suǒyǐ zhè ge xiǎozhèn de fǎngzhī yè shíxiànle fēiyuèfāzhǎn.","vi":"Vì đưa vào công nghệ mới nên ngành dệt của thị trấn nhỏ này đã phát triển nhảy vọt."}],"related":[{"hanzi":"飞跃","pinyin":"fēiyuè","vi":"nhảy vọt"},{"hanzi":"突飞猛进","pinyin":"tūfēiměngjìn","vi":"tiến bộ vượt bậc"},{"hanzi":"腾飞","pinyin":"téngfēi","vi":"cất cánh"},{"hanzi":"停滞不前","pinyin":"tíngzhìbùqián","vi":"đình trệ không tiến"}],"traditional":"飛躍發展"},{"id":"非遗","hanzi":"非遗","pinyin":"fēiyí","meaning_vi":"di sản văn hóa phi vật thể (viết tắt)","explanation":"非 (không) + 遗 (di sản/để lại).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"剪纸是一项非遗。","pinyin":"Jiǎnzhǐ shì yí xiàng fēiyí.","vi":"Cắt giấy là một di sản phi vật thể."},{"type":"simple","zh":"这位八十岁的老人是苏绣非遗传承人。","pinyin":"Zhè wèi bāshí suì de lǎorén shì Sūxiù fēiyí chuánchéngrén.","vi":"Cụ già tám mươi tuổi này là nghệ nhân kế thừa di sản phi vật thể thêu Tô Châu."},{"type":"compound","zh":"只要把非遗和旅游结合起来，传统手艺就能焕发新的活力。","pinyin":"Zhǐyào bǎ fēiyí hé lǚyóu jiéhé qǐlái, chuántǒng shǒuyì jiù néng huànfā xīn de huólì.","vi":"Chỉ cần kết hợp di sản phi vật thể với du lịch, nghề thủ công truyền thống sẽ bừng lên sức sống mới."}],"related":[{"hanzi":"非物质文化遗产","pinyin":"fēi wùzhì wénhuà yíchǎn","vi":"di sản văn hóa phi vật thể"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"truyền thừa"},{"hanzi":"手工艺","pinyin":"shǒugōngyì","vi":"thủ công mỹ nghệ"},{"hanzi":"文化遗产","pinyin":"wénhuàyíchǎn","vi":"di sản văn hóa"}],"traditional":"非遺"},{"id":"分辨率","hanzi":"分辨率","pinyin":"fēnbiànlǜ","meaning_vi":"độ phân giải (màn hình/ảnh)","explanation":"分辨 (phân biện – phân biệt) + 率 (suất – tỷ lệ) → độ phân giải của màn hình, ảnh, máy ảnh. VD: 高分辨率.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🖥️","examples":[{"type":"basic","zh":"这张照片分辨率太低。","pinyin":"Zhè zhāng zhàopiàn fēnbiànlǜ tài dī.","vi":"Độ phân giải của bức ảnh này quá thấp."},{"type":"simple","zh":"这款新手机的屏幕分辨率非常高。","pinyin":"Zhè kuǎn xīnshǒu jī de píngmù fēnbiànlǜ fēicháng gāo.","vi":"Màn hình của mẫu điện thoại mới này có độ phân giải rất cao."},{"type":"compound","zh":"如果分辨率不够高，海报印出来就会模糊。","pinyin":"Rúguǒ fēnbiànlǜ búgòu gāo, hǎibào yìn chūlái jiù huì móhu.","vi":"Nếu độ phân giải không đủ cao, áp phích in ra sẽ bị mờ."}],"related":[{"hanzi":"像素","pinyin":"xiàngsù","vi":"điểm ảnh"},{"hanzi":"清晰度","pinyin":"qīngxīdù","vi":"độ nét"},{"hanzi":"高清","pinyin":"gāoqīng","vi":"độ nét cao"},{"hanzi":"屏幕","pinyin":"píngmù","vi":"màn hình"}]},{"id":"分寸感","hanzi":"分寸感","pinyin":"fēncùngǎn","meaning_vi":"sự chừng mực tinh tế trong giao tiếp","explanation":"分寸 (phân thốn – phân và tấc, chừng mực) + 感 (cảm giác) → ý thức về chừng mực, biết điểm dừng trong lời nói, cư xử. VD: 说话有分寸感.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"📏","examples":[{"type":"basic","zh":"她说话很有分寸感。","pinyin":"Tā shuōhuà hěn yǒu fēncùngǎn.","vi":"Cô ấy nói chuyện rất có chừng mực."},{"type":"simple","zh":"好的主持人提问时总能保持恰当的分寸感。","pinyin":"Hǎo de zhǔchírén tíwèn shí zǒngnéng bǎochí qiàdàng de fēncùngǎn.","vi":"Người dẫn chương trình giỏi khi đặt câu hỏi luôn giữ được sự chừng mực thích đáng."},{"type":"compound","zh":"即使是最好的朋友，相处时也需要一点分寸感。","pinyin":"Jíshǐ shì zuìhǎo de péngyou, xiāngchǔ shí yě xūyào yìdiǎn fēncùngǎn.","vi":"Dù là bạn thân nhất, khi ở cạnh nhau cũng cần một chút chừng mực."}],"related":[{"hanzi":"分寸","pinyin":"fēncun","vi":"chừng mực"},{"hanzi":"适度","pinyin":"shìdù","vi":"vừa phải"},{"hanzi":"得体","pinyin":"détǐ","vi":"đúng mực"},{"hanzi":"过分","pinyin":"guòfèn","vi":"quá đáng"}]},{"id":"分级","hanzi":"分级","pinyin":"fēnjí","meaning_vi":"phân cấp, phân loại theo mức độ","explanation":"分 (phút) + 级 (cấp bậc).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📶","examples":[{"type":"basic","zh":"电影实行分级制度。","pinyin":"Diànyǐng shíxíng fēnjí zhìdù.","vi":"Phim ảnh áp dụng chế độ phân loại."},{"type":"simple","zh":"医院对急诊病人按病情轻重进行分级。","pinyin":"Yīyuàn duì jízhěn bìngrén àn bìngqíng qīngzhòng jìnxíng fēnjí.","vi":"Bệnh viện phân cấp bệnh nhân cấp cứu theo mức độ nặng nhẹ của bệnh."},{"type":"compound","zh":"如果不对游戏内容进行分级，孩子就可能接触到暴力画面。","pinyin":"Rúguǒ bú duì yóuxì nèiróng jìnxíng fēnjí, háizi jiù kěnéng jiēchù dào bàolì huàmiàn.","vi":"Nếu không phân loại nội dung trò chơi, trẻ em có thể tiếp xúc với hình ảnh bạo lực."}],"related":[{"hanzi":"等级","pinyin":"děngjí","vi":"cấp bậc"},{"hanzi":"分类","pinyin":"fēnlèi","vi":"phân loại"},{"hanzi":"分层","pinyin":"fēncéng","vi":"phân tầng"},{"hanzi":"级别","pinyin":"jíbié","vi":"cấp độ"}],"traditional":"分級"},{"id":"分流","hanzi":"分流","pinyin":"fēnliú","meaning_vi":"phân luồng (giao thông/học sinh)","explanation":"分 (phút) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🔀","examples":[{"type":"basic","zh":"交警在路口分流车辆。","pinyin":"Jiāojǐng zài lùkǒu fēnliú chēliàng.","vi":"Cảnh sát giao thông phân luồng xe tại ngã tư."},{"type":"simple","zh":"初中毕业后学生将分流到普通高中和职业学校。","pinyin":"Chūzhōng bìyè hòu xuésheng jiāng fēnliú dào pǔtōng gāo zhōnghé zhíyè xuéxiào.","vi":"Sau khi tốt nghiệp trung học cơ sở, học sinh sẽ được phân luồng vào trung học phổ thông và trường nghề."},{"type":"compound","zh":"因为主干道正在施工，所以车辆被分流到了旁边的小路。","pinyin":"Yīnwèi zhǔgàndào zhèngzài shīgōng, suǒyǐ chēliàng bèi fēnliú dàole pángbiān de xiǎolù.","vi":"Vì trục đường chính đang thi công nên xe cộ được phân luồng sang đường nhỏ bên cạnh."}],"related":[{"hanzi":"分散","pinyin":"fēnsàn","vi":"phân tán"},{"hanzi":"疏导","pinyin":"shūdǎo","vi":"khơi thông"},{"hanzi":"分配","pinyin":"fēnpèi","vi":"phân phối"},{"hanzi":"合流","pinyin":"héliú","vi":"hợp lưu"}]},{"id":"分期付款","hanzi":"分期付款","pinyin":"fēnqīfùkuǎn","meaning_vi":"trả góp","explanation":"分期 (chia kỳ) + 付款 (thanh toán).","hsk_level":"7-9","tags":["dong-tu","tien-te","mua-sam"],"image":"📅","examples":[{"type":"basic","zh":"可以分期付款吗？","pinyin":"Kěyǐ fēnqīfùkuǎn ma?","vi":"Có thể trả góp không?"},{"type":"simple","zh":"他用分期付款的方式买了一台新电脑。","pinyin":"Tāyòng fēnqīfùkuǎn de fāngshì mǎile yì tái xīn diànnǎo.","vi":"Anh ấy mua một chiếc máy tính mới theo hình thức trả góp."},{"type":"compound","zh":"分期付款虽然减轻了压力，但是总价往往比一次付清更高。","pinyin":"Fēnqīfùkuǎn suīrán jiǎnqīngle yālì, dànshì zǒngjià wǎngwǎng bǐ yí cì fùqīng gèng gāo.","vi":"Trả góp tuy giảm bớt áp lực, nhưng tổng giá thường cao hơn trả một lần."}],"related":[{"hanzi":"分期","pinyin":"fēnqī","vi":"trả theo kỳ"},{"hanzi":"一次性付款","pinyin":"yícìxìng fùkuǎn","vi":"trả một lần"},{"hanzi":"首付","pinyin":"shǒufù","vi":"trả trước"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"vay tiền"}]},{"id":"分水岭","hanzi":"分水岭","pinyin":"fēnshuǐlǐng","meaning_vi":"đường phân thủy; bước ngoặt, ranh giới quan trọng","explanation":"分 (phút) + 水 (nước) + 岭 (岭).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"这次考试是分水岭。","pinyin":"Zhè cì kǎoshì shì fēnshuǐlǐng.","vi":"Kỳ thi này là bước ngoặt."},{"type":"simple","zh":"秦岭是中国南北方重要的地理分水岭。","pinyin":"Qínlǐng shì Zhōngguó nán běifāng zhòngyào de dìlǐ fēnshuǐlǐng.","vi":"Tần Lĩnh là đường phân thủy địa lý quan trọng giữa miền Nam và miền Bắc Trung Quốc."},{"type":"compound","zh":"那次车祸成了他人生的分水岭，因为从此他学会了珍惜。","pinyin":"Nà cì chēhuò chéngle tā rénshēng de fēnshuǐlǐng, yīnwèi cóngcǐ tā xuéhuìle zhēnxī.","vi":"Vụ tai nạn ấy trở thành bước ngoặt trong đời anh, vì từ đó anh học được cách trân trọng."}],"related":[{"hanzi":"转折点","pinyin":"zhuǎnzhédiǎn","vi":"bước ngoặt"},{"hanzi":"里程碑","pinyin":"lǐchéngbēi","vi":"cột mốc"},{"hanzi":"界线","pinyin":"jièxiàn","vi":"ranh giới"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"}],"traditional":"分水嶺"},{"id":"风采","hanzi":"风采","pinyin":"fēngcǎi","meaning_vi":"phong thái, vẻ đẹp rạng rỡ","explanation":"风 (phong – phong độ) + 采 (thái – vẻ, sắc thái) → phong thái, vẻ đẹp tài hoa toát ra từ con người. VD: 一睹风采, 展现风采.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"她依旧风采照人。","pinyin":"Tā yījiù fēngcǎi zhào rén.","vi":"Cô ấy vẫn rạng rỡ cuốn hút như xưa."},{"type":"simple","zh":"运动员们在开幕式上展现了青春风采。","pinyin":"Yùndòngyuánmen zài kāimùshì shàng zhǎnxiànle qīngchūn fēngcǎi.","vi":"Các vận động viên đã thể hiện phong thái thanh xuân tại lễ khai mạc."},{"type":"compound","zh":"虽然已经年过七十，但是这位老艺术家仍不减当年风采。","pinyin":"Suīrán yǐjīng niánguò qīshí, dànshì zhè wèi lǎo yìshùjiā réng bù jiǎn dāngnián fēngcǎi.","vi":"Tuy đã ngoài bảy mươi nhưng người nghệ sĩ lão thành này vẫn giữ nguyên phong thái năm nào."}],"related":[{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"风范","pinyin":"fēngfàn","vi":"phong thái mẫu mực"},{"hanzi":"神采","pinyin":"shéncǎi","vi":"thần thái"},{"hanzi":"风姿","pinyin":"fēngzī","vi":"dáng vẻ"}],"traditional":"風采"},{"id":"封顶","hanzi":"封顶","pinyin":"fēngdǐng","meaning_vi":"cất nóc (công trình); khống chế mức trần, tối đa","explanation":"封 (phong – đóng kín) + 顶 (đỉnh – nóc) → cất nóc công trình; nghĩa mở rộng: đặt mức trần tối đa. VD: 大楼封顶, 工资封顶.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"大楼今天封顶了。","pinyin":"Dàlóu jīntiān fēngdǐng le.","vi":"Tòa nhà hôm nay đã cất nóc."},{"type":"simple","zh":"这份工作的年终奖最高封顶三个月工资。","pinyin":"Zhè fèn gōngzuò de niánzhōngjiǎng zuì gāo fēngdǐng sān gèyuè gōngzī.","vi":"Thưởng cuối năm của công việc này tối đa không vượt quá ba tháng lương."},{"type":"compound","zh":"如果天气一直晴好，新医院就能在年底前封顶。","pinyin":"Rúguǒ tiānqì yìzhí qínghǎo, xīn yīyuàn jiù néng zài niándǐ qián fēngdǐng.","vi":"Nếu thời tiết tiếp tục đẹp, bệnh viện mới sẽ cất nóc trước cuối năm."}],"related":[{"hanzi":"上限","pinyin":"shàngxiàn","vi":"mức trần"},{"hanzi":"封顶仪式","pinyin":"fēngdǐngyíshì","vi":"lễ cất nóc"},{"hanzi":"竣工","pinyin":"jùngōng","vi":"hoàn công"},{"hanzi":"封顶价","pinyin":"fēngdǐngjià","vi":"giá trần"}],"traditional":"封頂"},{"id":"风范","hanzi":"风范","pinyin":"fēngfàn","meaning_vi":"phong thái mẫu mực","explanation":"风 (phong – phong cách) + 范 (phạm – khuôn mẫu) → phong thái mẫu mực, khí độ đáng làm gương. VD: 大将风范, 学者风范.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"他有大将风范。","pinyin":"Tā yǒu dàjiàng fēngfàn.","vi":"Anh ấy có phong thái của một đại tướng."},{"type":"simple","zh":"老校长谦和儒雅的学者风范深受师生敬重。","pinyin":"Lǎo xiàozhǎng qiānhé rúyǎ de xuézhě fēngfàn shēnshòu shīshēng jìngzhòng.","vi":"Phong thái học giả khiêm nhường, nho nhã của thầy hiệu trưởng cũ được thầy trò hết mực kính trọng."},{"type":"compound","zh":"虽然输了比赛，但是他主动向对手祝贺，尽显冠军风范。","pinyin":"Suīrán shūle bǐsài, dànshì tā zhǔ dòngxiàng duìshǒu zhùhè, jìn xiǎn guànjūn fēngfàn.","vi":"Tuy thua trận nhưng anh ấy chủ động chúc mừng đối thủ, thể hiện trọn vẹn phong thái nhà vô địch."}],"related":[{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"风采","pinyin":"fēngcǎi","vi":"phong thái"},{"hanzi":"典范","pinyin":"diǎnfàn","vi":"điển hình"},{"hanzi":"大将风范","pinyin":"dàjiàngfēngfàn","vi":"phong thái đại tướng"}],"traditional":"風範"},{"id":"峰会","hanzi":"峰会","pinyin":"fēnghuì","meaning_vi":"hội nghị thượng đỉnh","explanation":"峰 (đỉnh cao) + 会 (hội nghị).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"峰会在河内举行。","pinyin":"Fēnghuì zài Hénèi jǔxíng.","vi":"Hội nghị thượng đỉnh được tổ chức tại Hà Nội."},{"type":"simple","zh":"二十国集团领导人峰会讨论了全球经济复苏问题。","pinyin":"Èrshí guó jítuán lǐngdǎorén fēnghuì tǎolùnle quánqiú jīngjìfùsū wèntí.","vi":"Hội nghị thượng đỉnh G20 đã thảo luận vấn đề phục hồi kinh tế toàn cầu."},{"type":"compound","zh":"峰会一结束，两国就发表了联合声明。","pinyin":"Fēnghuì yì jiéshù, liǎngguó jiù fābiǎole liánhéshēngmíng.","vi":"Hội nghị thượng đỉnh vừa kết thúc, hai nước liền ra tuyên bố chung."}],"related":[{"hanzi":"首脑会议","pinyin":"shǒunǎohuìyì","vi":"hội nghị thượng đỉnh"},{"hanzi":"论坛","pinyin":"lùntán","vi":"diễn đàn"},{"hanzi":"会议","pinyin":"huìyì","vi":"hội nghị"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"đỉnh cao"}],"traditional":"峰會"},{"id":"风貌","hanzi":"风貌","pinyin":"fēngmào","meaning_vi":"diện mạo, phong thái","explanation":"风 (风) + 貌 (diện mạo).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏙️","examples":[{"type":"basic","zh":"古镇保持着原有风貌。","pinyin":"Gǔzhèn bǎochízhe yuányǒu fēngmào.","vi":"Thị trấn cổ giữ được diện mạo vốn có."},{"type":"simple","zh":"这组照片真实记录了上世纪八十年代的城市风貌。","pinyin":"Zhè zǔ zhàopiàn zhēnshí jìlùle shàng shìjì bāshí niándài de chéngshì fēngmào.","vi":"Bộ ảnh này ghi lại chân thực diện mạo đô thị thập niên tám mươi thế kỷ trước."},{"type":"compound","zh":"经过十年改造，这座小城既保留了传统风貌，又增添了现代气息。","pinyin":"Jīngguò shí nián gǎizào, zhè zuò xiǎochéng jì bǎoliúle chuántǒng fēngmào, yòu zēngtiānle xiàndài qìxī.","vi":"Qua mười năm cải tạo, thị trấn nhỏ này vừa giữ được diện mạo truyền thống, vừa thêm hơi thở hiện đại."}],"related":[{"hanzi":"面貌","pinyin":"miànmào","vi":"diện mạo"},{"hanzi":"风格","pinyin":"fēnggé","vi":"phong cách"},{"hanzi":"风土人情","pinyin":"fēngtǔrénqíng","vi":"phong tục tập quán"},{"hanzi":"风景","pinyin":"fēngjǐng","vi":"phong cảnh"}],"traditional":"風貌"},{"id":"风能","hanzi":"风能","pinyin":"fēngnéng","meaning_vi":"năng lượng gió","explanation":"风 (风) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🌬️","examples":[{"type":"basic","zh":"风能是清洁能源。","pinyin":"Fēngnéng shì qīngjié néngyuán.","vi":"Năng lượng gió là năng lượng sạch."},{"type":"simple","zh":"沿海地区建起了一排排利用风能发电的风车。","pinyin":"Yánhǎi dìqū jiàn qǐle yìpái pái lìyòng fēngnéng fādiàn de fēngchē.","vi":"Vùng ven biển đã dựng lên từng hàng tua bin dùng năng lượng gió để phát điện."},{"type":"compound","zh":"因为这里常年刮大风，所以非常适合开发风能。","pinyin":"Yīnwèi zhèlǐ chángnián guā dàfēng, suǒyǐ fēicháng shìhé kāifā fēngnéng.","vi":"Vì nơi đây quanh năm gió lớn nên rất thích hợp khai thác năng lượng gió."}],"related":[{"hanzi":"太阳能","pinyin":"tàiyángnéng","vi":"năng lượng mặt trời"},{"hanzi":"能源","pinyin":"néngyuán","vi":"năng lượng"},{"hanzi":"风力发电","pinyin":"fēnglìfādiàn","vi":"điện gió"},{"hanzi":"清洁能源","pinyin":"qīngjiénéngyuán","vi":"năng lượng sạch"}],"traditional":"風能"},{"id":"风尚","hanzi":"风尚","pinyin":"fēngshàng","meaning_vi":"phong trào tốt đẹp, nếp sống văn minh","explanation":"风 (phong – phong tục) + 尚 (thượng – được chuộng) → phong khí, nếp sống được xã hội chuộng. VD: 社会新风尚, 文明风尚.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","van-hoa"],"image":"🌸","examples":[{"type":"basic","zh":"节俭成为新风尚。","pinyin":"Jiéjiǎn chéngwéi xīn fēngshàng.","vi":"Tiết kiệm trở thành nếp sống mới."},{"type":"simple","zh":"社区里逐渐形成了邻里互助的良好风尚。","pinyin":"Shèqū lǐ zhújiàn xíng chéngle línlǐ hùzhù de liánghǎo fēngshàng.","vi":"Trong khu dân cư dần hình thành nếp sống tốt đẹp hàng xóm giúp đỡ lẫn nhau."},{"type":"compound","zh":"如今光盘行动不但是一种习惯，而且成了社会新风尚。","pinyin":"Rújīn guāngpánxíngdòng bú dànshì yì zhǒng xíguàn, érqiě chéngle shèhuì xīn fēngshàng.","vi":"Ngày nay phong trào ăn hết không để thừa không chỉ là một thói quen mà còn trở thành nếp sống mới của xã hội."}],"related":[{"hanzi":"风气","pinyin":"fēngqì","vi":"phong khí"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"thời thượng"},{"hanzi":"潮流","pinyin":"cháoliú","vi":"trào lưu"},{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"}],"traditional":"風尚"},{"id":"丰盛","hanzi":"丰盛","pinyin":"fēngshèng","meaning_vi":"thịnh soạn, phong phú (bữa ăn)","explanation":"丰 + 盛 (dồi dào).","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"🍱","examples":[{"type":"basic","zh":"晚餐非常丰盛。","pinyin":"Wǎncān fēicháng fēngshèng.","vi":"Bữa tối rất thịnh soạn."},{"type":"simple","zh":"外婆为我们准备了一桌丰盛的年夜饭。","pinyin":"Wàipó wèi wǒmen zhǔnbèile yì zhuō fēngshèng de niányèfàn.","vi":"Bà ngoại đã chuẩn bị cho chúng tôi một mâm cơm tất niên thịnh soạn."},{"type":"compound","zh":"虽然早餐很丰盛，但是他因为紧张一口也吃不下。","pinyin":"Suīrán zǎocān hěn fēngshèng, dànshì tā yīnwèi jǐnzhāng yìkǒu yě chībuxià.","vi":"Tuy bữa sáng rất thịnh soạn, nhưng vì căng thẳng mà anh ấy không ăn nổi một miếng."}],"related":[{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"},{"hanzi":"丰盛的晚餐","pinyin":"fēngshèng de wǎncān","vi":"bữa tối thịnh soạn"},{"hanzi":"简单","pinyin":"jiǎndān","vi":"đơn giản"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"được mùa"}],"traditional":"豐盛"},{"id":"风向标","hanzi":"风向标","pinyin":"fēngxiàngbiāo","meaning_vi":"chong chóng chỉ hướng gió; chỉ dấu xu hướng, kim chỉ nam","explanation":"风 (风) + 向 (hướng về) + 标 (tiêu chuẩn/ký hiệu).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet"],"image":"🧭","examples":[{"type":"basic","zh":"屋顶上有个风向标。","pinyin":"Wūdǐng shàng yǒu gè fēngxiàngbiāo.","vi":"Trên mái nhà có một chiếc chong chóng chỉ hướng gió."},{"type":"simple","zh":"这场车展被视为汽车行业发展的风向标。","pinyin":"Zhè chǎng chēzhǎn bèi shìwéi qìchē hángyè fāzhǎn de fēngxiàngbiāo.","vi":"Triển lãm ô tô này được xem là kim chỉ nam cho xu hướng phát triển của ngành ô tô."},{"type":"compound","zh":"因为这位博主的推荐很准，所以她成了年轻人消费的风向标。","pinyin":"Yīnwèi zhè wèi bózhǔ de tuījiàn hěn zhǔn, suǒyǐ tā chéngle niánqīngrén xiāofèi de fēngxiàngbiāo.","vi":"Vì những gợi ý của blogger này rất chuẩn nên cô ấy trở thành chỉ dấu xu hướng tiêu dùng của giới trẻ."}],"related":[{"hanzi":"风向","pinyin":"fēngxiàng","vi":"hướng gió"},{"hanzi":"指南针","pinyin":"zhǐnánzhēn","vi":"la bàn"},{"hanzi":"晴雨表","pinyin":"qíngyǔbiǎo","vi":"phong vũ biểu"},{"hanzi":"趋势","pinyin":"qūshì","vi":"xu thế"}],"traditional":"風向標"},{"id":"法宝","hanzi":"法宝","pinyin":"fǎbǎo","meaning_vi":"bảo bối, bí quyết thành công","explanation":"法 (pháp – phép thuật) + 宝 (bảo – báu vật) → pháp bảo của thần tiên trong truyện; nghĩa bóng: bí quyết, công cụ đắc lực để thành công.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💎","examples":[{"type":"basic","zh":"微笑是她的法宝。","pinyin":"Wēixiào shì tā de fǎbǎo.","vi":"Nụ cười là bảo bối của cô ấy."},{"type":"simple","zh":"坚持每天复习是他学好中文的法宝。","pinyin":"Jiānchí měitiān fùxí shì tā xuéhǎo Zhōngwén de fǎbǎo.","vi":"Kiên trì ôn tập mỗi ngày là bí quyết giúp anh ấy học giỏi tiếng Trung."},{"type":"compound","zh":"只要掌握了这个法宝，你就能轻松应对任何面试。","pinyin":"Zhǐyào zhǎngwòle zhè ge fǎbǎo, nǐ jiù néng qīngsōng yìngduì rènhé miànshì.","vi":"Chỉ cần nắm được bí quyết này, bạn có thể dễ dàng ứng phó với bất kỳ cuộc phỏng vấn nào."}],"related":[{"hanzi":"宝贝","pinyin":"bǎobèi","vi":"báu vật"},{"hanzi":"秘诀","pinyin":"mìjué","vi":"bí quyết"},{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"},{"hanzi":"诀窍","pinyin":"juéqiào","vi":"mẹo"}],"traditional":"法寶"},{"id":"法典","hanzi":"法典","pinyin":"fǎdiǎn","meaning_vi":"bộ luật","explanation":"法 (法) + 典 (điển hình/nghi lễ).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"民法典正式实施。","pinyin":"Mínfǎdiǎn zhèngshì shíshī.","vi":"Bộ luật Dân sự chính thức có hiệu lực."},{"type":"simple","zh":"汉谟拉比法典是世界上最古老的成文法之一。","pinyin":"Hàn mó lābǐ fǎdiǎn shì shìjiè shàng zuì gǔlǎo de chéngwénfǎ zhīyī.","vi":"Bộ luật Hammurabi là một trong những bộ luật thành văn cổ xưa nhất thế giới."},{"type":"compound","zh":"一旦新法典生效，原有的几部单行法就将同时废止。","pinyin":"Yídàn xīn fǎdiǎn shēngxiào, yuán yǒude jǐ bù dānxíng fǎ jiù jiāng tóngshí fèizhǐ.","vi":"Một khi bộ luật mới có hiệu lực, một số luật riêng lẻ cũ sẽ đồng thời bị bãi bỏ."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"民法典","pinyin":"mínfǎdiǎn","vi":"bộ luật dân sự"},{"hanzi":"宪法","pinyin":"xiànfǎ","vi":"hiến pháp"},{"hanzi":"法规","pinyin":"fǎguī","vi":"pháp quy"}]},{"id":"法官","hanzi":"法官","pinyin":"fǎguān","meaning_vi":"thẩm phán","explanation":"法 (法) + 官 (quan chức).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"法官宣布休庭。","pinyin":"Fǎguān xuānbù xiūtíng.","vi":"Thẩm phán tuyên bố tạm nghỉ phiên tòa."},{"type":"simple","zh":"法官仔细听取了原告和被告双方的陈述。","pinyin":"Fǎguān zǐxì tīngqǔle yuángào hé bèigào shuāngfāng de chénshù.","vi":"Thẩm phán đã chăm chú lắng nghe lời trình bày của cả nguyên đơn và bị đơn."},{"type":"compound","zh":"法官既要依法判决，又要考虑案件的社会影响。","pinyin":"Fǎguān jì yào yīfǎ pànjué, yòu yào kǎolǜ ànjiàn de shèhuì yǐngxiǎng.","vi":"Thẩm phán vừa phải xét xử theo pháp luật, vừa phải cân nhắc tác động xã hội của vụ án."}],"related":[{"hanzi":"律师","pinyin":"lǜshī","vi":"luật sư"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"},{"hanzi":"检察官","pinyin":"jiǎncháguān","vi":"kiểm sát viên"},{"hanzi":"审判","pinyin":"shěnpàn","vi":"xét xử"}]},{"id":"法学","hanzi":"法学","pinyin":"fǎxué","meaning_vi":"luật học, khoa Luật","explanation":"法 (法) + 学 (học thuật/học thuyết).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","phap-luat"],"image":"🎓","examples":[{"type":"basic","zh":"她在大学读法学。","pinyin":"Tā zài dàxué dú fǎxué.","vi":"Cô ấy học ngành luật ở đại học."},{"type":"simple","zh":"这位法学教授经常为政府立法提供咨询意见。","pinyin":"Zhè wèi fǎxué jiàoshòu jīngcháng wèi zhèngfǔ lìfǎ tígōng zīxún yìjiàn.","vi":"Vị giáo sư luật học này thường xuyên tư vấn cho chính phủ trong công tác lập pháp."},{"type":"compound","zh":"如果你想当律师，就得先拿到法学学位。","pinyin":"Rúguǒ nǐ xiǎng dāng lǜshī, jiù děi xiān nádào fǎxué xuéwèi.","vi":"Nếu bạn muốn làm luật sư thì trước hết phải có bằng luật."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"法学院","pinyin":"fǎxuéyuàn","vi":"trường luật"},{"hanzi":"律师","pinyin":"lǜshī","vi":"luật sư"},{"hanzi":"司法","pinyin":"sīfǎ","vi":"tư pháp"}],"traditional":"法學"},{"id":"反差","hanzi":"反差","pinyin":"fǎnchā","meaning_vi":"sự tương phản, chênh lệch rõ rệt","explanation":"反 (phản – ngược) + 差 (sai – chênh lệch) → độ tương phản, sự chênh lệch rõ khi so sánh hai thứ. VD: 反差很大, 形成鲜明反差.","hsk_level":"7-9","tags":["danh-tu"],"image":"↔️","examples":[{"type":"basic","zh":"两人性格反差很大。","pinyin":"Liǎng rén xìnggé fǎnchā hěn dà.","vi":"Tính cách hai người tương phản rất lớn."},{"type":"simple","zh":"他在舞台上的狂野和生活中的害羞形成了强烈反差。","pinyin":"Tā zài wǔtái shàng de kuángyě hé shēnghuó zhōng de hàixiū xíng chéngle qiángliè fǎnchā.","vi":"Sự cuồng nhiệt trên sân khấu và vẻ nhút nhát ngoài đời của anh ấy tạo nên sự tương phản mạnh mẽ."},{"type":"compound","zh":"因为期望太高，所以真实结果带来的反差让他很失落。","pinyin":"Yīnwèi qīwàng tài gāo, suǒyǐ zhēnshí jiéguǒ dàilái de fǎnchā ràng tā hěn shīluò.","vi":"Vì kỳ vọng quá cao nên sự chênh lệch với kết quả thực tế khiến anh ấy rất hụt hẫng."}],"related":[{"hanzi":"对比","pinyin":"duìbǐ","vi":"đối lập"},{"hanzi":"差距","pinyin":"chājù","vi":"chênh lệch"},{"hanzi":"落差","pinyin":"luòchā","vi":"độ chênh"},{"hanzi":"鲜明","pinyin":"xiānmíng","vi":"rõ rệt"}]},{"id":"反垄断","hanzi":"反垄断","pinyin":"fǎnlǒngduàn","meaning_vi":"chống độc quyền","explanation":"反 (chống) + 垄断 (độc quyền).","hsk_level":"7-9","tags":["danh-tu","phap-luat","cong-viec"],"image":"⚖️","examples":[{"type":"basic","zh":"政府加强了反垄断调查。","pinyin":"Zhèngfǔ jiāqiángle fǎnlǒngduàn diàochá.","vi":"Chính phủ đã tăng cường điều tra chống độc quyền."},{"type":"simple","zh":"这家科技巨头因违反反垄断法被罚款数十亿元。","pinyin":"Zhè jiā kējì jùtóu yīn wéifǎn fǎnlǒngduàn fǎ bèi fákuǎn shùshíyì yuán.","vi":"Gã khổng lồ công nghệ này bị phạt hàng tỉ tệ vì vi phạm luật chống độc quyền."},{"type":"compound","zh":"如果平台继续滥用市场地位，反垄断机构就会介入调查。","pinyin":"Rúguǒ píngtái jìxù lànyòng shìchǎng dìwèi, fǎnlǒngduàn jīgòu jiù huì jièrù diàochá.","vi":"Nếu nền tảng tiếp tục lạm dụng vị thế thị trường, cơ quan chống độc quyền sẽ vào cuộc điều tra."}],"related":[{"hanzi":"垄断","pinyin":"lǒngduàn","vi":"độc quyền"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"反倾销","pinyin":"fǎnqīngxiāo","vi":"chống bán phá giá"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"}],"traditional":"反壟斷"},{"id":"反问句","hanzi":"反问句","pinyin":"fǎnwènjù","meaning_vi":"câu hỏi tu từ","explanation":"反 (反) + 问 (hỏi) + 句 (câu).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"❓","examples":[{"type":"basic","zh":"这是一个反问句。","pinyin":"Zhè shì yí gè fǎnwènjù.","vi":"Đây là một câu hỏi tu từ."},{"type":"simple","zh":"老师要求我们把这个反问句改成陈述句。","pinyin":"Lǎoshī yāoqiú wǒmen bǎ zhè ge fǎnwènjù gǎichéng chénshùjù.","vi":"Cô giáo yêu cầu chúng tôi đổi câu hỏi tu từ này thành câu trần thuật."},{"type":"compound","zh":"虽然反问句没有疑问，但是语气比陈述句更强烈。","pinyin":"Suīrán fǎnwènjù méiyǒu yíwèn, dànshì yǔqì bǐ chénshùjù gèng qiángliè.","vi":"Tuy câu hỏi tu từ không mang ý hỏi, nhưng ngữ khí mạnh hơn câu trần thuật."}],"related":[{"hanzi":"疑问句","pinyin":"yíwènjù","vi":"câu nghi vấn"},{"hanzi":"反问","pinyin":"fǎnwèn","vi":"hỏi vặn lại"},{"hanzi":"修辞","pinyin":"xiūcí","vi":"tu từ"}],"traditional":"反問句"},{"id":"返乡","hanzi":"返乡","pinyin":"fǎnxiāng","meaning_vi":"về quê hương","explanation":"返 (返) + 乡 (quê hương).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🏡","examples":[{"type":"basic","zh":"春节前他坐火车返乡。","pinyin":"Chūnjié qián tā zuò huǒchē fǎnxiāng.","vi":"Trước Tết anh ấy đi tàu về quê."},{"type":"simple","zh":"大批外出务工人员陆续返乡过年。","pinyin":"Dàpī wàichū wùgōng rényuán lùxù fǎnxiāng guònián.","vi":"Đông đảo lao động đi làm xa lần lượt về quê ăn Tết."},{"type":"compound","zh":"大学毕业后，他不但返乡创业，而且带动了全村致富。","pinyin":"Dàxué bìyè hòu, tā búdàn fǎnxiāng chuàngyè, érqiě dàidòngle quán cūn zhìfù.","vi":"Sau khi tốt nghiệp đại học, anh không những về quê khởi nghiệp mà còn giúp cả làng làm giàu."}],"related":[{"hanzi":"回乡","pinyin":"huíxiāng","vi":"về quê"},{"hanzi":"故乡","pinyin":"gùxiāng","vi":"quê hương"},{"hanzi":"返回","pinyin":"fǎnhuí","vi":"quay trở về"}],"traditional":"返鄉"},{"id":"反响热烈","hanzi":"反响热烈","pinyin":"fǎnxiǎngrèliè","meaning_vi":"phản hồi nhiệt liệt","explanation":"反 (反) + 响 (vang) + 热 (nóng) + 烈 (mãnh liệt/anh liệt).","hsk_level":"7-9","tags":["tinh-tu","giai-tri","xa-hoi"],"image":"👏","examples":[{"type":"basic","zh":"新书出版后反响热烈。","pinyin":"Xīn shū chūbǎn hòu fǎnxiǎngrèliè.","vi":"Sách mới ra mắt nhận được phản hồi nhiệt liệt."},{"type":"simple","zh":"这部纪录片在网上播出后观众反响热烈。","pinyin":"Zhè bù jìlùpiàn zài wǎngshàng bōchū hòu guānzhòng fǎnxiǎngrèliè.","vi":"Bộ phim tài liệu này sau khi phát sóng trên mạng được khán giả hưởng ứng nhiệt liệt."},{"type":"compound","zh":"因为讲座内容贴近生活，所以学生们反响热烈。","pinyin":"Yīnwèi jiǎngzuò nèiróng tiējìn shēnghuó, suǒyǐ xuéshēngmen fǎnxiǎngrèliè.","vi":"Vì nội dung buổi tọa đàm gần gũi với cuộc sống nên sinh viên hưởng ứng rất nhiệt liệt."}],"related":[{"hanzi":"反响","pinyin":"fǎnxiǎng","vi":"phản hồi, tiếng vang"},{"hanzi":"热烈","pinyin":"rèliè","vi":"nhiệt liệt"},{"hanzi":"好评","pinyin":"hǎopíng","vi":"đánh giá tốt"}],"traditional":"反響熱烈"},{"id":"仿制","hanzi":"仿制","pinyin":"fǎngzhì","meaning_vi":"mô phỏng chế tạo, làm theo mẫu","explanation":"仿 (仿) + 制 (chế độ/kiềm chế).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这件瓷器是仿制的。","pinyin":"Zhè jiàn cíqì shì fǎngzhì de.","vi":"Món đồ sứ này là đồ làm theo mẫu."},{"type":"simple","zh":"工厂未经授权仿制了一款名牌手表。","pinyin":"Gōngchǎng wèijīng shòuquán fǎngzhìle yì kuǎn míngpái shǒubiǎo.","vi":"Nhà máy đã làm nhái một mẫu đồng hồ hàng hiệu mà không được cấp phép."},{"type":"compound","zh":"即使外观仿制得再像，内部零件也很难达到原厂水平。","pinyin":"Jíshǐ wàiguān fǎngzhì de zài xiàng, nèibù língjiàn yě hěn nán dádào yuán chǎng shuǐpíng.","vi":"Dù vẻ ngoài có được làm nhái giống đến đâu, linh kiện bên trong cũng khó đạt chuẩn hãng gốc."}],"related":[{"hanzi":"仿造","pinyin":"fǎngzào","vi":"làm giả theo mẫu"},{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"},{"hanzi":"仿制品","pinyin":"fǎngzhìpǐn","vi":"hàng nhái"}],"traditional":"仿製"},{"id":"过冬","hanzi":"过冬","pinyin":"guòdōng","meaning_vi":"trải qua mùa đông","explanation":"过 (quá – trải qua) + 冬 (đông – mùa đông) → trải qua mùa đông, tránh rét. VD: 候鸟南飞过冬.","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"燕子飞到南方过冬。","pinyin":"Yànzi fēi dào nánfāng guòdōng.","vi":"Chim én bay về phương Nam để tránh đông."},{"type":"simple","zh":"奶奶早早备好了过冬用的棉被和白菜。","pinyin":"Nǎinai zǎo zǎo bèi hǎole guòdōng yòng de miánbèi hé báicài.","vi":"Bà đã sớm chuẩn bị chăn bông và cải thảo để qua mùa đông."},{"type":"compound","zh":"只要储存足够的粮食，松鼠就能安全过冬。","pinyin":"Zhǐyào chǔcún zúgòu de liángshi, sōngshǔ jiù néng ānquán guòdōng.","vi":"Chỉ cần dự trữ đủ thức ăn, sóc có thể qua mùa đông an toàn."}],"related":[{"hanzi":"冬天","pinyin":"dōngtiān","vi":"mùa đông"},{"hanzi":"越冬","pinyin":"yuèdōng","vi":"qua mùa đông"},{"hanzi":"御寒","pinyin":"yùhán","vi":"chống rét"}],"traditional":"過冬"},{"id":"过关","hanzi":"过关","pinyin":"guòguān","meaning_vi":"qua ải; đạt yêu cầu, đạt chuẩn","explanation":"过 (từng) + 关 (đóng).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✅","examples":[{"type":"basic","zh":"他的驾照考试过关了。","pinyin":"Tā de jiàzhào kǎoshì guòguān le.","vi":"Anh ấy đã thi đỗ bằng lái."},{"type":"simple","zh":"这批产品的质量检测终于全部过关。","pinyin":"Zhè pī chǎnpǐn de zhìliàng jiǎncè zhōngyú quánbù guòguān.","vi":"Lô sản phẩm này cuối cùng đã đạt toàn bộ kiểm định chất lượng."},{"type":"compound","zh":"如果基本功不过关，就很难在比赛中取得好成绩。","pinyin":"Rúguǒ jīběngōng bú guòguān, jiù hěn nán zài bǐsài zhōng qǔdé hǎo chéngjì.","vi":"Nếu kỹ năng cơ bản chưa đạt, sẽ khó có thành tích tốt trong thi đấu."}],"related":[{"hanzi":"闯关","pinyin":"chuǎngguān","vi":"vượt ải"},{"hanzi":"合格","pinyin":"hégé","vi":"đạt tiêu chuẩn"},{"hanzi":"关口","pinyin":"guānkǒu","vi":"cửa ải"}],"traditional":"過關"},{"id":"贯彻落实","hanzi":"贯彻落实","pinyin":"guànchèluòshí","meaning_vi":"quán triệt và thực hiện nghiêm túc","explanation":"贯 (quán triệt/xuyên suốt) + 彻 (triệt để/thông suốt) + 落 (rơi rụng/thực hiện) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"各部门要贯彻落实新规定。","pinyin":"Gè bùmén yào guànchèluòshí xīn guīdìng.","vi":"Các bộ phận phải quán triệt và thực hiện quy định mới."},{"type":"simple","zh":"学校认真贯彻落实了减轻学生课业负担的政策。","pinyin":"Xuéxiào rènzhēn guànchèluòshíle jiǎnqīng xuéshēng kèyè fùdān de zhèngcè.","vi":"Nhà trường nghiêm túc quán triệt và thực hiện chính sách giảm tải bài vở cho học sinh."},{"type":"compound","zh":"如果不把政策贯彻落实到基层，再好的方案也只是一纸空文。","pinyin":"Rúguǒ bù bǎ zhèngcè guànchèluòshí dào jīcéng, zài hǎo de fāng'àn yě zhǐshì yì zhǐ kōng wén.","vi":"Nếu không quán triệt thực hiện chính sách đến tận cơ sở, phương án hay đến mấy cũng chỉ là giấy tờ suông."}],"related":[{"hanzi":"贯彻","pinyin":"guànchè","vi":"quán triệt"},{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện"},{"hanzi":"执行","pinyin":"zhíxíng","vi":"chấp hành"}],"traditional":"貫徹落實"},{"id":"贯通","hanzi":"贯通","pinyin":"guàntōng","meaning_vi":"thông suốt, nối liền","explanation":"贯 (quán triệt/xuyên suốt) + 通 (thông suốt/phổ biến).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"这条隧道已全线贯通。","pinyin":"Zhè tiáo suìdào yǐ quánxiàn guàntōng.","vi":"Đường hầm này đã thông suốt toàn tuyến."},{"type":"simple","zh":"新建的跨江大桥把南北两岸贯通起来了。","pinyin":"Xīnjiàn de kuà jiāng Dàqiáo bǎ nánběi liǎng'àn guàntōng qǐlái le.","vi":"Cây cầu vượt sông mới xây đã nối liền hai bờ nam bắc."},{"type":"compound","zh":"一旦地铁三号线贯通，从机场到市中心只需半小时。","pinyin":"Yídàn dìtiě sān hào xiàn guàntōng, cóng jīchǎng dào shìzhōngxīn zhǐxū bànxiǎoshí.","vi":"Một khi tuyến metro số 3 thông suốt, từ sân bay vào trung tâm chỉ mất nửa tiếng."}],"related":[{"hanzi":"连通","pinyin":"liántōng","vi":"nối liền"},{"hanzi":"融会贯通","pinyin":"rónghuìguàntōng","vi":"thông hiểu thấu đáo"},{"hanzi":"畅通","pinyin":"chàngtōng","vi":"thông suốt"}],"traditional":"貫通"},{"id":"国宝","hanzi":"国宝","pinyin":"guóbǎo","meaning_vi":"quốc bảo, báu vật quốc gia","explanation":"国 (quốc – nước) + 宝 (bảo – báu vật) → báu vật quốc gia; ở TQ hay dùng để gọi gấu trúc (熊猫是国宝).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🐼","examples":[{"type":"basic","zh":"大熊猫是中国的国宝。","pinyin":"Dàxióngmāo shì Zhōngguó de guóbǎo.","vi":"Gấu trúc lớn là quốc bảo của Trung Quốc."},{"type":"simple","zh":"这件青铜器被誉为博物馆的镇馆国宝。","pinyin":"Zhè jiàn qīngtóngqì bèi yù wéi bówùguǎn de zhèn guǎn guóbǎo.","vi":"Món đồ đồng này được ví là quốc bảo trấn giữ của bảo tàng."},{"type":"compound","zh":"这批流失海外的国宝一回到故土，就吸引了大批观众前来参观。","pinyin":"Zhè pī liúshī hǎiwài de guóbǎo yì huídào gùtǔ, jiù xīyǐnle dàpī guānzhòng qiánlái cānguān.","vi":"Lô quốc bảo thất lạc ở nước ngoài này vừa trở về cố hương đã thu hút đông đảo khách đến tham quan."}],"related":[{"hanzi":"大熊猫","pinyin":"dàxióngmāo","vi":"gấu trúc"},{"hanzi":"文物","pinyin":"wénwù","vi":"cổ vật"},{"hanzi":"珍宝","pinyin":"zhēnbǎo","vi":"báu vật"}],"traditional":"國寶"},{"id":"国粹","hanzi":"国粹","pinyin":"guócuì","meaning_vi":"quốc túy (tinh hoa văn hóa dân tộc như Kinh kịch)","explanation":"国 (quốc – nước) + 粹 (túy – tinh túy) → tinh hoa văn hóa của dân tộc. VD: 京剧是中国的国粹.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"京剧被称为国粹。","pinyin":"Jīngjù bèi chēngwéi guócuì.","vi":"Kinh kịch được gọi là quốc túy."},{"type":"simple","zh":"这位老艺人一辈子都在传承书法这门国粹。","pinyin":"Zhè wèi lǎo yìrén yíbèizi dōu zài chuánchéng shūfǎ zhè mén guócuì.","vi":"Vị nghệ nhân già này cả đời truyền dạy thư pháp, một tinh hoa quốc túy."},{"type":"compound","zh":"虽然年轻人喜欢流行音乐，但是不少人也开始欣赏京剧这一国粹。","pinyin":"Suīrán niánqīngrén xǐhuan liúxíng yīnyuè, dànshì bùshǎo rén yě kāishǐ xīnshǎng Jīngjù zhè yì guócuì.","vi":"Tuy giới trẻ thích nhạc pop, nhưng không ít người cũng bắt đầu thưởng thức Kinh kịch, một quốc túy."}],"related":[{"hanzi":"京剧","pinyin":"Jīngjù","vi":"Kinh kịch"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"传统文化","pinyin":"chuántǒngwénhuà","vi":"văn hóa truyền thống"}],"traditional":"國粹"},{"id":"国画","hanzi":"国画","pinyin":"guóhuà","meaning_vi":"tranh quốc họa (hội họa truyền thống Trung Quốc)","explanation":"国 (quốc – nước) + 画 (họa – tranh) → quốc họa, tranh truyền thống TQ vẽ bằng bút lông, mực nước trên giấy Tuyên.","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🖼️","examples":[{"type":"basic","zh":"爷爷喜欢画国画。","pinyin":"Yéye xǐhuan huà guóhuà.","vi":"Ông nội thích vẽ tranh quốc họa."},{"type":"simple","zh":"她在美术馆欣赏了一幅齐白石的国画。","pinyin":"Tā zài měishùguǎn xīnshǎngle yì fú Qíbáishí de guóhuà.","vi":"Cô ấy ngắm một bức quốc họa của Tề Bạch Thạch tại bảo tàng mỹ thuật."},{"type":"compound","zh":"国画既讲究笔墨技法，又注重意境的表达。","pinyin":"Guóhuà jì jiǎngjiu bǐmò jìfǎ, yòu zhùzhòng yìjìng de biǎodá.","vi":"Tranh quốc họa vừa chú trọng kỹ pháp bút mực, vừa coi trọng việc thể hiện ý cảnh."}],"related":[{"hanzi":"山水画","pinyin":"shānshuǐhuà","vi":"tranh sơn thủy"},{"hanzi":"油画","pinyin":"yóuhuà","vi":"tranh sơn dầu"},{"hanzi":"水墨画","pinyin":"shuǐmòhuà","vi":"tranh thủy mặc"}],"traditional":"國畫"},{"id":"国际化","hanzi":"国际化","pinyin":"guójìhuà","meaning_vi":"quốc tế hóa","explanation":"国 (nước) + 际 (quốc tế/ranh giới) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"这座城市越来越国际化。","pinyin":"Zhè zuò chéngshì yuèláiyuè guójìhuà.","vi":"Thành phố này ngày càng quốc tế hóa."},{"type":"simple","zh":"公司计划明年推进品牌国际化战略。","pinyin":"Gōngsī jìhuà míngnián tuījìn pǐnpái guójìhuà zhànlüè.","vi":"Công ty dự định năm sau thúc đẩy chiến lược quốc tế hóa thương hiệu."},{"type":"compound","zh":"如果学校想走国际化道路，就要多招收外国留学生。","pinyin":"Rúguǒ xuéxiào xiǎng zǒu guójìhuà dàolù, jiùyào duō zhāoshōu wàiguó liúxuéshēng.","vi":"Nếu trường muốn đi theo con đường quốc tế hóa thì phải tuyển nhiều du học sinh nước ngoài hơn."}],"related":[{"hanzi":"全球化","pinyin":"quánqiúhuà","vi":"toàn cầu hóa"},{"hanzi":"国际","pinyin":"Guójì","vi":"quốc tế"},{"hanzi":"本土化","pinyin":"běntǔhuà","vi":"bản địa hóa"}],"traditional":"國際化"},{"id":"国民生产总值","hanzi":"国民生产总值","pinyin":"guómín shēngchǎn zǒngzhí","meaning_vi":"tổng sản phẩm quốc dân (GNP)","explanation":"Thuật ngữ kinh tế vĩ mô.","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"🌐","examples":[{"type":"basic","zh":"去年国民生产总值有所增长。","pinyin":"Qùnián guómínshēngchǎnzǒngzhí yǒusuǒ zēngzhǎng.","vi":"Năm ngoái tổng sản phẩm quốc dân có tăng trưởng."},{"type":"simple","zh":"经济学家比较了两国的人均国民生产总值。","pinyin":"Jīngjìxué jiā bǐjiàole liǎngguó de rénjūn guómínshēngchǎnzǒngzhí.","vi":"Các nhà kinh tế học đã so sánh GNP bình quân đầu người của hai nước."},{"type":"compound","zh":"国民生产总值虽然在上升，但是普通家庭的收入并没有明显增加。","pinyin":"Guómínshēngchǎnzǒngzhí suīrán zài shàngshēng, dànshì pǔtōng jiātíng de shōurù bìng méiyǒu míngxiǎn zēngjiā.","vi":"Tổng sản phẩm quốc dân tuy đang tăng, nhưng thu nhập của các gia đình bình thường không tăng rõ rệt."}],"related":[{"hanzi":"国内生产总值","pinyin":"guónèi shēngchǎn zǒngzhí","vi":"GDP"},{"hanzi":"经济增长","pinyin":"jīngjìzēngzhǎng","vi":"tăng trưởng kinh tế"},{"hanzi":"人均收入","pinyin":"rénjūnshōurù","vi":"thu nhập bình quân"}],"traditional":"國民生產總值"},{"id":"国内生产总值","hanzi":"国内生产总值","pinyin":"guónèi shēngchǎn zǒngzhí","meaning_vi":"tổng sản phẩm quốc nội (GDP)","explanation":"Thuật ngữ kinh tế vĩ mô.","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"📈","examples":[{"type":"basic","zh":"国内生产总值是重要指标。","pinyin":"Guónèishēngchǎnzǒngzhí shì zhòngyào zhǐbiāo.","vi":"GDP là một chỉ số quan trọng."},{"type":"simple","zh":"今年第三季度的国内生产总值同比增长了百分之五。","pinyin":"Jīnnián dì sān jìdù de guónèishēngchǎnzǒngzhí tóngbǐ zēngzhǎngle bǎifēnzhī wǔ.","vi":"GDP quý ba năm nay tăng 5% so với cùng kỳ."},{"type":"compound","zh":"一旦出口大幅下滑，国内生产总值的增速就会受到影响。","pinyin":"Yídàn chūkǒu dàfú xiàhuá, guónèishēngchǎnzǒngzhí de zēngsù jiù huì shòudào yǐngxiǎng.","vi":"Một khi xuất khẩu sụt giảm mạnh, tốc độ tăng GDP sẽ bị ảnh hưởng."}],"related":[{"hanzi":"国民生产总值","pinyin":"guómín shēngchǎn zǒngzhí","vi":"GNP"},{"hanzi":"经济增长","pinyin":"jīngjìzēngzhǎng","vi":"tăng trưởng kinh tế"},{"hanzi":"增长率","pinyin":"zēngzhǎnglǜ","vi":"tỷ lệ tăng trưởng"}],"traditional":"國內生產總值"},{"id":"国情","hanzi":"国情","pinyin":"guóqíng","meaning_vi":"tình hình đất nước","explanation":"国 (nước) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"每个国家国情不同。","pinyin":"Měi gè guójiā guóqíng bùtóng.","vi":"Tình hình mỗi nước mỗi khác."},{"type":"simple","zh":"外交官出发前专门学习了驻在国的国情。","pinyin":"Wàijiāoguān chūfā qián zhuānmén xuéxíle zhù zài guó de guóqíng.","vi":"Trước khi lên đường, nhà ngoại giao đã chuyên tâm tìm hiểu tình hình nước sở tại."},{"type":"compound","zh":"与其照搬别国的模式，不如从本国国情出发制定政策。","pinyin":"Yǔqí zhàobān bié guó de móshì, bùrú cóng běnguó guóqíng chūfā zhìdìng zhèngcè.","vi":"Thay vì rập khuôn mô hình nước khác, chi bằng xây dựng chính sách xuất phát từ tình hình trong nước."}],"related":[{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"},{"hanzi":"民情","pinyin":"mínqíng","vi":"tình hình dân chúng"},{"hanzi":"实际情况","pinyin":"shíjìqíngkuàng","vi":"tình hình thực tế"}],"traditional":"國情"},{"id":"国学","hanzi":"国学","pinyin":"guóxué","meaning_vi":"Quốc học (học thuật truyền thống Trung Hoa)","explanation":"国 (nước) + 学 (học thuật/học thuyết).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"他从小学习国学。","pinyin":"Tā cóngxiǎo xuéxí guóxué.","vi":"Anh ấy học Quốc học từ nhỏ."},{"type":"simple","zh":"这位教授在大学里开设了一门国学经典选读课。","pinyin":"Zhè wèi jiàoshòu zài dàxué lǐ kāishèle yì mén guóxué jīngdiǎn xuǎn dú kè.","vi":"Vị giáo sư này mở một môn đọc chọn lọc kinh điển Quốc học ở trường đại học."},{"type":"compound","zh":"读国学经典不但能积累知识，而且能提高个人修养。","pinyin":"Dú guóxué jīngdiǎn búdàn néng jīlěi zhīshi, érqiě néng tígāo gèrén xiūyǎng.","vi":"Đọc kinh điển Quốc học không chỉ tích lũy tri thức mà còn nâng cao tu dưỡng cá nhân."}],"related":[{"hanzi":"儒学","pinyin":"Rúxué","vi":"Nho học"},{"hanzi":"经典","pinyin":"jīngdiǎn","vi":"kinh điển"},{"hanzi":"传统文化","pinyin":"chuántǒngwénhuà","vi":"văn hóa truyền thống"}],"traditional":"國學"},{"id":"观感","hanzi":"观感","pinyin":"guāngǎn","meaning_vi":"cảm nhận sau khi xem/trải nghiệm","explanation":"观 (quan – xem) + 感 (cảm – cảm nhận) → cảm nhận, ấn tượng sau khi xem hoặc trải nghiệm. VD: 谈谈你的观感.","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"👀","examples":[{"type":"basic","zh":"请谈谈你的观感。","pinyin":"Qǐng tántan nǐ de guāngǎn.","vi":"Xin hãy nói cảm nhận của bạn."},{"type":"simple","zh":"访问团回国后写了一篇关于乡村振兴的观感。","pinyin":"Fǎngwèn tuán huíguó hòu xiěle yì piān guānyú xiāngcūnzhènxīng de guāngǎn.","vi":"Sau khi về nước, đoàn khảo sát đã viết một bài cảm nhận về chấn hưng nông thôn."},{"type":"compound","zh":"虽然只在西安待了三天，但是这座古城给我的观感非常好。","pinyin":"Suīrán zhǐ zài Xī'ān dāile sān tiān, dànshì zhè zuò gǔchéng gěi wǒ de guāngǎn fēicháng hǎo.","vi":"Tuy chỉ ở Tây An ba ngày, nhưng thành cổ này để lại cho tôi cảm nhận rất tốt."}],"related":[{"hanzi":"感受","pinyin":"gǎnshòu","vi":"cảm nhận"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"ấn tượng"},{"hanzi":"观后感","pinyin":"guānhòugǎn","vi":"cảm nghĩ sau khi xem"}],"traditional":"觀感"},{"id":"关键词","hanzi":"关键词","pinyin":"guānjiàncí","meaning_vi":"từ khóa (keywords)","explanation":"关 (đóng) + 键 (phím bấm/then chốt) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","cong-nghe"],"image":"🔑","examples":[{"type":"basic","zh":"请输入关键词搜索。","pinyin":"Qǐng shūrù guānjiàncí sōusuǒ.","vi":"Hãy nhập từ khóa để tìm kiếm."},{"type":"simple","zh":"编辑要求作者在论文摘要后面列出三个关键词。","pinyin":"Biānjí yāoqiú zuòzhě zài lùnwén zhāiyào hòumiàn lièchū sān gè guānjiàncí.","vi":"Biên tập viên yêu cầu tác giả liệt kê ba từ khóa sau phần tóm tắt bài báo."},{"type":"compound","zh":"只要抓住文章的关键词，就能很快理解作者的观点。","pinyin":"Zhǐyào zhuāzhù wénzhāng de guānjiàncí, jiù néng hěn kuài lǐjiě zuòzhě de guāndiǎn.","vi":"Chỉ cần nắm được từ khóa của bài viết là có thể nhanh chóng hiểu quan điểm tác giả."}],"related":[{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"搜索","pinyin":"sōusuǒ","vi":"tìm kiếm"},{"hanzi":"标题","pinyin":"biāotí","vi":"tiêu đề"}],"traditional":"關鍵詞"},{"id":"关口","hanzi":"关口","pinyin":"guānkǒu","meaning_vi":"cửa ải, cửa khẩu; giai đoạn then chốt, thời khắc quyết định","explanation":"关 (quan – cửa ải) + 口 (khẩu – cửa) → cửa ải, nơi qua lại hiểm yếu; nghĩa bóng: thời điểm then chốt. VD: 在这个关口上.","hsk_level":"7-9","tags":["danh-tu"],"image":"🚧","examples":[{"type":"basic","zh":"改革到了关键关口。","pinyin":"Gǎigé dàole guānjiàn guānkǒu.","vi":"Cải cách đã đến giai đoạn then chốt."},{"type":"simple","zh":"古代商队必须在这个关口接受士兵的检查。","pinyin":"Gǔdài shāngduì bìxū zài zhè ge guānkǒu jiēshòu shìbīng de jiǎnchá.","vi":"Thời xưa các đoàn thương nhân phải chịu binh lính kiểm tra tại cửa ải này."},{"type":"compound","zh":"越是在人生的重要关口，越要保持冷静。","pinyin":"Yuè shì zài rénshēng de zhòngyào guānkǒu, yuè yào bǎochí lěngjìng.","vi":"Càng ở những thời khắc then chốt của cuộc đời, càng phải giữ bình tĩnh."}],"related":[{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"},{"hanzi":"过关","pinyin":"guòguān","vi":"vượt ải"},{"hanzi":"转折点","pinyin":"zhuǎnzhédiǎn","vi":"bước ngoặt"}],"traditional":"關口"},{"id":"关税壁垒","hanzi":"关税壁垒","pinyin":"guānshuìbìlěi","meaning_vi":"hàng rào thuế quan","explanation":"关税 (thuế hải quan) + 壁垒 (thành lũy ngăn cách).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"🚧","examples":[{"type":"basic","zh":"两国取消了关税壁垒。","pinyin":"Liǎngguó qǔxiāole guānshuìbìlěi.","vi":"Hai nước đã dỡ bỏ hàng rào thuế quan."},{"type":"simple","zh":"高额的关税壁垒让这家企业的出口订单大幅减少。","pinyin":"Gāo'é de guānshuìbìlěi ràng zhè jiā qǐyè de chūkǒu dìngdān dàfú jiǎnshǎo.","vi":"Hàng rào thuế quan cao khiến đơn hàng xuất khẩu của doanh nghiệp này giảm mạnh."},{"type":"compound","zh":"如果各国不断设置关税壁垒，全球贸易就会陷入低迷。","pinyin":"Rúguǒ gèguó búduàn shèzhì guānshuìbìlěi, quánqiú màoyì jiù huì xiànrù dīmí.","vi":"Nếu các nước liên tục dựng hàng rào thuế quan, thương mại toàn cầu sẽ rơi vào trì trệ."}],"related":[{"hanzi":"关税","pinyin":"guānshuì","vi":"thuế quan"},{"hanzi":"贸易保护","pinyin":"màoyìbǎohù","vi":"bảo hộ thương mại"},{"hanzi":"自由贸易","pinyin":"zìyóumàoyì","vi":"thương mại tự do"}],"traditional":"關稅壁壘"},{"id":"观赏","hanzi":"观赏","pinyin":"guānshǎng","meaning_vi":"thưởng ngoạn, ngắm cảnh","explanation":"观 (观) + 赏 (thưởng thức/ban thưởng).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🌸","examples":[{"type":"basic","zh":"游客们在湖边观赏荷花。","pinyin":"Yóukèmen zài húbiān guānshǎng héhuā.","vi":"Du khách ngắm hoa sen bên hồ."},{"type":"simple","zh":"这种颜色鲜艳的金鱼具有很高的观赏价值。","pinyin":"Zhè zhǒng yánsè xiānyàn de jīnyú jùyǒu hěn gāo de guānshǎng jiàzhí.","vi":"Loài cá vàng màu sắc rực rỡ này có giá trị thưởng ngoạn rất cao."},{"type":"compound","zh":"既然来到了香山，就一定要观赏一下满山的红叶。","pinyin":"Jìrán láidàole xiāng shān, jiù yídìngyào guānshǎng yíxià mǎn shān de hóngyè.","vi":"Đã đến Hương Sơn thì nhất định phải ngắm lá đỏ khắp núi."}],"related":[{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức"},{"hanzi":"观看","pinyin":"guānkàn","vi":"xem"},{"hanzi":"游览","pinyin":"yóulǎn","vi":"du ngoạn"}],"traditional":"觀賞"},{"id":"光环","hanzi":"光环","pinyin":"guānghuán","meaning_vi":"vầng hào quang","explanation":"光 (ánh sáng) + 环 (环).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🌟","examples":[{"type":"basic","zh":"她渐渐摆脱了童星光环。","pinyin":"Tā jiànjiàn bǎituōle tóngxīng guānghuán.","vi":"Cô dần thoát khỏi hào quang ngôi sao nhí."},{"type":"simple","zh":"名校毕业的光环并不能保证他找到理想的工作。","pinyin":"Míngxiào bìyè de guānghuán bìngbù néng bǎozhèng tā zhǎodào lǐxiǎng de gōngzuò.","vi":"Hào quang tốt nghiệp trường danh tiếng không đảm bảo anh ấy tìm được việc lý tưởng."},{"type":"compound","zh":"一旦失去了明星的光环，很多人就会感到失落。","pinyin":"Yídàn shīqùle míngxīng de guānghuán, hěn duō rén jiù huì gǎndào shīluò.","vi":"Một khi mất đi hào quang ngôi sao, nhiều người sẽ cảm thấy hụt hẫng."}],"related":[{"hanzi":"光芒","pinyin":"guāngmáng","vi":"tia sáng"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"明星","pinyin":"míngxīng","vi":"ngôi sao"}],"traditional":"光環"},{"id":"光年","hanzi":"光年","pinyin":"guāngnián","meaning_vi":"năm ánh sáng","explanation":"光 (ánh sáng) + 年 (năm).","hsk_level":"7-9","tags":["luong-tu","khoa-hoc"],"image":"✨","examples":[{"type":"basic","zh":"那颗星离我们十光年。","pinyin":"Nà kē xīng lí wǒmen shí guāngnián.","vi":"Ngôi sao đó cách chúng ta mười năm ánh sáng."},{"type":"simple","zh":"光年是天文学中用来测量距离的单位。","pinyin":"Guāngnián shì tiānwénxué zhōng yònglái cèliáng jùlí de dānwèi.","vi":"Năm ánh sáng là đơn vị dùng để đo khoảng cách trong thiên văn học."},{"type":"compound","zh":"虽然光年带个年字，但是它是距离单位而不是时间单位。","pinyin":"Suīrán guāngnián dài gè nián zì, dànshì tā shì jùlí dānwèi ér bú shì shíjiān dānwèi.","vi":"Tuy năm ánh sáng có chữ năm, nhưng nó là đơn vị khoảng cách chứ không phải đơn vị thời gian."}],"related":[{"hanzi":"天文","pinyin":"tiānwén","vi":"thiên văn"},{"hanzi":"光速","pinyin":"guāngsù","vi":"tốc độ ánh sáng"},{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"}]},{"id":"光阴","hanzi":"光阴","pinyin":"guāngyīn","meaning_vi":"thời gian, năm tháng","explanation":"光 (ánh sáng) + 阴 (âm u).","hsk_level":"7-9","tags":["danh-tu","thoi-gian","van-hoa"],"image":"⏳","examples":[{"type":"basic","zh":"光阴似箭，日月如梭。","pinyin":"Guāngyīn sì jiàn, rìyuè rú suō.","vi":"Thời gian thấm thoắt, ngày tháng thoi đưa."},{"type":"simple","zh":"他把大学四年的光阴都花在了实验室里。","pinyin":"Tā bǎ dàxué sì nián de guāngyīn dōu huā zài le shíyànshì lǐ.","vi":"Anh ấy đã dành trọn bốn năm đại học trong phòng thí nghiệm."},{"type":"compound","zh":"与其虚度光阴，不如趁年轻多学一门技能。","pinyin":"Yǔqí xūdù guāngyīn, bùrú chèn niánqīng duō xué yì mén jìnéng.","vi":"Thay vì phí hoài thời gian, chi bằng nhân lúc còn trẻ học thêm một kỹ năng."}],"related":[{"hanzi":"时光","pinyin":"shíguāng","vi":"thời gian"},{"hanzi":"岁月","pinyin":"suìyuè","vi":"năm tháng"},{"hanzi":"光阴似箭","pinyin":"guāngyīnsìjiàn","vi":"thời gian trôi nhanh"}],"traditional":"光陰"},{"id":"规范化","hanzi":"规范化","pinyin":"guīfànhuà","meaning_vi":"quy chuẩn hóa, chuẩn hóa","explanation":"规范 (quy phạm – chuẩn mực) + 化 (hóa – làm cho) → quy chuẩn hóa, đưa vào khuôn khổ tiêu chuẩn. VD: 管理规范化.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📏","examples":[{"type":"basic","zh":"管理流程需要规范化。","pinyin":"Guǎnlǐ liúchéng xūyào guīfànhuà.","vi":"Quy trình quản lý cần được chuẩn hóa."},{"type":"simple","zh":"医院对病历书写进行了规范化管理。","pinyin":"Yīyuàn duì bìnglì shūxiě jìnxíngle guīfànhuà guǎnlǐ.","vi":"Bệnh viện đã quản lý chuẩn hóa việc ghi chép bệnh án."},{"type":"compound","zh":"只有把数据格式规范化，不同系统之间才能顺利对接。","pinyin":"Zhǐyǒu bǎ shùjù géshì guīfànhuà, bùtóng xìtǒng zhījiān cáinéng shùnlì duìjiē.","vi":"Chỉ khi chuẩn hóa định dạng dữ liệu, các hệ thống khác nhau mới kết nối trơn tru được."}],"related":[{"hanzi":"规范","pinyin":"guīfàn","vi":"quy phạm"},{"hanzi":"标准化","pinyin":"biāozhǔnhuà","vi":"tiêu chuẩn hóa"},{"hanzi":"制度化","pinyin":"zhìdùhuà","vi":"thể chế hóa"}],"traditional":"規範化"},{"id":"归属感","hanzi":"归属感","pinyin":"guīshǔgǎn","meaning_vi":"cảm giác thuộc về, sự gắn bó","explanation":"归 (归) + 属 (thuộc về) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","xa-hoi"],"image":"🏡","examples":[{"type":"basic","zh":"我在这里找到了归属感。","pinyin":"Wǒ zài zhèlǐ zhǎodàole guīshǔgǎn.","vi":"Tôi đã tìm thấy cảm giác thuộc về ở đây."},{"type":"simple","zh":"社区定期举办邻里聚会来增强居民的归属感。","pinyin":"Shèqū dìngqī jǔbàn línlǐ jùhuì lái zēngqiáng jūmín de guīshǔgǎn.","vi":"Khu dân cư định kỳ tổ chức họp mặt hàng xóm để tăng cảm giác gắn bó của cư dân."},{"type":"compound","zh":"如果员工缺乏归属感，就很容易跳槽到别的公司。","pinyin":"Rúguǒ yuángōng quēfá guīshǔgǎn, jiù hěn róngyì tiàocáo dào biéde gōngsī.","vi":"Nếu nhân viên thiếu cảm giác gắn bó, họ rất dễ nhảy việc sang công ty khác."}],"related":[{"hanzi":"归属","pinyin":"guīshǔ","vi":"thuộc về"},{"hanzi":"认同感","pinyin":"rèntónggǎn","vi":"cảm giác đồng cảm"},{"hanzi":"安全感","pinyin":"ānquángǎn","vi":"cảm giác an toàn"}],"traditional":"歸屬感"},{"id":"归宿","hanzi":"归宿","pinyin":"guīsù","meaning_vi":"chốn về, điểm dừng chân cuối cùng","explanation":"归 (quy – trở về) + 宿 (túc – chỗ trú lại) → nơi trở về nương tựa, chốn về cuối cùng. VD: 找到好的归宿 (thường nói về hôn nhân).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🏡","examples":[{"type":"basic","zh":"家是心灵的归宿。","pinyin":"Jiā shì xīnlíng de guīsù.","vi":"Nhà là chốn về của tâm hồn."},{"type":"simple","zh":"落叶归根是许多海外游子心中最好的归宿。","pinyin":"Luòyèguīgēn shì xǔduō hǎiwài yóuzǐ xīnzhōng zuìhǎo de guīsù.","vi":"Lá rụng về cội là chốn về tốt đẹp nhất trong lòng nhiều người con xa xứ."},{"type":"compound","zh":"虽然他漂泊了半生，但是最终在故乡找到了归宿。","pinyin":"Suīrán tā piāobóle bànshēng, dànshì zuìzhōng zài gùxiāng zhǎodàole guīsù.","vi":"Tuy phiêu bạt nửa đời, nhưng cuối cùng ông đã tìm thấy chốn về ở quê nhà."}],"related":[{"hanzi":"归属","pinyin":"guīshǔ","vi":"thuộc về"},{"hanzi":"结局","pinyin":"jiéjú","vi":"kết cục"},{"hanzi":"家园","pinyin":"jiāyuán","vi":"mái nhà"}],"traditional":"歸宿"},{"id":"管弦乐","hanzi":"管弦乐","pinyin":"guǎnxiányuè","meaning_vi":"nhạc giao hưởng (dàn nhạc dây và hơi)","explanation":"管 (管) + 弦 (dây đàn) + 乐 (vui vẻ/lạc quan).","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🎻","examples":[{"type":"basic","zh":"我爱听管弦乐。","pinyin":"Wǒ ài tīng guǎnxiányuè.","vi":"Tôi thích nghe nhạc giao hưởng."},{"type":"simple","zh":"音乐厅今晚将上演一场大型管弦乐演出。","pinyin":"Yīnyuètīng jīnwǎn jiāng shàngyǎn yì chǎng dàxíng guǎnxiányuè yǎnchū.","vi":"Tối nay phòng hòa nhạc sẽ diễn một buổi hòa nhạc giao hưởng quy mô lớn."},{"type":"compound","zh":"管弦乐团一开始演奏，全场观众就安静了下来。","pinyin":"Guǎnxiányuè tuán yì kāishǐ yǎnzòu, quánchǎng guānzhòng jiù ānjìngle xiàlái.","vi":"Dàn nhạc giao hưởng vừa bắt đầu biểu diễn, toàn thể khán giả liền im lặng."}],"related":[{"hanzi":"交响乐","pinyin":"jiāoxiǎngyuè","vi":"nhạc giao hưởng"},{"hanzi":"乐队","pinyin":"yuèduì","vi":"ban nhạc"},{"hanzi":"乐器","pinyin":"yuèqì","vi":"nhạc cụ"}],"traditional":"管弦樂"},{"id":"轨道交通","hanzi":"轨道交通","pinyin":"guǐdàojiāotōng","meaning_vi":"giao thông đường sắt đô thị (metro/tàu điện)","explanation":"轨道 (quỹ đạo – đường ray) + 交通 (giao thông) → giao thông chạy trên đường ray như tàu điện ngầm, đường sắt nhẹ đô thị.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚇","examples":[{"type":"basic","zh":"城市轨道交通很方便。","pinyin":"Chéngshì guǐdàojiāotōng hěn fāngbiàn.","vi":"Giao thông đường sắt đô thị rất tiện lợi."},{"type":"simple","zh":"市政府计划五年内新建三条轨道交通线路。","pinyin":"Shìzhèngfǔ jìhuà wǔ niánnèi xīnjiàn sāntiáo guǐdàojiāotōng xiànlù.","vi":"Chính quyền thành phố dự định xây mới ba tuyến đường sắt đô thị trong năm năm."},{"type":"compound","zh":"自从轨道交通开通以后，市民上下班就不再担心堵车了。","pinyin":"Zìcóng guǐdàojiāotōng kāitōng yǐhòu, shìmín shàngxiàbān jiù bú zài dānxīn dǔchē le.","vi":"Từ khi có đường sắt đô thị, người dân đi làm không còn lo tắc đường nữa."}],"related":[{"hanzi":"地铁","pinyin":"dìtiě","vi":"tàu điện ngầm"},{"hanzi":"轻轨","pinyin":"qīngguǐ","vi":"đường sắt nhẹ"},{"hanzi":"公共交通","pinyin":"gōnggòngjiāotōng","vi":"giao thông công cộng"}],"traditional":"軌道交通"},{"id":"果园","hanzi":"果园","pinyin":"guǒyuán","meaning_vi":"vườn cây ăn quả","explanation":"果 (果) + 园 (công viên/vườn).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🍎","examples":[{"type":"basic","zh":"秋天果园里很热闹。","pinyin":"Qiūtiān guǒyuán lǐ hěn rènao.","vi":"Mùa thu trong vườn cây ăn quả rất nhộn nhịp."},{"type":"simple","zh":"周末我们一家人去郊区的果园摘苹果。","pinyin":"Zhōumò wǒmen yìjiārén qù jiāoqū de guǒyuán zhāi píngguǒ.","vi":"Cuối tuần cả nhà chúng tôi đến vườn cây ở ngoại ô hái táo."},{"type":"compound","zh":"因为今年雨水充足，所以叔叔家的果园获得了大丰收。","pinyin":"Yīnwèi jīnnián yǔshuǐ chōngzú, suǒyǐ shūshu jiā de guǒyuán huò déle dà fēngshōu.","vi":"Vì năm nay mưa thuận nên vườn cây của chú được mùa lớn."}],"related":[{"hanzi":"果树","pinyin":"guǒshù","vi":"cây ăn quả"},{"hanzi":"菜园","pinyin":"càiyuán","vi":"vườn rau"},{"hanzi":"水果","pinyin":"shuǐguǒ","vi":"hoa quả"}],"traditional":"果園"},{"id":"概貌","hanzi":"概貌","pinyin":"gàimào","meaning_vi":"diện mạo khái quát","explanation":"概 (khái quát) + 貌 (diện mạo).","hsk_level":"7-9","tags":["danh-tu"],"image":"🗺️","examples":[{"type":"basic","zh":"本文介绍了唐代社会的概貌。","pinyin":"Běnwén jièshàole Tángdài shèhuì de gàimào.","vi":"Bài viết giới thiệu diện mạo khái quát của xã hội đời Đường."},{"type":"simple","zh":"站在山顶上可以看到整座城市的概貌。","pinyin":"Zhàn zài shāndǐng shang kěyǐ kàndào zhěng zuò chéngshì de gàimào.","vi":"Đứng trên đỉnh núi có thể thấy toàn cảnh khái quát của cả thành phố."},{"type":"compound","zh":"虽然这份报告篇幅不长，但是勾勒出了行业发展的概貌。","pinyin":"Suīrán zhè fèn bàogào piānfú bù cháng, dànshì gōulè chūle hángyè fāzhǎn de gàimào.","vi":"Tuy bản báo cáo không dài, nhưng đã phác họa được diện mạo khái quát sự phát triển của ngành."}],"related":[{"hanzi":"概况","pinyin":"gàikuàng","vi":"tình hình chung"},{"hanzi":"面貌","pinyin":"miànmào","vi":"diện mạo"},{"hanzi":"全貌","pinyin":"quánmào","vi":"toàn cảnh"}]},{"id":"个性化","hanzi":"个性化","pinyin":"gèxìnghuà","meaning_vi":"cá nhân hóa","explanation":"个 (cái) + 性 (tính chất/tính cách) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"👤","examples":[{"type":"basic","zh":"这家店提供个性化服务。","pinyin":"Zhè jiā diàn tígōng gèxìnghuà fúwù.","vi":"Cửa hàng này cung cấp dịch vụ cá nhân hóa."},{"type":"simple","zh":"购物软件会根据浏览记录推送个性化的商品。","pinyin":"Gòuwù ruǎnjiàn huì gēnjù liúlǎn jìlù tuīsòng gèxìnghuà de shāngpǐn.","vi":"Ứng dụng mua sắm sẽ đề xuất sản phẩm cá nhân hóa dựa trên lịch sử duyệt."},{"type":"compound","zh":"只要上传自己的照片，就能定制个性化的手机壳。","pinyin":"Zhǐyào shàngchuán zìjǐ de zhàopiàn, jiù néng dìngzhì gèxìnghuà de shǒujīké.","vi":"Chỉ cần tải ảnh của mình lên là có thể đặt làm ốp điện thoại cá nhân hóa."}],"related":[{"hanzi":"个性","pinyin":"gèxìng","vi":"cá tính"},{"hanzi":"定制","pinyin":"dìngzhì","vi":"đặt làm riêng"},{"hanzi":"多样化","pinyin":"duōyànghuà","vi":"đa dạng hóa"}],"traditional":"個性化"},{"id":"各自为政","hanzi":"各自为政","pinyin":"gèzì-wéizhèng","meaning_vi":"mỗi người làm theo ý mình, thiếu phối hợp","explanation":"各 (các) + 自 (tự chủ/tự hào) + 为 (vì) + 政 (chính sách/chính trị).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔀","examples":[{"type":"basic","zh":"各部门不能各自为政。","pinyin":"Gè bùmén bù néng gèzìwéizhèng.","vi":"Các phòng ban không thể mạnh ai nấy làm."},{"type":"simple","zh":"几个分公司长期各自为政导致了严重的资源浪费。","pinyin":"Jǐ gè fēngōngsī chángqī gèzìwéizhèng dǎozhìle yánzhòng de zīyuán làngfèi.","vi":"Việc mấy chi nhánh lâu nay mạnh ai nấy làm đã gây lãng phí nguồn lực nghiêm trọng."},{"type":"compound","zh":"如果各地在治水问题上各自为政，洪灾就很难得到控制。","pinyin":"Rúguǒ gèdì zài zhìshuǐ wèntí shang gèzìwéizhèng, hóngzāi jiù hěn nándé dào kòngzhì.","vi":"Nếu các địa phương mạnh ai nấy làm trong vấn đề trị thủy, lũ lụt sẽ khó được kiểm soát."}],"related":[{"hanzi":"各行其是","pinyin":"gèxíngqíshì","vi":"ai làm việc nấy"},{"hanzi":"团结协作","pinyin":"tuánjiéxiézuò","vi":"đoàn kết hợp tác"},{"hanzi":"一盘散沙","pinyin":"yìpánsǎnshā","vi":"rời rạc như cát"}],"traditional":"各自為政"},{"id":"格格不入","hanzi":"格格不入","pinyin":"gégé-búrù","meaning_vi":"không hòa hợp, lạc lõng hoàn toàn","explanation":"格格不入: chẳng ăn khớp (格格) vào nhau (入) → hoàn toàn không hòa hợp, lạc lõng, xung khắc với xung quanh. Ví dụ: 与环境格格不入.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🚫","examples":[{"type":"basic","zh":"他觉得自己与周围格格不入。","pinyin":"Tā juéde zìjǐ yǔ zhōuwéi gégébúrù.","vi":"Anh ấy cảm thấy mình lạc lõng với xung quanh."},{"type":"simple","zh":"这栋现代玻璃大楼与古镇的风格显得格格不入。","pinyin":"Zhè dòng xiàndài bōli dàlóu yǔ gǔzhèn de fēnggé xiǎnde gégébúrù.","vi":"Tòa nhà kính hiện đại này trông hoàn toàn lạc lõng với phong cách của cổ trấn."},{"type":"compound","zh":"虽然她努力融入新班级，但是总觉得和同学们格格不入。","pinyin":"Suīrán tā nǔlì róngrù xīn bānjí, dànshì zǒng juéde hé tóngxuémen gégébúrù.","vi":"Tuy cô cố gắng hòa nhập lớp mới, nhưng vẫn luôn thấy lạc lõng với các bạn."}],"related":[{"hanzi":"不合群","pinyin":"bùhéqún","vi":"không hòa đồng"},{"hanzi":"水火不容","pinyin":"shuǐhuǒbùróng","vi":"như nước với lửa"},{"hanzi":"融洽","pinyin":"róngqià","vi":"hòa hợp"}]},{"id":"格调","hanzi":"格调","pinyin":"gédiào","meaning_vi":"phong cách, phẩm chất thẩm mỹ","explanation":"格 (格) + 调 (điều chỉnh/hòa giải).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"这家咖啡馆格调高雅。","pinyin":"Zhè jiā kāfēiguǎn gédiào gāoyǎ.","vi":"Quán cà phê này có phong cách tao nhã."},{"type":"simple","zh":"设计师用暖色灯光提升了整个客厅的格调。","pinyin":"Shèjìshī yòng nuǎnsè dēngguāng tíshēngle zhěnggè kètīng de gédiào.","vi":"Nhà thiết kế dùng ánh đèn tông ấm để nâng tầm phong cách của cả phòng khách."},{"type":"compound","zh":"这部小说虽然情节简单，但是格调清新，耐人寻味。","pinyin":"Zhè bù xiǎoshuō suīrán qíngjié jiǎndān, dànshì gédiào qīngxīn, nàirénxúnwèi.","vi":"Cuốn tiểu thuyết này tuy cốt truyện đơn giản nhưng phong cách trong trẻo, đáng suy ngẫm."}],"related":[{"hanzi":"风格","pinyin":"fēnggé","vi":"phong cách"},{"hanzi":"品位","pinyin":"pǐnwèi","vi":"gu thẩm mỹ"},{"hanzi":"情调","pinyin":"qíngdiào","vi":"không khí, phong vị"}],"traditional":"格調"},{"id":"共建","hanzi":"共建","pinyin":"gòngjiàn","meaning_vi":"cùng nhau xây dựng","explanation":"共 (cộng – cùng) + 建 (kiến – xây dựng) → cùng nhau xây dựng. VD: 共建美好家园, 共建一带一路.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"两国共建工业园区。","pinyin":"Liǎngguó gòngjiàn gōngyèyuánqū.","vi":"Hai nước cùng xây dựng khu công nghiệp."},{"type":"simple","zh":"学校和企业共建了一个人工智能实验室。","pinyin":"Xuéxiào hé qǐyè gòngjiànle yígèrén gōng zhìnéng shíyànshì.","vi":"Nhà trường và doanh nghiệp cùng xây dựng một phòng thí nghiệm trí tuệ nhân tạo."},{"type":"compound","zh":"只要居民们齐心协力共建家园，小区环境就会越来越好。","pinyin":"Zhǐyào jūmínmen qíxīnxiélì gòngjiàn jiāyuán, xiǎoqū huánjìng jiù huì yuèláiyuè hǎo.","vi":"Chỉ cần cư dân đồng lòng cùng xây dựng mái nhà chung, môi trường khu dân cư sẽ ngày càng tốt hơn."}],"related":[{"hanzi":"共享","pinyin":"gòngxiǎng","vi":"cùng chia sẻ"},{"hanzi":"建设","pinyin":"jiànshè","vi":"xây dựng"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"}]},{"id":"共建共享","hanzi":"共建共享","pinyin":"gòngjiàngòngxiǎng","meaning_vi":"cùng xây dựng và cùng chia sẻ","explanation":"共 (共) + 建 (建) + 共 (共) + 享 (hưởng thụ).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"城市建设要共建共享。","pinyin":"Chéngshì jiànshè yào gòngjiàngòngxiǎng.","vi":"Xây dựng đô thị cần cùng xây và cùng hưởng."},{"type":"simple","zh":"这座由居民共建共享的社区花园深受大家喜爱。","pinyin":"Zhè zuò yóu jūmín gòngjiàngòngxiǎng de shèqū huāyuán shēnshòu dàjiā xǐ'ài.","vi":"Khu vườn cộng đồng do cư dân cùng xây cùng hưởng này được mọi người rất yêu thích."},{"type":"compound","zh":"既然图书角是大家共建共享的，每个人就都应该爱护书籍。","pinyin":"Jìrán tú shūjiǎo shì dàjiā gòngjiàngòngxiǎng de, měigèrén jiù dōu yīnggāi àihù shūjí.","vi":"Đã là góc sách do mọi người cùng xây cùng hưởng thì ai cũng nên giữ gìn sách vở."}],"related":[{"hanzi":"共建","pinyin":"gòngjiàn","vi":"cùng xây dựng"},{"hanzi":"共享","pinyin":"gòngxiǎng","vi":"cùng chia sẻ"},{"hanzi":"共赢","pinyin":"gòngyíng","vi":"cùng thắng"}]},{"id":"共识","hanzi":"共识","pinyin":"gòngshí","meaning_vi":"nhận thức chung, sự đồng thuận","explanation":"共 (共) + 识 (kiến thức/nhận biết).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"双方达成了共识。","pinyin":"Shuāngfāng dáchéngle gòngshí.","vi":"Hai bên đã đạt được đồng thuận."},{"type":"simple","zh":"各方经过三轮谈判终于就价格问题形成了共识。","pinyin":"Gèfāng jīngguò sānlún tánpàn zhōngyú jiù jiàgé wèntí xíng chéngle gòngshí.","vi":"Các bên sau ba vòng đàm phán cuối cùng đã đạt đồng thuận về vấn đề giá cả."},{"type":"compound","zh":"虽然大家意见不一，但是在保护环境这一点上已有共识。","pinyin":"Suīrán dàjiā yìjiàn bù yī, dànshì zài bǎohù huánjìng zhè yìdiǎn shang yǐ yǒu gòngshí.","vi":"Tuy mọi người bất đồng ý kiến, nhưng về việc bảo vệ môi trường thì đã có nhận thức chung."}],"related":[{"hanzi":"一致","pinyin":"yízhì","vi":"nhất trí"},{"hanzi":"分歧","pinyin":"fēnqí","vi":"bất đồng"},{"hanzi":"达成共识","pinyin":"dáchénggòngshí","vi":"đạt được đồng thuận"}],"traditional":"共識"},{"id":"共同富裕","hanzi":"共同富裕","pinyin":"gòngtóngfùyù","meaning_vi":"cùng nhau giàu có thịnh vượng","explanation":"共 (共) + 同 (đồng lòng/đồng bào) + 富 (giàu) + 裕 (giàu có/dư dả).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"我们追求共同富裕。","pinyin":"Wǒmen zhuīqiú gòngtóngfùyù.","vi":"Chúng ta theo đuổi sự cùng giàu có."},{"type":"simple","zh":"这个村通过发展乡村旅游走上了共同富裕之路。","pinyin":"Zhè ge cūn tōngguò fāzhǎn xiāngcūnlǚyóu zǒushàngle gòngtóngfùyù zhī lù.","vi":"Ngôi làng này nhờ phát triển du lịch nông thôn mà bước lên con đường cùng giàu có."},{"type":"compound","zh":"只有缩小城乡收入差距，才能真正实现共同富裕。","pinyin":"Zhǐyǒu suōxiǎo chéngxiāng shōurù chājù, cáinéng zhēnzhèng shíxiàn gòngtóngfùyù.","vi":"Chỉ có thu hẹp chênh lệch thu nhập giữa thành thị và nông thôn mới thực sự đạt được cùng giàu có."}],"related":[{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"},{"hanzi":"小康","pinyin":"xiǎokāng","vi":"khá giả"},{"hanzi":"贫富差距","pinyin":"pínfùchājù","vi":"chênh lệch giàu nghèo"}]},{"id":"固定资产","hanzi":"固定资产","pinyin":"gùdìngzīchǎn","meaning_vi":"tài sản cố định","explanation":"固 (kiên cố/vốn có) + 定 (定) + 资 (tài nguyên/tư bản) + 产 (产).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"公司固定资产增加了。","pinyin":"Gōngsī gùdìngzīchǎn zēngjiā le.","vi":"Tài sản cố định của công ty đã tăng."},{"type":"simple","zh":"会计每年都要对厂房和设备等固定资产计提折旧。","pinyin":"Kuàijì měinián dōu yào duì chǎngfáng hé shèbèi děng gùdìngzīchǎn jìtí zhéjiù.","vi":"Kế toán mỗi năm đều phải trích khấu hao tài sản cố định như nhà xưởng, thiết bị."},{"type":"compound","zh":"虽然这家工厂固定资产雄厚，但是流动资金十分紧张。","pinyin":"Suīrán zhè jiā gōngchǎng gùdìngzīchǎn xiónghòu, dànshì liúdòng zījīn shífēn jǐnzhāng.","vi":"Tuy nhà máy này có tài sản cố định hùng hậu, nhưng vốn lưu động rất eo hẹp."}],"related":[{"hanzi":"资产","pinyin":"zīchǎn","vi":"tài sản"},{"hanzi":"流动资产","pinyin":"liúdòngzīchǎn","vi":"tài sản lưu động"},{"hanzi":"不动产","pinyin":"búdòngchǎn","vi":"bất động sản"}],"traditional":"固定資產"},{"id":"故宫博物院","hanzi":"故宫博物院","pinyin":"Gùgōng Bówùyuàn","meaning_vi":"Bảo tàng Cố Cung (Tử Cấm Thành Bắc Kinh)","explanation":"故宫 (Cố Cung – cung điện cũ, tức Tử Cấm Thành) + 博物院 (bác vật viện – viện bảo tàng) → Bảo tàng Cố Cung tại Bắc Kinh.","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏯","examples":[{"type":"basic","zh":"我们去了故宫博物院。","pinyin":"Wǒmen qùle Gùgōngbówùyuàn.","vi":"Chúng tôi đã đến Bảo tàng Cố Cung."},{"type":"simple","zh":"故宫博物院每天限量接待四万名游客。","pinyin":"Gùgōngbówùyuàn měitiān xiànliàng jiēdài sì wànmíng yóukè.","vi":"Bảo tàng Cố Cung mỗi ngày chỉ tiếp đón giới hạn bốn vạn du khách."},{"type":"compound","zh":"如果想参观故宫博物院，就最好提前在网上预约门票。","pinyin":"Rúguǒ xiǎng cānguān Gùgōngbówùyuàn, jiù zuìhǎo tíqián zài wǎngshàng yùyuē ménpiào.","vi":"Nếu muốn tham quan Bảo tàng Cố Cung thì tốt nhất nên đặt vé trước trên mạng."}],"related":[{"hanzi":"故宫","pinyin":"gùgōng","vi":"Cố Cung"},{"hanzi":"紫禁城","pinyin":"Zǐjìnchéng","vi":"Tử Cấm Thành"},{"hanzi":"博物馆","pinyin":"bówùguǎn","vi":"bảo tàng"}],"traditional":"故宮博物院"},{"id":"故居","hanzi":"故居","pinyin":"gùjū","meaning_vi":"nhà cũ của danh nhân","explanation":"故 (故) + 居 (cư trú).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏡","examples":[{"type":"basic","zh":"这里是鲁迅故居。","pinyin":"Zhèlǐ shì Lǔxùn gùjū.","vi":"Đây là nhà cũ của Lỗ Tấn."},{"type":"simple","zh":"暑假我们去广东参观了孙中山故居。","pinyin":"Shǔjià wǒmen qù Guǎngdōng cānguānle Sūnzhōngshān gùjū.","vi":"Kỳ nghỉ hè chúng tôi đến Quảng Đông thăm nhà cũ của Tôn Trung Sơn."},{"type":"compound","zh":"这座故居虽然面积不大，但是完整保留了主人生前的书房。","pinyin":"Zhè zuò gùjū suīrán miànjī búdà, dànshì wánzhěng bǎoliúle zhǔrén shēngqián de shūfáng.","vi":"Ngôi nhà cũ này tuy diện tích không lớn, nhưng giữ nguyên vẹn thư phòng của chủ nhân khi còn sống."}],"related":[{"hanzi":"旧居","pinyin":"jiùjū","vi":"nhà cũ"},{"hanzi":"名人","pinyin":"míngrén","vi":"danh nhân"},{"hanzi":"纪念馆","pinyin":"jìniànguǎn","vi":"nhà tưởng niệm"}]},{"id":"故人","hanzi":"故人","pinyin":"gùrén","meaning_vi":"người bạn cũ","explanation":"故 (cố – cũ) + 人 (nhân – người) → người quen cũ, bạn cũ; văn viết. Câu thơ quen thuộc: 西出阳关无故人.","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"🫂","examples":[{"type":"basic","zh":"他乡遇故人。","pinyin":"Tāxiāng yù gùrén.","vi":"Gặp bạn cũ nơi đất khách."},{"type":"simple","zh":"多年后他在火车站意外碰到了一位故人。","pinyin":"Duōnián hòu tā zài huǒchēzhàn yìwài pèngdàole yí wèi gùrén.","vi":"Nhiều năm sau anh tình cờ gặp lại một người bạn cũ ở ga tàu."},{"type":"compound","zh":"每当读到这封旧信，我就会想起远方的故人。","pinyin":"Měidāng dú dào zhè fēng jiù xìn, wǒ jiù huì xiǎngqǐ yuǎnfāng de gùrén.","vi":"Mỗi khi đọc lá thư cũ này, tôi lại nhớ đến người bạn cũ phương xa."}],"related":[{"hanzi":"老朋友","pinyin":"lǎopéngyou","vi":"bạn cũ"},{"hanzi":"故友","pinyin":"gùyǒu","vi":"bạn xưa"},{"hanzi":"新朋友","pinyin":"xīnpéngyou","vi":"bạn mới"}]},{"id":"干线","hanzi":"干线","pinyin":"gànxiàn","meaning_vi":"tuyến đường chính, trục giao thông chính","explanation":"干 (干) + 线 (manh mối/đường nét).","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"这是一条铁路干线。","pinyin":"Zhè shì yì tiáo tiělù gànxiàn.","vi":"Đây là một tuyến đường sắt chính."},{"type":"simple","zh":"这条高速公路是连接南北的交通干线。","pinyin":"Zhè tiáo gāosùgōnglù shì liánjiē nánběi de jiāotōng gànxiàn.","vi":"Đường cao tốc này là trục giao thông chính nối Bắc Nam."},{"type":"compound","zh":"一旦这条干线发生拥堵，周边的小路就会挤满车辆。","pinyin":"Yídàn zhè tiáo gànxiàn fāshēng yōngdǔ, zhōubiān de xiǎolù jiù huì jǐmǎn chēliàng.","vi":"Một khi tuyến đường chính này ùn tắc, các đường nhỏ xung quanh sẽ chật kín xe."}],"related":[{"hanzi":"支线","pinyin":"zhīxiàn","vi":"tuyến nhánh"},{"hanzi":"主干道","pinyin":"zhǔgàndào","vi":"đường trục chính"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"giao thông"}],"traditional":"幹線"},{"id":"刚柔并济","hanzi":"刚柔并济","pinyin":"gāngróu-bìngjì","meaning_vi":"cương nhu kết hợp hài hòa","explanation":"刚 (刚) + 柔 (dịu dàng/mềm mại) + 并 (并) + 济 (济).","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"☯️","examples":[{"type":"basic","zh":"他的管理方式刚柔并济。","pinyin":"Tā de guǎnlǐ fāngshì gāngróubìngjì.","vi":"Cách quản lý của anh ấy cương nhu kết hợp."},{"type":"simple","zh":"太极拳的动作讲究刚柔并济、动静结合。","pinyin":"Tàijíquán de dòngzuò jiǎngjiu gāngróubìngjì, dòngjìng jiéhé.","vi":"Động tác Thái cực quyền chú trọng cương nhu kết hợp, động tĩnh hòa quyện."},{"type":"compound","zh":"父母教育孩子如果能刚柔并济，孩子就更容易接受。","pinyin":"Fùmǔ jiàoyù háizi rúguǒ néng gāngróubìngjì, háizi jiù gèng róngyì jiēshòu.","vi":"Cha mẹ dạy con nếu biết cương nhu kết hợp thì con sẽ dễ tiếp nhận hơn."}],"related":[{"hanzi":"刚柔相济","pinyin":"gāngróuxiāngjì","vi":"cương nhu kết hợp"},{"hanzi":"软硬兼施","pinyin":"ruǎnyìngjiānshī","vi":"vừa đấm vừa xoa"},{"hanzi":"刚强","pinyin":"gāngqiáng","vi":"cứng rắn"}],"traditional":"剛柔並濟"},{"id":"高等教育","hanzi":"高等教育","pinyin":"gāoděngjiàoyù","meaning_vi":"giáo dục đại học","explanation":"高 (cao) + 等 (đợi) + 教 (dạy) + 育 (giáo dục/nuôi dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"她接受过高等教育。","pinyin":"Tā jiē shòuguo gāoděngjiàoyù.","vi":"Cô ấy đã được học đại học."},{"type":"simple","zh":"近年来越来越多的农村孩子获得了接受高等教育的机会。","pinyin":"Jìnniánlái yuèláiyuè duō de nóngcūn háizi huòdéle jiēshòu gāoděngjiàoyù de jīhuì.","vi":"Những năm gần đây ngày càng nhiều trẻ em nông thôn có cơ hội học đại học."},{"type":"compound","zh":"高等教育不但培养专业人才，而且推动科学研究的发展。","pinyin":"Gāoděngjiàoyù búdàn péiyǎng zhuānyè réncái, érqiě tuīdòng kēxué yánjiū de fāzhǎn.","vi":"Giáo dục đại học không những đào tạo nhân tài chuyên môn mà còn thúc đẩy nghiên cứu khoa học phát triển."}],"related":[{"hanzi":"大学","pinyin":"dàxué","vi":"đại học"},{"hanzi":"义务教育","pinyin":"yìwùjiàoyù","vi":"giáo dục bắt buộc"},{"hanzi":"研究生","pinyin":"yánjiūshēng","vi":"nghiên cứu sinh"}]},{"id":"高收入","hanzi":"高收入","pinyin":"gāoshōurù","meaning_vi":"thu nhập cao","explanation":"高 (cao) + 收 (nhận) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["tinh-tu","tien-te","xa-hoi"],"image":"💰","examples":[{"type":"basic","zh":"律师属于高收入职业。","pinyin":"Lǜshī shǔyú gāoshōurù zhíyè.","vi":"Luật sư thuộc nghề có thu nhập cao."},{"type":"simple","zh":"新的税收政策对高收入群体适当提高了税率。","pinyin":"Xīn de shuìshōu zhèngcè duì gāoshōurù qúntǐ shìdàng tígāole shuìlǜ.","vi":"Chính sách thuế mới đã nâng thuế suất một cách hợp lý đối với nhóm thu nhập cao."},{"type":"compound","zh":"虽然这份工作属于高收入岗位，但是经常需要加班到深夜。","pinyin":"Suīrán zhè fèn gōngzuò shǔyú gāoshōurù gǎngwèi, dànshì jīngcháng xūyào jiābān dào shēnyè.","vi":"Tuy công việc này thuộc vị trí thu nhập cao, nhưng thường xuyên phải tăng ca đến khuya."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"低收入","pinyin":"dīshōurù","vi":"thu nhập thấp"},{"hanzi":"中等收入","pinyin":"zhōngděngshōurù","vi":"thu nhập trung bình"}]},{"id":"高速铁路","hanzi":"高速铁路","pinyin":"gāosùtiělù","meaning_vi":"đường sắt cao tốc","explanation":"高速 (cao tốc) + 铁路 (thiết lộ – đường sắt) → đường sắt cao tốc; gọi tắt 高铁.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚄","examples":[{"type":"basic","zh":"高速铁路通到了我的家乡。","pinyin":"Gāosùtiělù tōng dàole wǒ de jiāxiāng.","vi":"Đường sắt cao tốc đã chạy đến quê tôi."},{"type":"simple","zh":"这条高速铁路把两地的行程缩短到了两小时。","pinyin":"Zhè tiáo gāosùtiělù bǎ liǎng dì de xíngchéng suōduǎn dàole liǎng xiǎoshí.","vi":"Tuyến đường sắt cao tốc này rút ngắn hành trình giữa hai nơi xuống còn hai tiếng."},{"type":"compound","zh":"自从开通了高速铁路，周末去邻省旅游的人就多了起来。","pinyin":"Zìcóng kāitōngle gāosùtiělù, zhōumò qù lín shěng lǚyóu de rén jiù duōle qǐlái.","vi":"Từ khi đường sắt cao tốc khai thông, người đi du lịch tỉnh lân cận cuối tuần đông hẳn lên."}],"related":[{"hanzi":"高铁","pinyin":"gāotiě","vi":"tàu cao tốc"},{"hanzi":"动车","pinyin":"dòngchē","vi":"tàu điện cao tốc"},{"hanzi":"火车站","pinyin":"huǒchēzhàn","vi":"ga tàu"}],"traditional":"高速鐵路"},{"id":"高血压","hanzi":"高血压","pinyin":"gāoxuèyā","meaning_vi":"cao huyết áp","explanation":"高 (cao) + 血 (máu/tâm huyết) + 压 (áp lực/áp bức).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"爷爷患有高血压。","pinyin":"Yéye huànyǒu gāoxuèyā.","vi":"Ông nội bị cao huyết áp."},{"type":"simple","zh":"医生建议高血压患者每天减少食盐的摄入量。","pinyin":"Yīshēng jiànyì gāoxuèyā huànzhě měitiān jiǎnshǎo shíyán de shèrùliàng.","vi":"Bác sĩ khuyên người cao huyết áp mỗi ngày giảm lượng muối ăn vào."},{"type":"compound","zh":"高血压一旦得不到控制，就可能引发心脏病和中风。","pinyin":"Gāoxuèyā yídàn débúdào kòngzhì, jiù kěnéng yǐnfā xīnzàngbìng hé zhòngfēng.","vi":"Cao huyết áp một khi không được kiểm soát có thể gây bệnh tim và đột quỵ."}],"related":[{"hanzi":"血压","pinyin":"xuèyā","vi":"huyết áp"},{"hanzi":"低血压","pinyin":"dīxuèyā","vi":"huyết áp thấp"},{"hanzi":"糖尿病","pinyin":"tángniàobìng","vi":"bệnh tiểu đường"}],"traditional":"高血壓"},{"id":"高新技术","hanzi":"高新技术","pinyin":"gāoxīnjìshù","meaning_vi":"công nghệ cao và mới","explanation":"高 (cao) + 新 (mới) + 技 (kỹ thuật) + 术 (术).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","khoa-hoc"],"image":"🚀","examples":[{"type":"basic","zh":"这里聚集了高新技术企业。","pinyin":"Zhèlǐ jùjíle gāoxīnjìshù qǐyè.","vi":"Nơi đây tập trung các doanh nghiệp công nghệ cao."},{"type":"simple","zh":"政府为高新技术企业提供了税收优惠。","pinyin":"Zhèngfǔ wèi gāoxīnjìshù qǐyè tígōngle shuìshōu yōuhuì.","vi":"Chính phủ dành ưu đãi thuế cho các doanh nghiệp công nghệ cao."},{"type":"compound","zh":"如果没有高新技术的支撑，传统制造业就难以转型升级。","pinyin":"Rúguǒ méiyǒu gāoxīnjìshù de zhīchēng, chuántǒng zhìzàoyè jiù nányǐ zhuǎnxíngshēngjí.","vi":"Nếu không có công nghệ cao hỗ trợ, ngành chế tạo truyền thống khó chuyển đổi nâng cấp."}],"related":[{"hanzi":"高科技","pinyin":"gāokējì","vi":"công nghệ cao"},{"hanzi":"新技术","pinyin":"xīnjìshù","vi":"công nghệ mới"},{"hanzi":"科技园","pinyin":"kējìyuán","vi":"khu công nghệ"}],"traditional":"高新技術"},{"id":"高雅","hanzi":"高雅","pinyin":"gāoyǎ","meaning_vi":"cao nhã, tao nhã","explanation":"高 (cao) + 雅 (tao nhã/văn nhã).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🎻","examples":[{"type":"basic","zh":"她的谈吐很高雅。","pinyin":"Tā de tántǔ hěn gāoyǎ.","vi":"Cách ăn nói của cô ấy rất tao nhã."},{"type":"simple","zh":"学校邀请交响乐团进校园普及高雅艺术。","pinyin":"Xuéxiào yāoqǐng jiāoxiǎngyuètuán jìn xiàoyuán pǔjí gāoyǎ yìshù.","vi":"Trường mời dàn nhạc giao hưởng đến phổ biến nghệ thuật cao nhã trong khuôn viên."},{"type":"compound","zh":"这家餐厅既装修得高雅，又价格合理。","pinyin":"Zhè jiā cāntīng jì zhuāngxiū de gāoyǎ, yòu jiàgé hélǐ.","vi":"Nhà hàng này vừa trang trí thanh lịch, vừa giá cả hợp lý."}],"related":[{"hanzi":"优雅","pinyin":"yōuyǎ","vi":"thanh lịch"},{"hanzi":"典雅","pinyin":"diǎnyǎ","vi":"trang nhã"},{"hanzi":"庸俗","pinyin":"yōngsú","vi":"tầm thường"}]},{"id":"歌剧","hanzi":"歌剧","pinyin":"gējù","meaning_vi":"nhạc kịch (opera)","explanation":"歌 (bài hát) + 剧 (kịch/dữ dội).","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"他们去看了一场歌剧。","pinyin":"Tāmen qù kànle yì chǎng gējù.","vi":"Họ đi xem một vở nhạc kịch."},{"type":"simple","zh":"这部意大利歌剧在国家大剧院连演了五场。","pinyin":"Zhè bù Yìdàlì gējù zài guójiā dà jùyuàn lián yǎnle wǔ chǎng.","vi":"Vở opera Ý này được diễn liên tục năm suất tại Nhà hát Lớn Quốc gia."},{"type":"compound","zh":"虽然我听不懂意大利语，但是歌剧演员的歌声深深打动了我。","pinyin":"Suīrán wǒ tīngbùdǒng Yìdàlìyǔ, dànshì gējù yǎnyuán de gēshēng shēnshēn dǎdòngle wǒ.","vi":"Tuy tôi không hiểu tiếng Ý, nhưng giọng hát của diễn viên opera đã làm tôi xúc động sâu sắc."}],"related":[{"hanzi":"歌剧院","pinyin":"gējùyuàn","vi":"nhà hát opera"},{"hanzi":"话剧","pinyin":"huàjù","vi":"kịch nói"},{"hanzi":"京剧","pinyin":"Jīngjù","vi":"Kinh kịch"}],"traditional":"歌劇"},{"id":"根治","hanzi":"根治","pinyin":"gēnzhì","meaning_vi":"chữa trị tận gốc","explanation":"根 (rễ cây) + 治 (quản lý/điều trị).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"这种病很难根治。","pinyin":"Zhè zhǒng bìng hěn nán gēnzhì.","vi":"Bệnh này rất khó chữa dứt điểm."},{"type":"simple","zh":"当地政府花了十年时间根治了这条河的污染。","pinyin":"Dāngdì zhèngfǔ huāle shí nián shíjiān gēnzhìle zhè tiáo hé de wūrǎn.","vi":"Chính quyền địa phương mất mười năm để xử lý tận gốc ô nhiễm con sông này."},{"type":"compound","zh":"如果不改变饮食习惯，胃病就很难根治。","pinyin":"Rúguǒ bù gǎibiàn yǐnshí xíguàn, wèibìng jiù hěn nán gēnzhì.","vi":"Nếu không thay đổi thói quen ăn uống thì bệnh dạ dày rất khó chữa tận gốc."}],"related":[{"hanzi":"治疗","pinyin":"zhìliáo","vi":"điều trị"},{"hanzi":"治本","pinyin":"zhìběn","vi":"trị tận gốc"},{"hanzi":"根除","pinyin":"gēnchú","vi":"diệt tận gốc"}]},{"id":"公德","hanzi":"公德","pinyin":"gōngdé","meaning_vi":"đạo đức công cộng","explanation":"公 (công – chung) + 德 (đức – đạo đức) → đạo đức nơi công cộng, ý thức chung. VD: 遵守社会公德, 没有公德心.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"乱扔垃圾不讲公德。","pinyin":"Luànrēng lājī bù jiǎng gōngdé.","vi":"Vứt rác bừa bãi là thiếu đạo đức công cộng."},{"type":"simple","zh":"在地铁里大声外放视频是缺乏公德的表现。","pinyin":"Zài dìtiě lǐ dàshēng wàifàng shìpín shì quēfá gōngdé de biǎoxiàn.","vi":"Mở to video trên tàu điện ngầm là biểu hiện thiếu ý thức công cộng."},{"type":"compound","zh":"只要每个人都遵守社会公德，城市就会更加文明。","pinyin":"Zhǐyào měigèrén dōu zūnshǒu shèhuì gōngdé, chéngshì jiù huì gèngjiā wénmíng.","vi":"Chỉ cần mỗi người đều tuân thủ đạo đức xã hội, thành phố sẽ văn minh hơn."}],"related":[{"hanzi":"公德心","pinyin":"gōngdéxīn","vi":"ý thức công cộng"},{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"社会公德","pinyin":"shèhuìgōngdé","vi":"đạo đức xã hội"}]},{"id":"工匠精神","hanzi":"工匠精神","pinyin":"gōngjiàngjīngshén","meaning_vi":"tinh thần nghệ nhân (tỉ mỉ, tận tâm hoàn thiện sản phẩm)","explanation":"工 (工) + 匠 (匠) + 精 (tinh hoa/tinh xảo) + 神 (thần kỳ/tinh thần).","hsk_level":"7-9","tags":["danh-tu","van-hoa","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"这把刀体现了工匠精神。","pinyin":"Zhè bǎ dāo tǐxiànle gōngjiàngjīngshén.","vi":"Con dao này thể hiện tinh thần nghệ nhân."},{"type":"simple","zh":"老木匠花三个月打磨一张椅子的故事诠释了工匠精神。","pinyin":"Lǎo mùjiàng huā sān gèyuè dǎmó yì zhāng yǐzi de gùshi quánshìle gōngjiàngjīngshén.","vi":"Câu chuyện người thợ mộc già mất ba tháng mài giũa một chiếc ghế đã minh chứng cho tinh thần nghệ nhân."},{"type":"compound","zh":"正因为具备工匠精神，这家小店的手工皮鞋才能畅销百年。","pinyin":"Zhèng yīnwèi jùbèi gōngjiàngjīngshén, zhè jiā xiǎodiàn de shǒugōng píxié cáinéng chàngxiāo bǎinián.","vi":"Chính nhờ có tinh thần nghệ nhân mà giày da thủ công của tiệm nhỏ này bán chạy suốt trăm năm."}],"related":[{"hanzi":"工匠","pinyin":"gōngjiàng","vi":"thợ thủ công"},{"hanzi":"精益求精","pinyin":"jīngyìqiújīng","vi":"tinh lại càng tinh"},{"hanzi":"敬业","pinyin":"jìngyè","vi":"tận tụy với nghề"}]},{"id":"攻坚克难","hanzi":"攻坚克难","pinyin":"gōngjiān-kènán","meaning_vi":"vượt qua mọi khó khăn thử thách","explanation":"攻 (攻) + 坚 (kiên định/vững chắc) + 克 (gam (đơn vị khối lượng)) + 难 (khó).","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"🏔️","examples":[{"type":"basic","zh":"团队正在攻坚克难。","pinyin":"Tuánduì zhèngzài gōngjiānkènán.","vi":"Đội ngũ đang dốc sức vượt khó."},{"type":"simple","zh":"科研人员经过数月攻坚克难终于突破了芯片技术。","pinyin":"Kēyán rényuán jīngguò shùyuè gōngjiānkènán zhōngyú tūpòle xīnpiàn jìshù.","vi":"Các nhà nghiên cứu sau nhiều tháng vượt khó cuối cùng đã đột phá công nghệ chip."},{"type":"compound","zh":"只要全体工人团结一心、攻坚克难，大桥就能如期竣工。","pinyin":"Zhǐyào quántǐ gōngrén tuánjié yìxīn, gōngjiānkènán, Dàqiáo jiù néng rúqī jùngōng.","vi":"Chỉ cần toàn thể công nhân đồng lòng, vượt mọi khó khăn, cây cầu sẽ hoàn thành đúng hạn."}],"related":[{"hanzi":"攻坚","pinyin":"gōngjiān","vi":"tấn công khó khăn"},{"hanzi":"克服困难","pinyin":"kèfúkùnnan","vi":"khắc phục khó khăn"},{"hanzi":"迎难而上","pinyin":"yíngnán'érshàng","vi":"đối mặt khó khăn"}],"traditional":"攻堅克難"},{"id":"公积金","hanzi":"公积金","pinyin":"gōngjījīn","meaning_vi":"quỹ tiết kiệm nhà ở / quỹ dự phòng","explanation":"公积 (công tích – tích lũy chung) + 金 (kim – tiền) → quỹ tích lũy; thường chỉ 住房公积金 – quỹ nhà ở do người lao động và đơn vị cùng đóng.","hsk_level":"7-9","tags":["danh-tu","tien-te","nha-cua"],"image":"🏦","examples":[{"type":"basic","zh":"他用公积金贷款买房。","pinyin":"Tāyòng gōngjījīn dàikuǎn mǎifáng.","vi":"Anh ấy vay từ quỹ tiết kiệm nhà ở để mua nhà."},{"type":"simple","zh":"公司每个月按工资的百分之十二为员工缴纳公积金。","pinyin":"Gōngsī měi gèyuè àn gōngzī de bǎifēnzhī shí'èr wèi yuángōng jiǎonà gōngjījīn.","vi":"Mỗi tháng công ty đóng quỹ nhà ở cho nhân viên bằng 12% tiền lương."},{"type":"compound","zh":"如果你在本市连续缴存公积金满一年，就可以申请低息房贷。","pinyin":"Rúguǒ nǐ zài běnshì liánxù jiǎo cún gōngjījīn mǎn yì nián, jiù kěyǐ shēnqǐng dīxī fángdài.","vi":"Nếu bạn đóng quỹ nhà ở liên tục đủ một năm tại thành phố này thì có thể xin vay mua nhà lãi suất thấp."}],"related":[{"hanzi":"住房公积金","pinyin":"zhùfáng gōngjījīn","vi":"quỹ nhà ở"},{"hanzi":"社保","pinyin":"shèbǎo","vi":"bảo hiểm xã hội"},{"hanzi":"养老金","pinyin":"yǎnglǎojīn","vi":"lương hưu"}],"traditional":"公積金"},{"id":"公开化","hanzi":"公开化","pinyin":"gōngkāihuà","meaning_vi":"công khai hóa","explanation":"公开 (công khai) + 化 (hóa – làm cho) → công khai hóa, đưa ra cho mọi người biết. VD: 矛盾公开化.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🔓","examples":[{"type":"basic","zh":"矛盾已经公开化了。","pinyin":"Máodùn yǐjīng gōngkāihuà le.","vi":"Mâu thuẫn đã bị công khai hóa rồi."},{"type":"simple","zh":"新规定要求政府采购信息全面公开化。","pinyin":"Xīn guīdìng yāoqiú zhèngfǔ cǎigòu xìnxī quánmiàn gōngkāihuà.","vi":"Quy định mới yêu cầu công khai hóa toàn diện thông tin mua sắm của chính phủ."},{"type":"compound","zh":"两位合伙人的分歧一旦公开化，公司股价就应声下跌。","pinyin":"Liǎng wèi héhuǒrén de fēnqí yídàn gōngkāihuà, gōngsī gǔjià jiù yìngshēng xiàdiē.","vi":"Bất đồng giữa hai người cộng sự một khi bị công khai, giá cổ phiếu công ty liền sụt giảm theo."}],"related":[{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"透明","pinyin":"tòumíng","vi":"minh bạch"},{"hanzi":"保密","pinyin":"bǎomì","vi":"bảo mật"}],"traditional":"公開化"},{"id":"供暖","hanzi":"供暖","pinyin":"gōngnuǎn","meaning_vi":"cung cấp hệ thống sưởi (mùa đông miền Bắc TQ)","explanation":"供 (cung – cung cấp) + 暖 (noãn – ấm) → cung cấp sưởi ấm tập trung mùa đông (miền Bắc TQ). VD: 供暖季, 集中供暖.","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🔥","examples":[{"type":"basic","zh":"北京十一月开始供暖。","pinyin":"Běijīng Shíyīyuè kāishǐ gōngnuǎn.","vi":"Bắc Kinh bắt đầu cấp sưởi từ tháng mười một."},{"type":"simple","zh":"管道故障导致这栋楼昨晚停止供暖。","pinyin":"Guǎndào gùzhàng dǎozhì zhè dòng lóu zuówǎn tíngzhǐ gōngnuǎn.","vi":"Sự cố đường ống khiến tòa nhà này ngừng cấp sưởi tối qua."},{"type":"compound","zh":"虽然外面零下十度，但是屋里集中供暖，暖和得像春天。","pinyin":"Suīrán wàimiàn língxià shí dù, dànshì wū lǐ jízhōng gōngnuǎn, nuǎnhuo de xiàng chūntiān.","vi":"Tuy ngoài trời âm mười độ, nhưng trong nhà có sưởi tập trung nên ấm như mùa xuân."}],"related":[{"hanzi":"暖气","pinyin":"nuǎnqì","vi":"hệ thống sưởi"},{"hanzi":"取暖","pinyin":"qǔnuǎn","vi":"sưởi ấm"},{"hanzi":"供电","pinyin":"gōngdiàn","vi":"cung cấp điện"}]},{"id":"公仆","hanzi":"公仆","pinyin":"gōngpú","meaning_vi":"công bộc của nhân dân","explanation":"公 (公) + 仆 (người phục vụ/công bộc).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"🙇","examples":[{"type":"basic","zh":"官员是人民的公仆。","pinyin":"Guānyuán shì rénmín de gōngpú.","vi":"Quan chức là công bộc của nhân dân."},{"type":"simple","zh":"清廉的老县长被百姓亲切地称为好公仆。","pinyin":"Qīnglián de lǎo xiànzhǎng bèi bǎixìng qīnqiè de chēngwéi hǎo gōngpú.","vi":"Vị huyện trưởng già liêm khiết được dân thân mật gọi là người công bộc tốt."},{"type":"compound","zh":"既然是人民的公仆，就应该把群众的困难放在心上。","pinyin":"Jìrán shì rénmín de gōngpú, jiù yīnggāi bǎ qúnzhòng de kùnnan fàng zài xīn shang.","vi":"Đã là công bộc của nhân dân thì phải đặt khó khăn của quần chúng trong lòng."}],"related":[{"hanzi":"人民公仆","pinyin":"rénmíngōngpú","vi":"công bộc nhân dân"},{"hanzi":"官员","pinyin":"guānyuán","vi":"quan chức"},{"hanzi":"为人民服务","pinyin":"wèirén mín fúwù","vi":"phục vụ nhân dân"}],"traditional":"公僕"},{"id":"供求关系","hanzi":"供求关系","pinyin":"gōngqiúguānxì","meaning_vi":"quan hệ cung cầu","explanation":"供求 (cung cầu) + 关系 (quan hệ) → quan hệ cung cầu trên thị trường. VD: 供求关系决定价格.","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"⚖️","examples":[{"type":"basic","zh":"价格受供求关系影响。","pinyin":"Jiàgé shòu gōngqiúguānxì yǐngxiǎng.","vi":"Giá cả chịu ảnh hưởng của quan hệ cung cầu."},{"type":"simple","zh":"春节前猪肉的供求关系变得十分紧张。","pinyin":"Chūnjié qián zhūròu de gōngqiúguānxì biànde shífēn jǐnzhāng.","vi":"Trước Tết quan hệ cung cầu thịt lợn trở nên rất căng thẳng."},{"type":"compound","zh":"一旦市场供求关系失衡，房价就可能出现大幅波动。","pinyin":"Yídàn shìchǎng gōngqiúguānxì shīhéng, fángjià jiù kěnéng chūxiàn dàfú bōdòng.","vi":"Một khi quan hệ cung cầu thị trường mất cân bằng, giá nhà có thể biến động mạnh."}],"related":[{"hanzi":"供应","pinyin":"gōngyìng","vi":"cung ứng"},{"hanzi":"需求","pinyin":"xūqiú","vi":"nhu cầu"},{"hanzi":"供不应求","pinyin":"gōngbúyìngqiú","vi":"cung không đủ cầu"}],"traditional":"供求關係"},{"id":"工商界","hanzi":"工商界","pinyin":"gōngshāngjiè","meaning_vi":"giới công thương","explanation":"工 (工) + 商 (thương mại/bàn bạc) + 界 (ranh giới/giới hạn).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"💼","examples":[{"type":"basic","zh":"他在工商界很有名。","pinyin":"Tā zài gōngshāngjiè hěn yǒumíng.","vi":"Ông ấy rất nổi tiếng trong giới công thương."},{"type":"simple","zh":"市长邀请工商界代表座谈营商环境问题。","pinyin":"Shìzhǎng yāoqǐng gōngshāngjiè dàibiǎo zuòtán yíngshānghuánjìng wèntí.","vi":"Thị trưởng mời đại diện giới công thương tọa đàm về môi trường kinh doanh."},{"type":"compound","zh":"这项减税政策一出台，就受到了工商界的普遍欢迎。","pinyin":"Zhè xiàng jiǎnshuì zhèngcè yì chūtái, jiù shòudàole gōngshāngjiè de pǔbiàn huānyíng.","vi":"Chính sách giảm thuế này vừa ban hành đã được giới công thương hoan nghênh rộng rãi."}],"related":[{"hanzi":"商界","pinyin":"shāngjiè","vi":"giới kinh doanh"},{"hanzi":"企业家","pinyin":"qǐyèjiā","vi":"doanh nhân"},{"hanzi":"工商业","pinyin":"gōngshāngyè","vi":"công thương nghiệp"}]},{"id":"公信力","hanzi":"公信力","pinyin":"gōngxìnlì","meaning_vi":"uy tín và niềm tin của công chúng","explanation":"公 (公) + 信 (niềm tin/uy tín) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"媒体需要公信力。","pinyin":"Méitǐ xūyào gōngxìnlì.","vi":"Truyền thông cần có uy tín với công chúng."},{"type":"simple","zh":"这起数据造假事件严重损害了机构的公信力。","pinyin":"Zhè qǐ shùjù zàojiǎ shìjiàn yánzhòng sǔnhàile jīgòu de gōngxìnlì.","vi":"Vụ làm giả số liệu này đã làm tổn hại nghiêm trọng uy tín của cơ quan."},{"type":"compound","zh":"如果政府能及时公开真相，就能赢得更高的公信力。","pinyin":"Rúguǒ zhèngfǔ néng jíshí gōngkāi zhēnxiàng, jiù néng yíngdé gèng gāo de gōngxìnlì.","vi":"Nếu chính phủ kịp thời công bố sự thật thì sẽ giành được lòng tin công chúng cao hơn."}],"related":[{"hanzi":"信誉","pinyin":"xìnyù","vi":"uy tín"},{"hanzi":"权威","pinyin":"quánwēi","vi":"uy quyền"},{"hanzi":"可信度","pinyin":"kěxìndù","vi":"độ tin cậy"}]},{"id":"工业国","hanzi":"工业国","pinyin":"Gōngyèguó","meaning_vi":"nước công nghiệp","explanation":"工 (工) + 业 (sự nghiệp/ngành nghề) + 国 (nước).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-danh"],"image":"🏭","examples":[{"type":"basic","zh":"德国是传统工业国。","pinyin":"Dé guóshì chuántǒng Gōngyèguó.","vi":"Đức là một nước công nghiệp truyền thống."},{"type":"simple","zh":"这个国家用了三十年时间从农业国变成了工业国。","pinyin":"Zhè ge guó jiāyòngle sānshí nián shíjiān cóng Nóngyèguó biàn chéngle Gōngyèguó.","vi":"Đất nước này mất ba mươi năm để từ nước nông nghiệp trở thành nước công nghiệp."},{"type":"compound","zh":"虽然它已经成为工业国，但是环境污染问题也随之而来。","pinyin":"Suīrán tā yǐjīng chéngwéi Gōngyèguó, dànshì huánjìng wūrǎn wèntí yě suízhī ér lái.","vi":"Tuy đã trở thành nước công nghiệp, nhưng vấn đề ô nhiễm môi trường cũng theo đó mà đến."}],"related":[{"hanzi":"工业化","pinyin":"gōngyèhuà","vi":"công nghiệp hóa"},{"hanzi":"发达国家","pinyin":"fādáguójiā","vi":"nước phát triển"},{"hanzi":"农业国","pinyin":"Nóngyèguó","vi":"nước nông nghiệp"}],"traditional":"工業國"},{"id":"工业化","hanzi":"工业化","pinyin":"gōngyèhuà","meaning_vi":"công nghiệp hóa","explanation":"工 (工) + 业 (sự nghiệp/ngành nghề) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这个地区正在工业化。","pinyin":"Zhè ge dìqū zhèngzài gōngyèhuà.","vi":"Khu vực này đang công nghiệp hóa."},{"type":"simple","zh":"十九世纪的工业化彻底改变了英国人的生活方式。","pinyin":"Shíjiǔ shìjì de gōngyèhuà chèdǐ gǎibiànle Yīngguórén de shēnghuó fāngshì.","vi":"Công nghiệp hóa thế kỷ 19 đã thay đổi hoàn toàn lối sống của người Anh."},{"type":"compound","zh":"工业化虽然带来了经济繁荣，但是也造成了大量农田被占用。","pinyin":"Gōngyèhuà suīrán dàiláile jīngjì fánróng, dànshì yě zào chéngle dàliàng nóngtián bèi zhànyòng.","vi":"Công nghiệp hóa tuy mang lại phồn vinh kinh tế, nhưng cũng khiến nhiều ruộng đất bị chiếm dụng."}],"related":[{"hanzi":"现代化","pinyin":"xiàndàihuà","vi":"hiện đại hóa"},{"hanzi":"城市化","pinyin":"chéngshìhuà","vi":"đô thị hóa"},{"hanzi":"工业","pinyin":"gōngyè","vi":"công nghiệp"}],"traditional":"工業化"},{"id":"公益","hanzi":"公益","pinyin":"gōngyì","meaning_vi":"công ích, hoạt động vì cộng đồng","explanation":"公 (公) + 益 (lợi ích/bổ ích).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"💖","examples":[{"type":"basic","zh":"她热心公益事业。","pinyin":"Tā rèxīn gōngyìshìyè.","vi":"Cô ấy nhiệt tình với sự nghiệp công ích."},{"type":"simple","zh":"这家公司每年拿出部分利润资助山区公益项目。","pinyin":"Zhè jiā gōngsī měinián náchū bùfen lìrùn zīzhù shānqū gōngyì xiàngmù.","vi":"Công ty này hằng năm trích một phần lợi nhuận tài trợ các dự án công ích ở vùng núi."},{"type":"compound","zh":"参加公益活动不但能帮助别人，而且能让自己更快乐。","pinyin":"Cānjiā gōngyì huódòng búdàn néng bāngzhù biérén, érqiě néng ràng zìjǐ gèng kuàilè.","vi":"Tham gia hoạt động công ích không chỉ giúp người khác mà còn khiến bản thân vui hơn."}],"related":[{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"志愿者","pinyin":"zhìyuànzhě","vi":"tình nguyện viên"},{"hanzi":"公益活动","pinyin":"gōngyìhuódòng","vi":"hoạt động công ích"}]},{"id":"供应链","hanzi":"供应链","pinyin":"gōngyìngliàn","meaning_vi":"chuỗi cung ứng","explanation":"供应 (cung ứng) + 链 (chuỗi mắt xích).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔗","examples":[{"type":"basic","zh":"疫情打乱了供应链。","pinyin":"Yìqíng dǎ luànle gōngyìngliàn.","vi":"Dịch bệnh đã làm rối loạn chuỗi cung ứng."},{"type":"simple","zh":"这家汽车厂正在寻找更稳定的零部件供应链。","pinyin":"Zhè jiā qìchēchǎng zhèngzài xúnzhǎo gèng wěndìng de língbùjiàn gōngyìngliàn.","vi":"Nhà máy ô tô này đang tìm chuỗi cung ứng linh kiện ổn định hơn."},{"type":"compound","zh":"只要供应链中有一个环节断裂，整条生产线就会停工。","pinyin":"Zhǐyào gōngyìngliàn zhōng yǒu yí gè huánjié duànliè, zhěngtiáo shēngchǎnxiàn jiù huì tínggōng.","vi":"Chỉ cần một khâu trong chuỗi cung ứng đứt gãy, cả dây chuyền sản xuất sẽ ngừng hoạt động."}],"related":[{"hanzi":"供应商","pinyin":"gōngyìngshāng","vi":"nhà cung cấp"},{"hanzi":"价值链","pinyin":"jiàzhíliàn","vi":"chuỗi giá trị"},{"hanzi":"物流","pinyin":"wùliú","vi":"hậu cần"}],"traditional":"供應鏈"},{"id":"孤岛","hanzi":"孤岛","pinyin":"gūdǎo","meaning_vi":"hòn đảo cô độc","explanation":"孤 (cô độc) + 岛 (岛).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏝️","examples":[{"type":"basic","zh":"海中有一座孤岛。","pinyin":"Hǎi zhōng yǒu yí zuò gūdǎo.","vi":"Giữa biển có một hòn đảo cô độc."},{"type":"simple","zh":"洪水把整个村子围成了一座孤岛。","pinyin":"Hóngshuǐ bǎ zhěnggè cūnzi wéi chéngle yí zuò gūdǎo.","vi":"Lũ lụt đã vây cả ngôi làng thành một ốc đảo biệt lập."},{"type":"compound","zh":"如果拒绝与外界交流，一个国家就会变成信息孤岛。","pinyin":"Rúguǒ jùjué yǔ wàijiè jiāoliú, yí gè guójiā jiù huì biànchéng xìnxī gūdǎo.","vi":"Nếu từ chối giao lưu với bên ngoài, một quốc gia sẽ trở thành ốc đảo thông tin."}],"related":[{"hanzi":"岛屿","pinyin":"dǎoyǔ","vi":"hải đảo"},{"hanzi":"孤立","pinyin":"gūlì","vi":"cô lập"},{"hanzi":"孤独","pinyin":"gūdú","vi":"cô đơn"}],"traditional":"孤島"},{"id":"改朝换代","hanzi":"改朝换代","pinyin":"gǎicháo-huàndài","meaning_vi":"thay triều đổi đại","explanation":"改朝换代: đổi (改) triều (朝), thay (换) đời (代) → triều đại cũ bị thay bằng triều đại mới; nghĩa rộng là thay đổi chính quyền, người nắm quyền.","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🏯","examples":[{"type":"basic","zh":"历史上多次改朝换代。","pinyin":"Lìshǐshang duōcì gǎicháohuàndài.","vi":"Trong lịch sử đã nhiều lần thay triều đổi đại."},{"type":"simple","zh":"这座古寺经历了多次改朝换代却依然屹立不倒。","pinyin":"Zhè zuò gǔ sì jīnglìle duōcì gǎicháohuàndài què yīrán yìlì bù dǎo.","vi":"Ngôi chùa cổ này trải qua bao lần thay triều đổi đại mà vẫn đứng vững."},{"type":"compound","zh":"公司高层一改朝换代，原来的规章制度就全被推翻了。","pinyin":"Gōngsī gāocéng yì gǎicháohuàndài, yuánlái de guīzhāng zhìdù jiù quán bèi tuīfān le.","vi":"Ban lãnh đạo công ty vừa thay ngôi đổi chủ, toàn bộ quy chế cũ liền bị lật đổ."}],"related":[{"hanzi":"朝代","pinyin":"cháodài","vi":"triều đại"},{"hanzi":"王朝","pinyin":"wángcháo","vi":"vương triều"},{"hanzi":"更替","pinyin":"gēngtì","vi":"thay thế"}],"traditional":"改朝換代"},{"id":"改观","hanzi":"改观","pinyin":"gǎiguān","meaning_vi":"thay đổi diện mạo theo hướng tốt hơn","explanation":"改 (cải – đổi) + 观 (quan – diện mạo) → thay đổi diện mạo, tình hình chuyển biến (thường theo hướng tốt). VD: 面貌大为改观.","hsk_level":"7-9","tags":["dong-tu"],"image":"✨","examples":[{"type":"basic","zh":"小镇面貌大为改观。","pinyin":"Xiǎozhèn miànmào dàwéi gǎiguān.","vi":"Diện mạo thị trấn nhỏ đã thay đổi lớn."},{"type":"simple","zh":"新校长上任一年后学校的风气有了明显改观。","pinyin":"Xīn xiàozhǎng shàng rènyì nián hòu xuéxiào de fēngqì yǒule míngxiǎn gǎiguān.","vi":"Một năm sau khi hiệu trưởng mới nhậm chức, nề nếp nhà trường đã thay đổi rõ rệt."},{"type":"compound","zh":"自从修了这条公路，山村的经济状况就逐渐改观了。","pinyin":"Zìcóng xiūle zhè tiáo gōnglù, shāncūn de jīngjì zhuàngkuàng jiù zhújiàn gǎiguān le.","vi":"Từ khi làm con đường này, tình hình kinh tế làng núi dần khởi sắc."}],"related":[{"hanzi":"改变","pinyin":"gǎibiàn","vi":"thay đổi"},{"hanzi":"好转","pinyin":"hǎozhuǎn","vi":"chuyển biến tốt"},{"hanzi":"面貌一新","pinyin":"miànmàoyìxīn","vi":"diện mạo mới"}],"traditional":"改觀"},{"id":"感召","hanzi":"感召","pinyin":"gǎnzhào","meaning_vi":"cảm hóa, kêu gọi truyền cảm hứng","explanation":"感 (感) + 召 (triệu tập/kêu gọi).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💖","examples":[{"type":"basic","zh":"他被英雄事迹感召。","pinyin":"Tā bèi yīngxióng shìjì gǎnzhào.","vi":"Anh ấy được cảm hóa bởi tấm gương anh hùng."},{"type":"simple","zh":"上千名市民在志愿精神的感召下报名献血。","pinyin":"Shàng qiān míng shìmín zài zhìyuàn jīngshén de gǎnzhào xià bàomíng xiànxuè.","vi":"Hàng nghìn người dân, được tinh thần tình nguyện truyền cảm hứng, đã đăng ký hiến máu."},{"type":"compound","zh":"因为受到老师人格魅力的感召，所以他毕业后也选择了支教。","pinyin":"Yīnwèi shòudào lǎoshī réngé mèilì de gǎnzhào, suǒyǐ tā bìyè hòu yě xuǎnzéle zhījiào.","vi":"Vì được nhân cách của thầy cảm hóa nên sau khi tốt nghiệp anh cũng chọn đi dạy học tình nguyện."}],"related":[{"hanzi":"感化","pinyin":"gǎnhuà","vi":"cảm hóa"},{"hanzi":"号召","pinyin":"hàozhào","vi":"kêu gọi"},{"hanzi":"鼓舞","pinyin":"gǔwǔ","vi":"cổ vũ"}]},{"id":"谷底","hanzi":"谷底","pinyin":"gǔdǐ","meaning_vi":"đáy thung lũng; mức thấp nhất, đáy","explanation":"谷 (cốc – thung lũng) + 底 (để – đáy) → đáy thung lũng; nghĩa bóng: mức thấp nhất. VD: 跌入谷底, 走出谷底.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"📉","examples":[{"type":"basic","zh":"股价跌到了谷底。","pinyin":"Gǔjià diē dàole gǔdǐ.","vi":"Giá cổ phiếu rơi xuống đáy."},{"type":"simple","zh":"一条清澈的小溪从谷底缓缓流过。","pinyin":"Yì tiáo qīngchè de xiǎoxī cóng gǔdǐ huǎnhuǎn liú guò.","vi":"Một con suối trong vắt chầm chậm chảy qua đáy thung lũng."},{"type":"compound","zh":"即使人生跌入谷底，也不要放弃对未来的希望。","pinyin":"Jíshǐ rénshēng diē rù gǔdǐ, yě bú yào fàngqì duì wèilái de xīwàng.","vi":"Dù cuộc đời rơi xuống đáy vực, cũng đừng từ bỏ hy vọng vào tương lai."}],"related":[{"hanzi":"低谷","pinyin":"dīgǔ","vi":"giai đoạn thấp"},{"hanzi":"山谷","pinyin":"shāngǔ","vi":"thung lũng"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"đỉnh cao"}]},{"id":"古迹","hanzi":"古迹","pinyin":"gǔjì","meaning_vi":"di tích cổ","explanation":"古 (cổ – xưa) + 迹 (tích – dấu vết) → di tích cổ. VD: 名胜古迹 (danh lam thắng cảnh và di tích).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏯","examples":[{"type":"basic","zh":"西安有很多名胜古迹。","pinyin":"Xī'ān yǒu hěn duō míngshènggǔjì.","vi":"Tây An có nhiều danh lam và di tích cổ."},{"type":"simple","zh":"考古队在修路时意外发现了一处汉代古迹。","pinyin":"Kǎogǔ duì zài xiūlù shí yìwài fāxiànle yí chù Hàndài gǔjì.","vi":"Đội khảo cổ tình cờ phát hiện một di tích thời Hán khi làm đường."},{"type":"compound","zh":"游客如果在古迹上乱刻乱画，就会受到严厉处罚。","pinyin":"Yóukè rúguǒ zài gǔjì shang luàn kè luànhuà, jiù huì shòudào yánlì chǔfá.","vi":"Du khách nếu khắc vẽ bừa bãi lên di tích cổ sẽ bị xử phạt nghiêm khắc."}],"related":[{"hanzi":"名胜古迹","pinyin":"míngshènggǔjì","vi":"danh lam cổ tích"},{"hanzi":"遗址","pinyin":"yízhǐ","vi":"di chỉ"},{"hanzi":"文物","pinyin":"wénwù","vi":"cổ vật"}],"traditional":"古跡"},{"id":"古籍","hanzi":"古籍","pinyin":"gǔjí","meaning_vi":"sách cổ","explanation":"古 (古) + 籍 (sách vở/quê quán).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"图书馆收藏了许多古籍。","pinyin":"Túshūguǎn shōucángle xǔduō gǔjí.","vi":"Thư viện lưu giữ nhiều sách cổ."},{"type":"simple","zh":"修复人员小心翼翼地修补一本明代古籍的书页。","pinyin":"Xiūfù rényuán xiǎoxīnyìyì de xiūbǔ yì běn Míngdài gǔjí de shūyè.","vi":"Nhân viên phục chế cẩn thận vá từng trang của một cuốn sách cổ đời Minh."},{"type":"compound","zh":"古籍一旦被数字化，普通读者就能在网上免费阅读。","pinyin":"Gǔjí yídàn bèi shùzìhuà, pǔtōng dúzhě jiù néng zài wǎngshàng miǎnfèi yuèdú.","vi":"Sách cổ một khi được số hóa, độc giả bình thường có thể đọc miễn phí trên mạng."}],"related":[{"hanzi":"古书","pinyin":"gǔshū","vi":"sách cổ"},{"hanzi":"典籍","pinyin":"diǎnjí","vi":"điển tịch"},{"hanzi":"文献","pinyin":"wénxiàn","vi":"văn hiến"}]},{"id":"骨气","hanzi":"骨气","pinyin":"gǔqì","meaning_vi":"khí phách, cốt cách kiên cường","explanation":"骨 (骨) + 气 (khí phách/khí hậu).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🦁","examples":[{"type":"basic","zh":"他是个有骨气的人。","pinyin":"Tā shì gè yǒu gǔqì de rén.","vi":"Anh ấy là người có khí phách."},{"type":"simple","zh":"穷书生宁可挨饿也不接受施舍的骨气令人敬佩。","pinyin":"Qióng shūshēng nìngkě ái'è yě bù jiēshòu shīshě de gǔqì lìngrén jìngpèi.","vi":"Khí phách thà chịu đói chứ không nhận bố thí của anh thư sinh nghèo khiến người ta kính phục."},{"type":"compound","zh":"虽然他家境贫寒，但是从来不向权贵低头，非常有骨气。","pinyin":"Suīrán tā jiājìng pínhán, dànshì cóngláibú xiàng quánguì dītóu, fēicháng yǒu gǔqì.","vi":"Tuy nhà nghèo, nhưng anh chưa bao giờ cúi đầu trước kẻ quyền thế, rất có khí phách."}],"related":[{"hanzi":"气节","pinyin":"qìjié","vi":"khí tiết"},{"hanzi":"志气","pinyin":"zhìqì","vi":"chí khí"},{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"yếu đuối"}],"traditional":"骨氣"},{"id":"古镇","hanzi":"古镇","pinyin":"gǔzhèn","meaning_vi":"cổ trấn, thị trấn cổ","explanation":"古 (古) + 镇 (bình tĩnh/thị trấn).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏮","examples":[{"type":"basic","zh":"周庄是江南古镇。","pinyin":"Zhōuzhuāng shì Jiāngnán gǔzhèn.","vi":"Chu Trang là một cổ trấn Giang Nam."},{"type":"simple","zh":"我们沿着青石板路在古镇里慢慢散步。","pinyin":"Wǒmen yánzhe qīng shíbǎnlù zài gǔzhèn lǐ mànmàn sànbù.","vi":"Chúng tôi thong thả dạo bước trên con đường lát đá xanh trong cổ trấn."},{"type":"compound","zh":"这座古镇既保留了明清建筑，又开了不少文艺小店。","pinyin":"Zhè zuò gǔzhèn jì bǎoliúle Míngqīng jiànzhù, yòu kāile bùshǎo wényì xiǎodiàn.","vi":"Cổ trấn này vừa giữ được kiến trúc Minh Thanh, vừa mở nhiều cửa hàng nhỏ mang phong cách nghệ thuật."}],"related":[{"hanzi":"古城","pinyin":"gǔchéng","vi":"thành cổ"},{"hanzi":"小镇","pinyin":"xiǎozhèn","vi":"thị trấn nhỏ"},{"hanzi":"古迹","pinyin":"gǔjì","vi":"di tích cổ"}],"traditional":"古鎮"},{"id":"呼声","hanzi":"呼声","pinyin":"hūshēng","meaning_vi":"tiếng nói nguyện vọng (của quần chúng)","explanation":"呼 (kêu gọi/thở ra) + 声 (thanh thế/tuyên bố).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"改革的呼声越来越高。","pinyin":"Gǎigé de hūshēng yuèláiyuè gāo.","vi":"Tiếng nói đòi cải cách ngày càng mạnh."},{"type":"simple","zh":"政府认真倾听了市民要求增加公园绿地的呼声。","pinyin":"Zhèngfǔ rènzhēn qīngtīngle shìmín yāoqiú zēngjiā gōngyuán lǜdì de hūshēng.","vi":"Chính quyền đã nghiêm túc lắng nghe nguyện vọng của người dân muốn có thêm công viên cây xanh."},{"type":"compound","zh":"虽然他在选举前呼声很高，但是最后只得了第二名。","pinyin":"Suīrán tā zài xuǎnjǔ qián hūshēng hěn gāo, dànshì zuìhòu zhǐ déle dì'èr míng.","vi":"Tuy trước bầu cử anh được kỳ vọng rất cao, nhưng cuối cùng chỉ về thứ hai."}],"related":[{"hanzi":"呼吁","pinyin":"hūyù","vi":"kêu gọi"},{"hanzi":"心声","pinyin":"xīnshēng","vi":"tiếng lòng"},{"hanzi":"民意","pinyin":"mínyì","vi":"ý dân"}],"traditional":"呼聲"},{"id":"欢聚一堂","hanzi":"欢聚一堂","pinyin":"huānjù-yìtáng","meaning_vi":"vui vẻ quây quần, sum họp một nơi","explanation":"欢 (vui mừng) + 聚 (tụ họp/ngưng tụ) + 一 (số 1) + 堂 (đường hoàng/hội trường).","hsk_level":"7-9","tags":["thanh-ngu","gia-dinh"],"image":"🥳","examples":[{"type":"basic","zh":"全家人欢聚一堂。","pinyin":"Quán jiārén huānjùyìtáng.","vi":"Cả nhà vui vẻ sum họp."},{"type":"simple","zh":"毕业二十年的老同学们在母校欢聚一堂。","pinyin":"Bìyè èrshí nián de lǎo tóngxuémen zài mǔxiào huānjùyìtáng.","vi":"Những người bạn học đã tốt nghiệp hai mươi năm vui vẻ hội ngộ tại trường cũ."},{"type":"compound","zh":"每到除夕夜，分散各地的亲人就会回到老家欢聚一堂。","pinyin":"Měi dào chúxīyè, fēnsàn gèdì de qīnrén jiù huì huídào lǎojiā huānjùyìtáng.","vi":"Mỗi đêm giao thừa, người thân ở khắp nơi lại về quê sum họp."}],"related":[{"hanzi":"欢聚","pinyin":"huānjù","vi":"vui vẻ sum họp"},{"hanzi":"团聚","pinyin":"tuánjù","vi":"đoàn tụ"},{"hanzi":"相聚","pinyin":"xiāngjù","vi":"gặp gỡ"}],"traditional":"歡聚一堂"},{"id":"欢声笑语","hanzi":"欢声笑语","pinyin":"huānshēng-xiàoyǔ","meaning_vi":"tiếng cười nói rộn rã","explanation":"欢 (vui mừng) + 声 (thanh thế/tuyên bố) + 笑 (cười) + 语 (ngôn ngữ/lời nói).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😄","examples":[{"type":"basic","zh":"教室里充满欢声笑语。","pinyin":"Jiàoshì lǐ chōngmǎn huānshēngxiàoyǔ.","vi":"Lớp học tràn ngập tiếng cười nói."},{"type":"simple","zh":"孩子们的欢声笑语从院子里一直传到街上。","pinyin":"Háizimen de huānshēngxiàoyǔ cóng yuànzi lǐ yìzhí chuán dào jiēshang.","vi":"Tiếng cười nói của bọn trẻ vang từ trong sân ra tận ngoài phố."},{"type":"compound","zh":"奶奶一出院，家里就又恢复了往日的欢声笑语。","pinyin":"Nǎinai yì chūyuàn, jiālǐ jiù yòu huīfùle wǎngrì de huānshēngxiàoyǔ.","vi":"Bà vừa xuất viện, trong nhà lại rộn rã tiếng cười nói như xưa."}],"related":[{"hanzi":"欢笑","pinyin":"huānxiào","vi":"cười vui"},{"hanzi":"笑声","pinyin":"xiàoshēng","vi":"tiếng cười"},{"hanzi":"热闹","pinyin":"rènao","vi":"náo nhiệt"}],"traditional":"歡聲笑語"},{"id":"化险为夷","hanzi":"化险为夷","pinyin":"huàxiǎn-wéiyí","meaning_vi":"biến nguy thành an","explanation":"化 (化) + 险 (nguy hiểm/bảo hiểm) + 为 (vì) + 夷 (夷).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🍀","examples":[{"type":"basic","zh":"他总能化险为夷。","pinyin":"Tā zǒngnéng huàxiǎnwéiyí.","vi":"Anh ấy luôn biến nguy thành an."},{"type":"simple","zh":"机长凭借冷静的操作让飞机化险为夷。","pinyin":"Jīzhǎng píngjiè lěngjìng de cāozuò ràng fēijī huàxiǎnwéiyí.","vi":"Cơ trưởng nhờ thao tác bình tĩnh đã giúp máy bay thoát nạn."},{"type":"compound","zh":"虽然登山队遇到了暴风雪，但是在向导的带领下化险为夷。","pinyin":"Suīrán dēngshān duì yùdàole bàofēngxuě, dànshì zài xiàngdǎo de dàilǐng xià huàxiǎnwéiyí.","vi":"Tuy đoàn leo núi gặp bão tuyết, nhưng dưới sự dẫn dắt của hướng dẫn viên đã thoát hiểm an toàn."}],"related":[{"hanzi":"转危为安","pinyin":"zhuǎnwēiwéi'ān","vi":"chuyển nguy thành an"},{"hanzi":"脱险","pinyin":"tuōxiǎn","vi":"thoát hiểm"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"}],"traditional":"化險為夷"},{"id":"换位思考","hanzi":"换位思考","pinyin":"huànwèisīkǎo","meaning_vi":"đặt mình vào vị trí người khác để suy nghĩ","explanation":"换 (đổi) + 位 (vị trí/địa vị) + 思 (suy nghĩ/tư duy) + 考 (khảo sát/thi cử).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc","giao-tiep"],"image":"🧠","examples":[{"type":"basic","zh":"吵架时要学会换位思考。","pinyin":"Chǎojià shí yào xuéhuì huànwèisīkǎo.","vi":"Khi cãi nhau cần học cách đặt mình vào vị trí người khác."},{"type":"simple","zh":"优秀的产品经理总是站在用户角度换位思考。","pinyin":"Yōuxiù de chǎnpǐn jīnglǐ zǒngshì zhàn zài yònghù jiǎodù huànwèisīkǎo.","vi":"Người quản lý sản phẩm giỏi luôn đứng ở góc độ người dùng để suy nghĩ."},{"type":"compound","zh":"如果你能换位思考，就会明白妈妈为什么这么担心你。","pinyin":"Rúguǒ nǐ néng huànwèisīkǎo, jiù huì míngbai māma wèishénme zhème dānxīn nǐ.","vi":"Nếu con biết đặt mình vào vị trí người khác, con sẽ hiểu vì sao mẹ lo cho con đến thế."}],"related":[{"hanzi":"将心比心","pinyin":"jiāngxīnbǐxīn","vi":"suy bụng ta ra bụng người"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"thấu hiểu"},{"hanzi":"体谅","pinyin":"tǐliàng","vi":"thông cảm"}],"traditional":"換位思考"},{"id":"华诞","hanzi":"华诞","pinyin":"huádàn","meaning_vi":"ngày sinh nhật trọng đại (của quốc gia/vĩ nhân)","explanation":"华 (hoa lệ/Trung Hoa) + 诞 (ra đời/hoang đường).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🎂","examples":[{"type":"basic","zh":"今年是学校百年华诞。","pinyin":"Jīnnián shì xuéxiào bǎinián huádàn.","vi":"Năm nay là đại lễ kỷ niệm trăm năm thành lập trường."},{"type":"simple","zh":"全国各地举行了隆重的活动庆祝祖国华诞。","pinyin":"Quánguó gèdì jǔxíngle lóngzhòng de huódòng qìngzhù zǔguó huádàn.","vi":"Khắp cả nước tổ chức các hoạt động long trọng mừng ngày sinh của Tổ quốc."},{"type":"compound","zh":"母校九十华诞一到，海内外校友就纷纷赶回来参加庆典。","pinyin":"Mǔxiào jiǔshí huádàn yí dào, Hǎinèiwài xiàoyǒu jiù fēnfēn gǎn huílái cānjiā qìngdiǎn.","vi":"Dịp kỷ niệm 90 năm thành lập trường vừa đến, cựu sinh viên trong và ngoài nước đã lũ lượt trở về dự lễ."}],"related":[{"hanzi":"诞辰","pinyin":"dànchén","vi":"ngày sinh"},{"hanzi":"生日","pinyin":"shēngrì","vi":"sinh nhật"},{"hanzi":"周年","pinyin":"zhōunián","vi":"kỷ niệm năm"}],"traditional":"華誕"},{"id":"华美","hanzi":"华美","pinyin":"huáměi","meaning_vi":"hoa mỹ, lộng lẫy","explanation":"华 (hoa lệ/Trung Hoa) + 美 (tươi đẹp/mỹ mãn).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"宫殿装饰华美。","pinyin":"Gōngdiàn zhuāngshì huáměi.","vi":"Cung điện được trang trí lộng lẫy."},{"type":"simple","zh":"她穿着一件绣满金线的华美长裙出席晚宴。","pinyin":"Tā chuānzhe yí jiàn xiù mǎn jīn xiàn de huáměi chángqún chūxí wǎnyàn.","vi":"Cô mặc chiếc váy dài lộng lẫy thêu đầy chỉ vàng đến dự tiệc tối."},{"type":"compound","zh":"这篇散文虽然辞藻华美，但是内容有些空洞。","pinyin":"Zhè piān sǎnwén suīrán cízǎo huáměi, dànshì nèiróng yǒuxiē kōngdòng.","vi":"Bài tản văn này tuy lời lẽ hoa mỹ, nhưng nội dung hơi rỗng."}],"related":[{"hanzi":"华丽","pinyin":"huálì","vi":"lộng lẫy"},{"hanzi":"美丽","pinyin":"měilì","vi":"xinh đẹp"},{"hanzi":"朴素","pinyin":"pǔsù","vi":"giản dị"}],"traditional":"華美"},{"id":"华夏","hanzi":"华夏","pinyin":"Huáxià","meaning_vi":"Hoa Hạ (tên gọi cổ của Trung Hoa)","explanation":"华 (hoa lệ/Trung Hoa) + 夏 (夏).","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-danh"],"image":"🏯","examples":[{"type":"basic","zh":"华夏文明源远流长。","pinyin":"Huáxià wénmíng yuányuǎnliúcháng.","vi":"Văn minh Hoa Hạ có nguồn gốc lâu đời."},{"type":"simple","zh":"黄河流域被认为是华夏文化的发源地之一。","pinyin":"Huánghéliúyù bèi rènwéi shì Huáxià wénhuà de fāyuándì zhīyī.","vi":"Lưu vực sông Hoàng Hà được coi là một trong những cái nôi của văn hóa Hoa Hạ."},{"type":"compound","zh":"不管身在何方，海外华人都把自己看作华夏儿女。","pinyin":"Bùguǎn shēn zài héfāng, hǎiwài Huárén dōu bǎ zìjǐ kànzuò Huáxià érnǚ.","vi":"Dù ở phương nào, người Hoa hải ngoại đều coi mình là con cháu Hoa Hạ."}],"related":[{"hanzi":"中华","pinyin":"Zhōnghuá","vi":"Trung Hoa"},{"hanzi":"炎黄子孙","pinyin":"Yánhuángzǐsūn","vi":"con cháu Viêm Hoàng"},{"hanzi":"华人","pinyin":"Huárén","vi":"người Hoa"}],"traditional":"華夏"},{"id":"怀旧","hanzi":"怀旧","pinyin":"huáijiù","meaning_vi":"hoài cổ, nhớ về quá khứ","explanation":"怀 (hoài niệm/lòng) + 旧 (cũ).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"📻","examples":[{"type":"basic","zh":"人老了容易怀旧。","pinyin":"Rén lǎole róngyì huáijiù.","vi":"Người già dễ hoài niệm."},{"type":"simple","zh":"这家餐厅用老式搪瓷杯营造出浓浓的怀旧氛围。","pinyin":"Zhè jiā cāntīng yòng lǎoshì tángcí bēi yíngzào chū nóng nóng de huáijiù fēnwéi.","vi":"Nhà hàng này dùng cốc tráng men kiểu cũ tạo nên bầu không khí hoài cổ đậm đà."},{"type":"compound","zh":"每当听到这首老歌，爸爸就会变得特别怀旧。","pinyin":"Měidāng tīngdào zhè shǒu lǎogē, bàba jiù huì biànde tèbié huáijiù.","vi":"Mỗi khi nghe bài hát cũ này, bố lại trở nên đặc biệt hoài niệm."}],"related":[{"hanzi":"怀念","pinyin":"huáiniàn","vi":"hoài niệm"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi ức"},{"hanzi":"念旧","pinyin":"niànjiù","vi":"nhớ chuyện cũ"}],"traditional":"懷舊"},{"id":"黄河","hanzi":"黄河","pinyin":"Huánghé","meaning_vi":"sông Hoàng Hà (sông mẹ của nền văn minh Trung Hoa)","explanation":"黄 (vàng) + 河 (sông).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"黄河是中国的母亲河。","pinyin":"Huánghé shì Zhōngguó de mǔqīnhé.","vi":"Hoàng Hà là sông mẹ của Trung Quốc."},{"type":"simple","zh":"我们站在壶口瀑布旁观看黄河奔腾而下。","pinyin":"Wǒmen zhàn zài hú kǒu pùbù pángguān kàn Huánghé bēnténg ér xià.","vi":"Chúng tôi đứng bên thác Hồ Khẩu ngắm sông Hoàng Hà cuồn cuộn đổ xuống."},{"type":"compound","zh":"因为黄河携带大量泥沙，所以河水看起来是黄色的。","pinyin":"Yīnwèi Huánghé xiédài dàliàng níshā, suǒyǐ héshuǐ kànqǐlái shì huángsè de.","vi":"Vì sông Hoàng Hà mang theo rất nhiều phù sa nên nước sông trông có màu vàng."}],"related":[{"hanzi":"长江","pinyin":"Chángjiāng","vi":"sông Trường Giang"},{"hanzi":"母亲河","pinyin":"mǔqīnhé","vi":"sông mẹ"},{"hanzi":"黄土高原","pinyin":"Huángtǔgāoyuán","vi":"cao nguyên Hoàng Thổ"}],"traditional":"黃河"},{"id":"黄金周","hanzi":"黄金周","pinyin":"huángjīnzhōu","meaning_vi":"Tuần lễ Vàng (kỳ nghỉ lễ dài ở TQ)","explanation":"黄 (màu vàng) + 金 (金) + 周 (chu đáo/chu kỳ).","hsk_level":"7-9","tags":["danh-tu","du-lich","thoi-gian"],"image":"🏖️","examples":[{"type":"basic","zh":"黄金周景区人山人海。","pinyin":"Huángjīnzhōu jǐngqū rénshānrénhǎi.","vi":"Dịp Tuần lễ Vàng các khu du lịch đông nghịt người."},{"type":"simple","zh":"我们打算利用国庆黄金周去云南自驾游。","pinyin":"Wǒmen dǎsuàn lìyòng Guóqìng huángjīnzhōu qù Yúnnán zìjiàyóu.","vi":"Chúng tôi dự định tranh thủ Tuần lễ Vàng Quốc khánh tự lái xe đi du lịch Vân Nam."},{"type":"compound","zh":"如果黄金周出游，就一定要提前订好酒店和车票。","pinyin":"Rúguǒ huángjīnzhōu chūyóu, jiù yídìngyào tíqián dìng hǎo jiǔdiàn hé chēpiào.","vi":"Nếu đi chơi dịp Tuần lễ Vàng thì nhất định phải đặt trước khách sạn và vé xe."}],"related":[{"hanzi":"假期","pinyin":"jiàqī","vi":"kỳ nghỉ"},{"hanzi":"国庆节","pinyin":"Guóqìngjié","vi":"Quốc khánh"},{"hanzi":"长假","pinyin":"chángjià","vi":"kỳ nghỉ dài"}],"traditional":"黃金周"},{"id":"黄山","hanzi":"黄山","pinyin":"Huángshān","meaning_vi":"núi Hoàng Sơn (An Huy)","explanation":"Danh thắng nổi tiếng Trung Quốc.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"黄山以奇松闻名。","pinyin":"Huángshān yǐ qí sōng wénmíng.","vi":"Hoàng Sơn nổi tiếng với những cây thông kỳ lạ."},{"type":"simple","zh":"我们凌晨四点就爬上黄山光明顶等着看日出。","pinyin":"Wǒmen língchén sì diǎn jiù páshàng Huángshān guāngmíng dǐng děngzhe kàn rìchū.","vi":"Chúng tôi leo lên đỉnh Quang Minh của Hoàng Sơn lúc bốn giờ sáng để chờ xem mặt trời mọc."},{"type":"compound","zh":"虽然黄山的台阶又陡又长，但是山顶的云海让人觉得不虚此行。","pinyin":"Suīrán Huángshān de táijiē yòu dǒu yòu cháng, dànshì shāndǐng de yúnhǎi ràng rén juéde bù xū cǐxíng.","vi":"Tuy bậc đá Hoàng Sơn vừa dốc vừa dài, nhưng biển mây trên đỉnh khiến người ta thấy chuyến đi thật xứng đáng."}],"related":[{"hanzi":"泰山","pinyin":"Tàishān","vi":"núi Thái Sơn"},{"hanzi":"名山","pinyin":"míngshān","vi":"núi nổi tiếng"},{"hanzi":"安徽","pinyin":"Ānhuī","vi":"An Huy"}],"traditional":"黃山"},{"id":"黄土高原","hanzi":"黄土高原","pinyin":"Huángtǔgāoyuán","meaning_vi":"cao nguyên Hoàng Thổ","explanation":"黄 (màu vàng) + 土 (đất đai/bản địa) + 高 (cao) + 原 (nguyên lý/nguyên tắc).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"黄土高原水土流失严重。","pinyin":"Huángtǔgāoyuán shuǐtǔliúshī yánzhòng.","vi":"Cao nguyên Hoàng Thổ bị xói mòn đất nghiêm trọng."},{"type":"simple","zh":"很多农民至今仍住在黄土高原的窑洞里。","pinyin":"Hěn duō nóngmín zhìjīn réng zhùzài Huángtǔgāoyuán de yáodòng lǐ.","vi":"Nhiều nông dân đến nay vẫn sống trong những hang động trên cao nguyên Hoàng Thổ."},{"type":"compound","zh":"经过多年植树造林，黄土高原不但绿了，而且沙尘天气也少了。","pinyin":"Jīngguò duōnián zhíshùzàolín, Huángtǔgāoyuán búdàn lǜ le, érqiě shāchén tiānqì yě shǎo le.","vi":"Sau nhiều năm trồng rừng, cao nguyên Hoàng Thổ không những xanh lên mà thời tiết bão cát cũng giảm đi."}],"related":[{"hanzi":"黄河","pinyin":"Huánghé","vi":"sông Hoàng Hà"},{"hanzi":"高原","pinyin":"gāoyuán","vi":"cao nguyên"},{"hanzi":"水土流失","pinyin":"shuǐtǔliúshī","vi":"xói mòn đất"}],"traditional":"黃土高原"},{"id":"荟萃","hanzi":"荟萃","pinyin":"huìcuì","meaning_vi":"hội tụ tinh hoa","explanation":"荟 (tụ họp tinh hoa) + 萃 (萃).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🌟","examples":[{"type":"basic","zh":"这里名家荟萃。","pinyin":"Zhèlǐ míngjiā huìcuì.","vi":"Nơi đây hội tụ nhiều danh gia."},{"type":"simple","zh":"本届美食节荟萃了全国各地的特色小吃。","pinyin":"Běnjiè měishí jié huìcuìle quánguó gèdì de tèsè xiǎochī.","vi":"Lễ hội ẩm thực lần này hội tụ các món ăn vặt đặc sắc khắp cả nước."},{"type":"compound","zh":"这座博物馆不但藏品丰富，而且荟萃了历代书画精品。","pinyin":"Zhè zuò bówùguǎn búdàn cángpǐn fēngfù, érqiě huìcuìle lìdài shūhuà jīngpǐn.","vi":"Bảo tàng này không những hiện vật phong phú mà còn hội tụ những kiệt tác thư họa qua các triều đại."}],"related":[{"hanzi":"汇集","pinyin":"huìjí","vi":"tập hợp"},{"hanzi":"云集","pinyin":"yúnjí","vi":"tụ hội đông đảo"},{"hanzi":"精华","pinyin":"jīnghuá","vi":"tinh hoa"}],"traditional":"薈萃"},{"id":"汇合","hanzi":"汇合","pinyin":"huìhé","meaning_vi":"hội tụ, hợp lưu (dòng sông/lực lượng)","explanation":"汇 (tổng hợp/chuyển tiền) + 合 (合).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"两条河在这里汇合。","pinyin":"Liǎng tiáo hé zài zhèlǐ huìhé.","vi":"Hai con sông hợp lưu tại đây."},{"type":"simple","zh":"两支救援队计划下午三点在山脚下汇合。","pinyin":"Liǎng zhī jiùyuánduì jìhuà xiàwǔ sān diǎn zài shān jiǎoxià huìhé.","vi":"Hai đội cứu hộ dự định hội quân dưới chân núi lúc ba giờ chiều."},{"type":"compound","zh":"你们先去酒店放行李，然后到广场和我们汇合。","pinyin":"Nǐmen xiān qù jiǔdiàn fàng xíngli, ránhòu dào guǎngchǎng hé wǒmen huìhé.","vi":"Các bạn đến khách sạn cất hành lý trước, rồi ra quảng trường gặp chúng tôi."}],"related":[{"hanzi":"汇集","pinyin":"huìjí","vi":"tập hợp"},{"hanzi":"会合","pinyin":"huìhé","vi":"gặp nhau"},{"hanzi":"交汇","pinyin":"jiāohuì","vi":"giao nhau"}],"traditional":"匯合"},{"id":"汇集","hanzi":"汇集","pinyin":"huìjí","meaning_vi":"tập hợp, hội tụ","explanation":"汇 (tổng hợp/chuyển tiền) + 集 (tập hợp).","hsk_level":"7-9","tags":["dong-tu"],"image":"👥","examples":[{"type":"basic","zh":"广场上汇集了上万人。","pinyin":"Guǎngchǎng shang huìjíle shàng wànrén.","vi":"Trên quảng trường tụ tập hơn vạn người."},{"type":"simple","zh":"这本论文集汇集了二十位学者的最新研究成果。","pinyin":"Zhè běn lùnwén jí huìjíle èrshí wèi xuézhě de zuì xīn yánjiū chéngguǒ.","vi":"Tuyển tập luận văn này tập hợp thành quả nghiên cứu mới nhất của hai mươi học giả."},{"type":"compound","zh":"只要把大家的建议汇集起来，就能找到更好的方案。","pinyin":"Zhǐyào bǎ dàjiā de jiànyì huìjí qǐlái, jiù néng zhǎodào gèng hǎo de fāng'àn.","vi":"Chỉ cần tập hợp ý kiến của mọi người lại là có thể tìm ra phương án tốt hơn."}],"related":[{"hanzi":"收集","pinyin":"shōují","vi":"thu thập"},{"hanzi":"聚集","pinyin":"jùjí","vi":"tụ tập"},{"hanzi":"汇总","pinyin":"huìzǒng","vi":"tổng hợp"}],"traditional":"匯集"},{"id":"回荡","hanzi":"回荡","pinyin":"huídàng","meaning_vi":"vang vọng","explanation":"回 (về) + 荡 (dao động/lắc lư).","hsk_level":"7-9","tags":["dong-tu"],"image":"🎶","examples":[{"type":"basic","zh":"歌声在山谷中回荡。","pinyin":"Gēshēng zài shāngǔ zhōng huídàng.","vi":"Tiếng hát vang vọng trong thung lũng."},{"type":"simple","zh":"古寺的钟声在清晨的山林间久久回荡。","pinyin":"Gǔ sì de zhōngshēng zài qīngchén de shānlín jiān jiǔjiǔ huídàng.","vi":"Tiếng chuông chùa cổ vang vọng mãi giữa núi rừng buổi sớm."},{"type":"compound","zh":"虽然演讲已经结束，但是他的话一直在我耳边回荡。","pinyin":"Suīrán yǎnjiǎng yǐjīng jiéshù, dànshì tā dehuà yìzhí zài wǒ ěr biān huídàng.","vi":"Tuy bài diễn thuyết đã kết thúc, nhưng lời ông vẫn vang vọng bên tai tôi."}],"related":[{"hanzi":"回响","pinyin":"huíxiǎng","vi":"tiếng vang"},{"hanzi":"回音","pinyin":"huíyīn","vi":"tiếng vọng"},{"hanzi":"飘荡","pinyin":"piāodàng","vi":"phiêu đãng"}],"traditional":"迴盪"},{"id":"回暖","hanzi":"回暖","pinyin":"huínuǎn","meaning_vi":"ấm lên (thời tiết); khởi sắc trở lại (thị trường)","explanation":"回 (hồi – quay lại) + 暖 (noãn – ấm) → ấm trở lại; nghĩa bóng: thị trường, kinh tế phục hồi. VD: 天气回暖, 楼市回暖.","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"气温开始回暖了。","pinyin":"Qìwēn kāishǐ huínuǎn le.","vi":"Nhiệt độ bắt đầu ấm lên."},{"type":"simple","zh":"楼市在第二季度出现了明显的回暖迹象。","pinyin":"Lóushì zài dì'èr jìdù chūxiànle míngxiǎn de huínuǎn jìxiàng.","vi":"Thị trường nhà đất xuất hiện dấu hiệu ấm lên rõ rệt trong quý hai."},{"type":"compound","zh":"一旦天气回暖，公园里的樱花就会陆续开放。","pinyin":"Yídàn tiānqì huínuǎn, gōngyuán lǐ de yīnghuā jiù huì lùxù kāifàng.","vi":"Một khi thời tiết ấm lên, hoa anh đào trong công viên sẽ lần lượt nở."}],"related":[{"hanzi":"变暖","pinyin":"biànnuǎn","vi":"ấm lên"},{"hanzi":"复苏","pinyin":"fùsū","vi":"phục hồi"},{"hanzi":"降温","pinyin":"jiàngwēn","vi":"hạ nhiệt"}]},{"id":"回响","hanzi":"回响","pinyin":"huíxiǎng","meaning_vi":"vang vọng; tiếng vang, sự hưởng ứng","explanation":"回 (về) + 响 (vang).","hsk_level":"7-9","tags":["danh-tu","dong-tu"],"image":"🔊","examples":[{"type":"basic","zh":"枪声在山间回响。","pinyin":"Qiāngshēng zài shān jiān huíxiǎng.","vi":"Tiếng súng vang vọng giữa núi."},{"type":"simple","zh":"他的这篇文章在教育界引起了强烈的回响。","pinyin":"Tā de zhè piān wénzhāng zài jiàoyùjiè yǐnqǐle qiángliè de huíxiǎng.","vi":"Bài viết của ông đã gây tiếng vang mạnh mẽ trong giới giáo dục."},{"type":"compound","zh":"虽然这部电影票房一般，但是在影评人中获得了不小的回响。","pinyin":"Suīrán zhè bù diànyǐng piàofáng yìbān, dànshì zài yǐngpíng rénzhōng huò déle bù xiǎo de huíxiǎng.","vi":"Tuy bộ phim doanh thu bình thường, nhưng đã tạo được tiếng vang không nhỏ trong giới phê bình."}],"related":[{"hanzi":"回音","pinyin":"huíyīn","vi":"tiếng vọng"},{"hanzi":"反响","pinyin":"fǎnxiǎng","vi":"phản hồi"},{"hanzi":"回荡","pinyin":"huídàng","vi":"vang vọng"}],"traditional":"迴響"},{"id":"回音","hanzi":"回音","pinyin":"huíyīn","meaning_vi":"tiếng vang, tiếng vọng; hồi âm","explanation":"回 (về) + 音 (âm thanh/tin tức).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"山谷里传来回音。","pinyin":"Shāngǔ lǐ chuánlái huíyīn.","vi":"Từ thung lũng vọng lại tiếng vang."},{"type":"simple","zh":"他寄出求职信已经两周了还没有收到任何回音。","pinyin":"Tā jìchū qiúzhíxìn yǐjīng liǎng zhōule hái méiyǒu shōudào rènhé huíyīn.","vi":"Anh gửi thư xin việc đã hai tuần mà vẫn chưa nhận được hồi âm nào."},{"type":"compound","zh":"如果对方三天内没有回音，我们就另找合作伙伴。","pinyin":"Rúguǒ duìfāng sān tiān nèi méiyǒu huíyīn, wǒmen jiù lìng zhǎo hézuò huǒbàn.","vi":"Nếu trong ba ngày bên kia không hồi âm, chúng ta sẽ tìm đối tác khác."}],"related":[{"hanzi":"回响","pinyin":"huíxiǎng","vi":"tiếng vang"},{"hanzi":"回信","pinyin":"huíxìn","vi":"thư trả lời"},{"hanzi":"答复","pinyin":"dáfù","vi":"trả lời"}],"traditional":"迴音"},{"id":"祸不单行","hanzi":"祸不单行","pinyin":"huòbù-dānxíng","meaning_vi":"họa vô đơn chí","explanation":"祸 (祸) + 不 (không) + 单 (单) + 行 (được).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⛈️","examples":[{"type":"basic","zh":"真是祸不单行啊！","pinyin":"Zhēn shì huòbùdānxíng a!","vi":"Đúng là họa vô đơn chí!"},{"type":"simple","zh":"这个月对他来说真是祸不单行。","pinyin":"Zhè geyuè duì tā lái shuō zhēn shì huòbùdānxíng.","vi":"Tháng này đối với anh ấy đúng là họa vô đơn chí."},{"type":"compound","zh":"他刚丢了工作，紧接着又生了一场大病，真是祸不单行。","pinyin":"Tā gāng diūle gōngzuò, jǐnjiēzhe yòu shēngle yì chǎng dàbìng, zhēn shì huòbùdānxíng.","vi":"Anh vừa mất việc, ngay sau đó lại đổ bệnh nặng, đúng là họa vô đơn chí."}],"related":[{"hanzi":"雪上加霜","pinyin":"xuěshàngjiāshuāng","vi":"họa chồng họa"},{"hanzi":"福无双至","pinyin":"fúwúshuāngzhì","vi":"phúc bất trùng lai"},{"hanzi":"倒霉","pinyin":"dǎoméi","vi":"xui xẻo"}],"traditional":"禍不單行"},{"id":"货运","hanzi":"货运","pinyin":"huòyùn","meaning_vi":"vận tải hàng hóa","explanation":"货 (货) + 运 (vận dụng/vận hành).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"🚚","examples":[{"type":"basic","zh":"这条铁路主要用于货运。","pinyin":"Zhè tiáo tiělù zhǔyào yòngyú huòyùn.","vi":"Tuyến đường sắt này chủ yếu dùng để vận tải hàng hóa."},{"type":"simple","zh":"中欧班列大大缩短了亚欧之间的货运时间。","pinyin":"Zhōng'ōu bān liè dàdà suōduǎnle Yà'ōu zhījiān de huòyùn shíjiān.","vi":"Tàu hàng Trung Quốc - châu Âu đã rút ngắn đáng kể thời gian vận chuyển hàng hóa giữa Á và Âu."},{"type":"compound","zh":"因为航空货运成本太高，所以公司改用海运发货。","pinyin":"Yīnwèi hángkōng huòyùn chéngběn tài gāo, suǒyǐ gōngsī gǎiyòng hǎiyùn fāhuò.","vi":"Vì chi phí vận tải hàng không quá cao nên công ty chuyển sang gửi hàng bằng đường biển."}],"related":[{"hanzi":"客运","pinyin":"kèyùn","vi":"vận tải hành khách"},{"hanzi":"物流","pinyin":"wùliú","vi":"hậu cần"},{"hanzi":"运输","pinyin":"yùnshū","vi":"vận chuyển"}],"traditional":"貨運"},{"id":"活灵活现","hanzi":"活灵活现","pinyin":"huólíng-huóxiàn","meaning_vi":"sống động như thật","explanation":"活 (活) + 灵 (linh hoạt/linh hồn) + 活 (活) + 现 (hiện thực/hiện trường).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎨","examples":[{"type":"basic","zh":"他讲得活灵活现。","pinyin":"Tā jiǎng de huólínghuóxiàn.","vi":"Anh ấy kể sống động như thật."},{"type":"simple","zh":"画家笔下的几只小猫画得活灵活现。","pinyin":"Huàjiā bǐxià de jǐ zhī xiǎomāo huà de huólínghuóxiàn.","vi":"Mấy chú mèo con dưới ngòi bút họa sĩ được vẽ sống động như thật."},{"type":"compound","zh":"爷爷一讲起当年的故事，就说得活灵活现，让我们听入了迷。","pinyin":"Yéye yì jiǎng qǐ dāngnián de gùshi, jiù shuō de huólínghuóxiàn, ràng wǒmen tīng rùle mí.","vi":"Ông nội hễ kể chuyện ngày xưa là kể sống động như thật, khiến chúng tôi nghe say mê."}],"related":[{"hanzi":"栩栩如生","pinyin":"xǔxǔrúshēng","vi":"sống động như thật"},{"hanzi":"生动","pinyin":"shēngdòng","vi":"sinh động"},{"hanzi":"逼真","pinyin":"bīzhēn","vi":"giống như thật"}],"traditional":"活靈活現"},{"id":"花蕾","hanzi":"花蕾","pinyin":"huālěi","meaning_vi":"nụ hoa","explanation":"花 (tiêu (tiền/thời gian)) + 蕾 (nụ hoa).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌷","examples":[{"type":"basic","zh":"枝头长满了花蕾。","pinyin":"Zhī tóu zhǎngmǎnle huālěi.","vi":"Đầu cành đầy nụ hoa."},{"type":"simple","zh":"院子里的玉兰树已经冒出了毛茸茸的花蕾。","pinyin":"Yuànzi lǐ de Yùlán shù yǐjīng mào chūle máoróngróng de huālěi.","vi":"Cây ngọc lan trong sân đã nhú ra những nụ hoa phủ lông tơ."},{"type":"compound","zh":"只要再暖和几天，这些花蕾就会全部绽放。","pinyin":"Zhǐyào zài nuǎnhuo jǐtiān, zhèxiē huālěi jiù huì quánbù zhànfàng.","vi":"Chỉ cần ấm thêm vài ngày nữa, những nụ hoa này sẽ nở rộ hết."}],"related":[{"hanzi":"花朵","pinyin":"huāduǒ","vi":"bông hoa"},{"hanzi":"含苞待放","pinyin":"hánbāodàifàng","vi":"chúm chím chờ nở"},{"hanzi":"开花","pinyin":"kāihuā","vi":"nở hoa"}]},{"id":"花絮","hanzi":"花絮","pinyin":"huāxù","meaning_vi":"chuyện bên lề, hậu trường thú vị","explanation":"花 (tiêu (tiền/thời gian)) + 絮 (bông/chuyện bên lề).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"这是电影拍摄花絮。","pinyin":"Zhè shì diànyǐng pāishè huāxù.","vi":"Đây là cảnh hậu trường quay phim."},{"type":"simple","zh":"片尾播放的拍摄花絮让观众笑得前仰后合。","pinyin":"Piànwěi bōfàng de pāishè huāxù ràng guānzhòng xiào de qiányǎnghòuhé.","vi":"Những cảnh hậu trường phát cuối phim khiến khán giả cười nghiêng ngả."},{"type":"compound","zh":"记者不但报道了比赛结果，而且整理了赛场上的趣味花絮。","pinyin":"Jìzhě búdàn bàodàole bǐsài jiéguǒ, érqiě zhěnglǐle sàichǎng shang de qùwèi huāxù.","vi":"Phóng viên không những đưa tin kết quả trận đấu mà còn tổng hợp những chuyện bên lề thú vị trên sân."}],"related":[{"hanzi":"幕后","pinyin":"mùhòu","vi":"hậu trường"},{"hanzi":"趣闻","pinyin":"qùwén","vi":"chuyện thú vị"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"}]},{"id":"荒废","hanzi":"荒废","pinyin":"huāngfèi","meaning_vi":"bỏ hoang (ruộng đất); bỏ bê, để mai một (việc học, tay nghề)","explanation":"荒 (hoang vắng/hoang đường) + 废 (phế bỏ/hoang phế).","hsk_level":"7-9","tags":["dong-tu"],"image":"🥀","examples":[{"type":"basic","zh":"他荒废了学业。","pinyin":"Tā huāngfèile xuéyè.","vi":"Anh ấy bỏ bê việc học."},{"type":"simple","zh":"村里那几亩荒废多年的田地重新种上了水稻。","pinyin":"Cūnlǐ nà jǐ mǔ huāngfèi duōnián de tiándì chóngxīn zhòng shàngle shuǐdào.","vi":"Mấy mẫu ruộng bỏ hoang nhiều năm trong làng đã được trồng lúa trở lại."},{"type":"compound","zh":"如果长时间不练习，你的钢琴技艺就会慢慢荒废。","pinyin":"Rúguǒ cháng shíjiān bú liànxí, nǐ de gāngqín jìyì jiù huì mànmàn huāngfèi.","vi":"Nếu lâu không luyện tập, tay nghề piano của bạn sẽ dần mai một."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"},{"hanzi":"荒芜","pinyin":"huāngwú","vi":"hoang vu"},{"hanzi":"废弃","pinyin":"fèiqì","vi":"bỏ phế"}],"traditional":"荒廢"},{"id":"荒漠化","hanzi":"荒漠化","pinyin":"huāngmòhuà","meaning_vi":"sa mạc hóa","explanation":"荒 (hoang vắng/hoang đường) + 漠 (漠) + 化 (化).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"荒漠化威胁着草原。","pinyin":"Huāngmòhuà wēixiézhe cǎoyuán.","vi":"Sa mạc hóa đang đe dọa thảo nguyên."},{"type":"simple","zh":"过度放牧是造成这片草原荒漠化的主要原因。","pinyin":"Guòdù fàngmù shì zàochéng zhè piàn cǎoyuán huāngmòhuà de zhǔyào yuányīn.","vi":"Chăn thả quá mức là nguyên nhân chính gây sa mạc hóa vùng thảo nguyên này."},{"type":"compound","zh":"如果不及时种草固沙，荒漠化就会继续向南扩展。","pinyin":"Rúguǒ bù jíshí zhòngcǎo gù shā, huāngmòhuà jiù huì jìxù xiàng nán kuòzhǎn.","vi":"Nếu không kịp trồng cỏ giữ cát, sa mạc hóa sẽ tiếp tục lan về phía nam."}],"related":[{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"沙尘暴","pinyin":"shāchénbào","vi":"bão cát"},{"hanzi":"水土流失","pinyin":"shuǐtǔliúshī","vi":"xói mòn đất"}]},{"id":"毁誉参半","hanzi":"毁誉参半","pinyin":"huǐyù-cānbàn","meaning_vi":"khen chê lẫn lộn","explanation":"毁 (hủy diệt) + 誉 (danh dự/ca ngợi) + 参 (参) + 半 (một nửa).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"这部电影毁誉参半。","pinyin":"Zhè bù diànyǐng huǐyùcānbàn.","vi":"Bộ phim này khen chê lẫn lộn."},{"type":"simple","zh":"这位改革派官员在历史上的评价一直毁誉参半。","pinyin":"Zhè wèi gǎigépài guānyuán zài lìshǐshang de píngjià yìzhí huǐyùcānbàn.","vi":"Đánh giá lịch sử về vị quan cải cách này luôn khen chê lẫn lộn."},{"type":"compound","zh":"虽然新版教材毁誉参半，但是它确实引发了不少有益的讨论。","pinyin":"Suīrán xīnbǎn jiàocái huǐyùcānbàn, dànshì tā quèshí yǐnfāle bùshǎo yǒuyì de tǎolùn.","vi":"Tuy bộ giáo trình mới khen chê lẫn lộn, nhưng nó thực sự đã khơi dậy nhiều cuộc thảo luận bổ ích."}],"related":[{"hanzi":"褒贬不一","pinyin":"bāobiǎnbùyī","vi":"khen chê khác nhau"},{"hanzi":"争议","pinyin":"zhēngyì","vi":"tranh cãi"},{"hanzi":"好坏参半","pinyin":"hǎohuàicānbàn","vi":"tốt xấu lẫn lộn"}],"traditional":"毀譽參半"},{"id":"火候","hanzi":"火候","pinyin":"huǒhou","meaning_vi":"độ lửa (nấu ăn); độ chín muồi, trình độ (tay nghề)","explanation":"火 (hỏa – lửa) + 候 (hậu – thời điểm, mức độ) → độ lửa, thời gian đun nấu; nghĩa bóng: độ thuần thục, đúng thời điểm. VD: 火候不到.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🔥","examples":[{"type":"basic","zh":"炖汤要掌握火候。","pinyin":"Dùn tāng yào zhǎngwò huǒhou.","vi":"Hầm canh phải canh đúng độ lửa."},{"type":"simple","zh":"这位老师傅炒菜的火候拿捏得恰到好处。","pinyin":"Zhè wèi lǎo shīfu chǎocài de huǒhou nániē de qiàdàohǎochù.","vi":"Ông đầu bếp già canh lửa khi xào món ăn vừa vặn hoàn hảo."},{"type":"compound","zh":"他的书法虽然有了进步，但是火候还差一些。","pinyin":"Tā de shūfǎ suīrán yǒule jìnbù, dànshì huǒhou hái chà yìxiē.","vi":"Thư pháp của anh tuy có tiến bộ, nhưng độ chín muồi vẫn còn thiếu chút ít."}],"related":[{"hanzi":"火力","pinyin":"huǒlì","vi":"sức lửa"},{"hanzi":"分寸","pinyin":"fēncun","vi":"chừng mực"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"công phu"}]},{"id":"火热","hanzi":"火热","pinyin":"huǒrè","meaning_vi":"nóng bỏng, sôi nổi nhiệt huyết","explanation":"火 (hỏa – lửa) + 热 (nhiệt – nóng) → nóng như lửa; nghĩa bóng: sôi nổi, nồng nhiệt, nóng bỏng. VD: 火热的夏天, 火热的心.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"工地上一派火热的景象。","pinyin":"Gōngdì shang yí pài huǒrè de jǐngxiàng.","vi":"Công trường là một khung cảnh sôi động."},{"type":"simple","zh":"年轻人怀着一颗火热的心投身到乡村建设中。","pinyin":"Niánqīngrén huáizhe yì kē huǒrè de xīn tóushēn dào xiāngcūn jiànshè zhōng.","vi":"Người trẻ mang trái tim nhiệt huyết dấn thân vào xây dựng nông thôn."},{"type":"compound","zh":"虽然外面寒风刺骨，但是体育馆里的比赛气氛十分火热。","pinyin":"Suīrán wàimiàn hánfēng cìgǔ, dànshì tǐyùguǎn lǐ de bǐsài qìfēn shífēn huǒrè.","vi":"Tuy ngoài trời gió rét buốt xương, nhưng không khí trận đấu trong nhà thi đấu vô cùng sôi nổi."}],"related":[{"hanzi":"热烈","pinyin":"rèliè","vi":"sôi nổi"},{"hanzi":"炎热","pinyin":"yánrè","vi":"nóng bức"},{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"}],"traditional":"火熱"},{"id":"火山爆发","hanzi":"火山爆发","pinyin":"huǒshānbàofā","meaning_vi":"núi lửa phun trào","explanation":"火 (火) + 山 (núi non) + 爆 (爆) + 发 (发).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌋","examples":[{"type":"basic","zh":"那座岛上发生了火山爆发。","pinyin":"Nà zuò dǎo shang fāshēngle huǒshānbàofā.","vi":"Trên hòn đảo đó đã xảy ra núi lửa phun trào."},{"type":"simple","zh":"古城庞贝在一次火山爆发中被火山灰掩埋了。","pinyin":"Gǔchéng Pángbèi zài yí cì huǒshānbàofā zhōng bèi huǒshānhuī yǎnmái le.","vi":"Thành cổ Pompeii bị tro núi lửa chôn vùi trong một lần núi lửa phun trào."},{"type":"compound","zh":"由于火山爆发产生大量火山灰，所以附近机场全部关闭了。","pinyin":"Yóuyú huǒshānbàofā chǎnshēng dàliàng huǒshānhuī, suǒyǐ fùjìn jīchǎng quánbù guānbì le.","vi":"Do núi lửa phun trào tạo ra lượng lớn tro bụi nên các sân bay lân cận đều đóng cửa."}],"related":[{"hanzi":"火山","pinyin":"huǒshān","vi":"núi lửa"},{"hanzi":"地震","pinyin":"dìzhèn","vi":"động đất"},{"hanzi":"岩浆","pinyin":"yánjiāng","vi":"dung nham"}],"traditional":"火山爆發"},{"id":"含金量","hanzi":"含金量","pinyin":"hánjīnliàng","meaning_vi":"hàm lượng vàng; giá trị thực chất (của bằng cấp, giải thưởng)","explanation":"含 (含) + 金 (金) + 量 (đo lường/số lượng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🥇","examples":[{"type":"basic","zh":"这个证书含金量很高。","pinyin":"Zhè ge zhèngshū hánjīnliàng hěn gāo.","vi":"Chứng chỉ này có giá trị thực chất rất cao."},{"type":"simple","zh":"这枚金币的含金量达到了百分之九十九点九。","pinyin":"Zhè méi jīnbì de hánjīnliàng dádàole bǎifēnzhī jiǔ shíjiǔ diǎn jiǔ.","vi":"Hàm lượng vàng của đồng xu này đạt 99,9%."},{"type":"compound","zh":"如果比赛评审不够公正，奖项的含金量就会大打折扣。","pinyin":"Rúguǒ bǐsài píngshěn búgòu gōngzhèng, jiǎngxiàng de hánjīnliàng jiù huì dà dǎzhékòu.","vi":"Nếu việc chấm thi không công bằng, giá trị thực của giải thưởng sẽ giảm sút nhiều."}],"related":[{"hanzi":"含量","pinyin":"hánliàng","vi":"hàm lượng"},{"hanzi":"价值","pinyin":"jiàzhí","vi":"giá trị"},{"hanzi":"分量","pinyin":"fènliàng","vi":"tầm quan trọng"}]},{"id":"涵养","hanzi":"涵养","pinyin":"hányǎng","meaning_vi":"sự tu dưỡng, điềm đạm; giữ gìn, tích trữ (nguồn nước)","explanation":"涵 (涵) + 养 (nuôi dưỡng/tu dưỡng).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧘","examples":[{"type":"basic","zh":"他很有涵养。","pinyin":"Tā hěn yǒu hányǎng.","vi":"Anh ấy rất có tu dưỡng, điềm đạm."},{"type":"simple","zh":"这片森林在涵养水源方面发挥着重要作用。","pinyin":"Zhè piàn sēnlín zài hányǎng shuǐyuán fāngmiàn fāhuīzhe zhòngyào zuòyòng.","vi":"Khu rừng này đóng vai trò quan trọng trong việc giữ gìn nguồn nước."},{"type":"compound","zh":"即使被顾客当面指责，那位店长也很有涵养地微笑回应。","pinyin":"Jíshǐ bèi gùkè dāngmiàn zhǐzé, nà wèi diànzhǎng yě hěn yǒu hányǎng de wēixiào huíyìng.","vi":"Dù bị khách chỉ trích ngay trước mặt, vị cửa hàng trưởng vẫn điềm đạm mỉm cười đáp lại."}],"related":[{"hanzi":"修养","pinyin":"xiūyǎng","vi":"tu dưỡng"},{"hanzi":"素养","pinyin":"sùyǎng","vi":"tố chất"},{"hanzi":"水源","pinyin":"shuǐyuán","vi":"nguồn nước"}],"traditional":"涵養"},{"id":"航天器","hanzi":"航天器","pinyin":"hángtiānqì","meaning_vi":"tàu vũ trụ, thiết bị bay vào vũ trụ","explanation":"航 (航) + 天 (ngày) + 器 (thiết bị/cơ quan).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🚀","examples":[{"type":"basic","zh":"航天器成功入轨。","pinyin":"Hángtiānqì chénggōng rùguǐ.","vi":"Tàu vũ trụ đã vào quỹ đạo thành công."},{"type":"simple","zh":"这个航天器将在月球背面采集岩石样本。","pinyin":"Zhè ge hángtiānqì jiāng zài yuèqiú bèimiàn cǎijí yánshí yàngběn.","vi":"Tàu vũ trụ này sẽ thu thập mẫu đá ở mặt sau Mặt Trăng."},{"type":"compound","zh":"航天器一进入大气层，表面温度就会急剧升高。","pinyin":"Hángtiānqì yí jìnrù dàqìcéng, biǎomiàn wēndù jiù huì jíjù shēnggāo.","vi":"Tàu vũ trụ vừa đi vào tầng khí quyển, nhiệt độ bề mặt sẽ tăng vọt."}],"related":[{"hanzi":"宇宙飞船","pinyin":"yǔzhòufēichuán","vi":"tàu vũ trụ"},{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"航天员","pinyin":"hángtiānyuán","vi":"phi hành gia"}]},{"id":"航天员","hanzi":"航天员","pinyin":"hángtiānyuán","meaning_vi":"phi hành gia","explanation":"航天 (hàng thiên – bay vào vũ trụ) + 员 (viên – người làm) → nhà du hành vũ trụ (cách gọi của TQ). VD: 中国航天员.","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","khoa-hoc"],"image":"👨‍🚀","examples":[{"type":"basic","zh":"航天员安全返回地球。","pinyin":"Hángtiānyuán ānquán fǎnhuí dìqiú.","vi":"Phi hành gia đã trở về Trái Đất an toàn."},{"type":"simple","zh":"三名航天员将在空间站工作和生活六个月。","pinyin":"Sān míng hángtiānyuán jiāng zài kōngjiānzhàn gōngzuò hé shēnghuó liù gèyuè.","vi":"Ba phi hành gia sẽ làm việc và sinh sống trên trạm vũ trụ sáu tháng."},{"type":"compound","zh":"航天员不但要身体素质过硬，而且要有极强的心理承受能力。","pinyin":"Hángtiānyuán búdàn yào shēntǐ sùzhì guòyìng, érqiě yàoyǒu jí qiáng de xīnlǐ chéngshòu nénglì.","vi":"Phi hành gia không những phải có thể lực vững vàng mà còn phải có khả năng chịu đựng tâm lý cực tốt."}],"related":[{"hanzi":"宇航员","pinyin":"yǔhángyuán","vi":"phi hành gia"},{"hanzi":"航天器","pinyin":"hángtiānqì","vi":"tàu vũ trụ"},{"hanzi":"空间站","pinyin":"kōngjiānzhàn","vi":"trạm vũ trụ"}],"traditional":"航天員"},{"id":"航线","hanzi":"航线","pinyin":"hángxiàn","meaning_vi":"đường bay, tuyến hàng hải","explanation":"航 (航) + 线 (manh mối/đường nét).","hsk_level":"7-9","tags":["danh-tu","giao-thong","du-lich"],"image":"✈️","examples":[{"type":"basic","zh":"航空公司开通了新航线。","pinyin":"Hángkōng gōngsī kāitōngle xīn hángxiàn.","vi":"Hãng hàng không đã mở đường bay mới."},{"type":"simple","zh":"这条航线每周有三个航班往返河内和广州。","pinyin":"Zhè tiáo hángxiàn měizhōu yǒu sān gè hángbān wǎngfǎn Hénèi hé Guǎngzhōu.","vi":"Đường bay này mỗi tuần có ba chuyến khứ hồi giữa Hà Nội và Quảng Châu."},{"type":"compound","zh":"因为台风即将登陆，所以这条海上航线暂停运营。","pinyin":"Yīnwèi táifēng jíjiāng dēnglù, suǒyǐ zhè tiáo hǎishàng hángxiàn zàntíng yùnyíng.","vi":"Vì bão sắp đổ bộ nên tuyến hàng hải này tạm ngừng hoạt động."}],"related":[{"hanzi":"航班","pinyin":"hángbān","vi":"chuyến bay"},{"hanzi":"路线","pinyin":"lùxiàn","vi":"tuyến đường"},{"hanzi":"航空公司","pinyin":"hángkōnggōngsī","vi":"hãng hàng không"}],"traditional":"航線"},{"id":"行政权","hanzi":"行政权","pinyin":"xíngzhèngquán","meaning_vi":"quyền hành pháp","explanation":"行 (được) + 政 (chính sách/chính trị) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🏛️","examples":[{"type":"basic","zh":"总统拥有行政权。","pinyin":"Zǒngtǒng yōngyǒu xíngzhèngquán.","vi":"Tổng thống nắm quyền hành pháp."},{"type":"simple","zh":"宪法对政府行政权的行使范围作出了明确规定。","pinyin":"Xiànfǎ duì zhèngfǔ xíngzhèngquán de xíngshǐ fànwéi zuòchūle míngquè guīdìng.","vi":"Hiến pháp quy định rõ phạm vi thực thi quyền hành pháp của chính phủ."},{"type":"compound","zh":"如果行政权缺乏有效监督，就容易出现滥用权力的现象。","pinyin":"Rúguǒ xíngzhèngquán quēfá yǒuxiào jiāndū, jiù róngyì chūxiàn lànyòng quánlì de xiànxiàng.","vi":"Nếu quyền hành pháp thiếu giám sát hiệu quả thì dễ xảy ra hiện tượng lạm quyền."}],"related":[{"hanzi":"立法权","pinyin":"lìfǎquán","vi":"quyền lập pháp"},{"hanzi":"司法权","pinyin":"sīfǎquán","vi":"quyền tư pháp"},{"hanzi":"政府","pinyin":"zhèngfǔ","vi":"chính phủ"}],"traditional":"行政權"},{"id":"豪情","hanzi":"豪情","pinyin":"háoqíng","meaning_vi":"tình cảm hào hùng sôi nổi","explanation":"豪 (豪) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他心中充满豪情。","pinyin":"Tā xīnzhōng chōngmǎn háoqíng.","vi":"Lòng anh tràn đầy khí thế hào hùng."},{"type":"simple","zh":"站在长城上的他不禁豪情满怀。","pinyin":"Zhàn zài Chángchéng shang de tā bùjīn háoqíng mǎnhuái.","vi":"Đứng trên Vạn Lý Trường Thành, anh không khỏi dâng trào hào khí."},{"type":"compound","zh":"虽然已经年过六十，但是他攀登雪山的豪情丝毫不减。","pinyin":"Suīrán yǐjīng niánguò liùshí, dànshì tā pāndēng xuěshān de háoqíng sī háobù jiǎn.","vi":"Tuy đã ngoài sáu mươi, nhưng hào khí chinh phục núi tuyết của ông không hề suy giảm."}],"related":[{"hanzi":"激情","pinyin":"jīqíng","vi":"nhiệt huyết"},{"hanzi":"壮志","pinyin":"zhuàngzhì","vi":"chí lớn"},{"hanzi":"豪迈","pinyin":"háomài","vi":"hào hùng"}]},{"id":"核电站","hanzi":"核电站","pinyin":"hédiànzhàn","meaning_vi":"nhà máy điện hạt nhân","explanation":"核 (hạt nhân/kiểm tra) + 电 (电) + 站 (đứng).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","dia-diem"],"image":"🏭","examples":[{"type":"basic","zh":"这里建了一座核电站。","pinyin":"Zhèlǐ jiànle yí zuò hédiànzhàn.","vi":"Ở đây đã xây một nhà máy điện hạt nhân."},{"type":"simple","zh":"这座核电站每年能为沿海城市提供大量清洁电力。","pinyin":"Zhè zuò hédiànzhàn měinián néng wèi yánhǎi chéngshì tígōng dàliàng qīngjié diànlì.","vi":"Nhà máy điện hạt nhân này mỗi năm cung cấp lượng lớn điện sạch cho các thành phố ven biển."},{"type":"compound","zh":"虽然核电站发电效率高，但是一旦发生泄漏后果不堪设想。","pinyin":"Suīrán hédiànzhàn fādiàn xiàolǜ gāo, dànshì yídàn fāshēng xièlòu hòuguǒ bùkān shèxiǎng.","vi":"Tuy nhà máy điện hạt nhân phát điện hiệu suất cao, nhưng một khi rò rỉ thì hậu quả khôn lường."}],"related":[{"hanzi":"核能","pinyin":"hénéng","vi":"năng lượng hạt nhân"},{"hanzi":"发电站","pinyin":"fādiànzhàn","vi":"nhà máy điện"},{"hanzi":"核辐射","pinyin":"héfúshè","vi":"phóng xạ hạt nhân"}],"traditional":"核電站"},{"id":"合法化","hanzi":"合法化","pinyin":"héfǎhuà","meaning_vi":"hợp pháp hóa","explanation":"合法 (hợp pháp) + 化 (hóa – làm cho) → hợp pháp hóa, làm cho được pháp luật thừa nhận. VD: 同性婚姻合法化.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"该行为尚未合法化。","pinyin":"Gāi xíngwéi shàngwèi héfǎhuà.","vi":"Hành vi này vẫn chưa được hợp pháp hóa."},{"type":"simple","zh":"这个国家去年正式把网约车运营合法化了。","pinyin":"Zhè ge guójiā qùnián zhèngshì bǎ wǎngyuēchē yùnyíng héfǎhuà le.","vi":"Năm ngoái nước này đã chính thức hợp pháp hóa dịch vụ gọi xe công nghệ."},{"type":"compound","zh":"即使某些交易被合法化了，监管部门也不能放松审查。","pinyin":"Jíshǐ mǒuxiē jiāoyì bèi héfǎhuà le, jiānguǎn bùmén yě bù néng fàngsōng shěnchá.","vi":"Dù một số giao dịch đã được hợp pháp hóa, cơ quan quản lý cũng không được nới lỏng thẩm tra."}],"related":[{"hanzi":"合法","pinyin":"héfǎ","vi":"hợp pháp"},{"hanzi":"非法","pinyin":"fēifǎ","vi":"phi pháp"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"}]},{"id":"合法权益","hanzi":"合法权益","pinyin":"héfǎquányì","meaning_vi":"quyền và lợi ích hợp pháp","explanation":"合法 (hợp pháp) + 权益 (quyền ích – quyền và lợi ích) → quyền lợi hợp pháp. VD: 维护消费者的合法权益.","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"消费者要维护合法权益。","pinyin":"Xiāofèizhě yào wéihù héfǎquányì.","vi":"Người tiêu dùng cần bảo vệ quyền lợi hợp pháp của mình."},{"type":"simple","zh":"工会代表工人与资方谈判以保障他们的合法权益。","pinyin":"Gōnghuì dàibiǎo gōngrén yǔ zīfāng tánpàn yǐ bǎozhàng tāmen de héfǎquányì.","vi":"Công đoàn đại diện công nhân đàm phán với giới chủ để bảo đảm quyền lợi hợp pháp của họ."},{"type":"compound","zh":"如果你的合法权益受到侵害，就可以向法院提起诉讼。","pinyin":"Rúguǒ nǐ de héfǎquányì shòudào qīnhài, jiù kěyǐ xiàng fǎyuàn tíqǐ sùsòng.","vi":"Nếu quyền lợi hợp pháp của bạn bị xâm hại, bạn có thể khởi kiện ra tòa."}],"related":[{"hanzi":"权益","pinyin":"quányì","vi":"quyền lợi"},{"hanzi":"维权","pinyin":"wéiquán","vi":"bảo vệ quyền lợi"},{"hanzi":"合法","pinyin":"héfǎ","vi":"hợp pháp"}],"traditional":"合法權益"},{"id":"合力","hanzi":"合力","pinyin":"hélì","meaning_vi":"hợp lực, sức mạnh chung","explanation":"合 (合) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"大家齐心形成合力。","pinyin":"Dàjiā qíxīn xíngchéng hélì.","vi":"Mọi người đồng lòng tạo thành sức mạnh chung."},{"type":"simple","zh":"几个村民合力把陷在泥里的拖拉机推了出来。","pinyin":"Jǐ gè cūnmín hélì bǎ xiàn zài ní lǐ de tuōlājī tuīle chūlái.","vi":"Mấy người dân hợp sức đẩy chiếc máy kéo bị sa lầy ra."},{"type":"compound","zh":"只要家庭和学校形成合力，孩子的坏习惯就容易改正。","pinyin":"Zhǐyào jiātíng hé xuéxiào xíngchéng hélì, háizi de huài xíguàn jiù róngyì gǎizhèng.","vi":"Chỉ cần gia đình và nhà trường hợp sức, thói quen xấu của trẻ sẽ dễ sửa."}],"related":[{"hanzi":"协力","pinyin":"xiélì","vi":"hiệp lực"},{"hanzi":"齐心协力","pinyin":"qíxīnxiélì","vi":"đồng lòng hiệp lực"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"}]},{"id":"合理化","hanzi":"合理化","pinyin":"hélǐhuà","meaning_vi":"hợp lý hóa","explanation":"合 (合) + 理 (lý luận/quản lý) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"他提了合理化建议。","pinyin":"Tā tíle hélǐhuà jiànyì.","vi":"Anh ấy đã đưa ra đề xuất hợp lý hóa."},{"type":"simple","zh":"工厂对生产线布局进行了合理化调整。","pinyin":"Gōngchǎng duìshēng chǎnxiàn bùjú jìnxíngle hélǐhuà tiáozhěng.","vi":"Nhà máy đã điều chỉnh hợp lý hóa bố cục dây chuyền sản xuất."},{"type":"compound","zh":"与其一味地为错误找借口把它合理化，不如坦然承认。","pinyin":"Yǔqí yíwèi de wèi cuòwù zhǎojièkǒu bǎ tā hélǐhuà, bùrú tǎnrán chéngrèn.","vi":"Thay vì cứ tìm cớ để hợp lý hóa lỗi lầm, chi bằng thẳng thắn thừa nhận."}],"related":[{"hanzi":"合理","pinyin":"hélǐ","vi":"hợp lý"},{"hanzi":"优化","pinyin":"yōuhuà","vi":"tối ưu hóa"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"chuẩn hóa"}]},{"id":"核能","hanzi":"核能","pinyin":"hénéng","meaning_vi":"năng lượng hạt nhân","explanation":"核 (hạt nhân/kiểm tra) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚛️","examples":[{"type":"basic","zh":"核能是一种清洁能源。","pinyin":"Hénéng shì yì zhǒng qīngjié néngyuán.","vi":"Năng lượng hạt nhân là một nguồn năng lượng sạch."},{"type":"simple","zh":"法国超过一半的电力来自核能发电。","pinyin":"Fǎguó chāoguò yíbàn de diànlì láizì hénéng fādiàn.","vi":"Hơn một nửa lượng điện của Pháp đến từ điện hạt nhân."},{"type":"compound","zh":"核能虽然能减少碳排放，但是核废料的处理仍是难题。","pinyin":"Hénéng suīrán néng jiǎnshǎo tànpáifàng, dànshì hé fèiliào de chǔlǐ réng shì nántí.","vi":"Năng lượng hạt nhân tuy giảm được phát thải carbon, nhưng xử lý chất thải hạt nhân vẫn là bài toán khó."}],"related":[{"hanzi":"核电站","pinyin":"hédiànzhàn","vi":"nhà máy điện hạt nhân"},{"hanzi":"太阳能","pinyin":"tàiyángnéng","vi":"năng lượng mặt trời"},{"hanzi":"能源","pinyin":"néngyuán","vi":"năng lượng"}]},{"id":"和平共处","hanzi":"和平共处","pinyin":"hépínggòngchǔ","meaning_vi":"chung sống hòa bình","explanation":"和平 (hòa bình) + 共处 (cộng xử – cùng chung sống) → chung sống hòa bình; nằm trong 和平共处五项原则 (5 nguyên tắc chung sống hòa bình).","hsk_level":"7-9","tags":["dong-tu","xa-hoi","giao-tiep"],"image":"🕊️","examples":[{"type":"basic","zh":"两国和平共处多年。","pinyin":"Liǎngguó hépínggòngchǔ duōnián.","vi":"Hai nước chung sống hòa bình nhiều năm."},{"type":"simple","zh":"这个小镇上不同民族的居民一直和平共处。","pinyin":"Zhè ge xiǎozhèn shang bùtóng mínzú de jūmín yìzhí hépínggòngchǔ.","vi":"Cư dân các dân tộc khác nhau ở thị trấn nhỏ này luôn chung sống hòa bình."},{"type":"compound","zh":"只要彼此尊重主权，国家之间就能和平共处。","pinyin":"Zhǐyào bǐcǐ zūnzhòng zhǔquán, guójiā zhījiān jiù néng hépínggòngchǔ.","vi":"Chỉ cần tôn trọng chủ quyền của nhau, các quốc gia có thể chung sống hòa bình."}],"related":[{"hanzi":"和平","pinyin":"hépíng","vi":"hòa bình"},{"hanzi":"和睦相处","pinyin":"hémùxiāngchǔ","vi":"sống hòa thuận"},{"hanzi":"共存","pinyin":"gòngcún","vi":"cùng tồn tại"}],"traditional":"和平共處"},{"id":"和声","hanzi":"和声","pinyin":"héshēng","meaning_vi":"hòa âm","explanation":"和 (và) + 声 (thanh thế/tuyên bố).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎵","examples":[{"type":"basic","zh":"这段和声很优美。","pinyin":"Zhè duàn héshēng hěn yōuměi.","vi":"Đoạn hòa âm này rất du dương."},{"type":"simple","zh":"合唱团用四个声部唱出了层次丰富的和声。","pinyin":"Héchàngtuán yòng sì gè shēngbù chàng chūle céngcì fēngfù de héshēng.","vi":"Dàn hợp xướng dùng bốn bè hát nên phần hòa âm nhiều tầng lớp."},{"type":"compound","zh":"如果没有和声的衬托，这首歌的旋律就会显得单薄。","pinyin":"Rúguǒ méiyǒu héshēng de chèntuō, zhè shǒu gē de xuánlǜ jiù huì xiǎnde dānbó.","vi":"Nếu không có hòa âm làm nền, giai điệu bài hát này sẽ trở nên đơn điệu."}],"related":[{"hanzi":"旋律","pinyin":"xuánlǜ","vi":"giai điệu"},{"hanzi":"合唱","pinyin":"héchàng","vi":"hợp xướng"},{"hanzi":"节奏","pinyin":"jiézòu","vi":"nhịp điệu"}],"traditional":"和聲"},{"id":"核酸检测","hanzi":"核酸检测","pinyin":"hésuānjiǎncè","meaning_vi":"xét nghiệm axit nucleic (PCR)","explanation":"核 (hạt nhân/kiểm tra) + 酸 (chua) + 检 (kiểm tra) + 测 (测).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","khoa-hoc"],"image":"🧪","examples":[{"type":"basic","zh":"他去做了核酸检测。","pinyin":"Tā qù zuòle hésuānjiǎncè.","vi":"Anh ấy đã đi xét nghiệm axit nucleic."},{"type":"simple","zh":"入境旅客需要出示四十八小时内的核酸检测报告。","pinyin":"Rùjìng lǚkè xūyào chūshì sì shíbā xiǎoshí nèi de hésuānjiǎncè bàogào.","vi":"Hành khách nhập cảnh cần xuất trình kết quả xét nghiệm PCR trong vòng 48 giờ."},{"type":"compound","zh":"如果核酸检测结果呈阳性，就必须立即隔离治疗。","pinyin":"Rúguǒ hésuānjiǎncè jiéguǒ chéngyángxìng, jiù bìxū lìjí gélí zhìliáo.","vi":"Nếu kết quả xét nghiệm PCR dương tính thì phải cách ly điều trị ngay."}],"related":[{"hanzi":"检测","pinyin":"jiǎncè","vi":"xét nghiệm"},{"hanzi":"疫苗","pinyin":"yìmiáo","vi":"vắc-xin"},{"hanzi":"阴性","pinyin":"yīnxìng","vi":"âm tính"}],"traditional":"核酸檢測"},{"id":"核武器","hanzi":"核武器","pinyin":"héwǔqì","meaning_vi":"vũ khí hạt nhân","explanation":"核 (hạt nhân/kiểm tra) + 武 (võ thuật/vũ trang) + 器 (thiết bị/cơ quan).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","khoa-hoc"],"image":"☢️","examples":[{"type":"basic","zh":"世界需要销毁核武器。","pinyin":"Shìjiè xūyào xiāohuǐ héwǔqì.","vi":"Thế giới cần tiêu hủy vũ khí hạt nhân."},{"type":"simple","zh":"联合国多次呼吁有关国家停止研发核武器。","pinyin":"Liánhéguó duōcì hūyù yǒuguān guójiā tíngzhǐ yánfā héwǔqì.","vi":"Liên Hợp Quốc nhiều lần kêu gọi các nước liên quan ngừng phát triển vũ khí hạt nhân."},{"type":"compound","zh":"如果爆发核武器冲突，整个人类文明都可能遭受毁灭。","pinyin":"Rúguǒ bàofā héwǔqì chōngtū, zhěnggè rénlèi wénmíng dōu kěnéng zāoshòu huǐmiè.","vi":"Nếu nổ ra xung đột vũ khí hạt nhân, cả nền văn minh nhân loại đều có thể bị hủy diệt."}],"related":[{"hanzi":"核弹","pinyin":"hédàn","vi":"bom hạt nhân"},{"hanzi":"导弹","pinyin":"dǎodàn","vi":"tên lửa"},{"hanzi":"裁军","pinyin":"cáijūn","vi":"giải trừ quân bị"}]},{"id":"核心竞争力","hanzi":"核心竞争力","pinyin":"héxīn jìngzhēnglì","meaning_vi":"năng lực cạnh tranh cốt lõi","explanation":"核心 (hạch tâm – cốt lõi) + 竞争力 (năng lực cạnh tranh) → năng lực cạnh tranh cốt lõi, lợi thế khó sao chép của doanh nghiệp/quốc gia.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏆","examples":[{"type":"basic","zh":"技术是核心竞争力。","pinyin":"Jìshù shì héxīnjìngzhēnglì.","vi":"Công nghệ là năng lực cạnh tranh cốt lõi."},{"type":"simple","zh":"这家手机企业把自主研发的芯片视为核心竞争力。","pinyin":"Zhè jiā shǒujī qǐyè bǎ zìzhǔ yánfā de xīnpiàn shìwéi héxīnjìngzhēnglì.","vi":"Doanh nghiệp điện thoại này coi chip tự nghiên cứu là năng lực cạnh tranh cốt lõi."},{"type":"compound","zh":"如果没有核心竞争力，企业就很容易被市场淘汰。","pinyin":"Rúguǒ méiyǒu héxīnjìngzhēnglì, qǐyè jiù hěn róngyì bèi shìchǎng táotài.","vi":"Nếu không có năng lực cạnh tranh cốt lõi, doanh nghiệp rất dễ bị thị trường đào thải."}],"related":[{"hanzi":"竞争力","pinyin":"jìngzhēnglì","vi":"sức cạnh tranh"},{"hanzi":"核心","pinyin":"héxīn","vi":"cốt lõi"},{"hanzi":"优势","pinyin":"yōushì","vi":"ưu thế"}],"traditional":"核心競爭力"},{"id":"合奏","hanzi":"合奏","pinyin":"hézòu","meaning_vi":"hòa tấu","explanation":"合 (hợp – cùng nhau) + 奏 (tấu – diễn nhạc) → hòa tấu, nhiều nhạc cụ cùng biểu diễn; trái với 独奏 (độc tấu).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎶","examples":[{"type":"basic","zh":"他们合奏了一首曲子。","pinyin":"Tāmen hézòule yì shǒu qǔzi.","vi":"Họ đã hòa tấu một bản nhạc."},{"type":"simple","zh":"二胡和钢琴的合奏给观众带来了新奇的听觉体验。","pinyin":"Èrhú hé gāngqín de hézòu gěi guānzhòng dàiláile xīnqí de tīngjué tǐyàn.","vi":"Màn hòa tấu đàn nhị và piano mang lại trải nghiệm thính giác mới lạ cho khán giả."},{"type":"compound","zh":"合奏时只要有一个人抢拍，整首曲子就会乱套。","pinyin":"Hézòu shí zhǐyào yǒu yígèrén qiǎng pāi, zhěng shǒu qǔzi jiù huì luàntào.","vi":"Khi hòa tấu chỉ cần một người vào nhịp sớm, cả bản nhạc sẽ rối loạn."}],"related":[{"hanzi":"独奏","pinyin":"dúzòu","vi":"độc tấu"},{"hanzi":"演奏","pinyin":"yǎnzòu","vi":"biểu diễn nhạc"},{"hanzi":"合唱","pinyin":"héchàng","vi":"hợp xướng"}]},{"id":"横跨","hanzi":"横跨","pinyin":"héngkuà","meaning_vi":"bắc ngang qua, trải rộng qua","explanation":"横 (ngang/hoành hành) + 跨 (bước qua).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🌉","examples":[{"type":"basic","zh":"大桥横跨长江。","pinyin":"Dàqiáo héngkuà Chángjiāng.","vi":"Cây cầu bắc ngang sông Trường Giang."},{"type":"simple","zh":"俄罗斯的国土横跨欧亚两大洲。","pinyin":"Éluósī de Guótǔ héngkuà Ōuyà liǎng dàzhōu.","vi":"Lãnh thổ Nga trải rộng qua hai châu lục Âu và Á."},{"type":"compound","zh":"这座大桥横跨海湾，不但缩短了路程，而且成了城市地标。","pinyin":"Zhè zuò Dàqiáo héngkuà hǎiwān, búdàn suōduǎnle lùchéng, érqiě chéngle chéngshì dìbiāo.","vi":"Cây cầu bắc ngang vịnh này không những rút ngắn quãng đường mà còn trở thành biểu tượng thành phố."}],"related":[{"hanzi":"跨越","pinyin":"kuàyuè","vi":"vượt qua"},{"hanzi":"横贯","pinyin":"héngguàn","vi":"xuyên ngang"},{"hanzi":"跨度","pinyin":"kuàdù","vi":"nhịp cầu"}],"traditional":"橫跨"},{"id":"恒心","hanzi":"恒心","pinyin":"héngxīn","meaning_vi":"lòng kiên trì bền bỉ","explanation":"恒 (恒) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"✊","examples":[{"type":"basic","zh":"学外语要有恒心。","pinyin":"Xué wàiyǔ yàoyǒu héngxīn.","vi":"Học ngoại ngữ phải có lòng kiên trì."},{"type":"simple","zh":"他凭着恒心坚持晨跑了整整三年。","pinyin":"Tā píngzhe héngxīn jiānchí chénpǎole zhěngzhěng sān nián.","vi":"Anh nhờ lòng kiên trì đã chạy bộ buổi sáng suốt ba năm."},{"type":"compound","zh":"只要有恒心和毅力，再粗的铁杵也能磨成细针。","pinyin":"Zhǐ yàoyǒu héngxīn hé yìlì, zài cū de tiě chǔ yě néng mó chéng xì zhēn.","vi":"Chỉ cần có lòng kiên trì và nghị lực, chày sắt to đến mấy cũng mài thành kim nhỏ."}],"related":[{"hanzi":"毅力","pinyin":"yìlì","vi":"nghị lực"},{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"},{"hanzi":"持之以恒","pinyin":"chízhīyǐhéng","vi":"bền bỉ kiên trì"}],"traditional":"恆心"},{"id":"后盾","hanzi":"后盾","pinyin":"hòudùn","meaning_vi":"hậu thuẫn, chỗ dựa vững chắc","explanation":"后 (sau) + 盾 (cái khiên).","hsk_level":"7-9","tags":["danh-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"家人是我的后盾。","pinyin":"Jiārén shì wǒ de hòudùn.","vi":"Gia đình là chỗ dựa của tôi."},{"type":"simple","zh":"强大的国防是国家经济发展的坚强后盾。","pinyin":"Qiángdà de guófáng shì guójiā jīngjì fāzhǎn de jiānqiáng hòudùn.","vi":"Quốc phòng vững mạnh là hậu thuẫn vững chắc cho phát triển kinh tế đất nước."},{"type":"compound","zh":"因为有父母做后盾，所以她敢辞职去追求自己的梦想。","pinyin":"Yīnwèi yǒu fùmǔ zuò hòudùn, suǒyǐ tā gǎn cízhí qù zhuīqiú zìjǐ de mèngxiǎng.","vi":"Vì có bố mẹ làm hậu thuẫn nên cô dám nghỉ việc theo đuổi ước mơ."}],"related":[{"hanzi":"靠山","pinyin":"kàoshān","vi":"chỗ dựa"},{"hanzi":"支持","pinyin":"zhīchí","vi":"ủng hộ"},{"hanzi":"坚强后盾","pinyin":"jiānqiánghòudùn","vi":"hậu thuẫn vững chắc"}],"traditional":"後盾"},{"id":"后劲","hanzi":"后劲","pinyin":"hòujìn","meaning_vi":"sức bật về sau, sức bền lâu dài; (rượu) ngấm về sau","explanation":"后 (sau) + 劲 (sức lực/nhiệt huyết).","hsk_level":"7-9","tags":["danh-tu"],"image":"💪","examples":[{"type":"basic","zh":"这酒后劲很大。","pinyin":"Zhè jiǔ hòujìn hěn dà.","vi":"Rượu này ngấm về sau rất mạnh."},{"type":"simple","zh":"这位长跑运动员在最后一圈显示出了惊人的后劲。","pinyin":"Zhè wèi chángpǎo yùndòngyuán zài zuìhòu yìquān xiǎnshìchūle jīngrén de hòujìn.","vi":"Vận động viên chạy đường dài này cho thấy sức bền đáng kinh ngạc ở vòng cuối."},{"type":"compound","zh":"如果只顾眼前利益，经济发展就会缺乏后劲。","pinyin":"Rúguǒ zhǐgù yǎnqián lìyì, jīngjì fāzhǎn jiù huì quēfá hòujìn.","vi":"Nếu chỉ chăm chăm lợi ích trước mắt, phát triển kinh tế sẽ thiếu sức bật lâu dài."}],"related":[{"hanzi":"潜力","pinyin":"qiánlì","vi":"tiềm năng"},{"hanzi":"劲头","pinyin":"jìntóu","vi":"sức lực"},{"hanzi":"持久","pinyin":"chíjiǔ","vi":"lâu bền"}],"traditional":"後勁"},{"id":"后裔","hanzi":"后裔","pinyin":"hòuyì","meaning_vi":"hậu duệ, con cháu","explanation":"后 (hậu – sau) + 裔 (duệ – dòng dõi) → hậu duệ, con cháu đời sau; văn viết. VD: 名门后裔, 炎黄后裔.","hsk_level":"7-9","tags":["danh-tu","gia-dinh","van-hoa"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"他是孔子的后裔。","pinyin":"Tā shì Kǒngzǐ de hòuyì.","vi":"Ông ấy là hậu duệ của Khổng Tử."},{"type":"simple","zh":"这个村子里住着几百户明代将军的后裔。","pinyin":"Zhè ge cūnzi lǐ zhùzhe jǐ bǎi hù Míngdài jiāngjūn de hòuyì.","vi":"Trong làng này có vài trăm hộ là hậu duệ của một vị tướng đời Minh."},{"type":"compound","zh":"虽然他们是移民后裔，但是一直保留着祖先的语言。","pinyin":"Suīrán tāmen shì yímín hòuyì, dànshì yìzhí bǎoliúzhe zǔxiān de yǔyán.","vi":"Tuy họ là hậu duệ di dân, nhưng vẫn luôn giữ ngôn ngữ của tổ tiên."}],"related":[{"hanzi":"后代","pinyin":"hòudài","vi":"đời sau"},{"hanzi":"子孙","pinyin":"zǐsūn","vi":"con cháu"},{"hanzi":"祖先","pinyin":"zǔxiān","vi":"tổ tiên"}],"traditional":"後裔"},{"id":"后遗症","hanzi":"后遗症","pinyin":"hòuyízhèng","meaning_vi":"di chứng","explanation":"后 (sau) + 遗 (di sản/để lại) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"车祸留下了后遗症。","pinyin":"Chēhuò liúxiàle hòuyízhèng.","vi":"Tai nạn xe để lại di chứng."},{"type":"simple","zh":"他中风后留下了说话不清的后遗症。","pinyin":"Tā zhòngfēng hòu liúxiàle shuōhuà bùqīng de hòuyízhèng.","vi":"Sau cơn đột quỵ, ông bị di chứng nói không rõ."},{"type":"compound","zh":"如果骨折后不好好休养，就可能留下后遗症。","pinyin":"Rúguǒ gǔzhé hòu bù hǎohǎo xiūyǎng, jiù kěnéng liúxià hòuyízhèng.","vi":"Nếu sau khi gãy xương không nghỉ ngơi tử tế, có thể để lại di chứng."}],"related":[{"hanzi":"副作用","pinyin":"fùzuòyòng","vi":"tác dụng phụ"},{"hanzi":"病症","pinyin":"bìngzhèng","vi":"bệnh chứng"},{"hanzi":"康复","pinyin":"kāngfù","vi":"hồi phục"}],"traditional":"後遺症"},{"id":"红茶","hanzi":"红茶","pinyin":"hóngchá","meaning_vi":"hồng trà, trà đen","explanation":"红 (hồng – đỏ) + 茶 (trà) → hồng trà (nước trà màu đỏ), tiếng Anh gọi black tea – trà lên men hoàn toàn.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🫖","examples":[{"type":"basic","zh":"我喜欢喝红茶。","pinyin":"Wǒ xǐhuan hē hóngchá.","vi":"Tôi thích uống hồng trà."},{"type":"simple","zh":"英国人习惯在下午茶时往红茶里加牛奶。","pinyin":"Yīngguórén xíguàn zài xiàwǔchá shí wǎng hóngchá Lǐjiā niúnǎi.","vi":"Người Anh có thói quen cho sữa vào hồng trà trong giờ trà chiều."},{"type":"compound","zh":"因为红茶性温，所以胃不好的人冬天可以适量饮用。","pinyin":"Yīnwèi hóngchá xìng wēn, suǒyǐ wèi bù hǎo de rén dōngtiān kěyǐ shìliàng yǐnyòng.","vi":"Vì hồng trà có tính ấm nên người đau dạ dày có thể uống vừa phải vào mùa đông."}],"related":[{"hanzi":"绿茶","pinyin":"lǜchá","vi":"trà xanh"},{"hanzi":"乌龙茶","pinyin":"wūlóngchá","vi":"trà ô long"},{"hanzi":"茶叶","pinyin":"cháyè","vi":"lá trà"}],"traditional":"紅茶"},{"id":"宏大","hanzi":"宏大","pinyin":"hóngdà","meaning_vi":"to lớn, hoành tráng","explanation":"宏 (vĩ mô/hùng vĩ) + 大 (to).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏛️","examples":[{"type":"basic","zh":"这项工程规模宏大。","pinyin":"Zhè xiàng gōngchéng guīmó hóngdà.","vi":"Công trình này quy mô to lớn."},{"type":"simple","zh":"开幕式以宏大的场面展现了五千年的历史。","pinyin":"Kāimùshì yǐ hóngdà de chǎngmiàn zhǎnxiànle wǔqiānnián de lìshǐ.","vi":"Lễ khai mạc tái hiện năm nghìn năm lịch sử bằng những cảnh tượng hoành tráng."},{"type":"compound","zh":"这部小说虽然篇幅宏大，但是人物刻画得十分细腻。","pinyin":"Zhè bù xiǎoshuō suīrán piānfú hóngdà, dànshì rénwù kèhuà de shífēn xìnì.","vi":"Cuốn tiểu thuyết này tuy dung lượng đồ sộ, nhưng khắc họa nhân vật rất tinh tế."}],"related":[{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"hùng vĩ"},{"hanzi":"巨大","pinyin":"jùdà","vi":"to lớn"},{"hanzi":"渺小","pinyin":"miǎoxiǎo","vi":"nhỏ bé"}]},{"id":"宏观调控","hanzi":"宏观调控","pinyin":"hóngguāntiáokòng","meaning_vi":"điều tiết vĩ mô","explanation":"宏观 (vĩ mô) + 调控 (điều tiết kiểm soát).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"📊","examples":[{"type":"basic","zh":"国家加强了宏观调控。","pinyin":"Guójiā jiāqiángle hóngguāntiáokòng.","vi":"Nhà nước đã tăng cường điều tiết vĩ mô."},{"type":"simple","zh":"央行通过调整利率对房地产市场进行宏观调控。","pinyin":"Yāngháng tōngguò tiáozhěng lìlǜ duì fángdìchǎn shìchǎng jìnxíng hóngguāntiáokòng.","vi":"Ngân hàng trung ương điều tiết vĩ mô thị trường bất động sản thông qua điều chỉnh lãi suất."},{"type":"compound","zh":"如果缺少必要的宏观调控，市场就可能出现过热现象。","pinyin":"Rúguǒ quēshǎo bìyào de hóngguāntiáokòng, shìchǎng jiù kěnéng chūxiàn guòrè xiànxiàng.","vi":"Nếu thiếu sự điều tiết vĩ mô cần thiết, thị trường có thể rơi vào tình trạng quá nóng."}],"related":[{"hanzi":"宏观经济","pinyin":"hóngguānjīngjì","vi":"kinh tế vĩ mô"},{"hanzi":"微观","pinyin":"wēiguān","vi":"vi mô"},{"hanzi":"调控","pinyin":"tiáokòng","vi":"điều tiết"}],"traditional":"宏觀調控"},{"id":"红火","hanzi":"红火","pinyin":"hónghuǒ","meaning_vi":"phát đạt, nhộn nhịp (làm ăn/cuộc sống)","explanation":"红 (màu đỏ) + 火 (火).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"他的小店生意红火。","pinyin":"Tā de xiǎodiàn shēngyi hónghuǒ.","vi":"Cửa hàng nhỏ của anh ấy làm ăn phát đạt."},{"type":"simple","zh":"村民们靠种草莓把日子过得越来越红火。","pinyin":"Cūnmínmen kào zhòng cǎoméi bǎ rìzi guòde yuèláiyuè hónghuǒ.","vi":"Dân làng nhờ trồng dâu tây mà cuộc sống ngày càng sung túc."},{"type":"compound","zh":"自从老街改造完成以后，这里的夜市就一天比一天红火。","pinyin":"Zìcóng lǎojiē gǎizào wánchéng yǐhòu, zhèlǐ de yèshì jiù yì tiān bǐ yì tiān hónghuǒ.","vi":"Từ khi cải tạo phố cổ xong, chợ đêm ở đây ngày một nhộn nhịp."}],"related":[{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"thịnh vượng"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng vẻ"}],"traditional":"紅火"},{"id":"宏图","hanzi":"宏图","pinyin":"hóngtú","meaning_vi":"kế hoạch lớn, đại nghiệp","explanation":"宏 (vĩ mô/hùng vĩ) + 图 (mưu đồ/bản đồ).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🗺️","examples":[{"type":"basic","zh":"青年人要大展宏图。","pinyin":"Qīngniánrén yào dà zhǎn hóngtú.","vi":"Thanh niên hãy thỏa sức thực hiện hoài bão lớn."},{"type":"simple","zh":"市长在大会上描绘了未来十年城市发展的宏图。","pinyin":"Shìzhǎng zài dàhuì shang miáohuìle wèilái shí nián chéngshì fāzhǎn de hóngtú.","vi":"Thị trưởng phác họa tại đại hội kế hoạch lớn phát triển thành phố trong mười năm tới."},{"type":"compound","zh":"虽然创业之初困难重重，但是他心中早已绘好了宏图。","pinyin":"Suīrán chuàngyè zhī chū kùnnan chóngchóng, dànshì tā xīnzhōng zǎoyǐ huì hǎole hóngtú.","vi":"Tuy buổi đầu khởi nghiệp gặp vô vàn khó khăn, nhưng trong lòng anh đã sớm vẽ sẵn kế hoạch lớn."}],"related":[{"hanzi":"蓝图","pinyin":"lántú","vi":"bản thiết kế"},{"hanzi":"宏伟","pinyin":"hóngwěi","vi":"hùng vĩ"},{"hanzi":"大展宏图","pinyin":"dàzhǎnhóngtú","vi":"thực hiện hoài bão lớn"}],"traditional":"宏圖"},{"id":"喉咙","hanzi":"喉咙","pinyin":"hóulóng","meaning_vi":"cổ họng, yết hầu","explanation":"Cả hai chữ đều có bộ khẩu 口.","hsk_level":"7-9","tags":["danh-tu","co-the"],"image":"🗣️","examples":[{"type":"basic","zh":"我的喉咙有点疼。","pinyin":"Wǒ de hóulóng yǒudiǎn téng.","vi":"Cổ họng tôi hơi đau."},{"type":"simple","zh":"一根鱼刺卡在了他的喉咙里。","pinyin":"Yìgēn yúcì qiǎ zài le tā de hóulóng lǐ.","vi":"Một chiếc xương cá mắc trong cổ họng anh ấy."},{"type":"compound","zh":"如果喉咙发炎，就要少吃辛辣食物，多喝温水。","pinyin":"Rúguǒ hóulóng fāyán, jiùyào shǎo chī xīnlà shíwù, duō hē wēn shuǐ.","vi":"Nếu cổ họng bị viêm thì nên ăn ít đồ cay, uống nhiều nước ấm."}],"related":[{"hanzi":"嗓子","pinyin":"sǎngzi","vi":"cổ họng"},{"hanzi":"咽喉","pinyin":"yānhóu","vi":"yết hầu"},{"hanzi":"声音","pinyin":"shēngyīn","vi":"giọng nói"}],"traditional":"喉嚨"},{"id":"互动","hanzi":"互动","pinyin":"hùdòng","meaning_vi":"tương tác","explanation":"互 (lẫn nhau) + 动 (动).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔄","examples":[{"type":"basic","zh":"老师和学生积极互动。","pinyin":"Lǎoshī hé xuéshēng jījí hùdòng.","vi":"Thầy và trò tích cực tương tác."},{"type":"simple","zh":"这位主播每天晚上都会在直播间和粉丝互动。","pinyin":"Zhè wèi zhǔbō měitiān wǎnshang dōuhuì zài zhíbōjiān hé fěnsī hùdòng.","vi":"Người dẫn livestream này tối nào cũng tương tác với người hâm mộ trong phòng phát trực tiếp."},{"type":"compound","zh":"自从博物馆增加了互动展项，来参观的孩子就明显多了。","pinyin":"Zìcóng bówùguǎn zēngjiāle hùdòng zhǎn xiàng, lái cānguān de háizi jiù míngxiǎn duō le.","vi":"Từ khi bảo tàng bổ sung các hạng mục trưng bày tương tác, trẻ em đến tham quan đông hẳn."}],"related":[{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"互相","pinyin":"hùxiāng","vi":"lẫn nhau"},{"hanzi":"沟通","pinyin":"gōutōng","vi":"trao đổi"}],"traditional":"互動"},{"id":"互惠","hanzi":"互惠","pinyin":"hùhuì","meaning_vi":"cùng có lợi","explanation":"互 (lẫn nhau) + 惠 (惠).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"两国签订了互惠协议。","pinyin":"Liǎngguó qiāndìngle hùhuì xiéyì.","vi":"Hai nước đã ký hiệp định cùng có lợi."},{"type":"simple","zh":"超市和本地农场建立了长期互惠的合作关系。","pinyin":"Chāoshì hé běndì nóngchǎng jiànlìle chángqī hùhuì de hézuò guānxì.","vi":"Siêu thị và trang trại địa phương đã thiết lập quan hệ hợp tác lâu dài cùng có lợi."},{"type":"compound","zh":"只有坚持平等互惠的原则，双方的合作才能长久。","pinyin":"Zhǐyǒu jiānchí píngděng hùhuì de yuánzé, shuāngfāng de hézuò cáinéng chángjiǔ.","vi":"Chỉ khi kiên trì nguyên tắc bình đẳng cùng có lợi, sự hợp tác của hai bên mới lâu dài."}],"related":[{"hanzi":"互利","pinyin":"hùlì","vi":"cùng có lợi"},{"hanzi":"互惠互利","pinyin":"hùhuìhùlì","vi":"đôi bên cùng có lợi"},{"hanzi":"双赢","pinyin":"shuāngyíng","vi":"đôi bên cùng thắng"}]},{"id":"互联互通","hanzi":"互联互通","pinyin":"hùliánhùtōng","meaning_vi":"kết nối thông suốt lẫn nhau","explanation":"互 (lẫn nhau) + 联 (liên hợp/liên lạc) + 互 (lẫn nhau) + 通 (thông suốt/phổ biến).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🌐","examples":[{"type":"basic","zh":"两地交通实现互联互通。","pinyin":"Liǎng dì jiāotōng shíxiàn hùliánhùtōng.","vi":"Giao thông hai nơi đã được kết nối thông suốt."},{"type":"simple","zh":"这项工程将推动东南亚各国铁路网的互联互通。","pinyin":"Zhè xiàng gōngchéng jiāng tuīdòng Dōngnányà gèguó tiělù wǎng de hùliánhùtōng.","vi":"Công trình này sẽ thúc đẩy kết nối thông suốt mạng đường sắt giữa các nước Đông Nam Á."},{"type":"compound","zh":"如果各医院的病历系统能互联互通，病人就不用反复做检查了。","pinyin":"Rúguǒ gè yīyuàn de bìnglì xìtǒng néng hùliánhùtōng, bìngrén jiù bú yòng fǎnfù zuò jiǎnchá le.","vi":"Nếu hệ thống bệnh án của các bệnh viện được liên thông, bệnh nhân sẽ không phải xét nghiệm đi xét nghiệm lại."}],"related":[{"hanzi":"互联网","pinyin":"Hùliánwǎng","vi":"internet"},{"hanzi":"连通","pinyin":"liántōng","vi":"nối liền"},{"hanzi":"一带一路","pinyin":"Yídàiyílù","vi":"Vành đai và Con đường"}],"traditional":"互聯互通"},{"id":"互利共赢","hanzi":"互利共赢","pinyin":"hùlìgòngyíng","meaning_vi":"hợp tác đôi bên cùng có lợi","explanation":"互利 (hỗ lợi – cùng có lợi) + 共赢 (cộng doanh – cùng thắng) → đôi bên cùng có lợi, win-win; hay dùng trong ngoại giao, kinh tế.","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"双方实现了互利共赢。","pinyin":"Shuāngfāng shíxiànle hùlìgòngyíng.","vi":"Hai bên đã đạt được cùng có lợi, cùng thắng."},{"type":"simple","zh":"这个跨境电商项目给中越两国企业带来了互利共赢的结果。","pinyin":"Zhè ge kuàjìngdiànshāng xiàngmù gěi zhōng yuè liǎngguó qǐyè dàiláile hùlìgòngyíng de jiéguǒ.","vi":"Dự án thương mại điện tử xuyên biên giới này mang lại kết quả đôi bên cùng có lợi cho doanh nghiệp Trung Quốc và Việt Nam."},{"type":"compound","zh":"与其互相压价恶性竞争，不如携手合作实现互利共赢。","pinyin":"Yǔqí hùxiāng yājià èxìngjìngzhēng, bùrú xiéshǒu hézuò shíxiàn hùlìgòngyíng.","vi":"Thay vì ép giá cạnh tranh không lành mạnh, chi bằng bắt tay hợp tác để cùng có lợi."}],"related":[{"hanzi":"双赢","pinyin":"shuāngyíng","vi":"đôi bên cùng thắng"},{"hanzi":"互惠","pinyin":"hùhuì","vi":"cùng có lợi"},{"hanzi":"合作共赢","pinyin":"hézuògòngyíng","vi":"hợp tác cùng thắng"}],"traditional":"互利共贏"},{"id":"互学互鉴","hanzi":"互学互鉴","pinyin":"hùxuéhùjiàn","meaning_vi":"cùng học hỏi và tham khảo lẫn nhau","explanation":"互 (lẫn nhau) + 学 (học thuật/học thuyết) + 互 (lẫn nhau) + 鉴 (giám định/soi xét).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📚","examples":[{"type":"basic","zh":"不同文明应互学互鉴。","pinyin":"Bùtóng wénmíng yīng hùxuéhùjiàn.","vi":"Các nền văn minh khác nhau nên học hỏi lẫn nhau."},{"type":"simple","zh":"两所大学通过交换教师的方式在教学上互学互鉴。","pinyin":"Liǎng suǒ dàxué tōngguò jiāohuàn jiàoshī de fāngshì zài jiàoxué shang hùxuéhùjiàn.","vi":"Hai trường đại học học hỏi lẫn nhau về giảng dạy thông qua trao đổi giảng viên."},{"type":"compound","zh":"只要各国在文化上互学互鉴，世界就会变得更加多彩。","pinyin":"Zhǐyào gèguó zài wénhuà shang hùxuéhùjiàn, shìjiè jiù huì biànde gèngjiā duōcǎi.","vi":"Chỉ cần các nước cùng học hỏi lẫn nhau về văn hóa, thế giới sẽ trở nên đa sắc màu hơn."}],"related":[{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"取长补短","pinyin":"qǔchángbǔduǎn","vi":"học hỏi ưu điểm"}],"traditional":"互學互鑒"},{"id":"互信","hanzi":"互信","pinyin":"hùxìn","meaning_vi":"tin cậy lẫn nhau","explanation":"互 (lẫn nhau) + 信 (niềm tin/uy tín).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"双方缺乏互信。","pinyin":"Shuāngfāng quēfá hùxìn.","vi":"Hai bên thiếu tin cậy lẫn nhau."},{"type":"simple","zh":"两国领导人的这次会晤增进了彼此的政治互信。","pinyin":"Liǎngguó lǐngdǎorén de zhè cì huìwù zēngjìnle bǐcǐ de zhèngzhì hùxìn.","vi":"Cuộc hội kiến lần này của lãnh đạo hai nước đã tăng cường lòng tin chính trị lẫn nhau."},{"type":"compound","zh":"夫妻之间一旦失去了互信，婚姻就很难维持下去。","pinyin":"Fūqī zhījiān yídàn shīqùle hùxìn, hūnyīn jiù hěn nán wéichí xiàqù.","vi":"Vợ chồng một khi mất lòng tin lẫn nhau thì hôn nhân rất khó duy trì."}],"related":[{"hanzi":"信任","pinyin":"xìnrèn","vi":"tin cậy"},{"hanzi":"互相信任","pinyin":"hùxiāngxìnrèn","vi":"tin tưởng lẫn nhau"},{"hanzi":"猜疑","pinyin":"cāiyí","vi":"nghi kỵ"}]},{"id":"黑洞","hanzi":"黑洞","pinyin":"hēidòng","meaning_vi":"hố đen vũ trụ","explanation":"黑 (màu đen) + 洞 (hang động).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","thien-nhien"],"image":"🕳️","examples":[{"type":"basic","zh":"科学家拍到了黑洞照片。","pinyin":"Kēxuéjiā pāi dàole hēidòng zhàopiàn.","vi":"Các nhà khoa học đã chụp được ảnh hố đen."},{"type":"simple","zh":"黑洞的引力强大到连光都无法从中逃脱。","pinyin":"Hēidòng de yǐnlì qiángdà dào lián guāng dōu wúfǎ cóng zhōng táotuō.","vi":"Lực hấp dẫn của hố đen mạnh đến mức ngay cả ánh sáng cũng không thể thoát ra."},{"type":"compound","zh":"虽然黑洞本身看不见，但是天文学家能通过周围物质发现它。","pinyin":"Suīrán hēidòng běnshēn kànbújiàn, dànshì tiān wénxuéjiā néng tōngguò zhōuwéi wùzhì fāxiàn tā.","vi":"Tuy bản thân hố đen không nhìn thấy được, nhưng các nhà thiên văn có thể phát hiện nó qua vật chất xung quanh."}],"related":[{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"},{"hanzi":"星系","pinyin":"xīngxì","vi":"thiên hà"},{"hanzi":"天文学","pinyin":"tiānwénxué","vi":"thiên văn học"}]},{"id":"黑客","hanzi":"黑客","pinyin":"hēikè","meaning_vi":"tin tặc (hacker)","explanation":"Phiên âm tiếng Anh 'hacker'.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","phap-luat"],"image":"🥷","examples":[{"type":"basic","zh":"网站遭到黑客攻击。","pinyin":"Wǎngzhàn zāodào hēikè gōngjī.","vi":"Trang web bị tin tặc tấn công."},{"type":"simple","zh":"警方抓获了一名窃取银行客户信息的黑客。","pinyin":"Jǐngfāng zhuāhuòle yì míng qièqǔ yínháng kèhù xìnxī de hēikè.","vi":"Cảnh sát đã bắt giữ một tin tặc đánh cắp thông tin khách hàng ngân hàng."},{"type":"compound","zh":"如果密码设置得太简单，账号就很容易被黑客破解。","pinyin":"Rúguǒ mìmǎ shèzhì de tài jiǎndān, zhànghào jiù hěn róngyì bèi hēikè pòjiě.","vi":"Nếu đặt mật khẩu quá đơn giản, tài khoản rất dễ bị tin tặc bẻ khóa."}],"related":[{"hanzi":"网络安全","pinyin":"wǎngluò'ānquán","vi":"an ninh mạng"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"入侵","pinyin":"rùqīn","vi":"xâm nhập"}]},{"id":"黑马","hanzi":"黑马","pinyin":"hēimǎ","meaning_vi":"ngựa ô (nhân tố bất ngờ giành chiến thắng)","explanation":"黑 (màu đen) + 马 (马).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🐎","examples":[{"type":"basic","zh":"他成了本届比赛的黑马。","pinyin":"Tā chéngle běnjiè bǐsài de hēimǎ.","vi":"Anh ấy trở thành ngựa ô của giải đấu năm nay."},{"type":"simple","zh":"这支名不见经传的球队成了本赛季最大的黑马。","pinyin":"Zhè zhī míng bújiàn jīngzhuàn de qiúduì chéngle běn sàijì zuì dà de hēimǎ.","vi":"Đội bóng vô danh này đã trở thành ngựa ô lớn nhất mùa giải."},{"type":"compound","zh":"虽然这部小成本电影没有明星，但是成了暑期档的一匹黑马。","pinyin":"Suīrán zhè bù xiǎo chéngběn diànyǐng méiyǒu míngxīng, dànshì chéngle shǔqī dàng de yì pǐ hēimǎ.","vi":"Tuy bộ phim kinh phí thấp này không có ngôi sao, nhưng đã trở thành ngựa ô của mùa phim hè."}],"related":[{"hanzi":"冠军","pinyin":"guànjūn","vi":"nhà vô địch"},{"hanzi":"爆冷门","pinyin":"bàolěngmén","vi":"kết quả bất ngờ"},{"hanzi":"新秀","pinyin":"xīnxiù","vi":"tài năng mới"}],"traditional":"黑馬"},{"id":"婚纱","hanzi":"婚纱","pinyin":"hūnshā","meaning_vi":"váy cưới","explanation":"婚 (婚) + 纱 (vải mỏng/voan).","hsk_level":"7-9","tags":["danh-tu","trang-phuc","gia-dinh"],"image":"👰","examples":[{"type":"basic","zh":"她试穿了一件婚纱。","pinyin":"Tā shìchuānle yí jiàn hūnshā.","vi":"Cô ấy đã thử một chiếc váy cưới."},{"type":"simple","zh":"这对新人专门去海边拍了一组婚纱照。","pinyin":"Zhè duì xīnrén zhuānmén qù hǎibiān pāile yì zǔ hūnshāzhào.","vi":"Đôi uyên ương đặc biệt ra biển chụp một bộ ảnh cưới."},{"type":"compound","zh":"与其花大价钱买婚纱，不如租一件只穿一天的。","pinyin":"Yǔqí huā dà jiàqián mǎi hūnshā, bùrú zū yí jiàn zhǐ chuān yì tiān de.","vi":"Thay vì bỏ nhiều tiền mua váy cưới, chi bằng thuê một chiếc chỉ mặc một ngày."}],"related":[{"hanzi":"婚礼","pinyin":"hūnlǐ","vi":"đám cưới"},{"hanzi":"新娘","pinyin":"xīnniáng","vi":"cô dâu"},{"hanzi":"婚纱照","pinyin":"hūnshāzhào","vi":"ảnh cưới"}],"traditional":"婚紗"},{"id":"海内外","hanzi":"海内外","pinyin":"Hǎinèiwài","meaning_vi":"trong và ngoài nước","explanation":"海 (biển) + 内 (nội bộ/nội tại) + 外 (ngoài).","hsk_level":"7-9","tags":["danh-tu","dia-danh","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"这本书在海内外畅销。","pinyin":"Zhè běn shū zài Hǎinèiwài chàngxiāo.","vi":"Cuốn sách này bán chạy trong và ngoài nước."},{"type":"simple","zh":"这场直播吸引了海内外数百万观众同时在线观看。","pinyin":"Zhè chǎng zhíbō xīyǐnle Hǎinèiwài shùbǎiwàn guānzhòng tóngshí zàixiàn guānkàn.","vi":"Buổi phát trực tiếp thu hút hàng triệu khán giả trong và ngoài nước cùng xem trực tuyến."},{"type":"compound","zh":"这位作家的作品不但在国内获奖，而且在海内外都很有影响。","pinyin":"Zhè wèi zuòjiā de zuòpǐn búdàn zài guónèi huòjiǎng, érqiě zài Hǎinèiwài dōu hěn yǒuyǐngxiǎng.","vi":"Tác phẩm của nhà văn này không những đoạt giải trong nước mà còn có ảnh hưởng lớn cả trong và ngoài nước."}],"related":[{"hanzi":"国内外","pinyin":"guónèiwài","vi":"trong và ngoài nước"},{"hanzi":"海外","pinyin":"hǎiwài","vi":"hải ngoại"},{"hanzi":"华侨","pinyin":"Huáqiáo","vi":"Hoa kiều"}],"traditional":"海內外"},{"id":"海啸","hanzi":"海啸","pinyin":"hǎixiào","meaning_vi":"sóng thần","explanation":"海 (hải – biển) + 啸 (khiếu – gầm thét) → biển gầm, sóng thần do động đất dưới đáy biển gây ra. VD: 地震引发海啸.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"地震引发了海啸。","pinyin":"Dìzhèn yǐnfāle hǎixiào.","vi":"Động đất gây ra sóng thần."},{"type":"simple","zh":"二〇〇四年的印度洋海啸造成了二十多万人遇难。","pinyin":"Èr líng líng sì nián de yìn dù yáng hǎi xiào zào chéng le èr shí duō wàn rén yù nàn.","vi":"Trận sóng thần Ấn Độ Dương năm 2004 đã khiến hơn hai trăm nghìn người thiệt mạng."},{"type":"compound","zh":"一旦收到海啸预警，沿海居民就必须马上撤离到高处。","pinyin":"Yídàn shōudào hǎixiào yùjǐng, yánhǎi jūmín jiù bìxū mǎshàng chèlí dào gāochù.","vi":"Một khi nhận được cảnh báo sóng thần, cư dân ven biển phải lập tức sơ tán lên chỗ cao."}],"related":[{"hanzi":"地震","pinyin":"dìzhèn","vi":"động đất"},{"hanzi":"台风","pinyin":"táifēng","vi":"bão"},{"hanzi":"自然灾害","pinyin":"zìránzāihài","vi":"thiên tai"}],"traditional":"海嘯"},{"id":"海洋馆","hanzi":"海洋馆","pinyin":"hǎiyángguǎn","meaning_vi":"thủy cung","explanation":"海 (biển) + 洋 (đại dương/nước ngoài) + 馆 (馆).","hsk_level":"7-9","tags":["danh-tu","du-lich","dia-diem"],"image":"🐠","examples":[{"type":"basic","zh":"孩子们爱去海洋馆。","pinyin":"Háizimen ài qù hǎiyángguǎn.","vi":"Bọn trẻ thích đến thủy cung."},{"type":"simple","zh":"我们在海洋馆的海底隧道里看到了巨大的鲨鱼。","pinyin":"Wǒmen zài hǎiyángguǎn de hǎidǐ suìdào lǐ kàndàole jùdà de shāyú.","vi":"Chúng tôi đã nhìn thấy những con cá mập khổng lồ trong đường hầm đáy biển của thủy cung."},{"type":"compound","zh":"如果周末下雨，我们就带孩子去海洋馆看海豚表演。","pinyin":"Rúguǒ zhōumò xiàyǔ, wǒmen jiù dàiháizi qù hǎiyángguǎn kàn hǎitún biǎoyǎn.","vi":"Nếu cuối tuần trời mưa, chúng ta sẽ đưa con đến thủy cung xem cá heo biểu diễn."}],"related":[{"hanzi":"水族馆","pinyin":"shuǐzúguǎn","vi":"thủy cung"},{"hanzi":"动物园","pinyin":"dòngwùyuán","vi":"sở thú"},{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"}],"traditional":"海洋館"},{"id":"海运","hanzi":"海运","pinyin":"hǎiyùn","meaning_vi":"vận chuyển đường biển","explanation":"海 (biển) + 运 (vận dụng/vận hành).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"🚢","examples":[{"type":"basic","zh":"这批货走海运。","pinyin":"Zhè pī huò zǒu hǎiyùn.","vi":"Lô hàng này đi đường biển."},{"type":"simple","zh":"从上海海运到汉堡大约需要一个多月。","pinyin":"Cóng Shànghǎi hǎiyùn dào hànbǎo dàyuē xūyào yí gè duō yuè.","vi":"Vận chuyển đường biển từ Thượng Hải đến Hamburg mất khoảng hơn một tháng."},{"type":"compound","zh":"海运虽然速度慢，但是运费比空运便宜得多。","pinyin":"Hǎiyùn suīrán sùdù màn, dànshì yùnfèi bǐ kōngyùn piányi de duō.","vi":"Vận chuyển đường biển tuy chậm nhưng cước phí rẻ hơn đường hàng không nhiều."}],"related":[{"hanzi":"空运","pinyin":"kōngyùn","vi":"vận chuyển hàng không"},{"hanzi":"货运","pinyin":"huòyùn","vi":"vận tải hàng hóa"},{"hanzi":"港口","pinyin":"gǎngkǒu","vi":"bến cảng"}],"traditional":"海運"},{"id":"海岸线","hanzi":"海岸线","pinyin":"hǎi'ànxiàn","meaning_vi":"đường bờ biển","explanation":"海 (biển) + 岸 (bờ (sông/biển)) + 线 (manh mối/đường nét).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏖️","examples":[{"type":"basic","zh":"越南的海岸线很长。","pinyin":"Yuènán de hǎi'ànxiàn hěn cháng.","vi":"Đường bờ biển Việt Nam rất dài."},{"type":"simple","zh":"我们骑着自行车沿着蜿蜒的海岸线一路向南。","pinyin":"Wǒmen qízhe zìxíngchē yánzhe wānyán de hǎi'ànxiàn yí lùxiàng nán.","vi":"Chúng tôi đạp xe dọc theo đường bờ biển uốn lượn thẳng hướng nam."},{"type":"compound","zh":"因为海平面不断上升，所以这里的海岸线每年都在后退。","pinyin":"Yīnwèi hǎipíngmiàn búduàn shàngshēng, suǒyǐ zhèlǐ de hǎi'ànxiàn měinián dōu zài hòutuì.","vi":"Vì mực nước biển không ngừng dâng cao nên đường bờ biển ở đây năm nào cũng lùi vào."}],"related":[{"hanzi":"海岸","pinyin":"hǎi'àn","vi":"bờ biển"},{"hanzi":"沙滩","pinyin":"shātān","vi":"bãi cát"},{"hanzi":"海边","pinyin":"hǎibiān","vi":"bờ biển"}],"traditional":"海岸線"},{"id":"好奇心","hanzi":"好奇心","pinyin":"hàoqíxīn","meaning_vi":"tính hiếu kỳ, sự tò mò","explanation":"好 (tốt) + 奇 (kỳ diệu/kỳ lạ) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","hoc-tap"],"image":"🧐","examples":[{"type":"basic","zh":"孩子的好奇心很强。","pinyin":"Háizi de hàoqíxīn hěn qiáng.","vi":"Tính tò mò của trẻ con rất mạnh."},{"type":"simple","zh":"这本科普书极大地激发了儿子对宇宙的好奇心。","pinyin":"Zhè běn kēpǔ shū jí dàde jīfāle érzi duì yǔzhòu de hàoqíxīn.","vi":"Cuốn sách khoa học phổ thông này đã khơi dậy mạnh mẽ trí tò mò của con trai tôi về vũ trụ."},{"type":"compound","zh":"他出于好奇心打开了那个陌生的链接，结果电脑中了病毒。","pinyin":"Tā chūyú hàoqíxīn dǎkāile nà ge mòshēng de liànjiē, jiéguǒ diànnǎo zhòngle bìngdú.","vi":"Vì tò mò, anh mở đường link lạ đó, kết quả máy tính bị nhiễm virus."}],"related":[{"hanzi":"好奇","pinyin":"hàoqí","vi":"tò mò"},{"hanzi":"求知欲","pinyin":"qiúzhīyù","vi":"khát khao hiểu biết"},{"hanzi":"兴趣","pinyin":"xìngqù","vi":"hứng thú"}]},{"id":"好转","hanzi":"好转","pinyin":"hǎozhuǎn","meaning_vi":"chuyển biến tốt lên (bệnh tình/tình hình)","explanation":"好 (tốt) + 转 (rẽ).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"📈","examples":[{"type":"basic","zh":"病情有所好转。","pinyin":"Bìngqíng yǒusuǒ hǎozhuǎn.","vi":"Bệnh tình đã có chuyển biến tốt."},{"type":"simple","zh":"这条河的水质经过三个月治理已明显好转。","pinyin":"Zhè tiáo hé de shuǐzhì jīngguò sān gèyuè zhìlǐ yǐ míngxiǎn hǎozhuǎn.","vi":"Chất lượng nước sông này sau ba tháng xử lý đã cải thiện rõ rệt."},{"type":"compound","zh":"只要天气好转，航班就会马上恢复起飞。","pinyin":"Zhǐyào tiānqì hǎozhuǎn, hángbān jiù huì mǎshàng huīfù qǐfēi.","vi":"Chỉ cần thời tiết chuyển tốt, các chuyến bay sẽ lập tức cất cánh trở lại."}],"related":[{"hanzi":"改善","pinyin":"gǎishàn","vi":"cải thiện"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"康复","pinyin":"kāngfù","vi":"hồi phục"}],"traditional":"好轉"},{"id":"价位","hanzi":"价位","pinyin":"jiàwèi","meaning_vi":"mức giá","explanation":"价 (价) + 位 (vị trí/địa vị).","hsk_level":"7-9","tags":["danh-tu","mua-sam","tien-te"],"image":"🏷️","examples":[{"type":"basic","zh":"这个价位很合理。","pinyin":"Zhè ge jiàwèi hěn hélǐ.","vi":"Mức giá này rất hợp lý."},{"type":"simple","zh":"她想买一部两千元价位左右的手机。","pinyin":"Tā xiǎng mǎi yí bù liǎng qiān yuán jiàwèi zuǒyòu de shǒujī.","vi":"Cô ấy muốn mua một chiếc điện thoại tầm giá khoảng hai nghìn tệ."},{"type":"compound","zh":"虽然这款相机价位偏高，但是它的画质确实无可挑剔。","pinyin":"Suīrán zhè kuǎn xiàngjī jiàwèi piāngāo, dànshì tā de huàzhì quèshí wúkě tiāotī.","vi":"Tuy chiếc máy ảnh này giá hơi cao, nhưng chất lượng hình ảnh thực sự không chê vào đâu được."}],"related":[{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"档次","pinyin":"dàngcì","vi":"đẳng cấp"},{"hanzi":"价钱","pinyin":"jiàqián","vi":"giá tiền"}],"traditional":"價位"},{"id":"假象","hanzi":"假象","pinyin":"jiǎxiàng","meaning_vi":"giả tượng, vẻ bề ngoài đánh lừa","explanation":"假 (giả mạo/giả sử) + 象 (hiện tượng/tượng trưng).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🎭","examples":[{"type":"basic","zh":"这只是一种假象。","pinyin":"Zhè zhǐshì yì zhǒng jiǎxiàng.","vi":"Đây chỉ là một vẻ ngoài đánh lừa."},{"type":"simple","zh":"主人出门前开着灯制造家里有人的假象。","pinyin":"Zhǔrén chū ménqián kāizhe dēng zhìzào jiālǐ yǒurén de jiǎxiàng.","vi":"Chủ nhà để đèn sáng trước khi ra ngoài để tạo vẻ như trong nhà có người."},{"type":"compound","zh":"股市的短暂上涨只是假象，如果盲目跟风就会损失惨重。","pinyin":"Gǔshì de duǎnzàn shàngzhǎng zhǐshì jiǎxiàng, rúguǒ mángmù gēnfēng jiù huì sǔnshī cǎnzhòng.","vi":"Đợt tăng ngắn của chứng khoán chỉ là ảo ảnh, nếu mù quáng chạy theo sẽ thua lỗ nặng."}],"related":[{"hanzi":"表象","pinyin":"biǎoxiàng","vi":"bề ngoài"},{"hanzi":"真相","pinyin":"zhēnxiàng","vi":"sự thật"},{"hanzi":"错觉","pinyin":"cuòjué","vi":"ảo giác"}]},{"id":"驾驭","hanzi":"驾驭","pinyin":"jiàyù","meaning_vi":"điều khiển, làm chủ (tình thế/ngôn ngữ)","explanation":"驾 (lái xe/sánh ngang) + 驭 (điều khiển/chế ngự).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐎","examples":[{"type":"basic","zh":"他能驾驭烈马。","pinyin":"Tā néng jiàyù lièmǎ.","vi":"Anh ấy có thể điều khiển ngựa dữ."},{"type":"simple","zh":"这位年轻作家已经能够熟练地驾驭长篇小说。","pinyin":"Zhè wèi niánqīng zuòjiā yǐjīng nénggòu shúliàn de jiàyù chángpiān xiǎoshuō.","vi":"Nhà văn trẻ này đã có thể làm chủ thành thạo thể loại tiểu thuyết dài."},{"type":"compound","zh":"如果你驾驭不了自己的情绪，就很难管理好一个团队。","pinyin":"Rúguǒ nǐ jiàyù bùliǎo zìjǐ de qíngxù, jiù hěn nán guǎnlǐ hǎo yí gè tuánduì.","vi":"Nếu bạn không làm chủ được cảm xúc của mình thì rất khó quản lý tốt một đội ngũ."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"khống chế"},{"hanzi":"掌握","pinyin":"zhǎngwò","vi":"nắm vững"},{"hanzi":"驾驶","pinyin":"jiàshǐ","vi":"lái xe"}],"traditional":"駕馭"},{"id":"价值链","hanzi":"价值链","pinyin":"jiàzhíliàn","meaning_vi":"chuỗi giá trị","explanation":"价值 (giá trị) + 链.","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"💎","examples":[{"type":"basic","zh":"这家公司处于价值链高端。","pinyin":"Zhè jiā gōngsī chǔyú jiàzhíliàn gāoduān.","vi":"Công ty này nằm ở phân khúc cao của chuỗi giá trị."},{"type":"simple","zh":"越南的电子制造业正在努力向全球价值链上游攀升。","pinyin":"Yuènán de diànzǐ zhìzàoyè zhèngzài nǔlì xiàng quánqiú jiàzhíliàn shàngyóu pānshēng.","vi":"Ngành chế tạo điện tử Việt Nam đang nỗ lực leo lên thượng nguồn chuỗi giá trị toàn cầu."},{"type":"compound","zh":"如果只做来料加工，企业在价值链中就只能赚取微薄利润。","pinyin":"Rúguǒ zhǐ zuò lái liào jiāgōng, qǐyè zài jiàzhíliàn zhōng jiù zhǐnéng zhuànqǔ wēibó lìrùn.","vi":"Nếu chỉ gia công theo nguyên liệu được cung cấp, doanh nghiệp chỉ kiếm được lợi nhuận ít ỏi trong chuỗi giá trị."}],"related":[{"hanzi":"供应链","pinyin":"gōngyìngliàn","vi":"chuỗi cung ứng"},{"hanzi":"产业链","pinyin":"chǎnyèliàn","vi":"chuỗi ngành"},{"hanzi":"价值","pinyin":"jiàzhí","vi":"giá trị"}],"traditional":"價值鏈"},{"id":"践行","hanzi":"践行","pinyin":"jiànxíng","meaning_vi":"thực hành, thực hiện theo","explanation":"践 (tiễn – giẫm lên, thực hiện) + 行 (hành – làm) → thực hành, biến lời hứa, lý tưởng thành hành động. VD: 践行诺言, 践行理念.","hsk_level":"7-9","tags":["dong-tu"],"image":"👣","examples":[{"type":"basic","zh":"他用行动践行诺言。","pinyin":"Tāyòng xíngdòng jiànxíng nuòyán.","vi":"Anh ấy dùng hành động để thực hiện lời hứa."},{"type":"simple","zh":"这位乡村医生用四十年时间践行了救死扶伤的誓言。","pinyin":"Zhè wèi xiāngcūn yīshēng yòng sìshí nián shíjiān jiànxíngle jiùsǐfúshāng de shìyán.","vi":"Vị bác sĩ nông thôn này đã dùng bốn mươi năm để thực hiện lời thề cứu người."},{"type":"compound","zh":"环保理念说起来容易，但是在日常生活中践行起来并不简单。","pinyin":"Huánbǎo lǐniàn shuōqǐlái róngyì, dànshì zài rìcháng shēnghuó zhōng jiànxíng qǐlái bìngbù jiǎndān.","vi":"Lý niệm bảo vệ môi trường nói thì dễ, nhưng thực hành trong đời sống hằng ngày không hề đơn giản."}],"related":[{"hanzi":"实践","pinyin":"shíjiàn","vi":"thực tiễn"},{"hanzi":"履行","pinyin":"lǚxíng","vi":"thực hiện"},{"hanzi":"落实","pinyin":"luòshí","vi":"thực hiện"}],"traditional":"踐行"},{"id":"健美","hanzi":"健美","pinyin":"jiànměi","meaning_vi":"khỏe đẹp, cân đối; thể hình (môn thể thao)","explanation":"健 (健) + 美 (tươi đẹp/mỹ mãn).","hsk_level":"7-9","tags":["tinh-tu","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"她的身材很健美。","pinyin":"Tā de shēncái hěn jiànměi.","vi":"Vóc dáng cô ấy rất khỏe đẹp."},{"type":"simple","zh":"他参加了今年全省业余健美比赛并获得了冠军。","pinyin":"Tā cānjiāle jīnnián quánshěng yèyú jiànměi bǐsài bìng huòdéle guànjūn.","vi":"Anh ấy tham gia cuộc thi thể hình nghiệp dư toàn tỉnh năm nay và giành chức vô địch."},{"type":"compound","zh":"只要坚持锻炼并合理饮食，你也能拥有健美的体形。","pinyin":"Zhǐyào jiānchí duànliàn bìng hélǐ yǐnshí, nǐ yě néng yōngyǒu jiànměi de tǐxíng.","vi":"Chỉ cần kiên trì tập luyện và ăn uống hợp lý, bạn cũng có thể sở hữu thân hình khỏe đẹp."}],"related":[{"hanzi":"健身","pinyin":"jiànshēn","vi":"tập thể hình"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"khỏe mạnh"},{"hanzi":"身材","pinyin":"shēncái","vi":"vóc dáng"}]},{"id":"建树","hanzi":"建树","pinyin":"jiànshù","meaning_vi":"thành tựu đóng góp lớn","explanation":"建 (建) + 树 (xây dựng/cây cối).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏆","examples":[{"type":"basic","zh":"他在物理学上颇有建树。","pinyin":"Tā zài wùlǐxué shang pō yǒu jiànshù.","vi":"Ông có nhiều đóng góp trong vật lý học."},{"type":"simple","zh":"这位学者在敦煌研究领域取得了卓越的建树。","pinyin":"Zhè wèi xuézhě zài Dūnhuáng yánjiū lǐngyù qǔ déle zhuóyuè de jiànshù.","vi":"Học giả này đạt được những thành tựu xuất sắc trong lĩnh vực nghiên cứu Đôn Hoàng."},{"type":"compound","zh":"虽然他当了十年经理，但是在管理上并没有什么建树。","pinyin":"Suīrán tā dāngle shí nián jīnglǐ, dànshì zài guǎnlǐ shang bìng méiyǒu shénme jiànshù.","vi":"Tuy làm giám đốc mười năm, nhưng anh chẳng có thành tựu gì về quản lý."}],"related":[{"hanzi":"成就","pinyin":"chéngjiù","vi":"thành tựu"},{"hanzi":"贡献","pinyin":"gòngxiàn","vi":"cống hiến"},{"hanzi":"业绩","pinyin":"yèjì","vi":"thành tích"}],"traditional":"建樹"},{"id":"见闻","hanzi":"见闻","pinyin":"jiànwén","meaning_vi":"điều mắt thấy tai nghe, kiến văn","explanation":"见 (见) + 闻 (ngửi (mùi)).","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"👀","examples":[{"type":"basic","zh":"他讲了旅途见闻。","pinyin":"Tā jiǎngle lǚtú jiànwén.","vi":"Anh ấy kể những điều mắt thấy tai nghe trên đường đi."},{"type":"simple","zh":"她把在非洲支教一年的见闻写成了一本书。","pinyin":"Tā bǎ zài Fēizhōu zhījiào yì nián de jiànwén xiě chéngle yì běn shū.","vi":"Cô viết những điều mắt thấy tai nghe trong một năm dạy tình nguyện ở châu Phi thành một cuốn sách."},{"type":"compound","zh":"多出去走走不但能增长见闻，而且能开阔心胸。","pinyin":"Duō chūqù zǒu zou búdàn néng zēngzhǎng jiànwén, érqiě néng kāikuò xīnxiōng.","vi":"Đi đây đi đó nhiều không những mở mang hiểu biết mà còn rộng mở tấm lòng."}],"related":[{"hanzi":"见识","pinyin":"jiànshi","vi":"kiến thức"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"},{"hanzi":"所见所闻","pinyin":"suǒjiànsuǒwén","vi":"điều thấy và nghe"}],"traditional":"見聞"},{"id":"健壮","hanzi":"健壮","pinyin":"jiànzhuàng","meaning_vi":"khỏe mạnh cường tráng","explanation":"健 (健) + 壮 (hùng vĩ/tráng lệ).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"💪","examples":[{"type":"basic","zh":"这匹马很健壮。","pinyin":"Zhè pǐ mǎ hěn jiànzhuàng.","vi":"Con ngựa này rất khỏe mạnh."},{"type":"simple","zh":"农场劳动让瘦弱的他变得黝黑而健壮。","pinyin":"Nóngchǎng láodòng ràng shòuruò de tā biànde yǒuhēi ér jiànzhuàng.","vi":"Lao động ở nông trại khiến anh từ gầy yếu trở nên rám nắng và cường tráng."},{"type":"compound","zh":"只要每天坚持锻炼，爷爷的身体就会越来越健壮。","pinyin":"Zhǐyào měitiān jiānchí duànliàn, yéye de shēntǐ jiù huì yuèláiyuè jiànzhuàng.","vi":"Chỉ cần kiên trì tập luyện mỗi ngày, cơ thể của ông sẽ ngày càng cường tráng."}],"related":[{"hanzi":"强壮","pinyin":"qiángzhuàng","vi":"cường tráng"},{"hanzi":"结实","pinyin":"jiēshi","vi":"rắn chắc"},{"hanzi":"虚弱","pinyin":"xūruò","vi":"yếu ớt"}],"traditional":"健壯"},{"id":"建筑师","hanzi":"建筑师","pinyin":"jiànzhùshī","meaning_vi":"kiến trúc sư","explanation":"建 (建) + 筑 (xây dựng) + 师 (thầy giáo/sư phụ).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","cong-viec"],"image":"🏛️","examples":[{"type":"basic","zh":"她是一名建筑师。","pinyin":"Tā shì yì míng jiànzhùshī.","vi":"Cô ấy là một kiến trúc sư."},{"type":"simple","zh":"这座歌剧院是由一位丹麦建筑师设计的。","pinyin":"Zhè zuò gējùyuàn shì yóu yí wèi Dānmài jiànzhùshī shèjì de.","vi":"Nhà hát opera này do một kiến trúc sư Đan Mạch thiết kế."},{"type":"compound","zh":"优秀的建筑师既要懂美学，又要考虑结构安全。","pinyin":"Yōuxiù de jiànzhùshī jì yào dǒng měixué, yòu yào kǎolǜ jiégòu ānquán.","vi":"Kiến trúc sư giỏi vừa phải hiểu mỹ học, vừa phải tính đến an toàn kết cấu."}],"related":[{"hanzi":"建筑","pinyin":"jiànzhù","vi":"kiến trúc"},{"hanzi":"设计师","pinyin":"shèjìshī","vi":"nhà thiết kế"},{"hanzi":"工程师","pinyin":"gōngchéngshī","vi":"kỹ sư"}],"traditional":"建築師"},{"id":"降幅","hanzi":"降幅","pinyin":"jiàngfú","meaning_vi":"mức giảm","explanation":"降 (giáng lâm/giảm xuống) + 幅 (bức (lượng từ tranh/ảnh/vải)).","hsk_level":"7-9","tags":["danh-tu","so-luong","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"本月房价降幅扩大。","pinyin":"Běnyuè fángjià jiàngfú kuòdà.","vi":"Tháng này mức giảm giá nhà mở rộng."},{"type":"simple","zh":"今年流感病例数的降幅超过了专家的预期。","pinyin":"Jīnnián liúgǎn bìnglì shù de jiàngfú chāoguòle zhuānjiā de yùqī.","vi":"Mức giảm số ca cúm năm nay đã vượt dự đoán của chuyên gia."},{"type":"compound","zh":"虽然油价连续下调，但是每次的降幅都不到百分之二。","pinyin":"Suīrán yóujià liánxù xiàtiáo, dànshì měi cì de jiàngfú dōu búdào bǎifēnzhī èr.","vi":"Tuy giá xăng liên tục giảm, nhưng mỗi lần mức giảm đều chưa đến 2%."}],"related":[{"hanzi":"涨幅","pinyin":"zhǎngfú","vi":"mức tăng"},{"hanzi":"下降","pinyin":"xiàjiàng","vi":"giảm xuống"},{"hanzi":"幅度","pinyin":"fúdù","vi":"biên độ"}]},{"id":"降温","hanzi":"降温","pinyin":"jiàngwēn","meaning_vi":"hạ nhiệt độ, làm mát; hạ nhiệt (thị trường, cơn sốt)","explanation":"降 (giáng lâm/giảm xuống) + 温 (ôn hòa/ấm áp).","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"🌡️","examples":[{"type":"basic","zh":"明天将大幅降温。","pinyin":"Míngtiān jiāng dàfú jiàngwēn.","vi":"Ngày mai nhiệt độ sẽ giảm mạnh."},{"type":"simple","zh":"工人们用冰块和电扇给闷热的车间降温。","pinyin":"Gōngrénmen yòng bīngkuài hé diànshàn gěi mēnrè de chējiān jiàngwēn.","vi":"Công nhân dùng đá lạnh và quạt điện để làm mát xưởng oi bức."},{"type":"compound","zh":"政府一出台限购政策，火热的楼市就开始降温了。","pinyin":"Zhèngfǔ yì chūtái xiàngòu zhèngcè, huǒrè de lóushì jiù kāishǐ jiàngwēn le.","vi":"Chính phủ vừa ban hành chính sách hạn chế mua nhà, thị trường bất động sản đang sốt liền bắt đầu hạ nhiệt."}],"related":[{"hanzi":"升温","pinyin":"shēngwēn","vi":"tăng nhiệt"},{"hanzi":"气温","pinyin":"qìwēn","vi":"nhiệt độ"},{"hanzi":"冷却","pinyin":"lěngquè","vi":"làm nguội"}],"traditional":"降溫"},{"id":"界定","hanzi":"界定","pinyin":"jièdìng","meaning_vi":"xác định ranh giới/định nghĩa","explanation":"界 (ranh giới/giới hạn) + 定 (定).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📏","examples":[{"type":"basic","zh":"这个概念很难界定。","pinyin":"Zhè ge gàiniàn hěn nán jièdìng.","vi":"Khái niệm này rất khó định nghĩa."},{"type":"simple","zh":"新法律明确界定了个人信息的范围。","pinyin":"Xīn fǎlǜ míngquè jièdìngle gèrén xìnxī de fànwéi.","vi":"Luật mới đã xác định rõ phạm vi thông tin cá nhân."},{"type":"compound","zh":"如果责任界定不清，出了事故以后各方就会互相推诿。","pinyin":"Rúguǒ zérèn jièdìng bùqīng, chūleshì gù yǐhòu gèfāng jiù huì hùxiāng tuīwěi.","vi":"Nếu trách nhiệm không được phân định rõ, khi xảy ra sự cố các bên sẽ đùn đẩy cho nhau."}],"related":[{"hanzi":"定义","pinyin":"dìngyì","vi":"định nghĩa"},{"hanzi":"界限","pinyin":"jièxiàn","vi":"ranh giới"},{"hanzi":"明确","pinyin":"míngquè","vi":"làm rõ"}]},{"id":"借镜","hanzi":"借镜","pinyin":"jièjìng","meaning_vi":"tham khảo rút kinh nghiệm","explanation":"借 (mượn) + 镜 (gương/ống kính).","hsk_level":"7-9","tags":["dong-tu"],"image":"🪞","examples":[{"type":"basic","zh":"他国经验值得借镜。","pinyin":"Tāguó jīngyàn zhídé jièjìng.","vi":"Kinh nghiệm nước khác đáng để tham khảo."},{"type":"simple","zh":"这座城市借镜新加坡的做法来治理交通拥堵。","pinyin":"Zhè zuò chéngshì jièjìng Xīnjiāpō de zuòfǎ lái zhìlǐ jiāotōng yōngdǔ.","vi":"Thành phố này tham khảo cách làm của Singapore để giải quyết ùn tắc giao thông."},{"type":"compound","zh":"虽然别人的失败与我们无关，但是其中的教训可以借镜。","pinyin":"Suīrán biérén de shībài yǔ wǒmen wúguān, dànshì qízhōng de jiàoxùn kěyǐ jièjìng.","vi":"Tuy thất bại của người khác không liên quan đến ta, nhưng bài học trong đó có thể rút kinh nghiệm."}],"related":[{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"},{"hanzi":"参考","pinyin":"cānkǎo","vi":"tham khảo"},{"hanzi":"教训","pinyin":"jiàoxun","vi":"bài học"}],"traditional":"借鏡"},{"id":"结伴","hanzi":"结伴","pinyin":"jiébàn","meaning_vi":"rủ nhau cùng đi, đi theo nhóm","explanation":"结 (kết hợp/kết tinh) + 伴 (伴).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"👫","examples":[{"type":"basic","zh":"我们结伴去旅行。","pinyin":"Wǒmen jiébàn qù lǚxíng.","vi":"Chúng tôi rủ nhau cùng đi du lịch."},{"type":"simple","zh":"几个大学生结伴骑行穿越了整个川藏线。","pinyin":"Jǐ gè dàxuéshēng jiébàn qíxíng chuānyuèle zhěnggè Chuānzàng xiàn.","vi":"Mấy sinh viên cùng nhau đạp xe vượt qua toàn tuyến Tứ Xuyên - Tây Tạng."},{"type":"compound","zh":"因为山路偏僻危险，所以游客最好结伴而行。","pinyin":"Yīnwèi shānlù piānpì wēixiǎn, suǒyǐ yóukè zuìhǎo jiébàn ér xíng.","vi":"Vì đường núi hẻo lánh nguy hiểm nên du khách tốt nhất nên đi theo nhóm."}],"related":[{"hanzi":"结伴同行","pinyin":"jiébàntóngxíng","vi":"cùng nhau đồng hành"},{"hanzi":"同伴","pinyin":"tóngbàn","vi":"bạn đồng hành"},{"hanzi":"作伴","pinyin":"zuòbàn","vi":"làm bạn"}],"traditional":"結伴"},{"id":"洁白","hanzi":"洁白","pinyin":"jiébái","meaning_vi":"trắng tinh khôi","explanation":"洁 (sạch sẽ/thuần khiết) + 白 (màu trắng).","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🤍","examples":[{"type":"basic","zh":"她穿着洁白的裙子。","pinyin":"Tā chuānzhe jiébái de qúnzi.","vi":"Cô ấy mặc chiếc váy trắng tinh."},{"type":"simple","zh":"一夜大雪给整个村庄披上了洁白的外衣。","pinyin":"Yí yè Dàxuě gěi zhěnggè cūnzhuāng pī shàngle jiébái de wàiyī.","vi":"Trận tuyết lớn suốt đêm đã khoác lên cả ngôi làng tấm áo trắng tinh."},{"type":"compound","zh":"这些瓷盘虽然用了很多年，但是依然洁白如新。","pinyin":"Zhèxiē cí pán suīrán yòngle hěn duōnián, dànshì yīrán jiébái rú xīn.","vi":"Những chiếc đĩa sứ này tuy đã dùng nhiều năm nhưng vẫn trắng tinh như mới."}],"related":[{"hanzi":"雪白","pinyin":"xuěbái","vi":"trắng như tuyết"},{"hanzi":"纯洁","pinyin":"chúnjié","vi":"trong trắng"},{"hanzi":"乌黑","pinyin":"wūhēi","vi":"đen nhánh"}],"traditional":"潔白"},{"id":"结冰","hanzi":"结冰","pinyin":"jiébīng","meaning_vi":"đóng băng","explanation":"结 (kết hợp/kết tinh) + 冰 (冰).","hsk_level":"7-9","tags":["dong-tu","thoi-tiet"],"image":"🧊","examples":[{"type":"basic","zh":"湖面已经结冰了。","pinyin":"Húmiàn yǐjīng jiébīng le.","vi":"Mặt hồ đã đóng băng."},{"type":"simple","zh":"清晨路面结冰导致高速公路上发生了多起追尾事故。","pinyin":"Qīngchén lùmiàn jiébīng dǎozhì gāosùgōnglù shang fāshēngle duō qǐ zhuīwěi shìgù.","vi":"Mặt đường đóng băng sáng sớm đã gây ra nhiều vụ va chạm liên hoàn trên cao tốc."},{"type":"compound","zh":"一旦气温降到零度以下，水管里的水就可能结冰。","pinyin":"Yídàn qìwēn jiàng dào língdù yǐxià, shuǐguǎn lǐ de shuǐ jiù kěnéng jiébīng.","vi":"Một khi nhiệt độ xuống dưới không độ, nước trong ống có thể đóng băng."}],"related":[{"hanzi":"冰冻","pinyin":"bīngdòng","vi":"đóng băng"},{"hanzi":"融化","pinyin":"rónghuà","vi":"tan chảy"},{"hanzi":"零度","pinyin":"língdù","vi":"không độ"}],"traditional":"結冰"},{"id":"节能","hanzi":"节能","pinyin":"jiénéng","meaning_vi":"tiết kiệm năng lượng","explanation":"节 (节) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["dong-tu","thien-nhien","cong-nghe"],"image":"🔋","examples":[{"type":"basic","zh":"这种灯泡很节能。","pinyin":"Zhè zhǒng dēngpào hěn jiénéng.","vi":"Loại bóng đèn này rất tiết kiệm điện."},{"type":"simple","zh":"这栋办公楼采用了太阳能等多项节能技术。","pinyin":"Zhè dòng bàngōnglóu cǎiyòngle tàiyángnéng děng duōxiàng jiénéng jìshù.","vi":"Tòa văn phòng này áp dụng nhiều công nghệ tiết kiệm năng lượng như năng lượng mặt trời."},{"type":"compound","zh":"节能家电虽然价格贵一些，但是长期使用能省下不少电费。","pinyin":"Jiénéng jiādiàn suīrán jiàgé guì yìxiē, dànshì chángqī shǐyòng néng shěng xià bùshǎo diànfèi.","vi":"Đồ điện gia dụng tiết kiệm năng lượng tuy giá đắt hơn chút, nhưng dùng lâu dài tiết kiệm được nhiều tiền điện."}],"related":[{"hanzi":"节约","pinyin":"jiéyuē","vi":"tiết kiệm"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"},{"hanzi":"节能减排","pinyin":"jiénéngjiǎnpái","vi":"tiết kiệm năng lượng giảm phát thải"}],"traditional":"節能"},{"id":"节拍","hanzi":"节拍","pinyin":"jiépāi","meaning_vi":"nhịp phách (âm nhạc)","explanation":"节 (tiết – đốt, nhịp) + 拍 (phách – nhịp vỗ) → nhịp phách trong âm nhạc. VD: 跟着节拍跳舞.","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎵","examples":[{"type":"basic","zh":"跟着节拍拍手。","pinyin":"Gēnzhe jiépāi pāishǒu.","vi":"Vỗ tay theo nhịp."},{"type":"simple","zh":"舞者们随着鼓点的节拍整齐地跳了起来。","pinyin":"Wǔzhěmen suízhe gǔdiǎn de jiépāi zhěngqí de tiàole qǐlái.","vi":"Các vũ công nhảy đều tăm tắp theo nhịp trống."},{"type":"compound","zh":"如果你总是跟不上节拍，就先用节拍器慢速练习。","pinyin":"Rúguǒ nǐ zǒngshì gēnbúshàng jiépāi, jiù xiān yòng jiépāiqì mànsù liànxí.","vi":"Nếu bạn luôn theo không kịp nhịp thì hãy luyện chậm với máy đếm nhịp trước."}],"related":[{"hanzi":"节奏","pinyin":"jiézòu","vi":"nhịp điệu"},{"hanzi":"拍子","pinyin":"pāizi","vi":"nhịp phách"},{"hanzi":"旋律","pinyin":"xuánlǜ","vi":"giai điệu"}],"traditional":"節拍"},{"id":"节气","hanzi":"节气","pinyin":"jiéqì","meaning_vi":"tiết khí","explanation":"节 (节) + 气 (khí phách/khí hậu).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","van-hoa"],"image":"📅","examples":[{"type":"basic","zh":"立春是第一个节气。","pinyin":"Lìchūn shì dìyī gè jiéqì.","vi":"Lập xuân là tiết khí đầu tiên."},{"type":"simple","zh":"农民们世世代代按照二十四节气安排农活。","pinyin":"Nóngmínmen shìshìdàidài ànzhào èrshísìjiéqì ānpái nónghuó.","vi":"Nông dân bao đời nay sắp xếp việc đồng áng theo hai mươi bốn tiết khí."},{"type":"compound","zh":"到了冬至这个节气，北方人就一定要吃饺子。","pinyin":"Dàole Dōngzhì zhè ge jiéqì, běifāng rén jiù yídìngyào chī jiǎozi.","vi":"Đến tiết Đông chí, người miền Bắc nhất định phải ăn sủi cảo."}],"related":[{"hanzi":"二十四节气","pinyin":"èr shísì jiéqì","vi":"24 tiết khí"},{"hanzi":"立春","pinyin":"Lìchūn","vi":"lập xuân"},{"hanzi":"农历","pinyin":"nónglì","vi":"âm lịch"}],"traditional":"節氣"},{"id":"截然","hanzi":"截然","pinyin":"jiérán","meaning_vi":"hoàn toàn, rạch ròi (截然不同: hoàn toàn khác nhau)","explanation":"截 (cắt đứt/tính đến) + 然 (然).","hsk_level":"7-9","tags":["pho-tu"],"image":"↔️","examples":[{"type":"basic","zh":"两人性格截然不同。","pinyin":"Liǎng rén xìnggé jiéránbùtóng.","vi":"Tính cách hai người hoàn toàn khác nhau."},{"type":"simple","zh":"这两份调查报告得出了截然相反的结论。","pinyin":"Zhè liǎng fèn diàochá bàogào déchūle jiérán xiāngfǎn de jiélùn.","vi":"Hai bản báo cáo điều tra đưa ra kết luận hoàn toàn trái ngược."},{"type":"compound","zh":"虽然是双胞胎，但是兄弟俩的爱好截然不同。","pinyin":"Suīrán shì shuāngbāotāi, dànshì xiōngdì liǎ de àihào jiéránbùtóng.","vi":"Tuy là anh em sinh đôi, nhưng sở thích của hai anh em hoàn toàn khác nhau."}],"related":[{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác nhau"},{"hanzi":"完全","pinyin":"wánquán","vi":"hoàn toàn"},{"hanzi":"迥然","pinyin":"jiǒngrán","vi":"khác hẳn"}]},{"id":"节水","hanzi":"节水","pinyin":"jiéshuǐ","meaning_vi":"tiết kiệm nước","explanation":"节 (tiết – tiết kiệm) + 水 (thủy – nước) → tiết kiệm nước. VD: 节水型社会, 节约用水.","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"💧","examples":[{"type":"basic","zh":"家家户户都要节水。","pinyin":"Jiājiāhùhù dōu yào jiéshuǐ.","vi":"Nhà nhà đều phải tiết kiệm nước."},{"type":"simple","zh":"这个干旱地区的农民普遍采用滴灌技术来节水。","pinyin":"Zhè ge gānhàn dìqū de nóngmín pǔbiàn cǎiyòng dīguàn jìshù lái jiéshuǐ.","vi":"Nông dân ở vùng khô hạn này phổ biến dùng kỹ thuật tưới nhỏ giọt để tiết kiệm nước."},{"type":"compound","zh":"只要换上节水马桶，一个家庭每年就能省下好几吨水。","pinyin":"Zhǐyào huàn shàng jiéshuǐ mǎtǒng, yí gè jiātíng měinián jiù néng shěng xià hǎojǐ dūn shuǐ.","vi":"Chỉ cần thay bồn cầu tiết kiệm nước, mỗi gia đình mỗi năm có thể tiết kiệm được vài tấn nước."}],"related":[{"hanzi":"节约用水","pinyin":"jiéyuēyòngshuǐ","vi":"tiết kiệm nước"},{"hanzi":"节能","pinyin":"jiénéng","vi":"tiết kiệm năng lượng"},{"hanzi":"水资源","pinyin":"shuǐzīyuán","vi":"tài nguyên nước"}],"traditional":"節水"},{"id":"结语","hanzi":"结语","pinyin":"jiéyǔ","meaning_vi":"lời kết","explanation":"结 (kết hợp/kết tinh) + 语 (ngôn ngữ/lời nói).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🏁","examples":[{"type":"basic","zh":"文章的结语很精彩。","pinyin":"Wénzhāng de jiéyǔ hěn jīngcǎi.","vi":"Lời kết của bài viết rất hay."},{"type":"simple","zh":"他在论文的结语部分总结了三点研究发现。","pinyin":"Tā zài lùnwén de jiéyǔ bùfen zǒngjiéle sān diǎn yánjiū fāxiàn.","vi":"Trong phần lời kết của luận văn, anh tổng kết ba phát hiện nghiên cứu."},{"type":"compound","zh":"结语虽然只有短短几句，但是让整篇演讲升华了。","pinyin":"Jiéyǔ suīrán zhǐyǒu duǎn duǎn jǐ jù, dànshì ràng zhěng piān yǎnjiǎng shēnghuá le.","vi":"Lời kết tuy chỉ vỏn vẹn vài câu, nhưng đã nâng tầm cả bài diễn thuyết."}],"related":[{"hanzi":"结论","pinyin":"jiélùn","vi":"kết luận"},{"hanzi":"结尾","pinyin":"jiéwěi","vi":"phần kết"},{"hanzi":"前言","pinyin":"qiányán","vi":"lời nói đầu"}],"traditional":"結語"},{"id":"就读","hanzi":"就读","pinyin":"jiùdú","meaning_vi":"theo học tại (trường)","explanation":"就 (thì) + 读 (đọc (thành tiếng)).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"他就读于北京大学。","pinyin":"Tā jiùdú yú Běijīngdàxué.","vi":"Anh ấy theo học tại Đại học Bắc Kinh."},{"type":"simple","zh":"我妹妹目前在一所国际学校就读初中二年级。","pinyin":"Wǒ mèimei mùqián zài yì suǒ Guójì xuéxiào jiùdú chūzhōng èr niánjí.","vi":"Em gái tôi hiện đang học lớp 8 tại một trường quốc tế."},{"type":"compound","zh":"如果想在这所大学就读，就必须先通过汉语水平考试。","pinyin":"Rúguǒ xiǎng zài zhè suǒ dàxué jiùdú, jiù bìxū xiān tōngguò Hànyǔshuǐpíngkǎoshì.","vi":"Nếu muốn theo học ở trường đại học này thì trước hết phải thi đỗ kỳ thi năng lực Hán ngữ."}],"related":[{"hanzi":"就学","pinyin":"jiùxué","vi":"đi học"},{"hanzi":"上学","pinyin":"shàngxué","vi":"đi học"},{"hanzi":"毕业","pinyin":"bìyè","vi":"tốt nghiệp"}],"traditional":"就讀"},{"id":"就医","hanzi":"就医","pinyin":"jiùyī","meaning_vi":"đi khám chữa bệnh","explanation":"就 (tựu – đến, tìm đến) + 医 (y – thầy thuốc, chữa bệnh) → đi khám chữa bệnh. VD: 及时就医, 就医难.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"生病要及时就医。","pinyin":"Shēngbìng yào jíshí jiùyī.","vi":"Bị bệnh phải kịp thời đi khám."},{"type":"simple","zh":"偏远山区的村民过去要走几十里山路才能就医。","pinyin":"Piānyuǎn shānqū de cūnmín guòqù yào zǒu jǐ shí lǐ shānlù cáinéng jiùyī.","vi":"Người dân vùng núi xa xôi trước đây phải đi mấy chục dặm đường núi mới được khám bệnh."},{"type":"compound","zh":"如果出现持续高烧，就应该立即到医院就医。","pinyin":"Rúguǒ chūxiàn chíxù gāoshāo, jiù yīnggāi lìjí dào yīyuàn jiùyī.","vi":"Nếu bị sốt cao kéo dài thì nên đến bệnh viện khám ngay."}],"related":[{"hanzi":"看病","pinyin":"kànbìng","vi":"khám bệnh"},{"hanzi":"就诊","pinyin":"jiùzhěn","vi":"đi khám"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"bệnh viện"}],"traditional":"就醫"},{"id":"佳话","hanzi":"佳话","pinyin":"jiāhuà","meaning_vi":"giai thoại đẹp","explanation":"佳 (tốt đẹp/món ngon) + 话 (话).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"这段友谊传为佳话。","pinyin":"Zhè duàn yǒuyì chuán wéi jiāhuà.","vi":"Tình bạn này được lưu truyền thành giai thoại đẹp."},{"type":"simple","zh":"伯牙和子期以琴会友的故事成了千古佳话。","pinyin":"Bó yá hé zǐ qī yǐ qín huìyǒu de gùshi chéngle qiāngǔ jiāhuà.","vi":"Câu chuyện Bá Nha và Tử Kỳ kết bạn qua tiếng đàn đã thành giai thoại muôn đời."},{"type":"compound","zh":"两位老人虽然失散了六十年，但是终于重逢，在当地传为佳话。","pinyin":"Liǎng wèi lǎorén suīrán shīsànle liùshí nián, dànshì zhōngyú chóngféng, zài dāngdì chuán wéi jiāhuà.","vi":"Hai cụ già tuy thất lạc sáu mươi năm nhưng cuối cùng đã đoàn tụ, trở thành giai thoại đẹp ở địa phương."}],"related":[{"hanzi":"美谈","pinyin":"měitán","vi":"chuyện đẹp"},{"hanzi":"传说","pinyin":"chuánshuō","vi":"truyền thuyết"},{"hanzi":"故事","pinyin":"gùshi","vi":"câu chuyện"}],"traditional":"佳話"},{"id":"家教","hanzi":"家教","pinyin":"jiājiào","meaning_vi":"gia sư; giáo dục gia đình, gia giáo","explanation":"家 (nhà) + 教 (dạy).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","gia-dinh"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"她周末去做家教。","pinyin":"Tā zhōumò qù zuò jiājiào.","vi":"Cuối tuần cô ấy đi làm gia sư."},{"type":"simple","zh":"这孩子彬彬有礼的举止体现了良好的家教。","pinyin":"Zhè háizi bīnbīnyǒulǐ de jǔzhǐ tǐxiànle liánghǎo de jiājiào.","vi":"Cử chỉ lễ phép của đứa trẻ này thể hiện nền giáo dục gia đình tốt."},{"type":"compound","zh":"因为父母工作太忙，所以他们给儿子请了一位数学家教。","pinyin":"Yīnwèi fùmǔ gōngzuò tài máng, suǒyǐ tāmen gěi érzi qǐngle yí wèi shùxué jiājiào.","vi":"Vì bố mẹ quá bận nên họ thuê cho con trai một gia sư toán."}],"related":[{"hanzi":"家庭教育","pinyin":"jiātíngjiàoyù","vi":"giáo dục gia đình"},{"hanzi":"家庭教师","pinyin":"jiātíngjiàoshī","vi":"gia sư"},{"hanzi":"家风","pinyin":"jiāfēng","vi":"nề nếp gia đình"}]},{"id":"家境","hanzi":"家境","pinyin":"jiājìng","meaning_vi":"hoàn cảnh gia đình","explanation":"家 (nhà) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["danh-tu","gia-dinh"],"image":"🏡","examples":[{"type":"basic","zh":"他家境贫寒。","pinyin":"Tā jiājìng pínhán.","vi":"Hoàn cảnh gia đình anh ấy nghèo khó."},{"type":"simple","zh":"学校为家境困难的学生减免了全部学费。","pinyin":"Xuéxiào wèi jiājìng kùnnan de xuéshēng jiǎnmiǎnle quánbù xuéfèi.","vi":"Nhà trường miễn giảm toàn bộ học phí cho học sinh có hoàn cảnh khó khăn."},{"type":"compound","zh":"虽然她家境优越，但是从不在同学面前炫耀。","pinyin":"Suīrán tā jiājìng yōuyuè, dànshì cóng bú zài tóngxué miànqián xuànyào.","vi":"Tuy gia cảnh sung túc, nhưng cô chưa bao giờ khoe khoang trước bạn bè."}],"related":[{"hanzi":"家庭","pinyin":"jiātíng","vi":"gia đình"},{"hanzi":"家境贫寒","pinyin":"jiājìngpínhán","vi":"gia cảnh nghèo khó"},{"hanzi":"条件","pinyin":"tiáojiàn","vi":"điều kiện"}]},{"id":"加快推进","hanzi":"加快推进","pinyin":"jiākuàituījìn","meaning_vi":"đẩy nhanh tiến độ","explanation":"加 (加) + 快 (nhanh) + 推 (đẩy) + 进 (vào).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"⚡","examples":[{"type":"basic","zh":"新区建设正加快推进。","pinyin":"Xīn qū jiànshè zhèng jiākuàituījìn.","vi":"Việc xây dựng khu mới đang được đẩy nhanh."},{"type":"simple","zh":"本市正在加快推进老旧小区的电梯加装工程。","pinyin":"Běnshì zhèngzài jiākuàituījìn lǎojiù xiǎoqū de diàntī jiā zhuāng gōngchéng.","vi":"Thành phố đang đẩy nhanh dự án lắp thêm thang máy cho các khu dân cư cũ."},{"type":"compound","zh":"只有加快推进农村电网改造，偏远村庄才能用上稳定的电。","pinyin":"Zhǐyǒu jiākuàituījìn nóngcūn diànwǎng gǎizào, piānyuǎn cūnzhuāng cáinéng yòng shàng wěndìng de diàn.","vi":"Chỉ có đẩy nhanh cải tạo lưới điện nông thôn, các làng xa xôi mới có điện ổn định."}],"related":[{"hanzi":"加快","pinyin":"jiākuài","vi":"đẩy nhanh"},{"hanzi":"推进","pinyin":"tuījìn","vi":"thúc đẩy"},{"hanzi":"加速","pinyin":"jiāsù","vi":"tăng tốc"}],"traditional":"加快推進"},{"id":"家书","hanzi":"家书","pinyin":"jiāshū","meaning_vi":"thư nhà","explanation":"家 (nhà) + 书 (sách).","hsk_level":"7-9","tags":["danh-tu","gia-dinh","van-hoa"],"image":"✉️","examples":[{"type":"basic","zh":"他收到了一封家书。","pinyin":"Tā shōudàole yì fēng jiāshū.","vi":"Anh ấy nhận được một lá thư nhà."},{"type":"simple","zh":"这些泛黄的家书记录了一个家族百年的变迁。","pinyin":"Zhèxiē fàn huáng de jiāshū jìlùle yí gè jiāzú bǎinián de biànqiān.","vi":"Những lá thư nhà ố vàng này ghi lại biến thiên trăm năm của một gia tộc."},{"type":"compound","zh":"那时候交通不便，因此一封家书往往要走一个多月才能寄到。","pinyin":"Nàshíhou jiāotōng búbiàn, yīncǐ yì fēng jiāshū wǎngwǎng yào zǒu yí gè duō yuè cáinéng jì dào.","vi":"Thời đó giao thông bất tiện, vì vậy một lá thư nhà thường phải mất hơn một tháng mới đến nơi."}],"related":[{"hanzi":"书信","pinyin":"shūxìn","vi":"thư từ"},{"hanzi":"家信","pinyin":"jiāxìn","vi":"thư nhà"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê nhà"}],"traditional":"家書"},{"id":"佳作","hanzi":"佳作","pinyin":"jiāzuò","meaning_vi":"tác phẩm xuất sắc","explanation":"佳 (tốt đẹp/món ngon) + 作 (tác phẩm/tác phong).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"这是一部难得的佳作。","pinyin":"Zhè shì yí bù nándé de jiāzuò.","vi":"Đây là một tác phẩm xuất sắc hiếm có."},{"type":"simple","zh":"本次摄影展共展出了一百多幅获奖佳作。","pinyin":"Běn cì shèyǐng zhǎn gòng zhǎnchūle yī bǎi duō fú huòjiǎng jiāzuò.","vi":"Triển lãm nhiếp ảnh lần này trưng bày hơn một trăm tác phẩm xuất sắc đoạt giải."},{"type":"compound","zh":"只要作家沉下心来体验生活，就一定能写出佳作。","pinyin":"Zhǐyào zuòjiā chén xià xīn lái tǐyàn shēnghuó, jiù yídìng néng xiě chū jiāzuò.","vi":"Chỉ cần nhà văn tĩnh tâm trải nghiệm cuộc sống, nhất định sẽ viết ra được tác phẩm hay."}],"related":[{"hanzi":"作品","pinyin":"zuòpǐn","vi":"tác phẩm"},{"hanzi":"杰作","pinyin":"jiézuò","vi":"kiệt tác"},{"hanzi":"名作","pinyin":"míngzuò","vi":"tác phẩm nổi tiếng"}]},{"id":"兼并","hanzi":"兼并","pinyin":"jiānbìng","meaning_vi":"sáp nhập, thâu tóm (doanh nghiệp)","explanation":"兼 (kiêm nhiệm/chiếu cố) + 并 (并).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"大公司兼并了小公司。","pinyin":"Dàgōngsī jiānbìngle xiǎo gōngsī.","vi":"Công ty lớn đã thâu tóm công ty nhỏ."},{"type":"simple","zh":"这家连锁超市去年兼并了三家地方零售企业。","pinyin":"Zhè jiā liánsuǒ chāoshì qùnián jiānbìngle sān jiā dìfāng língshòu qǐyè.","vi":"Chuỗi siêu thị này năm ngoái đã sáp nhập ba doanh nghiệp bán lẻ địa phương."},{"type":"compound","zh":"如果这次兼并顺利完成，新公司就将成为行业第一。","pinyin":"Rúguǒ zhè cì jiānbìng shùnlì wánchéng, xīn gōngsī jiù jiāng chéngwéi hángyè dìyī.","vi":"Nếu thương vụ sáp nhập lần này hoàn tất suôn sẻ, công ty mới sẽ trở thành số một trong ngành."}],"related":[{"hanzi":"并购","pinyin":"bìnggòu","vi":"mua bán sáp nhập"},{"hanzi":"收购","pinyin":"shōugòu","vi":"thu mua"},{"hanzi":"合并","pinyin":"hébìng","vi":"hợp nhất"}],"traditional":"兼併"},{"id":"监测","hanzi":"监测","pinyin":"jiāncè","meaning_vi":"quan trắc, giám sát đo lường","explanation":"监 (giám sát) + 测 (测).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"📡","examples":[{"type":"basic","zh":"气象站监测风速。","pinyin":"Qìxiàngzhàn jiāncè fēngsù.","vi":"Trạm khí tượng đo đạc tốc độ gió."},{"type":"simple","zh":"环保部门在河流沿岸安装了水质自动监测设备。","pinyin":"Huánbǎo bùmén zài héliú yán'àn ānzhuāngle shuǐzhì zìdòng jiāncè shèbèi.","vi":"Cơ quan môi trường đã lắp thiết bị quan trắc chất lượng nước tự động dọc bờ sông."},{"type":"compound","zh":"一旦监测到地震波，系统就会自动向手机发送警报。","pinyin":"Yídàn jiāncè dào dìzhènbō, xìtǒng jiù huì zì dòngxiàng shǒujī fāsòng jǐngbào.","vi":"Một khi phát hiện sóng địa chấn, hệ thống sẽ tự động gửi cảnh báo đến điện thoại."}],"related":[{"hanzi":"检测","pinyin":"jiǎncè","vi":"kiểm tra"},{"hanzi":"监控","pinyin":"jiānkòng","vi":"giám sát"},{"hanzi":"观测","pinyin":"guāncè","vi":"quan trắc"}],"traditional":"監測"},{"id":"监管","hanzi":"监管","pinyin":"jiānguǎn","meaning_vi":"giám sát quản lý","explanation":"监 (giám sát) + 管 (管).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👀","examples":[{"type":"basic","zh":"食品安全需要严格监管。","pinyin":"Shípǐn ānquán xūyào yángé jiānguǎn.","vi":"An toàn thực phẩm cần được giám sát chặt chẽ."},{"type":"simple","zh":"金融监管机构对这家网贷平台展开了调查。","pinyin":"Jīnróng jiānguǎn jīgòu duì zhè jiā wǎngdài píngtái zhǎnkāile diàochá.","vi":"Cơ quan giám sát tài chính đã mở cuộc điều tra đối với nền tảng cho vay trực tuyến này."},{"type":"compound","zh":"因为缺乏有效监管，所以这条小河曾被工厂污水严重污染。","pinyin":"Yīnwèi quēfá yǒuxiào jiānguǎn, suǒyǐ zhè tiáo xiǎohé céng bèi gōngchǎng wūshuǐ yánzhòng wūrǎn.","vi":"Vì thiếu giám sát hiệu quả nên con sông nhỏ này từng bị nước thải nhà máy ô nhiễm nghiêm trọng."}],"related":[{"hanzi":"监督","pinyin":"jiāndū","vi":"giám sát"},{"hanzi":"管理","pinyin":"guǎnlǐ","vi":"quản lý"},{"hanzi":"监管部门","pinyin":"jiānguǎnbùmén","vi":"cơ quan quản lý"}],"traditional":"監管"},{"id":"监控","hanzi":"监控","pinyin":"jiānkòng","meaning_vi":"giám sát, theo dõi; camera giám sát","explanation":"监 (giám sát) + 控 (khống chế/kiểm soát).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"📹","examples":[{"type":"basic","zh":"门口装了监控摄像头。","pinyin":"Ménkǒu zhuāngle jiānkòng shèxiàngtóu.","vi":"Ở cửa đã lắp camera giám sát."},{"type":"simple","zh":"警察调取了路口的监控录像寻找肇事车辆。","pinyin":"Jǐngchá diàoqǔle lùkǒu de jiānkòng lùxiàng xúnzhǎo zhàoshì chēliàng.","vi":"Cảnh sát trích xuất camera giám sát ở ngã tư để tìm xe gây tai nạn."},{"type":"compound","zh":"医生一边监控病人的心率，一边调整药物剂量。","pinyin":"Yīshēng yìbiān jiānkòng bìngrén de xīnlǜ, yìbiān tiáozhěng yàowù jìliàng.","vi":"Bác sĩ vừa theo dõi nhịp tim bệnh nhân, vừa điều chỉnh liều thuốc."}],"related":[{"hanzi":"摄像头","pinyin":"shèxiàngtóu","vi":"camera"},{"hanzi":"监视","pinyin":"jiānshì","vi":"theo dõi"},{"hanzi":"监测","pinyin":"jiāncè","vi":"quan trắc"}],"traditional":"監控"},{"id":"兼收并蓄","hanzi":"兼收并蓄","pinyin":"jiānshōu-bìngxù","meaning_vi":"tiếp thu chọn lọc mọi tinh hoa","explanation":"兼 (kiêm nhiệm/chiếu cố) + 收 (nhận) + 并 (并) + 蓄 (tích lũy/hàm súc).","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🌐","examples":[{"type":"basic","zh":"他读书兼收并蓄。","pinyin":"Tā dúshū jiānshōubìngxù.","vi":"Anh ấy đọc sách tiếp thu rộng rãi mọi loại."},{"type":"simple","zh":"唐代文化以兼收并蓄的胸怀吸收了大量外来元素。","pinyin":"Tángdài wénhuà yǐ jiānshōubìngxù de xiōnghuái xīshōule dàliàng wàilái yuánsù.","vi":"Văn hóa đời Đường với tấm lòng bao dung đã tiếp thu rất nhiều yếu tố ngoại lai."},{"type":"compound","zh":"一个民族只有兼收并蓄，才能让自己的文化保持活力。","pinyin":"Yí gè mínzú zhǐyǒu jiānshōubìngxù, cáinéng ràng zìjǐ de wénhuà bǎochí huólì.","vi":"Một dân tộc chỉ có tiếp thu chọn lọc mọi tinh hoa mới giữ được sức sống cho văn hóa của mình."}],"related":[{"hanzi":"博采众长","pinyin":"bócǎizhòngcháng","vi":"học hỏi điểm mạnh"},{"hanzi":"包容","pinyin":"bāoróng","vi":"bao dung"},{"hanzi":"吸收","pinyin":"xīshōu","vi":"hấp thụ"}],"traditional":"兼收並蓄"},{"id":"坚守","hanzi":"坚守","pinyin":"jiānshǒu","meaning_vi":"kiên trì giữ vững (vị trí/nguyên tắc)","explanation":"坚 (kiên định/vững chắc) + 守 (tuân thủ/bảo vệ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"他始终坚守原则。","pinyin":"Tā shǐzhōng jiānshǒu yuánzé.","vi":"Anh ấy luôn giữ vững nguyên tắc."},{"type":"simple","zh":"春节期间许多医护人员仍然坚守在工作岗位上。","pinyin":"Chūnjié qījiān xǔduō yīhù rényuán réngrán jiānshǒu zài gōngzuò gǎngwèi shang.","vi":"Dịp Tết nhiều nhân viên y tế vẫn kiên trì bám trụ tại vị trí công tác."},{"type":"compound","zh":"即使收入微薄，这位老教师也坚守在山村讲台三十年。","pinyin":"Jíshǐ shōurù wēibó, zhè wèi lǎo jiàoshī yě jiānshǒu zài shāncūn jiǎngtái sānshí nián.","vi":"Dù thu nhập ít ỏi, thầy giáo già này vẫn bám trụ bục giảng làng núi suốt ba mươi năm."}],"related":[{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"},{"hanzi":"守护","pinyin":"shǒuhù","vi":"bảo vệ"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"}],"traditional":"堅守"},{"id":"坚信","hanzi":"坚信","pinyin":"jiānxìn","meaning_vi":"tin tưởng vững chắc","explanation":"坚 (kiên định/vững chắc) + 信 (niềm tin/uy tín).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💯","examples":[{"type":"basic","zh":"我坚信他是无辜的。","pinyin":"Wǒ jiānxìn tā shì wúgū de.","vi":"Tôi tin chắc anh ấy vô tội."},{"type":"simple","zh":"科学家坚信这种新药能够有效治疗阿尔茨海默病。","pinyin":"Kēxuéjiā jiānxìn zhè zhǒng xīn yào nénggòu yǒuxiào zhìliáo Ā'ěrcíhǎimò bìng.","vi":"Các nhà khoa học tin chắc loại thuốc mới này có thể điều trị hiệu quả bệnh Alzheimer."},{"type":"compound","zh":"虽然实验失败了很多次，但是她坚信自己的方向是对的。","pinyin":"Suīrán shíyàn shībàile hěn duōcì, dànshì tā jiānxìn zìjǐ de fāngxiàng shì duì de.","vi":"Tuy thí nghiệm thất bại nhiều lần, nhưng cô tin chắc hướng đi của mình là đúng."}],"related":[{"hanzi":"相信","pinyin":"xiāngxìn","vi":"tin tưởng"},{"hanzi":"深信","pinyin":"shēnxìn","vi":"tin sâu sắc"},{"hanzi":"怀疑","pinyin":"huáiyí","vi":"hoài nghi"}],"traditional":"堅信"},{"id":"尖子生","hanzi":"尖子生","pinyin":"jiānzishēng","meaning_vi":"học sinh xuất sắc mũi nhọn","explanation":"尖 (nhọn/sắc bén) + 子 (hạt giống/con cái) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","con-nguoi"],"image":"🎓","examples":[{"type":"basic","zh":"他是班里的尖子生。","pinyin":"Tā shì bān lǐ de jiānzishēng.","vi":"Cậu ấy là học sinh mũi nhọn của lớp."},{"type":"simple","zh":"学校专门为尖子生开设了数学竞赛辅导班。","pinyin":"Xuéxiào zhuānmén wèi jiānzishēng kāishèle shùxué jìngsài fǔdǎobān.","vi":"Nhà trường mở riêng lớp bồi dưỡng thi toán cho học sinh mũi nhọn."},{"type":"compound","zh":"即使是尖子生，也需要老师关心他们的心理健康。","pinyin":"Jíshǐ shì jiānzishēng, yě xūyào lǎoshī guānxīn tāmen de xīnlǐjiànkāng.","vi":"Dù là học sinh giỏi, các em cũng cần thầy cô quan tâm đến sức khỏe tâm lý."}],"related":[{"hanzi":"优等生","pinyin":"yōuděngshēng","vi":"học sinh giỏi"},{"hanzi":"学霸","pinyin":"xuébà","vi":"học bá"},{"hanzi":"差生","pinyin":"chàshēng","vi":"học sinh kém"}]},{"id":"交锋","hanzi":"交锋","pinyin":"jiāofēng","meaning_vi":"giao đấu, đối đầu; tranh luận trực diện","explanation":"交 (giao) + 锋 (sắc bén/tiên phong).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"⚔️","examples":[{"type":"basic","zh":"两队再次交锋。","pinyin":"Liǎng duì zàicì jiāofēng.","vi":"Hai đội lại đối đầu lần nữa."},{"type":"simple","zh":"两位候选人在电视辩论中进行了激烈交锋。","pinyin":"Liǎng wèi hòuxuǎnrén zài diànshì biànlùn zhōng jìnxíngle jīliè jiāofēng.","vi":"Hai ứng cử viên đã đối đầu gay gắt trong cuộc tranh luận truyền hình."},{"type":"compound","zh":"虽然这两支球队多次交锋，但是从来没有打过平局。","pinyin":"Suīrán zhè liǎng zhī qiúduì duōcì jiāofēng, dànshì cónglái méiyǒu dǎguo píngjú.","vi":"Tuy hai đội bóng này đã nhiều lần đối đầu, nhưng chưa bao giờ hòa."}],"related":[{"hanzi":"交战","pinyin":"jiāozhàn","vi":"giao chiến"},{"hanzi":"较量","pinyin":"jiàoliàng","vi":"so tài"},{"hanzi":"辩论","pinyin":"biànlùn","vi":"tranh luận"}],"traditional":"交鋒"},{"id":"交汇","hanzi":"交汇","pinyin":"jiāohuì","meaning_vi":"giao nhau, hội tụ","explanation":"交 (giao) + 汇 (tổng hợp/chuyển tiền).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🔀","examples":[{"type":"basic","zh":"三条地铁线在这里交汇。","pinyin":"Sāntiáo dìtiě xiàn zài zhèlǐ jiāohuì.","vi":"Ba tuyến tàu điện ngầm giao nhau tại đây."},{"type":"simple","zh":"武汉是长江与汉江交汇的地方。","pinyin":"Wǔhàn shì Chángjiāng yǔ Hànjiāng jiāohuì de dìfang.","vi":"Vũ Hán là nơi sông Trường Giang và sông Hán giao nhau."},{"type":"compound","zh":"这座城市既是东西方文化交汇之地，又是重要的贸易港口。","pinyin":"Zhè zuò chéngshì jìshì dōngxīfāng wénhuà jiāohuì zhī dì, yòu shì zhòngyào de màoyì gǎngkǒu.","vi":"Thành phố này vừa là nơi giao thoa văn hóa Đông Tây, vừa là cảng thương mại quan trọng."}],"related":[{"hanzi":"汇合","pinyin":"huìhé","vi":"hội tụ"},{"hanzi":"交叉","pinyin":"jiāochā","vi":"giao nhau"},{"hanzi":"交汇点","pinyin":"jiāohuìdiǎn","vi":"điểm giao"}],"traditional":"交匯"},{"id":"胶卷","hanzi":"胶卷","pinyin":"jiāojuǎn","meaning_vi":"cuộn phim chụp ảnh","explanation":"胶 (keo dán/cao su) + 卷 (cuộn).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","do-vat"],"image":"🎞️","examples":[{"type":"basic","zh":"我买了两卷胶卷。","pinyin":"Wǒ mǎile liǎng juǎn jiāojuǎn.","vi":"Tôi đã mua hai cuộn phim."},{"type":"simple","zh":"爷爷的旧相机里还装着一卷没冲洗的胶卷。","pinyin":"Yéye de jiù xiàngjī lǐ hái zhuāngzhe yìjuǎn méi chōngxǐ de jiāojuǎn.","vi":"Trong chiếc máy ảnh cũ của ông vẫn còn một cuộn phim chưa rửa."},{"type":"compound","zh":"虽然数码相机很方便，但是不少摄影爱好者仍然喜欢用胶卷。","pinyin":"Suīrán shùmǎ xiàngjī hěn fāngbiàn, dànshì bùshǎo shèyǐng àihàozhě réngrán xǐhuan yòng jiāojuǎn.","vi":"Tuy máy ảnh kỹ thuật số rất tiện, nhưng nhiều người yêu nhiếp ảnh vẫn thích dùng phim."}],"related":[{"hanzi":"相机","pinyin":"xiàngjī","vi":"máy ảnh"},{"hanzi":"底片","pinyin":"dǐpiàn","vi":"phim âm bản"},{"hanzi":"数码","pinyin":"shùmǎ","vi":"kỹ thuật số"}],"traditional":"膠捲"},{"id":"焦距","hanzi":"焦距","pinyin":"jiāojù","meaning_vi":"tiêu cự (ống kính)","explanation":"焦 (tiêu điểm/sốt ruột) + 距 (距).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","khoa-hoc"],"image":"📷","examples":[{"type":"basic","zh":"请调好镜头焦距。","pinyin":"Qǐngtiáo hǎo jìngtóu jiāojù.","vi":"Hãy chỉnh tiêu cự ống kính cho chuẩn."},{"type":"simple","zh":"这款长焦镜头的焦距可以达到六百毫米。","pinyin":"Zhè kuǎn cháng jiāo jìngtóu de jiāojù kěyǐ dádào liù bǎi háomǐ.","vi":"Tiêu cự của ống kính tele này có thể đạt 600 mm."},{"type":"compound","zh":"如果焦距没有对准，拍出来的照片就会模糊不清。","pinyin":"Rúguǒ jiāojù méiyǒu duìzhǔn, pāi chūlái de zhàopiàn jiù huì móhubùqīng.","vi":"Nếu không chỉnh đúng tiêu cự, ảnh chụp ra sẽ bị mờ."}],"related":[{"hanzi":"镜头","pinyin":"jìngtóu","vi":"ống kính"},{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"},{"hanzi":"对焦","pinyin":"duìjiāo","vi":"lấy nét"}]},{"id":"教科书","hanzi":"教科书","pinyin":"jiàokēshū","meaning_vi":"sách giáo khoa","explanation":"教 (dạy) + 科 (khoa học/môn học) + 书 (sách).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","do-vat"],"image":"📚","examples":[{"type":"basic","zh":"这是新版教科书。","pinyin":"Zhè shì xīnbǎn jiàokēshū.","vi":"Đây là sách giáo khoa phiên bản mới."},{"type":"simple","zh":"这位科学家的发现已经被写进了中学物理教科书。","pinyin":"Zhè wèi kēxuéjiā de fāxiàn yǐjīng bèi xiě jìnle zhōngxué wùlǐ jiàokēshū.","vi":"Phát hiện của nhà khoa học này đã được đưa vào sách giáo khoa vật lý trung học."},{"type":"compound","zh":"这场战役打得十分漂亮，因此被称为教科书式的胜利。","pinyin":"Zhè chǎng zhànyì dǎ de shífēn piàoliang, yīncǐ bèi chēngwéi jiàokēshū shì de shènglì.","vi":"Trận đánh này diễn ra cực kỳ đẹp mắt, vì vậy được gọi là chiến thắng kiểu mẫu như sách giáo khoa."}],"related":[{"hanzi":"课本","pinyin":"kèběn","vi":"sách giáo khoa"},{"hanzi":"教材","pinyin":"jiàocái","vi":"giáo trình"},{"hanzi":"参考书","pinyin":"cānkǎoshū","vi":"sách tham khảo"}],"traditional":"教科書"},{"id":"焦虑症","hanzi":"焦虑症","pinyin":"jiāolǜzhèng","meaning_vi":"rối loạn lo âu","explanation":"焦 (tiêu điểm/sốt ruột) + 虑 (lo lắng/suy nghĩ) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"她患上了焦虑症。","pinyin":"Tā huànshàngle jiāolǜzhèng.","vi":"Cô ấy mắc chứng rối loạn lo âu."},{"type":"simple","zh":"医生建议他每周去心理科治疗焦虑症。","pinyin":"Yīshēng jiànyì tā měizhōu qù xīn lǐkē zhìliáo jiāolǜzhèng.","vi":"Bác sĩ khuyên anh ấy mỗi tuần đến khoa tâm lý để điều trị chứng rối loạn lo âu."},{"type":"compound","zh":"虽然焦虑症让他夜里失眠，但是坚持跑步后他好多了。","pinyin":"Suīrán jiāolǜzhèng ràng tā yèlǐ shīmián, dànshì jiānchí pǎobù hòu tā hǎoduō le.","vi":"Tuy chứng rối loạn lo âu khiến anh ấy mất ngủ về đêm, nhưng sau khi kiên trì chạy bộ anh ấy đã đỡ hơn nhiều."}],"related":[{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"抑郁症","pinyin":"yìyùzhèng","vi":"trầm cảm"},{"hanzi":"心理健康","pinyin":"xīnlǐjiànkāng","vi":"sức khỏe tâm lý"}],"traditional":"焦慮症"},{"id":"交融","hanzi":"交融","pinyin":"jiāoróng","meaning_vi":"giao hòa, hòa quyện","explanation":"交 (giao) + 融 (hòa tan/tài chính).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🤝","examples":[{"type":"basic","zh":"东西方文化在这里交融。","pinyin":"Dōngxīfāng wénhuà zài zhèlǐ jiāoróng.","vi":"Văn hóa phương Đông và phương Tây hòa quyện tại đây."},{"type":"simple","zh":"这首歌让古筝和电子乐完美交融。","pinyin":"Zhè shǒu gē ràng gǔzhēng hé diànzǐ yuè wánměi jiāoróng.","vi":"Bài hát này khiến đàn tranh và nhạc điện tử hòa quyện một cách hoàn hảo."},{"type":"compound","zh":"这座古镇既保留了老建筑，又让新旧生活自然交融。","pinyin":"Zhè zuò gǔzhèn jì bǎoliúle lǎo jiànzhù, yòu ràng xīn jiù shēnghuó zìrán jiāoróng.","vi":"Thị trấn cổ này vừa giữ lại những công trình cũ, vừa để nếp sống mới và cũ hòa quyện tự nhiên."}],"related":[{"hanzi":"融合","pinyin":"rónghé","vi":"dung hợp"},{"hanzi":"交流","pinyin":"jiāoliú","vi":"giao lưu"},{"hanzi":"水乳交融","pinyin":"shuǐrǔjiāoróng","vi":"hòa quyện khăng khít"}]},{"id":"交响乐","hanzi":"交响乐","pinyin":"jiāoxiǎngyuè","meaning_vi":"nhạc giao hưởng","explanation":"交 (giao) + 响 (vang) + 乐 (vui vẻ/lạc quan).","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🎼","examples":[{"type":"basic","zh":"他爱听交响乐。","pinyin":"Tā ài tīng jiāoxiǎngyuè.","vi":"Anh ấy thích nghe nhạc giao hưởng."},{"type":"simple","zh":"周六晚上我们去音乐厅听了一场交响乐。","pinyin":"Zhōuliù wǎnshang wǒmen qù yīnyuètīng tīngle yì chǎng jiāoxiǎngyuè.","vi":"Tối thứ Bảy chúng tôi đến nhà hát nghe một buổi hòa nhạc giao hưởng."},{"type":"compound","zh":"只要一听贝多芬的交响乐，我就觉得浑身充满力量。","pinyin":"Zhǐyào yì tīng Bèiduōfēn de jiāoxiǎngyuè, wǒ jiù juéde húnshēn chōngmǎn lìliàng.","vi":"Chỉ cần nghe nhạc giao hưởng của Beethoven là tôi thấy toàn thân tràn đầy sức mạnh."}],"related":[{"hanzi":"管弦乐","pinyin":"guǎnxiányuè","vi":"nhạc giao hưởng dàn nhạc"},{"hanzi":"交响乐团","pinyin":"jiāoxiǎngyuètuán","vi":"dàn nhạc giao hưởng"},{"hanzi":"古典音乐","pinyin":"gǔdiǎnyīnyuè","vi":"nhạc cổ điển"}],"traditional":"交響樂"},{"id":"教学相长","hanzi":"教学相长","pinyin":"jiàoxué-xiāngzhǎng","meaning_vi":"dạy và học cùng giúp nhau tiến bộ","explanation":"教 (dạy) + 学 (học thuật/học thuyết) + 相 (tương hỗ/tướng mạo) + 长 (dài).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🤝","examples":[{"type":"basic","zh":"教学相长，老师也在进步。","pinyin":"Jiàoxuéxiāngzhǎng, lǎoshī yě zài jìnbù.","vi":"Dạy và học cùng giúp nhau tiến bộ, giáo viên cũng đang tiến bộ."},{"type":"simple","zh":"王老师常说课堂上的讨论就是教学相长。","pinyin":"Wáng lǎoshī cháng shuō kètáng shang de tǎolùn jiùshì jiàoxuéxiāngzhǎng.","vi":"Thầy Vương thường nói thảo luận trên lớp chính là dạy và học cùng giúp nhau tiến bộ."},{"type":"compound","zh":"因为学生的提问常常难住我，所以我体会到了教学相长。","pinyin":"Yīnwèi xuéshēng de tíwèn chángcháng nánzhù wǒ, suǒyǐ wǒ tǐhuì dàole jiàoxuéxiāngzhǎng.","vi":"Vì câu hỏi của học sinh thường làm tôi bí, nên tôi đã thấm thía việc dạy và học giúp nhau cùng tiến bộ."}],"related":[{"hanzi":"教学","pinyin":"jiàoxué","vi":"dạy học"},{"hanzi":"互相学习","pinyin":"hùxiāngxuéxí","vi":"học hỏi lẫn nhau"},{"hanzi":"师生","pinyin":"shīshēng","vi":"thầy trò"}],"traditional":"教學相長"},{"id":"教研","hanzi":"教研","pinyin":"jiàoyán","meaning_vi":"giảng dạy và nghiên cứu","explanation":"教 (dạy) + 研 (nghiên cứu).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","cong-viec"],"image":"🔬","examples":[{"type":"basic","zh":"下午有教研活动。","pinyin":"Xiàwǔ yǒu jiàoyán huódòng.","vi":"Buổi chiều có hoạt động sinh hoạt chuyên môn giảng dạy."},{"type":"simple","zh":"数学组每周三在三楼会议室开教研会。","pinyin":"Shùxué zǔ měi Zhōusān zài sān lóu huìyìshì kāi jiàoyán huì.","vi":"Tổ Toán họp chuyên môn giảng dạy vào thứ Tư hằng tuần ở phòng họp tầng ba."},{"type":"compound","zh":"只要教研工作做扎实了，课堂质量就会明显提高。","pinyin":"Zhǐyào jiàoyán gōngzuò zuò zhāshi le, kètáng zhìliàng jiù huì míngxiǎn tígāo.","vi":"Chỉ cần công tác nghiên cứu giảng dạy được làm chắc chắn, chất lượng giờ học sẽ nâng lên rõ rệt."}],"related":[{"hanzi":"教学","pinyin":"jiàoxué","vi":"giảng dạy"},{"hanzi":"科研","pinyin":"kēyán","vi":"nghiên cứu khoa học"},{"hanzi":"教研室","pinyin":"jiàoyánshì","vi":"tổ bộ môn"}]},{"id":"焦灼","hanzi":"焦灼","pinyin":"jiāozhuó","meaning_vi":"lo lắng bồn chồn như lửa đốt","explanation":"焦 (tiêu điểm/sốt ruột) + 灼 (nóng rát/sáng rõ).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"他焦灼地等着消息。","pinyin":"Tā jiāozhuó de děngzhe xiāoxi.","vi":"Anh ấy sốt ruột như lửa đốt chờ tin tức."},{"type":"simple","zh":"手术室外的家属们个个神情焦灼。","pinyin":"Shǒushù shìwài de jiāshǔmen gègè shénqíng jiāozhuó.","vi":"Người nhà bên ngoài phòng mổ ai nấy đều mang vẻ mặt lo lắng bồn chồn."},{"type":"compound","zh":"虽然比分一直很焦灼，但是主队最后还是赢了。","pinyin":"Suīrán bǐfēn yìzhí hěn jiāozhuó, dànshì zhǔduì zuìhòu háishì yíng le.","vi":"Tuy tỉ số luôn giằng co căng thẳng, nhưng cuối cùng đội chủ nhà vẫn thắng."}],"related":[{"hanzi":"焦急","pinyin":"jiāojí","vi":"sốt ruột"},{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"不安","pinyin":"bù'ān","vi":"bất an"}]},{"id":"接班人","hanzi":"接班人","pinyin":"jiēbānrén","meaning_vi":"người kế nhiệm, thế hệ kế thừa","explanation":"接 (接) + 班 (lớp học) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","cong-viec"],"image":"🌱","examples":[{"type":"basic","zh":"他是公司的接班人。","pinyin":"Tā shì gōngsī de jiēbānrén.","vi":"Anh ấy là người kế nhiệm của công ty."},{"type":"simple","zh":"老厂长退休前一直在物色合适的接班人。","pinyin":"Lǎo chǎngzhǎng tuìxiū qián yìzhí zài wùsè héshì de jiēbānrén.","vi":"Trước khi nghỉ hưu, ông giám đốc nhà máy luôn tìm kiếm người kế nhiệm phù hợp."},{"type":"compound","zh":"如果找不到可靠的接班人，这家老字号就可能失传。","pinyin":"Rúguǒ zhǎobúdào kěkào de jiēbānrén, zhè jiālǎo zìhao jiù kěnéng shīchuán.","vi":"Nếu không tìm được người kế nhiệm đáng tin cậy, thương hiệu lâu đời này có thể bị thất truyền."}],"related":[{"hanzi":"继承人","pinyin":"jìchéngrén","vi":"người thừa kế"},{"hanzi":"接班","pinyin":"jiēbān","vi":"kế nhiệm"},{"hanzi":"后继有人","pinyin":"hòujìyǒurén","vi":"có người kế tục"}]},{"id":"接地气","hanzi":"接地气","pinyin":"jiēdìqì","meaning_vi":"gần gũi với đời sống thực tế bình dân","explanation":"接 (tiếp – nối, chạm) + 地气 (địa khí – hơi đất) → chạm hơi đất; từ mới chỉ gần gũi với đời sống, hợp ý người bình dân. VD: 这个广告很接地气.","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"🌱","examples":[{"type":"basic","zh":"这部电影很接地气。","pinyin":"Zhè bù diànyǐng hěn jiēdìqì.","vi":"Bộ phim này rất gần gũi với đời sống thường ngày."},{"type":"simple","zh":"他用方言写的段子特别接地气。","pinyin":"Tāyòng fāngyán xiě de duànzi tèbié jiēdìqì.","vi":"Những mẩu chuyện cười anh ấy viết bằng tiếng địa phương đặc biệt gần gũi đời thường."},{"type":"compound","zh":"这位教授讲课既有深度又接地气，学生们都爱听。","pinyin":"Zhè wèi jiàoshòu jiǎngkè jìyǒu shēndù yòu jiēdìqì, xuéshēngmen dōu ài tīng.","vi":"Vị giáo sư này giảng bài vừa sâu sắc vừa gần gũi, sinh viên ai cũng thích nghe."}],"related":[{"hanzi":"通俗","pinyin":"tōngsú","vi":"bình dân dễ hiểu"},{"hanzi":"贴近生活","pinyin":"tiējìnshēnghuó","vi":"gần gũi đời sống"},{"hanzi":"高高在上","pinyin":"gāogāozàishàng","vi":"xa rời quần chúng"}],"traditional":"接地氣"},{"id":"接轨","hanzi":"接轨","pinyin":"jiēguǐ","meaning_vi":"hòa nhập, kết nối đồng bộ (với quốc tế)","explanation":"接 (接) + 轨 (đường ray/quỹ đạo).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚆","examples":[{"type":"basic","zh":"我们要与国际接轨。","pinyin":"Wǒmen yào yǔ Guójì jiēguǐ.","vi":"Chúng ta phải hội nhập với quốc tế."},{"type":"simple","zh":"这所大学的课程体系已经和国际标准接轨。","pinyin":"Zhè suǒ dàxué de kèchéng tǐxì yǐjīng hé Guójì biāozhǔn jiēguǐ.","vi":"Hệ thống chương trình của trường đại học này đã đồng bộ với chuẩn quốc tế."},{"type":"compound","zh":"一旦检测标准与欧盟接轨，我们的水果就能出口了。","pinyin":"Yídàn jiǎncè biāozhǔn yǔ Ōuméng jiēguǐ, wǒmen de shuǐguǒ jiù néng chūkǒu le.","vi":"Một khi tiêu chuẩn kiểm định đồng bộ với EU, trái cây của chúng ta sẽ có thể xuất khẩu."}],"related":[{"hanzi":"与国际接轨","pinyin":"yǔ Guójì jiēguǐ","vi":"hội nhập quốc tế"},{"hanzi":"对接","pinyin":"duìjiē","vi":"kết nối"},{"hanzi":"融入","pinyin":"róngrù","vi":"hòa nhập"}],"traditional":"接軌"},{"id":"接纳","hanzi":"接纳","pinyin":"jiēnà","meaning_vi":"tiếp nhận, đón nhận","explanation":"接 (接) + 纳 (tiếp thu/chứa đựng).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"新同学很快被大家接纳了。","pinyin":"Xīn tóngxué hěn kuài bèi dàjiā jiēnà le.","vi":"Bạn học mới nhanh chóng được mọi người đón nhận."},{"type":"simple","zh":"这家收容所去年接纳了三百多只流浪猫。","pinyin":"Zhè jiā shōuróngsuǒ qùnián jiēnàle sān bǎi duō zhī liúlàngmāo.","vi":"Năm ngoái trại cứu hộ này đã tiếp nhận hơn ba trăm con mèo hoang."},{"type":"compound","zh":"只要你真诚待人，别人就会慢慢接纳你。","pinyin":"Zhǐyào nǐ zhēnchéng dàirén, biérén jiù huì mànmàn jiēnà nǐ.","vi":"Chỉ cần bạn đối xử chân thành, người khác sẽ dần dần đón nhận bạn."}],"related":[{"hanzi":"接受","pinyin":"jiēshòu","vi":"tiếp nhận"},{"hanzi":"容纳","pinyin":"róngnà","vi":"dung nạp"},{"hanzi":"排斥","pinyin":"páichì","vi":"bài xích"}],"traditional":"接納"},{"id":"揭晓","hanzi":"揭晓","pinyin":"jiēxiǎo","meaning_vi":"công bố kết quả (giải thưởng/kỳ thi)","explanation":"揭 (vạch trần/mở ra) + 晓 (hiểu biết/bình minh).","hsk_level":"7-9","tags":["dong-tu"],"image":"📢","examples":[{"type":"basic","zh":"比赛结果明天揭晓。","pinyin":"Bǐsài jiéguǒ míngtiān jiēxiǎo.","vi":"Kết quả cuộc thi sẽ được công bố vào ngày mai."},{"type":"simple","zh":"今年的金马奖将于本周六晚上正式揭晓。","pinyin":"Jīnnián de Jīnmǎjiǎng jiāng yú běn Zhōuliù wǎnshang zhèngshì jiēxiǎo.","vi":"Giải Kim Mã năm nay sẽ chính thức công bố vào tối thứ Bảy tuần này."},{"type":"compound","zh":"答案一揭晓，全场观众就欢呼起来。","pinyin":"Dá'àn yì jiēxiǎo, quánchǎng guānzhòng jiù huānhū qǐlái.","vi":"Đáp án vừa được công bố, khán giả cả hội trường liền reo hò."}],"related":[{"hanzi":"公布","pinyin":"gōngbù","vi":"công bố"},{"hanzi":"揭开","pinyin":"jiēkāi","vi":"vén mở"},{"hanzi":"宣布","pinyin":"xuānbù","vi":"tuyên bố"}],"traditional":"揭曉"},{"id":"解答","hanzi":"解答","pinyin":"jiědá","meaning_vi":"giải đáp","explanation":"解 (giải quyết/hiểu) + 答 (答).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"💡","examples":[{"type":"basic","zh":"老师耐心解答问题。","pinyin":"Lǎoshī nàixīn jiědá wèntí.","vi":"Thầy giáo kiên nhẫn giải đáp câu hỏi."},{"type":"simple","zh":"客服人员在线解答了我关于退货的疑问。","pinyin":"Kèfú rényuán zàixiàn jiědále wǒ guānyú tuìhuò de yíwèn.","vi":"Nhân viên chăm sóc khách hàng đã giải đáp trực tuyến thắc mắc của tôi về việc trả hàng."},{"type":"compound","zh":"如果你有不懂的地方，我课后就可以为你解答。","pinyin":"Rúguǒ nǐ yǒu bù dǒng de dìfang, wǒ kè hòu jiù kě yǐwèi nǐ jiědá.","vi":"Nếu em có chỗ nào chưa hiểu, sau giờ học thầy có thể giải đáp cho em."}],"related":[{"hanzi":"回答","pinyin":"huídá","vi":"trả lời"},{"hanzi":"解释","pinyin":"jiěshì","vi":"giải thích"},{"hanzi":"答疑","pinyin":"dáyí","vi":"giải đáp thắc mắc"}]},{"id":"解读","hanzi":"解读","pinyin":"jiědú","meaning_vi":"giải mã, phân tích chuyên sâu","explanation":"解 (giải quyết/hiểu) + 读 (đọc (thành tiếng)).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"专家解读新政策。","pinyin":"Zhuānjiā jiědú xīn zhèngcè.","vi":"Chuyên gia phân tích chính sách mới."},{"type":"simple","zh":"这篇文章从心理学角度解读了年轻人的消费习惯。","pinyin":"Zhè piān wénzhāng cóng xīnlǐxué jiǎodù jiědúle niánqīngrén de xiāofèi xíguàn.","vi":"Bài viết này phân tích thói quen tiêu dùng của giới trẻ từ góc độ tâm lý học."},{"type":"compound","zh":"即使是同一首诗，不同读者的解读也可能完全不同。","pinyin":"Jíshǐ shì tóngyī shǒu shī, bùtóng dúzhě de jiědú yě kěnéng wánquán bùtóng.","vi":"Dù là cùng một bài thơ, cách lý giải của mỗi độc giả cũng có thể hoàn toàn khác nhau."}],"related":[{"hanzi":"解释","pinyin":"jiěshì","vi":"giải thích"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"理解","pinyin":"lǐjiě","vi":"hiểu"}],"traditional":"解讀"},{"id":"解说","hanzi":"解说","pinyin":"jiěshuō","meaning_vi":"thuyết minh, bình luận (trận đấu/triển lãm)","explanation":"解 (giải quyết/hiểu) + 说 (nói).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🎙️","examples":[{"type":"basic","zh":"他负责解说足球赛。","pinyin":"Tā fùzé jiěshuō zúqiúsài.","vi":"Anh ấy phụ trách bình luận trận bóng đá."},{"type":"simple","zh":"讲解员正在为游客解说青铜器的来历。","pinyin":"Jiǎngjiěyuán zhèngzài wèi yóukè jiěshuō qīngtóngqì de láilì.","vi":"Hướng dẫn viên đang thuyết minh cho du khách về nguồn gốc của đồ đồng."},{"type":"compound","zh":"虽然他第一次解说比赛，但是语言很专业。","pinyin":"Suīrán tā dìyīcì jiěshuō bǐsài, dànshì yǔyán hěn zhuānyè.","vi":"Tuy là lần đầu bình luận trận đấu, nhưng lời lẽ của anh ấy rất chuyên nghiệp."}],"related":[{"hanzi":"解说员","pinyin":"jiěshuōyuán","vi":"bình luận viên"},{"hanzi":"讲解","pinyin":"jiǎngjiě","vi":"giảng giải"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"}],"traditional":"解說"},{"id":"甲骨文","hanzi":"甲骨文","pinyin":"jiǎgǔwén","meaning_vi":"chữ Giáp cốt","explanation":"甲 (giáp (thứ nhất trong thiên can)) + 骨 (骨) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["danh-tu","van-hoa","ngon-ngu"],"image":"🦴","examples":[{"type":"basic","zh":"这是商代的甲骨文。","pinyin":"Zhè shì Shāngdài de jiǎgǔwén.","vi":"Đây là chữ Giáp cốt thời nhà Thương."},{"type":"simple","zh":"博物馆里展出了一块刻满甲骨文的牛骨。","pinyin":"Bówùguǎn lǐ zhǎnchūle yíkuài kè mǎn jiǎgǔwén de niú gǔ.","vi":"Bảo tàng trưng bày một mảnh xương bò khắc đầy chữ Giáp cốt."},{"type":"compound","zh":"因为甲骨文年代久远，所以很多字至今无人能识。","pinyin":"Yīnwèi jiǎgǔwén niándài jiǔyuǎn, suǒyǐ hěn duō zì zhìjīn wúrén néng shí.","vi":"Vì chữ Giáp cốt có niên đại quá xa xưa, nên đến nay nhiều chữ vẫn chưa ai đọc được."}],"related":[{"hanzi":"汉字","pinyin":"hànzì","vi":"chữ Hán"},{"hanzi":"金文","pinyin":"jīnwén","vi":"chữ Kim văn"},{"hanzi":"象形文字","pinyin":"xiàngxíngwénzì","vi":"chữ tượng hình"}]},{"id":"简报","hanzi":"简报","pinyin":"jiǎnbào","meaning_vi":"bản tin tóm tắt","explanation":"简 (đơn giản/ngắn gọn) + 报 (报).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📰","examples":[{"type":"basic","zh":"请把简报发给我。","pinyin":"Qǐng bǎ jiǎnbào fāgěi wǒ.","vi":"Vui lòng gửi bản tin tóm tắt cho tôi."},{"type":"simple","zh":"秘书每天早上都会整理一份行业简报。","pinyin":"Mìshū měitiān zǎoshang dōuhuì zhěnglǐ yí fèn hángyè jiǎnbào.","vi":"Mỗi sáng thư ký đều soạn một bản tin tóm tắt về ngành."},{"type":"compound","zh":"简报既要简短，又要把重点写清楚。","pinyin":"Jiǎnbào jì yào jiǎnduǎn, yòu yào bǎ zhòngdiǎn xiě qīngchu.","vi":"Bản tin tóm tắt vừa phải ngắn gọn, vừa phải viết rõ các điểm chính."}],"related":[{"hanzi":"报告","pinyin":"bàogào","vi":"báo cáo"},{"hanzi":"简讯","pinyin":"jiǎnxùn","vi":"tin vắn"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"}],"traditional":"簡報"},{"id":"简化","hanzi":"简化","pinyin":"jiǎnhuà","meaning_vi":"đơn giản hóa, tinh giản","explanation":"简 (đơn giản/ngắn gọn) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✂️","examples":[{"type":"basic","zh":"办事流程简化了。","pinyin":"Bànshì liúchéng jiǎnhuà le.","vi":"Quy trình làm thủ tục đã được đơn giản hóa."},{"type":"simple","zh":"银行简化了手机开户的审核步骤。","pinyin":"Yínháng jiǎnhuàle shǒujī kāihù de shěnhé bùzhòu.","vi":"Ngân hàng đã tinh giản các bước xét duyệt mở tài khoản qua điện thoại."},{"type":"compound","zh":"如果把这道公式简化一下，计算就会快很多。","pinyin":"Rúguǒ bǎ zhè dào gōngshì jiǎnhuà yíxià, jìsuàn jiù huì kuài hěn duō.","vi":"Nếu đơn giản hóa công thức này một chút, việc tính toán sẽ nhanh hơn nhiều."}],"related":[{"hanzi":"简单","pinyin":"jiǎndān","vi":"đơn giản"},{"hanzi":"简化字","pinyin":"jiǎnhuàzì","vi":"chữ giản thể"},{"hanzi":"复杂化","pinyin":"fùzáhuà","vi":"phức tạp hóa"}],"traditional":"簡化"},{"id":"简明","hanzi":"简明","pinyin":"jiǎnmíng","meaning_vi":"ngắn gọn rõ ràng","explanation":"简 (đơn giản/ngắn gọn) + 明 (sáng suốt/rõ ràng).","hsk_level":"7-9","tags":["tinh-tu"],"image":"📄","examples":[{"type":"basic","zh":"说明书写得很简明。","pinyin":"Shuōmíng shūxiě de hěn jiǎnmíng.","vi":"Sách hướng dẫn viết rất ngắn gọn rõ ràng."},{"type":"simple","zh":"他用一张简明的图表说明了全年销量。","pinyin":"Tāyòng yì zhāng jiǎnmíng de túbiǎo shuōmíngle quánnián xiāoliàng.","vi":"Anh ấy dùng một biểu đồ ngắn gọn rõ ràng để trình bày doanh số cả năm."},{"type":"compound","zh":"这本教材不但简明易懂，而且例子很实用。","pinyin":"Zhè běn jiàocái búdàn jiǎnmíng yìdǒng, érqiě lìzi hěn shíyòng.","vi":"Cuốn giáo trình này không những ngắn gọn dễ hiểu mà ví dụ còn rất thực tế."}],"related":[{"hanzi":"简洁","pinyin":"jiǎnjié","vi":"ngắn gọn"},{"hanzi":"明了","pinyin":"míngliǎo","vi":"rõ ràng"},{"hanzi":"简明扼要","pinyin":"jiǎnmíng'èyào","vi":"ngắn gọn súc tích"}],"traditional":"簡明"},{"id":"剪纸","hanzi":"剪纸","pinyin":"jiǎnzhǐ","meaning_vi":"nghệ thuật cắt giấy truyền thống","explanation":"剪 (cắt) + 纸 (giấy).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"✂️","examples":[{"type":"basic","zh":"奶奶擅长剪纸。","pinyin":"Nǎinai shàncháng jiǎnzhǐ.","vi":"Bà nội rất giỏi cắt giấy nghệ thuật."},{"type":"simple","zh":"春节前，妈妈在窗户上贴了几张红色剪纸。","pinyin":"Chūnjié qián, māma zài chuānghu shang tiēle jǐ zhāng hóngsè jiǎnzhǐ.","vi":"Trước Tết, mẹ dán mấy bức tranh cắt giấy màu đỏ lên cửa sổ."},{"type":"compound","zh":"虽然剪纸看起来简单，但是剪好一幅要很大耐心。","pinyin":"Suīrán jiǎnzhǐ kànqǐlái jiǎndān, dànshì jiǎn hǎo yì fú yào hěn dà nàixīn.","vi":"Tuy cắt giấy trông có vẻ đơn giản, nhưng cắt đẹp một bức cần rất nhiều kiên nhẫn."}],"related":[{"hanzi":"窗花","pinyin":"chuānghuā","vi":"hoa giấy dán cửa"},{"hanzi":"剪刀","pinyin":"jiǎndāo","vi":"cái kéo"},{"hanzi":"民间艺术","pinyin":"mínjiānyìshù","vi":"nghệ thuật dân gian"}],"traditional":"剪紙"},{"id":"奖杯","hanzi":"奖杯","pinyin":"jiǎngbēi","meaning_vi":"cúp vô địch","explanation":"奖 (khen thưởng) + 杯 (cốc).","hsk_level":"7-9","tags":["danh-tu","the-thao","do-vat"],"image":"🏆","examples":[{"type":"basic","zh":"他高高举起奖杯。","pinyin":"Tā gāo gāo jǔqǐ jiǎngbēi.","vi":"Anh ấy giơ cao chiếc cúp."},{"type":"simple","zh":"队长把冠军奖杯放在了学校的荣誉室里。","pinyin":"Duìzhǎng bǎ guànjūn jiǎngbēi fàng zài le xuéxiào de róngyù shì lǐ.","vi":"Đội trưởng đặt chiếc cúp vô địch trong phòng truyền thống của trường."},{"type":"compound","zh":"虽然这只奖杯不值钱，但是对我意义重大。","pinyin":"Suīrán zhè zhī jiǎngbēi bù zhíqián, dànshì duì wǒ yìyì zhòngdà.","vi":"Tuy chiếc cúp này không đáng tiền, nhưng nó có ý nghĩa rất lớn với tôi."}],"related":[{"hanzi":"奖牌","pinyin":"jiǎngpái","vi":"huy chương"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"nhà vô địch"},{"hanzi":"颁奖","pinyin":"bānjiǎng","vi":"trao giải"}],"traditional":"獎杯"},{"id":"奖牌","hanzi":"奖牌","pinyin":"jiǎngpái","meaning_vi":"huy chương","explanation":"奖 (khen thưởng) + 牌 (牌).","hsk_level":"7-9","tags":["danh-tu","the-thao","do-vat"],"image":"🥇","examples":[{"type":"basic","zh":"她赢得了三枚奖牌。","pinyin":"Tā yíng déle sān méi jiǎngpái.","vi":"Cô ấy đã giành được ba tấm huy chương."},{"type":"simple","zh":"中国游泳队在本届亚运会上收获了大量奖牌。","pinyin":"Zhōngguó yóuyǒng duì zài běnjiè Yàyùnhuì shang shōuhuòle dàliàng jiǎngpái.","vi":"Đội bơi Trung Quốc đã thu về rất nhiều huy chương tại kỳ Á vận hội này."},{"type":"compound","zh":"即使拿不到奖牌，他也要坚持跑完全程。","pinyin":"Jíshǐ ná búdào jiǎngpái, tā yě yào jiānchí pǎo wán quánchéng.","vi":"Dù không giành được huy chương, anh ấy vẫn quyết chạy hết toàn bộ chặng đua."}],"related":[{"hanzi":"金牌","pinyin":"jīnpái","vi":"huy chương vàng"},{"hanzi":"银牌","pinyin":"yínpái","vi":"huy chương bạc"},{"hanzi":"奖杯","pinyin":"jiǎngbēi","vi":"cúp"}],"traditional":"獎牌"},{"id":"讲坛","hanzi":"讲坛","pinyin":"jiǎngtán","meaning_vi":"diễn đàn, bục giảng","explanation":"讲 (giảng) + 坛 (đàn – bục, đàn) → bục giảng, diễn đàn để giảng giải, thuyết trình. VD: 百家讲坛 (chương trình nổi tiếng của CCTV).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎤","examples":[{"type":"basic","zh":"他走上了讲坛。","pinyin":"Tā zǒushàngle jiǎngtán.","vi":"Ông ấy bước lên bục giảng."},{"type":"simple","zh":"这位老教授在大学讲坛上站了四十年。","pinyin":"Zhè wèi lǎo jiàoshòu zài dàxué jiǎngtán shang zhànle sìshí nián.","vi":"Vị giáo sư già này đã đứng trên bục giảng đại học suốt bốn mươi năm."},{"type":"compound","zh":"虽然他已经八十岁了，但是仍然活跃在讲坛上。","pinyin":"Suīrán tā yǐjīng bāshí suì le, dànshì réngrán huóyuè zài jiǎngtán shang.","vi":"Tuy đã tám mươi tuổi, nhưng ông vẫn hoạt động sôi nổi trên diễn đàn."}],"related":[{"hanzi":"讲台","pinyin":"jiǎngtái","vi":"bục giảng"},{"hanzi":"论坛","pinyin":"lùntán","vi":"diễn đàn"},{"hanzi":"讲座","pinyin":"jiǎngzuò","vi":"bài giảng chuyên đề"}],"traditional":"講壇"},{"id":"讲学","hanzi":"讲学","pinyin":"jiǎngxué","meaning_vi":"diễn thuyết học thuật","explanation":"讲 (讲) + 学 (học thuật/học thuyết).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"他应邀来华讲学。","pinyin":"Tā yìngyāo láihuá jiǎngxué.","vi":"Ông ấy được mời sang Trung Quốc giảng dạy học thuật."},{"type":"simple","zh":"张教授下个月要去北京大学讲学一周。","pinyin":"Zhāng jiàoshòu xiàgèyuè yào qù Běijīngdàxué jiǎngxué yìzhōu.","vi":"Tháng sau giáo sư Trương sẽ đến Đại học Bắc Kinh thuyết giảng một tuần."},{"type":"compound","zh":"每当他到外地讲学，礼堂里就坐满了年轻学者。","pinyin":"Měidāng tā dào wàidì jiǎngxué, lǐtáng lǐ jiù zuò mǎnle niánqīng xuézhě.","vi":"Mỗi khi ông đến nơi khác thuyết giảng, hội trường lại chật kín các học giả trẻ."}],"related":[{"hanzi":"讲座","pinyin":"jiǎngzuò","vi":"bài giảng chuyên đề"},{"hanzi":"演讲","pinyin":"yǎnjiǎng","vi":"diễn thuyết"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"}],"traditional":"講學"},{"id":"奖学金","hanzi":"奖学金","pinyin":"jiǎngxuéjīn","meaning_vi":"học bổng","explanation":"奖 (tưởng – thưởng) 学 (học) + 金 (kim – tiền) → tiền thưởng cho học tập, học bổng. VD: 申请奖学金, 获得全额奖学金.","hsk_level":"7-9","tags":["danh-tu","hoc-tap","tien-te"],"image":"🎓","examples":[{"type":"basic","zh":"她拿到了奖学金。","pinyin":"Tā nádàole jiǎngxuéjīn.","vi":"Cô ấy đã nhận được học bổng."},{"type":"simple","zh":"他凭优异的成绩申请到了全额奖学金。","pinyin":"Tā píng yōuyì de chéngjì shēnqǐng dàole quán'é jiǎngxuéjīn.","vi":"Nhờ thành tích xuất sắc, anh ấy đã xin được học bổng toàn phần."},{"type":"compound","zh":"如果没有这笔奖学金，我就没法出国读书了。","pinyin":"Rúguǒ méiyǒu zhè bǐ jiǎngxuéjīn, wǒ jiù méifǎ chūguó dúshū le.","vi":"Nếu không có khoản học bổng này, tôi đã không thể ra nước ngoài du học."}],"related":[{"hanzi":"助学金","pinyin":"zhùxuéjīn","vi":"trợ cấp học tập"},{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"},{"hanzi":"学费","pinyin":"xuéfèi","vi":"học phí"}],"traditional":"獎學金"},{"id":"搅拌","hanzi":"搅拌","pinyin":"jiǎobàn","meaning_vi":"khuấy đều, trộn đều","explanation":"Cả hai chữ đều có bộ tài gảy 扌.","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🥄","examples":[{"type":"basic","zh":"把鸡蛋搅拌均匀。","pinyin":"Bǎ jīdàn jiǎobàn jūnyún.","vi":"Đánh trứng cho thật đều."},{"type":"simple","zh":"工人们正在用机器搅拌水泥和沙子。","pinyin":"Gōngrénmen zhèngzài yòng jīqì jiǎobàn shuǐní hé shāzi.","vi":"Công nhân đang dùng máy trộn xi măng với cát."},{"type":"compound","zh":"只要不停地搅拌，酱汁就不会粘锅。","pinyin":"Zhǐyào bùtíng de jiǎobàn, jiàng zhī jiù bú huì zhān guō.","vi":"Chỉ cần khuấy liên tục, nước sốt sẽ không bị dính nồi."}],"related":[{"hanzi":"搅拌机","pinyin":"jiǎobànjī","vi":"máy trộn"},{"hanzi":"混合","pinyin":"hùnhé","vi":"trộn lẫn"},{"hanzi":"搅动","pinyin":"jiǎodòng","vi":"khuấy động"}],"traditional":"攪拌"},{"id":"脚步声","hanzi":"脚步声","pinyin":"jiǎobùshēng","meaning_vi":"tiếng bước chân","explanation":"脚 (脚) + 步 (步) + 声 (thanh thế/tuyên bố).","hsk_level":"7-9","tags":["danh-tu"],"image":"👣","examples":[{"type":"basic","zh":"门外传来脚步声。","pinyin":"Ménwài chuánlái jiǎobùshēng.","vi":"Ngoài cửa vọng vào tiếng bước chân."},{"type":"simple","zh":"深夜的走廊里响起了一阵急促的脚步声。","pinyin":"Shēnyè de zǒuláng lǐ xiǎngqǐle yízhèn jícù de jiǎobùshēng.","vi":"Trong hành lang lúc nửa đêm vang lên một tràng tiếng bước chân vội vã."},{"type":"compound","zh":"一听到爸爸的脚步声，孩子就赶紧关掉了电视。","pinyin":"Yì tīngdào bàba de jiǎobùshēng, háizi jiù gǎnjǐn guāndiàole diànshì.","vi":"Vừa nghe tiếng bước chân của bố, đứa trẻ liền vội tắt tivi."}],"related":[{"hanzi":"脚步","pinyin":"jiǎobù","vi":"bước chân"},{"hanzi":"脚印","pinyin":"jiǎoyìn","vi":"dấu chân"},{"hanzi":"敲门声","pinyin":"qiāoménshēng","vi":"tiếng gõ cửa"}],"traditional":"腳步聲"},{"id":"角逐","hanzi":"角逐","pinyin":"juézhú","meaning_vi":"tranh tài, cạnh tranh quyết liệt","explanation":"角 (角) + 逐 (từng bước/trục xuất).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"十支队伍角逐冠军。","pinyin":"Shí zhī duìwǔ juézhú guànjūn.","vi":"Mười đội tranh tài giành chức vô địch."},{"type":"simple","zh":"五位歌手将在决赛中角逐年度最佳新人奖。","pinyin":"Wǔ wèi gēshǒu jiāng zài juésài zhōng juézhú niándù zuì jiā xīnrén jiǎng.","vi":"Năm ca sĩ sẽ tranh giải Nghệ sĩ mới xuất sắc nhất năm trong đêm chung kết."},{"type":"compound","zh":"虽然参加角逐的企业很多，但是最后只有一家能中标。","pinyin":"Suīrán cānjiā juézhú de qǐyè hěn duō, dànshì zuìhòu zhǐyǒu yìjiā néng zhòngbiāo.","vi":"Tuy có rất nhiều doanh nghiệp tham gia cạnh tranh, nhưng cuối cùng chỉ một đơn vị trúng thầu."}],"related":[{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"thi đấu"},{"hanzi":"争夺","pinyin":"zhēngduó","vi":"tranh giành"}]},{"id":"窘迫","hanzi":"窘迫","pinyin":"jiǒngpò","meaning_vi":"túng quẫn, lúng túng khó xử","explanation":"窘 (túng quẫn/lúng túng) + 迫 (bức bách/ép buộc).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😅","examples":[{"type":"basic","zh":"他的处境很窘迫。","pinyin":"Tā de chǔjìng hěn jiǒngpò.","vi":"Hoàn cảnh của anh ấy rất túng quẫn."},{"type":"simple","zh":"失业那年他家的生活十分窘迫。","pinyin":"Shīyè nà nián tā jiā de shēnghuó shífēn jiǒngpò.","vi":"Năm thất nghiệp đó, cuộc sống gia đình anh ấy vô cùng túng quẫn."},{"type":"compound","zh":"因为忘带钱包，所以他在收银台前窘迫得满脸通红。","pinyin":"Yīnwèi wàng dài qiánbāo, suǒyǐ tā zài shōuyín táiqián jiǒngpò de mǎnliǎn tōnghóng.","vi":"Vì quên mang ví, anh ấy lúng túng đến đỏ bừng mặt trước quầy thu ngân."}],"related":[{"hanzi":"尴尬","pinyin":"gāngà","vi":"lúng túng"},{"hanzi":"困窘","pinyin":"kùnjiǒng","vi":"khốn quẫn"},{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"}]},{"id":"卷入","hanzi":"卷入","pinyin":"juǎnrù","meaning_vi":"bị cuốn vào (vụ việc/tranh chấp)","explanation":"卷 (cuộn) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌀","examples":[{"type":"basic","zh":"他卷入了一场官司。","pinyin":"Tā juǎnrùle yì chǎng guānsi.","vi":"Anh ấy bị cuốn vào một vụ kiện tụng."},{"type":"simple","zh":"这家公司因为数据泄露卷入了多起诉讼。","pinyin":"Zhè jiā gōngsī yīnwèi shùjù xièlù juǎnrùle duō qǐ sùsòng.","vi":"Công ty này bị cuốn vào nhiều vụ kiện vì rò rỉ dữ liệu."},{"type":"compound","zh":"你最好别插手，否则自己也会被卷入纠纷。","pinyin":"Nǐ zuìhǎo bié chāshǒu, fǒuzé zìjǐ yě huì bèi juǎnrù jiūfēn.","vi":"Tốt nhất bạn đừng can thiệp, nếu không chính bạn cũng sẽ bị cuốn vào tranh chấp."}],"related":[{"hanzi":"陷入","pinyin":"xiànrù","vi":"rơi vào"},{"hanzi":"牵连","pinyin":"qiānlián","vi":"liên lụy"},{"hanzi":"纠纷","pinyin":"jiūfēn","vi":"tranh chấp"}],"traditional":"捲入"},{"id":"绝技","hanzi":"绝技","pinyin":"juéjì","meaning_vi":"tuyệt kỹ, tài nghệ độc đáo","explanation":"绝 (tuyệt đối/đoạn tuyệt) + 技 (kỹ thuật).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"他有一手绝技。","pinyin":"Tā yǒuyìshǒu juéjì.","vi":"Anh ấy có một tuyệt kỹ."},{"type":"simple","zh":"这位杂技演员表演了顶碗的绝技。","pinyin":"Zhè wèi zájì yǎnyuán biǎoyǎnle dǐng wǎn de juéjì.","vi":"Diễn viên xiếc này đã biểu diễn tuyệt kỹ đội bát trên đầu."},{"type":"compound","zh":"这门绝技如果没人继承，就会彻底失传。","pinyin":"Zhè mén juéjì rúguǒ méi rén jìchéng, jiù huì chèdǐ shīchuán.","vi":"Nếu không ai kế thừa, tuyệt kỹ này sẽ bị thất truyền hoàn toàn."}],"related":[{"hanzi":"绝活","pinyin":"juéhuó","vi":"tuyệt chiêu"},{"hanzi":"技艺","pinyin":"jìyì","vi":"tài nghệ"},{"hanzi":"本领","pinyin":"běnlǐng","vi":"bản lĩnh"}],"traditional":"絕技"},{"id":"绝境","hanzi":"绝境","pinyin":"juéjìng","meaning_vi":"tình thế tuyệt vọng, bước đường cùng","explanation":"绝 (tuyệt đối/đoạn tuyệt) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["danh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"他们陷入了绝境。","pinyin":"Tāmen xiànrùle juéjìng.","vi":"Họ đã rơi vào bước đường cùng."},{"type":"simple","zh":"被困在雪山上的登山队员已经身处绝境。","pinyin":"Bèi kùn zài xuěshān shang de dēngshān duìyuán yǐjīng shēnchǔ juéjìng.","vi":"Những nhà leo núi bị mắc kẹt trên núi tuyết đã lâm vào tình thế tuyệt vọng."},{"type":"compound","zh":"即使身处绝境，她也从来没有放弃希望。","pinyin":"Jíshǐ shēnchǔ juéjìng, tā yě cónglái méiyǒu fàngqì xīwàng.","vi":"Dù lâm vào bước đường cùng, cô ấy cũng chưa bao giờ từ bỏ hy vọng."}],"related":[{"hanzi":"困境","pinyin":"kùnjìng","vi":"nghịch cảnh"},{"hanzi":"绝路","pinyin":"juélù","vi":"đường cùng"},{"hanzi":"绝处逢生","pinyin":"juéchùféngshēng","vi":"tìm thấy lối thoát"}],"traditional":"絕境"},{"id":"绝妙","hanzi":"绝妙","pinyin":"juémiào","meaning_vi":"tuyệt diệu","explanation":"绝 (tuyệt đối/đoạn tuyệt) + 妙 (tuyệt diệu/khéo léo).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"这是个绝妙的主意。","pinyin":"Zhè shì gè juémiào de zhǔyi.","vi":"Đây là một ý tưởng tuyệt diệu."},{"type":"simple","zh":"他在最后一秒投出了一个绝妙的三分球。","pinyin":"Tā zài zuìhòu yì miǎo tóu chūle yí gè juémiào de sānfēnqiú.","vi":"Anh ấy đã ném một quả ba điểm tuyệt diệu ở giây cuối cùng."},{"type":"compound","zh":"这首诗不但用词绝妙，而且意境深远。","pinyin":"Zhè shǒu shī búdàn yòngcí juémiào, érqiě yìjìng shēnyuǎn.","vi":"Bài thơ này không chỉ dùng từ tuyệt diệu mà ý cảnh còn sâu xa."}],"related":[{"hanzi":"巧妙","pinyin":"qiǎomiào","vi":"khéo léo"},{"hanzi":"奇妙","pinyin":"qímiào","vi":"kỳ diệu"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"đặc sắc"}],"traditional":"絕妙"},{"id":"诀窍","hanzi":"诀窍","pinyin":"juéqiào","meaning_vi":"bí quyết, mẹo hay","explanation":"诀 (bí quyết/lời từ biệt) + 窍 (mấu chốt/bí quyết).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🔑","examples":[{"type":"basic","zh":"学外语有诀窍吗？","pinyin":"Xué wàiyǔ yǒu juéqiào ma?","vi":"Học ngoại ngữ có bí quyết gì không?"},{"type":"simple","zh":"老师傅告诉我炒青菜不变黄的诀窍。","pinyin":"Lǎo shīfu gàosu wǒ chǎo qīngcài búbiàn huáng de juéqiào.","vi":"Bác đầu bếp lâu năm chỉ cho tôi mẹo xào rau không bị vàng."},{"type":"compound","zh":"一旦掌握了诀窍，背单词就轻松多了。","pinyin":"Yídàn zhǎngwòle juéqiào, bèi dāncí jiù qīngsōng duō le.","vi":"Một khi đã nắm được bí quyết, việc học thuộc từ vựng sẽ nhẹ nhàng hơn nhiều."}],"related":[{"hanzi":"窍门","pinyin":"qiàomén","vi":"mẹo"},{"hanzi":"秘诀","pinyin":"mìjué","vi":"bí quyết"},{"hanzi":"技巧","pinyin":"jìqiǎo","vi":"kỹ xảo"}],"traditional":"訣竅"},{"id":"崛起","hanzi":"崛起","pinyin":"juéqǐ","meaning_vi":"trỗi dậy mạnh mẽ","explanation":"崛 (trỗi dậy mạnh mẽ) + 起 (khởi nguồn/trỗi dậy).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚀","examples":[{"type":"basic","zh":"一座新城正在崛起。","pinyin":"Yí zuò Xīnchéng zhèngzài juéqǐ.","vi":"Một thành phố mới đang trỗi dậy."},{"type":"simple","zh":"近年来一批国产手机品牌在海外市场迅速崛起。","pinyin":"Jìnniánlái yìpī guóchǎn shǒujī pǐnpái zài hǎiwài shìchǎng xùnsù juéqǐ.","vi":"Những năm gần đây, một loạt thương hiệu điện thoại nội địa đã nhanh chóng vươn lên ở thị trường nước ngoài."},{"type":"compound","zh":"这个小国既缺资源又缺人口，却在几十年内崛起了。","pinyin":"Zhè gè xiǎo guó jì quē zīyuán yòu quē rénkǒu, què zài jǐ shí niánnèi juéqǐ le.","vi":"Quốc gia nhỏ này vừa thiếu tài nguyên vừa ít dân, vậy mà đã trỗi dậy chỉ trong vài chục năm."}],"related":[{"hanzi":"兴起","pinyin":"xīngqǐ","vi":"nổi lên"},{"hanzi":"复兴","pinyin":"fùxīng","vi":"phục hưng"},{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"}]},{"id":"决胜","hanzi":"决胜","pinyin":"juéshèng","meaning_vi":"quyết định thắng bại","explanation":"决 (quyết định/phán quyết) + 胜 (thắng lợi/vượt trội).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"今晚是决胜之战。","pinyin":"Jīnwǎn shì juéshèng zhī zhàn.","vi":"Tối nay là trận chiến quyết định thắng bại."},{"type":"simple","zh":"双方在第五局进入了决胜阶段。","pinyin":"Shuāngfāng zài dìwǔ jú jìnrùle juéshèng jiēduàn.","vi":"Hai bên bước vào giai đoạn quyết định thắng bại ở ván thứ năm."},{"type":"compound","zh":"只要在决胜局保持冷静，我们就有机会夺冠。","pinyin":"Zhǐyào zài juéshèng jú bǎochí lěngjìng, wǒmen jiù yǒujī huì duóguàn.","vi":"Chỉ cần giữ bình tĩnh ở ván quyết định, chúng ta sẽ có cơ hội giành chức vô địch."}],"related":[{"hanzi":"决赛","pinyin":"juésài","vi":"trận chung kết"},{"hanzi":"胜负","pinyin":"shèngfù","vi":"thắng thua"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"}],"traditional":"決勝"},{"id":"纪录片","hanzi":"纪录片","pinyin":"jìlùpiàn","meaning_vi":"phim tài liệu","explanation":"纪 (kỷ luật/kỷ niệm) + 录 (ghi chép/tuyển dụng) + 片 (miếng).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"我在看纪录片。","pinyin":"Wǒ zài kàn jìlùpiàn.","vi":"Tôi đang xem phim tài liệu."},{"type":"simple","zh":"这部关于大熊猫的纪录片拍了整整三年。","pinyin":"Zhè bù guānyú dàxióngmāo de jìlùpiàn pāile zhěngzhěng sān nián.","vi":"Bộ phim tài liệu về gấu trúc này được quay suốt ba năm trời."},{"type":"compound","zh":"虽然这部纪录片没有明星，但是票房出奇地好。","pinyin":"Suīrán zhè bù jìlùpiàn méiyǒu míngxīng, dànshì piàofáng chūqí de hǎo.","vi":"Tuy bộ phim tài liệu này không có ngôi sao nào, nhưng doanh thu phòng vé lại tốt bất ngờ."}],"related":[{"hanzi":"电影","pinyin":"diànyǐng","vi":"phim"},{"hanzi":"纪实","pinyin":"jìshí","vi":"ghi chép thực tế"},{"hanzi":"电视剧","pinyin":"diànshìjù","vi":"phim truyền hình"}],"traditional":"紀錄片"},{"id":"纪实","hanzi":"纪实","pinyin":"jìshí","meaning_vi":"ghi chép người thật việc thật (phóng sự/phim tài liệu)","explanation":"纪 (kỷ luật/kỷ niệm) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🎥","examples":[{"type":"basic","zh":"这是一部纪实作品。","pinyin":"Zhè shì yí bù jìshí zuòpǐn.","vi":"Đây là một tác phẩm ghi chép người thật việc thật."},{"type":"simple","zh":"他写的纪实文学记录了矿工的真实生活。","pinyin":"Tā xiě de jìshí wénxué jìlùle kuànggōng de zhēnshí shēnghuó.","vi":"Văn học phóng sự anh ấy viết đã ghi lại cuộc sống thật của thợ mỏ."},{"type":"compound","zh":"因为这本书是纪实的，所以每个细节都经过了核对。","pinyin":"Yīnwèi zhè běn shū shì jìshí de, suǒyǐ měi gè xìjié dōu jīngguòle héduì.","vi":"Vì cuốn sách này là ghi chép người thật việc thật, nên mọi chi tiết đều đã được kiểm chứng."}],"related":[{"hanzi":"纪录片","pinyin":"jìlùpiàn","vi":"phim tài liệu"},{"hanzi":"报道","pinyin":"bàodào","vi":"đưa tin"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"}],"traditional":"紀實"},{"id":"技师","hanzi":"技师","pinyin":"jìshī","meaning_vi":"kỹ thuật viên bậc cao","explanation":"技 (kỹ thuật) + 师 (thầy giáo/sư phụ).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","cong-viec"],"image":"🔧","examples":[{"type":"basic","zh":"他是高级技师。","pinyin":"Tā shì gāojí jìshī.","vi":"Anh ấy là kỹ thuật viên bậc cao."},{"type":"simple","zh":"修理厂请来一位技师检查发动机。","pinyin":"Xiūlǐchǎng qǐng lái yí wèi jìshī jiǎnchá fādòngjī.","vi":"Xưởng sửa chữa mời một kỹ thuật viên đến kiểm tra động cơ."},{"type":"compound","zh":"他不但考取了技师证，而且带出了十几个徒弟。","pinyin":"Tā búdàn kǎoqǔle jìshī zhèng, érqiě dài chūle shíjǐ gè túdì.","vi":"Anh ấy không chỉ thi đỗ chứng chỉ kỹ thuật viên mà còn đào tạo được hơn chục học trò."}],"related":[{"hanzi":"技工","pinyin":"jìgōng","vi":"thợ kỹ thuật"},{"hanzi":"工程师","pinyin":"gōngchéngshī","vi":"kỹ sư"},{"hanzi":"技术员","pinyin":"jìshùyuán","vi":"kỹ thuật viên"}],"traditional":"技師"},{"id":"技校","hanzi":"技校","pinyin":"jìxiào","meaning_vi":"trường dạy nghề","explanation":"技 (kỹ thuật) + 校 (校).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","dia-diem"],"image":"🏫","examples":[{"type":"basic","zh":"他在技校学电焊。","pinyin":"Tā zài jìxiào xué diànhàn.","vi":"Anh ấy học hàn điện ở trường nghề."},{"type":"simple","zh":"表哥初中毕业后去了一所技校学汽修。","pinyin":"Biǎogē chūzhōng bìyè hòu qùle yì suǒ jìxiào xué qìxiū.","vi":"Anh họ tôi tốt nghiệp cấp hai xong thì vào một trường nghề học sửa ô tô."},{"type":"compound","zh":"虽然他只读过技校，但是现在已经是车间主任了。","pinyin":"Suīrán tā zhǐdúguò jìxiào, dànshì xiànzài yǐjīng shì chējiān zhǔrèn le.","vi":"Tuy chỉ học trường nghề, nhưng giờ anh ấy đã là quản đốc phân xưởng."}],"related":[{"hanzi":"职业学校","pinyin":"zhíyèxuéxiào","vi":"trường nghề"},{"hanzi":"职业教育","pinyin":"zhíyèjiàoyù","vi":"giáo dục nghề nghiệp"},{"hanzi":"技师","pinyin":"jìshī","vi":"kỹ thuật viên bậc cao"}]},{"id":"寄语","hanzi":"寄语","pinyin":"jìyǔ","meaning_vi":"lời nhắn gửi, lời chúc","explanation":"寄 (gửi (thư/bưu phẩm)) + 语 (ngôn ngữ/lời nói).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"💌","examples":[{"type":"basic","zh":"校长给毕业生寄语。","pinyin":"Xiàozhǎng gěi bìyèshēng jìyǔ.","vi":"Hiệu trưởng gửi lời nhắn nhủ tới các học sinh tốt nghiệp."},{"type":"simple","zh":"毕业纪念册的扉页上印着班主任的寄语。","pinyin":"Bìyè jìniàncè de fēiyè shang yìnzhe bānzhǔrèn de jìyǔ.","vi":"Trang đầu cuốn kỷ yếu tốt nghiệp in lời nhắn gửi của cô chủ nhiệm."},{"type":"compound","zh":"每当我想放弃时，就会想起老师的新年寄语。","pinyin":"Měidāng wǒ xiǎng fàngqì shí, jiù huì xiǎngqǐ lǎoshī de xīnnián jìyǔ.","vi":"Mỗi khi muốn bỏ cuộc, tôi lại nhớ đến lời chúc năm mới của thầy."}],"related":[{"hanzi":"祝福","pinyin":"zhùfú","vi":"lời chúc phúc"},{"hanzi":"赠言","pinyin":"zèngyán","vi":"lời tặng"},{"hanzi":"希望","pinyin":"xīwàng","vi":"hy vọng"}],"traditional":"寄語"},{"id":"进程","hanzi":"进程","pinyin":"jìnchéng","meaning_vi":"tiến trình","explanation":"进 (tiến – tiến lên) + 程 (trình – chặng đường) → tiến trình, quá trình phát triển của sự việc. VD: 历史进程, 加快进程.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📈","examples":[{"type":"basic","zh":"谈判进程很顺利。","pinyin":"Tánpàn jìnchéng hěn shùnlì.","vi":"Tiến trình đàm phán rất suôn sẻ."},{"type":"simple","zh":"高铁的开通加快了这座小城的城市化进程。","pinyin":"Gāotiě de kāitōng jiākuàile zhè zuò xiǎochéng de chéngshìhuà jìnchéng.","vi":"Việc khai trương đường sắt cao tốc đã đẩy nhanh tiến trình đô thị hóa của thành phố nhỏ này."},{"type":"compound","zh":"如果资金不能及时到位，工程进程就会被拖慢。","pinyin":"Rúguǒ zījīn bù néng jíshí dàowèi, gōngchéng jìnchéng jiù huì bèi tuōmàn.","vi":"Nếu vốn không về kịp thời, tiến độ công trình sẽ bị chậm lại."}],"related":[{"hanzi":"过程","pinyin":"guòchéng","vi":"quá trình"},{"hanzi":"进展","pinyin":"jìnzhǎn","vi":"tiến triển"},{"hanzi":"历程","pinyin":"lìchéng","vi":"chặng đường"}],"traditional":"進程"},{"id":"进出口贸易","hanzi":"进出口贸易","pinyin":"jìnchūkǒu màoyì","meaning_vi":"thương mại xuất nhập khẩu","explanation":"进出口 (tiến xuất khẩu – nhập và xuất khẩu) + 贸易 (mậu dịch – thương mại) → thương mại xuất nhập khẩu, mua bán hàng hóa với nước ngoài.","hsk_level":"7-9","tags":["danh-tu","cong-viec","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"他从事进出口贸易。","pinyin":"Tā cóngshì jìnchūkǒumàoyì.","vi":"Anh ấy làm nghề thương mại xuất nhập khẩu."},{"type":"simple","zh":"这座港口城市的经济主要依靠进出口贸易。","pinyin":"Zhè zuò gǎngkǒu chéngshì de jīngjì zhǔyào yīkào jìnchūkǒumàoyì.","vi":"Kinh tế của thành phố cảng này chủ yếu dựa vào thương mại xuất nhập khẩu."},{"type":"compound","zh":"一旦汇率大幅波动，进出口贸易就会受到冲击。","pinyin":"Yídàn huìlǜ dàfú bōdòng, jìnchūkǒumàoyì jiù huì shòudào chōngjī.","vi":"Một khi tỷ giá biến động mạnh, thương mại xuất nhập khẩu sẽ bị ảnh hưởng."}],"related":[{"hanzi":"进口","pinyin":"jìnkǒu","vi":"nhập khẩu"},{"hanzi":"出口","pinyin":"chūkǒu","vi":"xuất khẩu"},{"hanzi":"外贸","pinyin":"wàimào","vi":"ngoại thương"}],"traditional":"進出口貿易"},{"id":"近郊","hanzi":"近郊","pinyin":"jìnjiāo","meaning_vi":"vùng ngoại ô gần thành phố","explanation":"近 (gần) + 郊 (ngoại ô).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🏡","examples":[{"type":"basic","zh":"他家住在近郊。","pinyin":"Tā jiā zhùzài jìnjiāo.","vi":"Nhà anh ấy ở vùng ven thành phố."},{"type":"simple","zh":"周末很多市民开车去近郊的果园摘草莓。","pinyin":"Zhōumò hěn duō shìmín kāichē qù jìnjiāo de guǒyuán zhāi cǎoméi.","vi":"Cuối tuần nhiều người dân lái xe ra vườn cây ở ngoại ô gần thành phố hái dâu."},{"type":"compound","zh":"近郊的房价虽然便宜，但是上班路上要花很长时间。","pinyin":"Jìnjiāo de fángjià suīrán piányi, dànshì shàngbān lùshang yào huā hěn cháng shíjiān.","vi":"Giá nhà ở vùng ven tuy rẻ, nhưng đường đi làm mất rất nhiều thời gian."}],"related":[{"hanzi":"郊区","pinyin":"jiāoqū","vi":"ngoại ô"},{"hanzi":"远郊","pinyin":"yuǎnjiāo","vi":"ngoại ô xa"},{"hanzi":"市区","pinyin":"shìqū","vi":"nội thành"}]},{"id":"近视","hanzi":"近视","pinyin":"jìnshì","meaning_vi":"cận thị","explanation":"近 (gần) + 视 (tầm nhìn/coi trọng).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"👓","examples":[{"type":"basic","zh":"我有点近视。","pinyin":"Wǒ yǒudiǎn jìnshì.","vi":"Tôi hơi bị cận thị."},{"type":"simple","zh":"长时间看手机让不少小学生近视了。","pinyin":"Cháng shíjiān kàn shǒujī ràng bùshǎo xiǎoxuéshēng jìnshì le.","vi":"Xem điện thoại lâu khiến không ít học sinh tiểu học bị cận thị."},{"type":"compound","zh":"因为他高度近视，所以不能报考飞行员。","pinyin":"Yīnwèi tā gāodù jìnshì, suǒyǐ bù néng bàokǎo fēixíngyuán.","vi":"Vì bị cận thị nặng nên anh ấy không thể đăng ký thi làm phi công."}],"related":[{"hanzi":"近视眼","pinyin":"jìnshìyǎn","vi":"mắt cận thị"},{"hanzi":"远视","pinyin":"yuǎnshì","vi":"viễn thị"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"kính mắt"}],"traditional":"近視"},{"id":"近视眼","hanzi":"近视眼","pinyin":"jìnshìyǎn","meaning_vi":"cận thị","explanation":"近 (gần) + 视 (tầm nhìn/coi trọng) + 眼 (ánh mắt/tầm nhìn).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","co-the"],"image":"👓","examples":[{"type":"basic","zh":"他是个近视眼。","pinyin":"Tā shì gè jìnshìyǎn.","vi":"Anh ấy là người bị cận thị."},{"type":"simple","zh":"这位近视眼患者终于做了激光矫正手术。","pinyin":"Zhè wèi jìnshìyǎn huànzhě zhōngyú zuòle jīguāng jiǎozhèng shǒushù.","vi":"Bệnh nhân cận thị này cuối cùng đã làm phẫu thuật chỉnh mắt bằng laser."},{"type":"compound","zh":"如果不注意用眼卫生，孩子就容易变成近视眼。","pinyin":"Rúguǒ bú zhùyì yòng yǎn wèishēng, háizi jiù róngyì biànchéng jìnshìyǎn.","vi":"Nếu không chú ý giữ gìn mắt đúng cách, trẻ em rất dễ bị cận thị."}],"related":[{"hanzi":"近视","pinyin":"jìnshì","vi":"cận thị"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"kính mắt"},{"hanzi":"视力","pinyin":"shìlì","vi":"thị lực"}],"traditional":"近視眼"},{"id":"进修","hanzi":"进修","pinyin":"jìnxiū","meaning_vi":"học nâng cao, tu nghiệp","explanation":"进 (vào) + 修 (tu dưỡng/sửa chữa).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"她去北京进修了。","pinyin":"Tā qù Běijīng jìnxiū le.","vi":"Cô ấy đã đi Bắc Kinh tu nghiệp."},{"type":"simple","zh":"医院派他到上海的一家大医院进修半年。","pinyin":"Yīyuàn pài tā dào Shànghǎi de yìjiā dà yīyuàn jìnxiū bàn nián.","vi":"Bệnh viện cử anh ấy đến một bệnh viện lớn ở Thượng Hải tu nghiệp nửa năm."},{"type":"compound","zh":"虽然工作很忙，但是她每个周末都去大学进修英语。","pinyin":"Suīrán gōngzuò hěn máng, dànshì tā měi gè zhōumò dōu qù dàxué jìnxiū Yīngyǔ.","vi":"Tuy công việc rất bận, nhưng cuối tuần nào cô ấy cũng đến trường đại học học nâng cao tiếng Anh."}],"related":[{"hanzi":"深造","pinyin":"shēnzào","vi":"học sâu thêm"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"},{"hanzi":"留学","pinyin":"liúxué","vi":"du học"}],"traditional":"進修"},{"id":"近义词","hanzi":"近义词","pinyin":"jìnyìcí","meaning_vi":"từ cận nghĩa","explanation":"近 (gần) + 义 (chính nghĩa/ý nghĩa) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🔗","examples":[{"type":"basic","zh":"请找出近义词。","pinyin":"Qǐng zhǎochū jìnyìcí.","vi":"Hãy tìm ra các từ cận nghĩa."},{"type":"simple","zh":"老师让我们给每个生词写两个近义词。","pinyin":"Lǎoshī ràng wǒmen gěi měi gè shēngcí xiě liǎng gè jìnyìcí.","vi":"Thầy giáo bảo chúng tôi viết hai từ cận nghĩa cho mỗi từ mới."},{"type":"compound","zh":"虽然这两个词是近义词，但是用法并不完全一样。","pinyin":"Suīrán zhè liǎng gè cí shì jìnyìcí, dànshì yòngfǎ bìngbù wánquán yíyàng.","vi":"Tuy hai từ này là từ cận nghĩa, nhưng cách dùng không hoàn toàn giống nhau."}],"related":[{"hanzi":"反义词","pinyin":"fǎnyìcí","vi":"từ trái nghĩa"},{"hanzi":"同义词","pinyin":"tóngyìcí","vi":"từ đồng nghĩa"},{"hanzi":"词语","pinyin":"cíyǔ","vi":"từ ngữ"}],"traditional":"近義詞"},{"id":"净化","hanzi":"净化","pinyin":"jìnghuà","meaning_vi":"thanh lọc, làm sạch (không khí/tâm hồn)","explanation":"净 (sạch sẽ/ròng) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"💧","examples":[{"type":"basic","zh":"绿植能净化空气。","pinyin":"Lǜzhí néng jìnghuà kōngqì.","vi":"Cây xanh có thể làm sạch không khí."},{"type":"simple","zh":"这片湿地每天能净化数万吨生活污水。","pinyin":"Zhè piàn shīdì měitiān néng jìnghuà shùwàn dūn shēnghuó wūshuǐ.","vi":"Vùng đất ngập nước này mỗi ngày có thể lọc sạch hàng vạn tấn nước thải sinh hoạt."},{"type":"compound","zh":"读一首好诗，既能放松心情，又能净化心灵。","pinyin":"Dú yì shǒu hǎo shī, jì néng fàngsōng xīnqíng, yòu néng jìnghuà xīnlíng.","vi":"Đọc một bài thơ hay vừa giúp thư giãn, vừa có thể thanh lọc tâm hồn."}],"related":[{"hanzi":"污染","pinyin":"wūrǎn","vi":"ô nhiễm"},{"hanzi":"清洁","pinyin":"qīngjié","vi":"sạch sẽ"},{"hanzi":"净化器","pinyin":"jìnghuàqì","vi":"máy lọc"}],"traditional":"淨化"},{"id":"净化器","hanzi":"净化器","pinyin":"jìnghuàqì","meaning_vi":"máy lọc (không khí/nước)","explanation":"净 (sạch sẽ/ròng) + 化 (化) + 器 (thiết bị/cơ quan).","hsk_level":"7-9","tags":["danh-tu","do-vat","cong-nghe"],"image":"💨","examples":[{"type":"basic","zh":"我买了个净化器。","pinyin":"Wǒ mǎile gè jìnghuàqì.","vi":"Tôi đã mua một chiếc máy lọc."},{"type":"simple","zh":"雾霾天里，卧室的空气净化器一直开着。","pinyin":"Wùmái tiān lǐ, wòshì de kōngqì jìnghuàqì yìzhí kāi zhe.","vi":"Những ngày khói mù, máy lọc không khí trong phòng ngủ luôn bật."},{"type":"compound","zh":"只要定期更换滤芯，净化器就能保持好的效果。","pinyin":"Zhǐyào dìngqī gēng huàn lǜxīn, jìnghuàqì jiù néng bǎochí hǎo de xiàoguǒ.","vi":"Chỉ cần thay lõi lọc định kỳ, máy lọc sẽ giữ được hiệu quả tốt."}],"related":[{"hanzi":"空气净化器","pinyin":"kōngqì jìnghuàqì","vi":"máy lọc không khí"},{"hanzi":"净水器","pinyin":"jìngshuǐqì","vi":"máy lọc nước"},{"hanzi":"过滤","pinyin":"guòlǜ","vi":"lọc"}],"traditional":"淨化器"},{"id":"净利润","hanzi":"净利润","pinyin":"jìnglìrùn","meaning_vi":"lợi nhuận ròng","explanation":"净 (sạch/ròng) + 利润 (lợi nhuận).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"💵","examples":[{"type":"basic","zh":"今年净利润翻倍了。","pinyin":"Jīnnián jìnglìrùn fānbèi le.","vi":"Năm nay lợi nhuận ròng đã tăng gấp đôi."},{"type":"simple","zh":"这家公司第三季度的净利润达到了两亿元。","pinyin":"Zhè jiā gōngsī dì sān jìdù de jìnglìrùn dádàole liǎng yì yuán.","vi":"Lợi nhuận ròng quý ba của công ty này đạt hai trăm triệu tệ."},{"type":"compound","zh":"虽然营业额增长了，但是净利润反而下降了。","pinyin":"Suīrán yíngyè'é zēngzhǎng le, dànshì jìnglìrùn fǎn'ér xiàjiàng le.","vi":"Tuy doanh thu tăng, nhưng lợi nhuận ròng lại giảm."}],"related":[{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"毛利","pinyin":"máolì","vi":"lợi nhuận gộp"},{"hanzi":"营业额","pinyin":"yíngyè'é","vi":"doanh thu"}],"traditional":"淨利潤"},{"id":"静谧","hanzi":"静谧","pinyin":"jìngmì","meaning_vi":"tĩnh mịch yên bình","explanation":"静 (静) + 谧 (yên tĩnh/tĩnh mịch).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌙","examples":[{"type":"basic","zh":"夜晚的湖边很静谧。","pinyin":"Yèwǎn de húbiān hěn jìngmì.","vi":"Bờ hồ về đêm thật tĩnh mịch."},{"type":"simple","zh":"山谷里的小村庄在月光下显得格外静谧。","pinyin":"Shāngǔ lǐ de xiǎo cūnzhuāng zài yuèguāng xià xiǎnde géwài jìngmì.","vi":"Ngôi làng nhỏ trong thung lũng dưới ánh trăng trông đặc biệt yên bình."},{"type":"compound","zh":"一走进静谧的竹林，城市的喧嚣就全被抛在了身后。","pinyin":"Yì zǒujìn jìngmì de zhúlín, chéngshì de xuānxiāo jiù quán bèi pāo zài le shēnhòu.","vi":"Vừa bước vào rừng trúc tĩnh mịch, mọi ồn ào của thành phố liền bị bỏ lại phía sau."}],"related":[{"hanzi":"宁静","pinyin":"níngjìng","vi":"yên tĩnh"},{"hanzi":"幽静","pinyin":"yōujìng","vi":"u tĩnh"},{"hanzi":"喧嚣","pinyin":"xuānxiāo","vi":"ồn ào"}],"traditional":"靜謐"},{"id":"竞拍","hanzi":"竞拍","pinyin":"jìngpāi","meaning_vi":"đấu giá","explanation":"竞 (cạnh tranh/thi đua) + 拍 (vỗ).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🔨","examples":[{"type":"basic","zh":"他参加了竞拍。","pinyin":"Tā cānjiāle jìngpāi.","vi":"Anh ấy đã tham gia đấu giá."},{"type":"simple","zh":"一位收藏家以五百万元竞拍到了这幅古画。","pinyin":"Yí wèi shōucángjiā yǐ wǔ bǎiwàn yuán jìngpāi dàole zhè fú gǔ huà.","vi":"Một nhà sưu tầm đã đấu giá được bức tranh cổ này với giá năm triệu tệ."},{"type":"compound","zh":"如果出价的人太多，竞拍价格就会一路上涨。","pinyin":"Rúguǒ chūjià de rén tài duō, jìngpāi jiàgé jiù huì yílù shàngzhǎng.","vi":"Nếu có quá nhiều người trả giá, giá đấu sẽ liên tục tăng lên."}],"related":[{"hanzi":"拍卖","pinyin":"pāimài","vi":"bán đấu giá"},{"hanzi":"竞标","pinyin":"jìngbiāo","vi":"đấu thầu"},{"hanzi":"出价","pinyin":"chūjià","vi":"ra giá"}],"traditional":"競拍"},{"id":"净土","hanzi":"净土","pinyin":"Jìngtǔ","meaning_vi":"mảnh đất thanh tịnh trong lành","explanation":"净 (sạch sẽ/ròng) + 土 (đất đai/bản địa).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","van-hoa"],"image":"🌿","examples":[{"type":"basic","zh":"这里是一片净土。","pinyin":"Zhèlǐ shì yípiàn Jìngtǔ.","vi":"Nơi đây là một mảnh đất thanh tịnh."},{"type":"simple","zh":"这座远离工厂的小岛是候鸟最后的净土。","pinyin":"Zhè zuò yuǎnlí gōngchǎng de xiǎodǎo shì hòuniǎo zuìhòu de Jìngtǔ.","vi":"Hòn đảo nhỏ cách xa nhà máy này là mảnh đất trong lành cuối cùng của chim di cư."},{"type":"compound","zh":"即使城市再喧闹，书房也是我心中的一片净土。","pinyin":"Jíshǐ chéngshì zài xuānnào, shūfáng yě shì wǒ xīnzhōng de yípiàn Jìngtǔ.","vi":"Dù thành phố có ồn ào đến đâu, phòng đọc sách vẫn là chốn thanh tịnh trong lòng tôi."}],"related":[{"hanzi":"乐土","pinyin":"lètǔ","vi":"miền đất hạnh phúc"},{"hanzi":"世外桃源","pinyin":"shìwàitáoyuán","vi":"chốn đào nguyên"},{"hanzi":"纯净","pinyin":"chúnjìng","vi":"thuần khiết"}],"traditional":"淨土"},{"id":"敬业","hanzi":"敬业","pinyin":"jìngyè","meaning_vi":"yêu nghề tận tụy","explanation":"敬 (tôn kính) + 业 (sự nghiệp/ngành nghề).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"她非常敬业。","pinyin":"Tā fēicháng jìngyè.","vi":"Cô ấy rất tận tụy với nghề."},{"type":"simple","zh":"这位敬业的快递员冒着大雨把包裹送到了家门口。","pinyin":"Zhè wèi jìngyè de kuàidìyuán màozhe dàyǔ bǎ bāoguǒ sòng dàole jiā ménkǒu.","vi":"Anh shipper tận tụy này đội mưa lớn giao gói hàng đến tận cửa nhà."},{"type":"compound","zh":"他不但敬业，而且对同事特别热心。","pinyin":"Tā búdàn jìngyè, érqiě duì tóngshì tèbié rèxīn.","vi":"Anh ấy không chỉ tận tụy với công việc mà còn rất nhiệt tình với đồng nghiệp."}],"related":[{"hanzi":"爱岗敬业","pinyin":"àigǎngjìngyè","vi":"yêu nghề tận tụy"},{"hanzi":"尽职","pinyin":"jìnzhí","vi":"tận chức"},{"hanzi":"敬业精神","pinyin":"jìngyèjīngshén","vi":"tinh thần tận tụy"}],"traditional":"敬業"},{"id":"敬意","hanzi":"敬意","pinyin":"jìngyì","meaning_vi":"lòng kính trọng","explanation":"敬 (tôn kính) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"向老兵致以敬意。","pinyin":"Xiàng lǎobīng zhìyǐ jìngyì.","vi":"Xin gửi lòng kính trọng tới các cựu chiến binh."},{"type":"simple","zh":"全场观众起立鼓掌向老艺术家表达敬意。","pinyin":"Quánchǎng guānzhòng qǐlì gǔzhǎng xiàng lǎo yìshùjiā biǎodá jìngyì.","vi":"Toàn bộ khán giả đứng dậy vỗ tay bày tỏ lòng kính trọng với người nghệ sĩ lão thành."},{"type":"compound","zh":"虽然我们素不相识，但是我对他的勇气充满敬意。","pinyin":"Suīrán wǒmen sùbùxiāngshí, dànshì wǒ duì tā de yǒngqì chōngmǎn jìngyì.","vi":"Tuy chúng tôi chưa từng quen biết, nhưng tôi vô cùng kính phục lòng dũng cảm của anh ấy."}],"related":[{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"致敬","pinyin":"zhìjìng","vi":"bày tỏ lòng kính trọng"},{"hanzi":"敬佩","pinyin":"jìngpèi","vi":"khâm phục"}]},{"id":"境遇","hanzi":"境遇","pinyin":"jìngyù","meaning_vi":"cảnh ngộ, hoàn cảnh sống","explanation":"境 (cảnh giới/hoàn cảnh) + 遇 (遇).","hsk_level":"7-9","tags":["danh-tu"],"image":"🧭","examples":[{"type":"basic","zh":"他的境遇很糟糕。","pinyin":"Tā de jìngyù hěn zāogāo.","vi":"Cảnh ngộ của anh ấy rất tồi tệ."},{"type":"simple","zh":"小说描写了一个农村女孩在大城市里的境遇。","pinyin":"Xiǎoshuō miáoxiěle yí gè nóngcūn nǚhái zài Dàchéng shìlǐ de jìngyù.","vi":"Cuốn tiểu thuyết miêu tả cảnh ngộ của một cô gái nông thôn ở thành phố lớn."},{"type":"compound","zh":"虽然境遇坎坷，但是他始终保持着乐观。","pinyin":"Suīrán jìngyù kǎnkě, dànshì tā shǐzhōng bǎochízhe lèguān.","vi":"Tuy cảnh ngộ lận đận, nhưng anh ấy luôn giữ được sự lạc quan."}],"related":[{"hanzi":"处境","pinyin":"chǔjìng","vi":"hoàn cảnh"},{"hanzi":"遭遇","pinyin":"zāoyù","vi":"gặp phải"},{"hanzi":"境况","pinyin":"jìngkuàng","vi":"tình cảnh"}]},{"id":"集大成","hanzi":"集大成","pinyin":"jídàchéng","meaning_vi":"tổng hợp tinh hoa đạt đỉnh cao","explanation":"集 (tập hợp) + 大 (to) + 成 (成).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"👑","examples":[{"type":"basic","zh":"他是集大成者。","pinyin":"Tā shì jídàchéng zhě.","vi":"Ông ấy là người tổng hợp tinh hoa đạt đến đỉnh cao."},{"type":"simple","zh":"这部医书是古代中医药学的集大成之作。","pinyin":"Zhè bù yīshū shì gǔdài zhōngyī yàoxué de jídàchéng zhī zuò.","vi":"Bộ sách y này là tác phẩm tập đại thành của y dược học cổ truyền Trung Hoa."},{"type":"compound","zh":"因为他吸收了各派的长处，所以成为武术的集大成者。","pinyin":"Yīnwèi tā xīshōule gè pài de chángchù, suǒyǐ chéngwéi wǔshù de jídàchéng zhě.","vi":"Vì tiếp thu ưu điểm của các môn phái, ông đã trở thành người tập đại thành của võ thuật."}],"related":[{"hanzi":"集大成者","pinyin":"jídàchéngzhě","vi":"người tổng hợp tinh hoa"},{"hanzi":"汇集","pinyin":"huìjí","vi":"tập hợp"},{"hanzi":"精华","pinyin":"jīnghuá","vi":"tinh hoa"}]},{"id":"及物动词","hanzi":"及物动词","pinyin":"jíwùdòngcí","meaning_vi":"ngoại động từ (ngữ pháp)","explanation":"及 (kịp thời/đạt tới) + 物 (vật chất/sự vật) + 动 (动) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"吃是及物动词。","pinyin":"Chī shì jíwùdòngcí.","vi":"\"Ăn\" là ngoại động từ."},{"type":"simple","zh":"及物动词后面通常可以直接带宾语。","pinyin":"Jíwùdòngcí hòumiàn tōngcháng kěyǐ zhíjiē dài bīnyǔ.","vi":"Sau ngoại động từ thường có thể trực tiếp mang tân ngữ."},{"type":"compound","zh":"如果你分不清及物动词，就很容易写出病句。","pinyin":"Rúguǒ nǐ fēn bùqīng jíwùdòngcí, jiù hěn róngyì xiě chū bìngjù.","vi":"Nếu bạn không phân biệt được ngoại động từ thì rất dễ viết ra câu sai."}],"related":[{"hanzi":"不及物动词","pinyin":"bù jíwùdòngcí","vi":"nội động từ"},{"hanzi":"动词","pinyin":"dòngcí","vi":"động từ"},{"hanzi":"宾语","pinyin":"bīnyǔ","vi":"tân ngữ"}],"traditional":"及物動詞"},{"id":"集装箱","hanzi":"集装箱","pinyin":"jízhuāngxiāng","meaning_vi":"thùng công-ten-nơ (container)","explanation":"集 (tập hợp) + 装 (trang bị/ngụy trang) + 箱 (箱).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"🚢","examples":[{"type":"basic","zh":"码头堆满了集装箱。","pinyin":"Mǎtóu duīmǎnle jízhuāngxiāng.","vi":"Bến cảng chất đầy công-ten-nơ."},{"type":"simple","zh":"一艘巨轮正把上千个集装箱运往欧洲。","pinyin":"Yì sōu jùlún zhèng bǎ shàng qiān gè jízhuāngxiāng yùn wǎng Ōuzhōu.","vi":"Một con tàu khổng lồ đang chở hàng nghìn công-ten-nơ sang châu Âu."},{"type":"compound","zh":"因为港口拥堵，所以运一个集装箱的费用翻了三倍。","pinyin":"Yīnwèi gǎngkǒu yōngdǔ, suǒyǐ yùn yí gè jízhuāngxiāng de fèiyòng fānle sānbèi.","vi":"Vì cảng bị ùn tắc, nên chi phí vận chuyển một công-ten-nơ đã tăng gấp ba."}],"related":[{"hanzi":"货柜","pinyin":"huòguì","vi":"công-ten-nơ"},{"hanzi":"码头","pinyin":"mǎtóu","vi":"bến cảng"},{"hanzi":"货运","pinyin":"huòyùn","vi":"vận tải hàng hóa"}],"traditional":"集裝箱"},{"id":"急转直下","hanzi":"急转直下","pinyin":"jízhuǎn-zhíxià","meaning_vi":"chuyển biến xấu đột ngột","explanation":"急 (cấp bách/vội) + 转 (rẽ) + 直 (trực tiếp/thẳng thắn) + 下 (dưới).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"📉","examples":[{"type":"basic","zh":"局势急转直下。","pinyin":"Júshì jízhuǎnzhíxià.","vi":"Tình hình chuyển biến xấu đột ngột."},{"type":"simple","zh":"他的病情在入院第三天急转直下。","pinyin":"Tā de bìngqíng zài rùyuàn dì sān tiān jízhuǎnzhíxià.","vi":"Bệnh tình của ông ấy đột ngột trở nặng vào ngày thứ ba nhập viện."},{"type":"compound","zh":"主力球员一受伤，比赛形势就急转直下。","pinyin":"Zhǔlì qiúyuán yí shòushāng, bǐsài xíngshì jiù jízhuǎnzhíxià.","vi":"Cầu thủ chủ lực vừa bị thương, cục diện trận đấu liền xấu đi nhanh chóng."}],"related":[{"hanzi":"急剧","pinyin":"jíjù","vi":"đột ngột"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"一落千丈","pinyin":"yíluòqiānzhàng","vi":"tụt dốc thảm hại"}],"traditional":"急轉直下"},{"id":"巨变","hanzi":"巨变","pinyin":"jùbiàn","meaning_vi":"biến đổi to lớn","explanation":"巨 (to lớn) + 变 (变).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"家乡发生了巨变。","pinyin":"Jiāxiāng fāshēngle jùbiàn.","vi":"Quê hương đã có những đổi thay to lớn."},{"type":"simple","zh":"短短十年间这座渔村经历了翻天覆地的巨变。","pinyin":"Duǎn duǎn shí niánjiān zhè zuò yú cūn jīnglìle fāntiānfùdì de jùbiàn.","vi":"Chỉ trong mười năm ngắn ngủi, làng chài này đã trải qua những biến đổi long trời lở đất."},{"type":"compound","zh":"虽然街道经历了巨变，但是那家面馆还在老地方。","pinyin":"Suīrán jiēdào jīnglìle jùbiàn, dànshì nà jiā miànguǎn hái zài lǎodìfang.","vi":"Tuy khu phố đã thay đổi rất lớn, nhưng quán mì ấy vẫn ở chỗ cũ."}],"related":[{"hanzi":"剧变","pinyin":"jùbiàn","vi":"biến đổi dữ dội"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"翻天覆地","pinyin":"fāntiānfùdì","vi":"thay trời đổi đất"}],"traditional":"巨變"},{"id":"聚会","hanzi":"聚会","pinyin":"jùhuì","meaning_vi":"tụ họp, họp mặt; buổi họp mặt, bữa tiệc","explanation":"聚 (tụ họp/ngưng tụ) + 会 (biết (kỹ năng)).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🥳","examples":[{"type":"basic","zh":"今晚有个聚会。","pinyin":"Jīnwǎn yǒu gè jùhuì.","vi":"Tối nay có một buổi tụ họp."},{"type":"simple","zh":"老同学们约好国庆节在母校门口聚会。","pinyin":"Lǎo tóngxuémen yuē hǎo Guóqìngjié zài mǔxiào ménkǒu jùhuì.","vi":"Các bạn học cũ hẹn nhau tụ họp trước cổng trường cũ vào dịp Quốc khánh."},{"type":"compound","zh":"如果你今晚有空，就来参加我们的生日聚会吧。","pinyin":"Rúguǒ nǐ jīnwǎn yǒukòng, jiù lái cānjiā wǒmen de shēngrì jùhuì ba.","vi":"Nếu tối nay bạn rảnh thì đến dự tiệc sinh nhật của chúng tôi nhé."}],"related":[{"hanzi":"聚餐","pinyin":"jùcān","vi":"liên hoan"},{"hanzi":"派对","pinyin":"pàiduì","vi":"bữa tiệc"},{"hanzi":"同学会","pinyin":"tóngxuéhuì","vi":"họp lớp"}],"traditional":"聚會"},{"id":"聚焦","hanzi":"聚焦","pinyin":"jùjiāo","meaning_vi":"lấy nét, tập trung vào tiêu điểm","explanation":"聚 (tụ họp/ngưng tụ) + 焦 (tiêu điểm/sốt ruột).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🎯","examples":[{"type":"basic","zh":"镜头聚焦在她脸上。","pinyin":"Jìngtóu jùjiāo zài tā liǎn shang.","vi":"Ống kính lấy nét vào khuôn mặt cô ấy."},{"type":"simple","zh":"今年的峰会聚焦人工智能带来的就业问题。","pinyin":"Jīnnián de fēnghuì jùjiāo réngōngzhìnéng dàilái de jiùyè wèntí.","vi":"Hội nghị thượng đỉnh năm nay tập trung vào vấn đề việc làm do trí tuệ nhân tạo gây ra."},{"type":"compound","zh":"只要把精力聚焦在一件事上，效率就会大大提高。","pinyin":"Zhǐyào bǎ jīnglì jùjiāo zài yí jiàn shì shang, xiàolǜ jiù huì dàdà tígāo.","vi":"Chỉ cần dồn sức tập trung vào một việc, hiệu suất sẽ tăng lên rất nhiều."}],"related":[{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"},{"hanzi":"关注","pinyin":"guānzhù","vi":"quan tâm"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"}]},{"id":"剧增","hanzi":"剧增","pinyin":"jùzēng","meaning_vi":"tăng vọt mạnh","explanation":"剧 (kịch/dữ dội) + 增 (tăng thêm).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"游客人数剧增。","pinyin":"Yóukè rénshù jùzēng.","vi":"Số lượng du khách tăng vọt."},{"type":"simple","zh":"寒潮来袭后，医院的感冒病人剧增。","pinyin":"Háncháo láixí hòu, yīyuàn de gǎnmào bìngrén jùzēng.","vi":"Sau khi đợt rét ập đến, số bệnh nhân cảm cúm ở bệnh viện tăng vọt."},{"type":"compound","zh":"一到暑假，景区的客流量就会剧增。","pinyin":"Yí dào shǔjià, jǐngqū de kèliúliàng jiù huì jùzēng.","vi":"Cứ đến kỳ nghỉ hè, lượng khách ở khu du lịch lại tăng vọt."}],"related":[{"hanzi":"激增","pinyin":"jīzēng","vi":"tăng vọt"},{"hanzi":"猛增","pinyin":"měngzēng","vi":"tăng mạnh"},{"hanzi":"锐减","pinyin":"ruìjiǎn","vi":"giảm mạnh"}],"traditional":"劇增"},{"id":"竣工","hanzi":"竣工","pinyin":"jùngōng","meaning_vi":"hoàn thành thi công, khánh thành","explanation":"竣 (hoàn thành (công trình)) + 工 (工).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"大桥已经竣工了。","pinyin":"Dàqiáo yǐjīng jùngōng le.","vi":"Cây cầu lớn đã hoàn thành thi công."},{"type":"simple","zh":"这座新体育馆预计明年五月正式竣工。","pinyin":"Zhè zuò xīn tǐyùguǎn yùjì míngnián Wǔyuè zhèngshì jùngōng.","vi":"Nhà thi đấu mới này dự kiến chính thức hoàn công vào tháng Năm năm sau."},{"type":"compound","zh":"地铁三号线一竣工，我们上班就方便多了。","pinyin":"Dìtiě sān hào xiàn yí jùngōng, wǒmen shàngbān jiù fāngbiàn duō le.","vi":"Tuyến tàu điện ngầm số 3 vừa hoàn thành, chúng tôi đi làm thuận tiện hơn hẳn."}],"related":[{"hanzi":"完工","pinyin":"wángōng","vi":"hoàn công"},{"hanzi":"开工","pinyin":"kāigōng","vi":"khởi công"},{"hanzi":"施工","pinyin":"shīgōng","vi":"thi công"}]},{"id":"局限于","hanzi":"局限于","pinyin":"júxiànyú","meaning_vi":"giới hạn trong phạm vi","explanation":"局 (cục diện/cơ quan) + 限 (hạn chế/giới hạn) + 于 (ở/đối với).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚧","examples":[{"type":"basic","zh":"问题不局限于此。","pinyin":"Wèntí bù júxiànyú cǐ.","vi":"Vấn đề không chỉ giới hạn ở đây."},{"type":"simple","zh":"他的研究兴趣并不局限于古代文学。","pinyin":"Tā de yánjiū xìngqù bìngbù júxiànyú gǔdài wénxué.","vi":"Mối quan tâm nghiên cứu của ông ấy không chỉ giới hạn ở văn học cổ đại."},{"type":"compound","zh":"如果眼光只局限于眼前利益，企业就很难长远发展。","pinyin":"Rúguǒ yǎnguāng zhǐ júxiànyú yǎnqián lìyì, qǐyè jiù hěn nán chángyuǎn fāzhǎn.","vi":"Nếu tầm nhìn chỉ bó hẹp trong lợi ích trước mắt, doanh nghiệp sẽ khó phát triển lâu dài."}],"related":[{"hanzi":"局限","pinyin":"júxiàn","vi":"giới hạn"},{"hanzi":"限于","pinyin":"xiànyú","vi":"hạn chế ở"},{"hanzi":"局限性","pinyin":"júxiànxìng","vi":"tính hạn chế"}],"traditional":"局限於"},{"id":"畸变","hanzi":"畸变","pinyin":"jībiàn","meaning_vi":"biến dạng lệch lạc","explanation":"畸 (cơ/kỳ – lệch lạc, dị dạng) + 变 (biến – thay đổi) → biến dạng, biến đổi lệch lạc khác thường (hình ảnh, tín hiệu, tâm lý). VD: 心理畸变.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"⚠️","examples":[{"type":"basic","zh":"图像发生了畸变。","pinyin":"Túxiàng fāshēngle jībiàn.","vi":"Hình ảnh đã bị biến dạng."},{"type":"simple","zh":"广角镜头拍出的照片边缘容易出现畸变。","pinyin":"Guǎngjiǎo jìngtóu pāichū de zhàopiàn biānyuán róngyì chūxiàn jībiàn.","vi":"Ảnh chụp bằng ống kính góc rộng dễ bị méo ở phần rìa."},{"type":"compound","zh":"一旦细胞基因发生畸变，就可能引发疾病。","pinyin":"Yídàn xìbāo jīyīn fāshēng jībiàn, jiù kěnéng yǐnfā jíbìng.","vi":"Một khi gen tế bào bị biến dị, có thể sẽ gây ra bệnh tật."}],"related":[{"hanzi":"变形","pinyin":"biànxíng","vi":"biến dạng"},{"hanzi":"畸形","pinyin":"jīxíng","vi":"dị dạng"},{"hanzi":"失真","pinyin":"shīzhēn","vi":"méo mó"}],"traditional":"畸變"},{"id":"机场高速","hanzi":"机场高速","pinyin":"jīchǎnggāosù","meaning_vi":"đường cao tốc sân bay","explanation":"机 (cơ hội/máy móc) + 场 (trận) + 高 (cao) + 速 (nhanh chóng/tốc độ).","hsk_level":"7-9","tags":["danh-tu","giao-thong","dia-diem"],"image":"🛣️","examples":[{"type":"basic","zh":"机场高速堵车了。","pinyin":"Jīchǎnggāosù dǔchē le.","vi":"Đường cao tốc sân bay đang bị tắc."},{"type":"simple","zh":"出租车沿着机场高速开了四十分钟才到航站楼。","pinyin":"Chūzūchē yánzhe jīchǎnggāosù kāile sìshí fēnzhōng cái dào hángzhànlóu.","vi":"Taxi chạy dọc đường cao tốc sân bay bốn mươi phút mới tới nhà ga."},{"type":"compound","zh":"如果机场高速不堵，我们半小时就能到。","pinyin":"Rúguǒ jīchǎnggāosù bù dǔ, wǒmen bànxiǎoshí jiù néng dào.","vi":"Nếu đường cao tốc sân bay không tắc, nửa tiếng là chúng ta tới nơi."}],"related":[{"hanzi":"高速公路","pinyin":"gāosùgōnglù","vi":"đường cao tốc"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"sân bay"},{"hanzi":"机场大巴","pinyin":"jīchǎngdàbā","vi":"xe buýt sân bay"}],"traditional":"機場高速"},{"id":"基础设施","hanzi":"基础设施","pinyin":"jīchǔshèshī","meaning_vi":"cơ sở hạ tầng","explanation":"基础 (cơ sở – nền móng) + 设施 (thiết thi – công trình, thiết bị) → cơ sở hạ tầng như đường sá, điện nước, viễn thông. VD: 基础设施建设.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"基础设施很完善。","pinyin":"Jīchǔshèshī hěn wánshàn.","vi":"Cơ sở hạ tầng rất hoàn thiện."},{"type":"simple","zh":"政府投入大量资金改善山区的基础设施。","pinyin":"Zhèngfǔ tóurù dàliàng zījīn gǎishàn shānqū de jīchǔshèshī.","vi":"Chính phủ đầu tư một lượng vốn lớn để cải thiện cơ sở hạ tầng vùng núi."},{"type":"compound","zh":"因为基础设施落后，所以这里很难吸引外资。","pinyin":"Yīnwèi jīchǔshèshī luòhòu, suǒyǐ zhèlǐ hěn nán xīyǐn wàizī.","vi":"Vì cơ sở hạ tầng lạc hậu, nên nơi này rất khó thu hút vốn nước ngoài."}],"related":[{"hanzi":"设施","pinyin":"shèshī","vi":"thiết bị"},{"hanzi":"基建","pinyin":"jījiàn","vi":"xây dựng cơ bản"},{"hanzi":"公共设施","pinyin":"gōnggòngshèshī","vi":"công trình công cộng"}],"traditional":"基礎設施"},{"id":"机舱","hanzi":"机舱","pinyin":"jīcāng","meaning_vi":"khoang máy bay","explanation":"机 (cơ hội/máy móc) + 舱 (khoang tàu/máy bay).","hsk_level":"7-9","tags":["danh-tu","giao-thong","dia-diem"],"image":"✈️","examples":[{"type":"basic","zh":"机舱里很安静。","pinyin":"Jīcāng lǐ hěn ānjìng.","vi":"Trong khoang máy bay rất yên tĩnh."},{"type":"simple","zh":"空姐推着饮料车在机舱过道里慢慢走着。","pinyin":"Kōngjiě tuīzhe yǐnliào chē zài jīcāng guòdào lǐ mànmàn zǒu zhe.","vi":"Tiếp viên đẩy xe đồ uống chầm chậm đi dọc lối đi trong khoang máy bay."},{"type":"compound","zh":"飞机一遇到气流，机舱就剧烈地颠簸起来。","pinyin":"Fēijī yí yùdào qìliú, jīcāng jiù jùliè de diānbǒ qǐlái.","vi":"Máy bay vừa gặp luồng khí, khoang máy bay liền rung lắc dữ dội."}],"related":[{"hanzi":"客舱","pinyin":"kècāng","vi":"khoang hành khách"},{"hanzi":"头等舱","pinyin":"tóuděngcāng","vi":"khoang hạng nhất"},{"hanzi":"经济舱","pinyin":"jīngjìcāng","vi":"khoang phổ thông"}],"traditional":"機艙"},{"id":"积淀","hanzi":"积淀","pinyin":"jīdiàn","meaning_vi":"tích tụ lắng đọng (văn hóa/kinh nghiệm)","explanation":"积 (tích – chất chứa) + 淀 (điến – lắng đọng) → tích tụ lắng đọng lâu dài; thường nói về văn hóa, lịch sử, kinh nghiệm: 文化积淀.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"这座城文化积淀深厚。","pinyin":"Zhè zuò chéng wénhuà jīdiàn shēnhòu.","vi":"Thành phố này có bề dày văn hóa sâu sắc."},{"type":"simple","zh":"这些建议是他三十年工作经验的积淀。","pinyin":"Zhèxiē jiànyì shì tā sānshí nián gōngzuò jīngyàn de jīdiàn.","vi":"Những lời khuyên này là sự đúc kết từ ba mươi năm kinh nghiệm làm việc của ông."},{"type":"compound","zh":"虽然这家酒厂规模不大，但是积淀了几百年的酿酒工艺。","pinyin":"Suīrán zhè jiā jiǔchǎng guīmó búdà, dànshì jīdiànle jǐ bǎinián de niàngjiǔ gōngyì.","vi":"Tuy xưởng rượu này quy mô không lớn, nhưng đã tích lũy kỹ thuật nấu rượu mấy trăm năm."}],"related":[{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"},{"hanzi":"沉淀","pinyin":"chéndiàn","vi":"lắng đọng"},{"hanzi":"底蕴","pinyin":"dǐyùn","vi":"nội hàm"}],"traditional":"積澱"},{"id":"激荡","hanzi":"激荡","pinyin":"jīdàng","meaning_vi":"khuấy động, sục sôi","explanation":"激 (kích thích/mãnh liệt) + 荡 (dao động/lắc lư).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"海浪激荡着礁石。","pinyin":"Hǎilàng jīdàngzhe jiāoshí.","vi":"Sóng biển vỗ dồn dập vào ghềnh đá."},{"type":"simple","zh":"国歌声中他的心里激荡着自豪感。","pinyin":"Guógē shēng zhōng tā de xīnlǐ jīdàngzhe zìháogǎn.","vi":"Trong tiếng quốc ca, lòng anh ấy dâng trào niềm tự hào."},{"type":"compound","zh":"一走上领奖台，她的心情就激荡得久久不能平静。","pinyin":"Yì zǒushàng lǐngjiǎngtái, tā de xīnqíng jiù jīdàng de jiǔjiǔ bù néng píngjìng.","vi":"Vừa bước lên bục nhận giải, lòng cô ấy sục sôi mãi không thể bình tĩnh lại."}],"related":[{"hanzi":"激动","pinyin":"jīdòng","vi":"kích động"},{"hanzi":"澎湃","pinyin":"péngpài","vi":"cuồn cuộn"},{"hanzi":"动荡","pinyin":"dòngdàng","vi":"biến động"}],"traditional":"激蕩"},{"id":"激化","hanzi":"激化","pinyin":"jīhuà","meaning_vi":"làm gay gắt thêm (mâu thuẫn)","explanation":"激 (kích thích/mãnh liệt) + 化 (化).","hsk_level":"7-9","tags":["dong-tu"],"image":"💥","examples":[{"type":"basic","zh":"矛盾进一步激化了。","pinyin":"Máodùn jìnyíbù jīhuà le.","vi":"Mâu thuẫn càng thêm gay gắt."},{"type":"simple","zh":"房东突然涨租金激化了他和租客之间的矛盾。","pinyin":"Fángdōng tūrán zhǎng zūjīn jīhuàle tā hé zūkè zhījiān de máodùn.","vi":"Việc chủ nhà đột ngột tăng tiền thuê đã làm mâu thuẫn giữa ông ấy và người thuê thêm gay gắt."},{"type":"compound","zh":"如果双方都不肯让步，冲突就会继续激化。","pinyin":"Rúguǒ shuāngfāng dōu bùkěn ràngbù, chōngtū jiù huì jìxù jīhuà.","vi":"Nếu hai bên đều không chịu nhượng bộ, xung đột sẽ tiếp tục leo thang."}],"related":[{"hanzi":"矛盾","pinyin":"máodùn","vi":"mâu thuẫn"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"缓和","pinyin":"huǎnhé","vi":"hòa hoãn"}]},{"id":"积劳成疾","hanzi":"积劳成疾","pinyin":"jīláo-chéngjí","meaning_vi":"làm việc vất vả quá độ sinh bệnh","explanation":"积 (积) + 劳 (lao động/vất vả) + 成 (成) + 疾 (bệnh tật/nhanh).","hsk_level":"7-9","tags":["thanh-ngu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"他积劳成疾，病倒了。","pinyin":"Tā jīláochéngjí, bìngdǎo le.","vi":"Anh ấy làm việc quá sức sinh bệnh, đã ngã quỵ."},{"type":"simple","zh":"这位老医生因长年连轴转而积劳成疾。","pinyin":"Zhè wèi lǎo yīshēng yīn chángnián liánzhóuzhuàn ér jīláochéngjí.","vi":"Vị bác sĩ già này vì nhiều năm làm việc không ngừng nghỉ mà kiệt sức sinh bệnh."},{"type":"compound","zh":"如果你再这样天天熬夜加班，迟早会积劳成疾。","pinyin":"Rúguǒ nǐ zài zhèyàng tiāntiān áoyè jiābān, chízǎo huì jīláochéngjí.","vi":"Nếu bạn cứ ngày nào cũng thức khuya tăng ca thế này, sớm muộn gì cũng kiệt sức sinh bệnh."}],"related":[{"hanzi":"劳累","pinyin":"láolèi","vi":"mệt nhọc"},{"hanzi":"过度劳累","pinyin":"guòdùláolèi","vi":"làm việc quá sức"},{"hanzi":"疾病","pinyin":"jíbìng","vi":"bệnh tật"}],"traditional":"積勞成疾"},{"id":"机理","hanzi":"机理","pinyin":"jīlǐ","meaning_vi":"cơ chế, nguyên lý hoạt động","explanation":"机 (cơ hội/máy móc) + 理 (lý luận/quản lý).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"⚙️","examples":[{"type":"basic","zh":"其中机理尚不清楚。","pinyin":"Qízhōng jīlǐ shàng bù qīngchu.","vi":"Cơ chế bên trong vẫn chưa rõ ràng."},{"type":"simple","zh":"科学家终于弄清了这种药物降血压的机理。","pinyin":"Kēxuéjiā zhōngyú nòngqīngle zhè zhǒng yàowù jiàng xuèyā de jīlǐ.","vi":"Các nhà khoa học cuối cùng đã làm rõ cơ chế hạ huyết áp của loại thuốc này."},{"type":"compound","zh":"只有搞清楚发病机理，才能找到有效的治疗办法。","pinyin":"Zhǐyǒu gǎo qīngchu fābìng jīlǐ, cáinéng zhǎodào yǒuxiào de zhìliáo bànfǎ.","vi":"Chỉ khi làm rõ cơ chế phát bệnh mới có thể tìm ra cách điều trị hiệu quả."}],"related":[{"hanzi":"原理","pinyin":"yuánlǐ","vi":"nguyên lý"},{"hanzi":"机制","pinyin":"jīzhì","vi":"cơ chế"},{"hanzi":"规律","pinyin":"guīlǜ","vi":"quy luật"}],"traditional":"機理"},{"id":"机器人","hanzi":"机器人","pinyin":"jīqìrén","meaning_vi":"người máy, rô-bốt","explanation":"机 (cơ hội/máy móc) + 器 (thiết bị/cơ quan) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🤖","examples":[{"type":"basic","zh":"机器人会扫地。","pinyin":"Jīqìrén huì sǎodì.","vi":"Rô-bốt biết quét nhà."},{"type":"simple","zh":"这家餐厅用送餐机器人把菜端到每张桌子上。","pinyin":"Zhè jiā cāntīng yòng sòngcān jīqìrén bǎ cài duān dào měi zhāng zhuōzi shang.","vi":"Nhà hàng này dùng rô-bốt phục vụ để mang món ăn đến từng bàn."},{"type":"compound","zh":"虽然机器人能代替很多工作，但是它代替不了人的情感。","pinyin":"Suīrán jīqìrén néng dàitì hěn duō gōngzuò, dànshì tā dàitì bùliǎo rén de qínggǎn.","vi":"Tuy rô-bốt có thể thay thế nhiều công việc, nhưng nó không thể thay thế tình cảm con người."}],"related":[{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"},{"hanzi":"机器","pinyin":"jīqì","vi":"máy móc"},{"hanzi":"自动化","pinyin":"zìdònghuà","vi":"tự động hóa"}],"traditional":"機器人"},{"id":"机器学习","hanzi":"机器学习","pinyin":"jīqìxuéxí","meaning_vi":"học máy (Machine Learning)","explanation":"机器 (cơ khí – máy móc) + 学习 (học tập) → học máy, nhánh của trí tuệ nhân tạo giúp máy tự học từ dữ liệu.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","khoa-hoc"],"image":"🧠","examples":[{"type":"basic","zh":"他研究机器学习。","pinyin":"Tā yánjiū jīqìxuéxí.","vi":"Anh ấy nghiên cứu học máy."},{"type":"simple","zh":"这家银行利用机器学习识别可疑的转账记录。","pinyin":"Zhè jiā yínháng lìyòng jīqìxuéxí shíbié kěyí de zhuǎnzhàng jìlù.","vi":"Ngân hàng này dùng học máy để phát hiện các giao dịch chuyển khoản đáng ngờ."},{"type":"compound","zh":"如果训练数据不够多，机器学习模型就很难准确。","pinyin":"Rúguǒ xùnliàn shùjù búgòu duō, jīqìxuéxí móxíng jiù hěn nán zhǔnquè.","vi":"Nếu dữ liệu huấn luyện không đủ nhiều, mô hình học máy sẽ khó đạt độ chính xác."}],"related":[{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"},{"hanzi":"深度学习","pinyin":"shēndùxuéxí","vi":"học sâu"},{"hanzi":"算法","pinyin":"suànfǎ","vi":"thuật toán"}],"traditional":"機器學習"},{"id":"机缘","hanzi":"机缘","pinyin":"jīyuán","meaning_vi":"cơ duyên","explanation":"机 (cơ hội/máy móc) + 缘 (duyên phận/nguyên cớ).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🍀","examples":[{"type":"basic","zh":"这是难得的机缘。","pinyin":"Zhè shì nándé de jīyuán.","vi":"Đây là cơ duyên hiếm có."},{"type":"simple","zh":"一次偶然的机缘让他走上了绘画的道路。","pinyin":"Yí cì ǒurán de jīyuán ràng tā zǒushàngle huìhuà de dàolù.","vi":"Một cơ duyên tình cờ đã đưa anh ấy đến với con đường hội họa."},{"type":"compound","zh":"如果没有那次旅行的机缘，我们就不会相识了。","pinyin":"Rúguǒ méiyǒu nà cì lǚxíng de jīyuán, wǒmen jiù bú huì xiāngshí le.","vi":"Nếu không có cơ duyên từ chuyến du lịch ấy, chúng ta đã không quen nhau."}],"related":[{"hanzi":"缘分","pinyin":"yuánfèn","vi":"duyên phận"},{"hanzi":"机遇","pinyin":"jīyù","vi":"cơ hội"},{"hanzi":"巧合","pinyin":"qiǎohé","vi":"trùng hợp"}],"traditional":"機緣"},{"id":"基因工程","hanzi":"基因工程","pinyin":"jīyīngōngchéng","meaning_vi":"kỹ thuật di truyền","explanation":"基 (基) + 因 (nguyên nhân/nhân tố) + 工 (工) + 程 (程).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","suc-khoe"],"image":"🧬","examples":[{"type":"basic","zh":"他主修基因工程。","pinyin":"Tā zhǔxiū jīyīngōngchéng.","vi":"Anh ấy học chuyên ngành kỹ thuật di truyền."},{"type":"simple","zh":"科学家通过基因工程培育出了抗虫的棉花。","pinyin":"Kēxuéjiā tōngguò jīyīngōngchéng péiyù chūle kàng chóng de miánhua.","vi":"Các nhà khoa học đã tạo ra giống bông kháng sâu bằng kỹ thuật di truyền."},{"type":"compound","zh":"基因工程虽然前景广阔，但是也引发了伦理争议。","pinyin":"Jīyīngōngchéng suīrán qiánjǐng guǎngkuò, dànshì yě yǐnfāle lúnlǐ zhēngyì.","vi":"Kỹ thuật di truyền tuy có triển vọng rộng mở, nhưng cũng gây ra tranh cãi về đạo đức."}],"related":[{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"},{"hanzi":"克隆","pinyin":"kèlóng","vi":"nhân bản vô tính"},{"hanzi":"生物技术","pinyin":"shēngwùjìshù","vi":"công nghệ sinh học"}]},{"id":"机制","hanzi":"机制","pinyin":"jīzhì","meaning_vi":"cơ chế","explanation":"机 (cơ hội/máy móc) + 制 (chế độ/kiềm chế).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"⚙️","examples":[{"type":"basic","zh":"公司有奖励机制。","pinyin":"Gōngsī yǒu jiǎnglì jīzhì.","vi":"Công ty có cơ chế khen thưởng."},{"type":"simple","zh":"这家医院建立了二十四小时的急诊响应机制。","pinyin":"Zhè jiā yīyuàn jiànlìle èr shísì xiǎoshí de jízhěn xiǎngyìng jīzhì.","vi":"Bệnh viện này đã xây dựng cơ chế phản ứng cấp cứu hai mươi bốn giờ."},{"type":"compound","zh":"只要监督机制健全，腐败就很难滋生。","pinyin":"Zhǐyào jiāndū jīzhì jiànquán, fǔbài jiù hěn nán zīshēng.","vi":"Chỉ cần cơ chế giám sát hoàn thiện, tham nhũng sẽ khó nảy sinh."}],"related":[{"hanzi":"体制","pinyin":"tǐzhì","vi":"thể chế"},{"hanzi":"机理","pinyin":"jīlǐ","vi":"cơ chế"},{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"}],"traditional":"機制"},{"id":"激增","hanzi":"激增","pinyin":"jīzēng","meaning_vi":"tăng vọt mạnh mẽ","explanation":"激 (kích thích/mãnh liệt) + 增 (tăng thêm).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"网购订单激增。","pinyin":"Wǎnggòu dìngdān jīzēng.","vi":"Đơn hàng mua sắm trực tuyến tăng vọt."},{"type":"simple","zh":"双十一当天快递公司的包裹量激增了五倍。","pinyin":"Shuāngshíyī dāngtiān kuàidì gōngsī de bāoguǒ liàng jīzēngle wǔ bèi.","vi":"Ngày 11/11, lượng bưu kiện của công ty chuyển phát tăng vọt gấp năm lần."},{"type":"compound","zh":"因为电动车销量激增，所以充电桩严重不足。","pinyin":"Yīnwèi diàndòngchē xiāoliàng jīzēng, suǒyǐ chōngdiànzhuāng yánzhòng bùzú.","vi":"Vì doanh số xe điện tăng vọt, nên trụ sạc bị thiếu trầm trọng."}],"related":[{"hanzi":"剧增","pinyin":"jùzēng","vi":"tăng vọt"},{"hanzi":"猛增","pinyin":"měngzēng","vi":"tăng mạnh"},{"hanzi":"骤减","pinyin":"zhòujiǎn","vi":"giảm đột ngột"}]},{"id":"巾帼","hanzi":"巾帼","pinyin":"jīnguó","meaning_vi":"phụ nữ, nữ giới (巾帼英雄 - nữ anh hùng)","explanation":"巾 (khăn) + 帼 (khăn trùm đầu phụ nữ).","hsk_level":"7-9","tags":["danh-tu","van-hoa","con-nguoi"],"image":"🦸‍♀️","examples":[{"type":"basic","zh":"她是巾帼英雄。","pinyin":"Tā shì jīnguó yīngxióng.","vi":"Bà ấy là một nữ anh hùng."},{"type":"simple","zh":"这支巾帼救援队常年驻守在高原上。","pinyin":"Zhè zhī jīnguó jiùyuánduì chángnián zhùshǒu zài gāoyuán shang.","vi":"Đội cứu hộ toàn nữ này quanh năm túc trực trên cao nguyên."},{"type":"compound","zh":"虽然她身材瘦小，但是巾帼不让须眉。","pinyin":"Suīrán tā shēncái shòuxiǎo, dànshì jīnguó bú ràng xūméi.","vi":"Tuy dáng người nhỏ nhắn, nhưng cô ấy tài giỏi chẳng kém gì nam nhi."}],"related":[{"hanzi":"巾帼英雄","pinyin":"jīnguóyīngxióng","vi":"nữ anh hùng"},{"hanzi":"妇女","pinyin":"fùnǚ","vi":"phụ nữ"},{"hanzi":"须眉","pinyin":"xūméi","vi":"nam nhi"}],"traditional":"巾幗"},{"id":"金牌","hanzi":"金牌","pinyin":"jīnpái","meaning_vi":"huy chương vàng","explanation":"金 (kim – vàng) + 牌 (bài – tấm thẻ, huy chương) → huy chương vàng; nghĩa bóng: hạng nhất. VD: 金牌得主, 金牌销售.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🥇","examples":[{"type":"basic","zh":"他拿了一枚金牌。","pinyin":"Tā nále yìméi jīnpái.","vi":"Anh ấy giành được một huy chương vàng."},{"type":"simple","zh":"她在女子跳水决赛中为国家队夺得了金牌。","pinyin":"Tā zài nǚzǐ tiàoshuǐ juésài zhōng wèi guójiāduì duó déle jīnpái.","vi":"Cô ấy đã giành huy chương vàng cho đội tuyển quốc gia trong trận chung kết nhảy cầu nữ."},{"type":"compound","zh":"即使这次拿不到金牌，他也已经创造了个人最好成绩。","pinyin":"Jíshǐ zhè cì ná búdào jīnpái, tā yě yǐjīng chuàngzàole gèrén zuìhǎo chéngjì.","vi":"Dù lần này không giành được huy chương vàng, anh ấy cũng đã lập thành tích tốt nhất của bản thân."}],"related":[{"hanzi":"银牌","pinyin":"yínpái","vi":"huy chương bạc"},{"hanzi":"铜牌","pinyin":"tóngpái","vi":"huy chương đồng"},{"hanzi":"冠军","pinyin":"guànjūn","vi":"nhà vô địch"}]},{"id":"金秋","hanzi":"金秋","pinyin":"jīnqiū","meaning_vi":"mùa thu vàng","explanation":"金 (kim – vàng) + 秋 (thu – mùa thu) → mùa thu vàng, mùa thu hoạch; văn viết. VD: 金秋十月.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","van-hoa"],"image":"🍂","examples":[{"type":"basic","zh":"金秋十月到了。","pinyin":"Jīnqiū Shíyuè dào le.","vi":"Tháng Mười mùa thu vàng đã đến."},{"type":"simple","zh":"金秋时节，农民们在田里收割稻子。","pinyin":"Jīnqiū shíjié, nóngmínmen zài tián lǐ shōugē dàozi.","vi":"Vào mùa thu vàng, nông dân gặt lúa trên đồng."},{"type":"compound","zh":"一到金秋，满山的枫叶就红得像火一样。","pinyin":"Yí dào jīnqiū, mǎn shān de fēngyè jiù hóng de xiàng huǒ yíyàng.","vi":"Cứ đến mùa thu vàng, lá phong khắp núi lại đỏ rực như lửa."}],"related":[{"hanzi":"秋天","pinyin":"qiūtiān","vi":"mùa thu"},{"hanzi":"丰收","pinyin":"fēngshōu","vi":"được mùa"},{"hanzi":"秋高气爽","pinyin":"qiūgāoqìshuǎng","vi":"trời thu trong mát"}]},{"id":"金融危机","hanzi":"金融危机","pinyin":"jīnróngwēijī","meaning_vi":"khủng hoảng tài chính","explanation":"金融 (kim dung – tài chính) + 危机 (nguy cơ – khủng hoảng) → khủng hoảng tài chính. VD: 2008年全球金融危机.","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"📉","examples":[{"type":"basic","zh":"金融危机爆发了。","pinyin":"Jīnróngwēijī bàofā le.","vi":"Khủng hoảng tài chính đã bùng nổ."},{"type":"simple","zh":"二零零八年的金融危机让许多工厂倒闭了。","pinyin":"Èr líng líng bā nián de jīnróngwēijī ràng xǔduō gōngchǎng dǎobì le.","vi":"Cuộc khủng hoảng tài chính năm 2008 đã khiến nhiều nhà máy đóng cửa."},{"type":"compound","zh":"一旦发生金融危机，普通人的储蓄就可能大幅缩水。","pinyin":"Yídàn fāshēng jīnróngwēijī, pǔtōngrén de chǔxù jiù kěnéng dàfú suōshuǐ.","vi":"Một khi xảy ra khủng hoảng tài chính, tiền tiết kiệm của người bình thường có thể bị hao hụt nặng."}],"related":[{"hanzi":"经济危机","pinyin":"jīngjìwēijī","vi":"khủng hoảng kinh tế"},{"hanzi":"金融","pinyin":"jīnróng","vi":"tài chính"},{"hanzi":"经济复苏","pinyin":"jīngjìfùsū","vi":"phục hồi kinh tế"}],"traditional":"金融危機"},{"id":"金山银山","hanzi":"金山银山","pinyin":"jīnshānyínshān","meaning_vi":"núi vàng núi bạc (tài sản kinh tế)","explanation":"金 (金) + 山 (núi non) + 银 (bạc/ngân hàng) + 山 (núi non).","hsk_level":"7-9","tags":["danh-tu","tien-te","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"绿水青山就是金山银山。","pinyin":"Lǜshuǐqīngshān jiùshì jīnshānyínshān.","vi":"Nước biếc non xanh chính là núi vàng núi bạc."},{"type":"simple","zh":"村民们靠生态旅游把荒山变成了金山银山。","pinyin":"Cūnmínmen kào shēngtài lǚyóu bǎ huāngshān biàn chéngle jīnshānyínshān.","vi":"Nhờ du lịch sinh thái, dân làng đã biến núi hoang thành núi vàng núi bạc."},{"type":"compound","zh":"即使给我金山银山，我也不会卖掉祖传的老宅。","pinyin":"Jíshǐ gěi wǒ jīnshānyínshān, wǒ yě bú huì màidiào zǔchuán de lǎo zhái.","vi":"Dù có cho tôi núi vàng núi bạc, tôi cũng không bán ngôi nhà cổ của tổ tiên."}],"related":[{"hanzi":"绿水青山","pinyin":"lǜshuǐqīngshān","vi":"non xanh nước biếc"},{"hanzi":"财富","pinyin":"cáifù","vi":"của cải"},{"hanzi":"经济发展","pinyin":"jīngjìfāzhǎn","vi":"phát triển kinh tế"}],"traditional":"金山銀山"},{"id":"金字塔","hanzi":"金字塔","pinyin":"Jīnzìtǎ","meaning_vi":"kim tự tháp","explanation":"金 (金) + 字 (chữ) + 塔 (ngôi tháp).","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-danh"],"image":"🏜️","examples":[{"type":"basic","zh":"我们参观了金字塔。","pinyin":"Wǒmen cānguānle Jīnzìtǎ.","vi":"Chúng tôi đã tham quan kim tự tháp."},{"type":"simple","zh":"古埃及人用巨大的石块建造了金字塔。","pinyin":"Gǔ Āijí rén yòng jùdà de shíkuài jiànzàole Jīnzìtǎ.","vi":"Người Ai Cập cổ đại đã dùng những khối đá khổng lồ để xây kim tự tháp."},{"type":"compound","zh":"虽然金字塔已有四千多年历史，但是至今仍有许多谜团。","pinyin":"Suīrán Jīnzìtǎ yǐ yǒu sì qiān duōnián lìshǐ, dànshì zhìjīn réng yǒu xǔduō mítuán.","vi":"Tuy kim tự tháp đã có lịch sử hơn bốn nghìn năm, nhưng đến nay vẫn còn nhiều bí ẩn."}],"related":[{"hanzi":"埃及","pinyin":"Āijí","vi":"Ai Cập"},{"hanzi":"古迹","pinyin":"gǔjì","vi":"di tích cổ"},{"hanzi":"法老","pinyin":"fǎlǎo","vi":"pharaoh"}]},{"id":"经济复苏","hanzi":"经济复苏","pinyin":"jīngjìfùsū","meaning_vi":"phục hồi kinh tế","explanation":"经济 + 复苏 (hồi sinh).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"🌱","examples":[{"type":"basic","zh":"经济复苏很缓慢。","pinyin":"Jīngjìfùsū hěn huǎnmàn.","vi":"Kinh tế phục hồi rất chậm."},{"type":"simple","zh":"旅游业的回暖有力推动了当地的经济复苏。","pinyin":"Lǚyóuyè de huínuǎn yǒulì tuīdòngle dāngdì de jīngjìfùsū.","vi":"Sự khởi sắc của ngành du lịch đã thúc đẩy mạnh mẽ việc phục hồi kinh tế địa phương."},{"type":"compound","zh":"只要消费信心恢复，经济复苏就会加快。","pinyin":"Zhǐyào xiāofèi xìnxīn huīfù, jīngjìfùsū jiù huì jiākuài.","vi":"Chỉ cần niềm tin tiêu dùng được khôi phục, kinh tế sẽ phục hồi nhanh hơn."}],"related":[{"hanzi":"复苏","pinyin":"fùsū","vi":"phục hồi"},{"hanzi":"经济衰退","pinyin":"jīngjìshuāituì","vi":"suy thoái kinh tế"},{"hanzi":"回暖","pinyin":"huínuǎn","vi":"ấm lên"}],"traditional":"經濟復甦"},{"id":"京剧","hanzi":"京剧","pinyin":"Jīngjù","meaning_vi":"Kinh kịch","explanation":"京 (Bắc Kinh) + 剧 (kịch).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"爷爷爱听京剧。","pinyin":"Yéye ài tīng Jīngjù.","vi":"Ông nội thích nghe Kinh kịch."},{"type":"simple","zh":"她在留学生晚会上唱了一段京剧。","pinyin":"Tā zài liúxuéshēng wǎnhuì shang chàngle yí duàn Jīngjù.","vi":"Cô ấy hát một đoạn Kinh kịch trong buổi dạ hội của lưu học sinh."},{"type":"compound","zh":"虽然我听不懂京剧唱词，但是很喜欢演员的服装。","pinyin":"Suīrán wǒ tīngbùdǒng Jīngjù chàngcí, dànshì hěn xǐhuan yǎnyuán de fúzhuāng.","vi":"Tuy tôi nghe không hiểu lời hát Kinh kịch, nhưng tôi rất thích trang phục của diễn viên."}],"related":[{"hanzi":"脸谱","pinyin":"liǎnpǔ","vi":"mặt nạ Kinh kịch"},{"hanzi":"戏曲","pinyin":"xìqǔ","vi":"hí khúc"},{"hanzi":"国粹","pinyin":"guócuì","vi":"quốc túy"}],"traditional":"京劇"},{"id":"精辟","hanzi":"精辟","pinyin":"jīngpì","meaning_vi":"sâu sắc sắc sảo (lập luận/nhận xét)","explanation":"精 (tinh hoa/tinh xảo) + 辟 (khai phá/bác bỏ).","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"💡","examples":[{"type":"basic","zh":"他的分析很精辟。","pinyin":"Tā de fēnxī hěn jīngpì.","vi":"Phân tích của anh ấy rất sắc sảo."},{"type":"simple","zh":"教授用一句精辟的话概括了全书的主题。","pinyin":"Jiàoshòu yòng yíjù jīngpì dehuà gàikuòle quánshū de zhǔtí.","vi":"Giáo sư dùng một câu nói sâu sắc để khái quát chủ đề của cả cuốn sách."},{"type":"compound","zh":"他的发言不但精辟，而且幽默，赢得了满堂掌声。","pinyin":"Tā de fāyán búdàn jīngpì, érqiě yōumò, yíng déle mǎntáng zhǎngshēng.","vi":"Bài phát biểu của anh ấy không chỉ sắc sảo mà còn hài hước, nhận được tràng pháo tay của cả hội trường."}],"related":[{"hanzi":"深刻","pinyin":"shēnkè","vi":"sâu sắc"},{"hanzi":"透彻","pinyin":"tòuchè","vi":"thấu đáo"},{"hanzi":"精辟见解","pinyin":"jīngpìjiànjiě","vi":"kiến giải sắc sảo"}],"traditional":"精闢"},{"id":"精髓","hanzi":"精髓","pinyin":"jīngsuǐ","meaning_vi":"tinh túy, cốt lõi tinh hoa","explanation":"精 (tinh hoa/tinh xảo) + 髓 (tủy xương/tinh túy).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💎","examples":[{"type":"basic","zh":"这就是功夫的精髓。","pinyin":"Zhè jiùshì gōngfu de jīngsuǐ.","vi":"Đây chính là tinh túy của võ công."},{"type":"simple","zh":"这本书抓住了中医养生理论的精髓。","pinyin":"Zhè běn shū zhuāzhùle zhōngyī yǎngshēng lǐlùn de jīngsuǐ.","vi":"Cuốn sách này đã nắm bắt được tinh túy của lý luận dưỡng sinh Đông y."},{"type":"compound","zh":"如果只学外在形式，就领会不到太极拳的精髓。","pinyin":"Rúguǒ zhǐ xué wàizài xíngshì, jiù lǐnghuì búdào tàijíquán de jīngsuǐ.","vi":"Nếu chỉ học hình thức bên ngoài thì sẽ không lĩnh hội được tinh túy của Thái cực quyền."}],"related":[{"hanzi":"精华","pinyin":"jīnghuá","vi":"tinh hoa"},{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"核心","pinyin":"héxīn","vi":"cốt lõi"}]},{"id":"惊叹","hanzi":"惊叹","pinyin":"jīngtàn","meaning_vi":"kinh ngạc thán phục","explanation":"惊 (kinh ngạc) + 叹 (cảm thán/thở dài).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😲","examples":[{"type":"basic","zh":"观众连连惊叹。","pinyin":"Guānzhòng liánlián jīngtàn.","vi":"Khán giả liên tục trầm trồ thán phục."},{"type":"simple","zh":"游客们无不惊叹于九寨沟湖水的色彩。","pinyin":"Yóukèmen wúbù jīngtàn yú Jiǔzhàigōu húshuǐ de sècǎi.","vi":"Du khách ai nấy đều kinh ngạc trước màu sắc của nước hồ Cửu Trại Câu."},{"type":"compound","zh":"那个十岁女孩一开口唱歌，评委们就惊叹不已。","pinyin":"Nà gè shí suì nǚhái yì kāikǒu chànggē, píngwěimen jiù jīngtàn bùyǐ.","vi":"Cô bé mười tuổi ấy vừa cất tiếng hát, các giám khảo liền trầm trồ không ngớt."}],"related":[{"hanzi":"赞叹","pinyin":"zàntàn","vi":"tán thán"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"},{"hanzi":"叹为观止","pinyin":"tànwéiguānzhǐ","vi":"đẹp tuyệt vời"}],"traditional":"驚嘆"},{"id":"惊险","hanzi":"惊险","pinyin":"jīngxiǎn","meaning_vi":"ly kỳ mạo hiểm, thót tim","explanation":"惊 (kinh ngạc) + 险 (nguy hiểm/bảo hiểm).","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🎢","examples":[{"type":"basic","zh":"这段路很惊险。","pinyin":"Zhè duàn lù hěn jīngxiǎn.","vi":"Đoạn đường này rất hiểm trở thót tim."},{"type":"simple","zh":"杂技演员在高空钢丝上做了一个惊险的动作。","pinyin":"Zájì yǎnyuán zài gāokōng gāngsī shang zuòle yí gè jīngxiǎn de dòngzuò.","vi":"Diễn viên xiếc thực hiện một động tác mạo hiểm trên dây thép trên cao."},{"type":"compound","zh":"虽然过程十分惊险，但是所有乘客都安全着陆了。","pinyin":"Suīrán guòchéng shífēn jīngxiǎn, dànshì suǒyǒu chéngkè dōu ānquán zhuólù le.","vi":"Tuy quá trình vô cùng thót tim, nhưng tất cả hành khách đều đã hạ cánh an toàn."}],"related":[{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"},{"hanzi":"刺激","pinyin":"cìjī","vi":"kích thích"},{"hanzi":"惊心动魄","pinyin":"jīngxīndòngpò","vi":"kinh hồn bạt vía"}],"traditional":"驚險"},{"id":"精益","hanzi":"精益","pinyin":"jīngyì","meaning_vi":"tinh gọn hiệu quả (Lean)","explanation":"精 (tinh hoa/tinh xảo) + 益 (lợi ích/bổ ích).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"⚙️","examples":[{"type":"basic","zh":"工厂推行精益生产。","pinyin":"Gōngchǎng tuīxíng jīngyì shēngchǎn.","vi":"Nhà máy áp dụng sản xuất tinh gọn."},{"type":"simple","zh":"这家车企靠精益管理把库存降低了一半。","pinyin":"Zhè jiā chē qǐ kào jīngyì guǎnlǐ bǎ kùcún jiàngdīle yíbàn.","vi":"Hãng xe này nhờ quản lý tinh gọn mà đã giảm được một nửa hàng tồn kho."},{"type":"compound","zh":"因为引入了精益管理，所以车间的浪费明显减少了。","pinyin":"Yīnwèi yǐnrùle jīngyì guǎnlǐ, suǒyǐ chējiān de làngfèi míngxiǎn jiǎnshǎo le.","vi":"Vì áp dụng quản lý tinh gọn, nên lãng phí trong phân xưởng đã giảm rõ rệt."}],"related":[{"hanzi":"精益求精","pinyin":"jīngyìqiújīng","vi":"tinh lại càng tinh"},{"hanzi":"精细","pinyin":"jīngxì","vi":"tinh tế"},{"hanzi":"高效","pinyin":"gāoxiào","vi":"hiệu quả cao"}]},{"id":"晶莹","hanzi":"晶莹","pinyin":"jīngyíng","meaning_vi":"lấp lánh trong suốt (giọt sương/ngọc)","explanation":"晶 (tinh thể/trong suốt) + 莹 (trong suốt lấp lánh).","hsk_level":"7-9","tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"露珠晶莹剔透。","pinyin":"Lùzhū jīngyíng tītòu.","vi":"Giọt sương trong suốt lấp lánh."},{"type":"simple","zh":"她眼眶里闪着晶莹的泪花。","pinyin":"Tā yǎnkuàng lǐ shǎnzhe jīngyíng de lèihuā.","vi":"Trong khóe mắt cô ấy lấp lánh những giọt lệ trong suốt."},{"type":"compound","zh":"太阳一出来，草叶上的露珠就显得格外晶莹。","pinyin":"Tàiyáng yì chūlái, cǎo yè shang de lùzhū jiù xiǎnde géwài jīngyíng.","vi":"Mặt trời vừa lên, những giọt sương trên lá cỏ càng trở nên lấp lánh."}],"related":[{"hanzi":"晶莹剔透","pinyin":"jīngyíngtītòu","vi":"trong suốt lấp lánh"},{"hanzi":"透明","pinyin":"tòumíng","vi":"trong suốt"},{"hanzi":"露珠","pinyin":"lùzhū","vi":"giọt sương"}],"traditional":"晶瑩"},{"id":"居高不下","hanzi":"居高不下","pinyin":"jūgāo-búxià","meaning_vi":"duy trì ở mức cao không giảm (giá cả)","explanation":"居 (cư trú) + 高 (cao) + 不 (không) + 下 (dưới).","hsk_level":"7-9","tags":["thanh-ngu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"房价居高不下。","pinyin":"Fángjià jūgāobúxià.","vi":"Giá nhà vẫn ở mức cao không giảm."},{"type":"simple","zh":"这座城市的失业率去年一直居高不下。","pinyin":"Zhè zuò chéngshì de shīyèlǜ qùnián yìzhí jūgāobúxià.","vi":"Năm ngoái tỷ lệ thất nghiệp của thành phố này luôn ở mức cao."},{"type":"compound","zh":"由于饲料涨价，所以猪肉价格持续居高不下。","pinyin":"Yóuyú sìliào zhǎngjià, suǒyǐ zhūròu jiàgé chíxù jūgāobúxià.","vi":"Do thức ăn chăn nuôi tăng giá, nên giá thịt lợn liên tục ở mức cao không giảm."}],"related":[{"hanzi":"高涨","pinyin":"gāozhǎng","vi":"tăng cao"},{"hanzi":"房价","pinyin":"fángjià","vi":"giá nhà"},{"hanzi":"回落","pinyin":"huíluò","vi":"giảm lại"}]},{"id":"居家","hanzi":"居家","pinyin":"jūjiā","meaning_vi":"ở nhà (làm việc tại nhà - 居家办公)","explanation":"居 (cư trú) + 家 (nhà).","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏡","examples":[{"type":"basic","zh":"他今天居家办公。","pinyin":"Tā jīntiān jūjiā bàngōng.","vi":"Hôm nay anh ấy làm việc tại nhà."},{"type":"simple","zh":"疫情期间，许多老人居家隔离了两个星期。","pinyin":"Yìqíng qījiān, xǔduō lǎorén jūjiā gélíle liǎng gè xīngqī.","vi":"Trong thời gian dịch bệnh, nhiều người già đã cách ly tại nhà hai tuần."},{"type":"compound","zh":"虽然居家办公很自由，但是很容易分心。","pinyin":"Suīrán jūjiā bàngōng hěn zìyóu, dànshì hěn róngyì fēnxīn.","vi":"Tuy làm việc tại nhà rất tự do, nhưng lại rất dễ mất tập trung."}],"related":[{"hanzi":"居家办公","pinyin":"jūjiābàngōng","vi":"làm việc tại nhà"},{"hanzi":"在家","pinyin":"zàijiā","vi":"ở nhà"},{"hanzi":"家居","pinyin":"jiājū","vi":"nội thất gia đình"}]},{"id":"居民楼","hanzi":"居民楼","pinyin":"jūmínlóu","meaning_vi":"tòa nhà chung cư dân cư","explanation":"居 (cư trú) + 民 (nhân dân/dân chủ) + 楼 (tầng).","hsk_level":"7-9","tags":["danh-tu","nha-cua","dia-diem"],"image":"🏢","examples":[{"type":"basic","zh":"这是一栋老居民楼。","pinyin":"Zhè shì yí dòng lǎo jūmínlóu.","vi":"Đây là một tòa nhà dân cư cũ."},{"type":"simple","zh":"街角那栋居民楼今年加装了两部电梯。","pinyin":"Jiē jiǎo nà dòng jūmínlóu jīnnián jiā zhuāngle liǎng bù diàntī.","vi":"Tòa nhà dân cư ở góc phố năm nay đã lắp thêm hai thang máy."},{"type":"compound","zh":"因为居民楼离工地太近，所以住户们投诉噪音太大。","pinyin":"Yīnwèi jūmínlóu lí gōngdì tài jìn, suǒyǐ zhùhùmen tóusù zàoyīn tài dà.","vi":"Vì tòa nhà dân cư quá gần công trường, nên các hộ dân phàn nàn tiếng ồn quá lớn."}],"related":[{"hanzi":"居民","pinyin":"jūmín","vi":"cư dân"},{"hanzi":"小区","pinyin":"xiǎoqū","vi":"khu dân cư"},{"hanzi":"公寓","pinyin":"gōngyù","vi":"chung cư"}],"traditional":"居民樓"},{"id":"均衡","hanzi":"均衡","pinyin":"jūnhéng","meaning_vi":"cân bằng, đồng đều","explanation":"均 (đồng đều/bình quân) + 衡 (cân nhắc/cân bằng).","hsk_level":"7-9","tags":["tinh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"饮食要营养均衡。","pinyin":"Yǐnshí yào yíngyǎng jūnhéng.","vi":"Ăn uống cần cân bằng dinh dưỡng."},{"type":"simple","zh":"政府正在努力促进城乡教育资源均衡分配。","pinyin":"Zhèngfǔ zhèngzài nǔlì cùjìn chéngxiāng jiàoyù zīyuán jūnhéng fēnpèi.","vi":"Chính phủ đang nỗ lực thúc đẩy phân bổ đồng đều nguồn lực giáo dục giữa thành thị và nông thôn."},{"type":"compound","zh":"这支球队既有强大的进攻，又有稳固的防守，实力非常均衡。","pinyin":"Zhè zhī qiúduì jìyǒu qiángdà de jìngōng, yòu yǒu wěngù de fángshǒu, shílì fēicháng jūnhéng.","vi":"Đội bóng này vừa có hàng công mạnh mẽ, vừa có hàng thủ vững chắc, thực lực rất cân bằng."}],"related":[{"hanzi":"平衡","pinyin":"pínghéng","vi":"cân bằng"},{"hanzi":"均匀","pinyin":"jūnyún","vi":"đồng đều"},{"hanzi":"失衡","pinyin":"shīhéng","vi":"mất cân bằng"}]},{"id":"军舰","hanzi":"军舰","pinyin":"jūnjiàn","meaning_vi":"tàu chiến","explanation":"军 (quân đội) + 舰 (tàu chiến).","hsk_level":"7-9","tags":["danh-tu","giao-thong","xa-hoi"],"image":"🚢","examples":[{"type":"basic","zh":"港口停着军舰。","pinyin":"Gǎngkǒu tíngzhe jūnjiàn.","vi":"Trong cảng có tàu chiến đang neo đậu."},{"type":"simple","zh":"一艘军舰缓缓驶入了军港。","pinyin":"Yì sōu jūnjiàn huǎnhuǎn shǐrùle jūngǎng.","vi":"Một chiếc tàu chiến chầm chậm tiến vào quân cảng."},{"type":"compound","zh":"军舰一靠岸，水兵们就整齐地列队下船。","pinyin":"Jūnjiàn yí kào'àn, shuǐbīngmen jiù zhěngqí de lièduì xià chuán.","vi":"Tàu chiến vừa cập bến, các thủy thủ liền xếp hàng ngay ngắn xuống tàu."}],"related":[{"hanzi":"航空母舰","pinyin":"hángkōngmǔjiàn","vi":"tàu sân bay"},{"hanzi":"海军","pinyin":"hǎijūn","vi":"hải quân"},{"hanzi":"潜艇","pinyin":"qiántǐng","vi":"tàu ngầm"}],"traditional":"軍艦"},{"id":"几代人","hanzi":"几代人","pinyin":"jǐdàirén","meaning_vi":"mấy thế hệ người","explanation":"几 (mấy) + 代 (代) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","gia-dinh","thoi-gian"],"image":"👨‍👩‍👧‍👦","examples":[{"type":"basic","zh":"这是几代人的梦想。","pinyin":"Zhè shì jǐdàirén de mèngxiǎng.","vi":"Đây là ước mơ của mấy thế hệ."},{"type":"simple","zh":"这座老宅里先后住过张家几代人。","pinyin":"Zhè zuò lǎo zhái lǐ xiānhòu zhùguò zhāng jiā jǐdàirén.","vi":"Ngôi nhà cổ này lần lượt có mấy thế hệ nhà họ Trương sinh sống."},{"type":"compound","zh":"正因为有几代人的接力，这片沙漠才变成了绿洲。","pinyin":"Zhèng yīnwèi yǒu jǐdàirén de jiēlì, zhè piàn shāmò cái biàn chéngle lǜzhōu.","vi":"Chính nhờ mấy thế hệ nối tiếp nhau, vùng sa mạc này mới trở thành ốc đảo xanh."}],"related":[{"hanzi":"世世代代","pinyin":"shìshìdàidài","vi":"đời đời kiếp kiếp"},{"hanzi":"一代人","pinyin":"yídàirén","vi":"một thế hệ"},{"hanzi":"祖祖辈辈","pinyin":"zǔzǔbèibèi","vi":"bao đời tổ tiên"}],"traditional":"幾代人"},{"id":"紧缺","hanzi":"紧缺","pinyin":"jǐnquē","meaning_vi":"khan hiếm, thiếu hụt trầm trọng","explanation":"紧 (khẩn cấp/chặt chẽ) + 缺 (thiếu hụt/khiếm khuyết).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"药品十分紧缺。","pinyin":"Yàopǐn shífēn jǐnquē.","vi":"Thuốc men vô cùng khan hiếm."},{"type":"simple","zh":"这家医院的儿科医生一直处于紧缺状态。","pinyin":"Zhè jiā yīyuàn de érkē yīshēng yìzhí chǔyú jǐnquē zhuàngtài.","vi":"Bác sĩ nhi khoa của bệnh viện này luôn trong tình trạng thiếu hụt."},{"type":"compound","zh":"因为芯片紧缺，所以很多汽车厂被迫停产。","pinyin":"Yīnwèi xīnpiàn jǐnquē, suǒyǐ hěn duō qìchēchǎng bèipò tíngchǎn.","vi":"Vì chip khan hiếm, nên nhiều nhà máy ô tô buộc phải ngừng sản xuất."}],"related":[{"hanzi":"短缺","pinyin":"duǎnquē","vi":"thiếu hụt"},{"hanzi":"缺乏","pinyin":"quēfá","vi":"thiếu"},{"hanzi":"充足","pinyin":"chōngzú","vi":"đầy đủ"}],"traditional":"緊缺"},{"id":"尽情","hanzi":"尽情","pinyin":"jìnqíng","meaning_vi":"thỏa thích, hết mình","explanation":"尽 (hết sức/tận cùng) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["pho-tu"],"image":"🥳","examples":[{"type":"basic","zh":"孩子们尽情玩耍。","pinyin":"Háizimen jìnqíng wánshuǎ.","vi":"Bọn trẻ vui chơi thỏa thích."},{"type":"simple","zh":"毕业晚会上同学们尽情地唱歌跳舞。","pinyin":"Bìyè wǎnhuì shang tóngxuémen jìnqíng de chànggē tiàowǔ.","vi":"Trong đêm tiệc tốt nghiệp, các bạn học hát hò nhảy múa hết mình."},{"type":"compound","zh":"既然考试已经结束了，大家就尽情放松几天吧。","pinyin":"Jìrán kǎoshì yǐjīng jiéshù le, dàjiā jiù jìnqíng fàngsōng jǐtiān ba.","vi":"Kỳ thi đã kết thúc rồi, mọi người hãy thư giãn thỏa thích vài ngày đi."}],"related":[{"hanzi":"尽兴","pinyin":"jìnxìng","vi":"thỏa thích"},{"hanzi":"痛快","pinyin":"tòngkuài","vi":"sảng khoái"},{"hanzi":"尽情享受","pinyin":"jìnqíngxiǎngshòu","vi":"tận hưởng thỏa thích"}],"traditional":"盡情"},{"id":"紧身","hanzi":"紧身","pinyin":"jǐnshēn","meaning_vi":"bó sát (quần áo)","explanation":"紧 (khẩn cấp/chặt chẽ) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["tinh-tu","trang-phuc"],"image":"👗","examples":[{"type":"basic","zh":"她穿了条紧身裤。","pinyin":"Tā chuānle tiáo jǐnshēn kù.","vi":"Cô ấy mặc một chiếc quần bó sát."},{"type":"simple","zh":"健身教练穿着一件黑色紧身运动衣。","pinyin":"Jiànshēn jiàoliàn chuānzhe yí jiàn hēisè jǐnshēn yùndòng yī.","vi":"Huấn luyện viên thể hình mặc một chiếc áo thể thao bó sát màu đen."},{"type":"compound","zh":"紧身衣虽然显身材，但是穿久了会觉得不舒服。","pinyin":"Jǐnshēnyī suīrán xiǎn shēncái, dànshì chuān jiǔle huì juéde bù shūfu.","vi":"Áo bó sát tuy tôn dáng, nhưng mặc lâu sẽ thấy khó chịu."}],"related":[{"hanzi":"紧身衣","pinyin":"jǐnshēnyī","vi":"áo bó"},{"hanzi":"宽松","pinyin":"kuānsōng","vi":"rộng rãi"},{"hanzi":"服装","pinyin":"fúzhuāng","vi":"trang phục"}],"traditional":"緊身"},{"id":"谨言慎行","hanzi":"谨言慎行","pinyin":"jǐnyán-shènxíng","meaning_vi":"cẩn trọng trong lời nói và hành động","explanation":"谨 (thận trọng) + 言 (ngôn luận/lời nói) + 慎 (thận trọng) + 行 (được).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧐","examples":[{"type":"basic","zh":"在外要谨言慎行。","pinyin":"Zài wài yào jǐnyánshènxíng.","vi":"Ở bên ngoài phải cẩn trọng lời nói và việc làm."},{"type":"simple","zh":"新官上任的他在会上处处谨言慎行。","pinyin":"Xīn guān shàngrèn de tā zài huì shang chùchù jǐnyánshènxíng.","vi":"Mới nhậm chức, ông ấy luôn thận trọng từng lời nói, hành động trong cuộc họp."},{"type":"compound","zh":"因为身份特殊，所以他在公开场合一向谨言慎行。","pinyin":"Yīnwèi shēnfèn tèshū, suǒyǐ tā zài gōngkāi chǎnghé yīxiàng jǐnyánshènxíng.","vi":"Vì thân phận đặc biệt, nên ở nơi công cộng ông ấy luôn cẩn trọng trong lời nói và hành động."}],"related":[{"hanzi":"谨慎","pinyin":"jǐnshèn","vi":"thận trọng"},{"hanzi":"小心翼翼","pinyin":"xiǎoxīnyìyì","vi":"cẩn thận từng li"},{"hanzi":"口无遮拦","pinyin":"kǒuwúzhēlán","vi":"ăn nói bừa bãi"}],"traditional":"謹言慎行"},{"id":"尽职","hanzi":"尽职","pinyin":"jìnzhí","meaning_vi":"tận tụy làm tròn chức trách","explanation":"尽 (hết sức/tận cùng) + 职 (chức vụ/nghề nghiệp).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他工作很尽职。","pinyin":"Tā gōngzuò hěn jìnzhí.","vi":"Anh ấy làm việc rất tận tụy."},{"type":"simple","zh":"这位尽职的保安每晚都要巡逻三遍。","pinyin":"Zhè wèi jìnzhí de bǎo'ān měi wǎn dōu yào xúnluó sān biàn.","vi":"Người bảo vệ tận tụy này mỗi đêm đều đi tuần ba lượt."},{"type":"compound","zh":"只要每个人都尽职尽责，项目就能按时完成。","pinyin":"Zhǐyào měigèrén dōu jìnzhí jìnzé, xiàngmù jiù néng ànshí wánchéng.","vi":"Chỉ cần mỗi người đều làm tròn chức trách, dự án sẽ hoàn thành đúng hạn."}],"related":[{"hanzi":"尽职尽责","pinyin":"jìnzhíjìnzé","vi":"hết lòng làm tròn trách nhiệm"},{"hanzi":"敬业","pinyin":"jìngyè","vi":"tận tụy"},{"hanzi":"失职","pinyin":"shīzhí","vi":"thất trách"}],"traditional":"盡職"},{"id":"井底之蛙","hanzi":"井底之蛙","pinyin":"jǐngdǐ-zhīwā","meaning_vi":"ếch ngồi đáy giếng (tầm nhìn hạn hẹp)","explanation":"井底之蛙: con ếch (蛙) ở đáy giếng (井底) (truyện trong Trang Tử) → ví người hiểu biết hạn hẹp mà tự cho là giỏi; tương đương \"ếch ngồi đáy giếng\".","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐸","examples":[{"type":"basic","zh":"别做井底之蛙。","pinyin":"Bié zuò jǐngdǐzhīwā.","vi":"Đừng làm ếch ngồi đáy giếng."},{"type":"simple","zh":"出国留学后他才发现自己曾是井底之蛙。","pinyin":"Chūguó liúxué hòu tā cái fāxiàn zìjǐ céng shì jǐngdǐzhīwā.","vi":"Sau khi đi du học, anh ấy mới nhận ra mình từng là ếch ngồi đáy giếng."},{"type":"compound","zh":"如果从不走出小镇，你就可能变成井底之蛙。","pinyin":"Rúguǒ cóng bù zǒuchū xiǎozhèn, nǐ jiù kěnéng biànchéng jǐngdǐzhīwā.","vi":"Nếu chưa bao giờ bước ra khỏi thị trấn nhỏ, bạn có thể trở thành ếch ngồi đáy giếng."}],"related":[{"hanzi":"坐井观天","pinyin":"zuòjǐngguāntiān","vi":"ếch ngồi đáy giếng"},{"hanzi":"目光短浅","pinyin":"mùguāngduǎnqiǎn","vi":"tầm nhìn hạn hẹp"},{"hanzi":"见多识广","pinyin":"jiànduōshíguǎng","vi":"hiểu biết rộng"}]},{"id":"景仰","hanzi":"景仰","pinyin":"jǐngyǎng","meaning_vi":"kính ngưỡng, ngưỡng mộ","explanation":"景 (cảnh tượng/triển vọng) + 仰 (ngưỡng mộ/ngước nhìn).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"人们景仰这位英雄。","pinyin":"Rénmen jǐngyǎng zhè wèi yīngxióng.","vi":"Mọi người kính ngưỡng vị anh hùng này."},{"type":"simple","zh":"他的高尚品格令后人无比景仰。","pinyin":"Tā de gāoshàng pǐngé lìng hòurén wúbǐ jǐngyǎng.","vi":"Phẩm cách cao thượng của ông khiến hậu thế vô cùng ngưỡng mộ."},{"type":"compound","zh":"虽然这位科学家已去世多年，但是人们依然景仰他。","pinyin":"Suīrán zhè wèi kēxuéjiā yǐ qùshì duōnián, dànshì rénmen yīrán jǐngyǎng tā.","vi":"Tuy nhà khoa học này đã qua đời nhiều năm, nhưng mọi người vẫn kính ngưỡng ông."}],"related":[{"hanzi":"敬仰","pinyin":"jìngyǎng","vi":"kính ngưỡng"},{"hanzi":"仰慕","pinyin":"yǎngmù","vi":"ngưỡng mộ"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"}]},{"id":"警钟","hanzi":"警钟","pinyin":"jǐngzhōng","meaning_vi":"hồi chuông cảnh tỉnh","explanation":"警 (cảnh giác/cảnh báo) + 钟 (chuông/yêu thích).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🔔","examples":[{"type":"basic","zh":"这件事敲响了警钟。","pinyin":"Zhè jiàn shì qiāoxiǎngle jǐngzhōng.","vi":"Sự việc này đã gióng lên hồi chuông cảnh tỉnh."},{"type":"simple","zh":"这场火灾给所有商场敲响了消防安全的警钟。","pinyin":"Zhè chǎng huǒzāi gěi suǒyǒu shāngchǎng qiāoxiǎngle xiāofáng ānquán de jǐngzhōng.","vi":"Vụ hỏa hoạn này đã gióng hồi chuông cảnh tỉnh về an toàn phòng cháy cho mọi trung tâm thương mại."},{"type":"compound","zh":"如果对体检报告视而不见，健康警钟就白敲了。","pinyin":"Rúguǒ duì tǐjiǎnbàogào shì'érbújiàn, jiànkāng jǐngzhōng jiù bái qiāo le.","vi":"Nếu làm ngơ trước kết quả khám sức khỏe, hồi chuông cảnh báo về sức khỏe coi như vô ích."}],"related":[{"hanzi":"警告","pinyin":"jǐnggào","vi":"cảnh báo"},{"hanzi":"敲警钟","pinyin":"qiāojǐngzhōng","vi":"gióng hồi chuông cảnh tỉnh"},{"hanzi":"警惕","pinyin":"jǐngtì","vi":"cảnh giác"}],"traditional":"警鐘"},{"id":"咀嚼","hanzi":"咀嚼","pinyin":"jǔjué","meaning_vi":"nhai kỹ, nghiền ngẫm","explanation":"咀 (nhai/nghiền ngẫm) + 嚼 (nhai/suy ngẫm).","hsk_level":"7-9","tags":["dong-tu","an-uong"],"image":"🍽️","examples":[{"type":"basic","zh":"吃饭要细细咀嚼。","pinyin":"Chīfàn yào xìxì jǔjué.","vi":"Ăn cơm phải nhai kỹ."},{"type":"simple","zh":"老人坐在窗前反复咀嚼着这封信里的每一句话。","pinyin":"Lǎorén zuò zài chuāng qián fǎnfù jǔjuézhe zhè fēng xìn lǐ de měi yíjùhuà.","vi":"Ông lão ngồi bên cửa sổ nghiền ngẫm đi nghiền ngẫm lại từng câu trong bức thư."},{"type":"compound","zh":"因为没有充分咀嚼，所以他吃完饭总是胃疼。","pinyin":"Yīnwèi méiyǒu chōngfèn jǔjué, suǒyǐ tā chīwán fàn zǒngshì wèiténg.","vi":"Vì không nhai kỹ, nên ăn xong anh ấy thường bị đau dạ dày."}],"related":[{"hanzi":"嚼","pinyin":"jiáo","vi":"nhai"},{"hanzi":"消化","pinyin":"xiāohuà","vi":"tiêu hóa"},{"hanzi":"回味","pinyin":"huíwèi","vi":"nghiền ngẫm lại"}]},{"id":"举世瞩目","hanzi":"举世瞩目","pinyin":"jǔshì-zhǔmù","meaning_vi":"cả thế giới chú mục quan tâm","explanation":"举 (cử chỉ/nêu ra) + 世 (thế giới/thế hệ) + 瞩 (chú mục/nhìn xa) + 目 (mục tiêu/ánh mắt).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"这是举世瞩目的盛会。","pinyin":"Zhè shì jǔshìzhǔmù de shènghuì.","vi":"Đây là sự kiện trọng đại được cả thế giới chú ý."},{"type":"simple","zh":"嫦娥五号带回月壤是一项举世瞩目的成就。","pinyin":"Cháng'é wǔhào dàihuí yuèrǎng shì yí xiàng jǔshìzhǔmù de chéngjiù.","vi":"Việc tàu Hằng Nga 5 mang đất Mặt Trăng về là một thành tựu được cả thế giới chú mục."},{"type":"compound","zh":"虽然这场比赛举世瞩目，但是他上场时一点也不紧张。","pinyin":"Suīrán zhè chǎng bǐsài jǔshìzhǔmù, dànshì tā shàngchǎng shí yìdiǎn yě bù jǐnzhāng.","vi":"Tuy trận đấu này được cả thế giới dõi theo, nhưng khi ra sân anh ấy không hề căng thẳng."}],"related":[{"hanzi":"瞩目","pinyin":"zhǔmù","vi":"chú ý"},{"hanzi":"举世闻名","pinyin":"jǔshìwénmíng","vi":"nổi tiếng thế giới"},{"hanzi":"引人注目","pinyin":"yǐnrénzhùmù","vi":"thu hút sự chú ý"}],"traditional":"舉世矚目"},{"id":"跨度","hanzi":"跨度","pinyin":"kuàdù","meaning_vi":"nhịp cầu, khoảng cách thời gian/không gian","explanation":"跨 (bước qua) + 度 (度).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌉","examples":[{"type":"basic","zh":"这座桥跨度很大。","pinyin":"Zhè zuò qiáo kuàdù hěn dà.","vi":"Cây cầu này có nhịp rất lớn."},{"type":"simple","zh":"这部小说讲述的故事时间跨度长达一百年。","pinyin":"Zhè bù xiǎoshuō jiǎngshù de gùshi shíjiān kuàdù chángdá yī bǎinián.","vi":"Câu chuyện trong cuốn tiểu thuyết này trải dài suốt một trăm năm."},{"type":"compound","zh":"因为大桥跨度太大，所以工程师采用了斜拉索结构。","pinyin":"Yīnwèi Dàqiáo kuàdù tài dà, suǒyǐ gōngchéngshī cǎiyòngle xié lā suǒ jiégòu.","vi":"Vì nhịp cầu quá lớn, nên các kỹ sư đã dùng kết cấu dây văng."}],"related":[{"hanzi":"跨越","pinyin":"kuàyuè","vi":"vượt qua"},{"hanzi":"距离","pinyin":"jùlí","vi":"khoảng cách"},{"hanzi":"时间跨度","pinyin":"shíjiānkuàdù","vi":"khoảng thời gian"}]},{"id":"跨界","hanzi":"跨界","pinyin":"kuàjiè","meaning_vi":"giao thoa đa lĩnh vực (crossover)","explanation":"跨 (bước qua) + 界 (ranh giới/giới hạn).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔀","examples":[{"type":"basic","zh":"这位歌手跨界演戏。","pinyin":"Zhè wèi gēshǒu kuàjiè yǎnxì.","vi":"Ca sĩ này lấn sân sang đóng phim."},{"type":"simple","zh":"这家老字号茶馆和潮牌跨界推出了联名款。","pinyin":"Zhè jiālǎo zìhao cháguǎn hé cháo pái kuàjiè tuīchūle liánmíng kuǎn.","vi":"Quán trà lâu đời này đã bắt tay với một thương hiệu thời trang trẻ ra mắt sản phẩm hợp tác."},{"type":"compound","zh":"虽然他是跨界做导演，但是第一部电影就获了奖。","pinyin":"Suīrán tā shì kuàjiè zuò dǎoyǎn, dànshì dìyī bù diànyǐng jiù huòle jiǎng.","vi":"Tuy anh ấy lấn sân sang làm đạo diễn, nhưng ngay bộ phim đầu tiên đã đoạt giải."}],"related":[{"hanzi":"跨行业","pinyin":"kuàhángyè","vi":"liên ngành"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"},{"hanzi":"跨界合作","pinyin":"kuàjièhézuò","vi":"hợp tác liên ngành"}]},{"id":"跨境","hanzi":"跨境","pinyin":"kuàjìng","meaning_vi":"xuyên biên giới","explanation":"跨 (bước qua) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["tinh-tu","du-lich"],"image":"🌍","examples":[{"type":"basic","zh":"这是跨境铁路。","pinyin":"Zhè shì kuàjìng tiělù.","vi":"Đây là tuyến đường sắt xuyên biên giới."},{"type":"simple","zh":"这条跨境公路把两个国家的边境小镇连了起来。","pinyin":"Zhè tiáo kuàjìng gōnglù bǎ liǎng gè guójiā de biānjìng xiǎozhèn liánle qǐlái.","vi":"Con đường xuyên biên giới này đã nối liền các thị trấn biên giới của hai nước."},{"type":"compound","zh":"如果你经常跨境出差，就最好办一张多币种卡。","pinyin":"Rúguǒ nǐ jīngcháng kuàjìng chūchāi, jiù zuìhǎo bàn yì zhāng duō bìzhǒng kǎ.","vi":"Nếu bạn thường xuyên công tác xuyên biên giới, tốt nhất nên làm một thẻ đa tiền tệ."}],"related":[{"hanzi":"跨境电商","pinyin":"kuàjìngdiànshāng","vi":"TMĐT xuyên biên giới"},{"hanzi":"边境","pinyin":"biānjìng","vi":"biên giới"},{"hanzi":"出境","pinyin":"chūjìng","vi":"xuất cảnh"}]},{"id":"跨境电商","hanzi":"跨境电商","pinyin":"kuàjìngdiànshāng","meaning_vi":"thương mại điện tử xuyên biên giới","explanation":"跨境 (vượt biên giới) + 电商.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","cong-viec"],"image":"✈️","examples":[{"type":"basic","zh":"她做跨境电商。","pinyin":"Tā zuò kuàjìngdiànshāng.","vi":"Cô ấy kinh doanh thương mại điện tử xuyên biên giới."},{"type":"simple","zh":"他通过跨境电商把家乡的茶叶卖到了欧洲。","pinyin":"Tā tōngguò kuàjìngdiànshāng bǎ jiāxiāng de cháyè mài dàole Ōuzhōu.","vi":"Anh ấy bán trà quê nhà sang châu Âu qua thương mại điện tử xuyên biên giới."},{"type":"compound","zh":"跨境电商不但降低了成本，而且让小企业也能出海。","pinyin":"Kuàjìngdiànshāng búdàn jiàngdīle chéngběn, érqiě ràng xiǎoqǐyè yě néng chūhǎi.","vi":"Thương mại điện tử xuyên biên giới không chỉ giảm chi phí mà còn giúp doanh nghiệp nhỏ cũng vươn ra thế giới."}],"related":[{"hanzi":"电子商务","pinyin":"diànzǐshāngwù","vi":"thương mại điện tử"},{"hanzi":"网购","pinyin":"wǎnggòu","vi":"mua sắm trực tuyến"},{"hanzi":"跨境","pinyin":"kuàjìng","vi":"xuyên biên giới"}],"traditional":"跨境電商"},{"id":"跨文化交际","hanzi":"跨文化交际","pinyin":"kuàwénhuà jiāojì","meaning_vi":"giao tiếp liên văn hóa","explanation":"跨 (bước qua) + 文 (văn hóa/văn minh) + 化 (化) + 交 (giao) + 际 (quốc tế/ranh giới).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giao-tiep"],"image":"🌍","examples":[{"type":"basic","zh":"我选修跨文化交际。","pinyin":"Wǒ xuǎnxiū kuàwénhuàjiāojì.","vi":"Tôi chọn học môn giao tiếp liên văn hóa."},{"type":"simple","zh":"这门课专门讨论跨文化交际中的误解问题。","pinyin":"Zhè mén kè zhuānmén tǎolùn kuàwénhuàjiāojì zhōng de wùjiě wèntí.","vi":"Môn học này chuyên thảo luận về những hiểu lầm trong giao tiếp liên văn hóa."},{"type":"compound","zh":"如果不了解对方的习俗，跨文化交际就容易出问题。","pinyin":"Rúguǒ bù liǎojiě duìfāng de xísú, kuàwénhuàjiāojì jiù róngyì chūwèntí.","vi":"Nếu không hiểu phong tục của đối phương, giao tiếp liên văn hóa sẽ dễ gặp trục trặc."}],"related":[{"hanzi":"跨文化","pinyin":"kuàwénhuà","vi":"liên văn hóa"},{"hanzi":"交际","pinyin":"jiāojì","vi":"giao tiếp"},{"hanzi":"文化差异","pinyin":"wénhuàchāyì","vi":"khác biệt văn hóa"}],"traditional":"跨文化交際"},{"id":"快节奏","hanzi":"快节奏","pinyin":"kuàijiézòu","meaning_vi":"nhịp sống nhanh","explanation":"快 (khoái – nhanh) + 节奏 (tiết tấu – nhịp điệu) → nhịp điệu nhanh, chỉ nhịp sống, làm việc gấp gáp. VD: 快节奏的都市生活.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"⚡","examples":[{"type":"basic","zh":"他厌倦了快节奏。","pinyin":"Tā yànjuànle kuàijiézòu.","vi":"Anh ấy đã chán ngấy nhịp sống hối hả."},{"type":"simple","zh":"在快节奏的大城市里，很多人连早饭都顾不上吃。","pinyin":"Zài kuàijiézòu de Dàchéng shìlǐ, hěn duō rén lián zǎofàn dōu gùbúshàng chī.","vi":"Ở thành phố lớn nhịp sống nhanh, nhiều người đến bữa sáng cũng không kịp ăn."},{"type":"compound","zh":"与其在快节奏中焦虑，不如回老家慢慢生活。","pinyin":"Yǔqí zài kuàijiézòu zhōng jiāolǜ, bùrú huílǎojiā mànmàn shēnghuó.","vi":"Thay vì lo âu giữa nhịp sống hối hả, chi bằng về quê sống chậm lại."}],"related":[{"hanzi":"节奏","pinyin":"jiézòu","vi":"nhịp điệu"},{"hanzi":"慢生活","pinyin":"mànshēnghuó","vi":"lối sống chậm"},{"hanzi":"生活压力","pinyin":"shēnghuóyālì","vi":"áp lực cuộc sống"}],"traditional":"快節奏"},{"id":"矿产","hanzi":"矿产","pinyin":"kuàngchǎn","meaning_vi":"khoáng sản","explanation":"矿 (khoáng sản/mỏ) + 产 (sản xuất/tài sản).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛏️","examples":[{"type":"basic","zh":"这里矿产丰富。","pinyin":"Zhèlǐ kuàngchǎn fēngfù.","vi":"Nơi đây giàu khoáng sản."},{"type":"simple","zh":"西部山区蕴藏着大量稀有矿产。","pinyin":"Xībù shānqū yùncángzhe dàliàng xīyǒu kuàngchǎn.","vi":"Vùng núi phía Tây chứa đựng trữ lượng lớn khoáng sản quý hiếm."},{"type":"compound","zh":"如果过度开采矿产，当地的生态就会遭到破坏。","pinyin":"Rúguǒ guòdù kāicǎi kuàngchǎn, dāngdì de shēngtài jiù huì zāodào pòhuài.","vi":"Nếu khai thác khoáng sản quá mức, sinh thái địa phương sẽ bị phá hoại."}],"related":[{"hanzi":"矿产资源","pinyin":"kuàngchǎnzīyuán","vi":"tài nguyên khoáng sản"},{"hanzi":"矿山","pinyin":"kuàngshān","vi":"mỏ"},{"hanzi":"煤炭","pinyin":"méitàn","vi":"than đá"}],"traditional":"礦產"},{"id":"框框","hanzi":"框框","pinyin":"kuàngkuang","meaning_vi":"khuôn sáo, định kiến gò bó","explanation":"框 (khung sườn) + 框 (khung sườn).","hsk_level":"7-9","tags":["danh-tu"],"image":"🖼️","examples":[{"type":"basic","zh":"要打破旧框框。","pinyin":"Yào dǎ pòjiù kuàngkuang.","vi":"Phải phá bỏ những khuôn sáo cũ."},{"type":"simple","zh":"这位年轻导演的作品完全不受传统框框的束缚。","pinyin":"Zhè wèi niánqīng dǎoyǎn de zuòpǐn wánquán bú shòu chuántǒng kuàngkuang de shùfù.","vi":"Tác phẩm của vị đạo diễn trẻ này hoàn toàn không bị gò bó bởi khuôn khổ truyền thống."},{"type":"compound","zh":"只要跳出固有的框框，问题就有新的解法。","pinyin":"Zhǐyào tiàochū gùyǒu de kuàngkuang, wèntí jiù yǒu xīn de jiěfǎ.","vi":"Chỉ cần thoát khỏi lối mòn tư duy cố hữu, vấn đề sẽ có cách giải mới."}],"related":[{"hanzi":"框架","pinyin":"kuàngjià","vi":"khung"},{"hanzi":"条条框框","pinyin":"tiáotiáokuàngkuàng","vi":"quy tắc gò bó"},{"hanzi":"束缚","pinyin":"shùfù","vi":"trói buộc"}]},{"id":"矿泉水","hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","meaning_vi":"nước khoáng","explanation":"矿 (khoáng sản/mỏ) + 泉 (suối nước) + 水 (nước).","hsk_level":"7-9","tags":["danh-tu","do-uong"],"image":"💧","examples":[{"type":"basic","zh":"给我一瓶矿泉水。","pinyin":"Gěi wǒ yì píng kuàngquánshuǐ.","vi":"Cho tôi một chai nước khoáng."},{"type":"simple","zh":"登山前他在背包里装了三瓶矿泉水。","pinyin":"Dēngshān qián tā zài bēibāo lǐ zhuāngle sān píng kuàngquánshuǐ.","vi":"Trước khi leo núi, anh ấy bỏ ba chai nước khoáng vào ba lô."},{"type":"compound","zh":"因为自来水停了，所以我们只好用矿泉水煮面。","pinyin":"Yīnwèi zìláishuǐ tíng le, suǒyǐ wǒmen zhǐhǎo yòng kuàngquánshuǐ zhǔ miàn.","vi":"Vì bị cắt nước máy, nên chúng tôi đành dùng nước khoáng để nấu mì."}],"related":[{"hanzi":"纯净水","pinyin":"chúnjìngshuǐ","vi":"nước tinh khiết"},{"hanzi":"饮料","pinyin":"yǐnliào","vi":"đồ uống"},{"hanzi":"泉水","pinyin":"quánshuǐ","vi":"nước suối"}],"traditional":"礦泉水"},{"id":"旷野","hanzi":"旷野","pinyin":"kuàngyě","meaning_vi":"cánh đồng hoang rộng lớn","explanation":"旷 (bỏ trống/rộng lớn) + 野 (hoang dã/tầm nhìn).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"旷野上寒风呼啸。","pinyin":"Kuàngyě shang hánfēng hūxiào.","vi":"Gió lạnh rít gào trên cánh đồng hoang."},{"type":"simple","zh":"一匹白马在辽阔的旷野上自由奔跑。","pinyin":"Yì pǐ bái mǎ zài liáokuò de kuàngyě shang zìyóu bēnpǎo.","vi":"Một con ngựa trắng tự do phi nước đại trên cánh đồng hoang bao la."},{"type":"compound","zh":"一走进无人的旷野，他就感到了自己的渺小。","pinyin":"Yì zǒujìn wúrén de kuàngyě, tā jiù gǎndàole zìjǐ de miǎoxiǎo.","vi":"Vừa bước vào cánh đồng hoang không bóng người, anh ấy liền cảm thấy mình thật nhỏ bé."}],"related":[{"hanzi":"原野","pinyin":"yuányě","vi":"đồng hoang"},{"hanzi":"荒野","pinyin":"huāngyě","vi":"vùng hoang dã"},{"hanzi":"草原","pinyin":"cǎoyuán","vi":"thảo nguyên"}],"traditional":"曠野"},{"id":"馈赠","hanzi":"馈赠","pinyin":"kuìzèng","meaning_vi":"biếu tặng; quà biếu, quà tặng","explanation":"馈 (phản hồi/biếu tặng) + 赠 (tặng/biếu).","hsk_level":"7-9","tags":["dong-tu","danh-tu"],"image":"🎁","examples":[{"type":"basic","zh":"这是朋友的馈赠。","pinyin":"Zhè shì péngyou de kuìzèng.","vi":"Đây là món quà bạn bè tặng."},{"type":"simple","zh":"他把亲手做的陶罐馈赠给了远道而来的客人。","pinyin":"Tā bǎ qīnshǒu zuò de táo guàn kuìzèng gěile yuǎn dào ér lái de kèrén.","vi":"Anh ấy biếu chiếc bình gốm tự tay làm cho vị khách từ phương xa đến."},{"type":"compound","zh":"虽然这份馈赠并不贵重，但是包含着满满的心意。","pinyin":"Suīrán zhè fèn kuìzèng bìngbú guìzhòng, dànshì bāohánzhe mǎnmǎn de xīnyì.","vi":"Tuy món quà này không đắt giá, nhưng chứa đựng cả tấm lòng."}],"related":[{"hanzi":"赠送","pinyin":"zèngsòng","vi":"tặng"},{"hanzi":"礼物","pinyin":"lǐwù","vi":"quà tặng"},{"hanzi":"礼品","pinyin":"lǐpǐn","vi":"lễ vật"}],"traditional":"饋贈"},{"id":"扩建","hanzi":"扩建","pinyin":"kuòjiàn","meaning_vi":"mở rộng xây dựng thêm","explanation":"扩 (mở rộng) + 建 (建).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"机场正在扩建。","pinyin":"Jīchǎng zhèngzài kuòjiàn.","vi":"Sân bay đang được mở rộng."},{"type":"simple","zh":"学校今年暑假扩建了食堂和图书馆。","pinyin":"Xuéxiào jīnnián shǔjià kuòjiànle shítáng hé túshūguǎn.","vi":"Kỳ nghỉ hè năm nay nhà trường đã mở rộng nhà ăn và thư viện."},{"type":"compound","zh":"因为病人越来越多，所以医院决定扩建门诊楼。","pinyin":"Yīnwèi bìngrén yuèláiyuè duō, suǒyǐ yīyuàn juédìng kuòjiàn ménzhěn lóu.","vi":"Vì bệnh nhân ngày càng đông, nên bệnh viện quyết định xây mở rộng khu khám bệnh."}],"related":[{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"新建","pinyin":"xīnjiàn","vi":"xây mới"},{"hanzi":"改建","pinyin":"gǎijiàn","vi":"cải tạo"}],"traditional":"擴建"},{"id":"扩容","hanzi":"扩容","pinyin":"kuòróng","meaning_vi":"mở rộng dung lượng / sức chứa","explanation":"扩 (mở rộng) + 容 (dung nạp/khoan dung).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"💾","examples":[{"type":"basic","zh":"服务器需要扩容。","pinyin":"Fúwùqì xūyào kuòróng.","vi":"Máy chủ cần được mở rộng dung lượng."},{"type":"simple","zh":"这座停车场扩容后可以多停两百辆车。","pinyin":"Zhè zuò tíngchēchǎng kuòróng hòu kěyǐ duō tíng liǎng bǎi liàng chē.","vi":"Bãi đỗ xe này sau khi mở rộng có thể chứa thêm hai trăm xe."},{"type":"compound","zh":"如果网盘不扩容，这些照片就存不下了。","pinyin":"Rúguǒ wǎngpán bú kuòróng, zhèxiē zhàopiàn jiù cún búxià le.","vi":"Nếu không nâng dung lượng ổ đĩa mạng, sẽ không lưu nổi những bức ảnh này."}],"related":[{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"容量","pinyin":"róngliàng","vi":"dung lượng"},{"hanzi":"扩建","pinyin":"kuòjiàn","vi":"mở rộng xây dựng"}],"traditional":"擴容"},{"id":"扩招","hanzi":"扩招","pinyin":"kuòzhāo","meaning_vi":"mở rộng chỉ tiêu tuyển sinh","explanation":"扩 (mở rộng) + 招 (chiêu mộ/thu hút).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"今年研究生扩招了。","pinyin":"Jīnnián yánjiūshēng kuòzhāo le.","vi":"Năm nay chỉ tiêu tuyển sinh cao học được mở rộng."},{"type":"simple","zh":"这所师范大学今年计划扩招五百名本科生。","pinyin":"Zhè suǒ shīfàn dàxué jīnnián jìhuà kuòzhāo wǔ bǎi míng běnkēshēng.","vi":"Năm nay trường đại học sư phạm này dự định tuyển thêm năm trăm sinh viên đại học."},{"type":"compound","zh":"虽然高校连年扩招，但是热门专业仍然很难考。","pinyin":"Suīrán gāoxiào liánnián kuòzhāo, dànshì rèmén zhuānyè réngrán hěn nán kǎo.","vi":"Tuy các trường đại học liên tục mở rộng tuyển sinh, nhưng các ngành hot vẫn rất khó đỗ."}],"related":[{"hanzi":"招生","pinyin":"zhāoshēng","vi":"tuyển sinh"},{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"录取","pinyin":"lùqǔ","vi":"trúng tuyển"}],"traditional":"擴招"},{"id":"宽带","hanzi":"宽带","pinyin":"kuāndài","meaning_vi":"băng thông rộng (Internet cáp quang)","explanation":"宽 (rộng) + 带 (dải tần).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"家里装了宽带。","pinyin":"Jiālǐ zhuāngle kuāndài.","vi":"Nhà đã lắp mạng băng thông rộng."},{"type":"simple","zh":"搬家后我第一件事就是打电话申请宽带。","pinyin":"Bānjiā hòu wǒ dìyī jiàn shì jiùshì dǎdiànhuà shēnqǐng kuāndài.","vi":"Sau khi chuyển nhà, việc đầu tiên tôi làm là gọi điện đăng ký mạng internet."},{"type":"compound","zh":"如果宽带速度太慢，开视频会议就会一直卡顿。","pinyin":"Rúguǒ kuāndài sùdù tài màn, kāi shìpínhuìyì jiù huì yìzhí kǎdùn.","vi":"Nếu tốc độ mạng quá chậm, họp trực tuyến sẽ bị giật lag liên tục."}],"related":[{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"},{"hanzi":"光纤","pinyin":"guāngxiān","vi":"cáp quang"},{"hanzi":"网速","pinyin":"wǎngsù","vi":"tốc độ mạng"}],"traditional":"寬帶"},{"id":"宽广","hanzi":"宽广","pinyin":"kuānguǎng","meaning_vi":"rộng lớn bao la","explanation":"宽 (khoan – rộng) + 广 (quảng – rộng lớn) → rộng lớn, bao la; dùng cho không gian, tầm nhìn, tấm lòng. VD: 宽广的胸怀.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"草原无比宽广。","pinyin":"Cǎoyuán wúbǐ kuānguǎng.","vi":"Thảo nguyên rộng lớn vô cùng."},{"type":"simple","zh":"这条宽广的大道两旁种满了梧桐树。","pinyin":"Zhè tiáo kuānguǎng de dàdào liǎngpáng zhòng mǎnle wútóng shù.","vi":"Hai bên đại lộ rộng lớn này trồng đầy cây ngô đồng."},{"type":"compound","zh":"只要心胸宽广，就不会为小事斤斤计较。","pinyin":"Zhǐyào xīnxiōng kuānguǎng, jiù bú huì wèi xiǎoshì jīnjīnjìjiào.","vi":"Chỉ cần lòng dạ rộng rãi, sẽ không so đo tính toán vì chuyện nhỏ."}],"related":[{"hanzi":"宽阔","pinyin":"kuānkuò","vi":"rộng rãi"},{"hanzi":"辽阔","pinyin":"liáokuò","vi":"bao la"},{"hanzi":"狭窄","pinyin":"xiázhǎi","vi":"chật hẹp"}],"traditional":"寬廣"},{"id":"宽厚","hanzi":"宽厚","pinyin":"kuānhòu","meaning_vi":"nhân hậu độ lượng","explanation":"宽 (khoan – rộng lượng) + 厚 (hậu – dày, đôn hậu) → rộng lượng, nhân hậu với người khác. VD: 为人宽厚.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🤗","examples":[{"type":"basic","zh":"他为人宽厚。","pinyin":"Tā wéirén kuānhòu.","vi":"Anh ấy là người nhân hậu độ lượng."},{"type":"simple","zh":"宽厚的老板没有追究那个新员工的失误。","pinyin":"Kuānhòu de lǎobǎn méiyǒu zhuījiū nà gè xīn yuángōng de shīwù.","vi":"Ông chủ độ lượng không truy cứu lỗi của nhân viên mới đó."},{"type":"compound","zh":"奶奶不但待人宽厚，而且总是乐于帮助邻居。","pinyin":"Nǎinai búdàn dàirén kuānhòu, érqiě zǒngshì lèyú bāngzhù línjū.","vi":"Bà nội không chỉ đối xử nhân hậu với mọi người mà còn luôn sẵn lòng giúp đỡ hàng xóm."}],"related":[{"hanzi":"宽容","pinyin":"kuānróng","vi":"khoan dung"},{"hanzi":"厚道","pinyin":"hòudao","vi":"tử tế"},{"hanzi":"刻薄","pinyin":"kèbó","vi":"cay nghiệt"}],"traditional":"寬厚"},{"id":"宽松","hanzi":"宽松","pinyin":"kuānsōng","meaning_vi":"rộng rãi (quần áo), nới lỏng (chính sách)","explanation":"宽 (rộng) + 松 (thư giãn/cây thông).","hsk_level":"7-9","tags":["tinh-tu","trang-phuc"],"image":"👕","examples":[{"type":"basic","zh":"这件衬衫很宽松。","pinyin":"Zhè jiàn chènshān hěn kuānsōng.","vi":"Chiếc áo sơ mi này rất rộng rãi."},{"type":"simple","zh":"央行出台了更加宽松的货币政策。","pinyin":"Yāngháng chūtáile gèngjiā kuānsōng de huòbìzhèngcè.","vi":"Ngân hàng trung ương đã ban hành chính sách tiền tệ nới lỏng hơn."},{"type":"compound","zh":"孕妇最好穿宽松的衣服，因为太紧会影响血液循环。","pinyin":"Yùnfù zuìhǎo chuān kuānsōng de yīfu, yīnwèi tài jǐn huì yǐngxiǎng xuèyè xúnhuán.","vi":"Phụ nữ mang thai nên mặc quần áo rộng rãi, vì quá chật sẽ ảnh hưởng đến tuần hoàn máu."}],"related":[{"hanzi":"宽大","pinyin":"kuāndà","vi":"rộng rãi"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"nới lỏng"},{"hanzi":"紧身","pinyin":"jǐnshēn","vi":"bó sát"}],"traditional":"寬鬆"},{"id":"宽慰","hanzi":"宽慰","pinyin":"kuānwèi","meaning_vi":"an ủi, yên lòng","explanation":"宽 (rộng) + 慰 (an ủi).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😌","examples":[{"type":"basic","zh":"我宽慰了她几句。","pinyin":"Wǒ kuānwèile tā jǐ jù.","vi":"Tôi đã an ủi cô ấy vài câu."},{"type":"simple","zh":"听到孩子平安的消息，母亲心里宽慰了许多。","pinyin":"Tīngdào háizi píng'ān de xiāoxi, mǔqīn xīnlǐ kuānwèile xǔduō.","vi":"Nghe tin con bình an, người mẹ yên lòng hơn nhiều."},{"type":"compound","zh":"虽然朋友们一再宽慰他，但是他还是很自责。","pinyin":"Suīrán péngyoumen yízài kuānwèi tā, dànshì tā háishì hěn zìzé.","vi":"Tuy bạn bè nhiều lần an ủi, nhưng anh ấy vẫn rất tự trách mình."}],"related":[{"hanzi":"安慰","pinyin":"ānwèi","vi":"an ủi"},{"hanzi":"欣慰","pinyin":"xīnwèi","vi":"mãn nguyện"},{"hanzi":"放心","pinyin":"fàngxīn","vi":"yên tâm"}],"traditional":"寬慰"},{"id":"亏本","hanzi":"亏本","pinyin":"kuīběn","meaning_vi":"lỗ vốn","explanation":"亏 (thua lỗ/thiệt thòi) + 本 (quyển).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"这笔生意亏本了。","pinyin":"Zhè bǐ shēngyi kuīběn le.","vi":"Vụ làm ăn này bị lỗ vốn."},{"type":"simple","zh":"他开的奶茶店第一年就亏本十几万元。","pinyin":"Tā kāi de nǎichá diàn dìyī nián jiù kuīběn shíjǐ wàn yuán.","vi":"Tiệm trà sữa anh ấy mở lỗ hơn trăm nghìn tệ ngay năm đầu."},{"type":"compound","zh":"即使亏本卖，这批过季的衣服也得清掉。","pinyin":"Jíshǐ kuīběn mài, zhè pīguò jì de yīfu yě děi qīng diào.","vi":"Dù có bán lỗ vốn, lô quần áo hết mùa này cũng phải thanh lý."}],"related":[{"hanzi":"亏损","pinyin":"kuīsǔn","vi":"thua lỗ"},{"hanzi":"赔钱","pinyin":"péiqián","vi":"lỗ tiền"},{"hanzi":"盈利","pinyin":"yínglì","vi":"có lãi"}],"traditional":"虧本"},{"id":"款项","hanzi":"款项","pinyin":"kuǎnxiàng","meaning_vi":"khoản tiền","explanation":"款 (tiền/kiểu dáng/tiếp đãi) + 项 (hạng mục/dự án).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"款项已经到账。","pinyin":"Kuǎnxiàng yǐjīng dàozhàng.","vi":"Khoản tiền đã về tài khoản."},{"type":"simple","zh":"请在月底前把这笔款项汇到公司账户上。","pinyin":"Qǐng zài yuèdǐ qián bǎ zhè bǐ kuǎnxiàng huì dào gōngsī zhànghù shang.","vi":"Vui lòng chuyển khoản tiền này vào tài khoản công ty trước cuối tháng."},{"type":"compound","zh":"一旦客户的款项到账，我们就马上发货。","pinyin":"Yídàn kèhù de kuǎnxiàng dàozhàng, wǒmen jiù mǎshàng fāhuò.","vi":"Một khi khoản tiền của khách hàng về tài khoản, chúng tôi sẽ giao hàng ngay."}],"related":[{"hanzi":"款","pinyin":"kuǎn","vi":"khoản tiền"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"},{"hanzi":"付款","pinyin":"fùkuǎn","vi":"thanh toán"}],"traditional":"款項"},{"id":"看点","hanzi":"看点","pinyin":"kàndiǎn","meaning_vi":"điểm hấp dẫn đáng xem","explanation":"看 (nhìn) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"👀","examples":[{"type":"basic","zh":"这场比赛看点很多。","pinyin":"Zhè chǎng bǐsài kàndiǎn hěn duō.","vi":"Trận đấu này có nhiều điểm đáng xem."},{"type":"simple","zh":"这部电影最大的看点是那场长达十分钟的追车戏。","pinyin":"Zhè bù diànyǐng zuì dà de kàndiǎn shì nà chǎng chángdá shí fēnzhōng de zhuī chē xì.","vi":"Điểm hấp dẫn nhất của bộ phim là cảnh rượt đuổi bằng xe dài tới mười phút."},{"type":"compound","zh":"如果节目没有新的看点，观众就会慢慢流失。","pinyin":"Rúguǒ jiémù méiyǒu xīn de kàndiǎn, guānzhòng jiù huì mànmàn liúshī.","vi":"Nếu chương trình không có điểm nhấn mới, khán giả sẽ dần rời bỏ."}],"related":[{"hanzi":"亮点","pinyin":"liàngdiǎn","vi":"điểm sáng"},{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"},{"hanzi":"卖点","pinyin":"màidiǎn","vi":"điểm bán hàng"}],"traditional":"看點"},{"id":"看好","hanzi":"看好","pinyin":"kànhǎo","meaning_vi":"đánh giá cao, tin tưởng triển vọng","explanation":"看 (nhìn) + 好 (tốt).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👍","examples":[{"type":"basic","zh":"我很看好他。","pinyin":"Wǒ hěn kànhǎo tā.","vi":"Tôi rất tin tưởng vào triển vọng của anh ấy."},{"type":"simple","zh":"不少投资者看好新能源汽车的发展前景。","pinyin":"Bùshǎo tóuzīzhě kànhǎo xīnnéngyuánqìchē de fāzhǎn qiánjǐng.","vi":"Không ít nhà đầu tư đánh giá cao triển vọng phát triển của xe năng lượng mới."},{"type":"compound","zh":"虽然没人看好这支球队，但是他们一路杀进了决赛。","pinyin":"Suīrán méi rén kànhǎo zhè zhī qiúduì, dànshì tāmen yílù shājìnle juésài.","vi":"Tuy không ai đánh giá cao đội bóng này, nhưng họ đã vượt qua tất cả để vào chung kết."}],"related":[{"hanzi":"看重","pinyin":"kànzhòng","vi":"coi trọng"},{"hanzi":"前景","pinyin":"qiánjǐng","vi":"triển vọng"},{"hanzi":"不看好","pinyin":"búkànhǎo","vi":"không đánh giá cao"}]},{"id":"看齐","hanzi":"看齐","pinyin":"kànqí","meaning_vi":"noi gương học tập theo chuẩn mực","explanation":"看 (nhìn) + 齐 (đồng lòng/đầy đủ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚩","examples":[{"type":"basic","zh":"向榜样看齐。","pinyin":"Xiàng bǎngyàng kànqí.","vi":"Noi theo tấm gương."},{"type":"simple","zh":"新来的员工处处向那位金牌销售看齐。","pinyin":"Xīn lái de yuángōng chùchù xiàng nà wèi jīnpái xiāoshòu kànqí.","vi":"Nhân viên mới mọi mặt đều noi theo người bán hàng xuất sắc nhất ấy."},{"type":"compound","zh":"只要我们向先进单位看齐，服务水平就会提高。","pinyin":"Zhǐyào wǒmen xiàng xiānjìn dānwèi kànqí, fúwù shuǐpíng jiù huì tígāo.","vi":"Chỉ cần chúng ta học tập theo các đơn vị tiên tiến, chất lượng phục vụ sẽ được nâng lên."}],"related":[{"hanzi":"学习","pinyin":"xuéxí","vi":"học tập"},{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"效仿","pinyin":"xiàofǎng","vi":"noi theo"}],"traditional":"看齊"},{"id":"抗衡","hanzi":"抗衡","pinyin":"kànghéng","meaning_vi":"đối đầu ngang sức","explanation":"抗 (kháng cự/chống lại) + 衡 (cân nhắc/cân bằng).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"小店难以与大超市抗衡。","pinyin":"Xiǎodiàn nányǐ yǔ dà chāoshì kànghéng.","vi":"Cửa hàng nhỏ khó lòng cạnh tranh ngang sức với siêu thị lớn."},{"type":"simple","zh":"这家初创公司的产品已经足以和行业巨头抗衡。","pinyin":"Zhè jiā chūchuàng gōngsī de chǎnpǐn yǐjīng zúyǐ hé hángyè jùtóu kànghéng.","vi":"Sản phẩm của công ty khởi nghiệp này đã đủ sức đối đầu với các ông lớn trong ngành."},{"type":"compound","zh":"虽然对手实力强大，但是我们完全有能力与之抗衡。","pinyin":"Suīrán duìshǒu shílì qiángdà, dànshì wǒmen wánquán yǒunénglì yǔ zhī kànghéng.","vi":"Tuy đối thủ rất mạnh, nhưng chúng ta hoàn toàn đủ sức đương đầu với họ."}],"related":[{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"},{"hanzi":"匹敌","pinyin":"pǐdí","vi":"sánh ngang"},{"hanzi":"较量","pinyin":"jiàoliàng","vi":"so tài"}]},{"id":"抗击","hanzi":"抗击","pinyin":"kàngjī","meaning_vi":"chống trả, đẩy lùi (dịch bệnh/thiên tai)","explanation":"抗 (kháng cự/chống lại) + 击 (击).","hsk_level":"7-9","tags":["dong-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"全民抗击疫情。","pinyin":"Quánmín kàngjī yìqíng.","vi":"Toàn dân chống dịch."},{"type":"simple","zh":"沿海居民连夜加固堤坝抗击台风。","pinyin":"Yánhǎi jūmín liányè jiāgù dībà kàngjī táifēng.","vi":"Cư dân ven biển gia cố đê điều suốt đêm để chống bão."},{"type":"compound","zh":"因为医护人员冲在一线抗击病毒，所以疫情很快得到了控制。","pinyin":"Yīnwèi yīhù rényuán chōng zài yíxiàn kàngjī bìngdú, suǒyǐ yìqíng hěn kuài dédàole kòngzhì.","vi":"Vì đội ngũ y tế xông pha tuyến đầu chống virus, nên dịch bệnh nhanh chóng được kiểm soát."}],"related":[{"hanzi":"抵抗","pinyin":"dǐkàng","vi":"chống cự"},{"hanzi":"抗疫","pinyin":"kàngyì","vi":"chống dịch"},{"hanzi":"战胜","pinyin":"zhànshèng","vi":"chiến thắng"}],"traditional":"抗擊"},{"id":"抗生素","hanzi":"抗生素","pinyin":"kàngshēngsù","meaning_vi":"thuốc kháng sinh","explanation":"抗 (kháng cự/chống lại) + 生 (sinh tồn/sinh động) + 素 (tố chất/vốn dĩ).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"别乱用抗生素。","pinyin":"Bié luàn yòng kàngshēngsù.","vi":"Đừng dùng kháng sinh bừa bãi."},{"type":"simple","zh":"医生给发高烧的孩子开了三天的抗生素。","pinyin":"Yīshēng gěi fā gāoshāo de háizi kāile sān tiān de kàngshēngsù.","vi":"Bác sĩ kê ba ngày thuốc kháng sinh cho đứa trẻ bị sốt cao."},{"type":"compound","zh":"如果长期滥用抗生素，细菌就会产生耐药性。","pinyin":"Rúguǒ chángqī lànyòng kàngshēngsù, xìjūn jiù huì chǎnshēng nàiyàoxìng.","vi":"Nếu lạm dụng kháng sinh lâu dài, vi khuẩn sẽ sinh ra tính kháng thuốc."}],"related":[{"hanzi":"青霉素","pinyin":"qīngméisù","vi":"penicillin"},{"hanzi":"消炎药","pinyin":"xiāoyányào","vi":"thuốc kháng viêm"},{"hanzi":"细菌","pinyin":"xìjūn","vi":"vi khuẩn"}]},{"id":"抗压能力","hanzi":"抗压能力","pinyin":"kàngyānénglì","meaning_vi":"khả năng chịu áp lực","explanation":"抗 (kháng cự/chống lại) + 压 (áp lực/áp bức) + 能 (có thể (năng lực/điều kiện)) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","cong-viec","cam-xuc"],"image":"💪","examples":[{"type":"basic","zh":"她的抗压能力很强。","pinyin":"Tā de kàngyānénglì hěn qiáng.","vi":"Khả năng chịu áp lực của cô ấy rất tốt."},{"type":"simple","zh":"面试官特意问了几个问题来测试他的抗压能力。","pinyin":"Miànshìguān tèyì wènle jǐ gè wèntí lái cèshì tā de kàngyānénglì.","vi":"Người phỏng vấn cố ý hỏi vài câu để thử khả năng chịu áp lực của anh ấy."},{"type":"compound","zh":"如果抗压能力太差，就很难在急诊科坚持下去。","pinyin":"Rúguǒ kàngyānénglì tài chà, jiù hěn nán zài jízhěn kē jiānchí xiàqù.","vi":"Nếu khả năng chịu áp lực quá kém thì rất khó trụ lại ở khoa cấp cứu."}],"related":[{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"心理素质","pinyin":"xīnlǐsùzhì","vi":"tố chất tâm lý"},{"hanzi":"承受能力","pinyin":"chéngshòunénglì","vi":"khả năng chịu đựng"}],"traditional":"抗壓能力"},{"id":"靠山","hanzi":"靠山","pinyin":"kàoshān","meaning_vi":"chỗ dựa vững chắc","explanation":"靠 (dựa vào) + 山 (núi non).","hsk_level":"7-9","tags":["danh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"他背后有靠山。","pinyin":"Tā bèihòu yǒu kàoshān.","vi":"Đằng sau anh ta có chỗ dựa."},{"type":"simple","zh":"父母永远是我们最坚实的靠山。","pinyin":"Fùmǔ yǒngyuǎn shì wǒmen zuì jiānshí de kàoshān.","vi":"Cha mẹ mãi mãi là chỗ dựa vững chắc nhất của chúng ta."},{"type":"compound","zh":"即使没有任何靠山，她也靠自己闯出了一片天。","pinyin":"Jíshǐ méiyǒu rènhé kàoshān, tā yě kào zìjǐ chuǎng chūle yípiàn tiān.","vi":"Dù không có bất kỳ chỗ dựa nào, cô ấy vẫn tự mình gây dựng được sự nghiệp."}],"related":[{"hanzi":"后盾","pinyin":"hòudùn","vi":"hậu thuẫn"},{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa dẫm"},{"hanzi":"后台","pinyin":"hòutái","vi":"ô dù"}]},{"id":"刻板印象","hanzi":"刻板印象","pinyin":"kèbǎnyìnxiàng","meaning_vi":"định kiến khuôn mẫu (stereotype)","explanation":"刻 (khắc ghi/sâu sắc) + 板 (板) + 印 (ấn tượng/in ấn) + 象 (hiện tượng/tượng trưng).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","nhan-thuc"],"image":"🧱","examples":[{"type":"basic","zh":"这是一种刻板印象。","pinyin":"Zhè shì yì zhǒng kèbǎnyìnxiàng.","vi":"Đây là một định kiến khuôn mẫu."},{"type":"simple","zh":"这部电视剧打破了观众对程序员的刻板印象。","pinyin":"Zhè bù diànshìjù dǎpòle guānzhòng duì chéngxùyuán de kèbǎnyìnxiàng.","vi":"Bộ phim truyền hình này đã phá vỡ định kiến của khán giả về lập trình viên."},{"type":"compound","zh":"只要多和不同的人交往，刻板印象就会逐渐消失。","pinyin":"Zhǐyào duō hé bùtóng de rén jiāowǎng, kèbǎnyìnxiàng jiù huì zhújiàn xiāoshī.","vi":"Chỉ cần giao tiếp nhiều với những người khác nhau, định kiến khuôn mẫu sẽ dần biến mất."}],"related":[{"hanzi":"偏见","pinyin":"piānjiàn","vi":"thành kiến"},{"hanzi":"印象","pinyin":"yìnxiàng","vi":"ấn tượng"},{"hanzi":"成见","pinyin":"chéngjiàn","vi":"định kiến"}]},{"id":"客流","hanzi":"客流","pinyin":"kèliú","meaning_vi":"lượng khách qua lại","explanation":"客 (khách quan/khách hàng) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","du-lich","giao-thong"],"image":"👥","examples":[{"type":"basic","zh":"车站客流很大。","pinyin":"Chēzhàn kèliú hěn dà.","vi":"Lượng khách ở nhà ga rất lớn."},{"type":"simple","zh":"地铁公司在早高峰增开列车来疏导客流。","pinyin":"Dìtiě gōngsī zài zǎogāofēng zēng kāi lièchē lái shūdǎo kèliú.","vi":"Công ty tàu điện ngầm tăng chuyến vào giờ cao điểm sáng để phân luồng hành khách."},{"type":"compound","zh":"一到春运，火车站的客流就会成倍增加。","pinyin":"Yí dào chūnyùn, huǒchēzhàn de kèliú jiù huì chéngbèi zēngjiā.","vi":"Cứ đến mùa vận tải Tết, lượng khách ở ga tàu lại tăng gấp bội."}],"related":[{"hanzi":"客流量","pinyin":"kèliúliàng","vi":"lượng khách"},{"hanzi":"人流","pinyin":"rénliú","vi":"dòng người"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"giờ cao điểm"}]},{"id":"克隆","hanzi":"克隆","pinyin":"kèlóng","meaning_vi":"nhân bản vô tính","explanation":"克 (gam (đơn vị khối lượng)) + 隆 (隆).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🐑","examples":[{"type":"basic","zh":"科学家克隆了一只羊。","pinyin":"Kēxuéjiā kèlóngle yì zhī yáng.","vi":"Các nhà khoa học đã nhân bản vô tính một con cừu."},{"type":"simple","zh":"这家公司被指控克隆了竞争对手的网站。","pinyin":"Zhè jiā gōngsī bèi zhǐkòng kèlóngle jìngzhēng duìshǒu de wǎngzhàn.","vi":"Công ty này bị cáo buộc sao chép y nguyên trang web của đối thủ."},{"type":"compound","zh":"虽然克隆技术已经成熟，但是克隆人仍被严格禁止。","pinyin":"Suīrán kèlóng jìshù yǐjīng chéngshú, dànshì kèlóngrén réng bèi yángé jìnzhǐ.","vi":"Tuy công nghệ nhân bản vô tính đã hoàn thiện, nhưng việc nhân bản người vẫn bị nghiêm cấm."}],"related":[{"hanzi":"复制","pinyin":"fùzhì","vi":"sao chép"},{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"},{"hanzi":"克隆羊","pinyin":"kèlóngyáng","vi":"cừu nhân bản"}]},{"id":"课题组","hanzi":"课题组","pinyin":"kètízǔ","meaning_vi":"nhóm nghiên cứu đề tài","explanation":"课 (bài học) + 题 (đề tài/vấn đề) + 组 (tổ chức/tổ hợp).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"👥","examples":[{"type":"basic","zh":"他加入了课题组。","pinyin":"Tā jiārùle kètízǔ.","vi":"Anh ấy đã gia nhập nhóm nghiên cứu đề tài."},{"type":"simple","zh":"课题组在山区采集了上千份土壤样本。","pinyin":"Kètízǔ zài shānqū cǎijíle shàng qiān fèn tǔrǎng yàngběn.","vi":"Nhóm nghiên cứu đã thu thập hàng nghìn mẫu đất ở vùng núi."},{"type":"compound","zh":"因为经费不足，所以课题组不得不推迟了实验。","pinyin":"Yīnwèi jīngfèi bùzú, suǒyǐ kètízǔ bùdébù tuīchíle shíyàn.","vi":"Vì thiếu kinh phí, nên nhóm nghiên cứu buộc phải hoãn thí nghiệm."}],"related":[{"hanzi":"课题","pinyin":"kètí","vi":"đề tài"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"团队","pinyin":"tuánduì","vi":"đội nhóm"}],"traditional":"課題組"},{"id":"克星","hanzi":"克星","pinyin":"kèxīng","meaning_vi":"khắc tinh","explanation":"克 (gam (đơn vị khối lượng)) + 星 (ngôi sao).","hsk_level":"7-9","tags":["danh-tu"],"image":"⚔️","examples":[{"type":"basic","zh":"猫是老鼠的克星。","pinyin":"Māo shì lǎoshǔ de kèxīng.","vi":"Mèo là khắc tinh của chuột."},{"type":"simple","zh":"这位左手投手是对方强打者的克星。","pinyin":"Zhè wèi zuǒshǒu tóushǒu shì duìfāng qiángdǎ zhě de kèxīng.","vi":"Tay ném bóng thuận tay trái này là khắc tinh của các tay đánh mạnh bên đối phương."},{"type":"compound","zh":"每次一碰上这位老对手他就输，对方简直是他的克星。","pinyin":"Měi cì yí pèngshàng zhè wèi lǎo duìshǒu tā jiù shū, duìfāng jiǎnzhí shì tā de kèxīng.","vi":"Lần nào chạm trán đối thủ cũ này anh ấy cũng thua, người kia đúng là khắc tinh của anh ấy."}],"related":[{"hanzi":"对手","pinyin":"duìshǒu","vi":"đối thủ"},{"hanzi":"天敌","pinyin":"tiāndí","vi":"thiên địch"},{"hanzi":"救星","pinyin":"jiùxīng","vi":"cứu tinh"}],"traditional":"剋星"},{"id":"客运","hanzi":"客运","pinyin":"kèyùn","meaning_vi":"vận tải hành khách","explanation":"客 (khách quan/khách hàng) + 运 (vận dụng/vận hành).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"🚌","examples":[{"type":"basic","zh":"客运站人很多。","pinyin":"Kèyùnzhàn rén hěn duō.","vi":"Bến xe khách rất đông người."},{"type":"simple","zh":"这条高铁线路主要承担城际客运任务。","pinyin":"Zhè tiáo gāotiě xiànlù zhǔyào chéngdān chéng jì kèyùn rènwù.","vi":"Tuyến đường sắt cao tốc này chủ yếu đảm nhận vận tải hành khách liên tỉnh."},{"type":"compound","zh":"因为暴雪封路，所以长途客运全部暂停了。","pinyin":"Yīnwèi bàoxuě fēnglù, suǒyǐ chángtú kèyùn quánbù zàntíng le.","vi":"Vì bão tuyết làm phong tỏa đường, nên toàn bộ vận tải hành khách đường dài đã tạm ngừng."}],"related":[{"hanzi":"货运","pinyin":"huòyùn","vi":"vận tải hàng hóa"},{"hanzi":"旅客","pinyin":"lǚkè","vi":"hành khách"},{"hanzi":"客运站","pinyin":"kèyùnzhàn","vi":"bến xe khách"}],"traditional":"客運"},{"id":"扣人心弦","hanzi":"扣人心弦","pinyin":"kòurén-xīnxián","meaning_vi":"hồi hộp gay cấn chạm tới trái tim","explanation":"扣 (khấu trừ/chạm tới) + 人 (người) + 心 (tâm lý/tâm huyết) + 弦 (dây đàn).","hsk_level":"7-9","tags":["thanh-ngu","giai-tri"],"image":"💓","examples":[{"type":"basic","zh":"剧情扣人心弦。","pinyin":"Jùqíng kòurénxīnxián.","vi":"Tình tiết phim hồi hộp gay cấn."},{"type":"simple","zh":"决赛最后一分钟的点球扣人心弦。","pinyin":"Juésài zuìhòu yì fēnzhōng de diǎnqiú kòurénxīnxián.","vi":"Quả phạt đền ở phút cuối trận chung kết khiến người xem nghẹt thở."},{"type":"compound","zh":"这部小说情节扣人心弦，我一拿起来就放不下。","pinyin":"Zhè bù xiǎoshuō qíngjié kòurénxīnxián, wǒ yì ná qǐlái jiù fàngbúxià.","vi":"Tình tiết cuốn tiểu thuyết này lôi cuốn đến nghẹt thở, tôi vừa cầm lên là không đặt xuống được."}],"related":[{"hanzi":"动人心弦","pinyin":"dòngrénxīnxián","vi":"làm rung động lòng người"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"},{"hanzi":"精彩","pinyin":"jīngcǎi","vi":"đặc sắc"}],"traditional":"扣人心絃"},{"id":"库房","hanzi":"库房","pinyin":"kùfáng","meaning_vi":"nhà kho","explanation":"库 (kho chứa) + 房 (房).","hsk_level":"7-9","tags":["danh-tu","cong-viec","dia-diem"],"image":"🏭","examples":[{"type":"basic","zh":"货物放在库房里。","pinyin":"Huòwù fàng zài kùfáng lǐ.","vi":"Hàng hóa được để trong nhà kho."},{"type":"simple","zh":"管理员每周都会清点一次库房里的物资。","pinyin":"Guǎnlǐyuán měizhōu dōuhuì qīngdiǎn yí cì kùfáng lǐ de wùzī.","vi":"Người quản lý mỗi tuần đều kiểm kê vật tư trong kho một lần."},{"type":"compound","zh":"如果库房不通风，粮食就很容易发霉。","pinyin":"Rúguǒ kùfáng bù tōngfēng, liángshi jiù hěn róngyì fāméi.","vi":"Nếu nhà kho không thông gió, lương thực sẽ rất dễ bị mốc."}],"related":[{"hanzi":"仓库","pinyin":"cāngkù","vi":"kho hàng"},{"hanzi":"库存","pinyin":"kùcún","vi":"hàng tồn kho"},{"hanzi":"货物","pinyin":"huòwù","vi":"hàng hóa"}],"traditional":"庫房"},{"id":"困惑","hanzi":"困惑","pinyin":"kùnhuò","meaning_vi":"bối rối, thắc mắc khó hiểu","explanation":"困 (khốn – bị vây hãm, khó khăn) + 惑 (hoặc – nghi hoặc) → bối rối, băn khoăn không hiểu. VD: 感到困惑, 解答困惑.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🤔","examples":[{"type":"basic","zh":"他一脸困惑。","pinyin":"Tā yì liǎn kùnhuò.","vi":"Anh ấy mặt đầy bối rối."},{"type":"simple","zh":"这道题的答案让全班同学都感到困惑。","pinyin":"Zhè dào tí de dá'àn ràng quánbān tóngxué dōu gǎndào kùnhuò.","vi":"Đáp án của câu hỏi này khiến cả lớp đều thấy khó hiểu."},{"type":"compound","zh":"虽然读了三遍，但是我对结尾仍然很困惑。","pinyin":"Suīrán dúle sān biàn, dànshì wǒ duì jiéwěi réngrán hěn kùnhuò.","vi":"Tuy đã đọc ba lần, nhưng tôi vẫn rất băn khoăn về đoạn kết."}],"related":[{"hanzi":"迷惑","pinyin":"míhuò","vi":"mơ hồ"},{"hanzi":"疑惑","pinyin":"yíhuò","vi":"nghi hoặc"},{"hanzi":"不解","pinyin":"bùjiě","vi":"không hiểu"}]},{"id":"困境","hanzi":"困境","pinyin":"kùnjìng","meaning_vi":"nghịch cảnh, tình thế khó khăn","explanation":"困 (困) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["danh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"公司陷入困境。","pinyin":"Gōngsī xiànrù kùnjìng.","vi":"Công ty rơi vào khó khăn."},{"type":"simple","zh":"一笔政府贷款帮这家小工厂摆脱了困境。","pinyin":"Yì bǐ zhèngfǔ dàikuǎn bāng zhè jiā xiǎo gōngchǎng bǎituōle kùnjìng.","vi":"Một khoản vay của chính phủ đã giúp nhà máy nhỏ này thoát khỏi khó khăn."},{"type":"compound","zh":"只要大家齐心协力，就一定能走出困境。","pinyin":"Zhǐyào dàjiā qíxīnxiélì, jiù yídìng néng zǒuchū kùnjìng.","vi":"Chỉ cần mọi người đồng lòng hợp sức, nhất định sẽ vượt qua nghịch cảnh."}],"related":[{"hanzi":"绝境","pinyin":"juéjìng","vi":"tuyệt cảnh"},{"hanzi":"逆境","pinyin":"nìjìng","vi":"nghịch cảnh"},{"hanzi":"摆脱困境","pinyin":"bǎituōkùnjìng","vi":"thoát khỏi khó khăn"}]},{"id":"开端","hanzi":"开端","pinyin":"kāiduān","meaning_vi":"sự khởi đầu","explanation":"开 (mở) + 端 (bưng).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌅","examples":[{"type":"basic","zh":"这是好的开端。","pinyin":"Zhè shì hǎo de kāiduān.","vi":"Đây là một khởi đầu tốt."},{"type":"simple","zh":"这次握手成为两国关系改善的开端。","pinyin":"Zhè cì wòshǒu chéngwéi liǎngguó guānxì gǎishàn de kāiduān.","vi":"Cái bắt tay lần này trở thành khởi đầu cho sự cải thiện quan hệ hai nước."},{"type":"compound","zh":"虽然比赛开端不太顺利，但是我们后来扳回了比分。","pinyin":"Suīrán bǐsài kāiduān bú tài shùnlì, dànshì wǒmen hòulái bānhuíle bǐfēn.","vi":"Tuy khởi đầu trận đấu không mấy suôn sẻ, nhưng sau đó chúng tôi đã gỡ lại tỉ số."}],"related":[{"hanzi":"开始","pinyin":"kāishǐ","vi":"bắt đầu"},{"hanzi":"起点","pinyin":"qǐdiǎn","vi":"điểm xuất phát"},{"hanzi":"结局","pinyin":"jiéjú","vi":"kết cục"}],"traditional":"開端"},{"id":"开馆","hanzi":"开馆","pinyin":"kāiguǎn","meaning_vi":"mở cửa đón khách (bảo tàng/thư viện)","explanation":"开 (khai – mở) + 馆 (quán – nhà, viện) → khai trương hoặc mở cửa (bảo tàng, thư viện, triển lãm); trái nghĩa 闭馆.","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"博物馆九点开馆。","pinyin":"Bówùguǎn jiǔ diǎn kāiguǎn.","vi":"Bảo tàng mở cửa lúc chín giờ."},{"type":"simple","zh":"新建的市图书馆将在国庆节正式开馆。","pinyin":"Xīnjiàn de shì túshūguǎn jiāng zài Guóqìngjié zhèngshì kāiguǎn.","vi":"Thư viện thành phố mới xây sẽ chính thức mở cửa vào dịp Quốc khánh."},{"type":"compound","zh":"科技馆一开馆，门口就排起了长队。","pinyin":"Kējì guǎn yì kāiguǎn, ménkǒu jiù pái qǐle chángduì.","vi":"Bảo tàng khoa học vừa mở cửa, trước cổng đã xếp hàng dài."}],"related":[{"hanzi":"闭馆","pinyin":"bìguǎn","vi":"đóng cửa (bảo tàng)"},{"hanzi":"开放","pinyin":"kāifàng","vi":"mở cửa"},{"hanzi":"博物馆","pinyin":"bówùguǎn","vi":"bảo tàng"}],"traditional":"開館"},{"id":"开卷有益","hanzi":"开卷有益","pinyin":"kāijuàn-yǒuyì","meaning_vi":"mở sách ra đọc ắt có ích","explanation":"开 (mở) + 卷 (cuộn) + 有 (có) + 益 (lợi ích/bổ ích).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"开卷有益，多读书吧。","pinyin":"Kāijuànyǒuyì, duō dúshū ba.","vi":"Mở sách ra ắt có ích, hãy đọc nhiều sách nhé."},{"type":"simple","zh":"爷爷常用开卷有益这句话鼓励我多读书。","pinyin":"Yéye chángyòng kāijuànyǒuyì zhè jù huà gǔlì wǒ duō dúshū.","vi":"Ông nội thường dùng câu \"mở sách ắt có ích\" để khuyến khích tôi đọc nhiều sách."},{"type":"compound","zh":"即使是一本闲书，也能让人学到东西，真是开卷有益。","pinyin":"Jíshǐ shì yì běn xiánshū, yě néng ràng rén xuédào dōngxi, zhēn shì kāijuànyǒuyì.","vi":"Dù chỉ là một cuốn sách giải trí cũng giúp người ta học được điều gì đó, đúng là mở sách ắt có ích."}],"related":[{"hanzi":"读书","pinyin":"dúshū","vi":"đọc sách"},{"hanzi":"开卷","pinyin":"kāijuàn","vi":"mở sách"},{"hanzi":"书籍","pinyin":"shūjí","vi":"sách vở"}],"traditional":"開卷有益"},{"id":"开阔地","hanzi":"开阔地","pinyin":"kāikuòdì","meaning_vi":"vùng đất trống rộng rãi","explanation":"开 (mở) + 阔 (bao la/rộng lớn) + 地 (地).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"前面是一片开阔地。","pinyin":"Qiánmiàn shì yípiàn kāikuòdì.","vi":"Phía trước là một vùng đất trống rộng rãi."},{"type":"simple","zh":"救援直升机降落在村外的一块开阔地上。","pinyin":"Jiùyuán zhíshēngjī jiàngluò zài cūn wài de yíkuài kāikuò dìshang.","vi":"Trực thăng cứu hộ hạ cánh xuống một bãi đất trống ngoài làng."},{"type":"compound","zh":"一旦发生地震，大家就应迅速转移到开阔地。","pinyin":"Yídàn fāshēng dìzhèn, dàjiā jiù yīng xùnsù zhuǎnyí dào kāikuòdì.","vi":"Một khi xảy ra động đất, mọi người nên nhanh chóng di chuyển đến chỗ đất trống."}],"related":[{"hanzi":"开阔","pinyin":"kāikuò","vi":"rộng rãi"},{"hanzi":"空地","pinyin":"kòngdì","vi":"đất trống"},{"hanzi":"平原","pinyin":"píngyuán","vi":"đồng bằng"}],"traditional":"開闊地"},{"id":"开水壶","hanzi":"开水壶","pinyin":"kāishuǐhú","meaning_vi":"ấm đun nước sôi","explanation":"开 (mở) + 水 (nước) + 壶 (cái ấm).","hsk_level":"7-9","tags":["danh-tu","do-vat","nha-cua"],"image":"🫖","examples":[{"type":"basic","zh":"开水壶响了。","pinyin":"Kāishuǐhú xiǎng le.","vi":"Ấm đun nước reo rồi."},{"type":"simple","zh":"她拿起开水壶给客人泡了一杯绿茶。","pinyin":"Tā náqǐ kāishuǐhú gěi kèrén pàole yì bēi lǜchá.","vi":"Cô ấy cầm ấm nước sôi pha cho khách một tách trà xanh."},{"type":"compound","zh":"因为开水壶里结了很多水垢，所以妈妈用白醋把它煮了一遍。","pinyin":"Yīnwèi kāishuǐhú lǐ jiéle hěn duō shuǐgòu, suǒyǐ māma yòng báicù bǎ tā zhǔle yíbiàn.","vi":"Vì trong ấm đun nước đóng nhiều cặn, nên mẹ đã đun nó với giấm trắng một lượt."}],"related":[{"hanzi":"开水","pinyin":"kāishuǐ","vi":"nước sôi"},{"hanzi":"水壶","pinyin":"shuǐhú","vi":"ấm nước"},{"hanzi":"热水瓶","pinyin":"rèshuǐpíng","vi":"phích nước"}],"traditional":"開水壺"},{"id":"开天辟地","hanzi":"开天辟地","pinyin":"kāitiān-pìdì","meaning_vi":"khai thiên lập địa (sự kiện vĩ đại chưa từng có)","explanation":"开 (mở) + 天 (ngày) + 辟 (khai phá/bác bỏ) + 地 (地).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌍","examples":[{"type":"basic","zh":"这是开天辟地的大事。","pinyin":"Zhè shì kāitiānpìdì de dàshì.","vi":"Đây là sự kiện trọng đại chưa từng có."},{"type":"simple","zh":"盘古开天辟地的神话在中国家喻户晓。","pinyin":"Pángǔ kāitiānpìdì de shénhuà zài Zhōngguó jiāyùhùxiǎo.","vi":"Thần thoại Bàn Cổ khai thiên lập địa ở Trung Quốc ai ai cũng biết."},{"type":"compound","zh":"因为通公路在村里是开天辟地头一回，所以大家都放起了鞭炮。","pinyin":"Yīnwèi tōng gōnglù zài cūnlǐ shì kāitiānpìdì tóuyìhuí, suǒyǐ dàjiā dōu fàng qǐle biānpào.","vi":"Vì việc làng có đường ô tô là chuyện lần đầu tiên từ xưa đến nay, nên mọi người đều đốt pháo ăn mừng."}],"related":[{"hanzi":"盘古","pinyin":"Pángǔ","vi":"Bàn Cổ"},{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có trong lịch sử"},{"hanzi":"创举","pinyin":"chuàngjǔ","vi":"sáng kiến lớn"}],"traditional":"開天闢地"},{"id":"开拓创新","hanzi":"开拓创新","pinyin":"kāituòchuàngxīn","meaning_vi":"khai phá và đổi mới sáng tạo","explanation":"开 (mở) + 拓 (mở mang/khai phá) + 创 (sáng tạo) + 新 (mới).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💡","examples":[{"type":"basic","zh":"年轻人敢于开拓创新。","pinyin":"Niánqīngrén gǎnyú kāituòchuàngxīn.","vi":"Người trẻ dám khai phá và đổi mới sáng tạo."},{"type":"simple","zh":"这家老国企靠开拓创新打开了海外市场。","pinyin":"Zhè jiālǎo guóqǐ kào kāituòchuàngxīn dǎkāile hǎiwài shìchǎng.","vi":"Doanh nghiệp nhà nước lâu đời này đã mở ra thị trường nước ngoài nhờ khai phá và đổi mới."},{"type":"compound","zh":"如果企业不开拓创新，就迟早会被市场淘汰。","pinyin":"Rúguǒ qǐyè bù kāituòchuàngxīn, jiù chízǎo huì bèi shìchǎng táotài.","vi":"Nếu doanh nghiệp không khai phá đổi mới, sớm muộn sẽ bị thị trường đào thải."}],"related":[{"hanzi":"开拓","pinyin":"kāituò","vi":"khai phá"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"đổi mới"},{"hanzi":"进取","pinyin":"jìnqǔ","vi":"cầu tiến"}],"traditional":"開拓創新"},{"id":"开心果","hanzi":"开心果","pinyin":"kāixīnguǒ","meaning_vi":"hạt dẻ cười; người mang lại niềm vui cho mọi người","explanation":"开 (mở) + 心 (tâm lý/tâm huyết) + 果 (果).","hsk_level":"7-9","tags":["danh-tu","an-uong","con-nguoi"],"image":"😄","examples":[{"type":"basic","zh":"我爱吃开心果。","pinyin":"Wǒ ài chī kāixīnguǒ.","vi":"Tôi thích ăn hạt dẻ cười."},{"type":"simple","zh":"小女儿是我们全家的开心果。","pinyin":"Xiǎo nǚ'ér shì wǒmen quánjiā de kāixīnguǒ.","vi":"Cô con gái út là niềm vui của cả nhà chúng tôi."},{"type":"compound","zh":"他一来，办公室就笑声不断，真是个开心果。","pinyin":"Tā yìlái, bàngōngshì jiù xiàoshēng búduàn, zhēn shì gè kāixīnguǒ.","vi":"Anh ấy vừa đến là văn phòng rộn tiếng cười, đúng là cây hài của cả nhóm."}],"related":[{"hanzi":"坚果","pinyin":"jiānguǒ","vi":"hạt khô"},{"hanzi":"开心","pinyin":"kāixīn","vi":"vui vẻ"},{"hanzi":"活宝","pinyin":"huóbǎo","vi":"người vui tính"}],"traditional":"開心果"},{"id":"开演","hanzi":"开演","pinyin":"kāiyǎn","meaning_vi":"bắt đầu biểu diễn","explanation":"开 (mở) + 演 (diễn biến/biểu diễn).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"电影七点开演。","pinyin":"Diànyǐng qīdiǎn kāiyǎn.","vi":"Phim bắt đầu chiếu lúc bảy giờ."},{"type":"simple","zh":"话剧开演前十分钟，剧场里已经坐满了观众。","pinyin":"Huàjù kāiyǎn qián shí fēnzhōng, jùchǎng lǐ yǐjīng zuò mǎnle guānzhòng.","vi":"Mười phút trước khi vở kịch bắt đầu, nhà hát đã kín chỗ khán giả."},{"type":"compound","zh":"我们一到剧院门口，音乐会就开演了。","pinyin":"Wǒmen yí dào jùyuàn ménkǒu, yīnyuèhuì jiù kāiyǎn le.","vi":"Chúng tôi vừa đến cửa nhà hát thì buổi hòa nhạc bắt đầu."}],"related":[{"hanzi":"开场","pinyin":"kāichǎng","vi":"mở màn"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"biểu diễn"},{"hanzi":"散场","pinyin":"sànchǎng","vi":"tan buổi"}],"traditional":"開演"},{"id":"堪比","hanzi":"堪比","pinyin":"kānbǐ","meaning_vi":"sánh ngang với","explanation":"堪 (chịu đựng được/xứng đáng) + 比 (so với).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"他的厨艺堪比大厨。","pinyin":"Tā de chúyì kānbǐ dàchú.","vi":"Tay nghề nấu ăn của anh ấy sánh ngang đầu bếp chuyên nghiệp."},{"type":"simple","zh":"这家小店的牛肉面味道堪比五星级酒店。","pinyin":"Zhè jiā xiǎodiàn de niúròumiàn wèidào kānbǐ wǔxīngjí jiǔdiàn.","vi":"Mì bò của quán nhỏ này có hương vị sánh ngang khách sạn năm sao."},{"type":"compound","zh":"这款手机虽然价格不高，但是拍照效果堪比单反相机。","pinyin":"Zhè kuǎn shǒujī suīrán jiàgé bù gāo, dànshì pāizhào xiàoguǒ kānbǐ dānfǎn xiàngjī.","vi":"Chiếc điện thoại này tuy giá không cao, nhưng chất lượng ảnh sánh ngang máy ảnh DSLR."}],"related":[{"hanzi":"媲美","pinyin":"pìměi","vi":"sánh đẹp"},{"hanzi":"比得上","pinyin":"bǐdeshàng","vi":"sánh được"},{"hanzi":"相当于","pinyin":"xiāngdāngyú","vi":"tương đương với"}]},{"id":"刊发","hanzi":"刊发","pinyin":"kānfā","meaning_vi":"đăng tải phát hành (bài báo)","explanation":"刊 (ấn phẩm/đăng báo) + 发 (发).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📰","examples":[{"type":"basic","zh":"报纸刊发了此文。","pinyin":"Bàozhǐ kānfāle cǐ wén.","vi":"Tờ báo đã đăng bài viết này."},{"type":"simple","zh":"这本医学期刊刊发了他关于肝癌的研究论文。","pinyin":"Zhè běn yīxué qīkān kānfāle tā guānyú gān'ái de yánjiū lùnwén.","vi":"Tạp chí y học này đã đăng bài nghiên cứu của anh ấy về ung thư gan."},{"type":"compound","zh":"文章一经刊发，就引起了社会的广泛讨论。","pinyin":"Wénzhāng yìjīng kānfā, jiù yǐnqǐle shèhuì de guǎngfàn tǎolùn.","vi":"Bài viết vừa được đăng tải đã gây ra cuộc thảo luận rộng rãi trong xã hội."}],"related":[{"hanzi":"发表","pinyin":"fābiǎo","vi":"đăng tải"},{"hanzi":"刊登","pinyin":"kāndēng","vi":"đăng báo"},{"hanzi":"报刊","pinyin":"bàokān","vi":"báo chí"}],"traditional":"刊發"},{"id":"康复","hanzi":"康复","pinyin":"kāngfù","meaning_vi":"hồi phục sức khỏe","explanation":"康 (khang – khỏe mạnh) + 复 (phục – trở lại) → khôi phục sức khỏe sau ốm, chấn thương. VD: 祝你早日康复, 康复训练.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"祝你早日康复！","pinyin":"Zhù nǐ zǎorì kāngfù!","vi":"Chúc bạn sớm bình phục!"},{"type":"simple","zh":"经过半年的训练，他的腿伤已经基本康复。","pinyin":"Jīng guòbàn nián de xùnliàn, tā de tuǐ shāng yǐjīng jīběn kāngfù.","vi":"Sau nửa năm tập luyện, vết thương ở chân anh ấy đã cơ bản hồi phục."},{"type":"compound","zh":"只要坚持做康复训练，你就能重新走路。","pinyin":"Zhǐyào jiānchí zuò kāngfù xùnliàn, nǐ jiù néng chóngxīn zǒulù.","vi":"Chỉ cần kiên trì tập phục hồi chức năng, bạn sẽ có thể đi lại được."}],"related":[{"hanzi":"恢复","pinyin":"huīfù","vi":"hồi phục"},{"hanzi":"痊愈","pinyin":"quányù","vi":"khỏi bệnh"},{"hanzi":"康复中心","pinyin":"kāngfùzhōngxīn","vi":"trung tâm phục hồi"}],"traditional":"康復"},{"id":"苛刻","hanzi":"苛刻","pinyin":"kēkè","meaning_vi":"khắt khe, hà khắc","explanation":"苛 (khắt khe/hà khắc) + 刻 (khắc ghi/sâu sắc).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😠","examples":[{"type":"basic","zh":"条件太苛刻了。","pinyin":"Tiáojiàn tài kēkè le.","vi":"Điều kiện quá khắt khe."},{"type":"simple","zh":"这家外企对新员工的英语水平要求十分苛刻。","pinyin":"Zhè jiā wàiqǐ duì xīn yuángōng de Yīngyǔ shuǐpíng yāoqiú shífēn kēkè.","vi":"Công ty nước ngoài này yêu cầu rất khắt khe về trình độ tiếng Anh của nhân viên mới."},{"type":"compound","zh":"虽然合同条款很苛刻，但是为了生存他们只能签字。","pinyin":"Suīrán hétóng tiáokuǎn hěn kēkè, dànshì wèile shēngcún tāmen zhǐnéng qiānzì.","vi":"Tuy điều khoản hợp đồng rất hà khắc, nhưng để tồn tại họ đành phải ký."}],"related":[{"hanzi":"严格","pinyin":"yángé","vi":"nghiêm khắc"},{"hanzi":"刻薄","pinyin":"kèbó","vi":"cay nghiệt"},{"hanzi":"宽松","pinyin":"kuānsōng","vi":"nới lỏng"}]},{"id":"科普","hanzi":"科普","pinyin":"kēpǔ","meaning_vi":"phổ biến kiến thức khoa học","explanation":"科 (khoa học/môn học) + 普 (phổ cập/phổ biến).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"📘","examples":[{"type":"basic","zh":"他爱看科普书。","pinyin":"Tā ài kàn kēpǔ shū.","vi":"Anh ấy thích đọc sách phổ biến khoa học."},{"type":"simple","zh":"这位天文学家每周在网上做一期科普直播。","pinyin":"Zhè wèi tiān wénxuéjiā měizhōu zài wǎngshang zuò yì qī kēpǔ zhíbō.","vi":"Nhà thiên văn học này mỗi tuần livestream một buổi phổ biến kiến thức khoa học."},{"type":"compound","zh":"如果科普工作做得好，谣言就很难传播。","pinyin":"Rúguǒ kēpǔ gōngzuò zuò de hǎo, yáoyán jiù hěn nán chuánbō.","vi":"Nếu công tác phổ biến khoa học làm tốt, tin đồn thất thiệt sẽ khó lan truyền."}],"related":[{"hanzi":"科学","pinyin":"kēxué","vi":"khoa học"},{"hanzi":"普及","pinyin":"pǔjí","vi":"phổ cập"},{"hanzi":"科普读物","pinyin":"kēpǔdúwù","vi":"sách phổ biến khoa học"}]},{"id":"科学化","hanzi":"科学化","pinyin":"kēxuéhuà","meaning_vi":"khoa học hóa","explanation":"科 (khoa học/môn học) + 学 (học thuật/học thuyết) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔬","examples":[{"type":"basic","zh":"训练要科学化。","pinyin":"Xùnliàn yào kēxuéhuà.","vi":"Việc tập luyện cần được khoa học hóa."},{"type":"simple","zh":"这家农场用传感器实现了灌溉管理的科学化。","pinyin":"Zhè jiā nóngchǎng yòng chuángǎnqì shíxiànle guàngài guǎnlǐ de kēxuéhuà.","vi":"Nông trại này dùng cảm biến để khoa học hóa việc quản lý tưới tiêu."},{"type":"compound","zh":"一旦饮食安排科学化，运动员的体能就提升得更快。","pinyin":"Yídàn yǐnshí ānpái kēxuéhuà, yùndòngyuán de tǐnéng jiù tíshēng de gèng kuài.","vi":"Một khi chế độ ăn được khoa học hóa, thể lực của vận động viên sẽ tăng nhanh hơn."}],"related":[{"hanzi":"科学","pinyin":"kēxué","vi":"khoa học"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"chuẩn hóa"},{"hanzi":"系统化","pinyin":"xìtǒnghuà","vi":"hệ thống hóa"}],"traditional":"科學化"},{"id":"科研","hanzi":"科研","pinyin":"kēyán","meaning_vi":"nghiên cứu khoa học","explanation":"科 (khoa học/môn học) + 研 (nghiên cứu).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"她从事科研工作。","pinyin":"Tā cóngshì kēyán gōngzuò.","vi":"Cô ấy làm công tác nghiên cứu khoa học."},{"type":"simple","zh":"这所大学每年投入上亿元用于科研。","pinyin":"Zhè suǒ dàxué měinián tóurù shàng yì yuán yòngyú kēyán.","vi":"Trường đại học này mỗi năm đầu tư hơn trăm triệu tệ cho nghiên cứu khoa học."},{"type":"compound","zh":"虽然科研过程很枯燥，但是他从没想过放弃。","pinyin":"Suīrán kēyán guòchéng hěn kūzào, dànshì tā cóng méi xiǎngguò fàngqì.","vi":"Tuy quá trình nghiên cứu khoa học rất khô khan, nhưng anh ấy chưa từng nghĩ đến chuyện bỏ cuộc."}],"related":[{"hanzi":"科研成果","pinyin":"kēyánchéngguǒ","vi":"thành quả nghiên cứu"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"科学家","pinyin":"kēxuéjiā","vi":"nhà khoa học"}]},{"id":"科研成果","hanzi":"科研成果","pinyin":"kēyánchéngguǒ","meaning_vi":"thành quả nghiên cứu khoa học","explanation":"科 (khoa học/môn học) + 研 (nghiên cứu) + 成 (成) + 果 (果).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"这是新的科研成果。","pinyin":"Zhè shì xīn de kēyánchéngguǒ.","vi":"Đây là thành quả nghiên cứu khoa học mới."},{"type":"simple","zh":"这项科研成果已经被用于治疗罕见病。","pinyin":"Zhè xiàng kēyánchéngguǒ yǐjīng bèi yòngyú zhìliáo hǎnjiàn bìng.","vi":"Thành quả nghiên cứu này đã được ứng dụng vào điều trị bệnh hiếm gặp."},{"type":"compound","zh":"只有把科研成果转化为产品，才能真正造福百姓。","pinyin":"Zhǐyǒu bǎ kēyánchéngguǒ zhuǎnhuà wéi chǎnpǐn, cáinéng zhēnzhèng zàofú bǎixìng.","vi":"Chỉ khi biến thành quả nghiên cứu khoa học thành sản phẩm mới thực sự mang lại lợi ích cho người dân."}],"related":[{"hanzi":"成果","pinyin":"chéngguǒ","vi":"thành quả"},{"hanzi":"科研","pinyin":"kēyán","vi":"nghiên cứu khoa học"},{"hanzi":"论文","pinyin":"lùnwén","vi":"luận văn"}]},{"id":"可持续发展","hanzi":"可持续发展","pinyin":"kěchíxù fāzhǎn","meaning_vi":"phát triển bền vững","explanation":"可持续 (có thể duy trì lâu dài) + 发展.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","thien-nhien"],"image":"♻️","examples":[{"type":"basic","zh":"要坚持可持续发展。","pinyin":"Yào jiānchí kěchíxùfāzhǎn.","vi":"Phải kiên trì phát triển bền vững."},{"type":"simple","zh":"这座海岛通过限制游客数量来实现可持续发展。","pinyin":"Zhè zuò hǎidǎo tōngguò xiànzhì yóukè shùliàng lái shíxiàn kěchíxùfāzhǎn.","vi":"Hòn đảo này thực hiện phát triển bền vững bằng cách giới hạn số lượng du khách."},{"type":"compound","zh":"如果只顾眼前利益，就谈不上可持续发展。","pinyin":"Rúguǒ zhǐgù yǎnqián lìyì, jiù tánbúshàng kěchíxùfāzhǎn.","vi":"Nếu chỉ lo lợi ích trước mắt thì không thể nói đến phát triển bền vững."}],"related":[{"hanzi":"可持续","pinyin":"kěchíxù","vi":"bền vững"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"},{"hanzi":"绿色经济","pinyin":"lǜsèjīngjì","vi":"kinh tế xanh"}],"traditional":"可持續發展"},{"id":"可贵","hanzi":"可贵","pinyin":"kěguì","meaning_vi":"đáng quý","explanation":"可 (khả – đáng) + 贵 (quý – quý giá) → đáng quý, đáng trân trọng. VD: 难能可贵, 可贵的品质.","hsk_level":"7-9","tags":["tinh-tu"],"image":"💎","examples":[{"type":"basic","zh":"诚实很可贵。","pinyin":"Chéngshí hěn kěguì.","vi":"Sự trung thực thật đáng quý."},{"type":"simple","zh":"她在逆境中保持乐观的精神非常可贵。","pinyin":"Tā zài nìjìng zhōng bǎochí lèguān de jīngshén fēicháng kěguì.","vi":"Tinh thần lạc quan của cô ấy giữa nghịch cảnh thật vô cùng đáng quý."},{"type":"compound","zh":"这孩子虽然成绩一般，但是乐于助人的品质很可贵。","pinyin":"Zhè háizi suīrán chéngjì yìbān, dànshì lèyú zhùrén de pǐnzhì hěn kěguì.","vi":"Đứa trẻ này tuy thành tích bình thường, nhưng phẩm chất thích giúp đỡ người khác rất đáng quý."}],"related":[{"hanzi":"宝贵","pinyin":"bǎoguì","vi":"quý báu"},{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý giá"},{"hanzi":"难能可贵","pinyin":"nánnéngkěguì","vi":"đáng quý hiếm có"}],"traditional":"可貴"},{"id":"可怜巴巴","hanzi":"可怜巴巴","pinyin":"kěliánbābā","meaning_vi":"tội nghiệp đáng thương","explanation":"可 (可) + 怜 (thương xót) + 巴 (巴) + 巴 (巴).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"小狗可怜巴巴的。","pinyin":"Xiǎogǒu kěliánbābā de.","vi":"Chú cún trông thật tội nghiệp."},{"type":"simple","zh":"弟弟可怜巴巴地看着我手里的冰淇淋。","pinyin":"Dìdi kěliánbābā de kànzhe wǒ shǒulǐ de bīngqílín.","vi":"Em trai nhìn cây kem trong tay tôi với vẻ tội nghiệp."},{"type":"compound","zh":"他一露出可怜巴巴的样子，妈妈就心软了。","pinyin":"Tā yí lùchū kěliánbābā de yàngzi, māma jiù xīnruǎn le.","vi":"Cậu bé vừa tỏ vẻ đáng thương, mẹ liền mềm lòng."}],"related":[{"hanzi":"可怜","pinyin":"kělián","vi":"đáng thương"},{"hanzi":"委屈","pinyin":"wěiqu","vi":"tủi thân"},{"hanzi":"楚楚可怜","pinyin":"chǔchǔkělián","vi":"đáng thương tội nghiệp"}],"traditional":"可憐巴巴"},{"id":"可取","hanzi":"可取","pinyin":"kěqǔ","meaning_vi":"đáng học hỏi, chấp nhận được","explanation":"可 (khả – có thể, đáng) + 取 (thủ – lấy) → đáng lấy, có thể học hỏi, chấp nhận được. VD: 这种做法不可取.","hsk_level":"7-9","tags":["tinh-tu"],"image":"👍","examples":[{"type":"basic","zh":"这种做法不可取。","pinyin":"Zhè zhǒng zuòfǎ bù kěqǔ.","vi":"Cách làm này không nên."},{"type":"simple","zh":"他的方案中有几点可取之处值得借鉴。","pinyin":"Tā de fāng'àn zhōng yǒu jǐ diǎn kěqǔ zhī chù zhíde jièjiàn.","vi":"Phương án của anh ấy có vài điểm hay đáng để tham khảo."},{"type":"compound","zh":"虽然他的态度不太好，但是意见本身很可取。","pinyin":"Suīrán tā de tàidù bú tài hǎo, dànshì yìjiàn běnshēn hěn kěqǔ.","vi":"Tuy thái độ của anh ấy không tốt lắm, nhưng bản thân ý kiến thì rất đáng tiếp thu."}],"related":[{"hanzi":"可行","pinyin":"kěxíng","vi":"khả thi"},{"hanzi":"借鉴","pinyin":"jièjiàn","vi":"tham khảo"},{"hanzi":"不可取","pinyin":"bùkěqǔ","vi":"không nên làm"}]},{"id":"可塑性","hanzi":"可塑性","pinyin":"kěsùxìng","meaning_vi":"tính dẻo, khả năng rèn luyện phát triển","explanation":"可 (可) + 塑 (xây dựng hình tượng) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌱","examples":[{"type":"basic","zh":"孩子可塑性很强。","pinyin":"Háizi kěsùxìng hěn qiáng.","vi":"Trẻ em có khả năng uốn nắn rất cao."},{"type":"simple","zh":"这种黏土加水后具有很好的可塑性。","pinyin":"Zhè zhǒng niántǔ jiā shuǐ hòu jùyǒu hěn hǎo de kěsùxìng.","vi":"Loại đất sét này sau khi thêm nước có tính dẻo rất tốt."},{"type":"compound","zh":"因为年轻人可塑性大，所以公司更愿意招应届生。","pinyin":"Yīnwèi niánqīngrén kěsùxìng dà, suǒyǐ gōngsī gèng yuànyì zhāo yìngjièshēng.","vi":"Vì người trẻ có khả năng rèn luyện cao, nên công ty thích tuyển sinh viên mới tốt nghiệp hơn."}],"related":[{"hanzi":"塑造","pinyin":"sùzào","vi":"nhào nặn"},{"hanzi":"潜力","pinyin":"qiánlì","vi":"tiềm năng"},{"hanzi":"灵活性","pinyin":"línghuóxìng","vi":"tính linh hoạt"}]},{"id":"可再生资源","hanzi":"可再生资源","pinyin":"kězàishēng zīyuán","meaning_vi":"tài nguyên tái tạo","explanation":"可 (可) + 再 (tiếp tục/lặp lại) + 生 (sinh tồn/sinh động) + 资 (tài nguyên/tư bản) + 源 (nguồn gốc).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"♻️","examples":[{"type":"basic","zh":"风能是可再生资源。","pinyin":"Fēngnéng shì kězàishēngzīyuán.","vi":"Năng lượng gió là tài nguyên tái tạo."},{"type":"simple","zh":"这座小岛的电力全部来自太阳能等可再生资源。","pinyin":"Zhè zuò xiǎodǎo de diànlì quánbù láizì tàiyángnéng děng kězàishēngzīyuán.","vi":"Toàn bộ điện năng của hòn đảo nhỏ này đến từ các tài nguyên tái tạo như năng lượng mặt trời."},{"type":"compound","zh":"即使是可再生资源，过度利用也会造成破坏。","pinyin":"Jíshǐ shì kězàishēngzīyuán, guòdù lìyòng yě huì zàochéng pòhuài.","vi":"Dù là tài nguyên tái tạo, khai thác quá mức cũng sẽ gây ra tổn hại."}],"related":[{"hanzi":"不可再生资源","pinyin":"bù kězàishēngzīyuán","vi":"tài nguyên không tái tạo"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"新能源","pinyin":"xīnnéngyuán","vi":"năng lượng mới"}],"traditional":"可再生資源"},{"id":"恳谈","hanzi":"恳谈","pinyin":"kěntán","meaning_vi":"trò chuyện chân thành cởi mở","explanation":"恳 (khẩn thiết/chân thành) + 谈 (nói chuyện).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"☕","examples":[{"type":"basic","zh":"双方进行了恳谈。","pinyin":"Shuāngfāng jìnxíngle kěntán.","vi":"Hai bên đã có cuộc trò chuyện chân thành."},{"type":"simple","zh":"校长邀请几位家长代表到会议室恳谈。","pinyin":"Xiàozhǎng yāoqǐng jǐ wèi jiāzhǎng dàibiǎo dào huìyìshì kěntán.","vi":"Hiệu trưởng mời vài đại diện phụ huynh đến phòng họp để trao đổi thẳng thắn."},{"type":"compound","zh":"只要双方坐下来恳谈，误会就能解开。","pinyin":"Zhǐyào shuāngfāng zuò xiàlái kěntán, wùhuì jiù néng jiěkāi.","vi":"Chỉ cần hai bên ngồi lại trò chuyện chân thành, hiểu lầm sẽ được hóa giải."}],"related":[{"hanzi":"恳切","pinyin":"kěnqiè","vi":"khẩn thiết"},{"hanzi":"谈心","pinyin":"tánxīn","vi":"tâm sự"},{"hanzi":"座谈","pinyin":"zuòtán","vi":"tọa đàm"}],"traditional":"懇談"},{"id":"空间站","hanzi":"空间站","pinyin":"kōngjiānzhàn","meaning_vi":"trạm vũ trụ, trạm không gian","explanation":"空 (trống rỗng/không gian) + 间 (间) + 站 (đứng).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🛰️","examples":[{"type":"basic","zh":"空间站建成了。","pinyin":"Kōngjiānzhàn jiàn chéngle.","vi":"Trạm vũ trụ đã được xây dựng xong."},{"type":"simple","zh":"三名航天员将在空间站上生活半年。","pinyin":"Sān míng hángtiānyuán jiāng zài kōngjiānzhàn shang shēnghuó bàn nián.","vi":"Ba phi hành gia sẽ sống nửa năm trên trạm vũ trụ."},{"type":"compound","zh":"如果夜空足够晴朗，我们就能看到空间站飞过。","pinyin":"Rúguǒ yèkōng zúgòu qínglǎng, wǒmen jiù néng kàndào kōngjiānzhàn fēiguò.","vi":"Nếu bầu trời đêm đủ quang đãng, chúng ta có thể nhìn thấy trạm vũ trụ bay qua."}],"related":[{"hanzi":"航天员","pinyin":"hángtiānyuán","vi":"phi hành gia"},{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"太空","pinyin":"tàikōng","vi":"vũ trụ"}],"traditional":"空間站"},{"id":"空前","hanzi":"空前","pinyin":"kōngqián","meaning_vi":"chưa từng có trước đây","explanation":"空 (trống rỗng/không gian) + 前 (trước).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"展会盛况空前。","pinyin":"Zhǎnhuì shèngkuàng kōngqián.","vi":"Triển lãm đông vui chưa từng có."},{"type":"simple","zh":"这次演唱会的门票销量达到了空前的规模。","pinyin":"Zhè cì yǎnchànghuì de ménpiào xiāoliàng dádàole kōngqián de guīmó.","vi":"Lượng vé bán ra của buổi hòa nhạc lần này đạt quy mô chưa từng có."},{"type":"compound","zh":"一宣布降价，商场就出现了空前的抢购热潮。","pinyin":"Yì xuānbù jiàngjià, shāngchǎng jiù chūxiànle kōngqián de qiǎnggòu rècháo.","vi":"Vừa công bố giảm giá, trung tâm thương mại liền xuất hiện làn sóng mua sắm chưa từng có."}],"related":[{"hanzi":"空前绝后","pinyin":"kōngqiánjuéhòu","vi":"trước chưa có sau không có"},{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có"},{"hanzi":"前所未有","pinyin":"qiánsuǒwèiyǒu","vi":"chưa từng có"}]},{"id":"空运","hanzi":"空运","pinyin":"kōngyùn","meaning_vi":"vận chuyển đường hàng không","explanation":"空 (trống rỗng/không gian) + 运 (vận dụng/vận hành).","hsk_level":"7-9","tags":["dong-tu","giao-thong","cong-viec"],"image":"✈️","examples":[{"type":"basic","zh":"这批货要空运。","pinyin":"Zhè pī huò yào kōngyùn.","vi":"Lô hàng này phải vận chuyển bằng đường hàng không."},{"type":"simple","zh":"新鲜的三文鱼每天从挪威空运到上海。","pinyin":"Xīnxiān de sānwényú měitiān cóng Nuówēi kōngyùn dào Shànghǎi.","vi":"Cá hồi tươi mỗi ngày được vận chuyển bằng máy bay từ Na Uy đến Thượng Hải."},{"type":"compound","zh":"空运虽然速度快，但是费用比海运高得多。","pinyin":"Kōngyùn suīrán sùdù kuài, dànshì fèiyòng bǐ hǎiyùn gāo de duō.","vi":"Vận chuyển hàng không tuy nhanh, nhưng chi phí cao hơn đường biển rất nhiều."}],"related":[{"hanzi":"海运","pinyin":"hǎiyùn","vi":"vận chuyển đường biển"},{"hanzi":"陆运","pinyin":"lùyùn","vi":"vận chuyển đường bộ"},{"hanzi":"航空","pinyin":"hángkōng","vi":"hàng không"}],"traditional":"空運"},{"id":"枯竭","hanzi":"枯竭","pinyin":"kūjié","meaning_vi":"cạn kiệt (tài nguyên/cảm hứng)","explanation":"枯 (khô héo/khô khan) + 竭 (dốc hết sức).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"泉水已经枯竭。","pinyin":"Quánshuǐ yǐjīng kūjié.","vi":"Mạch nước suối đã cạn kiệt."},{"type":"simple","zh":"长期过度开采使这座煤矿的资源逐渐枯竭。","pinyin":"Chángqī guòdù kāicǎi shǐ zhè zuò méikuàng de zīyuán zhújiàn kūjié.","vi":"Khai thác quá mức lâu dài khiến tài nguyên của mỏ than này dần cạn kiệt."},{"type":"compound","zh":"每当灵感枯竭时，这位作家就去海边散步。","pinyin":"Měidāng línggǎn kūjié shí, zhè wèi zuòjiā jiù qù hǎibiān sànbù.","vi":"Mỗi khi cạn cảm hứng, nhà văn này lại ra bờ biển đi dạo."}],"related":[{"hanzi":"干涸","pinyin":"gānhé","vi":"khô cạn"},{"hanzi":"耗尽","pinyin":"hàojìn","vi":"cạn kiệt"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"}]},{"id":"考场","hanzi":"考场","pinyin":"kǎochǎng","meaning_vi":"phòng thi, trường thi","explanation":"考 (khảo sát/thi cử) + 场 (trận).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","dia-diem"],"image":"📝","examples":[{"type":"basic","zh":"考生进入考场。","pinyin":"Kǎoshēng jìnrù kǎochǎng.","vi":"Thí sinh vào phòng thi."},{"type":"simple","zh":"监考老师提前半小时就在考场门口检查证件。","pinyin":"Jiānkǎo lǎoshī tíqián bànxiǎoshí jiù zài kǎochǎng ménkǒu jiǎnchá zhèngjiàn.","vi":"Giám thị kiểm tra giấy tờ ở cửa phòng thi từ nửa tiếng trước."},{"type":"compound","zh":"一走进考场，他就紧张得手心冒汗。","pinyin":"Yì zǒujìn kǎochǎng, tā jiù jǐnzhāng deshǒu xīn màohàn.","vi":"Vừa bước vào phòng thi, anh ấy đã căng thẳng đến toát mồ hôi tay."}],"related":[{"hanzi":"考试","pinyin":"kǎoshì","vi":"thi cử"},{"hanzi":"考生","pinyin":"kǎoshēng","vi":"thí sinh"},{"hanzi":"监考","pinyin":"jiānkǎo","vi":"coi thi"}],"traditional":"考場"},{"id":"考究","hanzi":"考究","pinyin":"kǎojiū","meaning_vi":"tinh tế cầu kỳ, nghiên cứu khảo chứng","explanation":"考 (khảo sát/thi cử) + 究 (nghiên cứu/truy cứu).","hsk_level":"7-9","tags":["tinh-tu","dong-tu"],"image":"✨","examples":[{"type":"basic","zh":"他穿着很考究。","pinyin":"Tā chuānzhuó hěn kǎojiū.","vi":"Anh ấy ăn mặc rất cầu kỳ tinh tế."},{"type":"simple","zh":"这家茶馆的桌椅和茶具都十分考究。","pinyin":"Zhè jiā cháguǎn de zhuō yǐ hé chájù dōu shífēn kǎojiū.","vi":"Bàn ghế và bộ trà của quán trà này đều vô cùng tinh tế."},{"type":"compound","zh":"这本书不但装帧考究，而且内容扎实。","pinyin":"Zhè běn shū búdàn zhuāngzhēn kǎojiū, érqiě nèiróng zhāshi.","vi":"Cuốn sách này không chỉ đóng bìa tinh xảo mà nội dung còn chắc chắn."}],"related":[{"hanzi":"讲究","pinyin":"jiǎngjiu","vi":"cầu kỳ"},{"hanzi":"精致","pinyin":"jīngzhì","vi":"tinh xảo"},{"hanzi":"考证","pinyin":"kǎozhèng","vi":"khảo chứng"}]},{"id":"考生","hanzi":"考生","pinyin":"kǎoshēng","meaning_vi":"thí sinh dự thi","explanation":"考 (khảo sát/thi cử) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","con-nguoi"],"image":"🧑‍🎓","examples":[{"type":"basic","zh":"考生们很紧张。","pinyin":"Kǎoshēngmen hěn jǐnzhāng.","vi":"Các thí sinh rất căng thẳng."},{"type":"simple","zh":"今年全国共有一千多万名考生参加高考。","pinyin":"Jīnnián quánguó gòngyǒu yī qiān duō wànmíng kǎoshēng cānjiā gāokǎo.","vi":"Năm nay cả nước có hơn mười triệu thí sinh tham dự kỳ thi đại học."},{"type":"compound","zh":"如果考生迟到超过十五分钟，就不能进入考场。","pinyin":"Rúguǒ kǎoshēng chídào chāoguò shíwǔ fēnzhōng, jiù bù néng jìnrù kǎochǎng.","vi":"Nếu thí sinh đến muộn quá mười lăm phút thì không được vào phòng thi."}],"related":[{"hanzi":"考场","pinyin":"kǎochǎng","vi":"phòng thi"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"thi cử"},{"hanzi":"高考","pinyin":"gāokǎo","vi":"thi đại học"}]},{"id":"考题","hanzi":"考题","pinyin":"kǎotí","meaning_vi":"đề thi","explanation":"考 (khảo sát/thi cử) + 题 (đề tài/vấn đề).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"今年考题很难。","pinyin":"Jīnnián kǎotí hěn nán.","vi":"Đề thi năm nay rất khó."},{"type":"simple","zh":"这次数学考试的最后一道考题难倒了很多人。","pinyin":"Zhè cì shùxué kǎoshì de zuìhòu yídào kǎotí nándǎole hěn duō rén.","vi":"Câu hỏi cuối cùng trong bài thi toán lần này đã làm khó rất nhiều người."},{"type":"compound","zh":"虽然考题出得很灵活，但是考的都是基础知识。","pinyin":"Suīrán kǎotí chū de hěn línghuó, dànshì kǎo de dōu shì jīchǔ zhīshi.","vi":"Tuy đề thi ra rất linh hoạt, nhưng đều kiểm tra kiến thức cơ bản."}],"related":[{"hanzi":"试题","pinyin":"shìtí","vi":"đề thi"},{"hanzi":"考卷","pinyin":"kǎojuàn","vi":"bài thi"},{"hanzi":"答案","pinyin":"dá'àn","vi":"đáp án"}],"traditional":"考題"},{"id":"考研","hanzi":"考研","pinyin":"kǎoyán","meaning_vi":"thi cao học (thạc sĩ)","explanation":"考 (khảo sát/thi cử) + 研 (nghiên cứu).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"她准备考研。","pinyin":"Tā zhǔnbèi kǎoyán.","vi":"Cô ấy chuẩn bị thi cao học."},{"type":"simple","zh":"他每天早上六点去图书馆复习考研英语。","pinyin":"Tā měitiān zǎoshang liù diǎn qù túshūguǎn fùxí kǎoyán Yīngyǔ.","vi":"Mỗi sáng sáu giờ anh ấy đến thư viện ôn môn tiếng Anh thi cao học."},{"type":"compound","zh":"与其盲目考研，不如先工作几年再决定。","pinyin":"Yǔqí mángmù kǎoyán, bùrú xiān gōngzuò jǐ nián zài juédìng.","vi":"Thay vì thi cao học một cách mù quáng, chi bằng đi làm vài năm rồi hãy quyết định."}],"related":[{"hanzi":"研究生","pinyin":"yánjiūshēng","vi":"học viên cao học"},{"hanzi":"硕士","pinyin":"shuòshì","vi":"thạc sĩ"},{"hanzi":"读研","pinyin":"dúyán","vi":"học cao học"}]},{"id":"口碑","hanzi":"口碑","pinyin":"kǒubēi","meaning_vi":"tiếng tăm tốt, đánh giá truyền miệng của khách hàng","explanation":"口 (miệng) + 碑 (bia đá).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"⭐","examples":[{"type":"basic","zh":"这家店口碑很好。","pinyin":"Zhè jiā diàn kǒubēi hěn hǎo.","vi":"Cửa hàng này được khách đánh giá rất tốt."},{"type":"simple","zh":"这部低成本电影靠观众的口碑逆袭成了黑马。","pinyin":"Zhè bù dīchéngběn diànyǐng kào guānzhòng de kǒubēi nìxí chéngle hēimǎ.","vi":"Bộ phim kinh phí thấp này nhờ khán giả truyền tai nhau mà lội ngược dòng thành hiện tượng."},{"type":"compound","zh":"一旦口碑坏了，再多的广告也救不了一个品牌。","pinyin":"Yídàn kǒubēi huàile, zài duō de guǎnggào yě jiù bùliǎo yí gè pǐnpái.","vi":"Một khi tiếng tăm đã xấu, quảng cáo nhiều đến đâu cũng không cứu nổi một thương hiệu."}],"related":[{"hanzi":"名声","pinyin":"míngshēng","vi":"danh tiếng"},{"hanzi":"信誉","pinyin":"xìnyù","vi":"uy tín"},{"hanzi":"好评","pinyin":"hǎopíng","vi":"đánh giá tốt"}]},{"id":"口碑载道","hanzi":"口碑载道","pinyin":"kǒubēi-zàidào","meaning_vi":"tiếng thơm vang khắp mọi nẻo đường","explanation":"口 (口) + 碑 (bia đá) + 载 (ghi chép/chuyên chở) + 道 (道).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⭐","examples":[{"type":"basic","zh":"他的政绩口碑载道。","pinyin":"Tā de zhèngjì kǒubēizàidào.","vi":"Thành tích làm quan của ông ấy được người người ca ngợi."},{"type":"simple","zh":"这位医术高明的老中医在当地口碑载道。","pinyin":"Zhè wèi yīshù gāomíng de lǎo zhōngyī zài dāngdì kǒubēizàidào.","vi":"Vị lão lương y giỏi nghề này được người dân địa phương hết lời khen ngợi."},{"type":"compound","zh":"因为他为官清廉，所以离任多年后仍然口碑载道。","pinyin":"Yīnwèi tā wéi guān qīnglián, suǒyǐ lírèn duōnián hòu réngrán kǒubēizàidào.","vi":"Vì làm quan thanh liêm, nên dù rời nhiệm sở nhiều năm ông vẫn được mọi người ca ngợi."}],"related":[{"hanzi":"口碑","pinyin":"kǒubēi","vi":"tiếng tăm"},{"hanzi":"有口皆碑","pinyin":"yǒukǒujiēbēi","vi":"ai cũng khen"},{"hanzi":"怨声载道","pinyin":"yuànshēngzàidào","vi":"tiếng oán thán khắp nơi"}],"traditional":"口碑載道"},{"id":"口才","hanzi":"口才","pinyin":"kǒucái","meaning_vi":"tài ăn nói, khẩu tài","explanation":"口 (khẩu – miệng) + 才 (tài – tài năng) → tài ăn nói, khẩu tài. VD: 口才很好, 锻炼口才.","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他口才很好。","pinyin":"Tā kǒucái hěn hǎo.","vi":"Anh ấy có tài ăn nói."},{"type":"simple","zh":"她凭着出色的口才赢得了全市演讲比赛冠军。","pinyin":"Tā píngzhe chūsè de kǒucái yíng déle quánshì yǎnjiǎng bǐsài guànjūn.","vi":"Nhờ tài ăn nói xuất sắc, cô ấy đã giành chức vô địch cuộc thi hùng biện toàn thành phố."},{"type":"compound","zh":"做销售不但要有好口才，而且要懂得倾听。","pinyin":"Zuò xiāoshòu búdàn yàoyǒu hǎo kǒucái, érqiě yào dǒngde qīngtīng.","vi":"Làm bán hàng không những cần có tài ăn nói mà còn phải biết lắng nghe."}],"related":[{"hanzi":"能说会道","pinyin":"néngshuōhuìdào","vi":"ăn nói giỏi"},{"hanzi":"演讲","pinyin":"yǎnjiǎng","vi":"diễn thuyết"},{"hanzi":"表达能力","pinyin":"biǎodánénglì","vi":"khả năng diễn đạt"}]},{"id":"口号","hanzi":"口号","pinyin":"kǒuhào","meaning_vi":"khẩu hiệu","explanation":"口 (口) + 号 (ngày (trong tháng)).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"他们高喊口号。","pinyin":"Tāmen gāohǎn kǒuhào.","vi":"Họ hô vang khẩu hiệu."},{"type":"simple","zh":"运动会上各班都喊出了自己设计的口号。","pinyin":"Yùndònghuì shang gè bān dōu hǎn chūle zìjǐ shèjì de kǒuhào.","vi":"Tại hội thao, các lớp đều hô vang khẩu hiệu do mình tự sáng tác."},{"type":"compound","zh":"如果环保只停留在口号上，污染就不会减少。","pinyin":"Rúguǒ huánbǎo zhǐ tíngliú zài kǒuhào shang, wūrǎn jiù bú huì jiǎnshǎo.","vi":"Nếu bảo vệ môi trường chỉ dừng lại ở khẩu hiệu, ô nhiễm sẽ không giảm."}],"related":[{"hanzi":"标语","pinyin":"biāoyǔ","vi":"khẩu hiệu viết"},{"hanzi":"喊口号","pinyin":"hǎnkǒuhào","vi":"hô khẩu hiệu"},{"hanzi":"宣传","pinyin":"xuānchuán","vi":"tuyên truyền"}],"traditional":"口號"},{"id":"口诀","hanzi":"口诀","pinyin":"kǒujué","meaning_vi":"khẩu quyết, bài vè dễ nhớ","explanation":"口 (口) + 诀 (bí quyết/lời từ biệt).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎶","examples":[{"type":"basic","zh":"背熟乘法口诀。","pinyin":"Bèi shú chéngfǎ kǒujué.","vi":"Học thuộc bảng cửu chương."},{"type":"simple","zh":"老师编了一首口诀帮我们记住化学元素。","pinyin":"Lǎoshī biānle yì shǒu kǒujué bāng wǒmen jìzhù huàxué yuánsù.","vi":"Cô giáo soạn một bài vè giúp chúng tôi nhớ các nguyên tố hóa học."},{"type":"compound","zh":"只要记住这句口诀，你就不会再搞错方向了。","pinyin":"Zhǐyào jìzhù zhè jù kǒujué, nǐ jiù bú huì zài gǎocuò fāngxiàng le.","vi":"Chỉ cần nhớ câu khẩu quyết này, bạn sẽ không nhầm hướng nữa."}],"related":[{"hanzi":"乘法口诀","pinyin":"chéngfǎkǒujué","vi":"bảng cửu chương"},{"hanzi":"诀窍","pinyin":"juéqiào","vi":"bí quyết"},{"hanzi":"顺口溜","pinyin":"shùnkǒuliū","vi":"vè"}],"traditional":"口訣"},{"id":"口若悬河","hanzi":"口若悬河","pinyin":"kǒuruò-xuánhé","meaning_vi":"nói năng lưu loát trôi chảy như nước thác","explanation":"口 (口) + 若 (若) + 悬 (treo/lo lắng) + 河 (sông).","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🌊","examples":[{"type":"basic","zh":"他讲起来口若悬河。","pinyin":"Tā jiǎng qǐlái kǒuruòxuánhé.","vi":"Anh ấy nói năng trôi chảy như nước chảy."},{"type":"simple","zh":"那位推销员在顾客面前口若悬河地介绍新产品。","pinyin":"Nà wèi tuīxiāoyuán zài gùkè miànqián kǒuruòxuánhé de jièshào xīnchǎnpǐn.","vi":"Người chào hàng ấy thao thao bất tuyệt giới thiệu sản phẩm mới trước mặt khách hàng."},{"type":"compound","zh":"他平时沉默寡言，可是一谈起足球就口若悬河。","pinyin":"Tā píngshí chénmò guǎyán, kěshì yì tánqǐ zúqiú jiù kǒuruòxuánhé.","vi":"Bình thường anh ấy ít nói, nhưng hễ nhắc đến bóng đá là nói thao thao bất tuyệt."}],"related":[{"hanzi":"滔滔不绝","pinyin":"tāotāobùjué","vi":"nói thao thao"},{"hanzi":"能说会道","pinyin":"néngshuōhuìdào","vi":"ăn nói giỏi"},{"hanzi":"笨嘴拙舌","pinyin":"bènzuǐzhuōshé","vi":"ăn nói vụng về"}],"traditional":"口若懸河"},{"id":"苦闷","hanzi":"苦闷","pinyin":"kǔmèn","meaning_vi":"buồn bực u uất","explanation":"苦 (khổ – đắng, khổ) + 闷 (muộn – bức bối) → buồn bực, u uất trong lòng không giải tỏa được. VD: 心情苦闷.","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"他心里很苦闷。","pinyin":"Tā xīnlǐ hěn kǔmèn.","vi":"Trong lòng anh ấy rất buồn bực."},{"type":"simple","zh":"找不到工作的那半年是他最苦闷的日子。","pinyin":"Zhǎobúdào gōngzuò de nà bàn nián shì tā zuì kǔmèn de rìzi.","vi":"Nửa năm không tìm được việc là quãng thời gian u uất nhất của anh ấy."},{"type":"compound","zh":"她每当感到苦闷，就去江边独自走走。","pinyin":"Tā měidāng gǎndào kǔmèn, jiù qù jiāngbiān dúzì zǒu zou.","vi":"Mỗi khi thấy buồn bực, cô ấy lại một mình ra bờ sông dạo bước."}],"related":[{"hanzi":"烦闷","pinyin":"fánmèn","vi":"buồn bực"},{"hanzi":"郁闷","pinyin":"yùmèn","vi":"u uất"},{"hanzi":"苦恼","pinyin":"kǔnǎo","vi":"phiền muộn"}],"traditional":"苦悶"},{"id":"苦恼","hanzi":"苦恼","pinyin":"kǔnǎo","meaning_vi":"phiền muộn khổ tâm","explanation":"苦 (đắng) + 恼 (bực tức).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😟","examples":[{"type":"basic","zh":"别为小事苦恼。","pinyin":"Bié wèi xiǎoshì kǔnǎo.","vi":"Đừng phiền muộn vì chuyện nhỏ."},{"type":"simple","zh":"她最近一直为孩子不爱吃饭的事苦恼。","pinyin":"Tā zuìjìn yìzhí wèi háizi bú ài chīfàn de shì kǔnǎo.","vi":"Dạo này cô ấy luôn khổ tâm vì chuyện con biếng ăn."},{"type":"compound","zh":"虽然他很苦恼，但是从来不在家人面前表现出来。","pinyin":"Suīrán tā hěn kǔnǎo, dànshì cóngláibú zài jiārén miànqián biǎoxiàn chūlái.","vi":"Tuy anh ấy rất phiền muộn, nhưng chưa bao giờ thể hiện ra trước mặt người nhà."}],"related":[{"hanzi":"烦恼","pinyin":"fánnǎo","vi":"phiền não"},{"hanzi":"苦闷","pinyin":"kǔmèn","vi":"buồn bực"},{"hanzi":"痛苦","pinyin":"tòngkǔ","vi":"đau khổ"}],"traditional":"苦惱"},{"id":"苦心","hanzi":"苦心","pinyin":"kǔxīn","meaning_vi":"dụng tâm, công sức tâm huyết","explanation":"苦 (đắng) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"父母一片苦心。","pinyin":"Fùmǔ yípiàn kǔxīn.","vi":"Cha mẹ một lòng tâm huyết."},{"type":"simple","zh":"他苦心经营这家小书店整整二十年。","pinyin":"Tā kǔxīn jīngyíng zhè jiā xiǎo shūdiàn zhěngzhěng èrshí nián.","vi":"Ông ấy dốc tâm huyết gây dựng hiệu sách nhỏ này suốt hai mươi năm."},{"type":"compound","zh":"直到自己当了老师，我才明白当年班主任的苦心。","pinyin":"Zhídào zìjǐ dāngle lǎoshī, wǒ cái míngbai dāngnián bānzhǔrèn de kǔxīn.","vi":"Mãi đến khi tự mình làm giáo viên, tôi mới hiểu tấm lòng của cô chủ nhiệm năm xưa."}],"related":[{"hanzi":"用心","pinyin":"yòngxīn","vi":"dụng tâm"},{"hanzi":"苦心经营","pinyin":"kǔxīnjīngyíng","vi":"dày công gây dựng"},{"hanzi":"良苦用心","pinyin":"liángkǔyòngxīn","vi":"tấm lòng tốt"}]},{"id":"量变","hanzi":"量变","pinyin":"liàngbiàn","meaning_vi":"biến đổi về lượng (triết học)","explanation":"量 (đo lường/số lượng) + 变 (变).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"📊","examples":[{"type":"basic","zh":"量变引起质变。","pinyin":"Liàngbiàn yǐnqǐ zhìbiàn.","vi":"Biến đổi về lượng dẫn đến biến đổi về chất."},{"type":"simple","zh":"每天背十个单词就是一种看不见的量变。","pinyin":"Měitiān bèi shí gè dāncí jiùshì yì zhǒng kànbújiàn de liàngbiàn.","vi":"Mỗi ngày học thuộc mười từ chính là một sự tích lũy về lượng không nhìn thấy được."},{"type":"compound","zh":"只要量变积累到一定程度，就会发生质变。","pinyin":"Zhǐyào liàngbiàn jīlěi dào yídìng chéngdù, jiù huì fāshēng zhìbiàn.","vi":"Chỉ cần biến đổi về lượng tích lũy đến một mức nhất định, sẽ xảy ra biến đổi về chất."}],"related":[{"hanzi":"质变","pinyin":"zhìbiàn","vi":"biến đổi về chất"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"}],"traditional":"量變"},{"id":"量化","hanzi":"量化","pinyin":"liànghuà","meaning_vi":"lượng hóa, đo lường bằng con số","explanation":"量 (đo lường/số lượng) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"📊","examples":[{"type":"basic","zh":"目标要能量化。","pinyin":"Mùbiāo yào néng liànghuà.","vi":"Mục tiêu phải đo lường được bằng con số."},{"type":"simple","zh":"公司用打分表来量化每位员工的工作表现。","pinyin":"Gōngsī yòng dǎfēn biǎo lái liànghuà měi wèi yuángōng de gōngzuò biǎoxiàn.","vi":"Công ty dùng bảng chấm điểm để lượng hóa hiệu quả làm việc của từng nhân viên."},{"type":"compound","zh":"虽然幸福感很难量化，但是研究者设计了一套问卷。","pinyin":"Suīrán xìngfúgǎn hěn nán liànghuà, dànshì yánjiūzhě shèjìle yítào wènjuàn.","vi":"Tuy cảm giác hạnh phúc rất khó lượng hóa, nhưng các nhà nghiên cứu đã thiết kế một bộ bảng hỏi."}],"related":[{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"量化指标","pinyin":"liànghuàzhǐbiāo","vi":"chỉ tiêu định lượng"},{"hanzi":"衡量","pinyin":"héngliáng","vi":"đo lường"}]},{"id":"量身定制","hanzi":"量身定制","pinyin":"liángshēn-dìngzhì","meaning_vi":"may đo riêng theo yêu cầu","explanation":"量 (đo lường/số lượng) + 身 (thân phận/tự thân) + 定 (定) + 制 (chế độ/kiềm chế).","hsk_level":"7-9","tags":["thanh-ngu","mua-sam"],"image":"👔","examples":[{"type":"basic","zh":"这套西装是量身定制的。","pinyin":"Zhè tào xīzhuāng shì liángshēndìngzhì de.","vi":"Bộ vest này được may đo riêng."},{"type":"simple","zh":"健身教练为她量身定制了一份减脂计划。","pinyin":"Jiànshēn jiàoliàn wèi tā liángshēndìngzhìle yí fèn jiǎnzhī jìhuà.","vi":"Huấn luyện viên thể hình đã thiết kế riêng cho cô ấy một kế hoạch giảm mỡ."},{"type":"compound","zh":"如果课程是量身定制的，学习效果就会好得多。","pinyin":"Rúguǒ kèchéng shì liángshēndìngzhì de, xuéxí xiàoguǒ jiù huì hǎo de duō.","vi":"Nếu khóa học được thiết kế riêng theo nhu cầu, hiệu quả học tập sẽ tốt hơn nhiều."}],"related":[{"hanzi":"定制","pinyin":"dìngzhì","vi":"đặt làm riêng"},{"hanzi":"个性化","pinyin":"gèxìnghuà","vi":"cá nhân hóa"},{"hanzi":"量身","pinyin":"liángshēn","vi":"đo người"}],"traditional":"量身定製"},{"id":"练兵","hanzi":"练兵","pinyin":"liànbīng","meaning_vi":"luyện quân, rèn luyện đội ngũ","explanation":"练 (luyện tập) + 兵 (兵).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🪖","examples":[{"type":"basic","zh":"部队在海边练兵。","pinyin":"Bùduì zài hǎibiān liànbīng.","vi":"Quân đội luyện quân ở bờ biển."},{"type":"simple","zh":"国家队借这次热身赛为世界杯预选赛练兵。","pinyin":"Guójiāduì jiè zhè cì rèshēnsài wèi Shìjièbēi yùxuǎnsài liànbīng.","vi":"Đội tuyển quốc gia tận dụng trận giao hữu này để rèn quân cho vòng loại World Cup."},{"type":"compound","zh":"只要平时多练兵，真遇到火灾时就不会慌乱。","pinyin":"Zhǐyào píngshí duō liànbīng, zhēn yùdào huǒzāi shí jiù bú huì huāngluàn.","vi":"Chỉ cần thường xuyên diễn tập, khi thật sự gặp hỏa hoạn sẽ không hoảng loạn."}],"related":[{"hanzi":"训练","pinyin":"xùnliàn","vi":"huấn luyện"},{"hanzi":"演习","pinyin":"yǎnxí","vi":"diễn tập"},{"hanzi":"军队","pinyin":"jūnduì","vi":"quân đội"}],"traditional":"練兵"},{"id":"炼钢","hanzi":"炼钢","pinyin":"liàngāng","meaning_vi":"luyện thép","explanation":"炼 (tinh luyện/rèn giũa) + 钢 (钢).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"他在工厂炼钢。","pinyin":"Tā zài gōngchǎng liàngāng.","vi":"Anh ấy luyện thép trong nhà máy."},{"type":"simple","zh":"这家钢厂改用电炉炼钢后排放大幅减少。","pinyin":"Zhè jiā gāngchǎng gǎiyòng diànlú liàngāng hòu páifàng dàfú jiǎnshǎo.","vi":"Nhà máy thép này sau khi chuyển sang luyện thép bằng lò điện đã giảm mạnh lượng khí thải."},{"type":"compound","zh":"炼钢既需要高温，又需要精确控制碳含量。","pinyin":"Liàngāng jì xūyào gāowēn, yòu xūyào jīngquè kòngzhì tàn hánliàng.","vi":"Luyện thép vừa cần nhiệt độ cao, vừa cần kiểm soát chính xác hàm lượng carbon."}],"related":[{"hanzi":"钢铁","pinyin":"gāngtiě","vi":"sắt thép"},{"hanzi":"冶炼","pinyin":"yěliàn","vi":"luyện kim"},{"hanzi":"钢厂","pinyin":"gāngchǎng","vi":"nhà máy thép"}],"traditional":"煉鋼"},{"id":"链条","hanzi":"链条","pinyin":"liàntiáo","meaning_vi":"dây xích, chuỗi liên kết","explanation":"链 (dây xích/chuỗi) + 条 (điều khoản/mạch lạc).","hsk_level":"7-9","tags":["danh-tu","do-vat"],"image":"⛓️","examples":[{"type":"basic","zh":"自行车链条断了。","pinyin":"Zìxíngchē liàntiáo duàn le.","vi":"Xích xe đạp bị đứt rồi."},{"type":"simple","zh":"这家企业打通了从种植到销售的整个产业链条。","pinyin":"Zhè jiā qǐyè dǎtōngle cóng zhòngzhí dào xiāoshòu de zhěnggè chǎnyè liàntiáo.","vi":"Doanh nghiệp này đã kết nối toàn bộ chuỗi sản xuất từ trồng trọt đến tiêu thụ."},{"type":"compound","zh":"如果链条长期不上油，骑起来就会咔咔作响。","pinyin":"Rúguǒ liàntiáo chángqī bú shàng yóu, qí qǐlái jiù huì kā kā zuò xiǎng.","vi":"Nếu xích lâu ngày không tra dầu, khi đạp sẽ kêu lạch cạch."}],"related":[{"hanzi":"链子","pinyin":"liànzi","vi":"dây xích"},{"hanzi":"环节","pinyin":"huánjié","vi":"khâu"},{"hanzi":"产业链","pinyin":"chǎnyèliàn","vi":"chuỗi ngành"}],"traditional":"鏈條"},{"id":"连带","hanzi":"连带","pinyin":"liándài","meaning_vi":"liên đới, kéo theo","explanation":"连 (liên tiếp/kết nối) + 带 (mang theo).","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🔗","examples":[{"type":"basic","zh":"他的失误连带影响了全组。","pinyin":"Tā de shīwù liándài yǐngxiǎngle quán zǔ.","vi":"Sai sót của anh ấy kéo theo ảnh hưởng đến cả nhóm."},{"type":"simple","zh":"物业公司因管理失职被判承担连带赔偿责任。","pinyin":"Wùyè gōngsī yīn guǎnlǐ shīzhí bèi pàn chéngdān liándài péicháng zérèn.","vi":"Công ty quản lý tòa nhà vì lơ là quản lý đã bị tuyên phải chịu trách nhiệm bồi thường liên đới."},{"type":"compound","zh":"如果借款人还不上钱，担保人就要负连带责任。","pinyin":"Rúguǒ jièkuǎnrén huán bú shàng qián, dānbǎorén jiùyào fù liándài zérèn.","vi":"Nếu người vay không trả được tiền, người bảo lãnh phải chịu trách nhiệm liên đới."}],"related":[{"hanzi":"连带责任","pinyin":"liándàizérèn","vi":"trách nhiệm liên đới"},{"hanzi":"牵连","pinyin":"qiānlián","vi":"liên lụy"},{"hanzi":"附带","pinyin":"fùdài","vi":"kèm theo"}],"traditional":"連帶"},{"id":"联合声明","hanzi":"联合声明","pinyin":"liánhéshēngmíng","meaning_vi":"tuyên bố chung","explanation":"联合 (liên hợp – cùng nhau) + 声明 (thanh minh – tuyên bố) → tuyên bố chung giữa hai hay nhiều bên, quốc gia. VD: 发表联合声明.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"两国发表联合声明。","pinyin":"Liǎngguó fābiǎo liánhéshēngmíng.","vi":"Hai nước ra tuyên bố chung."},{"type":"simple","zh":"五家航空公司在会后签署了一份联合声明。","pinyin":"Wǔ jiā hángkōng gōngsī zài huì hòu qiānshǔle yí fèn liánhéshēngmíng.","vi":"Năm hãng hàng không đã ký một bản tuyên bố chung sau cuộc họp."},{"type":"compound","zh":"虽然双方发表了联合声明，但是分歧并没有完全消除。","pinyin":"Suīrán shuāngfāng fābiǎole liánhéshēngmíng, dànshì fēnqí bìng méiyǒu wánquán xiāochú.","vi":"Tuy hai bên đã ra tuyên bố chung, nhưng bất đồng vẫn chưa hoàn toàn được xóa bỏ."}],"related":[{"hanzi":"声明","pinyin":"shēngmíng","vi":"tuyên bố"},{"hanzi":"联合","pinyin":"liánhé","vi":"liên hợp"},{"hanzi":"公报","pinyin":"gōngbào","vi":"thông cáo"}],"traditional":"聯合聲明"},{"id":"廉价","hanzi":"廉价","pinyin":"liánjià","meaning_vi":"giá rẻ","explanation":"廉 (liêm khiết/giá rẻ) + 价 (价).","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"这件外套很廉价。","pinyin":"Zhè jiàn wàitào hěn liánjià.","vi":"Chiếc áo khoác này rất rẻ."},{"type":"simple","zh":"超市门口摆着一排廉价的塑料拖鞋。","pinyin":"Chāoshì ménkǒu bǎizhe yìpái liánjià de sùliào tuōxié.","vi":"Trước cửa siêu thị bày một dãy dép nhựa giá rẻ."},{"type":"compound","zh":"虽然这家店的商品很廉价，但是质量并不差。","pinyin":"Suīrán zhè jiā diàn de shāngpǐn hěn liánjià, dànshì zhìliàng bìng búchà.","vi":"Tuy hàng hóa của cửa hàng này rất rẻ, nhưng chất lượng không hề tệ."}],"related":[{"hanzi":"便宜","pinyin":"piányi","vi":"rẻ"},{"hanzi":"低价","pinyin":"dījià","vi":"giá thấp"},{"hanzi":"昂贵","pinyin":"ángguì","vi":"đắt đỏ"}],"traditional":"廉價"},{"id":"联结","hanzi":"联结","pinyin":"liánjié","meaning_vi":"kết nối, gắn kết","explanation":"联 (liên hợp/liên lạc) + 结 (kết hợp/kết tinh).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔗","examples":[{"type":"basic","zh":"音乐联结了我们。","pinyin":"Yīnyuè liánjiéle wǒmen.","vi":"Âm nhạc đã gắn kết chúng tôi."},{"type":"simple","zh":"这座新桥把两岸的村庄联结在一起。","pinyin":"Zhè zuò xīn qiáo bǎ liǎng'àn de cūnzhuāng liánjié zài yìqǐ.","vi":"Cây cầu mới này nối liền các làng hai bên bờ sông."},{"type":"compound","zh":"因为有共同的回忆，所以老同学之间的感情一直紧紧联结着。","pinyin":"Yīnwèi yǒu gòngtóng de huíyì, suǒyǐ lǎo tóngxué zhījiān de gǎnqíng yìzhí jǐnjǐn liánjié zhe.","vi":"Vì có chung những kỷ niệm nên tình cảm giữa các bạn học cũ luôn gắn bó chặt chẽ."}],"related":[{"hanzi":"连接","pinyin":"liánjiē","vi":"kết nối"},{"hanzi":"联系","pinyin":"liánxì","vi":"liên hệ"},{"hanzi":"纽带","pinyin":"niǔdài","vi":"sợi dây gắn kết"}],"traditional":"聯結"},{"id":"廉洁","hanzi":"廉洁","pinyin":"liánjié","meaning_vi":"liêm khiết, trong sạch","explanation":"廉 (liêm khiết/giá rẻ) + 洁 (sạch sẽ/thuần khiết).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"⚖️","examples":[{"type":"basic","zh":"他一生为官廉洁。","pinyin":"Tā yìshēng wéi guān liánjié.","vi":"Cả đời làm quan ông ấy đều liêm khiết."},{"type":"simple","zh":"这位局长从不收礼，以廉洁出名。","pinyin":"Zhè wèi júzhǎng cóng bù shōulǐ, yǐ liánjié chūmíng.","vi":"Vị cục trưởng này không bao giờ nhận quà, nổi tiếng vì liêm khiết."},{"type":"compound","zh":"只要干部个个廉洁奉公，群众就会信任政府。","pinyin":"Zhǐyào gànbù gègè liánjié fènggōng, qúnzhòng jiù huì xìnrèn zhèngfǔ.","vi":"Chỉ cần cán bộ ai cũng liêm khiết vì việc công, quần chúng sẽ tin tưởng chính quyền."}],"related":[{"hanzi":"清廉","pinyin":"qīnglián","vi":"thanh liêm"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"tham nhũng"},{"hanzi":"廉政","pinyin":"liánzhèng","vi":"liêm chính"}],"traditional":"廉潔"},{"id":"连任","hanzi":"连任","pinyin":"liánrèn","meaning_vi":"tái đắc cử, giữ chức nhiệm kỳ tiếp theo","explanation":"连 (liên tiếp/kết nối) + 任 (nhiệm vụ/bổ nhiệm).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👔","examples":[{"type":"basic","zh":"她成功连任市长。","pinyin":"Tā chénggōng liánrèn shìzhǎng.","vi":"Bà ấy đã tái đắc cử thị trưởng thành công."},{"type":"simple","zh":"老张在上周的选举中连任了业主委员会主任。","pinyin":"Lǎo Zhāng zài shàngzhōu de xuǎnjǔ zhōng liánrènle yèzhǔ wěiyuánhuì zhǔrèn.","vi":"Trong cuộc bầu cử tuần trước, ông Trương tiếp tục giữ chức chủ nhiệm ban quản trị tòa nhà."},{"type":"compound","zh":"如果这次能够连任，他就打算继续推进养老改革。","pinyin":"Rúguǒ zhè cì nénggòu liánrèn, tā jiù dǎsuàn jìxù tuījìn yǎnglǎo gǎigé.","vi":"Nếu lần này được tái đắc cử, ông ấy dự định tiếp tục thúc đẩy cải cách hưu trí."}],"related":[{"hanzi":"任期","pinyin":"rènqī","vi":"nhiệm kỳ"},{"hanzi":"当选","pinyin":"dāngxuǎn","vi":"đắc cử"},{"hanzi":"卸任","pinyin":"xièrèn","vi":"mãn nhiệm"}],"traditional":"連任"},{"id":"联网","hanzi":"联网","pinyin":"liánwǎng","meaning_vi":"kết nối mạng","explanation":"联 (liên hợp/liên lạc) + 网 (mạng lưới).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"这台电视可以联网。","pinyin":"Zhè tái diànshì kěyǐ liánwǎng.","vi":"Chiếc tivi này có thể kết nối mạng."},{"type":"simple","zh":"山区的小学今年终于和县城图书馆联网了。","pinyin":"Shānqū de xiǎoxué jīnnián zhōngyú hé xiànchéng túshūguǎn liánwǎng le.","vi":"Năm nay trường tiểu học vùng núi cuối cùng đã nối mạng với thư viện huyện."},{"type":"compound","zh":"一旦全市医院联网，病人就不用重复做检查了。","pinyin":"Yídàn quánshì yīyuàn liánwǎng, bìngrén jiù bú yòng chóngfù zuò jiǎnchá le.","vi":"Một khi các bệnh viện toàn thành phố được nối mạng, bệnh nhân sẽ không phải xét nghiệm lại nữa."}],"related":[{"hanzi":"互联网","pinyin":"Hùliánwǎng","vi":"internet"},{"hanzi":"上网","pinyin":"shàngwǎng","vi":"lên mạng"},{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"}],"traditional":"聯網"},{"id":"连夜","hanzi":"连夜","pinyin":"liányè","meaning_vi":"ngay trong đêm, suốt đêm","explanation":"连 (liên tiếp/kết nối) + 夜 (ban đêm).","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🦉","examples":[{"type":"basic","zh":"他们连夜赶回了家。","pinyin":"Tāmen liányè gǎn huíle jiā.","vi":"Họ đã vội vã về nhà ngay trong đêm."},{"type":"simple","zh":"救援队连夜把物资运到了受灾的村子。","pinyin":"Jiùyuánduì liányè bǎ wùzī yùn dàole shòuzāi de cūnzi.","vi":"Đội cứu hộ đã chở hàng cứu trợ đến ngôi làng bị nạn ngay trong đêm."},{"type":"compound","zh":"因为明天一早要交方案，所以我们只好连夜修改。","pinyin":"Yīnwèi míngtiān yìzǎo yào jiāo fāng'àn, suǒyǐ wǒmen zhǐhǎo liányè xiūgǎi.","vi":"Vì sáng sớm mai phải nộp phương án nên chúng tôi đành sửa suốt đêm."}],"related":[{"hanzi":"通宵","pinyin":"tōngxiāo","vi":"suốt đêm"},{"hanzi":"熬夜","pinyin":"áoyè","vi":"thức khuya"},{"hanzi":"连日","pinyin":"liánrì","vi":"liên tục nhiều ngày"}],"traditional":"連夜"},{"id":"连载","hanzi":"连载","pinyin":"liánzǎi","meaning_vi":"đăng nhiều kỳ liên tiếp (truyện/báo)","explanation":"连 (liên tiếp/kết nối) + 载 (ghi chép/chuyên chở).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📰","examples":[{"type":"basic","zh":"这部小说正在连载。","pinyin":"Zhè bù xiǎoshuō zhèngzài liánzǎi.","vi":"Cuốn tiểu thuyết này đang được đăng nhiều kỳ."},{"type":"simple","zh":"他的武侠故事在晚报上连载了整整两年。","pinyin":"Tā de wǔxiá gùshi zài wǎn bàoshàng liánzǎile zhěngzhěng liǎng nián.","vi":"Truyện võ hiệp của ông ấy được đăng nhiều kỳ trên báo chiều suốt hai năm."},{"type":"compound","zh":"漫画一开始在网上连载，就吸引了大批年轻读者。","pinyin":"Mànhuà yì kāishǐ zài wǎngshàng liánzǎi, jiù xīyǐnle dàpī niánqīng dúzhě.","vi":"Bộ truyện tranh vừa bắt đầu đăng kỳ trên mạng đã thu hút đông đảo độc giả trẻ."}],"related":[{"hanzi":"小说","pinyin":"xiǎoshuō","vi":"tiểu thuyết"},{"hanzi":"刊登","pinyin":"kāndēng","vi":"đăng báo"},{"hanzi":"连续剧","pinyin":"liánxùjù","vi":"phim nhiều tập"}],"traditional":"連載"},{"id":"凉爽","hanzi":"凉爽","pinyin":"liángshuǎng","meaning_vi":"mát mẻ dễ chịu","explanation":"凉 (mát) + 爽 (sảng khoái/thẳng thắn).","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🍃","examples":[{"type":"basic","zh":"今晚的风很凉爽。","pinyin":"Jīnwǎn de fēng hěn liángshuǎng.","vi":"Gió tối nay rất mát mẻ."},{"type":"simple","zh":"雨后的山谷格外凉爽，到处是青草的味道。","pinyin":"Yǔ hòu de shāngǔ géwài liángshuǎng, dàochù shì qīngcǎo de wèidao.","vi":"Thung lũng sau mưa đặc biệt mát mẻ, khắp nơi thoang thoảng mùi cỏ non."},{"type":"compound","zh":"既然傍晚已经凉爽了，我们就出去散散步吧。","pinyin":"Jìrán bàngwǎn yǐjīng liángshuǎng le, wǒmen jiù chūqù sàn sanbù ba.","vi":"Chiều tối đã mát rồi, chúng ta ra ngoài đi dạo một chút nhé."}],"related":[{"hanzi":"凉快","pinyin":"liángkuai","vi":"mát mẻ"},{"hanzi":"清爽","pinyin":"qīngshuǎng","vi":"mát mẻ dễ chịu"},{"hanzi":"闷热","pinyin":"mēnrè","vi":"oi bức"}],"traditional":"涼爽"},{"id":"良性","hanzi":"良性","pinyin":"liángxìng","meaning_vi":"lành tính (khối u / phát triển tích cực)","explanation":"良 (tốt đẹp/lương thiện) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"✅","examples":[{"type":"basic","zh":"医生说肿瘤是良性的。","pinyin":"Yīshēng shuō zhǒngliú shì liángxìng de.","vi":"Bác sĩ nói khối u là lành tính."},{"type":"simple","zh":"两家公司之间的良性竞争提高了服务水平。","pinyin":"Liǎng jiā gōngsī zhījiān de liángxìng jìngzhēng tígāole fúwù shuǐpíng.","vi":"Sự cạnh tranh lành mạnh giữa hai công ty đã nâng cao chất lượng dịch vụ."},{"type":"compound","zh":"虽然检查结果是良性的，但是医生仍建议他定期复查。","pinyin":"Suīrán jiǎnchá jiéguǒ shì liángxìng de, dànshì yīshēng réng jiànyì tā dìngqī fùchá.","vi":"Tuy kết quả kiểm tra là lành tính, nhưng bác sĩ vẫn khuyên anh ấy tái khám định kỳ."}],"related":[{"hanzi":"恶性","pinyin":"èxìng","vi":"ác tính"},{"hanzi":"良性肿瘤","pinyin":"liángxìngzhǒngliú","vi":"khối u lành tính"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"lành mạnh"}]},{"id":"良性循环","hanzi":"良性循环","pinyin":"liángxìngxúnhuán","meaning_vi":"vòng tuần hoàn tích cực/lành mạnh","explanation":"良性 (lương tính – tính tốt, lành) + 循环 (tuần hoàn – vòng lặp) → vòng tuần hoàn tích cực; trái nghĩa 恶性循环 (vòng luẩn quẩn).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","xa-hoi"],"image":"♻️","examples":[{"type":"basic","zh":"这形成了良性循环。","pinyin":"Zhè xíng chéngle liángxìngxúnhuán.","vi":"Điều này đã tạo thành một vòng tuần hoàn tích cực."},{"type":"simple","zh":"多读书多思考，学习就会进入良性循环。","pinyin":"Duō dúshū duō sīkǎo, xuéxí jiù huì jìnrù liángxìngxúnhuán.","vi":"Đọc nhiều nghĩ nhiều thì việc học sẽ đi vào vòng tuần hoàn tích cực."},{"type":"compound","zh":"因为顾客口碑越来越好，所以小店的生意走上了良性循环。","pinyin":"Yīnwèi gùkè kǒubēi yuèláiyuè hǎo, suǒyǐ xiǎodiàn de shēngyi zǒushàngle liángxìngxúnhuán.","vi":"Vì tiếng lành của khách hàng ngày càng tốt nên việc kinh doanh của tiệm nhỏ đã đi vào vòng tuần hoàn tích cực."}],"related":[{"hanzi":"恶性循环","pinyin":"èxìngxúnhuán","vi":"vòng luẩn quẩn"},{"hanzi":"循环","pinyin":"xúnhuán","vi":"tuần hoàn"},{"hanzi":"良性","pinyin":"liángxìng","vi":"lành tính"}],"traditional":"良性循環"},{"id":"良药苦口","hanzi":"良药苦口","pinyin":"liángyào-kǔkǒu","meaning_vi":"thuốc đắng dã tật","explanation":"良 (tốt đẹp/lương thiện) + 药 (thuốc) + 苦 (đắng) + 口 (口).","hsk_level":"7-9","tags":["thanh-ngu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"良药苦口利于病。","pinyin":"Liángyàokǔkǒu lìyú bìng.","vi":"Thuốc đắng dã tật."},{"type":"simple","zh":"老师的批评虽然刺耳，却是良药苦口。","pinyin":"Lǎoshī de pīpíng suīrán cì'ěr, quèshì liángyàokǔkǒu.","vi":"Lời phê bình của thầy tuy chói tai nhưng đúng là thuốc đắng dã tật."},{"type":"compound","zh":"良药苦口，忠言逆耳，所以你要认真听取朋友的意见。","pinyin":"Liángyàokǔkǒu, zhōngyán nì'ěr, suǒyǐ nǐ yào rènzhēn tīngqǔ péngyou de yìjiàn.","vi":"Thuốc đắng dã tật, sự thật mất lòng, vì vậy bạn nên nghiêm túc lắng nghe ý kiến của bạn bè."}],"related":[{"hanzi":"忠言逆耳","pinyin":"zhōngyánnì'ěr","vi":"lời thật mất lòng"},{"hanzi":"良药","pinyin":"liángyào","vi":"thuốc tốt"},{"hanzi":"苦口婆心","pinyin":"kǔkǒupóxīn","vi":"khuyên nhủ hết lời"}],"traditional":"良藥苦口"},{"id":"寥寥无几","hanzi":"寥寥无几","pinyin":"liáoliáo-wújǐ","meaning_vi":"lác đác vài người/cái, rất ít","explanation":"寥 (thưa thớt/vắng vẻ) + 寥 (thưa thớt/vắng vẻ) + 无 (không có) + 几 (mấy).","hsk_level":"7-9","tags":["thanh-ngu","so-luong"],"image":"🤏","examples":[{"type":"basic","zh":"观众寥寥无几。","pinyin":"Guānzhòng liáoliáowújǐ.","vi":"Khán giả lác đác chẳng có mấy người."},{"type":"simple","zh":"下雨天的夜市上，行人寥寥无几。","pinyin":"Xià yǔtiān de yèshì shàng, xíngrén liáoliáowújǐ.","vi":"Ở chợ đêm ngày mưa, người qua lại thưa thớt chẳng mấy ai."},{"type":"compound","zh":"虽然报名的人很多，但是坚持到最后的寥寥无几。","pinyin":"Suīrán bàomíng de rén hěn duō, dànshì jiānchí dào zuìhòu de liáoliáowújǐ.","vi":"Tuy người đăng ký rất đông, nhưng người kiên trì đến cuối cùng thì chẳng được mấy ai."}],"related":[{"hanzi":"屈指可数","pinyin":"qūzhǐkěshǔ","vi":"đếm trên đầu ngón tay"},{"hanzi":"稀少","pinyin":"xīshǎo","vi":"thưa thớt"},{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"vô số"}],"traditional":"寥寥無幾"},{"id":"燎原","hanzi":"燎原","pinyin":"liáoyuán","meaning_vi":"cháy lan khắp cánh đồng (phong trào lan rộng)","explanation":"燎 (cháy lan) + 原 (nguyên lý/nguyên tắc).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔥","examples":[{"type":"basic","zh":"星星之火，可以燎原。","pinyin":"Xīngxīng zhī huǒ, kěyǐ liáoyuán.","vi":"Một đốm lửa nhỏ có thể thiêu cháy cả cánh đồng."},{"type":"simple","zh":"这场改革运动很快以燎原之势席卷全国。","pinyin":"Zhè chǎng gǎigé yùndòng hěn kuài yǐ liáoyuán zhī shì xíjuǎn quánguó.","vi":"Phong trào cải cách này nhanh chóng lan rộng khắp cả nước như lửa cháy đồng."},{"type":"compound","zh":"一旦群众被发动起来，革命的火焰就会燎原。","pinyin":"Yídàn qúnzhòng bèi fādòng qǐlái, gémìng de huǒyàn jiù huì liáoyuán.","vi":"Một khi quần chúng được vận động, ngọn lửa cách mạng sẽ lan khắp nơi."}],"related":[{"hanzi":"星火燎原","pinyin":"xīnghuǒliáoyuán","vi":"đốm lửa nhỏ cháy lan cánh đồng"},{"hanzi":"蔓延","pinyin":"mànyán","vi":"lan rộng"},{"hanzi":"燃烧","pinyin":"ránshāo","vi":"cháy"}]},{"id":"疗养","hanzi":"疗养","pinyin":"liáoyǎng","meaning_vi":"điều dưỡng, nghỉ dưỡng phục hồi sức khỏe","explanation":"疗 (điều trị) + 养 (nuôi dưỡng/tu dưỡng).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他去海边疗养了。","pinyin":"Tā qù hǎibiān liáoyǎng le.","vi":"Ông ấy đã ra bờ biển để an dưỡng."},{"type":"simple","zh":"手术以后，爷爷在山里的疗养院住了三个月。","pinyin":"Shǒushù yǐhòu, yéye zài shān lǐ de liáoyǎngyuàn zhùle sān gèyuè.","vi":"Sau ca phẫu thuật, ông nội ở viện điều dưỡng trên núi ba tháng."},{"type":"compound","zh":"只要安心疗养一段时间，你的身体就能慢慢恢复。","pinyin":"Zhǐyào ānxīn liáoyǎng yí duàn shíjiān, nǐ de shēntǐ jiù néng mànmàn huīfù.","vi":"Chỉ cần yên tâm điều dưỡng một thời gian, sức khỏe của bạn sẽ dần hồi phục."}],"related":[{"hanzi":"疗养院","pinyin":"liáoyǎngyuàn","vi":"viện điều dưỡng"},{"hanzi":"休养","pinyin":"xiūyǎng","vi":"nghỉ dưỡng"},{"hanzi":"康复","pinyin":"kāngfù","vi":"hồi phục"}],"traditional":"療養"},{"id":"裂痕","hanzi":"裂痕","pinyin":"lièhén","meaning_vi":"vết nứt, sự rạn nứt tình cảm","explanation":"裂 (nứt vỡ/chia rẽ) + 痕 (dấu vết).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"两人之间有了裂痕。","pinyin":"Liǎng rén zhījiān yǒule lièhén.","vi":"Giữa hai người đã có rạn nứt."},{"type":"simple","zh":"地震过后，老房子的墙上出现了几道裂痕。","pinyin":"Dìzhèn guòhòu, lǎo fángzi de qiáng shàng chūxiànle jǐ dào lièhén.","vi":"Sau trận động đất, trên tường ngôi nhà cũ xuất hiện mấy vết nứt."},{"type":"compound","zh":"感情一旦出现裂痕，就很难恢复到从前的样子。","pinyin":"Gǎnqíng yídàn chūxiàn lièhén, jiù hěn nán huīfù dào cóngqián de yàngzi.","vi":"Tình cảm một khi đã rạn nứt thì rất khó trở lại như xưa."}],"related":[{"hanzi":"裂缝","pinyin":"lièfèng","vi":"khe nứt"},{"hanzi":"隔阂","pinyin":"géhé","vi":"khoảng cách"},{"hanzi":"破裂","pinyin":"pòliè","vi":"rạn vỡ"}]},{"id":"猎奇","hanzi":"猎奇","pinyin":"lièqí","meaning_vi":"săn tìm điều kỳ lạ mới mẻ","explanation":"猎 (săn bắn) + 奇 (kỳ diệu/kỳ lạ).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"🧐","examples":[{"type":"basic","zh":"他写文章爱猎奇。","pinyin":"Tā xiě wénzhāng ài lièqí.","vi":"Anh ấy viết bài thích săn chuyện lạ."},{"type":"simple","zh":"有些游客到古镇只是为了猎奇拍照。","pinyin":"Yǒuxiē yóukè dào gǔzhèn zhǐshì wèile lièqí pāizhào.","vi":"Một số du khách đến thị trấn cổ chỉ để tìm cái lạ mà chụp ảnh."},{"type":"compound","zh":"与其用猎奇的标题吸引眼球，不如认真写好内容。","pinyin":"Yǔqí yòng lièqí de biāotí xīyǐn yǎnqiú, bùrú rènzhēn xiě hǎo nèiróng.","vi":"Thay vì dùng tiêu đề giật gân để câu view, chi bằng nghiêm túc viết cho tốt nội dung."}],"related":[{"hanzi":"好奇","pinyin":"hàoqí","vi":"tò mò"},{"hanzi":"新奇","pinyin":"xīnqí","vi":"mới lạ"},{"hanzi":"猎奇心理","pinyin":"lièqíxīnlǐ","vi":"tâm lý tò mò cái lạ"}],"traditional":"獵奇"},{"id":"烈士","hanzi":"烈士","pinyin":"lièshì","meaning_vi":"liệt sĩ","explanation":"烈 (mãnh liệt/anh liệt) + 士 (nhân sĩ/chiến sĩ).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"🎖️","examples":[{"type":"basic","zh":"我们去祭奠烈士。","pinyin":"Wǒmen qù jìdiàn lièshì.","vi":"Chúng tôi đi viếng các liệt sĩ."},{"type":"simple","zh":"清明节那天，学生们在烈士陵园献上了鲜花。","pinyin":"Qīngmíngjié nà tiān, xuéshengmen zài lièshì língyuán xiànshàngle xiānhuā.","vi":"Ngày Thanh minh, học sinh đã dâng hoa tại nghĩa trang liệt sĩ."},{"type":"compound","zh":"虽然烈士们已经离开了，但是他们的精神永远激励着后人。","pinyin":"Suīrán lièshìmen yǐjīng líkāi le, dànshì tāmen de jīngshén yǒngyuǎn jīlìzhe hòurén.","vi":"Tuy các liệt sĩ đã ra đi, nhưng tinh thần của họ mãi mãi cổ vũ thế hệ sau."}],"related":[{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"},{"hanzi":"牺牲","pinyin":"xīshēng","vi":"hy sinh"},{"hanzi":"烈士陵园","pinyin":"lièshìlíngyuán","vi":"nghĩa trang liệt sĩ"}]},{"id":"流传千古","hanzi":"流传千古","pinyin":"liúchuán-qiāngǔ","meaning_vi":"lưu truyền muôn đời","explanation":"流 (lưu truyền/dòng chảy) + 传 (传) + 千 (nghìn (1.000)) + 古 (古).","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"这首诗流传千古。","pinyin":"Zhè shǒu shī liúchuánqiāngǔ.","vi":"Bài thơ này lưu truyền muôn đời."},{"type":"simple","zh":"屈原的爱国故事流传千古，人人皆知。","pinyin":"Qūyuán de àiguó gùshi liúchuánqiāngǔ, rénrén jiē zhī.","vi":"Câu chuyện yêu nước của Khuất Nguyên lưu truyền muôn đời, ai ai cũng biết."},{"type":"compound","zh":"因为文字优美、情感真挚，所以这篇散文得以流传千古。","pinyin":"Yīnwèi wénzì yōuměi, qínggǎn zhēnzhì, suǒyǐ zhè piān sǎnwén déyǐ liúchuánqiāngǔ.","vi":"Vì văn chương đẹp đẽ, tình cảm chân thành nên bài tản văn này được lưu truyền muôn đời."}],"related":[{"hanzi":"流传","pinyin":"liúchuán","vi":"lưu truyền"},{"hanzi":"千古","pinyin":"qiāngǔ","vi":"ngàn đời"},{"hanzi":"万古流芳","pinyin":"wàngǔliúfāng","vi":"tiếng thơm muôn thuở"}],"traditional":"流傳千古"},{"id":"流露","hanzi":"流露","pinyin":"liúlù","meaning_vi":"bộc lộ, để lộ (cảm xúc tự nhiên)","explanation":"流 (lưu truyền/dòng chảy) + 露 (tiết lộ/sương mù).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"她眼里流露出喜悦。","pinyin":"Tā yǎn lǐ liúlù chū xǐyuè.","vi":"Trong mắt cô ấy lộ rõ niềm vui."},{"type":"simple","zh":"听到儿子考上大学，父亲的脸上流露出少见的笑容。","pinyin":"Tīngdào érzi kǎoshàng dàxué, fùqīn de liǎn shàngliú lùchū shǎojiàn de xiàoróng.","vi":"Nghe tin con trai đỗ đại học, trên mặt người cha lộ ra nụ cười hiếm thấy."},{"type":"compound","zh":"他虽然嘴上不说，但是字里行间流露着对家乡的思念。","pinyin":"Tā suīrán zuǐ shàng bù shuō, dànshì zì lǐ hángjiān liúlùzhe duì jiāxiāng de sīniàn.","vi":"Tuy anh ấy không nói ra, nhưng giữa các dòng chữ đều toát lên nỗi nhớ quê hương."}],"related":[{"hanzi":"表露","pinyin":"biǎolù","vi":"bộc lộ"},{"hanzi":"显露","pinyin":"xiǎnlù","vi":"lộ ra"},{"hanzi":"掩饰","pinyin":"yǎnshì","vi":"che giấu"}]},{"id":"流失","hanzi":"流失","pinyin":"liúshī","meaning_vi":"thất thoát, chảy mất (nhân tài/đất đai)","explanation":"流 (lưu truyền/dòng chảy) + 失 (mất đi/sai sót).","hsk_level":"7-9","tags":["dong-tu"],"image":"📉","examples":[{"type":"basic","zh":"人才流失很严重。","pinyin":"Réncáiliúshī hěn yánzhòng.","vi":"Tình trạng chảy máu chất xám rất nghiêm trọng."},{"type":"simple","zh":"大量砍伐树木导致山坡上的水土不断流失。","pinyin":"Dàliàng kǎnfá shùmù dǎozhì shānpō shàng de shuǐtǔ búduàn liúshī.","vi":"Chặt phá cây cối hàng loạt khiến đất đai trên sườn đồi liên tục bị xói mòn."},{"type":"compound","zh":"如果待遇长期得不到改善，公司的骨干就会流失。","pinyin":"Rúguǒ dàiyù chángqī débúdào gǎishàn, gōngsī de gǔgàn jiù huì liúshī.","vi":"Nếu đãi ngộ lâu dài không được cải thiện, nhân sự nòng cốt của công ty sẽ bỏ đi."}],"related":[{"hanzi":"人才流失","pinyin":"réncáiliúshī","vi":"chảy máu chất xám"},{"hanzi":"丢失","pinyin":"diūshī","vi":"đánh mất"},{"hanzi":"水土流失","pinyin":"shuǐtǔliúshī","vi":"xói mòn đất"}]},{"id":"留守","hanzi":"留守","pinyin":"liúshǒu","meaning_vi":"ở lại trông coi (trẻ em ở quê khi bố mẹ đi làm xa)","explanation":"留 (ở lại) + 守 (tuân thủ/bảo vệ).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏡","examples":[{"type":"basic","zh":"爷爷在老家留守。","pinyin":"Yéye zài lǎojiā liúshǒu.","vi":"Ông nội ở lại quê trông nhà."},{"type":"simple","zh":"村里的留守儿童大多跟着祖父母生活。","pinyin":"Cūnlǐ de liúshǒu értóng dàduō gēnzhe zǔfùmǔ shēnghuó.","vi":"Trẻ em ở lại làng phần lớn sống cùng ông bà."},{"type":"compound","zh":"父母去城里打工了，所以小明只好留守在乡下。","pinyin":"Fùmǔ qù chénglǐ dǎgōng le, suǒyǐ xiǎo míng zhǐhǎo liúshǒu zài xiāngxià.","vi":"Bố mẹ lên thành phố làm thuê nên Tiểu Minh đành ở lại quê."}],"related":[{"hanzi":"留守儿童","pinyin":"liúshǒu'értóng","vi":"trẻ em bị bỏ lại"},{"hanzi":"外出打工","pinyin":"wàichūdǎgōng","vi":"đi làm ăn xa"},{"hanzi":"看守","pinyin":"kānshǒu","vi":"trông coi"}]},{"id":"流通","hanzi":"流通","pinyin":"liútōng","meaning_vi":"lưu thông (hàng hóa/tiền tệ)","explanation":"流 (lưu truyền/dòng chảy) + 通 (thông suốt/phổ biến).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🔄","examples":[{"type":"basic","zh":"这种硬币已停止流通。","pinyin":"Zhè zhǒng yìngbì yǐ tíngzhǐ liútōng.","vi":"Loại tiền xu này đã ngừng lưu hành."},{"type":"simple","zh":"新修的公路加快了山区农产品的流通。","pinyin":"Xīnxiū de gōnglù jiākuàile shānqū nóngchǎnpǐn de liútōng.","vi":"Con đường mới làm đã đẩy nhanh việc lưu thông nông sản vùng núi."},{"type":"compound","zh":"只要商品流通顺畅，物价就能保持稳定。","pinyin":"Zhǐyào shāngpǐn liútōng shùnchàng, wùjià jiù néng bǎochí wěndìng.","vi":"Chỉ cần hàng hóa lưu thông thông suốt, giá cả sẽ giữ được ổn định."}],"related":[{"hanzi":"货币","pinyin":"huòbì","vi":"tiền tệ"},{"hanzi":"流动","pinyin":"liúdòng","vi":"lưu động"},{"hanzi":"交易","pinyin":"jiāoyì","vi":"giao dịch"}]},{"id":"留学生","hanzi":"留学生","pinyin":"liúxuéshēng","meaning_vi":"du học sinh","explanation":"留 (ở lại) + 学 (học thuật/học thuyết) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","con-nguoi"],"image":"🎓","examples":[{"type":"basic","zh":"她是越南留学生。","pinyin":"Tā shì Yuènán liúxuéshēng.","vi":"Cô ấy là du học sinh Việt Nam."},{"type":"simple","zh":"这所大学每年接收两千多名外国留学生。","pinyin":"Zhè suǒ dàxué měinián jiēshōu liǎng qiān duō míng wàiguó liúxuéshēng.","vi":"Trường đại học này mỗi năm tiếp nhận hơn hai nghìn du học sinh nước ngoài."},{"type":"compound","zh":"刚来的留学生一到宿舍，就忙着办理手机卡。","pinyin":"Gāng lái de liúxuéshēng yí dào sùshè, jiù mángzhe bànlǐ shǒujīkǎ.","vi":"Du học sinh mới đến vừa tới ký túc xá đã vội đi làm thẻ sim điện thoại."}],"related":[{"hanzi":"留学","pinyin":"liúxué","vi":"du học"},{"hanzi":"外国人","pinyin":"wàiguórén","vi":"người nước ngoài"},{"hanzi":"交换生","pinyin":"jiāohuànshēng","vi":"sinh viên trao đổi"}],"traditional":"留學生"},{"id":"流域","hanzi":"流域","pinyin":"liúyù","meaning_vi":"lưu vực (sông)","explanation":"流 (lưu truyền/dòng chảy) + 域 (域).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌊","examples":[{"type":"basic","zh":"长江流域人口密集。","pinyin":"Chángjiāngliúyù rénkǒu mìjí.","vi":"Lưu vực sông Trường Giang dân cư đông đúc."},{"type":"simple","zh":"湄公河流域生活着几千万依靠渔业的居民。","pinyin":"Méigōnghé liúyù shēng huózhe jǐ qiānwàn yīkào yúyè de jūmín.","vi":"Ở lưu vực sông Mê Kông có hàng chục triệu cư dân sống nhờ nghề cá."},{"type":"compound","zh":"因为黄河流域土地肥沃，所以这里很早就出现了农业文明。","pinyin":"Yīnwèi Huánghéliúyù tǔdì féiwò, suǒyǐ zhèlǐ hěn zǎojiù chūxiànle nóngyè wénmíng.","vi":"Vì đất đai lưu vực sông Hoàng Hà màu mỡ nên nơi đây sớm xuất hiện nền văn minh nông nghiệp."}],"related":[{"hanzi":"长江流域","pinyin":"Chángjiāngliúyù","vi":"lưu vực Trường Giang"},{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"},{"hanzi":"上游","pinyin":"shàngyóu","vi":"thượng nguồn"}]},{"id":"脸面","hanzi":"脸面","pinyin":"liǎnmiàn","meaning_vi":"thể diện","explanation":"脸 (khuôn mặt) + 面 (diện mạo/bề mặt).","hsk_level":"7-9","tags":["danh-tu"],"image":"😎","examples":[{"type":"basic","zh":"他很爱惜脸面。","pinyin":"Tā hěn àixī liǎnmiàn.","vi":"Anh ấy rất giữ thể diện."},{"type":"simple","zh":"当着全班同学的面被批评，他觉得脸面全丢了。","pinyin":"Dāngzhe quánbān tóngxué de miàn bèi pīpíng, tā juéde liǎnmiàn quán diū le.","vi":"Bị phê bình trước mặt cả lớp, cậu ấy cảm thấy mất hết thể diện."},{"type":"compound","zh":"与其为了脸面硬撑着，不如坦白承认自己的错误。","pinyin":"Yǔqí wèile liǎnmiàn yìngchēng zhe, bùrú tǎnbái chéngrèn zìjǐ de cuòwù.","vi":"Thay vì vì thể diện mà cố gồng, chi bằng thẳng thắn thừa nhận sai lầm của mình."}],"related":[{"hanzi":"面子","pinyin":"miànzi","vi":"thể diện"},{"hanzi":"丢脸","pinyin":"diūliǎn","vi":"mất mặt"},{"hanzi":"尊严","pinyin":"zūnyán","vi":"tôn nghiêm"}],"traditional":"臉面"},{"id":"脸谱","hanzi":"脸谱","pinyin":"liǎnpǔ","meaning_vi":"lối vẽ mặt Kinh kịch, mặt nạ Kinh kịch","explanation":"脸 (khuôn mặt) + 谱.","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"红色脸谱代表忠诚。","pinyin":"Hóngsè liǎnpǔ dàibiǎo zhōngchéng.","vi":"Mặt nạ màu đỏ tượng trưng cho lòng trung thành."},{"type":"simple","zh":"孩子们在博物馆里学着给京剧脸谱涂颜色。","pinyin":"Háizimen zài bówùguǎn lǐ xuézhe gěi Jīngjù liǎnpǔ tú yánsè.","vi":"Bọn trẻ học tô màu mặt nạ Kinh kịch trong bảo tàng."},{"type":"compound","zh":"只要看一眼演员的脸谱，老戏迷就知道他演的是什么角色。","pinyin":"Zhǐyào kàn yìyǎn yǎnyuán de liǎnpǔ, lǎo xì mí jiù zhīdào tā yǎn de shì shénme juésè.","vi":"Chỉ cần liếc nhìn mặt nạ của diễn viên, người mê kịch lâu năm đã biết anh ta đóng vai gì."}],"related":[{"hanzi":"京剧","pinyin":"Jīngjù","vi":"Kinh kịch"},{"hanzi":"面具","pinyin":"miànjù","vi":"mặt nạ"},{"hanzi":"戏曲","pinyin":"xìqǔ","vi":"hí khúc"}],"traditional":"臉譜"},{"id":"两极化","hanzi":"两极化","pinyin":"liǎngjíhuà","meaning_vi":"phân cực hai đầu","explanation":"两 (hai (số lượng)) + 极 (cực đoan/tột cùng) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"↔️","examples":[{"type":"basic","zh":"观点越来越两极化。","pinyin":"Guāndiǎn yuèláiyuè liǎngjíhuà.","vi":"Quan điểm ngày càng phân cực."},{"type":"simple","zh":"这部电影上映后，观众的评价出现了两极化。","pinyin":"Zhè bù diànyǐng shàngyìng hòu, guānzhòng de píngjià chūxiànle liǎngjíhuà.","vi":"Sau khi bộ phim ra rạp, đánh giá của khán giả trở nên phân cực."},{"type":"compound","zh":"如果贫富差距继续扩大，社会就可能进一步两极化。","pinyin":"Rúguǒ pínfùchājù jìxù kuòdà, shèhuì jiù kěnéng jìnyíbù liǎngjíhuà.","vi":"Nếu khoảng cách giàu nghèo tiếp tục nới rộng, xã hội có thể càng thêm phân cực."}],"related":[{"hanzi":"两极分化","pinyin":"liǎngjífēnhuà","vi":"phân hóa hai cực"},{"hanzi":"分化","pinyin":"fēnhuà","vi":"phân hóa"},{"hanzi":"贫富差距","pinyin":"pínfùchājù","vi":"chênh lệch giàu nghèo"}],"traditional":"兩極化"},{"id":"落差","hanzi":"落差","pinyin":"luòchā","meaning_vi":"độ chênh lệch (thác nước / kỳ vọng và thực tế)","explanation":"落 (rơi rụng/thực hiện) + 差 (差).","hsk_level":"7-9","tags":["danh-tu"],"image":"📉","examples":[{"type":"basic","zh":"这个瀑布落差很大。","pinyin":"Zhè ge pùbù luòchā hěn dà.","vi":"Thác nước này có độ chênh lệch độ cao rất lớn."},{"type":"simple","zh":"刚工作时，他感到理想和现实之间有巨大的落差。","pinyin":"Gāng gōngzuò shí, tā gǎndào lǐxiǎng hé xiànshí zhījiān yǒu jùdà de luòchā.","vi":"Khi mới đi làm, anh ấy cảm thấy khoảng cách giữa lý tưởng và hiện thực rất lớn."},{"type":"compound","zh":"虽然收入比以前少了，但是她很快就适应了这种落差。","pinyin":"Suīrán shōurù bǐ yǐqián shǎo le, dànshì tā hěn kuài jiù shìyìngle zhè zhǒng luòchā.","vi":"Tuy thu nhập ít hơn trước, nhưng cô ấy nhanh chóng thích nghi với sự chênh lệch này."}],"related":[{"hanzi":"差距","pinyin":"chājù","vi":"chênh lệch"},{"hanzi":"心理落差","pinyin":"xīnlǐluòchā","vi":"hụt hẫng tâm lý"},{"hanzi":"瀑布","pinyin":"pùbù","vi":"thác nước"}]},{"id":"落户","hanzi":"落户","pinyin":"luòhù","meaning_vi":"nhập hộ khẩu, định cư lập nghiệp","explanation":"落 (rơi rụng/thực hiện) + 户 (户).","hsk_level":"7-9","tags":["dong-tu","nha-cua"],"image":"🏡","examples":[{"type":"basic","zh":"他在上海落户了。","pinyin":"Tā zài Shànghǎi luòhù le.","vi":"Anh ấy đã nhập hộ khẩu ở Thượng Hải."},{"type":"simple","zh":"这家德国汽车厂去年正式落户我们开发区。","pinyin":"Zhè jiā Déguó qìchēchǎng qùnián zhèngshì luòhù wǒmen kāifāqū.","vi":"Nhà máy ô tô Đức này năm ngoái đã chính thức đặt cơ sở tại khu phát triển của chúng tôi."},{"type":"compound","zh":"只要在本市连续工作满五年，就可以申请落户。","pinyin":"Zhǐyào zài běnshì liánxù gōngzuò mǎn wǔ nián, jiù kěyǐ shēnqǐng luòhù.","vi":"Chỉ cần làm việc liên tục đủ năm năm tại thành phố này là có thể xin nhập hộ khẩu."}],"related":[{"hanzi":"户口","pinyin":"hùkǒu","vi":"hộ khẩu"},{"hanzi":"定居","pinyin":"dìngjū","vi":"định cư"},{"hanzi":"安家","pinyin":"ānjiā","vi":"lập nghiệp"}],"traditional":"落戶"},{"id":"落幕","hanzi":"落幕","pinyin":"luòmù","meaning_vi":"hạ màn, kết thúc","explanation":"落 (rơi rụng/thực hiện) + 幕 (màn hình/hậu trường).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"运动会圆满落幕。","pinyin":"Yùndònghuì yuánmǎn luòmù.","vi":"Đại hội thể thao đã khép lại tốt đẹp."},{"type":"simple","zh":"为期十天的国际电影节昨晚在掌声中落幕。","pinyin":"Wéiqī shí tiān de Guójì diànyǐngjié zuówǎn zài zhǎngshēng zhōng luòmù.","vi":"Liên hoan phim quốc tế kéo dài mười ngày đã hạ màn tối qua trong tiếng vỗ tay."},{"type":"compound","zh":"比赛虽然已经落幕，但是球迷们久久不愿离去。","pinyin":"Bǐsài suīrán yǐjīng luòmù, dànshì qiúmímen jiǔjiǔ búyuàn líqù.","vi":"Trận đấu tuy đã kết thúc, nhưng người hâm mộ mãi không muốn ra về."}],"related":[{"hanzi":"闭幕","pinyin":"bìmù","vi":"bế mạc"},{"hanzi":"开幕","pinyin":"kāimù","vi":"khai mạc"},{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"}]},{"id":"落伍","hanzi":"落伍","pinyin":"luòwǔ","meaning_vi":"tụt hậu, lỗi thời","explanation":"落 (rơi rụng/thực hiện) + 伍 (伍).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"📉","examples":[{"type":"basic","zh":"这种观念早已落伍。","pinyin":"Zhè zhǒng guānniàn zǎoyǐ luòwǔ.","vi":"Quan niệm này đã lỗi thời từ lâu."},{"type":"simple","zh":"爷爷学会了用手机支付，一点儿也不落伍。","pinyin":"Yéye xuéhuìle yòng shǒujī zhīfù, yìdiǎnr yě bú luòwǔ.","vi":"Ông nội đã biết thanh toán bằng điện thoại, chẳng lạc hậu chút nào."},{"type":"compound","zh":"如果不及时学习新技术，我们很快就会落伍。","pinyin":"Rúguǒ bù jíshí xuéxí xīnjìshù, wǒmen hěn kuài jiù huì luòwǔ.","vi":"Nếu không kịp thời học công nghệ mới, chúng ta sẽ nhanh chóng tụt hậu."}],"related":[{"hanzi":"落后","pinyin":"luòhòu","vi":"lạc hậu"},{"hanzi":"过时","pinyin":"guòshí","vi":"lỗi thời"},{"hanzi":"时髦","pinyin":"shímáo","vi":"thời thượng"}]},{"id":"逻辑性","hanzi":"逻辑性","pinyin":"luójíxìng","meaning_vi":"tính lô-gíc","explanation":"逻 (tuần tra/lô-gíc) + 辑 (辑) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"这篇文章逻辑性强。","pinyin":"Zhè piān wénzhāng luójíxìng qiáng.","vi":"Bài viết này có tính lô-gíc cao."},{"type":"simple","zh":"律师的辩护词条理清楚，很有逻辑性。","pinyin":"Lǜshī de biànhù cí tiáolǐ qīngchu, hěn yǒu luójíxìng.","vi":"Lời bào chữa của luật sư mạch lạc rõ ràng, rất có tính lô-gíc."},{"type":"compound","zh":"他的演讲虽然很生动，但是缺乏逻辑性。","pinyin":"Tā de yǎnjiǎng suīrán hěn shēngdòng, dànshì quēfá luójíxìng.","vi":"Bài diễn thuyết của anh ấy tuy sinh động, nhưng thiếu tính lô-gíc."}],"related":[{"hanzi":"逻辑","pinyin":"luójí","vi":"lô-gíc"},{"hanzi":"条理","pinyin":"tiáolǐ","vi":"mạch lạc"},{"hanzi":"严密","pinyin":"yánmì","vi":"chặt chẽ"}],"traditional":"邏輯性"},{"id":"赖以","hanzi":"赖以","pinyin":"làiyǐ","meaning_vi":"dựa vào để (sinh tồn/phát triển)","explanation":"赖 (ỷ lại/tin cậy) + 以 (lấy).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"土地是农民赖以生存的根本。","pinyin":"Tǔdì shì nóngmín làiyǐ shēngcún de gēnběn.","vi":"Đất đai là gốc rễ để người nông dân dựa vào mà sinh tồn."},{"type":"simple","zh":"这条河是两岸居民赖以生活的水源。","pinyin":"Zhè tiáo hé shì liǎng'àn jūmín làiyǐ shēnghuó de shuǐyuán.","vi":"Con sông này là nguồn nước mà cư dân hai bờ dựa vào để sống."},{"type":"compound","zh":"一旦失去赖以发展的市场，这家工厂就难以维持下去。","pinyin":"Yídàn shīqù làiyǐ fāzhǎn de shìchǎng, zhè jiā gōngchǎng jiù nányǐ wéichí xiàqù.","vi":"Một khi mất đi thị trường dựa vào để phát triển, nhà máy này sẽ khó mà duy trì."}],"related":[{"hanzi":"依赖","pinyin":"yīlài","vi":"phụ thuộc"},{"hanzi":"赖以生存","pinyin":"làiyǐshēngcún","vi":"dựa vào để sinh tồn"},{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"}],"traditional":"賴以"},{"id":"浪潮","hanzi":"浪潮","pinyin":"làngcháo","meaning_vi":"làn sóng (công nghệ/phong trào)","explanation":"浪 (lãng phí/sóng nước) + 潮 (潮).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"数字化浪潮来了。","pinyin":"Shùzìhuà làngcháo lái le.","vi":"Làn sóng số hóa đã đến."},{"type":"simple","zh":"上世纪九十年代，一股下海经商的浪潮席卷全国。","pinyin":"Shàng shìjì jiǔshí niándài, yì gǔ xiàhǎi jīngshāng de làngcháo xíjuǎn quánguó.","vi":"Thập niên chín mươi thế kỷ trước, làn sóng bỏ việc nhà nước ra kinh doanh lan khắp cả nước."},{"type":"compound","zh":"面对人工智能的浪潮，我们既要拥抱变化，又要保持清醒。","pinyin":"Miànduì réngōngzhìnéng de làngcháo, wǒmen jì yào yōngbào biànhuà, yòu yào bǎochí qīngxǐng.","vi":"Trước làn sóng trí tuệ nhân tạo, chúng ta vừa phải đón nhận thay đổi, vừa phải giữ tỉnh táo."}],"related":[{"hanzi":"潮流","pinyin":"cháoliú","vi":"trào lưu"},{"hanzi":"浪花","pinyin":"lànghuā","vi":"bọt sóng"},{"hanzi":"热潮","pinyin":"rècháo","vi":"cơn sốt"}]},{"id":"浪花","hanzi":"浪花","pinyin":"lànghuā","meaning_vi":"bọt sóng","explanation":"浪 (lãng phí/sóng nước) + 花 (tiêu (tiền/thời gian)).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"浪花拍打着礁石。","pinyin":"Lànghuā pāidǎzhe jiāoshí.","vi":"Bọt sóng vỗ vào đá ngầm."},{"type":"simple","zh":"孩子们光着脚在沙滩上追逐白色的浪花。","pinyin":"Háizimen guāngzhe jiǎo zài shātān shàng zhuīzhú báisè de lànghuā.","vi":"Bọn trẻ đi chân trần đuổi theo những bọt sóng trắng trên bãi cát."},{"type":"compound","zh":"每当海风吹起，岸边就溅起一朵朵雪白的浪花。","pinyin":"Měidāng hǎifēng chuī qǐ, ànbiān jiù jiàn qǐ yì duǒ duǒ xuěbái de lànghuā.","vi":"Mỗi khi gió biển thổi, bên bờ lại tung lên từng đóa bọt sóng trắng xóa."}],"related":[{"hanzi":"波浪","pinyin":"bōlàng","vi":"sóng"},{"hanzi":"海浪","pinyin":"hǎilàng","vi":"sóng biển"},{"hanzi":"浪潮","pinyin":"làngcháo","vi":"làn sóng"}]},{"id":"来宾","hanzi":"来宾","pinyin":"láibīn","meaning_vi":"khách mời","explanation":"来 (lai – đến) + 宾 (tân – khách) → khách đến dự, khách mời. VD: 欢迎各位来宾.","hsk_level":"7-9","tags":["danh-tu","giao-tiep","con-nguoi"],"image":"🎖️","examples":[{"type":"basic","zh":"欢迎各位来宾！","pinyin":"Huānyíng gèwèi láibīn!","vi":"Hoan nghênh quý vị khách quý!"},{"type":"simple","zh":"礼仪小姐把来宾一一引到前排就座。","pinyin":"Lǐyí xiǎojiě bǎ láibīn yīyī yǐn dào qiánpái jiùzuò.","vi":"Các cô lễ tân lần lượt dẫn khách mời đến ngồi ở hàng ghế đầu."},{"type":"compound","zh":"来宾一进会场，乐队就奏起了欢快的乐曲。","pinyin":"Láibīn yí jìn huìchǎng, yuèduì jiù zòu qǐle huānkuài de yuèqǔ.","vi":"Khách mời vừa bước vào hội trường, ban nhạc liền tấu lên khúc nhạc vui tươi."}],"related":[{"hanzi":"宾客","pinyin":"bīnkè","vi":"khách khứa"},{"hanzi":"嘉宾","pinyin":"jiābīn","vi":"khách mời"},{"hanzi":"贵宾","pinyin":"guìbīn","vi":"khách quý"}],"traditional":"來賓"},{"id":"来电","hanzi":"来电","pinyin":"láidiàn","meaning_vi":"cuộc gọi đến, có điện trở lại","explanation":"来 (lai – đến) + 电 (điện) → cuộc gọi, điện báo đến; cũng nghĩa có điện trở lại sau mất điện. VD: 来电显示.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📞","examples":[{"type":"basic","zh":"你有三个未接来电。","pinyin":"Nǐ yǒu sān gè wèi jiē láidiàn.","vi":"Bạn có ba cuộc gọi nhỡ."},{"type":"simple","zh":"停了一整天电，晚上八点终于来电了。","pinyin":"Tíngle yìzhěngtiān diàn, wǎnshang bā diǎn zhōngyú láidiàn le.","vi":"Mất điện cả ngày, đến tám giờ tối cuối cùng cũng có điện trở lại."},{"type":"compound","zh":"如果看到陌生号码来电，你最好先别急着接。","pinyin":"Rúguǒ kàndào mòshēng hàomǎ láidiàn, nǐ zuìhǎo xiān bié jízhe jiē.","vi":"Nếu thấy cuộc gọi từ số lạ, tốt nhất bạn đừng vội nghe máy."}],"related":[{"hanzi":"电话","pinyin":"diànhuà","vi":"điện thoại"},{"hanzi":"来电显示","pinyin":"láidiànxiǎnshì","vi":"hiển thị cuộc gọi"},{"hanzi":"停电","pinyin":"tíngdiàn","vi":"mất điện"}],"traditional":"來電"},{"id":"来回","hanzi":"来回","pinyin":"láihuí","meaning_vi":"đi đi lại lại, khứ hồi","explanation":"来 (đến) + 回 (về).","hsk_level":"7-9","tags":["dong-tu","pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他在门口来回走。","pinyin":"Tā zài ménkǒu láihuí zǒu.","vi":"Anh ấy đi đi lại lại trước cửa."},{"type":"simple","zh":"从家到机场来回要花三个小时。","pinyin":"Cóng jiā dào jīchǎng láihuí yào huā sān gè xiǎoshí.","vi":"Từ nhà ra sân bay đi về mất ba tiếng đồng hồ."},{"type":"compound","zh":"因为忘了带护照，所以他只好来回跑了两趟。","pinyin":"Yīnwèi wàngle dài hùzhào, suǒyǐ tā zhǐhǎo láihuí pǎole liǎng tàng.","vi":"Vì quên mang hộ chiếu nên anh ấy đành phải chạy đi chạy về hai lượt."}],"related":[{"hanzi":"往返","pinyin":"wǎngfǎn","vi":"khứ hồi"},{"hanzi":"来来回回","pinyin":"láiláihuíhuí","vi":"đi đi lại lại"},{"hanzi":"单程","pinyin":"dānchéng","vi":"một chiều"}],"traditional":"來回"},{"id":"来日方长","hanzi":"来日方长","pinyin":"láirì-fāngcháng","meaning_vi":"tương lai còn dài (còn nhiều cơ hội)","explanation":"来 (đến) + 日 (ngày) + 方 (vuông) + 长 (dài).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌅","examples":[{"type":"basic","zh":"别急，来日方长。","pinyin":"Bié jí, láirìfāngcháng.","vi":"Đừng vội, ngày dài tháng rộng mà."},{"type":"simple","zh":"这次没能见面也没关系，我们来日方长。","pinyin":"Zhè cì méi néng jiànmiàn yě méiguānxi, wǒmen láirìfāngcháng.","vi":"Lần này không gặp được cũng không sao, chúng ta còn nhiều dịp."},{"type":"compound","zh":"虽然这次比赛输了，但是来日方长，你还有很多机会。","pinyin":"Suīrán zhè cì bǐsài shū le, dànshì láirìfāngcháng, nǐ háiyǒu hěn duō jīhuì.","vi":"Tuy trận này thua rồi, nhưng tương lai còn dài, bạn còn nhiều cơ hội."}],"related":[{"hanzi":"未来","pinyin":"wèilái","vi":"tương lai"},{"hanzi":"后会有期","pinyin":"hòuhuìyǒuqī","vi":"hẹn gặp lại"},{"hanzi":"机会","pinyin":"jīhuì","vi":"cơ hội"}],"traditional":"來日方長"},{"id":"蓝图","hanzi":"蓝图","pinyin":"lántú","meaning_vi":"bản thiết kế tương lai, kế hoạch lớn","explanation":"蓝 (màu xanh dương) + 图 (mưu đồ/bản đồ).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🗺️","examples":[{"type":"basic","zh":"城市发展蓝图已定。","pinyin":"Chéngshì fāzhǎn lántú yǐ dìng.","vi":"Bản quy hoạch phát triển đô thị đã được xác định."},{"type":"simple","zh":"市长在会上描绘了未来十年的交通蓝图。","pinyin":"Shìzhǎng zài huì shàng miáohuìle wèilái shí nián de jiāotōng lántú.","vi":"Tại hội nghị, thị trưởng đã phác họa bản kế hoạch giao thông cho mười năm tới."},{"type":"compound","zh":"只要大家齐心协力，美好的蓝图就一定能变成现实。","pinyin":"Zhǐyào dàjiā qíxīnxiélì, měihǎo de lántú jiù yídìng néng biànchéng xiànshí.","vi":"Chỉ cần mọi người đồng lòng hợp sức, bản kế hoạch tươi đẹp nhất định sẽ thành hiện thực."}],"related":[{"hanzi":"宏图","pinyin":"hóngtú","vi":"kế hoạch lớn"},{"hanzi":"规划","pinyin":"guīhuà","vi":"quy hoạch"},{"hanzi":"设计图","pinyin":"shèjìtú","vi":"bản vẽ thiết kế"}],"traditional":"藍圖"},{"id":"蓝牙","hanzi":"蓝牙","pinyin":"Lányá","meaning_vi":"Bluetooth","explanation":"Dịch nghĩa từ tiếng Anh 'Bluetooth'.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🎧","examples":[{"type":"basic","zh":"请打开手机蓝牙。","pinyin":"Qǐng dǎkāi shǒujī Lányá.","vi":"Vui lòng bật Bluetooth trên điện thoại."},{"type":"simple","zh":"我的蓝牙耳机在地铁上总是断开连接。","pinyin":"Wǒ de Lányá ěrjī zài dìtiě shàng zǒngshì duànkāi liánjiē.","vi":"Tai nghe Bluetooth của tôi trên tàu điện ngầm cứ bị mất kết nối."},{"type":"compound","zh":"只要打开蓝牙，音箱就会自动连上你的电脑。","pinyin":"Zhǐyào dǎkāi Lányá, yīnxiāng jiù huì zìdòng lián shàng nǐ de diànnǎo.","vi":"Chỉ cần bật Bluetooth, loa sẽ tự động kết nối với máy tính của bạn."}],"related":[{"hanzi":"耳机","pinyin":"ěrjī","vi":"tai nghe"},{"hanzi":"无线","pinyin":"wúxiàn","vi":"không dây"},{"hanzi":"连接","pinyin":"liánjiē","vi":"kết nối"}],"traditional":"藍牙"},{"id":"狼狈为奸","hanzi":"狼狈为奸","pinyin":"lángbèi-wéijiān","meaning_vi":"cấu kết làm việc xấu","explanation":"狼 (con sói) + 狈 (狈) + 为 (vì) + 奸 (gian trá).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐺","examples":[{"type":"basic","zh":"他们狼狈为奸。","pinyin":"Tāmen lángbèiwéijiān.","vi":"Bọn họ cấu kết với nhau làm điều xấu."},{"type":"simple","zh":"那个贪官和奸商狼狈为奸，骗走了大量公款。","pinyin":"Nà ge tānguān hé jiānshāng lángbèiwéijiān, piànzǒule dàliàng gōngkuǎn.","vi":"Tên quan tham đó cấu kết với gian thương, lừa lấy một lượng lớn công quỹ."},{"type":"compound","zh":"即使他们狼狈为奸、隐藏得再深，最终也逃不过法律的制裁。","pinyin":"Jíshǐ tāmen lángbèiwéijiān, yǐncáng de zài shēn, zuìzhōng yě táo búguò fǎlǜ de zhìcái.","vi":"Dù chúng có cấu kết với nhau và che giấu kỹ đến đâu, cuối cùng cũng không thoát khỏi sự trừng trị của pháp luật."}],"related":[{"hanzi":"同流合污","pinyin":"tóngliúhéwū","vi":"thông đồng làm bậy"},{"hanzi":"勾结","pinyin":"gōujié","vi":"cấu kết"},{"hanzi":"狼狈","pinyin":"lángbèi","vi":"khốn đốn"}],"traditional":"狼狽為奸"},{"id":"劳动合同","hanzi":"劳动合同","pinyin":"láodònghétong","meaning_vi":"hợp đồng lao động","explanation":"劳动 (lao động) + 合同 (hợp đồng) → hợp đồng lao động giữa người lao động và đơn vị. VD: 签订劳动合同.","hsk_level":"7-9","tags":["danh-tu","cong-viec","phap-luat"],"image":"📄","examples":[{"type":"basic","zh":"我签了劳动合同。","pinyin":"Wǒ qiānle láodònghétong.","vi":"Tôi đã ký hợp đồng lao động."},{"type":"simple","zh":"公司必须在员工入职一个月内签订劳动合同。","pinyin":"Gōngsī bìxū zài yuángōng rùzhí yí gèyuè nèi qiāndìng láodònghétong.","vi":"Công ty phải ký hợp đồng lao động trong vòng một tháng kể từ khi nhân viên vào làm."},{"type":"compound","zh":"如果老板不肯签劳动合同，你的权益就很难得到保障。","pinyin":"Rúguǒ lǎobǎn bùkěn qiān láodònghétong, nǐ de quányì jiù hěn nándé dào bǎozhàng.","vi":"Nếu ông chủ không chịu ký hợp đồng lao động, quyền lợi của bạn sẽ khó được đảm bảo."}],"related":[{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"劳动法","pinyin":"láodòngfǎ","vi":"luật lao động"},{"hanzi":"签约","pinyin":"qiānyuē","vi":"ký hợp đồng"}],"traditional":"勞動合同"},{"id":"劳工","hanzi":"劳工","pinyin":"láogōng","meaning_vi":"người lao động, công nhân","explanation":"劳 (lao động/vất vả) + 工 (工).","hsk_level":"7-9","tags":["danh-tu","cong-viec","con-nguoi"],"image":"👷","examples":[{"type":"basic","zh":"劳工权益受法律保护。","pinyin":"Láogōng quányì shòu fǎlǜ bǎohù.","vi":"Quyền lợi của người lao động được pháp luật bảo vệ."},{"type":"simple","zh":"大批外籍劳工在这个港口城市从事建筑工作。","pinyin":"Dàpī wàijí láogōng zài zhè ge gǎngkǒu chéngshì cóngshì jiànzhù gōngzuò.","vi":"Đông đảo lao động nước ngoài làm nghề xây dựng tại thành phố cảng này."},{"type":"compound","zh":"因为劳工短缺，所以不少工厂不得不提高工资。","pinyin":"Yīnwèi láogōng duǎnquē, suǒyǐ bùshǎo gōngchǎng bùdébù tígāo gōngzī.","vi":"Vì thiếu hụt lao động nên không ít nhà máy buộc phải tăng lương."}],"related":[{"hanzi":"工人","pinyin":"gōngrén","vi":"công nhân"},{"hanzi":"劳动者","pinyin":"láodòngzhě","vi":"người lao động"},{"hanzi":"雇主","pinyin":"gùzhǔ","vi":"chủ thuê"}],"traditional":"勞工"},{"id":"牢记使命","hanzi":"牢记使命","pinyin":"láojìshǐmìng","meaning_vi":"khắc ghi sứ mệnh","explanation":"牢 (vững chắc/nhà tù) + 记 (记) + 使 (khiến cho) + 命 (mệnh lệnh/số phận).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"我们要牢记使命。","pinyin":"Wǒmen yào láojìshǐmìng.","vi":"Chúng ta phải khắc ghi sứ mệnh."},{"type":"simple","zh":"年轻的边防战士在界碑前庄严宣誓，牢记使命。","pinyin":"Niánqīng de biānfáng zhànshì zài jièbēi qián zhuāngyán xuānshì, láojìshǐmìng.","vi":"Những chiến sĩ biên phòng trẻ trang nghiêm tuyên thệ trước cột mốc, khắc ghi sứ mệnh."},{"type":"compound","zh":"只有不忘初心、牢记使命，医生才能真正做到救死扶伤。","pinyin":"Zhǐyǒu bú wàng chūxīn, láojìshǐmìng, yīshēng cáinéng zhēnzhèng zuòdào jiùsǐfúshāng.","vi":"Chỉ khi không quên tâm nguyện ban đầu, khắc ghi sứ mệnh, bác sĩ mới thật sự cứu người giúp đời."}],"related":[{"hanzi":"使命","pinyin":"shǐmìng","vi":"sứ mệnh"},{"hanzi":"牢记","pinyin":"láojì","vi":"ghi nhớ"},{"hanzi":"不忘初心","pinyin":"búwàngchūxīn","vi":"không quên ý nguyện ban đầu"}],"traditional":"牢記使命"},{"id":"劳累","hanzi":"劳累","pinyin":"láolèi","meaning_vi":"mệt nhọc","explanation":"劳 (lao động/vất vả) + 累 (mệt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"😫","examples":[{"type":"basic","zh":"妈妈今天很劳累。","pinyin":"Māma jīntiān hěn láolèi.","vi":"Hôm nay mẹ rất mệt nhọc."},{"type":"simple","zh":"连续加班一周后，他因过度劳累住进了医院。","pinyin":"Liánxù jiābān yìzhōu hòu, tā yīn guòdù láolèi zhù jìnle yīyuàn.","vi":"Sau một tuần tăng ca liên tục, anh ấy phải nhập viện vì quá lao lực."},{"type":"compound","zh":"尽管一天的农活非常劳累，但是爷爷从来不抱怨。","pinyin":"Jǐnguǎn yì tiān de nónghuó fēicháng láolèi, dànshì yéye cóngláibú bàoyuàn.","vi":"Mặc dù việc đồng áng cả ngày rất mệt nhọc, nhưng ông nội chưa bao giờ than phiền."}],"related":[{"hanzi":"疲劳","pinyin":"píláo","vi":"mệt mỏi"},{"hanzi":"辛苦","pinyin":"xīnkǔ","vi":"vất vả"},{"hanzi":"疲惫","pinyin":"píbèi","vi":"mệt mỏi rã rời"}],"traditional":"勞累"},{"id":"劳力","hanzi":"劳力","pinyin":"láolì","meaning_vi":"sức lao động","explanation":"劳 (lao động/vất vả) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"农村缺少青壮劳力。","pinyin":"Nóngcūn quēshǎo qīng zhuàng láolì.","vi":"Nông thôn thiếu lao động trẻ khỏe."},{"type":"simple","zh":"收割季节一到，全村的劳力都下地干活了。","pinyin":"Shōugē jìjié yí dào, quán cūn de láolì dōu xiàdì gànhuó le.","vi":"Mùa gặt vừa đến, toàn bộ sức lao động trong làng đều ra đồng làm việc."},{"type":"compound","zh":"有了收割机以后，不但节省了劳力，而且提高了效率。","pinyin":"Yǒule shōugējī yǐhòu, búdàn jiéshěngle láolì, érqiě tígāole xiàolǜ.","vi":"Có máy gặt rồi, không những tiết kiệm sức lao động mà còn nâng cao hiệu suất."}],"related":[{"hanzi":"劳动力","pinyin":"láodònglì","vi":"sức lao động"},{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"人力","pinyin":"rénlì","vi":"nhân lực"}],"traditional":"勞力"},{"id":"劳民伤财","hanzi":"劳民伤财","pinyin":"láomín-shāngcái","meaning_vi":"tốn tiền hại sức dân","explanation":"劳 (lao động/vất vả) + 民 (nhân dân/dân chủ) + 伤 (tổn thương) + 财 (财).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💸","examples":[{"type":"basic","zh":"这个工程劳民伤财。","pinyin":"Zhè ge gōngchéng láomínshāngcái.","vi":"Công trình này tốn tiền hại sức dân."},{"type":"simple","zh":"为了一场形式主义的庆典大搞装修，简直劳民伤财。","pinyin":"Wèile yì chǎng xíngshì zhǔyì de qìngdiǎn dà gǎo zhuāngxiū, jiǎnzhí láomínshāngcái.","vi":"Vì một lễ kỷ niệm hình thức mà sửa sang rầm rộ, quả thực là hao người tốn của."},{"type":"compound","zh":"与其年年翻修马路劳民伤财，不如一次把质量做好。","pinyin":"Yǔqí niánnián fānxiū mǎlù láomínshāngcái, bùrú yí cì bǎ zhìliàng zuò hǎo.","vi":"Thay vì năm nào cũng sửa đường vừa tốn của vừa nhọc dân, chi bằng làm tốt chất lượng ngay một lần."}],"related":[{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"},{"hanzi":"得不偿失","pinyin":"débùchángshī","vi":"được không bù mất"},{"hanzi":"铺张浪费","pinyin":"pūzhānglàngfèi","vi":"phung phí"}],"traditional":"勞民傷財"},{"id":"乐此不疲","hanzi":"乐此不疲","pinyin":"lècǐ-bùpí","meaning_vi":"say mê làm không biết mệt","explanation":"乐 (vui vẻ/lạc quan) + 此 (此) + 不 (không) + 疲 (mệt mỏi).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤩","examples":[{"type":"basic","zh":"他对钓鱼乐此不疲。","pinyin":"Tā duì diàoyú lècǐbùpí.","vi":"Anh ấy mê câu cá không biết mệt."},{"type":"simple","zh":"奶奶每天给小区的流浪猫喂食，乐此不疲。","pinyin":"Nǎinai měitiān gěi xiǎoqū de liúlàngmāo wèishí, lècǐbùpí.","vi":"Ngày nào bà cũng cho mèo hoang trong khu dân cư ăn, làm mãi không chán."},{"type":"compound","zh":"虽然修理旧钟表很费时间，但是他一直乐此不疲。","pinyin":"Suīrán xiūlǐ jiù zhōngbiǎo hěn fèi shíjiān, dànshì tā yìzhí lècǐbùpí.","vi":"Tuy sửa đồng hồ cũ rất tốn thời gian, nhưng ông ấy luôn say mê không biết mệt."}],"related":[{"hanzi":"津津有味","pinyin":"jīnjīnyǒuwèi","vi":"say sưa thích thú"},{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"不知疲倦","pinyin":"bùzhīpíjuàn","vi":"không biết mệt"}],"traditional":"樂此不疲"},{"id":"乐善好施","hanzi":"乐善好施","pinyin":"lèshàn-hàoshī","meaning_vi":"thích làm việc thiện giúp người","explanation":"乐 (vui vẻ/lạc quan) + 善 (lương thiện/giỏi về) + 好 (tốt) + 施 (thi hành/thực hiện).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💖","examples":[{"type":"basic","zh":"老人乐善好施。","pinyin":"Lǎorén lèshànhàoshī.","vi":"Cụ già thích làm việc thiện."},{"type":"simple","zh":"这位乐善好施的商人捐资修建了三所小学。","pinyin":"Zhè wèi lèshànhàoshī de shāngrén juānzī xiūjiànle sān suǒ xiǎoxué.","vi":"Vị thương nhân hay làm việc thiện này đã góp tiền xây ba trường tiểu học."},{"type":"compound","zh":"他不但生意做得好，而且乐善好施，在乡里口碑很好。","pinyin":"Tā búdàn shēngyi zuò de hǎo, érqiě lèshànhàoshī, zài xiānglǐ kǒubēi hěn hǎo.","vi":"Ông ấy không những làm ăn giỏi mà còn hay làm việc thiện, được bà con trong vùng khen ngợi."}],"related":[{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"助人为乐","pinyin":"zhùrénwéilè","vi":"vui khi giúp người"},{"hanzi":"施舍","pinyin":"shīshě","vi":"bố thí"}],"traditional":"樂善好施"},{"id":"累积","hanzi":"累积","pinyin":"lěijī","meaning_vi":"tích lũy","explanation":"累 (lũy – chồng chất) + 积 (tích – tích tụ) → tích lũy dần dần. Lưu ý 累 ở đây đọc lěi, không phải lèi (mệt). VD: 累积经验.","hsk_level":"7-9","tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"经验需要慢慢累积。","pinyin":"Jīngyàn xūyào mànmàn lěijī.","vi":"Kinh nghiệm cần được tích lũy dần dần."},{"type":"simple","zh":"这张会员卡已经累积了两万多积分。","pinyin":"Zhè zhāng huìyuánkǎ yǐjīng lěijīle liǎng wàn duō jīfēn.","vi":"Thẻ thành viên này đã tích lũy được hơn hai vạn điểm."},{"type":"compound","zh":"如果压力长期累积而不释放，人就容易生病。","pinyin":"Rúguǒ yālì chángqī lěijī ér bú shìfàng, rén jiù róngyì shēngbìng.","vi":"Nếu áp lực tích tụ lâu ngày mà không được giải tỏa, con người sẽ dễ sinh bệnh."}],"related":[{"hanzi":"积累","pinyin":"jīlěi","vi":"tích lũy"},{"hanzi":"积攒","pinyin":"jīzǎn","vi":"dành dụm"},{"hanzi":"累计","pinyin":"lěijì","vi":"cộng dồn"}],"traditional":"累積"},{"id":"雷同","hanzi":"雷同","pinyin":"léitóng","meaning_vi":"giống nhau một cách trùng lặp (sao chép)","explanation":"雷 (sấm) + 同 (đồng lòng/đồng bào).","hsk_level":"7-9","tags":["tinh-tu","dong-tu"],"image":"👯","examples":[{"type":"basic","zh":"两篇作文内容雷同。","pinyin":"Liǎng piān zuòwén nèiróng léitóng.","vi":"Hai bài văn có nội dung trùng lặp."},{"type":"simple","zh":"这几家奶茶店的装修风格几乎完全雷同。","pinyin":"Zhè jǐ jiā nǎichá diàn de zhuāngxiū fēnggé jīhū wánquán léitóng.","vi":"Phong cách trang trí của mấy tiệm trà sữa này gần như giống hệt nhau."},{"type":"compound","zh":"如果论文和别人的雷同，就会被判定为抄袭。","pinyin":"Rúguǒ lùnwén hé biérén de léitóng, jiù huì bèi pàn dìngwéi chāoxí.","vi":"Nếu luận văn trùng lặp với của người khác, sẽ bị coi là đạo văn."}],"related":[{"hanzi":"相同","pinyin":"xiāngtóng","vi":"giống nhau"},{"hanzi":"抄袭","pinyin":"chāoxí","vi":"đạo văn"},{"hanzi":"独特","pinyin":"dútè","vi":"độc đáo"}]},{"id":"利弊","hanzi":"利弊","pinyin":"lìbì","meaning_vi":"lợi và hại","explanation":"利 (lợi ích/thuận lợi) + 弊 (tệ nạn/hại).","hsk_level":"7-9","tags":["danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"凡事都有利弊。","pinyin":"Fánshì dōu yǒu lìbì.","vi":"Việc gì cũng có lợi có hại."},{"type":"simple","zh":"做决定之前，他把出国读书的利弊都写在了纸上。","pinyin":"Zuò juédìng zhīqián, tā bǎ chūguó dúshū de lìbì dōu xiě zài le zhǐ shàng.","vi":"Trước khi quyết định, anh ấy đã viết ra giấy tất cả lợi hại của việc đi du học."},{"type":"compound","zh":"只有权衡利弊以后，我们才能选出最合适的方案。","pinyin":"Zhǐyǒu quánhéng lìbì yǐhòu, wǒmen cáinéng xuǎnchū zuì héshì de fāng'àn.","vi":"Chỉ sau khi cân nhắc lợi hại, chúng ta mới chọn ra được phương án phù hợp nhất."}],"related":[{"hanzi":"利害","pinyin":"lìhài","vi":"lợi hại"},{"hanzi":"优缺点","pinyin":"yōuquēdiǎn","vi":"ưu nhược điểm"},{"hanzi":"权衡利弊","pinyin":"quánhénglìbì","vi":"cân nhắc lợi hại"}]},{"id":"力不从心","hanzi":"力不从心","pinyin":"lìbù-cóngxīn","meaning_vi":"lực bất tòng tâm","explanation":"力 (sức mạnh/nỗ lực) + 不 (không) + 从 (từ (thời gian/địa điểm)) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤷‍♂️","examples":[{"type":"basic","zh":"我感到力不从心。","pinyin":"Wǒ gǎndào lìbùcóngxīn.","vi":"Tôi cảm thấy lực bất tòng tâm."},{"type":"simple","zh":"年过七十，爷爷爬山时已经有些力不从心了。","pinyin":"Niánguò qīshí, yéye páshān shí yǐjīng yǒuxiē lìbùcóngxīn le.","vi":"Đã ngoài bảy mươi, ông nội leo núi đã có phần lực bất tòng tâm."},{"type":"compound","zh":"虽然他很想帮忙，但是身体不好，实在力不从心。","pinyin":"Suīrán tā hěn xiǎng bāngmáng, dànshì shēntǐ bù hǎo, shízài lìbùcóngxīn.","vi":"Tuy anh ấy rất muốn giúp, nhưng sức khỏe không tốt, thật sự lực bất tòng tâm."}],"related":[{"hanzi":"心有余而力不足","pinyin":"xīn yǒuyú ér lì bùzú","vi":"lực bất tòng tâm"},{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"得心应手","pinyin":"déxīnyìngshǒu","vi":"thuận tay dễ dàng"}],"traditional":"力不從心"},{"id":"历程","hanzi":"历程","pinyin":"lìchéng","meaning_vi":"chặng đường lịch sử, quá trình trải qua","explanation":"历 (lịch sử/trải qua) + 程 (程).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🛤️","examples":[{"type":"basic","zh":"这是一段艰辛的历程。","pinyin":"Zhè shì yí duàn jiānxīn de lìchéng.","vi":"Đây là một chặng đường gian khổ."},{"type":"simple","zh":"展览用两百张照片记录了这座城市的发展历程。","pinyin":"Zhǎnlǎn yòng liǎng bǎi zhāng zhàopiàn jìlùle zhè zuò chéngshì de fāzhǎn lìchéng.","vi":"Triển lãm dùng hai trăm bức ảnh ghi lại quá trình phát triển của thành phố này."},{"type":"compound","zh":"回顾自己的创业历程，他既感到骄傲，又有些心酸。","pinyin":"Huígù zìjǐ de chuàngyè lìchéng, tā jì gǎndào jiāo'ào, yòu yǒuxiē xīnsuān.","vi":"Nhìn lại chặng đường khởi nghiệp của mình, anh ấy vừa thấy tự hào, vừa có chút chua xót."}],"related":[{"hanzi":"过程","pinyin":"guòchéng","vi":"quá trình"},{"hanzi":"进程","pinyin":"jìnchéng","vi":"tiến trình"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"}],"traditional":"歷程"},{"id":"立春","hanzi":"立春","pinyin":"Lìchūn","meaning_vi":"tiết Lập xuân (mở đầu mùa xuân)","explanation":"立 (lập trường/thiết lập) + 春 (春).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🌱","examples":[{"type":"basic","zh":"明天就立春了。","pinyin":"Míngtiān jiù Lìchūn le.","vi":"Ngày mai đã là tiết Lập xuân rồi."},{"type":"simple","zh":"立春那天，北方人习惯吃春饼迎接春天。","pinyin":"Lìchūn nà tiān, běifāng rén xíguàn chī chūnbǐng yíngjiē chūntiān.","vi":"Ngày Lập xuân, người miền Bắc Trung Quốc có thói quen ăn bánh xuân để đón mùa xuân."},{"type":"compound","zh":"虽然已经立春了，但是外面还是冷得让人发抖。","pinyin":"Suīrán yǐjīng Lìchūn le, dànshì wàimiàn háishì lěng de ràng rén fādǒu.","vi":"Tuy đã sang tiết Lập xuân, nhưng bên ngoài vẫn lạnh đến run người."}],"related":[{"hanzi":"立夏","pinyin":"Lìxià","vi":"Lập hạ"},{"hanzi":"立秋","pinyin":"Lìqiū","vi":"Lập thu"},{"hanzi":"节气","pinyin":"jiéqì","vi":"tiết khí"}]},{"id":"立冬","hanzi":"立冬","pinyin":"Lìdōng","meaning_vi":"tiết Lập đông","explanation":"立 (lập trường/thiết lập) + 冬 (冬).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"❄️","examples":[{"type":"basic","zh":"立冬后天气转冷。","pinyin":"Lìdōng hòu tiānqì zhuǎn lěng.","vi":"Sau tiết Lập đông trời chuyển lạnh."},{"type":"simple","zh":"按照老家的习俗，立冬这天全家要一起包饺子。","pinyin":"Ànzhào lǎojiā de xísú, Lìdōng zhè tiān quánjiā yào yìqǐ bāojiǎozi.","vi":"Theo phong tục quê nhà, ngày Lập đông cả nhà phải cùng nhau gói sủi cảo."},{"type":"compound","zh":"一过立冬，奶奶就把厚棉被从柜子里拿了出来。","pinyin":"Yíguò Lìdōng, nǎinai jiù bǎ hòu miánbèi cóng guìzi lǐ nále chūlái.","vi":"Vừa qua tiết Lập đông, bà nội đã lấy chăn bông dày trong tủ ra."}],"related":[{"hanzi":"立秋","pinyin":"Lìqiū","vi":"Lập thu"},{"hanzi":"冬至","pinyin":"Dōngzhì","vi":"Đông chí"},{"hanzi":"节气","pinyin":"jiéqì","vi":"tiết khí"}]},{"id":"立法","hanzi":"立法","pinyin":"lìfǎ","meaning_vi":"lập pháp, ban hành luật","explanation":"立 (lập nên) + 法 (pháp luật).","hsk_level":"7-9","tags":["dong-tu","phap-luat","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"国家正在立法保护野生动物。","pinyin":"Guójiā zhèngzài lìfǎ bǎohù yěshēng dòngwù.","vi":"Nhà nước đang lập pháp để bảo vệ động vật hoang dã."},{"type":"simple","zh":"人大常委会计划明年就个人信息保护问题立法。","pinyin":"Réndà chángwěihuì jìhuà míngnián jiù gèrén xìnxī bǎohù wèntí lìfǎ.","vi":"Ủy ban Thường vụ Quốc hội dự kiến năm sau sẽ lập pháp về vấn đề bảo vệ thông tin cá nhân."},{"type":"compound","zh":"如果不尽快立法，网络诈骗就会越来越猖狂。","pinyin":"Rúguǒ bú jìnkuài lìfǎ, wǎngluòzhàpiàn jiù huì yuèláiyuè chāngkuáng.","vi":"Nếu không nhanh chóng ban hành luật, lừa đảo qua mạng sẽ ngày càng hoành hành."}],"related":[{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"立法权","pinyin":"lìfǎquán","vi":"quyền lập pháp"},{"hanzi":"执法","pinyin":"zhífǎ","vi":"thực thi pháp luật"}]},{"id":"立法权","hanzi":"立法权","pinyin":"lìfǎquán","meaning_vi":"quyền lập pháp","explanation":"立 (lập trường/thiết lập) + 法 (法) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"议会拥有立法权。","pinyin":"Yìhuì yōngyǒu lìfǎquán.","vi":"Nghị viện nắm quyền lập pháp."},{"type":"simple","zh":"根据宪法，全国人民代表大会行使国家立法权。","pinyin":"Gēnjù xiànfǎ, quánguó rénmín dàibiǎo dàhuì xíngshǐ guójiā lìfǎquán.","vi":"Theo hiến pháp, Đại hội Đại biểu Nhân dân toàn quốc thực thi quyền lập pháp của nhà nước."},{"type":"compound","zh":"虽然地方政府有一定的立法权，但是不能违背上位法。","pinyin":"Suīrán dìfāng zhèngfǔ yǒu yídìng de lìfǎquán, dànshì bù néng wéibèi shàngwèi fǎ.","vi":"Tuy chính quyền địa phương có một số quyền lập pháp nhất định, nhưng không được trái với luật cấp trên."}],"related":[{"hanzi":"行政权","pinyin":"xíngzhèngquán","vi":"quyền hành pháp"},{"hanzi":"司法权","pinyin":"sīfǎquán","vi":"quyền tư pháp"},{"hanzi":"立法","pinyin":"lìfǎ","vi":"lập pháp"}],"traditional":"立法權"},{"id":"历历在目","hanzi":"历历在目","pinyin":"lìlì-zàimù","meaning_vi":"hiện rõ mồn một trước mắt (kỷ niệm)","explanation":"历历在目: rõ ràng từng cái một (历历) ở trước mắt (在目) → cảnh vật, chuyện cũ hiện lên rõ mồn một như mới xảy ra. Thường dùng khi hồi tưởng.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"往事历历在目。","pinyin":"Wǎngshì lìlìzàimù.","vi":"Chuyện cũ hiện rõ mồn một trước mắt."},{"type":"simple","zh":"二十年前离开家乡的那个清晨，至今仍历历在目。","pinyin":"Èrshí niánqián líkāi jiāxiāng de nà ge qīngchén, zhìjīn réng lìlìzàimù.","vi":"Buổi sáng sớm rời quê hai mươi năm trước, đến nay vẫn hiện rõ trước mắt."},{"type":"compound","zh":"虽然毕业已经十年了，但是和室友熬夜聊天的情景依然历历在目。","pinyin":"Suīrán bìyè yǐjīng shí nián le, dànshì hé shìyǒu áoyè liáotiān de qíngjǐng yīrán lìlìzàimù.","vi":"Tuy đã tốt nghiệp mười năm, nhưng cảnh thức khuya trò chuyện với bạn cùng phòng vẫn hiện rõ mồn một."}],"related":[{"hanzi":"记忆犹新","pinyin":"jìyìyóuxīn","vi":"ký ức còn mới"},{"hanzi":"清清楚楚","pinyin":"qīngqīngchǔchǔ","vi":"rõ ràng"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi ức"}],"traditional":"歷歷在目"},{"id":"立秋","hanzi":"立秋","pinyin":"Lìqiū","meaning_vi":"tiết Lập thu","explanation":"立 (lập trường/thiết lập) + 秋 (秋).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🍂","examples":[{"type":"basic","zh":"立秋以后早晚凉了。","pinyin":"Lìqiū yǐhòu zǎowǎn liáng le.","vi":"Sau tiết Lập thu, sáng sớm và chiều tối đã mát."},{"type":"simple","zh":"立秋这天，很多人家有吃西瓜“啃秋”的习惯。","pinyin":"Lìqiū zhè tiān, hěn duō rénjiā yǒu chī xīguā \"kěn qiū\" de xíguàn.","vi":"Ngày Lập thu, nhiều gia đình có thói quen ăn dưa hấu để \"gặm thu\"."},{"type":"compound","zh":"虽然日历上已经立秋，但是南方仍然热得像蒸笼。","pinyin":"Suīrán rìlì shàng yǐjīng Lìqiū, dànshì nánfāng réngrán rè de xiàng zhēnglóng.","vi":"Tuy trên lịch đã là Lập thu, nhưng miền Nam vẫn nóng như lồng hấp."}],"related":[{"hanzi":"立冬","pinyin":"Lìdōng","vi":"Lập đông"},{"hanzi":"秋分","pinyin":"Qiūfēn","vi":"Thu phân"},{"hanzi":"节气","pinyin":"jiéqì","vi":"tiết khí"}]},{"id":"历史性","hanzi":"历史性","pinyin":"lìshǐxìng","meaning_vi":"mang tính lịch sử","explanation":"历 (lịch sử/trải qua) + 史 (lịch sử) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"这是历史性的时刻。","pinyin":"Zhè shì lìshǐxìng de shíkè.","vi":"Đây là một khoảnh khắc mang tính lịch sử."},{"type":"simple","zh":"两国领导人在边境小城举行了历史性会晤。","pinyin":"Liǎngguó lǐngdǎorén zài biānjìng xiǎochéng jǔxíngle lìshǐxìng huìwù.","vi":"Lãnh đạo hai nước đã có cuộc gặp lịch sử tại một thị trấn biên giới."},{"type":"compound","zh":"因为这次登月取得了历史性突破，所以全世界都在关注。","pinyin":"Yīnwèi zhè cì dēngyuè qǔ déle lìshǐxìng tūpò, suǒyǐ quánshìjiè dōu zài guānzhù.","vi":"Vì chuyến đổ bộ mặt trăng lần này đạt được bước đột phá lịch sử nên cả thế giới đều dõi theo."}],"related":[{"hanzi":"历史","pinyin":"lìshǐ","vi":"lịch sử"},{"hanzi":"里程碑","pinyin":"lǐchéngbēi","vi":"cột mốc"},{"hanzi":"划时代","pinyin":"huàshídài","vi":"mở ra thời đại mới"}],"traditional":"歷史性"},{"id":"立体声","hanzi":"立体声","pinyin":"lìtǐshēng","meaning_vi":"âm thanh nổi (stereo)","explanation":"立 (lập trường/thiết lập) + 体 (thể hiện/hệ thống) + 声 (thanh thế/tuyên bố).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🔊","examples":[{"type":"basic","zh":"这台音响是立体声的。","pinyin":"Zhè tái yīnxiǎng shì lìtǐshēng de.","vi":"Dàn âm thanh này là loại âm thanh nổi."},{"type":"simple","zh":"戴上耳机后，立体声效果让人仿佛置身音乐厅。","pinyin":"Dàishàng ěrjī hòu, lìtǐshēng xiàoguǒ ràng rén fǎngfú zhìshēn yīnyuètīng.","vi":"Đeo tai nghe vào, hiệu ứng âm thanh nổi khiến người ta như đang ngồi trong phòng hòa nhạc."},{"type":"compound","zh":"如果只用一个喇叭，就听不出立体声的层次感。","pinyin":"Rúguǒ zhǐ yòng yí gè lǎba, jiù tīng bù chū lìtǐshēng de céngcì gǎn.","vi":"Nếu chỉ dùng một chiếc loa thì sẽ không nghe ra được chiều sâu của âm thanh nổi."}],"related":[{"hanzi":"音响","pinyin":"yīnxiǎng","vi":"dàn âm thanh"},{"hanzi":"耳机","pinyin":"ěrjī","vi":"tai nghe"},{"hanzi":"单声道","pinyin":"dānshēngdào","vi":"âm thanh đơn kênh"}],"traditional":"立體聲"},{"id":"立夏","hanzi":"立夏","pinyin":"Lìxià","meaning_vi":"tiết Lập hạ","explanation":"立 (lập trường/thiết lập) + 夏 (夏).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"☀️","examples":[{"type":"basic","zh":"立夏标志着夏天开始。","pinyin":"Lìxià biāozhìzhe xiàtiān kāishǐ.","vi":"Lập hạ đánh dấu mùa hè bắt đầu."},{"type":"simple","zh":"立夏那天，外婆给每个孩子煮了一个鸡蛋。","pinyin":"Lìxià nà tiān, wàipó gěi měi gè háizi zhǔle yí gè jīdàn.","vi":"Ngày Lập hạ, bà ngoại luộc cho mỗi đứa trẻ một quả trứng gà."},{"type":"compound","zh":"一到立夏，田里的秧苗就长得一天比一天高。","pinyin":"Yí dào Lìxià, tián lǐ de yāngmiáo jiù zhǎngde yì tiān bǐ yì tiān gāo.","vi":"Cứ đến tiết Lập hạ, mạ ngoài ruộng lại cao lên từng ngày."}],"related":[{"hanzi":"立春","pinyin":"Lìchūn","vi":"Lập xuân"},{"hanzi":"夏至","pinyin":"Xiàzhì","vi":"Hạ chí"},{"hanzi":"节气","pinyin":"jiéqì","vi":"tiết khí"}]},{"id":"利息率","hanzi":"利息率","pinyin":"lìxīlǜ","meaning_vi":"lãi suất","explanation":"利息 (lợi tức – tiền lãi) + 率 (suất – tỷ lệ) → lãi suất; thường nói gọn là 利率.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"银行下调了利息率。","pinyin":"Yínháng xiàtiáole lìxīlǜ.","vi":"Ngân hàng đã hạ lãi suất."},{"type":"simple","zh":"这家银行三年定期存款的利息率是百分之二。","pinyin":"Zhè jiā yínháng sān nián dìngqī cúnkuǎn de lìxīlǜ shì bǎifēnzhī èr.","vi":"Lãi suất tiền gửi kỳ hạn ba năm của ngân hàng này là hai phần trăm."},{"type":"compound","zh":"如果利息率继续上升，买房的人就会明显减少。","pinyin":"Rúguǒ lìxīlǜ jìxù shàngshēng, mǎifáng de rén jiù huì míngxiǎn jiǎnshǎo.","vi":"Nếu lãi suất tiếp tục tăng, người mua nhà sẽ giảm rõ rệt."}],"related":[{"hanzi":"利率","pinyin":"lìlǜ","vi":"lãi suất"},{"hanzi":"利息","pinyin":"lìxī","vi":"tiền lãi"},{"hanzi":"存款","pinyin":"cúnkuǎn","vi":"tiền gửi"}]},{"id":"力争","hanzi":"力争","pinyin":"lìzhēng","meaning_vi":"ra sức phấn đấu giành lấy","explanation":"力 (sức mạnh/nỗ lực) + 争 (tranh đấu/tranh thủ).","hsk_level":"7-9","tags":["dong-tu"],"image":"💪","examples":[{"type":"basic","zh":"我们力争第一名。","pinyin":"Wǒmen lìzhēng dìyīmíng.","vi":"Chúng tôi ra sức giành hạng nhất."},{"type":"simple","zh":"工程队力争在雨季到来之前完成大桥主体。","pinyin":"Gōngchéng duì lìzhēng zài yǔjì dàolái zhīqián wánchéng Dàqiáo zhǔtǐ.","vi":"Đội thi công ra sức hoàn thành phần chính của cây cầu trước khi mùa mưa đến."},{"type":"compound","zh":"虽然对手很强，但是我们仍要力争打进决赛。","pinyin":"Suīrán duìshǒu hěn qiáng, dànshì wǒmen réng yào lìzhēng dǎjìn juésài.","vi":"Tuy đối thủ rất mạnh, nhưng chúng ta vẫn phải cố gắng giành vé vào chung kết."}],"related":[{"hanzi":"争取","pinyin":"zhēngqǔ","vi":"tranh thủ giành"},{"hanzi":"努力","pinyin":"nǔlì","vi":"nỗ lực"},{"hanzi":"力争上游","pinyin":"lìzhēngshàngyóu","vi":"phấn đấu vươn lên"}],"traditional":"力爭"},{"id":"立足点","hanzi":"立足点","pinyin":"lìzúdiǎn","meaning_vi":"điểm đứng chân, xuất phát điểm","explanation":"立 (lập trường/thiết lập) + 足 (đầy đủ/chân) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["danh-tu"],"image":"📍","examples":[{"type":"basic","zh":"这是我们的立足点。","pinyin":"Zhè shì wǒmen de lìzúdiǎn.","vi":"Đây là chỗ đứng của chúng tôi."},{"type":"simple","zh":"写论文时，必须先找准自己的立足点。","pinyin":"Xiě lùnwén shí, bìxū xiān zhǎo zhǔn zìjǐ de lìzúdiǎn.","vi":"Khi viết luận văn, trước hết phải xác định đúng điểm xuất phát của mình."},{"type":"compound","zh":"只要把用户需求作为立足点，产品就不会偏离方向。","pinyin":"Zhǐyào bǎ yònghù xūqiú zuòwéi lìzúdiǎn, chǎnpǐn jiù bú huì piānlí fāngxiàng.","vi":"Chỉ cần lấy nhu cầu người dùng làm điểm xuất phát, sản phẩm sẽ không đi chệch hướng."}],"related":[{"hanzi":"出发点","pinyin":"chūfādiǎn","vi":"điểm xuất phát"},{"hanzi":"立足","pinyin":"lìzú","vi":"đứng chân"},{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"}],"traditional":"立足點"},{"id":"令人瞩目","hanzi":"令人瞩目","pinyin":"lìngrénzhǔmù","meaning_vi":"khiến mọi người chú ý","explanation":"令 (mệnh lệnh/khiến cho) + 人 (người) + 瞩 (chú mục/nhìn xa) + 目 (mục tiêu/ánh mắt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他的成绩令人瞩目。","pinyin":"Tā de chéngjì lìngrénzhǔmù.","vi":"Thành tích của anh ấy khiến mọi người chú ý."},{"type":"simple","zh":"这座小城近年来的变化令人瞩目。","pinyin":"Zhè zuò xiǎochéng jìnniánlái de biànhuà lìngrénzhǔmù.","vi":"Những thay đổi của thị trấn nhỏ này mấy năm gần đây thật đáng chú ý."},{"type":"compound","zh":"她不但获得了金牌，而且打破了世界纪录，表现令人瞩目。","pinyin":"Tā búdàn huòdéle jīnpái, érqiě dǎpòle shìjiè jìlù, biǎoxiàn lìngrénzhǔmù.","vi":"Cô ấy không những giành huy chương vàng mà còn phá kỷ lục thế giới, màn thể hiện thật gây chú ý."}],"related":[{"hanzi":"引人注目","pinyin":"yǐnrénzhùmù","vi":"thu hút sự chú ý"},{"hanzi":"举世瞩目","pinyin":"jǔshìzhǔmù","vi":"cả thế giới chú ý"},{"hanzi":"醒目","pinyin":"xǐngmù","vi":"nổi bật"}],"traditional":"令人矚目"},{"id":"离别","hanzi":"离别","pinyin":"líbié","meaning_vi":"ly biệt, chia tay","explanation":"离 (cách (khoảng cách)) + 别 (đừng (câu cầu khiến)).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"👋","examples":[{"type":"basic","zh":"离别总是让人伤感。","pinyin":"Líbié zǒngshì ràng rén shānggǎn.","vi":"Chia ly luôn khiến người ta buồn."},{"type":"simple","zh":"站台上，母女俩紧紧拥抱，不忍离别。","pinyin":"Zhàntái shàng, mǔnǚ liǎ jǐnjǐn yōngbào, bùrěn líbié.","vi":"Trên sân ga, hai mẹ con ôm chặt nhau, không nỡ chia xa."},{"type":"compound","zh":"虽然离别在即，但是大家都约好十年后再相聚。","pinyin":"Suīrán líbié zài jí, dànshì dàjiā dōu yuē hǎo shí nián hòu zài xiāngjù.","vi":"Tuy giờ chia tay đã cận kề, nhưng mọi người đều hẹn mười năm sau gặp lại."}],"related":[{"hanzi":"分别","pinyin":"fēnbié","vi":"chia tay"},{"hanzi":"告别","pinyin":"gàobié","vi":"từ biệt"},{"hanzi":"重逢","pinyin":"chóngféng","vi":"gặp lại"}],"traditional":"離別"},{"id":"离奇","hanzi":"离奇","pinyin":"líqí","meaning_vi":"ly kỳ, kỳ lạ khó tin","explanation":"离 (cách (khoảng cách)) + 奇 (kỳ diệu/kỳ lạ).","hsk_level":"7-9","tags":["tinh-tu","giai-tri"],"image":"🔮","examples":[{"type":"basic","zh":"这个案子很离奇。","pinyin":"Zhè ge'àn zi hěn líqí.","vi":"Vụ án này rất ly kỳ."},{"type":"simple","zh":"小说讲述了一个富商在旅馆里离奇失踪的故事。","pinyin":"Xiǎoshuō jiǎngshùle yí gè fùshāng zài lǚguǎn lǐ líqí shīzōng de gùshi.","vi":"Cuốn tiểu thuyết kể câu chuyện một phú thương mất tích bí ẩn trong khách sạn."},{"type":"compound","zh":"他的经历虽然离奇，但是每一件事都有证据。","pinyin":"Tā de jīnglì suīrán líqí, dànshì měi yí jiàn shì dōu yǒu zhèngjù.","vi":"Trải nghiệm của anh ấy tuy ly kỳ, nhưng việc nào cũng có bằng chứng."}],"related":[{"hanzi":"奇怪","pinyin":"qíguài","vi":"kỳ lạ"},{"hanzi":"稀奇","pinyin":"xīqí","vi":"hiếm lạ"},{"hanzi":"离奇古怪","pinyin":"líqígǔguài","vi":"kỳ quái ly kỳ"}],"traditional":"離奇"},{"id":"离心力","hanzi":"离心力","pinyin":"líxīnlì","meaning_vi":"lực ly tâm","explanation":"离 (cách (khoảng cách)) + 心 (tâm lý/tâm huyết) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌀","examples":[{"type":"basic","zh":"洗衣机靠离心力甩干。","pinyin":"Xǐyījī kào líxīnlì shuǎigān.","vi":"Máy giặt dựa vào lực ly tâm để vắt khô."},{"type":"simple","zh":"汽车急转弯时，乘客会感到一股强大的离心力。","pinyin":"Qìchē jízhuǎnwān shí, chéngkè huì gǎndào yì gǔ qiángdà de líxīnlì.","vi":"Khi ô tô cua gấp, hành khách sẽ cảm thấy một lực ly tâm mạnh."},{"type":"compound","zh":"转速越快，离心力就越大，所以过山车上要系紧安全带。","pinyin":"Zhuànsù yuè kuài, líxīnlì jiù yuè dà, suǒyǐ guòshānchē shàng yào jì jǐn ānquándài.","vi":"Tốc độ quay càng nhanh thì lực ly tâm càng lớn, vì vậy trên tàu lượn phải thắt chặt dây an toàn."}],"related":[{"hanzi":"向心力","pinyin":"xiàngxīnlì","vi":"lực hướng tâm"},{"hanzi":"引力","pinyin":"yǐnlì","vi":"lực hấp dẫn"},{"hanzi":"物理","pinyin":"wùlǐ","vi":"vật lý"}],"traditional":"離心力"},{"id":"邻国","hanzi":"邻国","pinyin":"Línguó","meaning_vi":"nước láng giềng","explanation":"邻 (láng giềng/lân cận) + 国 (nước).","hsk_level":"7-9","tags":["danh-tu","dia-danh","xa-hoi"],"image":"🗺️","examples":[{"type":"basic","zh":"越南是中国的邻国。","pinyin":"Yuènán shì Zhōngguó de Línguó.","vi":"Việt Nam là nước láng giềng của Trung Quốc."},{"type":"simple","zh":"这次地震波及了周边好几个邻国。","pinyin":"Zhè cì dìzhèn bōjíle zhōubiān hǎojǐ gè Línguó.","vi":"Trận động đất này đã ảnh hưởng đến mấy nước láng giềng xung quanh."},{"type":"compound","zh":"只要与邻国和睦相处，边境地区就能安定繁荣。","pinyin":"Zhǐyào yǔ Línguó hémù xiāngchǔ, biānjìng dìqū jiù néng āndìng fánróng.","vi":"Chỉ cần chung sống hòa thuận với các nước láng giềng, vùng biên giới sẽ ổn định và phồn vinh."}],"related":[{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"},{"hanzi":"周边国家","pinyin":"zhōubiānguójiā","vi":"các nước xung quanh"},{"hanzi":"邻里","pinyin":"línlǐ","vi":"láng giềng"}],"traditional":"鄰國"},{"id":"临近","hanzi":"临近","pinyin":"línjìn","meaning_vi":"cận kề, sắp tới gần","explanation":"临 (lâm sàng/đối mặt) + 近 (gần).","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"考试临近了。","pinyin":"Kǎoshì línjìn le.","vi":"Kỳ thi đã đến gần."},{"type":"simple","zh":"春节临近，火车站里挤满了回家的人。","pinyin":"Chūnjié línjìn, huǒchēzhàn lǐ jǐmǎnle huíjiā de rén.","vi":"Tết Nguyên đán cận kề, nhà ga chật kín người về quê."},{"type":"compound","zh":"随着婚期临近，她既兴奋又紧张，每晚都睡不好。","pinyin":"Suízhe hūnqī línjìn, tā jì xīngfèn yòu jǐnzhāng, měi wǎn dōu shuì bù hǎo.","vi":"Ngày cưới đến gần, cô ấy vừa háo hức vừa hồi hộp, tối nào cũng ngủ không ngon."}],"related":[{"hanzi":"接近","pinyin":"jiējìn","vi":"tiếp cận"},{"hanzi":"靠近","pinyin":"kàojìn","vi":"đến gần"},{"hanzi":"即将","pinyin":"jíjiāng","vi":"sắp sửa"}],"traditional":"臨近"},{"id":"林立","hanzi":"林立","pinyin":"línlì","meaning_vi":"mọc lên san sát như rừng (nhà cao tầng)","explanation":"林 (rừng cây) + 立 (lập trường/thiết lập).","hsk_level":"7-9","tags":["dong-tu","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"街上商店林立。","pinyin":"Jiēshàng shāngdiàn línlì.","vi":"Trên phố cửa hàng mọc san sát."},{"type":"simple","zh":"浦东江边高楼林立，夜景非常壮观。","pinyin":"Pǔdōng jiāngbiān gāolóu línlì, yèjǐng fēicháng zhuàngguān.","vi":"Ven sông Phố Đông nhà cao tầng mọc san sát, cảnh đêm vô cùng hoành tráng."},{"type":"compound","zh":"三十年前这里还是一片稻田，如今却已工厂林立。","pinyin":"Sānshí niánqián zhèlǐ háishì yípiàn dàotián, rújīn què yǐ gōngchǎng línlì.","vi":"Ba mươi năm trước nơi đây vẫn là cánh đồng lúa, giờ đây nhà máy đã mọc lên san sát."}],"related":[{"hanzi":"高楼林立","pinyin":"gāolóulínlì","vi":"nhà cao tầng san sát"},{"hanzi":"密集","pinyin":"mìjí","vi":"dày đặc"},{"hanzi":"耸立","pinyin":"sǒnglì","vi":"sừng sững"}]},{"id":"邻里","hanzi":"邻里","pinyin":"línlǐ","meaning_vi":"hàng xóm láng giềng","explanation":"邻 (láng giềng/lân cận) + 里 (trong).","hsk_level":"7-9","tags":["danh-tu","gia-dinh","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"邻里之间要互相帮助。","pinyin":"Línlǐ zhījiān yào hùxiāng bāngzhù.","vi":"Hàng xóm láng giềng phải giúp đỡ lẫn nhau."},{"type":"simple","zh":"社区每月举办一次邻里聚餐，大家都很喜欢。","pinyin":"Shèqū měiyuè jǔbàn yí cì línlǐ jùcān, dàjiā dōu hěn xǐhuan.","vi":"Mỗi tháng khu dân cư tổ chức một bữa ăn hàng xóm, mọi người đều rất thích."},{"type":"compound","zh":"因为邻里关系和睦，所以这栋楼从来没发生过争吵。","pinyin":"Yīnwèi línlǐ guānxì hémù, suǒyǐ zhè dòng lóu cónglái méi fāshēngguò zhēngchǎo.","vi":"Vì quan hệ hàng xóm hòa thuận nên tòa nhà này chưa từng xảy ra cãi vã."}],"related":[{"hanzi":"邻居","pinyin":"línjū","vi":"hàng xóm"},{"hanzi":"街坊","pinyin":"jiēfang","vi":"hàng phố"},{"hanzi":"邻里关系","pinyin":"línlǐguānxì","vi":"quan hệ láng giềng"}],"traditional":"鄰里"},{"id":"淋浴","hanzi":"淋浴","pinyin":"línyù","meaning_vi":"tắm vòi hoa sen","explanation":"淋 (dầm (mưa)) + 浴 (tắm gội).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🚿","examples":[{"type":"basic","zh":"我每天早上淋浴。","pinyin":"Wǒ měitiān zǎoshang línyù.","vi":"Sáng nào tôi cũng tắm vòi sen."},{"type":"simple","zh":"健身房的淋浴间在更衣室的最里面。","pinyin":"Jiànshēnfáng de línyù jiān zài gēngyīshì de zuì lǐmiàn.","vi":"Phòng tắm vòi sen của phòng gym ở trong cùng phòng thay đồ."},{"type":"compound","zh":"既然热水器修好了，你就先去淋浴吧。","pinyin":"Jìrán rèshuǐqì xiūhǎo le, nǐ jiù xiān qù línyù ba.","vi":"Bình nóng lạnh đã sửa xong rồi, vậy bạn đi tắm trước đi."}],"related":[{"hanzi":"洗澡","pinyin":"xǐzǎo","vi":"tắm"},{"hanzi":"浴室","pinyin":"yùshì","vi":"phòng tắm"},{"hanzi":"泡澡","pinyin":"pàozǎo","vi":"tắm bồn"}]},{"id":"临终","hanzi":"临终","pinyin":"línzhōng","meaning_vi":"lúc lâm chung, sắp qua đời","explanation":"临 (lâm sàng/đối mặt) + 终 (cuối cùng/suốt đời).","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"🕯️","examples":[{"type":"basic","zh":"他临终前留下遗言。","pinyin":"Tā línzhōng qián liúxià yíyán.","vi":"Trước lúc lâm chung ông ấy để lại di ngôn."},{"type":"simple","zh":"老人临终时把那块祖传的玉佩交给了孙女。","pinyin":"Lǎorén línzhōng shí bǎ nà kuài zǔchuán de yùpèi jiāogěile sūnnǚ.","vi":"Lúc lâm chung, cụ già trao miếng ngọc bội gia truyền cho cháu gái."},{"type":"compound","zh":"虽然父亲临终前没能见到儿子，但是他留下了一封长信。","pinyin":"Suīrán fùqīn línzhōng qián méi néng jiàndào érzi, dànshì tā liúxiàle yì fēng cháng xìn.","vi":"Tuy trước lúc lâm chung người cha không gặp được con trai, nhưng ông đã để lại một bức thư dài."}],"related":[{"hanzi":"去世","pinyin":"qùshì","vi":"qua đời"},{"hanzi":"遗言","pinyin":"yíyán","vi":"lời trăng trối"},{"hanzi":"临死","pinyin":"línsǐ","vi":"sắp chết"}],"traditional":"臨終"},{"id":"灵丹妙药","hanzi":"灵丹妙药","pinyin":"língdān-miàoyào","meaning_vi":"thuốc tiên diệu kỳ (giải pháp thần kỳ)","explanation":"灵 (linh hoạt/linh hồn) + 丹 (丹) + 妙 (tuyệt diệu/khéo léo) + 药 (thuốc).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💊","examples":[{"type":"basic","zh":"世上没有灵丹妙药。","pinyin":"Shìshàng méiyǒu língdānmiàoyào.","vi":"Trên đời không có thuốc tiên."},{"type":"simple","zh":"很多人把减肥茶当成灵丹妙药，结果伤了身体。","pinyin":"Hěn duō rén bǎ jiǎnféi chá dàngchéng língdānmiàoyào, jiéguǒ shāngle shēntǐ.","vi":"Nhiều người coi trà giảm cân là thần dược, kết quả lại hại sức khỏe."},{"type":"compound","zh":"即使有再好的灵丹妙药，也代替不了规律的作息。","pinyin":"Jíshǐ yǒu zài hǎo de língdānmiàoyào, yě dàitì bùliǎo guīlǜ de zuòxī.","vi":"Dù có thần dược tốt đến đâu cũng không thể thay thế được nếp sinh hoạt điều độ."}],"related":[{"hanzi":"良药","pinyin":"liángyào","vi":"thuốc tốt"},{"hanzi":"万能药","pinyin":"wànnéngyào","vi":"thuốc chữa bách bệnh"},{"hanzi":"秘方","pinyin":"mìfāng","vi":"bài thuốc bí truyền"}],"traditional":"靈丹妙藥"},{"id":"零花钱","hanzi":"零花钱","pinyin":"línghuāqián","meaning_vi":"tiền tiêu vặt","explanation":"零 (số 0) + 花 (tiêu (tiền/thời gian)) + 钱 (钱).","hsk_level":"7-9","tags":["danh-tu","tien-te","sinh-hoat"],"image":"💵","examples":[{"type":"basic","zh":"妈妈给我零花钱。","pinyin":"Māma gěi wǒ línghuāqián.","vi":"Mẹ cho tôi tiền tiêu vặt."},{"type":"simple","zh":"他把每周的零花钱都存进了小猪储钱罐。","pinyin":"Tā bǎ měizhōu de línghuāqián dōu cún jìnle xiǎo zhū chǔ qián guàn.","vi":"Cậu bé bỏ hết tiền tiêu vặt hằng tuần vào ống heo."},{"type":"compound","zh":"如果你这次考得好，我就多给你一些零花钱。","pinyin":"Rúguǒ nǐ zhè cì kǎo de hǎo, wǒ jiù duō gěi nǐ yìxiē línghuāqián.","vi":"Nếu lần này con thi tốt, bố sẽ cho con thêm ít tiền tiêu vặt."}],"related":[{"hanzi":"零用钱","pinyin":"língyòngqián","vi":"tiền tiêu vặt"},{"hanzi":"压岁钱","pinyin":"yāsuìqián","vi":"tiền mừng tuổi"},{"hanzi":"零钱","pinyin":"língqián","vi":"tiền lẻ"}],"traditional":"零花錢"},{"id":"灵巧","hanzi":"灵巧","pinyin":"língqiǎo","meaning_vi":"khéo léo tinh xảo","explanation":"灵 (linh hoạt/linh hồn) + 巧 (巧).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✨","examples":[{"type":"basic","zh":"她的手非常灵巧。","pinyin":"Tā de shǒu fēicháng língqiǎo.","vi":"Đôi tay cô ấy vô cùng khéo léo."},{"type":"simple","zh":"小猴子灵巧地从一棵树跳到了另一棵树上。","pinyin":"Xiǎo hóuzi língqiǎo de cóng yì kē shù tiào dàole lìngyì kē shù shàng.","vi":"Chú khỉ con nhanh nhẹn nhảy từ cây này sang cây khác."},{"type":"compound","zh":"这种机器人不但动作灵巧，而且能分辨不同的水果。","pinyin":"Zhè zhǒng jīqìrén búdàn dòngzuò língqiǎo, érqiě néng fēnbiàn bùtóng de shuǐguǒ.","vi":"Loại robot này không những cử động khéo léo mà còn phân biệt được các loại trái cây khác nhau."}],"related":[{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"心灵手巧","pinyin":"xīnlíngshǒuqiǎo","vi":"khéo tay"},{"hanzi":"笨拙","pinyin":"bènzhuō","vi":"vụng về"}],"traditional":"靈巧"},{"id":"零碎","hanzi":"零碎","pinyin":"língsuì","meaning_vi":"lặt vặt, vụn vặt","explanation":"零 (số 0) + 碎 (vỡ vụn).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🧩","examples":[{"type":"basic","zh":"抽屉里都是零碎东西。","pinyin":"Chōuti lǐ dōu shì língsuì dōngxi.","vi":"Trong ngăn kéo toàn đồ lặt vặt."},{"type":"simple","zh":"她利用零碎的时间在地铁上背单词。","pinyin":"Tā lìyòng língsuì de shíjiān zài dìtiě shàng bèi dāncí.","vi":"Cô ấy tận dụng thời gian vụn vặt trên tàu điện ngầm để học thuộc từ vựng."},{"type":"compound","zh":"虽然这些记忆很零碎，但是拼起来就是完整的童年。","pinyin":"Suīrán zhèxiē jìyì hěn língsuì, dànshì pīnqǐlái jiùshì wánzhěng de tóngnián.","vi":"Tuy những ký ức này rất rời rạc, nhưng ghép lại chính là cả một tuổi thơ trọn vẹn."}],"related":[{"hanzi":"琐碎","pinyin":"suǒsuì","vi":"vụn vặt"},{"hanzi":"零散","pinyin":"língsǎn","vi":"rải rác"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"}]},{"id":"灵通","hanzi":"灵通","pinyin":"língtōng","meaning_vi":"nhanh nhạy thông tin","explanation":"灵 (linh hoạt/linh hồn) + 通 (thông suốt/phổ biến).","hsk_level":"7-9","tags":["tinh-tu"],"image":"📡","examples":[{"type":"basic","zh":"他的消息很灵通。","pinyin":"Tā de xiāoxi hěn língtōng.","vi":"Anh ấy rất nhanh nhạy tin tức."},{"type":"simple","zh":"楼下的小卖部老板消息灵通，什么新闻都知道。","pinyin":"Lóuxià de xiǎomàibù lǎobǎn xiāoxi língtōng, shénme xīnwén dōu zhīdào.","vi":"Ông chủ tiệm tạp hóa dưới nhà rất nhanh tin, tin tức gì cũng biết."},{"type":"compound","zh":"因为他消息灵通，所以总能第一个抢到打折机票。","pinyin":"Yīnwèi tā xiāoxi língtōng, suǒyǐ zǒngnéng dìyī gè qiǎng dào dǎzhé jīpiào.","vi":"Vì nhanh nhạy tin tức nên anh ấy luôn là người đầu tiên săn được vé máy bay giảm giá."}],"related":[{"hanzi":"消息灵通","pinyin":"xiāoxilíngtōng","vi":"nhanh nhạy tin tức"},{"hanzi":"灵敏","pinyin":"língmǐn","vi":"nhạy bén"},{"hanzi":"闭塞","pinyin":"bìsè","vi":"bế tắc"}],"traditional":"靈通"},{"id":"漏洞","hanzi":"漏洞","pinyin":"lòudòng","meaning_vi":"lỗ hổng (bảo mật/pháp luật)","explanation":"漏 (rò rỉ) + 洞 (hang động).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","phap-luat"],"image":"🕳️","examples":[{"type":"basic","zh":"系统存在安全漏洞。","pinyin":"Xìtǒng cúnzài ānquán lòudòng.","vi":"Hệ thống tồn tại lỗ hổng bảo mật."},{"type":"simple","zh":"黑客利用软件漏洞盗取了上万名用户的信息。","pinyin":"Hēikè lìyòng ruǎnjiàn lòudòng dàoqǔle shàng wànmíng yònghù de xìnxī.","vi":"Tin tặc lợi dụng lỗ hổng phần mềm đánh cắp thông tin của hơn một vạn người dùng."},{"type":"compound","zh":"如果法律存在漏洞，就会有人钻空子逃避责任。","pinyin":"Rúguǒ fǎlǜ cúnzài lòudòng, jiù huì yǒurén zuānkòngzi táobì zérèn.","vi":"Nếu pháp luật có lỗ hổng, sẽ có người lách luật để trốn tránh trách nhiệm."}],"related":[{"hanzi":"缺陷","pinyin":"quēxiàn","vi":"khiếm khuyết"},{"hanzi":"漏洞百出","pinyin":"lòudòngbǎichū","vi":"đầy sơ hở"},{"hanzi":"弥补","pinyin":"míbǔ","vi":"bù đắp"}]},{"id":"漏网之鱼","hanzi":"漏网之鱼","pinyin":"lòuwǎng-zhīyú","meaning_vi":"cá lọt lưới (tội phạm trốn thoát)","explanation":"漏 (rò rỉ) + 网 (mạng lưới) + 之 (của (trợ từ văn viết)) + 鱼 (cá).","hsk_level":"7-9","tags":["thanh-ngu","phap-luat"],"image":"🐟","examples":[{"type":"basic","zh":"他是一条漏网之鱼。","pinyin":"Tā shì yì tiáo lòuwǎngzhīyú.","vi":"Hắn là một con cá lọt lưới."},{"type":"simple","zh":"警方展开全城搜捕，决不放过一条漏网之鱼。","pinyin":"Jǐngfāng zhǎnkāi quánchéng sōubǔ, juébú fàngguò yì tiáo lòuwǎngzhīyú.","vi":"Cảnh sát mở cuộc truy bắt khắp thành phố, quyết không để lọt một con cá nào."},{"type":"compound","zh":"虽然主犯已经落网，但是还有几条漏网之鱼在逃。","pinyin":"Suīrán zhǔfàn yǐjīng luòwǎng, dànshì háiyǒu jǐ tiáo lòuwǎngzhīyú zài táo.","vi":"Tuy chủ mưu đã sa lưới, nhưng vẫn còn vài kẻ lọt lưới đang lẩn trốn."}],"related":[{"hanzi":"逃犯","pinyin":"táofàn","vi":"tội phạm bỏ trốn"},{"hanzi":"漏网","pinyin":"lòuwǎng","vi":"lọt lưới"},{"hanzi":"一网打尽","pinyin":"yìwǎngdǎjìn","vi":"bắt gọn một mẻ"}],"traditional":"漏網之魚"},{"id":"龙舟","hanzi":"龙舟","pinyin":"lóngzhōu","meaning_vi":"thuyền rồng (đua thuyền Tết Đoan Ngọ)","explanation":"龙 (con rồng) + 舟 (con thuyền (văn viết)).","hsk_level":"7-9","tags":["danh-tu","van-hoa","the-thao"],"image":"🚣","examples":[{"type":"basic","zh":"端午节要赛龙舟。","pinyin":"Duānwǔjié yào sàilóngzhōu.","vi":"Tết Đoan Ngọ có đua thuyền rồng."},{"type":"simple","zh":"二十名划手随着鼓声把龙舟划得飞快。","pinyin":"Èrshí míng huá shǒu suízhe gǔshēng bǎ lóngzhōu huá de fēikuài.","vi":"Hai mươi tay chèo theo nhịp trống chèo thuyền rồng đi như bay."},{"type":"compound","zh":"龙舟一冲过终点，岸上的观众就欢呼起来。","pinyin":"Lóngzhōu yì chōngguò zhōngdiǎn, ànshàng de guānzhòng jiù huānhū qǐlái.","vi":"Thuyền rồng vừa lao qua vạch đích, khán giả trên bờ liền reo hò."}],"related":[{"hanzi":"赛龙舟","pinyin":"sàilóngzhōu","vi":"đua thuyền rồng"},{"hanzi":"端午节","pinyin":"Duānwǔjié","vi":"Tết Đoan Ngọ"},{"hanzi":"粽子","pinyin":"zòngzi","vi":"bánh ú"}],"traditional":"龍舟"},{"id":"路程","hanzi":"路程","pinyin":"lùchéng","meaning_vi":"quãng đường, lộ trình","explanation":"路 (lộ – đường) + 程 (trình – chặng) → quãng đường, chặng đường đi; nghĩa bóng: hành trình. VD: 路程很远, 人生路程.","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"路程不算太远。","pinyin":"Lùchéng búsuàn tài yuǎn.","vi":"Quãng đường không tính là quá xa."},{"type":"simple","zh":"从河内到下龙湾的路程大约需要两个半小时。","pinyin":"Cóng Hénèi dào Xiàlóngwān de lùchéng dàyuē xūyào liǎng gè bànxiǎoshí.","vi":"Quãng đường từ Hà Nội đến vịnh Hạ Long mất khoảng hai tiếng rưỡi."},{"type":"compound","zh":"因为路程太长，所以我们决定中途在服务区休息一下。","pinyin":"Yīnwèi lùchéng tài cháng, suǒyǐ wǒmen juédìng zhōngtú zài fúwùqū xiūxi yíxià.","vi":"Vì quãng đường quá dài nên chúng tôi quyết định dừng nghỉ ở trạm dừng chân giữa đường."}],"related":[{"hanzi":"路途","pinyin":"lùtú","vi":"đường đi"},{"hanzi":"距离","pinyin":"jùlí","vi":"khoảng cách"},{"hanzi":"旅程","pinyin":"lǚchéng","vi":"hành trình"}]},{"id":"陆陆续续","hanzi":"陆陆续续","pinyin":"lùlùxùxù","meaning_vi":"lần lượt nối tiếp nhau","explanation":"陆 (đất liền/lần lượt) + 陆 (đất liền/lần lượt) + 续 (续) + 续 (续).","hsk_level":"7-9","tags":["pho-tu"],"image":"🚶‍♂️","examples":[{"type":"basic","zh":"客人陆陆续续到了。","pinyin":"Kèrén lùlùxùxù dào le.","vi":"Khách lần lượt kéo đến."},{"type":"simple","zh":"下课铃响后，学生们陆陆续续走出了教室。","pinyin":"Xiàkè líng xiǎng hòu, xuéshengmen lùlùxùxù zǒuchūle jiàoshì.","vi":"Chuông tan học reo, học sinh lần lượt bước ra khỏi lớp."},{"type":"compound","zh":"雨一停，街上的小摊就陆陆续续摆了出来。","pinyin":"Yǔ yì tíng, jiēshàng de xiǎotān jiù lùlùxùxù bǎile chūlái.","vi":"Mưa vừa tạnh, các sạp hàng nhỏ trên phố lại lần lượt bày ra."}],"related":[{"hanzi":"陆续","pinyin":"lùxù","vi":"lần lượt"},{"hanzi":"接连","pinyin":"jiēlián","vi":"liên tiếp"},{"hanzi":"断断续续","pinyin":"duànduànxùxù","vi":"lúc có lúc không"}],"traditional":"陸陸續續"},{"id":"露面","hanzi":"露面","pinyin":"lòumiàn","meaning_vi":"lộ diện, xuất hiện trước công chúng","explanation":"露 (tiết lộ/sương mù) + 面 (diện mạo/bề mặt).","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"他很少公开露面。","pinyin":"Tā hěn shǎo gōngkāi lòumiàn.","vi":"Ông ấy rất ít khi xuất hiện công khai."},{"type":"simple","zh":"那位歌星退出乐坛后第一次在电视上露面。","pinyin":"Nà wèi gēxīng tuìchū yuètán hòu dìyīcì zài diànshì shàng lòumiàn.","vi":"Ca sĩ đó lần đầu lộ diện trên truyền hình kể từ khi rút khỏi làng nhạc."},{"type":"compound","zh":"虽然导演没有露面，但是他通过视频向观众表示了感谢。","pinyin":"Suīrán dǎoyǎn méiyǒu lòumiàn, dànshì tā tōngguò shìpín xiàng guānzhòng biǎoshìle gǎnxiè.","vi":"Tuy đạo diễn không xuất hiện, nhưng ông đã gửi lời cảm ơn khán giả qua video."}],"related":[{"hanzi":"出面","pinyin":"chūmiàn","vi":"ra mặt"},{"hanzi":"亮相","pinyin":"liàngxiàng","vi":"xuất hiện"},{"hanzi":"露脸","pinyin":"lòuliǎn","vi":"lộ mặt"}]},{"id":"露天","hanzi":"露天","pinyin":"lùtiān","meaning_vi":"ngoài trời","explanation":"露 (tiết lộ/sương mù) + 天 (ngày).","hsk_level":"7-9","tags":["tinh-tu","dia-diem"],"image":"🌤️","examples":[{"type":"basic","zh":"我们去看露天电影。","pinyin":"Wǒmen qù kàn lùtiān diànyǐng.","vi":"Chúng ta đi xem phim ngoài trời."},{"type":"simple","zh":"夏天的晚上，广场上的露天烧烤摊坐满了人。","pinyin":"Xiàtiān de wǎnshang, guǎngchǎng shàng de lùtiān shāokǎo tān zuò mǎnle rén.","vi":"Tối mùa hè, các quán nướng ngoài trời ở quảng trường kín chỗ."},{"type":"compound","zh":"如果明天下雨，露天音乐会就改到体育馆举行。","pinyin":"Rúguǒ míngtiān xiàyǔ, lùtiān yīnyuèhuì jiù gǎi dào tǐyùguǎn jǔxíng.","vi":"Nếu mai trời mưa, buổi hòa nhạc ngoài trời sẽ chuyển vào nhà thi đấu."}],"related":[{"hanzi":"户外","pinyin":"hùwài","vi":"ngoài trời"},{"hanzi":"室外","pinyin":"shìwài","vi":"ngoài trời"},{"hanzi":"室内","pinyin":"shìnèi","vi":"trong nhà"}]},{"id":"路途","hanzi":"路途","pinyin":"lùtú","meaning_vi":"đường đi, hành trình","explanation":"路 (路) + 途 (con đường/tiền đồ).","hsk_level":"7-9","tags":["danh-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"路途遥远，多保重。","pinyin":"Lùtú yáoyuǎn, duō bǎozhòng.","vi":"Đường xa vạn dặm, bảo trọng nhé."},{"type":"simple","zh":"为了见网友，他忍受了三天三夜的路途颠簸。","pinyin":"Wèile jiàn wǎngyǒu, tā rěnshòule sān tiān sān yè de lùtú diānbǒ.","vi":"Để gặp bạn trên mạng, anh ấy chịu đựng ba ngày ba đêm đường xá xóc nảy."},{"type":"compound","zh":"虽然路途艰险，但是探险队还是按时到达了雪山脚下。","pinyin":"Suīrán lùtú jiānxiǎn, dànshì tànxiǎn duì háishì ànshí dàodále xuěshān jiǎoxià.","vi":"Tuy đường đi gian hiểm, nhưng đoàn thám hiểm vẫn đến chân núi tuyết đúng giờ."}],"related":[{"hanzi":"路程","pinyin":"lùchéng","vi":"quãng đường"},{"hanzi":"旅途","pinyin":"lǚtú","vi":"chuyến đi"},{"hanzi":"路途遥远","pinyin":"lùtúyáoyuǎn","vi":"đường xa"}]},{"id":"录用","hanzi":"录用","pinyin":"lùyòng","meaning_vi":"tuyển dụng chính thức","explanation":"录 (ghi chép/tuyển dụng) + 用 (vận dụng/công dụng).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"她被公司录用了。","pinyin":"Tā bèi gōngsī lùyòng le.","vi":"Cô ấy đã được công ty tuyển dụng."},{"type":"simple","zh":"这次招聘一共有三百人报名，只录用了五个。","pinyin":"Zhè cì zhāopìn yí gòngyǒu sān bǎi rén bàomíng, zhǐ lùyòngle wǔ gè.","vi":"Đợt tuyển dụng này có tổng cộng ba trăm người đăng ký, chỉ tuyển năm người."},{"type":"compound","zh":"一旦被正式录用，你就要和公司签三年合同。","pinyin":"Yídàn bèi zhèngshì lùyòng, nǐ jiùyào hé gōngsī qiān sān nián hétong.","vi":"Một khi được tuyển chính thức, bạn sẽ phải ký hợp đồng ba năm với công ty."}],"related":[{"hanzi":"录取","pinyin":"lùqǔ","vi":"tuyển"},{"hanzi":"聘用","pinyin":"pìnyòng","vi":"thuê"},{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"}],"traditional":"錄用"},{"id":"陆运","hanzi":"陆运","pinyin":"lùyùn","meaning_vi":"vận chuyển đường bộ","explanation":"陆 (đất liền/lần lượt) + 运 (vận dụng/vận hành).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"🚚","examples":[{"type":"basic","zh":"这批货物走陆运。","pinyin":"Zhè pī huòwù zǒu lùyùn.","vi":"Lô hàng này đi đường bộ."},{"type":"simple","zh":"从昆明到河内的水果主要依靠陆运。","pinyin":"Cóng Kūnmíng dào Hénèi de shuǐguǒ zhǔyào yīkào lùyùn.","vi":"Trái cây từ Côn Minh đến Hà Nội chủ yếu dựa vào vận chuyển đường bộ."},{"type":"compound","zh":"虽然陆运比海运贵一些，但是时间短得多。","pinyin":"Suīrán lùyùn bǐ hǎiyùn guì yìxiē, dànshì shíjiān duǎn de duō.","vi":"Tuy vận chuyển đường bộ đắt hơn đường biển một chút, nhưng thời gian ngắn hơn nhiều."}],"related":[{"hanzi":"海运","pinyin":"hǎiyùn","vi":"vận chuyển đường biển"},{"hanzi":"空运","pinyin":"kōngyùn","vi":"vận chuyển hàng không"},{"hanzi":"公路运输","pinyin":"gōnglùyùnshū","vi":"vận tải đường bộ"}],"traditional":"陸運"},{"id":"论点","hanzi":"论点","pinyin":"lùndiǎn","meaning_vi":"luận điểm","explanation":"论 (luận văn/bàn luận) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📌","examples":[{"type":"basic","zh":"你的论点很明确。","pinyin":"Nǐ de lùndiǎn hěn míngquè.","vi":"Luận điểm của bạn rất rõ ràng."},{"type":"simple","zh":"老师要求我们在第一段就清楚提出论点。","pinyin":"Lǎoshī yāoqiú wǒmen zài dìyī duàn jiù qīngchu tíchū lùndiǎn.","vi":"Thầy giáo yêu cầu chúng tôi nêu rõ luận điểm ngay trong đoạn đầu tiên."},{"type":"compound","zh":"如果论点站不住脚，那么论证再长也没有说服力。","pinyin":"Rúguǒ lùndiǎn zhàn bú zhùjiǎo, nàme lùnzhèng zài cháng yě méiyǒu shuōfúlì.","vi":"Nếu luận điểm không vững, thì lập luận dài đến mấy cũng không có sức thuyết phục."}],"related":[{"hanzi":"论据","pinyin":"lùnjù","vi":"luận cứ"},{"hanzi":"论证","pinyin":"lùnzhèng","vi":"luận chứng"},{"hanzi":"观点","pinyin":"guāndiǎn","vi":"quan điểm"}],"traditional":"論點"},{"id":"论据","hanzi":"论据","pinyin":"lùnjù","meaning_vi":"luận cứ","explanation":"论 (luận văn/bàn luận) + 据 (căn cứ/chiếm giữ).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📑","examples":[{"type":"basic","zh":"这些论据不够充分。","pinyin":"Zhèxiē lùnjù búgòu chōngfèn.","vi":"Những luận cứ này chưa đủ thuyết phục."},{"type":"simple","zh":"他用三组统计数据作为论据支持自己的观点。","pinyin":"Tāyòng sān zǔ tǒngjì shùjù zuòwéi lùnjù zhīchí zìjǐ de guāndiǎn.","vi":"Anh ấy dùng ba bộ số liệu thống kê làm luận cứ để ủng hộ quan điểm của mình."},{"type":"compound","zh":"只有论据真实可靠，结论才能让评委信服。","pinyin":"Zhǐyǒu lùnjù zhēnshí kěkào, jiélùn cáinéng ràng píngwěi xìnfú.","vi":"Chỉ khi luận cứ chân thực đáng tin, kết luận mới khiến ban giám khảo tin phục."}],"related":[{"hanzi":"论点","pinyin":"lùndiǎn","vi":"luận điểm"},{"hanzi":"证据","pinyin":"zhèngjù","vi":"chứng cứ"},{"hanzi":"论证","pinyin":"lùnzhèng","vi":"luận chứng"}],"traditional":"論據"},{"id":"论述","hanzi":"论述","pinyin":"lùnshù","meaning_vi":"luận thuật, trình bày phân tích","explanation":"论 (luận văn/bàn luận) + 述 (thuật lại/trình bày).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🗣️","examples":[{"type":"basic","zh":"书中详细论述了这个问题。","pinyin":"Shū zhōng xiángxì lùnshùle zhè ge wèntí.","vi":"Trong sách đã luận giải chi tiết vấn đề này."},{"type":"simple","zh":"这篇论文从三个角度论述了城市化对农村的影响。","pinyin":"Zhè piān lùnwén cóng sān gè jiǎodù lùnshùle chéngshìhuà duì nóngcūn de yǐngxiǎng.","vi":"Luận văn này phân tích ảnh hưởng của đô thị hóa đối với nông thôn từ ba góc độ."},{"type":"compound","zh":"他虽然论述得很全面，但是没有提出解决办法。","pinyin":"Tā suīrán lùnshù de hěn quánmiàn, dànshì méiyǒu tíchū jiějué bànfǎ.","vi":"Tuy anh ấy trình bày rất toàn diện, nhưng không đưa ra được biện pháp giải quyết."}],"related":[{"hanzi":"阐述","pinyin":"chǎnshù","vi":"trình bày"},{"hanzi":"论证","pinyin":"lùnzhèng","vi":"luận chứng"},{"hanzi":"叙述","pinyin":"xùshù","vi":"tường thuật"}],"traditional":"論述"},{"id":"炉火","hanzi":"炉火","pinyin":"lúhuǒ","meaning_vi":"lửa lò","explanation":"炉 (bếp lò) + 火 (火).","hsk_level":"7-9","tags":["danh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"炉火烧得正旺。","pinyin":"Lúhuǒ shāo de zhèng wàng.","vi":"Lửa lò đang cháy rất đượm."},{"type":"simple","zh":"冬夜里，一家人围坐在炉火旁听爷爷讲故事。","pinyin":"Dōng yèlǐ, yìjiārén wéizuò zài lúhuǒ pángtīng yéye jiǎng gùshi.","vi":"Đêm đông, cả nhà ngồi quanh bếp lửa nghe ông kể chuyện."},{"type":"compound","zh":"炉火一灭，屋里就冷得像冰窖一样，谁也睡不着。","pinyin":"Lúhuǒ yí miè, wū lǐ jiù lěng de xiàng bīngjiào yíyàng, shéi yě shuìbùzháo.","vi":"Lửa lò vừa tắt, trong nhà đã lạnh như hầm băng, chẳng ai ngủ được."}],"related":[{"hanzi":"炉子","pinyin":"lúzi","vi":"cái lò"},{"hanzi":"火炉","pinyin":"huǒlú","vi":"lò sưởi"},{"hanzi":"炉火纯青","pinyin":"lúhuǒchúnqīng","vi":"thuần thục điêu luyện"}],"traditional":"爐火"},{"id":"伦理","hanzi":"伦理","pinyin":"lúnlǐ","meaning_vi":"luân lý, đạo đức","explanation":"伦 (伦) + 理 (lý luận/quản lý).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"⚖️","examples":[{"type":"basic","zh":"这涉及医学伦理。","pinyin":"Zhè shèjí yīxué lúnlǐ.","vi":"Việc này liên quan đến y đức."},{"type":"simple","zh":"基因编辑技术引发了科学界关于伦理的激烈争论。","pinyin":"Jīyīn biānjí jìshù yǐnfāle kēxuéjiè guānyú lúnlǐ de jīliè zhēnglùn.","vi":"Công nghệ chỉnh sửa gen đã gây ra cuộc tranh luận gay gắt về đạo đức trong giới khoa học."},{"type":"compound","zh":"即使技术上可以实现，如果违背伦理，也不应该去做。","pinyin":"Jíshǐ jìshù shàng kěyǐ shíxiàn, rúguǒ wéibèi lúnlǐ, yě bù yīnggāi qù zuò.","vi":"Dù về kỹ thuật có thể làm được, nếu trái với luân lý thì cũng không nên làm."}],"related":[{"hanzi":"道德","pinyin":"dàodé","vi":"đạo đức"},{"hanzi":"伦理学","pinyin":"lúnlǐxué","vi":"đạo đức học"},{"hanzi":"伦理道德","pinyin":"lúnlǐdàodé","vi":"luân lý đạo đức"}],"traditional":"倫理"},{"id":"垃圾分类","hanzi":"垃圾分类","pinyin":"lājīfēnlèi","meaning_vi":"phân loại rác thải","explanation":"垃 (rác) + 圾 (rác) + 分 (phút) + 类 (loại hình/tương tự).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","sinh-hoat"],"image":"♻️","examples":[{"type":"basic","zh":"我们小区实行垃圾分类。","pinyin":"Wǒmen xiǎoqū shíxíng lājīfēnlèi.","vi":"Khu dân cư chúng tôi thực hiện phân loại rác."},{"type":"simple","zh":"社区志愿者每天早上在垃圾桶旁指导居民垃圾分类。","pinyin":"Shèqū zhìyuànzhě měitiān zǎoshang zài lājītǒng páng zhǐdǎo jūmín lājīfēnlèi.","vi":"Tình nguyện viên khu phố mỗi sáng đứng cạnh thùng rác hướng dẫn cư dân phân loại rác."},{"type":"compound","zh":"只要每个家庭都做好垃圾分类，资源回收率就会大大提高。","pinyin":"Zhǐyào měi gè jiātíng dōu zuò hǎo lājīfēnlèi, zīyuán huíshōu lǜ jiù huì dàdà tígāo.","vi":"Chỉ cần mỗi gia đình làm tốt việc phân loại rác, tỷ lệ tái chế sẽ tăng lên rất nhiều."}],"related":[{"hanzi":"垃圾","pinyin":"lājī","vi":"rác"},{"hanzi":"回收","pinyin":"huíshōu","vi":"tái chế"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"}],"traditional":"垃圾分類"},{"id":"捞取","hanzi":"捞取","pinyin":"lāoqǔ","meaning_vi":"kiếm chác (lợi ích bất chính)","explanation":"捞 (vớt (dưới nước lên)) + 取 (lấy).","hsk_level":"7-9","tags":["dong-tu"],"image":"🎣","examples":[{"type":"basic","zh":"他想捞取好处。","pinyin":"Tā xiǎng lāoqǔ hǎochù.","vi":"Hắn muốn kiếm chác lợi lộc."},{"type":"simple","zh":"有人借救灾之名捞取个人利益，令人愤慨。","pinyin":"Yǒurén jiè jiùzāi zhī míng lāoqǔ gèrén lìyì, lìngrén fènkǎi.","vi":"Có kẻ mượn danh cứu trợ thiên tai để vơ vét lợi ích cá nhân, khiến người ta phẫn nộ."},{"type":"compound","zh":"如果有人利用职权捞取钱财，就一定要严肃查处。","pinyin":"Rúguǒ yǒurén lìyòng zhíquán lāoqǔ qiáncái, jiù yídìngyào yánsù cháchǔ.","vi":"Nếu có kẻ lợi dụng chức quyền để vơ vét tiền của, nhất định phải điều tra xử lý nghiêm."}],"related":[{"hanzi":"捞","pinyin":"lāo","vi":"vớt"},{"hanzi":"牟取","pinyin":"móuqǔ","vi":"mưu lợi"},{"hanzi":"谋取私利","pinyin":"móuqǔsīlì","vi":"mưu lợi riêng"}],"traditional":"撈取"},{"id":"冷静期","hanzi":"冷静期","pinyin":"lěngjìngqī","meaning_vi":"thời gian bình tĩnh suy xét lại","explanation":"冷静 (lãnh tĩnh – bình tĩnh) + 期 (kỳ – thời kỳ) → thời gian để bình tĩnh suy xét lại trước khi quyết định. VD: 离婚冷静期 (30 ngày theo luật TQ).","hsk_level":"7-9","tags":["danh-tu","thoi-gian","phap-luat"],"image":"⏳","examples":[{"type":"basic","zh":"离婚有三十天冷静期。","pinyin":"Líhūn yǒu sānshí tiān lěngjìngqī.","vi":"Ly hôn có ba mươi ngày thời gian suy xét lại."},{"type":"simple","zh":"网购的商品通常有七天的冷静期可以退货。","pinyin":"Wǎnggòu de shāngpǐn tōngcháng yǒu qī tiān de lěngjìngqī kěyǐ tuìhuò.","vi":"Hàng mua trực tuyến thường có bảy ngày cân nhắc lại để có thể trả hàng."},{"type":"compound","zh":"如果冷静期内双方都改变了主意，离婚申请就会被撤回。","pinyin":"Rúguǒ lěngjìngqī nèi shuāngfāng dōu gǎibiànle zhǔyi, líhūn shēnqǐng jiù huì bèi chèhuí.","vi":"Nếu trong thời gian suy xét lại cả hai bên đều đổi ý, đơn ly hôn sẽ được rút lại."}],"related":[{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"},{"hanzi":"离婚","pinyin":"líhūn","vi":"ly hôn"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"suy nghĩ"}],"traditional":"冷靜期"},{"id":"冷落","hanzi":"冷落","pinyin":"lěngluò","meaning_vi":"lạnh nhạt, vắng vẻ hiu quạnh","explanation":"冷 (lạnh) + 落 (rơi rụng/thực hiện).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"😔","examples":[{"type":"basic","zh":"别冷落了客人。","pinyin":"Bié lěngluòle kèrén.","vi":"Đừng thờ ơ với khách."},{"type":"simple","zh":"自从有了弟弟，姐姐总觉得自己被父母冷落了。","pinyin":"Zìcóng yǒule dìdi, jiějie zǒng juéde zìjǐ bèi fùmǔ lěngluò le.","vi":"Từ khi có em trai, cô chị luôn cảm thấy mình bị bố mẹ lạnh nhạt."},{"type":"compound","zh":"新商场开业后，老街上的店铺就变得冷落起来。","pinyin":"Xīn shāngchǎng kāiyè hòu, lǎo jiēshàng de diànpù jiù biànde lěngluò qǐlái.","vi":"Sau khi trung tâm thương mại mới khai trương, các cửa hàng trên phố cũ trở nên vắng vẻ."}],"related":[{"hanzi":"冷淡","pinyin":"lěngdàn","vi":"lạnh nhạt"},{"hanzi":"冷清","pinyin":"lěngqīng","vi":"vắng vẻ"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"}]},{"id":"冷门","hanzi":"冷门","pinyin":"lěngmén","meaning_vi":"ít người quan tâm, ít phổ biến (ngành nghề, lĩnh vực); (đối thủ) không được đánh giá cao, ẩn số","explanation":"冷 (lãnh – lạnh) + 门 (môn – ngành, cửa) → ngành ít người theo, việc ít được quan tâm; trong thi đấu: kết quả bất ngờ. VD: 冷门专业, 爆冷门.","hsk_level":"7-9","tags":["tinh-tu"],"image":"❄️","examples":[{"type":"basic","zh":"考古是个冷门专业。","pinyin":"Kǎogǔ shì gè lěngmén zhuānyè.","vi":"Khảo cổ là một ngành ít người theo học."},{"type":"simple","zh":"这匹没人看好的冷门马竟然赢得了比赛。","pinyin":"Zhè pǐ méi rén kànhǎo de lěngmén mǎ jìngrán yíng déle bǐsài.","vi":"Con ngựa không được ai đánh giá cao này lại giành chiến thắng cuộc đua."},{"type":"compound","zh":"虽然这个专业比较冷门，但是毕业生的就业率很高。","pinyin":"Suīrán zhè ge zhuānyè bǐjiào lěngmén, dànshì bìyèshēng de jiùyè lǜ hěn gāo.","vi":"Tuy ngành này khá ít người theo, nhưng tỷ lệ có việc làm của sinh viên tốt nghiệp rất cao."}],"related":[{"hanzi":"热门","pinyin":"rèmén","vi":"được ưa chuộng"},{"hanzi":"冷僻","pinyin":"lěngpì","vi":"hiếm gặp"},{"hanzi":"爆冷门","pinyin":"bàolěngmén","vi":"kết quả bất ngờ"}],"traditional":"冷門"},{"id":"冷战","hanzi":"冷战","pinyin":"lěngzhàn","meaning_vi":"chiến tranh lạnh; giận dỗi không nói chuyện với nhau","explanation":"冷 (lạnh) + 战 (chiến đấu/chiến lược).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cam-xuc"],"image":"🧊","examples":[{"type":"basic","zh":"他俩又在冷战了。","pinyin":"Tā liǎ yòu zài lěngzhàn le.","vi":"Hai người họ lại đang chiến tranh lạnh."},{"type":"simple","zh":"冷战结束以后，世界格局发生了深刻变化。","pinyin":"Lěngzhàn jiéshù yǐhòu, shìjiè géjú fāshēngle shēnkè biànhuà.","vi":"Sau khi Chiến tranh Lạnh kết thúc, cục diện thế giới đã thay đổi sâu sắc."},{"type":"compound","zh":"与其跟丈夫冷战好几天，不如坐下来把话说清楚。","pinyin":"Yǔqí gēn zhàngfu lěngzhàn hǎo jǐtiān, bùrú zuò xiàlái bǎ huàshuō qīngchu.","vi":"Thay vì giận dỗi chồng mấy ngày liền, chi bằng ngồi xuống nói rõ mọi chuyện."}],"related":[{"hanzi":"热战","pinyin":"rèzhàn","vi":"chiến tranh nóng"},{"hanzi":"吵架","pinyin":"chǎojià","vi":"cãi nhau"},{"hanzi":"对抗","pinyin":"duìkàng","vi":"đối kháng"}],"traditional":"冷戰"},{"id":"懒散","hanzi":"懒散","pinyin":"lǎnsǎn","meaning_vi":"lười biếng uể oải, thiếu kỷ luật","explanation":"懒 (lười) + 散 (phân tán/tản văn).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🦥","examples":[{"type":"basic","zh":"他最近很懒散。","pinyin":"Tā zuìjìn hěn lǎnsǎn.","vi":"Dạo này anh ấy rất uể oải."},{"type":"simple","zh":"放了一个月暑假，孩子们都变得懒散起来。","pinyin":"Fàngle yí gèyuè shǔjià, háizimen dōu biànde lǎnsǎn qǐlái.","vi":"Nghỉ hè một tháng, bọn trẻ đều trở nên lười nhác."},{"type":"compound","zh":"如果团队作风懒散，再好的计划也难以完成。","pinyin":"Rúguǒ tuánduì zuòfēng lǎnsǎn, zài hǎo de jìhuà yě nányǐ wánchéng.","vi":"Nếu tác phong của nhóm uể oải, kế hoạch tốt đến mấy cũng khó hoàn thành."}],"related":[{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"},{"hanzi":"散漫","pinyin":"sǎnmàn","vi":"lỏng lẻo"},{"hanzi":"勤快","pinyin":"qínkuai","vi":"chăm chỉ"}],"traditional":"懶散"},{"id":"老龄","hanzi":"老龄","pinyin":"lǎolíng","meaning_vi":"tuổi già, cao tuổi","explanation":"老 (lão – già) + 龄 (linh – tuổi) → tuổi già, cao tuổi. VD: 人口老龄化, 老龄人口.","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"老龄人口逐年增加。","pinyin":"Lǎolíng rénkǒu zhúnián zēngjiā.","vi":"Dân số cao tuổi tăng dần qua từng năm."},{"type":"simple","zh":"社区为老龄居民开设了免费的健康讲座。","pinyin":"Shèqū wèi lǎolíng jūmín kāishèle miǎnfèi de jiànkāng jiǎngzuò.","vi":"Khu dân cư mở các buổi nói chuyện sức khỏe miễn phí cho cư dân cao tuổi."},{"type":"compound","zh":"随着老龄人口越来越多，养老服务的需求也在不断扩大。","pinyin":"Suízhe lǎolíng rénkǒu yuèláiyuè duō, yǎnglǎo fúwù de xūqiú yě zài búduàn kuòdà.","vi":"Cùng với dân số cao tuổi ngày càng đông, nhu cầu dịch vụ dưỡng lão cũng không ngừng tăng."}],"related":[{"hanzi":"老年","pinyin":"lǎonián","vi":"tuổi già"},{"hanzi":"高龄","pinyin":"gāolíng","vi":"cao tuổi"},{"hanzi":"老龄化","pinyin":"lǎolínghuà","vi":"già hóa"}],"traditional":"老齡"},{"id":"老龄化","hanzi":"老龄化","pinyin":"lǎolínghuà","meaning_vi":"già hóa dân số","explanation":"老龄 (tuổi già) + 化.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👴","examples":[{"type":"basic","zh":"人口老龄化加快了。","pinyin":"Rénkǒulǎolínghuà jiākuài le.","vi":"Già hóa dân số đã tăng tốc."},{"type":"simple","zh":"日本是世界上老龄化最严重的国家之一。","pinyin":"Rìběn shì shìjiè shàng lǎolínghuà zuì yánzhòng de guójiā zhīyī.","vi":"Nhật Bản là một trong những quốc gia già hóa dân số nghiêm trọng nhất thế giới."},{"type":"compound","zh":"因为出生率下降，所以人口老龄化问题越来越突出。","pinyin":"Yīnwèi chūshēnglǜ xiàjiàng, suǒyǐ rénkǒulǎolínghuà wèntí yuèláiyuè tūchū.","vi":"Vì tỷ lệ sinh giảm nên vấn đề già hóa dân số ngày càng nổi bật."}],"related":[{"hanzi":"人口老龄化","pinyin":"rénkǒu lǎolínghuà","vi":"già hóa dân số"},{"hanzi":"养老","pinyin":"yǎnglǎo","vi":"dưỡng lão"},{"hanzi":"少子化","pinyin":"shǎozǐhuà","vi":"giảm tỷ lệ sinh"}],"traditional":"老齡化"},{"id":"老字号","hanzi":"老字号","pinyin":"lǎozìhao","meaning_vi":"thương hiệu lâu đời nổi tiếng","explanation":"老 (già) + 字 (chữ) + 号 (ngày (trong tháng)).","hsk_level":"7-9","tags":["danh-tu","van-hoa","mua-sam"],"image":"🏮","examples":[{"type":"basic","zh":"这是一家老字号。","pinyin":"Zhè shì yìjiā lǎozìhao.","vi":"Đây là một cửa hiệu lâu đời."},{"type":"simple","zh":"全聚德是北京有名的烤鸭老字号。","pinyin":"Quánjùdé shì Běijīng yǒumíng de kǎoyā lǎozìhao.","vi":"Toàn Tụ Đức là thương hiệu vịt quay lâu đời nổi tiếng của Bắc Kinh."},{"type":"compound","zh":"这家老字号虽然开了一百多年，但是一直坚持手工制作。","pinyin":"Zhè jiālǎo zìhao suīrán kāile yī bǎi duōnián, dànshì yìzhí jiānchí shǒugōng zhìzuò.","vi":"Cửa hiệu lâu đời này tuy đã mở hơn một trăm năm, nhưng vẫn luôn kiên trì làm thủ công."}],"related":[{"hanzi":"品牌","pinyin":"pǐnpái","vi":"thương hiệu"},{"hanzi":"百年老店","pinyin":"bǎiniánlǎodiàn","vi":"cửa hàng trăm năm"},{"hanzi":"招牌","pinyin":"zhāopai","vi":"biển hiệu"}],"traditional":"老字號"},{"id":"礼节","hanzi":"礼节","pinyin":"lǐjié","meaning_vi":"lễ nghi, phép lịch sự","explanation":"礼 (lễ nghi/lễ phép) + 节 (节).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"他很懂礼节。","pinyin":"Tā hěn dǒng lǐjié.","vi":"Anh ấy rất hiểu lễ nghi."},{"type":"simple","zh":"在日本拜访别人时，进门要脱鞋，这是基本礼节。","pinyin":"Zài Rìběn bàifǎng biérén shí, jìnmén yào tuōxié, zhè shì jīběn lǐjié.","vi":"Khi đến thăm nhà người khác ở Nhật, vào cửa phải cởi giày, đây là phép lịch sự cơ bản."},{"type":"compound","zh":"虽然只是一次简单的会面，但是他在礼节上一点儿也不马虎。","pinyin":"Suīrán zhǐshì yí cì jiǎndān de huìmiàn, dànshì tā zài lǐjié shàng yìdiǎnr yě bù mǎhu.","vi":"Tuy chỉ là một buổi gặp mặt đơn giản, nhưng anh ấy không hề qua loa về mặt lễ nghi."}],"related":[{"hanzi":"礼貌","pinyin":"lǐmào","vi":"lễ phép"},{"hanzi":"礼仪","pinyin":"lǐyí","vi":"lễ nghi"},{"hanzi":"失礼","pinyin":"shīlǐ","vi":"thất lễ"}],"traditional":"禮節"},{"id":"理所当然","hanzi":"理所当然","pinyin":"lǐsuǒ-dāngrán","meaning_vi":"lẽ đương nhiên","explanation":"理 (lý luận/quản lý) + 所 (nơi) + 当 (当) + 然 (然).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✅","examples":[{"type":"basic","zh":"这是理所当然的。","pinyin":"Zhè shì lǐsuǒdāngrán de.","vi":"Đây là lẽ đương nhiên."},{"type":"simple","zh":"很多孩子把父母的付出看作理所当然。","pinyin":"Hěn duō háizi bǎ fùmǔ de fùchū kànzuò lǐsuǒdāngrán.","vi":"Nhiều đứa trẻ coi sự hy sinh của cha mẹ là điều đương nhiên."},{"type":"compound","zh":"既然你犯了错，理所当然要向大家道歉。","pinyin":"Jìrán nǐ fànle cuò, lǐsuǒdāngrán yào xiàng dàjiā dàoqiàn.","vi":"Đã phạm lỗi thì đương nhiên bạn phải xin lỗi mọi người."}],"related":[{"hanzi":"天经地义","pinyin":"tiānjīngdìyì","vi":"lẽ trời đất"},{"hanzi":"当然","pinyin":"dāngrán","vi":"đương nhiên"},{"hanzi":"不言而喻","pinyin":"bùyán'éryù","vi":"không nói cũng hiểu"}],"traditional":"理所當然"},{"id":"理想化","hanzi":"理想化","pinyin":"lǐxiǎnghuà","meaning_vi":"lý tưởng hóa","explanation":"理 (lý luận/quản lý) + 想 (muốn) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🌠","examples":[{"type":"basic","zh":"你把婚姻理想化了。","pinyin":"Nǐ bǎ hūnyīn lǐxiǎnghuà le.","vi":"Bạn đã lý tưởng hóa hôn nhân rồi."},{"type":"simple","zh":"他的创业计划太理想化，完全没考虑成本。","pinyin":"Tā de chuàngyè jìhuà tài lǐxiǎnghuà, wánquán méi kǎolǜ chéngběn.","vi":"Kế hoạch khởi nghiệp của anh ấy quá lý tưởng hóa, hoàn toàn không tính đến chi phí."},{"type":"compound","zh":"如果把出国生活想得过于理想化，到了国外就容易失望。","pinyin":"Rúguǒ bǎ chūguó shēnghuó xiǎng de guòyú lǐxiǎnghuà, dàole guówài jiù róngyì shīwàng.","vi":"Nếu tưởng tượng cuộc sống ở nước ngoài quá lý tưởng, khi ra nước ngoài sẽ dễ thất vọng."}],"related":[{"hanzi":"理想","pinyin":"lǐxiǎng","vi":"lý tưởng"},{"hanzi":"现实","pinyin":"xiànshí","vi":"hiện thực"},{"hanzi":"美化","pinyin":"měihuà","vi":"mỹ hóa"}]},{"id":"理性","hanzi":"理性","pinyin":"lǐxìng","meaning_vi":"lý tính","explanation":"理 (lý luận/quản lý) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["tinh-tu","danh-tu"],"image":"🧠","examples":[{"type":"basic","zh":"请保持理性。","pinyin":"Qǐng bǎochí lǐxìng.","vi":"Xin hãy giữ lý trí."},{"type":"simple","zh":"面对网上的谣言，我们应该理性地分析判断。","pinyin":"Miànduì wǎngshàng de yáoyán, wǒmen yīnggāi lǐxìng de fēnxī pànduàn.","vi":"Trước những tin đồn trên mạng, chúng ta nên phân tích phán đoán một cách lý tính."},{"type":"compound","zh":"吵架的时候人往往失去理性，所以最好先冷静一下。","pinyin":"Chǎojià de shíhou rén wǎngwǎng shīqù lǐxìng, suǒyǐ zuìhǎo xiān lěngjìng yíxià.","vi":"Khi cãi nhau con người thường mất lý trí, vì vậy tốt nhất nên bình tĩnh lại trước."}],"related":[{"hanzi":"感性","pinyin":"gǎnxìng","vi":"cảm tính"},{"hanzi":"理智","pinyin":"lǐzhì","vi":"lý trí"},{"hanzi":"冷静","pinyin":"lěngjìng","vi":"bình tĩnh"}]},{"id":"理性消费","hanzi":"理性消费","pinyin":"lǐxìngxiāofèi","meaning_vi":"tiêu dùng lý trí","explanation":"理性 (lý tính – lý trí) + 消费 (tiêu dùng) → tiêu dùng có lý trí, cân nhắc nhu cầu thật; trái với 冲动消费.","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🧠","examples":[{"type":"basic","zh":"年轻人要理性消费。","pinyin":"Niánqīngrén yào lǐxìngxiāofèi.","vi":"Người trẻ cần tiêu dùng lý trí."},{"type":"simple","zh":"“双十一”前，银行提醒大家理性消费，不要盲目囤货。","pinyin":"\"Shuāngshíyī\" qián, yínháng tíxǐng dàjiā lǐxìngxiāofèi, bú yào mángmù túnhuò.","vi":"Trước ngày \"11/11\", ngân hàng nhắc mọi người tiêu dùng lý trí, đừng tích trữ hàng mù quáng."},{"type":"compound","zh":"只要坚持理性消费，月底就不会再为信用卡账单发愁了。","pinyin":"Zhǐyào jiānchí lǐxìngxiāofèi, yuèdǐ jiù bú huì zài wèi xìnyòngkǎ zhàngdān fāchóu le.","vi":"Chỉ cần kiên trì tiêu dùng lý trí, cuối tháng sẽ không còn lo lắng vì hóa đơn thẻ tín dụng nữa."}],"related":[{"hanzi":"消费","pinyin":"xiāofèi","vi":"tiêu dùng"},{"hanzi":"冲动消费","pinyin":"chōngdòngxiāofèi","vi":"mua sắm bốc đồng"},{"hanzi":"理性","pinyin":"lǐxìng","vi":"lý tính"}],"traditional":"理性消費"},{"id":"礼遇","hanzi":"礼遇","pinyin":"lǐyù","meaning_vi":"sự tiếp đãi trọng thị","explanation":"礼 (lễ nghi/lễ phép) + 遇 (遇).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🎖️","examples":[{"type":"basic","zh":"他受到了很高的礼遇。","pinyin":"Tā shòudàole hěn gāo de lǐyù.","vi":"Ông ấy đã được tiếp đãi rất trọng thị."},{"type":"simple","zh":"总统抵达机场时受到了二十一响礼炮的礼遇。","pinyin":"Zǒngtǒng dǐdá jīchǎng shí shòudàole èr shíyī xiǎng lǐpào de lǐyù.","vi":"Khi tổng thống đến sân bay, ông được đón tiếp trọng thị bằng hai mươi mốt phát đại bác."},{"type":"compound","zh":"虽然对方给了他特殊的礼遇，但是他坚持和普通游客一起排队。","pinyin":"Suīrán duìfāng gěile tā tèshū de lǐyù, dànshì tā jiānchí hé pǔtōng yóukè yìqǐ páiduì.","vi":"Tuy phía bên kia dành cho ông sự tiếp đãi đặc biệt, nhưng ông vẫn kiên quyết xếp hàng cùng du khách bình thường."}],"related":[{"hanzi":"待遇","pinyin":"dàiyù","vi":"đãi ngộ"},{"hanzi":"款待","pinyin":"kuǎndài","vi":"khoản đãi"},{"hanzi":"冷遇","pinyin":"lěngyù","vi":"đối xử lạnh nhạt"}],"traditional":"禮遇"},{"id":"领带","hanzi":"领带","pinyin":"lǐngdài","meaning_vi":"cà vạt","explanation":"领 (lĩnh vực/lãnh đạo) + 带 (mang theo).","hsk_level":"7-9","tags":["danh-tu","trang-phuc","do-vat"],"image":"👔","examples":[{"type":"basic","zh":"他系了一条红领带。","pinyin":"Tā jìle yì tiáo hóng lǐngdài.","vi":"Anh ấy thắt một chiếc cà vạt đỏ."},{"type":"simple","zh":"父亲节那天，女儿送给爸爸一条蓝色领带。","pinyin":"Fùqīnjié nà tiān, nǚ'ér sònggěi bàba yì tiáo lánsè lǐngdài.","vi":"Ngày của Cha, cô con gái tặng bố một chiếc cà vạt màu xanh."},{"type":"compound","zh":"虽然公司不要求穿正装，但是见客户时他总会打上领带。","pinyin":"Suīrán gōngsī bù yāoqiú chuān zhèngzhuāng, dànshì jiàn kèhù shí tā zǒng huì dǎ shàng lǐngdài.","vi":"Tuy công ty không bắt mặc đồ công sở, nhưng khi gặp khách hàng anh ấy luôn thắt cà vạt."}],"related":[{"hanzi":"西装","pinyin":"xīzhuāng","vi":"com-lê"},{"hanzi":"衬衫","pinyin":"chènshān","vi":"áo sơ mi"},{"hanzi":"领结","pinyin":"lǐngjié","vi":"nơ cổ"}],"traditional":"領帶"},{"id":"领海","hanzi":"领海","pinyin":"lǐnghǎi","meaning_vi":"lãnh hải","explanation":"领 (lĩnh vực/lãnh đạo) + 海 (biển).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"外国渔船闯入了领海。","pinyin":"Wàiguó yúchuán chuǎngrùle lǐnghǎi.","vi":"Tàu cá nước ngoài đã xâm nhập lãnh hải."},{"type":"simple","zh":"海警船每天在领海范围内巡逻好几次。","pinyin":"Hǎijǐng chuán měitiān zài lǐnghǎi fànwéinèi xúnluó hǎojǐ cì.","vi":"Tàu cảnh sát biển mỗi ngày tuần tra nhiều lần trong phạm vi lãnh hải."},{"type":"compound","zh":"如果未经允许进入他国领海，船只就可能被扣留。","pinyin":"Rúguǒ wèijīng yǔnxǔ jìnrù tāguó lǐnghǎi, chuánzhī jiù kěnéng bèi kòuliú.","vi":"Nếu vào lãnh hải nước khác mà chưa được phép, tàu thuyền có thể bị bắt giữ."}],"related":[{"hanzi":"领空","pinyin":"lǐngkōng","vi":"không phận"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"海域","pinyin":"Hǎiyù","vi":"vùng biển"}],"traditional":"領海"},{"id":"领空","hanzi":"领空","pinyin":"lǐngkōng","meaning_vi":"không phận","explanation":"领 (lĩnh vực/lãnh đạo) + 空 (trống rỗng/không gian).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","giao-thong"],"image":"✈️","examples":[{"type":"basic","zh":"战机飞越了领空。","pinyin":"Zhànjī fēiyuèle lǐngkōng.","vi":"Máy bay chiến đấu đã bay qua không phận."},{"type":"simple","zh":"民航飞机经过别国领空时需要提前申请。","pinyin":"Mínháng fēijī jīngguò bié guó lǐngkōng shí xūyào tíqián shēnqǐng.","vi":"Máy bay dân dụng khi đi qua không phận nước khác cần phải xin phép trước."},{"type":"compound","zh":"因为邻国暂时关闭了领空，所以这趟航班只好绕道飞行。","pinyin":"Yīnwèi Línguó zànshí guānbìle lǐngkōng, suǒyǐ zhè tàng hángbān zhǐhǎo ràodào fēixíng.","vi":"Vì nước láng giềng tạm đóng cửa không phận nên chuyến bay này đành phải bay vòng."}],"related":[{"hanzi":"领海","pinyin":"lǐnghǎi","vi":"lãnh hải"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"主权","pinyin":"zhǔquán","vi":"chủ quyền"}],"traditional":"領空"},{"id":"领略","hanzi":"领略","pinyin":"lǐnglüè","meaning_vi":"cảm nhận, thưởng thức (cảnh đẹp/tinh thần)","explanation":"领 (lĩnh vực/lãnh đạo) + 略 (chiến lược/sơ lược).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🌄","examples":[{"type":"basic","zh":"我们领略了山水之美。","pinyin":"Wǒmen lǐnglüèle shānshuǐ zhī měi.","vi":"Chúng tôi đã cảm nhận vẻ đẹp của núi sông."},{"type":"simple","zh":"坐竹筏游漓江，可以充分领略桂林的秀丽风光。","pinyin":"Zuò zhú fá yóu Líjiāng, kěyǐ chōngfèn lǐnglüè Guìlín de xiùlì fēngguāng.","vi":"Ngồi bè tre dạo sông Ly, có thể thưởng thức trọn vẹn phong cảnh tươi đẹp của Quế Lâm."},{"type":"compound","zh":"只有亲自走进苗寨，才能真正领略那里独特的民族风情。","pinyin":"Zhǐyǒu qīnzì zǒujìn miáo zhài, cáinéng zhēnzhèng lǐnglüè nàlǐ dútè de mínzú fēngqíng.","vi":"Chỉ khi tự mình đến bản người Miêu, mới thực sự cảm nhận được phong tình dân tộc độc đáo nơi đó."}],"related":[{"hanzi":"领会","pinyin":"lǐnghuì","vi":"lĩnh hội"},{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức"},{"hanzi":"体会","pinyin":"tǐhuì","vi":"thể nghiệm"}],"traditional":"領略"},{"id":"领土完整","hanzi":"领土完整","pinyin":"lǐngtǔwánzhěng","meaning_vi":"toàn vẹn lãnh thổ","explanation":"领土 (lãnh thổ) + 完整 (hoàn chỉnh – trọn vẹn) → toàn vẹn lãnh thổ. VD: 维护国家主权和领土完整.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗺️","examples":[{"type":"basic","zh":"国家维护领土完整。","pinyin":"Guójiā wéihù lǐngtǔwánzhěng.","vi":"Nhà nước giữ gìn toàn vẹn lãnh thổ."},{"type":"simple","zh":"各国都应当尊重彼此的主权和领土完整。","pinyin":"Gè guódōu yīngdāng zūnzhòng bǐcǐ de zhǔquán hé lǐngtǔwánzhěng.","vi":"Các nước đều nên tôn trọng chủ quyền và toàn vẹn lãnh thổ của nhau."},{"type":"compound","zh":"只要事关领土完整，政府就绝不会作出任何让步。","pinyin":"Zhǐyào shìguān lǐngtǔwánzhěng, zhèngfǔ jiù juébú huì zuòchū rènhé ràngbù.","vi":"Hễ việc gì liên quan đến toàn vẹn lãnh thổ, chính phủ tuyệt đối không nhượng bộ."}],"related":[{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"},{"hanzi":"主权","pinyin":"zhǔquán","vi":"chủ quyền"},{"hanzi":"国家统一","pinyin":"guójiātǒngyī","vi":"thống nhất đất nước"}],"traditional":"領土完整"},{"id":"垄断性","hanzi":"垄断性","pinyin":"lǒngduànxìng","meaning_vi":"tính độc quyền","explanation":"垄 (độc quyền/bờ ruộng) + 断 (đứt) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"这个行业垄断性很强。","pinyin":"Zhè ge hángyè lǒngduànxìng hěn qiáng.","vi":"Ngành này có tính độc quyền rất cao."},{"type":"simple","zh":"自来水公司具有天然的垄断性，价格由政府监管。","pinyin":"Zìláishuǐ gōngsī jùyǒu tiānrán de lǒngduànxìng, jiàgé yóu zhèngfǔ jiānguǎn.","vi":"Công ty cấp nước có tính độc quyền tự nhiên, giá cả do chính phủ giám sát."},{"type":"compound","zh":"因为平台的垄断性越来越明显，所以监管部门开始介入调查。","pinyin":"Yīnwèi píngtái de lǒngduànxìng yuèláiyuè míngxiǎn, suǒyǐ jiānguǎn bùmén kāishǐ jièrù diàochá.","vi":"Vì tính độc quyền của nền tảng ngày càng rõ rệt nên cơ quan quản lý bắt đầu vào cuộc điều tra."}],"related":[{"hanzi":"垄断","pinyin":"lǒngduàn","vi":"độc quyền"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"反垄断","pinyin":"fǎnlǒngduàn","vi":"chống độc quyền"}],"traditional":"壟斷性"},{"id":"屡见不鲜","hanzi":"屡见不鲜","pinyin":"lǚjiàn-bùxiān","meaning_vi":"thấy nhiều không còn lạ nữa","explanation":"屡 (nhiều lần) + 见 (见) + 不 (không) + 鲜 (tươi sáng/hiếm).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"这种事屡见不鲜。","pinyin":"Zhè zhǒng shì lǚjiànbùxiān.","vi":"Chuyện này thấy nhiều chẳng lạ."},{"type":"simple","zh":"在旅游旺季，景区宰客的现象屡见不鲜。","pinyin":"Zài lǚyóu wàngjì, jǐngqū zǎikè de xiànxiàng lǚjiànbùxiān.","vi":"Vào mùa du lịch cao điểm, chuyện chặt chém du khách ở khu thắng cảnh chẳng còn lạ."},{"type":"compound","zh":"虽然网络诈骗屡见不鲜，但是仍有很多老人上当受骗。","pinyin":"Suīrán wǎngluòzhàpiàn lǚjiànbùxiān, dànshì réng yǒu hěn duō lǎorén shàngdàng shòupiàn.","vi":"Tuy lừa đảo qua mạng xảy ra nhan nhản, nhưng vẫn có nhiều người già bị mắc lừa."}],"related":[{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"quen mắt"},{"hanzi":"常见","pinyin":"chángjiàn","vi":"thường gặp"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"}],"traditional":"屢見不鮮"},{"id":"履历","hanzi":"履历","pinyin":"lǚlì","meaning_vi":"lý lịch công tác","explanation":"履 (thực hiện/giày dép) + 历 (lịch sử/trải qua).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📄","examples":[{"type":"basic","zh":"请把履历发给我。","pinyin":"Qǐng bǎ lǚlì fāgěi wǒ.","vi":"Vui lòng gửi lý lịch cho tôi."},{"type":"simple","zh":"他的履历上写着曾在三家外企担任经理。","pinyin":"Tā de lǚlì shàng xiězhe céng zài sān jiā wàiqǐ dānrèn jīnglǐ.","vi":"Lý lịch của anh ấy ghi rằng từng làm quản lý ở ba công ty nước ngoài."},{"type":"compound","zh":"虽然她的履历很漂亮，但是面试时的表现让人失望。","pinyin":"Suīrán tā de lǚlì hěn piàoliang, dànshì miànshì shí de biǎoxiàn ràng rén shīwàng.","vi":"Tuy lý lịch của cô ấy rất đẹp, nhưng màn thể hiện khi phỏng vấn lại khiến người ta thất vọng."}],"related":[{"hanzi":"简历","pinyin":"jiǎnlì","vi":"sơ yếu lý lịch"},{"hanzi":"经历","pinyin":"jīnglì","vi":"kinh nghiệm"},{"hanzi":"资历","pinyin":"zīlì","vi":"thâm niên"}],"traditional":"履歷"},{"id":"绿茶","hanzi":"绿茶","pinyin":"lǜchá","meaning_vi":"trà xanh","explanation":"绿 (lục – xanh lá) + 茶 (trà) → trà xanh, loại trà không lên men. VD: 西湖龙井是有名的绿茶.","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"🍵","examples":[{"type":"basic","zh":"我想喝杯绿茶。","pinyin":"Wǒ xiǎng hē bēi lǜchá.","vi":"Tôi muốn uống một cốc trà xanh."},{"type":"simple","zh":"越南太原的绿茶味道清香，很受本地人喜爱。","pinyin":"Yuènán tài yuán de lǜchá wèidào qīngxiāng, hěn shòu běndìrén xǐ'ài.","vi":"Trà xanh Thái Nguyên có hương vị thanh thơm, rất được người địa phương yêu thích."},{"type":"compound","zh":"绿茶虽然对身体有好处，但是空腹喝容易伤胃。","pinyin":"Lǜchá suīrán duì shēntǐ yǒu hǎochù, dànshì kōngfù hē róngyì shāng wèi.","vi":"Trà xanh tuy tốt cho sức khỏe, nhưng uống lúc đói dễ hại dạ dày."}],"related":[{"hanzi":"红茶","pinyin":"hóngchá","vi":"hồng trà"},{"hanzi":"龙井","pinyin":"Lóngjǐng","vi":"trà Long Tỉnh"},{"hanzi":"茶叶","pinyin":"cháyè","vi":"lá trà"}],"traditional":"綠茶"},{"id":"绿化","hanzi":"绿化","pinyin":"lǜhuà","meaning_vi":"phủ xanh, trồng cây xanh","explanation":"绿 (màu xanh lá cây) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌳","examples":[{"type":"basic","zh":"校园绿化得很好。","pinyin":"Xiàoyuán lǜhuà de hěn hǎo.","vi":"Khuôn viên trường được phủ xanh rất tốt."},{"type":"simple","zh":"居民们利用周末在河边绿化了一片荒地。","pinyin":"Jūmínmen lìyòng zhōumò zài hébiān lǜhuàle yípiàn huāngdì.","vi":"Cư dân tranh thủ cuối tuần phủ xanh một mảnh đất hoang bên bờ sông."},{"type":"compound","zh":"只要坚持植树绿化，沙漠的面积就会逐渐减少。","pinyin":"Zhǐyào jiānchí zhíshù lǜhuà, shāmò de miànjī jiù huì zhújiàn jiǎnshǎo.","vi":"Chỉ cần kiên trì trồng cây phủ xanh, diện tích sa mạc sẽ dần thu hẹp."}],"related":[{"hanzi":"植树","pinyin":"zhíshù","vi":"trồng cây"},{"hanzi":"绿地","pinyin":"lǜdì","vi":"khu cây xanh"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"}],"traditional":"綠化"},{"id":"绿水青山","hanzi":"绿水青山","pinyin":"lǜshuǐ-qīngshān","meaning_vi":"non xanh nước biếc (môi trường sinh thái)","explanation":"绿 (màu xanh lá cây) + 水 (nước) + 青 (màu xanh (xanh lá/xanh da trời/đen)) + 山 (núi non).","hsk_level":"7-9","tags":["thanh-ngu","thien-nhien","van-hoa"],"image":"🏞️","examples":[{"type":"basic","zh":"这里绿水青山。","pinyin":"Zhèlǐ lǜshuǐqīngshān.","vi":"Nơi đây non xanh nước biếc."},{"type":"simple","zh":"这个小山村靠着绿水青山发展起了生态旅游。","pinyin":"Zhè ge xiǎo shāncūn kàozhe lǜshuǐqīngshān fāzhǎn qǐle shēngtài lǚyóu.","vi":"Ngôi làng miền núi nhỏ này dựa vào non xanh nước biếc mà phát triển du lịch sinh thái."},{"type":"compound","zh":"如果为了赚钱破坏绿水青山，子孙后代就会付出沉重代价。","pinyin":"Rúguǒ wèile zhuànqián pòhuài lǜshuǐqīngshān, zǐsūn hòudài jiù huì fùchū chénzhòng dàijià.","vi":"Nếu vì kiếm tiền mà phá hủy non xanh nước biếc, con cháu đời sau sẽ phải trả giá đắt."}],"related":[{"hanzi":"金山银山","pinyin":"jīnshānyínshān","vi":"núi vàng núi bạc"},{"hanzi":"生态","pinyin":"shēngtài","vi":"sinh thái"},{"hanzi":"山清水秀","pinyin":"shānqīngshuǐxiù","vi":"non xanh nước biếc"}],"traditional":"綠水青山"},{"id":"绿色经济","hanzi":"绿色经济","pinyin":"lǜsèjīngjì","meaning_vi":"kinh tế xanh","explanation":"绿色 (lục sắc – màu xanh, thân thiện môi trường) + 经济 (kinh tế) → kinh tế xanh, phát triển bền vững, ít ô nhiễm.","hsk_level":"7-9","tags":["danh-tu","thien-nhien","cong-viec"],"image":"🌱","examples":[{"type":"basic","zh":"发展绿色经济很重要。","pinyin":"Fāzhǎn lǜsèjīngjì hěn zhòngyào.","vi":"Phát triển kinh tế xanh rất quan trọng."},{"type":"simple","zh":"这座煤城正在努力转型，大力发展绿色经济。","pinyin":"Zhè zuò méi chéng zhèngzài nǔlì zhuǎnxíng, dàlì fāzhǎn lǜsèjīngjì.","vi":"Thành phố than này đang nỗ lực chuyển đổi, đẩy mạnh phát triển kinh tế xanh."},{"type":"compound","zh":"发展绿色经济不但能保护环境，而且能创造大量新岗位。","pinyin":"Fāzhǎn lǜsèjīngjì búdàn néng bǎohù huánjìng, érqiě néng chuàngzào dàliàng xīn gǎngwèi.","vi":"Phát triển kinh tế xanh không những bảo vệ được môi trường mà còn tạo ra rất nhiều việc làm mới."}],"related":[{"hanzi":"低碳","pinyin":"dītàn","vi":"các-bon thấp"},{"hanzi":"可持续发展","pinyin":"kěchíxù fāzhǎn","vi":"phát triển bền vững"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"}],"traditional":"綠色經濟"},{"id":"绿洲","hanzi":"绿洲","pinyin":"lǜzhōu","meaning_vi":"ốc đảo xanh (giữa sa mạc)","explanation":"绿 (màu xanh lá cây) + 洲 (châu lục).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌴","examples":[{"type":"basic","zh":"沙漠里出现了一片绿洲。","pinyin":"Shāmò lǐ chūxiànle yípiàn lǜzhōu.","vi":"Giữa sa mạc hiện ra một ốc đảo."},{"type":"simple","zh":"驼队走了三天，终于在傍晚到达了绿洲。","pinyin":"Tuó duì zǒule sān tiān, zhōngyú zài bàngwǎn dàodále lǜzhōu.","vi":"Đoàn lạc đà đi ba ngày, cuối cùng chiều tối cũng đến được ốc đảo."},{"type":"compound","zh":"因为绿洲里有泉水，所以古代商人都在这里歇脚。","pinyin":"Yīnwèi lǜzhōu lǐ yǒu quánshuǐ, suǒyǐ gǔdài shāngrén dōu zài zhèlǐ xiējiǎo.","vi":"Vì trong ốc đảo có suối nước nên thương nhân thời xưa đều dừng chân nghỉ ở đây."}],"related":[{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"水源","pinyin":"shuǐyuán","vi":"nguồn nước"},{"hanzi":"骆驼","pinyin":"luòtuo","vi":"lạc đà"}],"traditional":"綠洲"},{"id":"面貌一新","hanzi":"面貌一新","pinyin":"miànmào-yìxīn","meaning_vi":"diện mạo đổi mới hoàn toàn","explanation":"面 (diện mạo/bề mặt) + 貌 (diện mạo) + 一 (số 1) + 新 (mới).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"老城区面貌一新。","pinyin":"Lǎochéngqū miànmàoyìxīn.","vi":"Khu phố cổ đã thay da đổi thịt."},{"type":"simple","zh":"经过半年改造，这条脏乱的小巷面貌一新。","pinyin":"Jīng guòbàn nián gǎizào, zhè tiáo zāngluàn de xiǎoxiàng miànmàoyìxīn.","vi":"Sau nửa năm cải tạo, con hẻm bẩn thỉu lộn xộn này đã đổi mới hoàn toàn."},{"type":"compound","zh":"新校长一上任，学校就变得面貌一新。","pinyin":"Xīn xiàozhǎng yí shàngrèn, xuéxiào jiù biànde miànmàoyìxīn.","vi":"Hiệu trưởng mới vừa nhậm chức, trường học đã khoác lên diện mạo mới hoàn toàn."}],"related":[{"hanzi":"焕然一新","pinyin":"huànrányìxīn","vi":"mới hoàn toàn"},{"hanzi":"改观","pinyin":"gǎiguān","vi":"thay đổi diện mạo"},{"hanzi":"面貌","pinyin":"miànmào","vi":"diện mạo"}]},{"id":"面向","hanzi":"面向","pinyin":"miànxiàng","meaning_vi":"hướng tới (tương lai/thế giới/công chúng)","explanation":"面 (diện mạo/bề mặt) + 向 (hướng về).","hsk_level":"7-9","tags":["dong-tu","gioi-tu"],"image":"🧭","examples":[{"type":"basic","zh":"我们要面向未来。","pinyin":"Wǒmen yào miànxiàng wèilái.","vi":"Chúng ta phải hướng tới tương lai."},{"type":"simple","zh":"这个培训班主要面向刚毕业的大学生。","pinyin":"Zhè ge péixùnbān zhǔyào miànxiàng gāng bìyè de dàxuéshēng.","vi":"Lớp đào tạo này chủ yếu dành cho sinh viên vừa tốt nghiệp."},{"type":"compound","zh":"既然产品是面向老年人的，按键就应该做得大一些。","pinyin":"Jìrán chǎnpǐn shì miànxiàng lǎoniánrén de, ànjiàn jiù yīnggāi zuò de dàyìxiē.","vi":"Đã là sản phẩm hướng đến người già thì phím bấm nên làm to hơn một chút."}],"related":[{"hanzi":"面对","pinyin":"miànduì","vi":"đối mặt"},{"hanzi":"朝向","pinyin":"cháoxiàng","vi":"hướng về"},{"hanzi":"面向未来","pinyin":"miànxiàngwèilái","vi":"hướng tới tương lai"}]},{"id":"妙趣横生","hanzi":"妙趣横生","pinyin":"miàoqù-héngshēng","meaning_vi":"vô cùng thú vị dí dỏm","explanation":"妙 (tuyệt diệu/khéo léo) + 趣 (hứng thú) + 横 (ngang/hoành hành) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["thanh-ngu","giai-tri"],"image":"😄","examples":[{"type":"basic","zh":"这本书妙趣横生。","pinyin":"Zhè běn shū miàoqùhéngshēng.","vi":"Cuốn sách này vô cùng thú vị."},{"type":"simple","zh":"那位老教授讲课妙趣横生，教室里常常笑声不断。","pinyin":"Nà wèi lǎo jiàoshòu jiǎngkè miàoqùhéngshēng, jiàoshì lǐ chángcháng xiàoshēng búduàn.","vi":"Vị giáo sư già giảng bài rất dí dỏm, trong lớp thường xuyên rộn tiếng cười."},{"type":"compound","zh":"这部动画片不但妙趣横生，而且蕴含着深刻的道理。","pinyin":"Zhè bù dònghuàpiàn búdàn miàoqùhéngshēng, érqiě yùnhánzhe shēnkè de dàolǐ.","vi":"Bộ phim hoạt hình này không những dí dỏm thú vị mà còn hàm chứa đạo lý sâu sắc."}],"related":[{"hanzi":"妙趣","pinyin":"miàoqù","vi":"thú vị"},{"hanzi":"风趣","pinyin":"fēngqù","vi":"hóm hỉnh"},{"hanzi":"枯燥","pinyin":"kūzào","vi":"khô khan"}],"traditional":"妙趣橫生"},{"id":"绵延","hanzi":"绵延","pinyin":"miányán","meaning_vi":"kéo dài liên miên (dãy núi/lịch sử)","explanation":"绵 (liên miên/mềm mại) + 延 (kéo dài/lan tràn).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"群山绵延不断。","pinyin":"Qúnshān miányán búduàn.","vi":"Dãy núi trải dài liên miên không dứt."},{"type":"simple","zh":"长城在北方的崇山峻岭间绵延上万里。","pinyin":"Chángchéng zài běifāng de chóngshānjùnlǐng jiān miányán shàng wànlǐ.","vi":"Vạn Lý Trường Thành uốn lượn hơn vạn dặm giữa núi non hiểm trở phương Bắc."},{"type":"compound","zh":"虽然经历了无数战乱，但是中华文明依然绵延了几千年。","pinyin":"Suīrán jīnglìle wúshù zhànluàn, dànshì zhōnghuáwénmíng yīrán miányánle jǐ qiānnián.","vi":"Tuy trải qua vô số loạn lạc, nhưng nền văn minh Trung Hoa vẫn kéo dài liên tục mấy nghìn năm."}],"related":[{"hanzi":"连绵","pinyin":"liánmián","vi":"liên miên"},{"hanzi":"延绵不断","pinyin":"yánmiánbúduàn","vi":"kéo dài không dứt"},{"hanzi":"延伸","pinyin":"yánshēn","vi":"kéo dài"}],"traditional":"綿延"},{"id":"描绘出","hanzi":"描绘出","pinyin":"miáohuìchū","meaning_vi":"khắc họa nên","explanation":"描 (miêu tả) + 绘 (vẽ/miêu tả) + 出 (xuất hiện/xuất sắc).","hsk_level":"7-9","tags":["dong-tu"],"image":"🎨","examples":[{"type":"basic","zh":"他描绘出一幅美景。","pinyin":"Tā miáohuìchū yì fú měijǐng.","vi":"Anh ấy đã khắc họa nên một bức tranh tuyệt đẹp."},{"type":"simple","zh":"作家用细腻的笔触描绘出江南水乡的宁静。","pinyin":"Zuò jiāyòng xìnì de bǐchù miáohuìchū Jiāngnánshuǐxiāng de níngjìng.","vi":"Nhà văn dùng ngòi bút tinh tế khắc họa nên sự yên bình của vùng sông nước Giang Nam."},{"type":"compound","zh":"虽然孩子只用了几支蜡笔，但是描绘出了一个五彩缤纷的世界。","pinyin":"Suīrán háizi zhǐ yòngle jǐ zhī làbǐ, dànshì miáohuìchūle yí gè wǔcǎibīnfēn de shìjiè.","vi":"Tuy đứa trẻ chỉ dùng vài cây bút sáp, nhưng đã vẽ nên cả một thế giới rực rỡ sắc màu."}],"related":[{"hanzi":"描绘","pinyin":"miáohuì","vi":"miêu tả"},{"hanzi":"描写","pinyin":"miáoxiě","vi":"miêu tả"},{"hanzi":"勾勒","pinyin":"gōulè","vi":"phác họa"}],"traditional":"描繪出"},{"id":"免除","hanzi":"免除","pinyin":"miǎnchú","meaning_vi":"miễn trừ (nghĩa vụ/hình phạt)","explanation":"免 (miễn dịch/tránh) + 除 (loại trừ/ngoài ra).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🔓","examples":[{"type":"basic","zh":"他的债务被免除了。","pinyin":"Tā de zhàiwù bèi miǎnchú le.","vi":"Khoản nợ của anh ấy đã được xóa bỏ."},{"type":"simple","zh":"因为家庭困难，学校免除了她的全部学费。","pinyin":"Yīnwèi jiātíng kùnnan, xuéxiào miǎnchúle tā de quánbù xuéfèi.","vi":"Vì gia cảnh khó khăn, nhà trường đã miễn toàn bộ học phí cho em."},{"type":"compound","zh":"如果他主动交代犯罪事实，就有可能被免除处罚。","pinyin":"Rúguǒ tā zhǔdòng jiāodài fànzuì shìshí, jiù yǒukěnéng bèi miǎnchú chǔfá.","vi":"Nếu hắn chủ động khai báo hành vi phạm tội, có thể được miễn hình phạt."}],"related":[{"hanzi":"免去","pinyin":"miǎnqù","vi":"miễn bỏ"},{"hanzi":"豁免","pinyin":"huòmiǎn","vi":"miễn trừ"},{"hanzi":"减免","pinyin":"jiǎnmiǎn","vi":"giảm miễn"}]},{"id":"免费开放","hanzi":"免费开放","pinyin":"miǎnfèikāifàng","meaning_vi":"mở cửa miễn phí","explanation":"免 (miễn dịch/tránh) + 费 (费) + 开 (mở) + 放 (đặt).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"博物馆周一免费开放。","pinyin":"Bówùguǎn Zhōuyì miǎnfèikāifàng.","vi":"Bảo tàng mở cửa miễn phí vào thứ Hai."},{"type":"simple","zh":"国庆期间，市里的十几个公园全部免费开放。","pinyin":"Guóqìng qījiān, shìlǐ de shíjǐ gè gōngyuán quánbù miǎnfèikāifàng.","vi":"Trong dịp Quốc khánh, mười mấy công viên trong thành phố đều mở cửa miễn phí."},{"type":"compound","zh":"自从图书馆免费开放以后，来看书的市民一下子多了一倍。","pinyin":"Zìcóng túshūguǎn miǎnfèikāifàng yǐhòu, lái kànshū de shìmín yíxiàzi duōle yí bèi.","vi":"Từ khi thư viện mở cửa miễn phí, số người dân đến đọc sách bỗng tăng gấp đôi."}],"related":[{"hanzi":"免费","pinyin":"miǎnfèi","vi":"miễn phí"},{"hanzi":"开放","pinyin":"kāifàng","vi":"mở cửa"},{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"}],"traditional":"免費開放"},{"id":"免疫力","hanzi":"免疫力","pinyin":"miǎnyìlì","meaning_vi":"khả năng miễn dịch","explanation":"免 (miễn dịch/tránh) + 疫 (dịch bệnh/miễn dịch) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🛡️","examples":[{"type":"basic","zh":"运动能增强免疫力。","pinyin":"Yùndòng néng zēngqiáng miǎnyìlì.","vi":"Vận động có thể tăng cường khả năng miễn dịch."},{"type":"simple","zh":"换季时，免疫力低的老人和孩子容易感冒。","pinyin":"Huànjì shí, miǎnyìlì dī de lǎorén hé háizi róngyì gǎnmào.","vi":"Lúc giao mùa, người già và trẻ em có sức đề kháng kém dễ bị cảm."},{"type":"compound","zh":"如果长期熬夜，身体的免疫力就会明显下降。","pinyin":"Rúguǒ chángqī áoyè, shēntǐ de miǎnyìlì jiù huì míngxiǎn xiàjiàng.","vi":"Nếu thức khuya trong thời gian dài, khả năng miễn dịch của cơ thể sẽ giảm rõ rệt."}],"related":[{"hanzi":"免疫","pinyin":"miǎnyì","vi":"miễn dịch"},{"hanzi":"抵抗力","pinyin":"dǐkànglì","vi":"sức đề kháng"},{"hanzi":"疫苗","pinyin":"yìmiáo","vi":"vắc-xin"}]},{"id":"脉络","hanzi":"脉络","pinyin":"màiluò","meaning_vi":"mạch lạc, hệ thống kết cấu","explanation":"脉 (mạch máu/dãy núi) + 络 (mạng lưới/liên lạc).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🕸️","examples":[{"type":"basic","zh":"文章脉络清晰。","pinyin":"Wénzhāng màiluò qīngxī.","vi":"Bài văn có mạch lạc rõ ràng."},{"type":"simple","zh":"这本书梳理了两千年来中国思想发展的脉络。","pinyin":"Zhè běn shū shūlǐle liǎngqiānnián lái Zhōngguó sīxiǎng fāzhǎn de màiluò.","vi":"Cuốn sách này hệ thống lại mạch phát triển tư tưởng Trung Quốc suốt hai nghìn năm."},{"type":"compound","zh":"只要理清了事件的脉络，真相就不难看清楚了。","pinyin":"Zhǐyào lǐqīngle shìjiàn de màiluò, zhēnxiàng jiù bù nánkàn qīngchu le.","vi":"Chỉ cần làm rõ mạch diễn biến của sự việc, sự thật sẽ không khó nhìn ra."}],"related":[{"hanzi":"条理","pinyin":"tiáolǐ","vi":"mạch lạc"},{"hanzi":"线索","pinyin":"xiànsuǒ","vi":"manh mối"},{"hanzi":"脉搏","pinyin":"màibó","vi":"mạch đập"}],"traditional":"脈絡"},{"id":"迈向","hanzi":"迈向","pinyin":"màixiàng","meaning_vi":"tiến tới, sải bước hướng tới","explanation":"迈 (bước (bước chân)) + 向 (hướng về).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚀","examples":[{"type":"basic","zh":"我们正迈向新阶段。","pinyin":"Wǒmen zhèng màixiàng xīnjiēduàn.","vi":"Chúng ta đang tiến sang một giai đoạn mới."},{"type":"simple","zh":"毕业典礼后，同学们即将迈向各自的人生道路。","pinyin":"Bìyè diǎnlǐ hòu, tóngxuémen jíjiāng màixiàng gèzì de rénshēng dàolù.","vi":"Sau lễ tốt nghiệp, các bạn sắp bước vào con đường đời riêng của mình."},{"type":"compound","zh":"只要坚持创新，这家小公司就能一步步迈向国际市场。","pinyin":"Zhǐyào jiānchí chuàngxīn, zhè jiā xiǎo gōngsī jiù néng yí bùbù màixiàng Guójì shìchǎng.","vi":"Chỉ cần kiên trì đổi mới, công ty nhỏ này có thể từng bước tiến ra thị trường quốc tế."}],"related":[{"hanzi":"走向","pinyin":"zǒuxiàng","vi":"hướng tới"},{"hanzi":"迈进","pinyin":"màijìn","vi":"tiến lên"},{"hanzi":"奔向","pinyin":"bēnxiàng","vi":"lao tới"}],"traditional":"邁向"},{"id":"漫步","hanzi":"漫步","pinyin":"mànbù","meaning_vi":"tản bộ, đi dạo thong thả","explanation":"漫 (lãng mạn/tràn ngập) + 步 (步).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"🚶","examples":[{"type":"basic","zh":"我们在湖边漫步。","pinyin":"Wǒmen zài húbiān mànbù.","vi":"Chúng tôi tản bộ bên hồ."},{"type":"simple","zh":"晚饭后，老两口手拉手在公园里漫步。","pinyin":"Wǎnfàn hòu, lǎoliǎngkǒu shǒulāshǒu zài gōngyuán lǐ mànbù.","vi":"Sau bữa tối, đôi vợ chồng già nắm tay nhau tản bộ trong công viên."},{"type":"compound","zh":"每当心情烦躁时，她就去海边漫步，听听海浪声。","pinyin":"Měidāng xīnqíng fánzào shí, tā jiù qù hǎibiān mànbù, tīng ting hǎilàng shēng.","vi":"Mỗi khi tâm trạng bực bội, cô ấy lại ra biển dạo bước, nghe tiếng sóng."}],"related":[{"hanzi":"散步","pinyin":"sànbù","vi":"đi dạo"},{"hanzi":"闲逛","pinyin":"xiánguàng","vi":"đi lang thang"},{"hanzi":"徘徊","pinyin":"páihuái","vi":"bồi hồi"}]},{"id":"慢生活","hanzi":"慢生活","pinyin":"mànshēnghuó","meaning_vi":"lối sống chậm rãi thư thái","explanation":"慢 (chậm) + 生 (sinh tồn/sinh động) + 活 (活).","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"☕","examples":[{"type":"basic","zh":"我喜欢慢生活。","pinyin":"Wǒ xǐhuan mànshēnghuó.","vi":"Tôi thích lối sống chậm."},{"type":"simple","zh":"辞职后，他搬到大理，开始了种花喝茶的慢生活。","pinyin":"Cízhí hòu, tā bān dào dàlǐ, kāishǐle zhònghuā hēchá de mànshēnghuó.","vi":"Sau khi nghỉ việc, anh ấy chuyển đến Đại Lý, bắt đầu cuộc sống chậm trồng hoa uống trà."},{"type":"compound","zh":"虽然慢生活很让人向往，但是并不是每个人都能放下工作。","pinyin":"Suīrán mànshēnghuó hěn ràng rén xiàngwǎng, dànshì bìngbú shì měigèrén dōu néng fàngxià gōngzuò.","vi":"Tuy lối sống chậm rất đáng mơ ước, nhưng không phải ai cũng có thể buông bỏ công việc."}],"related":[{"hanzi":"快节奏","pinyin":"kuàijiézòu","vi":"nhịp sống nhanh"},{"hanzi":"悠闲","pinyin":"yōuxián","vi":"thong thả"},{"hanzi":"休闲","pinyin":"xiūxián","vi":"nghỉ ngơi thư giãn"}]},{"id":"冒牌","hanzi":"冒牌","pinyin":"màopái","meaning_vi":"giả mạo, nhái (nhãn hiệu)","explanation":"冒 (mạo hiểm/giả mạo) + 牌 (牌).","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"🚫","examples":[{"type":"basic","zh":"这个包是冒牌货。","pinyin":"Zhè ge bāo shì màopáihuò.","vi":"Chiếc túi này là hàng nhái."},{"type":"simple","zh":"警方查获了一个生产冒牌名酒的地下工厂。","pinyin":"Jǐngfāng cháhuòle yí gè shēngchǎn màopái míngjiǔ de dìxià gōngchǎng.","vi":"Cảnh sát triệt phá một xưởng ngầm sản xuất rượu danh tiếng giả mạo."},{"type":"compound","zh":"如果价格便宜得离谱，那就很可能是冒牌商品。","pinyin":"Rúguǒ jiàgé piányi de lípǔ, nà jiù hěn kěnéng shì màopái shāngpǐn.","vi":"Nếu giá rẻ đến mức vô lý, thì rất có thể là hàng giả."}],"related":[{"hanzi":"冒牌货","pinyin":"màopáihuò","vi":"hàng giả"},{"hanzi":"假冒","pinyin":"jiǎmào","vi":"giả mạo"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"}]},{"id":"贸易逆差","hanzi":"贸易逆差","pinyin":"màoyìnìchā","meaning_vi":"thâm hụt thương mại (nhập siêu)","explanation":"贸易 (mậu dịch – thương mại) + 逆差 (nghịch sai – chênh lệch ngược) → thâm hụt thương mại, nhập nhiều hơn xuất; trái nghĩa 贸易顺差.","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"今年出现了贸易逆差。","pinyin":"Jīnnián chūxiànle màoyìnìchā.","vi":"Năm nay đã xuất hiện thâm hụt thương mại."},{"type":"simple","zh":"由于大量进口能源，这个国家的贸易逆差持续扩大。","pinyin":"Yóuyú dàliàng jìnkǒu néngyuán, zhè ge guójiā de màoyìnìchā chíxù kuòdà.","vi":"Do nhập khẩu năng lượng với số lượng lớn, thâm hụt thương mại của nước này tiếp tục gia tăng."},{"type":"compound","zh":"如果出口一直疲软，贸易逆差就会给本国货币带来压力。","pinyin":"Rúguǒ chūkǒu yìzhí píruǎn, màoyìnìchā jiù huì gěi běnguó huòbì dàilái yālì.","vi":"Nếu xuất khẩu cứ yếu ớt, thâm hụt thương mại sẽ gây áp lực lên đồng nội tệ."}],"related":[{"hanzi":"贸易顺差","pinyin":"màoyìshùnchā","vi":"thặng dư thương mại"},{"hanzi":"逆差","pinyin":"nìchā","vi":"thâm hụt"},{"hanzi":"进口","pinyin":"jìnkǒu","vi":"nhập khẩu"}],"traditional":"貿易逆差"},{"id":"贸易顺差","hanzi":"贸易顺差","pinyin":"màoyìshùnchā","meaning_vi":"thặng dư thương mại (xuất siêu)","explanation":"贸易 + 顺差. Đối nghĩa với 贸易逆差 (thâm hụt thương mại).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"📈","examples":[{"type":"basic","zh":"越南保持贸易顺差。","pinyin":"Yuènán bǎochí màoyìshùnchā.","vi":"Việt Nam duy trì thặng dư thương mại."},{"type":"simple","zh":"上个月电子产品出口大增，带来了可观的贸易顺差。","pinyin":"Shànggèyuè diànzǐ chǎnpǐn chūkǒu dà zēng, dàiláile kěguān de màoyìshùnchā.","vi":"Tháng trước xuất khẩu hàng điện tử tăng mạnh, mang lại khoản thặng dư thương mại đáng kể."},{"type":"compound","zh":"虽然贸易顺差创了新高，但是国内消费依然不旺。","pinyin":"Suīrán màoyìshùnchā chuàngle xīngāo, dànshì guónèi xiāofèi yīrán bú wàng.","vi":"Tuy thặng dư thương mại lập kỷ lục mới, nhưng tiêu dùng trong nước vẫn chưa sôi động."}],"related":[{"hanzi":"贸易逆差","pinyin":"màoyìnìchā","vi":"thâm hụt thương mại"},{"hanzi":"顺差","pinyin":"shùnchā","vi":"thặng dư"},{"hanzi":"出口","pinyin":"chūkǒu","vi":"xuất khẩu"}],"traditional":"貿易順差"},{"id":"贸易额","hanzi":"贸易额","pinyin":"màoyì'é","meaning_vi":"kim ngạch thương mại","explanation":"贸 (thương mại) + 易 (dễ dàng/trao đổi) + 额 (额).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"两国贸易额增长了。","pinyin":"Liǎngguó màoyì'é zēngzhǎng le.","vi":"Kim ngạch thương mại hai nước đã tăng."},{"type":"simple","zh":"去年中越双边贸易额突破了两千亿美元。","pinyin":"Qù niánzhōng yuè shuāngbiān màoyì'é tūpòle liǎng qiānyì měiyuán.","vi":"Năm ngoái kim ngạch thương mại song phương Trung - Việt đã vượt mốc hai trăm tỷ đô la Mỹ."},{"type":"compound","zh":"只要关税继续下降，两国的贸易额就有望再创新高。","pinyin":"Zhǐyào guānshuì jìxù xiàjiàng, liǎngguó de màoyì'é jiù yǒuwàng zài chuàngxīn gāo.","vi":"Chỉ cần thuế quan tiếp tục giảm, kim ngạch thương mại hai nước có triển vọng lập kỷ lục mới."}],"related":[{"hanzi":"贸易","pinyin":"màoyì","vi":"thương mại"},{"hanzi":"进出口","pinyin":"jìnchūkǒu","vi":"xuất nhập khẩu"},{"hanzi":"总额","pinyin":"zǒng'é","vi":"tổng ngạch"}],"traditional":"貿易額"},{"id":"埋头","hanzi":"埋头","pinyin":"máitóu","meaning_vi":"vùi đầu vào (học tập/làm việc)","explanation":"埋 (chôn vùi/mai phục) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他埋头看书。","pinyin":"Tā máitóu kànshū.","vi":"Anh ấy vùi đầu đọc sách."},{"type":"simple","zh":"整个下午，她都埋头在实验室里分析数据。","pinyin":"Zhěnggè xiàwǔ, tā dōu máitóu zài shíyànshì lǐ fēnxī shùjù.","vi":"Cả buổi chiều, cô ấy vùi đầu trong phòng thí nghiệm phân tích dữ liệu."},{"type":"compound","zh":"他一回到宿舍就埋头写论文，连饭都忘了吃。","pinyin":"Tā yì huídào sùshè jiù máitóu xiě lùnwén, lián fàn dōu wàngle chī.","vi":"Anh ấy vừa về ký túc xá đã vùi đầu viết luận văn, đến cơm cũng quên ăn."}],"related":[{"hanzi":"埋头苦干","pinyin":"máitóukǔgàn","vi":"cắm cúi làm việc"},{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"},{"hanzi":"投入","pinyin":"tóurù","vi":"dốc sức"}],"traditional":"埋頭"},{"id":"盲目性","hanzi":"盲目性","pinyin":"mángmùxìng","meaning_vi":"tính mù quáng tự phát","explanation":"盲 (mù quáng) + 目 (mục tiêu/ánh mắt) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🙈","examples":[{"type":"basic","zh":"投资要避免盲目性。","pinyin":"Tóuzī yào bìmiǎn mángmùxìng.","vi":"Đầu tư cần tránh tính mù quáng."},{"type":"simple","zh":"很多家长报兴趣班带有很大的盲目性。","pinyin":"Hěn duō jiāzhǎng bào xìngqù bān dàiyǒu hěn dà de mángmùxìng.","vi":"Nhiều phụ huynh đăng ký lớp năng khiếu cho con một cách rất mù quáng."},{"type":"compound","zh":"如果扩张缺乏规划，就会带有盲目性，最终拖垮企业。","pinyin":"Rúguǒ kuòzhāng quēfá guīhuà, jiù huì dàiyǒu mángmùxìng, zuìzhōng tuōkuǎ qǐyè.","vi":"Nếu mở rộng thiếu quy hoạch thì sẽ mang tính mù quáng, cuối cùng kéo sập doanh nghiệp."}],"related":[{"hanzi":"盲目","pinyin":"mángmù","vi":"mù quáng"},{"hanzi":"盲从","pinyin":"mángcóng","vi":"a dua"},{"hanzi":"理性","pinyin":"lǐxìng","vi":"lý tính"}]},{"id":"盲区","hanzi":"盲区","pinyin":"mángqū","meaning_vi":"điểm mù (giao thông/nhận thức)","explanation":"盲 (mù quáng) + 区 (区).","hsk_level":"7-9","tags":["danh-tu","giao-thong","nhan-thuc"],"image":"⚠️","examples":[{"type":"basic","zh":"大货车有很多盲区。","pinyin":"Dà huòchē yǒu hěn duō mángqū.","vi":"Xe tải lớn có rất nhiều điểm mù."},{"type":"simple","zh":"骑电动车时千万不要停在公交车的视线盲区里。","pinyin":"Qí diàndòngchē shí qiānwàn bú yào tíng zài gōngjiāochē de shìxiàn mángqū lǐ.","vi":"Khi đi xe đạp điện tuyệt đối đừng dừng ở điểm mù tầm nhìn của xe buýt."},{"type":"compound","zh":"因为这个领域是他的知识盲区，所以他请教了专家。","pinyin":"Yīnwèi zhè ge lǐngyù shì tā de zhīshi mángqū, suǒyǐ tā qǐngjiàole zhuānjiā.","vi":"Vì lĩnh vực này là vùng mù kiến thức của anh ấy nên anh ấy đã thỉnh giáo chuyên gia."}],"related":[{"hanzi":"死角","pinyin":"sǐjiǎo","vi":"góc chết"},{"hanzi":"盲点","pinyin":"mángdiǎn","vi":"điểm mù"},{"hanzi":"视线","pinyin":"shìxiàn","vi":"tầm nhìn"}],"traditional":"盲區"},{"id":"毛笔","hanzi":"毛笔","pinyin":"máobǐ","meaning_vi":"bút lông viết thư pháp","explanation":"毛 (lông) + 笔 (bút).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🖌️","examples":[{"type":"basic","zh":"爷爷用毛笔写春联。","pinyin":"Yéye yòng máobǐ xiě chūnlián.","vi":"Ông nội dùng bút lông viết câu đối Tết."},{"type":"simple","zh":"书法课上，老师教我们怎样正确握毛笔。","pinyin":"Shūfǎ kè shàng, lǎoshī jiāo wǒmen zěnyàng zhèngquè wò máobǐ.","vi":"Trong giờ thư pháp, thầy dạy chúng tôi cách cầm bút lông đúng."},{"type":"compound","zh":"毛笔用完以后要马上洗干净，否则笔毛就会变硬。","pinyin":"Máobǐ yòngwán yǐhòu yào mǎshàng xǐ gānjìng, fǒuzé bǐ máo jiù huì biànyìng.","vi":"Bút lông dùng xong phải rửa sạch ngay, nếu không lông bút sẽ bị cứng."}],"related":[{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"墨水","pinyin":"mòshuǐ","vi":"mực"},{"hanzi":"文房四宝","pinyin":"wénfángsìbǎo","vi":"văn phòng tứ bảo"}],"traditional":"毛筆"},{"id":"毛利率","hanzi":"毛利率","pinyin":"máolìlǜ","meaning_vi":"tỷ suất lợi nhuận gộp","explanation":"毛利 + 率 (tỷ lệ).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"这个产品毛利率很高。","pinyin":"Zhè ge chǎnpǐn máolìlǜ hěn gāo.","vi":"Sản phẩm này có tỷ suất lợi nhuận gộp rất cao."},{"type":"simple","zh":"受原材料涨价影响，公司第三季度毛利率下滑了。","pinyin":"Shòu yuáncáiliào zhǎngjià yǐngxiǎng, gōngsī dì sān jìdù máolìlǜ xiàhuá le.","vi":"Do ảnh hưởng của giá nguyên liệu tăng, tỷ suất lợi nhuận gộp quý ba của công ty đã giảm."},{"type":"compound","zh":"虽然销量增长了，但是毛利率却在下降。","pinyin":"Suīrán xiāoliàng zēngzhǎng le, dànshì máolìlǜ què zài xiàjiàng.","vi":"Tuy doanh số đã tăng, nhưng tỷ suất lợi nhuận gộp lại đang giảm."}],"related":[{"hanzi":"毛利","pinyin":"máolì","vi":"lợi nhuận gộp"},{"hanzi":"净利润","pinyin":"jìnglìrùn","vi":"lợi nhuận ròng"},{"hanzi":"利润率","pinyin":"lìrùnlǜ","vi":"tỷ suất lợi nhuận"}]},{"id":"梦想成真","hanzi":"梦想成真","pinyin":"mèngxiǎng-chéngzhēn","meaning_vi":"ước mơ thành hiện thực","explanation":"梦 (ước mơ) + 想 (muốn) + 成 (thành công/trưởng thành) + 真 (thật).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌠","examples":[{"type":"basic","zh":"祝你梦想成真！","pinyin":"Zhù nǐ mèngxiǎngchéngzhēn!","vi":"Chúc bạn ước mơ thành hiện thực!"},{"type":"simple","zh":"经过十年苦练，他终于站上奥运领奖台，梦想成真。","pinyin":"Jīngguò shí nián kǔliàn, tā zhōngyú zhàn shàng Àoyùn lǐngjiǎngtái, mèngxiǎngchéngzhēn.","vi":"Sau mười năm khổ luyện, anh ấy cuối cùng đứng trên bục nhận giải Olympic, ước mơ đã thành hiện thực."},{"type":"compound","zh":"只要你脚踏实地地努力，梦想成真的那一天就一定会到来。","pinyin":"Zhǐyào nǐ jiǎotàshídì de nǔlì, mèngxiǎngchéngzhēn de nà yì tiān jiù yídìng huì dàolái.","vi":"Chỉ cần bạn nỗ lực một cách thực tế, ngày ước mơ thành hiện thực nhất định sẽ đến."}],"related":[{"hanzi":"梦想","pinyin":"mèngxiǎng","vi":"ước mơ"},{"hanzi":"实现","pinyin":"shíxiàn","vi":"thực hiện"},{"hanzi":"心想事成","pinyin":"xīnxiǎngshìchéng","vi":"cầu được ước thấy"}],"traditional":"夢想成真"},{"id":"媒体曝光","hanzi":"媒体曝光","pinyin":"méitǐbàoguāng","meaning_vi":"truyền thông phanh phui/đưa tin","explanation":"媒体 (môi thể – truyền thông) + 曝光 (bộc quang – phơi ra ánh sáng) → bị truyền thông phanh phui, đưa ra công luận. VD: 丑闻被媒体曝光.","hsk_level":"7-9","tags":["dong-tu","cong-nghe","xa-hoi"],"image":"📸","examples":[{"type":"basic","zh":"丑闻被媒体曝光了。","pinyin":"Chǒuwén bèi méitǐbàoguāng le.","vi":"Vụ bê bối đã bị truyền thông phanh phui."},{"type":"simple","zh":"那家餐厅用过期食材的事经媒体曝光后被查封了。","pinyin":"Nà jiā cāntīng yòng guòqī shícái de shì jīng méitǐbàoguāng hòu bèi cháfēng le.","vi":"Chuyện nhà hàng đó dùng nguyên liệu hết hạn sau khi bị truyền thông phanh phui đã bị niêm phong."},{"type":"compound","zh":"一旦遭到媒体曝光，这家企业的声誉就会一落千丈。","pinyin":"Yídàn zāodào méitǐbàoguāng, zhè jiā qǐyè de shēngyù jiù huì yíluòqiānzhàng.","vi":"Một khi bị truyền thông phanh phui, danh tiếng của doanh nghiệp này sẽ tụt dốc không phanh."}],"related":[{"hanzi":"曝光","pinyin":"bàoguāng","vi":"phơi bày"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"},{"hanzi":"揭露","pinyin":"jiēlù","vi":"vạch trần"}],"traditional":"媒體曝光"},{"id":"媒体人","hanzi":"媒体人","pinyin":"méitǐrén","meaning_vi":"người làm truyền thông, nhà báo","explanation":"媒 (truyền thông/môi giới) + 体 (thể hiện/hệ thống) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","con-nguoi"],"image":"🎙️","examples":[{"type":"basic","zh":"她是资深媒体人。","pinyin":"Tā shì zīshēn méitǐrén.","vi":"Cô ấy là người làm truyền thông kỳ cựu."},{"type":"simple","zh":"这位媒体人在网上分享了自己采访灾区的经历。","pinyin":"Zhè wèi méitǐrén zài wǎngshàng fēnxiǎngle zìjǐ cǎifǎng zāiqū de jīnglì.","vi":"Nhà báo này đã chia sẻ trên mạng trải nghiệm phỏng vấn ở vùng thiên tai của mình."},{"type":"compound","zh":"作为媒体人，既要追求时效，又要保证报道真实。","pinyin":"Zuòwéi méitǐrén, jì yào zhuīqiú shíxiào, yòu yào bǎozhèng bàodào zhēnshí.","vi":"Là người làm truyền thông, vừa phải theo đuổi tính thời sự, vừa phải đảm bảo tin tức chân thực."}],"related":[{"hanzi":"记者","pinyin":"jìzhě","vi":"phóng viên"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"},{"hanzi":"主持人","pinyin":"zhǔchírén","vi":"người dẫn chương trình"}],"traditional":"媒體人"},{"id":"没完没了","hanzi":"没完没了","pinyin":"méiwán-méiliǎo","meaning_vi":"không dứt, liên miên bất tận","explanation":"没 (không) + 完 (hoàn thiện/nguyên vẹn) + 没 (không) + 了 (rồi (trợ từ động thái/ngữ khí)).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔁","examples":[{"type":"basic","zh":"他说个没完没了。","pinyin":"Tā shuō gè méi wán méiliǎo.","vi":"Anh ta nói mãi không dứt."},{"type":"simple","zh":"楼上装修的电钻声没完没了，吵得我头疼。","pinyin":"Lóushàng zhuāngxiū de diànzuàn shēng méi wán méiliǎo, chǎo de wǒ tóuténg.","vi":"Tiếng khoan sửa nhà tầng trên cứ kéo dài không dứt, ồn đến nỗi tôi nhức đầu."},{"type":"compound","zh":"如果你们再这样没完没了地吵下去，邻居就要报警了。","pinyin":"Rúguǒ nǐmen zài zhèyàng méi wán méiliǎo de chǎo xiàqù, línjū jiùyào bàojǐng le.","vi":"Nếu các người cứ cãi nhau không dứt như thế này, hàng xóm sẽ báo cảnh sát đấy."}],"related":[{"hanzi":"无休无止","pinyin":"wúxiūwúzhǐ","vi":"không ngừng nghỉ"},{"hanzi":"不停","pinyin":"bùtíng","vi":"không ngừng"},{"hanzi":"啰嗦","pinyin":"luōsuo","vi":"lải nhải"}],"traditional":"沒完沒了"},{"id":"门道","hanzi":"门道","pinyin":"méndao","meaning_vi":"bí quyết, ngõ ngách trong nghề","explanation":"门 (môn – cửa) + 道 (đạo – đường) → đường đi vào cửa; nghĩa bóng: bí quyết, mánh khóe trong nghề. Câu quen thuộc: 外行看热闹, 内行看门道.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔑","examples":[{"type":"basic","zh":"做生意有很多门道。","pinyin":"Zuòshēngyi yǒu hěn duō méndao.","vi":"Làm ăn buôn bán có rất nhiều bí quyết."},{"type":"simple","zh":"老师傅一看木头的纹理，就能说出其中的门道。","pinyin":"Lǎo shīfu yí kàn mùtou de wénlǐ, jiù néng shuōchū qízhōng de méndao.","vi":"Bác thợ cả chỉ cần nhìn vân gỗ là nói ra được những điều tinh tường bên trong."},{"type":"compound","zh":"内行看门道，外行看热闹，所以你要多向师傅请教。","pinyin":"Nèiháng kàn méndao, wàiháng kànrènao, suǒyǐ nǐ yào duō xiàng shīfu qǐngjiào.","vi":"Người trong nghề xem bí quyết, kẻ ngoại đạo xem cho vui, vì vậy bạn nên thỉnh giáo sư phụ nhiều hơn."}],"related":[{"hanzi":"窍门","pinyin":"qiàomén","vi":"mẹo"},{"hanzi":"诀窍","pinyin":"juéqiào","vi":"bí quyết"},{"hanzi":"内行","pinyin":"nèiháng","vi":"người trong nghề"}],"traditional":"門道"},{"id":"门户","hanzi":"门户","pinyin":"ménhù","meaning_vi":"cửa ngõ; môn phái, bè phái","explanation":"门 (môn – cửa) + 户 (hộ – cửa một cánh, nhà) → cửa ngõ, cửa ra vào; nghĩa mở rộng: môn phái, gia thế, cổng thông tin (门户网站).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"🚪","examples":[{"type":"basic","zh":"这里是城市的门户。","pinyin":"Zhèlǐ shì chéngshì de ménhù.","vi":"Đây là cửa ngõ của thành phố."},{"type":"simple","zh":"海防港是越南北部重要的出海门户。","pinyin":"Hǎifáng gǎng shì Yuènán Běibù zhòngyào de chūhǎi ménhù.","vi":"Cảng Hải Phòng là cửa ngõ ra biển quan trọng của miền Bắc Việt Nam."},{"type":"compound","zh":"既然大家都是为了把武术传下去，就不要再有门户之见了。","pinyin":"Jìrán dàjiā dōu shì wèile bǎ wǔshù chuán xiàqù, jiù bú yào zài yǒu ménhù zhī jiàn le.","vi":"Mọi người đều vì muốn truyền lại võ thuật, vậy thì đừng còn thành kiến môn phái nữa."}],"related":[{"hanzi":"门户网站","pinyin":"ménhùwǎngzhàn","vi":"cổng thông tin"},{"hanzi":"门派","pinyin":"ménpài","vi":"môn phái"},{"hanzi":"大门","pinyin":"dàmén","vi":"cổng chính"}],"traditional":"門戶"},{"id":"门槛","hanzi":"门槛","pinyin":"ménkǎn","meaning_vi":"ngưỡng cửa; tiêu chuẩn đầu vào, rào cản gia nhập","explanation":"门 (门) + 槛 (ngưỡng cửa).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🚧","examples":[{"type":"basic","zh":"这家公司的门槛很高。","pinyin":"Zhè jiā gōngsī de ménkǎn hěn gāo.","vi":"Tiêu chuẩn đầu vào của công ty này rất cao."},{"type":"simple","zh":"新娘跨过门槛时，亲友们纷纷撒下彩纸。","pinyin":"Xīnniáng kuàguò ménkǎn shí, qīnyǒumen fēnfēn sǎ xià cǎi zhǐ.","vi":"Khi cô dâu bước qua ngưỡng cửa, người thân bạn bè rải giấy màu."},{"type":"compound","zh":"虽然开奶茶店的门槛不高，但是想长期经营下去并不容易。","pinyin":"Suīrán kāi nǎichá diàn de ménkǎn bù gāo, dànshì xiǎng chángqī jīngyíng xiàqù bìngbù róngyì.","vi":"Tuy ngưỡng gia nhập để mở tiệm trà sữa không cao, nhưng muốn kinh doanh lâu dài thì không hề dễ."}],"related":[{"hanzi":"门坎","pinyin":"ménkǎn","vi":"bậu cửa"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"准入","pinyin":"zhǔnrù","vi":"điều kiện gia nhập"}],"traditional":"門檻"},{"id":"蒙蔽","hanzi":"蒙蔽","pinyin":"méngbì","meaning_vi":"che mắt, lừa gạt","explanation":"蒙 (đoán bừa) + 蔽 (che giấu/che khuất).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙈","examples":[{"type":"basic","zh":"别被假象蒙蔽了。","pinyin":"Bié bèi jiǎxiàng méngbì le.","vi":"Đừng để vẻ bề ngoài đánh lừa."},{"type":"simple","zh":"那个骗子用高额回报蒙蔽了上百位退休老人。","pinyin":"Nà ge piànzi yòng gāo'é huíbào méngbìle shàng bǎiwèi tuìxiū lǎorén.","vi":"Tên lừa đảo đó dùng lợi nhuận cao để lừa gạt hơn trăm người già về hưu."},{"type":"compound","zh":"即使一时能蒙蔽群众，谎言最终也会被揭穿。","pinyin":"Jíshǐ yìshí néng méngbì qúnzhòng, huǎngyán zuìzhōng yě huì bèi jiēchuān.","vi":"Dù có thể che mắt quần chúng nhất thời, lời dối trá cuối cùng cũng sẽ bị vạch trần."}],"related":[{"hanzi":"欺骗","pinyin":"qīpiàn","vi":"lừa dối"},{"hanzi":"蒙骗","pinyin":"mēngpiàn","vi":"lừa gạt"},{"hanzi":"揭穿","pinyin":"jiēchuān","vi":"vạch trần"}],"traditional":"矇蔽"},{"id":"萌发","hanzi":"萌发","pinyin":"méngfā","meaning_vi":"nảy mầm, nảy sinh (ý tưởng/tình cảm)","explanation":"萌 (nảy mầm/dễ thương) + 发 (发).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"种子萌发了。","pinyin":"Zhǒngzi méngfā le.","vi":"Hạt giống đã nảy mầm."},{"type":"simple","zh":"看完那部纪录片，他心中萌发了学医的念头。","pinyin":"Kàn wán nà bù jìlùpiàn, tā xīnzhōng méngfāle xuéyī de niàntou.","vi":"Xem xong bộ phim tài liệu đó, trong lòng anh ấy nảy sinh ý định học y."},{"type":"compound","zh":"只要温度和水分合适，豆子两三天就会萌发出嫩芽。","pinyin":"Zhǐyào wēndù hé shuǐfèn héshì, dòuzi liǎng sān tiān jiù huì méngfā chū nènyá.","vi":"Chỉ cần nhiệt độ và độ ẩm phù hợp, hạt đậu hai ba ngày sẽ nảy mầm non."}],"related":[{"hanzi":"萌芽","pinyin":"méngyá","vi":"nảy mầm"},{"hanzi":"发芽","pinyin":"fāyá","vi":"nảy mầm"},{"hanzi":"产生","pinyin":"chǎnshēng","vi":"nảy sinh"}],"traditional":"萌發"},{"id":"密集","hanzi":"密集","pinyin":"mìjí","meaning_vi":"dày đặc, tập trung cao độ","explanation":"密 (bí mật/mật độ) + 集 (tập hợp).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏙️","examples":[{"type":"basic","zh":"这里人口密集。","pinyin":"Zhèlǐ rénkǒu mìjí.","vi":"Nơi đây dân cư đông đúc."},{"type":"simple","zh":"雨点密集地打在铁皮屋顶上，噼里啪啦响个不停。","pinyin":"Yǔdiǎn mìjí de dǎ zài tiěpí wūdǐng shàng, pī li pā lā xiǎng gè bùtíng.","vi":"Hạt mưa dày đặc rơi xuống mái tôn, kêu lộp độp không ngớt."},{"type":"compound","zh":"因为这一带工厂密集，所以空气质量一直不太好。","pinyin":"Yīnwèi zhè yídài gōngchǎng mìjí, suǒyǐ kōngqì zhìliàng yìzhí bú tài hǎo.","vi":"Vì khu vực này nhà máy dày đặc nên chất lượng không khí luôn không được tốt."}],"related":[{"hanzi":"稠密","pinyin":"chóumì","vi":"đông đúc"},{"hanzi":"密度","pinyin":"mìdù","vi":"mật độ"},{"hanzi":"稀疏","pinyin":"xīshū","vi":"thưa thớt"}]},{"id":"命脉","hanzi":"命脉","pinyin":"mìngmài","meaning_vi":"mạch sống, huyết mạch (kinh tế/giao thông)","explanation":"命 (mệnh lệnh/số phận) + 脉 (mạch máu/dãy núi).","hsk_level":"7-9","tags":["danh-tu"],"image":"🫀","examples":[{"type":"basic","zh":"水利是农业的命脉。","pinyin":"Shuǐlì shì nóngyè de mìngmài.","vi":"Thủy lợi là huyết mạch của nông nghiệp."},{"type":"simple","zh":"这条铁路是连接南北的交通命脉。","pinyin":"Zhè tiáo tiělù shì liánjiē nánběi de jiāotōng mìngmài.","vi":"Tuyến đường sắt này là huyết mạch giao thông nối liền Bắc Nam."},{"type":"compound","zh":"一旦能源命脉被别人控制，国家安全就会受到威胁。","pinyin":"Yídàn néngyuán mìngmài bèi biérén kòngzhì, guójiā ānquán jiù huì shòudào wēixié.","vi":"Một khi huyết mạch năng lượng bị người khác khống chế, an ninh quốc gia sẽ bị đe dọa."}],"related":[{"hanzi":"生命线","pinyin":"shēngmìngxiàn","vi":"huyết mạch"},{"hanzi":"经济命脉","pinyin":"jīngjìmìngmài","vi":"huyết mạch kinh tế"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"then chốt"}],"traditional":"命脈"},{"id":"命题","hanzi":"命题","pinyin":"mìngtí","meaning_vi":"mệnh đề; ra đề (thi)","explanation":"命 (mệnh lệnh/số phận) + 题 (đề tài/vấn đề).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"这个命题是错误的。","pinyin":"Zhè ge mìngtí shì cuòwù de.","vi":"Mệnh đề này là sai."},{"type":"simple","zh":"今年的高考作文由教育部考试中心统一命题。","pinyin":"Jīnnián de gāokǎo zuòwén yóu Jiàoyùbù kǎoshì zhōngxīn tǒngyī mìngtí.","vi":"Đề văn thi đại học năm nay do Trung tâm Khảo thí Bộ Giáo dục thống nhất ra đề."},{"type":"compound","zh":"如果命题的前提不成立，那么结论自然也不成立。","pinyin":"Rúguǒ mìngtí de qiántí bù chénglì, nàme jiélùn zìrán yě bù chénglì.","vi":"Nếu tiền đề của mệnh đề không đúng, thì kết luận đương nhiên cũng không đúng."}],"related":[{"hanzi":"出题","pinyin":"chūtí","vi":"ra đề"},{"hanzi":"题目","pinyin":"tímù","vi":"đề bài"},{"hanzi":"论题","pinyin":"lùntí","vi":"luận đề"}],"traditional":"命題"},{"id":"谜底","hanzi":"谜底","pinyin":"mídǐ","meaning_vi":"lời giải câu đố, bí mật được hé lộ","explanation":"谜 (câu đố/bí ẩn) + 底 (đáy).","hsk_level":"7-9","tags":["danh-tu"],"image":"💡","examples":[{"type":"basic","zh":"谜底终于揭晓了。","pinyin":"Mídǐ zhōngyú jiēxiǎo le.","vi":"Lời giải cuối cùng đã được công bố."},{"type":"simple","zh":"元宵节晚上，孩子们围着灯笼猜谜底。","pinyin":"Yuánxiāojié wǎnshang, háizimen wéizhe dēnglong cāi mídǐ.","vi":"Tối Tết Nguyên tiêu, bọn trẻ vây quanh đèn lồng đoán câu đố."},{"type":"compound","zh":"直到警方公布调查结果，这起失踪案的谜底才被揭开。","pinyin":"Zhídào jǐngfāng gōngbù diàochá jiéguǒ, zhè qǐ shīzōng àn de mídǐ cái bèi jiēkāi.","vi":"Mãi đến khi cảnh sát công bố kết quả điều tra, bí mật của vụ mất tích này mới được hé lộ."}],"related":[{"hanzi":"谜语","pinyin":"míyǔ","vi":"câu đố"},{"hanzi":"谜面","pinyin":"mímiàn","vi":"câu đố đưa ra"},{"hanzi":"答案","pinyin":"dá'àn","vi":"đáp án"}],"traditional":"謎底"},{"id":"迷恋","hanzi":"迷恋","pinyin":"míliàn","meaning_vi":"mê luyến, say đắm","explanation":"迷 (mê mẩn/lạc) + 恋 (lưu luyến/yêu đương).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😍","examples":[{"type":"basic","zh":"他迷恋上了摄影。","pinyin":"Tā míliàn shàngle shèyǐng.","vi":"Anh ấy đã say mê nhiếp ảnh."},{"type":"simple","zh":"弟弟迷恋网络游戏，常常玩到半夜才睡。","pinyin":"Dìdi míliàn wǎngluò yóuxì, chángcháng wán dào bànyè cái shuì.","vi":"Em trai mê game online, thường chơi đến nửa đêm mới ngủ."},{"type":"compound","zh":"与其迷恋过去的辉煌，不如脚踏实地做好眼前的事。","pinyin":"Yǔqí míliàn guòqù de huīhuáng, bùrú jiǎotàshídì zuò hǎo yǎnqián de shì.","vi":"Thay vì đắm chìm trong vinh quang quá khứ, chi bằng chăm chỉ làm tốt việc trước mắt."}],"related":[{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"mê mẩn"},{"hanzi":"痴迷","pinyin":"chīmí","vi":"si mê"}],"traditional":"迷戀"},{"id":"迷失","hanzi":"迷失","pinyin":"míshī","meaning_vi":"lạc lối, đánh mất phương hướng","explanation":"迷 (mê mẩn/lạc) + 失 (mất đi/sai sót).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧭","examples":[{"type":"basic","zh":"我们在森林里迷失了。","pinyin":"Wǒmen zài sēnlín lǐ míshī le.","vi":"Chúng tôi đã lạc đường trong rừng."},{"type":"simple","zh":"突然成名以后，这位年轻歌手渐渐迷失了自我。","pinyin":"Tūrán chéngmíng yǐhòu, zhè wèi niánqīng gēshǒu jiànjiàn míshīle zìwǒ.","vi":"Sau khi đột nhiên nổi tiếng, ca sĩ trẻ này dần dần đánh mất bản thân."},{"type":"compound","zh":"如果没有明确的目标，人就很容易在诱惑中迷失方向。","pinyin":"Rúguǒ méiyǒu míngquè de mùbiāo, rén jiù hěn róngyì zài yòuhuò zhōng míshī fāngxiàng.","vi":"Nếu không có mục tiêu rõ ràng, con người rất dễ lạc hướng giữa những cám dỗ."}],"related":[{"hanzi":"迷路","pinyin":"mílù","vi":"lạc đường"},{"hanzi":"迷失方向","pinyin":"míshīfāngxiàng","vi":"mất phương hướng"},{"hanzi":"迷茫","pinyin":"mímáng","vi":"mơ hồ"}]},{"id":"谜团","hanzi":"谜团","pinyin":"mítuán","meaning_vi":"bí ẩn chưa có lời giải","explanation":"谜 (câu đố/bí ẩn) + 团 (đoàn).","hsk_level":"7-9","tags":["danh-tu"],"image":"❓","examples":[{"type":"basic","zh":"这仍是个谜团。","pinyin":"Zhè réng shì gè mítuán.","vi":"Đây vẫn là một điều bí ẩn."},{"type":"simple","zh":"金字塔是怎样建成的，至今仍是一个谜团。","pinyin":"Jīnzìtǎ shì zěnyàng jiànchéng de, zhìjīn réng shì yí gè mítuán.","vi":"Kim tự tháp được xây dựng thế nào đến nay vẫn là một bí ẩn."},{"type":"compound","zh":"虽然专家们研究了几十年，但是这个谜团还是没有解开。","pinyin":"Suīrán zhuānjiāmen yánjiūle jǐ shí nián, dànshì zhè ge mítuán háishì méiyǒu jiěkāi.","vi":"Tuy các chuyên gia đã nghiên cứu mấy chục năm, nhưng bí ẩn này vẫn chưa được giải đáp."}],"related":[{"hanzi":"谜","pinyin":"mí","vi":"câu đố"},{"hanzi":"疑团","pinyin":"yítuán","vi":"mối nghi ngờ"},{"hanzi":"悬案","pinyin":"xuán'àn","vi":"vụ án chưa giải"}],"traditional":"謎團"},{"id":"弥足珍贵","hanzi":"弥足珍贵","pinyin":"mízú-zhēnguì","meaning_vi":"vô cùng quý giá","explanation":"弥 (bù đắp/lan tỏa) + 足 (đầy đủ/chân) + 珍 (trân trọng/quý giá) + 贵 (đắt).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"友情弥足珍贵。","pinyin":"Yǒuqíng mízúzhēnguì.","vi":"Tình bạn vô cùng quý giá."},{"type":"simple","zh":"这张泛黄的全家福对奶奶来说弥足珍贵。","pinyin":"Zhè zhāng fàn huáng de quánjiāfú duì nǎinai lái shuō mízúzhēnguì.","vi":"Tấm ảnh gia đình đã ố vàng này đối với bà nội vô cùng quý giá."},{"type":"compound","zh":"因为和父母相处的时间越来越少，所以每次团聚都弥足珍贵。","pinyin":"Yīnwèi hé fùmǔ xiāngchǔ de shíjiān yuèláiyuè shǎo, suǒyǐ měi cì tuánjù dōu mízúzhēnguì.","vi":"Vì thời gian ở bên cha mẹ ngày càng ít nên mỗi lần đoàn tụ đều vô cùng quý giá."}],"related":[{"hanzi":"珍贵","pinyin":"zhēnguì","vi":"quý giá"},{"hanzi":"宝贵","pinyin":"bǎoguì","vi":"quý báu"},{"hanzi":"难能可贵","pinyin":"nánnéngkěguì","vi":"hiếm có đáng quý"}],"traditional":"彌足珍貴"},{"id":"民办","hanzi":"民办","pinyin":"mínbàn","meaning_vi":"dân lập, tư thục (trường học/bệnh viện)","explanation":"民 (nhân dân/dân chủ) + 办 (办).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🏫","examples":[{"type":"basic","zh":"这是一所民办大学。","pinyin":"Zhè shì yì suǒ mínbàn dàxué.","vi":"Đây là một trường đại học dân lập."},{"type":"simple","zh":"小区旁边新开了一家民办幼儿园。","pinyin":"Xiǎoqū pángbiān xīn kāile yìjiā mínbàn yòu'éryuán.","vi":"Bên cạnh khu dân cư mới mở một trường mầm non tư thục."},{"type":"compound","zh":"虽然民办学校的学费比较高，但是班级人数少。","pinyin":"Suīrán mínbàn xuéxiào de xuéfèi bǐjiào gāo, dànshì bānjí rénshù shǎo.","vi":"Tuy học phí trường tư thục khá cao, nhưng sĩ số mỗi lớp ít."}],"related":[{"hanzi":"公办","pinyin":"gōngbàn","vi":"công lập"},{"hanzi":"私立","pinyin":"sīlì","vi":"tư lập"},{"hanzi":"民营","pinyin":"mínyíng","vi":"dân doanh"}],"traditional":"民辦"},{"id":"民风","hanzi":"民风","pinyin":"mínfēng","meaning_vi":"phong tục tập quán dân gian","explanation":"民 (nhân dân/dân chủ) + 风 (风).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏮","examples":[{"type":"basic","zh":"这里民风淳朴。","pinyin":"Zhèlǐ mínfēng chúnpǔ.","vi":"Phong tục nơi đây chất phác."},{"type":"simple","zh":"山里的民风热情好客，游客常被请到家里吃饭。","pinyin":"Shān lǐ de mínfēng rèqíng hàokè, yóukè cháng bèi qǐng dào jiālǐ chīfàn.","vi":"Người dân vùng núi nhiệt tình hiếu khách, du khách thường được mời vào nhà ăn cơm."},{"type":"compound","zh":"因为民风淳朴，所以村里多年来夜不闭户。","pinyin":"Yīnwèi mínfēng chúnpǔ, suǒyǐ cūnlǐ duōniánlái yè bú bì hù.","vi":"Vì phong tục chất phác nên nhiều năm nay trong làng đêm không cần đóng cửa."}],"related":[{"hanzi":"民俗","pinyin":"mínsú","vi":"phong tục dân gian"},{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"民风淳朴","pinyin":"mínfēngchúnpǔ","vi":"phong tục chất phác"}],"traditional":"民風"},{"id":"民生福祉","hanzi":"民生福祉","pinyin":"mínshēngfúzhǐ","meaning_vi":"phúc lợi dân sinh","explanation":"民 (nhân dân/dân chủ) + 生 (sinh tồn/sinh động) + 福 (福) + 祉 (phúc lành).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏡","examples":[{"type":"basic","zh":"政府重视民生福祉。","pinyin":"Zhèngfǔ zhòngshì mínshēngfúzhǐ.","vi":"Chính phủ coi trọng phúc lợi dân sinh."},{"type":"simple","zh":"新建的地铁线路直接关系到几百万市民的民生福祉。","pinyin":"Xīnjiàn de dìtiě xiànlù zhíjiē guānxìdào jǐ bǎiwàn shìmín de mínshēngfúzhǐ.","vi":"Tuyến tàu điện ngầm mới xây liên quan trực tiếp đến phúc lợi dân sinh của mấy triệu người dân."},{"type":"compound","zh":"只有经济持续发展，民生福祉才能不断提高。","pinyin":"Zhǐyǒu jīngjì chíxù fāzhǎn, mínshēngfúzhǐ cáinéng búduàn tígāo.","vi":"Chỉ khi kinh tế phát triển bền vững, phúc lợi dân sinh mới không ngừng được nâng cao."}],"related":[{"hanzi":"民生","pinyin":"mínshēng","vi":"dân sinh"},{"hanzi":"福利","pinyin":"fúlì","vi":"phúc lợi"},{"hanzi":"幸福","pinyin":"xìngfú","vi":"hạnh phúc"}]},{"id":"民俗","hanzi":"民俗","pinyin":"mínsú","meaning_vi":"phong tục dân gian","explanation":"民 (nhân dân/dân chủ) + 俗 (phong tục/thông tục).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"我对民俗很感兴趣。","pinyin":"Wǒ duì mínsú hěn gǎnxìngqù.","vi":"Tôi rất hứng thú với phong tục dân gian."},{"type":"simple","zh":"春节期间，古镇上举办了舞狮、踩高跷等民俗活动。","pinyin":"Chūnjié qījiān, gǔzhèn shàng jǔbànle wǔshī, cǎigāoqiāo děng mínsú huódòng.","vi":"Dịp Tết, thị trấn cổ tổ chức các hoạt động dân gian như múa lân, đi cà kheo."},{"type":"compound","zh":"如果不及时记录整理，很多传统民俗就会慢慢消失。","pinyin":"Rúguǒ bù jíshí jìlù zhěnglǐ, hěn duō chuántǒng mínsú jiù huì mànmàn xiāoshī.","vi":"Nếu không kịp thời ghi chép chỉnh lý, nhiều phong tục dân gian truyền thống sẽ dần biến mất."}],"related":[{"hanzi":"风俗","pinyin":"fēngsú","vi":"phong tục"},{"hanzi":"习俗","pinyin":"xísú","vi":"tập tục"},{"hanzi":"民间","pinyin":"mínjiān","vi":"dân gian"}]},{"id":"民意","hanzi":"民意","pinyin":"mínyì","meaning_vi":"ý nguyện của nhân dân, dư luận","explanation":"民 (nhân dân/dân chủ) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🗳️","examples":[{"type":"basic","zh":"要尊重民意。","pinyin":"Yào zūnzhòng mínyì.","vi":"Phải tôn trọng ý dân."},{"type":"simple","zh":"电视台在街头做了一次关于房价的民意调查。","pinyin":"Diànshìtái zài jiētóu zuòle yí cì guānyú fángjià de mínyì diàochá.","vi":"Đài truyền hình đã làm một cuộc thăm dò dư luận về giá nhà trên đường phố."},{"type":"compound","zh":"如果政策违背民意，即使强行推行也难以长久。","pinyin":"Rúguǒ zhèngcè wéibèi mínyì, jíshǐ qiángxíng tuīxíng yě nányǐ chángjiǔ.","vi":"Nếu chính sách đi ngược ý dân, dù có cưỡng ép thi hành cũng khó mà lâu dài."}],"related":[{"hanzi":"民心","pinyin":"mínxīn","vi":"lòng dân"},{"hanzi":"舆论","pinyin":"yúlùn","vi":"dư luận"},{"hanzi":"民意调查","pinyin":"mínyìdiàochá","vi":"thăm dò dư luận"}]},{"id":"民众","hanzi":"民众","pinyin":"mínzhòng","meaning_vi":"quần chúng nhân dân","explanation":"民 (nhân dân/dân chủ) + 众 (quần chúng/đông đảo).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"👥","examples":[{"type":"basic","zh":"民众纷纷捐款。","pinyin":"Mínzhòng fēnfēn juānkuǎn.","vi":"Người dân nô nức quyên góp tiền."},{"type":"simple","zh":"台风过后，当地民众自发清理街道上的树枝。","pinyin":"Táifēng guòhòu, dāngdì mínzhòng zìfā qīnglǐ jiēdào shàng de shùzhī.","vi":"Sau cơn bão, người dân địa phương tự giác dọn dẹp cành cây trên đường phố."},{"type":"compound","zh":"只要政府信息公开透明，民众就不会轻信谣言。","pinyin":"Zhǐyào zhèngfǔ xìnxī gōngkāi tòumíng, mínzhòng jiù bú huì qīngxìn yáoyán.","vi":"Chỉ cần chính quyền công khai minh bạch thông tin, người dân sẽ không dễ tin tin đồn."}],"related":[{"hanzi":"群众","pinyin":"qúnzhòng","vi":"quần chúng"},{"hanzi":"百姓","pinyin":"bǎixìng","vi":"dân chúng"},{"hanzi":"公众","pinyin":"gōngzhòng","vi":"công chúng"}],"traditional":"民眾"},{"id":"名家","hanzi":"名家","pinyin":"míngjiā","meaning_vi":"danh gia, bậc thầy nổi tiếng","explanation":"名 (danh tiếng/nổi tiếng) + 家 (nhà).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"👑","examples":[{"type":"basic","zh":"这是名家的作品。","pinyin":"Zhè shì míngjiā de zuòpǐn.","vi":"Đây là tác phẩm của danh gia."},{"type":"simple","zh":"这次书法展汇集了全国二十多位名家的真迹。","pinyin":"Zhè cì shūfǎ zhǎn huìjíle quánguó èrshíduō wèi míngjiā de zhēn jì.","vi":"Triển lãm thư pháp lần này quy tụ bút tích thật của hơn hai mươi danh gia cả nước."},{"type":"compound","zh":"虽然他拜过很多名家为师，但是一直坚持自己的风格。","pinyin":"Suīrán tā bàiguò hěn duō míngjiā wéishī, dànshì yìzhí jiānchí zìjǐ de fēnggé.","vi":"Tuy anh ấy đã bái nhiều bậc thầy nổi tiếng làm thầy, nhưng vẫn luôn giữ phong cách riêng."}],"related":[{"hanzi":"大师","pinyin":"dàshī","vi":"bậc thầy"},{"hanzi":"名人","pinyin":"míngrén","vi":"người nổi tiếng"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"}]},{"id":"铭记","hanzi":"铭记","pinyin":"míngjì","meaning_vi":"khắc ghi sâu sắc","explanation":"铭 (khắc ghi) + 记 (记).","hsk_level":"7-9","tags":["dong-tu"],"image":"❤️","examples":[{"type":"basic","zh":"我会永远铭记这一天。","pinyin":"Wǒ huì yǒngyuǎn míngjì zhè yì tiān.","vi":"Tôi sẽ mãi khắc ghi ngày hôm nay."},{"type":"simple","zh":"我们应当铭记那些为国家献出生命的英雄。","pinyin":"Wǒmen yīngdāng míngjì nàxiē wèi guójiā xiànchū shēngmìng de yīngxióng.","vi":"Chúng ta nên khắc ghi những anh hùng đã hiến dâng sinh mạng cho đất nước."},{"type":"compound","zh":"虽然老师已经退休多年，但是学生们一直铭记着她的教诲。","pinyin":"Suīrán lǎoshī yǐjīng tuìxiū duōnián, dànshì xuéshengmen yìzhí míngjìzhe tā de jiàohuì.","vi":"Tuy cô giáo đã nghỉ hưu nhiều năm, nhưng học trò vẫn luôn khắc ghi lời dạy của cô."}],"related":[{"hanzi":"牢记","pinyin":"láojì","vi":"ghi nhớ"},{"hanzi":"铭刻","pinyin":"míngkè","vi":"khắc sâu"},{"hanzi":"遗忘","pinyin":"yíwàng","vi":"lãng quên"}],"traditional":"銘記"},{"id":"铭刻","hanzi":"铭刻","pinyin":"míngkè","meaning_vi":"khắc sâu","explanation":"铭 (khắc ghi) + 刻 (khắc ghi/sâu sắc).","hsk_level":"7-9","tags":["dong-tu"],"image":"🗿","examples":[{"type":"basic","zh":"碑上铭刻着名字。","pinyin":"Bēi shàng míngkèzhe míngzi.","vi":"Trên bia có khắc tên."},{"type":"simple","zh":"这段苦难的历史深深铭刻在每个村民的心里。","pinyin":"Zhè duàn kǔnàn de lìshǐ shēnshēn míngkè zài měi gè cūnmín de xīnlǐ.","vi":"Đoạn lịch sử khổ nạn này khắc sâu trong lòng mỗi người dân làng."},{"type":"compound","zh":"即使过了半个世纪，那次离别也依然铭刻在她的记忆中。","pinyin":"Jíshǐguò le bàn gè shìjì, nà cì líbié yě yīrán míngkè zài tā de jìyì zhōng.","vi":"Dù đã qua nửa thế kỷ, cuộc chia ly ấy vẫn khắc sâu trong ký ức của bà."}],"related":[{"hanzi":"铭记","pinyin":"míngjì","vi":"khắc ghi"},{"hanzi":"雕刻","pinyin":"diāokè","vi":"điêu khắc"},{"hanzi":"刻骨铭心","pinyin":"kègǔmíngxīn","vi":"khắc cốt ghi tâm"}],"traditional":"銘刻"},{"id":"名利","hanzi":"名利","pinyin":"mínglì","meaning_vi":"danh lợi","explanation":"名 (danh tiếng/nổi tiếng) + 利 (lợi ích/thuận lợi).","hsk_level":"7-9","tags":["danh-tu"],"image":"💰","examples":[{"type":"basic","zh":"他看淡了名利。","pinyin":"Tā kàndànle mínglì.","vi":"Ông ấy đã xem nhẹ danh lợi."},{"type":"simple","zh":"这位老科学家一生淡泊名利，只专心做研究。","pinyin":"Zhè wèi lǎo kēxuéjiā yìshēng dànbómínglì, zhǐ zhuānxīn zuò yánjiū.","vi":"Vị nhà khoa học già cả đời không màng danh lợi, chỉ chuyên tâm nghiên cứu."},{"type":"compound","zh":"一个人如果太看重名利，就很容易迷失初心。","pinyin":"Yígèrén rúguǒ tài kànzhòng mínglì, jiù hěn róngyì míshī chūxīn.","vi":"Một người nếu quá coi trọng danh lợi, sẽ rất dễ đánh mất tâm nguyện ban đầu."}],"related":[{"hanzi":"名声","pinyin":"míngshēng","vi":"danh tiếng"},{"hanzi":"利益","pinyin":"lìyì","vi":"lợi ích"},{"hanzi":"淡泊名利","pinyin":"dànbómínglì","vi":"xem nhẹ danh lợi"}]},{"id":"明朗","hanzi":"明朗","pinyin":"mínglǎng","meaning_vi":"rõ ràng sáng sủa (tình hình/tính cách)","explanation":"明 (sáng suốt/rõ ràng) + 朗 (sáng sủa/cởi mở).","hsk_level":"7-9","tags":["tinh-tu"],"image":"☀️","examples":[{"type":"basic","zh":"形势逐渐明朗了。","pinyin":"Xíngshì zhújiàn mínglǎng le.","vi":"Tình hình đã dần sáng tỏ."},{"type":"simple","zh":"她性格明朗大方，跟谁都能聊得来。","pinyin":"Tā xìnggé mínglǎng dàfang, gēn shéi dōu néng liáo delái.","vi":"Cô ấy tính cách cởi mở hào phóng, nói chuyện với ai cũng hợp."},{"type":"compound","zh":"等到调查结果明朗以后，我们再决定下一步怎么做。","pinyin":"Děngdào diàochá jiéguǒ mínglǎng yǐhòu, wǒmen zài juédìng xiàyíbù zěnme zuò.","vi":"Đợi đến khi kết quả điều tra rõ ràng, chúng ta sẽ quyết định bước tiếp theo."}],"related":[{"hanzi":"晴朗","pinyin":"qínglǎng","vi":"quang đãng"},{"hanzi":"开朗","pinyin":"kāilǎng","vi":"cởi mở"},{"hanzi":"模糊","pinyin":"móhu","vi":"mơ hồ"}]},{"id":"明媚","hanzi":"明媚","pinyin":"míngmèi","meaning_vi":"tươi sáng rạng rỡ (ánh nắng/cảnh xuân)","explanation":"明 (sáng suốt/rõ ràng) + 媚 (tươi đẹp/nịnh bợ).","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🌸","examples":[{"type":"basic","zh":"今天阳光明媚。","pinyin":"Jīntiān yángguāng míngmèi.","vi":"Hôm nay nắng đẹp rực rỡ."},{"type":"simple","zh":"春光明媚的周末，公园里到处是放风筝的孩子。","pinyin":"Chūnguāng míngmèi de zhōumò, gōngyuán lǐ dàochù shì fàngfēngzheng de háizi.","vi":"Cuối tuần xuân sắc tươi sáng, công viên đâu đâu cũng có trẻ em thả diều."},{"type":"compound","zh":"虽然早上还下着雨，但是中午就变得阳光明媚了。","pinyin":"Suīrán zǎoshang hái xiàzhe yǔ, dànshì zhōngwǔ jiù biànde yángguāng míngmèi le.","vi":"Tuy buổi sáng vẫn còn mưa, nhưng đến trưa trời đã nắng đẹp rạng rỡ."}],"related":[{"hanzi":"阳光明媚","pinyin":"yángguāngmíngmèi","vi":"nắng xuân rực rỡ"},{"hanzi":"灿烂","pinyin":"cànlàn","vi":"rực rỡ"},{"hanzi":"阴暗","pinyin":"yīn'àn","vi":"âm u"}]},{"id":"明晰","hanzi":"明晰","pinyin":"míngxī","meaning_vi":"rõ ràng mạch lạc","explanation":"明 (sáng suốt/rõ ràng) + 晰 (晰).","hsk_level":"7-9","tags":["tinh-tu"],"image":"💡","examples":[{"type":"basic","zh":"思路很明晰。","pinyin":"Sīlù hěn míngxī.","vi":"Mạch suy nghĩ rất rõ ràng."},{"type":"simple","zh":"这份报告结构明晰，重点一目了然。","pinyin":"Zhè fèn bàogào jiégòu míngxī, zhòngdiǎn yímùliǎorán.","vi":"Bản báo cáo này kết cấu rõ ràng, trọng điểm nhìn qua là thấy."},{"type":"compound","zh":"只有职责划分明晰，部门之间才不会互相推诿。","pinyin":"Zhǐyǒu zhízé huàfēn míngxī, bùmén zhījiān cái bú huì hùxiāng tuīwěi.","vi":"Chỉ khi phân chia trách nhiệm rõ ràng, các phòng ban mới không đùn đẩy lẫn nhau."}],"related":[{"hanzi":"清晰","pinyin":"qīngxī","vi":"rõ nét"},{"hanzi":"明确","pinyin":"míngquè","vi":"rõ ràng"},{"hanzi":"模糊","pinyin":"móhu","vi":"mơ hồ"}]},{"id":"默契","hanzi":"默契","pinyin":"mòqì","meaning_vi":"sự ăn ý tâm đầu ý hợp","explanation":"默 (âm thầm/im lặng) + 契 (hợp đồng/ăn ý).","hsk_level":"7-9","tags":["danh-tu","tinh-tu"],"image":"🤝","examples":[{"type":"basic","zh":"我们配合很默契。","pinyin":"Wǒmen pèihé hěn mòqì.","vi":"Chúng tôi phối hợp rất ăn ý."},{"type":"simple","zh":"两位老搭档一个眼神，就知道对方想说什么，非常默契。","pinyin":"Liǎng wèi lǎodādàng yí gè yǎnshén, jiù zhīdào duìfāng xiǎng shuō shénme, fēicháng mòqì.","vi":"Hai cộng sự lâu năm chỉ cần một ánh mắt là biết đối phương muốn nói gì, vô cùng ăn ý."},{"type":"compound","zh":"虽然他们第一次合作，但是彼此之间已经有了默契。","pinyin":"Suīrán tāmen dìyīcì hézuò, dànshì bǐcǐ zhījiān yǐjīng yǒule mòqì.","vi":"Tuy họ mới hợp tác lần đầu, nhưng giữa hai bên đã có sự ăn ý."}],"related":[{"hanzi":"配合默契","pinyin":"pèihémòqì","vi":"phối hợp ăn ý"},{"hanzi":"心照不宣","pinyin":"xīnzhàobùxuān","vi":"ngầm hiểu nhau"},{"hanzi":"合拍","pinyin":"hépāi","vi":"ăn khớp"}]},{"id":"末期","hanzi":"末期","pinyin":"mòqī","meaning_vi":"giai đoạn cuối","explanation":"末 (cuối cùng/vụn nhỏ) + 期 (期).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"他是癌症末期。","pinyin":"Tā shì áizhèng mòqī.","vi":"Ông ấy bị ung thư giai đoạn cuối."},{"type":"simple","zh":"明朝末期，各地农民起义接连不断。","pinyin":"Míngcháo mòqī, gèdì nóngmín qǐyì jiēlián búduàn.","vi":"Cuối thời nhà Minh, khởi nghĩa nông dân các nơi liên tiếp nổ ra."},{"type":"compound","zh":"因为病人已经到了末期，所以医生建议以减轻痛苦为主。","pinyin":"Yīnwèi bìngrén yǐjīng dàole mòqī, suǒyǐ yīshēng jiànyì yǐ jiǎnqīng tòngkǔ wéizhǔ.","vi":"Vì bệnh nhân đã ở giai đoạn cuối nên bác sĩ đề nghị chủ yếu giảm nhẹ đau đớn."}],"related":[{"hanzi":"晚期","pinyin":"wǎnqī","vi":"giai đoạn cuối"},{"hanzi":"初期","pinyin":"chūqī","vi":"giai đoạn đầu"},{"hanzi":"中期","pinyin":"zhōngqī","vi":"giai đoạn giữa"}]},{"id":"末日","hanzi":"末日","pinyin":"mòrì","meaning_vi":"ngày tận thế, ngày tàn","explanation":"末 (cuối cùng/vụn nhỏ) + 日 (ngày).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"🌑","examples":[{"type":"basic","zh":"末日并没有来临。","pinyin":"Mòrì bìng méiyǒu láilín.","vi":"Ngày tận thế đã không hề đến."},{"type":"simple","zh":"这部科幻电影讲述了人类在末日之后重建家园的故事。","pinyin":"Zhè bù kēhuàn diànyǐng jiǎngshùle rénlèi zài mòrì zhīhòu chóngjiàn jiāyuán de gùshi.","vi":"Bộ phim khoa học viễn tưởng này kể câu chuyện loài người xây dựng lại quê hương sau ngày tận thế."},{"type":"compound","zh":"虽然网上流传着各种末日预言，但是没有一个成真。","pinyin":"Suīrán wǎngshàng liúchuánzhe gèzhǒng mòrì yùyán, dànshì méiyǒu yí gè chéngzhēn.","vi":"Tuy trên mạng lan truyền đủ loại lời tiên tri về ngày tận thế, nhưng chưa có cái nào thành sự thật."}],"related":[{"hanzi":"世界末日","pinyin":"shìjièmòrì","vi":"ngày tận thế"},{"hanzi":"灾难","pinyin":"zāinàn","vi":"thảm họa"},{"hanzi":"终结","pinyin":"zhōngjié","vi":"kết thúc"}]},{"id":"陌生人","hanzi":"陌生人","pinyin":"mòshēngrén","meaning_vi":"người lạ","explanation":"陌 (陌) + 生 (sinh tồn/sinh động) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"不要给陌生人开门。","pinyin":"Bú yào gěi mòshēngrén kāimén.","vi":"Đừng mở cửa cho người lạ."},{"type":"simple","zh":"一个陌生人在雨中把伞借给了我。","pinyin":"Yí gè mòshēngrén zài yǔ zhōng bǎ sǎn jiègěile wǒ.","vi":"Một người lạ đã cho tôi mượn ô trong mưa."},{"type":"compound","zh":"如果陌生人在网上向你借钱，你一定要提高警惕。","pinyin":"Rúguǒ mòshēngrén zài wǎngshàng xiàng nǐ jièqián, nǐ yídìngyào tígāo jǐngtì.","vi":"Nếu người lạ hỏi vay tiền bạn trên mạng, bạn nhất định phải nâng cao cảnh giác."}],"related":[{"hanzi":"陌生","pinyin":"mòshēng","vi":"xa lạ"},{"hanzi":"熟人","pinyin":"shúrén","vi":"người quen"},{"hanzi":"路人","pinyin":"lùrén","vi":"người qua đường"}]},{"id":"默许","hanzi":"默许","pinyin":"mòxǔ","meaning_vi":"ngầm đồng ý","explanation":"默 (âm thầm/im lặng) + 许 (cho phép/hứa hẹn).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤫","examples":[{"type":"basic","zh":"老板默许了这件事。","pinyin":"Lǎobǎn mòxǔle zhè jiàn shì.","vi":"Ông chủ đã ngầm đồng ý việc này."},{"type":"simple","zh":"父亲没有反对，算是默许了她去外地工作。","pinyin":"Fùqīn méiyǒu fǎnduì, suànshì mòxǔle tā qù wàidì gōngzuò.","vi":"Bố không phản đối, coi như đã ngầm đồng ý cho cô đi làm ở nơi khác."},{"type":"compound","zh":"如果管理者对违规行为一再默许，问题就会越来越严重。","pinyin":"Rúguǒ guǎnlǐ zhě duì wéiguī xíngwéi yízài mòxǔ, wèntí jiù huì yuèláiyuè yánzhòng.","vi":"Nếu người quản lý cứ ngầm dung túng hành vi vi phạm, vấn đề sẽ ngày càng nghiêm trọng."}],"related":[{"hanzi":"默认","pinyin":"mòrèn","vi":"mặc nhận"},{"hanzi":"同意","pinyin":"tóngyì","vi":"đồng ý"},{"hanzi":"允许","pinyin":"yǔnxǔ","vi":"cho phép"}],"traditional":"默許"},{"id":"模仿力","hanzi":"模仿力","pinyin":"mófǎnglì","meaning_vi":"khả năng bắt chước mô phỏng","explanation":"模 (mô hình/gương mẫu) + 仿 (仿) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🦜","examples":[{"type":"basic","zh":"孩子的模仿力很强。","pinyin":"Háizi de mófǎnglì hěn qiáng.","vi":"Khả năng bắt chước của trẻ em rất mạnh."},{"type":"simple","zh":"这只八哥模仿力惊人，能学会主人说的好几句话。","pinyin":"Zhè zhī bāge mófǎnglì jīngrén, néng xuéhuì zhǔrén shuō de hǎojǐ jù huà.","vi":"Con sáo này có khả năng bắt chước đáng kinh ngạc, học được mấy câu chủ nói."},{"type":"compound","zh":"因为幼儿的模仿力特别强，所以父母要处处以身作则。","pinyin":"Yīnwèi yòu'ér de mófǎnglì tèbié qiáng, suǒyǐ fùmǔ yào chùchù yǐshēnzuòzé.","vi":"Vì khả năng bắt chước của trẻ nhỏ đặc biệt mạnh nên cha mẹ phải luôn làm gương."}],"related":[{"hanzi":"模仿","pinyin":"mófǎng","vi":"bắt chước"},{"hanzi":"创造力","pinyin":"chuàngzàolì","vi":"sức sáng tạo"},{"hanzi":"想象力","pinyin":"xiǎngxiànglì","vi":"sức tưởng tượng"}]},{"id":"模糊不清","hanzi":"模糊不清","pinyin":"móhubùqīng","meaning_vi":"mơ hồ không rõ ràng","explanation":"模 (mô hình/gương mẫu) + 糊 (mơ hồ/dán hồ) + 不 (không/bất) + 清 (trong sạch/rõ nét).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"照片模糊不清。","pinyin":"Zhàopiàn móhubùqīng.","vi":"Bức ảnh mờ nhòe không rõ."},{"type":"simple","zh":"监控录像里嫌疑人的脸模糊不清，很难辨认。","pinyin":"Jiānkòng lùxiàng lǐ xiányírén de liǎn móhubùqīng, hěn nán biànrèn.","vi":"Khuôn mặt nghi phạm trong video giám sát mờ nhòe, rất khó nhận dạng."},{"type":"compound","zh":"虽然合同条款模糊不清，但是他还是匆忙签了字。","pinyin":"Suīrán hétong tiáokuǎn móhubùqīng, dànshì tā háishì cōngmáng qiānle zì.","vi":"Tuy điều khoản hợp đồng mập mờ không rõ ràng, nhưng anh ấy vẫn vội vàng ký tên."}],"related":[{"hanzi":"模糊","pinyin":"móhu","vi":"mơ hồ"},{"hanzi":"清晰","pinyin":"qīngxī","vi":"rõ nét"},{"hanzi":"朦胧","pinyin":"ménglóng","vi":"mờ ảo"}]},{"id":"模棱两可","hanzi":"模棱两可","pinyin":"móléng-liǎngkě","meaning_vi":"nước đôi mập mờ không dứt khoát","explanation":"模 (mô hình/gương mẫu) + 棱 (góc cạnh/nước đôi) + 两 (hai (số lượng)) + 可 (可).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤔","examples":[{"type":"basic","zh":"他的回答模棱两可。","pinyin":"Tā de huídá móléngliǎngkě.","vi":"Câu trả lời của anh ấy nước đôi."},{"type":"simple","zh":"发言人对记者的提问只给出了模棱两可的答复。","pinyin":"Fāyánrén duì jìzhě de tíwèn zhǐ gěi chūle móléngliǎngkě de dáfù.","vi":"Người phát ngôn chỉ đưa ra câu trả lời nước đôi cho câu hỏi của phóng viên."},{"type":"compound","zh":"与其说一些模棱两可的话，不如直接告诉他你的决定。","pinyin":"Yǔqíshuō yìxiē móléngliǎngkě dehuà, bùrú zhíjiē gàosu tā nǐ de juédìng.","vi":"Thay vì nói những lời nước đôi, chi bằng nói thẳng cho anh ấy biết quyết định của bạn."}],"related":[{"hanzi":"含糊其辞","pinyin":"hánhuqící","vi":"nói lấp lửng"},{"hanzi":"似是而非","pinyin":"sìshì'érfēi","vi":"tưởng đúng mà sai"},{"hanzi":"明确","pinyin":"míngquè","vi":"rõ ràng"}],"traditional":"模棱兩可"},{"id":"魔力","hanzi":"魔力","pinyin":"mólì","meaning_vi":"ma lực, sức hấp dẫn kỳ diệu","explanation":"魔 (ma quỷ/ảo thuật) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"音乐有一种魔力。","pinyin":"Yīnyuè yǒu yì zhǒng mólì.","vi":"Âm nhạc có một ma lực."},{"type":"simple","zh":"这家小店的牛肉面仿佛有魔力，让人吃了还想再来。","pinyin":"Zhè jiā xiǎodiàn de niúròumiàn fǎngfú yǒu mólì, ràng rén chīle hái xiǎng zài lái.","vi":"Mì bò của tiệm nhỏ này như có ma lực, khiến người ta ăn rồi còn muốn quay lại."},{"type":"compound","zh":"她的笑容好像有魔力，一出现就让紧张的气氛缓和下来。","pinyin":"Tā de xiàoróng hǎoxiàng yǒu mólì, yì chūxiàn jiù ràng jǐnzhāng de qìfēn huǎnhé xiàlái.","vi":"Nụ cười của cô ấy như có ma lực, vừa xuất hiện đã khiến bầu không khí căng thẳng dịu lại."}],"related":[{"hanzi":"魅力","pinyin":"mèilì","vi":"sức quyến rũ"},{"hanzi":"魔术","pinyin":"móshù","vi":"ảo thuật"},{"hanzi":"吸引力","pinyin":"xīyǐnlì","vi":"sức hút"}]},{"id":"磨难","hanzi":"磨难","pinyin":"mónàn","meaning_vi":"gian nan thử thách","explanation":"磨 (mài giũa) + 难 (khó).","hsk_level":"7-9","tags":["danh-tu"],"image":"⛰️","examples":[{"type":"basic","zh":"他经历了许多磨难。","pinyin":"Tā jīnglìle xǔduō mónàn.","vi":"Ông ấy đã trải qua nhiều gian nan."},{"type":"simple","zh":"这位母亲在战乱中受尽磨难，却始终没有放弃孩子。","pinyin":"Zhè wèi mǔqīn zài zhànluàn zhōng shòujìn mónàn, què shǐzhōng méiyǒu fàngqì háizi.","vi":"Người mẹ này chịu đủ gian khổ trong chiến loạn, nhưng trước sau không bỏ rơi con."},{"type":"compound","zh":"虽然创业路上磨难重重，但是他从来没有想过放弃。","pinyin":"Suīrán chuàngyè lùshàng mónàn chóngchóng, dànshì tā cónglái méiyǒu xiǎngguò fàngqì.","vi":"Tuy con đường khởi nghiệp đầy rẫy gian nan, nhưng anh ấy chưa từng nghĩ đến chuyện bỏ cuộc."}],"related":[{"hanzi":"苦难","pinyin":"kǔnàn","vi":"khổ nạn"},{"hanzi":"挫折","pinyin":"cuòzhé","vi":"thất bại"},{"hanzi":"磨炼","pinyin":"móliàn","vi":"tôi luyện"}],"traditional":"磨難"},{"id":"谋划","hanzi":"谋划","pinyin":"móuhuà","meaning_vi":"mưu tính, hoạch định","explanation":"谋 (mưu cầu/âm mưu) + 划 (chèo (thuyền)).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"♟️","examples":[{"type":"basic","zh":"他们正在谋划新项目。","pinyin":"Tāmen zhèngzài móuhuà xīn xiàngmù.","vi":"Họ đang hoạch định dự án mới."},{"type":"simple","zh":"市政府提前谋划了明年的城市更新工程。","pinyin":"Shìzhèngfǔ tíqián móuhuàle míngnián de chéngshì gēngxīn gōngchéng.","vi":"Chính quyền thành phố đã hoạch định trước công trình chỉnh trang đô thị năm sau."},{"type":"compound","zh":"只有提前谋划、周密部署，大型活动才能顺利进行。","pinyin":"Zhǐyǒu tíqián móuhuà, zhōumì bùshǔ, dàxíng huódòng cáinéng shùnlì jìnxíng.","vi":"Chỉ khi hoạch định sớm và bố trí chu đáo, các sự kiện lớn mới diễn ra suôn sẻ."}],"related":[{"hanzi":"策划","pinyin":"cèhuà","vi":"lên kế hoạch"},{"hanzi":"规划","pinyin":"guīhuà","vi":"quy hoạch"},{"hanzi":"筹划","pinyin":"chóuhuà","vi":"trù tính"}],"traditional":"謀劃"},{"id":"谋生","hanzi":"谋生","pinyin":"móushēng","meaning_vi":"mưu sinh, kiếm sống","explanation":"谋 (mưu cầu/âm mưu) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他靠卖菜谋生。","pinyin":"Tā kào mài cài móushēng.","vi":"Ông ấy kiếm sống bằng nghề bán rau."},{"type":"simple","zh":"十六岁那年，他独自一人到广州谋生。","pinyin":"Shíliù suì nà nián, tā dúzì yìrén dào Guǎngzhōu móushēng.","vi":"Năm mười sáu tuổi, anh ấy một mình đến Quảng Châu mưu sinh."},{"type":"compound","zh":"虽然在外谋生很辛苦，但是他每个月都按时给家里寄钱。","pinyin":"Suīrán zài wài móushēng hěn xīnkǔ, dànshì tā měi gèyuè dōu ànshí gěi jiālǐ jì qián.","vi":"Tuy mưu sinh nơi xa rất vất vả, nhưng tháng nào anh ấy cũng gửi tiền về nhà đúng hạn."}],"related":[{"hanzi":"生计","pinyin":"shēngjì","vi":"sinh kế"},{"hanzi":"打工","pinyin":"dǎgōng","vi":"làm thuê"},{"hanzi":"养家糊口","pinyin":"yǎngjiāhúkǒu","vi":"nuôi sống gia đình"}],"traditional":"謀生"},{"id":"目标明确","hanzi":"目标明确","pinyin":"mùbiāomíngquè","meaning_vi":"mục tiêu rõ ràng","explanation":"目 (mục tiêu/ánh mắt) + 标 (tiêu chuẩn/biểu tượng) + 明 (sáng suốt/rõ ràng) + 确 (xác thực/đảm bảo).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🎯","examples":[{"type":"basic","zh":"她做事目标明确。","pinyin":"Tā zuòshì mùbiāomíngquè.","vi":"Cô ấy làm việc có mục tiêu rõ ràng."},{"type":"simple","zh":"这支球队目标明确，就是要拿下本赛季冠军。","pinyin":"Zhè zhī qiúduì mùbiāomíngquè, jiùshì yào náxià běn sàijì guànjūn.","vi":"Đội bóng này có mục tiêu rõ ràng, đó là giành chức vô địch mùa giải này."},{"type":"compound","zh":"只要目标明确，每天进步一点点，就一定能考上理想的大学。","pinyin":"Zhǐyào mùbiāomíngquè, měitiān jìnbù yìdiǎndiǎn, jiù yídìng néng kǎoshàng lǐxiǎng de dàxué.","vi":"Chỉ cần mục tiêu rõ ràng, mỗi ngày tiến bộ một chút, nhất định sẽ đỗ vào trường đại học mơ ước."}],"related":[{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"明确","pinyin":"míngquè","vi":"rõ ràng"},{"hanzi":"有的放矢","pinyin":"yǒudìfàngshǐ","vi":"nhắm đúng mục tiêu"}],"traditional":"目標明確"},{"id":"目不暇接","hanzi":"目不暇接","pinyin":"mùbù-xiájiē","meaning_vi":"nhiều cảnh đẹp đến mức mắt nhìn không xuể","explanation":"目 (mục tiêu/ánh mắt) + 不 (không/bất) + 暇 (rảnh rỗi) + 接 (接).","hsk_level":"7-9","tags":["thanh-ngu","du-lich"],"image":"👀","examples":[{"type":"basic","zh":"展品让人目不暇接。","pinyin":"Zhǎnpǐn ràng rén mùbùxiájiē.","vi":"Hiện vật trưng bày nhiều đến mức nhìn không xuể."},{"type":"simple","zh":"夜市上各种小吃摊一字排开，让游客目不暇接。","pinyin":"Yèshì shàng gèzhǒng xiǎochī tān yízì pái kāi, ràng yóukè mùbùxiájiē.","vi":"Ở chợ đêm, các sạp đồ ăn vặt xếp thành hàng dài, khiến du khách nhìn không xuể."},{"type":"compound","zh":"一走进花卉博览会，五颜六色的鲜花就让我们目不暇接。","pinyin":"Yì zǒujìn huāhuì bólǎnhuì, wǔyánliùsè de xiānhuā jiù ràng wǒmen mùbùxiájiē.","vi":"Vừa bước vào hội chợ hoa, muôn sắc hoa tươi đã khiến chúng tôi ngắm không xuể."}],"related":[{"hanzi":"琳琅满目","pinyin":"línlángmǎnmù","vi":"đủ thứ đẹp mắt"},{"hanzi":"眼花缭乱","pinyin":"yǎnhuāliáoluàn","vi":"hoa cả mắt"},{"hanzi":"应接不暇","pinyin":"yìngjiēbùxiá","vi":"tiếp không xuể"}]},{"id":"目瞪口呆","hanzi":"目瞪口呆","pinyin":"mùdèng-kǒudāi","meaning_vi":"mắt trợn tròn miệng há hốc (kinh ngạc sững sờ)","explanation":"目 (mục – mắt) 瞪 (trừng – trợn) + 口 (khẩu – miệng) 呆 (ngây – đờ ra) → mắt trợn tròn, miệng đờ ra; tả vẻ kinh ngạc sững sờ.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😱","examples":[{"type":"basic","zh":"大家都目瞪口呆。","pinyin":"Dàjiā dōu mùdèngkǒudāi.","vi":"Mọi người đều trợn mắt há hốc mồm."},{"type":"simple","zh":"魔术师把一只鸽子变没了，观众看得目瞪口呆。","pinyin":"Móshùshī bǎ yì zhī gēzi biàn méile, guānzhòng kàn de mùdèngkǒudāi.","vi":"Ảo thuật gia làm biến mất một con bồ câu, khán giả xem mà sững sờ."},{"type":"compound","zh":"他一打开信封，就被里面的中奖通知惊得目瞪口呆。","pinyin":"Tā yì dǎkāi xìnfēng, jiù bèi lǐmiàn de zhòngjiǎng tōngzhī jīng de mùdèngkǒudāi.","vi":"Anh ấy vừa mở phong bì đã sững sờ trước thông báo trúng thưởng bên trong."}],"related":[{"hanzi":"惊呆","pinyin":"jīngdāi","vi":"sững sờ"},{"hanzi":"瞠目结舌","pinyin":"chēngmùjiéshé","vi":"trố mắt cứng lưỡi"},{"hanzi":"惊讶","pinyin":"jīngyà","vi":"kinh ngạc"}]},{"id":"目击者","hanzi":"目击者","pinyin":"mùjīzhě","meaning_vi":"nhân chứng tận mắt chứng kiến","explanation":"目 (mục tiêu/ánh mắt) + 击 (击) + 者 (者).","hsk_level":"7-9","tags":["danh-tu","phap-luat","con-nguoi"],"image":"👁️","examples":[{"type":"basic","zh":"警察在寻找目击者。","pinyin":"Jǐngchá zài xúnzhǎo mùjīzhě.","vi":"Cảnh sát đang tìm nhân chứng."},{"type":"simple","zh":"一位目击者用手机拍下了肇事车辆的车牌。","pinyin":"Yí wèi mùjīzhě yòng shǒujī pāi xiàle zhàoshì chēliàng de chēpái.","vi":"Một nhân chứng đã dùng điện thoại chụp lại biển số xe gây tai nạn."},{"type":"compound","zh":"如果没有目击者出来作证，这个案子就很难破了。","pinyin":"Rúguǒ méiyǒu mùjīzhě chūlái zuòzhèng, zhè ge'àn zi jiù hěn nán pò le.","vi":"Nếu không có nhân chứng ra làm chứng, vụ án này sẽ rất khó phá."}],"related":[{"hanzi":"证人","pinyin":"zhèngrén","vi":"nhân chứng"},{"hanzi":"目击","pinyin":"mùjī","vi":"chứng kiến"},{"hanzi":"旁观者","pinyin":"pángguānzhě","vi":"người ngoài cuộc"}],"traditional":"目擊者"},{"id":"暮年","hanzi":"暮年","pinyin":"mùnián","meaning_vi":"tuổi xế chiều, tuổi già","explanation":"暮 (chiều tà/tuổi già) + 年 (năm).","hsk_level":"7-9","tags":["danh-tu","thoi-gian","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"他已到了暮年。","pinyin":"Tā yǐ dàole mùnián.","vi":"Ông ấy đã đến tuổi xế chiều."},{"type":"simple","zh":"暮年的画家依然每天清晨坐在窗前作画。","pinyin":"Mùnián de huàjiā yīrán měitiān qīngchén zuò zài chuāng qián zuòhuà.","vi":"Người họa sĩ tuổi xế chiều vẫn mỗi sáng sớm ngồi bên cửa sổ vẽ tranh."},{"type":"compound","zh":"虽然已步入暮年，但是她仍然坚持去社区教孩子们唱歌。","pinyin":"Suīrán yǐ bùrù mùnián, dànshì tā réngrán jiānchí qù shèqū jiāo háizimen chànggē.","vi":"Tuy đã bước vào tuổi già, nhưng bà vẫn kiên trì đến khu dân cư dạy bọn trẻ hát."}],"related":[{"hanzi":"晚年","pinyin":"wǎnnián","vi":"tuổi già"},{"hanzi":"老年","pinyin":"lǎonián","vi":"tuổi già"},{"hanzi":"青春","pinyin":"qīngchūn","vi":"tuổi xuân"}]},{"id":"美感","hanzi":"美感","pinyin":"měigǎn","meaning_vi":"cảm giác thẩm mỹ, vẻ đẹp","explanation":"美 (tươi đẹp/mỹ mãn) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"这幅画很有美感。","pinyin":"Zhè fú huà hěn yǒu měigǎn.","vi":"Bức tranh này rất có tính thẩm mỹ."},{"type":"simple","zh":"这座木桥的弧线设计充满了东方的美感。","pinyin":"Zhè zuò mù qiáo de húxiàn shèjì chōngmǎnle dōngfāng de měigǎn.","vi":"Thiết kế đường cong của cây cầu gỗ này tràn đầy vẻ đẹp phương Đông."},{"type":"compound","zh":"如果房间里堆满杂物，再贵的家具也没有美感。","pinyin":"Rúguǒ fángjiān lǐ duīmǎn záwù, zài guì de jiājù yě méiyǒu měigǎn.","vi":"Nếu trong phòng chất đầy đồ lặt vặt, đồ nội thất đắt đến mấy cũng chẳng có vẻ đẹp."}],"related":[{"hanzi":"美","pinyin":"měi","vi":"đẹp"},{"hanzi":"审美","pinyin":"shěnměi","vi":"thẩm mỹ"},{"hanzi":"美学","pinyin":"měixué","vi":"mỹ học"}]},{"id":"美化","hanzi":"美化","pinyin":"měihuà","meaning_vi":"làm đẹp, mỹ hóa","explanation":"美 (tươi đẹp/mỹ mãn) + 化 (化).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌸","examples":[{"type":"basic","zh":"我们要美化校园。","pinyin":"Wǒmen yào měihuà xiàoyuán.","vi":"Chúng ta cần làm đẹp khuôn viên trường."},{"type":"simple","zh":"居民们在墙上画了彩色壁画，美化了老旧的小巷。","pinyin":"Jūmínmen zài qiáng shàng huàle cǎisè bìhuà, měihuàle lǎojiù de xiǎoxiàng.","vi":"Cư dân vẽ tranh tường nhiều màu sắc, làm đẹp con hẻm cũ kỹ."},{"type":"compound","zh":"虽然广告把产品美化得很完美，但是实物差了很多。","pinyin":"Suīrán guǎnggào bǎ chǎnpǐn měihuà de hěn wánměi, dànshì shíwù chàle hěn duō.","vi":"Tuy quảng cáo tô vẽ sản phẩm rất hoàn hảo, nhưng hàng thật kém xa."}],"related":[{"hanzi":"美化环境","pinyin":"měihuàhuánjìng","vi":"làm đẹp môi trường"},{"hanzi":"装饰","pinyin":"zhuāngshì","vi":"trang trí"},{"hanzi":"丑化","pinyin":"chǒuhuà","vi":"bôi xấu"}]},{"id":"美术馆","hanzi":"美术馆","pinyin":"měishùguǎn","meaning_vi":"bảo tàng mỹ thuật","explanation":"美 (tươi đẹp/mỹ mãn) + 术 (术) + 馆 (馆).","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-diem"],"image":"🖼️","examples":[{"type":"basic","zh":"周末我去了美术馆。","pinyin":"Zhōumò wǒqùle měishùguǎn.","vi":"Cuối tuần tôi đã đến bảo tàng mỹ thuật."},{"type":"simple","zh":"美术馆正在展出一批印象派画家的油画。","pinyin":"Měishùguǎn zhèngzài zhǎnchū yìpī yìnxiàngpài huàjiā de yóuhuà.","vi":"Bảo tàng mỹ thuật đang trưng bày một loạt tranh sơn dầu của các họa sĩ trường phái Ấn tượng."},{"type":"compound","zh":"既然下雨不能爬山，我们不如去美术馆看看画展。","pinyin":"Jìrán xiàyǔ bù néng páshān, wǒmen bùrú qù měishùguǎn kànkan huàzhǎn.","vi":"Trời mưa không leo núi được, chúng ta chi bằng đến bảo tàng mỹ thuật xem triển lãm tranh."}],"related":[{"hanzi":"博物馆","pinyin":"bówùguǎn","vi":"bảo tàng"},{"hanzi":"画展","pinyin":"huàzhǎn","vi":"triển lãm tranh"},{"hanzi":"美术","pinyin":"měishù","vi":"mỹ thuật"}],"traditional":"美術館"},{"id":"美誉","hanzi":"美誉","pinyin":"měiyù","meaning_vi":"danh tiếng tốt đẹp","explanation":"美 (tươi đẹp/mỹ mãn) + 誉 (danh dự/ca ngợi).","hsk_level":"7-9","tags":["danh-tu"],"image":"🏅","examples":[{"type":"basic","zh":"杭州有人间天堂的美誉。","pinyin":"Hángzhōu yǒu rénjiān tiāntáng de měiyù.","vi":"Hàng Châu có mỹ danh là thiên đường nơi trần thế."},{"type":"simple","zh":"这家小餐馆凭着地道的家乡菜赢得了“第二个家”的美誉。","pinyin":"Zhè jiā xiǎo cānguǎn píngzhe dìdao de jiāxiāngcài yíng déle \"dì'èr gè jiā\" de měiyù.","vi":"Quán ăn nhỏ này nhờ món ăn quê hương chuẩn vị mà được mệnh danh là \"ngôi nhà thứ hai\"."},{"type":"compound","zh":"因为瓷器精美，所以景德镇自古就有“瓷都”的美誉。","pinyin":"Yīnwèi cíqì jīngměi, suǒyǐ Jǐngdézhèn zìgǔ jiù yǒu \"cí dū\" de měiyù.","vi":"Vì đồ sứ tinh xảo nên Cảnh Đức Trấn từ xưa đã có mỹ danh \"kinh đô đồ sứ\"."}],"related":[{"hanzi":"声誉","pinyin":"shēngyù","vi":"danh tiếng"},{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"美名","pinyin":"měimíng","vi":"tiếng tốt"}],"traditional":"美譽"},{"id":"猛增","hanzi":"猛增","pinyin":"měngzēng","meaning_vi":"tăng vọt mạnh mẽ","explanation":"猛 (mãnh liệt) + 增 (tăng thêm).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"游客人数猛增。","pinyin":"Yóukè rénshù měngzēng.","vi":"Số lượng du khách tăng vọt."},{"type":"simple","zh":"高温天气使空调的销量在一周内猛增了三倍。","pinyin":"Gāowēn tiānqì shǐ kōngtiáo de xiāoliàng zài yìzhōu nèi měngzēngle sānbèi.","vi":"Thời tiết nắng nóng khiến doanh số điều hòa tăng vọt gấp ba trong vòng một tuần."},{"type":"compound","zh":"视频一上传到网上，点击量就猛增到了上百万。","pinyin":"Shìpín yí shàngchuán dào wǎngshàng, diǎnjī liàng jiù měngzēng dàole shàng bǎiwàn.","vi":"Video vừa đăng lên mạng, lượt xem đã tăng vọt lên hàng triệu."}],"related":[{"hanzi":"激增","pinyin":"jīzēng","vi":"tăng vọt"},{"hanzi":"剧增","pinyin":"jùzēng","vi":"tăng mạnh"},{"hanzi":"骤减","pinyin":"zhòujiǎn","vi":"giảm đột ngột"}]},{"id":"摸清","hanzi":"摸清","pinyin":"mōqīng","meaning_vi":"nắm rõ tình hình","explanation":"摸 (sờ) + 清 (trong sạch/rõ nét).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"先摸清情况再说。","pinyin":"Xiān mōqīng qíngkuàng zàishuō.","vi":"Nắm rõ tình hình trước rồi hãy tính."},{"type":"simple","zh":"调查组花了一个月摸清了这个村的土地使用情况。","pinyin":"Diàochá zǔ huāle yí gèyuè mōqīngle zhè ge cūn de tǔdì shǐyòng qíngkuàng.","vi":"Tổ điều tra mất một tháng để nắm rõ tình hình sử dụng đất của làng này."},{"type":"compound","zh":"只有摸清了顾客的真实需求，我们才能设计出好产品。","pinyin":"Zhǐyǒu mōqīngle gùkè de zhēnshí xūqiú, wǒmen cáinéng shèjì chū hǎo chǎnpǐn.","vi":"Chỉ khi nắm rõ nhu cầu thực sự của khách hàng, chúng ta mới thiết kế được sản phẩm tốt."}],"related":[{"hanzi":"摸底","pinyin":"mōdǐ","vi":"nắm tình hình"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"tìm hiểu"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"}]},{"id":"满腔热情","hanzi":"满腔热情","pinyin":"mǎnqiāng-rèqíng","meaning_vi":"tràn đầy nhiệt huyết","explanation":"满 (đầy đủ/thỏa mãn) + 腔 (腔) + 热 (nóng) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"她满腔热情地工作。","pinyin":"Tā mǎnqiāngrèqíng de gōngzuò.","vi":"Cô ấy làm việc với đầy nhiệt huyết."},{"type":"simple","zh":"新来的志愿者满腔热情地帮老人搬家。","pinyin":"Xīn lái de zhìyuànzhě mǎnqiāngrèqíng de bāng lǎorén bānjiā.","vi":"Các tình nguyện viên mới đến tràn đầy nhiệt huyết giúp các cụ già chuyển nhà."},{"type":"compound","zh":"他虽然满腔热情，但是缺乏实际经验。","pinyin":"Tā suīrán mǎnqiāngrèqíng, dànshì quēfá shíjì jīngyàn.","vi":"Tuy anh ấy tràn đầy nhiệt huyết nhưng lại thiếu kinh nghiệm thực tế."}],"related":[{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"热忱","pinyin":"rèchén","vi":"nhiệt thành"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"thờ ơ"}],"traditional":"滿腔熱情"},{"id":"满载","hanzi":"满载","pinyin":"mǎnzài","meaning_vi":"chở đầy ắp","explanation":"满 (đầy đủ/thỏa mãn) + 载 (ghi chép/chuyên chở).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚢","examples":[{"type":"basic","zh":"货车满载而归。","pinyin":"Huòchē mǎnzài'érguī.","vi":"Xe tải chở đầy hàng trở về."},{"type":"simple","zh":"这艘满载集装箱的货轮今早驶出了港口。","pinyin":"Zhè sōu mǎnzài jízhuāngxiāng de huòlún jīnzǎo shǐchūle gǎngkǒu.","vi":"Con tàu chở đầy container này đã rời cảng sáng nay."},{"type":"compound","zh":"渔船一靠岸，满载的鱼虾就被抢购一空。","pinyin":"Yúchuán yí kào'àn, mǎnzài de yúxiā jiù bèi qiǎnggòu yìkōng.","vi":"Thuyền đánh cá vừa cập bờ, cá tôm chở đầy thuyền đã bị mua sạch."}],"related":[{"hanzi":"满载而归","pinyin":"mǎnzài'érguī","vi":"thắng lợi trở về"},{"hanzi":"装载","pinyin":"zhuāngzài","vi":"chất hàng"},{"hanzi":"空载","pinyin":"kōngzài","vi":"chạy không tải"}],"traditional":"滿載"},{"id":"敏锐性","hanzi":"敏锐性","pinyin":"mǐnruìxìng","meaning_vi":"sự nhạy bén","explanation":"敏 (nhạy bén/nhanh nhẹn) + 锐 (nhạy bén/sắc bén) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🦅","examples":[{"type":"basic","zh":"记者需要政治敏锐性。","pinyin":"Jìzhě xūyào zhèngzhì mǐnruìxìng.","vi":"Phóng viên cần sự nhạy bén chính trị."},{"type":"simple","zh":"这位投资人对市场变化有极高的敏锐性。","pinyin":"Zhè wèi tóuzīrén duì shìchǎng biànhuà yǒu jí gāo de mǐnruìxìng.","vi":"Nhà đầu tư này có sự nhạy bén rất cao với biến động thị trường."},{"type":"compound","zh":"如果缺乏敏锐性，就很难发现数据里的异常。","pinyin":"Rúguǒ quēfá mǐnruìxìng, jiù hěn nán fāxiàn shùjù lǐ de yìcháng.","vi":"Nếu thiếu sự nhạy bén thì rất khó phát hiện điểm bất thường trong dữ liệu."}],"related":[{"hanzi":"敏锐","pinyin":"mǐnruì","vi":"nhạy bén"},{"hanzi":"洞察力","pinyin":"dòngchálì","vi":"khả năng thấu hiểu"},{"hanzi":"敏感","pinyin":"mǐngǎn","vi":"nhạy cảm"}],"traditional":"敏銳性"},{"id":"母校","hanzi":"母校","pinyin":"mǔxiào","meaning_vi":"trường cũ (nơi từng theo học)","explanation":"母 (mẹ/gốc) + 校 (校).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","dia-diem"],"image":"🏫","examples":[{"type":"basic","zh":"我回母校看老师。","pinyin":"Wǒ huí mǔxiào kàn lǎoshī.","vi":"Tôi về trường cũ thăm thầy cô."},{"type":"simple","zh":"毕业二十年后，他向母校捐赠了一座图书馆。","pinyin":"Bìyè èrshí nián hòu, tā xiàng mǔxiào juānzèngle yí zuò túshūguǎn.","vi":"Hai mươi năm sau khi tốt nghiệp, anh ấy đã tặng trường cũ một thư viện."},{"type":"compound","zh":"虽然母校已经搬了新址，但是我们仍然常回去聚会。","pinyin":"Suīrán mǔxiào yǐjīng bānle xīn zhǐ, dànshì wǒmen réngrán cháng huíqù jùhuì.","vi":"Tuy trường cũ đã chuyển đến địa điểm mới, nhưng chúng tôi vẫn thường quay về họp mặt."}],"related":[{"hanzi":"校友","pinyin":"xiàoyǒu","vi":"cựu học sinh"},{"hanzi":"学校","pinyin":"xuéxiào","vi":"trường học"},{"hanzi":"毕业","pinyin":"bìyè","vi":"tốt nghiệp"}]},{"id":"闹钟","hanzi":"闹钟","pinyin":"nàozhōng","meaning_vi":"đồng hồ báo thức","explanation":"闹 (闹) + 钟 (chuông/yêu thích).","hsk_level":"7-9","tags":["danh-tu","do-vat","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"闹钟响了三次。","pinyin":"Nàozhōng xiǎngle sāncì.","vi":"Đồng hồ báo thức đã reo ba lần."},{"type":"simple","zh":"我把闹钟定在早上六点半。","pinyin":"Wǒ bǎ nàozhōng dìng zài zǎoshang liù diǎn bàn.","vi":"Tôi đặt đồng hồ báo thức lúc sáu giờ rưỡi sáng."},{"type":"compound","zh":"闹钟一响，他就迅速关掉，又钻回了被窝。","pinyin":"Nàozhōng yì xiǎng, tā jiù xùnsù guāndiào, yòu zuān huíle bèi wō.","vi":"Đồng hồ báo thức vừa reo, anh ấy liền tắt ngay rồi lại chui vào chăn."}],"related":[{"hanzi":"手表","pinyin":"shǒubiǎo","vi":"đồng hồ đeo tay"},{"hanzi":"起床","pinyin":"qǐchuáng","vi":"thức dậy"},{"hanzi":"定时","pinyin":"dìngshí","vi":"hẹn giờ"}],"traditional":"鬧鐘"},{"id":"念头","hanzi":"念头","pinyin":"niàntou","meaning_vi":"ý nghĩ, ý định thoáng qua","explanation":"念 (đọc thành tiếng) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"我打消了这个念头。","pinyin":"Wǒ dǎxiāole zhè ge niàntou.","vi":"Tôi đã gạt bỏ ý nghĩ này."},{"type":"simple","zh":"看到招聘广告，她心里冒出了辞职的念头。","pinyin":"Kàndào zhāopìn guǎnggào, tā xīnlǐ mào chūle cízhí de niàntou.","vi":"Nhìn thấy quảng cáo tuyển dụng, trong lòng cô ấy nảy ra ý định nghỉ việc."},{"type":"compound","zh":"一旦有了放弃的念头，就很难再坚持下去。","pinyin":"Yídàn yǒule fàngqì de niàntou, jiù hěn nán zài jiānchí xiàqù.","vi":"Một khi đã có ý nghĩ bỏ cuộc thì rất khó kiên trì tiếp."}],"related":[{"hanzi":"想法","pinyin":"xiǎngfǎ","vi":"suy nghĩ"},{"hanzi":"主意","pinyin":"zhǔyi","vi":"ý kiến"},{"hanzi":"打消念头","pinyin":"dǎxiāoniàntou","vi":"từ bỏ ý định"}],"traditional":"念頭"},{"id":"年华","hanzi":"年华","pinyin":"niánhuá","meaning_vi":"năm tháng thanh xuân","explanation":"年 (năm) + 华 (hoa lệ/Trung Hoa).","hsk_level":"7-9","tags":["danh-tu","thoi-gian","van-hoa"],"image":"🌸","examples":[{"type":"basic","zh":"别虚度年华。","pinyin":"Bié xūdù niánhuá.","vi":"Đừng phí hoài năm tháng tuổi trẻ."},{"type":"simple","zh":"她把最美好的年华献给了山区的孩子们。","pinyin":"Tā bǎ zuì měihǎo de niánhuá xiàn gěile shānqū de háizimen.","vi":"Cô ấy đã dành những năm tháng đẹp nhất của tuổi trẻ cho trẻ em vùng núi."},{"type":"compound","zh":"与其在抱怨中浪费年华，不如去学一门手艺。","pinyin":"Yǔqí zài bàoyuàn zhōng làngfèi niánhuá, bùrú qù xué yì mén shǒuyì.","vi":"Thay vì lãng phí tuổi xuân trong than vãn, chi bằng đi học một nghề."}],"related":[{"hanzi":"青春","pinyin":"qīngchūn","vi":"tuổi xuân"},{"hanzi":"岁月","pinyin":"suìyuè","vi":"năm tháng"},{"hanzi":"似水年华","pinyin":"sìshuǐniánhuá","vi":"năm tháng như nước trôi"}],"traditional":"年華"},{"id":"年迈","hanzi":"年迈","pinyin":"niánmài","meaning_vi":"tuổi cao sức yếu","explanation":"年 (năm) + 迈 (bước (bước chân)).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"👴","examples":[{"type":"basic","zh":"他的父母都已年迈。","pinyin":"Tā de fùmǔ dōu yǐ niánmài.","vi":"Cha mẹ anh ấy đều đã tuổi cao sức yếu."},{"type":"simple","zh":"年迈的老奶奶每天坚持在公园里打太极拳。","pinyin":"Niánmài de lǎonǎinai měitiān jiānchí zài gōngyuán lǐ dǎ tàijíquán.","vi":"Bà cụ tuổi cao ngày nào cũng kiên trì tập thái cực quyền trong công viên."},{"type":"compound","zh":"因为母亲年迈多病，所以他辞去了外地的工作。","pinyin":"Yīnwèi mǔqīn niánmài duō bìng, suǒyǐ tā cíqùle wàidì de gōngzuò.","vi":"Vì mẹ tuổi cao lại hay đau ốm nên anh ấy đã bỏ công việc ở nơi xa."}],"related":[{"hanzi":"年老","pinyin":"niánlǎo","vi":"già cả"},{"hanzi":"衰老","pinyin":"shuāilǎo","vi":"già yếu"},{"hanzi":"年轻","pinyin":"niánqīng","vi":"trẻ"}],"traditional":"年邁"},{"id":"年轻化","hanzi":"年轻化","pinyin":"niánqīnghuà","meaning_vi":"trẻ hóa (đội ngũ)","explanation":"年 (năm) + 轻 (nhẹ) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🌱","examples":[{"type":"basic","zh":"管理层正在年轻化。","pinyin":"Guǎnlǐ céng zhèngzài niánqīnghuà.","vi":"Tầng lớp quản lý đang được trẻ hóa."},{"type":"simple","zh":"这家老字号通过年轻化的包装吸引了大学生。","pinyin":"Zhè jiālǎo zìhào tōngguò niánqīnghuà de bāozhuāng xīyǐnle dàxuéshēng.","vi":"Thương hiệu lâu đời này đã thu hút sinh viên nhờ bao bì được trẻ hóa."},{"type":"compound","zh":"糖尿病患者不但越来越多，而且呈现年轻化趋势。","pinyin":"Tángniàobìng huànzhě búdàn yuèláiyuè duō, érqiě chéngxiàn niánqīnghuà qūshì.","vi":"Bệnh nhân tiểu đường không những ngày càng nhiều mà còn có xu hướng trẻ hóa."}],"related":[{"hanzi":"年轻","pinyin":"niánqīng","vi":"trẻ"},{"hanzi":"老龄化","pinyin":"lǎolínghuà","vi":"già hóa"},{"hanzi":"新生代","pinyin":"xīnshēngdài","vi":"thế hệ mới"}],"traditional":"年輕化"},{"id":"年终奖","hanzi":"年终奖","pinyin":"niánzhōngjiǎng","meaning_vi":"thưởng cuối năm, thưởng Tết","explanation":"年终 (cuối năm) + 奖 (thưởng).","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"🧧","examples":[{"type":"basic","zh":"年终奖发下来了。","pinyin":"Niánzhōngjiǎng fā xiàlái le.","vi":"Thưởng cuối năm đã được phát rồi."},{"type":"simple","zh":"今年公司给每位员工发了三个月工资的年终奖。","pinyin":"Jīnnián gōngsī gěi měi wèi yuángōng fāle sān gèyuè gōngzī de niánzhōngjiǎng.","vi":"Năm nay công ty phát thưởng cuối năm bằng ba tháng lương cho mỗi nhân viên."},{"type":"compound","zh":"只要完成全年业绩目标，年终奖就会翻倍。","pinyin":"Zhǐyào wánchéng quánnián yèjì mùbiāo, niánzhōngjiǎng jiù huì fānbèi.","vi":"Chỉ cần hoàn thành mục tiêu doanh số cả năm, thưởng cuối năm sẽ tăng gấp đôi."}],"related":[{"hanzi":"奖金","pinyin":"jiǎngjīn","vi":"tiền thưởng"},{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"年底","pinyin":"niándǐ","vi":"cuối năm"}],"traditional":"年終獎"},{"id":"暖流","hanzi":"暖流","pinyin":"nuǎnliú","meaning_vi":"dòng hải lưu ấm; dòng cảm xúc ấm áp","explanation":"暖 (暖) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","cam-xuc"],"image":"☀️","examples":[{"type":"basic","zh":"我心中涌起一股暖流。","pinyin":"Wǒ xīnzhōng yǒngqǐ yì gǔ nuǎnliú.","vi":"Trong lòng tôi dâng lên một dòng cảm xúc ấm áp."},{"type":"simple","zh":"北大西洋暖流让西欧的冬天比较温和。","pinyin":"Běidàxīyáng nuǎnliú ràng Xī'ōu de dōngtiān bǐjiào wēnhé.","vi":"Hải lưu ấm Bắc Đại Tây Dương khiến mùa đông ở Tây Âu khá ôn hòa."},{"type":"compound","zh":"看到陌生人送来的热汤，她既感动，又觉得一股暖流传遍全身。","pinyin":"Kàndào mòshēngrén sòng lái de rè tāng, tā jì gǎndòng, yòu juéde yì gǔ nuǎnliú chuánbiàn quánshēn.","vi":"Nhìn thấy bát canh nóng người lạ mang đến, cô ấy vừa cảm động, vừa thấy một dòng ấm áp lan khắp người."}],"related":[{"hanzi":"寒流","pinyin":"hánliú","vi":"dòng hải lưu lạnh"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"洋流","pinyin":"yángliú","vi":"hải lưu"}]},{"id":"纳入","hanzi":"纳入","pinyin":"nàrù","meaning_vi":"đưa vào, thu nạp vào (kế hoạch/hệ thống)","explanation":"纳 (tiếp thu/chứa đựng) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📥","examples":[{"type":"basic","zh":"此事已纳入议程。","pinyin":"Cǐshì yǐ nàrù yìchéng.","vi":"Việc này đã được đưa vào chương trình nghị sự."},{"type":"simple","zh":"这种新药明年将被纳入医保报销范围。","pinyin":"Zhè zhǒng xīn yào míngnián jiāng bèi nàrù yībǎo bàoxiāo fànwéi.","vi":"Loại thuốc mới này năm sau sẽ được đưa vào danh mục bảo hiểm y tế chi trả."},{"type":"compound","zh":"如果把员工满意度纳入考核，管理者就会更重视沟通。","pinyin":"Rúguǒ bǎ yuángōng mǎnyìdù nàrù kǎohé, guǎnlǐ zhě jiù huì gèng zhòngshì gōutōng.","vi":"Nếu đưa mức độ hài lòng của nhân viên vào đánh giá, người quản lý sẽ chú trọng giao tiếp hơn."}],"related":[{"hanzi":"列入","pinyin":"lièrù","vi":"đưa vào danh sách"},{"hanzi":"归入","pinyin":"guīrù","vi":"xếp vào"},{"hanzi":"包括","pinyin":"bāokuò","vi":"bao gồm"}],"traditional":"納入"},{"id":"纳税","hanzi":"纳税","pinyin":"nàshuì","meaning_vi":"nộp thuế","explanation":"纳 (tiếp thu/chứa đựng) + 税 (thuế).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"依法纳税是义务。","pinyin":"Yīfǎ nàshuì shì yìwù.","vi":"Nộp thuế theo pháp luật là nghĩa vụ."},{"type":"simple","zh":"这家小餐馆每个季度都按时向税务局纳税。","pinyin":"Zhè jiā xiǎo cānguǎn měi gè jìdù dōu ànshí xiàng Shuìwùjú nàshuì.","vi":"Nhà hàng nhỏ này mỗi quý đều nộp thuế đúng hạn cho cơ quan thuế."},{"type":"compound","zh":"虽然收入不高，但是他从来没有逃避过纳税。","pinyin":"Suīrán shōurù bù gāo, dànshì tā cónglái méiyǒu táobìguo nàshuì.","vi":"Tuy thu nhập không cao nhưng anh ấy chưa bao giờ trốn tránh nộp thuế."}],"related":[{"hanzi":"缴税","pinyin":"jiǎoshuì","vi":"đóng thuế"},{"hanzi":"税收","pinyin":"shuìshōu","vi":"thu thuế"},{"hanzi":"逃税","pinyin":"táoshuì","vi":"trốn thuế"}],"traditional":"納稅"},{"id":"纳税人","hanzi":"纳税人","pinyin":"nàshuìrén","meaning_vi":"người nộp thuế","explanation":"纳税 (đóng thuế) + 人.","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"🧾","examples":[{"type":"basic","zh":"纳税人有知情权。","pinyin":"Nàshuìrén yǒu zhīqíngquán.","vi":"Người nộp thuế có quyền được biết thông tin."},{"type":"simple","zh":"政府的每一分钱都来自纳税人的辛苦劳动。","pinyin":"Zhèngfǔ de měi yì fēnqián dōu láizì nàshuìrén de xīnkǔ láodòng.","vi":"Từng đồng của chính phủ đều đến từ sức lao động vất vả của người nộp thuế."},{"type":"compound","zh":"既然花的是纳税人的钱，就应该公开每一笔开支。","pinyin":"Jìrán huā de shì nàshuìrén de qián, jiù yīnggāi gōngkāi měi yì bǐ kāizhī.","vi":"Đã tiêu tiền của người nộp thuế thì phải công khai từng khoản chi."}],"related":[{"hanzi":"纳税","pinyin":"nàshuì","vi":"nộp thuế"},{"hanzi":"税务局","pinyin":"Shuìwùjú","vi":"cục thuế"},{"hanzi":"公民","pinyin":"gōngmín","vi":"công dân"}],"traditional":"納稅人"},{"id":"耐力","hanzi":"耐力","pinyin":"nàilì","meaning_vi":"sức bền, sự dẻo dai","explanation":"耐 (kiên nhẫn/bền bỉ) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏃","examples":[{"type":"basic","zh":"长跑很考验耐力。","pinyin":"Chángpǎo hěn kǎoyàn nàilì.","vi":"Chạy đường dài rất thử thách sức bền."},{"type":"simple","zh":"他每天游泳两千米来提高自己的耐力。","pinyin":"Tā měitiān yóuyǒng liǎng qiānmǐ lái tígāo zìjǐ de nàilì.","vi":"Mỗi ngày anh ấy bơi hai nghìn mét để nâng cao sức bền."},{"type":"compound","zh":"她的速度虽然不快，但是耐力惊人，最后反超了对手。","pinyin":"Tā de sùdù suīrán búkuài, dànshì nàilì jīngrén, zuìhòu fǎnchāole duìshǒu.","vi":"Tốc độ của cô ấy tuy không nhanh nhưng sức bền đáng kinh ngạc, cuối cùng đã vượt qua đối thủ."}],"related":[{"hanzi":"毅力","pinyin":"yìlì","vi":"nghị lực"},{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"耐心","pinyin":"nàixīn","vi":"kiên nhẫn"}]},{"id":"耐用性","hanzi":"耐用性","pinyin":"nàiyòngxìng","meaning_vi":"độ bền","explanation":"耐 (kiên nhẫn/bền bỉ) + 用 (vận dụng/công dụng) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"💪","examples":[{"type":"basic","zh":"这款背包耐用性强。","pinyin":"Zhè kuǎn bēibāo nàiyòngxìng qiáng.","vi":"Chiếc ba lô này có độ bền cao."},{"type":"simple","zh":"消费者买家具时往往最看重它的耐用性。","pinyin":"Xiāofèizhě mǎi jiājù shí wǎngwǎng zuì kànzhòng tā de nàiyòngxìng.","vi":"Người tiêu dùng khi mua đồ nội thất thường coi trọng nhất là độ bền."},{"type":"compound","zh":"这双登山鞋不但价格实惠，而且耐用性极佳。","pinyin":"Zhè shuāng dēngshān xié búdàn jiàgé shíhuì, érqiě nàiyòngxìng jí jiā.","vi":"Đôi giày leo núi này không những giá cả phải chăng mà độ bền còn rất tốt."}],"related":[{"hanzi":"耐用","pinyin":"nàiyòng","vi":"bền"},{"hanzi":"质量","pinyin":"zhìliàng","vi":"chất lượng"},{"hanzi":"寿命","pinyin":"shòumìng","vi":"tuổi thọ"}]},{"id":"南半球","hanzi":"南半球","pinyin":"Nánbànqiú","meaning_vi":"bán cầu Nam","explanation":"南 (hướng Nam) + 半 (một nửa) + 球 (球).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"澳大利亚在南半球。","pinyin":"Àodàlìyà zài Nánbànqiú.","vi":"Úc nằm ở bán cầu Nam."},{"type":"simple","zh":"每年十二月，南半球正处于炎热的夏季。","pinyin":"Měinián Shí'èryuè, Nánbànqiú zhèng chǔyú yánrè de xiàjì.","vi":"Mỗi năm vào tháng mười hai, bán cầu Nam đang ở giữa mùa hè nóng bức."},{"type":"compound","zh":"因为位于南半球，所以阿根廷的季节和中国正好相反。","pinyin":"Yīnwèi wèiyú Nánbànqiú, suǒyǐ Āgēntíng de jìjié hé Zhōngguó zhènghǎo xiāngfǎn.","vi":"Vì nằm ở bán cầu Nam nên mùa ở Argentina hoàn toàn ngược với Trung Quốc."}],"related":[{"hanzi":"北半球","pinyin":"Běibànqiú","vi":"bán cầu Bắc"},{"hanzi":"赤道","pinyin":"Chìdào","vi":"xích đạo"},{"hanzi":"地球","pinyin":"dìqiú","vi":"trái đất"}]},{"id":"难关","hanzi":"难关","pinyin":"nánguān","meaning_vi":"cửa ải khó khăn","explanation":"难 (khó) + 关 (đóng).","hsk_level":"7-9","tags":["danh-tu"],"image":"🚧","examples":[{"type":"basic","zh":"我们一起渡过难关。","pinyin":"Wǒmen yìqǐ dùguò nánguān.","vi":"Chúng ta cùng nhau vượt qua cửa ải khó khăn."},{"type":"simple","zh":"疫情期间，邻居们互相帮助闯过了一道道难关。","pinyin":"Yìqíng qījiān, línjūmen hùxiāng bāngzhù chuǎngguòle yídào dào nánguān.","vi":"Trong thời gian dịch bệnh, hàng xóm giúp đỡ nhau vượt qua hết cửa ải khó khăn này đến cửa ải khác."},{"type":"compound","zh":"只要大家团结一心，再大的难关也能攻克。","pinyin":"Zhǐyào dàjiā tuánjié yìxīn, zài dà de nánguān yě néng gōngkè.","vi":"Chỉ cần mọi người đồng lòng thì khó khăn lớn đến đâu cũng có thể vượt qua."}],"related":[{"hanzi":"难题","pinyin":"nántí","vi":"vấn đề khó"},{"hanzi":"渡过难关","pinyin":"dùguònánguān","vi":"vượt qua khó khăn"},{"hanzi":"关口","pinyin":"guānkǒu","vi":"cửa ải"}],"traditional":"難關"},{"id":"难忘","hanzi":"难忘","pinyin":"nánwàng","meaning_vi":"khó quên","explanation":"难 (khó) + 忘 (quên).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"那次旅行令人难忘。","pinyin":"Nà cì lǚxíng lìngrén nánwàng.","vi":"Chuyến du lịch đó thật khó quên."},{"type":"simple","zh":"外婆包的饺子是我童年最难忘的味道。","pinyin":"Wàipó bāo de jiǎozi shì wǒ tóngnián zuì nánwàng de wèidào.","vi":"Món sủi cảo bà ngoại gói là hương vị khó quên nhất thời thơ ấu của tôi."},{"type":"compound","zh":"虽然比赛输了，但是那段一起训练的日子让我难忘。","pinyin":"Suīrán bǐsài shū le, dànshì nà duàn yìqǐ xùnliàn de rìzi ràng wǒ nánwàng.","vi":"Tuy thua trận nhưng những ngày cùng nhau luyện tập ấy khiến tôi khó quên."}],"related":[{"hanzi":"难以忘怀","pinyin":"nányǐwànghuái","vi":"khó lòng quên"},{"hanzi":"铭记","pinyin":"míngjì","vi":"khắc ghi"},{"hanzi":"回忆","pinyin":"huíyì","vi":"hồi ức"}],"traditional":"難忘"},{"id":"内涵丰富","hanzi":"内涵丰富","pinyin":"nèihánfēngfù","meaning_vi":"nội hàm phong phú sâu sắc","explanation":"内 (nội bộ/nội tại) + 涵 (涵) + 丰 (phong phú/bội thu) + 富 (giàu).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"📚","examples":[{"type":"basic","zh":"这首诗内涵丰富。","pinyin":"Zhè shǒu shī nèihánfēngfù.","vi":"Bài thơ này có nội hàm phong phú."},{"type":"simple","zh":"故宫的每一处建筑都内涵丰富，值得细细品读。","pinyin":"Gùgōng de měi yí chù jiànzhù dōu nèihánfēngfù, zhíde xìxì pǐndú.","vi":"Mỗi công trình trong Cố Cung đều có nội hàm phong phú, đáng để thưởng thức kỹ."},{"type":"compound","zh":"这部电影不但画面精美，而且内涵丰富。","pinyin":"Zhè bù diànyǐng búdàn huàmiàn jīngměi, érqiě nèihánfēngfù.","vi":"Bộ phim này không những hình ảnh đẹp mà nội hàm còn phong phú."}],"related":[{"hanzi":"内涵","pinyin":"nèihán","vi":"nội hàm"},{"hanzi":"丰富","pinyin":"fēngfù","vi":"phong phú"},{"hanzi":"空洞","pinyin":"kōngdòng","vi":"trống rỗng"}],"traditional":"內涵豐富"},{"id":"内行","hanzi":"内行","pinyin":"nèiháng","meaning_vi":"người trong nghề, chuyên gia sành sỏi","explanation":"内 (nội bộ/nội tại) + 行 (được).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","cong-viec"],"image":"🧑‍💼","examples":[{"type":"basic","zh":"他是修车的内行。","pinyin":"Tā shì xiūchē de nèiháng.","vi":"Anh ấy là người sành nghề sửa xe."},{"type":"simple","zh":"内行一眼就能看出这块玉是不是真的。","pinyin":"Nèiháng yìyǎn jiù néng kànchū zhè kuài yù shìbushì zhēn de.","vi":"Người trong nghề nhìn một cái là biết miếng ngọc này có thật hay không."},{"type":"compound","zh":"你如果不是内行，就别对装修指手画脚。","pinyin":"Nǐ rúguǒ bú shì nèiháng, jiù bié duì zhuāngxiū zhǐshǒuhuàjiǎo.","vi":"Nếu anh không phải người trong nghề thì đừng chỉ trỏ chuyện sửa nhà."}],"related":[{"hanzi":"外行","pinyin":"wàiháng","vi":"người ngoài nghề"},{"hanzi":"行家","pinyin":"hángjia","vi":"người sành"},{"hanzi":"专家","pinyin":"zhuānjiā","vi":"chuyên gia"}],"traditional":"內行"},{"id":"内卷","hanzi":"内卷","pinyin":"nèijuǎn","meaning_vi":"cạnh tranh khốc liệt nội bộ (từ nóng xã hội)","explanation":"内 (nội – bên trong) + 卷 (quyển – cuộn vào) → cuộn vào trong; từ nóng chỉ cạnh tranh nội bộ quá mức, tốn sức mà không thêm giá trị. Trái lại: 躺平.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌀","examples":[{"type":"basic","zh":"这个行业太内卷了。","pinyin":"Zhè ge hángyè tài nèijuǎn le.","vi":"Ngành này cạnh tranh nội bộ quá khốc liệt."},{"type":"simple","zh":"年轻人开始反思职场上无休止的内卷。","pinyin":"Niánqīngrén kāishǐ fǎnsī zhíchǎng shàng wúxiūzhǐ de nèijuǎn.","vi":"Người trẻ bắt đầu suy ngẫm lại sự cạnh tranh khốc liệt không hồi kết nơi công sở."},{"type":"compound","zh":"一旦家长都给孩子报补习班，内卷就会越来越严重。","pinyin":"Yídàn jiāzhǎng dōu gěi háizi bào bǔxíbān, nèijuǎn jiù huì yuèláiyuè yánzhòng.","vi":"Một khi phụ huynh nào cũng cho con đi học thêm thì cạnh tranh sẽ ngày càng khốc liệt."}],"related":[{"hanzi":"躺平","pinyin":"tǎngpíng","vi":"buông xuôi"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"}],"traditional":"內卷"},{"id":"内陆","hanzi":"内陆","pinyin":"Nèilù","meaning_vi":"nội địa","explanation":"内 (nội bộ/nội tại) + 陆 (đất liền/lần lượt).","hsk_level":"7-9","tags":["danh-tu","dia-danh"],"image":"🗺️","examples":[{"type":"basic","zh":"新疆深居内陆。","pinyin":"Xīnjiāng shēn jū Nèilù.","vi":"Tân Cương nằm sâu trong nội địa."},{"type":"simple","zh":"内陆城市的冬天通常比沿海城市更干燥寒冷。","pinyin":"Nèilù chéngshì de dōngtiān tōngcháng bǐ yánhǎi chéngshì gèng gānzào hánlěng.","vi":"Mùa đông ở các thành phố nội địa thường khô và lạnh hơn thành phố ven biển."},{"type":"compound","zh":"因为远离海洋，所以内陆地区降水很少。","pinyin":"Yīnwèi yuǎnlí hǎiyáng, suǒyǐ Nèilù dìqū jiàngshuǐ hěn shǎo.","vi":"Vì xa biển nên vùng nội địa có lượng mưa rất ít."}],"related":[{"hanzi":"沿海","pinyin":"yánhǎi","vi":"ven biển"},{"hanzi":"内地","pinyin":"nèidì","vi":"nội địa"},{"hanzi":"腹地","pinyin":"fùdì","vi":"vùng nội địa"}],"traditional":"內陸"},{"id":"内外","hanzi":"内外","pinyin":"nèiwài","meaning_vi":"trong và ngoài","explanation":"内 (nội bộ/nội tại) + 外 (ngoài).","hsk_level":"7-9","tags":["danh-tu","phuong-huong"],"image":"🔄","examples":[{"type":"basic","zh":"屋子内外都很干净。","pinyin":"Wūzi nèiwài dōu hěn gānjìng.","vi":"Trong ngoài căn nhà đều rất sạch sẽ."},{"type":"simple","zh":"春节前，奶奶把院子内外打扫得一尘不染。","pinyin":"Chūnjié qián, nǎinai bǎ yuànzi nèiwài dǎsǎo de yì chén bù rǎn.","vi":"Trước Tết, bà quét dọn trong ngoài sân sạch không một hạt bụi."},{"type":"compound","zh":"这家公司既要应对内外压力，又要保持员工稳定。","pinyin":"Zhè jiā gōngsī jì yào yìngduì nèiwài yālì, yòu yào bǎochí yuángōng wěndìng.","vi":"Công ty này vừa phải đối phó áp lực trong và ngoài, vừa phải giữ ổn định nhân sự."}],"related":[{"hanzi":"内部","pinyin":"nèibù","vi":"bên trong"},{"hanzi":"外部","pinyin":"wàibù","vi":"bên ngoài"},{"hanzi":"海内外","pinyin":"Hǎinèiwài","vi":"trong và ngoài nước"}],"traditional":"內外"},{"id":"内需","hanzi":"内需","pinyin":"nèixū","meaning_vi":"nhu cầu nội địa","explanation":"内 (nội bộ/nội tại) + 需 (nhu cầu/cần thiết).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"🛒","examples":[{"type":"basic","zh":"政府鼓励扩大内需。","pinyin":"Zhèngfǔ gǔlì kuòdà nèixū.","vi":"Chính phủ khuyến khích mở rộng nhu cầu nội địa."},{"type":"simple","zh":"发放消费券是这座城市拉动内需的新办法。","pinyin":"Fāfàng xiāofèiquàn shì zhè zuò chéngshì lādòng nèixū de xīn bànfǎ.","vi":"Phát phiếu tiêu dùng là cách mới của thành phố này để kích thích nhu cầu nội địa."},{"type":"compound","zh":"外贸出口一旦明显下滑，经济增长就更依赖内需。","pinyin":"Wàimào chūkǒu yídàn míngxiǎn xiàhuá, jīngjì zēngzhǎng jiù gèng yīlài nèixū.","vi":"Một khi xuất khẩu ngoại thương sụt giảm rõ rệt, tăng trưởng kinh tế sẽ càng dựa vào nhu cầu nội địa."}],"related":[{"hanzi":"外需","pinyin":"wàixū","vi":"nhu cầu bên ngoài"},{"hanzi":"消费","pinyin":"xiāofèi","vi":"tiêu dùng"},{"hanzi":"扩大内需","pinyin":"kuòdànèixū","vi":"mở rộng nhu cầu nội địa"}],"traditional":"內需"},{"id":"能源危机","hanzi":"能源危机","pinyin":"néngyuánwēijī","meaning_vi":"khủng hoảng năng lượng","explanation":"能 (có thể (năng lực/điều kiện)) + 源 (nguồn gốc) + 危 (khủng hoảng/nguy cơ) + 机 (cơ hội/máy móc).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","xa-hoi"],"image":"🔋","examples":[{"type":"basic","zh":"能源危机爆发了。","pinyin":"Néngyuánwēijī bàofā le.","vi":"Khủng hoảng năng lượng đã bùng nổ."},{"type":"simple","zh":"七十年代的能源危机让油价在短期内暴涨数倍。","pinyin":"Qīshí niándài de néngyuánwēijī ràng yóujià zài duǎnqī nèi bàozhǎng shù bèi.","vi":"Khủng hoảng năng lượng những năm bảy mươi khiến giá dầu tăng vọt gấp nhiều lần trong thời gian ngắn."},{"type":"compound","zh":"如果不发展可再生能源，能源危机迟早会到来。","pinyin":"Rúguǒ bù fāzhǎn kězàishēngnéngyuán, néngyuánwēijī chízǎo huì dàolái.","vi":"Nếu không phát triển năng lượng tái tạo thì sớm muộn khủng hoảng năng lượng cũng sẽ đến."}],"related":[{"hanzi":"能源","pinyin":"néngyuán","vi":"năng lượng"},{"hanzi":"石油","pinyin":"shíyóu","vi":"dầu mỏ"},{"hanzi":"新能源","pinyin":"xīnnéngyuán","vi":"năng lượng mới"}],"traditional":"能源危機"},{"id":"逆差","hanzi":"逆差","pinyin":"nìchā","meaning_vi":"nhập siêu, thâm hụt","explanation":"逆 (ngược lại/nghịch cảnh) + 差 (chênh lệch/sai sót).","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📉","examples":[{"type":"basic","zh":"贸易逆差扩大了。","pinyin":"Màoyìnìchā kuòdà le.","vi":"Thâm hụt thương mại đã gia tăng."},{"type":"simple","zh":"去年该国对邻国的贸易逆差达到五十亿美元。","pinyin":"Qùnián gāi guó duì Línguó de màoyìnìchā dádào wǔ shíyì měiyuán.","vi":"Năm ngoái thâm hụt thương mại của nước đó với nước láng giềng đạt năm tỷ đô la Mỹ."},{"type":"compound","zh":"因为进口大量能源，所以这个国家长期处于逆差。","pinyin":"Yīnwèi jìnkǒu dàliàng néngyuán, suǒyǐ zhè ge guójiā chángqī chǔyú nìchā.","vi":"Vì nhập khẩu lượng lớn năng lượng nên đất nước này lâu nay luôn ở tình trạng nhập siêu."}],"related":[{"hanzi":"顺差","pinyin":"shùnchā","vi":"thặng dư"},{"hanzi":"贸易逆差","pinyin":"màoyìnìchā","vi":"thâm hụt thương mại"},{"hanzi":"赤字","pinyin":"chìzì","vi":"thâm hụt"}]},{"id":"逆反心理","hanzi":"逆反心理","pinyin":"nìfǎnxīnlǐ","meaning_vi":"tâm lý chống đối ngược lại","explanation":"逆 (ngược lại/nghịch cảnh) + 反 (反) + 心 (tâm lý/tâm huyết) + 理 (lý luận/quản lý).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","nhan-thuc"],"image":"😤","examples":[{"type":"basic","zh":"孩子有逆反心理。","pinyin":"Háizi yǒu nìfǎnxīnlǐ.","vi":"Đứa trẻ có tâm lý chống đối."},{"type":"simple","zh":"过多的说教容易激起青少年的逆反心理。","pinyin":"Guòduō de shuōjiào róngyì jīqǐ qīngshàonián de nìfǎnxīnlǐ.","vi":"Thuyết giảng quá nhiều dễ khơi dậy tâm lý chống đối của thanh thiếu niên."},{"type":"compound","zh":"如果家长总是强迫孩子学琴，孩子就会产生逆反心理。","pinyin":"Rúguǒ jiāzhǎng zǒngshì qiǎngpò háizi xué qín, háizi jiù huì chǎnshēng nìfǎnxīnlǐ.","vi":"Nếu phụ huynh luôn ép con học đàn thì con sẽ nảy sinh tâm lý chống đối."}],"related":[{"hanzi":"叛逆","pinyin":"pànnì","vi":"nổi loạn"},{"hanzi":"青春期","pinyin":"qīngchūnqī","vi":"tuổi dậy thì"},{"hanzi":"抵触","pinyin":"dǐchù","vi":"phản đối"}]},{"id":"逆流","hanzi":"逆流","pinyin":"nìliú","meaning_vi":"dòng nước ngược, ngược dòng; trào lưu đi ngược (thời đại)","explanation":"逆 (ngược lại/nghịch cảnh) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"小船逆流而上。","pinyin":"Xiǎochuán nìliú ér shàng.","vi":"Chiếc thuyền nhỏ đi ngược dòng nước."},{"type":"simple","zh":"每年秋天，大批三文鱼逆流游回出生的河流产卵。","pinyin":"Měinián qiūtiān, dàpī sānwényú nìliú yóu huí chūshēng de héliú chǎnluǎn.","vi":"Mỗi mùa thu, hàng đàn cá hồi bơi ngược dòng về con sông nơi chúng sinh ra để đẻ trứng."},{"type":"compound","zh":"尽管保护主义逆流涌动，但是全球合作仍是大势所趋。","pinyin":"Jǐnguǎn bǎohù zhǔyì nìliú yǒngdòng, dànshì quánqiú hézuò réng shì dàshìsuǒqū.","vi":"Mặc dù trào lưu bảo hộ đi ngược đang dâng lên, nhưng hợp tác toàn cầu vẫn là xu thế tất yếu."}],"related":[{"hanzi":"顺流","pinyin":"shùnliú","vi":"xuôi dòng"},{"hanzi":"逆流而上","pinyin":"nìliú'érshàng","vi":"ngược dòng tiến lên"},{"hanzi":"潮流","pinyin":"cháoliú","vi":"trào lưu"}]},{"id":"逆向","hanzi":"逆向","pinyin":"nìxiàng","meaning_vi":"ngược chiều","explanation":"逆 (ngược lại/nghịch cảnh) + 向 (hướng về).","hsk_level":"7-9","tags":["tinh-tu","phuong-huong"],"image":"↩️","examples":[{"type":"basic","zh":"这辆车逆向行驶。","pinyin":"Zhè liàng chē nìxiàng xíngshǐ.","vi":"Chiếc xe này chạy ngược chiều."},{"type":"simple","zh":"设计师用逆向思维解决了这个难题。","pinyin":"Shèjìshī yòng nìxiàng sīwéi jiějuéle zhè ge nántí.","vi":"Nhà thiết kế đã dùng tư duy ngược để giải quyết vấn đề khó này."},{"type":"compound","zh":"一旦在高速公路上逆向行驶，就可能酿成大祸。","pinyin":"Yídàn zài gāosùgōnglù shàng nìxiàng xíngshǐ, jiù kěnéng niàngchéng dàhuò.","vi":"Một khi chạy ngược chiều trên đường cao tốc thì có thể gây ra tai họa lớn."}],"related":[{"hanzi":"反向","pinyin":"fǎnxiàng","vi":"ngược hướng"},{"hanzi":"逆行","pinyin":"nìxíng","vi":"đi ngược chiều"},{"hanzi":"正向","pinyin":"zhèngxiàng","vi":"thuận chiều"}]},{"id":"泥石流","hanzi":"泥石流","pinyin":"níshíliú","meaning_vi":"lũ bùn đá","explanation":"泥 (泥) + 石 (đá) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"山区发生了泥石流。","pinyin":"Shānqū fāshēngle níshíliú.","vi":"Vùng núi đã xảy ra lũ bùn đá."},{"type":"simple","zh":"一场突如其来的泥石流冲毁了村口的小桥。","pinyin":"Yì chǎng tūrúqílái de níshíliú chōng huǐle cūn kǒu de Xiǎoqiáo.","vi":"Một trận lũ bùn đá bất ngờ đã cuốn trôi cây cầu nhỏ đầu làng."},{"type":"compound","zh":"因为连续下了三天暴雨，所以山路随时可能出现泥石流。","pinyin":"Yīnwèi liánxù xiàle sān tiān bàoyǔ, suǒyǐ shānlù suíshí kěnéng chūxiàn níshíliú.","vi":"Vì mưa lớn liên tục ba ngày nên đường núi có thể xảy ra lũ bùn đá bất cứ lúc nào."}],"related":[{"hanzi":"山体滑坡","pinyin":"shāntǐhuápō","vi":"sạt lở núi"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"自然灾害","pinyin":"zìránzāihài","vi":"thiên tai"}]},{"id":"凝聚力","hanzi":"凝聚力","pinyin":"níngjùlì","meaning_vi":"sức gắn kết tập thể","explanation":"凝 (ngưng tụ/đông đặc) + 聚 (tụ họp/ngưng tụ) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"这支球队凝聚力强。","pinyin":"Zhè zhī qiúduì níngjùlì qiáng.","vi":"Đội bóng này có sức gắn kết mạnh."},{"type":"simple","zh":"每年的团建活动大大增强了部门的凝聚力。","pinyin":"Měinián de tuánjiàn huódòng dàdà zēngqiángle bùmén de níngjùlì.","vi":"Hoạt động gắn kết đội nhóm hằng năm đã tăng cường đáng kể sức gắn kết của phòng."},{"type":"compound","zh":"一个团队如果缺乏凝聚力，再优秀的个人也难有作为。","pinyin":"Yí gè tuánduì rúguǒ quēfá níngjùlì, zài yōuxiù de gèrén yě nán yǒu zuòwéi.","vi":"Một đội ngũ nếu thiếu sức gắn kết thì cá nhân xuất sắc đến đâu cũng khó làm nên chuyện."}],"related":[{"hanzi":"向心力","pinyin":"xiàngxīnlì","vi":"lực hướng tâm"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"},{"hanzi":"凝聚","pinyin":"níngjù","vi":"ngưng tụ"}]},{"id":"弄巧成拙","hanzi":"弄巧成拙","pinyin":"nòngqiǎo-chéngzhuō","meaning_vi":"khôn quá hóa dại, muốn làm khéo lại thành hỏng","explanation":"弄 (làm) + 巧 (巧) + 成 (thành công/trưởng thành) + 拙 (vụng về/mộc mạc).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤦","examples":[{"type":"basic","zh":"他这次弄巧成拙了。","pinyin":"Tā zhè cì nòngqiǎochéngzhuō le.","vi":"Lần này anh ấy khôn quá hóa dại rồi."},{"type":"simple","zh":"他精心设计的惊喜派对最终弄巧成拙。","pinyin":"Tā jīngxīn shèjì de jīngxǐ pàiduì zuìzhōng nòngqiǎochéngzhuō.","vi":"Bữa tiệc bất ngờ được anh ấy dày công chuẩn bị cuối cùng lại thành khéo quá hóa vụng."},{"type":"compound","zh":"你如果再添油加醋地解释，就会弄巧成拙。","pinyin":"Nǐ rúguǒ zài tiān yóu jiā cù de jiěshì, jiù huì nòngqiǎochéngzhuō.","vi":"Nếu bạn còn thêm mắm thêm muối giải thích nữa thì sẽ thành khéo quá hóa vụng."}],"related":[{"hanzi":"画蛇添足","pinyin":"huàshétiānzú","vi":"vẽ rắn thêm chân"},{"hanzi":"适得其反","pinyin":"shìdéqífǎn","vi":"phản tác dụng"},{"hanzi":"聪明反被聪明误","pinyin":"cōngmíng fǎn bèi cōngmíng wù","vi":"khôn quá hóa dại"}]},{"id":"农副产品","hanzi":"农副产品","pinyin":"nóngfùchǎnpǐn","meaning_vi":"nông sản và sản phẩm phụ","explanation":"农 (农) + 副 (phó (chức vụ)) + 产 (sản xuất/tài sản) + 品 (phẩm chất/thưởng thức).","hsk_level":"7-9","tags":["danh-tu","an-uong","cong-viec"],"image":"🌾","examples":[{"type":"basic","zh":"这里盛产农副产品。","pinyin":"Zhèlǐ shèngchǎn nóngfùchǎnpǐn.","vi":"Nơi đây sản xuất nhiều nông sản và sản phẩm phụ."},{"type":"simple","zh":"村民们通过直播把农副产品卖到了全国各地。","pinyin":"Cūnmínmen tōngguò zhíbō bǎ nóngfùchǎnpǐn mài dàole quánguó gèdì.","vi":"Dân làng thông qua livestream đã bán nông sản và sản phẩm phụ đi khắp cả nước."},{"type":"compound","zh":"只要物流畅通，山里的农副产品就不愁销路。","pinyin":"Zhǐyào wùliú chàngtōng, shān lǐ de nóngfùchǎnpǐn jiù bù chóu xiāolù.","vi":"Chỉ cần vận chuyển thông suốt thì nông sản và sản phẩm phụ trên núi không lo đầu ra."}],"related":[{"hanzi":"农产品","pinyin":"nóngchǎnpǐn","vi":"nông sản"},{"hanzi":"副产品","pinyin":"fùchǎnpǐn","vi":"sản phẩm phụ"},{"hanzi":"土特产","pinyin":"tǔtèchǎn","vi":"đặc sản địa phương"}],"traditional":"農副產品"},{"id":"农耕","hanzi":"农耕","pinyin":"nónggēng","meaning_vi":"canh tác nông nghiệp","explanation":"农 (nông – nghề nông) + 耕 (canh – cày cấy) → cày cấy, canh tác nông nghiệp. VD: 农耕文明, 农耕文化.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thien-nhien"],"image":"🚜","examples":[{"type":"basic","zh":"这里农耕历史悠久。","pinyin":"Zhèlǐ nónggēng lìshǐ yōujiǔ.","vi":"Nơi đây có lịch sử canh tác nông nghiệp lâu đời."},{"type":"simple","zh":"博物馆里陈列着几千年前的农耕工具。","pinyin":"Bówùguǎn lǐ chénlièzhe jǐqiān niánqián de nónggēng gōngjù.","vi":"Trong bảo tàng trưng bày các công cụ canh tác nông nghiệp từ mấy nghìn năm trước."},{"type":"compound","zh":"虽然机械化普及了，但是这个村子仍保留着传统的农耕方式。","pinyin":"Suīrán jīxièhuà pǔjí le, dànshì zhè ge cūnzi réng bǎoliúzhe chuántǒng de nónggēng fāngshì.","vi":"Tuy cơ giới hóa đã phổ biến nhưng ngôi làng này vẫn giữ phương thức canh tác truyền thống."}],"related":[{"hanzi":"耕地","pinyin":"gēngdì","vi":"cày ruộng"},{"hanzi":"农业","pinyin":"nóngyè","vi":"nông nghiệp"},{"hanzi":"农耕文明","pinyin":"nónggēngwénmíng","vi":"văn minh nông nghiệp"}],"traditional":"農耕"},{"id":"农家乐","hanzi":"农家乐","pinyin":"nóngjiālè","meaning_vi":"du lịch sinh thái nhà vườn","explanation":"农 (农) + 家 (nhà) + 乐 (vui vẻ/lạc quan).","hsk_level":"7-9","tags":["danh-tu","du-lich","an-uong"],"image":"🏡","examples":[{"type":"basic","zh":"周末去农家乐吧。","pinyin":"Zhōumò qù nóngjiālè ba.","vi":"Cuối tuần đi du lịch nhà vườn nhé."},{"type":"simple","zh":"我们在郊区的农家乐吃到了现杀的土鸡。","pinyin":"Wǒmen zài jiāoqū de nóngjiālè chī dàole xiàn shā de tǔjī.","vi":"Chúng tôi đã được ăn gà ta vừa làm tại khu du lịch nhà vườn ở ngoại ô."},{"type":"compound","zh":"自从开了农家乐，他家不但收入翻番，而且结识了很多城里朋友。","pinyin":"Zìcóng kāile nóngjiālè, tā jiā búdàn shōurù fānfān, érqiě jiéshíle hěn duō chénglǐ péngyou.","vi":"Từ khi mở dịch vụ du lịch nhà vườn, nhà anh ấy không những thu nhập tăng gấp đôi mà còn quen được nhiều bạn bè thành phố."}],"related":[{"hanzi":"乡村旅游","pinyin":"xiāngcūnlǚyóu","vi":"du lịch nông thôn"},{"hanzi":"生态旅游","pinyin":"shēngtàilǚyóu","vi":"du lịch sinh thái"},{"hanzi":"农家","pinyin":"nóngjiā","vi":"nhà nông"}],"traditional":"農家樂"},{"id":"浓烈","hanzi":"浓烈","pinyin":"nóngliè","meaning_vi":"nồng nàn, đậm đặc (mùi vị/tình cảm)","explanation":"浓 (đậm) + 烈 (mãnh liệt/anh liệt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🍷","examples":[{"type":"basic","zh":"酒味很浓烈。","pinyin":"Jiǔwèi hěn nóngliè.","vi":"Mùi rượu rất nồng."},{"type":"simple","zh":"厨房里飘出一股浓烈的辣椒味。","pinyin":"Chúfáng lǐ piāo chū yì gǔ nóngliè de làjiāo wèi.","vi":"Trong bếp bay ra một mùi ớt nồng nặc."},{"type":"compound","zh":"虽然这款香水味道浓烈，但是很多年轻人喜欢。","pinyin":"Suīrán zhè kuǎn xiāngshuǐ wèidào nóngliè, dànshì hěn duō niánqīngrén xǐhuan.","vi":"Tuy loại nước hoa này mùi rất nồng nhưng nhiều bạn trẻ lại thích."}],"related":[{"hanzi":"浓郁","pinyin":"nóngyù","vi":"đậm đà"},{"hanzi":"强烈","pinyin":"qiángliè","vi":"mãnh liệt"},{"hanzi":"清淡","pinyin":"qīngdàn","vi":"thanh đạm"}],"traditional":"濃烈"},{"id":"农业国","hanzi":"农业国","pinyin":"Nóngyèguó","meaning_vi":"nước nông nghiệp","explanation":"农 (农) + 业 (sự nghiệp/ngành nghề) + 国 (nước).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-danh"],"image":"🌾","examples":[{"type":"basic","zh":"那曾是个农业国。","pinyin":"Nà céng shì gè Nóngyèguó.","vi":"Đó từng là một nước nông nghiệp."},{"type":"simple","zh":"这个国家在几十年里从农业国变成了工业强国。","pinyin":"Zhè ge guójiā zài jǐ shí nián lǐ cóng Nóngyèguó biàn chéngle gōngyè qiángguó.","vi":"Đất nước này trong vài chục năm đã từ một nước nông nghiệp trở thành cường quốc công nghiệp."},{"type":"compound","zh":"因为是传统的农业国，所以粮食安全一直是头等大事。","pinyin":"Yīnwèi shì chuántǒng de Nóngyèguó, suǒyǐ liángshi ānquán yìzhí shì tóuděng dàshì.","vi":"Vì là nước nông nghiệp truyền thống nên an ninh lương thực luôn là việc hệ trọng hàng đầu."}],"related":[{"hanzi":"工业国","pinyin":"Gōngyèguó","vi":"nước công nghiệp"},{"hanzi":"农业","pinyin":"nóngyè","vi":"nông nghiệp"},{"hanzi":"发展中国家","pinyin":"fāzhǎnzhōng guójiā","vi":"nước đang phát triển"}],"traditional":"農業國"},{"id":"浓郁","hanzi":"浓郁","pinyin":"nóngyù","meaning_vi":"đậm đà, nồng nàn (hương thơm/không khí)","explanation":"浓 (đậm) + 郁 (u uất/tươi tốt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"咖啡香气浓郁。","pinyin":"Kāfēi xiāngqì nóngyù.","vi":"Hương cà phê đậm đà."},{"type":"simple","zh":"这条老街充满浓郁的南洋风情。","pinyin":"Zhè tiáo lǎojiē chōngmǎn nóngyù de Nányáng fēngqíng.","vi":"Con phố cũ này đậm đà phong vị Nam Dương."},{"type":"compound","zh":"一走进花园，浓郁的桂花香就扑鼻而来。","pinyin":"Yì zǒujìn huāyuán, nóngyù de guìhuā xiāng jiù pūbí ér lái.","vi":"Vừa bước vào vườn, hương hoa quế nồng nàn đã xộc vào mũi."}],"related":[{"hanzi":"浓厚","pinyin":"nónghòu","vi":"nồng hậu"},{"hanzi":"芳香","pinyin":"fāngxiāng","vi":"thơm ngát"},{"hanzi":"清淡","pinyin":"qīngdàn","vi":"thanh đạm"}],"traditional":"濃郁"},{"id":"怒火","hanzi":"怒火","pinyin":"nùhuǒ","meaning_vi":"cơn thịnh nộ","explanation":"怒 (phẫn nộ) + 火 (火).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🔥","examples":[{"type":"basic","zh":"他压住了怒火。","pinyin":"Tā yāzhùle nùhuǒ.","vi":"Anh ấy đã kìm nén cơn giận."},{"type":"simple","zh":"涨价的消息点燃了乘客们心中的怒火。","pinyin":"Zhǎngjià de xiāoxi diǎnránle chéngkèmen xīnzhōng de nùhuǒ.","vi":"Tin tăng giá đã thổi bùng cơn giận trong lòng hành khách."},{"type":"compound","zh":"他一听到同事在背后造谣，怒火就涌上心头。","pinyin":"Tā yì tīngdào tóngshì zài bèihòu zàoyáo, nùhuǒ jiù yǒng shàng xīntóu.","vi":"Anh vừa nghe đồng nghiệp tung tin đồn sau lưng, cơn giận liền dâng lên trong lòng."}],"related":[{"hanzi":"愤怒","pinyin":"fènnù","vi":"phẫn nộ"},{"hanzi":"怒气","pinyin":"nùqì","vi":"cơn giận"},{"hanzi":"火冒三丈","pinyin":"huǒmàosānzhàng","vi":"nổi giận đùng đùng"}]},{"id":"脑海","hanzi":"脑海","pinyin":"nǎohǎi","meaning_vi":"tâm trí, trong đầu","explanation":"脑 (đầu óc) + 海 (biển).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"往事浮现在脑海。","pinyin":"Wǎngshì fú xiànzài nǎohǎi.","vi":"Chuyện cũ hiện lên trong tâm trí."},{"type":"simple","zh":"那首老歌的旋律一整天都在我脑海里回响。","pinyin":"Nà shǒu lǎogē de xuánlǜ yìzhěngtiān dōu zài wǒ nǎohǎi lǐ huíxiǎng.","vi":"Giai điệu của bài hát cũ ấy vang vọng trong đầu tôi suốt cả ngày."},{"type":"compound","zh":"每当闻到槐花香，奶奶的笑脸就会浮现在我脑海中。","pinyin":"Měidāng wéndào huái huāxiāng, nǎinai de xiàoliǎn jiù huì fú xiànzài wǒ nǎohǎi zhōng.","vi":"Mỗi khi ngửi thấy hương hoa hòe, gương mặt tươi cười của bà lại hiện lên trong tâm trí tôi."}],"related":[{"hanzi":"脑子","pinyin":"nǎozi","vi":"đầu óc"},{"hanzi":"记忆","pinyin":"jìyì","vi":"ký ức"},{"hanzi":"浮现","pinyin":"fúxiàn","vi":"hiện lên"}],"traditional":"腦海"},{"id":"脑力劳动","hanzi":"脑力劳动","pinyin":"nǎolìláodòng","meaning_vi":"lao động trí óc","explanation":"脑 (đầu óc) + 力 (sức mạnh/nỗ lực) + 劳 (lao động/vất vả) + 动 (动).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💻","examples":[{"type":"basic","zh":"写作是脑力劳动。","pinyin":"Xiězuò shì nǎolìláodòng.","vi":"Viết lách là lao động trí óc."},{"type":"simple","zh":"长时间的脑力劳动让程序员们常常感到头痛。","pinyin":"Cháng shíjiān de nǎolìláodòng ràng chéngxùyuánmen chángcháng gǎndào tóutòng.","vi":"Lao động trí óc trong thời gian dài khiến các lập trình viên thường xuyên đau đầu."},{"type":"compound","zh":"脑力劳动虽然不费体力，但是同样让人疲惫。","pinyin":"Nǎolìláodòng suīrán bú fèi tǐlì, dànshì tóngyàng ràng rén píbèi.","vi":"Lao động trí óc tuy không tốn sức nhưng cũng khiến người ta mệt mỏi như vậy."}],"related":[{"hanzi":"体力劳动","pinyin":"tǐlìláodòng","vi":"lao động chân tay"},{"hanzi":"脑力","pinyin":"nǎolì","vi":"trí lực"},{"hanzi":"劳动","pinyin":"láodòng","vi":"lao động"}],"traditional":"腦力勞動"},{"id":"拟人","hanzi":"拟人","pinyin":"nǐrén","meaning_vi":"nhân hóa","explanation":"拟 (soạn thảo/mô phỏng) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🧚","examples":[{"type":"basic","zh":"这句话用了拟人。","pinyin":"Zhè jù huà yòngle nǐrén.","vi":"Câu này dùng biện pháp nhân hóa."},{"type":"simple","zh":"作者用拟人的手法把月亮写成了害羞的姑娘。","pinyin":"Zuòzhě yòng nǐrén de shǒufǎ bǎ yuèliang xiě chéngle hàixiū de gūniang.","vi":"Tác giả dùng thủ pháp nhân hóa để viết mặt trăng thành một cô gái e thẹn."},{"type":"compound","zh":"如果在作文里恰当地运用拟人，文章就会生动许多。","pinyin":"Rúguǒ zài zuòwén lǐ qià dàngde yùnyòng nǐrén, wénzhāng jiù huì shēngdòng xǔduō.","vi":"Nếu vận dụng nhân hóa hợp lý trong bài văn thì bài viết sẽ sinh động hơn nhiều."}],"related":[{"hanzi":"拟人化","pinyin":"nǐrénhuà","vi":"nhân cách hóa"},{"hanzi":"比喻","pinyin":"bǐyù","vi":"so sánh ẩn dụ"},{"hanzi":"修辞","pinyin":"xiūcí","vi":"tu từ"}],"traditional":"擬人"},{"id":"拟人化","hanzi":"拟人化","pinyin":"nǐrénhuà","meaning_vi":"nhân cách hóa","explanation":"拟 (soạn thảo/mô phỏng) + 人 (người) + 化 (化).","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"🧚","examples":[{"type":"basic","zh":"动画里的动物都很拟人化。","pinyin":"Dònghuà lǐ de dòngwù dōu hěn nǐrénhuà.","vi":"Các con vật trong phim hoạt hình đều được nhân cách hóa."},{"type":"simple","zh":"这家品牌把吉祥物设计成拟人化的小熊。","pinyin":"Zhè jiā pǐnpái bǎ jíxiángwù shèjì chéng nǐrénhuà de xiǎo Xióng.","vi":"Thương hiệu này thiết kế linh vật thành chú gấu nhỏ được nhân cách hóa."},{"type":"compound","zh":"因为语音助手越来越拟人化，所以老人也愿意跟它聊天。","pinyin":"Yīnwèi yǔyīn zhùshǒu yuèláiyuè nǐrénhuà, suǒyǐ lǎorén yě yuànyì gēn tā liáotiān.","vi":"Vì trợ lý giọng nói ngày càng được nhân cách hóa nên người già cũng sẵn lòng trò chuyện với nó."}],"related":[{"hanzi":"拟人","pinyin":"nǐrén","vi":"nhân hóa"},{"hanzi":"比喻","pinyin":"bǐyù","vi":"so sánh ẩn dụ"},{"hanzi":"夸张","pinyin":"kuāzhāng","vi":"phóng đại"}],"traditional":"擬人化"},{"id":"片酬","hanzi":"片酬","pinyin":"piànchóu","meaning_vi":"thù lao đóng phim (cát-xê)","explanation":"片 (miếng) + 酬 (thù lao/đáp lễ).","hsk_level":"7-9","tags":["danh-tu","giai-tri","tien-te"],"image":"🎬","examples":[{"type":"basic","zh":"他的片酬很高。","pinyin":"Tā de piànchóu hěn gāo.","vi":"Cát-xê đóng phim của anh ấy rất cao."},{"type":"simple","zh":"这位新人演员的片酬一年内涨了十倍。","pinyin":"Zhè wèi xīnrén yǎnyuán de piànchóu yì niánnèi zhǎngle shíbèi.","vi":"Cát-xê của diễn viên mới này đã tăng gấp mười lần trong vòng một năm."},{"type":"compound","zh":"明星片酬如果过高，制作经费就会被严重挤压。","pinyin":"Míngxīng piànchóu rúguǒ guògāo, zhìzuò jīngfèi jiù huì bèi yánzhòng jǐyā.","vi":"Nếu cát-xê ngôi sao quá cao thì kinh phí sản xuất sẽ bị chèn ép nghiêm trọng."}],"related":[{"hanzi":"报酬","pinyin":"bàochou","vi":"thù lao"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"片场","pinyin":"piànchǎng","vi":"phim trường"}]},{"id":"片断","hanzi":"片断","pinyin":"piànduàn","meaning_vi":"đoạn trích, ký ức rời rạc","explanation":"片 (miếng) + 断 (đứt).","hsk_level":"7-9","tags":["danh-tu"],"image":"🎞️","examples":[{"type":"basic","zh":"我只记得一些片断。","pinyin":"Wǒ zhǐ jìde yìxiē piànduàn.","vi":"Tôi chỉ nhớ được vài mảnh ký ức rời rạc."},{"type":"simple","zh":"老师让我们朗读小说中最感人的一个片断。","pinyin":"Lǎoshī ràng wǒmen lǎngdú xiǎoshuō zhōng zuì gǎnrén de yí gè piànduàn.","vi":"Cô giáo bảo chúng tôi đọc to một đoạn trích cảm động nhất trong tiểu thuyết."},{"type":"compound","zh":"虽然醒来后梦只剩下几个片断，但是那种恐惧依然清晰。","pinyin":"Suīrán xǐnglái hòu mèng zhǐ shèngxià jǐ gè piànduàn, dànshì nà zhǒng kǒngjù yīrán qīngxī.","vi":"Tuy sau khi tỉnh dậy giấc mơ chỉ còn lại vài mảnh rời rạc, nhưng nỗi sợ ấy vẫn còn rõ ràng."}],"related":[{"hanzi":"片段","pinyin":"piànduàn","vi":"đoạn"},{"hanzi":"断片","pinyin":"duànpiàn","vi":"mảnh vụn"},{"hanzi":"完整","pinyin":"wánzhěng","vi":"hoàn chỉnh"}],"traditional":"片斷"},{"id":"便装","hanzi":"便装","pinyin":"biànzhuāng","meaning_vi":"thường phục (không phải đồng phục/lễ phục)","explanation":"便 (liền) + 装 (trang bị/ngụy trang).","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👕","examples":[{"type":"basic","zh":"他今天穿着便装。","pinyin":"Tā jīntiān chuānzhe biànzhuāng.","vi":"Hôm nay anh ấy mặc thường phục."},{"type":"simple","zh":"几名身穿便装的警察悄悄混进了人群。","pinyin":"Jǐ míng shēnchuān biànzhuāng de jǐngchá qiāoqiāo hùnjìnle rénqún.","vi":"Mấy cảnh sát mặc thường phục lặng lẽ trà trộn vào đám đông."},{"type":"compound","zh":"既然是朋友聚会，就穿便装来吧，不用打领带。","pinyin":"Jìrán shì péngyou jùhuì, jiù chuān biànzhuāng lái ba, bú yòng dǎ lǐngdài.","vi":"Đã là buổi gặp mặt bạn bè thì cứ mặc thường phục đến, không cần thắt cà vạt."}],"related":[{"hanzi":"便服","pinyin":"biànfú","vi":"thường phục"},{"hanzi":"休闲装","pinyin":"xiūxiánzhuāng","vi":"đồ thường ngày"},{"hanzi":"制服","pinyin":"zhìfú","vi":"đồng phục"}],"traditional":"便裝"},{"id":"偏离","hanzi":"偏离","pinyin":"piānlí","meaning_vi":"đi chệch hướng","explanation":"偏 (thành kiến/sai lệch) + 离 (cách (khoảng cách)).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧭","examples":[{"type":"basic","zh":"飞机偏离了航线。","pinyin":"Fēijī piānlíle hángxiàn.","vi":"Máy bay đã đi chệch đường bay."},{"type":"simple","zh":"讨论渐渐偏离了会议的主题。","pinyin":"Tǎolùn jiànjiàn piānlíle huìyì de zhǔtí.","vi":"Cuộc thảo luận dần dần đi chệch khỏi chủ đề cuộc họp."},{"type":"compound","zh":"一旦偏离了最初的目标，再多的努力也可能白费。","pinyin":"Yídàn piānlíle zuìchū de mùbiāo, zài duō de nǔlì yě kěnéng báifèi.","vi":"Một khi đã đi chệch mục tiêu ban đầu thì nỗ lực nhiều đến đâu cũng có thể uổng phí."}],"related":[{"hanzi":"背离","pinyin":"bèilí","vi":"đi ngược"},{"hanzi":"偏差","pinyin":"piānchā","vi":"sai lệch"},{"hanzi":"偏离轨道","pinyin":"piānlíguǐdào","vi":"chệch quỹ đạo"}],"traditional":"偏離"},{"id":"偏旁部首","hanzi":"偏旁部首","pinyin":"piānpángbùshǒu","meaning_vi":"bộ thủ chữ Hán","explanation":"偏 (thành kiến/sai lệch) + 旁 (bàng quan/bên cạnh) + 部 (部) + 首 (bài (lượng từ thơ/ca khúc)).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"先学偏旁部首。","pinyin":"Xiān xué piānpángbùshǒu.","vi":"Hãy học bộ thủ chữ Hán trước."},{"type":"simple","zh":"外国学生可以通过偏旁部首猜出生字的大概意思。","pinyin":"Wàiguó xuéshēng kěyǐ tōngguò piānpángbùshǒu cāi chū shēngzì de dàgài yìsi.","vi":"Sinh viên nước ngoài có thể đoán ý nghĩa đại khái của chữ mới thông qua bộ thủ."},{"type":"compound","zh":"只要掌握了常用的偏旁部首，查字典就快多了。","pinyin":"Zhǐyào zhǎngwòle chángyòng de piānpángbùshǒu, chá zìdiǎn jiù kuài duō le.","vi":"Chỉ cần nắm được các bộ thủ thường dùng thì tra từ điển sẽ nhanh hơn nhiều."}],"related":[{"hanzi":"部首","pinyin":"bùshǒu","vi":"bộ thủ"},{"hanzi":"偏旁","pinyin":"piānpáng","vi":"thiên bàng"},{"hanzi":"笔画","pinyin":"bǐhuà","vi":"nét chữ"}]},{"id":"偏向","hanzi":"偏向","pinyin":"piānxiàng","meaning_vi":"nghiêng về, thiên về; thiên vị","explanation":"偏 (thành kiến/sai lệch) + 向 (hướng về).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"裁判偏向主队。","pinyin":"Cáipàn piānxiàng zhǔduì.","vi":"Trọng tài thiên vị đội chủ nhà."},{"type":"simple","zh":"在专业选择上，她更偏向于实用的计算机方向。","pinyin":"Zài zhuānyè xuǎnzé shàng, tā gèng piānxiàng yú shíyòng de jìsuànjī fāngxiàng.","vi":"Trong việc chọn chuyên ngành, cô ấy nghiêng về hướng máy tính mang tính thực dụng hơn."},{"type":"compound","zh":"虽然两个方案各有优点，但是大多数人偏向第一个。","pinyin":"Suīrán liǎng gè fāng'àn gè yǒu yōudiǎn, dànshì dàduōshù rén piānxiàng dìyī gè.","vi":"Tuy hai phương án đều có ưu điểm nhưng đa số mọi người nghiêng về phương án thứ nhất."}],"related":[{"hanzi":"倾向","pinyin":"qīngxiàng","vi":"khuynh hướng"},{"hanzi":"偏爱","pinyin":"piān'ài","vi":"thiên vị"},{"hanzi":"偏袒","pinyin":"piāntǎn","vi":"bênh vực một phía"}]},{"id":"偏爱","hanzi":"偏爱","pinyin":"piān'ài","meaning_vi":"đặc biệt yêu thích, ưa chuộng; thiên vị","explanation":"偏 (thành kiến/sai lệch) + 爱 (yêu).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"奶奶偏爱小孙子。","pinyin":"Nǎinai piān'ài xiǎo sūnzi.","vi":"Bà đặc biệt cưng chiều đứa cháu út."},{"type":"simple","zh":"这位导演特别偏爱用长镜头拍摄城市夜景。","pinyin":"Zhè wèi dǎoyǎn tèbié piān'ài yòng cháng jìngtóu pāishè chéngshì yèjǐng.","vi":"Đạo diễn này đặc biệt ưa dùng cảnh quay dài để quay cảnh đêm thành phố."},{"type":"compound","zh":"父母如果偏爱其中一个孩子，其他孩子就会觉得委屈。","pinyin":"Fùmǔ rúguǒ piān'ài qízhōng yí gè háizi, qítā háizi jiù huì juéde wěiqu.","vi":"Nếu cha mẹ thiên vị một đứa con thì những đứa khác sẽ thấy tủi thân."}],"related":[{"hanzi":"喜爱","pinyin":"xǐ'ài","vi":"yêu thích"},{"hanzi":"偏心","pinyin":"piānxīn","vi":"thiên vị"},{"hanzi":"偏向","pinyin":"piānxiàng","vi":"nghiêng về"}],"traditional":"偏愛"},{"id":"飘荡","hanzi":"飘荡","pinyin":"piāodàng","meaning_vi":"bay lơ lửng, dập dềnh","explanation":"飘 (bay lơ lửng) + 荡 (dao động/lắc lư).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍃","examples":[{"type":"basic","zh":"歌声在山谷飘荡。","pinyin":"Gēshēng zài shāngǔ piāodàng.","vi":"Tiếng hát vang vọng lơ lửng trong thung lũng."},{"type":"simple","zh":"一只小木船在湖面上随风飘荡。","pinyin":"Yì zhī xiǎo mùchuán zài húmiàn shàng suífēng piāodàng.","vi":"Một chiếc thuyền gỗ nhỏ dập dềnh theo gió trên mặt hồ."},{"type":"compound","zh":"风一吹，晾在阳台上的床单就飘荡起来。","pinyin":"Fēng yì chuī, liàng zài yángtái shàng de chuángdān jiù piāodàng qǐlái.","vi":"Gió vừa thổi, tấm ga trải giường phơi ngoài ban công liền bay phấp phới."}],"related":[{"hanzi":"飘扬","pinyin":"piāoyáng","vi":"tung bay"},{"hanzi":"飘浮","pinyin":"piāofú","vi":"trôi nổi"},{"hanzi":"回荡","pinyin":"huídàng","vi":"vang vọng"}],"traditional":"飄蕩"},{"id":"飘零","hanzi":"飘零","pinyin":"piāolíng","meaning_vi":"phiêu bạt, rơi rụng","explanation":"飘 (bay lơ lửng) + 零 (số 0).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"秋叶片片飘零。","pinyin":"Qiū yèpiàn piàn piāolíng.","vi":"Lá thu rơi rụng từng chiếc."},{"type":"simple","zh":"战乱让无数家庭在异国他乡四处飘零。","pinyin":"Zhànluàn ràng wúshù jiātíng zài yìguótāxiāng sìchù piāolíng.","vi":"Chiến tranh khiến vô số gia đình phiêu bạt khắp nơi nơi đất khách quê người."},{"type":"compound","zh":"他虽然半生飘零，但是始终没有忘记回家的路。","pinyin":"Tā suīrán bànshēng piāolíng, dànshì shǐzhōng méiyǒu wàngjì huíjiā de lù.","vi":"Tuy nửa đời phiêu bạt nhưng ông ấy chưa bao giờ quên đường về nhà."}],"related":[{"hanzi":"凋零","pinyin":"diāolíng","vi":"tàn úa"},{"hanzi":"漂泊","pinyin":"piāobó","vi":"phiêu bạt"},{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"}],"traditional":"飄零"},{"id":"派系","hanzi":"派系","pinyin":"pàixì","meaning_vi":"phe phái","explanation":"派 (cử đi) + 系 (khoa (trong trường đại học)).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"公司内部派系林立。","pinyin":"Gōngsī nèibù pàixì línlì.","vi":"Nội bộ công ty có nhiều phe phái."},{"type":"simple","zh":"新校长上任后努力化解教师之间的派系矛盾。","pinyin":"Xīn xiàozhǎng shàngrèn hòu nǔlì huàjiě jiàoshī zhījiān de pàixì máodùn.","vi":"Sau khi nhậm chức, hiệu trưởng mới cố gắng hóa giải mâu thuẫn phe phái giữa các giáo viên."},{"type":"compound","zh":"一旦陷入派系斗争，团队就很难专注于业务。","pinyin":"Yídàn xiànrù pàixì dòuzhēng, tuánduì jiù hěn nán zhuānzhù yú yèwù.","vi":"Một khi sa vào đấu đá phe phái, đội ngũ sẽ rất khó tập trung vào công việc."}],"related":[{"hanzi":"派别","pinyin":"pàibié","vi":"phe phái"},{"hanzi":"党派","pinyin":"dǎngpài","vi":"đảng phái"},{"hanzi":"帮派","pinyin":"bāngpài","vi":"băng nhóm"}]},{"id":"叛逆","hanzi":"叛逆","pinyin":"pànnì","meaning_vi":"nổi loạn, chống đối","explanation":"叛 (phản bội) + 逆 (ngược lại/nghịch cảnh).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"⚡","examples":[{"type":"basic","zh":"他青春期很叛逆。","pinyin":"Tā qīngchūnqī hěn pànnì.","vi":"Thời dậy thì cậu ấy rất nổi loạn."},{"type":"simple","zh":"这位歌手用叛逆的摇滚风格征服了年轻观众。","pinyin":"Zhè wèi gē shǒuyòng pànnì de yáogǔn fēnggé zhēngfúle niánqīng guānzhòng.","vi":"Ca sĩ này đã chinh phục khán giả trẻ bằng phong cách rock nổi loạn."},{"type":"compound","zh":"虽然儿子小时候很叛逆，但是长大后变得非常懂事。","pinyin":"Suīrán érzi xiǎoshíhou hěn pànnì, dànshì zhǎngdà hòu biànde fēicháng dǒngshì.","vi":"Tuy con trai hồi nhỏ rất nổi loạn nhưng lớn lên lại trở nên rất hiểu chuyện."}],"related":[{"hanzi":"逆反","pinyin":"nìfǎn","vi":"chống đối"},{"hanzi":"反叛","pinyin":"fǎnpàn","vi":"phản loạn"},{"hanzi":"叛逆期","pinyin":"pànnìqī","vi":"tuổi nổi loạn"}]},{"id":"判若两人","hanzi":"判若两人","pinyin":"pànruò-liǎngrén","meaning_vi":"khác hẳn như hai người hoàn toàn khác nhau","explanation":"判 (phán quyết/xét xử) + 若 (若) + 两 (hai (số lượng)) + 人 (người).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"他现在判若两人。","pinyin":"Tā xiànzài pànruòliǎngrén.","vi":"Bây giờ anh ấy khác hẳn như hai người."},{"type":"simple","zh":"登上舞台的她和平时害羞的样子判若两人。","pinyin":"Dēngshàng wǔtái de tā hé píngshí hàixiū de yàngzi pànruòliǎngrén.","vi":"Cô ấy khi bước lên sân khấu khác hẳn so với dáng vẻ rụt rè thường ngày."},{"type":"compound","zh":"他一喝酒就判若两人，平时的温和全都不见了。","pinyin":"Tā yì hējiǔ jiù pànruòliǎngrén, píngshí de wēnhé quándōu bújiàn le.","vi":"Anh ta hễ uống rượu là như biến thành người khác, vẻ ôn hòa thường ngày biến mất hết."}],"related":[{"hanzi":"截然不同","pinyin":"jiéránbùtóng","vi":"hoàn toàn khác"},{"hanzi":"脱胎换骨","pinyin":"tuōtāihuàngǔ","vi":"thay da đổi thịt"},{"hanzi":"前后","pinyin":"qiánhòu","vi":"trước sau"}],"traditional":"判若兩人"},{"id":"泡沫经济","hanzi":"泡沫经济","pinyin":"pàomòjīngjì","meaning_vi":"kinh tế bong bóng","explanation":"泡 (ngâm/bong bóng) + 沫 (沫) + 经 (经) + 济 (济).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"🫧","examples":[{"type":"basic","zh":"泡沫经济终会破裂。","pinyin":"Pàomòjīngjì zhōng huì pòliè.","vi":"Kinh tế bong bóng rồi sẽ vỡ."},{"type":"simple","zh":"九十年代初的泡沫经济让日本陷入了长期低迷。","pinyin":"Jiǔshí niándàichū de pàomòjīngjì ràng Rìběn xiànrùle chángqī dīmí.","vi":"Kinh tế bong bóng đầu những năm chín mươi khiến Nhật Bản rơi vào trì trệ kéo dài."},{"type":"compound","zh":"如果房价长期脱离实际收入，就可能形成泡沫经济。","pinyin":"Rúguǒ fángjià chángqī tuōlí shíjì shōurù, jiù kěnéng xíngchéng pàomòjīngjì.","vi":"Nếu giá nhà lâu dài tách rời thu nhập thực tế thì có thể hình thành kinh tế bong bóng."}],"related":[{"hanzi":"泡沫","pinyin":"pàomò","vi":"bong bóng"},{"hanzi":"经济危机","pinyin":"jīngjìwēijī","vi":"khủng hoảng kinh tế"},{"hanzi":"房地产","pinyin":"fángdìchǎn","vi":"bất động sản"}],"traditional":"泡沫經濟"},{"id":"排比","hanzi":"排比","pinyin":"páibǐ","meaning_vi":"liệt kê trùng điệp (biện pháp tu từ)","explanation":"排 (bài xích/sắp xếp) + 比 (so với).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"📑","examples":[{"type":"basic","zh":"这段用了排比。","pinyin":"Zhè duàn yòngle páibǐ.","vi":"Đoạn này dùng phép liệt kê trùng điệp."},{"type":"simple","zh":"演讲者用三个排比句把会场气氛推向了高潮。","pinyin":"Yǎnjiǎng zhě yòng sān gè páibǐ jù bǎ huìchǎng qìfēn tuī xiàngle gāocháo.","vi":"Diễn giả dùng ba câu điệp cấu trúc để đẩy không khí hội trường lên cao trào."},{"type":"compound","zh":"排比虽然能增强气势，但是用多了就显得空洞。","pinyin":"Páibǐ suīrán néng zēngqiáng qìshì, dànshì yòng duōle jiù xiǎnde kōngdòng.","vi":"Phép điệp cấu trúc tuy có thể tăng khí thế nhưng dùng nhiều lại có vẻ sáo rỗng."}],"related":[{"hanzi":"比喻","pinyin":"bǐyù","vi":"so sánh ẩn dụ"},{"hanzi":"拟人","pinyin":"nǐrén","vi":"nhân hóa"},{"hanzi":"修辞","pinyin":"xiūcí","vi":"tu từ"}]},{"id":"排场","hanzi":"排场","pinyin":"páichǎng","meaning_vi":"sự phô trương hình thức","explanation":"排 (bài xích/sắp xếp) + 场 (địa điểm/trận đấu).","hsk_level":"7-9","tags":["danh-tu"],"image":"🎊","examples":[{"type":"basic","zh":"婚礼排场太大了。","pinyin":"Hūnlǐ páichǎng tài dà le.","vi":"Đám cưới phô trương quá."},{"type":"simple","zh":"这位老板出差时总带着五六个助理撑排场。","pinyin":"Zhè wèi lǎobǎn chūchāi shí zǒng dàizhe wǔ liù gè zhùlǐ chēng páichǎng.","vi":"Ông chủ này đi công tác luôn mang theo năm sáu trợ lý cho thêm phần phô trương."},{"type":"compound","zh":"与其花钱讲排场，不如把钱用在孩子的教育上。","pinyin":"Yǔqí huāqián jiǎngpáichǎng, bùrú bǎ qián yòng zài háizi de jiàoyù shàng.","vi":"Thay vì tiêu tiền để phô trương, chi bằng dùng tiền đó cho việc học của con."}],"related":[{"hanzi":"讲排场","pinyin":"jiǎngpáichǎng","vi":"thích phô trương"},{"hanzi":"铺张","pinyin":"pūzhāng","vi":"phô trương"},{"hanzi":"简朴","pinyin":"jiǎnpǔ","vi":"giản dị"}],"traditional":"排場"},{"id":"排行","hanzi":"排行","pinyin":"páiháng","meaning_vi":"thứ bậc anh chị em trong nhà; xếp hạng","explanation":"排 (bài xích/sắp xếp) + 行 (được).","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"🔢","examples":[{"type":"basic","zh":"我在家排行老二。","pinyin":"Wǒ zài jiā páiháng lǎo'èr.","vi":"Tôi là con thứ hai trong nhà."},{"type":"simple","zh":"这部电影上映三天就登上了票房排行榜第一。","pinyin":"Zhè bù diànyǐng shàngyìng sān tiān jiù dēngshàngle piàofáng páihángbǎng dìyī.","vi":"Bộ phim này công chiếu ba ngày đã đứng đầu bảng xếp hạng doanh thu phòng vé."},{"type":"compound","zh":"他虽然在兄弟中排行最小，但是最有主见。","pinyin":"Tā suīrán zài xiōngdì zhōng páiháng zuì xiǎo, dànshì zuì yǒuzhǔjiàn.","vi":"Tuy anh ấy là út trong số anh em nhưng lại là người có chính kiến nhất."}],"related":[{"hanzi":"排名","pinyin":"páimíng","vi":"xếp hạng"},{"hanzi":"排行榜","pinyin":"páihángbǎng","vi":"bảng xếp hạng"},{"hanzi":"老大","pinyin":"lǎodà","vi":"con cả"}]},{"id":"排练","hanzi":"排练","pinyin":"páiliàn","meaning_vi":"diễn tập (kịch/múa/ca nhạc)","explanation":"排 (bài xích/sắp xếp) + 练 (luyện tập).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎭","examples":[{"type":"basic","zh":"乐队正在排练。","pinyin":"Yuèduì zhèngzài páiliàn.","vi":"Ban nhạc đang tập luyện."},{"type":"simple","zh":"为了毕业晚会，我们每天放学后排练两个小时。","pinyin":"Wèile bìyè wǎnhuì, wǒmen měitiān fàngxué hòu páiliàn liǎng gè xiǎoshí.","vi":"Để chuẩn bị cho đêm liên hoan tốt nghiệp, mỗi ngày sau giờ học chúng tôi tập luyện hai tiếng."},{"type":"compound","zh":"只要再排练几遍，正式演出就不会出错。","pinyin":"Zhǐyào zài páiliàn jǐ biàn, zhèngshì yǎnchū jiù bú huì chūcuò.","vi":"Chỉ cần tập thêm vài lần nữa thì buổi diễn chính thức sẽ không mắc lỗi."}],"related":[{"hanzi":"彩排","pinyin":"cǎipái","vi":"tổng duyệt"},{"hanzi":"演出","pinyin":"yǎnchū","vi":"biểu diễn"},{"hanzi":"练习","pinyin":"liànxí","vi":"luyện tập"}],"traditional":"排練"},{"id":"排忧解难","hanzi":"排忧解难","pinyin":"páiyōu-jiěnàn","meaning_vi":"gỡ rối giúp đỡ giải quyết khó khăn","explanation":"排 (bài xích/sắp xếp) + 忧 (lo âu/u sầu) + 解 (giải quyết/hiểu) + 难 (khó).","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"社工为居民排忧解难。","pinyin":"Shègōng wèi jūmín páiyōujiěnàn.","vi":"Nhân viên công tác xã hội gỡ rối khó khăn cho cư dân."},{"type":"simple","zh":"这条热线专门为独居老人排忧解难。","pinyin":"Zhè tiáo rèxiàn zhuānmén wèi dújū lǎorén páiyōujiěnàn.","vi":"Đường dây nóng này chuyên giải quyết khó khăn cho người già sống một mình."},{"type":"compound","zh":"只要同事遇到麻烦，老张就会主动帮他们排忧解难。","pinyin":"Zhǐyào tóngshì yùdào máfan, lǎo Zhāng jiù huì zhǔdòng bāng tāmen páiyōujiěnàn.","vi":"Chỉ cần đồng nghiệp gặp rắc rối là ông Trương sẽ chủ động giúp họ tháo gỡ khó khăn."}],"related":[{"hanzi":"解决","pinyin":"jiějué","vi":"giải quyết"},{"hanzi":"分忧","pinyin":"fēnyōu","vi":"chia sẻ lo âu"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"}],"traditional":"排憂解難"},{"id":"盘点","hanzi":"盘点","pinyin":"pándiǎn","meaning_vi":"kiểm kê (hàng hóa/sự kiện cuối năm)","explanation":"盘 (tính toán/bàn cờ) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"超市今晚盘点。","pinyin":"Chāoshì jīnwǎn pándiǎn.","vi":"Siêu thị kiểm kê tối nay."},{"type":"simple","zh":"年底这家媒体盘点了十大科技新闻。","pinyin":"Niándǐ zhè jiā méitǐ pándiǎnle shí dà kējì xīnwén.","vi":"Cuối năm, cơ quan truyền thông này đã điểm lại mười tin tức công nghệ lớn."},{"type":"compound","zh":"因为仓库要盘点库存，所以明天暂停发货。","pinyin":"Yīnwèi cāngkù yào pándiǎn kùcún, suǒyǐ míngtiān zàntíng fāhuò.","vi":"Vì kho phải kiểm kê hàng tồn nên ngày mai tạm ngừng giao hàng."}],"related":[{"hanzi":"清点","pinyin":"qīngdiǎn","vi":"kiểm đếm"},{"hanzi":"库存","pinyin":"kùcún","vi":"hàng tồn kho"},{"hanzi":"总结","pinyin":"zǒngjié","vi":"tổng kết"}],"traditional":"盤點"},{"id":"旁观者清","hanzi":"旁观者清","pinyin":"pángguān-zhěqīng","meaning_vi":"người ngoài cuộc sáng suốt hơn người trong cuộc","explanation":"旁 (bàng quan/bên cạnh) + 观 (观) + 者 (者) + 清 (trong sạch/rõ nét).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"当局者迷，旁观者清。","pinyin":"Dāngjú zhě mí, pángguānzhěqīng.","vi":"Người trong cuộc thì mê, người ngoài cuộc thì tỉnh."},{"type":"simple","zh":"俗话说旁观者清，你不妨听听老同学的看法。","pinyin":"Súhuàshuō pángguānzhěqīng, nǐ bùfáng tīng ting lǎo tóngxué de kànfǎ.","vi":"Tục ngữ nói người ngoài cuộc thì sáng suốt, bạn thử nghe ý kiến của bạn học cũ xem."},{"type":"compound","zh":"因为旁观者清，所以朋友一眼就看出了他们感情的问题。","pinyin":"Yīnwèi pángguānzhěqīng, suǒyǐ péngyou yìyǎn jiù kànchūle tāmen gǎnqíng de wèntí.","vi":"Vì người ngoài cuộc thì sáng suốt nên bạn bè nhìn một cái là thấy ngay vấn đề trong tình cảm của họ."}],"related":[{"hanzi":"当局者迷","pinyin":"dāngjúzhěmí","vi":"người trong cuộc thì mù quáng"},{"hanzi":"旁观者","pinyin":"pángguānzhě","vi":"người ngoài cuộc"},{"hanzi":"客观","pinyin":"kèguān","vi":"khách quan"}],"traditional":"旁觀者清"},{"id":"旁若无人","hanzi":"旁若无人","pinyin":"pángruò-wúrén","meaning_vi":"coi như không có ai bên cạnh (tự nhiên hoặc kiêu ngạo)","explanation":"旁 (bàng quan/bên cạnh) + 若 (若) + 无 (không có) + 人 (người).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😎","examples":[{"type":"basic","zh":"他旁若无人地大笑。","pinyin":"Tā pángruòwúrén de dàxiào.","vi":"Anh ta cười lớn như thể không có ai bên cạnh."},{"type":"simple","zh":"那对情侣在地铁上旁若无人地大声争吵。","pinyin":"Nà duì qínglǚ zài dìtiě shàng pángruòwúrén de dàshēng zhēngchǎo.","vi":"Cặp đôi đó cãi nhau to tiếng trên tàu điện ngầm như thể không có ai xung quanh."},{"type":"compound","zh":"她一坐到钢琴前，就旁若无人地沉浸在音乐里。","pinyin":"Tā yí zuò dào gāngqín qián, jiù pángruòwúrén de chénjìn zài yīnyuè lǐ.","vi":"Cô ấy vừa ngồi vào đàn piano là chìm đắm trong âm nhạc như chẳng có ai xung quanh."}],"related":[{"hanzi":"目中无人","pinyin":"mùzhōngwúrén","vi":"coi trời bằng vung"},{"hanzi":"自顾自","pinyin":"zìgùzì","vi":"chỉ biết mình"},{"hanzi":"嚣张","pinyin":"xiāozhāng","vi":"ngang ngược"}],"traditional":"旁若無人"},{"id":"配合默契","hanzi":"配合默契","pinyin":"pèihémòqì","meaning_vi":"phối hợp ăn ý","explanation":"配 (phối hợp/trang bị) + 合 (合) + 默 (âm thầm/im lặng) + 契 (hợp đồng/ăn ý).","hsk_level":"7-9","tags":["tinh-tu","cong-viec","the-thao"],"image":"🤝","examples":[{"type":"basic","zh":"两人配合默契。","pinyin":"Liǎng rén pèihémòqì.","vi":"Hai người phối hợp ăn ý."},{"type":"simple","zh":"这对双打选手在决赛中配合默契，连赢两局。","pinyin":"Zhè duì shuāngdǎ xuǎnshǒu zài juésài zhōng pèihémòqì, lián yíng liǎng jú.","vi":"Cặp vận động viên đánh đôi này phối hợp ăn ý trong trận chung kết, thắng liền hai ván."},{"type":"compound","zh":"只要大家配合默契，再紧的工期也能按时完成。","pinyin":"Zhǐyào dàjiā pèihémòqì, zài jǐn de gōngqī yě néng ànshí wánchéng.","vi":"Chỉ cần mọi người phối hợp ăn ý thì tiến độ gấp đến đâu cũng có thể hoàn thành đúng hạn."}],"related":[{"hanzi":"默契","pinyin":"mòqì","vi":"ăn ý"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"},{"hanzi":"协作","pinyin":"xiézuò","vi":"hợp tác"}]},{"id":"配偶权","hanzi":"配偶权","pinyin":"pèi'ǒuquán","meaning_vi":"quyền vợ chồng","explanation":"配 (phối hợp/trang bị) + 偶 (ngẫu nhiên/thần tượng) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["danh-tu","phap-luat","gia-dinh"],"image":"💍","examples":[{"type":"basic","zh":"配偶权受法律保护。","pinyin":"Pèi'ǒuquán shòu fǎlǜ bǎohù.","vi":"Quyền vợ chồng được pháp luật bảo vệ."},{"type":"simple","zh":"律师认为第三者的行为侵犯了原告的配偶权。","pinyin":"Lǜshī rènwéi dìsānzhě de xíngwéi qīnfànle yuángào de pèi'ǒuquán.","vi":"Luật sư cho rằng hành vi của người thứ ba đã xâm phạm quyền vợ chồng của nguyên đơn."},{"type":"compound","zh":"虽然法律承认配偶权，但是具体赔偿标准仍有争议。","pinyin":"Suīrán fǎlǜ chéngrèn pèi'ǒuquán, dànshì jùtǐ péicháng biāozhǔn réng yǒuzhēngyì.","vi":"Tuy pháp luật thừa nhận quyền vợ chồng nhưng tiêu chuẩn bồi thường cụ thể vẫn còn tranh cãi."}],"related":[{"hanzi":"配偶","pinyin":"pèi'ǒu","vi":"vợ hoặc chồng"},{"hanzi":"婚姻法","pinyin":"hūnyīnfǎ","vi":"luật hôn nhân"},{"hanzi":"权利","pinyin":"quánlì","vi":"quyền lợi"}],"traditional":"配偶權"},{"id":"陪伴","hanzi":"陪伴","pinyin":"péibàn","meaning_vi":"bầu bạn, ở bên cạnh chăm sóc","explanation":"陪 (bồi – đi cùng) + 伴 (bạn – bạn đồng hành) → bầu bạn, ở bên cạnh. VD: 陪伴家人, 感谢你的陪伴.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🤗","examples":[{"type":"basic","zh":"谢谢你一直陪伴我。","pinyin":"Xièxie nǐ yìzhí péibàn wǒ.","vi":"Cảm ơn bạn đã luôn ở bên tôi."},{"type":"simple","zh":"这只老狗陪伴了爷爷整整十五年。","pinyin":"Zhè zhī lǎo gǒu péibànle yéye zhěngzhěng shíwǔ nián.","vi":"Chú chó già này đã bầu bạn với ông suốt mười lăm năm."},{"type":"compound","zh":"孩子需要的不是昂贵的玩具，而是父母的陪伴。","pinyin":"Háizi xūyào de bú shì ángguì de wánjù, érshì fùmǔ de péibàn.","vi":"Điều trẻ cần không phải là đồ chơi đắt tiền mà là sự bầu bạn của cha mẹ."}],"related":[{"hanzi":"陪同","pinyin":"péitóng","vi":"đi cùng"},{"hanzi":"相伴","pinyin":"xiāngbàn","vi":"bầu bạn"},{"hanzi":"照顾","pinyin":"zhàogù","vi":"chăm sóc"}]},{"id":"赔偿金","hanzi":"赔偿金","pinyin":"péichángjīn","meaning_vi":"tiền bồi thường","explanation":"赔 (bồi thường/thua lỗ) + 偿 (bồi thường/đền đáp) + 金 (金).","hsk_level":"7-9","tags":["danh-tu","tien-te","phap-luat"],"image":"💰","examples":[{"type":"basic","zh":"他拿到了赔偿金。","pinyin":"Tā nádàole péichángjīn.","vi":"Anh ấy đã nhận được tiền bồi thường."},{"type":"simple","zh":"航空公司向每位延误的乘客支付了三百元赔偿金。","pinyin":"Hángkōng gōngsī xiàng měi wèi yánwù de chéngkè zhīfùle sān bǎi yuán péichángjīn.","vi":"Hãng hàng không đã trả ba trăm tệ tiền bồi thường cho mỗi hành khách bị chậm chuyến."},{"type":"compound","zh":"如果公司违法解除合同，就必须支付双倍赔偿金。","pinyin":"Rúguǒ gōngsī wéifǎ jiěchú hétong, jiù bìxū zhīfù shuāngbèi péichángjīn.","vi":"Nếu công ty chấm dứt hợp đồng trái luật thì phải trả gấp đôi tiền bồi thường."}],"related":[{"hanzi":"赔偿","pinyin":"péicháng","vi":"bồi thường"},{"hanzi":"补偿","pinyin":"bǔcháng","vi":"bù đắp"},{"hanzi":"违约金","pinyin":"wéiyuējīn","vi":"tiền phạt vi phạm hợp đồng"}],"traditional":"賠償金"},{"id":"陪衬","hanzi":"陪衬","pinyin":"péichèn","meaning_vi":"làm nền tôn lên","explanation":"陪 (cùng) + 衬 (làm nền/tôn lên).","hsk_level":"7-9","tags":["dong-tu","danh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"绿叶陪衬红花。","pinyin":"Lǜyè péichèn hónghuā.","vi":"Lá xanh làm nền tôn hoa đỏ."},{"type":"simple","zh":"在这部电影里，男二号只是主角的陪衬。","pinyin":"Zài zhè bù diànyǐng lǐ, nán èrhào zhǐshì zhǔjué de péichèn.","vi":"Trong bộ phim này, nam phụ chỉ là người làm nền cho nhân vật chính."},{"type":"compound","zh":"虽然她只是去当陪衬，但是仍然认真准备了每一句台词。","pinyin":"Suīrán tā zhǐshì qù dāng péichèn, dànshì réngrán rènzhēn zhǔnbèile měi yíjù táicí.","vi":"Tuy cô ấy chỉ đi làm nền nhưng vẫn chuẩn bị kỹ từng câu thoại."}],"related":[{"hanzi":"衬托","pinyin":"chèntuō","vi":"làm nổi bật"},{"hanzi":"配角","pinyin":"pèijué","vi":"vai phụ"},{"hanzi":"烘托","pinyin":"hōngtuō","vi":"tôn lên"}],"traditional":"陪襯"},{"id":"培土","hanzi":"培土","pinyin":"péitǔ","meaning_vi":"vun gốc cây","explanation":"培 (bồi dưỡng/nuôi trồng) + 土 (đất đai/bản địa).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌱","examples":[{"type":"basic","zh":"给玉米培土。","pinyin":"Gěi yùmǐ péitǔ.","vi":"Vun gốc cho cây ngô."},{"type":"simple","zh":"爷爷每天清晨都到菜地里给番茄苗培土。","pinyin":"Yéye měitiān qīngchén dōu dào càidì lǐ gěi fānqié miáo péitǔ.","vi":"Sáng sớm nào ông cũng ra vườn rau vun gốc cho cây cà chua con."},{"type":"compound","zh":"如果不及时培土，大风一来幼苗就会倒伏。","pinyin":"Rúguǒ bù jíshí péitǔ, dàfēng yìlái yòumiáo jiù huì dǎofú.","vi":"Nếu không kịp vun gốc thì gió lớn đến là cây non sẽ đổ rạp."}],"related":[{"hanzi":"施肥","pinyin":"shīféi","vi":"bón phân"},{"hanzi":"浇水","pinyin":"jiāoshuǐ","vi":"tưới nước"},{"hanzi":"栽培","pinyin":"zāipéi","vi":"trồng trọt"}]},{"id":"盆景","hanzi":"盆景","pinyin":"pénjǐng","meaning_vi":"cây cảnh bonsai","explanation":"盆 (chậu) + 景 (cảnh).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thien-nhien"],"image":"🪴","examples":[{"type":"basic","zh":"他喜欢养盆景。","pinyin":"Tā xǐhuan yǎng pénjǐng.","vi":"Ông ấy thích chơi cây cảnh bonsai."},{"type":"simple","zh":"这盆造型独特的松树盆景在展会上拿了金奖。","pinyin":"Zhè pén zàoxíng dútè de sōngshù pénjǐng zài zhǎnhuì shàng nále jīnjiǎng.","vi":"Chậu bonsai cây thông có dáng độc đáo này đã đoạt giải vàng tại triển lãm."},{"type":"compound","zh":"盆景虽然体积小，但是能展现山水的意境。","pinyin":"Pénjǐng suīrán tǐjī xiǎo, dànshì néng zhǎnxiàn shānshuǐ de yìjìng.","vi":"Bonsai tuy kích thước nhỏ nhưng có thể thể hiện ý cảnh sơn thủy."}],"related":[{"hanzi":"盆栽","pinyin":"pénzāi","vi":"cây trồng chậu"},{"hanzi":"园艺","pinyin":"yuányì","vi":"làm vườn"},{"hanzi":"花盆","pinyin":"huāpén","vi":"chậu hoa"}]},{"id":"疲于奔命","hanzi":"疲于奔命","pinyin":"píyú-bēnmìng","meaning_vi":"bận rộn chạy đôn chạy đáo mệt nhoài","explanation":"疲 (mệt mỏi) + 于 (ở/đối với) + 奔 (chạy nhanh/bôn ba) + 命 (mệnh lệnh/số phận).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"他每天疲于奔命。","pinyin":"Tā měitiān píyúbēnmìng.","vi":"Ngày nào anh ấy cũng chạy đôn chạy đáo mệt nhoài."},{"type":"simple","zh":"接连不断的投诉让客服人员疲于奔命。","pinyin":"Jiēlián búduàn de tóusù ràng kèfú rényuán píyúbēnmìng.","vi":"Những lời khiếu nại liên tiếp khiến nhân viên chăm sóc khách hàng chạy đôn chạy đáo mệt nhoài."},{"type":"compound","zh":"如果事事都亲力亲为，管理者就会疲于奔命。","pinyin":"Rúguǒ shìshì dōu qīn lì qīn wéi, guǎnlǐ zhě jiù huì píyúbēnmìng.","vi":"Nếu việc gì cũng tự mình làm thì người quản lý sẽ bận rộn đến kiệt sức."}],"related":[{"hanzi":"奔波","pinyin":"bēnbō","vi":"bôn ba"},{"hanzi":"忙碌","pinyin":"mánglù","vi":"bận rộn"},{"hanzi":"焦头烂额","pinyin":"jiāotóulàn'é","vi":"rối bời"}],"traditional":"疲於奔命"},{"id":"皮影戏","hanzi":"皮影戏","pinyin":"píyǐngxì","meaning_vi":"múa rối bóng","explanation":"皮 (da) + 影 (bóng) + 戏 (kịch).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🏮","examples":[{"type":"basic","zh":"孩子们爱看皮影戏。","pinyin":"Háizimen ài kàn píyǐngxì.","vi":"Bọn trẻ thích xem múa rối bóng."},{"type":"simple","zh":"这位老艺人表演皮影戏已经有五十多年了。","pinyin":"Zhè wèi lǎo yìrén biǎoyǎn píyǐngxì yǐjīng yǒu wǔshí duōnián le.","vi":"Nghệ nhân già này đã biểu diễn múa rối bóng hơn năm mươi năm rồi."},{"type":"compound","zh":"灯光一亮，皮影戏里的孙悟空就活灵活现地跳了出来。","pinyin":"Dēngguāng yí liàng, píyǐngxì lǐ de Sūnwùkōng jiù huólínghuóxiàn de tiàole chūlái.","vi":"Đèn vừa sáng, Tôn Ngộ Không trong vở múa rối bóng liền nhảy ra sống động như thật."}],"related":[{"hanzi":"木偶戏","pinyin":"mù'ǒuxì","vi":"múa rối"},{"hanzi":"剪纸","pinyin":"jiǎnzhǐ","vi":"cắt giấy"},{"hanzi":"民间艺术","pinyin":"mínjiānyìshù","vi":"nghệ thuật dân gian"}],"traditional":"皮影戲"},{"id":"贫富差距","hanzi":"贫富差距","pinyin":"pínfùchājù","meaning_vi":"khoảng cách giàu nghèo","explanation":"贫 (nghèo nàn/cằn cỗi) + 富 (giàu) + 差 (chênh lệch/sai sót) + 距 (距).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","tien-te"],"image":"⚖️","examples":[{"type":"basic","zh":"贫富差距在扩大。","pinyin":"Pínfùchājù zài kuòdà.","vi":"Khoảng cách giàu nghèo đang gia tăng."},{"type":"simple","zh":"这份报告详细分析了城乡之间的贫富差距。","pinyin":"Zhè fèn bàogào xiángxì fēnxīle chéngxiāng zhījiān de pínfùchājù.","vi":"Bản báo cáo này phân tích chi tiết khoảng cách giàu nghèo giữa thành thị và nông thôn."},{"type":"compound","zh":"贫富差距一旦过大，社会矛盾就容易激化。","pinyin":"Pínfùchājù yídànguò dà, shèhuì máodùn jiù róngyì jīhuà.","vi":"Một khi khoảng cách giàu nghèo quá lớn, mâu thuẫn xã hội sẽ dễ trở nên gay gắt."}],"related":[{"hanzi":"两极分化","pinyin":"liǎngjífēnhuà","vi":"phân hóa hai cực"},{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"},{"hanzi":"共同富裕","pinyin":"gòngtóngfùyù","vi":"cùng giàu có"}],"traditional":"貧富差距"},{"id":"频频","hanzi":"频频","pinyin":"pínpín","meaning_vi":"liên tục, hết lần này đến lần khác","explanation":"频 (thường xuyên/tần suất) + 频 (thường xuyên/tần suất).","hsk_level":"7-9","tags":["pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"他频频点头。","pinyin":"Tā pínpín diǎntóu.","vi":"Anh ấy liên tục gật đầu."},{"type":"simple","zh":"这位新秀在决赛中频频失误。","pinyin":"Zhè wèi xīnxiù zài juésài zhōng pínpín shīwù.","vi":"Tân binh này liên tục mắc lỗi trong trận chung kết."},{"type":"compound","zh":"因为这一路段事故频频发生，所以交警加装了测速摄像头。","pinyin":"Yīnwèi zhè yí lùduàn shìgù pínpín fāshēng, suǒyǐ jiāojǐng jiā zhuāngle cèsù shèxiàngtóu.","vi":"Vì đoạn đường này liên tục xảy ra tai nạn nên cảnh sát giao thông đã lắp thêm camera bắn tốc độ."}],"related":[{"hanzi":"频繁","pinyin":"pínfán","vi":"thường xuyên"},{"hanzi":"屡次","pinyin":"lǚcì","vi":"nhiều lần"},{"hanzi":"接连","pinyin":"jiēlián","vi":"liên tiếp"}],"traditional":"頻頻"},{"id":"贫穷","hanzi":"贫穷","pinyin":"pínqióng","meaning_vi":"nghèo khổ","explanation":"贫 (nghèo nàn/cằn cỗi) + 穷 (nghèo).","hsk_level":"7-9","tags":["tinh-tu"],"image":"💸","examples":[{"type":"basic","zh":"他出身贫穷。","pinyin":"Tā chūshēn pínqióng.","vi":"Anh ấy xuất thân nghèo khó."},{"type":"simple","zh":"这个基金会致力于帮助贫穷地区的女孩上学。","pinyin":"Zhè ge jījīnhuì zhìlìyú bāngzhù pínqióng dìqū de nǚhái shàngxué.","vi":"Quỹ này tận lực giúp các bé gái ở vùng nghèo khó được đến trường."},{"type":"compound","zh":"虽然童年很贫穷，但是他从未放弃读书的梦想。","pinyin":"Suīrán tóngnián hěn pínqióng, dànshì tā cóngwèi fàngqì dúshū de mèngxiǎng.","vi":"Tuy tuổi thơ rất nghèo khổ nhưng anh ấy chưa bao giờ từ bỏ ước mơ đi học."}],"related":[{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"},{"hanzi":"穷人","pinyin":"qióngrén","vi":"người nghèo"}],"traditional":"貧窮"},{"id":"平白无故","hanzi":"平白无故","pinyin":"píngbái-wúgù","meaning_vi":"vô duyên vô cớ","explanation":"平 (bằng phẳng) + 白 (màu trắng) + 无 (không có) + 故 (故).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"❓","examples":[{"type":"basic","zh":"他平白无故发火。","pinyin":"Tā píngbáiwúgù fāhuǒ.","vi":"Anh ta nổi giận vô duyên vô cớ."},{"type":"simple","zh":"我的银行卡平白无故被扣了两百块钱。","pinyin":"Wǒ de yínhángkǎ píngbáiwúgù bèi kòule liǎng bǎi kuài qián.","vi":"Thẻ ngân hàng của tôi vô duyên vô cớ bị trừ mất hai trăm tệ."},{"type":"compound","zh":"既然他平白无故地冤枉你，你就应该要求他道歉。","pinyin":"Jìrán tā píngbáiwúgù de yuānwang nǐ, nǐ jiù yīnggāi yāoqiú tā dàoqiàn.","vi":"Anh ta đã vô cớ đổ oan cho bạn thì bạn nên yêu cầu anh ta xin lỗi."}],"related":[{"hanzi":"无缘无故","pinyin":"wúyuánwúgù","vi":"vô duyên vô cớ"},{"hanzi":"莫名其妙","pinyin":"mòmíngqímiào","vi":"không hiểu ra sao"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"}],"traditional":"平白無故"},{"id":"凭借","hanzi":"凭借","pinyin":"píngjiè","meaning_vi":"dựa vào, nhờ vào","explanation":"凭 (dựa vào) + 借 (mượn).","hsk_level":"7-9","tags":["gioi-tu","dong-tu"],"image":"🧱","examples":[{"type":"basic","zh":"她凭借实力获胜。","pinyin":"Tā píngjiè shílì huòshèng.","vi":"Cô ấy giành chiến thắng nhờ thực lực."},{"type":"simple","zh":"这部小成本电影凭借真实的故事打动了观众。","pinyin":"Zhè bù xiǎo chéngběn diànyǐng píngjiè zhēnshí de gùshi dǎdòngle guānzhòng.","vi":"Bộ phim kinh phí thấp này đã chạm đến trái tim khán giả nhờ câu chuyện chân thực."},{"type":"compound","zh":"即使没有人脉，他也能凭借专业能力找到好工作。","pinyin":"Jíshǐ méiyǒu rénmài, tā yě néng píngjiè zhuānyè nénglì zhǎodào hǎo gōngzuò.","vi":"Cho dù không có quan hệ, anh ấy vẫn có thể nhờ năng lực chuyên môn mà tìm được việc tốt."}],"related":[{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"借助","pinyin":"jièzhù","vi":"nhờ vào"},{"hanzi":"凭","pinyin":"píng","vi":"dựa vào"}],"traditional":"憑藉"},{"id":"瓶颈","hanzi":"瓶颈","pinyin":"píngjǐng","meaning_vi":"nút thắt cổ chai, điểm nghẽn phát triển","explanation":"瓶 (cái bình/chai) + 颈 (cái cổ).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🍾","examples":[{"type":"basic","zh":"研究遇到了瓶颈。","pinyin":"Yánjiū yùdàole píngjǐng.","vi":"Nghiên cứu đã gặp phải nút thắt."},{"type":"simple","zh":"芯片短缺成了这家车企扩大产能的最大瓶颈。","pinyin":"Xīnpiàn duǎnquē chéngle zhè jiā chē qǐ kuòdà chǎnnéng de zuì dà píngjǐng.","vi":"Thiếu hụt chip đã trở thành điểm nghẽn lớn nhất trong việc mở rộng công suất của hãng xe này."},{"type":"compound","zh":"只要突破了技术瓶颈，产品成本就能大幅下降。","pinyin":"Zhǐyào tūpòle jìshù píngjǐng, chǎnpǐn chéngběn jiù néng dàfú xiàjiàng.","vi":"Chỉ cần vượt qua nút thắt kỹ thuật thì giá thành sản phẩm có thể giảm mạnh."}],"related":[{"hanzi":"障碍","pinyin":"zhàng'ài","vi":"trở ngại"},{"hanzi":"突破","pinyin":"tūpò","vi":"đột phá"},{"hanzi":"难题","pinyin":"nántí","vi":"vấn đề khó"}],"traditional":"瓶頸"},{"id":"评判","hanzi":"评判","pinyin":"píngpàn","meaning_vi":"phán xét, đánh giá","explanation":"评 (đánh giá/bình luận) + 判 (phán quyết/xét xử).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"请大家公正评判。","pinyin":"Qǐng dàjiā gōngzhèng píngpàn.","vi":"Mời mọi người đánh giá công bằng."},{"type":"simple","zh":"我们不能只用分数来评判一个学生的好坏。","pinyin":"Wǒmen bù néng zhǐ yòng fēnshù lái píngpàn yí gè xuéshēng de hǎohuài.","vi":"Chúng ta không thể chỉ dùng điểm số để đánh giá một học sinh tốt hay xấu."},{"type":"compound","zh":"既然你不了解全部真相，就不要轻易评判别人。","pinyin":"Jìrán nǐ bù liǎojiě quánbù zhēnxiàng, jiù bú yào qīngyì píngpàn biérén.","vi":"Đã không hiểu hết sự thật thì đừng vội phán xét người khác."}],"related":[{"hanzi":"评价","pinyin":"píngjià","vi":"đánh giá"},{"hanzi":"判断","pinyin":"pànduàn","vi":"phán đoán"},{"hanzi":"评委","pinyin":"píngwěi","vi":"giám khảo"}],"traditional":"評判"},{"id":"平起平坐","hanzi":"平起平坐","pinyin":"píngqǐ-píngzuò","meaning_vi":"ngang hàng ngang vế","explanation":"平 (bằng phẳng) + 起 (khởi nguồn/trỗi dậy) + 平 (bằng phẳng) + 坐 (ngồi).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"他们平起平坐。","pinyin":"Tāmen píngqǐpíngzuò.","vi":"Họ ngang hàng ngang vế với nhau."},{"type":"simple","zh":"这家小公司终于能和行业巨头平起平坐了。","pinyin":"Zhè jiā xiǎo gōngsī zhōngyú néng hé hángyè jùtóu píngqǐpíngzuò le.","vi":"Công ty nhỏ này cuối cùng đã có thể ngang hàng với các ông lớn trong ngành."},{"type":"compound","zh":"虽然他只是实习生，但是开会时大家与他平起平坐。","pinyin":"Suīrán tā zhǐshì shíxíshēng, dànshì kāihuì shí dàjiā yǔ tā píngqǐpíngzuò.","vi":"Tuy cậu ấy chỉ là thực tập sinh nhưng khi họp mọi người đều đối xử ngang hàng với cậu."}],"related":[{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"不分上下","pinyin":"bùfēnshàngxià","vi":"ngang nhau"},{"hanzi":"高低贵贱","pinyin":"gāodīguìjiàn","vi":"sang hèn cao thấp"}]},{"id":"评委","hanzi":"评委","pinyin":"píngwěi","meaning_vi":"ban giám khảo","explanation":"评 (đánh giá/bình luận) + 委 (ủy thác/ấm ức).","hsk_level":"7-9","tags":["danh-tu","giai-tri","con-nguoi"],"image":"📋","examples":[{"type":"basic","zh":"评委打了高分。","pinyin":"Píngwěi dǎle gāofēn.","vi":"Giám khảo đã cho điểm cao."},{"type":"simple","zh":"这次歌唱比赛请来了五位知名音乐人担任评委。","pinyin":"Zhè cì gēchàng bǐsài qǐng láile wǔ wèi zhīmíng yīnyuè rén dānrèn píngwěi.","vi":"Cuộc thi ca hát lần này đã mời năm nhạc sĩ nổi tiếng làm giám khảo."},{"type":"compound","zh":"评委如果和选手有亲属关系，就必须主动回避。","pinyin":"Píngwěi rúguǒ hé xuǎnshǒu yǒu qīnshǔ guānxì, jiù bìxū zhǔdòng huíbì.","vi":"Nếu giám khảo có quan hệ họ hàng với thí sinh thì phải chủ động rút lui."}],"related":[{"hanzi":"评审","pinyin":"píngshěn","vi":"thẩm định"},{"hanzi":"裁判","pinyin":"cáipàn","vi":"trọng tài"},{"hanzi":"评分","pinyin":"píngfēn","vi":"chấm điểm"}],"traditional":"評委"},{"id":"平心而论","hanzi":"平心而论","pinyin":"píngxīn-érlùn","meaning_vi":"công tâm mà nói","explanation":"平 (bằng phẳng) + 心 (tâm lý/tâm huyết) + 而 (mà) + 论 (luận văn/bàn luận).","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"⚖️","examples":[{"type":"basic","zh":"平心而论，他没错。","pinyin":"Píngxīn'érlùn, tā méicuò.","vi":"Công tâm mà nói, anh ấy không sai."},{"type":"simple","zh":"平心而论，这家餐厅的服务确实无可挑剔。","pinyin":"Píngxīn'érlùn, zhè jiā cāntīng de fúwù quèshí wúkě tiāotī.","vi":"Công tâm mà nói, dịch vụ của nhà hàng này quả thực không chê vào đâu được."},{"type":"compound","zh":"平心而论，这个方案虽然成本高，但是效果最好。","pinyin":"Píngxīn'érlùn, zhè ge fāng'àn suīrán chéngběn gāo, dànshì xiàoguǒ zuìhǎo.","vi":"Công tâm mà nói, phương án này tuy chi phí cao nhưng hiệu quả tốt nhất."}],"related":[{"hanzi":"客观","pinyin":"kèguān","vi":"khách quan"},{"hanzi":"公正","pinyin":"gōngzhèng","vi":"công bằng"},{"hanzi":"说实话","pinyin":"shuōshíhuà","vi":"nói thật"}],"traditional":"平心而論"},{"id":"平庸之辈","hanzi":"平庸之辈","pinyin":"píngyōngzhībèi","meaning_vi":"kẻ tầm thường","explanation":"平 (bằng phẳng) + 庸 (tầm thường) + 之 (của (trợ từ văn viết)) + 辈 (thế hệ).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"😐","examples":[{"type":"basic","zh":"他绝非平庸之辈。","pinyin":"Tā juéfēi píngyōngzhībèi.","vi":"Anh ấy tuyệt đối không phải kẻ tầm thường."},{"type":"simple","zh":"能在这次选拔中胜出的选手绝不是平庸之辈。","pinyin":"Néng zài zhè cì xuǎnbá zhōng shèngchū de xuǎnshǒu juébú shì píngyōngzhībèi.","vi":"Những thí sinh có thể chiến thắng trong đợt tuyển chọn này tuyệt đối không phải hạng tầm thường."},{"type":"compound","zh":"如果不肯走出舒适区，再聪明的人也会沦为平庸之辈。","pinyin":"Rúguǒ bùkěn zǒuchū shūshìqū, zài cōngmíng de rén yě huì lúnwéi píngyōngzhībèi.","vi":"Nếu không chịu bước ra khỏi vùng an toàn thì người thông minh đến đâu cũng sẽ trở thành kẻ tầm thường."}],"related":[{"hanzi":"平庸","pinyin":"píngyōng","vi":"tầm thường"},{"hanzi":"无名小卒","pinyin":"wúmíngxiǎozú","vi":"kẻ vô danh"},{"hanzi":"佼佼者","pinyin":"jiǎojiǎozhě","vi":"người xuất sắc"}],"traditional":"平庸之輩"},{"id":"评语","hanzi":"评语","pinyin":"píngyǔ","meaning_vi":"lời phê, nhận xét","explanation":"评 (đánh giá/bình luận) + 语 (ngôn ngữ/lời nói).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"老师写了评语。","pinyin":"Lǎoshī xiěle píngyǔ.","vi":"Thầy giáo đã viết lời phê."},{"type":"simple","zh":"班主任在成绩单上给每个学生写了一段评语。","pinyin":"Bānzhǔrèn zài chéngjìdān shàng gěi měi gè xuéshēng xiěle yí duàn píngyǔ.","vi":"Giáo viên chủ nhiệm đã viết một đoạn nhận xét cho mỗi học sinh trên bảng điểm."},{"type":"compound","zh":"虽然评语只有短短一句，但是让我备受鼓舞。","pinyin":"Suīrán píngyǔ zhǐyǒu duǎn duǎn yíjù, dànshì ràng wǒ bèishòu gǔwǔ.","vi":"Tuy lời phê chỉ có một câu ngắn ngủi nhưng đã khiến tôi được khích lệ rất nhiều."}],"related":[{"hanzi":"评价","pinyin":"píngjià","vi":"đánh giá"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"},{"hanzi":"批语","pinyin":"pīyǔ","vi":"lời phê"}],"traditional":"評語"},{"id":"破产清算","hanzi":"破产清算","pinyin":"pòchǎnqīngsuàn","meaning_vi":"thanh lý phá sản","explanation":"破产 (phá sản) + 清算 (thanh toán – thanh lý) → thanh lý tài sản doanh nghiệp phá sản để trả nợ. VD: 进入破产清算程序.","hsk_level":"7-9","tags":["danh-tu","phap-luat","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"公司进入破产清算。","pinyin":"Gōngsī jìnrù pòchǎnqīngsuàn.","vi":"Công ty bước vào giai đoạn thanh lý phá sản."},{"type":"simple","zh":"法院正式受理了这家房企的破产清算申请。","pinyin":"Fǎyuàn zhèngshì shòulǐle zhè jiā fáng qǐ de pòchǎnqīngsuàn shēnqǐng.","vi":"Tòa án đã chính thức thụ lý đơn xin thanh lý phá sản của doanh nghiệp bất động sản này."},{"type":"compound","zh":"一旦进入破产清算程序，员工工资就会被优先支付。","pinyin":"Yídàn jìnrù pòchǎnqīngsuàn chéngxù, yuángōng gōngzī jiù huì bèi yōuxiān zhīfù.","vi":"Một khi bước vào thủ tục thanh lý phá sản, lương của nhân viên sẽ được ưu tiên chi trả."}],"related":[{"hanzi":"破产","pinyin":"pòchǎn","vi":"phá sản"},{"hanzi":"清算","pinyin":"qīngsuàn","vi":"thanh toán"},{"hanzi":"倒闭","pinyin":"dǎobì","vi":"đóng cửa"}],"traditional":"破產清算"},{"id":"破格","hanzi":"破格","pinyin":"pògé","meaning_vi":"phá lệ, vượt cấp (đề bạt/tuyển dụng)","explanation":"破 (phá – phá bỏ) + 格 (cách – quy cách, khuôn khổ) → phá lệ, vượt khuôn phép thông thường. VD: 破格录取, 破格提拔.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"他被破格提拔了。","pinyin":"Tā bèi pògé tíbá le.","vi":"Anh ấy đã được đề bạt phá lệ."},{"type":"simple","zh":"这所大学破格录取了一位数学天才少年。","pinyin":"Zhè suǒ dàxué pògé lùqǔle yí wèi shùxué tiāncái shàonián.","vi":"Trường đại học này đã phá lệ tuyển một thiếu niên thiên tài toán học."},{"type":"compound","zh":"因为她的研究成果突出，所以被破格晋升为教授。","pinyin":"Yīnwèi tā de yánjiū chéngguǒ tūchū, suǒyǐ bèi pògé jìnshēng wéi jiàoshòu.","vi":"Vì thành quả nghiên cứu nổi bật nên cô ấy được phá lệ thăng chức giáo sư."}],"related":[{"hanzi":"破例","pinyin":"pòlì","vi":"phá lệ"},{"hanzi":"越级","pinyin":"yuèjí","vi":"vượt cấp"},{"hanzi":"提拔","pinyin":"tíbá","vi":"đề bạt"}]},{"id":"破旧","hanzi":"破旧","pinyin":"pòjiù","meaning_vi":"cũ nát, rách nát","explanation":"破 (rách) + 旧 (cũ).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🏚️","examples":[{"type":"basic","zh":"这件外套很破旧。","pinyin":"Zhè jiàn wàitào hěn pòjiù.","vi":"Chiếc áo khoác này rất cũ nát."},{"type":"simple","zh":"那栋破旧的老楼明年就要被拆除了。","pinyin":"Nà dòng pòjiù de lǎo lóu míngnián jiùyào bèi chāi chúle.","vi":"Tòa nhà cũ nát đó năm sau sẽ bị phá dỡ."},{"type":"compound","zh":"这辆自行车虽然破旧，但是陪我走过了整个大学时光。","pinyin":"Zhè liàng zìxíngchē suīrán pòjiù, dànshì péi wǒ zǒuguòle zhěnggè dàxué shíguāng.","vi":"Chiếc xe đạp này tuy cũ nát nhưng đã cùng tôi đi qua suốt thời đại học."}],"related":[{"hanzi":"陈旧","pinyin":"chénjiù","vi":"cũ kỹ"},{"hanzi":"破烂","pinyin":"pòlàn","vi":"rách nát"},{"hanzi":"崭新","pinyin":"zhǎnxīn","vi":"mới tinh"}],"traditional":"破舊"},{"id":"破解","hanzi":"破解","pinyin":"pòjiě","meaning_vi":"giải mã, hóa giải (bài toán khó)","explanation":"破 (rách) + 解 (giải quyết/hiểu).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🔓","examples":[{"type":"basic","zh":"密码被破解了。","pinyin":"Mìmǎ bèi pòjiě le.","vi":"Mật khẩu đã bị bẻ khóa."},{"type":"simple","zh":"科学家们终于破解了这种古老文字的含义。","pinyin":"Kēxuéjiāmen zhōngyú pòjiěle zhè zhǒng gǔlǎo wénzì de hányì.","vi":"Các nhà khoa học cuối cùng đã giải mã được ý nghĩa của loại chữ cổ này."},{"type":"compound","zh":"只要找到关键线索，这个谜团就能被破解。","pinyin":"Zhǐyào zhǎodào guānjiàn xiànsuǒ, zhè ge mítuán jiù néng bèi pòjiě.","vi":"Chỉ cần tìm ra manh mối then chốt thì bí ẩn này có thể được giải đáp."}],"related":[{"hanzi":"解开","pinyin":"jiěkāi","vi":"mở ra"},{"hanzi":"破译","pinyin":"pòyì","vi":"giải mã"},{"hanzi":"难题","pinyin":"nántí","vi":"vấn đề khó"}]},{"id":"破纪录","hanzi":"破纪录","pinyin":"pòjìlù","meaning_vi":"phá kỷ lục","explanation":"破 (rách) + 纪 (kỷ luật/kỷ niệm) + 录 (ghi chép/tuyển dụng).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"她又破纪录了。","pinyin":"Tā yòu pòjìlù le.","vi":"Cô ấy lại phá kỷ lục rồi."},{"type":"simple","zh":"今年夏天的最高气温破纪录地达到了四十二度。","pinyin":"Jīnnián xiàtiān de zuì gāo qìwēn pòjìlù de dádàole sìshí èrdù.","vi":"Nhiệt độ cao nhất mùa hè năm nay đạt mức kỷ lục bốn mươi hai độ."},{"type":"compound","zh":"如果这次能破纪录，他就会成为最年轻的世界冠军。","pinyin":"Rúguǒ zhè cì néng pòjìlù, tā jiù huì chéngwéi zuì niánqīng de shìjiè guànjūn.","vi":"Nếu lần này phá được kỷ lục, anh ấy sẽ trở thành nhà vô địch thế giới trẻ nhất."}],"related":[{"hanzi":"纪录","pinyin":"jìlù","vi":"kỷ lục"},{"hanzi":"打破","pinyin":"dǎpò","vi":"phá vỡ"},{"hanzi":"刷新纪录","pinyin":"shuāxīnjìlù","vi":"lập kỷ lục mới"}],"traditional":"破紀錄"},{"id":"破天荒","hanzi":"破天荒","pinyin":"pòtiānhuāng","meaning_vi":"chưa từng có từ trước tới nay","explanation":"破 (rách) + 天 (ngày) + 荒 (hoang vắng/hoang đường).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他破天荒地道歉了。","pinyin":"Tā pòtiānhuāng dedào qiàn le.","vi":"Lần đầu tiên từ trước đến nay anh ta xin lỗi."},{"type":"simple","zh":"一向节俭的爸爸破天荒地请全家吃了顿大餐。","pinyin":"Yíxiàng jiéjiǎn de bàba pòtiānhuāng de qǐng quánjiā chīle dùn dàcān.","vi":"Người bố vốn tiết kiệm lần đầu tiên mời cả nhà đi ăn một bữa thịnh soạn."},{"type":"compound","zh":"这个小镇虽然一向冷清，今年却破天荒地迎来了上万游客。","pinyin":"Zhè ge xiǎozhèn suīrán yíxiàng lěngqīng, jīnnián què pòtiānhuāng de yíngláile shàngwàn yóukè.","vi":"Thị trấn nhỏ này tuy xưa nay vắng vẻ, nhưng năm nay lần đầu tiên đón tới hàng vạn du khách."}],"related":[{"hanzi":"史无前例","pinyin":"shǐwúqiánlì","vi":"chưa từng có"},{"hanzi":"头一回","pinyin":"tóuyìhuí","vi":"lần đầu tiên"},{"hanzi":"空前","pinyin":"kōngqián","vi":"chưa từng có"}]},{"id":"攀升","hanzi":"攀升","pinyin":"pānshēng","meaning_vi":"tăng vọt lên cao (giá cả/nhiệt độ)","explanation":"攀 (leo trèo/so bì) + 升 (tăng lên).","hsk_level":"7-9","tags":["dong-tu","so-luong"],"image":"📈","examples":[{"type":"basic","zh":"房价持续攀升。","pinyin":"Fángjià chíxù pānshēng.","vi":"Giá nhà liên tục tăng vọt."},{"type":"simple","zh":"这款手机的销量在上市后一路攀升。","pinyin":"Zhè kuǎn shǒujī de xiāoliàng zài shàngshì hòu yílù pānshēng.","vi":"Doanh số của mẫu điện thoại này tăng vọt liên tục sau khi ra mắt."},{"type":"compound","zh":"气温一旦攀升到三十八度，学校就会停止户外活动。","pinyin":"Qìwēn yídàn pānshēng dào sānshí bādù, xuéxiào jiù huì tíngzhǐ hùwài huódòng.","vi":"Một khi nhiệt độ tăng lên ba mươi tám độ, trường học sẽ ngừng hoạt động ngoài trời."}],"related":[{"hanzi":"上升","pinyin":"shàngshēng","vi":"tăng lên"},{"hanzi":"攀登","pinyin":"pāndēng","vi":"leo trèo"},{"hanzi":"下滑","pinyin":"xiàhuá","vi":"trượt giảm"}]},{"id":"喷发","hanzi":"喷发","pinyin":"pēnfā","meaning_vi":"phun trào (núi lửa/cảm xúc)","explanation":"喷 (phun trào) + 发 (发).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌋","examples":[{"type":"basic","zh":"火山突然喷发了。","pinyin":"Huǒshān tūrán pēnfā le.","vi":"Núi lửa đột nhiên phun trào."},{"type":"simple","zh":"这座沉睡百年的火山昨夜再次喷发。","pinyin":"Zhè zuò chénshuì bǎinián de huǒshān zuóyè zàicì pēnfā.","vi":"Ngọn núi lửa ngủ yên trăm năm này đêm qua lại phun trào."},{"type":"compound","zh":"压抑多年的情绪一旦喷发，就很难收拾。","pinyin":"Yāyì duōnián de qíngxù yídàn pēnfā, jiù hěn nán shōushi.","vi":"Cảm xúc bị dồn nén nhiều năm một khi bùng phát thì rất khó kiềm chế."}],"related":[{"hanzi":"爆发","pinyin":"bàofā","vi":"bùng nổ"},{"hanzi":"火山","pinyin":"huǒshān","vi":"núi lửa"},{"hanzi":"喷射","pinyin":"pēnshè","vi":"phun ra"}],"traditional":"噴發"},{"id":"烹饪技巧","hanzi":"烹饪技巧","pinyin":"pēngrènjìqiǎo","meaning_vi":"kỹ năng nấu nướng","explanation":"烹 (nấu nướng) + 饪 (饪) + 技 (kỹ thuật) + 巧 (巧).","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"👨‍🍳","examples":[{"type":"basic","zh":"她的烹饪技巧很高。","pinyin":"Tā de pēngrènjìqiǎo hěn gāo.","vi":"Kỹ năng nấu nướng của cô ấy rất giỏi."},{"type":"simple","zh":"这档节目每周教观众一种简单实用的烹饪技巧。","pinyin":"Zhè dàng jiémù měizhōu jiāo guānzhòng yì zhǒng jiǎndān shíyòng de pēngrènjìqiǎo.","vi":"Chương trình này mỗi tuần dạy khán giả một kỹ năng nấu nướng đơn giản và thiết thực."},{"type":"compound","zh":"只要掌握了烹饪技巧，普通的食材也能做出美味。","pinyin":"Zhǐyào zhǎngwòle pēngrènjìqiǎo, pǔtōng de shícái yě néng zuòchū měiwèi.","vi":"Chỉ cần nắm được kỹ năng nấu nướng thì nguyên liệu bình thường cũng có thể làm ra món ngon."}],"related":[{"hanzi":"烹饪","pinyin":"pēngrèn","vi":"nấu nướng"},{"hanzi":"厨艺","pinyin":"chúyì","vi":"tài nấu ăn"},{"hanzi":"厨师","pinyin":"chúshī","vi":"đầu bếp"}],"traditional":"烹飪技巧"},{"id":"捧腹大笑","hanzi":"捧腹大笑","pinyin":"pěngfù-dàxiào","meaning_vi":"cười ôm bụng, cười nghiêng ngả","explanation":"捧 (bưng) + 腹 (腹) + 大 (to) + 笑 (cười).","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😂","examples":[{"type":"basic","zh":"观众捧腹大笑。","pinyin":"Guānzhòng pěngfùdàxiào.","vi":"Khán giả cười ôm bụng."},{"type":"simple","zh":"爷爷讲的童年糗事让全家人捧腹大笑。","pinyin":"Yéye jiǎng de tóngnián qiǔshì ràng quán jiārén pěngfùdàxiào.","vi":"Chuyện xấu hổ thời thơ ấu ông kể khiến cả nhà cười ôm bụng."},{"type":"compound","zh":"他一开口模仿老师的口音，同学们就捧腹大笑。","pinyin":"Tā yì kāikǒu mófǎng lǎoshī de kǒuyīn, tóngxuémen jiù pěngfùdàxiào.","vi":"Cậu ấy vừa mở miệng bắt chước giọng thầy giáo, cả lớp đã cười nghiêng ngả."}],"related":[{"hanzi":"哈哈大笑","pinyin":"hāhādàxiào","vi":"cười ha hả"},{"hanzi":"笑掉大牙","pinyin":"xiàodiàodàyá","vi":"cười rụng răng"},{"hanzi":"忍俊不禁","pinyin":"rěnjùnbùjīn","vi":"không nhịn được cười"}]},{"id":"披荆斩棘","hanzi":"披荆斩棘","pinyin":"pījīng-zhǎnjí","meaning_vi":"vượt mọi chông gai mở đường tiến tới","explanation":"披 (khoác (áo/khăn lên vai)) + 荆 (gai góc) + 斩 (chặt đứt/dứt khoát) + 棘 (gai góc/hóc búa).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚔️","examples":[{"type":"basic","zh":"他们披荆斩棘前进。","pinyin":"Tāmen pījīngzhǎnjí qiánjìn.","vi":"Họ vượt mọi chông gai tiến lên."},{"type":"simple","zh":"创业初期，这支团队披荆斩棘地开拓了海外市场。","pinyin":"Chuàngyè chūqī, zhè zhī tuánduì pījīngzhǎnjí de kāituòle hǎiwài shìchǎng.","vi":"Thời kỳ đầu khởi nghiệp, đội ngũ này đã vượt mọi chông gai để mở rộng thị trường nước ngoài."},{"type":"compound","zh":"前路虽然坎坷，但是我们会披荆斩棘，勇往直前。","pinyin":"Qiánlù suīrán kǎnkě, dànshì wǒmen huì pījīngzhǎnjí, yǒngwǎngzhíqián.","vi":"Con đường phía trước tuy gập ghềnh, nhưng chúng ta sẽ vượt mọi chông gai, dũng cảm tiến lên."}],"related":[{"hanzi":"艰苦奋斗","pinyin":"jiānkǔfèndòu","vi":"gian khổ phấn đấu"},{"hanzi":"开拓","pinyin":"kāituò","vi":"khai phá"},{"hanzi":"克服困难","pinyin":"kèfúkùnnan","vi":"khắc phục khó khăn"}],"traditional":"披荊斬棘"},{"id":"批量","hanzi":"批量","pinyin":"pīliàng","meaning_vi":"số lượng lớn, hàng loạt","explanation":"批 (phê duyệt) + 量 (đo lường/số lượng).","hsk_level":"7-9","tags":["danh-tu","cong-viec","so-luong"],"image":"📦","examples":[{"type":"basic","zh":"这款零件将批量生产。","pinyin":"Zhè kuǎn língjiàn jiāng pīliàng shēngchǎn.","vi":"Linh kiện này sẽ được sản xuất hàng loạt."},{"type":"simple","zh":"新系统可以批量处理上千张发票。","pinyin":"Xīn xìtǒng kěyǐ pīliàng chǔlǐ shàng qiān zhāng fāpiào.","vi":"Hệ thống mới có thể xử lý hàng loạt hàng nghìn hóa đơn."},{"type":"compound","zh":"如果餐厅批量采购蔬菜，单价就能便宜两成。","pinyin":"Rúguǒ cāntīng pīliàng cǎigòu shūcài, dānjià jiù néng piányi liǎng chéng.","vi":"Nếu nhà hàng mua rau với số lượng lớn thì đơn giá có thể rẻ đi hai mươi phần trăm."}],"related":[{"hanzi":"大批","pinyin":"dàpī","vi":"số lượng lớn"},{"hanzi":"批量生产","pinyin":"pīliàngshēngchǎn","vi":"sản xuất hàng loạt"},{"hanzi":"批发","pinyin":"pīfā","vi":"bán buôn"}]},{"id":"批示","hanzi":"批示","pinyin":"pīshì","meaning_vi":"phê duyệt chỉ thị (của lãnh đạo)","explanation":"批 (phê duyệt) + 示 (biểu thị/ra hiệu).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✍️","examples":[{"type":"basic","zh":"局长已经批示了。","pinyin":"Júzhǎng yǐjīng pīshì le.","vi":"Cục trưởng đã phê duyệt rồi."},{"type":"simple","zh":"市长在报告上批示要求尽快修复这座危桥。","pinyin":"Shìzhǎng zài bàogào shàng pīshì yāoqiú jìnkuài xiūfù zhè zuò wēi qiáo.","vi":"Thị trưởng phê chỉ thị trên báo cáo, yêu cầu nhanh chóng sửa chữa cây cầu nguy hiểm này."},{"type":"compound","zh":"领导一批示，相关部门就立即着手调查。","pinyin":"Lǐngdǎo yì pīshì, xiāngguān bùmén jiù lìjí zhuóshǒu diàochá.","vi":"Lãnh đạo vừa phê chỉ thị, các ban ngành liên quan liền lập tức bắt tay vào điều tra."}],"related":[{"hanzi":"批准","pinyin":"pīzhǔn","vi":"phê chuẩn"},{"hanzi":"指示","pinyin":"zhǐshì","vi":"chỉ thị"},{"hanzi":"审批","pinyin":"shěnpī","vi":"xét duyệt"}]},{"id":"拼凑","hanzi":"拼凑","pinyin":"pīncòu","meaning_vi":"chắp vá, gom góp tạm bợ","explanation":"拼 (phấn đấu/ghép lại) + 凑 (gom góp/tạm bợ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"这篇文章是拼凑的。","pinyin":"Zhè piān wénzhāng shì pīncòu de.","vi":"Bài viết này là chắp vá mà thành."},{"type":"simple","zh":"警方根据目击者的描述拼凑出了案发经过。","pinyin":"Jǐngfāng gēnjù mùjīzhě de miáoshù pīncòu chūle ànfā jīngguò.","vi":"Cảnh sát dựa vào lời mô tả của nhân chứng để ghép nối lại diễn biến vụ án."},{"type":"compound","zh":"我们虽然只是临时拼凑的队伍，但是最后拿了亚军。","pinyin":"Wǒmen suīrán zhǐshì línshí pīncòu de duìwu, dànshì zuìhòu nále yàjūn.","vi":"Tuy chúng tôi chỉ là đội gom góp tạm bợ nhưng cuối cùng đã giành giải nhì."}],"related":[{"hanzi":"凑合","pinyin":"còuhe","vi":"tạm bợ"},{"hanzi":"东拼西凑","pinyin":"dōngpīnxīcòu","vi":"chắp vá"},{"hanzi":"拼接","pinyin":"pīnjiē","vi":"ghép nối"}],"traditional":"拼湊"},{"id":"拼图","hanzi":"拼图","pinyin":"pīntú","meaning_vi":"trò chơi ghép hình","explanation":"拼 (phấn đấu/ghép lại) + 图 (mưu đồ/bản đồ).","hsk_level":"7-9","tags":["danh-tu","giai-tri","do-vat"],"image":"🧩","examples":[{"type":"basic","zh":"我们一起玩拼图吧。","pinyin":"Wǒmen yìqǐ wán pīntú ba.","vi":"Chúng ta cùng chơi ghép hình nhé."},{"type":"simple","zh":"女儿花了整整一个下午拼完了一千块的拼图。","pinyin":"Nǚ'ér huāle zhěngzhěng yī gè xiàwǔ pīn wánle yī qiān kuài de pīntú.","vi":"Con gái mất trọn một buổi chiều để ghép xong bộ ghép hình một nghìn mảnh."},{"type":"compound","zh":"拼图只要少了一块，整幅画面就不完整。","pinyin":"Pīntú zhǐyào shǎole yíkuài, zhěng fú huàmiàn jiù bù wánzhěng.","vi":"Bộ ghép hình chỉ cần thiếu một mảnh là cả bức tranh không còn trọn vẹn."}],"related":[{"hanzi":"积木","pinyin":"jīmù","vi":"đồ chơi xếp hình"},{"hanzi":"游戏","pinyin":"yóuxì","vi":"trò chơi"},{"hanzi":"碎片","pinyin":"suìpiàn","vi":"mảnh vụn"}],"traditional":"拼圖"},{"id":"铺垫","hanzi":"铺垫","pinyin":"pūdiàn","meaning_vi":"làm nền, gợi mở trước (bố cục văn học)","explanation":"铺 (trải) + 垫 (lót).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🧱","examples":[{"type":"basic","zh":"前文做了铺垫。","pinyin":"Qiánwén zuòle pūdiàn.","vi":"Phần trước đã làm nền gợi mở."},{"type":"simple","zh":"作者在第一章就为结局埋下了巧妙的铺垫。","pinyin":"Zuòzhě zài dìyī zhāng jiù wèi jiéjú mái xiàle qiǎomiào de pūdiàn.","vi":"Tác giả đã cài cắm sự gợi mở khéo léo cho kết cục ngay từ chương một."},{"type":"compound","zh":"如果没有前面的铺垫，结尾的反转就不会这么震撼。","pinyin":"Rúguǒ méiyǒu qiánmiàn de pūdiàn, jiéwěi de fǎnzhuǎn jiù bú huì zhème zhènhàn.","vi":"Nếu không có phần dẫn dắt phía trước, cú lật ở đoạn kết sẽ không gây chấn động như vậy."}],"related":[{"hanzi":"伏笔","pinyin":"fúbǐ","vi":"chi tiết gợi mở"},{"hanzi":"过渡","pinyin":"guòdù","vi":"chuyển tiếp"},{"hanzi":"准备","pinyin":"zhǔnbèi","vi":"chuẩn bị"}],"traditional":"鋪墊"},{"id":"铺路","hanzi":"铺路","pinyin":"pūlù","meaning_vi":"lát đường, rải đường; mở đường, tạo tiền đề","explanation":"铺 (phô – trải) + 路 (lộ – đường) → trải đường, lát đường; nghĩa bóng: dọn đường, tạo điều kiện. VD: 为将来铺路.","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"工人们在铺路。","pinyin":"Gōngrénmen zài pūlù.","vi":"Công nhân đang lát đường."},{"type":"simple","zh":"父母省吃俭用，为孩子出国留学铺路。","pinyin":"Fùmǔ shěngchījiǎnyòng, wèi háizi chūguó liúxué pūlù.","vi":"Cha mẹ ăn tiêu dè sẻn để lót đường cho con đi du học."},{"type":"compound","zh":"这次合作虽然利润不高，但是能为进入欧洲市场铺路。","pinyin":"Zhè cì hézuò suīrán lìrùn bù gāo, dànshì néng wèi jìnrù Ōuzhōu shìchǎng pūlù.","vi":"Lần hợp tác này tuy lợi nhuận không cao nhưng có thể lót đường để vào thị trường châu Âu."}],"related":[{"hanzi":"开路","pinyin":"kāilù","vi":"mở đường"},{"hanzi":"修路","pinyin":"xiūlù","vi":"sửa đường"},{"hanzi":"奠定基础","pinyin":"diàndìngjīchǔ","vi":"đặt nền móng"}],"traditional":"鋪路"},{"id":"扑面而来","hanzi":"扑面而来","pinyin":"pūmiàn-érlái","meaning_vi":"ập thẳng vào mặt (làn gió/hương thơm/không khí)","explanation":"扑 (lao vào) + 面 (diện mạo/bề mặt) + 而 (mà) + 来 (đến).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌬️","examples":[{"type":"basic","zh":"热浪扑面而来。","pinyin":"Rèlàng pūmiàn'érlái.","vi":"Sóng nhiệt ập thẳng vào mặt."},{"type":"simple","zh":"推开面包店的门，一股甜香扑面而来。","pinyin":"Tuīkāi miànbāodiàn de mén, yì gǔ tián xiāng pūmiàn'érlái.","vi":"Đẩy cửa tiệm bánh mì, một mùi thơm ngọt ập thẳng vào mặt."},{"type":"compound","zh":"一走出机场，浓浓的热带气息就扑面而来。","pinyin":"Yì zǒuchū jīchǎng, nóng nóng de rèdài qìxī jiù pūmiàn'érlái.","vi":"Vừa bước ra khỏi sân bay, không khí nhiệt đới nồng nàn đã ập thẳng vào mặt."}],"related":[{"hanzi":"迎面而来","pinyin":"yíngmiàn'érlái","vi":"ập tới trước mặt"},{"hanzi":"扑鼻","pinyin":"pūbí","vi":"xộc vào mũi"},{"hanzi":"迎面","pinyin":"yíngmiàn","vi":"trước mặt"}],"traditional":"撲面而來"},{"id":"跑道","hanzi":"跑道","pinyin":"pǎodào","meaning_vi":"đường băng (sân bay); đường chạy (điền kinh)","explanation":"跑 (bào – chạy) + 道 (đạo – đường) → đường chạy điền kinh, đường băng sân bay; nghĩa bóng: lĩnh vực cạnh tranh. VD: 机场跑道.","hsk_level":"7-9","tags":["danh-tu","giao-thong","the-thao"],"image":"🛫","examples":[{"type":"basic","zh":"飞机滑上跑道。","pinyin":"Fēijī huá shàng pǎodào.","vi":"Máy bay lăn vào đường băng."},{"type":"simple","zh":"清晨的操场跑道上已经有不少人在慢跑了。","pinyin":"Qīngchén de cāochǎng pǎodào shàng yǐjīng yǒu bùshǎo rén zài mànpǎo le.","vi":"Sáng sớm trên đường chạy của sân vận động đã có khá nhiều người chạy bộ."},{"type":"compound","zh":"因为跑道积雪太厚，所以所有航班都推迟起飞。","pinyin":"Yīnwèi pǎodào jīxuě tài hòu, suǒyǐ suǒyǒu hángbān dōu tuīchí qǐfēi.","vi":"Vì tuyết đọng trên đường băng quá dày nên tất cả chuyến bay đều phải hoãn cất cánh."}],"related":[{"hanzi":"跑步","pinyin":"pǎobù","vi":"chạy bộ"},{"hanzi":"机场","pinyin":"jīchǎng","vi":"sân bay"},{"hanzi":"起飞","pinyin":"qǐfēi","vi":"cất cánh"}]},{"id":"匹敌","hanzi":"匹敌","pinyin":"pǐdí","meaning_vi":"sánh ngang, đối địch ngang sức","explanation":"匹 (con (ngựa)) + 敌 (敌).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"⚖️","examples":[{"type":"basic","zh":"无人能与他匹敌。","pinyin":"Wúrén néng yǔ tā pǐdí.","vi":"Không ai có thể sánh ngang với anh ấy."},{"type":"simple","zh":"这款国产相机的画质足以匹敌进口高端品牌。","pinyin":"Zhè kuǎn guóchǎn xiàngjī de huàzhì zúyǐ pǐdí jìnkǒu gāoduān pǐnpái.","vi":"Chất lượng hình ảnh của máy ảnh nội địa này đủ sức sánh ngang các thương hiệu cao cấp nhập khẩu."},{"type":"compound","zh":"虽然这支球队很年轻，但是实力足以和老牌强队匹敌。","pinyin":"Suīrán zhè zhī qiúduì hěn niánqīng, dànshì shílì zúyǐ hé lǎopái qiángduì pǐdí.","vi":"Tuy đội bóng này còn rất trẻ nhưng thực lực đủ sức ngang ngửa các đội mạnh lâu năm."}],"related":[{"hanzi":"抗衡","pinyin":"kànghéng","vi":"đối đầu ngang sức"},{"hanzi":"媲美","pinyin":"pìměi","vi":"sánh đẹp"},{"hanzi":"对手","pinyin":"duìshǒu","vi":"đối thủ"}],"traditional":"匹敵"},{"id":"品格","hanzi":"品格","pinyin":"pǐngé","meaning_vi":"phẩm cách, nhân cách","explanation":"品 (phẩm chất/thưởng thức) + 格 (格).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"他的品格很高尚。","pinyin":"Tā de pǐngé hěn gāoshàng.","vi":"Phẩm cách của anh ấy rất cao thượng."},{"type":"simple","zh":"这位乡村教师用一生诠释了无私奉献的品格。","pinyin":"Zhè wèi xiāngcūn jiàoshī yòng yìshēng quánshìle wúsīfèngxiàn de pǐngé.","vi":"Người giáo viên làng quê này đã dùng cả cuộc đời để thể hiện phẩm cách cống hiến vô tư."},{"type":"compound","zh":"一个人的才华固然重要，但是品格更加重要。","pinyin":"Yígèrén de cáihuá gùrán zhòngyào, dànshì pǐngé gèngjiā zhòngyào.","vi":"Tài hoa của một người tất nhiên quan trọng, nhưng phẩm cách còn quan trọng hơn."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"人格","pinyin":"réngé","vi":"nhân cách"},{"hanzi":"品质","pinyin":"pǐnzhì","vi":"phẩm chất"}]},{"id":"品牌效应","hanzi":"品牌效应","pinyin":"pǐnpáixiàoyìng","meaning_vi":"hiệu ứng thương hiệu","explanation":"品牌 (phẩm bài – thương hiệu) + 效应 (hiệu ứng) → hiệu ứng thương hiệu, sức ảnh hưởng của thương hiệu đến người tiêu dùng.","hsk_level":"7-9","tags":["danh-tu","cong-viec","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"品牌效应很明显。","pinyin":"Pǐnpáixiàoyìng hěn míngxiǎn.","vi":"Hiệu ứng thương hiệu rất rõ rệt."},{"type":"simple","zh":"这家咖啡店借助明星代言迅速形成了品牌效应。","pinyin":"Zhè jiā kāfēidiàn jièzhù míngxīng dàiyán xùnsù xíng chéngle pǐnpáixiàoyìng.","vi":"Quán cà phê này nhờ ngôi sao đại diện đã nhanh chóng tạo ra hiệu ứng thương hiệu."},{"type":"compound","zh":"一旦形成了品牌效应，产品就不愁卖不出去。","pinyin":"Yídàn xíng chéngle pǐnpáixiàoyìng, chǎnpǐn jiù bù chóu mài bu chūqù.","vi":"Một khi đã tạo ra hiệu ứng thương hiệu thì sản phẩm không lo bán không được."}],"related":[{"hanzi":"品牌","pinyin":"pǐnpái","vi":"thương hiệu"},{"hanzi":"名牌","pinyin":"míngpái","vi":"hàng hiệu"},{"hanzi":"知名度","pinyin":"zhīmíngdù","vi":"độ nổi tiếng"}],"traditional":"品牌效應"},{"id":"品味","hanzi":"品味","pinyin":"pǐnwèi","meaning_vi":"thưởng thức, nhấm nháp; gu, phẩm vị","explanation":"品 (phẩm chất/thưởng thức) + 味 (hương vị/suy ngẫm).","hsk_level":"7-9","tags":["dong-tu","danh-tu"],"image":"🍷","examples":[{"type":"basic","zh":"他很有品味。","pinyin":"Tā hěn yǒu pǐnwèi.","vi":"Anh ấy rất có gu."},{"type":"simple","zh":"坐在茶馆里慢慢品味一壶好茶是他的爱好。","pinyin":"Zuò zài cháguǎn lǐ mànmàn pǐnwèi yì hú hǎo chá shì tā de àihào.","vi":"Ngồi trong quán trà thong thả thưởng thức một ấm trà ngon là sở thích của ông ấy."},{"type":"compound","zh":"只有静下心来细细品味，才能读懂这本小说的深意。","pinyin":"Zhǐyǒu jìng xià xīn lái xìxì pǐnwèi, cáinéng dúdǒng zhè běn xiǎoshuō de shēn yì.","vi":"Chỉ có tĩnh tâm thưởng thức kỹ mới có thể hiểu được ý nghĩa sâu xa của cuốn tiểu thuyết này."}],"related":[{"hanzi":"品尝","pinyin":"pǐncháng","vi":"nếm thử"},{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức"},{"hanzi":"品位","pinyin":"pǐnwèi","vi":"phẩm vị"}]},{"id":"品位","hanzi":"品位","pinyin":"pǐnwèi","meaning_vi":"đẳng cấp thẩm mỹ, phẩm vị","explanation":"品 (phẩm chất/thưởng thức) + 位 (vị trí/địa vị).","hsk_level":"7-9","tags":["danh-tu"],"image":"💎","examples":[{"type":"basic","zh":"这家店很有品位。","pinyin":"Zhè jiā diàn hěn yǒu pǐnwèi.","vi":"Cửa hàng này rất có đẳng cấp."},{"type":"simple","zh":"她客厅的装修处处体现出主人高雅的品位。","pinyin":"Tā kètīng de zhuāngxiū chùchù tǐxiàn chū zhǔrén gāoyǎ de pǐnwèi.","vi":"Cách trang trí phòng khách của cô ấy chỗ nào cũng thể hiện gu thẩm mỹ thanh nhã của chủ nhà."},{"type":"compound","zh":"穿衣虽然不必追求名牌，但是要有自己的品位。","pinyin":"Chuānyī suīrán búbì zhuīqiú míngpái, dànshì yàoyǒu zìjǐ de pǐnwèi.","vi":"Ăn mặc tuy không cần chạy theo hàng hiệu nhưng phải có gu riêng của mình."}],"related":[{"hanzi":"品味","pinyin":"pǐnwèi","vi":"gu thẩm mỹ"},{"hanzi":"档次","pinyin":"dàngcì","vi":"đẳng cấp"},{"hanzi":"格调","pinyin":"gédiào","vi":"phong cách"}]},{"id":"普及率","hanzi":"普及率","pinyin":"pǔjílǜ","meaning_vi":"tỷ lệ phổ cập","explanation":"普 (phổ cập/phổ biến) + 及 (kịp thời/đạt tới) + 率 (dẫn dắt/tỷ lệ).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","so-luong"],"image":"📊","examples":[{"type":"basic","zh":"网络普及率很高。","pinyin":"Wǎngluò pǔjílǜ hěn gāo.","vi":"Tỷ lệ phổ cập internet rất cao."},{"type":"simple","zh":"近十年来农村地区的智能手机普及率大幅提升。","pinyin":"Jìn shí niánlái nóngcūn dìqū de zhìnéng shǒujī pǔjílǜ dàfú tíshēng.","vi":"Gần mười năm nay tỷ lệ phổ cập điện thoại thông minh ở nông thôn tăng mạnh."},{"type":"compound","zh":"只要疫苗普及率达到九成，传染病就很难大规模流行。","pinyin":"Zhǐyào yìmiáo pǔjílǜ dádào jiǔchéng, chuánrǎnbìng jiù hěn nán dàguīmó liúxíng.","vi":"Chỉ cần tỷ lệ phổ cập vắc-xin đạt chín mươi phần trăm thì bệnh truyền nhiễm khó lây lan trên diện rộng."}],"related":[{"hanzi":"普及","pinyin":"pǔjí","vi":"phổ cập"},{"hanzi":"覆盖率","pinyin":"fùgàilǜ","vi":"tỷ lệ bao phủ"},{"hanzi":"比率","pinyin":"bǐlǜ","vi":"tỷ lệ"}]},{"id":"普世价值","hanzi":"普世价值","pinyin":"pǔshìjiàzhí","meaning_vi":"giá trị phổ quát toàn nhân loại","explanation":"普 (phổ cập/phổ biến) + 世 (thế giới/thế hệ) + 价 (价) + 值 (giá trị/đáng giá).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","van-hoa"],"image":"🌍","examples":[{"type":"basic","zh":"和平是普世价值。","pinyin":"Hépíng shì pǔshìjiàzhí.","vi":"Hòa bình là giá trị phổ quát."},{"type":"simple","zh":"学者们围绕普世价值展开了激烈的辩论。","pinyin":"Xuézhěmen wéirào pǔshìjiàzhí zhǎnkāile jīliè de biànlùn.","vi":"Các học giả đã tranh luận gay gắt xung quanh giá trị phổ quát."},{"type":"compound","zh":"虽然各国文化不同，但是诚信被视为一种普世价值。","pinyin":"Suīrán gèguó wénhuà bùtóng, dànshì chéngxìn bèi shìwéi yì zhǒng pǔshìjiàzhí.","vi":"Tuy văn hóa các nước khác nhau nhưng sự trung thực được xem là một giá trị phổ quát."}],"related":[{"hanzi":"价值观","pinyin":"jiàzhíguān","vi":"giá trị quan"},{"hanzi":"人权","pinyin":"rénquán","vi":"nhân quyền"},{"hanzi":"普遍","pinyin":"pǔbiàn","vi":"phổ biến"}],"traditional":"普世價值"},{"id":"普洱茶","hanzi":"普洱茶","pinyin":"Pǔ'ěrchá","meaning_vi":"trà Phổ Nhĩ (đặc sản Vân Nam)","explanation":"普洱 (Phổ Nhĩ – địa danh ở Vân Nam) + 茶 (trà) → trà Phổ Nhĩ, loại trà lên men nổi tiếng, càng để lâu càng quý.","hsk_level":"7-9","tags":["danh-tu","an-uong","van-hoa"],"image":"🍵","examples":[{"type":"basic","zh":"他爱喝普洱茶。","pinyin":"Tā ài hē Pǔ'ěrchá.","vi":"Ông ấy thích uống trà Phổ Nhĩ."},{"type":"simple","zh":"这饼存放了二十年的普洱茶拍出了高价。","pinyin":"Zhè bǐng cúnfàngle èrshí nián de Pǔ'ěrchá pāichūle gāojià.","vi":"Bánh trà Phổ Nhĩ được cất giữ hai mươi năm này đã được đấu giá với giá cao."},{"type":"compound","zh":"普洱茶不但能解油腻，而且越陈越香。","pinyin":"Pǔ'ěrchá búdàn néng jiě yóunì, érqiě yuè chén yuè xiāng.","vi":"Trà Phổ Nhĩ không những giúp giải ngấy mà còn càng để lâu càng thơm."}],"related":[{"hanzi":"绿茶","pinyin":"lǜchá","vi":"trà xanh"},{"hanzi":"红茶","pinyin":"hóngchá","vi":"hồng trà"},{"hanzi":"云南","pinyin":"Yúnnán","vi":"Vân Nam"}]},{"id":"欠佳","hanzi":"欠佳","pinyin":"qiànjiā","meaning_vi":"chưa được tốt lắm (sức khỏe/thành tích)","explanation":"欠 (nợ) + 佳 (tốt đẹp/món ngon).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"📉","examples":[{"type":"basic","zh":"他最近状态欠佳。","pinyin":"Tā zuìjìn zhuàngtài qiànjiā.","vi":"Dạo này phong độ của anh ấy chưa được tốt."},{"type":"simple","zh":"由于身体欠佳，老教授取消了本周的讲座。","pinyin":"Yóuyú shēntǐ qiànjiā, lǎo jiàoshòu qǔxiāole běn zhōu de jiǎngzuò.","vi":"Vì sức khỏe không được tốt, vị giáo sư già đã hủy buổi giảng tuần này."},{"type":"compound","zh":"虽然这家餐厅环境不错，但是服务态度欠佳。","pinyin":"Suīrán zhè jiā cāntīng huánjìng búcuò, dànshì fúwù tàidù qiànjiā.","vi":"Tuy nhà hàng này không gian khá đẹp nhưng thái độ phục vụ chưa được tốt."}],"related":[{"hanzi":"不佳","pinyin":"bùjiā","vi":"không tốt"},{"hanzi":"良好","pinyin":"liánghǎo","vi":"tốt"},{"hanzi":"不理想","pinyin":"bùlǐxiǎng","vi":"chưa lý tưởng"}]},{"id":"翘首以盼","hanzi":"翘首以盼","pinyin":"qiáoshǒu-yǐpàn","meaning_vi":"ngẩng đầu mong ngóng tha thiết","explanation":"翘 (vểnh lên) + 首 (bài (lượng từ thơ/ca khúc)) + 以 (lấy) + 盼 (mong ngóng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🙏","examples":[{"type":"basic","zh":"球迷们翘首以盼。","pinyin":"Qiúmímen qiáoshǒuyǐpàn.","vi":"Người hâm mộ ngóng trông tha thiết."},{"type":"simple","zh":"全村人都翘首以盼新修的公路早日通车。","pinyin":"Quán cūn rén dōu qiáoshǒuyǐpàn xīnxiū de gōnglù zǎorì tōngchē.","vi":"Cả làng đều mong ngóng con đường mới làm sớm được thông xe."},{"type":"compound","zh":"因为新专辑一再推迟，所以歌迷们只能继续翘首以盼。","pinyin":"Yīnwèi xīn zhuānjí yízài tuīchí, suǒyǐ gēmímen zhǐnéng jìxù qiáoshǒuyǐpàn.","vi":"Vì album mới liên tục bị hoãn nên người hâm mộ chỉ có thể tiếp tục mong ngóng."}],"related":[{"hanzi":"期盼","pinyin":"qīpàn","vi":"mong đợi"},{"hanzi":"盼望","pinyin":"pànwàng","vi":"trông ngóng"},{"hanzi":"拭目以待","pinyin":"shìmùyǐdài","vi":"chờ xem"}],"traditional":"翹首以盼"},{"id":"潜伏期","hanzi":"潜伏期","pinyin":"qiánfúqī","meaning_vi":"thời kỳ ủ bệnh","explanation":"潜 (tiềm năng/ẩn giấu) + 伏 (nằm phục) + 期 (期).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"这种病潜伏期长。","pinyin":"Zhè zhǒng bìng qiánfúqī cháng.","vi":"Bệnh này có thời kỳ ủ bệnh dài."},{"type":"simple","zh":"专家指出流感的潜伏期一般为一到三天。","pinyin":"Zhuānjiā zhǐchū liúgǎn de qiánfúqī yìbān wéi yí dào sān tiān.","vi":"Chuyên gia chỉ ra thời kỳ ủ bệnh của cúm thường là một đến ba ngày."},{"type":"compound","zh":"因为潜伏期内没有症状，所以病毒很容易在人群中传播。","pinyin":"Yīnwèi qiánfúqī nèi méiyǒu zhèngzhuàng, suǒyǐ bìngdú hěn róngyì zài rénqún zhōng chuánbō.","vi":"Vì trong thời kỳ ủ bệnh không có triệu chứng nên virus rất dễ lây lan trong cộng đồng."}],"related":[{"hanzi":"潜伏","pinyin":"qiánfú","vi":"ẩn nấp"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"virus"},{"hanzi":"症状","pinyin":"zhèngzhuàng","vi":"triệu chứng"}],"traditional":"潛伏期"},{"id":"潜能","hanzi":"潜能","pinyin":"qiánnéng","meaning_vi":"tiềm năng","explanation":"潜 (tiềm năng/ẩn giấu) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"💡","examples":[{"type":"basic","zh":"每个人都有潜能。","pinyin":"Měigèrén dōu yǒu qiánnéng.","vi":"Mỗi người đều có tiềm năng."},{"type":"simple","zh":"这次野外生存训练激发了孩子们的潜能。","pinyin":"Zhè cì yěwài shēngcún xùnliàn jīfāle háizimen de qiánnéng.","vi":"Đợt huấn luyện sinh tồn ngoài trời này đã khơi dậy tiềm năng của bọn trẻ."},{"type":"compound","zh":"只要给予足够的信任，员工的潜能就会充分发挥出来。","pinyin":"Zhǐyào jǐyǔ zúgòu de xìnrèn, yuángōng de qiánnéng jiù huì chōngfèn fāhuī chūlái.","vi":"Chỉ cần trao đủ niềm tin thì tiềm năng của nhân viên sẽ được phát huy đầy đủ."}],"related":[{"hanzi":"潜力","pinyin":"qiánlì","vi":"tiềm lực"},{"hanzi":"潜质","pinyin":"qiánzhì","vi":"tố chất tiềm ẩn"},{"hanzi":"能力","pinyin":"nénglì","vi":"năng lực"}],"traditional":"潛能"},{"id":"前途无量","hanzi":"前途无量","pinyin":"qiántú-wúliàng","meaning_vi":"tiền đồ rộng mở vô lượng","explanation":"前 (trước) + 途 (con đường/tiền đồ) + 无 (không có) + 量 (đo lường/số lượng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌟","examples":[{"type":"basic","zh":"这孩子前途无量。","pinyin":"Zhè háizi qiántúwúliàng.","vi":"Đứa trẻ này tiền đồ rộng mở."},{"type":"simple","zh":"老教授认为这位年轻的研究员前途无量。","pinyin":"Lǎo jiàoshòu rènwéi zhè wèi niánqīng de yánjiūyuán qiántúwúliàng.","vi":"Vị giáo sư già cho rằng nhà nghiên cứu trẻ này có tiền đồ vô lượng."},{"type":"compound","zh":"他既有才华又肯吃苦，所以大家都说他前途无量。","pinyin":"Tā jìyǒu cáihuá yòu kěn chīkǔ, suǒyǐ dàjiā dōu shuō tā qiántúwúliàng.","vi":"Anh ấy vừa có tài vừa chịu khó nên ai cũng nói anh ấy tiền đồ rộng mở."}],"related":[{"hanzi":"前途","pinyin":"qiántú","vi":"tiền đồ"},{"hanzi":"前程似锦","pinyin":"qiánchéngsìjǐn","vi":"tiền đồ rực rỡ"},{"hanzi":"大有作为","pinyin":"dàyǒuzuòwéi","vi":"làm nên chuyện lớn"}],"traditional":"前途無量"},{"id":"潜心","hanzi":"潜心","pinyin":"qiánxīn","meaning_vi":"chuyên tâm, dồn hết tâm trí nghiên cứu","explanation":"潜 (tiềm năng/ẩn giấu) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["pho-tu","hoc-tap"],"image":"🧘","examples":[{"type":"basic","zh":"他潜心研究古籍。","pinyin":"Tā qiánxīn yánjiū gǔjí.","vi":"Ông ấy chuyên tâm nghiên cứu sách cổ."},{"type":"simple","zh":"这位作家隐居山村，潜心创作了整整五年。","pinyin":"Zhè wèi zuòjiā yǐnjū shāncūn, qiánxīn chuàngzuòle zhěngzhěng wǔ nián.","vi":"Nhà văn này ẩn cư ở làng núi, chuyên tâm sáng tác suốt năm năm."},{"type":"compound","zh":"只有远离喧嚣、潜心钻研，才能做出真正的学问。","pinyin":"Zhǐyǒu yuǎnlí xuānxiāo, qiánxīn zuānyán, cáinéng zuòchū zhēnzhèng de xuéwen.","vi":"Chỉ có tránh xa ồn ào, chuyên tâm nghiền ngẫm mới có thể làm nên học vấn thực sự."}],"related":[{"hanzi":"专心","pinyin":"zhuānxīn","vi":"chuyên tâm"},{"hanzi":"潜心研究","pinyin":"qiánxīnyánjiū","vi":"chuyên tâm nghiên cứu"},{"hanzi":"一心一意","pinyin":"yìxīnyíyì","vi":"một lòng một dạ"}],"traditional":"潛心"},{"id":"前沿","hanzi":"前沿","pinyin":"qiányán","meaning_vi":"tuyến đầu, lĩnh vực tiên phong (khoa học/công nghệ)","explanation":"前 (trước) + 沿 (ven biển/dọc theo).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🚀","examples":[{"type":"basic","zh":"他站在科技前沿。","pinyin":"Tā zhàn zài kējì qiányán.","vi":"Anh ấy đứng ở tuyến đầu khoa học công nghệ."},{"type":"simple","zh":"这场论坛汇聚了人工智能领域最前沿的研究成果。","pinyin":"Zhè chǎng lùntán huìjùle réngōngzhìnéng lǐngyù zuì qiányán de yánjiū chéngguǒ.","vi":"Diễn đàn này quy tụ những thành quả nghiên cứu tiên phong nhất trong lĩnh vực trí tuệ nhân tạo."},{"type":"compound","zh":"如果不持续学习，就很难跟上行业前沿的变化。","pinyin":"Rúguǒ bù chíxù xuéxí, jiù hěn nán gēnshàng hángyè qiányán de biànhuà.","vi":"Nếu không học tập liên tục thì rất khó theo kịp những thay đổi tiên phong của ngành."}],"related":[{"hanzi":"尖端","pinyin":"jiānduān","vi":"mũi nhọn"},{"hanzi":"前沿科技","pinyin":"qiányánkējì","vi":"công nghệ tiên tiến"},{"hanzi":"领先","pinyin":"lǐngxiān","vi":"dẫn đầu"}]},{"id":"潜意识","hanzi":"潜意识","pinyin":"qiányìshí","meaning_vi":"tiềm thức","explanation":"潜 (tiềm năng/ẩn giấu) + 意 (ý thức/ý nghĩa) + 识 (kiến thức/nhận biết).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc","khoa-hoc"],"image":"🧠","examples":[{"type":"basic","zh":"这是潜意识反应。","pinyin":"Zhè shì qiányìshí fǎnyìng.","vi":"Đây là phản ứng của tiềm thức."},{"type":"simple","zh":"梦境往往反映了人们潜意识里的焦虑。","pinyin":"Mèngjìng wǎngwǎng fǎnyìngle rénmen qiányìshí lǐ de jiāolǜ.","vi":"Giấc mơ thường phản ánh nỗi lo âu trong tiềm thức của con người."},{"type":"compound","zh":"他虽然嘴上说不在乎，但是潜意识里一直很在意。","pinyin":"Tā suīrán zuǐ shàng shuō bú zàihu, dànshì qiányìshí lǐ yìzhí hěn zàiyì.","vi":"Tuy ngoài miệng anh ấy nói không quan tâm nhưng trong tiềm thức luôn rất để ý."}],"related":[{"hanzi":"意识","pinyin":"yìshí","vi":"ý thức"},{"hanzi":"下意识","pinyin":"xiàyìshí","vi":"vô thức"},{"hanzi":"心理","pinyin":"xīnlǐ","vi":"tâm lý"}],"traditional":"潛意識"},{"id":"潜质","hanzi":"潜质","pinyin":"qiánzhì","meaning_vi":"tố chất tiềm ẩn","explanation":"潜 (tiềm năng/ẩn giấu) + 质 (chất lượng/bản chất).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌱","examples":[{"type":"basic","zh":"她很有明星潜质。","pinyin":"Tā hěn yǒu míngxīng qiánzhì.","vi":"Cô ấy rất có tố chất ngôi sao."},{"type":"simple","zh":"教练一眼就看出这个瘦小的男孩有跳水的潜质。","pinyin":"Jiàoliàn yìyǎn jiù kànchū zhè ge shòuxiǎo de nánhái yǒu tiàoshuǐ de qiánzhì.","vi":"Huấn luyện viên nhìn một cái đã thấy cậu bé gầy nhỏ này có tố chất nhảy cầu."},{"type":"compound","zh":"他虽然很有潜质，但是缺乏系统的训练。","pinyin":"Tā suīrán hěn yǒu qiánzhì, dànshì quēfá xìtǒng de xùnliàn.","vi":"Cậu ấy tuy rất có tố chất nhưng thiếu sự huấn luyện bài bản."}],"related":[{"hanzi":"潜能","pinyin":"qiánnéng","vi":"tiềm năng"},{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"素质","pinyin":"sùzhì","vi":"tố chất"}],"traditional":"潛質"},{"id":"前瞻性","hanzi":"前瞻性","pinyin":"qiánzhānxìng","meaning_vi":"tính nhìn xa trông rộng, tầm nhìn chiến lược","explanation":"前 (trước) + 瞻 (chiêm ngưỡng/nhìn xa) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔭","examples":[{"type":"basic","zh":"这个规划有前瞻性。","pinyin":"Zhè ge guīhuà yǒu qiánzhānxìng.","vi":"Quy hoạch này có tầm nhìn xa."},{"type":"simple","zh":"二十年前修建的地铁线路体现了极强的前瞻性。","pinyin":"Èrshí niánqián xiūjiàn de dìtiě xiànlù tǐxiànle jí qiáng de qiánzhānxìng.","vi":"Tuyến tàu điện ngầm xây từ hai mươi năm trước đã thể hiện tầm nhìn chiến lược rất xa."},{"type":"compound","zh":"因为决策缺乏前瞻性，所以公司错过了转型的最佳时机。","pinyin":"Yīnwèi juécè quēfá qiánzhānxìng, suǒyǐ gōngsī cuòguòle zhuǎnxíng de zuì jiā shíjī.","vi":"Vì quyết sách thiếu tầm nhìn xa nên công ty đã bỏ lỡ thời cơ chuyển đổi tốt nhất."}],"related":[{"hanzi":"远见","pinyin":"yuǎnjiàn","vi":"tầm nhìn xa"},{"hanzi":"预见性","pinyin":"yùjiànxìng","vi":"khả năng dự kiến"},{"hanzi":"战略","pinyin":"zhànlüè","vi":"chiến lược"}]},{"id":"强劲","hanzi":"强劲","pinyin":"qiángjìng","meaning_vi":"mạnh mẽ (đà tăng trưởng/gió)","explanation":"强 (cường đại/nhấn mạnh) + 劲 (sức lực/nhiệt huyết).","hsk_level":"7-9","tags":["tinh-tu"],"image":"💪","examples":[{"type":"basic","zh":"今天海风强劲。","pinyin":"Jīntiān hǎifēng qiángjìng.","vi":"Hôm nay gió biển rất mạnh."},{"type":"simple","zh":"新能源汽车的出口保持了强劲的增长势头。","pinyin":"Xīnnéngyuánqìchē de chūkǒu bǎochíle qiángjìng de zēngzhǎng shìtóu.","vi":"Xuất khẩu ô tô năng lượng mới duy trì đà tăng trưởng mạnh mẽ."},{"type":"compound","zh":"这款车虽然体积小，但是动力非常强劲。","pinyin":"Zhè kuǎn chē suīrán tǐjī xiǎo, dànshì dònglì fēicháng qiángjìng.","vi":"Mẫu xe này tuy nhỏ gọn nhưng động lực rất mạnh mẽ."}],"related":[{"hanzi":"强大","pinyin":"qiángdà","vi":"mạnh mẽ"},{"hanzi":"有力","pinyin":"yǒulì","vi":"có sức mạnh"},{"hanzi":"疲软","pinyin":"píruǎn","vi":"yếu ớt"}],"traditional":"強勁"},{"id":"强迫症","hanzi":"强迫症","pinyin":"qiǎngpòzhèng","meaning_vi":"rối loạn ám ảnh cưỡng chế (OCD)","explanation":"强 (cường đại/nhấn mạnh) + 迫 (bức bách/ép buộc) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cam-xuc"],"image":"🔄","examples":[{"type":"basic","zh":"他有点强迫症。","pinyin":"Tā yǒudiǎn qiǎngpòzhèng.","vi":"Anh ấy hơi bị ám ảnh cưỡng chế."},{"type":"simple","zh":"患有强迫症的她每天出门前要检查门锁十几次。","pinyin":"Huànyǒu qiǎngpòzhèng de tā měitiān chū ménqián yào jiǎnchá ménsuǒ shíjǐ cì.","vi":"Cô ấy mắc chứng rối loạn ám ảnh cưỡng chế, mỗi ngày trước khi ra ngoài phải kiểm tra khóa cửa hơn chục lần."},{"type":"compound","zh":"如果强迫症已经影响到生活，就应该及时去看心理医生。","pinyin":"Rúguǒ qiǎngpòzhèng yǐjīng yǐngxiǎng dào shēnghuó, jiù yīnggāi jíshí qù kàn xīnlǐ yīshēng.","vi":"Nếu chứng ám ảnh cưỡng chế đã ảnh hưởng đến cuộc sống thì nên kịp thời đi gặp bác sĩ tâm lý."}],"related":[{"hanzi":"焦虑症","pinyin":"jiāolǜzhèng","vi":"rối loạn lo âu"},{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"cưỡng ép"},{"hanzi":"心理疾病","pinyin":"xīnlǐjíbìng","vi":"bệnh tâm lý"}],"traditional":"強迫症"},{"id":"强盛","hanzi":"强盛","pinyin":"qiángshèng","meaning_vi":"hùng mạnh thịnh vượng","explanation":"强 (cường đại/nhấn mạnh) + 盛 (xới (cơm)).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"👑","examples":[{"type":"basic","zh":"国家日益强盛。","pinyin":"Guójiā rìyì qiángshèng.","vi":"Đất nước ngày càng hùng mạnh."},{"type":"simple","zh":"唐朝是中国历史上最强盛的朝代之一。","pinyin":"Tángcháo shì Zhōngguó lìshǐshàng zuì qiángshèng de cháodài zhīyī.","vi":"Nhà Đường là một trong những triều đại hùng mạnh nhất trong lịch sử Trung Quốc."},{"type":"compound","zh":"一个民族只有重视教育，才能长久强盛。","pinyin":"Yí gè mínzú zhǐyǒu zhòngshì jiàoyù, cáinéng chángjiǔ qiángshèng.","vi":"Một dân tộc chỉ có coi trọng giáo dục mới có thể hùng mạnh lâu dài."}],"related":[{"hanzi":"强大","pinyin":"qiángdà","vi":"hùng mạnh"},{"hanzi":"繁荣","pinyin":"fánróng","vi":"phồn vinh"},{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"}],"traditional":"強盛"},{"id":"强有力","hanzi":"强有力","pinyin":"qiángyǒulì","meaning_vi":"mạnh mẽ có hiệu lực","explanation":"强 (cường đại/nhấn mạnh) + 有 (có) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✊","examples":[{"type":"basic","zh":"这是强有力的证据。","pinyin":"Zhè shì qiángyǒulì de zhèngjù.","vi":"Đây là bằng chứng có sức thuyết phục mạnh mẽ."},{"type":"simple","zh":"政府出台了一系列强有力的措施稳定物价。","pinyin":"Zhèngfǔ chūtáile yíxìliè qiángyǒulì de cuòshī wěndìng wùjià.","vi":"Chính phủ đã ban hành một loạt biện pháp mạnh mẽ để ổn định giá cả."},{"type":"compound","zh":"如果没有强有力的领导，这次改革就很难推进。","pinyin":"Rúguǒ méiyǒu qiángyǒulì de lǐngdǎo, zhè cì gǎigé jiù hěn nán tuījìn.","vi":"Nếu không có sự lãnh đạo mạnh mẽ thì cuộc cải cách này rất khó thúc đẩy."}],"related":[{"hanzi":"有力","pinyin":"yǒulì","vi":"mạnh mẽ"},{"hanzi":"强大","pinyin":"qiángdà","vi":"hùng mạnh"},{"hanzi":"软弱无力","pinyin":"ruǎnruòwúlì","vi":"yếu ớt bất lực"}],"traditional":"強有力"},{"id":"切忌","hanzi":"切忌","pinyin":"qièjì","meaning_vi":"tuyệt đối kiêng kỵ","explanation":"切 (cắt) + 忌 (kiêng kỵ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"切忌空腹饮酒。","pinyin":"Qièjì kōngfù yǐnjiǔ.","vi":"Tuyệt đối không được uống rượu khi bụng đói."},{"type":"simple","zh":"面试时切忌随意打断面试官的提问。","pinyin":"Miànshì shí qièjì suíyì dǎduàn miànshìguān de tíwèn.","vi":"Khi phỏng vấn tuyệt đối tránh tùy tiện ngắt lời câu hỏi của người phỏng vấn."},{"type":"compound","zh":"刚拔完牙的人切忌吃辣，否则伤口容易发炎。","pinyin":"Gāng bá wán yá de rén qièjì chī là, fǒuzé shāngkǒu róngyì fāyán.","vi":"Người vừa nhổ răng tuyệt đối không được ăn cay, nếu không vết thương dễ bị viêm."}],"related":[{"hanzi":"忌讳","pinyin":"jìhuì","vi":"kiêng kỵ"},{"hanzi":"禁忌","pinyin":"jìnjì","vi":"điều cấm kỵ"},{"hanzi":"避免","pinyin":"bìmiǎn","vi":"tránh"}]},{"id":"切身","hanzi":"切身","pinyin":"qièshēn","meaning_vi":"thiết thân, trực tiếp liên quan bản thân","explanation":"切 (cắt) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🙋","examples":[{"type":"basic","zh":"这关乎切身利益。","pinyin":"Zhè guānhū qièshēnlìyì.","vi":"Điều này liên quan đến lợi ích thiết thân."},{"type":"simple","zh":"他用自己的切身经历提醒大家警惕网络诈骗。","pinyin":"Tāyòng zìjǐ de qièshēn jīnglì tíxǐng dàjiā jǐngtì wǎngluòzhàpiàn.","vi":"Anh ấy dùng chính trải nghiệm của bản thân để nhắc mọi người cảnh giác với lừa đảo qua mạng."},{"type":"compound","zh":"只有切身体会过失业的滋味，才能理解他的焦虑。","pinyin":"Zhǐyǒu qièshēn tǐhuìguo shīyè de zīwèi, cáinéng lǐjiě tā de jiāolǜ.","vi":"Chỉ khi tự mình nếm trải mùi vị thất nghiệp mới có thể hiểu được nỗi lo âu của anh ấy."}],"related":[{"hanzi":"亲身","pinyin":"qīnshēn","vi":"tự thân"},{"hanzi":"切身利益","pinyin":"qièshēnlìyì","vi":"lợi ích thiết thân"},{"hanzi":"体会","pinyin":"tǐhuì","vi":"thể nghiệm"}]},{"id":"穷困潦倒","hanzi":"穷困潦倒","pinyin":"qióngkùn-liáodǎo","meaning_vi":"nghèo túng khốn khổ","explanation":"穷 (nghèo) + 困 (困) + 潦 (lận đận/nước đọng) + 倒 (đổ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😔","examples":[{"type":"basic","zh":"他晚年穷困潦倒。","pinyin":"Tā wǎnnián qióngkùnliáodǎo.","vi":"Tuổi già ông ấy nghèo túng khốn khổ."},{"type":"simple","zh":"这位天才画家生前一直过着穷困潦倒的日子。","pinyin":"Zhè wèi tiāncái huàjiā shēngqián yìzhíguò zhe qióngkùnliáodǎo de rìzi.","vi":"Họa sĩ thiên tài này lúc sinh thời luôn sống những ngày nghèo túng khốn khổ."},{"type":"compound","zh":"即使穷困潦倒，他也从不向别人伸手借钱。","pinyin":"Jíshǐ qióngkùnliáodǎo, tā yě cóng bú xiàng biérén shēnshǒu jièqián.","vi":"Dù nghèo túng khốn khổ, ông ấy cũng chưa bao giờ ngửa tay vay tiền người khác."}],"related":[{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"},{"hanzi":"落魄","pinyin":"luòpò","vi":"sa sút"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"}],"traditional":"窮困潦倒"},{"id":"求助","hanzi":"求助","pinyin":"qiúzhù","meaning_vi":"cầu cứu, nhờ giúp đỡ","explanation":"求 (求) + 助 (hỗ trợ/trợ lý).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🆘","examples":[{"type":"basic","zh":"他向警察求助。","pinyin":"Tā xiàng jǐngchá qiúzhù.","vi":"Anh ấy cầu cứu cảnh sát."},{"type":"simple","zh":"迷路的游客通过手机向救援队发出了求助信号。","pinyin":"Mílù de yóukè tōngguò shǒujī xiàng jiùyuánduì fāchūle qiúzhù xìnhào.","vi":"Du khách bị lạc đường đã gửi tín hiệu cầu cứu cho đội cứu hộ qua điện thoại."},{"type":"compound","zh":"如果遇到解决不了的问题，就要及时向同事求助。","pinyin":"Rúguǒ yùdào jiějué bùliǎo de wèntí, jiùyào jíshí xiàng tóngshì qiúzhù.","vi":"Nếu gặp vấn đề không giải quyết được thì phải kịp thời nhờ đồng nghiệp giúp đỡ."}],"related":[{"hanzi":"求救","pinyin":"qiújiù","vi":"cầu cứu"},{"hanzi":"帮助","pinyin":"bāngzhù","vi":"giúp đỡ"},{"hanzi":"援助","pinyin":"yuánzhù","vi":"viện trợ"}]},{"id":"求真务实","hanzi":"求真务实","pinyin":"qiúzhēn-wùshí","meaning_vi":"tôn trọng sự thật và làm việc thiết thực","explanation":"求 (求) + 真 (thật) + 务 (nhiệm vụ/thiết thực) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"⚖️","examples":[{"type":"basic","zh":"我们要求真务实。","pinyin":"Wǒmen yào qiúzhēnwùshí.","vi":"Chúng ta phải tôn trọng sự thật và làm việc thiết thực."},{"type":"simple","zh":"这位老所长以求真务实的作风赢得了大家的尊重。","pinyin":"Zhè wèi lǎo suǒzhǎng yǐ qiúzhēnwùshí de zuòfēng yíng déle dàjiā de zūnzhòng.","vi":"Vị viện trưởng già đã giành được sự tôn trọng của mọi người nhờ tác phong tôn trọng sự thật và thiết thực."},{"type":"compound","zh":"做研究只有求真务实，结论才经得起检验。","pinyin":"Zuò yánjiū zhǐyǒu qiúzhēnwùshí, jiélùn cái jīngdeqǐ jiǎnyàn.","vi":"Làm nghiên cứu chỉ có tôn trọng sự thật và làm việc thiết thực thì kết luận mới chịu được kiểm nghiệm."}],"related":[{"hanzi":"务实","pinyin":"wùshí","vi":"thiết thực"},{"hanzi":"实事求是","pinyin":"shíshìqiúshì","vi":"thực sự cầu thị"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thực"}],"traditional":"求真務實"},{"id":"求知欲","hanzi":"求知欲","pinyin":"qiúzhīyù","meaning_vi":"lòng ham học hỏi, khát khao tri thức","explanation":"求 (求) + 知 (tri thức/tri giác) + 欲 (ham muốn/mong muốn).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🧠","examples":[{"type":"basic","zh":"孩子求知欲很强。","pinyin":"Háizi qiúzhīyù hěn qiáng.","vi":"Trẻ em có lòng ham hiểu biết rất mạnh."},{"type":"simple","zh":"一本好的科普书能点燃少年强烈的求知欲。","pinyin":"Yì běn hǎo de kēpǔ shū néng diǎnrán shàonián qiángliè de qiúzhīyù.","vi":"Một cuốn sách phổ biến khoa học hay có thể thắp lên khát khao tri thức mãnh liệt của thiếu niên."},{"type":"compound","zh":"老师如果总是批评提问的学生，就会扼杀他们的求知欲。","pinyin":"Lǎoshī rúguǒ zǒngshì pīpíng tíwèn de xuéshēng, jiù huì èshā tāmen de qiúzhīyù.","vi":"Nếu thầy cô luôn phê bình học sinh đặt câu hỏi thì sẽ bóp chết lòng ham học hỏi của các em."}],"related":[{"hanzi":"好奇心","pinyin":"hàoqíxīn","vi":"tính tò mò"},{"hanzi":"求知","pinyin":"qiúzhī","vi":"tìm hiểu tri thức"},{"hanzi":"好学","pinyin":"hàoxué","vi":"hiếu học"}],"traditional":"求知慾"},{"id":"千锤百炼","hanzi":"千锤百炼","pinyin":"qiānchuí-bǎiliàn","meaning_vi":"trăm rèn nghìn luyện (tôi luyện gian khổ)","explanation":"千 (nghìn (1.000)) + 锤 (cái búa/rèn giũa) + 百 (trăm (100)) + 炼 (tinh luyện/rèn giũa).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔨","examples":[{"type":"basic","zh":"好剑需千锤百炼。","pinyin":"Hǎo jiàn xū qiānchuíbǎiliàn.","vi":"Thanh kiếm tốt cần trăm rèn nghìn luyện."},{"type":"simple","zh":"这部经典剧本经过了演员们千锤百炼的打磨。","pinyin":"Zhè bù jīngdiǎn jùběn jīngguòle yǎnyuánmen qiānchuíbǎiliàn de dǎmó.","vi":"Kịch bản kinh điển này đã qua sự trau chuốt tôi luyện công phu của các diễn viên."},{"type":"compound","zh":"只有经过千锤百炼，运动员才能在赛场上稳定发挥。","pinyin":"Zhǐyǒu jīngguò qiānchuíbǎiliàn, yùndòngyuán cáinéng zài sàichǎng shàng wěndìng fāhuī.","vi":"Chỉ có trải qua trăm rèn nghìn luyện, vận động viên mới có thể thi đấu ổn định trên sân."}],"related":[{"hanzi":"磨炼","pinyin":"móliàn","vi":"tôi luyện"},{"hanzi":"锻炼","pinyin":"duànliàn","vi":"rèn luyện"},{"hanzi":"久经考验","pinyin":"jiǔjīngkǎoyàn","vi":"qua nhiều thử thách"}],"traditional":"千錘百煉"},{"id":"牵动","hanzi":"牵动","pinyin":"qiāndòng","meaning_vi":"tác động, làm rung động (lòng người)","explanation":"牵 (dắt (tay/thú)) + 动 (动).","hsk_level":"7-9","tags":["dong-tu"],"image":"💓","examples":[{"type":"basic","zh":"灾情牵动人心。","pinyin":"Zāiqíng qiāndòng rénxīn.","vi":"Tình hình thiên tai làm rung động lòng người."},{"type":"simple","zh":"被困矿工的安危牵动着全国人民的心。","pinyin":"Bèi kùn kuànggōng de ānwēi qiāndòngzhe quánguó rénmín de xīn.","vi":"Sự an nguy của những thợ mỏ bị mắc kẹt làm day dứt trái tim nhân dân cả nước."},{"type":"compound","zh":"油价一上涨，就会牵动物流、餐饮等多个行业。","pinyin":"Yóujià yí shàngzhǎng, jiù huì qiāndòng wùliú, cānyǐn děng duōgè hángyè.","vi":"Giá dầu vừa tăng sẽ tác động đến nhiều ngành như logistics, ăn uống."}],"related":[{"hanzi":"触动","pinyin":"chùdòng","vi":"chạm động"},{"hanzi":"影响","pinyin":"yǐngxiǎng","vi":"ảnh hưởng"},{"hanzi":"牵动人心","pinyin":"qiāndòngrénxīn","vi":"làm lay động lòng người"}],"traditional":"牽動"},{"id":"牵挂","hanzi":"牵挂","pinyin":"qiānguà","meaning_vi":"nhớ nhung lo lắng (cho người thân)","explanation":"牵 (dắt (tay/thú)) + 挂 (treo).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"妈妈总牵挂着我。","pinyin":"Māma zǒng qiānguàzhe wǒ.","vi":"Mẹ luôn nhớ nhung lo lắng cho tôi."},{"type":"simple","zh":"在外打工的他最牵挂的是留在老家的女儿。","pinyin":"Zài wài dǎgōng de tā zuì qiānguà de shì liú zài lǎojiā de nǚ'ér.","vi":"Người đang đi làm xa như anh ấy lo lắng nhớ nhung nhất là đứa con gái ở quê."},{"type":"compound","zh":"虽然儿子已经成年，但是父母依然时时牵挂。","pinyin":"Suīrán érzi yǐjīng chéngnián, dànshì fùmǔ yīrán shíshí qiānguà.","vi":"Tuy con trai đã trưởng thành nhưng cha mẹ vẫn luôn lo lắng nhớ nhung."}],"related":[{"hanzi":"挂念","pinyin":"guàniàn","vi":"nhớ nhung"},{"hanzi":"惦记","pinyin":"diànjì","vi":"canh cánh trong lòng"},{"hanzi":"思念","pinyin":"sīniàn","vi":"nhớ thương"}],"traditional":"牽掛"},{"id":"谦和","hanzi":"谦和","pinyin":"qiānhé","meaning_vi":"khiêm tốn hòa nhã","explanation":"谦 (khiêm tốn) + 和 (và).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"他待人很谦和。","pinyin":"Tā dàirén hěn qiānhé.","vi":"Anh ấy đối xử với người khác rất khiêm tốn hòa nhã."},{"type":"simple","zh":"这位获奖科学家在采访中始终保持谦和的态度。","pinyin":"Zhè wèi huòjiǎng kēxuéjiā zài cǎifǎng zhōng shǐzhōng bǎochí qiānhé de tàidù.","vi":"Nhà khoa học đoạt giải này luôn giữ thái độ khiêm tốn hòa nhã trong buổi phỏng vấn."},{"type":"compound","zh":"她虽然出身名门，但是为人十分谦和。","pinyin":"Tā suīrán chūshēn míngmén, dànshì wéirén shífēn qiānhé.","vi":"Cô ấy tuy xuất thân danh gia nhưng làm người rất khiêm tốn hòa nhã."}],"related":[{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"},{"hanzi":"傲慢","pinyin":"àomàn","vi":"kiêu ngạo"}],"traditional":"謙和"},{"id":"千家万户","hanzi":"千家万户","pinyin":"qiānjiā-wànhù","meaning_vi":"nghìn nhà vạn hộ, mọi gia đình","explanation":"千 (nghìn (1.000)) + 家 (nhà) + 万 (vạn vật/tuyệt đối) + 户 (户).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🏘️","examples":[{"type":"basic","zh":"网络走进千家万户。","pinyin":"Wǎngluò zǒujìn qiānjiāwànhù.","vi":"Internet đã đi vào mọi gia đình."},{"type":"simple","zh":"除夕夜，春晚的歌声传遍了千家万户。","pinyin":"Chúxīyè, Chūnwǎn de gēshēng chuánbiànle qiānjiāwànhù.","vi":"Đêm giao thừa, tiếng hát của chương trình Xuân Vãn vang khắp nghìn nhà vạn hộ."},{"type":"compound","zh":"只要电价稍有调整，就会影响到千家万户的生活。","pinyin":"Zhǐyào diànjià shāo yǒu tiáozhěng, jiù huì yǐngxiǎng dào qiānjiāwànhù de shēnghuó.","vi":"Chỉ cần giá điện điều chỉnh đôi chút là sẽ ảnh hưởng đến cuộc sống của mọi gia đình."}],"related":[{"hanzi":"家家户户","pinyin":"jiājiāhùhù","vi":"nhà nhà"},{"hanzi":"万家灯火","pinyin":"wànjiādēnghuǒ","vi":"vạn nhà sáng đèn"},{"hanzi":"老百姓","pinyin":"lǎobǎixìng","vi":"dân thường"}],"traditional":"千家萬戶"},{"id":"千奇百怪","hanzi":"千奇百怪","pinyin":"qiānqí-bǎiguài","meaning_vi":"muôn hình vạn trạng kỳ lạ","explanation":"千 (nghìn (1.000)) + 奇 (kỳ diệu/kỳ lạ) + 百 (trăm (100)) + 怪 (怪).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤪","examples":[{"type":"basic","zh":"海底生物千奇百怪。","pinyin":"Hǎidǐ shēngwù qiānqíbǎiguài.","vi":"Sinh vật dưới đáy biển muôn hình vạn trạng kỳ lạ."},{"type":"simple","zh":"这个溶洞里布满了千奇百怪的钟乳石。","pinyin":"Zhè ge róngdòng lǐ bùmǎnle qiānqíbǎiguài de zhōngrǔshí.","vi":"Hang động đá vôi này đầy những nhũ đá kỳ dị muôn hình vạn trạng."},{"type":"compound","zh":"孩子的问题虽然千奇百怪，但是父母应该耐心回答。","pinyin":"Háizi de wèntí suīrán qiānqíbǎiguài, dànshì fùmǔ yīnggāi nàixīn huídá.","vi":"Câu hỏi của trẻ con tuy muôn hình vạn trạng kỳ lạ nhưng cha mẹ nên kiên nhẫn trả lời."}],"related":[{"hanzi":"奇形怪状","pinyin":"qíxíngguàizhuàng","vi":"hình thù kỳ quái"},{"hanzi":"五花八门","pinyin":"wǔhuābāmén","vi":"đủ loại"},{"hanzi":"稀奇古怪","pinyin":"xīqígǔguài","vi":"kỳ lạ cổ quái"}]},{"id":"谦让","hanzi":"谦让","pinyin":"qiānràng","meaning_vi":"khiêm nhường nhường nhịn","explanation":"谦 (khiêm tốn) + 让 (bảo).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"兄弟俩互相谦让。","pinyin":"Xiōngdì liǎ hùxiāng qiānràng.","vi":"Hai anh em khiêm nhường nhường nhịn nhau."},{"type":"simple","zh":"公交车上，两位老人为了一个座位谦让了半天。","pinyin":"Gōngjiāochē shàng, liǎng wèi lǎorén wèile yí gè zuòwèi qiānràngle bàn tiān.","vi":"Trên xe buýt, hai cụ già nhường nhau một chỗ ngồi mãi."},{"type":"compound","zh":"既然大家都在谦让，你就别客气，先拿吧。","pinyin":"Jìrán dàjiā dōu zài qiānràng, nǐ jiù biékèqi, xiān ná ba.","vi":"Mọi người đều đang nhường nhau thì bạn đừng khách sáo, cứ lấy trước đi."}],"related":[{"hanzi":"礼让","pinyin":"lǐràng","vi":"nhường nhịn"},{"hanzi":"谦虚","pinyin":"qiānxū","vi":"khiêm tốn"},{"hanzi":"争抢","pinyin":"zhēngqiǎng","vi":"tranh giành"}],"traditional":"謙讓"},{"id":"千丝万缕","hanzi":"千丝万缕","pinyin":"qiānsī-wànlǚ","meaning_vi":"muôn vàn mối liên hệ chằng chịt","explanation":"千 (nghìn (1.000)) + 丝 (tơ lụa/mảy may) + 万 (vạn vật/tuyệt đối) + 缕 (sợi chỉ/từng sợi).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕸️","examples":[{"type":"basic","zh":"两者有千丝万缕的联系。","pinyin":"Liǎngzhě yǒu qiānsīwànlǚ de liánxì.","vi":"Hai bên có muôn vàn mối liên hệ chằng chịt."},{"type":"simple","zh":"这家公司和当地政府有着千丝万缕的关系。","pinyin":"Zhè jiā gōngsī hé dāngdì zhèngfǔ yǒuzhe qiānsīwànlǚ de guānxì.","vi":"Công ty này có muôn vàn mối quan hệ chằng chịt với chính quyền địa phương."},{"type":"compound","zh":"因为两国交往了上千年，所以文化上有着千丝万缕的联系。","pinyin":"Yīnwèi liǎngguó jiāowǎngle shàng qiānnián, suǒyǐ wénhuà shàng yǒuzhe qiānsīwànlǚ de liánxì.","vi":"Vì hai nước giao lưu hàng nghìn năm nên về văn hóa có muôn vàn mối liên hệ chằng chịt."}],"related":[{"hanzi":"错综复杂","pinyin":"cuòzōngfùzá","vi":"chằng chịt phức tạp"},{"hanzi":"密切","pinyin":"mìqiè","vi":"mật thiết"},{"hanzi":"关联","pinyin":"guānlián","vi":"liên quan"}],"traditional":"千絲萬縷"},{"id":"牵头","hanzi":"牵头","pinyin":"qiāntóu","meaning_vi":"đứng ra chủ trì dẫn dắt","explanation":"牵 (dắt (tay/thú)) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚩","examples":[{"type":"basic","zh":"这事由他牵头。","pinyin":"Zhè shìyóu tā qiāntóu.","vi":"Việc này do anh ấy đứng ra chủ trì."},{"type":"simple","zh":"由教育局牵头的读书节活动下周正式开幕。","pinyin":"Yóu jiàoyù jú qiāntóu de dúshū jié huódòng xiàzhōu zhèngshì kāimù.","vi":"Lễ hội đọc sách do Sở Giáo dục chủ trì sẽ chính thức khai mạc vào tuần sau."},{"type":"compound","zh":"如果没有人愿意牵头，这个项目就会一直拖下去。","pinyin":"Rúguǒ méiyǒu rén yuànyì qiāntóu, zhè ge xiàngmù jiù huì yìzhí tuō xiàqù.","vi":"Nếu không ai chịu đứng ra dẫn dắt thì dự án này sẽ cứ kéo dài mãi."}],"related":[{"hanzi":"带头","pinyin":"dàitóu","vi":"đi đầu"},{"hanzi":"主持","pinyin":"zhǔchí","vi":"chủ trì"},{"hanzi":"发起","pinyin":"fāqǐ","vi":"khởi xướng"}],"traditional":"牽頭"},{"id":"牵一发而动全身","hanzi":"牵一发而动全身","pinyin":"qiān yífà ér dòng quánshēn","meaning_vi":"nhổ một sợi tóc động cả toàn thân (tác động dây chuyền)","explanation":"牵 (dắt (tay/thú)) + 一 (số 1) + 发 (发) + 而 (mà) + 动 (动) + 全 (toàn diện/đầy đủ) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔗","examples":[{"type":"basic","zh":"改革牵一发而动全身。","pinyin":"Gǎigé qiānyífà'érdòngquánshēn.","vi":"Cải cách là việc nhổ một sợi tóc động cả toàn thân."},{"type":"simple","zh":"供应链上的每个环节都是牵一发而动全身的。","pinyin":"Gōngyìngliàn shàng de měi gè huánjié dōu shì qiānyífà'érdòngquánshēn de.","vi":"Mỗi khâu trong chuỗi cung ứng đều có tác động dây chuyền đến toàn bộ."},{"type":"compound","zh":"因为税制改革牵一发而动全身，所以必须稳步推进。","pinyin":"Yīnwèi shuìzhì gǎigé qiānyífà'érdòngquánshēn, suǒyǐ bìxū wěnbù tuījìn.","vi":"Vì cải cách thuế có tác động dây chuyền đến toàn bộ nên phải tiến hành từng bước vững chắc."}],"related":[{"hanzi":"连锁反应","pinyin":"liánsuǒfǎnyìng","vi":"phản ứng dây chuyền"},{"hanzi":"息息相关","pinyin":"xīxīxiāngguān","vi":"liên quan mật thiết"},{"hanzi":"全局","pinyin":"quánjú","vi":"toàn cục"}],"traditional":"牽一發而動全身"},{"id":"千真万确","hanzi":"千真万确","pinyin":"qiānzhēn-wànquè","meaning_vi":"hoàn toàn chính xác không sai chút nào","explanation":"千 (nghìn (1.000)) + 真 (thật) + 万 (vạn vật/tuyệt đối) + 确 (xác thực/đảm bảo).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💯","examples":[{"type":"basic","zh":"这消息千真万确。","pinyin":"Zhè xiāoxi qiānzhēnwànquè.","vi":"Tin này hoàn toàn chính xác."},{"type":"simple","zh":"他中了彩票头奖的事千真万确。","pinyin":"Tā zhòngle cǎipiào tóujiǎng de shì qiānzhēnwànquè.","vi":"Chuyện anh ấy trúng giải độc đắc xổ số là hoàn toàn có thật."},{"type":"compound","zh":"虽然听起来难以置信，但是这件事千真万确。","pinyin":"Suīrán tīngqǐlái nányǐzhìxìn, dànshì zhè jiàn shì qiānzhēnwànquè.","vi":"Tuy nghe có vẻ khó tin nhưng chuyện này hoàn toàn là thật."}],"related":[{"hanzi":"确凿","pinyin":"quèzáo","vi":"xác thực"},{"hanzi":"毫无疑问","pinyin":"háowúyíwèn","vi":"không chút nghi ngờ"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"}],"traditional":"千真萬確"},{"id":"悄然","hanzi":"悄然","pinyin":"qiǎorán","meaning_vi":"lặng lẽ, âm thầm","explanation":"悄 (lặng lẽ) + 然 (然).","hsk_level":"7-9","tags":["pho-tu"],"image":"🤫","examples":[{"type":"basic","zh":"春天悄然来临。","pinyin":"Chūntiān qiǎorán láilín.","vi":"Mùa xuân lặng lẽ đến."},{"type":"simple","zh":"移动支付悄然改变了人们的购物习惯。","pinyin":"Yídòngzhīfù qiǎorán gǎibiànle rénmen de gòuwù xíguàn.","vi":"Thanh toán di động đã âm thầm thay đổi thói quen mua sắm của mọi người."},{"type":"compound","zh":"演出一结束，那位明星就悄然离开了剧场。","pinyin":"Yǎnchū yì jiéshù, nà wèi míngxīng jiù qiǎorán líkāile jùchǎng.","vi":"Buổi diễn vừa kết thúc, ngôi sao ấy đã lặng lẽ rời khỏi nhà hát."}],"related":[{"hanzi":"悄悄","pinyin":"qiāoqiāo","vi":"lặng lẽ"},{"hanzi":"默默","pinyin":"mòmò","vi":"âm thầm"},{"hanzi":"悄无声息","pinyin":"qiǎowúshēngxī","vi":"không một tiếng động"}]},{"id":"秋高气爽","hanzi":"秋高气爽","pinyin":"qiūgāo-qìshuǎng","meaning_vi":"trời thu cao trong gió mát","explanation":"秋 (秋) + 高 (cao) + 气 (khí phách/khí hậu) + 爽 (sảng khoái/thẳng thắn).","hsk_level":"7-9","tags":["thanh-ngu","thoi-tiet"],"image":"🍂","examples":[{"type":"basic","zh":"今天秋高气爽。","pinyin":"Jīntiān qiūgāoqìshuǎng.","vi":"Hôm nay trời thu cao trong, gió mát."},{"type":"simple","zh":"秋高气爽的十月是登香山看红叶的好时节。","pinyin":"Qiūgāoqìshuǎng de Shíyuè shì dēng xiāng shān kàn hóngyè de hǎo shíjié.","vi":"Tháng mười trời thu trong mát là mùa đẹp để leo núi Hương Sơn ngắm lá đỏ."},{"type":"compound","zh":"既然秋高气爽，我们就别待在家里，去郊外野餐吧。","pinyin":"Jìrán qiūgāoqìshuǎng, wǒmen jiù bié dāi zài jiālǐ, qù jiāowài yěcān ba.","vi":"Trời thu đã trong mát thế này thì chúng ta đừng ở nhà nữa, ra ngoại ô dã ngoại đi."}],"related":[{"hanzi":"金秋","pinyin":"jīnqiū","vi":"mùa thu vàng"},{"hanzi":"晴空万里","pinyin":"qíngkōngwànlǐ","vi":"trời quang mây tạnh"},{"hanzi":"秋天","pinyin":"qiūtiān","vi":"mùa thu"}],"traditional":"秋高氣爽"},{"id":"强求","hanzi":"强求","pinyin":"qiǎngqiú","meaning_vi":"cưỡng cầu, ép buộc","explanation":"强 (đọc qiǎng) + 求 (cầu).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙅","examples":[{"type":"basic","zh":"感情不能强求。","pinyin":"Gǎnqíng bù néng qiǎngqiú.","vi":"Tình cảm không thể cưỡng cầu."},{"type":"simple","zh":"父母不应该强求孩子去完成自己未实现的梦想。","pinyin":"Fùmǔ bù yīnggāi qiǎngqiú háizi qù wánchéng zì jǐwèi shíxiàn de mèngxiǎng.","vi":"Cha mẹ không nên ép con thực hiện những ước mơ mà mình chưa đạt được."},{"type":"compound","zh":"既然他不愿意去国外读书，你就别再强求了。","pinyin":"Jìrán tā bú yuànyì qù guówài dúshū, nǐ jiù bié zài qiǎngqiú le.","vi":"Cậu ấy đã không muốn ra nước ngoài du học thì bạn đừng ép nữa."}],"related":[{"hanzi":"勉强","pinyin":"miǎnqiǎng","vi":"miễn cưỡng"},{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"cưỡng ép"},{"hanzi":"顺其自然","pinyin":"shùnqízìrán","vi":"thuận theo tự nhiên"}],"traditional":"強求"},{"id":"抢手","hanzi":"抢手","pinyin":"qiǎngshǒu","meaning_vi":"đắt hàng, được săn đón nhiều","explanation":"抢 (cướp) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"🔥","examples":[{"type":"basic","zh":"这款包很抢手。","pinyin":"Zhè kuǎn bāo hěn qiǎngshǒu.","vi":"Mẫu túi này rất đắt hàng."},{"type":"simple","zh":"学区房在这座城市一直是最抢手的房源。","pinyin":"Xuéqūfáng zài zhè zuò chéngshì yìzhí shì zuì qiǎngshǒu de fáng yuán.","vi":"Nhà gần trường học ở thành phố này luôn là nguồn nhà được săn đón nhất."},{"type":"compound","zh":"演唱会门票一开售就非常抢手，五分钟就卖光了。","pinyin":"Yǎnchànghuì ménpiào yì kāi shòu jiù fēicháng qiǎngshǒu, wǔ fēnzhōng jiù màiguāngle.","vi":"Vé buổi hòa nhạc vừa mở bán đã rất đắt hàng, năm phút là bán hết."}],"related":[{"hanzi":"热门","pinyin":"rèmén","vi":"được ưa chuộng"},{"hanzi":"畅销","pinyin":"chàngxiāo","vi":"bán chạy"},{"hanzi":"滞销","pinyin":"zhìxiāo","vi":"ế ẩm"}],"traditional":"搶手"},{"id":"抢先","hanzi":"抢先","pinyin":"qiǎngxiān","meaning_vi":"nhanh chân đi trước, giành trước","explanation":"抢 (cướp) + 先 (tiên tiến/trước).","hsk_level":"7-9","tags":["dong-tu","pho-tu"],"image":"⚡","examples":[{"type":"basic","zh":"他抢先一步。","pinyin":"Tā qiǎngxiān yí bù.","vi":"Anh ấy nhanh chân đi trước một bước."},{"type":"simple","zh":"这家报社抢先报道了新市长的任命消息。","pinyin":"Zhè jiā bàoshè qiǎngxiān bàodàole xīn shìzhǎng de rènmìng xiāoxi.","vi":"Tòa soạn này đã giành đưa tin trước về việc bổ nhiệm thị trưởng mới."},{"type":"compound","zh":"如果我们不抢先申请专利，竞争对手就会占得先机。","pinyin":"Rúguǒ wǒmen bù qiǎngxiān shēnqǐng zhuānlì, jìngzhēng duìshǒu jiù huì zhàn dé xiānjī.","vi":"Nếu chúng ta không nhanh chân đăng ký bằng sáng chế trước thì đối thủ cạnh tranh sẽ chiếm được tiên cơ."}],"related":[{"hanzi":"争先","pinyin":"zhēngxiān","vi":"tranh trước"},{"hanzi":"领先","pinyin":"lǐngxiān","vi":"dẫn đầu"},{"hanzi":"抢占","pinyin":"qiǎngzhàn","vi":"giành chiếm"}],"traditional":"搶先"},{"id":"劝告","hanzi":"劝告","pinyin":"quàngào","meaning_vi":"khuyên bảo","explanation":"劝 (khuyến – khuyên) + 告 (cáo – nói cho biết) → khuyên bảo, khuyên răn. VD: 不听劝告, 听从医生的劝告.","hsk_level":"7-9","tags":["dong-tu"],"image":"🗣️","examples":[{"type":"basic","zh":"他不听劝告。","pinyin":"Tā bù tīng quàngào.","vi":"Anh ấy không nghe lời khuyên."},{"type":"simple","zh":"医生多次劝告这位病人戒掉烟酒。","pinyin":"Yīshēng duōcì quàngào zhè wèi bìngrén jièdiào yānjiǔ.","vi":"Bác sĩ nhiều lần khuyên bệnh nhân này cai thuốc lá và rượu."},{"type":"compound","zh":"如果当初听了朋友的劝告，他就不会损失这么多钱。","pinyin":"Rúguǒ dāngchū tīngle péngyou de quàngào, tā jiù bú huì sǔnshī zhème duō qián.","vi":"Nếu lúc đầu nghe lời khuyên của bạn bè thì anh ấy đã không mất nhiều tiền như vậy."}],"related":[{"hanzi":"劝说","pinyin":"quànshuō","vi":"khuyên nhủ"},{"hanzi":"忠告","pinyin":"zhōnggào","vi":"lời khuyên chân thành"},{"hanzi":"建议","pinyin":"jiànyì","vi":"kiến nghị"}],"traditional":"勸告"},{"id":"劝阻","hanzi":"劝阻","pinyin":"quànzǔ","meaning_vi":"khuyên ngăn","explanation":"劝 (khuyên) + 阻 (ngăn cản/trở ngại).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🛑","examples":[{"type":"basic","zh":"妈妈劝阻了我。","pinyin":"Māma quànzǔle wǒ.","vi":"Mẹ đã khuyên ngăn tôi."},{"type":"simple","zh":"保安及时劝阻了几名想翻越护栏的游客。","pinyin":"Bǎo'ān jíshí quànzǔle jǐ míng xiǎng fānyuè hùlán de yóukè.","vi":"Bảo vệ đã kịp thời khuyên ngăn mấy du khách định trèo qua lan can."},{"type":"compound","zh":"虽然家人一再劝阻，但是他还是辞职去了西藏。","pinyin":"Suīrán jiārén yízài quànzǔ, dànshì tā háishi cízhí qùle Xīzàng.","vi":"Tuy gia đình nhiều lần khuyên ngăn nhưng anh ấy vẫn nghỉ việc đi Tây Tạng."}],"related":[{"hanzi":"阻止","pinyin":"zǔzhǐ","vi":"ngăn cản"},{"hanzi":"劝告","pinyin":"quàngào","vi":"khuyên bảo"},{"hanzi":"制止","pinyin":"zhìzhǐ","vi":"ngăn chặn"}],"traditional":"勸阻"},{"id":"全过程","hanzi":"全过程","pinyin":"quánguòchéng","meaning_vi":"toàn bộ quá trình","explanation":"全 (toàn diện/đầy đủ) + 过 (từng) + 程 (quá trình/hành trình).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"他看了全过程。","pinyin":"Tā kànle quánguòchéng.","vi":"Anh ấy đã xem toàn bộ quá trình."},{"type":"simple","zh":"监控录像清楚地记录了事故的全过程。","pinyin":"Jiānkòng lùxiàng qīngchu de jìlùle shìgù de quánguòchéng.","vi":"Camera giám sát đã ghi lại rõ ràng toàn bộ quá trình vụ tai nạn."},{"type":"compound","zh":"只要对生产全过程进行监督，食品安全就有了保障。","pinyin":"Zhǐyào duì shēngchǎn quánguòchéng jìnxíng jiāndū, shípǐn ānquán jiù yǒule bǎozhàng.","vi":"Chỉ cần giám sát toàn bộ quá trình sản xuất thì an toàn thực phẩm sẽ được bảo đảm."}],"related":[{"hanzi":"过程","pinyin":"guòchéng","vi":"quá trình"},{"hanzi":"全程","pinyin":"quánchéng","vi":"toàn bộ hành trình"},{"hanzi":"始终","pinyin":"shǐzhōng","vi":"từ đầu đến cuối"}],"traditional":"全過程"},{"id":"全能","hanzi":"全能","pinyin":"quánnéng","meaning_vi":"toàn năng, đa tài","explanation":"全 (toàn diện/đầy đủ) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["tinh-tu","the-thao"],"image":"🌟","examples":[{"type":"basic","zh":"她是全能选手。","pinyin":"Tā shì quánnéng xuǎnshǒu.","vi":"Cô ấy là vận động viên toàn năng."},{"type":"simple","zh":"这位全能艺人能唱歌、跳舞，还会导演电影。","pinyin":"Zhè wèi quánnéng yìrén néng chànggē, tiàowǔ, hái huì dǎoyǎn diànyǐng.","vi":"Nghệ sĩ đa tài này biết hát, nhảy, còn biết đạo diễn phim."},{"type":"compound","zh":"世上没有全能的人，所以我们要学会分工合作。","pinyin":"Shìshàng méiyǒu quánnéng de rén, suǒyǐ wǒmen yào xuéhuì fēngōng hézuò.","vi":"Trên đời không có ai toàn năng, vì vậy chúng ta phải học cách phân công hợp tác."}],"related":[{"hanzi":"多才多艺","pinyin":"duōcáiduōyì","vi":"đa tài đa nghệ"},{"hanzi":"万能","pinyin":"wànnéng","vi":"vạn năng"},{"hanzi":"全面","pinyin":"quánmiàn","vi":"toàn diện"}]},{"id":"全球变暖","hanzi":"全球变暖","pinyin":"quánqiúbiànnuǎn","meaning_vi":"nóng lên toàn cầu","explanation":"全 (toàn diện/đầy đủ) + 球 (球) + 变 (变) + 暖 (暖).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","thoi-tiet"],"image":"🌍","examples":[{"type":"basic","zh":"全球变暖加剧了。","pinyin":"Quánqiúbiànnuǎn jiājù le.","vi":"Sự nóng lên toàn cầu đã trầm trọng hơn."},{"type":"simple","zh":"全球变暖导致北极的海冰面积逐年缩小。","pinyin":"Quánqiúbiànnuǎn dǎozhì Běijí de hǎibīng miànjī zhúnián suōxiǎo.","vi":"Nóng lên toàn cầu khiến diện tích băng biển ở Bắc Cực thu hẹp dần qua từng năm."},{"type":"compound","zh":"如果全球变暖得不到控制，很多沿海城市就会被淹没。","pinyin":"Rúguǒ quánqiúbiànnuǎn débúdào kòngzhì, hěn duō yánhǎi chéngshì jiù huì bèi yānmò.","vi":"Nếu nóng lên toàn cầu không được kiểm soát thì nhiều thành phố ven biển sẽ bị nhấn chìm."}],"related":[{"hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","vi":"hiệu ứng nhà kính"},{"hanzi":"气候变化","pinyin":"qìhòubiànhuà","vi":"biến đổi khí hậu"},{"hanzi":"碳排放","pinyin":"tànpáifàng","vi":"phát thải các-bon"}],"traditional":"全球變暖"},{"id":"全球化","hanzi":"全球化","pinyin":"quánqiúhuà","meaning_vi":"toàn cầu hóa","explanation":"全 (toàn diện/đầy đủ) + 球 (球) + 化 (化).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"全球化势不可挡。","pinyin":"Quánqiúhuà shì bùkě dǎng.","vi":"Toàn cầu hóa là không thể ngăn cản."},{"type":"simple","zh":"全球化让一部手机的零件来自十几个国家。","pinyin":"Quánqiúhuà ràng yí bù shǒujī de língjiàn láizì shíjǐ gè guójiā.","vi":"Toàn cầu hóa khiến linh kiện của một chiếc điện thoại đến từ hơn chục quốc gia."},{"type":"compound","zh":"全球化虽然带来了机遇，但是也加剧了竞争。","pinyin":"Quánqiúhuà suīrán dàiláile jīyù, dànshì yě jiājùle jìngzhēng.","vi":"Toàn cầu hóa tuy mang lại cơ hội nhưng cũng làm cạnh tranh gay gắt hơn."}],"related":[{"hanzi":"国际化","pinyin":"guójìhuà","vi":"quốc tế hóa"},{"hanzi":"一体化","pinyin":"yìtǐhuà","vi":"nhất thể hóa"},{"hanzi":"本土化","pinyin":"běntǔhuà","vi":"bản địa hóa"}]},{"id":"泉水","hanzi":"泉水","pinyin":"quánshuǐ","meaning_vi":"nước suối","explanation":"泉 (suối nước) + 水 (nước).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","do-uong"],"image":"💧","examples":[{"type":"basic","zh":"泉水清澈见底。","pinyin":"Quánshuǐ qīngchè jiàndǐ.","vi":"Nước suối trong vắt nhìn thấy đáy."},{"type":"simple","zh":"村民们每天早上到山脚下挑泉水回家做饭。","pinyin":"Cūnmínmen měitiān zǎoshang dào shān jiǎoxià tiāo quánshuǐ huíjiā zuòfàn.","vi":"Dân làng mỗi sáng ra chân núi gánh nước suối về nhà nấu cơm."},{"type":"compound","zh":"这里的泉水不但甘甜，而且冬暖夏凉。","pinyin":"Zhèlǐ de quánshuǐ búdàn gāntián, érqiě dōng nuǎn xià liáng.","vi":"Nước suối ở đây không những ngọt mát mà còn đông ấm hè mát."}],"related":[{"hanzi":"矿泉水","pinyin":"kuàngquánshuǐ","vi":"nước khoáng"},{"hanzi":"温泉","pinyin":"wēnquán","vi":"suối nước nóng"},{"hanzi":"溪水","pinyin":"xīshuǐ","vi":"nước suối nhỏ"}]},{"id":"权威性","hanzi":"权威性","pinyin":"quánwēixìng","meaning_vi":"tính uy tín thẩm quyền","explanation":"权 (quyền lực/cân nhắc) + 威 (uy tín/uy lực) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"👑","examples":[{"type":"basic","zh":"这份报告有权威性。","pinyin":"Zhè fèn bàogào yǒu quánwēixìng.","vi":"Bản báo cáo này có tính uy tín."},{"type":"simple","zh":"这本词典的权威性得到了语言学界的普遍认可。","pinyin":"Zhè běn cídiǎn de quánwēixìng dédàole yǔyán xuéjiè de pǔbiàn rènkě.","vi":"Tính uy tín của cuốn từ điển này được giới ngôn ngữ học công nhận rộng rãi."},{"type":"compound","zh":"因为数据来源不明，所以这篇文章缺乏权威性。","pinyin":"Yīnwèi shùjù láiyuán bùmíng, suǒyǐ zhè piān wénzhāng quēfá quánwēixìng.","vi":"Vì nguồn dữ liệu không rõ ràng nên bài viết này thiếu tính uy tín."}],"related":[{"hanzi":"权威","pinyin":"quánwēi","vi":"uy quyền"},{"hanzi":"公信力","pinyin":"gōngxìnlì","vi":"uy tín công chúng"},{"hanzi":"可信度","pinyin":"kěxìndù","vi":"độ tin cậy"}],"traditional":"權威性"},{"id":"全心全意","hanzi":"全心全意","pinyin":"quánxīn-quányì","meaning_vi":"toàn tâm toàn ý","explanation":"全 (toàn diện/đầy đủ) + 心 (tâm lý/tâm huyết) + 全 (toàn diện/đầy đủ) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"❤️","examples":[{"type":"basic","zh":"她全心全意照顾病人。","pinyin":"Tā quánxīnquányì zhàogù bìngrén.","vi":"Cô ấy toàn tâm toàn ý chăm sóc bệnh nhân."},{"type":"simple","zh":"这位村医四十年来全心全意为乡亲们看病。","pinyin":"Zhè wèi cūn yī sìshí niánlái quánxīnquányì wèi xiāngqīnmen kànbìng.","vi":"Vị bác sĩ làng này bốn mươi năm qua toàn tâm toàn ý khám bệnh cho bà con."},{"type":"compound","zh":"只要你全心全意地投入，就一定能把这件事做好。","pinyin":"Zhǐyào nǐ quánxīnquányì de tóurù, jiù yídìng néng bǎ zhè jiàn shì zuò hǎo.","vi":"Chỉ cần bạn dốc toàn tâm toàn ý thì nhất định sẽ làm tốt việc này."}],"related":[{"hanzi":"一心一意","pinyin":"yìxīnyíyì","vi":"một lòng một dạ"},{"hanzi":"尽心尽力","pinyin":"jìnxīnjìnlì","vi":"tận tâm tận lực"},{"hanzi":"三心二意","pinyin":"sānxīn'èryì","vi":"không chuyên tâm"}]},{"id":"圈子","hanzi":"圈子","pinyin":"quānzi","meaning_vi":"vòng tròn quan hệ, giới (giới giải trí/kinh doanh)","explanation":"圈 (vòng tròn) + 子 (hạt giống/con cái).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"⭕","examples":[{"type":"basic","zh":"他的圈子很小。","pinyin":"Tā de quānzi hěn xiǎo.","vi":"Vòng tròn quan hệ của anh ấy rất hẹp."},{"type":"simple","zh":"她花了好几年才真正融入了上海的设计圈子。","pinyin":"Tā huāle hǎojǐnián cái zhēnzhèng róngrùle Shànghǎi de shèjì quānzi.","vi":"Cô ấy mất mấy năm mới thật sự hòa nhập được vào giới thiết kế ở Thượng Hải."},{"type":"compound","zh":"如果总待在自己的小圈子里，眼界就会越来越窄。","pinyin":"Rúguǒ zǒng dāi zài zìjǐ de xiǎo quānzi lǐ, yǎnjiè jiù huì yuèláiyuè zhǎi.","vi":"Nếu cứ ở mãi trong vòng tròn nhỏ của mình thì tầm nhìn sẽ ngày càng hẹp."}],"related":[{"hanzi":"社交圈","pinyin":"shèjiāoquān","vi":"vòng giao tiếp"},{"hanzi":"娱乐圈","pinyin":"yúlèquān","vi":"giới giải trí"},{"hanzi":"朋友圈","pinyin":"péngyouquān","vi":"vòng bạn bè"}]},{"id":"气场","hanzi":"气场","pinyin":"qìchǎng","meaning_vi":"khí chất, sức hút cá nhân","explanation":"气 (khí phách/khí hậu) + 场 (địa điểm/trận đấu).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"✨","examples":[{"type":"basic","zh":"她的气场很强。","pinyin":"Tā de qìchǎng hěn qiáng.","vi":"Khí chất của cô ấy rất mạnh."},{"type":"simple","zh":"这位女演员在红毯上展现了十足的气场。","pinyin":"Zhè wèi nǚ yǎnyuán zài hóngtǎn shàng zhǎnxiànle shízú de qìchǎng.","vi":"Nữ diễn viên này đã thể hiện khí chất ngút trời trên thảm đỏ."},{"type":"compound","zh":"新总经理一走进会议室，强大的气场就让全场安静下来。","pinyin":"Xīn zǒngjīnglǐ yì zǒujìn huìyìshì, qiángdà de qìchǎng jiù ràng quánchǎng ānjìng xiàlái.","vi":"Tổng giám đốc mới vừa bước vào phòng họp, khí chất mạnh mẽ đã khiến cả phòng im lặng."}],"related":[{"hanzi":"气质","pinyin":"qìzhì","vi":"khí chất"},{"hanzi":"魅力","pinyin":"mèilì","vi":"sức hút"},{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"}],"traditional":"氣場"},{"id":"气度","hanzi":"气度","pinyin":"qìdù","meaning_vi":"khí độ, phong thái rộng lượng","explanation":"气 (khí phách/khí hậu) + 度 (度).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"他很有气度。","pinyin":"Tā hěn yǒu qìdù.","vi":"Anh ấy rất có khí độ."},{"type":"simple","zh":"老将军用宽容的气度赢得了士兵们的敬重。","pinyin":"Lǎojiāng jūnyòng kuānróng de qìdù yíng déle shìbīngmen de jìngzhòng.","vi":"Vị lão tướng đã giành được sự kính trọng của binh sĩ bằng khí độ khoan dung."},{"type":"compound","zh":"即使被人误解，他也一笑置之，可见他的气度非凡。","pinyin":"Jíshǐ bèi rén wùjiě, tā yě yí xiào zhì zhī, kějiàn tā de qìdù fēifán.","vi":"Cho dù bị người khác hiểu lầm, anh ấy cũng chỉ cười cho qua, đủ thấy khí độ phi phàm của anh ấy."}],"related":[{"hanzi":"气量","pinyin":"qìliàng","vi":"độ lượng"},{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"胸怀","pinyin":"xiōnghuái","vi":"tấm lòng"}],"traditional":"氣度"},{"id":"契合","hanzi":"契合","pinyin":"qìhé","meaning_vi":"ăn khớp, hòa hợp","explanation":"契 (hợp đồng/ăn ý) + 合 (合).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧩","examples":[{"type":"basic","zh":"两人观点契合。","pinyin":"Liǎng rén guāndiǎn qìhé.","vi":"Quan điểm của hai người ăn khớp với nhau."},{"type":"simple","zh":"这首主题曲与电影的氛围契合得恰到好处。","pinyin":"Zhè shǒu zhǔtíqǔ yǔ diànyǐng de fēnwéi qìhé de qiàdàohǎochù.","vi":"Bài hát chủ đề này hòa hợp vừa vặn với bầu không khí của bộ phim."},{"type":"compound","zh":"只要公司的理念与个人价值观契合，员工就更愿意长期留下。","pinyin":"Zhǐyào gōngsī de lǐniàn yǔ gèrén jiàzhíguān qìhé, yuángōng jiù gèng yuànyì chángqī liúxià.","vi":"Chỉ cần triết lý của công ty hòa hợp với giá trị quan cá nhân thì nhân viên sẽ sẵn lòng gắn bó lâu dài hơn."}],"related":[{"hanzi":"吻合","pinyin":"wěnhé","vi":"khớp nhau"},{"hanzi":"符合","pinyin":"fúhé","vi":"phù hợp"},{"hanzi":"默契","pinyin":"mòqì","vi":"ăn ý"}]},{"id":"气节","hanzi":"气节","pinyin":"qìjié","meaning_vi":"khí tiết, lòng tự trọng kiên trung","explanation":"气 (khí phách/khí hậu) + 节 (节).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"🦁","examples":[{"type":"basic","zh":"他是有气节的人。","pinyin":"Tā shì yǒu qìjié de rén.","vi":"Ông ấy là người có khí tiết."},{"type":"simple","zh":"文天祥宁死不降的气节被后人代代传颂。","pinyin":"Wéntiānxiáng nìng sǐ bù xiáng de qìjié bèi hòurén dàidài chuánsòng.","vi":"Khí tiết thà chết không hàng của Văn Thiên Tường được hậu thế truyền tụng qua bao đời."},{"type":"compound","zh":"即使身陷困境，他也坚守气节，不肯接受贿赂。","pinyin":"Jíshǐ shēnxiàn kùnjìng, tā yě jiānshǒu qìjié, bùkěn jiēshòu huìlù.","vi":"Dù rơi vào cảnh khốn cùng, ông ấy vẫn giữ vững khí tiết, không chịu nhận hối lộ."}],"related":[{"hanzi":"骨气","pinyin":"gǔqì","vi":"khí phách"},{"hanzi":"节操","pinyin":"jiécāo","vi":"tiết tháo"},{"hanzi":"民族气节","pinyin":"mínzúqìjié","vi":"khí tiết dân tộc"}],"traditional":"氣節"},{"id":"契机","hanzi":"契机","pinyin":"qìjī","meaning_vi":"thời cơ, cơ hội bước ngoặt","explanation":"契 (hợp đồng/ăn ý) + 机 (cơ hội/máy móc).","hsk_level":"7-9","tags":["danh-tu"],"image":"🔑","examples":[{"type":"basic","zh":"这是一个契机。","pinyin":"Zhè shì yí gè qìjī.","vi":"Đây là một thời cơ."},{"type":"simple","zh":"举办亚运会成为这座城市更新交通的契机。","pinyin":"Jǔbàn Yàyùnhuì chéngwéi zhè zuò chéngshì gēngxīn jiāotōng de qìjī.","vi":"Việc tổ chức Á vận hội trở thành thời cơ để thành phố này đổi mới giao thông."},{"type":"compound","zh":"这次失败虽然痛苦，但是成了他重新反思自己的契机。","pinyin":"Zhè cì shībài suīrán tòngkǔ, dànshì chéngle tā chóngxīn fǎnsī zìjǐ de qìjī.","vi":"Thất bại lần này tuy đau đớn nhưng đã trở thành bước ngoặt để anh ấy tự nhìn nhận lại bản thân."}],"related":[{"hanzi":"机会","pinyin":"jīhuì","vi":"cơ hội"},{"hanzi":"时机","pinyin":"shíjī","vi":"thời cơ"},{"hanzi":"转机","pinyin":"zhuǎnjī","vi":"bước ngoặt"}],"traditional":"契機"},{"id":"气馁","hanzi":"气馁","pinyin":"qìněi","meaning_vi":"nản lòng, nhụt chí","explanation":"气 (khí phách/khí hậu) + 馁 (nản lòng/nhụt chí).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"别气馁，再试试。","pinyin":"Bié qìněi, zài shìshi.","vi":"Đừng nản lòng, thử lại xem."},{"type":"simple","zh":"第一次创业失败并没有让他感到气馁。","pinyin":"Dìyīcì chuàngyè shībài bìng méiyǒu ràng tā gǎndào qìněi.","vi":"Lần khởi nghiệp thất bại đầu tiên không hề khiến anh ấy nản lòng."},{"type":"compound","zh":"即使连续被拒绝了十次，她也没有气馁。","pinyin":"Jíshǐ liánxù bèi jùjuéle shí cì, tā yě méiyǒu qìněi.","vi":"Dù bị từ chối liên tiếp mười lần, cô ấy cũng không nản lòng."}],"related":[{"hanzi":"灰心","pinyin":"huīxīn","vi":"nản lòng"},{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"振作","pinyin":"zhènzuò","vi":"phấn chấn"}],"traditional":"氣餒"},{"id":"弃权","hanzi":"弃权","pinyin":"qìquán","meaning_vi":"bỏ quyền (bỏ phiếu trắng / rút lui thi đấu)","explanation":"弃 (vứt bỏ/từ bỏ) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏳️","examples":[{"type":"basic","zh":"他投了弃权票。","pinyin":"Tā tóule qìquán piào.","vi":"Anh ấy đã bỏ phiếu trắng."},{"type":"simple","zh":"这位网球选手因脚踝受伤宣布弃权。","pinyin":"Zhè wèi wǎngqiú xuǎnshǒu yīn jiǎohuái shòushāng xuānbù qìquán.","vi":"Tay vợt này tuyên bố bỏ cuộc vì bị chấn thương mắt cá chân."},{"type":"compound","zh":"如果比赛开始前十分钟还没到场，就视为弃权。","pinyin":"Rúguǒ bǐsài kāishǐ qián shí fēnzhōng hái méi dàochǎng, jiù shìwéi qìquán.","vi":"Nếu mười phút trước khi trận đấu bắt đầu vẫn chưa có mặt thì sẽ bị coi là bỏ cuộc."}],"related":[{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"投票","pinyin":"tóupiào","vi":"bỏ phiếu"},{"hanzi":"退赛","pinyin":"tuìsài","vi":"rút khỏi cuộc thi"}],"traditional":"棄權"},{"id":"气势磅礴","hanzi":"气势磅礴","pinyin":"qìshì-pángbó","meaning_vi":"khí thế hùng vĩ tráng lệ","explanation":"气 (khí phách/khí hậu) + 势 (thế lực/xu thế) + 磅 (hùng vĩ/đơn vị pao) + 礴 (礴).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏔️","examples":[{"type":"basic","zh":"黄河气势磅礴。","pinyin":"Huánghé qìshìpángbó.","vi":"Hoàng Hà khí thế hùng vĩ."},{"type":"simple","zh":"音乐厅里响起了气势磅礴的《黄河大合唱》。","pinyin":"Yīnyuètīng lǐ xiǎngqǐle qìshìpángbó de Huánghédàhéchàng.","vi":"Trong phòng hòa nhạc vang lên bản \"Đại hợp xướng Hoàng Hà\" đầy khí thế hùng tráng."},{"type":"compound","zh":"一登上长城，气势磅礴的群山就尽收眼底。","pinyin":"Yì dēngshàng Chángchéng, qìshìpángbó de qúnshān jiù jìn shōu yǎndǐ.","vi":"Vừa leo lên Vạn Lý Trường Thành, dãy núi hùng vĩ tráng lệ đã thu trọn vào tầm mắt."}],"related":[{"hanzi":"气势","pinyin":"qìshì","vi":"khí thế"},{"hanzi":"雄伟","pinyin":"xióngwěi","vi":"hùng vĩ"},{"hanzi":"波澜壮阔","pinyin":"bōlánzhuàngkuò","vi":"hùng tráng mênh mông"}],"traditional":"氣勢磅礴"},{"id":"气息","hanzi":"气息","pinyin":"qìxī","meaning_vi":"hơi thở; không khí, hơi hướng đặc trưng","explanation":"气 (khí phách/khí hậu) + 息 (tin tức/nghỉ ngơi).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌬️","examples":[{"type":"basic","zh":"空气中有春天的气息。","pinyin":"Kōngqì zhōng yǒu chūntiān de qìxī.","vi":"Trong không khí có hơi thở của mùa xuân."},{"type":"simple","zh":"这条胡同里处处洋溢着老北京的生活气息。","pinyin":"Zhè tiáo hútòng lǐ chùchù yángyìzhe lǎoběijīng de shēnghuó qìxī.","vi":"Con ngõ này đâu đâu cũng tràn ngập hơi thở cuộc sống của Bắc Kinh xưa."},{"type":"compound","zh":"病人虽然还有微弱的气息，但是情况十分危急。","pinyin":"Bìngrén suīrán háiyǒu wēiruò de qìxī, dànshì qíngkuàng shífēn wēijí.","vi":"Bệnh nhân tuy vẫn còn hơi thở yếu ớt nhưng tình hình rất nguy cấp."}],"related":[{"hanzi":"气味","pinyin":"qìwèi","vi":"mùi"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hơi thở"},{"hanzi":"氛围","pinyin":"fēnwéi","vi":"bầu không khí"}],"traditional":"氣息"},{"id":"器械","hanzi":"器械","pinyin":"qìxiè","meaning_vi":"dụng cụ, thiết bị máy móc","explanation":"器 (thiết bị/cơ quan) + 械 (械).","hsk_level":"7-9","tags":["danh-tu","do-vat","the-thao"],"image":"🏋️","examples":[{"type":"basic","zh":"健身房器械很新。","pinyin":"Jiànshēnfáng qìxiè hěn xīn.","vi":"Dụng cụ ở phòng tập rất mới."},{"type":"simple","zh":"医院新引进了一批先进的手术器械。","pinyin":"Yīyuàn xīn yǐnjìnle yìpī xiānjìn de shǒushù qìxiè.","vi":"Bệnh viện vừa nhập về một lô dụng cụ phẫu thuật tiên tiến."},{"type":"compound","zh":"使用器械之前如果不热身，就很容易拉伤肌肉。","pinyin":"Shǐyòng qìxiè zhīqián rúguǒ bú rèshēn, jiù hěn róngyì lāshāng jīròu.","vi":"Trước khi dùng thiết bị tập nếu không khởi động thì rất dễ bị căng cơ."}],"related":[{"hanzi":"器材","pinyin":"qìcái","vi":"dụng cụ"},{"hanzi":"医疗器械","pinyin":"yīliáoqìxiè","vi":"thiết bị y tế"},{"hanzi":"健身器械","pinyin":"jiànshēnqìxiè","vi":"dụng cụ tập thể hình"}]},{"id":"契约","hanzi":"契约","pinyin":"qìyuē","meaning_vi":"khế ước, hợp đồng cam kết","explanation":"契 (hợp đồng/ăn ý) + 约 (ràng buộc/hiệp ước).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"双方签订了契约。","pinyin":"Shuāngfāng qiāndìngle qìyuē.","vi":"Hai bên đã ký kết khế ước."},{"type":"simple","zh":"这份清朝的土地契约如今收藏在省博物馆里。","pinyin":"Zhè fèn Qīngcháo de tǔdì qìyuē rújīn shōucáng zài shěng bówùguǎn lǐ.","vi":"Khế ước đất đai từ thời nhà Thanh này nay được lưu giữ tại bảo tàng tỉnh."},{"type":"compound","zh":"既然签了契约，双方就必须严格履行各自的义务。","pinyin":"Jìrán qiānle qìyuē, shuāngfāng jiù bìxū yángé lǚxíng gèzì de yìwù.","vi":"Đã ký khế ước thì hai bên phải nghiêm túc thực hiện nghĩa vụ của mình."}],"related":[{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"协议","pinyin":"xiéyì","vi":"thỏa thuận"},{"hanzi":"契约精神","pinyin":"qìyuējīngshén","vi":"tinh thần giữ cam kết"}],"traditional":"契約"},{"id":"气宇轩昂","hanzi":"气宇轩昂","pinyin":"qìyǔ-xuān'áng","meaning_vi":"phong độ đĩnh đạc hiên ngang","explanation":"气 (khí phách/khí hậu) + 宇 (vũ trụ/nhà cửa) + 轩 (hiên ngang/cửa sổ) + 昂 (ngẩng cao/sôi nổi).","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🤵","examples":[{"type":"basic","zh":"他气宇轩昂。","pinyin":"Tā qìyǔxuān'áng.","vi":"Anh ấy phong độ đĩnh đạc hiên ngang."},{"type":"simple","zh":"一位气宇轩昂的中年男子走上了讲台。","pinyin":"Yí wèi qìyǔxuān'áng de zhōngnián nánzǐ zǒushàngle jiǎngtái.","vi":"Một người đàn ông trung niên phong thái hiên ngang bước lên bục giảng."},{"type":"compound","zh":"他一穿上军装，就显得格外气宇轩昂。","pinyin":"Tā yì chuānshàng jūnzhuāng, jiù xiǎnde géwài qìyǔxuān'áng.","vi":"Anh ấy vừa mặc quân phục vào là trông đặc biệt hiên ngang đĩnh đạc."}],"related":[{"hanzi":"英俊潇洒","pinyin":"yīngjùnxiāosǎ","vi":"đẹp trai phóng khoáng"},{"hanzi":"器宇不凡","pinyin":"qìyǔbùfán","vi":"phong thái phi phàm"},{"hanzi":"神采奕奕","pinyin":"shéncǎiyìyì","vi":"tinh thần phấn chấn"}],"traditional":"氣宇軒昂"},{"id":"气质","hanzi":"气质","pinyin":"qìzhì","meaning_vi":"khí chất","explanation":"气 (khí phách/khí hậu) + 质 (chất lượng/bản chất).","hsk_level":"7-9","tags":["danh-tu"],"image":"✨","examples":[{"type":"basic","zh":"她气质很优雅。","pinyin":"Tā qìzhì hěn yōuyǎ.","vi":"Cô ấy có khí chất rất thanh lịch."},{"type":"simple","zh":"常年练习书法让他身上多了一种沉静的气质。","pinyin":"Chángnián liànxí shūfǎ ràng tā shēnshàng duōle yì zhǒng chénjìng de qìzhì.","vi":"Nhiều năm luyện thư pháp khiến anh ấy có thêm một khí chất trầm tĩnh."},{"type":"compound","zh":"虽然她穿得很朴素，但是气质十分出众。","pinyin":"Suīrán tā chuān de hěn pǔsù, dànshì qìzhì shífēn chūzhòng.","vi":"Tuy cô ấy ăn mặc giản dị nhưng khí chất rất nổi bật."}],"related":[{"hanzi":"气场","pinyin":"qìchǎng","vi":"khí chất"},{"hanzi":"风度","pinyin":"fēngdù","vi":"phong độ"},{"hanzi":"性格","pinyin":"xìnggé","vi":"tính cách"}],"traditional":"氣質"},{"id":"庆典","hanzi":"庆典","pinyin":"qìngdiǎn","meaning_vi":"lễ kỷ niệm trọng đại","explanation":"庆 (chúc mừng/may mắn) + 典 (điển hình/nghi lễ).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎊","examples":[{"type":"basic","zh":"庆典明天举行。","pinyin":"Qìngdiǎn míngtiān jǔxíng.","vi":"Lễ kỷ niệm sẽ được tổ chức vào ngày mai."},{"type":"simple","zh":"学校为建校百年庆典邀请了上千名校友。","pinyin":"Xuéxiào wèi jiàn xiào bǎinián qìngdiǎn yāoqǐngle shàng qiān míng xiàoyǒu.","vi":"Nhà trường đã mời hơn một nghìn cựu học sinh cho lễ kỷ niệm trăm năm thành lập trường."},{"type":"compound","zh":"因为天气突变，所以户外庆典临时改到了体育馆。","pinyin":"Yīnwèi tiānqì tūbiàn, suǒyǐ hùwài qìngdiǎn línshí gǎi dàole tǐyùguǎn.","vi":"Vì thời tiết đột ngột thay đổi nên lễ kỷ niệm ngoài trời tạm thời chuyển vào nhà thi đấu."}],"related":[{"hanzi":"庆祝","pinyin":"qìngzhù","vi":"chúc mừng"},{"hanzi":"典礼","pinyin":"diǎnlǐ","vi":"lễ"},{"hanzi":"盛典","pinyin":"shèngdiǎn","vi":"đại lễ"}],"traditional":"慶典"},{"id":"齐备","hanzi":"齐备","pinyin":"qíbèi","meaning_vi":"đầy đủ trọn vẹn","explanation":"齐 (đồng lòng/đầy đủ) + 备 (chuẩn bị/đầy đủ).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"材料已经齐备。","pinyin":"Cáiliào yǐjīng qíbèi.","vi":"Tài liệu đã đầy đủ."},{"type":"simple","zh":"新装修的厨房里各种厨具一应齐备。","pinyin":"Xīn zhuāngxiū de chúfáng lǐ gèzhǒng chújù yìyīng qíbèi.","vi":"Trong căn bếp mới sửa sang, đủ loại dụng cụ nấu ăn đều có đầy đủ."},{"type":"compound","zh":"只要手续齐备，签证一周之内就能办好。","pinyin":"Zhǐyào shǒuxù qíbèi, qiānzhèng yìzhōu zhīnèi jiù néng bànhǎo.","vi":"Chỉ cần thủ tục đầy đủ thì visa trong vòng một tuần là làm xong."}],"related":[{"hanzi":"齐全","pinyin":"qíquán","vi":"đầy đủ"},{"hanzi":"完备","pinyin":"wánbèi","vi":"hoàn bị"},{"hanzi":"残缺","pinyin":"cánquē","vi":"thiếu sót"}],"traditional":"齊備"},{"id":"奇观","hanzi":"奇观","pinyin":"qíguān","meaning_vi":"kỳ quan","explanation":"奇 (kỳ diệu/kỳ lạ) + 观 (观).","hsk_level":"7-9","tags":["danh-tu","du-lich","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"极光是自然奇观。","pinyin":"Jí guāngshì zìrán qíguān.","vi":"Cực quang là kỳ quan thiên nhiên."},{"type":"simple","zh":"钱塘江大潮被誉为天下奇观。","pinyin":"Qiántángjiāng dàcháo bèi yù wéi tiānxià qíguān.","vi":"Thủy triều lớn trên sông Tiền Đường được ca ngợi là kỳ quan thiên hạ."},{"type":"compound","zh":"每当日落时分，沙漠中就会出现海市蜃楼的奇观。","pinyin":"Měidāng rìluò shífēn, shāmò zhōng jiù huì chūxiàn hǎishì shèn lóu de qíguān.","vi":"Mỗi khi hoàng hôn buông xuống, giữa sa mạc lại xuất hiện kỳ quan ảo ảnh."}],"related":[{"hanzi":"奇迹","pinyin":"qíjì","vi":"kỳ tích"},{"hanzi":"景观","pinyin":"jǐngguān","vi":"cảnh quan"},{"hanzi":"壮观","pinyin":"zhuàngguān","vi":"hùng vĩ"}],"traditional":"奇觀"},{"id":"旗号","hanzi":"旗号","pinyin":"qíhào","meaning_vi":"danh nghĩa, ngọn cờ hiệu","explanation":"旗 (ngọn cờ) + 号 (ngày (trong tháng)).","hsk_level":"7-9","tags":["danh-tu"],"image":"🚩","examples":[{"type":"basic","zh":"他打着慈善的旗号。","pinyin":"Tā dǎzhe císhàn de qíhào.","vi":"Hắn lấy danh nghĩa từ thiện."},{"type":"simple","zh":"骗子打着免费体检的旗号向老人推销保健品。","pinyin":"Piànzi dǎzhe miǎnfèi tǐjiǎn de qíhào xiàng lǎorén tuīxiāo bǎojiànpǐn.","vi":"Kẻ lừa đảo lấy danh nghĩa khám sức khỏe miễn phí để chào bán thực phẩm chức năng cho người già."},{"type":"compound","zh":"有些商家虽然打着环保的旗号，但是产品根本不环保。","pinyin":"Yǒuxiē shāngjiā suīrán dǎzhe huánbǎo de qíhào, dànshì chǎnpǐn gēnběnbù huánbǎo.","vi":"Một số doanh nghiệp tuy giương ngọn cờ bảo vệ môi trường nhưng sản phẩm hoàn toàn không thân thiện với môi trường."}],"related":[{"hanzi":"旗帜","pinyin":"qízhì","vi":"lá cờ"},{"hanzi":"名义","pinyin":"míngyì","vi":"danh nghĩa"},{"hanzi":"幌子","pinyin":"huǎngzi","vi":"chiêu bài"}],"traditional":"旗號"},{"id":"齐聚","hanzi":"齐聚","pinyin":"qíjù","meaning_vi":"tụ họp đông đủ","explanation":"齐 (đồng lòng/đầy đủ) + 聚 (tụ họp/ngưng tụ).","hsk_level":"7-9","tags":["dong-tu"],"image":"👥","examples":[{"type":"basic","zh":"家人齐聚一堂。","pinyin":"Jiārén qíjù yì táng.","vi":"Gia đình tụ họp đông đủ một nhà."},{"type":"simple","zh":"来自三十个国家的选手齐聚杭州参加比赛。","pinyin":"Láizì sānshí gè guójiā de xuǎnshǒu qíjù Hángzhōu cānjiā bǐsài.","vi":"Các vận động viên đến từ ba mươi quốc gia tụ họp đông đủ tại Hàng Châu để tham gia thi đấu."},{"type":"compound","zh":"每到除夕，全家人就会齐聚在奶奶家吃团圆饭。","pinyin":"Měi dào Chúxī, quán jiārén jiù huì qíjù zài nǎinai jiā chī tuányuánfàn.","vi":"Mỗi dịp giao thừa, cả nhà lại tụ họp đông đủ ở nhà bà để ăn bữa cơm đoàn viên."}],"related":[{"hanzi":"聚集","pinyin":"jùjí","vi":"tụ tập"},{"hanzi":"齐聚一堂","pinyin":"qíjùyìtáng","vi":"tụ họp đông đủ"},{"hanzi":"汇聚","pinyin":"huìjù","vi":"hội tụ"}],"traditional":"齊聚"},{"id":"齐名","hanzi":"齐名","pinyin":"qímíng","meaning_vi":"nổi tiếng ngang nhau","explanation":"齐 (đồng lòng/đầy đủ) + 名 (danh tiếng/nổi tiếng).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🌟","examples":[{"type":"basic","zh":"李杜二人齐名。","pinyin":"Lǐ dù èr rén qímíng.","vi":"Lý Bạch và Đỗ Phủ nổi tiếng ngang nhau."},{"type":"simple","zh":"这座古镇与周庄齐名，是江南水乡的代表。","pinyin":"Zhè zuò gǔzhèn yǔ Zhōuzhuāng qímíng, shì Jiāngnánshuǐxiāng de dàibiǎo.","vi":"Thị trấn cổ này nổi tiếng ngang với Chu Trang, là đại diện của vùng sông nước Giang Nam."},{"type":"compound","zh":"他虽然与那位大师齐名，但是作品风格完全不同。","pinyin":"Tā suīrán yǔ nà wèi dàshī qímíng, dànshì zuòpǐn fēnggé wánquán bùtóng.","vi":"Tuy ông ấy nổi tiếng ngang với vị đại sư kia nhưng phong cách tác phẩm hoàn toàn khác."}],"related":[{"hanzi":"并称","pinyin":"bìngchēng","vi":"cùng được gọi"},{"hanzi":"著名","pinyin":"zhùmíng","vi":"nổi tiếng"},{"hanzi":"闻名","pinyin":"wénmíng","vi":"nổi danh"}],"traditional":"齊名"},{"id":"奇思妙想","hanzi":"奇思妙想","pinyin":"qísī-miàoxiǎng","meaning_vi":"ý tưởng độc đáo kỳ diệu","explanation":"奇 (kỳ diệu/kỳ lạ) + 思 (suy nghĩ/tư duy) + 妙 (tuyệt diệu/khéo léo) + 想 (muốn).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💡","examples":[{"type":"basic","zh":"孩子们奇思妙想多。","pinyin":"Háizimen qísīmiàoxiǎng duō.","vi":"Trẻ con có nhiều ý tưởng độc đáo kỳ diệu."},{"type":"simple","zh":"这场设计大赛展出了许多学生的奇思妙想。","pinyin":"Zhè chǎng shèjì dàsài zhǎnchūle xǔduō xuéshēng de qísīmiàoxiǎng.","vi":"Cuộc thi thiết kế này đã trưng bày nhiều ý tưởng độc đáo của học sinh."},{"type":"compound","zh":"只要有一点奇思妙想，旧纸箱也能变成漂亮的玩具屋。","pinyin":"Zhǐyào yǒuyìdiǎn qísīmiàoxiǎng, jiù zhǐxiāng yě néng biànchéng piàoliang de wánjù wū.","vi":"Chỉ cần có một chút ý tưởng độc đáo, thùng giấy cũ cũng có thể biến thành ngôi nhà đồ chơi xinh xắn."}],"related":[{"hanzi":"创意","pinyin":"chuàngyì","vi":"ý tưởng sáng tạo"},{"hanzi":"想象力","pinyin":"xiǎngxiànglì","vi":"sức tưởng tượng"},{"hanzi":"灵感","pinyin":"línggǎn","vi":"cảm hứng"}]},{"id":"歧途","hanzi":"歧途","pinyin":"qítú","meaning_vi":"con đường sai lầm, lầm đường lạc lối","explanation":"歧 (bất đồng/kỳ thị) + 途 (con đường/tiền đồ).","hsk_level":"7-9","tags":["danh-tu"],"image":"🔀","examples":[{"type":"basic","zh":"他误入了歧途。","pinyin":"Tā wù rùle qítú.","vi":"Cậu ấy đã lầm đường lạc lối."},{"type":"simple","zh":"社区志愿者帮助几名误入歧途的少年重返校园。","pinyin":"Shèqū zhìyuànzhě bāngzhù jǐ míng wù rù qítú de shàonián chóngfǎn xiàoyuán.","vi":"Tình nguyện viên khu dân cư đã giúp mấy thiếu niên lầm đường lạc lối quay lại trường học."},{"type":"compound","zh":"如果没有父亲及时拉他一把，他可能早就走上了歧途。","pinyin":"Rúguǒ méiyǒu fùqīn jíshí lā tā yì bǎ, tā kěnéng zǎojiù zǒushàngle qítú.","vi":"Nếu không có cha kịp thời kéo lại, có lẽ cậu ấy đã sớm đi vào con đường sai lầm."}],"related":[{"hanzi":"误入歧途","pinyin":"wùrùqítú","vi":"lầm đường lạc lối"},{"hanzi":"邪路","pinyin":"xiélù","vi":"đường tà"},{"hanzi":"正道","pinyin":"zhèngdào","vi":"con đường đúng"}]},{"id":"奇效","hanzi":"奇效","pinyin":"qíxiào","meaning_vi":"hiệu quả thần kỳ","explanation":"奇 (kỳ diệu/kỳ lạ) + 效 (hiệu quả/hiệu suất).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"✨","examples":[{"type":"basic","zh":"这个偏方有奇效。","pinyin":"Zhè ge piānfāng yǒu qíxiào.","vi":"Bài thuốc dân gian này có hiệu quả thần kỳ."},{"type":"simple","zh":"教练的一次临场换人在决赛中收到了奇效。","pinyin":"Jiàoliàn de yí cì línchǎng huànrén zài juésài zhōng shōudàole qíxiào.","vi":"Một lần thay người tại chỗ của huấn luyện viên đã mang lại hiệu quả thần kỳ trong trận chung kết."},{"type":"compound","zh":"广告虽然宣称有奇效，但是这种药并没有科学依据。","pinyin":"Guǎnggào suīrán xuānchēng yǒu qíxiào, dànshì zhè zhǒng yào bìng méiyǒu kēxué yījù.","vi":"Quảng cáo tuy tuyên bố có hiệu quả thần kỳ nhưng loại thuốc này không hề có căn cứ khoa học."}],"related":[{"hanzi":"疗效","pinyin":"liáoxiào","vi":"hiệu quả điều trị"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"神奇","pinyin":"shénqí","vi":"thần kỳ"}]},{"id":"勤奋好学","hanzi":"勤奋好学","pinyin":"qínfèn-hàoxué","meaning_vi":"chăm chỉ hiếu học","explanation":"勤 (cần cù) + 奋 (奋) + 好 (tốt) + 学 (học thuật/học thuyết).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他勤奋好学。","pinyin":"Tā qínfènhàoxué.","vi":"Cậu ấy chăm chỉ hiếu học."},{"type":"simple","zh":"这个勤奋好学的女孩每天清晨都在院子里背单词。","pinyin":"Zhè ge qínfènhàoxué de nǚhái měitiān qīngchén dōu zài yuànzi lǐ bèi dāncí.","vi":"Cô bé chăm chỉ hiếu học này sáng sớm nào cũng học thuộc từ vựng trong sân."},{"type":"compound","zh":"他不但勤奋好学，而且乐于帮助成绩落后的同学。","pinyin":"Tā búdàn qínfènhàoxué, érqiě lèyú bāngzhù chéngjì luòhòu de tóngxué.","vi":"Cậu ấy không những chăm chỉ hiếu học mà còn sẵn lòng giúp đỡ các bạn học kém."}],"related":[{"hanzi":"勤奋","pinyin":"qínfèn","vi":"chăm chỉ"},{"hanzi":"好学","pinyin":"hàoxué","vi":"hiếu học"},{"hanzi":"刻苦","pinyin":"kèkǔ","vi":"chịu khó"}],"traditional":"勤奮好學"},{"id":"勤俭节约","hanzi":"勤俭节约","pinyin":"qínjiǎn-jiéyuē","meaning_vi":"cần kiệm tiết kiệm","explanation":"勤 (cần cù) + 俭 (tiết kiệm) + 节 (节) + 约 (ràng buộc/hiệp ước).","hsk_level":"7-9","tags":["thanh-ngu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"奶奶一向勤俭节约。","pinyin":"Nǎinai yíxiàng qínjiǎnjiéyuē.","vi":"Bà xưa nay luôn cần kiệm tiết kiệm."},{"type":"simple","zh":"这对老夫妻靠勤俭节约攒下了孙子的学费。","pinyin":"Zhè duì lǎo fūqī kào qínjiǎnjiéyuē zǎn xiàle sūnzi de xuéfèi.","vi":"Đôi vợ chồng già nhờ cần kiệm tiết kiệm mà dành dụm được học phí cho cháu nội."},{"type":"compound","zh":"即使生活富裕了，我们也不能丢掉勤俭节约的传统。","pinyin":"Jíshǐ shēnghuó fùyù le, wǒmen yě bù néng diūdiào qínjiǎnjiéyuē de chuántǒng.","vi":"Cho dù cuộc sống đã sung túc, chúng ta cũng không được đánh mất truyền thống cần kiệm."}],"related":[{"hanzi":"勤俭","pinyin":"qínjiǎn","vi":"cần kiệm"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"tiết kiệm"},{"hanzi":"铺张浪费","pinyin":"pūzhānglàngfèi","vi":"phung phí"}],"traditional":"勤儉節約"},{"id":"勤劳勇敢","hanzi":"勤劳勇敢","pinyin":"qínláo-yǒnggǎn","meaning_vi":"cần cù dũng cảm","explanation":"勤 (cần cù) + 劳 (lao động/vất vả) + 勇 (dũng cảm) + 敢 (dám).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💪","examples":[{"type":"basic","zh":"这是个勤劳勇敢的民族。","pinyin":"Zhè shì gè qínláoyǒnggǎn de mínzú.","vi":"Đây là một dân tộc cần cù dũng cảm."},{"type":"simple","zh":"勤劳勇敢的渔民们世世代代在这片海上谋生。","pinyin":"Qínláoyǒnggǎn de yúmínmen shìshìdàidài zài zhè piàn hǎishàng móushēng.","vi":"Những ngư dân cần cù dũng cảm đời đời mưu sinh trên vùng biển này."},{"type":"compound","zh":"因为村民们勤劳勇敢，所以荒山变成了果园。","pinyin":"Yīnwèi cūnmínmen qínláoyǒnggǎn, suǒyǐ huāngshān biàn chéngle guǒyuán.","vi":"Vì dân làng cần cù dũng cảm nên núi hoang đã biến thành vườn cây ăn quả."}],"related":[{"hanzi":"勤劳","pinyin":"qínláo","vi":"cần cù"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"dũng cảm"},{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"}],"traditional":"勤勞勇敢"},{"id":"情操","hanzi":"情操","pinyin":"qíngcāo","meaning_vi":"tình cảm cao đẹp, phẩm chất tinh thần","explanation":"情 (tình cảm/tình hình) + 操 (thao tác/đạo đức).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🎨","examples":[{"type":"basic","zh":"音乐能陶冶情操。","pinyin":"Yīnyuè néng táoyě qíngcāo.","vi":"Âm nhạc có thể bồi dưỡng tâm hồn."},{"type":"simple","zh":"这部纪录片歌颂了医生们舍己为人的高尚情操。","pinyin":"Zhè bù jìlùpiàn gēsòngle yīshēngmen shějǐwèirén de gāoshàng qíngcāo.","vi":"Bộ phim tài liệu này ca ngợi phẩm chất cao đẹp xả thân vì người khác của các bác sĩ."},{"type":"compound","zh":"读书不但能增长知识，而且可以陶冶情操。","pinyin":"Dúshū búdàn néng zēngzhǎng zhīshi, érqiě kěyǐ táoyě qíngcāo.","vi":"Đọc sách không những có thể mở mang kiến thức mà còn bồi dưỡng tâm hồn."}],"related":[{"hanzi":"品德","pinyin":"pǐndé","vi":"phẩm đức"},{"hanzi":"情感","pinyin":"qínggǎn","vi":"tình cảm"},{"hanzi":"陶冶情操","pinyin":"táoyěqíngcāo","vi":"hun đúc tâm hồn"}]},{"id":"情怀","hanzi":"情怀","pinyin":"qínghuái","meaning_vi":"tấm lòng, hoài bão tình cảm","explanation":"情 (tình cảm/tình hình) + 怀 (hoài niệm/lòng).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","van-hoa"],"image":"❤️","examples":[{"type":"basic","zh":"他有家国情怀。","pinyin":"Tā yǒu jiā guó qínghuái.","vi":"Ông ấy có tấm lòng với gia đình và đất nước."},{"type":"simple","zh":"这家老书店凭着一份文化情怀坚持经营了三十年。","pinyin":"Zhè jiālǎo shūdiàn píngzhe yí fèn wénhuà qínghuái jiānchí jīngyíngle sānshí nián.","vi":"Hiệu sách cũ này nhờ tấm lòng với văn hóa mà kiên trì kinh doanh suốt ba mươi năm."},{"type":"compound","zh":"创业虽然需要情怀，但是更需要清晰的商业模式。","pinyin":"Chuàngyè suīrán xūyào qínghuái, dànshì gèng xūyào qīngxī de shāngyè móshì.","vi":"Khởi nghiệp tuy cần tâm huyết nhưng càng cần mô hình kinh doanh rõ ràng."}],"related":[{"hanzi":"胸怀","pinyin":"xiōnghuái","vi":"tấm lòng"},{"hanzi":"家国情怀","pinyin":"jiāguóqínghuái","vi":"tình yêu quê hương đất nước"},{"hanzi":"情感","pinyin":"qínggǎn","vi":"tình cảm"}],"traditional":"情懷"},{"id":"晴空万里","hanzi":"晴空万里","pinyin":"qíngkōng-wànlǐ","meaning_vi":"trời quang mây tạnh","explanation":"晴 (nắng) + 空 (trống rỗng/không gian) + 万 (vạn vật/tuyệt đối) + 里 (trong).","hsk_level":"7-9","tags":["thanh-ngu","thoi-tiet"],"image":"☀️","examples":[{"type":"basic","zh":"今天晴空万里。","pinyin":"Jīntiān qíngkōngwànlǐ.","vi":"Hôm nay trời quang mây tạnh."},{"type":"simple","zh":"运动会开幕那天正好是个晴空万里的好日子。","pinyin":"Yùndònghuì kāimù nà tiān zhènghǎo shì gè qíngkōngwànlǐ de hǎorìzi.","vi":"Ngày khai mạc đại hội thể thao vừa đúng là một ngày đẹp trời quang mây tạnh."},{"type":"compound","zh":"飞机一穿过云层，窗外就是晴空万里。","pinyin":"Fēijī yì chuānguò yúncéng, chuāng wài jiùshì qíngkōngwànlǐ.","vi":"Máy bay vừa xuyên qua tầng mây, ngoài cửa sổ đã là bầu trời quang đãng bao la."}],"related":[{"hanzi":"万里无云","pinyin":"wànlǐwúyún","vi":"trời không gợn mây"},{"hanzi":"晴朗","pinyin":"qínglǎng","vi":"quang đãng"},{"hanzi":"阴云密布","pinyin":"yīnyúnmìbù","vi":"mây đen dày đặc"}],"traditional":"晴空萬里"},{"id":"情投意合","hanzi":"情投意合","pinyin":"qíngtóu-yìhé","meaning_vi":"tâm đầu ý hợp","explanation":"情 (tình cảm/tình hình) + 投 (đầu tư/bỏ phiếu) + 意 (ý thức/ý nghĩa) + 合 (合).","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"💑","examples":[{"type":"basic","zh":"两人情投意合。","pinyin":"Liǎng rén qíngtóuyìhé.","vi":"Hai người tâm đầu ý hợp."},{"type":"simple","zh":"他和这位情投意合的伙伴一起开了家书店。","pinyin":"Tā hé zhè wèi qíngtóuyìhé de huǒbàn yìqǐ kāile jiāshū diàn.","vi":"Anh ấy cùng người cộng sự tâm đầu ý hợp này mở một hiệu sách."},{"type":"compound","zh":"既然你们情投意合，就早点把婚事定下来吧。","pinyin":"Jìrán nǐmen qíngtóuyìhé, jiù zǎodiǎn bǎ hūnshì dìng xiàlái ba.","vi":"Hai đứa đã tâm đầu ý hợp thì sớm định ngày cưới đi."}],"related":[{"hanzi":"志同道合","pinyin":"zhìtóngdàohé","vi":"chí hướng hợp nhau"},{"hanzi":"心心相印","pinyin":"xīnxīnxiāngyìn","vi":"tâm đầu ý hợp"},{"hanzi":"默契","pinyin":"mòqì","vi":"ăn ý"}]},{"id":"情谊","hanzi":"情谊","pinyin":"qíngyì","meaning_vi":"tình cảm hữu nghị gắn bó","explanation":"情 (tình cảm/tình hình) + 谊 (tình hữu nghị).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"我们的情谊很深。","pinyin":"Wǒmen de qíngyì hěn shēn.","vi":"Tình cảm gắn bó giữa chúng tôi rất sâu đậm."},{"type":"simple","zh":"这封泛黄的旧信见证了两位老兵半个世纪的情谊。","pinyin":"Zhè fēng fàn huáng de jiù xìn jiànzhèngle liǎng wèi lǎobīng bàn gè shìjì de qíngyì.","vi":"Lá thư cũ ố vàng này chứng kiến tình cảm gắn bó nửa thế kỷ của hai cựu binh."},{"type":"compound","zh":"虽然分别多年，但是同窗的情谊丝毫没有变淡。","pinyin":"Suīrán fēnbié duōnián, dànshì tóngchuāng de qíngyì sīháo méiyǒu biàn dàn.","vi":"Tuy xa cách nhiều năm nhưng tình bạn học chung không hề phai nhạt chút nào."}],"related":[{"hanzi":"友谊","pinyin":"yǒuyì","vi":"tình bạn"},{"hanzi":"情义","pinyin":"qíngyì","vi":"tình nghĩa"},{"hanzi":"深情厚谊","pinyin":"shēnqínghòuyì","vi":"tình sâu nghĩa nặng"}],"traditional":"情誼"},{"id":"趣味性","hanzi":"趣味性","pinyin":"qùwèixìng","meaning_vi":"tính thú vị hấp dẫn","explanation":"趣 (hứng thú) + 味 (hương vị/suy ngẫm) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"😄","examples":[{"type":"basic","zh":"这本书趣味性强。","pinyin":"Zhè běn shū qùwèixìng qiáng.","vi":"Cuốn sách này rất thú vị hấp dẫn."},{"type":"simple","zh":"老师在数学课里加入游戏来增加课堂的趣味性。","pinyin":"Lǎoshī zài shùxué kè lǐ jiārù yóuxì lái zēngjiā kètáng de qùwèixìng.","vi":"Thầy giáo đưa trò chơi vào giờ toán để tăng tính thú vị cho lớp học."},{"type":"compound","zh":"科普节目如果缺乏趣味性，孩子们就看不下去。","pinyin":"Kēpǔ jiémù rúguǒ quēfá qùwèixìng, háizimen jiù kàn bu xiàqù.","vi":"Chương trình phổ biến khoa học nếu thiếu tính thú vị thì bọn trẻ sẽ không xem nổi."}],"related":[{"hanzi":"趣味","pinyin":"qùwèi","vi":"thú vị"},{"hanzi":"知识性","pinyin":"zhīshixìng","vi":"tính kiến thức"},{"hanzi":"娱乐性","pinyin":"yúlèxìng","vi":"tính giải trí"}]},{"id":"群众基础","hanzi":"群众基础","pinyin":"qúnzhòngjīchǔ","meaning_vi":"nền tảng quần chúng","explanation":"群 (đàn) + 众 (quần chúng/đông đảo) + 基 (基) + 础 (nền tảng/chân cột).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"👥","examples":[{"type":"basic","zh":"他有群众基础。","pinyin":"Tā yǒu qúnzhòngjīchǔ.","vi":"Ông ấy có nền tảng quần chúng."},{"type":"simple","zh":"广场舞在中国城乡拥有广泛的群众基础。","pinyin":"Guǎngchǎngwǔ zài Zhōngguó chéngxiāng yōngyǒu guǎngfàn de qúnzhòngjīchǔ.","vi":"Nhảy quảng trường có nền tảng quần chúng rộng rãi ở cả thành thị và nông thôn Trung Quốc."},{"type":"compound","zh":"如果政策缺乏群众基础，推行起来就会阻力重重。","pinyin":"Rúguǒ zhèngcè quēfá qúnzhòngjīchǔ, tuīxíng qǐlái jiù huì zǔlì chóngchóng.","vi":"Nếu chính sách thiếu nền tảng quần chúng thì khi triển khai sẽ gặp trở ngại chồng chất."}],"related":[{"hanzi":"群众","pinyin":"qúnzhòng","vi":"quần chúng"},{"hanzi":"基础","pinyin":"jīchǔ","vi":"nền tảng"},{"hanzi":"民心","pinyin":"mínxīn","vi":"lòng dân"}],"traditional":"群眾基礎"},{"id":"七夕节","hanzi":"七夕节","pinyin":"Qīxījié","meaning_vi":"lễ Thất Tịch (7/7 Âm lịch - Lễ tình nhân truyền thống)","explanation":"七夕 (thất tịch – đêm mùng 7) + 节 (tiết – lễ) → lễ Thất Tịch 7/7 âm lịch, gắn với truyền thuyết Ngưu Lang – Chức Nữ gặp nhau trên cầu Ô Thước.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"💑","examples":[{"type":"basic","zh":"今天是七夕节。","pinyin":"Jīntiān shì Qīxījié.","vi":"Hôm nay là lễ Thất Tịch."},{"type":"simple","zh":"七夕节那天，花店里的玫瑰卖得特别快。","pinyin":"Qīxījié nà tiān, huādiàn lǐ de méigui mài de tèbié kuài.","vi":"Vào ngày lễ Thất Tịch, hoa hồng ở các tiệm hoa bán rất chạy."},{"type":"compound","zh":"七夕节一到，商场里就挂满了牛郎织女的装饰。","pinyin":"Qīxījié yí dào, shāngchǎng lǐ jiù guà mǎnle niúlángzhīnǚ de zhuāngshì.","vi":"Lễ Thất Tịch vừa đến, trung tâm thương mại đã treo đầy đồ trang trí Ngưu Lang Chức Nữ."}],"related":[{"hanzi":"情人节","pinyin":"Qíngrénjié","vi":"Lễ tình nhân"},{"hanzi":"牛郎织女","pinyin":"niúlángzhīnǚ","vi":"Ngưu Lang Chức Nữ"},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vi":"Tết Trung thu"}],"traditional":"七夕節"},{"id":"欺压","hanzi":"欺压","pinyin":"qīyā","meaning_vi":"ức hiếp, áp bức","explanation":"欺 (lừa dối/bắt nạt) + 压 (áp lực/áp bức).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"😠","examples":[{"type":"basic","zh":"不许欺压弱者。","pinyin":"Bùxǔ qīyā ruòzhě.","vi":"Không được ức hiếp kẻ yếu."},{"type":"simple","zh":"旧社会的地主常常欺压无地的佃农。","pinyin":"Jiù shèhuì de dìzhǔ chángcháng qīyā wú dì de diànnóng.","vi":"Địa chủ trong xã hội cũ thường ức hiếp những tá điền không có đất."},{"type":"compound","zh":"如果大家都保持沉默，恶霸就会继续欺压村民。","pinyin":"Rúguǒ dàjiā dōu bǎochí chénmò, èbà jiù huì jìxù qīyā cūnmín.","vi":"Nếu mọi người đều im lặng thì kẻ cường hào sẽ tiếp tục ức hiếp dân làng."}],"related":[{"hanzi":"欺负","pinyin":"qīfu","vi":"bắt nạt"},{"hanzi":"压迫","pinyin":"yāpò","vi":"áp bức"},{"hanzi":"欺凌","pinyin":"qīlíng","vi":"ức hiếp"}],"traditional":"欺壓"},{"id":"侵害","hanzi":"侵害","pinyin":"qīnhài","meaning_vi":"xâm hại","explanation":"侵 (xâm phạm/xâm lược) + 害 (害).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚠️","examples":[{"type":"basic","zh":"他的权益受到侵害。","pinyin":"Tā de quányì shòudào qīnhài.","vi":"Quyền lợi của anh ấy bị xâm hại."},{"type":"simple","zh":"这种病虫害正在严重侵害南方的柑橘林。","pinyin":"Zhè zhǒng bìngchónghài zhèngzài yánzhòng qīnhài nánfāng de gānjú lín.","vi":"Loại sâu bệnh này đang xâm hại nghiêm trọng các vườn cam quýt ở miền Nam."},{"type":"compound","zh":"一旦个人信息被泄露，消费者的隐私就会受到侵害。","pinyin":"Yídàn gèrén xìnxī bèi xièlòu, xiāofèizhě de yǐnsī jiù huì shòudào qīnhài.","vi":"Một khi thông tin cá nhân bị rò rỉ, quyền riêng tư của người tiêu dùng sẽ bị xâm hại."}],"related":[{"hanzi":"侵犯","pinyin":"qīnfàn","vi":"xâm phạm"},{"hanzi":"伤害","pinyin":"shānghài","vi":"tổn hại"},{"hanzi":"侵权","pinyin":"qīnquán","vi":"xâm quyền"}]},{"id":"亲和力","hanzi":"亲和力","pinyin":"qīnhélì","meaning_vi":"sự thân thiện dễ gần, sức hút giao tiếp","explanation":"亲 (thân mật/tự thân) + 和 (và) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"她很有亲和力。","pinyin":"Tā hěn yǒu qīnhélì.","vi":"Cô ấy rất thân thiện dễ gần."},{"type":"simple","zh":"这位主持人凭借自然的亲和力赢得了观众喜爱。","pinyin":"Zhè wèi zhǔchírén píngjiè zìrán de qīnhélì yíng déle guānzhòng xǐ'ài.","vi":"Người dẫn chương trình này nhờ sự thân thiện tự nhiên mà được khán giả yêu mến."},{"type":"compound","zh":"医生如果有亲和力，病人就更愿意说出真实病情。","pinyin":"Yīshēng rúguǒ yǒu qīnhélì, bìngrén jiù gèng yuànyì shuōchū zhēnshí bìngqíng.","vi":"Nếu bác sĩ thân thiện dễ gần thì bệnh nhân sẽ sẵn lòng nói ra tình trạng bệnh thật hơn."}],"related":[{"hanzi":"亲切","pinyin":"qīnqiè","vi":"thân thiết"},{"hanzi":"平易近人","pinyin":"píngyìjìnrén","vi":"dễ gần"},{"hanzi":"魅力","pinyin":"mèilì","vi":"sức hút"}],"traditional":"親和力"},{"id":"亲历","hanzi":"亲历","pinyin":"qīnlì","meaning_vi":"tự mình trải qua","explanation":"亲 (thân mật/tự thân) + 历 (lịch sử/trải qua).","hsk_level":"7-9","tags":["dong-tu"],"image":"👣","examples":[{"type":"basic","zh":"他亲历了那场地震。","pinyin":"Tā qīnlìle nà chǎng dìzhèn.","vi":"Ông ấy đã tự mình trải qua trận động đất đó."},{"type":"simple","zh":"这本书记录了一位战地记者亲历的二十场战争。","pinyin":"Zhè běn shū jìlùle yí wèi zhàndì jìzhě qīnlì de èrshí chǎng zhànzhēng.","vi":"Cuốn sách này ghi lại hai mươi cuộc chiến mà một phóng viên chiến trường đã tự mình trải qua."},{"type":"compound","zh":"只有亲历过那段岁月，才能理解老人们的感受。","pinyin":"Zhǐyǒu qīnlìguo nà duàn suìyuè, cáinéng lǐjiě lǎo rénmen de gǎnshòu.","vi":"Chỉ có người tự mình trải qua những năm tháng ấy mới hiểu được cảm xúc của các cụ."}],"related":[{"hanzi":"亲身经历","pinyin":"qīnshēnjīnglì","vi":"tự mình trải qua"},{"hanzi":"经历","pinyin":"jīnglì","vi":"trải nghiệm"},{"hanzi":"目睹","pinyin":"mùdǔ","vi":"chứng kiến"}],"traditional":"親歷"},{"id":"亲切感","hanzi":"亲切感","pinyin":"qīnqiègǎn","meaning_vi":"cảm giác thân thiết gần gũi","explanation":"亲 (thân mật/tự thân) + 切 (cắt) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","giao-tiep"],"image":"❤️","examples":[{"type":"basic","zh":"乡音让人有亲切感。","pinyin":"Xiāngyīn ràng rén yǒu qīnqiègǎn.","vi":"Giọng quê khiến người ta có cảm giác thân thiết."},{"type":"simple","zh":"异国街头的中文招牌给了我一种莫名的亲切感。","pinyin":"Yìguó jiētóu de Zhōngwén zhāopai gěile wǒ yì zhǒng mòmíng de qīnqiègǎn.","vi":"Những tấm biển hiệu tiếng Trung trên phố nơi đất khách mang lại cho tôi một cảm giác thân thiết khó tả."},{"type":"compound","zh":"虽然我们第一次见面，但是她的笑容让我很有亲切感。","pinyin":"Suīrán wǒmen dìyīcì jiànmiàn, dànshì tā de xiào róngràng wǒ hěn yǒu qīnqiègǎn.","vi":"Tuy chúng tôi mới gặp lần đầu nhưng nụ cười của cô ấy khiến tôi cảm thấy rất thân thiết."}],"related":[{"hanzi":"亲切","pinyin":"qīnqiè","vi":"thân thiết"},{"hanzi":"亲近","pinyin":"qīnjìn","vi":"gần gũi"},{"hanzi":"陌生感","pinyin":"mòshēnggǎn","vi":"cảm giác xa lạ"}],"traditional":"親切感"},{"id":"侵权行为","hanzi":"侵权行为","pinyin":"qīnquánxíngwéi","meaning_vi":"hành vi xâm phạm quyền lợi","explanation":"侵权 (xâm quyền – xâm phạm quyền) + 行为 (hành vi) → hành vi xâm phạm quyền lợi hợp pháp (bản quyền, nhãn hiệu, quyền nhân thân).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"这是侵权行为。","pinyin":"Zhè shì qīnquánxíngwéi.","vi":"Đây là hành vi xâm phạm quyền lợi."},{"type":"simple","zh":"未经授权转载他人文章属于典型的侵权行为。","pinyin":"Wèijīng shòuquán zhuǎnzǎi tārén wénzhāng shǔyú diǎnxíng de qīnquánxíngwéi.","vi":"Đăng lại bài viết của người khác mà không được phép là hành vi xâm phạm quyền điển hình."},{"type":"compound","zh":"一旦发现侵权行为，权利人就可以向法院提起诉讼。","pinyin":"Yídàn fāxiàn qīnquánxíngwéi, quánlìrén jiù kěyǐ xiàng fǎyuàn tíqǐ sùsòng.","vi":"Một khi phát hiện hành vi xâm phạm quyền lợi, chủ sở hữu quyền có thể khởi kiện ra tòa."}],"related":[{"hanzi":"侵权","pinyin":"qīnquán","vi":"xâm quyền"},{"hanzi":"维权","pinyin":"wéiquán","vi":"bảo vệ quyền lợi"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"}],"traditional":"侵權行為"},{"id":"侵入","hanzi":"侵入","pinyin":"qīnrù","meaning_vi":"xâm nhập","explanation":"侵 (xâm phạm/xâm lược) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["dong-tu"],"image":"🚫","examples":[{"type":"basic","zh":"病毒侵入了电脑。","pinyin":"Bìngdú qīnrùle diànnǎo.","vi":"Virus đã xâm nhập vào máy tính."},{"type":"simple","zh":"黑客昨夜侵入了这家银行的内部系统。","pinyin":"Hēikè zuóyè qīnrùle zhè jiā yínháng de nèibù xìtǒng.","vi":"Tin tặc đêm qua đã xâm nhập vào hệ thống nội bộ của ngân hàng này."},{"type":"compound","zh":"冷空气一侵入，气温就会骤降十度以上。","pinyin":"Lěngkōngqì yì qīnrù, qìwēn jiù huì zhòujiàng shí dù yǐshàng.","vi":"Không khí lạnh vừa tràn vào, nhiệt độ sẽ giảm đột ngột hơn mười độ."}],"related":[{"hanzi":"入侵","pinyin":"rùqīn","vi":"xâm nhập"},{"hanzi":"侵略","pinyin":"qīnlüè","vi":"xâm lược"},{"hanzi":"闯入","pinyin":"chuǎngrù","vi":"xông vào"}]},{"id":"亲眼目睹","hanzi":"亲眼目睹","pinyin":"qīnyǎn-mùdǔ","meaning_vi":"tận mắt chứng kiến","explanation":"亲 (thân mật/tự thân) + 眼 (ánh mắt/tầm nhìn) + 目 (mục tiêu/ánh mắt) + 睹 (睹).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👀","examples":[{"type":"basic","zh":"我亲眼目睹了车祸。","pinyin":"Wǒ qīnyǎnmùdǔle chēhuò.","vi":"Tôi đã tận mắt chứng kiến vụ tai nạn xe."},{"type":"simple","zh":"游客们亲眼目睹了冰川崩塌的壮观场面。","pinyin":"Yóukèmen qīnyǎnmùdǔle bīngchuān bēngtā de zhuàngguān chǎngmiàn.","vi":"Du khách đã tận mắt chứng kiến cảnh tượng hùng vĩ của sông băng sụp đổ."},{"type":"compound","zh":"如果不是亲眼目睹，我根本不敢相信他会说谎。","pinyin":"Rúguǒ bú shì qīnyǎnmùdǔ, wǒ gēnběnbù gǎn xiāngxìn tā huì shuōhuǎng.","vi":"Nếu không phải tận mắt chứng kiến, tôi hoàn toàn không dám tin anh ấy lại nói dối."}],"related":[{"hanzi":"目睹","pinyin":"mùdǔ","vi":"chứng kiến"},{"hanzi":"亲眼","pinyin":"qīnyǎn","vi":"tận mắt"},{"hanzi":"耳闻目睹","pinyin":"ěrwénmùdǔ","vi":"tai nghe mắt thấy"}],"traditional":"親眼目睹"},{"id":"清白","hanzi":"清白","pinyin":"qīngbái","meaning_vi":"trong sạch, vô tội","explanation":"清 (trong sạch/rõ nét) + 白 (màu trắng).","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🕊️","examples":[{"type":"basic","zh":"他是清白的。","pinyin":"Tā shì qīngbái de.","vi":"Anh ấy vô tội."},{"type":"simple","zh":"法院最终证明了这位司机的清白。","pinyin":"Fǎyuàn zuìzhōng zhèngmíngle zhè wèi sījī de qīngbái.","vi":"Tòa án cuối cùng đã chứng minh sự trong sạch của người tài xế này."},{"type":"compound","zh":"虽然他被人怀疑偷了钱，但是监控录像证明了他的清白。","pinyin":"Suīrán tā bèi rén huáiyí tōule qián, dànshì jiānkòng lùxiàng zhèngmíngle tā de qīngbái.","vi":"Tuy anh ấy bị nghi ngờ trộm tiền, nhưng video giám sát đã chứng minh anh ấy trong sạch."}],"related":[{"hanzi":"无辜","pinyin":"wúgū","vi":"vô tội"},{"hanzi":"纯洁","pinyin":"chúnjié","vi":"trong sạch"},{"hanzi":"冤枉","pinyin":"yuānwang","vi":"oan uổng"}]},{"id":"青出于蓝而胜于蓝","hanzi":"青出于蓝而胜于蓝","pinyin":"qīngchūyúlán ér shèng yú lán","meaning_vi":"trò giỏi hơn thầy","explanation":"青 (màu xanh (xanh lá/xanh da trời/đen)) + 出 (xuất hiện/xuất sắc) + 于 (ở/đối với) + 蓝 (màu xanh dương) + 而 (mà) + 胜 (thắng lợi/vượt trội) + 于 (ở/đối với) + 蓝 (màu xanh dương).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"学生青出于蓝而胜于蓝。","pinyin":"Xuéshēng qīngchūyúlán ér shèng yú lán.","vi":"Học trò giỏi hơn thầy."},{"type":"simple","zh":"这位年轻画家的作品青出于蓝而胜于蓝。","pinyin":"Zhè wèi niánqīng huàjiā de zuòpǐn qīngchūyúlán ér shèng yú lán.","vi":"Tác phẩm của họa sĩ trẻ này còn vượt cả thầy mình."},{"type":"compound","zh":"只要你肯下苦功，就一定能青出于蓝而胜于蓝。","pinyin":"Zhǐyào nǐ kěn xià kǔgōng, jiù yídìng néng qīngchūyúlán ér shèng yú lán.","vi":"Chỉ cần em chịu khổ luyện, nhất định sẽ giỏi hơn cả thầy."}],"related":[{"hanzi":"后来居上","pinyin":"hòuláijūshàng","vi":"người sau vượt người trước"},{"hanzi":"长江后浪推前浪","pinyin":"Chángjiāng Hòu Làng Tuī Qián Làng","vi":"lớp trẻ thay lớp già"},{"hanzi":"超越","pinyin":"chāoyuè","vi":"vượt qua"},{"hanzi":"学生","pinyin":"xuésheng","vi":"học sinh"}],"traditional":"青出於藍而勝於藍"},{"id":"清脆","hanzi":"清脆","pinyin":"qīngcuì","meaning_vi":"trong trẻo vang vọng (giọng nói/tiếng chuông)","explanation":"清 (trong sạch/rõ nét) + 脆 (giòn/mong manh).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔔","examples":[{"type":"basic","zh":"铃声很清脆。","pinyin":"Língshēng hěn qīngcuì.","vi":"Tiếng chuông rất trong trẻo."},{"type":"simple","zh":"院子里传来小女孩清脆的笑声。","pinyin":"Yuànzi li chuánlái xiǎo nǚhái qīngcuì de xiàoshēng.","vi":"Trong sân vọng ra tiếng cười trong trẻo của cô bé."},{"type":"compound","zh":"风一吹，屋檐下的风铃就发出清脆的响声。","pinyin":"Fēng yì chuī, wūyán xià de fēnglíng jiù fāchū qīngcuì de xiǎngshēng.","vi":"Gió vừa thổi, chuông gió dưới mái hiên liền vang lên tiếng leng keng trong trẻo."}],"related":[{"hanzi":"清亮","pinyin":"qīngliàng","vi":"trong và vang"},{"hanzi":"悦耳","pinyin":"yuè'ěr","vi":"êm tai"},{"hanzi":"响亮","pinyin":"xiǎngliàng","vi":"vang dội"},{"hanzi":"沙哑","pinyin":"shāyǎ","vi":"khàn khàn"}]},{"id":"清凉","hanzi":"清凉","pinyin":"qīngliáng","meaning_vi":"mát mẻ trong lành","explanation":"清 (trong sạch/rõ nét) + 凉 (mát).","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"🍃","examples":[{"type":"basic","zh":"山里的风很清凉。","pinyin":"Shān li de fēng hěn qīngliáng.","vi":"Gió trên núi rất mát mẻ."},{"type":"simple","zh":"夏天喝一碗清凉的绿豆汤最舒服。","pinyin":"Xiàtiān hē yì wǎn qīngliáng de lǜdòu tāng zuì shūfu.","vi":"Mùa hè ăn một bát chè đậu xanh mát lạnh là dễ chịu nhất."},{"type":"compound","zh":"虽然外面烈日炎炎，但是树荫下却十分清凉。","pinyin":"Suīrán wàimiàn lièrì yányán, dànshì shùyīn xià què shífēn qīngliáng.","vi":"Tuy bên ngoài nắng gắt, nhưng dưới bóng cây lại rất mát mẻ."}],"related":[{"hanzi":"凉爽","pinyin":"liángshuǎng","vi":"mát mẻ"},{"hanzi":"清爽","pinyin":"qīngshuǎng","vi":"mát mẻ dễ chịu"},{"hanzi":"闷热","pinyin":"mēnrè","vi":"oi bức"},{"hanzi":"炎热","pinyin":"yánrè","vi":"nóng bức"}],"traditional":"清涼"},{"id":"清明节","hanzi":"清明节","pinyin":"Qīngmíngjié","meaning_vi":"Tết Thanh minh (tảo mộ)","explanation":"清明 + 节 (ngày lễ).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🌿","examples":[{"type":"basic","zh":"清明节快到了。","pinyin":"Qīngmíngjié kuài dào le.","vi":"Sắp đến Tết Thanh minh rồi."},{"type":"simple","zh":"清明节那天，我们全家回老家扫墓。","pinyin":"Qīngmíngjié nà tiān, wǒmen quánjiā huílǎojiā sǎomù.","vi":"Ngày Thanh minh, cả nhà tôi về quê tảo mộ."},{"type":"compound","zh":"每到清明节，路上就挤满了去祭祖的人。","pinyin":"Měi dào Qīngmíngjié, lùshang jiù jǐmǎnle qù jìzǔ de rén.","vi":"Cứ đến Tết Thanh minh, đường sá lại chật kín người đi cúng tổ tiên."}],"related":[{"hanzi":"扫墓","pinyin":"sǎomù","vi":"tảo mộ"},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","vi":"Tết Trung thu"},{"hanzi":"端午节","pinyin":"Duānwǔjié","vi":"Tết Đoan Ngọ"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"}],"traditional":"清明節"},{"id":"清贫","hanzi":"清贫","pinyin":"qīngpín","meaning_vi":"thanh bần, nghèo nhưng trong sạch","explanation":"清 (trong sạch/rõ nét) + 贫 (nghèo nàn/cằn cỗi).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"他一生清贫。","pinyin":"Tā yìshēng qīngpín.","vi":"Ông ấy cả đời thanh bần."},{"type":"simple","zh":"这位老教师过着清贫而充实的生活。","pinyin":"Zhè wèi lǎo jiàoshīguò zhe qīngpín ér chōngshí de shēnghuó.","vi":"Thầy giáo già này sống một cuộc đời thanh bần mà đầy ý nghĩa."},{"type":"compound","zh":"虽然家境清贫，但是父母从不让孩子失学。","pinyin":"Suīrán jiājìng qīngpín, dànshì fùmǔ cóng bú ràng háizi shīxué.","vi":"Tuy gia cảnh thanh bần, nhưng cha mẹ chưa bao giờ để con phải bỏ học."}],"related":[{"hanzi":"贫穷","pinyin":"pínqióng","vi":"nghèo khổ"},{"hanzi":"清廉","pinyin":"qīnglián","vi":"thanh liêm"},{"hanzi":"贫寒","pinyin":"pínhán","vi":"nghèo túng"},{"hanzi":"富裕","pinyin":"fùyù","vi":"giàu có"}],"traditional":"清貧"},{"id":"倾诉","hanzi":"倾诉","pinyin":"qīngsù","meaning_vi":"tâm sự, giãi bày nỗi lòng","explanation":"倾 (lắng nghe/khuynh hướng) + 诉 (tố tụng/khiếu nại).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💬","examples":[{"type":"basic","zh":"她需要倾诉。","pinyin":"Tā xūyào qīngsù.","vi":"Cô ấy cần được giãi bày."},{"type":"simple","zh":"深夜，他向老朋友倾诉了心中的烦恼。","pinyin":"Shēnyè, tā xiàng lǎopéngyou qīngsùle xīnzhōng de fánnǎo.","vi":"Đêm khuya, anh ấy tâm sự với bạn cũ những phiền muộn trong lòng."},{"type":"compound","zh":"一旦心里有委屈，她就给妈妈打电话倾诉。","pinyin":"Yídàn xīnli yǒu wěiqu, tā jiù gěi māma dǎdiànhuà qīngsù.","vi":"Hễ trong lòng có điều uất ức, cô ấy liền gọi điện cho mẹ để giãi bày."}],"related":[{"hanzi":"诉说","pinyin":"sùshuō","vi":"kể lể"},{"hanzi":"倾听","pinyin":"qīngtīng","vi":"lắng nghe"},{"hanzi":"吐露","pinyin":"tǔlù","vi":"thổ lộ"},{"hanzi":"心事","pinyin":"xīnshì","vi":"tâm sự"}],"traditional":"傾訴"},{"id":"青涩","hanzi":"青涩","pinyin":"qīngsè","meaning_vi":"non nớt, ngây ngô thuở ban đầu","explanation":"青 (màu xanh (xanh lá/xanh da trời/đen)) + 涩 (涩).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"那时的他很青涩。","pinyin":"Nàshí de tā hěn qīngsè.","vi":"Hồi đó anh ấy còn rất non nớt."},{"type":"simple","zh":"照片里是我们大一时青涩的模样。","pinyin":"Zhàopiàn li shì wǒmen dà yìshí qīngsè de múyàng.","vi":"Trong ảnh là dáng vẻ ngây ngô của chúng tôi hồi năm nhất."},{"type":"compound","zh":"虽然他第一次登台时还很青涩，但是观众都被他打动了。","pinyin":"Suīrán tā dìyīcì dēng tái shí hái hěn qīngsè, dànshì guānzhòng dōu bèi tā dǎdòng le.","vi":"Tuy lần đầu lên sân khấu anh ấy còn rất non nớt, nhưng khán giả đều bị anh làm cảm động."}],"related":[{"hanzi":"稚嫩","pinyin":"zhìnèn","vi":"non nớt"},{"hanzi":"幼稚","pinyin":"yòuzhì","vi":"ấu trĩ"},{"hanzi":"成熟","pinyin":"chéngshú","vi":"chín chắn"},{"hanzi":"青春","pinyin":"qīngchūn","vi":"tuổi xuân"}],"traditional":"青澀"},{"id":"清秀","hanzi":"清秀","pinyin":"qīngxiù","meaning_vi":"thanh tú (gương mặt/nét chữ)","explanation":"清 (trong sạch/rõ nét) + 秀 (ưu tú/tươi đẹp).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🌸","examples":[{"type":"basic","zh":"她长得很清秀。","pinyin":"Tā zhǎngde hěn qīngxiù.","vi":"Cô ấy có gương mặt rất thanh tú."},{"type":"simple","zh":"他在信封上写下一行清秀的小字。","pinyin":"Tā zài xìnfēng shang xiěxià yìháng qīngxiù de xiǎo zì.","vi":"Anh ấy viết lên phong bì một dòng chữ nhỏ thanh tú."},{"type":"compound","zh":"这个女孩不但眉目清秀，而且说话很有礼貌。","pinyin":"Zhè ge nǚhái búdàn méimù qīngxiù, érqiě shuōhuà hěn yǒulǐmào.","vi":"Cô bé này không những mặt mũi thanh tú mà còn ăn nói rất lễ phép."}],"related":[{"hanzi":"秀气","pinyin":"xiùqi","vi":"thanh tú"},{"hanzi":"俊秀","pinyin":"jùnxiù","vi":"đẹp đẽ tuấn tú"},{"hanzi":"秀丽","pinyin":"xiùlì","vi":"xinh đẹp thanh nhã"},{"hanzi":"漂亮","pinyin":"piàoliang","vi":"xinh đẹp"}]},{"id":"清晰可见","hanzi":"清晰可见","pinyin":"qīngxīkějiàn","meaning_vi":"nhìn thấy rõ mồn một","explanation":"清 (trong sạch/rõ nét) + 晰 (晰) + 可 (可) + 见 (见).","hsk_level":"7-9","tags":["tinh-tu"],"image":"👁️","examples":[{"type":"basic","zh":"远山清晰可见。","pinyin":"Yuǎn shān qīngxīkějiàn.","vi":"Núi xa hiện ra rõ mồn một."},{"type":"simple","zh":"雨后湖底的小石子清晰可见。","pinyin":"Yǔ hòu hú dǐ de xiǎo shízǐ qīngxīkějiàn.","vi":"Sau mưa, những viên sỏi dưới đáy hồ hiện rõ mồn một."},{"type":"compound","zh":"天气一转晴，对岸的高楼就清晰可见了。","pinyin":"Tiānqì yì zhuǎn qíng, duì'àn de gāolóu jiù qīngxīkějiàn le.","vi":"Trời vừa hửng nắng, những tòa nhà cao tầng bên kia bờ liền hiện rõ mồn một."}],"related":[{"hanzi":"清晰","pinyin":"qīngxī","vi":"rõ ràng"},{"hanzi":"一目了然","pinyin":"yímùliǎorán","vi":"nhìn là hiểu ngay"},{"hanzi":"模糊不清","pinyin":"móhubùqīng","vi":"mơ hồ không rõ"},{"hanzi":"显而易见","pinyin":"xiǎn'éryìjiàn","vi":"rõ ràng dễ thấy"}],"traditional":"清晰可見"},{"id":"清幽","hanzi":"清幽","pinyin":"qīngyōu","meaning_vi":"thanh tịnh u nhã (cảnh sắc)","explanation":"清 (trong sạch/rõ nét) + 幽 (幽).","hsk_level":"7-9","tags":["tinh-tu","thien-nhien"],"image":"🌿","examples":[{"type":"basic","zh":"这座寺庙很清幽。","pinyin":"Zhè zuò sìmiào hěn qīngyōu.","vi":"Ngôi chùa này rất thanh tịnh u nhã."},{"type":"simple","zh":"我们沿着清幽的竹林小路慢慢散步。","pinyin":"Wǒmen yánzhe qīngyōu de zhúlín xiǎolù mànmàn sànbù.","vi":"Chúng tôi chậm rãi tản bộ theo con đường nhỏ trong rừng trúc tĩnh mịch."},{"type":"compound","zh":"这里环境清幽，所以很多作家喜欢来这里写作。","pinyin":"Zhèlǐ huánjìng qīngyōu, suǒyǐ hěn duō zuòjiā xǐhuan lái zhèlǐ xiězuò.","vi":"Nơi đây cảnh sắc thanh u, nên nhiều nhà văn thích đến đây sáng tác."}],"related":[{"hanzi":"幽静","pinyin":"yōujìng","vi":"yên tĩnh u nhã"},{"hanzi":"清静","pinyin":"qīngjìng","vi":"thanh tịnh"},{"hanzi":"宁静","pinyin":"níngjìng","vi":"yên bình"},{"hanzi":"喧闹","pinyin":"xuānnào","vi":"ồn ào"}]},{"id":"轻装上阵","hanzi":"轻装上阵","pinyin":"qīngzhuāng-shàngzhèn","meaning_vi":"nhẹ nhàng ra trận (gỡ bỏ gánh nặng tâm lý)","explanation":"轻 (nhẹ) + 装 (trang bị/ngụy trang) + 上 (trên) + 阵 (trận địa/đội hình).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏃","examples":[{"type":"basic","zh":"我们要轻装上阵。","pinyin":"Wǒmen yào qīngzhuāngshàngzhèn.","vi":"Chúng ta phải nhẹ nhõm ra trận."},{"type":"simple","zh":"放下包袱后，队员们轻装上阵迎战对手。","pinyin":"Fàngxià bāofu hòu, duìyuánmen qīngzhuāngshàngzhèn yíngzhàn duìshǒu.","vi":"Sau khi trút bỏ gánh nặng, các cầu thủ nhẹ nhõm ra trận đón đánh đối thủ."},{"type":"compound","zh":"既然已经没有退路，不如放下压力轻装上阵。","pinyin":"Jìrán yǐjīng méiyǒu tuìlù, bùrú fàngxià yālì qīngzhuāngshàngzhèn.","vi":"Đã không còn đường lui, chi bằng gác lại áp lực mà nhẹ nhõm ra trận."}],"related":[{"hanzi":"放下包袱","pinyin":"fàngxiàbāofu","vi":"trút bỏ gánh nặng"},{"hanzi":"轻松","pinyin":"qīngsōng","vi":"thoải mái nhẹ nhõm"},{"hanzi":"上阵","pinyin":"shàngzhèn","vi":"ra trận"},{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"}],"traditional":"輕裝上陣"},{"id":"倾注","hanzi":"倾注","pinyin":"qīngzhù","meaning_vi":"dồn hết (tâm huyết/tình cảm)","explanation":"倾 (lắng nghe/khuynh hướng) + 注 (chú trọng/chú thích).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"她倾注了全部心血。","pinyin":"Tā qīngzhùle quánbù xīnxuè.","vi":"Cô ấy đã dồn hết tâm huyết."},{"type":"simple","zh":"老人把一生的感情都倾注在这片果园上。","pinyin":"Lǎorén bǎ yìshēng de gǎnqíng dōu qīngzhù zài zhè piàn guǒyuán shang.","vi":"Ông lão dồn cả tình cảm một đời vào mảnh vườn cây ăn quả này."},{"type":"compound","zh":"因为导演倾注了十年心血，所以这部电影格外感人。","pinyin":"Yīnwèi dǎoyǎn qīngzhùle shí nián xīnxuè, suǒyǐ zhè bù diànyǐng géwài gǎnrén.","vi":"Vì đạo diễn đã dồn mười năm tâm huyết nên bộ phim này đặc biệt cảm động."}],"related":[{"hanzi":"投入","pinyin":"tóurù","vi":"dồn vào"},{"hanzi":"倾尽","pinyin":"qīngjìn","vi":"dốc hết"},{"hanzi":"心血","pinyin":"xīnxuè","vi":"tâm huyết"},{"hanzi":"全力以赴","pinyin":"quánlìyǐfù","vi":"dốc toàn lực"}],"traditional":"傾注"},{"id":"青藏高原","hanzi":"青藏高原","pinyin":"Qīngzànggāoyuán","meaning_vi":"cao nguyên Thanh Tạng (nóc nhà thế giới)","explanation":"青 (Thanh Hải) 藏 (Tây Tạng) + 高原 (cao nguyên) → cao nguyên Thanh Tạng, cao nguyên cao nhất thế giới, được gọi là 世界屋脊 (nóc nhà thế giới).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🏔️","examples":[{"type":"basic","zh":"青藏高原海拔很高。","pinyin":"Qīngzànggāoyuán hǎibá hěn gāo.","vi":"Cao nguyên Thanh Tạng có độ cao so với mực nước biển rất lớn."},{"type":"simple","zh":"这条铁路一直通到青藏高原的腹地。","pinyin":"Zhè tiáo tiělù yì zhítōng dào Qīngzànggāoyuán de fùdì.","vi":"Tuyến đường sắt này chạy thẳng tới vùng lõi của cao nguyên Thanh Tạng."},{"type":"compound","zh":"刚到青藏高原的游客如果走得太快，就容易出现高原反应。","pinyin":"Gāng dào Qīngzànggāoyuán de yóukè rúguǒ zǒu de tài kuài, jiù róngyì chūxiàn gāoyuán fǎnyìng.","vi":"Du khách mới đến cao nguyên Thanh Tạng nếu đi quá nhanh thì dễ bị say độ cao."}],"related":[{"hanzi":"西藏","pinyin":"Xīzàng","vi":"Tây Tạng"},{"hanzi":"青海","pinyin":"Qīnghǎi","vi":"Thanh Hải"},{"hanzi":"喜马拉雅山","pinyin":"Xǐmǎlāyǎ Shān","vi":"dãy Himalaya"},{"hanzi":"高原","pinyin":"gāoyuán","vi":"cao nguyên"}]},{"id":"区块链","hanzi":"区块链","pinyin":"qūkuàiliàn","meaning_vi":"công nghệ chuỗi khối (Blockchain)","explanation":"区块 (khối) + 链 (chuỗi).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"⛓️","examples":[{"type":"basic","zh":"他在研究区块链。","pinyin":"Tā zài yánjiū qūkuàiliàn.","vi":"Anh ấy đang nghiên cứu blockchain."},{"type":"simple","zh":"这家银行用区块链技术记录每一笔交易。","pinyin":"Zhè jiā yínháng yòng qūkuàiliàn jìshù jìlù měi yì bǐ jiāoyì.","vi":"Ngân hàng này dùng công nghệ chuỗi khối để ghi lại từng giao dịch."},{"type":"compound","zh":"区块链上的数据一旦写入，就很难被篡改。","pinyin":"Qūkuàiliàn shang de shùjù yídàn xiě rù, jiù hěn nán bèi cuàngǎi.","vi":"Dữ liệu trên chuỗi khối một khi đã ghi vào thì rất khó bị sửa đổi."}],"related":[{"hanzi":"比特币","pinyin":"bǐtèbì","vi":"Bitcoin"},{"hanzi":"数字货币","pinyin":"shùzìhuòbì","vi":"tiền kỹ thuật số"},{"hanzi":"加密","pinyin":"jiāmì","vi":"mã hóa"},{"hanzi":"大数据","pinyin":"dàshùjù","vi":"dữ liệu lớn"}],"traditional":"區塊鏈"},{"id":"驱使","hanzi":"驱使","pinyin":"qūshǐ","meaning_vi":"sai khiến, thúc đẩy (bởi lòng hiếu kỳ/lợi ích)","explanation":"驱 (trục xuất/thúc đẩy) + 使 (khiến cho).","hsk_level":"7-9","tags":["dong-tu"],"image":"🐎","examples":[{"type":"basic","zh":"他被好奇心驱使。","pinyin":"Tā bèi hàoqíxīn qūshǐ.","vi":"Anh ấy bị sự tò mò thôi thúc."},{"type":"simple","zh":"在利益的驱使下，有些商家开始卖假货。","pinyin":"Zài lìyì de qūshǐ xià, yǒuxiē shāngjiā kāishǐ mài jiǎhuò.","vi":"Bị lợi ích thúc đẩy, một số người bán bắt đầu bán hàng giả."},{"type":"compound","zh":"虽然天已经黑了，但是好奇心驱使他走进了那条小巷。","pinyin":"Suīrán tiān yǐjīng hēi le, dànshì hàoqíxīn qūshǐ tā zǒujìnle nà tiáo xiǎoxiàng.","vi":"Tuy trời đã tối, nhưng sự tò mò thôi thúc anh bước vào con hẻm đó."}],"related":[{"hanzi":"驱动","pinyin":"qūdòng","vi":"thúc đẩy"},{"hanzi":"促使","pinyin":"cùshǐ","vi":"thúc đẩy khiến"},{"hanzi":"好奇心","pinyin":"hàoqíxīn","vi":"lòng hiếu kỳ"},{"hanzi":"指使","pinyin":"zhǐshǐ","vi":"sai khiến xúi giục"}],"traditional":"驅使"},{"id":"趋于","hanzi":"趋于","pinyin":"qūyú","meaning_vi":"có xu hướng tiến tới","explanation":"趋 (xu hướng) + 于 (ở/đối với).","hsk_level":"7-9","tags":["dong-tu"],"image":"📈","examples":[{"type":"basic","zh":"局势趋于稳定。","pinyin":"Júshì qūyú wěndìng.","vi":"Tình hình có xu hướng ổn định."},{"type":"simple","zh":"经过治疗，病人的血压逐渐趋于正常。","pinyin":"Jīngguò zhìliáo, bìngrén de xuèyā zhújiàn qūyú zhèngcháng.","vi":"Sau điều trị, huyết áp của bệnh nhân dần trở về mức bình thường."},{"type":"compound","zh":"因为竞争越来越激烈，所以手机价格逐渐趋于合理。","pinyin":"Yīnwèi jìngzhēng yuèláiyuè jīliè, suǒyǐ shǒujī jiàgé zhújiàn qūyú hélǐ.","vi":"Vì cạnh tranh ngày càng gay gắt nên giá điện thoại dần trở nên hợp lý."}],"related":[{"hanzi":"趋向","pinyin":"qūxiàng","vi":"có xu hướng"},{"hanzi":"趋势","pinyin":"qūshì","vi":"xu thế"},{"hanzi":"趋于稳定","pinyin":"qūyúwěndìng","vi":"dần ổn định"},{"hanzi":"倾向","pinyin":"qīngxiàng","vi":"khuynh hướng"}],"traditional":"趨於"},{"id":"起步","hanzi":"起步","pinyin":"qǐbù","meaning_vi":"khởi đầu, bắt đầu cất bước","explanation":"起 (khởi nguồn/trỗi dậy) + 步 (bước đi/tiến bộ).","hsk_level":"7-9","tags":["dong-tu"],"image":"👣","examples":[{"type":"basic","zh":"我们起步比较晚。","pinyin":"Wǒmen qǐbù bǐjiào wǎn.","vi":"Chúng ta khởi đầu khá muộn."},{"type":"simple","zh":"这家公司是从一间小车库起步的。","pinyin":"Zhè jiā gōngsī shì cóng yì jiān xiǎo chēkù qǐbù de.","vi":"Công ty này khởi nghiệp từ một nhà xe nhỏ."},{"type":"compound","zh":"虽然我国的芯片产业起步较晚，但是发展速度很快。","pinyin":"Suīrán wǒguó de xīnpiàn chǎnyè qǐbù jiào wǎn, dànshì fāzhǎn sùdù hěn kuài.","vi":"Tuy ngành chip của nước ta khởi đầu khá muộn, nhưng tốc độ phát triển rất nhanh."}],"related":[{"hanzi":"起点","pinyin":"qǐdiǎn","vi":"điểm xuất phát"},{"hanzi":"开端","pinyin":"kāiduān","vi":"khởi đầu"},{"hanzi":"起步价","pinyin":"qǐbùjià","vi":"giá mở cửa"},{"hanzi":"起飞","pinyin":"qǐfēi","vi":"cất cánh"}]},{"id":"起身","hanzi":"起身","pinyin":"qǐshēn","meaning_vi":"đứng dậy, lên đường","explanation":"起 (khởi nguồn/trỗi dậy) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧍","examples":[{"type":"basic","zh":"他起身让座。","pinyin":"Tā qǐshēn ràngzuò.","vi":"Anh ấy đứng dậy nhường chỗ."},{"type":"simple","zh":"会议结束后，老板第一个起身离开了会议室。","pinyin":"Huìyì jiéshù hòu, lǎobǎn dìyī gè qǐshēn líkāile huìyìshì.","vi":"Cuộc họp kết thúc, sếp là người đầu tiên đứng dậy rời phòng họp."},{"type":"compound","zh":"明天我们一早就要起身去机场，所以今晚得早点睡。","pinyin":"Míngtiān wǒmen yìzǎo jiùyào qǐshēn qù jīchǎng, suǒyǐ jīnwǎn děi zǎodiǎn shuì.","vi":"Sáng sớm mai chúng ta phải lên đường ra sân bay, nên tối nay phải ngủ sớm."}],"related":[{"hanzi":"起床","pinyin":"qǐchuáng","vi":"thức dậy"},{"hanzi":"站起来","pinyin":"zhànqǐlai","vi":"đứng dậy"},{"hanzi":"动身","pinyin":"dòngshēn","vi":"lên đường"},{"hanzi":"出发","pinyin":"chūfā","vi":"xuất phát"}]},{"id":"起色","hanzi":"起色","pinyin":"qǐsè","meaning_vi":"khởi sắc, chuyển biến tốt","explanation":"起 (khởi nguồn/trỗi dậy) + 色 (màu sắc/thần sắc).","hsk_level":"7-9","tags":["danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"生意有了起色。","pinyin":"Shēngyi yǒule qǐsè.","vi":"Việc kinh doanh đã khởi sắc."},{"type":"simple","zh":"吃了一个月中药，他的病情终于有了起色。","pinyin":"Chīle yí gèyuè zhōngyào, tā de bìngqíng zhōngyú yǒule qǐsè.","vi":"Uống thuốc bắc một tháng, bệnh tình của ông ấy cuối cùng đã chuyển biến tốt."},{"type":"compound","zh":"只要你每天坚持练习，你的口语就会慢慢有起色。","pinyin":"Zhǐyào nǐ měitiān jiānchí liànxí, nǐ de kǒuyǔ jiù huì mànmàn yǒu qǐsè.","vi":"Chỉ cần ngày nào cũng kiên trì luyện tập, khẩu ngữ của bạn sẽ dần khởi sắc."}],"related":[{"hanzi":"好转","pinyin":"hǎozhuǎn","vi":"chuyển biến tốt"},{"hanzi":"转机","pinyin":"zhuǎnjī","vi":"bước ngoặt tốt"},{"hanzi":"改善","pinyin":"gǎishàn","vi":"cải thiện"},{"hanzi":"毫无起色","pinyin":"háowúqǐsè","vi":"không chút khởi sắc"}]},{"id":"乞讨","hanzi":"乞讨","pinyin":"qǐtǎo","meaning_vi":"ăn xin","explanation":"乞 (ăn xin/cầu xin) + 讨 (thảo luận/lấy lòng).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"他在街头乞讨。","pinyin":"Tā zài jiētóu qǐtǎo.","vi":"Ông ấy ăn xin ngoài phố."},{"type":"simple","zh":"地铁站门口有一位老人正在乞讨。","pinyin":"Dìtiězhàn ménkǒu yǒu yí wèi lǎorén zhèngzài qǐtǎo.","vi":"Trước cửa ga tàu điện ngầm có một ông lão đang ăn xin."},{"type":"compound","zh":"他宁可饿着肚子，也不愿意去街上乞讨。","pinyin":"Tā nìngkě èzhe dùzi, yě bú yuànyì qù jiēshang qǐtǎo.","vi":"Anh ấy thà nhịn đói chứ không chịu ra đường ăn xin."}],"related":[{"hanzi":"乞丐","pinyin":"qǐgài","vi":"người ăn xin"},{"hanzi":"讨饭","pinyin":"tǎofàn","vi":"đi xin ăn"},{"hanzi":"施舍","pinyin":"shīshě","vi":"bố thí"},{"hanzi":"流浪","pinyin":"liúlàng","vi":"lang thang"}],"traditional":"乞討"},{"id":"企业家","hanzi":"企业家","pinyin":"qǐyèjiā","meaning_vi":"doanh nhân","explanation":"企 (doanh nghiệp/mưu toan) + 业 (sự nghiệp/ngành nghề) + 家 (nhà).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","cong-viec"],"image":"🤵","examples":[{"type":"basic","zh":"他是著名企业家。","pinyin":"Tā shì zhùmíng qǐyèjiā.","vi":"Ông ấy là doanh nhân nổi tiếng."},{"type":"simple","zh":"这位企业家把一半财产捐给了家乡的学校。","pinyin":"Zhè wèi qǐyèjiā bǎ yíbàn cáichǎn juāngěile jiāxiāng de xuéxiào.","vi":"Vị doanh nhân này đã quyên một nửa tài sản cho trường học ở quê nhà."},{"type":"compound","zh":"一个优秀的企业家不但要有眼光，而且要敢于承担风险。","pinyin":"Yí gè yōuxiù de qǐyèjiā búdàn yàoyǒu yǎnguāng, érqiě yào gǎnyú chéngdān fēngxiǎn.","vi":"Một doanh nhân giỏi không chỉ cần có tầm nhìn mà còn phải dám chấp nhận rủi ro."}],"related":[{"hanzi":"企业","pinyin":"qǐyè","vi":"doanh nghiệp"},{"hanzi":"老板","pinyin":"lǎobǎn","vi":"ông chủ"},{"hanzi":"创业者","pinyin":"chuàngyèzhě","vi":"người khởi nghiệp"},{"hanzi":"商人","pinyin":"shāngrén","vi":"thương nhân"}],"traditional":"企業家"},{"id":"企鹅","hanzi":"企鹅","pinyin":"qǐ'é","meaning_vi":"chim cánh cụt","explanation":"企 (doanh nghiệp/mưu toan) + 鹅 (con ngỗng).","hsk_level":"7-9","tags":["danh-tu","dong-vat"],"image":"🐧","examples":[{"type":"basic","zh":"企鹅不会飞。","pinyin":"Qǐ'é bú huì fēi.","vi":"Chim cánh cụt không biết bay."},{"type":"simple","zh":"孩子们在海洋馆里看企鹅排队走路。","pinyin":"Háizimen zài hǎiyángguǎn li kàn qǐ'é páiduì zǒulù.","vi":"Bọn trẻ xem chim cánh cụt xếp hàng đi bộ trong thủy cung."},{"type":"compound","zh":"企鹅虽然在陆地上走得很慢，但是在水里游得飞快。","pinyin":"Qǐ'é suīrán zài lùdì shang zǒu de hěn màn, dànshì zài shuǐ li yóu de fēikuài.","vi":"Chim cánh cụt tuy đi trên cạn rất chậm, nhưng bơi dưới nước nhanh như bay."}],"related":[{"hanzi":"南极","pinyin":"nánjí","vi":"Nam Cực"},{"hanzi":"北极熊","pinyin":"běijíxióng","vi":"gấu Bắc Cực"},{"hanzi":"海豹","pinyin":"hǎibào","vi":"hải cẩu"},{"hanzi":"动物","pinyin":"dòngwù","vi":"động vật"}],"traditional":"企鵝"},{"id":"取代","hanzi":"取代","pinyin":"qǔdài","meaning_vi":"thay thế","explanation":"取 (thủ – lấy) + 代 (đại – thay) → lấy chỗ của cái khác, thay thế. VD: 机器取代人工, 被…取代.","hsk_level":"7-9","tags":["dong-tu"],"image":"🔄","examples":[{"type":"basic","zh":"机器取代了人工。","pinyin":"Jīqì qǔdàile réngōng.","vi":"Máy móc đã thay thế sức người."},{"type":"simple","zh":"电子支付已经基本取代了现金。","pinyin":"Diànzǐ zhīfù yǐjīng jīběn qǔdàile xiànjīn.","vi":"Thanh toán điện tử về cơ bản đã thay thế tiền mặt."},{"type":"compound","zh":"即使人工智能再发达，也无法完全取代老师的作用。","pinyin":"Jíshǐ réngōngzhìnéng zài fādá, yě wúfǎ wánquán qǔdài lǎoshī de zuòyòng.","vi":"Dù trí tuệ nhân tạo có phát triển đến đâu cũng không thể hoàn toàn thay thế vai trò của giáo viên."}],"related":[{"hanzi":"代替","pinyin":"dàitì","vi":"thay thế"},{"hanzi":"替代","pinyin":"tìdài","vi":"thay thế"},{"hanzi":"取而代之","pinyin":"qǔ'érdàizhī","vi":"thay vào đó"},{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"}]},{"id":"取胜","hanzi":"取胜","pinyin":"qǔshèng","meaning_vi":"giành chiến thắng","explanation":"取 (lấy) + 胜 (thắng lợi/vượt trội).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"主队最终取胜。","pinyin":"Zhǔduì zuìzhōng qǔshèng.","vi":"Đội nhà cuối cùng đã giành chiến thắng."},{"type":"simple","zh":"中国女排以三比一取胜。","pinyin":"Zhōngguó nǚpái yǐ sān bǐ yì qǔshèng.","vi":"Đội bóng chuyền nữ Trung Quốc thắng với tỷ số 3-1."},{"type":"compound","zh":"如果想在决赛中取胜，就必须加强防守。","pinyin":"Rúguǒ xiǎng zài juésài zhōng qǔshèng, jiù bìxū jiāqiáng fángshǒu.","vi":"Nếu muốn giành chiến thắng trong trận chung kết thì phải tăng cường phòng thủ."}],"related":[{"hanzi":"获胜","pinyin":"huòshèng","vi":"giành thắng lợi"},{"hanzi":"战胜","pinyin":"zhànshèng","vi":"chiến thắng"},{"hanzi":"胜利","pinyin":"shènglì","vi":"thắng lợi"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"}],"traditional":"取勝"},{"id":"取舍","hanzi":"取舍","pinyin":"qǔshě","meaning_vi":"lựa chọn nên lấy hay bỏ","explanation":"取 (lấy) + 舍 (từ bỏ/bố thí).","hsk_level":"7-9","tags":["dong-tu","danh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"人生需要取舍。","pinyin":"Rénshēng xūyào qǔshě.","vi":"Đời người cần biết lấy bỏ."},{"type":"simple","zh":"面对两份工作，他一时难以取舍。","pinyin":"Miànduì liǎng fèn gōngzuò, tā yìshí nányǐ qǔshě.","vi":"Đứng trước hai công việc, anh ấy nhất thời khó chọn lựa."},{"type":"compound","zh":"时间有限，与其样样都学，不如有所取舍。","pinyin":"Shíjiān yǒuxiàn, yǔqí yàngyàng dōu xué, bùrú yǒusuǒ qǔshě.","vi":"Thời gian có hạn, thay vì cái gì cũng học, chi bằng biết chọn lọc."}],"related":[{"hanzi":"选择","pinyin":"xuǎnzé","vi":"lựa chọn"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"舍弃","pinyin":"shěqì","vi":"vứt bỏ"},{"hanzi":"权衡","pinyin":"quánhéng","vi":"cân nhắc"}],"traditional":"取捨"},{"id":"瑞气","hanzi":"瑞气","pinyin":"ruìqì","meaning_vi":"khí lành, điềm tốt lành","explanation":"瑞 (điềm lành) + 气 (khí phách/khí hậu).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🧧","examples":[{"type":"basic","zh":"新年瑞气满门。","pinyin":"Xīnnián ruìqì mǎnmén.","vi":"Năm mới khí lành đầy nhà."},{"type":"simple","zh":"春节时，整条老街都洋溢着祥光瑞气。","pinyin":"Chūnjié shí, zhěngtiáo lǎojiē dōu yángyìzhe xiángguāng ruìqì.","vi":"Dịp Tết, cả con phố cổ tràn ngập ánh sáng và khí lành."},{"type":"compound","zh":"人们相信，只要门口挂上红灯笼，家里就会充满瑞气。","pinyin":"Rénmen xiāngxìn, zhǐyào ménkǒu guà shang hóngdēnglong, jiāli jiù huì chōngmǎn ruìqì.","vi":"Người ta tin rằng chỉ cần treo đèn lồng đỏ trước cửa, trong nhà sẽ tràn đầy khí lành."}],"related":[{"hanzi":"祥瑞","pinyin":"xiángruì","vi":"điềm lành"},{"hanzi":"吉祥","pinyin":"jíxiáng","vi":"cát tường"},{"hanzi":"瑞雪","pinyin":"ruìxuě","vi":"tuyết lành"},{"hanzi":"福气","pinyin":"fúqi","vi":"phúc khí"}],"traditional":"瑞氣"},{"id":"弱小","hanzi":"弱小","pinyin":"ruòxiǎo","meaning_vi":"nhỏ bé yếu ớt","explanation":"弱 (yếu) + 小 (nhỏ).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"小猫很弱小。","pinyin":"Xiǎomāo hěn ruòxiǎo.","vi":"Chú mèo con rất nhỏ bé yếu ớt."},{"type":"simple","zh":"我们不应该欺负比自己弱小的人。","pinyin":"Wǒmen bù yīnggāi qīfu bǐ zìjǐ ruòxiǎo de rén.","vi":"Chúng ta không nên bắt nạt người yếu hơn mình."},{"type":"compound","zh":"这家公司刚成立时还很弱小，但是十年后已经成了行业龙头。","pinyin":"Zhè jiā gōngsī gāng chéng lìshí hái hěn ruòxiǎo, dànshì shí nián hòu yǐjīng chéngle hángyè lóngtóu.","vi":"Công ty này lúc mới thành lập còn rất nhỏ yếu, nhưng mười năm sau đã thành đầu tàu của ngành."}],"related":[{"hanzi":"弱者","pinyin":"ruòzhě","vi":"kẻ yếu"},{"hanzi":"微小","pinyin":"wēixiǎo","vi":"nhỏ bé"},{"hanzi":"强大","pinyin":"qiángdà","vi":"mạnh mẽ"},{"hanzi":"软弱","pinyin":"ruǎnruò","vi":"mềm yếu"}]},{"id":"软件工程","hanzi":"软件工程","pinyin":"ruǎnjiàngōngchéng","meaning_vi":"kỹ thuật phần mềm","explanation":"软 (mềm yếu) + 件 (件) + 工 (工) + 程 (quá trình/hành trình).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","hoc-tap"],"image":"💻","examples":[{"type":"basic","zh":"我学软件工程。","pinyin":"Wǒ xué ruǎnjiàngōngchéng.","vi":"Tôi học ngành kỹ thuật phần mềm."},{"type":"simple","zh":"她在大学里主修软件工程专业。","pinyin":"Tā zài dàxué li zhǔxiū ruǎnjiàngōngchéng zhuānyè.","vi":"Cô ấy học chuyên ngành kỹ thuật phần mềm ở đại học."},{"type":"compound","zh":"软件工程不仅要求会写代码，而且要懂得团队协作。","pinyin":"Ruǎnjiàngōngchéng bùjǐn yāoqiú huì xiě dàimǎ, érqiě yào dǒngde tuánduì xiézuò.","vi":"Kỹ thuật phần mềm không chỉ đòi hỏi biết viết code mà còn phải biết làm việc nhóm."}],"related":[{"hanzi":"软件","pinyin":"ruǎnjiàn","vi":"phần mềm"},{"hanzi":"工程师","pinyin":"gōngchéngshī","vi":"kỹ sư"},{"hanzi":"编程","pinyin":"biānchéng","vi":"lập trình"},{"hanzi":"计算机科学","pinyin":"jìsuànjī kēxué","vi":"khoa học máy tính"}],"traditional":"軟件工程"},{"id":"软实力","hanzi":"软实力","pinyin":"ruǎnshílì","meaning_vi":"sức mạnh mềm (văn hóa/ngoại giao)","explanation":"软 (mềm yếu) + 实 (thực tế/thực chất) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","van-hoa"],"image":"🌸","examples":[{"type":"basic","zh":"文化是软实力。","pinyin":"Wénhuà shì ruǎnshílì.","vi":"Văn hóa là sức mạnh mềm."},{"type":"simple","zh":"电影和音乐是提升国家软实力的重要途径。","pinyin":"Diànyǐng hé yīnyuè shì tíshēng guójiā ruǎnshílì de zhòngyào tújìng.","vi":"Phim ảnh và âm nhạc là con đường quan trọng để nâng cao sức mạnh mềm quốc gia."},{"type":"compound","zh":"一个国家如果只有经济实力，没有软实力，就很难赢得尊重。","pinyin":"Yí gè guójiā rúguǒ zhǐyǒu jīngjì shílì, méiyǒu ruǎnshílì, jiù hěn nán yíngdé zūnzhòng.","vi":"Một quốc gia nếu chỉ có sức mạnh kinh tế mà thiếu sức mạnh mềm thì khó giành được sự tôn trọng."}],"related":[{"hanzi":"硬实力","pinyin":"yìngshílì","vi":"sức mạnh cứng"},{"hanzi":"实力","pinyin":"shílì","vi":"thực lực"},{"hanzi":"影响力","pinyin":"yǐngxiǎnglì","vi":"sức ảnh hưởng"},{"hanzi":"文化","pinyin":"wénhuà","vi":"văn hóa"}],"traditional":"軟實力"},{"id":"让位","hanzi":"让位","pinyin":"ràngwèi","meaning_vi":"nhường chỗ, nhường ngôi","explanation":"让 (bảo) + 位 (vị trí/địa vị).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙇","examples":[{"type":"basic","zh":"老国王让位了。","pinyin":"Lǎo guówáng ràngwèi le.","vi":"Vị vua già đã nhường ngôi."},{"type":"simple","zh":"汽车出现以后，马车逐渐让位于新的交通工具。","pinyin":"Qìchē chūxiàn yǐhòu, mǎchē zhújiàn ràng wèiyú xīn de jiāotōng gōngjù.","vi":"Sau khi ô tô ra đời, xe ngựa dần nhường chỗ cho phương tiện mới."},{"type":"compound","zh":"因为年纪大了，所以老厂长主动让位给年轻人。","pinyin":"Yīnwèi niánjì dà le, suǒyǐ lǎo chǎngzhǎng zhǔdòng ràngwèi gěi niánqīngrén.","vi":"Vì tuổi đã cao nên ông giám đốc nhà máy chủ động nhường vị trí cho người trẻ."}],"related":[{"hanzi":"让座","pinyin":"ràngzuò","vi":"nhường ghế"},{"hanzi":"退位","pinyin":"tuìwèi","vi":"thoái vị"},{"hanzi":"让步","pinyin":"ràngbù","vi":"nhượng bộ"},{"hanzi":"让路","pinyin":"rànglù","vi":"nhường đường"}],"traditional":"讓位"},{"id":"燃眉之急","hanzi":"燃眉之急","pinyin":"ránméi-zhījí","meaning_vi":"việc cấp bách như lửa cháy lông mày","explanation":"燃眉之急: cái gấp (急) như lửa cháy (燃) lông mày (眉) → việc cực kỳ cấp bách, phải giải quyết ngay. Thường đi với 解燃眉之急.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔥","examples":[{"type":"basic","zh":"这解了燃眉之急。","pinyin":"Zhè jiěle ránméizhījí.","vi":"Việc này đã giải quyết được cái khẩn cấp trước mắt."},{"type":"simple","zh":"朋友借给他的两万块钱解了他的燃眉之急。","pinyin":"Péngyou jiègěi tā de liǎng wàn kuài qián jiěle tā de ránméizhījí.","vi":"Hai vạn tệ bạn cho vay đã giải quyết cơn nguy cấp của anh ấy."},{"type":"compound","zh":"虽然这笔贷款能救燃眉之急，但是长期问题还没解决。","pinyin":"Suīrán zhè bǐ dàikuǎn néng jiù ránméizhījí, dànshì chángqī wèntí hái méi jiějué.","vi":"Tuy khoản vay này cứu được tình thế cấp bách, nhưng vấn đề lâu dài vẫn chưa được giải quyết."}],"related":[{"hanzi":"当务之急","pinyin":"dāngwùzhījí","vi":"việc cấp bách trước mắt"},{"hanzi":"迫在眉睫","pinyin":"pòzàiméijié","vi":"cận kề trước mắt"},{"hanzi":"紧急","pinyin":"jǐnjí","vi":"khẩn cấp"},{"hanzi":"火烧眉毛","pinyin":"huǒshāoméimao","vi":"lửa cháy lông mày"}]},{"id":"热潮","hanzi":"热潮","pinyin":"rècháo","meaning_vi":"làn sóng sôi nổi, cao trào","explanation":"热 (nóng) + 潮 (thủy triều/trào lưu).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🔥","examples":[{"type":"basic","zh":"露营热潮来了。","pinyin":"Lùyíng rècháo lái le.","vi":"Làn sóng cắm trại đã đến."},{"type":"simple","zh":"这部纪录片在年轻人中掀起了一股学汉服的热潮。","pinyin":"Zhè bù jìlùpiàn zài niánqīng rénzhōng xiānqǐle yì gǔ xué hànfú de rècháo.","vi":"Bộ phim tài liệu này đã tạo nên làn sóng tìm hiểu Hán phục trong giới trẻ."},{"type":"compound","zh":"奥运会一结束，全国就掀起了一阵健身热潮。","pinyin":"Àoyùnhuì yì jiéshù, quánguó jiù xiānqǐle yízhèn jiànshēn rècháo.","vi":"Thế vận hội vừa kết thúc, cả nước liền dấy lên làn sóng tập thể dục."}],"related":[{"hanzi":"热浪","pinyin":"rèlàng","vi":"làn sóng nóng"},{"hanzi":"浪潮","pinyin":"làngcháo","vi":"làn sóng"},{"hanzi":"高潮","pinyin":"gāocháo","vi":"cao trào"},{"hanzi":"热门","pinyin":"rèmén","vi":"hot, được ưa chuộng"}],"traditional":"熱潮"},{"id":"热忱","hanzi":"热忱","pinyin":"rèchén","meaning_vi":"nhiệt tình chân thành","explanation":"热 (nóng) + 忱 (lòng chân thành).","hsk_level":"7-9","tags":["danh-tu","tinh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"他待人很热忱。","pinyin":"Tā dàirén hěn rèchén.","vi":"Anh ấy đối xử với mọi người rất nhiệt thành."},{"type":"simple","zh":"志愿者们以极大的热忱接待了每一位游客。","pinyin":"Zhìyuànzhěmen yǐ jídà de rèchén jiēdàile měi yí wèi yóukè.","vi":"Các tình nguyện viên tiếp đón từng du khách với sự nhiệt thành lớn lao."},{"type":"compound","zh":"虽然已经退休多年，但是她对教育的热忱一点也没减少。","pinyin":"Suīrán yǐjīng tuìxiū duōnián, dànshì tā duì jiàoyù de rèchén yìdiǎn yě méi jiǎnshǎo.","vi":"Tuy đã nghỉ hưu nhiều năm, nhưng lòng nhiệt thành của bà với giáo dục không hề giảm."}],"related":[{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"热心","pinyin":"rèxīn","vi":"nhiệt tâm"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh nhạt"}],"traditional":"熱忱"},{"id":"热点","hanzi":"热点","pinyin":"rèdiǎn","meaning_vi":"điểm nóng (dư luận/thời sự)","explanation":"热 (nóng) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🔥","examples":[{"type":"basic","zh":"这是新闻热点。","pinyin":"Zhè shì xīnwén rèdiǎn.","vi":"Đây là điểm nóng thời sự."},{"type":"simple","zh":"房价问题一直是两会期间的热点话题。","pinyin":"Fángjià wèntí yìzhí shì Liǎnghuì qījiān de rèdiǎn huàtí.","vi":"Giá nhà luôn là đề tài nóng trong kỳ họp Lưỡng hội."},{"type":"compound","zh":"一旦某个明星出了事，这件事就会马上成为网络热点。","pinyin":"Yídàn mǒu gè míngxīng chūleshì, zhè jiàn shì jiù huì mǎshàng chéngwéi wǎngluò rèdiǎn.","vi":"Một khi ngôi sao nào đó gặp chuyện, việc ấy sẽ lập tức thành điểm nóng trên mạng."}],"related":[{"hanzi":"热门","pinyin":"rèmén","vi":"hot, được ưa chuộng"},{"hanzi":"焦点","pinyin":"jiāodiǎn","vi":"tiêu điểm"},{"hanzi":"热点话题","pinyin":"rèdiǎnhuàtí","vi":"chủ đề nóng"},{"hanzi":"热搜","pinyin":"rèsōu","vi":"tìm kiếm nóng"}],"traditional":"熱點"},{"id":"热恋","hanzi":"热恋","pinyin":"rèliàn","meaning_vi":"đang yêu say đắm","explanation":"热 (nóng) + 恋 (lưu luyến/yêu đương).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💑","examples":[{"type":"basic","zh":"他们正在热恋。","pinyin":"Tāmen zhèngzài rèliàn.","vi":"Họ đang yêu nhau say đắm."},{"type":"simple","zh":"热恋中的两个人每天都要打好几个小时电话。","pinyin":"Rèliàn zhōng de liǎng gè rén měitiān dōu yào dǎ hǎojǐ gè xiǎoshí diànhuà.","vi":"Hai người đang yêu say đắm ngày nào cũng gọi điện mấy tiếng liền."},{"type":"compound","zh":"热恋时什么都觉得好，可是结婚后矛盾就慢慢出现了。","pinyin":"Rèliàn shí shénme dōu juéde hǎo, kěshì jiéhūn hòu máodùn jiù mànmàn chūxiàn le.","vi":"Lúc yêu say đắm thì cái gì cũng thấy tốt, nhưng cưới rồi mâu thuẫn mới dần lộ ra."}],"related":[{"hanzi":"恋爱","pinyin":"liàn'ài","vi":"yêu đương"},{"hanzi":"恋人","pinyin":"liànrén","vi":"người yêu"},{"hanzi":"初恋","pinyin":"chūliàn","vi":"mối tình đầu"},{"hanzi":"失恋","pinyin":"shīliàn","vi":"thất tình"}],"traditional":"熱戀"},{"id":"热泪","hanzi":"热泪","pinyin":"rèlèi","meaning_vi":"nước mắt nóng hổi cảm động","explanation":"热 (nhiệt – nóng) + 泪 (lệ – nước mắt) → nước mắt nóng hổi do xúc động. VD: 热泪盈眶 (nước mắt rưng rưng).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🥹","examples":[{"type":"basic","zh":"她流下了热泪。","pinyin":"Tā liú xiàle rèlèi.","vi":"Cô ấy rơi những giọt nước mắt nóng hổi."},{"type":"simple","zh":"领奖台上的老运动员眼里含着热泪。","pinyin":"Lǐngjiǎngtái shang de lǎo yùndòngyuán yǎn li hánzhe rèlèi.","vi":"Vận động viên lão làng trên bục nhận giải rưng rưng nước mắt."},{"type":"compound","zh":"一听到国歌响起，他就忍不住热泪盈眶。","pinyin":"Yì tīngdào guógē xiǎngqǐ, tā jiù rěnbuzhù rèlèiyíngkuàng.","vi":"Vừa nghe quốc ca vang lên, anh ấy không kìm được nước mắt trào dâng."}],"related":[{"hanzi":"热泪盈眶","pinyin":"rèlèiyíngkuàng","vi":"nước mắt rưng rưng"},{"hanzi":"泪水","pinyin":"lèishuǐ","vi":"nước mắt"},{"hanzi":"感动","pinyin":"gǎndòng","vi":"cảm động"},{"hanzi":"流泪","pinyin":"liúlèi","vi":"rơi lệ"}],"traditional":"熱淚"},{"id":"热销","hanzi":"热销","pinyin":"rèxiāo","meaning_vi":"bán chạy","explanation":"热 (nóng) + 销 (tiêu thụ/hủy bỏ).","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"这款手机很热销。","pinyin":"Zhè kuǎn shǒujī hěn rèxiāo.","vi":"Mẫu điện thoại này bán rất chạy."},{"type":"simple","zh":"入冬以后，羽绒服在各大商场持续热销。","pinyin":"Rùdōng yǐhòu, yǔróngfú zài gè dà shāngchǎng chíxù rèxiāo.","vi":"Từ khi vào đông, áo lông vũ liên tục bán chạy ở các trung tâm thương mại lớn."},{"type":"compound","zh":"因为价格便宜又好用，所以这款电饭锅一上市就热销。","pinyin":"Yīnwèi jiàgé piányi yòu hǎoyòng, suǒyǐ zhè kuǎn diànfànguō yí shàngshì jiù rèxiāo.","vi":"Vì giá rẻ lại dễ dùng nên mẫu nồi cơm điện này vừa ra mắt đã bán chạy."}],"related":[{"hanzi":"畅销","pinyin":"chàngxiāo","vi":"bán chạy"},{"hanzi":"抢购","pinyin":"qiǎnggòu","vi":"tranh mua"},{"hanzi":"滞销","pinyin":"zhìxiāo","vi":"ế ẩm"},{"hanzi":"销量","pinyin":"xiāoliàng","vi":"doanh số bán"}],"traditional":"熱銷"},{"id":"热心肠","hanzi":"热心肠","pinyin":"rèxīncháng","meaning_vi":"người nhiệt tình hay giúp đỡ","explanation":"热 (nóng) + 心 (tâm lý/tâm huyết) + 肠 (ruột/tấm lòng).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🤗","examples":[{"type":"basic","zh":"王阿姨是热心肠。","pinyin":"Wáng āyí shì rèxīncháng.","vi":"Dì Vương là người nhiệt tình tốt bụng."},{"type":"simple","zh":"我们楼里有个热心肠的大爷总帮邻居修东西。","pinyin":"Wǒmen lóu li yǒu gè rèxīncháng de dàye zǒng bāng línjū xiū dōngxi.","vi":"Tòa nhà chúng tôi có một ông cụ tốt bụng luôn giúp hàng xóm sửa đồ."},{"type":"compound","zh":"他虽然说话很冲，但其实是个热心肠的人。","pinyin":"Tā suīrán shuōhuà hěn chòng, dàn qíshí shì gè rèxīncháng de rén.","vi":"Anh ấy tuy ăn nói hơi gắt nhưng thực ra là người rất nhiệt tình tốt bụng."}],"related":[{"hanzi":"热心","pinyin":"rèxīn","vi":"nhiệt tâm"},{"hanzi":"好心人","pinyin":"hǎoxīnrén","vi":"người tốt bụng"},{"hanzi":"乐于助人","pinyin":"lèyúzhùrén","vi":"vui vẻ giúp người"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh nhạt"}],"traditional":"熱心腸"},{"id":"热议","hanzi":"热议","pinyin":"rèyì","meaning_vi":"bàn luận sôi nổi","explanation":"热 (nóng) + 议 (nghị luận/hiệp nghị).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"💬","examples":[{"type":"basic","zh":"此事引发热议。","pinyin":"Cǐshì yǐnfā rèyì.","vi":"Việc này gây bàn tán sôi nổi."},{"type":"simple","zh":"新出台的延迟退休政策引起了网友热议。","pinyin":"Xīn chūtái de yánchí tuìxiū zhèngcè yǐnqǐle wǎngyǒu rèyì.","vi":"Chính sách hoãn tuổi nghỉ hưu mới ban hành đã khiến cư dân mạng bàn tán sôi nổi."},{"type":"compound","zh":"虽然这部电影还没上映，但是演员阵容已经被热议了好几天。","pinyin":"Suīrán zhè bù diànyǐng hái méi shàngyìng, dànshì yǎnyuán zhènróng yǐjīng bèi rèyìle hǎo jǐtiān.","vi":"Tuy bộ phim chưa công chiếu, nhưng dàn diễn viên đã được bàn tán sôi nổi mấy ngày nay."}],"related":[{"hanzi":"议论","pinyin":"yìlùn","vi":"bàn tán"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"},{"hanzi":"热点","pinyin":"rèdiǎn","vi":"điểm nóng"},{"hanzi":"热搜","pinyin":"rèsōu","vi":"tìm kiếm nóng"}],"traditional":"熱議"},{"id":"热衷","hanzi":"热衷","pinyin":"rèzhōng","meaning_vi":"say mê, nhiệt tình theo đuổi","explanation":"热 (nhiệt – nóng) + 衷 (trung – nỗi lòng) → say mê, hăng hái theo đuổi điều gì. VD: 热衷于公益事业.","hsk_level":"7-9","tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"他热衷于摄影。","pinyin":"Tā rèzhōng yú shèyǐng.","vi":"Anh ấy say mê nhiếp ảnh."},{"type":"simple","zh":"退休后，爷爷热衷于在阳台上种花养鱼。","pinyin":"Tuìxiū hòu, yéye rèzhōng yú zài yángtái shang zhònghuā yǎng yú.","vi":"Sau khi nghỉ hưu, ông nội say mê trồng hoa nuôi cá ngoài ban công."},{"type":"compound","zh":"与其热衷于攀比名牌，不如多花钱提升自己。","pinyin":"Yǔqí rèzhōng yú pānbǐ míngpái, bùrú duō huāqián tíshēng zìjǐ.","vi":"Thay vì mải mê đua đòi hàng hiệu, chi bằng bỏ tiền nâng cao bản thân."}],"related":[{"hanzi":"热爱","pinyin":"rè'ài","vi":"yêu thích nồng nhiệt"},{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"đắm chìm"},{"hanzi":"爱好","pinyin":"àihào","vi":"sở thích"}],"traditional":"熱衷"},{"id":"认领","hanzi":"认领","pinyin":"rènlǐng","meaning_vi":"nhận lại (đồ thất lạc/nhiệm vụ)","explanation":"认 (công nhận/khẳng định) + 领 (lĩnh vực/lãnh đạo).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"请来认领失物。","pinyin":"Qǐng lái rènlǐng shī wù.","vi":"Xin hãy đến nhận lại đồ thất lạc."},{"type":"simple","zh":"车站失物招领处的一把雨伞至今无人认领。","pinyin":"Chēzhàn shī wù zhāolǐng chù de yì bǎ yǔsǎn zhìjīn wúrén rènlǐng.","vi":"Chiếc ô ở quầy đồ thất lạc của nhà ga đến nay vẫn chưa có ai nhận."},{"type":"compound","zh":"每个小组先认领一个任务，然后在周五前提交结果。","pinyin":"Měi gè xiǎozǔ xiān rènlǐng yí gè rènwù, ránhòu zài Zhōuwǔ qiántí jiāojié guǒ.","vi":"Mỗi nhóm trước tiên nhận một nhiệm vụ, sau đó nộp kết quả trước thứ Sáu."}],"related":[{"hanzi":"领取","pinyin":"lǐngqǔ","vi":"nhận lấy"},{"hanzi":"失物招领","pinyin":"shīwùzhāolǐng","vi":"nhận đồ thất lạc"},{"hanzi":"认养","pinyin":"rènyǎng","vi":"nhận nuôi"},{"hanzi":"冒领","pinyin":"màolǐng","vi":"nhận mạo danh"}],"traditional":"認領"},{"id":"认命","hanzi":"认命","pinyin":"rènmìng","meaning_vi":"cam chịu số phận","explanation":"认 (công nhận/khẳng định) + 命 (mệnh lệnh/số phận).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"我不想认命。","pinyin":"Wǒ bù xiǎng rènmìng.","vi":"Tôi không muốn cam chịu số phận."},{"type":"simple","zh":"那个山村的女孩不甘心就这样认命。","pinyin":"Nà ge shāncūn de nǚhái bù gānxīn jiù zhèyàng rènmìng.","vi":"Cô gái làng núi ấy không cam lòng cứ thế chấp nhận số phận."},{"type":"compound","zh":"即使出身贫寒，他也从来不肯轻易认命。","pinyin":"Jíshǐ chūshēn pínhán, tā yě cónglái bùkěn qīngyì rènmìng.","vi":"Dù xuất thân nghèo khó, anh ấy cũng chưa bao giờ chịu cam phận."}],"related":[{"hanzi":"命运","pinyin":"mìngyùn","vi":"số phận"},{"hanzi":"听天由命","pinyin":"tīngtiānyóumìng","vi":"phó mặc số trời"},{"hanzi":"认输","pinyin":"rènshū","vi":"nhận thua"},{"hanzi":"不甘心","pinyin":"bùgānxīn","vi":"không cam lòng"}],"traditional":"認命"},{"id":"任凭","hanzi":"任凭","pinyin":"rènpíng","meaning_vi":"mặc cho, tùy ý","explanation":"任 (nhiệm vụ/bổ nhiệm) + 凭 (dựa vào).","hsk_level":"7-9","tags":["lien-tu","gioi-tu"],"image":"🤷","examples":[{"type":"basic","zh":"任凭你挑选。","pinyin":"Rènpíng nǐ tiāoxuǎn.","vi":"Tùy bạn chọn lựa."},{"type":"simple","zh":"这些衣服任凭顾客随意试穿。","pinyin":"Zhèxiē yīfu rènpíng gùkè suíyì shìchuān.","vi":"Những bộ quần áo này để khách tùy ý mặc thử."},{"type":"compound","zh":"任凭别人怎么劝，他都不肯改变主意。","pinyin":"Rènpíng biérén zěnme quàn, tā dōu bùkěn gǎibiàn zhǔyi.","vi":"Mặc cho người khác khuyên thế nào, anh ấy cũng không chịu đổi ý."}],"related":[{"hanzi":"无论","pinyin":"wúlùn","vi":"bất kể"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"tùy ý"},{"hanzi":"听任","pinyin":"tīngrèn","vi":"mặc kệ"},{"hanzi":"任由","pinyin":"rènyóu","vi":"mặc cho"}],"traditional":"任憑"},{"id":"认清","hanzi":"认清","pinyin":"rènqīng","meaning_vi":"nhìn rõ, nhận thức rõ ràng","explanation":"认 (công nhận/khẳng định) + 清 (trong sạch/rõ nét).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"👁️","examples":[{"type":"basic","zh":"要认清现实。","pinyin":"Yào rènqīng xiànshí.","vi":"Phải nhìn rõ thực tế."},{"type":"simple","zh":"这次失败让他认清了自己的不足。","pinyin":"Zhè cì shībài ràng tā rènqīngle zìjǐ de bùzú.","vi":"Lần thất bại này giúp anh ấy nhận rõ thiếu sót của bản thân."},{"type":"compound","zh":"只有认清了对手的弱点，我们才能制定正确的战术。","pinyin":"Zhǐyǒu rènqīngle duìshǒu de ruòdiǎn, wǒmen cáinéng zhìdìng zhèngquè de zhànshù.","vi":"Chỉ khi nhận rõ điểm yếu của đối thủ, chúng ta mới đề ra được chiến thuật đúng."}],"related":[{"hanzi":"看清","pinyin":"kànqīng","vi":"nhìn rõ"},{"hanzi":"认识","pinyin":"rènshi","vi":"nhận thức"},{"hanzi":"看透","pinyin":"kàntòu","vi":"nhìn thấu"},{"hanzi":"认清现实","pinyin":"rènqīngxiànshí","vi":"nhìn rõ thực tế"}],"traditional":"認清"},{"id":"认输","hanzi":"认输","pinyin":"rènshū","meaning_vi":"nhận thua","explanation":"认 (công nhận/khẳng định) + 输 (vận chuyển/thua).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏳️","examples":[{"type":"basic","zh":"我绝不认输。","pinyin":"Wǒ juébú rènshū.","vi":"Tôi tuyệt đối không chịu thua."},{"type":"simple","zh":"下到第五十步时，对方主动推盘认输。","pinyin":"Xià dào dì wǔshí bù shí, duìfāng zhǔdòng tuī pán rènshū.","vi":"Đánh đến nước thứ năm mươi, đối phương chủ động đẩy bàn cờ nhận thua."},{"type":"compound","zh":"虽然比分落后很多，但是队员们谁也不肯认输。","pinyin":"Suīrán bǐfēn luòhòu hěn duō, dànshì duìyuánmen shéi yě bùkěn rènshū.","vi":"Tuy bị dẫn điểm nhiều, nhưng không cầu thủ nào chịu nhận thua."}],"related":[{"hanzi":"服输","pinyin":"fúshū","vi":"chịu thua"},{"hanzi":"投降","pinyin":"tóuxiáng","vi":"đầu hàng"},{"hanzi":"不服输","pinyin":"bùfúshū","vi":"không chịu thua"},{"hanzi":"认错","pinyin":"rèncuò","vi":"nhận lỗi"}],"traditional":"認輸"},{"id":"认同感","hanzi":"认同感","pinyin":"rèntónggǎn","meaning_vi":"cảm giác gắn bó, cảm giác thuộc về","explanation":"认 (công nhận/khẳng định) + 同 (đồng lòng/đồng bào) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cam-xuc"],"image":"🤝","examples":[{"type":"basic","zh":"他缺乏认同感。","pinyin":"Tā quēfá rèntónggǎn.","vi":"Anh ấy thiếu cảm giác được công nhận."},{"type":"simple","zh":"统一的工作服能增强员工对公司的认同感。","pinyin":"Tǒngyī de gōngzuòfú néng zēngqiáng yuángōng duì gōngsī de rèntónggǎn.","vi":"Đồng phục thống nhất có thể tăng sự gắn bó và công nhận của nhân viên đối với công ty."},{"type":"compound","zh":"移民的孩子如果学会了当地语言，就更容易产生认同感。","pinyin":"Yímín de háizi rúguǒ xuéhuìle dāngdì yǔyán, jiù gèng róngyì chǎnshēng rèntónggǎn.","vi":"Con cái người nhập cư nếu học được ngôn ngữ bản địa thì dễ nảy sinh cảm giác thuộc về hơn."}],"related":[{"hanzi":"认同","pinyin":"rèntóng","vi":"đồng tình công nhận"},{"hanzi":"归属感","pinyin":"guīshǔgǎn","vi":"cảm giác thuộc về"},{"hanzi":"共鸣","pinyin":"gòngmíng","vi":"đồng cảm cộng hưởng"},{"hanzi":"荣誉感","pinyin":"róngyùgǎn","vi":"niềm vinh dự"}],"traditional":"認同感"},{"id":"任职","hanzi":"任职","pinyin":"rènzhí","meaning_vi":"đảm nhiệm chức vụ","explanation":"任 (nhiệm vụ/bổ nhiệm) + 职 (chức vụ/nghề nghiệp).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他在银行任职。","pinyin":"Tā zài yínháng rènzhí.","vi":"Anh ấy làm việc ở ngân hàng."},{"type":"simple","zh":"她曾在外交部任职长达十五年。","pinyin":"Tā céng zài Wàijiāobù rènzhí chángdá shíwǔ nián.","vi":"Bà từng giữ chức ở Bộ Ngoại giao suốt mười lăm năm."},{"type":"compound","zh":"他在这家公司任职期间，不但业绩突出，而且培养了很多新人。","pinyin":"Tā zài zhè jiā gōngsī rènzhí qījiān, búdàn yèjì tūchū, érqiě péiyǎngle hěn duō xīnrén.","vi":"Trong thời gian công tác tại công ty này, anh ấy không chỉ có thành tích nổi bật mà còn đào tạo nhiều người mới."}],"related":[{"hanzi":"就职","pinyin":"jiùzhí","vi":"nhậm chức"},{"hanzi":"担任","pinyin":"dānrèn","vi":"đảm nhiệm"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"职务","pinyin":"zhíwù","vi":"chức vụ"}],"traditional":"任職"},{"id":"人才辈出","hanzi":"人才辈出","pinyin":"réncái-bèichū","meaning_vi":"nhân tài xuất hiện lớp lớp","explanation":"人 (người) + 才 (tài năng) + 辈 (thế hệ) + 出 (xuất hiện/xuất sắc).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🌟","examples":[{"type":"basic","zh":"这所学校人才辈出。","pinyin":"Zhè suǒ xuéxiào réncáibèichū.","vi":"Ngôi trường này nhân tài xuất hiện lớp lớp."},{"type":"simple","zh":"近几年，中国羽毛球界人才辈出。","pinyin":"Jìnjǐnián, Zhōngguó yǔmáoqiú jiè réncáibèichū.","vi":"Mấy năm gần đây, làng cầu lông Trung Quốc nhân tài xuất hiện liên tục."},{"type":"compound","zh":"因为这个村子特别重视教育，所以历代人才辈出。","pinyin":"Yīnwèi zhè ge cūnzi tèbié zhòngshì jiàoyù, suǒyǐ lìdài réncáibèichū.","vi":"Vì ngôi làng này đặc biệt coi trọng giáo dục nên đời nào cũng có nhân tài."}],"related":[{"hanzi":"人才济济","pinyin":"réncáijǐjǐ","vi":"nhân tài đông đúc"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"英才","pinyin":"yīngcái","vi":"anh tài"},{"hanzi":"后继有人","pinyin":"hòujìyǒurén","vi":"có người kế tục"}],"traditional":"人才輩出"},{"id":"人才流失","hanzi":"人才流失","pinyin":"réncáiliúshī","meaning_vi":"chảy máu chất xám","explanation":"人 (người) + 才 (tài năng) + 流 (lưu truyền/dòng chảy) + 失 (mất đi/sai sót).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"📉","examples":[{"type":"basic","zh":"人才流失很严重。","pinyin":"Réncáiliúshī hěn yánzhòng.","vi":"Chảy máu chất xám rất nghiêm trọng."},{"type":"simple","zh":"低工资是造成小城市人才流失的主要原因。","pinyin":"Dī gōngzī shì zàochéng xiǎo chéngshì réncáiliúshī de zhǔyào yuányīn.","vi":"Lương thấp là nguyên nhân chính gây chảy máu chất xám ở các thành phố nhỏ."},{"type":"compound","zh":"如果公司不提高待遇，人才流失就会越来越严重。","pinyin":"Rúguǒ gōngsī bù tígāo dàiyù, réncáiliúshī jiù huì yuèláiyuè yánzhòng.","vi":"Nếu công ty không nâng đãi ngộ thì tình trạng chảy máu chất xám sẽ ngày càng nghiêm trọng."}],"related":[{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"流失","pinyin":"liúshī","vi":"thất thoát"},{"hanzi":"引进人才","pinyin":"yǐnjìnréncái","vi":"thu hút nhân tài"},{"hanzi":"跳槽","pinyin":"tiàocáo","vi":"nhảy việc"}]},{"id":"人工智能","hanzi":"人工智能","pinyin":"réngōngzhìnéng","meaning_vi":"trí tuệ nhân tạo (AI)","explanation":"人工 (nhân công – do con người làm ra) + 智能 (trí năng – trí tuệ) → trí tuệ nhân tạo, AI. VD: 人工智能技术, 人工智能时代.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","khoa-hoc"],"image":"🤖","examples":[{"type":"basic","zh":"人工智能发展很快。","pinyin":"Réngōngzhìnéng fāzhǎn hěn kuài.","vi":"Trí tuệ nhân tạo phát triển rất nhanh."},{"type":"simple","zh":"医院开始用人工智能帮助医生看片子。","pinyin":"Yīyuàn kāishǐ yòng réngōngzhìnéng bāngzhù yīshēng kàn piānzi.","vi":"Bệnh viện bắt đầu dùng trí tuệ nhân tạo giúp bác sĩ đọc phim chụp."},{"type":"compound","zh":"人工智能不但能写文章，而且还能画画、作曲。","pinyin":"Réngōngzhìnéng búdàn néng xiě wénzhāng, érqiě hái néng huàhuà, zuòqǔ.","vi":"Trí tuệ nhân tạo không chỉ viết được bài mà còn có thể vẽ tranh, sáng tác nhạc."}],"related":[{"hanzi":"机器人","pinyin":"jīqìrén","vi":"người máy"},{"hanzi":"大数据","pinyin":"dàshùjù","vi":"dữ liệu lớn"},{"hanzi":"机器学习","pinyin":"jīqìxuéxí","vi":"học máy"},{"hanzi":"智能","pinyin":"zhìnéng","vi":"thông minh"}]},{"id":"人杰地灵","hanzi":"人杰地灵","pinyin":"rénjié-dìlíng","meaning_vi":"địa linh nhân kiệt","explanation":"人 (người) + 杰 (kiệt xuất) + 地 (地) + 灵 (linh hoạt/linh hồn).","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🏞️","examples":[{"type":"basic","zh":"这里人杰地灵。","pinyin":"Zhèlǐ rénjiédìlíng.","vi":"Nơi đây địa linh nhân kiệt."},{"type":"simple","zh":"人杰地灵的绍兴走出过许多文化名人。","pinyin":"Rénjiédìlíng de Shàoxīng zǒuchūguo xǔduō wénhuà míngrén.","vi":"Thiệu Hưng địa linh nhân kiệt đã sản sinh ra nhiều danh nhân văn hóa."},{"type":"compound","zh":"正因为这里人杰地灵，所以历史上出了好几位状元。","pinyin":"Zhèng yīnwèi zhèlǐ rénjiédìlíng, suǒyǐ lìshǐshang chūle hǎojǐ wèi zhuàngyuán.","vi":"Chính vì nơi đây địa linh nhân kiệt nên trong lịch sử đã có mấy vị trạng nguyên."}],"related":[{"hanzi":"地灵人杰","pinyin":"dìlíngrénjié","vi":"đất thiêng người tài"},{"hanzi":"钟灵毓秀","pinyin":"zhōnglíngyùxiù","vi":"đất linh người đẹp"},{"hanzi":"人才辈出","pinyin":"réncáibèichū","vi":"nhân tài lớp lớp"},{"hanzi":"山清水秀","pinyin":"shānqīngshuǐxiù","vi":"non xanh nước biếc"}],"traditional":"人傑地靈"},{"id":"人际关系","hanzi":"人际关系","pinyin":"rénjìguānxì","meaning_vi":"quan hệ giao tiếp giữa người với người","explanation":"人 (người) + 际 (quốc tế/ranh giới) + 关 (đóng) + 系 (khoa (trong trường đại học)).","hsk_level":"7-9","tags":["danh-tu","giao-tiep","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"他的人际关系很好。","pinyin":"Tā de rénjìguānxì hěn hǎo.","vi":"Quan hệ giao tiếp của anh ấy rất tốt."},{"type":"simple","zh":"刚进公司的新人往往不擅长处理人际关系。","pinyin":"Gāng jìn gōngsī de xīnrén wǎngwǎng bú shàncháng chǔlǐ rénjìguānxì.","vi":"Nhân viên mới vào công ty thường không giỏi xử lý quan hệ với mọi người."},{"type":"compound","zh":"如果你总是斤斤计较，人际关系就会越来越紧张。","pinyin":"Rúguǒ nǐ zǒngshì jīnjīnjìjiào, rénjìguānxì jiù huì yuèláiyuè jǐnzhāng.","vi":"Nếu bạn lúc nào cũng tính toán chi li thì quan hệ với mọi người sẽ ngày càng căng thẳng."}],"related":[{"hanzi":"人脉","pinyin":"rénmài","vi":"mạng lưới quan hệ"},{"hanzi":"交际","pinyin":"jiāojì","vi":"giao tiếp"},{"hanzi":"人缘","pinyin":"rényuán","vi":"duyên giao tiếp"},{"hanzi":"社交","pinyin":"shèjiāo","vi":"xã giao"}],"traditional":"人際關係"},{"id":"人口普查","hanzi":"人口普查","pinyin":"rénkǒupǔchá","meaning_vi":"tổng điều tra dân số","explanation":"人口 (nhân khẩu – dân số) + 普查 (phổ tra – điều tra toàn diện) → cuộc tổng điều tra dân số toàn quốc. Ở TQ thường tiến hành 10 năm một lần.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📊","examples":[{"type":"basic","zh":"今年进行人口普查。","pinyin":"Jīnnián jìnxíng rénkǒupǔchá.","vi":"Năm nay tiến hành tổng điều tra dân số."},{"type":"simple","zh":"工作人员挨家挨户上门做人口普查登记。","pinyin":"Gōngzuò rényuán āijiā'āihù shàngmén zuò rénkǒupǔchá dēngjì.","vi":"Nhân viên đến từng nhà để đăng ký tổng điều tra dân số."},{"type":"compound","zh":"因为人口普查显示儿童增多，所以政府决定新建几所学校。","pinyin":"Yīnwèi rénkǒupǔchá xiǎnshì értóng zēngduō, suǒyǐ zhèngfǔ juédìng xīnjiàn jǐ suǒ xuéxiào.","vi":"Vì tổng điều tra dân số cho thấy trẻ em tăng lên nên chính quyền quyết định xây thêm vài trường học."}],"related":[{"hanzi":"人口","pinyin":"rénkǒu","vi":"dân số"},{"hanzi":"普查","pinyin":"pǔchá","vi":"tổng điều tra"},{"hanzi":"户口","pinyin":"hùkǒu","vi":"hộ khẩu"},{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"}]},{"id":"人流","hanzi":"人流","pinyin":"rénliú","meaning_vi":"dòng người","explanation":"人 (người) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","giao-thong"],"image":"🚶‍♂️","examples":[{"type":"basic","zh":"车站人流很大。","pinyin":"Chēzhàn rénliú hěn dà.","vi":"Dòng người ở nhà ga rất đông."},{"type":"simple","zh":"国庆期间，西湖边的人流量创下新高。","pinyin":"Guóqìng qījiān, Xīhú biān de rénliú liàng chuàngxià xīngāo.","vi":"Dịp Quốc khánh, lưu lượng người bên Tây Hồ lập kỷ lục mới."},{"type":"compound","zh":"一到下班高峰，地铁站里的人流就像潮水一样涌来。","pinyin":"Yí dào xiàbān gāofēng, dìtiězhàn li de rénliú jiù xiàng cháoshuǐ yíyàng yǒng lái.","vi":"Cứ đến giờ tan tầm, dòng người trong ga tàu điện ngầm lại ùa đến như thủy triều."}],"related":[{"hanzi":"人群","pinyin":"rénqún","vi":"đám đông"},{"hanzi":"客流","pinyin":"kèliú","vi":"lượng khách"},{"hanzi":"车流","pinyin":"chēliú","vi":"dòng xe"},{"hanzi":"人山人海","pinyin":"rénshānrénhǎi","vi":"biển người"}]},{"id":"人力","hanzi":"人力","pinyin":"rénlì","meaning_vi":"nhân lực","explanation":"人 (người) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👥","examples":[{"type":"basic","zh":"这需要大量人力。","pinyin":"Zhè xūyào dàliàng rénlì.","vi":"Việc này cần rất nhiều nhân lực."},{"type":"simple","zh":"公司今年在人力成本上多花了三百万。","pinyin":"Gōngsī jīnnián zài rénlì chéngběn shang duō huāle sān bǎiwàn.","vi":"Năm nay công ty chi thêm ba triệu tệ cho chi phí nhân lực."},{"type":"compound","zh":"既然机器能完成这项工作，就没必要再浪费人力了。","pinyin":"Jìrán jīqì néng wánchéng zhè xiàng gōngzuò, jiù méi bìyào zài làngfèi rénlì le.","vi":"Đã có máy làm được việc này thì không cần lãng phí nhân lực nữa."}],"related":[{"hanzi":"人力资源","pinyin":"rénlìzīyuán","vi":"nguồn nhân lực"},{"hanzi":"劳动力","pinyin":"láodònglì","vi":"sức lao động"},{"hanzi":"物力","pinyin":"wùlì","vi":"vật lực"},{"hanzi":"人手","pinyin":"rénshǒu","vi":"nhân công"}]},{"id":"人脉","hanzi":"人脉","pinyin":"rénmài","meaning_vi":"mạng lưới quan hệ xã hội","explanation":"人 (người) + 脉 (mạch máu/dãy núi).","hsk_level":"7-9","tags":["danh-tu","giao-tiep","cong-viec"],"image":"🕸️","examples":[{"type":"basic","zh":"他人脉很广。","pinyin":"Tā rénmài hěn guǎng.","vi":"Anh ấy có mạng lưới quan hệ rất rộng."},{"type":"simple","zh":"她靠多年积累的人脉开了一家咨询公司。","pinyin":"Tā kào duōnián jīlěi de rénmài kāile yìjiā zīxún gōngsī.","vi":"Cô ấy dựa vào mạng lưới quan hệ tích lũy nhiều năm để mở một công ty tư vấn."},{"type":"compound","zh":"光有人脉是不够的，如果没有真本事，就很难长久。","pinyin":"Guāng yǒu rénmài shì búgòu de, rúguǒ méiyǒu zhēn běnshi, jiù hěn nán chángjiǔ.","vi":"Chỉ có quan hệ thôi là chưa đủ, nếu không có bản lĩnh thật thì khó bền lâu."}],"related":[{"hanzi":"人际关系","pinyin":"rénjìguānxì","vi":"quan hệ giữa người"},{"hanzi":"关系网","pinyin":"guānxiwǎng","vi":"mạng lưới quan hệ"},{"hanzi":"人缘","pinyin":"rényuán","vi":"duyên giao tiếp"},{"hanzi":"社交","pinyin":"shèjiāo","vi":"xã giao"}],"traditional":"人脈"},{"id":"人满为患","hanzi":"人满为患","pinyin":"rénmǎn-wéihuàn","meaning_vi":"đông nghịt người quá tải","explanation":"人 (người) + 满 (đầy đủ/thỏa mãn) + 为 (vì) + 患 (lo âu/bệnh nhân).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👥","examples":[{"type":"basic","zh":"景区人满为患。","pinyin":"Jǐngqū rénmǎnwéihuàn.","vi":"Khu du lịch đông nghịt người."},{"type":"simple","zh":"黄金周期间，各大景点都人满为患。","pinyin":"Huángjīnzhōu qījiān, gè dà jǐngdiǎn dōu rénmǎnwéihuàn.","vi":"Trong tuần lễ vàng, các điểm du lịch lớn đều quá tải người."},{"type":"compound","zh":"因为流感高发，所以儿童医院的门诊大厅人满为患。","pinyin":"Yīnwèi liúgǎn gāofā, suǒyǐ értóng yīyuàn de ménzhěn dàtīng rénmǎnwéihuàn.","vi":"Vì cúm bùng phát nên sảnh khám bệnh của bệnh viện nhi đông nghịt người."}],"related":[{"hanzi":"拥挤","pinyin":"yōngjǐ","vi":"chen chúc"},{"hanzi":"人山人海","pinyin":"rénshānrénhǎi","vi":"biển người"},{"hanzi":"水泄不通","pinyin":"shuǐxièbùtōng","vi":"chật như nêm"},{"hanzi":"冷冷清清","pinyin":"lěnglěngqīngqīng","vi":"vắng vẻ"}],"traditional":"人滿為患"},{"id":"人权","hanzi":"人权","pinyin":"rénquán","meaning_vi":"nhân quyền, quyền con người","explanation":"人 (con người) + 权 (quyền).","hsk_level":"7-9","tags":["danh-tu","phap-luat","xa-hoi"],"image":"🕊️","examples":[{"type":"basic","zh":"人权应该受到尊重。","pinyin":"Rénquán yīnggāi shòudào zūnzhòng.","vi":"Nhân quyền cần được tôn trọng."},{"type":"simple","zh":"这位律师多年来一直为残疾人的人权奔走。","pinyin":"Zhè wèi lǜshī duōniánlái yìzhí wèi cánjírén de rénquán bēnzǒu.","vi":"Vị luật sư này nhiều năm nay luôn bôn ba vì quyền con người của người khuyết tật."},{"type":"compound","zh":"不管一个人犯了什么错，他的基本人权都应该得到保障。","pinyin":"Bùguǎn yígèrén fànle shénme cuò, tā de jīběn rénquán dōu yīnggāi dédào bǎozhàng.","vi":"Dù một người phạm lỗi gì, quyền cơ bản của người đó vẫn phải được bảo đảm."}],"related":[{"hanzi":"人身权利","pinyin":"rénshēnquánlì","vi":"quyền nhân thân"},{"hanzi":"权利","pinyin":"quánlì","vi":"quyền lợi"},{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"自由","pinyin":"zìyóu","vi":"tự do"}],"traditional":"人權"},{"id":"人情味","hanzi":"人情味","pinyin":"rénqíngwèi","meaning_vi":"tình người ấm áp","explanation":"人 (người) + 情 (tình cảm/tình hình) + 味 (hương vị/suy ngẫm).","hsk_level":"7-9","tags":["danh-tu","van-hoa","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"小镇很有人情味。","pinyin":"Xiǎozhèn hěn yǒu rénqíngwèi.","vi":"Thị trấn nhỏ rất đậm tình người."},{"type":"simple","zh":"老街坊之间那种浓浓的人情味让我难忘。","pinyin":"Lǎo jiēfang zhījiān nà zhǒng nóng nóng de rénqíngwèi ràng wǒ nánwàng.","vi":"Tình người đậm đà giữa những hàng xóm lâu năm khiến tôi khó quên."},{"type":"compound","zh":"虽然大城市生活方便，但是总觉得少了点人情味。","pinyin":"Suīrán dàchéngshì shēnghuó fāngbiàn, dànshì zǒng juéde shǎole diǎn rénqíngwèi.","vi":"Tuy cuộc sống ở thành phố lớn tiện lợi, nhưng luôn thấy thiếu chút tình người."}],"related":[{"hanzi":"人情","pinyin":"rénqíng","vi":"tình người"},{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh nhạt"},{"hanzi":"人情世故","pinyin":"rénqíngshìgù","vi":"lẽ đời nhân tình"}]},{"id":"人身安全","hanzi":"人身安全","pinyin":"rénshēn'ānquán","meaning_vi":"an toàn tính mạng con người","explanation":"人 (người) + 身 (thân phận/tự thân) + 安 (安) + 全 (toàn diện/đầy đủ).","hsk_level":"7-9","tags":["danh-tu","phap-luat","xa-hoi"],"image":"🛡️","examples":[{"type":"basic","zh":"注意人身安全。","pinyin":"Zhùyì rénshēn'ānquán.","vi":"Hãy chú ý an toàn bản thân."},{"type":"simple","zh":"警方派人二十四小时保护证人的人身安全。","pinyin":"Jǐngfāng pàirén èr shísì xiǎoshí bǎohù zhèngrén de rénshēn'ānquán.","vi":"Cảnh sát cử người bảo vệ an toàn tính mạng cho nhân chứng suốt 24 giờ."},{"type":"compound","zh":"一旦遇到抢劫，就要先保证人身安全，别管财物。","pinyin":"Yídàn yùdào qiǎngjié, jiùyào xiān bǎozhèng rénshēn'ānquán, biéguǎn cáiwù.","vi":"Một khi gặp cướp thì phải đảm bảo an toàn tính mạng trước, đừng màng đến tài sản."}],"related":[{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"},{"hanzi":"人身","pinyin":"rénshēn","vi":"thân thể con người"},{"hanzi":"生命安全","pinyin":"shēngmìng'ānquán","vi":"an toàn tính mạng"},{"hanzi":"保障","pinyin":"bǎozhàng","vi":"bảo đảm"}]},{"id":"人体","hanzi":"人体","pinyin":"réntǐ","meaning_vi":"cơ thể người","explanation":"人 (người) + 体 (thể hiện/hệ thống).","hsk_level":"7-9","tags":["danh-tu","co-the","khoa-hoc"],"image":"🧍","examples":[{"type":"basic","zh":"人体需要水分。","pinyin":"Réntǐ xūyào shuǐfèn.","vi":"Cơ thể người cần nước."},{"type":"simple","zh":"博物馆里展出了一副完整的人体骨骼模型。","pinyin":"Bówùguǎn li zhǎnchūle yí fù wánzhěng de réntǐ gǔgé móxíng.","vi":"Bảo tàng trưng bày một mô hình bộ xương người hoàn chỉnh."},{"type":"compound","zh":"这种塑料一旦受热，就会释放对人体有害的物质。","pinyin":"Zhè zhǒng sùliào yídàn shòurè, jiù huì shìfàng duì réntǐ yǒuhài de wùzhì.","vi":"Loại nhựa này một khi bị nóng sẽ giải phóng chất có hại cho cơ thể người."}],"related":[{"hanzi":"身体","pinyin":"shēntǐ","vi":"cơ thể"},{"hanzi":"器官","pinyin":"qìguān","vi":"cơ quan"},{"hanzi":"人体器官","pinyin":"réntǐqìguān","vi":"cơ quan người"},{"hanzi":"健康","pinyin":"jiànkāng","vi":"sức khỏe"}],"traditional":"人體"},{"id":"人文","hanzi":"人文","pinyin":"rénwén","meaning_vi":"nhân văn","explanation":"人 (người) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"🏛️","examples":[{"type":"basic","zh":"我喜欢人文学科。","pinyin":"Wǒ xǐhuan rénwén xuékē.","vi":"Tôi thích các ngành khoa học nhân văn."},{"type":"simple","zh":"这座古城有着深厚的人文底蕴。","pinyin":"Zhè zuò gǔchéng yǒuzhe shēnhòu de rénwén dǐyùn.","vi":"Tòa cổ thành này có bề dày nhân văn sâu sắc."},{"type":"compound","zh":"去旅游时，与其只看风景，不如多了解当地的人文历史。","pinyin":"Qù lǚyóu shí, yǔqí zhǐ kàn fēngjǐng, bùrú duō liǎojiě dāngdì de rénwén lìshǐ.","vi":"Khi đi du lịch, thay vì chỉ ngắm cảnh, chi bằng tìm hiểu thêm lịch sử nhân văn của địa phương."}],"related":[{"hanzi":"人文科学","pinyin":"rénwénkēxué","vi":"khoa học nhân văn"},{"hanzi":"文化","pinyin":"wénhuà","vi":"văn hóa"},{"hanzi":"人文关怀","pinyin":"rénwénguānhuái","vi":"quan tâm nhân văn"},{"hanzi":"自然科学","pinyin":"zìránkēxué","vi":"khoa học tự nhiên"}]},{"id":"人选","hanzi":"人选","pinyin":"rénxuǎn","meaning_vi":"ứng viên được chọn","explanation":"人 (người) + 选 (tuyển chọn/bầu cử).","hsk_level":"7-9","tags":["danh-tu","cong-viec","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"他是最佳人选。","pinyin":"Tā shì zuì jiā rénxuǎn.","vi":"Anh ấy là ứng viên tốt nhất."},{"type":"simple","zh":"董事会还在讨论新任总经理的人选。","pinyin":"Dǒngshìhuì hái zài tǎolùn xīnrèn zǒngjīnglǐ de rénxuǎn.","vi":"Hội đồng quản trị vẫn đang bàn về người được chọn làm tổng giám đốc mới."},{"type":"compound","zh":"因为她既懂技术又会管理，所以成了项目负责人的合适人选。","pinyin":"Yīnwèi tā jì dǒng jìshù yòu huì guǎnlǐ, suǒyǐ chéngle xiàngmù fùzérén de héshì rénxuǎn.","vi":"Vì cô ấy vừa hiểu kỹ thuật vừa biết quản lý nên trở thành người phù hợp để phụ trách dự án."}],"related":[{"hanzi":"候选人","pinyin":"hòuxuǎnrén","vi":"ứng cử viên"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"选拔","pinyin":"xuǎnbá","vi":"tuyển chọn"},{"hanzi":"合适","pinyin":"héshì","vi":"phù hợp"}],"traditional":"人選"},{"id":"人性化","hanzi":"人性化","pinyin":"rénxìnghuà","meaning_vi":"nhân văn hóa, thân thiện với người dùng","explanation":"人 (người) + 性 (tính chất/tính cách) + 化 (化).","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🤗","examples":[{"type":"basic","zh":"这个设计很人性化。","pinyin":"Zhè ge shèjì hěn rénxìnghuà.","vi":"Thiết kế này rất thân thiện với người dùng."},{"type":"simple","zh":"这家医院在走廊两边都装了人性化的扶手。","pinyin":"Zhè jiā yīyuàn zài zǒuláng liǎngbiān dōu zhuāngle rénxìnghuà de fúshǒu.","vi":"Bệnh viện này lắp tay vịn tiện dụng cho người bệnh ở hai bên hành lang."},{"type":"compound","zh":"如果管理制度更人性化一点，员工就会更愿意留下来。","pinyin":"Rúguǒ guǎnlǐ zhìdù gèng rénxìnghuà yìdiǎn, yuángōng jiù huì gèng yuànyì liú xiàlái.","vi":"Nếu chế độ quản lý nhân văn hơn một chút, nhân viên sẽ muốn ở lại hơn."}],"related":[{"hanzi":"人性","pinyin":"rénxìng","vi":"nhân tính"},{"hanzi":"以人为本","pinyin":"yǐrénwéiběn","vi":"lấy con người làm gốc"},{"hanzi":"贴心","pinyin":"tiēxīn","vi":"chu đáo"},{"hanzi":"便捷","pinyin":"biànjié","vi":"tiện lợi"}]},{"id":"人缘","hanzi":"人缘","pinyin":"rényuán","meaning_vi":"duyên giao tiếp, được mọi người yêu mến","explanation":"人 (người) + 缘 (duyên phận/nguyên cớ).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"😊","examples":[{"type":"basic","zh":"她人缘很好。","pinyin":"Tā rényuán hěn hǎo.","vi":"Cô ấy được mọi người rất quý mến."},{"type":"simple","zh":"小李凭着幽默的性格在班里有了好人缘。","pinyin":"Xiǎo Lǐ píngzhe yōumò de xìnggé zài bān li yǒule hǎo rényuán.","vi":"Tiểu Lý nhờ tính cách hài hước mà được cả lớp quý mến."},{"type":"compound","zh":"一个人如果总是乐于助人，人缘自然就不会差。","pinyin":"Yígèrén rúguǒ zǒngshì lèyú zhùrén, rényuán zìrán jiù bú huì chà.","vi":"Một người nếu luôn vui vẻ giúp đỡ người khác thì tự nhiên sẽ được mọi người quý mến."}],"related":[{"hanzi":"人缘好","pinyin":"rényuánhǎo","vi":"được lòng mọi người"},{"hanzi":"人际关系","pinyin":"rénjìguānxì","vi":"quan hệ giữa người"},{"hanzi":"受欢迎","pinyin":"shòuhuānyíng","vi":"được yêu mến"},{"hanzi":"人脉","pinyin":"rénmài","vi":"mạng lưới quan hệ"}],"traditional":"人緣"},{"id":"人造","hanzi":"人造","pinyin":"rénzào","meaning_vi":"nhân tạo","explanation":"人 (người) + 造 (sáng tạo/chế tạo).","hsk_level":"7-9","tags":["tinh-tu","khoa-hoc"],"image":"🤖","examples":[{"type":"basic","zh":"这是人造皮革。","pinyin":"Zhè shì rénzào pígé.","vi":"Đây là da nhân tạo."},{"type":"simple","zh":"市中心新建了一个可以划船的人造湖。","pinyin":"Shìzhōngxīn xīnjiànle yí gè kěyǐ huáchuán de rénzào hú.","vi":"Trung tâm thành phố mới xây một hồ nhân tạo có thể chèo thuyền."},{"type":"compound","zh":"虽然人造钻石价格便宜，但是外观和天然钻石几乎一样。","pinyin":"Suīrán rénzào zuànshí jiàgé piányi, dànshì wàiguān hé tiānrán zuànshí jīhū yíyàng.","vi":"Tuy kim cương nhân tạo rẻ, nhưng bề ngoài gần như giống hệt kim cương tự nhiên."}],"related":[{"hanzi":"人工","pinyin":"réngōng","vi":"nhân công, nhân tạo"},{"hanzi":"人造卫星","pinyin":"rénzàowèixīng","vi":"vệ tinh nhân tạo"},{"hanzi":"天然","pinyin":"tiānrán","vi":"tự nhiên"},{"hanzi":"合成","pinyin":"héchéng","vi":"tổng hợp"}]},{"id":"人造卫星","hanzi":"人造卫星","pinyin":"rénzàowèixīng","meaning_vi":"vệ tinh nhân tạo","explanation":"人 (người) + 造 (sáng tạo/chế tạo) + 卫 (bảo vệ/vệ sinh) + 星 (ngôi sao).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🛰️","examples":[{"type":"basic","zh":"人造卫星发射了。","pinyin":"Rénzàowèixīng fāshè le.","vi":"Vệ tinh nhân tạo đã được phóng lên."},{"type":"simple","zh":"天气预报的数据很多来自人造卫星。","pinyin":"Tiānqì yùbào de shùjù hěn duō láizì rénzàowèixīng.","vi":"Dữ liệu dự báo thời tiết phần lớn đến từ vệ tinh nhân tạo."},{"type":"compound","zh":"如果没有人造卫星，我们的手机导航就无法使用。","pinyin":"Rúguǒ méiyǒu rénzàowèixīng, wǒmen de shǒujī dǎoháng jiù wúfǎ shǐyòng.","vi":"Nếu không có vệ tinh nhân tạo, định vị trên điện thoại của chúng ta sẽ không dùng được."}],"related":[{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"火箭","pinyin":"huǒjiàn","vi":"tên lửa"},{"hanzi":"太空","pinyin":"tàikōng","vi":"vũ trụ"},{"hanzi":"发射","pinyin":"fāshè","vi":"phóng"}],"traditional":"人造衛星"},{"id":"仁爱","hanzi":"仁爱","pinyin":"rén'ài","meaning_vi":"nhân ái","explanation":"仁 (nhân từ/lòng nhân) + 爱 (yêu).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"💖","examples":[{"type":"basic","zh":"他心怀仁爱。","pinyin":"Tā xīnhuái rén'ài.","vi":"Ông ấy mang lòng nhân ái."},{"type":"simple","zh":"儒家思想把仁爱看作做人的根本。","pinyin":"Rújiāsīxiǎng bǎ rén'ài kànzuò zuòrén de gēnběn.","vi":"Tư tưởng Nho gia coi nhân ái là gốc rễ của đạo làm người."},{"type":"compound","zh":"这位医生不但医术高明，而且对穷苦病人充满仁爱。","pinyin":"Zhè wèi yīshēng búdàn yīshù gāomíng, érqiě duì qióngkǔ bìngrén chōngmǎn rén'ài.","vi":"Vị bác sĩ này không chỉ y thuật cao minh mà còn đầy lòng nhân ái với bệnh nhân nghèo."}],"related":[{"hanzi":"仁慈","pinyin":"réncí","vi":"nhân từ"},{"hanzi":"博爱","pinyin":"bó'ài","vi":"bác ái"},{"hanzi":"善良","pinyin":"shànliáng","vi":"lương thiện"},{"hanzi":"爱心","pinyin":"àixīn","vi":"lòng yêu thương"}],"traditional":"仁愛"},{"id":"日夜","hanzi":"日夜","pinyin":"rìyè","meaning_vi":"ngày đêm","explanation":"日 (ngày) + 夜 (ban đêm).","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"🌓","examples":[{"type":"basic","zh":"工人日夜施工。","pinyin":"Gōngrén rìyè shīgōng.","vi":"Công nhân thi công ngày đêm."},{"type":"simple","zh":"母亲日夜守在病床前照顾发烧的孩子。","pinyin":"Mǔqīn rìyè shǒu zài bìngchuáng qián zhàogù fāshāo de háizi.","vi":"Người mẹ ngày đêm túc trực bên giường chăm sóc đứa con bị sốt."},{"type":"compound","zh":"因为订单太多，所以工厂只好日夜不停地生产。","pinyin":"Yīnwèi dìngdān tài duō, suǒyǐ gōngchǎng zhǐhǎo rìyè bùtíng de shēngchǎn.","vi":"Vì đơn hàng quá nhiều nên nhà máy đành sản xuất ngày đêm không nghỉ."}],"related":[{"hanzi":"昼夜","pinyin":"zhòuyè","vi":"ngày đêm"},{"hanzi":"日日夜夜","pinyin":"rìrìyèyè","vi":"ngày ngày đêm đêm"},{"hanzi":"白天","pinyin":"báitiān","vi":"ban ngày"},{"hanzi":"夜晚","pinyin":"yèwǎn","vi":"ban đêm"}]},{"id":"日用","hanzi":"日用","pinyin":"rìyòng","meaning_vi":"dùng hàng ngày","explanation":"日 (ngày) + 用 (vận dụng/công dụng).","hsk_level":"7-9","tags":["tinh-tu","sinh-hoat"],"image":"🧴","examples":[{"type":"basic","zh":"超市卖日用百货。","pinyin":"Chāoshì mài rìyòng bǎihuò.","vi":"Siêu thị bán hàng tạp hóa dùng hằng ngày."},{"type":"simple","zh":"搬家前，她把牙膏毛巾等日用品装进了一个箱子。","pinyin":"Bānjiā qián, tā bǎ yágāo máojīn děng rìyòngpǐn zhuāng jìnle yí gè xiāngzi.","vi":"Trước khi chuyển nhà, cô ấy cho kem đánh răng, khăn mặt và các đồ dùng hằng ngày vào một chiếc thùng."},{"type":"compound","zh":"只要有一家日用杂货店，村民买东西就方便多了。","pinyin":"Zhǐyào yǒu yìjiā rìyòng záhuòdiàn, cūnmín mǎidōngxi jiù fāngbiàn duō le.","vi":"Chỉ cần có một tiệm tạp hóa đồ dùng hằng ngày, dân làng mua sắm đã tiện hơn nhiều."}],"related":[{"hanzi":"日用品","pinyin":"rìyòngpǐn","vi":"đồ dùng hàng ngày"},{"hanzi":"日常","pinyin":"rìcháng","vi":"hằng ngày"},{"hanzi":"用品","pinyin":"yòngpǐn","vi":"đồ dùng"},{"hanzi":"生活用品","pinyin":"shēnghuóyòngpǐn","vi":"đồ dùng sinh hoạt"}]},{"id":"融入","hanzi":"融入","pinyin":"róngrù","meaning_vi":"hòa nhập vào","explanation":"融 (hòa tan/tài chính) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌊","examples":[{"type":"basic","zh":"他很快融入了团队。","pinyin":"Tā hěn kuài róngrùle tuánduì.","vi":"Anh ấy nhanh chóng hòa nhập vào nhóm."},{"type":"simple","zh":"留学第一年，她努力融入当地的生活。","pinyin":"Liúxué dìyī nián, tā nǔlì róngrù dāngdì de shēnghuó.","vi":"Năm đầu du học, cô ấy cố gắng hòa nhập vào cuộc sống bản địa."},{"type":"compound","zh":"只要你主动跟同学交流，就能很快融入新的集体。","pinyin":"Zhǐyào nǐ zhǔdòng gēn tóngxué jiāoliú, jiù néng hěn kuài róngrù xīn de jítǐ.","vi":"Chỉ cần bạn chủ động giao lưu với bạn học là có thể nhanh chóng hòa nhập vào tập thể mới."}],"related":[{"hanzi":"融合","pinyin":"rónghé","vi":"hòa hợp"},{"hanzi":"融为一体","pinyin":"róngwéiyìtǐ","vi":"hòa làm một"},{"hanzi":"适应","pinyin":"shìyìng","vi":"thích nghi"},{"hanzi":"加入","pinyin":"jiārù","vi":"gia nhập"}]},{"id":"融为一体","hanzi":"融为一体","pinyin":"róngwéi-yìtǐ","meaning_vi":"hòa quyện làm một","explanation":"融 (hòa tan/tài chính) + 为 (vì) + 一 (số 1) + 体 (thể hiện/hệ thống).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔗","examples":[{"type":"basic","zh":"人与自然融为一体。","pinyin":"Rén yǔ zìrán róngwéiyìtǐ.","vi":"Con người và thiên nhiên hòa làm một."},{"type":"simple","zh":"这座木屋的设计和周围的森林融为一体。","pinyin":"Zhè zuò mù wū de shèjì hé zhōuwéi de sēnlín róngwéiyìtǐ.","vi":"Thiết kế của ngôi nhà gỗ này hòa quyện làm một với khu rừng xung quanh."},{"type":"compound","zh":"舞者一跳起来，身体就仿佛和音乐融为一体了。","pinyin":"Wǔzhě yí tiào qǐlái, shēntǐ jiù fǎngfú hé yīnyuè róngwéiyìtǐ le.","vi":"Vũ công vừa cất bước nhảy, cơ thể dường như đã hòa làm một với âm nhạc."}],"related":[{"hanzi":"融合","pinyin":"rónghé","vi":"hòa hợp"},{"hanzi":"合为一体","pinyin":"héwéiyìtǐ","vi":"hợp thành một"},{"hanzi":"融入","pinyin":"róngrù","vi":"hòa nhập"},{"hanzi":"一体化","pinyin":"yìtǐhuà","vi":"nhất thể hóa"}],"traditional":"融為一體"},{"id":"荣誉感","hanzi":"荣誉感","pinyin":"róngyùgǎn","meaning_vi":"niềm vinh dự tự hào","explanation":"荣 (vinh dự/phồn vinh) + 誉 (danh dự/ca ngợi) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🏅","examples":[{"type":"basic","zh":"他荣誉感很强。","pinyin":"Tā róngyùgǎn hěn qiáng.","vi":"Anh ấy có ý thức danh dự rất cao."},{"type":"simple","zh":"穿上国家队的球衣让他充满了荣誉感。","pinyin":"Chuānshang guójiāduì de qiúyī ràng tā chōngmǎnle róngyùgǎn.","vi":"Khoác lên áo đội tuyển quốc gia khiến anh ấy tràn đầy niềm tự hào."},{"type":"compound","zh":"因为班级荣誉感很强，所以同学们在运动会上都拼尽了全力。","pinyin":"Yīnwèi bānjí róngyùgǎn hěn qiáng, suǒyǐ tóngxuémen zài yùndònghuì Shangdōu pīn jìnle quánlì.","vi":"Vì niềm tự hào tập thể lớp rất cao nên các bạn đều dốc toàn lực ở hội thao."}],"related":[{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"自豪感","pinyin":"zìháogǎn","vi":"niềm tự hào"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vẻ vang"},{"hanzi":"集体荣誉","pinyin":"jítǐróngyù","vi":"vinh dự tập thể"}],"traditional":"榮譽感"},{"id":"融资","hanzi":"融资","pinyin":"róngzī","meaning_vi":"huy động vốn, gọi vốn","explanation":"融 (lưu thông) + 资 (vốn). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"🏦","examples":[{"type":"basic","zh":"公司正在融资。","pinyin":"Gōngsī zhèngzài róngzī.","vi":"Công ty đang gọi vốn."},{"type":"simple","zh":"这家初创企业刚刚完成了五千万元的融资。","pinyin":"Zhè jiā chūchuàng qǐyè gānggāng wánchéngle wǔ qiānwàn yuán de róngzī.","vi":"Công ty khởi nghiệp này vừa hoàn tất vòng gọi vốn năm mươi triệu tệ."},{"type":"compound","zh":"如果下个月融资还不到位，项目就得暂停。","pinyin":"Rúguǒ xiàgèyuè róngzī hái bú dàowèi, xiàngmù jiù děi zàntíng.","vi":"Nếu tháng sau vốn gọi được vẫn chưa về thì dự án phải tạm dừng."}],"related":[{"hanzi":"投资","pinyin":"tóuzī","vi":"đầu tư"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"vay tiền"},{"hanzi":"投资人","pinyin":"tóuzīrén","vi":"nhà đầu tư"}],"traditional":"融資"},{"id":"揉搓","hanzi":"揉搓","pinyin":"róucuō","meaning_vi":"xoa bóp, vò","explanation":"揉 (xoa bóp/vò) + 搓 (vò/xoa).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"轻轻揉搓衣领。","pinyin":"Qīngqīng róucuō yīlǐng.","vi":"Nhẹ nhàng vò cổ áo."},{"type":"simple","zh":"洗手时要用肥皂把手心手背反复揉搓。","pinyin":"Xǐshǒu shí yào yòng féizào bǎshǒu xīn shǒubèi fǎnfù róucuō.","vi":"Khi rửa tay phải dùng xà phòng chà xát lòng bàn tay và mu bàn tay nhiều lần."},{"type":"compound","zh":"真丝衣服如果用力揉搓，就很容易变形。","pinyin":"Zhēn sī yīfu rúguǒ yònglì róucuō, jiù hěn róngyì biànxíng.","vi":"Quần áo lụa tơ tằm nếu vò mạnh thì rất dễ bị biến dạng."}],"related":[{"hanzi":"揉","pinyin":"róu","vi":"xoa, nhào"},{"hanzi":"搓","pinyin":"cuō","vi":"chà xát"},{"hanzi":"按摩","pinyin":"ànmó","vi":"xoa bóp"},{"hanzi":"搓洗","pinyin":"cuōxǐ","vi":"vò giặt"}]},{"id":"柔美","hanzi":"柔美","pinyin":"róuměi","meaning_vi":"mềm mại duyên dáng","explanation":"柔 (dịu dàng/mềm mại) + 美 (tươi đẹp/mỹ mãn).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌸","examples":[{"type":"basic","zh":"她的舞姿很柔美。","pinyin":"Tā de wǔzī hěn róuměi.","vi":"Dáng múa của cô ấy rất mềm mại duyên dáng."},{"type":"simple","zh":"她用柔美的嗓音唱了一首江南小调。","pinyin":"Tā yòng róuměi de sǎngyīn chàngle yì shǒu Jiāngnán xiǎodiào.","vi":"Cô ấy cất giọng mềm mại ngọt ngào hát một khúc dân ca Giang Nam."},{"type":"compound","zh":"这幅画虽然线条柔美，但是色彩却很大胆。","pinyin":"Zhè fú huà suīrán xiàntiáo róuměi, dànshì sècǎi què hěn dàdǎn.","vi":"Bức tranh này tuy đường nét mềm mại, nhưng màu sắc lại rất táo bạo."}],"related":[{"hanzi":"柔和","pinyin":"róuhé","vi":"dịu dàng"},{"hanzi":"优美","pinyin":"yōuměi","vi":"đẹp đẽ"},{"hanzi":"温柔","pinyin":"wēnróu","vi":"dịu dàng"},{"hanzi":"刚强","pinyin":"gāngqiáng","vi":"cứng cỏi"}]},{"id":"柔软","hanzi":"柔软","pinyin":"róuruǎn","meaning_vi":"mềm mại","explanation":"柔 (dịu dàng/mềm mại) + 软 (mềm yếu).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🧸","examples":[{"type":"basic","zh":"这条毛巾很柔软。","pinyin":"Zhè tiáo máojīn hěn róuruǎn.","vi":"Chiếc khăn này rất mềm mại."},{"type":"simple","zh":"小狗趴在柔软的沙发上睡着了。","pinyin":"Xiǎogǒu pā zài róuruǎn de shāfā shang shuìzháo le.","vi":"Chú chó con nằm bò trên chiếc sofa mềm mại ngủ thiếp đi."},{"type":"compound","zh":"面团揉得越久，做出来的馒头就越柔软。","pinyin":"Miàntuán róu de yuè jiǔ, zuò chūlái de mántou jiù yuè róuruǎn.","vi":"Bột nhào càng lâu thì bánh bao làm ra càng mềm."}],"related":[{"hanzi":"柔和","pinyin":"róuhé","vi":"dịu dàng"},{"hanzi":"松软","pinyin":"sōngruǎn","vi":"xốp mềm"},{"hanzi":"坚硬","pinyin":"jiānyìng","vi":"cứng rắn"},{"hanzi":"软绵绵","pinyin":"ruǎnmiánmián","vi":"mềm nhũn"}],"traditional":"柔軟"},{"id":"入场券","hanzi":"入场券","pinyin":"rùchǎngquàn","meaning_vi":"vé vào cửa","explanation":"入 (nhập vào/sâu sắc) + 场 (địa điểm/trận đấu) + 券 (券).","hsk_level":"7-9","tags":["danh-tu","giai-tri","do-vat"],"image":"🎫","examples":[{"type":"basic","zh":"我买到了入场券。","pinyin":"Wǒ mǎi dàole rùchǎngquàn.","vi":"Tôi đã mua được vé vào cửa."},{"type":"simple","zh":"这张音乐节的入场券在网上被炒到了两千元。","pinyin":"Zhè zhāng yīnyuèjié de rùchǎngquàn zài wǎngshang bèi chǎo dàole liǎng qiān yuán.","vi":"Tấm vé vào cửa lễ hội âm nhạc này bị đẩy giá trên mạng lên hai nghìn tệ."},{"type":"compound","zh":"只要赢下这场比赛，球队就能拿到世界杯的入场券。","pinyin":"Zhǐyào yíng xià zhè chǎng bǐsài, qiúduì jiù néng nádào Shìjièbēi de rùchǎngquàn.","vi":"Chỉ cần thắng trận này, đội bóng sẽ giành được tấm vé dự World Cup."}],"related":[{"hanzi":"门票","pinyin":"ménpiào","vi":"vé vào cửa"},{"hanzi":"入场","pinyin":"rùchǎng","vi":"vào cửa"},{"hanzi":"票价","pinyin":"piàojià","vi":"giá vé"},{"hanzi":"检票","pinyin":"jiǎnpiào","vi":"soát vé"}],"traditional":"入場券"},{"id":"入境","hanzi":"入境","pinyin":"rùjìng","meaning_vi":"nhập cảnh","explanation":"入 (nhập vào/sâu sắc) + 境 (cảnh giới/hoàn cảnh).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🛬","examples":[{"type":"basic","zh":"他已经入境了。","pinyin":"Tā yǐjīng rùjìng le.","vi":"Anh ấy đã nhập cảnh rồi."},{"type":"simple","zh":"外国游客入境时需要填写一张健康申报表。","pinyin":"Wàiguó yóukè rùjìng shí xūyào tiánxiě yì zhāng jiànkāng shēnbàobiǎo.","vi":"Du khách nước ngoài khi nhập cảnh cần điền một tờ khai y tế."},{"type":"compound","zh":"如果护照有效期不足六个月，就可能被拒绝入境。","pinyin":"Rúguǒ hùzhào yǒuxiàoqī bùzú liù gèyuè, jiù kěnéng bèi jùjué rùjìng.","vi":"Nếu hộ chiếu còn hạn dưới sáu tháng thì có thể bị từ chối nhập cảnh."}],"related":[{"hanzi":"出境","pinyin":"chūjìng","vi":"xuất cảnh"},{"hanzi":"签证","pinyin":"qiānzhèng","vi":"thị thực"},{"hanzi":"护照","pinyin":"hùzhào","vi":"hộ chiếu"},{"hanzi":"海关","pinyin":"hǎiguān","vi":"hải quan"}]},{"id":"入迷","hanzi":"入迷","pinyin":"rùmí","meaning_vi":"mê mẩn, say sưa","explanation":"入 (nhập vào/sâu sắc) + 迷 (mê mẩn/lạc).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🤩","examples":[{"type":"basic","zh":"孩子们听入迷了。","pinyin":"Háizimen tīng rùmí le.","vi":"Bọn trẻ nghe say mê."},{"type":"simple","zh":"弟弟对着那本恐龙百科看得入迷。","pinyin":"Dìdi duìzhe nà běn kǒnglóng bǎikē kàn de rùmí.","vi":"Em trai mải mê xem cuốn bách khoa về khủng long."},{"type":"compound","zh":"他一下起围棋来，就入迷得忘了时间。","pinyin":"Tā yíxià qǐ wéiqí lái, jiù rùmí de wàngle shíjiān.","vi":"Anh ấy hễ chơi cờ vây là mê mẩn quên cả thời gian."}],"related":[{"hanzi":"着迷","pinyin":"zháomí","vi":"say mê"},{"hanzi":"入神","pinyin":"rùshén","vi":"chăm chú say sưa"},{"hanzi":"沉迷","pinyin":"chénmí","vi":"đắm chìm"},{"hanzi":"陶醉","pinyin":"táozuì","vi":"say sưa"}]},{"id":"入睡","hanzi":"入睡","pinyin":"rùshuì","meaning_vi":"đi vào giấc ngủ","explanation":"入 (nhập vào/sâu sắc) + 睡 (睡).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"我很难入睡。","pinyin":"Wǒ hěn nán rùshuì.","vi":"Tôi rất khó ngủ."},{"type":"simple","zh":"睡前喝一杯热牛奶能帮助你更快入睡。","pinyin":"Shuì qián hē yì bēi rè niúnǎi néng bāngzhù nǐ gèng kuài rùshuì.","vi":"Uống một cốc sữa nóng trước khi ngủ giúp bạn ngủ nhanh hơn."},{"type":"compound","zh":"因为楼上一直在装修，所以她到凌晨两点才入睡。","pinyin":"Yīnwèi lóushàng yìzhí zài zhuāngxiū, suǒyǐ tā dào língchén liǎng diǎn cái rùshuì.","vi":"Vì tầng trên sửa nhà suốt nên đến hai giờ sáng cô ấy mới ngủ được."}],"related":[{"hanzi":"睡着","pinyin":"shuìzháo","vi":"ngủ thiếp đi"},{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"入眠","pinyin":"rùmián","vi":"chìm vào giấc ngủ"},{"hanzi":"睡眠","pinyin":"shuìmián","vi":"giấc ngủ"}]},{"id":"入手","hanzi":"入手","pinyin":"rùshǒu","meaning_vi":"bắt tay vào làm","explanation":"入 (nhập vào/sâu sắc) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"先从基础入手。","pinyin":"Xiān cóng jīchǔ rùshǒu.","vi":"Hãy bắt đầu từ nền tảng."},{"type":"simple","zh":"警方决定从那辆可疑的白色轿车入手调查。","pinyin":"Jǐngfāng juédìng cóng nà liàng kěyí de báisè jiàochē rùshǒu diàochá.","vi":"Cảnh sát quyết định bắt tay điều tra từ chiếc xe con màu trắng khả nghi."},{"type":"compound","zh":"要解决交通拥堵，与其多修马路，不如从发展公共交通入手。","pinyin":"Yào jiějué jiāotōng yōngdǔ, yǔqí duō xiū mǎlù, bùrú cóng fāzhǎn gōnggòng jiāotōng rùshǒu.","vi":"Muốn giải quyết ùn tắc, thay vì làm thêm đường, chi bằng bắt tay từ việc phát triển giao thông công cộng."}],"related":[{"hanzi":"着手","pinyin":"zhuóshǒu","vi":"bắt tay vào"},{"hanzi":"下手","pinyin":"xiàshǒu","vi":"ra tay"},{"hanzi":"动手","pinyin":"dòngshǒu","vi":"bắt tay làm"},{"hanzi":"开始","pinyin":"kāishǐ","vi":"bắt đầu"}]},{"id":"入选","hanzi":"入选","pinyin":"rùxuǎn","meaning_vi":"được tuyển chọn, lọt vào danh sách","explanation":"入 (nhập vào/sâu sắc) + 选 (tuyển chọn/bầu cử).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏅","examples":[{"type":"basic","zh":"她入选了国家队。","pinyin":"Tā rùxuǎnle guójiāduì.","vi":"Cô ấy được chọn vào đội tuyển quốc gia."},{"type":"simple","zh":"这篇作文入选了全市优秀作文集。","pinyin":"Zhè piān zuòwén rùxuǎnle quánshì yōuxiù zuò wénjí.","vi":"Bài văn này được chọn vào tuyển tập bài văn xuất sắc toàn thành phố."},{"type":"compound","zh":"他虽然入选了大名单，但是最终没能获得上场机会。","pinyin":"Tā suīrán rùxuǎnle dà míngdān, dànshì zuìzhōng méi néng huòdé shàngchǎng jīhuì.","vi":"Anh ấy tuy lọt vào danh sách sơ bộ, nhưng cuối cùng không được ra sân."}],"related":[{"hanzi":"当选","pinyin":"dāngxuǎn","vi":"trúng cử"},{"hanzi":"落选","pinyin":"luòxuǎn","vi":"trượt tuyển"},{"hanzi":"入围","pinyin":"rùwéi","vi":"lọt vào vòng"},{"hanzi":"选拔","pinyin":"xuǎnbá","vi":"tuyển chọn"}],"traditional":"入選"},{"id":"润色","hanzi":"润色","pinyin":"rùnsè","meaning_vi":"trau chuốt câu chữ (biên tập văn bản)","explanation":"润 (lợi nhuận/ẩm mịn) + 色 (màu sắc/thần sắc).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"请帮我润色一下。","pinyin":"Qǐng bāng wǒ rùnsè yíxià.","vi":"Nhờ bạn trau chuốt giúp tôi một chút."},{"type":"simple","zh":"编辑花了一周时间为这部小说润色。","pinyin":"Biānjí huāle yìzhōu shíjiān wèi zhè bù xiǎoshuō rùnsè.","vi":"Biên tập viên mất một tuần để trau chuốt câu chữ cho cuốn tiểu thuyết này."},{"type":"compound","zh":"这份演讲稿一经老师润色，就显得流畅多了。","pinyin":"Zhè fèn yǎnjiǎng gǎo yìjīng lǎoshī rùnsè, jiù xiǎnde liúchàng duō le.","vi":"Bản diễn văn này vừa được thầy trau chuốt đã trôi chảy hơn hẳn."}],"related":[{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa đổi"},{"hanzi":"修饰","pinyin":"xiūshì","vi":"chỉnh sửa trau chuốt"},{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập"},{"hanzi":"推敲","pinyin":"tuīqiāo","vi":"cân nhắc câu chữ"}],"traditional":"潤色"},{"id":"如常","hanzi":"如常","pinyin":"rúcháng","meaning_vi":"như thường lệ","explanation":"如 (如) + 常 (thường xuyên/thông lệ).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"今天一切如常。","pinyin":"Jīntiān yíqiè rúcháng.","vi":"Hôm nay mọi thứ vẫn như thường."},{"type":"simple","zh":"台风过后，市民的生活很快恢复如常。","pinyin":"Táifēng guòhòu, shìmín de shēnghuó hěn kuài huīfù rúcháng.","vi":"Sau bão, cuộc sống của người dân nhanh chóng trở lại như thường."},{"type":"compound","zh":"虽然外面下着大雪，但是早市的摊位营业如常。","pinyin":"Suīrán wàimiàn xiàzhe Dàxuě, dànshì zǎoshì de tānwèi yíngyè rúcháng.","vi":"Tuy bên ngoài tuyết rơi dày, nhưng các sạp ở chợ sáng vẫn buôn bán như thường lệ."}],"related":[{"hanzi":"照常","pinyin":"zhàocháng","vi":"như thường lệ"},{"hanzi":"正常","pinyin":"zhèngcháng","vi":"bình thường"},{"hanzi":"如故","pinyin":"rúgù","vi":"như cũ"},{"hanzi":"反常","pinyin":"fǎncháng","vi":"khác thường"}]},{"id":"如初","hanzi":"如初","pinyin":"rúchū","meaning_vi":"như thuở ban đầu","explanation":"如 (如) + 初 (ban đầu/sơ khai).","hsk_level":"7-9","tags":["pho-tu"],"image":"🌱","examples":[{"type":"basic","zh":"两人和好如初。","pinyin":"Liǎng rén héhǎo rúchū.","vi":"Hai người làm lành như xưa."},{"type":"simple","zh":"修复后的古画色彩鲜艳如初。","pinyin":"Xiūfù hòu de gǔ huà sècǎi xiānyàn rúchū.","vi":"Bức tranh cổ sau khi phục chế có màu sắc tươi tắn như ban đầu."},{"type":"compound","zh":"虽然分别了二十年，但是他们的友情依然如初。","pinyin":"Suīrán fēnbiéle èrshí nián, dànshì tāmen de yǒuqíng yīrán rúchū.","vi":"Tuy xa cách hai mươi năm, nhưng tình bạn của họ vẫn như thuở ban đầu."}],"related":[{"hanzi":"和好如初","pinyin":"héhǎorúchū","vi":"làm lành như xưa"},{"hanzi":"当初","pinyin":"dāngchū","vi":"lúc đầu"},{"hanzi":"依旧","pinyin":"yījiù","vi":"vẫn như cũ"},{"hanzi":"如故","pinyin":"rúgù","vi":"như cũ"}]},{"id":"如故","hanzi":"如故","pinyin":"rúgù","meaning_vi":"như cũ","explanation":"如 (như – giống như) + 故 (cố – cũ, như trước) → vẫn như cũ, không thay đổi. Hay gặp trong 一见如故 (mới gặp mà thân như bạn cũ).","hsk_level":"7-9","tags":["pho-tu"],"image":"🔄","examples":[{"type":"basic","zh":"他们一见如故。","pinyin":"Tāmen yí jiàn rúgù.","vi":"Họ vừa gặp đã thân như quen cũ."},{"type":"simple","zh":"十年后再回母校，教学楼的样子如故。","pinyin":"Shí nián hòu zài huí mǔxiào, jiàoxuélóu de yàngzi rúgù.","vi":"Mười năm sau trở lại trường cũ, dáng vẻ tòa nhà học vẫn như xưa."},{"type":"compound","zh":"尽管医生多次提醒，他却依然如故，每天抽一包烟。","pinyin":"Jǐnguǎn yīshēng duōcì tíxǐng, tā què yīrán rúgù, měitiān chōu yì bāo yān.","vi":"Dù bác sĩ đã nhiều lần nhắc nhở, anh ấy vẫn chứng nào tật nấy, mỗi ngày hút một bao thuốc."}],"related":[{"hanzi":"依旧","pinyin":"yījiù","vi":"vẫn như cũ"},{"hanzi":"一见如故","pinyin":"yíjiànrúgù","vi":"mới gặp như quen"},{"hanzi":"如常","pinyin":"rúcháng","vi":"như thường lệ"},{"hanzi":"照旧","pinyin":"zhàojiù","vi":"như cũ"}]},{"id":"如期","hanzi":"如期","pinyin":"rúqī","meaning_vi":"đúng kỳ hạn, đúng hẹn","explanation":"如 (như – theo đúng) + 期 (kỳ – thời hạn) → đúng thời hạn đã định. Thường đi với 完成, 举行, 交货.","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"会议如期举行。","pinyin":"Huìyì rúqī jǔxíng.","vi":"Cuộc họp diễn ra đúng hạn."},{"type":"simple","zh":"这座跨海大桥已经如期完工通车。","pinyin":"Zhè zuò kuà hǎi Dàqiáo yǐjīng rúqī wángōng tōngchē.","vi":"Cây cầu vượt biển này đã hoàn công và thông xe đúng tiến độ."},{"type":"compound","zh":"如果天气不好，飞机就不能如期起飞。","pinyin":"Rúguǒ tiānqì bù hǎo, fēijī jiù bù néng rúqī qǐfēi.","vi":"Nếu thời tiết xấu, máy bay sẽ không thể cất cánh đúng giờ."}],"related":[{"hanzi":"按期","pinyin":"ànqī","vi":"đúng hạn"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"đúng giờ"},{"hanzi":"延期","pinyin":"yánqī","vi":"hoãn lại"},{"hanzi":"到期","pinyin":"dàoqī","vi":"đến hạn"}]},{"id":"如实","hanzi":"如实","pinyin":"rúshí","meaning_vi":"đúng sự thật, trung thực","explanation":"如 (如) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["pho-tu"],"image":"✅","examples":[{"type":"basic","zh":"请如实回答。","pinyin":"Qǐng rúshí huídá.","vi":"Xin hãy trả lời đúng sự thật."},{"type":"simple","zh":"他向警察如实交代了事情的经过。","pinyin":"Tā xiàng jǐngchá rúshí jiāodàile shìqing de jīngguò.","vi":"Anh ấy khai thật với cảnh sát toàn bộ diễn biến sự việc."},{"type":"compound","zh":"只要你如实告诉医生病情，他就能对症下药。","pinyin":"Zhǐyào nǐ rúshí gàosu yīshēng bìngqíng, tā jiù néng duìzhèngxiàyào.","vi":"Chỉ cần bạn nói thật bệnh tình với bác sĩ, ông ấy sẽ kê đúng thuốc."}],"related":[{"hanzi":"据实","pinyin":"jùshí","vi":"theo sự thật"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"如实汇报","pinyin":"rúshíhuìbào","vi":"báo cáo trung thực"}],"traditional":"如實"},{"id":"如数","hanzi":"如数","pinyin":"rúshù","meaning_vi":"đủ số lượng","explanation":"如 (như – theo đúng) + 数 (số – số lượng) → đúng và đủ số lượng như đã định. Thường đi với 归还, 退还, 付清.","hsk_level":"7-9","tags":["pho-tu","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"钱已如数归还。","pinyin":"Qián yǐ rúshù guīhuán.","vi":"Tiền đã được trả lại đủ số."},{"type":"simple","zh":"商场把多收的五十元如数退给了顾客。","pinyin":"Shāngchǎng bǎ duō shōu de wǔshí yuán rúshù tuì gěile gùkè.","vi":"Trung tâm thương mại đã hoàn trả đủ năm mươi tệ thu thừa cho khách."},{"type":"compound","zh":"只要货物没有损坏，押金就会如数退还给您。","pinyin":"Zhǐyào huòwù méiyǒu sǔnhuài, yājīn jiù huì rúshù tuìhuán gěi nín.","vi":"Chỉ cần hàng không bị hư hỏng, tiền đặt cọc sẽ được hoàn trả đủ cho quý khách."}],"related":[{"hanzi":"全数","pinyin":"quánshù","vi":"toàn bộ số"},{"hanzi":"如数归还","pinyin":"rúshùguīhuán","vi":"trả lại đủ số"},{"hanzi":"足额","pinyin":"zú'é","vi":"đủ mức"},{"hanzi":"数目","pinyin":"shùmù","vi":"con số"}],"traditional":"如數"},{"id":"忍痛","hanzi":"忍痛","pinyin":"rěntòng","meaning_vi":"nén đau thương (đưa ra quyết định)","explanation":"忍 (nhẫn nại/chịu đựng) + 痛 (đau xót/quyết tâm).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😢","examples":[{"type":"basic","zh":"他忍痛放弃了比赛。","pinyin":"Tā rěntòng fàngqìle bǐsài.","vi":"Anh ấy đành nén đau từ bỏ cuộc thi."},{"type":"simple","zh":"为了给孩子治病，她忍痛卖掉了祖传的玉镯。","pinyin":"Wèile gěi háizi zhìbìng, tā rěntòng màidiàole zǔchuán de yù zhuó.","vi":"Để chữa bệnh cho con, cô ấy đành đau lòng bán chiếc vòng ngọc gia truyền."},{"type":"compound","zh":"因为篇幅有限，所以编辑只好忍痛删掉了这一章。","pinyin":"Yīnwèi piānfú yǒuxiàn, suǒyǐ biānjí zhǐhǎo rěntòng shāndiàole zhè yì zhāng.","vi":"Vì dung lượng có hạn nên biên tập viên đành đau lòng cắt bỏ chương này."}],"related":[{"hanzi":"忍受","pinyin":"rěnshòu","vi":"chịu đựng"},{"hanzi":"忍痛割爱","pinyin":"rěntònggē'ài","vi":"đành lòng từ bỏ thứ yêu"},{"hanzi":"忍耐","pinyin":"rěnnài","vi":"nhẫn nại"},{"hanzi":"心痛","pinyin":"xīntòng","vi":"đau lòng"}]},{"id":"染发","hanzi":"染发","pinyin":"rǎnfà","meaning_vi":"nhuộm tóc","explanation":"染 (nhuộm (tóc/vải)) + 发 (发).","hsk_level":"7-9","tags":["dong-tu","sinh-hoat"],"image":"💇","examples":[{"type":"basic","zh":"她去染发了。","pinyin":"Tā qù rǎnfà le.","vi":"Cô ấy đi nhuộm tóc rồi."},{"type":"simple","zh":"这家理发店染发要三百块钱。","pinyin":"Zhè jiā lǐfàdiàn rǎnfà yào sān bǎi kuài qián.","vi":"Tiệm cắt tóc này nhuộm tóc mất ba trăm tệ."},{"type":"compound","zh":"经常染发不但伤头发，而且可能刺激头皮。","pinyin":"Jīngcháng rǎnfà búdàn shāng tóufa, érqiě kěnéng cìjī tóupí.","vi":"Nhuộm tóc thường xuyên không chỉ hại tóc mà còn có thể kích ứng da đầu."}],"related":[{"hanzi":"理发","pinyin":"lǐfà","vi":"cắt tóc"},{"hanzi":"烫发","pinyin":"tàngfà","vi":"uốn tóc"},{"hanzi":"染料","pinyin":"rǎnliào","vi":"thuốc nhuộm"},{"hanzi":"发型","pinyin":"fàxíng","vi":"kiểu tóc"}],"traditional":"染髮"},{"id":"乳白","hanzi":"乳白","pinyin":"rǔbái","meaning_vi":"trắng sữa","explanation":"乳 (sữa/nuôi dưỡng) + 白 (màu trắng).","hsk_level":"7-9","tags":["tinh-tu","mau-sac"],"image":"🥛","examples":[{"type":"basic","zh":"墙是乳白色的。","pinyin":"Qiáng shì rǔbáisè de.","vi":"Bức tường màu trắng sữa."},{"type":"simple","zh":"清晨，山谷里升起一层乳白的薄雾。","pinyin":"Qīngchén, shāngǔ li shēngqǐ yīcéng rǔbái de bówù.","vi":"Sáng sớm, trong thung lũng bốc lên một lớp sương mỏng trắng sữa."},{"type":"compound","zh":"这种玉石刚开采时是乳白的，但是打磨后会变得透亮。","pinyin":"Zhè zhǒng yùshí gāng kāicǎi shí shì rǔbái de, dànshì dǎmó hòu huì biànde tòuliàng.","vi":"Loại ngọc này lúc mới khai thác có màu trắng sữa, nhưng sau khi mài giũa sẽ trở nên trong suốt."}],"related":[{"hanzi":"乳白色","pinyin":"rǔbáisè","vi":"màu trắng sữa"},{"hanzi":"洁白","pinyin":"jiébái","vi":"trắng tinh"},{"hanzi":"雪白","pinyin":"xuěbái","vi":"trắng như tuyết"},{"hanzi":"牛奶","pinyin":"niúnǎi","vi":"sữa bò"}]},{"id":"辱骂","hanzi":"辱骂","pinyin":"rǔmà","meaning_vi":"lăng mạ, chửi bới","explanation":"辱 (sỉ nhục) + 骂 (mắng).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"😠","examples":[{"type":"basic","zh":"不许辱骂他人。","pinyin":"Bùxǔ rǔmà tārén.","vi":"Không được lăng mạ người khác."},{"type":"simple","zh":"那名乘客因辱骂公交司机被警方拘留了。","pinyin":"Nà míng chéngkè yīn rǔmà gōngjiāo sījī bèi jǐngfāng jūliú le.","vi":"Hành khách đó bị cảnh sát tạm giữ vì lăng mạ tài xế xe buýt."},{"type":"compound","zh":"即使对方有错，你也不能在网上公开辱骂他。","pinyin":"Jíshǐ duìfāng yǒu cuò, nǐ yě bù néng zài wǎngshang gōngkāi rǔmà tā.","vi":"Dù đối phương có lỗi, bạn cũng không được công khai lăng mạ họ trên mạng."}],"related":[{"hanzi":"侮辱","pinyin":"wǔrǔ","vi":"sỉ nhục"},{"hanzi":"谩骂","pinyin":"mànmà","vi":"chửi rủa"},{"hanzi":"骂人","pinyin":"màrén","vi":"chửi người"},{"hanzi":"羞辱","pinyin":"xiūrǔ","vi":"làm nhục"}],"traditional":"辱罵"},{"id":"食疗","hanzi":"食疗","pinyin":"shíliáo","meaning_vi":"ẩm thực trị liệu (chữa bệnh bằng món ăn)","explanation":"食 (thực phẩm) + 疗 (điều trị).","hsk_level":"7-9","tags":["danh-tu","an-uong","suc-khoe"],"image":"🍲","examples":[{"type":"basic","zh":"奶奶相信食疗。","pinyin":"Nǎinai xiāngxìn shíliáo.","vi":"Bà nội tin vào ẩm thực trị liệu."},{"type":"simple","zh":"中医常推荐用山药粥作为调理脾胃的食疗方法。","pinyin":"Zhōngyī cháng tuījiàn yòng shānyào zhōu zuòwéi tiáolǐ píwèi de shíliáo fāngfǎ.","vi":"Đông y thường khuyên dùng cháo củ mài làm phương pháp ăn uống trị liệu điều hòa tỳ vị."},{"type":"compound","zh":"食疗虽然有一定效果，但是不能完全代替药物治疗。","pinyin":"Shíliáo suīrán yǒu yídìng xiàoguǒ, dànshì bù néng wánquán dàitì yàowù zhìliáo.","vi":"Ẩm thực trị liệu tuy có hiệu quả nhất định nhưng không thể hoàn toàn thay thế điều trị bằng thuốc."}],"related":[{"hanzi":"食补","pinyin":"shíbǔ","vi":"bồi bổ bằng ăn uống"},{"hanzi":"药膳","pinyin":"yàoshàn","vi":"món ăn bài thuốc"},{"hanzi":"养生","pinyin":"yǎngshēng","vi":"dưỡng sinh"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"}],"traditional":"食療"},{"id":"识破","hanzi":"识破","pinyin":"shípò","meaning_vi":"nhìn thấu, phát hiện ra âm mưu","explanation":"识 (kiến thức/nhận biết) + 破 (rách).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"他识破了骗局。","pinyin":"Tā shípòle piànjú.","vi":"Anh ấy đã nhìn thấu trò lừa đảo."},{"type":"simple","zh":"银行职员及时识破了那张假支票。","pinyin":"Yínháng zhíyuán jíshí shípòle nà zhāng jiǎ zhīpiào.","vi":"Nhân viên ngân hàng đã kịp thời phát hiện tấm séc giả đó."},{"type":"compound","zh":"他的谎话说得再圆，也被妈妈一眼识破了。","pinyin":"Tā de huǎnghuà shuō de zài yuán, yě bèi māma yìyǎn shípò le.","vi":"Lời nói dối của cậu ấy dù khéo đến mấy cũng bị mẹ nhìn thấu ngay."}],"related":[{"hanzi":"看穿","pinyin":"kànchuān","vi":"nhìn thấu"},{"hanzi":"揭穿","pinyin":"jiēchuān","vi":"vạch trần"},{"hanzi":"拆穿","pinyin":"chāichuān","vi":"vạch trần"},{"hanzi":"阴谋","pinyin":"yīnmóu","vi":"âm mưu"}],"traditional":"識破"},{"id":"识趣","hanzi":"识趣","pinyin":"shíqù","meaning_vi":"biết điều, tinh ý","explanation":"识 (kiến thức/nhận biết) + 趣 (hứng thú).","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"😉","examples":[{"type":"basic","zh":"他这个人很识趣。","pinyin":"Tā zhè ge rén hěn shíqù.","vi":"Anh ấy rất biết điều."},{"type":"simple","zh":"见老板脸色不好，小王识趣地闭上了嘴。","pinyin":"Jiàn lǎobǎn liǎnsè bù hǎo, xiǎo Wáng shíqù de bìshangle zuǐ.","vi":"Thấy sắc mặt sếp không tốt, Tiểu Vương biết điều mà im miệng."},{"type":"compound","zh":"他如果识趣的话，就不会在这个时候来借钱了。","pinyin":"Tā rúguǒ shíqù dehuà, jiù bú huì zài zhè ge shíhou lái jièqián le.","vi":"Nếu anh ta biết điều thì đã không đến vay tiền vào lúc này."}],"related":[{"hanzi":"知趣","pinyin":"zhīqù","vi":"biết điều"},{"hanzi":"识相","pinyin":"shíxiàng","vi":"biết điều"},{"hanzi":"懂事","pinyin":"dǒngshì","vi":"hiểu chuyện"},{"hanzi":"不识趣","pinyin":"bùshíqù","vi":"không biết điều"}],"traditional":"識趣"},{"id":"食宿","hanzi":"食宿","pinyin":"shísù","meaning_vi":"ăn ở","explanation":"食 (thực phẩm) + 宿 (宿).","hsk_level":"7-9","tags":["danh-tu","du-lich","sinh-hoat"],"image":"🏨","examples":[{"type":"basic","zh":"公司提供食宿。","pinyin":"Gōngsī tígōng shísù.","vi":"Công ty lo chỗ ăn ở."},{"type":"simple","zh":"参加夏令营的学生食宿全部免费。","pinyin":"Cānjiā xiàlìngyíng de xuéshēng shísù quánbù miǎnfèi.","vi":"Học sinh tham gia trại hè được miễn phí toàn bộ ăn ở."},{"type":"compound","zh":"虽然这份工作工资不高，但是包食宿，所以能存下不少钱。","pinyin":"Suīrán zhè fèn gōngzuò gōngzī bù gāo, dànshì bāo shísù, suǒyǐ néng cún xià bùshǎo qián.","vi":"Tuy công việc này lương không cao nhưng được bao ăn ở, nên có thể để dành được khá nhiều tiền."}],"related":[{"hanzi":"住宿","pinyin":"zhùsù","vi":"chỗ ở"},{"hanzi":"伙食","pinyin":"huǒshi","vi":"cơm nước"},{"hanzi":"包吃包住","pinyin":"bāochībāozhù","vi":"bao ăn ở"},{"hanzi":"吃住","pinyin":"chīzhù","vi":"ăn ở"}]},{"id":"税务","hanzi":"税务","pinyin":"shuìwù","meaning_vi":"nghiệp vụ thuế","explanation":"税 (thuế) + 务 (nhiệm vụ/thiết thực).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"🧾","examples":[{"type":"basic","zh":"他负责税务工作。","pinyin":"Tā fùzé shuìwù gōngzuò.","vi":"Anh ấy phụ trách công tác thuế."},{"type":"simple","zh":"公司每个月都要按时向税务局申报纳税。","pinyin":"Gōngsī měi gèyuè dōu yào ànshí xiàng Shuìwùjú shēnbào nàshuì.","vi":"Hằng tháng công ty đều phải khai báo nộp thuế đúng hạn với cục thuế."},{"type":"compound","zh":"如果你不熟悉税务问题，就最好请专业会计帮忙。","pinyin":"Rúguǒ nǐ bù shúxī shuìwù wèntí, jiù zuìhǎo qǐng zhuānyè kuàijì bāngmáng.","vi":"Nếu bạn không rành các vấn đề thuế thì tốt nhất nên nhờ kế toán chuyên nghiệp giúp."}],"related":[{"hanzi":"税务局","pinyin":"Shuìwùjú","vi":"cục thuế"},{"hanzi":"纳税","pinyin":"nàshuì","vi":"nộp thuế"},{"hanzi":"税收","pinyin":"shuìshōu","vi":"thu thuế"},{"hanzi":"报税","pinyin":"bàoshuì","vi":"khai thuế"}],"traditional":"稅務"},{"id":"睡意","hanzi":"睡意","pinyin":"shuìyì","meaning_vi":"cơn buồn ngủ","explanation":"睡 (睡) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","sinh-hoat"],"image":"😴","examples":[{"type":"basic","zh":"我毫无睡意。","pinyin":"Wǒ háowú shuìyì.","vi":"Tôi chẳng buồn ngủ chút nào."},{"type":"simple","zh":"午饭后，一阵浓浓的睡意向我袭来。","pinyin":"Wǔfàn hòu, yízhèn nóng nóng de shuì yìxiàng wǒ xí lái.","vi":"Sau bữa trưa, một cơn buồn ngủ nặng trĩu ập đến."},{"type":"compound","zh":"他一翻开厚厚的数学课本，睡意就上来了。","pinyin":"Tā yì fānkāi hòu hòu de shùxué kèběn, shuìyì jiù shànglái le.","vi":"Cậu ấy vừa mở sách toán là cơn buồn ngủ đã kéo đến."}],"related":[{"hanzi":"困意","pinyin":"kùnyì","vi":"cơn buồn ngủ"},{"hanzi":"困倦","pinyin":"kùnjuàn","vi":"mệt mỏi buồn ngủ"},{"hanzi":"打哈欠","pinyin":"dǎhāqian","vi":"ngáp"},{"hanzi":"睡意朦胧","pinyin":"shuìyìménglóng","vi":"ngái ngủ lơ mơ"}]},{"id":"硕士生","hanzi":"硕士生","pinyin":"shuòshìshēng","meaning_vi":"học viên cao học (thạc sĩ)","explanation":"硕 (to lớn/thạc sĩ) + 士 (nhân sĩ/chiến sĩ) + 生 (sinh tồn/sinh động).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","con-nguoi"],"image":"🎓","examples":[{"type":"basic","zh":"她是硕士生。","pinyin":"Tā shì shuòshìshēng.","vi":"Cô ấy là học viên cao học."},{"type":"simple","zh":"这个实验室里有八名硕士生和两名博士生。","pinyin":"Zhè ge shíyànshì li yǒu bā míng shuòshìshēng hé liǎng míng bóshìshēng.","vi":"Phòng thí nghiệm này có tám học viên thạc sĩ và hai nghiên cứu sinh tiến sĩ."},{"type":"compound","zh":"硕士生如果想按时毕业，就必须在第三年前发表论文。","pinyin":"Shuòshìshēng rúguǒ xiǎng ànshí bìyè, jiù bìxū zài dì sān niánqián fābiǎo lùnwén.","vi":"Học viên thạc sĩ nếu muốn tốt nghiệp đúng hạn thì phải công bố bài báo trước năm thứ ba."}],"related":[{"hanzi":"硕士","pinyin":"shuòshì","vi":"thạc sĩ"},{"hanzi":"研究生","pinyin":"yánjiūshēng","vi":"nghiên cứu sinh"},{"hanzi":"博士生","pinyin":"bóshìshēng","vi":"nghiên cứu sinh tiến sĩ"},{"hanzi":"本科生","pinyin":"běnkēshēng","vi":"sinh viên đại học"}],"traditional":"碩士生"},{"id":"刷屏","hanzi":"刷屏","pinyin":"shuāpíng","meaning_vi":"tràn ngập màn hình (tin tức hot xuất hiện liên tục)","explanation":"刷 (quét) + 屏 (màn hình).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"📱","examples":[{"type":"basic","zh":"这条新闻刷屏了。","pinyin":"Zhè tiáo xīnwén shuāpíng le.","vi":"Tin này phủ kín mạng xã hội."},{"type":"simple","zh":"婚礼当天，他们的结婚照刷屏了朋友圈。","pinyin":"Hūnlǐ dāngtiān, tāmen de jiéhūn zhào shuāpíngle péngyouquān.","vi":"Ngày cưới, ảnh cưới của họ tràn ngập trang cá nhân của bạn bè."},{"type":"compound","zh":"中国队一夺冠，祝贺的消息就在网上刷屏了。","pinyin":"Zhōngguó duì yì duóguàn, zhùhè de xiāoxi jiù zài wǎngshang shuāpíng le.","vi":"Đội Trung Quốc vừa giành chức vô địch, lời chúc mừng liền tràn ngập trên mạng."}],"related":[{"hanzi":"朋友圈","pinyin":"péngyouquān","vi":"vòng bạn bè WeChat"},{"hanzi":"热搜","pinyin":"rèsōu","vi":"tìm kiếm nóng"},{"hanzi":"走红","pinyin":"zǒuhóng","vi":"nổi tiếng"},{"hanzi":"转发","pinyin":"zhuǎnfā","vi":"chia sẻ lại"}]},{"id":"衰败","hanzi":"衰败","pinyin":"shuāibài","meaning_vi":"suy tàn, sa sút","explanation":"衰 (suy thoái/già yếu) + 败 (败).","hsk_level":"7-9","tags":["dong-tu"],"image":"🥀","examples":[{"type":"basic","zh":"家族逐渐衰败。","pinyin":"Jiāzú zhújiàn shuāibài.","vi":"Gia tộc dần suy tàn."},{"type":"simple","zh":"这条曾经繁华的商业街如今已经衰败了。","pinyin":"Zhè tiáo céngjīng fánhuá de shāngyè jiē rújīn yǐjīng shuāibài le.","vi":"Con phố thương mại từng sầm uất này nay đã suy tàn."},{"type":"compound","zh":"一个王朝如果官员腐败，就迟早会走向衰败。","pinyin":"Yí gè wángcháo rúguǒ guānyuán fǔbài, jiù chízǎo huì zǒuxiàng shuāibài.","vi":"Một vương triều nếu quan lại tham nhũng thì sớm muộn cũng đi đến suy tàn."}],"related":[{"hanzi":"衰落","pinyin":"shuāiluò","vi":"suy tàn"},{"hanzi":"衰退","pinyin":"shuāituì","vi":"suy thoái"},{"hanzi":"兴盛","pinyin":"xīngshèng","vi":"hưng thịnh"},{"hanzi":"没落","pinyin":"mòluò","vi":"sa sút"}],"traditional":"衰敗"},{"id":"衰弱","hanzi":"衰弱","pinyin":"shuāiruò","meaning_vi":"suy nhược, yếu ớt","explanation":"衰 (suy thoái/già yếu) + 弱 (yếu).","hsk_level":"7-9","tags":["tinh-tu","suc-khoe"],"image":"🤒","examples":[{"type":"basic","zh":"他身体很衰弱。","pinyin":"Tā shēntǐ hěn shuāiruò.","vi":"Cơ thể ông ấy rất suy nhược."},{"type":"simple","zh":"长期失眠让她的神经变得十分衰弱。","pinyin":"Chángqī shīmián ràng tā de shénjīng biànde shífēn shuāiruò.","vi":"Mất ngủ kéo dài khiến thần kinh cô ấy trở nên rất suy nhược."},{"type":"compound","zh":"老人手术后虽然很衰弱，但是精神还不错。","pinyin":"Lǎo rénshǒu shùhòu suīrán hěn shuāiruò, dànshì jīngshen hái búcuò.","vi":"Ông cụ sau phẫu thuật tuy rất yếu, nhưng tinh thần vẫn khá tốt."}],"related":[{"hanzi":"虚弱","pinyin":"xūruò","vi":"yếu ớt"},{"hanzi":"衰老","pinyin":"shuāilǎo","vi":"già yếu"},{"hanzi":"强壮","pinyin":"qiángzhuàng","vi":"cường tráng"},{"hanzi":"神经衰弱","pinyin":"shénjīngshuāiruò","vi":"suy nhược thần kinh"}]},{"id":"双边","hanzi":"双边","pinyin":"shuāngbiān","meaning_vi":"song phương","explanation":"双 (đôi bên/song song) + 边 (biên giới/bên rìa).","hsk_level":"7-9","tags":["tinh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"两国签了双边协议。","pinyin":"Liǎngguó qiānle shuāngbiān xiéyì.","vi":"Hai nước đã ký hiệp định song phương."},{"type":"simple","zh":"今年两国的双边贸易额增长了百分之十五。","pinyin":"Jīnnián liǎngguó de shuāngbiān màoyì'é zēngzhǎngle bǎifēnzhī shíwǔ.","vi":"Năm nay kim ngạch thương mại song phương giữa hai nước tăng 15%."},{"type":"compound","zh":"如果双边会谈进展顺利，两国领导人就会在年底互访。","pinyin":"Rúguǒ shuāngbiān huìtán jìnzhǎn shùnlì, liǎngguó lǐngdǎorén jiù huì zài niándǐ hùfǎng.","vi":"Nếu hội đàm song phương tiến triển thuận lợi, lãnh đạo hai nước sẽ thăm lẫn nhau vào cuối năm."}],"related":[{"hanzi":"多边","pinyin":"duōbiān","vi":"đa phương"},{"hanzi":"双方","pinyin":"shuāngfāng","vi":"hai bên"},{"hanzi":"双边关系","pinyin":"shuāngbiānguānxì","vi":"quan hệ song phương"},{"hanzi":"单边","pinyin":"dānbiān","vi":"đơn phương"}],"traditional":"雙邊"},{"id":"双边关系","hanzi":"双边关系","pinyin":"shuāngbiānguānxì","meaning_vi":"quan hệ song phương","explanation":"双边 (hai bên) + 关系.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"双边关系稳定。","pinyin":"Shuāngbiānguānxì wěndìng.","vi":"Quan hệ song phương ổn định."},{"type":"simple","zh":"两国外长就进一步发展双边关系交换了意见。","pinyin":"Liǎngguó wàizhǎng jiù jìnyíbù fāzhǎn shuāngbiānguānxì jiāohuànle yìjiàn.","vi":"Ngoại trưởng hai nước đã trao đổi ý kiến về việc phát triển hơn nữa quan hệ song phương."},{"type":"compound","zh":"虽然两国曾有过摩擦，但是双边关系近年来明显改善。","pinyin":"Suīrán liǎngguó céng yǒuguo mócā, dànshì shuāngbiānguānxì jìnniánlái míngxiǎn gǎishàn.","vi":"Tuy hai nước từng có va chạm, nhưng quan hệ song phương những năm gần đây đã cải thiện rõ rệt."}],"related":[{"hanzi":"外交关系","pinyin":"wàijiāoguānxì","vi":"quan hệ ngoại giao"},{"hanzi":"多边","pinyin":"duōbiān","vi":"đa phương"},{"hanzi":"双边贸易","pinyin":"shuāngbiānmàoyì","vi":"thương mại song phương"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"}],"traditional":"雙邊關係"},{"id":"双赢","hanzi":"双赢","pinyin":"shuāngyíng","meaning_vi":"đôi bên cùng thắng (win-win)","explanation":"双 (đôi bên/song song) + 赢 (thắng).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🏆","examples":[{"type":"basic","zh":"这是双赢的合作。","pinyin":"Zhè shì shuāngyíng de hézuò.","vi":"Đây là sự hợp tác đôi bên cùng có lợi."},{"type":"simple","zh":"农民和超市直接合作实现了双赢。","pinyin":"Nóngmín hé chāoshì zhíjiē hézuò shíxiànle shuāngyíng.","vi":"Nông dân và siêu thị hợp tác trực tiếp, đôi bên cùng có lợi."},{"type":"compound","zh":"只要双方都愿意让一步，就能找到双赢的方案。","pinyin":"Zhǐyào shuāngfāng dōu yuànyì ràng yí bù, jiù néng zhǎodào shuāngyíng de fāng'àn.","vi":"Chỉ cần hai bên đều chịu nhường một bước là có thể tìm ra phương án đôi bên cùng thắng."}],"related":[{"hanzi":"共赢","pinyin":"gòngyíng","vi":"cùng thắng"},{"hanzi":"互利","pinyin":"hùlì","vi":"cùng có lợi"},{"hanzi":"合作","pinyin":"hézuò","vi":"hợp tác"},{"hanzi":"两败俱伤","pinyin":"liǎngbàijùshāng","vi":"cả hai cùng thiệt"}],"traditional":"雙贏"},{"id":"双重否定","hanzi":"双重否定","pinyin":"shuāngchóngfǒudìng","meaning_vi":"phủ định hai lần (nhấn mạnh khẳng định)","explanation":"双 (đôi bên/song song) + 重 (nặng) + 否 (否) + 定 (定).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"❗","examples":[{"type":"basic","zh":"这是双重否定句。","pinyin":"Zhè shì shuāngchóng fǒudìngjù.","vi":"Đây là câu phủ định kép."},{"type":"simple","zh":"老师在课上讲解了汉语的双重否定用法。","pinyin":"Lǎoshī zài kè shang jiǎngjiěle Hànyǔ de shuāngchóngfǒudìng yòngfǎ.","vi":"Thầy giáo giảng giải cách dùng phủ định kép trong tiếng Hán trên lớp."},{"type":"compound","zh":"双重否定虽然表示肯定，但是语气比一般肯定句更强。","pinyin":"Shuāngchóngfǒudìng suīrán biǎoshì kěndìng, dànshì yǔqì bǐ yìbān kěndìngjù gèng qiáng.","vi":"Phủ định kép tuy biểu thị khẳng định, nhưng ngữ khí mạnh hơn câu khẳng định thông thường."}],"related":[{"hanzi":"否定","pinyin":"fǒudìng","vi":"phủ định"},{"hanzi":"肯定","pinyin":"kěndìng","vi":"khẳng định"},{"hanzi":"反问句","pinyin":"fǎnwènjù","vi":"câu hỏi tu từ"},{"hanzi":"语法","pinyin":"yǔfǎ","vi":"ngữ pháp"}],"traditional":"雙重否定"},{"id":"说服力","hanzi":"说服力","pinyin":"shuōfúlì","meaning_vi":"sức thuyết phục","explanation":"说 (nói) + 服 (服) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"这个理由很有说服力。","pinyin":"Zhè ge lǐyóu hěn yǒu shuōfúlì.","vi":"Lý do này rất có sức thuyết phục."},{"type":"simple","zh":"他用一组详细的数据增强了报告的说服力。","pinyin":"Tāyòng yì zǔ xiángxì de shùjù zēngqiángle bàogào de shuōfúlì.","vi":"Anh ấy dùng một loạt số liệu chi tiết để tăng sức thuyết phục cho bản báo cáo."},{"type":"compound","zh":"如果你自己都做不到，你的话就没有说服力。","pinyin":"Rúguǒ nǐ zìjǐ dōu zuòbúdào, nǐ dehuà jiù méiyǒu shuōfúlì.","vi":"Nếu chính bạn cũng không làm được thì lời bạn nói chẳng có sức thuyết phục."}],"related":[{"hanzi":"说服","pinyin":"shuōfú","vi":"thuyết phục"},{"hanzi":"有说服力","pinyin":"yǒushuōfúlì","vi":"có sức thuyết phục"},{"hanzi":"论据","pinyin":"lùnjù","vi":"luận cứ"},{"hanzi":"可信度","pinyin":"kěxìndù","vi":"độ tin cậy"}],"traditional":"說服力"},{"id":"说教","hanzi":"说教","pinyin":"shuōjiào","meaning_vi":"lên lớp giáo huấn","explanation":"说 (nói) + 教 (dạy).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🙄","examples":[{"type":"basic","zh":"我讨厌他说教。","pinyin":"Wǒ tǎoyàn tā shuōjiào.","vi":"Tôi ghét anh ta lên lớp dạy đời."},{"type":"simple","zh":"年轻人往往不喜欢长辈没完没了的说教。","pinyin":"Niánqīngrén wǎngwǎng bù xǐhuan zhǎngbèi méi wán méiliǎo de shuōjiào.","vi":"Người trẻ thường không thích những bài giáo huấn bất tận của bề trên."},{"type":"compound","zh":"与其对孩子空洞地说教，不如自己做个好榜样。","pinyin":"Yǔqí duì háizi kōngdòng de shuōjiào, bùrú zìjǐ zuò gè hǎo bǎngyàng.","vi":"Thay vì lên lớp suông với con, chi bằng tự mình làm tấm gương tốt."}],"related":[{"hanzi":"教训","pinyin":"jiàoxun","vi":"dạy dỗ, răn dạy"},{"hanzi":"唠叨","pinyin":"láodao","vi":"cằn nhằn"},{"hanzi":"讲道理","pinyin":"jiǎngdàolǐ","vi":"giảng giải lý lẽ"},{"hanzi":"训话","pinyin":"xùnhuà","vi":"lên lớp huấn thị"}],"traditional":"說教"},{"id":"爽朗","hanzi":"爽朗","pinyin":"shuǎnglǎng","meaning_vi":"cởi mở hào sảng (tiếng cười/tính cách)","explanation":"爽 (sảng khoái/thẳng thắn) + 朗 (sáng sủa/cởi mở).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😆","examples":[{"type":"basic","zh":"他笑得很爽朗。","pinyin":"Tā xiào de hěn shuǎnglǎng.","vi":"Anh ấy cười rất sảng khoái."},{"type":"simple","zh":"门外传来了张大爷爽朗的笑声。","pinyin":"Ménwài chuánláile Zhāng dàye shuǎnglǎng de xiàoshēng.","vi":"Ngoài cửa vọng vào tiếng cười sảng khoái của ông Trương."},{"type":"compound","zh":"她不但性格爽朗，而且做事干脆利落。","pinyin":"Tā búdàn xìnggé shuǎnglǎng, érqiě zuòshì gàncuì lìluò.","vi":"Cô ấy không chỉ tính cách cởi mở hào sảng mà còn làm việc dứt khoát gọn gàng."}],"related":[{"hanzi":"开朗","pinyin":"kāilǎng","vi":"cởi mở vui vẻ"},{"hanzi":"豪爽","pinyin":"háoshuǎng","vi":"hào sảng"},{"hanzi":"爽快","pinyin":"shuǎngkuai","vi":"sảng khoái"},{"hanzi":"笑声","pinyin":"xiàoshēng","vi":"tiếng cười"}]},{"id":"水产","hanzi":"水产","pinyin":"shuǐchǎn","meaning_vi":"thủy sản","explanation":"水 (nước) + 产 (sản xuất/tài sản).","hsk_level":"7-9","tags":["danh-tu","an-uong","thien-nhien"],"image":"🦐","examples":[{"type":"basic","zh":"这里水产丰富。","pinyin":"Zhèlǐ shuǐchǎn fēngfù.","vi":"Nơi đây thủy sản phong phú."},{"type":"simple","zh":"妈妈每周六去水产市场买新鲜的鱼虾。","pinyin":"Māma měi Zhōuliù qù shuǐchǎn shìchǎng mǎi xīnxiān de yúxiā.","vi":"Thứ Bảy nào mẹ cũng đi chợ thủy sản mua tôm cá tươi."},{"type":"compound","zh":"因为这个县靠近大海，所以水产养殖业非常发达。","pinyin":"Yīnwèi zhè ge xiàn kàojìn dàhǎi, suǒyǐ shuǐchǎn yǎngzhíyè fēicháng fādá.","vi":"Vì huyện này giáp biển nên ngành nuôi trồng thủy sản rất phát triển."}],"related":[{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"hải sản"},{"hanzi":"水产品","pinyin":"shuǐchǎnpǐn","vi":"sản phẩm thủy sản"},{"hanzi":"渔业","pinyin":"yúyè","vi":"ngư nghiệp"},{"hanzi":"养殖","pinyin":"yǎngzhí","vi":"nuôi trồng"}],"traditional":"水產"},{"id":"水电","hanzi":"水电","pinyin":"shuǐdiàn","meaning_vi":"điện nước; thủy điện","explanation":"水 (thủy – nước) + 电 (điện) → thủy điện (phát điện bằng sức nước), hoặc điện và nước dùng trong sinh hoạt. Ví dụ: 水电站 (nhà máy thủy điện).","hsk_level":"7-9","tags":["danh-tu","nha-cua","thien-nhien"],"image":"💡","examples":[{"type":"basic","zh":"房租包水电。","pinyin":"Fángzū bāo shuǐdiàn.","vi":"Tiền thuê nhà đã gồm điện nước."},{"type":"simple","zh":"三峡是世界上规模最大的水电站之一。","pinyin":"Sānxiá shì shìjiè shang guīmó zuì dà de shuǐdiànzhàn zhīyī.","vi":"Tam Hiệp là một trong những nhà máy thủy điện lớn nhất thế giới."},{"type":"compound","zh":"新房子虽然装修好了，但是水电还没接通。","pinyin":"Xīnfáng zi suīrán zhuāngxiū hǎo le, dànshì shuǐdiàn hái méi jiētōng.","vi":"Nhà mới tuy sửa xong rồi, nhưng điện nước vẫn chưa thông."}],"related":[{"hanzi":"水电站","pinyin":"shuǐdiànzhàn","vi":"nhà máy thủy điện"},{"hanzi":"水电费","pinyin":"shuǐdiànfèi","vi":"tiền điện nước"},{"hanzi":"水力发电","pinyin":"shuǐlìfādiàn","vi":"thủy điện"},{"hanzi":"火电","pinyin":"huǒdiàn","vi":"nhiệt điện"}],"traditional":"水電"},{"id":"水电费","hanzi":"水电费","pinyin":"shuǐdiànfèi","meaning_vi":"tiền điện nước","explanation":"水电 (thủy điện – điện nước) + 费 (phí – tiền phí) → tiền điện nước phải trả hằng tháng. Thường đi với 交, 缴纳.","hsk_level":"7-9","tags":["danh-tu","nha-cua","tien-te"],"image":"💡","examples":[{"type":"basic","zh":"该交水电费了。","pinyin":"Gāi jiāo shuǐdiànfèi le.","vi":"Đến lúc đóng tiền điện nước rồi."},{"type":"simple","zh":"现在可以直接用手机缴纳水电费。","pinyin":"Xiànzài kěyǐ zhíjiē yòng shǒujī jiǎonà shuǐdiànfèi.","vi":"Giờ có thể nộp tiền điện nước trực tiếp bằng điện thoại."},{"type":"compound","zh":"夏天一开空调，家里的水电费就翻了一倍。","pinyin":"Xiàtiān yì kāi kōngtiáo, jiāli de shuǐdiànfèi jiù fānle yí bèi.","vi":"Mùa hè hễ bật điều hòa là tiền điện nước nhà tôi tăng gấp đôi."}],"related":[{"hanzi":"电费","pinyin":"diànfèi","vi":"tiền điện"},{"hanzi":"水费","pinyin":"shuǐfèi","vi":"tiền nước"},{"hanzi":"房租","pinyin":"fángzū","vi":"tiền thuê nhà"},{"hanzi":"物业费","pinyin":"wùyèfèi","vi":"phí quản lý"}],"traditional":"水電費"},{"id":"水库","hanzi":"水库","pinyin":"shuǐkù","meaning_vi":"hồ chứa nước","explanation":"水 (nước) + 库 (kho chứa).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌊","examples":[{"type":"basic","zh":"水库的水满了。","pinyin":"Shuǐkù de shuǐ mǎn le.","vi":"Hồ chứa nước đã đầy."},{"type":"simple","zh":"这座水库为全市提供了一半的饮用水。","pinyin":"Zhè zuò shuǐkù wèi quánshì tígōngle yíbàn de yǐnyòngshuǐ.","vi":"Hồ chứa này cung cấp một nửa lượng nước uống cho toàn thành phố."},{"type":"compound","zh":"如果连续下暴雨，水库就要开闸泄洪。","pinyin":"Rúguǒ liánxù xià bàoyǔ, shuǐkù jiùyào kāi zhá xièhóng.","vi":"Nếu mưa lớn liên tục, hồ chứa sẽ phải mở cửa xả lũ."}],"related":[{"hanzi":"大坝","pinyin":"dàbà","vi":"đập lớn"},{"hanzi":"蓄水","pinyin":"xùshuǐ","vi":"trữ nước"},{"hanzi":"水利","pinyin":"shuǐlì","vi":"thủy lợi"},{"hanzi":"水电站","pinyin":"shuǐdiànzhàn","vi":"nhà máy thủy điện"}],"traditional":"水庫"},{"id":"水疗","hanzi":"水疗","pinyin":"shuǐliáo","meaning_vi":"thủy liệu pháp (spa)","explanation":"水 (nước) + 疗 (điều trị).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","giai-tri"],"image":"🛁","examples":[{"type":"basic","zh":"她喜欢做水疗。","pinyin":"Tā xǐhuan zuò shuǐliáo.","vi":"Cô ấy thích đi spa thủy liệu."},{"type":"simple","zh":"这家度假酒店提供温泉和水疗服务。","pinyin":"Zhè jiā dùjià jiǔdiàn tígōng wēnquán hé shuǐliáo fúwù.","vi":"Khách sạn nghỉ dưỡng này cung cấp dịch vụ suối nước nóng và spa thủy liệu."},{"type":"compound","zh":"运动员训练一结束，就去做水疗放松肌肉。","pinyin":"Yùndòngyuán xùnliàn yì jiéshù, jiù qù zuò shuǐliáo fàngsōng jīròu.","vi":"Vận động viên vừa tập xong liền đi trị liệu bằng nước để thả lỏng cơ bắp."}],"related":[{"hanzi":"按摩","pinyin":"ànmó","vi":"xoa bóp"},{"hanzi":"温泉","pinyin":"wēnquán","vi":"suối nước nóng"},{"hanzi":"理疗","pinyin":"lǐliáo","vi":"vật lý trị liệu"},{"hanzi":"美容","pinyin":"měiróng","vi":"làm đẹp"}],"traditional":"水療"},{"id":"水力发电","hanzi":"水力发电","pinyin":"shuǐlìfādiàn","meaning_vi":"thủy điện","explanation":"水 (nước) + 力 (sức mạnh/nỗ lực) + 发 (发) + 电 (电).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","cong-viec"],"image":"🌊","examples":[{"type":"basic","zh":"这里靠水力发电。","pinyin":"Zhèlǐ kào shuǐlìfādiàn.","vi":"Nơi đây dựa vào thủy điện."},{"type":"simple","zh":"落差大的山区河流非常适合水力发电。","pinyin":"Luòchā dà de shānqū héliú fēicháng shìhé shuǐlìfādiàn.","vi":"Sông suối miền núi có độ chênh lớn rất thích hợp để làm thủy điện."},{"type":"compound","zh":"水力发电虽然清洁，但是修建大坝会影响河流生态。","pinyin":"Shuǐlìfādiàn suīrán qīngjié, dànshì xiūjiàn dàbà huì yǐngxiǎng héliú shēngtài.","vi":"Thủy điện tuy sạch, nhưng xây đập sẽ ảnh hưởng đến sinh thái sông."}],"related":[{"hanzi":"水电站","pinyin":"shuǐdiànzhàn","vi":"nhà máy thủy điện"},{"hanzi":"火力发电","pinyin":"huǒlìfādiàn","vi":"nhiệt điện"},{"hanzi":"风力发电","pinyin":"fēnglìfādiàn","vi":"điện gió"},{"hanzi":"太阳能","pinyin":"tàiyángnéng","vi":"năng lượng mặt trời"}],"traditional":"水力發電"},{"id":"水墨","hanzi":"水墨","pinyin":"shuǐmò","meaning_vi":"mực tàu (vẽ tranh thủy mặc)","explanation":"水 (nước) + 墨 (mực viết).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🖌️","examples":[{"type":"basic","zh":"宣纸上水墨淋漓。","pinyin":"Xuānzhǐ shang shuǐmò línlí.","vi":"Mực tàu loang đẫm trên giấy Tuyên."},{"type":"simple","zh":"这本书的插图采用了淡雅的水墨风格。","pinyin":"Zhè běn shū de chātú cǎiyòngle dànyǎ de shuǐmò fēnggé.","vi":"Tranh minh họa của cuốn sách này dùng phong cách thủy mặc thanh nhã."},{"type":"compound","zh":"水墨虽然只有黑白两色，但是能表现出丰富的层次。","pinyin":"Shuǐmò suīrán zhǐyǒu hēibái liǎng sè, dànshì néng biǎoxiàn chū fēngfù de céngcì.","vi":"Mực tàu tuy chỉ có hai màu đen trắng, nhưng thể hiện được nhiều tầng lớp phong phú."}],"related":[{"hanzi":"水墨画","pinyin":"shuǐmòhuà","vi":"tranh thủy mặc"},{"hanzi":"笔墨","pinyin":"bǐmò","vi":"bút mực"},{"hanzi":"国画","pinyin":"guóhuà","vi":"quốc họa"},{"hanzi":"毛笔","pinyin":"máobǐ","vi":"bút lông"}]},{"id":"水墨画","hanzi":"水墨画","pinyin":"shuǐmòhuà","meaning_vi":"tranh thủy mặc","explanation":"水 (nước) + 墨 (mực) + 画 (tranh).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"我在学水墨画。","pinyin":"Wǒ zài xué shuǐmòhuà.","vi":"Tôi đang học vẽ tranh thủy mặc."},{"type":"simple","zh":"客厅墙上挂着一幅齐白石的水墨画。","pinyin":"Kètīng qiáng shang guàzhe yì fú Qíbáishí de shuǐmòhuà.","vi":"Trên tường phòng khách treo một bức tranh thủy mặc của Tề Bạch Thạch."},{"type":"compound","zh":"画水墨画讲究意境，所以留白和笔墨一样重要。","pinyin":"Huà shuǐmòhuà jiǎngjiu yìjìng, suǒyǐ liúbái hé bǐmò yíyàng zhòngyào.","vi":"Vẽ tranh thủy mặc chú trọng ý cảnh, nên khoảng trống cũng quan trọng như nét mực."}],"related":[{"hanzi":"国画","pinyin":"guóhuà","vi":"quốc họa"},{"hanzi":"山水画","pinyin":"shānshuǐhuà","vi":"tranh sơn thủy"},{"hanzi":"油画","pinyin":"yóuhuà","vi":"tranh sơn dầu"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"}],"traditional":"水墨畫"},{"id":"水土流失","hanzi":"水土流失","pinyin":"shuǐtǔliúshī","meaning_vi":"xói mòn đất, rửa trôi đất đai","explanation":"水 (nước) + 土 (đất đai/bản địa) + 流 (lưu truyền/dòng chảy) + 失 (mất đi/sai sót).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"植树能防止水土流失。","pinyin":"Zhíshù néng fángzhǐ shuǐtǔliúshī.","vi":"Trồng cây có thể ngăn xói mòn đất."},{"type":"simple","zh":"黄土高原的水土流失问题由来已久。","pinyin":"Huángtǔgāoyuán de shuǐtǔliúshī wèntí yóulái yǐjiǔ.","vi":"Vấn đề xói mòn đất ở cao nguyên Hoàng Thổ đã có từ lâu."},{"type":"compound","zh":"山上的树一旦被砍光，雨季就容易发生水土流失。","pinyin":"Shān shang de shù yídàn bèi kǎn guāng, yǔjì jiù róngyì fāshēng shuǐtǔliúshī.","vi":"Cây trên núi một khi bị chặt trụi, mùa mưa sẽ dễ xảy ra xói mòn đất."}],"related":[{"hanzi":"水土保持","pinyin":"shuǐtǔbǎochí","vi":"giữ đất giữ nước"},{"hanzi":"荒漠化","pinyin":"huāngmòhuà","vi":"sa mạc hóa"},{"hanzi":"植树造林","pinyin":"zhíshùzàolín","vi":"trồng cây gây rừng"},{"hanzi":"生态","pinyin":"shēngtài","vi":"sinh thái"}]},{"id":"水准","hanzi":"水准","pinyin":"shuǐzhǔn","meaning_vi":"trình độ, tiêu chuẩn","explanation":"水 (nước) + 准 (chuẩn mực/chính xác).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📏","examples":[{"type":"basic","zh":"他的水准很高。","pinyin":"Tā de shuǐzhǔn hěn gāo.","vi":"Trình độ của anh ấy rất cao."},{"type":"simple","zh":"这场演出达到了国际一流水准。","pinyin":"Zhè chǎng yǎnchū dádàole Guójì yìliú shuǐzhǔn.","vi":"Buổi biểu diễn này đạt tiêu chuẩn hàng đầu quốc tế."},{"type":"compound","zh":"虽然这家小店很不起眼，但是厨师的水准一点也不差。","pinyin":"Suīrán zhè jiā xiǎodiàn hěn bùqǐyǎn, dànshì chúshī de shuǐzhǔn yìdiǎn yě búchà.","vi":"Tuy quán nhỏ này chẳng mấy bắt mắt, nhưng tay nghề đầu bếp không hề kém."}],"related":[{"hanzi":"水平","pinyin":"shuǐpíng","vi":"trình độ"},{"hanzi":"标准","pinyin":"biāozhǔn","vi":"tiêu chuẩn"},{"hanzi":"档次","pinyin":"dàngcì","vi":"đẳng cấp"},{"hanzi":"生活水准","pinyin":"shēnghuóshuǐzhǔn","vi":"mức sống"}],"traditional":"水準"},{"id":"善举","hanzi":"善举","pinyin":"shànjǔ","meaning_vi":"hành động thiện nguyện cao đẹp","explanation":"善 (lương thiện/giỏi về) + 举 (cử chỉ/nêu ra).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"💖","examples":[{"type":"basic","zh":"这是一个善举。","pinyin":"Zhè shì yí gè shànjǔ.","vi":"Đây là một việc làm thiện nguyện."},{"type":"simple","zh":"他匿名资助贫困学生的善举感动了全校。","pinyin":"Tā nìmíng zīzhù pínkùn xuéshēng de shànjǔ gǎndòngle quán xiào.","vi":"Việc ông ấy ẩn danh tài trợ học sinh nghèo đã làm cảm động cả trường."},{"type":"compound","zh":"这位老人的善举一经报道，就有很多人主动加入了。","pinyin":"Zhè wèi lǎorén de shànjǔ yìjīng bàodào, jiù yǒu hěn duō rén zhǔdòng jiārù le.","vi":"Việc thiện của ông cụ vừa được đưa tin, đã có rất nhiều người chủ động tham gia."}],"related":[{"hanzi":"善行","pinyin":"shànxíng","vi":"việc thiện"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"义举","pinyin":"yìjǔ","vi":"nghĩa cử"},{"hanzi":"善款","pinyin":"shànkuǎn","vi":"tiền từ thiện"}],"traditional":"善舉"},{"id":"善款","hanzi":"善款","pinyin":"shànkuǎn","meaning_vi":"tiền quyên góp từ thiện","explanation":"善 (lương thiện/giỏi về) + 款 (tiền/kiểu dáng/tiếp đãi).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"💰","examples":[{"type":"basic","zh":"善款已经到账。","pinyin":"Shànkuǎn yǐjīng dàozhàng.","vi":"Tiền từ thiện đã về tài khoản."},{"type":"simple","zh":"慈善晚会共筹得善款八百万元。","pinyin":"Císhàn wǎnhuì gòng chóu dé shànkuǎn bā bǎiwàn yuán.","vi":"Đêm gala từ thiện quyên được tổng cộng tám triệu tệ."},{"type":"compound","zh":"只要善款的去向公开透明，大家就愿意继续捐款。","pinyin":"Zhǐyào shànkuǎn de qùxiàng gōngkāi tòumíng, dàjiā jiù yuànyì jìxù juānkuǎn.","vi":"Chỉ cần đường đi của tiền từ thiện công khai minh bạch, mọi người sẽ sẵn lòng tiếp tục quyên góp."}],"related":[{"hanzi":"捐款","pinyin":"juānkuǎn","vi":"quyên góp tiền"},{"hanzi":"慈善","pinyin":"císhàn","vi":"từ thiện"},{"hanzi":"募捐","pinyin":"mùjuān","vi":"quyên góp"},{"hanzi":"善举","pinyin":"shànjǔ","vi":"việc làm thiện"}]},{"id":"上榜","hanzi":"上榜","pinyin":"shàngbǎng","meaning_vi":"lọt vào bảng xếp hạng","explanation":"上 (trên) + 榜 (bảng vàng/tấm gương).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🏆","examples":[{"type":"basic","zh":"他的书上榜了。","pinyin":"Tā de shū shàngbǎng le.","vi":"Cuốn sách của anh ấy lọt vào bảng xếp hạng."},{"type":"simple","zh":"这首新歌发布第二天就上榜了。","pinyin":"Zhè shǒu xīn gē fābù dì'èrtiān jiù shàngbǎng le.","vi":"Bài hát mới này ngay ngày thứ hai phát hành đã lọt bảng xếp hạng."},{"type":"compound","zh":"虽然这家餐厅没有上榜，但是在本地人中口碑很好。","pinyin":"Suīrán zhè jiā cāntīng méiyǒu shàngbǎng, dànshì zài běndì rénzhōng kǒubēi hěn hǎo.","vi":"Tuy nhà hàng này không lọt bảng xếp hạng, nhưng rất được người địa phương khen ngợi."}],"related":[{"hanzi":"排行榜","pinyin":"páihángbǎng","vi":"bảng xếp hạng"},{"hanzi":"榜单","pinyin":"bǎngdān","vi":"danh sách xếp hạng"},{"hanzi":"落榜","pinyin":"luòbǎng","vi":"thi trượt"},{"hanzi":"榜首","pinyin":"bǎngshǒu","vi":"đứng đầu bảng"}]},{"id":"上空","hanzi":"上空","pinyin":"shàngkōng","meaning_vi":"bầu trời phía trên","explanation":"上 (trên) + 空 (trống rỗng/không gian).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"☁️","examples":[{"type":"basic","zh":"村子上空飘着炊烟。","pinyin":"Cūnzi shàngkōng piāozhe chuīyān.","vi":"Khói bếp lượn lờ trên bầu trời ngôi làng."},{"type":"simple","zh":"一架直升机在广场上空盘旋了很久。","pinyin":"Yí jià zhíshēngjī zài guǎngchǎng shàngkōng pánxuánle hěn jiǔ.","vi":"Một chiếc trực thăng lượn vòng rất lâu trên bầu trời quảng trường."},{"type":"compound","zh":"午夜钟声一响，江面上空就绽放出五彩的烟花。","pinyin":"Wǔyè zhōngshēng yì xiǎng, jiāngmiàn shàngkōng jiù zhànfàng chū wǔcǎi de yānhuā.","vi":"Chuông nửa đêm vừa điểm, trên mặt sông liền rực rỡ pháo hoa năm màu."}],"related":[{"hanzi":"天空","pinyin":"tiānkōng","vi":"bầu trời"},{"hanzi":"空中","pinyin":"kōngzhōng","vi":"trên không"},{"hanzi":"高空","pinyin":"gāokōng","vi":"trên cao"},{"hanzi":"领空","pinyin":"lǐngkōng","vi":"không phận"}]},{"id":"上市","hanzi":"上市","pinyin":"shàngshì","meaning_vi":"niêm yết trên sàn chứng khoán, tung ra thị trường","explanation":"上 + 市 (thị trường). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"新手机上市了。","pinyin":"Xīnshǒu jī shàngshì le.","vi":"Điện thoại mới đã ra mắt thị trường."},{"type":"simple","zh":"这家科技公司计划明年在香港上市。","pinyin":"Zhè jiā kējì gōngsī jìhuà míngnián zài Xiānggǎng shàngshì.","vi":"Công ty công nghệ này dự định niêm yết tại Hồng Kông vào năm sau."},{"type":"compound","zh":"每年荔枝一上市，水果店门口就排起了长队。","pinyin":"Měinián lìzhī yí shàngshì, shuǐguǒ diàn ménkǒu jiù pái qǐle chángduì.","vi":"Năm nào vải vừa vào mùa, trước cửa hàng trái cây đã xếp hàng dài."}],"related":[{"hanzi":"上市公司","pinyin":"shàngshìgōngsī","vi":"công ty niêm yết"},{"hanzi":"股票","pinyin":"gǔpiào","vi":"cổ phiếu"},{"hanzi":"新品上市","pinyin":"xīnpǐnshàngshì","vi":"sản phẩm mới ra mắt"},{"hanzi":"退市","pinyin":"tuìshì","vi":"hủy niêm yết"}]},{"id":"上手","hanzi":"上手","pinyin":"shàngshǒu","meaning_vi":"bắt đầu làm quen công việc","explanation":"上 (trên) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"这个软件很好上手。","pinyin":"Zhè ge ruǎnjiàn hěn hǎo shàngshǒu.","vi":"Phần mềm này rất dễ làm quen."},{"type":"simple","zh":"新来的收银员不到一周就上手了。","pinyin":"Xīn lái de shōuyínyuán búdào yìzhōu jiù shàngshǒu le.","vi":"Nhân viên thu ngân mới chưa đầy một tuần đã quen việc."},{"type":"compound","zh":"这台相机虽然功能复杂，但是新手也能很快上手。","pinyin":"Zhè tái xiàngjī suīrán gōngnéng fùzá, dànshì xīnshǒu yě néng hěn kuài shàngshǒu.","vi":"Chiếc máy ảnh này tuy nhiều chức năng phức tạp, nhưng người mới cũng nhanh chóng sử dụng được."}],"related":[{"hanzi":"入门","pinyin":"rùmén","vi":"nhập môn"},{"hanzi":"熟练","pinyin":"shúliàn","vi":"thành thạo"},{"hanzi":"容易上手","pinyin":"róngyìshàngshǒu","vi":"dễ làm quen"},{"hanzi":"新手","pinyin":"xīnshǒu","vi":"người mới"}]},{"id":"上旬","hanzi":"上旬","pinyin":"shàngxún","meaning_vi":"thượng tuần (10 ngày đầu tháng)","explanation":"上 (trên) + 旬 (tuần (10 ngày)/tuổi).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"三月上旬开学。","pinyin":"Sānyuè shàngxún kāixué.","vi":"Đầu tháng Ba khai giảng."},{"type":"simple","zh":"这批货预计在下个月上旬到达港口。","pinyin":"Zhè pī huò yùjì zài xiàgèyuè shàngxún dàodá gǎngkǒu.","vi":"Lô hàng này dự kiến sẽ cập cảng vào thượng tuần tháng sau."},{"type":"compound","zh":"如果十月上旬天气晴朗，我们就去香山看红叶。","pinyin":"Rúguǒ Shíyuè shàngxún tiānqì qínglǎng, wǒmen jiù qù xiāng shān kàn hóngyè.","vi":"Nếu đầu tháng Mười trời quang đãng, chúng ta sẽ đi Hương Sơn ngắm lá đỏ."}],"related":[{"hanzi":"中旬","pinyin":"zhōngxún","vi":"trung tuần"},{"hanzi":"下旬","pinyin":"xiàxún","vi":"hạ tuần"},{"hanzi":"月初","pinyin":"yuèchū","vi":"đầu tháng"},{"hanzi":"月底","pinyin":"yuèdǐ","vi":"cuối tháng"}]},{"id":"社会保障","hanzi":"社会保障","pinyin":"shèhuìbǎozhàng","meaning_vi":"an sinh xã hội","explanation":"社会 (xã hội) + 保障 (bảo chướng – bảo đảm) → hệ thống an sinh xã hội do nhà nước bảo đảm (hưu trí, y tế, thất nghiệp…). Gọi tắt 社保.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🛡️","examples":[{"type":"basic","zh":"社会保障很重要。","pinyin":"Shèhuìbǎozhàng hěn zhòngyào.","vi":"An sinh xã hội rất quan trọng."},{"type":"simple","zh":"政府不断扩大农村社会保障的覆盖范围。","pinyin":"Zhèngfǔ búduàn kuòdà nóngcūn shèhuìbǎozhàng de fùgài fànwéi.","vi":"Chính phủ không ngừng mở rộng phạm vi bao phủ của an sinh xã hội ở nông thôn."},{"type":"compound","zh":"只要社会保障体系健全，老百姓就敢放心消费。","pinyin":"Zhǐyào shèhuìbǎozhàng tǐxì jiànquán, lǎobǎixìng jiù gǎn fàngxīn xiāofèi.","vi":"Chỉ cần hệ thống an sinh xã hội hoàn thiện, người dân sẽ dám yên tâm chi tiêu."}],"related":[{"hanzi":"社保","pinyin":"shèbǎo","vi":"bảo hiểm xã hội"},{"hanzi":"养老保险","pinyin":"yǎnglǎobǎoxiǎn","vi":"bảo hiểm hưu trí"},{"hanzi":"医疗保险","pinyin":"yīliáobǎoxiǎn","vi":"bảo hiểm y tế"},{"hanzi":"福利","pinyin":"fúlì","vi":"phúc lợi"}],"traditional":"社會保障"},{"id":"社稷","hanzi":"社稷","pinyin":"shèjì","meaning_vi":"xã tắc, đất nước","explanation":"社 (xã hội/cộng đồng) + 稷 (cây kê/thần ngũ cốc).","hsk_level":"7-9","tags":["danh-tu","van-hoa","xa-hoi"],"image":"🏯","examples":[{"type":"basic","zh":"江山社稷为重。","pinyin":"Jiāngshān shèjì wéizhòng.","vi":"Giang sơn xã tắc là trọng."},{"type":"simple","zh":"古代的忠臣把江山社稷看得比生命还重。","pinyin":"Gǔdài de zhōngchén bǎ jiāngshān shèjì kàn de bǐ shēngmìng hái zhòng.","vi":"Trung thần thời xưa coi giang sơn xã tắc còn nặng hơn tính mạng."},{"type":"compound","zh":"皇帝如果只顾享乐，社稷就会陷入危机。","pinyin":"Huángdì rúguǒ zhǐgù xiǎnglè, shèjì jiù huì xiànrù wēijī.","vi":"Hoàng đế nếu chỉ biết hưởng lạc thì xã tắc sẽ lâm vào nguy cơ."}],"related":[{"hanzi":"江山","pinyin":"jiāngshān","vi":"giang sơn"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"},{"hanzi":"天下","pinyin":"tiānxià","vi":"thiên hạ"},{"hanzi":"朝廷","pinyin":"cháotíng","vi":"triều đình"}]},{"id":"涉猎","hanzi":"涉猎","pinyin":"shèliè","meaning_vi":"tìm hiểu đọc rộng nhiều lĩnh vực","explanation":"涉 (liên quan/can thiệp) + 猎 (săn bắn).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"他涉猎很广。","pinyin":"Tā shèliè hěn guǎng.","vi":"Anh ấy đọc rộng nhiều lĩnh vực."},{"type":"simple","zh":"这位作家广泛涉猎历史、哲学和天文学。","pinyin":"Zhè wèi zuòjiā guǎngfàn shèliè lìshǐ, zhéxué hé tiānwénxué.","vi":"Nhà văn này tìm hiểu rộng về lịch sử, triết học và thiên văn học."},{"type":"compound","zh":"一个人涉猎的书越多，看问题的角度就越丰富。","pinyin":"Yígèrén shèliè de shū yuè duō, kàn wèntí de jiǎodù jiù yuè fēngfù.","vi":"Một người đọc càng nhiều sách thì góc nhìn vấn đề càng phong phú."}],"related":[{"hanzi":"博览群书","pinyin":"bólǎnqúnshū","vi":"đọc nhiều sách"},{"hanzi":"广泛","pinyin":"guǎngfàn","vi":"rộng rãi"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"đọc"},{"hanzi":"涉足","pinyin":"shèzú","vi":"bước chân vào"}],"traditional":"涉獵"},{"id":"摄入","hanzi":"摄入","pinyin":"shèrù","meaning_vi":"hấp thụ, nạp vào cơ thể (dinh dưỡng/calo)","explanation":"摄 (nhiếp ảnh/hấp thụ) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🥗","examples":[{"type":"basic","zh":"少摄入糖分。","pinyin":"Shǎo shèrù tángfèn.","vi":"Hãy hạn chế nạp đường."},{"type":"simple","zh":"医生建议他每天摄入的盐不超过五克。","pinyin":"Yīshēng jiànyì tā měitiān shèrù de yán bù chāoguò wǔ kè.","vi":"Bác sĩ khuyên mỗi ngày anh ấy nạp không quá năm gam muối."},{"type":"compound","zh":"如果长期摄入过多的热量，就很容易发胖。","pinyin":"Rúguǒ chángqī shèrù guòduō de rèliàng, jiù hěn róngyì fāpàng.","vi":"Nếu lâu dài nạp quá nhiều năng lượng thì rất dễ tăng cân."}],"related":[{"hanzi":"吸收","pinyin":"xīshōu","vi":"hấp thụ"},{"hanzi":"摄取","pinyin":"shèqǔ","vi":"hấp thu"},{"hanzi":"热量","pinyin":"rèliàng","vi":"nhiệt lượng calo"},{"hanzi":"营养","pinyin":"yíngyǎng","vi":"dinh dưỡng"}],"traditional":"攝入"},{"id":"摄影师","hanzi":"摄影师","pinyin":"shèyǐngshī","meaning_vi":"nhiếp ảnh gia","explanation":"摄 (nhiếp ảnh/hấp thụ) + 影 (ảnh hưởng/hình ảnh) + 师 (thầy giáo/sư phụ).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","giai-tri"],"image":"📷","examples":[{"type":"basic","zh":"他是婚礼摄影师。","pinyin":"Tā shì hūnlǐ shèyǐngshī.","vi":"Anh ấy là nhiếp ảnh gia đám cưới."},{"type":"simple","zh":"摄影师在山顶等了三个小时才拍到日出。","pinyin":"Shèyǐngshī zài shāndǐng děngle sān gè xiǎoshí cái pāi dào rìchū.","vi":"Nhiếp ảnh gia đợi trên đỉnh núi ba tiếng mới chụp được cảnh mặt trời mọc."},{"type":"compound","zh":"一个好的摄影师不但要会用相机，而且要懂得抓住瞬间。","pinyin":"Yí gè hǎo de shèyǐngshī búdàn yào huì yòng xiàngjī, érqiě yào dǒngde zhuāzhù shùnjiān.","vi":"Một nhiếp ảnh gia giỏi không chỉ biết dùng máy ảnh mà còn phải biết nắm bắt khoảnh khắc."}],"related":[{"hanzi":"摄影","pinyin":"shèyǐng","vi":"nhiếp ảnh"},{"hanzi":"相机","pinyin":"xiàngjī","vi":"máy ảnh"},{"hanzi":"拍照","pinyin":"pāizhào","vi":"chụp ảnh"},{"hanzi":"模特","pinyin":"mótè","vi":"người mẫu"}],"traditional":"攝影師"},{"id":"涉足","hanzi":"涉足","pinyin":"shèzú","meaning_vi":"bước chân vào (lĩnh vực mới)","explanation":"涉 (liên quan/can thiệp) + 足 (đầy đủ/chân).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👣","examples":[{"type":"basic","zh":"他涉足房地产业。","pinyin":"Tā shèzú fángdìchǎn yè.","vi":"Ông ấy bước chân vào ngành bất động sản."},{"type":"simple","zh":"这家家电企业去年开始涉足新能源汽车领域。","pinyin":"Zhè jiā jiādiàn qǐyè qùnián kāishǐ shèzú xīnnéngyuánqìchē lǐngyù.","vi":"Doanh nghiệp điện máy này năm ngoái bắt đầu dấn chân vào lĩnh vực ô tô năng lượng mới."},{"type":"compound","zh":"如果对行业不了解，就不要轻易涉足。","pinyin":"Rúguǒ duì hángyè bù liǎojiě, jiù bú yào qīngyì shèzú.","vi":"Nếu không hiểu rõ ngành thì đừng dễ dàng dấn chân vào."}],"related":[{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan đến"},{"hanzi":"进军","pinyin":"jìnjūn","vi":"tiến quân vào"},{"hanzi":"踏入","pinyin":"tàrù","vi":"bước vào"},{"hanzi":"涉猎","pinyin":"shèliè","vi":"tìm hiểu rộng"}]},{"id":"胜地","hanzi":"胜地","pinyin":"shèngdì","meaning_vi":"thắng cảnh, địa điểm nổi tiếng","explanation":"胜 (thắng lợi/vượt trội) + 地 (地).","hsk_level":"7-9","tags":["danh-tu","du-lich","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"这里是避暑胜地。","pinyin":"Zhèlǐ shì bìshǔ shèngdì.","vi":"Đây là thắng cảnh nghỉ mát."},{"type":"simple","zh":"桂林自古就是闻名天下的旅游胜地。","pinyin":"Guìlín zìgǔ jiùshì wénmíng tiānxià de lǚyóu shèngdì.","vi":"Quế Lâm từ xưa đã là thắng cảnh du lịch nổi tiếng thiên hạ."},{"type":"compound","zh":"这个小岛原来默默无闻，但是自从拍了电影就成了度假胜地。","pinyin":"Zhè ge xiǎodǎo yuánlái mòmòwúwén, dànshì zìcóng pāile diànyǐng jiù chéngle dùjià shèngdì.","vi":"Hòn đảo nhỏ này vốn vô danh, nhưng từ khi quay phim đã trở thành điểm nghỉ dưỡng nổi tiếng."}],"related":[{"hanzi":"名胜","pinyin":"míngshèng","vi":"danh thắng"},{"hanzi":"旅游胜地","pinyin":"lǚyóushèngdì","vi":"điểm du lịch nổi tiếng"},{"hanzi":"景点","pinyin":"jǐngdiǎn","vi":"điểm tham quan"},{"hanzi":"避暑胜地","pinyin":"bìshǔshèngdì","vi":"nơi nghỉ mát"}],"traditional":"勝地"},{"id":"盛情难却","hanzi":"盛情难却","pinyin":"shèngqíng-nánquè","meaning_vi":"thịnh tình khó từ chối","explanation":"盛情 + 难却 (khó từ chối). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"主人盛情难却。","pinyin":"Zhǔrén shèngqíngnánquè.","vi":"Thịnh tình của chủ nhà khó chối từ."},{"type":"simple","zh":"盛情难却之下他又多住了三天。","pinyin":"Shèngqíngnánquè zhīxià tā yòu duō zhùle sān tiān.","vi":"Thịnh tình khó từ chối, anh ấy ở lại thêm ba ngày nữa."},{"type":"compound","zh":"本来我不想喝酒，可是盛情难却，只好陪大家喝了一杯。","pinyin":"Běnlái wǒ bù xiǎng hējiǔ, kěshì shèngqíngnánquè, zhǐhǎo péi dàjiā hēle yì bēi.","vi":"Vốn dĩ tôi không muốn uống rượu, nhưng thịnh tình khó từ chối nên đành uống cùng mọi người một ly."}],"related":[{"hanzi":"盛情","pinyin":"shèngqíng","vi":"thịnh tình"},{"hanzi":"却之不恭","pinyin":"quèzhībùgōng","vi":"từ chối thì bất kính"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"盛情款待","pinyin":"shèngqíngkuǎndài","vi":"tiếp đãi nồng hậu"}],"traditional":"盛情難卻"},{"id":"胜任","hanzi":"胜任","pinyin":"shèngrèn","meaning_vi":"đảm đương tốt (công việc)","explanation":"胜 (thắng lợi/vượt trội) + 任 (nhiệm vụ/bổ nhiệm).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✅","examples":[{"type":"basic","zh":"他能胜任这份工作。","pinyin":"Tā néng shèngrèn zhè fèn gōngzuò.","vi":"Anh ấy đảm đương tốt công việc này."},{"type":"simple","zh":"只有一年经验的她完全胜任了主编的职务。","pinyin":"Zhǐyǒu yì nián jīngyàn de tā wánquán shèngrènle zhǔbiān de zhíwù.","vi":"Chỉ với một năm kinh nghiệm, cô ấy đã hoàn toàn đảm đương tốt chức vụ tổng biên tập."},{"type":"compound","zh":"如果你觉得自己不能胜任，就应该早点告诉经理。","pinyin":"Rúguǒ nǐ juéde zìjǐ bù néng shèngrèn, jiù yīnggāi zǎodiǎn gàosu jīnglǐ.","vi":"Nếu bạn thấy mình không đảm đương được thì nên báo sớm cho quản lý."}],"related":[{"hanzi":"称职","pinyin":"chènzhí","vi":"xứng chức"},{"hanzi":"能干","pinyin":"nénggàn","vi":"giỏi giang"},{"hanzi":"胜任工作","pinyin":"shèngrèngōngzuò","vi":"đảm đương công việc"},{"hanzi":"不称职","pinyin":"búchènzhí","vi":"không xứng chức"}],"traditional":"勝任"},{"id":"胜算","hanzi":"胜算","pinyin":"shèngsuàn","meaning_vi":"khả năng chiến thắng","explanation":"胜 (thắng lợi/vượt trội) + 算 (tính toán).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🏆","examples":[{"type":"basic","zh":"我们胜算不大。","pinyin":"Wǒmen shèngsuàn búdà.","vi":"Khả năng thắng của chúng ta không cao."},{"type":"simple","zh":"主力球员受伤让球队的胜算大大降低。","pinyin":"Zhǔlì qiúyuán shòushāng ràng qiúduì de shèngsuàn dàdà jiàngdī.","vi":"Cầu thủ chủ lực chấn thương khiến cơ hội thắng của đội giảm mạnh."},{"type":"compound","zh":"既然没有胜算，与其硬拼，不如保存实力。","pinyin":"Jìrán méiyǒu shèngsuàn, yǔqí yìng pīn, bùrú bǎocún shílì.","vi":"Đã không có cửa thắng thì thay vì liều mạng, chi bằng giữ gìn thực lực."}],"related":[{"hanzi":"把握","pinyin":"bǎwò","vi":"sự nắm chắc"},{"hanzi":"胜率","pinyin":"shènglǜ","vi":"tỷ lệ thắng"},{"hanzi":"赢面","pinyin":"yíngmiàn","vi":"khả năng thắng"},{"hanzi":"稳操胜券","pinyin":"wěncāoshèngquàn","vi":"nắm chắc phần thắng"}],"traditional":"勝算"},{"id":"盛装","hanzi":"盛装","pinyin":"shèngzhuāng","meaning_vi":"lễ phục lộng lẫy","explanation":"盛 (xới (cơm)) + 装 (trang bị/ngụy trang).","hsk_level":"7-9","tags":["danh-tu","trang-phuc"],"image":"👗","examples":[{"type":"basic","zh":"她身着盛装。","pinyin":"Tā shēnzhuó shèngzhuāng.","vi":"Cô ấy khoác trên mình bộ lễ phục lộng lẫy."},{"type":"simple","zh":"节日那天，苗族姑娘们穿着盛装跳起了舞。","pinyin":"Jiérì nà tiān, Miáozú gūniangmen chuānzhe shèngzhuāng tiào qǐle wǔ.","vi":"Ngày lễ hội, các cô gái dân tộc Miêu mặc trang phục lộng lẫy nhảy múa."},{"type":"compound","zh":"虽然只是一次家庭聚会，但是奶奶还是盛装出席了。","pinyin":"Suīrán zhǐshì yí cì jiātíng jùhuì, dànshì nǎinai háishì shèngzhuāng chūxí le.","vi":"Tuy chỉ là buổi họp mặt gia đình, nhưng bà nội vẫn ăn diện lộng lẫy đến dự."}],"related":[{"hanzi":"礼服","pinyin":"lǐfú","vi":"lễ phục"},{"hanzi":"华丽","pinyin":"huálì","vi":"lộng lẫy"},{"hanzi":"打扮","pinyin":"dǎban","vi":"trang điểm ăn diện"},{"hanzi":"便装","pinyin":"biànzhuāng","vi":"thường phục"}],"traditional":"盛裝"},{"id":"盛赞","hanzi":"盛赞","pinyin":"shèngzàn","meaning_vi":"ca ngợi hết lời","explanation":"盛 (xới (cơm)) + 赞 (tán thành/khen ngợi).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👏","examples":[{"type":"basic","zh":"观众盛赞这部戏。","pinyin":"Guānzhòng shèngzàn zhè bù xì.","vi":"Khán giả hết lời khen ngợi vở kịch này."},{"type":"simple","zh":"外国媒体盛赞中国高铁的速度和舒适度。","pinyin":"Wàiguó méitǐ shèngzàn Zhōngguó gāotiě de sùdù hé shū shìdù.","vi":"Truyền thông nước ngoài hết lời ca ngợi tốc độ và sự thoải mái của tàu cao tốc Trung Quốc."},{"type":"compound","zh":"他的新书一出版，就受到了评论家的盛赞。","pinyin":"Tā de xīn shū yì chūbǎn, jiù shòudàole pínglùnjiā de shèngzàn.","vi":"Cuốn sách mới của anh ấy vừa xuất bản đã được các nhà phê bình hết lời ca ngợi."}],"related":[{"hanzi":"称赞","pinyin":"chēngzàn","vi":"khen ngợi"},{"hanzi":"赞扬","pinyin":"zànyáng","vi":"ca ngợi"},{"hanzi":"夸奖","pinyin":"kuājiǎng","vi":"khen"},{"hanzi":"批评","pinyin":"pīpíng","vi":"phê bình"}],"traditional":"盛讚"},{"id":"神采","hanzi":"神采","pinyin":"shéncǎi","meaning_vi":"thần sắc, vẻ rạng ngời","explanation":"神 (thần kỳ/tinh thần) + 采 (thu thập/phong thái).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"他的眼睛里没有了神采。","pinyin":"Tā de yǎnjing li méiyǒule shéncǎi.","vi":"Trong mắt anh ấy không còn vẻ rạng ngời."},{"type":"simple","zh":"领奖台上的冠军显得神采飞扬。","pinyin":"Lǐngjiǎngtái shang de guànjūn xiǎnde shéncǎifēiyáng.","vi":"Nhà vô địch trên bục nhận giải trông rạng ngời phấn chấn."},{"type":"compound","zh":"老人虽然已经八十岁了，但是依然神采奕奕。","pinyin":"Lǎorén suīrán yǐjīng bāshí suì le, dànshì yīrán shéncǎiyìyì.","vi":"Ông cụ tuy đã tám mươi tuổi, nhưng vẫn tinh thần quắc thước, rạng rỡ."}],"related":[{"hanzi":"神采奕奕","pinyin":"shéncǎiyìyì","vi":"rạng rỡ tinh thần"},{"hanzi":"精神","pinyin":"jīngshen","vi":"tinh thần, phấn chấn"},{"hanzi":"气色","pinyin":"qìsè","vi":"sắc mặt"},{"hanzi":"容光焕发","pinyin":"róngguānghuànfā","vi":"mặt mày rạng rỡ"}]},{"id":"神化","hanzi":"神化","pinyin":"shénhuà","meaning_vi":"thần thánh hóa","explanation":"神 (thần kỳ/tinh thần) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🔮","examples":[{"type":"basic","zh":"不要神化名人。","pinyin":"Bú yào shénhuà míngrén.","vi":"Đừng thần thánh hóa người nổi tiếng."},{"type":"simple","zh":"某些粉丝把自己的偶像神化成了完美的人。","pinyin":"Mǒuxiē fěnsī bǎ zìjǐ de ǒuxiàng shénhuà chéngle wánměi de rén.","vi":"Một số người hâm mộ thần thánh hóa thần tượng của mình thành người hoàn hảo."},{"type":"compound","zh":"历史人物一旦被神化，人们就很难看清他的真实面目。","pinyin":"Lìshǐ rénwù yídàn bèi shénhuà, rénmen jiù hěn nán kànqīng tā de zhēnshí miànmù.","vi":"Nhân vật lịch sử một khi bị thần thánh hóa thì người ta khó thấy rõ bộ mặt thật của họ."}],"related":[{"hanzi":"神话","pinyin":"shénhuà","vi":"thần thoại"},{"hanzi":"美化","pinyin":"měihuà","vi":"tô đẹp"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"偶像","pinyin":"ǒuxiàng","vi":"thần tượng"}]},{"id":"神经过敏","hanzi":"神经过敏","pinyin":"shénjīngguòmǐn","meaning_vi":"nhạy cảm quá mức, đa nghi","explanation":"神经 (thần kinh) + 过敏 (dị ứng).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"你太神经过敏了。","pinyin":"Nǐ tài shénjīngguòmǐn le.","vi":"Bạn nhạy cảm quá mức rồi."},{"type":"simple","zh":"她对别人的每一句玩笑都神经过敏。","pinyin":"Tā duì biérén de měi yíjù wánxiào dōu shénjīngguòmǐn.","vi":"Cô ấy nhạy cảm thái quá với từng câu đùa của người khác."},{"type":"compound","zh":"只是有人敲了下门，你就紧张成这样，真是神经过敏。","pinyin":"Zhǐshì yǒurén qiāole xià mén, nǐ jiù jǐnzhāng chéng zhèyàng, zhēn shì shénjīngguòmǐn.","vi":"Chỉ có người gõ cửa thôi mà bạn đã căng thẳng thế này, đúng là đa nghi quá mức."}],"related":[{"hanzi":"过敏","pinyin":"guòmǐn","vi":"dị ứng, quá nhạy"},{"hanzi":"多疑","pinyin":"duōyí","vi":"đa nghi"},{"hanzi":"敏感","pinyin":"mǐngǎn","vi":"nhạy cảm"},{"hanzi":"神经质","pinyin":"shénjīngzhì","vi":"thần kinh nhạy cảm"}],"traditional":"神經過敏"},{"id":"神秘感","hanzi":"神秘感","pinyin":"shénmìgǎn","meaning_vi":"cảm giác bí ẩn","explanation":"神 (thần kỳ/tinh thần) + 秘 (秘) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🔮","examples":[{"type":"basic","zh":"这座古堡很有神秘感。","pinyin":"Zhè zuò gǔbǎo hěn yǒu shénmìgǎn.","vi":"Tòa lâu đài cổ này rất bí ẩn."},{"type":"simple","zh":"昏暗的灯光给这家咖啡馆增添了几分神秘感。","pinyin":"Hūn'àn de dēngguāng gěi zhè jiā kāfēiguǎn zēngtiānle jǐfēn shénmìgǎn.","vi":"Ánh đèn lờ mờ tăng thêm vài phần bí ẩn cho quán cà phê này."},{"type":"compound","zh":"明星如果把私生活全都公开，就会失去神秘感。","pinyin":"Míngxīng rúguǒ bǎ sīshēnghuó quándōu gōngkāi, jiù huì shīqù shénmìgǎn.","vi":"Ngôi sao nếu công khai toàn bộ đời tư thì sẽ mất đi vẻ bí ẩn."}],"related":[{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"好奇","pinyin":"hàoqí","vi":"tò mò"},{"hanzi":"奥秘","pinyin":"àomì","vi":"bí ẩn"},{"hanzi":"悬念","pinyin":"xuánniàn","vi":"sự hồi hộp chờ đợi"}]},{"id":"神速","hanzi":"神速","pinyin":"shénsù","meaning_vi":"thần tốc, nhanh như chớp","explanation":"神 (thần kỳ/tinh thần) + 速 (nhanh chóng/tốc độ).","hsk_level":"7-9","tags":["tinh-tu"],"image":"⚡","examples":[{"type":"basic","zh":"他进步神速。","pinyin":"Tā jìnbù shénsù.","vi":"Anh ấy tiến bộ thần tốc."},{"type":"simple","zh":"消防队员以神速赶到了起火的大楼。","pinyin":"Xiāofáng duìyuán yǐ shénsù gǎndàole qǐhuǒ de dàlóu.","vi":"Lính cứu hỏa đến tòa nhà bốc cháy với tốc độ thần tốc."},{"type":"compound","zh":"因为采用了新工艺，所以工程进展神速。","pinyin":"Yīnwèi cǎiyòngle xīn gōngyì, suǒyǐ gōngchéng jìnzhǎn shénsù.","vi":"Vì áp dụng công nghệ mới nên công trình tiến triển thần tốc."}],"related":[{"hanzi":"迅速","pinyin":"xùnsù","vi":"nhanh chóng"},{"hanzi":"飞快","pinyin":"fēikuài","vi":"nhanh như bay"},{"hanzi":"进展神速","pinyin":"jìnzhǎnshénsù","vi":"tiến triển thần tốc"},{"hanzi":"缓慢","pinyin":"huǎnmàn","vi":"chậm chạp"}]},{"id":"神往","hanzi":"神往","pinyin":"shénwǎng","meaning_vi":"say mê hướng tới, khao khát","explanation":"神 (thần kỳ/tinh thần) + 往 (về phía).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🌠","examples":[{"type":"basic","zh":"西藏令人神往。","pinyin":"Xīzàng lìngrén shénwǎng.","vi":"Tây Tạng khiến người ta mơ ước."},{"type":"simple","zh":"爷爷讲的海上冒险故事让我无比神往。","pinyin":"Yéye jiǎng de hǎishang màoxiǎn gùshi ràng wǒ wúbǐ shénwǎng.","vi":"Những câu chuyện phiêu lưu trên biển ông kể khiến tôi vô cùng say mê khao khát."},{"type":"compound","zh":"虽然从没去过北极，但是那里的极光一直让我心驰神往。","pinyin":"Suīrán cóng méi qùguo Běijí, dànshì nàlǐ de jíguāng yìzhí ràng wǒ xīn chí shénwǎng.","vi":"Tuy chưa từng đến Bắc Cực, nhưng cực quang ở đó luôn khiến tôi khao khát hướng về."}],"related":[{"hanzi":"向往","pinyin":"xiàngwǎng","vi":"hướng tới, mong ước"},{"hanzi":"憧憬","pinyin":"chōngjǐng","vi":"khát khao"},{"hanzi":"心驰神往","pinyin":"xīnchíshénwǎng","vi":"say mê hướng về"},{"hanzi":"渴望","pinyin":"kěwàng","vi":"khát vọng"}]},{"id":"市场份额","hanzi":"市场份额","pinyin":"shìchǎngfèn'é","meaning_vi":"thị phần","explanation":"市场 + 份额 (phần định mức).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🥧","examples":[{"type":"basic","zh":"我们的市场份额扩大了。","pinyin":"Wǒmen de shìchǎngfèn'é kuòdà le.","vi":"Thị phần của chúng ta đã mở rộng."},{"type":"simple","zh":"这个国产品牌占据了三成的市场份额。","pinyin":"Zhè ge guóchǎn pǐnpái zhànjùle sān chéng de shìchǎngfèn'é.","vi":"Thương hiệu nội địa này chiếm ba mươi phần trăm thị phần."},{"type":"compound","zh":"如果不及时推出新产品，市场份额就会被对手抢走。","pinyin":"Rúguǒ bù jíshí tuīchū xīnchǎnpǐn, shìchǎngfèn'é jiù huì bèi duìshǒu qiǎngzǒu.","vi":"Nếu không kịp tung ra sản phẩm mới, thị phần sẽ bị đối thủ giành mất."}],"related":[{"hanzi":"份额","pinyin":"fèn'é","vi":"phần, tỷ lệ"},{"hanzi":"占有率","pinyin":"zhànyǒulǜ","vi":"tỷ lệ chiếm hữu"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"销量","pinyin":"xiāoliàng","vi":"doanh số bán"}],"traditional":"市場份額"},{"id":"市场化","hanzi":"市场化","pinyin":"shìchǎnghuà","meaning_vi":"thị trường hóa","explanation":"市 (thị trường/thành phố) + 场 (trận) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏪","examples":[{"type":"basic","zh":"电力改革走向市场化。","pinyin":"Diànlì gǎigé zǒuxiàng shìchǎnghuà.","vi":"Cải cách điện lực tiến tới thị trường hóa."},{"type":"simple","zh":"住房市场化改革改变了城市居民的生活。","pinyin":"Zhùfáng shìchǎnghuà gǎigé gǎibiànle chéngshì jūmín de shēnghuó.","vi":"Cải cách thị trường hóa nhà ở đã thay đổi cuộc sống cư dân đô thị."},{"type":"compound","zh":"虽然医疗行业需要一定程度的市场化，但是不能完全交给市场。","pinyin":"Suīrán yīliáo hángyè xūyào yídìng chéngdù de shìchǎnghuà, dànshì bù néng wánquán jiāogěi shìchǎng.","vi":"Tuy ngành y tế cần thị trường hóa ở mức độ nhất định, nhưng không thể giao hoàn toàn cho thị trường."}],"related":[{"hanzi":"市场经济","pinyin":"shìchǎngjīngjì","vi":"kinh tế thị trường"},{"hanzi":"商业化","pinyin":"shāngyèhuà","vi":"thương mại hóa"},{"hanzi":"计划经济","pinyin":"jìhuàjīngjì","vi":"kinh tế kế hoạch"},{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"}],"traditional":"市場化"},{"id":"市场调研","hanzi":"市场调研","pinyin":"shìchǎngdiàoyán","meaning_vi":"nghiên cứu khảo sát thị trường","explanation":"市 (thị trường/thành phố) + 场 (địa điểm/trận đấu) + 调 (điều chỉnh/hòa giải) + 研 (nghiên cứu).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"我们先做市场调研。","pinyin":"Wǒmen xiān zuò shìchǎngdiàoyán.","vi":"Chúng ta làm nghiên cứu thị trường trước."},{"type":"simple","zh":"她带着问卷到商场门口做市场调研。","pinyin":"Tā dàizhe wènjuàn dào shāngchǎng ménkǒu zuò shìchǎngdiàoyán.","vi":"Cô ấy mang phiếu khảo sát đến trước cửa trung tâm thương mại để nghiên cứu thị trường."},{"type":"compound","zh":"如果没做市场调研就盲目投产，很可能会亏本。","pinyin":"Rúguǒ méi zuò shìchǎngdiàoyán jiù mángmù tóuchǎn, hěn kěnéng huì kuīběn.","vi":"Nếu không nghiên cứu thị trường mà mù quáng đưa vào sản xuất thì rất có thể lỗ vốn."}],"related":[{"hanzi":"调研","pinyin":"diàoyán","vi":"khảo sát nghiên cứu"},{"hanzi":"问卷调查","pinyin":"wènjuàndiàochá","vi":"khảo sát bằng phiếu"},{"hanzi":"市场营销","pinyin":"shìchǎngyíngxiāo","vi":"tiếp thị"},{"hanzi":"消费者","pinyin":"xiāofèizhě","vi":"người tiêu dùng"}],"traditional":"市場調研"},{"id":"适度","hanzi":"适度","pinyin":"shìdù","meaning_vi":"vừa phải, điều độ","explanation":"适 (thích hợp/thoải mái) + 度 (度).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"运动要适度。","pinyin":"Yùndòng yào shìdù.","vi":"Vận động cần vừa phải."},{"type":"simple","zh":"适度的压力反而能提高工作效率。","pinyin":"Shìdù de yālì fǎn'ér néng tígāo gōngzuò xiàolǜ.","vi":"Áp lực vừa phải ngược lại có thể nâng cao hiệu suất làm việc."},{"type":"compound","zh":"喝酒如果能适度，就不会对身体造成太大伤害。","pinyin":"Hējiǔ rúguǒ néng shìdù, jiù bú huì duì shēntǐ zàochéng tài dà shānghài.","vi":"Uống rượu nếu điều độ thì sẽ không gây hại quá lớn cho cơ thể."}],"related":[{"hanzi":"适当","pinyin":"shìdàng","vi":"thích đáng"},{"hanzi":"适量","pinyin":"shìliàng","vi":"vừa phải"},{"hanzi":"过度","pinyin":"guòdù","vi":"quá mức"},{"hanzi":"节制","pinyin":"jiézhì","vi":"điều độ"}],"traditional":"適度"},{"id":"示范","hanzi":"示范","pinyin":"shìfàn","meaning_vi":"làm mẫu, thị phạm","explanation":"示 (biểu thị/ra hiệu) + 范 (范).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"老师先示范一遍。","pinyin":"Lǎoshī xiān shìfàn yíbiàn.","vi":"Thầy làm mẫu trước một lượt."},{"type":"simple","zh":"教练在泳池边给孩子们示范换气动作。","pinyin":"Jiàoliàn zài yǒngchí biān gěi háizimen shìfàn huànqì dòngzuò.","vi":"Huấn luyện viên làm mẫu động tác lấy hơi cho bọn trẻ bên hồ bơi."},{"type":"compound","zh":"只要师傅示范一次，他就能学得八九不离十。","pinyin":"Zhǐyào shīfu shìfàn yí cì, tā jiù néng xué de bājiǔbùlíshí.","vi":"Chỉ cần sư phụ làm mẫu một lần, cậu ấy đã học được gần như y hệt."}],"related":[{"hanzi":"榜样","pinyin":"bǎngyàng","vi":"tấm gương"},{"hanzi":"演示","pinyin":"yǎnshì","vi":"trình diễn"},{"hanzi":"模范","pinyin":"mófàn","vi":"mô phạm"},{"hanzi":"示范区","pinyin":"shìfànqū","vi":"khu thí điểm mẫu"}],"traditional":"示範"},{"id":"适逢","hanzi":"适逢","pinyin":"shìféng","meaning_vi":"đúng dịp, gặp đúng lúc","explanation":"适 (thích hợp/thoải mái) + 逢 (gặp).","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"🍀","examples":[{"type":"basic","zh":"适逢国庆长假。","pinyin":"Shìféng Guóqìng chángjià.","vi":"Đúng dịp nghỉ lễ Quốc khánh dài ngày."},{"type":"simple","zh":"我们到达杭州时适逢桂花盛开。","pinyin":"Wǒmen dàodá Hángzhōu shí shìféng guìhuā shèngkāi.","vi":"Khi chúng tôi đến Hàng Châu thì đúng dịp hoa quế nở rộ."},{"type":"compound","zh":"今年适逢建校一百周年，所以学校举办了盛大的庆典。","pinyin":"Jīnnián shìféng jiàn xiào yī bǎi zhōunián, suǒyǐ xuéxiào jǔbànle shèngdà de qìngdiǎn.","vi":"Năm nay đúng dịp kỷ niệm 100 năm thành lập trường, nên trường đã tổ chức lễ kỷ niệm long trọng."}],"related":[{"hanzi":"恰逢","pinyin":"qiàféng","vi":"vừa đúng dịp"},{"hanzi":"正值","pinyin":"zhèngzhí","vi":"đúng lúc"},{"hanzi":"赶上","pinyin":"gǎnshàng","vi":"bắt kịp, gặp đúng"},{"hanzi":"碰巧","pinyin":"pèngqiǎo","vi":"tình cờ"}],"traditional":"適逢"},{"id":"试飞","hanzi":"试飞","pinyin":"shìfēi","meaning_vi":"bay thử nghiệm","explanation":"试 (thí – thử) + 飞 (phi – bay) → bay thử máy bay, thiết bị bay mới trước khi đưa vào sử dụng. Ví dụ: 首次试飞 (chuyến bay thử đầu tiên).","hsk_level":"7-9","tags":["dong-tu","giao-thong","khoa-hoc"],"image":"✈️","examples":[{"type":"basic","zh":"新飞机试飞成功。","pinyin":"Xīn fēijī shìfēi chénggōng.","vi":"Máy bay mới bay thử thành công."},{"type":"simple","zh":"国产大飞机今天上午在浦东机场首次试飞。","pinyin":"Guóchǎn dà fēijī jīntiān shàngwǔ zài Pǔdōngjīchǎng shǒucì shìfēi.","vi":"Máy bay cỡ lớn sản xuất trong nước sáng nay bay thử lần đầu tại sân bay Phố Đông."},{"type":"compound","zh":"如果试飞过程中发现故障，就要立即返回地面检修。","pinyin":"Rúguǒ shìfēi guòchéng zhōng fāxiàn gùzhàng, jiùyào lìjí fǎnhuí dìmiàn jiǎnxiū.","vi":"Nếu trong quá trình bay thử phát hiện sự cố thì phải lập tức quay về mặt đất kiểm tra sửa chữa."}],"related":[{"hanzi":"试验","pinyin":"shìyàn","vi":"thử nghiệm"},{"hanzi":"飞行员","pinyin":"fēixíngyuán","vi":"phi công"},{"hanzi":"首飞","pinyin":"shǒufēi","vi":"chuyến bay đầu"},{"hanzi":"试驾","pinyin":"shìjià","vi":"lái thử"}],"traditional":"試飛"},{"id":"世故","hanzi":"世故","pinyin":"shìgù","meaning_vi":"sự đời, nhân tình thế thái; khôn khéo sành đời","explanation":"世 (thế giới/thế hệ) + 故 (故).","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"🦊","examples":[{"type":"basic","zh":"他为人很世故。","pinyin":"Tā wéirén hěn shìgù.","vi":"Ông ta rất khôn khéo sành đời."},{"type":"simple","zh":"才二十岁的他说起话来却像个世故的老人。","pinyin":"Cái èrshí suì de tā shuōqǐ huà lái què xiàng gè shìgù de lǎorén.","vi":"Mới hai mươi tuổi mà anh ấy ăn nói như một ông già từng trải sự đời."},{"type":"compound","zh":"他虽然懂得人情世故，但是从不做违背良心的事。","pinyin":"Tā suīrán dǒngde rénqíng shìgù, dànshì cóng bú zuò wéibèi liángxīn de shì.","vi":"Anh ấy tuy hiểu nhân tình thế thái, nhưng chưa bao giờ làm điều trái lương tâm."}],"related":[{"hanzi":"圆滑","pinyin":"yuánhuá","vi":"khéo léo láu cá"},{"hanzi":"老练","pinyin":"lǎoliàn","vi":"lão luyện"},{"hanzi":"人情世故","pinyin":"rénqíngshìgù","vi":"lẽ đời nhân tình"},{"hanzi":"天真","pinyin":"tiānzhēn","vi":"ngây thơ"}]},{"id":"试行","hanzi":"试行","pinyin":"shìxíng","meaning_vi":"thi hành thử nghiệm","explanation":"试 (thử) + 行 (được).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🧪","examples":[{"type":"basic","zh":"新规定开始试行。","pinyin":"Xīn guīdìng kāishǐ shìxíng.","vi":"Quy định mới bắt đầu thi hành thử."},{"type":"simple","zh":"这项垃圾分类办法先在三个小区试行半年。","pinyin":"Zhè xiàng lājīfēnlèi bànfǎ xiān zài sān gè xiǎoqū shìxíng bàn nián.","vi":"Biện pháp phân loại rác này được thí điểm trước ở ba khu dân cư trong nửa năm."},{"type":"compound","zh":"如果试行效果良好，这项政策就会在全省推广。","pinyin":"Rúguǒ shìxíng xiàoguǒ liánghǎo, zhè xiàng zhèngcè jiù huì zài quánshěng tuīguǎng.","vi":"Nếu hiệu quả thí điểm tốt, chính sách này sẽ được nhân rộng toàn tỉnh."}],"related":[{"hanzi":"试点","pinyin":"shìdiǎn","vi":"thí điểm"},{"hanzi":"实行","pinyin":"shíxíng","vi":"thực hiện"},{"hanzi":"推行","pinyin":"tuīxíng","vi":"thực thi"},{"hanzi":"试用","pinyin":"shìyòng","vi":"dùng thử"}],"traditional":"試行"},{"id":"世交","hanzi":"世交","pinyin":"shìjiāo","meaning_vi":"thế giao (hai gia đình quen biết nhiều đời)","explanation":"世 (thế giới/thế hệ) + 交 (giao).","hsk_level":"7-9","tags":["danh-tu","gia-dinh","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"王家与李家是世交。","pinyin":"Wángjiā yǔ lǐ jiā shì shìjiāo.","vi":"Nhà họ Vương và nhà họ Lý là thế giao lâu đời."},{"type":"simple","zh":"他的爷爷和我的爷爷是多年的世交。","pinyin":"Tā de yéye hé wǒ de yéye shì duōnián de shìjiāo.","vi":"Ông nội anh ấy và ông nội tôi là chỗ thâm giao nhiều năm."},{"type":"compound","zh":"因为两家是世交，所以我们从小就像亲兄妹一样。","pinyin":"Yīnwèi liǎng jiā shì shìjiāo, suǒyǐ wǒmen cóngxiǎo jiù xiàng qīn xiōngmèi yíyàng.","vi":"Vì hai nhà là thế giao nên chúng tôi từ nhỏ đã như anh em ruột."}],"related":[{"hanzi":"老朋友","pinyin":"lǎopéngyou","vi":"bạn cũ"},{"hanzi":"世代","pinyin":"shìdài","vi":"nhiều đời"},{"hanzi":"交情","pinyin":"jiāoqing","vi":"tình giao hảo"},{"hanzi":"故交","pinyin":"gùjiāo","vi":"bạn cũ"}]},{"id":"视角","hanzi":"视角","pinyin":"shìjiǎo","meaning_vi":"góc nhìn, quan điểm tiếp cận","explanation":"视 (tầm nhìn/coi trọng) + 角 (角).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"👁️","examples":[{"type":"basic","zh":"换个视角看问题。","pinyin":"Huàn gè shìjiǎo kàn wèntí.","vi":"Hãy nhìn vấn đề từ góc khác."},{"type":"simple","zh":"这部纪录片从一只猫的视角讲述城市生活。","pinyin":"Zhè bù jìlùpiàn cóng yì zhī māo de shìjiǎo jiǎngshù chéngshì shēnghuó.","vi":"Bộ phim tài liệu này kể về cuộc sống đô thị từ góc nhìn của một chú mèo."},{"type":"compound","zh":"如果你站在父母的视角想一想，就能理解他们的担心了。","pinyin":"Rúguǒ nǐ zhàn zài fùmǔ de shìjiǎo xiǎng yi xiǎng, jiù néng lǐjiě tāmen de dānxīn le.","vi":"Nếu bạn đứng ở góc nhìn của cha mẹ mà nghĩ thử, sẽ hiểu được nỗi lo của họ."}],"related":[{"hanzi":"角度","pinyin":"jiǎodù","vi":"góc độ"},{"hanzi":"观点","pinyin":"guāndiǎn","vi":"quan điểm"},{"hanzi":"视野","pinyin":"shìyě","vi":"tầm nhìn"},{"hanzi":"立场","pinyin":"lìchǎng","vi":"lập trường"}],"traditional":"視角"},{"id":"视觉","hanzi":"视觉","pinyin":"shìjué","meaning_vi":"thị giác","explanation":"视 (tầm nhìn/coi trọng) + 觉 (giác ngộ/cảm nhận).","hsk_level":"7-9","tags":["danh-tu","co-the","khoa-hoc"],"image":"👀","examples":[{"type":"basic","zh":"这是视觉错觉。","pinyin":"Zhè shì shìjué cuòjué.","vi":"Đây là ảo giác thị giác."},{"type":"simple","zh":"这家餐厅的摆盘给顾客带来了强烈的视觉冲击。","pinyin":"Zhè jiā cāntīng de bǎipán gěi gùkè dàiláile qiángliè de shìjué chōngjī.","vi":"Cách bày món của nhà hàng này tạo ấn tượng thị giác mạnh cho thực khách."},{"type":"compound","zh":"人类虽然主要依靠视觉，但是听觉和嗅觉也很重要。","pinyin":"Rénlèi suīrán zhǔyào yīkào shìjué, dànshì tīngjué hé xiùjué yě hěn zhòngyào.","vi":"Con người tuy chủ yếu dựa vào thị giác, nhưng thính giác và khứu giác cũng rất quan trọng."}],"related":[{"hanzi":"听觉","pinyin":"tīngjué","vi":"thính giác"},{"hanzi":"触觉","pinyin":"chùjué","vi":"xúc giác"},{"hanzi":"视觉效果","pinyin":"shìjuéxiàoguǒ","vi":"hiệu ứng thị giác"},{"hanzi":"感官","pinyin":"gǎnguān","vi":"giác quan"}],"traditional":"視覺"},{"id":"视力","hanzi":"视力","pinyin":"shìlì","meaning_vi":"thị lực","explanation":"视 (tầm nhìn/coi trọng) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","co-the","suc-khoe"],"image":"👓","examples":[{"type":"basic","zh":"我的视力下降了。","pinyin":"Wǒ de shìlì xiàjiàng le.","vi":"Thị lực của tôi đã giảm."},{"type":"simple","zh":"学校每学期都会给学生检查一次视力。","pinyin":"Xuéxiào měi xuéqī dōuhuì gěi xuéshēng jiǎnchá yí cì shìlì.","vi":"Mỗi học kỳ nhà trường đều kiểm tra thị lực cho học sinh một lần."},{"type":"compound","zh":"如果每天看手机超过八小时，视力就会受到严重影响。","pinyin":"Rúguǒ měitiān kàn shǒujī chāoguò bā xiǎoshí, shìlì jiù huì shòudào yánzhòng yǐngxiǎng.","vi":"Nếu mỗi ngày xem điện thoại quá tám tiếng, thị lực sẽ bị ảnh hưởng nghiêm trọng."}],"related":[{"hanzi":"近视","pinyin":"jìnshì","vi":"cận thị"},{"hanzi":"远视","pinyin":"yuǎnshì","vi":"viễn thị"},{"hanzi":"眼镜","pinyin":"yǎnjìng","vi":"kính mắt"},{"hanzi":"视力表","pinyin":"shìlìbiǎo","vi":"bảng đo thị lực"}],"traditional":"視力"},{"id":"适龄","hanzi":"适龄","pinyin":"shìlíng","meaning_vi":"đúng độ tuổi quy định","explanation":"适 (thích hợp/thoải mái) + 龄 (龄).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🎂","examples":[{"type":"basic","zh":"适龄儿童要入学。","pinyin":"Shìlíng értóng yào rùxué.","vi":"Trẻ em đúng độ tuổi phải đi học."},{"type":"simple","zh":"这个社区为适龄老人免费接种流感疫苗。","pinyin":"Zhè ge shèqū wèi shìlíng lǎorén miǎnfèi jiēzhòng liúgǎn yìmiáo.","vi":"Khu dân cư này tiêm miễn phí vắc-xin cúm cho người cao tuổi trong độ tuổi quy định."},{"type":"compound","zh":"只要是适龄青年，就有义务参加兵役登记。","pinyin":"Zhǐ yàoshì shìlíng qīngnián, jiù yǒu yìwù cānjiā bīngyì dēngjì.","vi":"Chỉ cần là thanh niên trong độ tuổi quy định thì có nghĩa vụ đăng ký nghĩa vụ quân sự."}],"related":[{"hanzi":"适龄儿童","pinyin":"shìlíng'értóng","vi":"trẻ đúng độ tuổi"},{"hanzi":"年龄","pinyin":"niánlíng","vi":"tuổi tác"},{"hanzi":"学龄","pinyin":"xuélíng","vi":"tuổi đi học"},{"hanzi":"适婚","pinyin":"shìhūn","vi":"đến tuổi kết hôn"}],"traditional":"適齡"},{"id":"世面","hanzi":"世面","pinyin":"shìmiàn","meaning_vi":"sự đời, thế giới rộng lớn (见过世面)","explanation":"世 (thế giới/thế hệ) + 面 (diện mạo/bề mặt).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌍","examples":[{"type":"basic","zh":"他见过世面。","pinyin":"Tā jiànguo shìmiàn.","vi":"Anh ấy đã từng trải sự đời."},{"type":"simple","zh":"第一次出国让这个农村孩子见了大世面。","pinyin":"Dìyīcì chūguó ràng zhè ge nóngcūn háizi jiànle dà shìmiàn.","vi":"Lần đầu ra nước ngoài giúp cậu bé nông thôn này được mở mang tầm mắt."},{"type":"compound","zh":"年轻人与其整天待在家里，不如出去见见世面。","pinyin":"Niánqīngrén yǔqí zhěngtiān dāi zài jiāli, bùrú chūqù jiàn jianshìmiàn.","vi":"Người trẻ thay vì suốt ngày ở nhà, chi bằng ra ngoài mở mang tầm mắt."}],"related":[{"hanzi":"见世面","pinyin":"jiànshìmiàn","vi":"mở mang tầm mắt"},{"hanzi":"见识","pinyin":"jiànshi","vi":"kiến thức hiểu biết"},{"hanzi":"阅历","pinyin":"yuèlì","vi":"từng trải"},{"hanzi":"社会","pinyin":"shèhuì","vi":"xã hội"}]},{"id":"视频会议","hanzi":"视频会议","pinyin":"shìpínhuìyì","meaning_vi":"họp trực tuyến qua video","explanation":"视 (tầm nhìn/coi trọng) + 频 (thường xuyên/tần suất) + 会 (biết (kỹ năng)) + 议 (nghị luận/hiệp nghị).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","cong-viec"],"image":"💻","examples":[{"type":"basic","zh":"下午开视频会议。","pinyin":"Xiàwǔ kāi shìpínhuìyì.","vi":"Chiều nay họp trực tuyến qua video."},{"type":"simple","zh":"总部和各地分公司每周一通过视频会议沟通。","pinyin":"Zǒngbù hé gèdì fēngōngsī měi Zhōuyì tōngguò shìpínhuìyì gōutōng.","vi":"Trụ sở chính và các chi nhánh trao đổi qua họp video vào thứ Hai hằng tuần."},{"type":"compound","zh":"视频会议虽然节省了出差费用，但是交流效果不如面对面。","pinyin":"Shìpínhuìyì suīrán jiéshěngle chūchāi fèiyòng, dànshì jiāoliú xiàoguǒ bùrú miànduìmiàn.","vi":"Họp video tuy tiết kiệm chi phí công tác, nhưng hiệu quả trao đổi không bằng gặp mặt trực tiếp."}],"related":[{"hanzi":"视频","pinyin":"shìpín","vi":"video"},{"hanzi":"线上","pinyin":"xiànshàng","vi":"trực tuyến"},{"hanzi":"远程","pinyin":"yuǎnchéng","vi":"từ xa"},{"hanzi":"会议","pinyin":"huìyì","vi":"cuộc họp"}],"traditional":"視頻會議"},{"id":"士气","hanzi":"士气","pinyin":"shìqì","meaning_vi":"sĩ khí, tinh thần chiến đấu","explanation":"士 (nhân sĩ/chiến sĩ) + 气 (khí phách/khí hậu).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🔥","examples":[{"type":"basic","zh":"全队士气高涨。","pinyin":"Quán duì shìqì gāozhǎng.","vi":"Tinh thần toàn đội dâng cao."},{"type":"simple","zh":"连输三场之后，队员们的士气十分低落。","pinyin":"Lián shū sān chǎng zhīhòu, duìyuánmen de shìqì shífēn dīluò.","vi":"Sau ba trận thua liên tiếp, tinh thần của các cầu thủ rất sa sút."},{"type":"compound","zh":"教练的一番讲话不但鼓舞了士气，而且稳定了军心。","pinyin":"Jiàoliàn de yìfān jiǎnghuà búdàn gǔwǔle shìqì, érqiě wěndìngle jūnxīn.","vi":"Bài nói của huấn luyện viên không chỉ cổ vũ tinh thần mà còn ổn định lòng quân."}],"related":[{"hanzi":"斗志","pinyin":"dòuzhì","vi":"ý chí chiến đấu"},{"hanzi":"鼓舞士气","pinyin":"gǔwǔshìqì","vi":"cổ vũ tinh thần"},{"hanzi":"士兵","pinyin":"shìbīng","vi":"binh lính"},{"hanzi":"低落","pinyin":"dīluò","vi":"sa sút"}],"traditional":"士氣"},{"id":"世人","hanzi":"世人","pinyin":"shìrén","meaning_vi":"người đời, nhân loại","explanation":"世 (thế giới/thế hệ) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"👥","examples":[{"type":"basic","zh":"世人都知道他。","pinyin":"Shìrén dōu zhīdào tā.","vi":"Người đời ai cũng biết ông ấy."},{"type":"simple","zh":"这位科学家的发现让世人重新认识了宇宙。","pinyin":"Zhè wèi kēxuéjiā de fāxiàn ràng shìrén chóngxīn rènshile yǔzhòu.","vi":"Phát hiện của nhà khoa học này giúp người đời nhận thức lại về vũ trụ."},{"type":"compound","zh":"虽然他生前穷困潦倒，但是去世后他的画作震惊了世人。","pinyin":"Suīrán tā shēngqián qióngkùnliáodǎo, dànshì qùshì hòu tā de huàzuò zhènjīngle shìrén.","vi":"Tuy lúc sinh thời ông nghèo khổ túng quẫn, nhưng sau khi qua đời tranh của ông đã làm chấn động người đời."}],"related":[{"hanzi":"世间","pinyin":"shìjiān","vi":"thế gian"},{"hanzi":"人类","pinyin":"rénlèi","vi":"nhân loại"},{"hanzi":"众人","pinyin":"zhòngrén","vi":"mọi người"},{"hanzi":"世界","pinyin":"shìjiè","vi":"thế giới"}]},{"id":"适时","hanzi":"适时","pinyin":"shìshí","meaning_vi":"kịp thời, đúng lúc","explanation":"适 (thích hợp/thoải mái) + 时 (thời đại/thời cơ).","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏰","examples":[{"type":"basic","zh":"雨下得很适时。","pinyin":"Yǔ xià de hěn shìshí.","vi":"Mưa rơi thật đúng lúc."},{"type":"simple","zh":"主持人适时地讲了个笑话缓解了尴尬。","pinyin":"Zhǔchírén shìshí de jiǎngle gè xiàohua huǎnjiěle gāngà.","vi":"Người dẫn chương trình kịp thời kể một câu chuyện cười để xoa dịu sự ngượng ngùng."},{"type":"compound","zh":"如果企业不能适时调整战略，就会被市场淘汰。","pinyin":"Rúguǒ qǐyè bù néng shìshí tiáozhěng zhànlüè, jiù huì bèi shìchǎng táotài.","vi":"Nếu doanh nghiệp không kịp thời điều chỉnh chiến lược thì sẽ bị thị trường đào thải."}],"related":[{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"},{"hanzi":"适当","pinyin":"shìdàng","vi":"thích đáng"},{"hanzi":"准时","pinyin":"zhǔnshí","vi":"đúng giờ"},{"hanzi":"不合时宜","pinyin":"bùhéshíyí","vi":"không hợp thời"}],"traditional":"適時"},{"id":"势头","hanzi":"势头","pinyin":"shìtóu","meaning_vi":"đà phát triển, xu thế","explanation":"势 (thế lực/xu thế) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["danh-tu"],"image":"📈","examples":[{"type":"basic","zh":"发展势头良好。","pinyin":"Fāzhǎn shìtóu liánghǎo.","vi":"Đà phát triển tốt."},{"type":"simple","zh":"今年新能源汽车的销量保持了强劲的增长势头。","pinyin":"Jīnnián xīnnéngyuánqìchē de xiāoliàng bǎochíle qiángjìng de zēngzhǎng shìtóu.","vi":"Năm nay doanh số ô tô năng lượng mới giữ đà tăng trưởng mạnh mẽ."},{"type":"compound","zh":"一看势头不对，他就赶紧把股票卖掉了。","pinyin":"Yí kàn shìtóu bú duì, tā jiù gǎnjǐn bǎ gǔpiào màidiào le.","vi":"Vừa thấy tình thế không ổn, anh ấy liền vội bán hết cổ phiếu."}],"related":[{"hanzi":"趋势","pinyin":"qūshì","vi":"xu thế"},{"hanzi":"劲头","pinyin":"jìntóu","vi":"sức lực, hăng hái"},{"hanzi":"发展势头","pinyin":"fāzhǎnshìtóu","vi":"đà phát triển"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình thế"}],"traditional":"勢頭"},{"id":"事宜","hanzi":"事宜","pinyin":"shìyí","meaning_vi":"những việc liên quan cần giải quyết","explanation":"事 (sự nghiệp/sự kiện) + 宜 (宜).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📌","examples":[{"type":"basic","zh":"商谈合作事宜。","pinyin":"Shāngtán hézuò shìyí.","vi":"Bàn bạc các việc liên quan đến hợp tác."},{"type":"simple","zh":"秘书正在安排董事长出访的相关事宜。","pinyin":"Mìshū zhèngzài ānpái dǒngshìzhǎng chūfǎng de xiāngguān shìyí.","vi":"Thư ký đang sắp xếp các công việc liên quan đến chuyến công du của chủ tịch."},{"type":"compound","zh":"如果您对报名事宜还有疑问，就请拨打这个电话咨询。","pinyin":"Rúguǒ nín duì bàomíng shìyí háiyǒu yíwèn, jiù qǐng bōdǎ zhè ge diànhuà zīxún.","vi":"Nếu quý vị còn thắc mắc về việc đăng ký, xin vui lòng gọi số này để được tư vấn."}],"related":[{"hanzi":"事项","pinyin":"shìxiàng","vi":"hạng mục công việc"},{"hanzi":"相关事宜","pinyin":"xiāngguānshìyí","vi":"các việc liên quan"},{"hanzi":"安排","pinyin":"ānpái","vi":"sắp xếp"},{"hanzi":"事务","pinyin":"shìwù","vi":"sự vụ"}]},{"id":"试用","hanzi":"试用","pinyin":"shìyòng","meaning_vi":"dùng thử; thử việc","explanation":"试 (thử) + 用 (vận dụng/công dụng).","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"可以免费试用。","pinyin":"Kěyǐ miǎnfèi shìyòng.","vi":"Có thể dùng thử miễn phí."},{"type":"simple","zh":"这款面霜的小样可以先拿回家试用一周。","pinyin":"Zhè kuǎn miànshuāng de xiǎoyàng kěyǐ xiān ná huíjiā shìyòng yìzhōu.","vi":"Mẫu thử kem dưỡng này có thể mang về nhà dùng thử một tuần trước."},{"type":"compound","zh":"你先试用几天，如果觉得好用，再决定买不买。","pinyin":"Nǐ xiān shìyòng jǐtiān, rúguǒ juéde hǎoyòng, zài juédìng mǎi bu mǎi.","vi":"Bạn cứ dùng thử vài hôm, nếu thấy dùng tốt thì hãy quyết định có mua hay không."}],"related":[{"hanzi":"试用期","pinyin":"shìyòngqī","vi":"thời gian thử việc"},{"hanzi":"试用装","pinyin":"shìyòngzhuāng","vi":"hàng dùng thử"},{"hanzi":"试穿","pinyin":"shìchuān","vi":"mặc thử"},{"hanzi":"免费试用","pinyin":"miǎnfèishìyòng","vi":"dùng thử miễn phí"}],"traditional":"試用"},{"id":"试用期","hanzi":"试用期","pinyin":"shìyòngqī","meaning_vi":"thời gian thử việc","explanation":"试用 (dùng thử) + 期 (kỳ hạn).","hsk_level":"7-9","tags":["danh-tu","cong-viec","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"试用期三个月。","pinyin":"Shìyòngqī sān gèyuè.","vi":"Thời gian thử việc là ba tháng."},{"type":"simple","zh":"她在试用期内就签下了两个大客户。","pinyin":"Tā zài shìyòngqī nèi jiù qiān xiàle liǎng gè dà kèhù.","vi":"Ngay trong thời gian thử việc, cô ấy đã ký được hai khách hàng lớn."},{"type":"compound","zh":"虽然试用期工资打八折，但是转正后福利很好。","pinyin":"Suīrán shìyòngqī gōngzī dǎ bā zhé, dànshì zhuǎnzhèng hòu fúlì hěn hǎo.","vi":"Tuy lương thời gian thử việc chỉ bằng 80%, nhưng sau khi lên chính thức phúc lợi rất tốt."}],"related":[{"hanzi":"转正","pinyin":"zhuǎnzhèng","vi":"chuyển chính thức"},{"hanzi":"实习期","pinyin":"shíxíqī","vi":"thời gian thực tập"},{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"入职","pinyin":"rùzhí","vi":"vào làm"}],"traditional":"試用期"},{"id":"市政","hanzi":"市政","pinyin":"shìzhèng","meaning_vi":"quản lý đô thị, công trình công cộng thành phố","explanation":"市 (thị trường/thành phố) + 政 (chính sách/chính trị).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"这是市政工程。","pinyin":"Zhè shì shìzhèng gōngchéng.","vi":"Đây là công trình đô thị."},{"type":"simple","zh":"市政部门连夜抢修了被暴雨冲坏的下水管道。","pinyin":"Shìzhèng bùmén liányè qiǎngxiūle bèi bàoyǔ chōng huài de xiàshuǐ guǎndào.","vi":"Cơ quan quản lý đô thị đã suốt đêm sửa gấp đường ống thoát nước bị mưa lớn làm hỏng."},{"type":"compound","zh":"因为市政设施年久失修，所以这条街一下雨就积水。","pinyin":"Yīnwèi shìzhèng shèshī nián jiǔ shīxiū, suǒyǐ zhè tiáo jiē yí xiàyǔ jiù jīshuǐ.","vi":"Vì cơ sở hạ tầng đô thị lâu năm không được tu sửa nên con phố này hễ mưa là ngập."}],"related":[{"hanzi":"市政府","pinyin":"shìzhèngfǔ","vi":"chính quyền thành phố"},{"hanzi":"市政工程","pinyin":"shìzhènggōngchéng","vi":"công trình đô thị"},{"hanzi":"城市建设","pinyin":"chéngshìjiànshè","vi":"xây dựng thành phố"},{"hanzi":"基础设施","pinyin":"jīchǔshèshī","vi":"cơ sở hạ tầng"}]},{"id":"势在必行","hanzi":"势在必行","pinyin":"shìzài-bìxíng","meaning_vi":"việc tất yếu phải làm ngay","explanation":"势 (thế lực/xu thế) + 在 (ở) + 必 (tất yếu/chắc chắn) + 行 (được).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"❗","examples":[{"type":"basic","zh":"改革势在必行。","pinyin":"Gǎigé shìzàibìxíng.","vi":"Cải cách là việc tất yếu phải làm."},{"type":"simple","zh":"面对严重的空气污染，治理工厂排放已经势在必行。","pinyin":"Miànduì yánzhòng de kōngqì wūrǎn, zhìlǐ gōngchǎng páifàng yǐjīng shìzàibìxíng.","vi":"Trước ô nhiễm không khí nghiêm trọng, việc xử lý khí thải nhà máy đã là tất yếu."},{"type":"compound","zh":"既然老城区的管道已经严重老化，更换工程就势在必行。","pinyin":"Jìrán lǎochéngqū de guǎndào yǐjīng yánzhòng lǎohuà, gēng huàn gōngchéng jiù shìzàibìxíng.","vi":"Đường ống ở khu phố cũ đã xuống cấp nghiêm trọng thì việc thay mới là điều bắt buộc."}],"related":[{"hanzi":"刻不容缓","pinyin":"kèbùrónghuǎn","vi":"không thể chậm trễ"},{"hanzi":"必然","pinyin":"bìrán","vi":"tất yếu"},{"hanzi":"迫在眉睫","pinyin":"pòzàiméijié","vi":"cận kề trước mắt"},{"hanzi":"当务之急","pinyin":"dāngwùzhījí","vi":"việc cấp bách"}],"traditional":"勢在必行"},{"id":"石碑","hanzi":"石碑","pinyin":"shíbēi","meaning_vi":"bia đá","explanation":"石 (đá) + 碑 (bia đá).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🗿","examples":[{"type":"basic","zh":"路边有块石碑。","pinyin":"Lùbiān yǒu kuài shíbēi.","vi":"Bên đường có một tấm bia đá."},{"type":"simple","zh":"寺庙门前立着一块刻满古字的石碑。","pinyin":"Sìmiào ménqián lìzhe yíkuài kè mǎn gǔzì de shíbēi.","vi":"Trước cổng chùa dựng một tấm bia đá khắc kín chữ cổ."},{"type":"compound","zh":"这块石碑虽然经历了千年风雨，但是上面的字依然清楚。","pinyin":"Zhè kuài shíbēi suīrán jīnglìle qiānnián fēngyǔ, dànshì shàngmiàn de zì yīrán qīngchu.","vi":"Tấm bia đá này tuy trải qua nghìn năm mưa gió, nhưng chữ trên đó vẫn còn rõ."}],"related":[{"hanzi":"墓碑","pinyin":"mùbēi","vi":"bia mộ"},{"hanzi":"纪念碑","pinyin":"jìniànbēi","vi":"đài tưởng niệm"},{"hanzi":"碑文","pinyin":"bēiwén","vi":"văn bia"},{"hanzi":"石头","pinyin":"shítou","vi":"hòn đá"}]},{"id":"实地","hanzi":"实地","pinyin":"shídì","meaning_vi":"thực địa, tại hiện trường","explanation":"实 (thực tế/thực chất) + 地 (地).","hsk_level":"7-9","tags":["pho-tu","dia-diem"],"image":"📍","examples":[{"type":"basic","zh":"我们去实地看看。","pinyin":"Wǒmen qù shídì kànkan.","vi":"Chúng ta đến tận nơi xem thử."},{"type":"simple","zh":"专家组到受灾村庄进行了实地考察。","pinyin":"Zhuānjiā zǔ dào shòuzāi cūnzhuāng jìnxíngle shídì kǎochá.","vi":"Tổ chuyên gia đã đến khảo sát thực địa ở ngôi làng bị thiên tai."},{"type":"compound","zh":"买房子之前，与其只看网上的照片，不如去实地看一看。","pinyin":"Mǎi fángzi zhīqián, yǔqí zhǐ kàn wǎngshang de zhàopiàn, bùrú qù shídì kànyikàn.","vi":"Trước khi mua nhà, thay vì chỉ xem ảnh trên mạng, chi bằng đến tận nơi xem thử."}],"related":[{"hanzi":"实地考察","pinyin":"shídìkǎochá","vi":"khảo sát thực địa"},{"hanzi":"现场","pinyin":"xiànchǎng","vi":"hiện trường"},{"hanzi":"调研","pinyin":"diàoyán","vi":"khảo sát nghiên cứu"},{"hanzi":"亲身","pinyin":"qīnshēn","vi":"đích thân"}],"traditional":"實地"},{"id":"实干","hanzi":"实干","pinyin":"shígàn","meaning_vi":"làm việc thực chất thiết thực","explanation":"实 (thực tế/thực chất) + 干 (干).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"他是实干家。","pinyin":"Tā shì shígànjiā.","vi":"Anh ấy là người làm việc thực chất."},{"type":"simple","zh":"这位村支书靠实干带领全村走上了致富路。","pinyin":"Zhè wèi cūn zhīshū kào shígàn dàilǐng quán cūn zǒushàngle zhìfù lù.","vi":"Vị bí thư chi bộ thôn này nhờ làm việc thiết thực đã dẫn cả làng đi lên con đường làm giàu."},{"type":"compound","zh":"与其整天空谈理想，不如脚踏实地地实干。","pinyin":"Yǔqí zhěngtiān kōngtán lǐxiǎng, bùrú jiǎotàshídì de shígàn.","vi":"Thay vì suốt ngày nói suông về lý tưởng, chi bằng chân đạp đất mà làm việc thực chất."}],"related":[{"hanzi":"苦干","pinyin":"kǔgàn","vi":"làm việc chăm chỉ"},{"hanzi":"实干家","pinyin":"shígànjiā","vi":"người làm thực tế"},{"hanzi":"空谈","pinyin":"kōngtán","vi":"nói suông"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thực"}],"traditional":"實幹"},{"id":"时局","hanzi":"时局","pinyin":"shíjú","meaning_vi":"thời cuộc, tình hình chính trị","explanation":"时 (thời đại/thời cơ) + 局 (cục diện/cơ quan).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌍","examples":[{"type":"basic","zh":"当时时局动荡。","pinyin":"Dāngshí shíjú dòngdàng.","vi":"Thời cuộc lúc đó rối ren."},{"type":"simple","zh":"老人每天看报纸关心着国内外的时局。","pinyin":"Lǎorén měitiān kàn bàozhǐ guānxīnzhe guónèiwài de shíjú.","vi":"Ông cụ ngày nào cũng đọc báo theo dõi thời cuộc trong và ngoài nước."},{"type":"compound","zh":"因为时局不稳，所以很多商人把资金转移到了国外。","pinyin":"Yīnwèi shíjú bùwěn, suǒyǐ hěn duō shāngrén bǎ zījīn zhuǎnyí dàole guówài.","vi":"Vì thời cuộc bất ổn nên nhiều thương nhân đã chuyển vốn ra nước ngoài."}],"related":[{"hanzi":"局势","pinyin":"júshì","vi":"cục diện"},{"hanzi":"形势","pinyin":"xíngshì","vi":"tình thế"},{"hanzi":"时事","pinyin":"shíshì","vi":"thời sự"},{"hanzi":"政局","pinyin":"zhèngjú","vi":"tình hình chính trị"}],"traditional":"時局"},{"id":"实况","hanzi":"实况","pinyin":"shíkuàng","meaning_vi":"tình hình thực tế, tường thuật trực tiếp","explanation":"实 (thực tế/thực chất) + 况 (tình hình/huống chi).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"📺","examples":[{"type":"basic","zh":"电视台直播比赛实况。","pinyin":"Diànshìtái zhíbō bǐsài shíkuàng.","vi":"Đài truyền hình tường thuật trực tiếp trận đấu."},{"type":"simple","zh":"记者在台风登陆现场报道了实况。","pinyin":"Jìzhě zài táifēng dēnglù xiànchǎng bàodàole shíkuàng.","vi":"Phóng viên đưa tin tình hình thực tế tại hiện trường bão đổ bộ."},{"type":"compound","zh":"虽然没能去现场，但是我在网上看了演唱会的实况转播。","pinyin":"Suīrán méi néng qù xiànchǎng, dànshì wǒ zài wǎngshang kànle yǎnchànghuì de shíkuàng zhuǎnbō.","vi":"Tuy không đến được hiện trường, nhưng tôi đã xem truyền hình trực tiếp buổi hòa nhạc trên mạng."}],"related":[{"hanzi":"实况转播","pinyin":"shíkuàngzhuǎnbō","vi":"truyền hình trực tiếp"},{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"现场","pinyin":"xiànchǎng","vi":"hiện trường"},{"hanzi":"情况","pinyin":"qíngkuàng","vi":"tình hình"}],"traditional":"實況"},{"id":"石窟","hanzi":"石窟","pinyin":"shíkū","meaning_vi":"hang đá điêu khắc (Long Môn/Vân Cương)","explanation":"石 (đá) + 窟 (hang động).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏛️","examples":[{"type":"basic","zh":"我们参观了石窟。","pinyin":"Wǒmen cānguānle shíkū.","vi":"Chúng tôi đã tham quan hang đá."},{"type":"simple","zh":"龙门石窟里保存着十万多尊佛像。","pinyin":"Lóngménshíkū li bǎocúnzhe shíwàn duō zūn fóxiàng.","vi":"Trong hang đá Long Môn còn lưu giữ hơn mười vạn pho tượng Phật."},{"type":"compound","zh":"因为洞内壁画很脆弱，所以有些石窟只能限量参观。","pinyin":"Yīnwèi dòng nèi bìhuà hěn cuìruò, suǒyǐ yǒuxiē shíkū zhǐnéng xiànliàng cānguān.","vi":"Vì bích họa trong hang rất dễ hư hại nên một số hang đá chỉ cho tham quan hạn chế số lượng."}],"related":[{"hanzi":"龙门石窟","pinyin":"Lóngménshíkū","vi":"hang đá Long Môn"},{"hanzi":"云冈石窟","pinyin":"Yúngāngshíkū","vi":"hang đá Vân Cương"},{"hanzi":"莫高窟","pinyin":"Mògāokū","vi":"hang Mạc Cao"},{"hanzi":"佛像","pinyin":"fóxiàng","vi":"tượng Phật"}]},{"id":"实力派","hanzi":"实力派","pinyin":"shílìpài","meaning_vi":"phái thực lực (diễn viên/ca sĩ có tài năng thật)","explanation":"实 (thực tế/thực chất) + 力 (sức mạnh/nỗ lực) + 派 (cử đi).","hsk_level":"7-9","tags":["danh-tu","giai-tri","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"他是实力派歌手。","pinyin":"Tā shì shílìpài gēshǒu.","vi":"Anh ấy là ca sĩ thực lực."},{"type":"simple","zh":"这部电影请来了好几位实力派演员。","pinyin":"Zhè bù diànyǐng qǐng láile hǎojǐ wèi shílìpài yǎnyuán.","vi":"Bộ phim này mời được nhiều diễn viên thực lực."},{"type":"compound","zh":"她虽然不是偶像明星，但是是公认的实力派。","pinyin":"Tā suīrán bú shì ǒuxiàng míngxīng, dànshì shì gōngrèn de shílìpài.","vi":"Cô ấy tuy không phải ngôi sao thần tượng, nhưng là người có thực lực được công nhận."}],"related":[{"hanzi":"偶像派","pinyin":"ǒuxiàngpài","vi":"phái thần tượng"},{"hanzi":"实力","pinyin":"shílì","vi":"thực lực"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"演技","pinyin":"yǎnjì","vi":"diễn xuất"}],"traditional":"實力派"},{"id":"时令","hanzi":"时令","pinyin":"shílìng","meaning_vi":"thời tiết theo mùa, đúng mùa","explanation":"时 (thời đại/thời cơ) + 令 (mệnh lệnh/khiến cho).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","an-uong"],"image":"🌸","examples":[{"type":"basic","zh":"多吃时令蔬菜。","pinyin":"Duō chī shílìng shūcài.","vi":"Hãy ăn nhiều rau theo mùa."},{"type":"simple","zh":"这家餐馆的菜单每个月都会根据时令更换。","pinyin":"Zhè jiā cānguǎn de càidān měi gèyuè dōuhuì gēnjù shílìng gēng huàn.","vi":"Thực đơn của quán ăn này thay đổi hằng tháng theo mùa."},{"type":"compound","zh":"时令水果不但新鲜，而且价格比反季节的便宜。","pinyin":"Shílìng shuǐguǒ búdàn xīnxiān, érqiě jiàgé bǐ fǎnjìjié de piányi.","vi":"Trái cây đúng mùa không chỉ tươi mà giá còn rẻ hơn trái cây trái mùa."}],"related":[{"hanzi":"季节","pinyin":"jìjié","vi":"mùa"},{"hanzi":"应季","pinyin":"yìngjì","vi":"đúng mùa"},{"hanzi":"时令水果","pinyin":"shílìngshuǐguǒ","vi":"trái cây theo mùa"},{"hanzi":"节气","pinyin":"jiéqi","vi":"tiết khí"}],"traditional":"時令"},{"id":"实名制","hanzi":"实名制","pinyin":"shímíngzhì","meaning_vi":"chế độ đăng ký tên thật","explanation":"实 (thực tế/thực chất) + 名 (danh tiếng/nổi tiếng) + 制 (chế độ/kiềm chế).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","xa-hoi"],"image":"🪪","examples":[{"type":"basic","zh":"火车票实行实名制。","pinyin":"Huǒchēpiào shíxíng shímíngzhì.","vi":"Vé tàu hỏa áp dụng chế độ tên thật."},{"type":"simple","zh":"手机号码实名制有效减少了诈骗电话。","pinyin":"Shǒujī hàomǎ shímíngzhì yǒuxiào jiǎnshǎole zhàpiàn diànhuà.","vi":"Chế độ đăng ký tên thật cho số điện thoại đã giảm hiệu quả các cuộc gọi lừa đảo."},{"type":"compound","zh":"自从网络游戏推行实名制，未成年人就不能整夜玩游戏了。","pinyin":"Zìcóng wǎngluò yóuxì tuīxíng shímíngzhì, wèichéngniánrén jiù bù néng zhěngyè wán yóuxì le.","vi":"Từ khi game online áp dụng chế độ tên thật, trẻ vị thành niên không thể chơi game thâu đêm nữa."}],"related":[{"hanzi":"实名认证","pinyin":"shímíngrènzhèng","vi":"xác thực tên thật"},{"hanzi":"身份证","pinyin":"shēnfènzhèng","vi":"chứng minh thư"},{"hanzi":"匿名","pinyin":"nìmíng","vi":"nặc danh"},{"hanzi":"登记","pinyin":"dēngjì","vi":"đăng ký"}],"traditional":"實名制"},{"id":"十拿九稳","hanzi":"十拿九稳","pinyin":"shíná-jiǔwěn","meaning_vi":"chắc chắn đến chín mươi phần trăm","explanation":"十 (số 10) + 拿 (cầm) + 九 (số 9) + 稳 (ổn định/vững vàng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💯","examples":[{"type":"basic","zh":"这事十拿九稳。","pinyin":"Zhè shì shínájiǔwěn.","vi":"Việc này chắc chắn đến chín phần."},{"type":"simple","zh":"他觉得这次面试已经十拿九稳了。","pinyin":"Tā juéde zhè cì miànshì yǐjīng shínájiǔwěn le.","vi":"Anh ấy cảm thấy lần phỏng vấn này đã chắc chín phần mười."},{"type":"compound","zh":"即使你觉得十拿九稳，也不要提前庆祝。","pinyin":"Jíshǐ nǐ juéde shínájiǔwěn, yě bú yào tíqián qìngzhù.","vi":"Dù bạn thấy đã chắc chín phần mười cũng đừng ăn mừng sớm."}],"related":[{"hanzi":"稳操胜券","pinyin":"wěncāoshèngquàn","vi":"nắm chắc phần thắng"},{"hanzi":"万无一失","pinyin":"wànwúyìshī","vi":"chắc chắn không sai"},{"hanzi":"有把握","pinyin":"yǒubǎwò","vi":"nắm chắc"},{"hanzi":"没把握","pinyin":"méibǎwò","vi":"không nắm chắc"}],"traditional":"十拿九穩"},{"id":"石器时代","hanzi":"石器时代","pinyin":"Shíqìshídài","meaning_vi":"thời kỳ Đồ Đá","explanation":"石 (đá) + 器 (thiết bị/cơ quan) + 时 (thời đại/thời cơ) + 代 (代).","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🪨","examples":[{"type":"basic","zh":"那是石器时代。","pinyin":"Nàshì Shíqìshídài.","vi":"Đó là thời kỳ đồ đá."},{"type":"simple","zh":"考古学家在这个山洞里发现了石器时代的工具。","pinyin":"Kǎogǔxué jiā zài zhè ge shāndòng li fāxiànle Shíqìshídài de gōngjù.","vi":"Các nhà khảo cổ phát hiện công cụ thời đồ đá trong hang núi này."},{"type":"compound","zh":"石器时代的人虽然没有文字，但是已经会在岩壁上画画了。","pinyin":"Shíqìshídài de rén suīrán méiyǒu wénzì, dànshì yǐjīng huì zài yán bì shang huàhuà le.","vi":"Người thời đồ đá tuy chưa có chữ viết, nhưng đã biết vẽ tranh trên vách đá."}],"related":[{"hanzi":"青铜器","pinyin":"qīngtóngqì","vi":"đồ đồng"},{"hanzi":"原始社会","pinyin":"yuánshǐshèhuì","vi":"xã hội nguyên thủy"},{"hanzi":"远古","pinyin":"yuǎngǔ","vi":"thời thượng cổ"},{"hanzi":"考古","pinyin":"kǎogǔ","vi":"khảo cổ"}],"traditional":"石器時代"},{"id":"实属","hanzi":"实属","pinyin":"shíshǔ","meaning_vi":"thực sự là (văn viết)","explanation":"实 (thực tế/thực chất) + 属 (thuộc về).","hsk_level":"7-9","tags":["dong-tu"],"image":"❗","examples":[{"type":"basic","zh":"此事实属罕见。","pinyin":"Cǐshì shíshǔ hǎnjiàn.","vi":"Việc này thực sự hiếm thấy."},{"type":"simple","zh":"他能在三天内完成这项任务实属不易。","pinyin":"Tā néng zài sān tiān nèi wánchéng zhè xiàng rènwù shíshǔ búyì.","vi":"Anh ấy hoàn thành nhiệm vụ này trong ba ngày thực sự không dễ."},{"type":"compound","zh":"他这么做虽然实属无奈，但是确实伤害了朋友。","pinyin":"Tā zhème zuò suīrán shíshǔ wúnài, dànshì quèshí shānghàile péngyou.","vi":"Anh ấy làm vậy tuy thực sự là bất đắc dĩ, nhưng quả thật đã làm tổn thương bạn bè."}],"related":[{"hanzi":"确实","pinyin":"quèshí","vi":"quả thực"},{"hanzi":"实在","pinyin":"shízài","vi":"thực sự"},{"hanzi":"实属不易","pinyin":"shíshǔbúyì","vi":"thực sự không dễ"},{"hanzi":"的确","pinyin":"díquè","vi":"đích thực"}],"traditional":"實屬"},{"id":"时速","hanzi":"时速","pinyin":"shísù","meaning_vi":"tốc độ mỗi giờ (km/h)","explanation":"时 (thời đại/thời cơ) + 速 (nhanh chóng/tốc độ).","hsk_level":"7-9","tags":["danh-tu","giao-thong","so-luong"],"image":"🚄","examples":[{"type":"basic","zh":"时速一百公里。","pinyin":"Shísù yī bǎi gōnglǐ.","vi":"Tốc độ một trăm cây số mỗi giờ."},{"type":"simple","zh":"这条高铁线路的最高时速可达三百五十公里。","pinyin":"Zhè tiáo gāotiě xiànlù de zuì gāo shí sùkědá sān bǎi wǔshí gōnglǐ.","vi":"Tốc độ tối đa của tuyến tàu cao tốc này có thể đạt 350 km/h."},{"type":"compound","zh":"如果在市区时速超过六十公里，就会被罚款扣分。","pinyin":"Rúguǒ zài shìqū shísù chāoguò liùshí gōnglǐ, jiù huì bèi fákuǎn kòufēn.","vi":"Nếu trong nội thành chạy quá 60 km/h thì sẽ bị phạt tiền và trừ điểm."}],"related":[{"hanzi":"速度","pinyin":"sùdù","vi":"tốc độ"},{"hanzi":"公里","pinyin":"gōnglǐ","vi":"ki-lô-mét"},{"hanzi":"限速","pinyin":"xiànsù","vi":"giới hạn tốc độ"},{"hanzi":"超速","pinyin":"chāosù","vi":"vượt tốc độ"}],"traditional":"時速"},{"id":"实体经济","hanzi":"实体经济","pinyin":"shítǐjīngjì","meaning_vi":"kinh tế thực (sản xuất hàng hóa/dịch vụ thực)","explanation":"实体 (thực thể – có thật, hữu hình) + 经济 (kinh tế) → nền kinh tế sản xuất hàng hóa, dịch vụ thực, đối lập với 虚拟经济 (kinh tế ảo, tài chính).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"要支持实体经济。","pinyin":"Yào zhīchí shítǐjīngjì.","vi":"Cần hỗ trợ kinh tế thực."},{"type":"simple","zh":"制造业是一个国家实体经济的根基。","pinyin":"Zhìzàoyè shì yí gè guójiā shítǐjīngjì de gēnjī.","vi":"Ngành chế tạo là nền móng của kinh tế thực của một quốc gia."},{"type":"compound","zh":"如果资金都流向了股市楼市，实体经济就会缺血。","pinyin":"Rúguǒ zījīn dōu liúxiàngle gǔshì lóushì, shítǐjīngjì jiù huì quēxuè.","vi":"Nếu vốn đều đổ vào chứng khoán và bất động sản, kinh tế thực sẽ bị thiếu máu."}],"related":[{"hanzi":"虚拟经济","pinyin":"xūnǐjīngjì","vi":"kinh tế ảo"},{"hanzi":"制造业","pinyin":"zhìzàoyè","vi":"ngành chế tạo"},{"hanzi":"实体店","pinyin":"shítǐdiàn","vi":"cửa hàng thực"},{"hanzi":"经济","pinyin":"jīngjì","vi":"kinh tế"}],"traditional":"實體經濟"},{"id":"实效","hanzi":"实效","pinyin":"shíxiào","meaning_vi":"hiệu quả thực tế","explanation":"实 (thực tế/thực chất) + 效 (hiệu quả/hiệu suất).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"📈","examples":[{"type":"basic","zh":"工作要讲求实效。","pinyin":"Gōngzuò yào jiǎngqiú shíxiào.","vi":"Làm việc phải chú trọng hiệu quả thực tế."},{"type":"simple","zh":"这种注重实效的培训深受员工欢迎。","pinyin":"Zhè zhǒng zhùzhòng shíxiào de péixùn shēnshòu yuángōng huānyíng.","vi":"Kiểu đào tạo chú trọng hiệu quả thực tế này rất được nhân viên hoan nghênh."},{"type":"compound","zh":"会议开得再多，如果没有实效，也只是浪费时间。","pinyin":"Huìyì kāi de zài duō, rúguǒ méiyǒu shíxiào, yě zhǐshì làngfèi shíjiān.","vi":"Họp nhiều đến mấy mà không có hiệu quả thực tế thì cũng chỉ là phí thời gian."}],"related":[{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"hiệu quả"},{"hanzi":"成效","pinyin":"chéngxiào","vi":"thành quả"},{"hanzi":"实际","pinyin":"shíjì","vi":"thực tế"},{"hanzi":"讲求实效","pinyin":"jiǎngqiúshíxiào","vi":"chú trọng hiệu quả"}],"traditional":"實效"},{"id":"时效性","hanzi":"时效性","pinyin":"shíxiàoxìng","meaning_vi":"tính thời sự, tính kịp thời","explanation":"时 (thời đại/thời cơ) + 效 (hiệu quả/hiệu suất) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"⏱️","examples":[{"type":"basic","zh":"新闻讲究时效性。","pinyin":"Xīnwén jiǎngjiu shíxiàoxìng.","vi":"Tin tức chú trọng tính kịp thời."},{"type":"simple","zh":"快递公司特别重视生鲜包裹的时效性。","pinyin":"Kuàidì gōngsī tèbié zhòngshì shēngxiān bāoguǒ de shíxiàoxìng.","vi":"Công ty chuyển phát đặc biệt coi trọng tính kịp thời của các kiện hàng tươi sống."},{"type":"compound","zh":"因为股市消息时效性很强，所以晚一分钟就可能错过机会。","pinyin":"Yīnwèi gǔshì xiāoxi shíxiàoxìng hěn qiáng, suǒyǐ wǎn yì fēnzhōng jiù kěnéng cuòguò jīhuì.","vi":"Vì tin tức chứng khoán có tính thời điểm rất cao nên chậm một phút cũng có thể lỡ cơ hội."}],"related":[{"hanzi":"时效","pinyin":"shíxiào","vi":"hiệu lực thời gian"},{"hanzi":"及时","pinyin":"jíshí","vi":"kịp thời"},{"hanzi":"新闻","pinyin":"xīnwén","vi":"tin tức"},{"hanzi":"有效期","pinyin":"yǒuxiàoqī","vi":"thời hạn hiệu lực"}],"traditional":"時效性"},{"id":"时兴","hanzi":"时兴","pinyin":"shíxīng","meaning_vi":"thịnh hành, hợp mốt","explanation":"时 (thời đại/thời cơ) + 兴 (hưng thịnh/hứng thú).","hsk_level":"7-9","tags":["tinh-tu","trang-phuc"],"image":"👗","examples":[{"type":"basic","zh":"现在时兴网购。","pinyin":"Xiànzài shíxīng wǎnggòu.","vi":"Bây giờ mua sắm online đang thịnh hành."},{"type":"simple","zh":"今年夏天特别时兴这种宽松的亚麻衬衫。","pinyin":"Jīnnián xiàtiān tèbié shíxīng zhè zhǒng kuānsōng de yàmá chènshān.","vi":"Mùa hè năm nay kiểu áo sơ mi vải lanh rộng này đặc biệt thịnh hành."},{"type":"compound","zh":"虽然这种发型现在很时兴，但是不一定适合你。","pinyin":"Suīrán zhè zhǒng fàxíng xiànzài hěn shíxīng, dànshì bù yídìng shìhé nǐ.","vi":"Tuy kiểu tóc này đang rất thịnh hành, nhưng chưa chắc đã hợp với bạn."}],"related":[{"hanzi":"时髦","pinyin":"shímáo","vi":"mốt, sành điệu"},{"hanzi":"流行","pinyin":"liúxíng","vi":"thịnh hành"},{"hanzi":"时尚","pinyin":"shíshàng","vi":"thời thượng"},{"hanzi":"过时","pinyin":"guòshí","vi":"lỗi thời"}],"traditional":"時興"},{"id":"实验数据","hanzi":"实验数据","pinyin":"shíyànshùjù","meaning_vi":"số liệu thực nghiệm","explanation":"实 (thực tế/thực chất) + 验 (kiểm nghiệm/nghiệm thu) + 数 (đếm) + 据 (căn cứ/chiếm giữ).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"📊","examples":[{"type":"basic","zh":"实验数据有误。","pinyin":"Shíyànshùjù yǒu wù.","vi":"Số liệu thực nghiệm có sai sót."},{"type":"simple","zh":"研究生连夜整理了三个月的实验数据。","pinyin":"Yánjiūshēng liányè zhěnglǐle sān gèyuè de shíyànshùjù.","vi":"Nghiên cứu sinh thức trắng đêm chỉnh lý số liệu thực nghiệm của ba tháng."},{"type":"compound","zh":"如果实验数据被人篡改，整个研究结论就不可信了。","pinyin":"Rúguǒ shíyànshùjù bèi rén cuàngǎi, zhěnggè yánjiū jiélùn jiù bù kěxìn le.","vi":"Nếu số liệu thực nghiệm bị sửa đổi thì toàn bộ kết luận nghiên cứu không còn đáng tin."}],"related":[{"hanzi":"实验","pinyin":"shíyàn","vi":"thí nghiệm"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"实验室","pinyin":"shíyànshì","vi":"phòng thí nghiệm"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"}],"traditional":"實驗數據"},{"id":"实战","hanzi":"实战","pinyin":"shízhàn","meaning_vi":"thực chiến, thực hành thực tế","explanation":"实 (thực tế/thực chất) + 战 (chiến đấu/chiến lược).","hsk_level":"7-9","tags":["danh-tu","the-thao","cong-viec"],"image":"⚔️","examples":[{"type":"basic","zh":"他缺少实战经验。","pinyin":"Tā quēshǎo shízhàn jīngyàn.","vi":"Anh ấy thiếu kinh nghiệm thực chiến."},{"type":"simple","zh":"新兵们在山区进行了为期一周的实战演练。","pinyin":"Xīnbīngmen zài shānqū jìnxíngle wéiqī yìzhōu de shízhàn yǎnliàn.","vi":"Các tân binh tiến hành diễn tập thực chiến một tuần ở vùng núi."},{"type":"compound","zh":"即使理论学得再扎实，也要通过实战来检验。","pinyin":"Jíshǐ lǐlùn xué de zài zhāshi, yě yào tōngguò shízhàn lái jiǎnyàn.","vi":"Dù lý thuyết học vững đến đâu cũng phải được kiểm nghiệm qua thực chiến."}],"related":[{"hanzi":"实践","pinyin":"shíjiàn","vi":"thực tiễn"},{"hanzi":"演习","pinyin":"yǎnxí","vi":"diễn tập"},{"hanzi":"实战经验","pinyin":"shízhànjīngyàn","vi":"kinh nghiệm thực chiến"},{"hanzi":"纸上谈兵","pinyin":"zhǐshàngtánbīng","vi":"bàn binh trên giấy"}],"traditional":"實戰"},{"id":"十二星座","hanzi":"十二星座","pinyin":"shí'èrxīngzuò","meaning_vi":"12 cung hoàng đạo","explanation":"十二 + 星座 (chòm sao).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"♈","examples":[{"type":"basic","zh":"你了解十二星座吗？","pinyin":"Nǐ liǎojiě shí'èrxīngzuò ma?","vi":"Bạn có hiểu về 12 cung hoàng đạo không?"},{"type":"simple","zh":"她能说出十二星座各自对应的日期。","pinyin":"Tā néng shuōchū shí'èrxīngzuò gèzì duìyìng de rìqī.","vi":"Cô ấy có thể nói ra khoảng ngày tương ứng của từng cung trong 12 cung hoàng đạo."},{"type":"compound","zh":"很多年轻人虽然爱聊十二星座，但是并不真的相信它。","pinyin":"Hěn duō niánqīngrén suīrán ài liáo shí'èrxīngzuò, dànshì bìngbù zhēn de xiāngxìn tā.","vi":"Nhiều người trẻ tuy thích bàn về 12 cung hoàng đạo, nhưng không thật sự tin vào nó."}],"related":[{"hanzi":"星座","pinyin":"xīngzuò","vi":"chòm sao"},{"hanzi":"十二生肖","pinyin":"shí'èrshēngxiào","vi":"mười hai con giáp"},{"hanzi":"白羊座","pinyin":"Báiyángzuò","vi":"cung Bạch Dương"},{"hanzi":"运势","pinyin":"yùnshì","vi":"vận thế"}]},{"id":"受挫","hanzi":"受挫","pinyin":"shòucuò","meaning_vi":"gặp trắc trở thất bại","explanation":"受 (chịu đựng/tiếp nhận) + 挫 (trắc trở/đánh bại).","hsk_level":"7-9","tags":["dong-tu"],"image":"📉","examples":[{"type":"basic","zh":"他的计划受挫了。","pinyin":"Tā de jìhuà shòucuò le.","vi":"Kế hoạch của anh ấy gặp trắc trở."},{"type":"simple","zh":"连续三次创业受挫后，他回老家开了一家面馆。","pinyin":"Liánxù sāncì chuàngyè shòucuò hòu, tā huílǎojiā kāile yìjiā miànguǎn.","vi":"Sau ba lần khởi nghiệp liên tiếp thất bại, anh ấy về quê mở một quán mì."},{"type":"compound","zh":"孩子一旦受挫，父母就应该多鼓励，而不是批评。","pinyin":"Háizi yídàn shòucuò, fùmǔ jiù yīnggāi duō gǔlì, ér bú shì pīpíng.","vi":"Một khi con gặp thất bại, cha mẹ nên động viên nhiều hơn chứ không phải phê bình."}],"related":[{"hanzi":"挫折","pinyin":"cuòzhé","vi":"thất bại trắc trở"},{"hanzi":"碰壁","pinyin":"pèngbì","vi":"gặp trở ngại"},{"hanzi":"失败","pinyin":"shībài","vi":"thất bại"},{"hanzi":"打击","pinyin":"dǎjī","vi":"đả kích"}]},{"id":"受访","hanzi":"受访","pinyin":"shòufǎng","meaning_vi":"trả lời phỏng vấn","explanation":"受 (chịu đựng/tiếp nhận) + 访 (访).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎙️","examples":[{"type":"basic","zh":"他拒绝受访。","pinyin":"Tā jùjué shòufǎng.","vi":"Anh ấy từ chối trả lời phỏng vấn."},{"type":"simple","zh":"受访的市民中有七成支持延长地铁运营时间。","pinyin":"Shòufǎng de shìmín zhōng yǒu qī chéng zhīchí yáncháng dìtiě yùnyíng shíjiān.","vi":"Trong số người dân được phỏng vấn, 70% ủng hộ kéo dài giờ hoạt động tàu điện ngầm."},{"type":"compound","zh":"这位导演很少受访，但是这次却主动谈起了新片。","pinyin":"Zhè wèi dǎoyǎn hěn shǎo shòufǎng, dànshì zhè cì què zhǔdòng tánqǐle xīn piàn.","vi":"Vị đạo diễn này hiếm khi nhận phỏng vấn, nhưng lần này lại chủ động nói về phim mới."}],"related":[{"hanzi":"采访","pinyin":"cǎifǎng","vi":"phỏng vấn"},{"hanzi":"受访者","pinyin":"shòufǎngzhě","vi":"người được phỏng vấn"},{"hanzi":"记者","pinyin":"jìzhě","vi":"phóng viên"},{"hanzi":"访谈","pinyin":"fǎngtán","vi":"cuộc phỏng vấn"}],"traditional":"受訪"},{"id":"售后服务","hanzi":"售后服务","pinyin":"shòuhòufúwù","meaning_vi":"dịch vụ hậu mãi, chăm sóc sau bán hàng","explanation":"售后 (thụ hậu – sau khi bán) + 服务 (phục vụ – dịch vụ) → dịch vụ hậu mãi như bảo hành, sửa chữa, đổi trả sau khi bán hàng.","hsk_level":"7-9","tags":["danh-tu","mua-sam","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"售后服务很好。","pinyin":"Shòuhòufúwù hěn hǎo.","vi":"Dịch vụ hậu mãi rất tốt."},{"type":"simple","zh":"这家电器商城承诺提供三年免费售后服务。","pinyin":"Zhè jiā diànqì shāngchéng chéngnuò tígōng sān nián miǎnfèi shòuhòufúwù.","vi":"Trung tâm điện máy này cam kết cung cấp ba năm dịch vụ hậu mãi miễn phí."},{"type":"compound","zh":"网购虽然便宜，但是售后服务有时候很麻烦。","pinyin":"Wǎnggòu suīrán piányi, dànshì shòuhòufúwù yǒushíhou hěn máfan.","vi":"Mua hàng online tuy rẻ, nhưng dịch vụ hậu mãi đôi khi rất phiền phức."}],"related":[{"hanzi":"售前","pinyin":"shòuqián","vi":"trước bán hàng"},{"hanzi":"保修","pinyin":"bǎoxiū","vi":"bảo hành"},{"hanzi":"客服","pinyin":"kèfú","vi":"chăm sóc khách hàng"},{"hanzi":"退换货","pinyin":"tuìhuànhuò","vi":"đổi trả hàng"}],"traditional":"售後服務"},{"id":"授意","hanzi":"授意","pinyin":"shòuyì","meaning_vi":"ra hiệu ý đồ, chỉ đạo ngầm","explanation":"授 (truyền thụ/trao tặng) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤫","examples":[{"type":"basic","zh":"这是老板授意的。","pinyin":"Zhè shì lǎobǎn shòuyì de.","vi":"Việc này do sếp ngầm chỉ đạo."},{"type":"simple","zh":"他在上级的授意下删除了那份文件。","pinyin":"Tā zài shàngjí de shòuyì xià shānchúle nà fèn wénjiàn.","vi":"Anh ta xóa tài liệu đó theo sự ngầm chỉ đạo của cấp trên."},{"type":"compound","zh":"如果没有人授意，他一个小职员就不敢这么做。","pinyin":"Rúguǒ méiyǒu rén shòuyì, tā yí gè xiǎo zhíyuán jiù bù gǎn zhème zuò.","vi":"Nếu không có người ngầm chỉ đạo, một nhân viên quèn như anh ta không dám làm vậy."}],"related":[{"hanzi":"指使","pinyin":"zhǐshǐ","vi":"sai khiến xúi giục"},{"hanzi":"暗示","pinyin":"ànshì","vi":"ám chỉ"},{"hanzi":"指示","pinyin":"zhǐshì","vi":"chỉ thị"},{"hanzi":"示意","pinyin":"shìyì","vi":"ra hiệu"}]},{"id":"受益人","hanzi":"受益人","pinyin":"shòuyìrén","meaning_vi":"người thụ hưởng (bảo hiểm/di chúc)","explanation":"受益 (thụ ích – nhận lợi ích) + 人 (nhân – người) → người được hưởng lợi, người thụ hưởng trong hợp đồng bảo hiểm, di chúc, quỹ tín thác.","hsk_level":"7-9","tags":["danh-tu","phap-luat","tien-te"],"image":"👤","examples":[{"type":"basic","zh":"她是唯一受益人。","pinyin":"Tā shì wéiyī shòuyìrén.","vi":"Cô ấy là người thụ hưởng duy nhất."},{"type":"simple","zh":"他在保险合同上把女儿写成了受益人。","pinyin":"Tā zài bǎoxiǎn hétóng shang bǎ nǚ'ér xiě chéngle shòuyìrén.","vi":"Anh ấy ghi con gái là người thụ hưởng trong hợp đồng bảo hiểm."},{"type":"compound","zh":"如果投保人去世，受益人就可以领取全部保险金。","pinyin":"Rúguǒ tóubǎorén qùshì, shòuyìrén jiù kěyǐ lǐngqǔ quánbù bǎoxiǎn jīn.","vi":"Nếu người mua bảo hiểm qua đời, người thụ hưởng sẽ được nhận toàn bộ tiền bảo hiểm."}],"related":[{"hanzi":"受益","pinyin":"shòuyì","vi":"được lợi"},{"hanzi":"保险","pinyin":"bǎoxiǎn","vi":"bảo hiểm"},{"hanzi":"遗嘱","pinyin":"yízhǔ","vi":"di chúc"},{"hanzi":"继承人","pinyin":"jìchéngrén","vi":"người thừa kế"}]},{"id":"受众","hanzi":"受众","pinyin":"shòuzhòng","meaning_vi":"khán thính giả, đối tượng tiếp nhận","explanation":"受 (chịu đựng/tiếp nhận) + 众 (quần chúng/đông đảo).","hsk_level":"7-9","tags":["danh-tu","giai-tri","cong-viec"],"image":"👥","examples":[{"type":"basic","zh":"这本书受众很广。","pinyin":"Zhè běn shū shòuzhòng hěn guǎng.","vi":"Cuốn sách này có lượng độc giả rất rộng."},{"type":"simple","zh":"这档节目的主要受众是二十岁左右的大学生。","pinyin":"Zhè dàng jié mùde zhǔyào shòuzhòng shì èrshí suì zuǒyòu de dàxuéshēng.","vi":"Khán giả chính của chương trình này là sinh viên khoảng hai mươi tuổi."},{"type":"compound","zh":"做广告之前，如果不了解受众，就很难打动他们。","pinyin":"Zuò guǎnggào zhīqián, rúguǒ bù liǎojiě shòuzhòng, jiù hěn nán dǎdòng tāmen.","vi":"Trước khi làm quảng cáo, nếu không hiểu đối tượng tiếp nhận thì rất khó làm họ rung động."}],"related":[{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"},{"hanzi":"听众","pinyin":"tīngzhòng","vi":"thính giả"},{"hanzi":"读者","pinyin":"dúzhě","vi":"độc giả"},{"hanzi":"目标人群","pinyin":"mùbiāorénqún","vi":"nhóm đối tượng"}],"traditional":"受眾"},{"id":"数据库","hanzi":"数据库","pinyin":"shùjùkù","meaning_vi":"cơ sở dữ liệu (Database)","explanation":"数据 (số cứ – dữ liệu) + 库 (khố – kho) → kho dữ liệu, cơ sở dữ liệu được lưu trữ có tổ chức trên máy tính.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🗄️","examples":[{"type":"basic","zh":"数据库崩溃了。","pinyin":"Shùjùkù bēngkuì le.","vi":"Cơ sở dữ liệu bị sập rồi."},{"type":"simple","zh":"图书馆把所有古籍都录入了电子数据库。","pinyin":"Túshūguǎn bǎ suǒyǒu gǔjí dōu lùrùle diànzǐ shùjùkù.","vi":"Thư viện đã nhập toàn bộ sách cổ vào cơ sở dữ liệu điện tử."},{"type":"compound","zh":"一旦数据库被黑客攻破，用户的信息就会泄露。","pinyin":"Yídàn shùjùkù bèi hēikè gōngpò, yònghù de xìnxī jiù huì xièlòu.","vi":"Một khi cơ sở dữ liệu bị tin tặc xâm nhập, thông tin người dùng sẽ bị rò rỉ."}],"related":[{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"服务器","pinyin":"fúwùqì","vi":"máy chủ"},{"hanzi":"大数据","pinyin":"dàshùjù","vi":"dữ liệu lớn"},{"hanzi":"信息系统","pinyin":"xìnxīxìtǒng","vi":"hệ thống thông tin"}],"traditional":"數據庫"},{"id":"数以万计","hanzi":"数以万计","pinyin":"shùyǐ-wànjì","meaning_vi":"hàng vạn, nhiều vô kể","explanation":"数 (đếm) + 以 (lấy) + 万 (vạn vật/tuyệt đối) + 计 (kế hoạch/tính toán).","hsk_level":"7-9","tags":["thanh-ngu","so-luong"],"image":"🔢","examples":[{"type":"basic","zh":"观众数以万计。","pinyin":"Guānzhòng shùyǐwànjì.","vi":"Khán giả lên tới hàng vạn."},{"type":"simple","zh":"每年春天都有数以万计的候鸟飞到这片湿地。","pinyin":"Měinián chūntiān dōu yǒu shùyǐwànjì de hòuniǎo fēi dào zhè piàn shīdì.","vi":"Mỗi mùa xuân có hàng vạn con chim di cư bay đến vùng đất ngập nước này."},{"type":"compound","zh":"这段视频一上传，就吸引了数以万计的网友观看。","pinyin":"Zhè duàn shìpín yí shàngchuán, jiù xīyǐnle shùyǐwànjì de wǎngyǒu guānkàn.","vi":"Đoạn video vừa đăng lên đã thu hút hàng vạn cư dân mạng xem."}],"related":[{"hanzi":"成千上万","pinyin":"chéngqiānshàngwàn","vi":"hàng nghìn hàng vạn"},{"hanzi":"不计其数","pinyin":"bújìqíshù","vi":"nhiều không đếm xuể"},{"hanzi":"数不胜数","pinyin":"shǔbúshèngshǔ","vi":"đếm không xuể"},{"hanzi":"寥寥无几","pinyin":"liáoliáowújǐ","vi":"lèo tèo vài cái"}],"traditional":"數以萬計"},{"id":"述职","hanzi":"述职","pinyin":"shùzhí","meaning_vi":"báo cáo công tác","explanation":"述 (trình bày/thuật lại) + 职 (chức vụ/nghề nghiệp).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"经理正在述职。","pinyin":"Jīnglǐ zhèngzài shùzhí.","vi":"Quản lý đang báo cáo công tác."},{"type":"simple","zh":"年底每位部门主管都要向董事会述职。","pinyin":"Niándǐ měi wèi bùmén zhǔguǎn dōu yào xiàng dǒngshìhuì shùzhí.","vi":"Cuối năm mỗi trưởng bộ phận đều phải báo cáo công tác trước hội đồng quản trị."},{"type":"compound","zh":"虽然述职报告写了很久，但是她讲得很简短。","pinyin":"Suīrán shùzhí bàogào xiěle hěn jiǔ, dànshì tā jiǎng de hěn jiǎnduǎn.","vi":"Tuy bản báo cáo công tác viết rất lâu nhưng cô ấy trình bày rất ngắn gọn."}],"related":[{"hanzi":"述职报告","pinyin":"shùzhíbàogào","vi":"báo cáo công tác"},{"hanzi":"汇报","pinyin":"huìbào","vi":"báo cáo"},{"hanzi":"总结","pinyin":"zǒngjié","vi":"tổng kết"},{"hanzi":"考核","pinyin":"kǎohé","vi":"đánh giá"}],"traditional":"述職"},{"id":"数字化转型","hanzi":"数字化转型","pinyin":"shùzìhuà zhuǎnxíng","meaning_vi":"chuyển đổi số","explanation":"数字化 + 转型 (chuyển đổi mô hình).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"工厂开始数字化转型。","pinyin":"Gōngchǎng kāishǐ shùzìhuàzhuǎnxíng.","vi":"Nhà máy bắt đầu chuyển đổi số."},{"type":"simple","zh":"这家老银行花了三年完成数字化转型。","pinyin":"Zhè jiālǎo yínháng huāle sān nián wánchéng shùzìhuàzhuǎnxíng.","vi":"Ngân hàng lâu đời này mất ba năm để hoàn thành chuyển đổi số."},{"type":"compound","zh":"如果中小企业不进行数字化转型，就很难留住年轻客户。","pinyin":"Rúguǒ zhōngxiǎoqǐyè bú jìnxíng shùzìhuàzhuǎnxíng, jiù hěn nán liúzhù niánqīng kèhù.","vi":"Nếu doanh nghiệp vừa và nhỏ không chuyển đổi số thì rất khó giữ chân khách hàng trẻ."}],"related":[{"hanzi":"数字化","pinyin":"shùzìhuà","vi":"số hóa"},{"hanzi":"转型","pinyin":"zhuǎnxíng","vi":"chuyển đổi"},{"hanzi":"数字经济","pinyin":"shùzìjīngjì","vi":"kinh tế số"},{"hanzi":"智能化","pinyin":"zhìnénghuà","vi":"thông minh hóa"}],"traditional":"數字化轉型"},{"id":"数字经济","hanzi":"数字经济","pinyin":"shùzìjīngjì","meaning_vi":"kinh tế số","explanation":"数字 (kỹ thuật số) + 经济.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","cong-viec"],"image":"💻","examples":[{"type":"basic","zh":"数字经济发展很快。","pinyin":"Shùzìjīngjì fāzhǎn hěn kuài.","vi":"Kinh tế số phát triển rất nhanh."},{"type":"simple","zh":"外卖和网购都是数字经济的一部分。","pinyin":"Wàimài hé wǎnggòu dōu shì shùzìjīngjì de yíbùfen.","vi":"Giao đồ ăn và mua sắm trực tuyến đều là một phần của kinh tế số."},{"type":"compound","zh":"数字经济不但创造了新职业，而且改变了人们的消费习惯。","pinyin":"Shùzìjīngjì búdàn chuàngzàole xīn zhíyè, érqiě gǎibiànle rénmen de xiāofèi xíguàn.","vi":"Kinh tế số không những tạo ra nghề nghiệp mới mà còn thay đổi thói quen tiêu dùng của mọi người."}],"related":[{"hanzi":"互联网","pinyin":"Hùliánwǎng","vi":"internet"},{"hanzi":"电子商务","pinyin":"diànzǐshāngwù","vi":"thương mại điện tử"},{"hanzi":"数字化","pinyin":"shùzìhuà","vi":"số hóa"},{"hanzi":"实体经济","pinyin":"shítǐjīngjì","vi":"kinh tế thực"}],"traditional":"數字經濟"},{"id":"顺畅","hanzi":"顺畅","pinyin":"shùnchàng","meaning_vi":"trôi chảy thông suốt","explanation":"顺 (thuận lợi/thuận theo) + 畅 (thông suốt/thoải mái).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"今天交通很顺畅。","pinyin":"Jīntiān jiāotōng hěn shùnchàng.","vi":"Hôm nay giao thông rất thông suốt."},{"type":"simple","zh":"换了新路由器以后网络顺畅多了。","pinyin":"Huànle xīn lùyóuqì yǐhòu wǎngluò shùnchàng duō le.","vi":"Sau khi đổi bộ phát wifi mới, mạng trơn tru hơn nhiều."},{"type":"compound","zh":"只要双方提前沟通好，合作就会进行得很顺畅。","pinyin":"Zhǐyào shuāngfāng tíqián gōutōng hǎo, hézuò jiù huì jìnxíng de hěn shùnchàng.","vi":"Chỉ cần hai bên trao đổi kỹ từ trước, việc hợp tác sẽ diễn ra rất suôn sẻ."}],"related":[{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"},{"hanzi":"流畅","pinyin":"liúchàng","vi":"trôi chảy"},{"hanzi":"通畅","pinyin":"tōngchàng","vi":"thông suốt"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"}],"traditional":"順暢"},{"id":"顺差","hanzi":"顺差","pinyin":"shùnchā","meaning_vi":"xuất siêu, thặng dư","explanation":"顺 (thuận lợi/thuận theo) + 差 (chênh lệch/sai sót).","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"去年贸易顺差扩大了。","pinyin":"Qùnián màoyìshùnchā kuòdà le.","vi":"Năm ngoái thặng dư thương mại đã mở rộng."},{"type":"simple","zh":"越南对美国保持着较大的贸易顺差。","pinyin":"Yuènán duì Měiguó bǎochízhe jiàodà de màoyìshùnchā.","vi":"Việt Nam duy trì mức xuất siêu khá lớn với Mỹ."},{"type":"compound","zh":"虽然出口增长放缓，但是全年仍然实现了顺差。","pinyin":"Suīrán chūkǒu zēngzhǎng fànghuǎn, dànshì quánnián réngrán shíxiànle shùnchā.","vi":"Tuy xuất khẩu tăng chậm lại nhưng cả năm vẫn đạt xuất siêu."}],"related":[{"hanzi":"逆差","pinyin":"nìchā","vi":"nhập siêu"},{"hanzi":"贸易","pinyin":"màoyì","vi":"thương mại"},{"hanzi":"出口","pinyin":"chūkǒu","vi":"xuất khẩu"},{"hanzi":"进口","pinyin":"jìnkǒu","vi":"nhập khẩu"}],"traditional":"順差"},{"id":"顺从","hanzi":"顺从","pinyin":"shùncóng","meaning_vi":"nghe lời, phục tùng","explanation":"顺 (thuận lợi/thuận theo) + 从 (tuân theo/từ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🙇","examples":[{"type":"basic","zh":"他从小就很顺从。","pinyin":"Tā cóngxiǎo jiù hěn shùncóng.","vi":"Từ nhỏ cậu ấy đã rất ngoan ngoãn nghe lời."},{"type":"simple","zh":"她不愿再顺从父母安排的婚事。","pinyin":"Tā búyuàn zài shùncóng fùmǔ ānpái de hūnshì.","vi":"Cô ấy không muốn tiếp tục nghe theo cuộc hôn nhân do bố mẹ sắp đặt."},{"type":"compound","zh":"与其一味顺从老板，不如把真实想法说出来。","pinyin":"Yǔqí yíwèi shùncóng lǎobǎn, bùrú bǎ zhēnshí xiǎngfǎ shuō chūlái.","vi":"Thay vì cứ một mực phục tùng sếp, chi bằng nói ra suy nghĩ thật của mình."}],"related":[{"hanzi":"听话","pinyin":"tīnghuà","vi":"nghe lời"},{"hanzi":"服从","pinyin":"fúcóng","vi":"phục tùng"},{"hanzi":"违抗","pinyin":"wéikàng","vi":"chống lệnh"},{"hanzi":"反抗","pinyin":"fǎnkàng","vi":"phản kháng"}],"traditional":"順從"},{"id":"顺风","hanzi":"顺风","pinyin":"shùnfēng","meaning_vi":"thuận gió (一路顺风 - thượng lộ bình an)","explanation":"顺 (thuận lợi/thuận theo) + 风 (风).","hsk_level":"7-9","tags":["dong-tu","thoi-tiet","du-lich"],"image":"⛵","examples":[{"type":"basic","zh":"祝你一路顺风！","pinyin":"Zhù nǐ yílù shùnfēng!","vi":"Chúc bạn thượng lộ bình an!"},{"type":"simple","zh":"帆船借着顺风很快驶出了港口。","pinyin":"Fānchuán jièzhe shùnfēng hěn kuài shǐchūle gǎngkǒu.","vi":"Chiếc thuyền buồm nhờ thuận gió nhanh chóng ra khỏi cảng."},{"type":"compound","zh":"因为回程一路顺风，所以我们骑车只用了半小时。","pinyin":"Yīnwèi huíchéng yílù shùnfēng, suǒyǐ wǒmen qíchē zhǐ yòngle bànxiǎoshí.","vi":"Vì đường về thuận gió suốt nên chúng tôi đạp xe chỉ mất nửa tiếng."}],"related":[{"hanzi":"一路顺风","pinyin":"yílùshùnfēng","vi":"thượng lộ bình an"},{"hanzi":"逆风","pinyin":"nìfēng","vi":"ngược gió"},{"hanzi":"顺利","pinyin":"shùnlì","vi":"thuận lợi"},{"hanzi":"顺风车","pinyin":"shùnfēngchē","vi":"xe đi nhờ"}],"traditional":"順風"},{"id":"瞬息万变","hanzi":"瞬息万变","pinyin":"shùnxī-wànbiàn","meaning_vi":"biến đổi khôn lường trong chớp mắt","explanation":"瞬 (khoảnh khắc) + 息 (tin tức/nghỉ ngơi) + 万 (vạn vật/tuyệt đối) + 变 (biến đổi/biến cố).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚡","examples":[{"type":"basic","zh":"股市瞬息万变。","pinyin":"Gǔshì shùnxīwànbiàn.","vi":"Thị trường chứng khoán biến đổi khôn lường."},{"type":"simple","zh":"高原山顶上的天气瞬息万变。","pinyin":"Gāoyuán shāndǐng shang de tiānqì shùnxīwànbiàn.","vi":"Thời tiết trên đỉnh núi cao nguyên thay đổi chóng mặt."},{"type":"compound","zh":"市场行情瞬息万变，因此投资者必须随时关注新闻。","pinyin":"Shìchǎng hángqíng shùnxīwànbiàn, yīncǐ tóuzīzhě bìxū suíshí guānzhù xīnwén.","vi":"Thị trường biến đổi khôn lường trong chớp mắt, vì vậy nhà đầu tư phải luôn theo dõi tin tức."}],"related":[{"hanzi":"变幻莫测","pinyin":"biànhuànmòcè","vi":"biến ảo khôn lường"},{"hanzi":"千变万化","pinyin":"qiānbiànwànhuà","vi":"thiên biến vạn hóa"},{"hanzi":"瞬间","pinyin":"shùnjiān","vi":"chớp mắt"},{"hanzi":"一成不变","pinyin":"yìchéngbúbiàn","vi":"không hề thay đổi"}],"traditional":"瞬息萬變"},{"id":"顺应","hanzi":"顺应","pinyin":"shùnyìng","meaning_vi":"thuận theo, thích ứng với (xu thế thời đại)","explanation":"顺 (thuận lợi/thuận theo) + 应 (ứng phó/phản ứng).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"我们要顺应潮流。","pinyin":"Wǒmen yào shùnyìng cháoliú.","vi":"Chúng ta phải thuận theo trào lưu."},{"type":"simple","zh":"这家书店顺应时代推出了线上阅读服务。","pinyin":"Zhè jiāshū diàn shùnyìng shídài tuīchūle xiànshàng yuèdú fúwù.","vi":"Hiệu sách này thuận theo thời đại, ra mắt dịch vụ đọc trực tuyến."},{"type":"compound","zh":"只有顺应市场变化，企业才能长久生存。","pinyin":"Zhǐyǒu shùnyìng shìchǎng biànhuà, qǐyè cáinéng chángjiǔ shēngcún.","vi":"Chỉ có thuận theo biến động thị trường, doanh nghiệp mới tồn tại lâu dài."}],"related":[{"hanzi":"适应","pinyin":"shìyìng","vi":"thích ứng"},{"hanzi":"顺应潮流","pinyin":"shùnyìngcháoliú","vi":"thuận theo trào lưu"},{"hanzi":"遵循","pinyin":"zūnxún","vi":"tuân theo"},{"hanzi":"违背","pinyin":"wéibèi","vi":"làm trái"}],"traditional":"順應"},{"id":"顺耳","hanzi":"顺耳","pinyin":"shùn'ěr","meaning_vi":"lọt tai, dễ nghe","explanation":"顺 (thuận lợi/thuận theo) + 耳 (耳).","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"👂","examples":[{"type":"basic","zh":"这话听着不顺耳。","pinyin":"Zhè huà tīngzhe bú shùn'ěr.","vi":"Câu này nghe không lọt tai."},{"type":"simple","zh":"批评的话往往不太顺耳。","pinyin":"Pīpíng dehuà wǎngwǎng bú tài shùn'ěr.","vi":"Lời phê bình thường không mấy dễ nghe."},{"type":"compound","zh":"虽然他的建议听起来不顺耳，但是对我很有帮助。","pinyin":"Suīrán tā de jiànyì tīngqǐlái bú shùn'ěr, dànshì duì wǒ hěn yǒubāngzhù.","vi":"Tuy lời khuyên của anh ấy nghe không lọt tai nhưng rất có ích với tôi."}],"related":[{"hanzi":"逆耳","pinyin":"nì'ěr","vi":"chướng tai"},{"hanzi":"悦耳","pinyin":"yuè'ěr","vi":"êm tai"},{"hanzi":"中听","pinyin":"zhōngtīng","vi":"dễ nghe"},{"hanzi":"忠言逆耳","pinyin":"zhōngyánnì'ěr","vi":"lời thật mất lòng"}],"traditional":"順耳"},{"id":"熟人","hanzi":"熟人","pinyin":"shúrén","meaning_vi":"người quen","explanation":"熟 (thành thạo/quen thuộc) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","giao-tiep"],"image":"👋","examples":[{"type":"basic","zh":"他在医院有熟人。","pinyin":"Tā zài yīyuàn yǒu shúrén.","vi":"Anh ấy có người quen ở bệnh viện."},{"type":"simple","zh":"我在地铁上碰到了一个多年不见的熟人。","pinyin":"Wǒ zài dìtiě shang pèngdàole yí gè duōnián bújiàn de shúrén.","vi":"Tôi gặp một người quen nhiều năm không gặp trên tàu điện ngầm."},{"type":"compound","zh":"因为老板是熟人，所以他给我们打了八折。","pinyin":"Yīnwèi lǎobǎn shì shúrén, suǒyǐ tā gěi wǒmen dǎle bā zhé.","vi":"Vì ông chủ là người quen nên ông ấy giảm giá hai mươi phần trăm cho chúng tôi."}],"related":[{"hanzi":"陌生人","pinyin":"mòshēngrén","vi":"người lạ"},{"hanzi":"朋友","pinyin":"péngyou","vi":"bạn bè"},{"hanzi":"老熟人","pinyin":"lǎoshúrén","vi":"người quen lâu năm"},{"hanzi":"熟悉","pinyin":"shúxī","vi":"quen thuộc"}]},{"id":"熟食","hanzi":"熟食","pinyin":"shúshí","meaning_vi":"thức ăn chín chế biến sẵn","explanation":"熟 (thành thạo/quen thuộc) + 食 (thực phẩm).","hsk_level":"7-9","tags":["danh-tu","an-uong","mua-sam"],"image":"🍗","examples":[{"type":"basic","zh":"超市的熟食很新鲜。","pinyin":"Chāoshì de shúshí hěn xīnxiān.","vi":"Đồ ăn chín ở siêu thị rất tươi."},{"type":"simple","zh":"妈妈下班顺路买了些熟食当晚饭。","pinyin":"Māma xiàbān shùnlù mǎile xiē shúshí dāngwǎn fàn.","vi":"Mẹ tan làm tiện đường mua ít đồ ăn chín làm bữa tối."},{"type":"compound","zh":"熟食如果放在常温下太久，就容易变质。","pinyin":"Shúshí rúguǒ fàng zài chángwēn xià tài jiǔ, jiù róngyì biànzhì.","vi":"Đồ ăn chín nếu để ở nhiệt độ thường quá lâu thì dễ bị hỏng."}],"related":[{"hanzi":"熟食店","pinyin":"shúshídiàn","vi":"cửa hàng đồ chín"},{"hanzi":"生食","pinyin":"shēngshí","vi":"đồ sống"},{"hanzi":"卤味","pinyin":"lǔwèi","vi":"món kho thuốc bắc"},{"hanzi":"快餐","pinyin":"kuàicān","vi":"đồ ăn nhanh"}]},{"id":"沙尘暴","hanzi":"沙尘暴","pinyin":"shāchénbào","meaning_vi":"bão cát","explanation":"沙 (沙) + 尘 (bụi bặm) + 暴 (暴).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","thien-nhien"],"image":"🌪️","examples":[{"type":"basic","zh":"北京刮起了沙尘暴。","pinyin":"Běijīng guā qǐle shāchénbào.","vi":"Bắc Kinh nổi bão cát."},{"type":"simple","zh":"一场强沙尘暴让整座城市变成了黄色。","pinyin":"Yì chǎng qiáng shāchénbào ràng zhěng zuò chéngshì biàn chéngle huángsè.","vi":"Một trận bão cát mạnh khiến cả thành phố chuyển sang màu vàng."},{"type":"compound","zh":"一旦遇到沙尘暴，就要关好门窗并戴上口罩。","pinyin":"Yídàn yùdào shāchénbào, jiùyào guān hǎo ménchuāng bìng dàishàng kǒuzhào.","vi":"Một khi gặp bão cát thì phải đóng kín cửa và đeo khẩu trang."}],"related":[{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"雾霾","pinyin":"wùmái","vi":"sương mù ô nhiễm"},{"hanzi":"风沙","pinyin":"fēngshā","vi":"gió cát"},{"hanzi":"沙漠化","pinyin":"shāmòhuà","vi":"sa mạc hóa"}],"traditional":"沙塵暴"},{"id":"杀毒","hanzi":"杀毒","pinyin":"shādú","meaning_vi":"diệt vi-rút (máy tính)","explanation":"杀 (sát – giết) + 毒 (độc – chất độc, virus) → diệt virus máy tính; cũng có nghĩa khử độc, tiêu độc. Ví dụ: 杀毒软件 (phần mềm diệt virus).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🛡️","examples":[{"type":"basic","zh":"电脑需要杀毒了。","pinyin":"Diànnǎo xūyào shādú le.","vi":"Máy tính cần diệt vi-rút rồi."},{"type":"simple","zh":"他每周都用软件给电脑杀毒。","pinyin":"Tā měizhōu dōu yòng ruǎnjiàn gěi diànnǎo shādú.","vi":"Mỗi tuần anh ấy đều dùng phần mềm diệt vi-rút cho máy tính."},{"type":"compound","zh":"下载的文件最好先杀毒，否则可能会感染整个系统。","pinyin":"Xiàzài de wénjiàn zuìhǎo xiān shādú, fǒuzé kěnéng huì gǎnrǎn zhěnggè xìtǒng.","vi":"Tệp tải về tốt nhất nên diệt vi-rút trước, nếu không có thể lây nhiễm cả hệ thống."}],"related":[{"hanzi":"病毒","pinyin":"bìngdú","vi":"vi-rút"},{"hanzi":"杀毒软件","pinyin":"shādúruǎnjiàn","vi":"phần mềm diệt vi-rút"},{"hanzi":"防火墙","pinyin":"fánghuǒqiáng","vi":"tường lửa"},{"hanzi":"消毒","pinyin":"xiāodú","vi":"khử trùng"}],"traditional":"殺毒"},{"id":"砂锅","hanzi":"砂锅","pinyin":"shāguō","meaning_vi":"nồi đất (nấu ăn)","explanation":"砂 (cát/sành sứ) + 锅 (cái nồi).","hsk_level":"7-9","tags":["danh-tu","do-vat","an-uong"],"image":"🍲","examples":[{"type":"basic","zh":"砂锅里炖着鸡汤。","pinyin":"Shāguō li dùnzhe jītāng.","vi":"Trong nồi đất đang hầm canh gà."},{"type":"simple","zh":"冬天吃一碗热腾腾的砂锅粥特别舒服。","pinyin":"Dōngtiān chī yì wǎn rètēngtēng de shāguōzhōu tèbié shūfu.","vi":"Mùa đông ăn một bát cháo nồi đất nóng hổi thật dễ chịu."},{"type":"compound","zh":"砂锅虽然保温效果好，但是不能直接放进冷水里。","pinyin":"Shāguō suīrán bǎowēn xiàoguǒ hǎo, dànshì bù néng zhíjiē fàngjìn lěngshuǐ li.","vi":"Nồi đất tuy giữ nhiệt tốt nhưng không được cho trực tiếp vào nước lạnh."}],"related":[{"hanzi":"炖","pinyin":"dùn","vi":"hầm"},{"hanzi":"火锅","pinyin":"huǒguō","vi":"lẩu"},{"hanzi":"砂锅粥","pinyin":"shāguōzhōu","vi":"cháo nồi đất"},{"hanzi":"锅","pinyin":"guō","vi":"nồi chảo"}],"traditional":"砂鍋"},{"id":"沙漠化","hanzi":"沙漠化","pinyin":"shāmòhuà","meaning_vi":"sa mạc hóa","explanation":"沙漠 (sa mạc) + 化 (hóa – biến thành) → quá trình đất đai bị biến thành sa mạc do khô hạn, phá rừng, chăn thả quá mức.","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"沙漠化问题很严重。","pinyin":"Shāmòhuà wèntí hěn yánzhòng.","vi":"Vấn đề sa mạc hóa rất nghiêm trọng."},{"type":"simple","zh":"过度放牧加快了草原的沙漠化。","pinyin":"Guòdù fàngmù jiākuàile cǎoyuán de shāmòhuà.","vi":"Chăn thả quá mức đã đẩy nhanh quá trình sa mạc hóa đồng cỏ."},{"type":"compound","zh":"因为当地人坚持植树三十年，所以土地沙漠化终于得到了遏制。","pinyin":"Yīnwèi dāngdìrén jiānchí zhíshù sānshí nián, suǒyǐ tǔdì shāmòhuà zhōngyú dédàole èzhì.","vi":"Vì người dân địa phương kiên trì trồng cây ba mươi năm nên tình trạng sa mạc hóa đất đai cuối cùng đã được ngăn chặn."}],"related":[{"hanzi":"荒漠化","pinyin":"huāngmòhuà","vi":"hoang mạc hóa"},{"hanzi":"水土流失","pinyin":"shuǐtǔliúshī","vi":"xói mòn đất"},{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"植树造林","pinyin":"zhíshùzàolín","vi":"trồng cây gây rừng"}]},{"id":"沙丘","hanzi":"沙丘","pinyin":"shāqiū","meaning_vi":"cồn cát, đụn cát","explanation":"沙 (cát) + 丘 (đồi gò).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏜️","examples":[{"type":"basic","zh":"远处有一片沙丘。","pinyin":"Yuǎnchù yǒu yípiàn shāqiū.","vi":"Đằng xa có một dải cồn cát."},{"type":"simple","zh":"孩子们在白色沙丘上滑沙玩。","pinyin":"Háizimen zài báisè shāqiū shang huáshā wán.","vi":"Bọn trẻ trượt cát chơi trên những đồi cát trắng."},{"type":"compound","zh":"风一吹，沙漠里沙丘的形状就会发生变化。","pinyin":"Fēng yì chuī, shāmò li shāqiū de xíngzhuàng jiù huì fāshēng biànhuà.","vi":"Gió vừa thổi là hình dạng cồn cát trong sa mạc sẽ thay đổi."}],"related":[{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"沙滩","pinyin":"shātān","vi":"bãi cát"},{"hanzi":"山丘","pinyin":"shānqiū","vi":"đồi núi"},{"hanzi":"骆驼","pinyin":"luòtuo","vi":"lạc đà"}]},{"id":"杀伤力","hanzi":"杀伤力","pinyin":"shāshānglì","meaning_vi":"sức sát thương, sức ảnh hưởng mạnh","explanation":"杀 (giết) + 伤 (tổn thương) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu"],"image":"💥","examples":[{"type":"basic","zh":"这种武器杀伤力大。","pinyin":"Zhè zhǒng wǔqì shāshānglì dà.","vi":"Loại vũ khí này có sức sát thương lớn."},{"type":"simple","zh":"网上的谣言有时比真刀真枪更有杀伤力。","pinyin":"Wǎngshàng de yáoyán yǒushí bǐ zhēn dāo zhēn qiāng gèng yǒu shāshānglì.","vi":"Tin đồn trên mạng đôi khi còn có sức sát thương hơn cả đao thật súng thật."},{"type":"compound","zh":"他的话虽然不多，但是每一句都很有杀伤力。","pinyin":"Tā dehuà suīrán bù duō, dànshì měi yíjù dōu hěn yǒu shāshānglì.","vi":"Lời anh ấy tuy không nhiều nhưng câu nào cũng có sức sát thương."}],"related":[{"hanzi":"威力","pinyin":"wēilì","vi":"uy lực"},{"hanzi":"破坏力","pinyin":"pòhuàilì","vi":"sức phá hoại"},{"hanzi":"武器","pinyin":"wǔqì","vi":"vũ khí"},{"hanzi":"伤害","pinyin":"shānghài","vi":"tổn thương"}],"traditional":"殺傷力"},{"id":"沙哑","hanzi":"沙哑","pinyin":"shāyǎ","meaning_vi":"khàn giọng","explanation":"沙 (cát) + 哑 (khàn giọng/câm).","hsk_level":"7-9","tags":["tinh-tu","co-the"],"image":"🗣️","examples":[{"type":"basic","zh":"他的声音有点沙哑。","pinyin":"Tā de shēngyīn yǒudiǎn shāyǎ.","vi":"Giọng anh ấy hơi khàn."},{"type":"simple","zh":"王老师连上四节课后嗓子变得沙哑。","pinyin":"Wáng lǎoshī lián shàng sì jié kè hòu sǎngzi biànde shāyǎ.","vi":"Thầy Vương sau khi dạy liền bốn tiết thì giọng bị khàn."},{"type":"compound","zh":"因为昨晚在演唱会上一直尖叫，所以她今天声音沙哑。","pinyin":"Yīnwèi zuówǎn zài yǎnchànghuì shang yìzhí jiānjiào, suǒyǐ tā jīntiān shēngyīn shāyǎ.","vi":"Vì tối qua hò hét suốt ở buổi hòa nhạc nên hôm nay giọng cô ấy khàn đặc."}],"related":[{"hanzi":"嘶哑","pinyin":"sīyǎ","vi":"khàn đặc"},{"hanzi":"嗓子","pinyin":"sǎngzi","vi":"cổ họng, giọng"},{"hanzi":"清脆","pinyin":"qīngcuì","vi":"trong trẻo"},{"hanzi":"喉咙","pinyin":"hóulóng","vi":"cổ họng"}],"traditional":"沙啞"},{"id":"山川","hanzi":"山川","pinyin":"shānchuān","meaning_vi":"núi sông","explanation":"山 (núi non) + 川 (sông ngòi/Tứ Xuyên).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🏞️","examples":[{"type":"basic","zh":"祖国山川秀美。","pinyin":"Zǔguó shānchuān xiùměi.","vi":"Núi sông tổ quốc tươi đẹp."},{"type":"simple","zh":"他用十年时间走遍了云南的山川。","pinyin":"Tāyòng shí nián shíjiān zǒu biànle Yúnnán de shānchuān.","vi":"Anh ấy dùng mười năm đi khắp núi sông Vân Nam."},{"type":"compound","zh":"一登上山顶，壮丽的山川就尽收眼底。","pinyin":"Yì dēngshàng shāndǐng, zhuànglì de shānchuān jiù jìn shōu yǎndǐ.","vi":"Vừa lên đến đỉnh núi, núi sông hùng vĩ đã thu trọn vào tầm mắt."}],"related":[{"hanzi":"山河","pinyin":"shānhé","vi":"núi sông"},{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"},{"hanzi":"大好河山","pinyin":"dàhǎohéshān","vi":"non sông tươi đẹp"},{"hanzi":"山脉","pinyin":"shānmài","vi":"dãy núi"}]},{"id":"山峰","hanzi":"山峰","pinyin":"shānfēng","meaning_vi":"đỉnh núi","explanation":"山 (núi non) + 峰 (峰).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"⛰️","examples":[{"type":"basic","zh":"山峰被云遮住了。","pinyin":"Shānfēng bèi yún zhēzhù le.","vi":"Đỉnh núi bị mây che khuất."},{"type":"simple","zh":"清晨的阳光照亮了远处的雪白山峰。","pinyin":"Qīngchén de yángguāng zhàoliàngle yuǎnchù de xuěbái shānfēng.","vi":"Ánh nắng sớm mai chiếu sáng những đỉnh núi trắng tuyết ở xa."},{"type":"compound","zh":"这座山峰虽然不高，但是山路非常陡峭。","pinyin":"Zhè zuò shānfēng suīrán bù gāo, dànshì shānlù fēicháng dǒuqiào.","vi":"Đỉnh núi này tuy không cao nhưng đường núi rất dốc."}],"related":[{"hanzi":"山顶","pinyin":"shāndǐng","vi":"đỉnh núi"},{"hanzi":"山脚","pinyin":"shānjiǎo","vi":"chân núi"},{"hanzi":"山峦","pinyin":"shānluán","vi":"núi non trùng điệp"},{"hanzi":"高峰","pinyin":"gāofēng","vi":"đỉnh cao"}]},{"id":"删改","hanzi":"删改","pinyin":"shāngǎi","meaning_vi":"xóa và sửa đổi (bản thảo)","explanation":"删 (xóa bỏ) + 改 (改).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✂️","examples":[{"type":"basic","zh":"稿子被删改了几处。","pinyin":"Gǎozi bèi shāngǎile jǐ chù.","vi":"Bản thảo bị xóa sửa vài chỗ."},{"type":"simple","zh":"编辑把我的文章删改得面目全非。","pinyin":"Biānjí bǎ wǒ de wénzhāng shāngǎi de miànmùquánfēi.","vi":"Biên tập viên xóa sửa bài viết của tôi đến mức không còn nhận ra."},{"type":"compound","zh":"如果要删改合同条款，就必须经过双方签字确认。","pinyin":"Rúguǒ yào shāngǎi hétong tiáokuǎn, jiù bìxū jīngguò shuāngfāng qiānzì quèrèn.","vi":"Nếu muốn xóa sửa điều khoản hợp đồng thì phải được hai bên ký xác nhận."}],"related":[{"hanzi":"删除","pinyin":"shānchú","vi":"xóa bỏ"},{"hanzi":"修改","pinyin":"xiūgǎi","vi":"sửa đổi"},{"hanzi":"删减","pinyin":"shānjiǎn","vi":"cắt bớt"},{"hanzi":"改动","pinyin":"gǎidòng","vi":"thay đổi"}],"traditional":"刪改"},{"id":"山谷","hanzi":"山谷","pinyin":"shāngǔ","meaning_vi":"thung lũng","explanation":"山 (núi non) + 谷 (谷).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🏞️","examples":[{"type":"basic","zh":"山谷里有回声。","pinyin":"Shāngǔ li yǒu huíshēng.","vi":"Trong thung lũng có tiếng vọng."},{"type":"simple","zh":"一条小溪从安静的山谷中间流过。","pinyin":"Yì tiáo xiǎoxī cóng ānjìng de shāngǔ zhōngjiān liú guò.","vi":"Một con suối nhỏ chảy qua giữa thung lũng yên tĩnh."},{"type":"compound","zh":"每到春天，这片山谷里就开满了各色野花。","pinyin":"Měi dào chūntiān, zhè piàn shāngǔ li jiù kāimǎnle gèsè yěhuā.","vi":"Cứ đến mùa xuân, thung lũng này lại nở đầy hoa dại đủ màu."}],"related":[{"hanzi":"峡谷","pinyin":"xiágǔ","vi":"hẻm núi"},{"hanzi":"山坡","pinyin":"shānpō","vi":"sườn núi"},{"hanzi":"山沟","pinyin":"shāngōu","vi":"khe núi"},{"hanzi":"山峰","pinyin":"shānfēng","vi":"đỉnh núi"}]},{"id":"删减","hanzi":"删减","pinyin":"shānjiǎn","meaning_vi":"cắt giảm","explanation":"删 (xóa bỏ) + 减 (减).","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"电影删减了几分钟。","pinyin":"Diànyǐng shānjiǎnle jǐ fēnzhōng.","vi":"Bộ phim bị cắt mất vài phút."},{"type":"simple","zh":"学校删减了一部分课外作业。","pinyin":"Xuéxiào shānjiǎnle yíbùfen kèwài zuòyè.","vi":"Nhà trường cắt giảm một phần bài tập ngoài giờ."},{"type":"compound","zh":"由于预算不足，公司不得不删减年会的节目。","pinyin":"Yóuyú yùsuàn bùzú, gōngsī bùdébù shānjiǎn niánhuì de jiémù.","vi":"Do ngân sách không đủ, công ty buộc phải cắt bớt tiết mục tiệc tất niên."}],"related":[{"hanzi":"删除","pinyin":"shānchú","vi":"xóa bỏ"},{"hanzi":"缩减","pinyin":"suōjiǎn","vi":"cắt giảm"},{"hanzi":"删节","pinyin":"shānjié","vi":"cắt bớt đoạn"},{"hanzi":"增加","pinyin":"zēngjiā","vi":"tăng thêm"}],"traditional":"刪減"},{"id":"山珍海味","hanzi":"山珍海味","pinyin":"shānzhēn-hǎiwèi","meaning_vi":"sơn hào hải vị","explanation":"山 (núi non) + 珍 (trân trọng/quý giá) + 海 (biển) + 味 (hương vị/suy ngẫm).","hsk_level":"7-9","tags":["thanh-ngu","an-uong"],"image":"🦞","examples":[{"type":"basic","zh":"桌上摆满了山珍海味。","pinyin":"Zhuō shang bǎimǎnle shānzhēnhǎiwèi.","vi":"Trên bàn bày đầy sơn hào hải vị."},{"type":"simple","zh":"再多的山珍海味也比不上妈妈做的家常菜。","pinyin":"Zài duō de shānzhēnhǎiwèi yě bǐbúshàng māma zuò de jiāchángcài.","vi":"Sơn hào hải vị nhiều đến mấy cũng không bằng món cơm nhà mẹ nấu."},{"type":"compound","zh":"即使天天吃山珍海味，他也觉得没有家乡菜香。","pinyin":"Jíshǐ tiāntiān chī shānzhēnhǎiwèi, tā yě juéde méiyǒu jiāxiāngcài xiāng.","vi":"Dù ngày nào cũng ăn sơn hào hải vị, anh ấy vẫn thấy không ngon bằng món quê nhà."}],"related":[{"hanzi":"美味佳肴","pinyin":"měiwèijiāyáo","vi":"món ngon"},{"hanzi":"海鲜","pinyin":"hǎixiān","vi":"hải sản"},{"hanzi":"粗茶淡饭","pinyin":"cūchádànfàn","vi":"cơm rau đạm bạc"},{"hanzi":"大鱼大肉","pinyin":"dàyúdàròu","vi":"cá thịt thịnh soạn"}]},{"id":"商标权","hanzi":"商标权","pinyin":"shāngbiāoquán","meaning_vi":"quyền nhãn hiệu thương mại","explanation":"商标 (thương tiêu – nhãn hiệu) + 权 (quyền) → quyền độc quyền sử dụng nhãn hiệu đã đăng ký; một loại 知识产权.","hsk_level":"7-9","tags":["danh-tu","phap-luat","cong-viec"],"image":"🏷️","examples":[{"type":"basic","zh":"他们侵犯了商标权。","pinyin":"Tāmen qīnfànle shāngbiāoquán.","vi":"Họ đã xâm phạm quyền nhãn hiệu."},{"type":"simple","zh":"这家老字号终于赢回了自己的商标权。","pinyin":"Zhè jiālǎo zìhào zhōngyú yíng huíle zìjǐ de shāngbiāoquán.","vi":"Thương hiệu lâu đời này cuối cùng đã giành lại quyền nhãn hiệu của mình."},{"type":"compound","zh":"如果不及时注册，商标权就可能被别人抢走。","pinyin":"Rúguǒ bù jíshí zhùcè, shāngbiāoquán jiù kěnéng bèi biérén qiǎngzǒu.","vi":"Nếu không đăng ký kịp thời, quyền nhãn hiệu có thể bị người khác giành mất."}],"related":[{"hanzi":"商标","pinyin":"shāngbiāo","vi":"nhãn hiệu"},{"hanzi":"知识产权","pinyin":"zhīshichǎnquán","vi":"sở hữu trí tuệ"},{"hanzi":"专利","pinyin":"zhuānlì","vi":"bằng sáng chế"},{"hanzi":"侵权","pinyin":"qīnquán","vi":"xâm phạm quyền"}],"traditional":"商標權"},{"id":"伤感","hanzi":"伤感","pinyin":"shānggǎn","meaning_vi":"đau buồn, đa sầu đa cảm","explanation":"伤 (tổn thương) + 感 (感).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"这首歌很伤感。","pinyin":"Zhè shǒu gē hěn shānggǎn.","vi":"Bài hát này rất buồn."},{"type":"simple","zh":"看到毕业照时她突然有些伤感。","pinyin":"Kàndào bìyè zhào shí tā tūrán yǒuxiē shānggǎn.","vi":"Khi nhìn thấy ảnh tốt nghiệp, cô ấy bỗng thấy hơi buồn."},{"type":"compound","zh":"每到秋天落叶的时候，他就变得格外伤感。","pinyin":"Měi dào qiūtiān luòyè de shíhou, tā jiù biànde géwài shānggǎn.","vi":"Cứ đến mùa thu lá rụng, anh ấy lại trở nên đặc biệt đa sầu đa cảm."}],"related":[{"hanzi":"悲伤","pinyin":"bēishāng","vi":"đau buồn"},{"hanzi":"感伤","pinyin":"gǎnshāng","vi":"thương cảm"},{"hanzi":"多愁善感","pinyin":"duōchóushàngǎn","vi":"đa sầu đa cảm"},{"hanzi":"忧伤","pinyin":"yōushāng","vi":"u buồn"}],"traditional":"傷感"},{"id":"商机","hanzi":"商机","pinyin":"shāngjī","meaning_vi":"cơ hội kinh doanh","explanation":"商 (thương mại/bàn bạc) + 机 (cơ hội/máy móc).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💡","examples":[{"type":"basic","zh":"他发现了新商机。","pinyin":"Tā fāxiànle xīn shāngjī.","vi":"Anh ấy phát hiện cơ hội kinh doanh mới."},{"type":"simple","zh":"老龄化社会带来了巨大的养老商机。","pinyin":"Lǎolínghuà shèhuì dàiláile jùdà de yǎnglǎo shāngjī.","vi":"Xã hội già hóa mang lại cơ hội kinh doanh lớn trong lĩnh vực dưỡng lão."},{"type":"compound","zh":"只要善于观察生活，就能在小事中找到商机。","pinyin":"Zhǐyào shànyú guānchá shēnghuó, jiù néng zài xiǎoshì zhōng zhǎodào shāngjī.","vi":"Chỉ cần giỏi quan sát cuộc sống là có thể tìm thấy cơ hội kinh doanh từ những việc nhỏ."}],"related":[{"hanzi":"机遇","pinyin":"jīyù","vi":"cơ hội"},{"hanzi":"商业","pinyin":"shāngyè","vi":"thương mại"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"},{"hanzi":"无限商机","pinyin":"wúxiànshāngjī","vi":"cơ hội vô hạn"}],"traditional":"商機"},{"id":"商榷","hanzi":"商榷","pinyin":"shāngquè","meaning_vi":"bàn bạc cân nhắc (học thuật)","explanation":"商 (thương mại/bàn bạc) + 榷 (bàn bạc/cân nhắc).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🤔","examples":[{"type":"basic","zh":"此观点值得商榷。","pinyin":"Cǐ guāndiǎn zhíde shāngquè.","vi":"Quan điểm này còn phải bàn thêm."},{"type":"simple","zh":"这篇论文的结论还有商榷的余地。","pinyin":"Zhè piān lùnwén de jiélùn háiyǒu shāngquè de yúdì.","vi":"Kết luận của bài luận văn này vẫn còn chỗ để bàn bạc."},{"type":"compound","zh":"虽然作者的数据很丰富，但是他的推论仍有待商榷。","pinyin":"Suīrán zuòzhě de shùjù hěn fēngfù, dànshì tā de tuīlùn réng yǒudài shāngquè.","vi":"Tuy dữ liệu của tác giả rất phong phú nhưng suy luận của ông vẫn cần bàn thêm."}],"related":[{"hanzi":"商量","pinyin":"shāngliang","vi":"bàn bạc"},{"hanzi":"探讨","pinyin":"tàntǎo","vi":"thảo luận"},{"hanzi":"有待商榷","pinyin":"yǒudàishāngquè","vi":"cần bàn thêm"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"}]},{"id":"商圈","hanzi":"商圈","pinyin":"shāngquān","meaning_vi":"khu thương mại sầm uất","explanation":"商 (thương mại/bàn bạc) + 圈 (vòng tròn).","hsk_level":"7-9","tags":["danh-tu","dia-diem","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"这里是核心商圈。","pinyin":"Zhèlǐ shì héxīn shāngquān.","vi":"Đây là khu thương mại trung tâm."},{"type":"simple","zh":"新地铁站开通后带火了周边商圈。","pinyin":"Xīn dìtiězhàn kāitōng hòu dài huǒle zhōubiān shāngquān.","vi":"Sau khi ga tàu điện mới khai trương đã làm sôi động khu thương mại xung quanh."},{"type":"compound","zh":"这个商圈不但交通方便，而且餐厅种类很多。","pinyin":"Zhè ge shāngquān búdàn jiāotōng fāngbiàn, érqiě cāntīng zhǒnglèi hěn duō.","vi":"Khu thương mại này không những giao thông thuận tiện mà còn có nhiều loại nhà hàng."}],"related":[{"hanzi":"商业区","pinyin":"shāngyèqū","vi":"khu thương mại"},{"hanzi":"购物中心","pinyin":"gòuwùzhōngxīn","vi":"trung tâm mua sắm"},{"hanzi":"商场","pinyin":"shāngchǎng","vi":"trung tâm thương mại"},{"hanzi":"步行街","pinyin":"bùxíngjiē","vi":"phố đi bộ"}]},{"id":"商讨","hanzi":"商讨","pinyin":"shāngtǎo","meaning_vi":"thảo luận, bàn bạc","explanation":"商 (thương mại/bàn bạc) + 讨 (thảo luận/lấy lòng).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🗣️","examples":[{"type":"basic","zh":"双方正在商讨细节。","pinyin":"Shuāngfāng zhèngzài shāngtǎo xìjié.","vi":"Hai bên đang bàn bạc chi tiết."},{"type":"simple","zh":"各国代表在日内瓦商讨气候问题。","pinyin":"Gèguó dàibiǎo zài Rìnèiwǎ shāngtǎo qìhòu wèntí.","vi":"Đại diện các nước bàn thảo vấn đề khí hậu tại Geneva."},{"type":"compound","zh":"既然价格谈不拢，我们就下周再商讨吧。","pinyin":"Jìrán jiàgé tánbùlǒng, wǒmen jiù xiàzhōu zài shāngtǎo ba.","vi":"Đã không thỏa thuận được giá thì tuần sau chúng ta bàn tiếp nhé."}],"related":[{"hanzi":"商量","pinyin":"shāngliang","vi":"bàn bạc"},{"hanzi":"协商","pinyin":"xiéshāng","vi":"hiệp thương"},{"hanzi":"讨论","pinyin":"tǎolùn","vi":"thảo luận"},{"hanzi":"磋商","pinyin":"cuōshāng","vi":"đàm phán bàn bạc"}],"traditional":"商討"},{"id":"伤亡","hanzi":"伤亡","pinyin":"shāngwáng","meaning_vi":"thương vong","explanation":"伤 (tổn thương) + 亡 (亡).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚑","examples":[{"type":"basic","zh":"事故没有造成伤亡。","pinyin":"Shìgù méiyǒu zàochéng shāngwáng.","vi":"Sự cố không gây thương vong."},{"type":"simple","zh":"地震造成的伤亡人数还在统计中。","pinyin":"Dìzhèn zàochéng de shāngwáng rénshù hái zài tǒngjì zhōng.","vi":"Số người thương vong do động đất vẫn đang được thống kê."},{"type":"compound","zh":"由于疏散及时，所以这次火灾没有人员伤亡。","pinyin":"Yóuyú shūsàn jíshí, suǒyǐ zhè cì huǒzāi méiyǒu rényuán shāngwáng.","vi":"Do sơ tán kịp thời nên vụ hỏa hoạn lần này không có thương vong."}],"related":[{"hanzi":"死亡","pinyin":"sǐwáng","vi":"tử vong"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"伤员","pinyin":"shāngyuán","vi":"người bị thương"},{"hanzi":"伤亡人数","pinyin":"shāngwángrénshù","vi":"số người thương vong"}],"traditional":"傷亡"},{"id":"伤心事","hanzi":"伤心事","pinyin":"shāngxīnshì","meaning_vi":"chuyện đau lòng","explanation":"伤 (tổn thương) + 心 (tâm lý/tâm huyết) + 事 (sự nghiệp/sự kiện).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"别提那件伤心事了。","pinyin":"Bié tí nà jiàn shāngxīnshì le.","vi":"Đừng nhắc chuyện đau lòng đó nữa."},{"type":"simple","zh":"奶奶很少跟我们讲起战争年代的伤心事。","pinyin":"Nǎinai hěn shǎo gēn wǒmen jiǎng qǐ zhànzhēng niándài de shāngxīnshì.","vi":"Bà hiếm khi kể cho chúng tôi những chuyện đau lòng thời chiến."},{"type":"compound","zh":"他一喝醉，就开始跟朋友讲自己的伤心事。","pinyin":"Tā yì hēzuì, jiù kāishǐ gēn péngyou jiǎng zìjǐ de shāngxīnshì.","vi":"Anh ấy hễ say là bắt đầu kể với bạn bè chuyện đau lòng của mình."}],"related":[{"hanzi":"伤心","pinyin":"shāngxīn","vi":"đau lòng"},{"hanzi":"往事","pinyin":"wǎngshì","vi":"chuyện cũ"},{"hanzi":"心事","pinyin":"xīnshì","vi":"tâm sự"},{"hanzi":"开心事","pinyin":"kāixīnshì","vi":"chuyện vui"}],"traditional":"傷心事"},{"id":"商业化","hanzi":"商业化","pinyin":"shāngyèhuà","meaning_vi":"thương mại hóa","explanation":"商 (thương mại/bàn bạc) + 业 (sự nghiệp/ngành nghề) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"古镇太商业化了。","pinyin":"Gǔzhèn tài shāngyèhuà le.","vi":"Thị trấn cổ bị thương mại hóa quá mức."},{"type":"simple","zh":"这项新技术预计明年实现商业化。","pinyin":"Zhè xiàng xīnjìshù yùjì míngnián shíxiàn shāngyèhuà.","vi":"Công nghệ mới này dự kiến sẽ được thương mại hóa vào năm sau."},{"type":"compound","zh":"节日一旦过度商业化，就会失去原来的意义。","pinyin":"Jiérì yídàn guòdù shāngyèhuà, jiù huì shīqù yuánlái de yìyì.","vi":"Lễ hội một khi bị thương mại hóa quá mức sẽ mất đi ý nghĩa ban đầu."}],"related":[{"hanzi":"商业","pinyin":"shāngyè","vi":"thương mại"},{"hanzi":"市场化","pinyin":"shìchǎnghuà","vi":"thị trường hóa"},{"hanzi":"商品化","pinyin":"shāngpǐnhuà","vi":"hàng hóa hóa"},{"hanzi":"过度商业化","pinyin":"guòdù shāngyèhuà","vi":"thương mại hóa quá mức"}],"traditional":"商業化"},{"id":"烧毁","hanzi":"烧毁","pinyin":"shāohuǐ","meaning_vi":"thiêu rụi","explanation":"烧 (đốt cháy/nấu) + 毁 (hủy diệt).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔥","examples":[{"type":"basic","zh":"大火烧毁了仓库。","pinyin":"Dàhuǒ shāohuǐle cāngkù.","vi":"Đám cháy lớn đã thiêu rụi nhà kho."},{"type":"simple","zh":"他把那些旧情书全部烧毁了。","pinyin":"Tā bǎ nàxiē jiù qíngshū quánbù shāohuǐ le.","vi":"Anh ấy đã đốt sạch những bức thư tình cũ đó."},{"type":"compound","zh":"因为电线老化短路，所以整间木屋都被烧毁了。","pinyin":"Yīnwèi diànxiàn lǎohuà duǎnlù, suǒyǐ zhěng jiān mù wū dōu bèi shāohuǐ le.","vi":"Vì dây điện cũ bị chập nên cả căn nhà gỗ bị thiêu rụi."}],"related":[{"hanzi":"焚烧","pinyin":"fénshāo","vi":"thiêu đốt"},{"hanzi":"火灾","pinyin":"huǒzāi","vi":"hỏa hoạn"},{"hanzi":"毁坏","pinyin":"huǐhuài","vi":"phá hủy"},{"hanzi":"烧伤","pinyin":"shāoshāng","vi":"bỏng"}],"traditional":"燒毀"},{"id":"稍后","hanzi":"稍后","pinyin":"shāohòu","meaning_vi":"một lát sau","explanation":"稍 (hơi một chút) + 后 (sau).","hsk_level":"7-9","tags":["pho-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"我稍后给你回电话。","pinyin":"Wǒ shāohòu gěi nǐ huí diànhuà.","vi":"Lát nữa tôi gọi lại cho bạn."},{"type":"simple","zh":"会议的详细安排将在稍后公布。","pinyin":"Huìyì de xiángxì ānpái jiāng zài shāohòu gōngbù.","vi":"Sắp xếp chi tiết của cuộc họp sẽ được công bố sau."},{"type":"compound","zh":"经理正在开会，如果您不着急，就请稍后再来。","pinyin":"Jīnglǐ zhèngzài kāihuì, rúguǒ nín bù zháojí, jiù qǐng shāohòu zài lái.","vi":"Giám đốc đang họp, nếu ngài không vội thì xin lát nữa quay lại."}],"related":[{"hanzi":"随后","pinyin":"suíhòu","vi":"sau đó"},{"hanzi":"等一会儿","pinyin":"děngyíhuìr","vi":"đợi một lát"},{"hanzi":"稍等","pinyin":"shāoděng","vi":"đợi chút"},{"hanzi":"马上","pinyin":"mǎshàng","vi":"ngay lập tức"}],"traditional":"稍後"},{"id":"稍许","hanzi":"稍许","pinyin":"shāoxǔ","meaning_vi":"một chút, hơi","explanation":"稍 (hơi một chút) + 许 (cho phép/hứa hẹn).","hsk_level":"7-9","tags":["pho-tu"],"image":"🤏","examples":[{"type":"basic","zh":"汤里稍许加点盐。","pinyin":"Tāng li shāoxǔ jiādiǎn yán.","vi":"Cho thêm chút muối vào canh."},{"type":"simple","zh":"听完解释后她的脸色稍许缓和了一些。","pinyin":"Tīng wán jiěshì hòu tā de liǎnsè shāoxǔ huǎnhéle yìxiē.","vi":"Nghe xong lời giải thích, sắc mặt cô ấy dịu đi đôi chút."},{"type":"compound","zh":"虽然价格稍许贵了一点，但是质量确实好很多。","pinyin":"Suīrán jiàgé shāoxǔ guìle yìdiǎn, dànshì zhìliàng quèshí hǎo hěn duō.","vi":"Tuy giá hơi đắt một chút nhưng chất lượng quả thực tốt hơn nhiều."}],"related":[{"hanzi":"稍微","pinyin":"shāowēi","vi":"hơi, một chút"},{"hanzi":"些许","pinyin":"xiēxǔ","vi":"chút ít"},{"hanzi":"一点儿","pinyin":"yìdiǎnr","vi":"một chút"},{"hanzi":"略微","pinyin":"lüèwēi","vi":"hơi"}],"traditional":"稍許"},{"id":"奢侈品","hanzi":"奢侈品","pinyin":"shēchǐpǐn","meaning_vi":"hàng xa xỉ, xa xỉ phẩm","explanation":"奢 (xa xỉ) + 侈 (侈) + 品 (phẩm chất/thưởng thức).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"💎","examples":[{"type":"basic","zh":"她从不买奢侈品。","pinyin":"Tā cóng bù mǎi shēchǐpǐn.","vi":"Cô ấy chưa bao giờ mua hàng xa xỉ."},{"type":"simple","zh":"机场免税店里的奢侈品比市区便宜不少。","pinyin":"Jīchǎng miǎnshuì diàn li de shēchǐpǐn bǐ shìqū piányi bùshǎo.","vi":"Hàng xa xỉ ở cửa hàng miễn thuế sân bay rẻ hơn trong thành phố khá nhiều."},{"type":"compound","zh":"与其花半年工资买奢侈品，不如拿去学一门技术。","pinyin":"Yǔqí huā bàn nián gōngzī mǎi shēchǐpǐn, bùrú ná qù xué yì mén jìshù.","vi":"Thay vì tiêu nửa năm lương mua hàng xa xỉ, chi bằng dùng để học một nghề."}],"related":[{"hanzi":"奢侈","pinyin":"shēchǐ","vi":"xa xỉ"},{"hanzi":"名牌","pinyin":"míngpái","vi":"hàng hiệu"},{"hanzi":"必需品","pinyin":"bìxūpǐn","vi":"hàng thiết yếu"},{"hanzi":"豪华","pinyin":"háohuá","vi":"sang trọng"}]},{"id":"身不由己","hanzi":"身不由己","pinyin":"shēnbù-yóujǐ","meaning_vi":"thân bất do kỷ (không thể tự quyết định)","explanation":"身 (thân phận/tự thân) + 不 (không/bất) + 由 (do) + 己 (己).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😔","examples":[{"type":"basic","zh":"在职场上常常身不由己。","pinyin":"Zài zhíchǎng shang chángcháng shēnbùyóujǐ.","vi":"Ở chốn công sở thường thân bất do kỷ."},{"type":"simple","zh":"他被拥挤的人群推着身不由己地往前走。","pinyin":"Tā bèi yōngjǐ de rénqún tuīzhe shēnbùyóujǐ de wǎng qián zǒu.","vi":"Anh ấy bị đám đông chen lấn đẩy đi, không tự chủ được mà bước về phía trước."},{"type":"compound","zh":"虽然他不想喝酒，但是在客户面前也身不由己。","pinyin":"Suīrán tā bù xiǎng hējiǔ, dànshì zài kèhù miànqián yě shēnbùyóujǐ.","vi":"Tuy không muốn uống rượu nhưng trước mặt khách hàng anh ấy cũng thân bất do kỷ."}],"related":[{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"không biết làm sao"},{"hanzi":"不由自主","pinyin":"bùyóuzìzhǔ","vi":"không tự chủ được"},{"hanzi":"被迫","pinyin":"bèipò","vi":"bị ép buộc"},{"hanzi":"自由自在","pinyin":"zìyóuzìzài","vi":"tự do tự tại"}]},{"id":"深层","hanzi":"深层","pinyin":"shēncéng","meaning_vi":"tầng sâu, chiều sâu","explanation":"深 (sâu) + 层 (tầng lớp/cấp bậc).","hsk_level":"7-9","tags":["tinh-tu","danh-tu"],"image":"🌊","examples":[{"type":"basic","zh":"这是深层原因。","pinyin":"Zhè shì shēncéng yuányīn.","vi":"Đây là nguyên nhân sâu xa."},{"type":"simple","zh":"这款洗面奶能深层清洁毛孔。","pinyin":"Zhè kuǎn xǐmiànnǎi néng shēncéng qīngjié máokǒng.","vi":"Sữa rửa mặt này có thể làm sạch sâu lỗ chân lông."},{"type":"compound","zh":"表面上是价格问题，实际上深层的矛盾是信任缺失。","pinyin":"Biǎomiànshang shì jiàgé wèntí, shíjìshang shēncéng de máodùn shì xìnrèn quēshī.","vi":"Bề ngoài là vấn đề giá cả, thực chất mâu thuẫn sâu xa là thiếu niềm tin."}],"related":[{"hanzi":"表层","pinyin":"biǎocéng","vi":"bề mặt"},{"hanzi":"深层次","pinyin":"shēncéngcì","vi":"tầng sâu"},{"hanzi":"深处","pinyin":"shēnchù","vi":"nơi sâu"},{"hanzi":"浅层","pinyin":"qiǎncéng","vi":"tầng nông"}],"traditional":"深層"},{"id":"深度","hanzi":"深度","pinyin":"shēndù","meaning_vi":"chiều sâu, chuyên sâu","explanation":"深 (thâm – sâu) + 度 (độ – mức độ) → độ sâu; nghĩa bóng là chiều sâu, mức độ sâu sắc. Ví dụ: 深度报道 (phóng sự chuyên sâu).","hsk_level":"7-9","tags":["danh-tu","tinh-tu"],"image":"🔍","examples":[{"type":"basic","zh":"这篇报道很有深度。","pinyin":"Zhè piān bàodào hěn yǒu shēndù.","vi":"Bài phóng sự này rất có chiều sâu."},{"type":"simple","zh":"这条河最深处的深度超过了二十米。","pinyin":"Zhè tiáo hé zuì shēnchù de shēndù chāoguòle èrshí mǐ.","vi":"Chỗ sâu nhất của con sông này có độ sâu hơn hai mươi mét."},{"type":"compound","zh":"他的演讲不但有趣，而且很有思想深度。","pinyin":"Tā de yǎnjiǎng búdàn yǒuqù, érqiě hěn yǒu sīxiǎng shēndù.","vi":"Bài diễn thuyết của anh ấy không những thú vị mà còn có chiều sâu tư tưởng."}],"related":[{"hanzi":"广度","pinyin":"guǎngdù","vi":"độ rộng"},{"hanzi":"深度报道","pinyin":"shēndùbàodào","vi":"đưa tin chuyên sâu"},{"hanzi":"深浅","pinyin":"shēnqiǎn","vi":"nông sâu"},{"hanzi":"高度","pinyin":"gāodù","vi":"độ cao"}]},{"id":"深化","hanzi":"深化","pinyin":"shēnhuà","meaning_vi":"làm sâu sắc thêm","explanation":"深 (thâm – sâu) + 化 (hóa – làm cho) → làm cho sâu sắc hơn, đẩy mạnh thêm. Thường đi với 改革, 合作, 认识.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌊","examples":[{"type":"basic","zh":"两国合作不断深化。","pinyin":"Liǎngguó hézuò búduàn shēnhuà.","vi":"Hợp tác giữa hai nước không ngừng được làm sâu sắc."},{"type":"simple","zh":"这次实地考察深化了我对农村的认识。","pinyin":"Zhè cì shídì kǎochá shēnhuàle wǒ duì nóngcūn de rènshi.","vi":"Chuyến khảo sát thực địa này làm sâu sắc thêm hiểu biết của tôi về nông thôn."},{"type":"compound","zh":"随着交流的增加，两校的友谊也在不断深化。","pinyin":"Suízhe jiāoliú de zēngjiā, liǎng xiào de yǒuyì yě zài búduàn shēnhuà.","vi":"Cùng với giao lưu tăng lên, tình hữu nghị giữa hai trường cũng không ngừng sâu sắc hơn."}],"related":[{"hanzi":"加深","pinyin":"jiāshēn","vi":"làm sâu thêm"},{"hanzi":"深化改革","pinyin":"shēnhuàgǎigé","vi":"cải cách sâu rộng"},{"hanzi":"强化","pinyin":"qiánghuà","vi":"tăng cường"},{"hanzi":"深入","pinyin":"shēnrù","vi":"đi sâu"}]},{"id":"深化改革","hanzi":"深化改革","pinyin":"shēnhuàgǎigé","meaning_vi":"đẩy mạnh cải cách sâu rộng","explanation":"深化 (thâm hóa – làm sâu sắc thêm) + 改革 (cải cách) → đẩy mạnh cải cách theo chiều sâu; thuật ngữ thường gặp trong văn bản chính sách TQ.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚀","examples":[{"type":"basic","zh":"国家决定深化改革。","pinyin":"Guójiā juédìng shēnhuàgǎigé.","vi":"Nhà nước quyết định đẩy mạnh cải cách."},{"type":"simple","zh":"政府提出要在医疗领域深化改革。","pinyin":"Zhèngfǔ tíchū yào zài yīliáo lǐngyù shēnhuàgǎigé.","vi":"Chính phủ đề ra việc phải cải cách sâu rộng trong lĩnh vực y tế."},{"type":"compound","zh":"只有深化改革，国有企业才能真正提高效率。","pinyin":"Zhǐyǒu shēnhuàgǎigé, guóyǒuqǐyè cáinéng zhēnzhèng tígāo xiàolǜ.","vi":"Chỉ có đẩy mạnh cải cách, doanh nghiệp nhà nước mới thực sự nâng cao hiệu quả."}],"related":[{"hanzi":"改革开放","pinyin":"gǎigékāifàng","vi":"cải cách mở cửa"},{"hanzi":"改革","pinyin":"gǎigé","vi":"cải cách"},{"hanzi":"体制","pinyin":"tǐzhì","vi":"thể chế"},{"hanzi":"深化","pinyin":"shēnhuà","vi":"làm sâu sắc"}]},{"id":"深厚","hanzi":"深厚","pinyin":"shēnhòu","meaning_vi":"sâu đậm, thâm hậu (tình cảm/nền tảng)","explanation":"深 (thâm – sâu) + 厚 (hậu – dày) → sâu và dày, tức sâu đậm, vững chắc. Thường đi với 感情, 友谊, 基础, 功底.","hsk_level":"7-9","tags":["tinh-tu"],"image":"❤️","examples":[{"type":"basic","zh":"他们感情深厚。","pinyin":"Tāmen gǎnqíng shēnhòu.","vi":"Tình cảm của họ sâu đậm."},{"type":"simple","zh":"这位老教授有着深厚的古典文学功底。","pinyin":"Zhè wèi lǎo jiàoshòu yǒuzhe shēnhòu de gǔdiǎn wénxué gōngdǐ.","vi":"Vị giáo sư già này có nền tảng văn học cổ điển thâm hậu."},{"type":"compound","zh":"他们虽然分开二十年，但是友谊依然深厚。","pinyin":"Tāmen suīrán fēnkāi èrshí nián, dànshì yǒuyì yīrán shēnhòu.","vi":"Tuy xa nhau hai mươi năm nhưng tình bạn của họ vẫn sâu đậm."}],"related":[{"hanzi":"深情","pinyin":"shēnqíng","vi":"tình sâu đậm"},{"hanzi":"浓厚","pinyin":"nónghòu","vi":"nồng hậu"},{"hanzi":"雄厚","pinyin":"xiónghòu","vi":"hùng hậu"},{"hanzi":"浅薄","pinyin":"qiǎnbó","vi":"nông cạn"}]},{"id":"身价","hanzi":"身价","pinyin":"shēnjià","meaning_vi":"giá trị bản thân, mức cát-xê","explanation":"身 (thân phận/tự thân) + 价 (价).","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"这名球员身价过亿。","pinyin":"Zhè míng qiúyuán shēnjiàguò yì.","vi":"Cầu thủ này có giá trị chuyển nhượng hơn trăm triệu."},{"type":"simple","zh":"获得金像奖后她的身价翻了好几倍。","pinyin":"Huòdé jīn xiàng jiǎng hòu tā de shēnjià fānle hǎo jǐbèi.","vi":"Sau khi giành giải Kim Tượng, cát-xê của cô ấy tăng gấp mấy lần."},{"type":"compound","zh":"一旦拿到世界冠军，他的身价就会大幅上涨。","pinyin":"Yídàn nádào shìjiè guànjūn, tā de shēnjià jiù huì dàfú shàngzhǎng.","vi":"Một khi giành chức vô địch thế giới, giá trị của anh ấy sẽ tăng mạnh."}],"related":[{"hanzi":"身价百倍","pinyin":"shēnjiàbǎibèi","vi":"giá trị tăng vọt"},{"hanzi":"片酬","pinyin":"piànchóu","vi":"cát-xê đóng phim"},{"hanzi":"价值","pinyin":"jiàzhí","vi":"giá trị"},{"hanzi":"身份","pinyin":"shēnfen","vi":"thân phận"}],"traditional":"身價"},{"id":"深究","hanzi":"深究","pinyin":"shēnjiū","meaning_vi":"nghiên cứu đào sâu, truy cứu kỹ","explanation":"深 (sâu) + 究 (nghiên cứu/truy cứu).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"这件事不必深究。","pinyin":"Zhè jiàn shì búbì shēnjiū.","vi":"Chuyện này không cần truy cứu sâu."},{"type":"simple","zh":"警方决定深究这起事故背后的责任。","pinyin":"Jǐngfāng juédìng shēnjiū zhè qǐ shìgù bèihòu de zérèn.","vi":"Cảnh sát quyết định truy cứu kỹ trách nhiệm đằng sau vụ tai nạn này."},{"type":"compound","zh":"如果深究下去，就会发现问题出在管理上。","pinyin":"Rúguǒ shēnjiū xiàqù, jiù huì fāxiàn wèntí chū zài guǎnlǐ shang.","vi":"Nếu đào sâu tiếp sẽ phát hiện vấn đề nằm ở khâu quản lý."}],"related":[{"hanzi":"追究","pinyin":"zhuījiū","vi":"truy cứu"},{"hanzi":"探究","pinyin":"tànjiū","vi":"tìm tòi"},{"hanzi":"钻研","pinyin":"zuānyán","vi":"nghiên cứu sâu"},{"hanzi":"不必深究","pinyin":"búbìshēnjiū","vi":"không cần truy cứu"}]},{"id":"身手","hanzi":"身手","pinyin":"shēnshǒu","meaning_vi":"tài nghệ, bản lĩnh","explanation":"身 (thân phận/tự thân) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🥋","examples":[{"type":"basic","zh":"他身手不凡。","pinyin":"Tā shēnshǒu bùfán.","vi":"Anh ấy bản lĩnh phi thường."},{"type":"simple","zh":"年轻的守门员在决赛中大显身手。","pinyin":"Niánqīng de shǒuményuán zài juésài zhōng dàxiǎnshēnshǒu.","vi":"Thủ môn trẻ đã thể hiện hết tài năng trong trận chung kết."},{"type":"compound","zh":"别看他个子小，他的身手却非常灵活。","pinyin":"Biékàn tā gèzi xiǎo, tā de shēnshǒu què fēicháng línghuó.","vi":"Đừng thấy anh ấy nhỏ con, thân thủ lại vô cùng linh hoạt."}],"related":[{"hanzi":"身手不凡","pinyin":"shēnshǒubùfán","vi":"tài nghệ phi phàm"},{"hanzi":"本领","pinyin":"běnlǐng","vi":"bản lĩnh"},{"hanzi":"功夫","pinyin":"gōngfu","vi":"võ công"},{"hanzi":"大显身手","pinyin":"dàxiǎnshēnshǒu","vi":"trổ hết tài năng"}]},{"id":"深邃","hanzi":"深邃","pinyin":"shēnsuì","meaning_vi":"sâu thẳm, uyên thâm (ánh mắt/tư tưởng)","explanation":"深 (sâu) + 邃 (sâu thẳm/uyên thâm).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌌","examples":[{"type":"basic","zh":"她的眼睛很深邃。","pinyin":"Tā de yǎnjing hěn shēnsuì.","vi":"Đôi mắt cô ấy rất sâu thẳm."},{"type":"simple","zh":"夜晚的星空显得格外深邃。","pinyin":"Yèwǎn de xīngkōng xiǎnde géwài shēnsuì.","vi":"Bầu trời sao ban đêm trông sâu thẳm lạ thường."},{"type":"compound","zh":"这本书语言虽然朴素，但是思想十分深邃。","pinyin":"Zhè běn shū yǔyán suīrán pǔsù, dànshì sīxiǎng shífēn shēnsuì.","vi":"Cuốn sách này ngôn ngữ tuy giản dị nhưng tư tưởng rất uyên thâm."}],"related":[{"hanzi":"深远","pinyin":"shēnyuǎn","vi":"sâu xa"},{"hanzi":"深沉","pinyin":"shēnchén","vi":"sâu lắng"},{"hanzi":"幽深","pinyin":"yōushēn","vi":"sâu thẳm"},{"hanzi":"眼神","pinyin":"yǎnshén","vi":"ánh mắt"}]},{"id":"申诉","hanzi":"申诉","pinyin":"shēnsù","meaning_vi":"khiếu nại, kháng cáo","explanation":"申 (khai báo/trình bày) + 诉 (tố tụng/kể lể).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"他向法院提出申诉。","pinyin":"Tā xiàng fǎyuàn tíchū shēnsù.","vi":"Anh ấy nộp đơn kháng cáo lên tòa án."},{"type":"simple","zh":"被平台封号的商家可以在七天内申诉。","pinyin":"Bèi píngtái fēnghào de shāngjiā kěyǐ zài qī tiān nèi shēnsù.","vi":"Người bán bị nền tảng khóa tài khoản có thể khiếu nại trong vòng bảy ngày."},{"type":"compound","zh":"如果你对处理结果不满意，就可以向上级部门申诉。","pinyin":"Rúguǒ nǐ duì chǔlǐ jiéguǒ bù mǎnyì, jiù kěyǐ xiàng shàngjí bùmén shēnsù.","vi":"Nếu bạn không hài lòng với kết quả xử lý thì có thể khiếu nại lên cơ quan cấp trên."}],"related":[{"hanzi":"上诉","pinyin":"shàngsù","vi":"kháng cáo"},{"hanzi":"投诉","pinyin":"tóusù","vi":"khiếu nại"},{"hanzi":"申辩","pinyin":"shēnbiàn","vi":"biện bạch"},{"hanzi":"诉讼","pinyin":"sùsòng","vi":"tố tụng"}],"traditional":"申訴"},{"id":"呻吟","hanzi":"呻吟","pinyin":"shēnyín","meaning_vi":"rên rỉ (vì đau đớn)","explanation":"Cả hai chữ đều có bộ khẩu 口.","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"😣","examples":[{"type":"basic","zh":"病人痛苦地呻吟着。","pinyin":"Bìngrén tòngkǔ de shēnyín zhe.","vi":"Bệnh nhân rên rỉ đau đớn."},{"type":"simple","zh":"半夜病房里传来一阵阵低声的呻吟。","pinyin":"Bànyè bìngfáng li chuánlái yízhèn zhèn dīshēng de shēnyín.","vi":"Nửa đêm trong phòng bệnh vọng ra từng tiếng rên khe khẽ."},{"type":"compound","zh":"他虽然伤得很重，但是一声也没有呻吟。","pinyin":"Tā suīrán shāng de hěn zhòng, dànshì yìshēng yě méiyǒu shēnyín.","vi":"Tuy bị thương rất nặng nhưng anh ấy không rên một tiếng nào."}],"related":[{"hanzi":"叹息","pinyin":"tànxī","vi":"thở dài"},{"hanzi":"哀叫","pinyin":"āijiào","vi":"kêu thảm"},{"hanzi":"疼痛","pinyin":"téngtòng","vi":"đau đớn"},{"hanzi":"无病呻吟","pinyin":"wúbìngshēnyín","vi":"không ốm mà rên"}]},{"id":"深知","hanzi":"深知","pinyin":"shēnzhī","meaning_vi":"hiểu rõ sâu sắc","explanation":"深 (sâu) + 知 (tri thức/tri giác).","hsk_level":"7-9","tags":["dong-tu"],"image":"💡","examples":[{"type":"basic","zh":"我深知其中的难处。","pinyin":"Wǒ shēnzhī qízhōng de nánchù.","vi":"Tôi hiểu rõ những khó khăn trong đó."},{"type":"simple","zh":"老船长深知这片海域的危险。","pinyin":"Lǎo chuánzhǎng shēnzhī zhè piàn Hǎiyù de wēixiǎn.","vi":"Thuyền trưởng già hiểu rõ sự nguy hiểm của vùng biển này."},{"type":"compound","zh":"因为他深知时间宝贵，所以从来不浪费一分钟。","pinyin":"Yīnwèi tā shēnzhī shíjiān bǎoguì, suǒyǐ cóngláibú làngfèi yì fēnzhōng.","vi":"Vì anh ấy hiểu rõ thời gian quý giá nên chưa bao giờ lãng phí một phút."}],"related":[{"hanzi":"深信","pinyin":"shēnxìn","vi":"tin tưởng sâu sắc"},{"hanzi":"明白","pinyin":"míngbai","vi":"hiểu rõ"},{"hanzi":"了解","pinyin":"liǎojiě","vi":"hiểu biết"},{"hanzi":"心知肚明","pinyin":"xīnzhīdùmíng","vi":"biết rõ trong lòng"}]},{"id":"伸展","hanzi":"伸展","pinyin":"shēnzhǎn","meaning_vi":"duỗi ra, mở rộng","explanation":"伸 (duỗi ra) + 展 (triển lãm/phát triển).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤸","examples":[{"type":"basic","zh":"猫伸展了一下身体。","pinyin":"Māo shēnzhǎnle yíxià shēntǐ.","vi":"Con mèo vươn mình một cái."},{"type":"simple","zh":"树枝向四面八方伸展开来。","pinyin":"Shùzhī xiàng sìmiànbāfāng shēnzhǎn kāi lái.","vi":"Cành cây vươn ra khắp bốn phương tám hướng."},{"type":"compound","zh":"如果坐了一上午，就应该站起来伸展一下四肢。","pinyin":"Rúguǒ zuòle yí shàngwǔ, jiù yīnggāi zhànqǐlái shēnzhǎn yíxià sìzhī.","vi":"Nếu đã ngồi cả buổi sáng thì nên đứng dậy duỗi tay chân một chút."}],"related":[{"hanzi":"舒展","pinyin":"shūzhǎn","vi":"duỗi thẳng"},{"hanzi":"伸开","pinyin":"shēnkāi","vi":"duỗi ra"},{"hanzi":"扩展","pinyin":"kuòzhǎn","vi":"mở rộng"},{"hanzi":"收缩","pinyin":"shōusuō","vi":"co lại"}]},{"id":"深造","hanzi":"深造","pinyin":"shēnzào","meaning_vi":"học lên cao, tu nghiệp chuyên sâu","explanation":"深 (sâu) + 造 (sáng tạo/chế tạo).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"她出国深造了。","pinyin":"Tā chūguó shēnzào le.","vi":"Cô ấy ra nước ngoài học lên cao."},{"type":"simple","zh":"他打算毕业后去德国继续深造。","pinyin":"Tā dǎsuàn bìyè hòu qù Déguó jìxù shēnzào.","vi":"Anh ấy dự định sau khi tốt nghiệp sẽ sang Đức tiếp tục học lên cao."},{"type":"compound","zh":"虽然工作机会很好，但是她还是选择继续深造。","pinyin":"Suīrán gōngzuò jīhuì hěn hǎo, dànshì tā háishì xuǎnzé jìxù shēnzào.","vi":"Tuy cơ hội việc làm rất tốt nhưng cô ấy vẫn chọn tiếp tục học lên."}],"related":[{"hanzi":"进修","pinyin":"jìnxiū","vi":"tu nghiệp"},{"hanzi":"留学","pinyin":"liúxué","vi":"du học"},{"hanzi":"读研","pinyin":"dúyán","vi":"học cao học"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"}]},{"id":"生活费","hanzi":"生活费","pinyin":"shēnghuófèi","meaning_vi":"sinh hoạt phí","explanation":"生活 (sinh hoạt – cuộc sống) + 费 (phí) → tiền chi tiêu cho cuộc sống hằng ngày như ăn ở, đi lại. Ví dụ: 每月生活费.","hsk_level":"7-9","tags":["danh-tu","sinh-hoat","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"这是下月的生活费。","pinyin":"Zhè shì xiàyuè de shēnghuófèi.","vi":"Đây là sinh hoạt phí tháng sau."},{"type":"simple","zh":"父母每个月给他打两千块生活费。","pinyin":"Fùmǔ měi gèyuè gěi tā dǎ liǎng qiān kuài shēnghuófèi.","vi":"Bố mẹ mỗi tháng chuyển cho cậu ấy hai nghìn tệ sinh hoạt phí."},{"type":"compound","zh":"为了减轻家里负担，他一边上学一边打工挣生活费。","pinyin":"Wèile jiǎnqīng jiāli fùdān, tā yìbiān shàngxué yìbiān dǎgōng zhèng shēnghuófèi.","vi":"Để giảm gánh nặng cho gia đình, cậu ấy vừa đi học vừa làm thêm kiếm sinh hoạt phí."}],"related":[{"hanzi":"学费","pinyin":"xuéfèi","vi":"học phí"},{"hanzi":"开销","pinyin":"kāixiāo","vi":"chi tiêu"},{"hanzi":"零花钱","pinyin":"línghuāqián","vi":"tiền tiêu vặt"},{"hanzi":"房租","pinyin":"fángzū","vi":"tiền thuê nhà"}],"traditional":"生活費"},{"id":"生计","hanzi":"生计","pinyin":"shēngjì","meaning_vi":"kế sinh nhai","explanation":"生 (sinh tồn/sinh động) + 计 (kế hoạch/tính toán).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他为生计奔波。","pinyin":"Tā wèi shēngjì bēnbō.","vi":"Anh ấy bôn ba vì kế sinh nhai."},{"type":"simple","zh":"渔民们靠这片海维持全家的生计。","pinyin":"Yúmínmen kào zhè piàn hǎi wéichí quánjiā de shēngjì.","vi":"Ngư dân dựa vào vùng biển này để duy trì kế sinh nhai cả nhà."},{"type":"compound","zh":"工厂一旦倒闭，几百个家庭的生计就会成问题。","pinyin":"Gōngchǎng yídàn dǎobì, jǐ bǎi gè jiātíng de shēngjì jiù huì chéngwèntí.","vi":"Nhà máy một khi đóng cửa, kế sinh nhai của mấy trăm gia đình sẽ thành vấn đề."}],"related":[{"hanzi":"谋生","pinyin":"móushēng","vi":"mưu sinh"},{"hanzi":"生活","pinyin":"shēnghuó","vi":"cuộc sống"},{"hanzi":"饭碗","pinyin":"fànwǎn","vi":"bát cơm, nghề"},{"hanzi":"养家糊口","pinyin":"yǎngjiāhúkǒu","vi":"nuôi sống gia đình"}],"traditional":"生計"},{"id":"声乐","hanzi":"声乐","pinyin":"shēngyuè","meaning_vi":"thanh nhạc","explanation":"声 (thanh thế/tuyên bố) + 乐 (vui vẻ/lạc quan).","hsk_level":"7-9","tags":["danh-tu","giai-tri","hoc-tap"],"image":"🎤","examples":[{"type":"basic","zh":"她在学声乐。","pinyin":"Tā zài xué shēngyuè.","vi":"Cô ấy đang học thanh nhạc."},{"type":"simple","zh":"他从小跟着一位名师学习声乐。","pinyin":"Tā cóngxiǎo gēnzhe yí wèi míngshī xuéxí shēngyuè.","vi":"Từ nhỏ anh ấy đã học thanh nhạc với một danh sư."},{"type":"compound","zh":"学声乐不但要有好嗓子，而且要长期坚持练习。","pinyin":"Xué shēngyuè búdàn yàoyǒu hǎo sǎngzi, érqiě yào chángqī jiānchí liànxí.","vi":"Học thanh nhạc không chỉ cần giọng tốt mà còn phải kiên trì luyện tập lâu dài."}],"related":[{"hanzi":"器乐","pinyin":"qìyuè","vi":"khí nhạc"},{"hanzi":"歌唱","pinyin":"gēchàng","vi":"ca hát"},{"hanzi":"音乐","pinyin":"yīnyuè","vi":"âm nhạc"},{"hanzi":"歌手","pinyin":"gēshǒu","vi":"ca sĩ"}],"traditional":"聲樂"},{"id":"生僻字","hanzi":"生僻字","pinyin":"shēngpìzì","meaning_vi":"chữ Hán hiếm gặp","explanation":"生 (sinh tồn/sinh động) + 僻 (僻) + 字 (chữ).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🈷️","examples":[{"type":"basic","zh":"这个名字有生僻字。","pinyin":"Zhè ge míngzi yǒu shēngpìzì.","vi":"Cái tên này có chữ hiếm gặp."},{"type":"simple","zh":"古籍里的生僻字让学生们读得很吃力。","pinyin":"Gǔjí li de shēngpìzì ràng xuéshengmen dú de hěn chīlì.","vi":"Những chữ hiếm trong sách cổ khiến học sinh đọc rất vất vả."},{"type":"compound","zh":"遇到生僻字时，只要查一下字典就能知道读音。","pinyin":"Yùdào shēngpìzì shí, zhǐyào chá yíxià zìdiǎn jiù néng zhīdào dúyīn.","vi":"Khi gặp chữ hiếm, chỉ cần tra từ điển là biết cách đọc."}],"related":[{"hanzi":"汉字","pinyin":"hànzì","vi":"chữ Hán"},{"hanzi":"常用字","pinyin":"chángyòngzì","vi":"chữ thường dùng"},{"hanzi":"繁体字","pinyin":"fántǐzì","vi":"chữ phồn thể"},{"hanzi":"字典","pinyin":"zìdiǎn","vi":"từ điển"}]},{"id":"生态平衡","hanzi":"生态平衡","pinyin":"shēngtàipínghéng","meaning_vi":"cân bằng sinh thái","explanation":"生 (sinh tồn/sinh động) + 态 (trạng thái/thái độ) + 平 (bằng phẳng) + 衡 (cân nhắc/cân bằng).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"⚖️","examples":[{"type":"basic","zh":"要保护生态平衡。","pinyin":"Yào bǎohù shēngtàipínghéng.","vi":"Phải bảo vệ cân bằng sinh thái."},{"type":"simple","zh":"外来物种的入侵破坏了湖泊的生态平衡。","pinyin":"Wàilái wùzhǒng de rùqīn pòhuàile húpō de shēngtàipínghéng.","vi":"Sự xâm lấn của loài ngoại lai đã phá vỡ cân bằng sinh thái của hồ."},{"type":"compound","zh":"如果狼被捕杀光了，草原的生态平衡就会被打破。","pinyin":"Rúguǒ láng bèibǔ shā guāng le, cǎoyuán de shēngtàipínghéng jiù huì bèi dǎpò.","vi":"Nếu sói bị săn bắt hết, cân bằng sinh thái của đồng cỏ sẽ bị phá vỡ."}],"related":[{"hanzi":"生态系统","pinyin":"shēngtàixìtǒng","vi":"hệ sinh thái"},{"hanzi":"环境保护","pinyin":"huánjìngbǎohù","vi":"bảo vệ môi trường"},{"hanzi":"失衡","pinyin":"shīhéng","vi":"mất cân bằng"},{"hanzi":"生物多样性","pinyin":"shēngwù duōyàngxìng","vi":"đa dạng sinh học"}],"traditional":"生態平衡"},{"id":"生物多样性","hanzi":"生物多样性","pinyin":"shēngwù duōyàngxìng","meaning_vi":"đa dạng sinh học","explanation":"生 (sinh tồn/sinh động) + 物 (vật chất/sự vật) + 多 (nhiều) + 样 (mẫu mã/kiểu dáng) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🦋","examples":[{"type":"basic","zh":"雨林生物多样性丰富。","pinyin":"Yǔlín shēngwùduōyàngxìng fēngfù.","vi":"Rừng mưa có đa dạng sinh học phong phú."},{"type":"simple","zh":"科学家们正在调查珊瑚礁的生物多样性。","pinyin":"Kēxuéjiāmen zhèngzài diàochá shānhújiāo de shēngwùduōyàngxìng.","vi":"Các nhà khoa học đang điều tra đa dạng sinh học của rạn san hô."},{"type":"compound","zh":"一旦湿地被填平，当地的生物多样性就会大大下降。","pinyin":"Yídàn shīdì bèi tián píng, dāngdì de shēngwùduōyàngxìng jiù huì dàdà xiàjiàng.","vi":"Một khi vùng đất ngập nước bị san lấp, đa dạng sinh học ở đó sẽ giảm mạnh."}],"related":[{"hanzi":"物种","pinyin":"wùzhǒng","vi":"loài"},{"hanzi":"生态系统","pinyin":"shēngtàixìtǒng","vi":"hệ sinh thái"},{"hanzi":"濒危","pinyin":"bīnwēi","vi":"có nguy cơ tuyệt chủng"},{"hanzi":"生态平衡","pinyin":"shēngtàipínghéng","vi":"cân bằng sinh thái"}],"traditional":"生物多樣性"},{"id":"生物技术","hanzi":"生物技术","pinyin":"shēngwùjìshù","meaning_vi":"công nghệ sinh học","explanation":"生 (sinh tồn/sinh động) + 物 (vật chất/sự vật) + 技 (kỹ thuật) + 术 (术).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🧬","examples":[{"type":"basic","zh":"他研究生物技术。","pinyin":"Tā yánjiū shēngwùjìshù.","vi":"Anh ấy nghiên cứu công nghệ sinh học."},{"type":"simple","zh":"这家生物技术公司研发出了新型疫苗。","pinyin":"Zhè jiā shēngwùjìshù gōngsī yánfā chūle xīnxíng yìmiáo.","vi":"Công ty công nghệ sinh học này đã nghiên cứu ra loại vắc-xin mới."},{"type":"compound","zh":"生物技术虽然能提高粮食产量，但是也引起了伦理争议。","pinyin":"Shēngwùjìshù suīrán néng tígāo liángshi chǎnliàng, dànshì yě yǐnqǐle lúnlǐ zhēngyì.","vi":"Công nghệ sinh học tuy có thể tăng sản lượng lương thực nhưng cũng gây tranh cãi về đạo đức."}],"related":[{"hanzi":"基因","pinyin":"jīyīn","vi":"gen"},{"hanzi":"生物学","pinyin":"shēngwùxué","vi":"sinh học"},{"hanzi":"科技","pinyin":"kējì","vi":"khoa học công nghệ"},{"hanzi":"克隆","pinyin":"kèlóng","vi":"nhân bản vô tính"}],"traditional":"生物技術"},{"id":"生肖","hanzi":"生肖","pinyin":"shēngxiào","meaning_vi":"con giáp (12 con giáp)","explanation":"生 (sinh – năm sinh) + 肖 (tiếu – giống, tượng trưng) → con vật tượng trưng cho năm sinh, tức con giáp. Cụm: 十二生肖; hỏi tuổi: 你属什么?","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🐉","examples":[{"type":"basic","zh":"你的生肖是什么？","pinyin":"Nǐ de shēngxiào shì shénme?","vi":"Bạn tuổi con gì?"},{"type":"simple","zh":"今年春节的邮票印着龙的生肖图案。","pinyin":"Jīnnián Chūnjié de yóupiào yìnzhe lóng de shēngxiào tú'àn.","vi":"Tem Tết năm nay in hình con giáp rồng."},{"type":"compound","zh":"越南的生肖和中国差不多，只是把兔换成了猫。","pinyin":"Yuènán de shēngxiào hé Zhōngguó chàbuduō, zhǐshì bǎ tù huànchéngle māo.","vi":"Mười hai con giáp của Việt Nam gần giống Trung Quốc, chỉ là thay thỏ bằng mèo."}],"related":[{"hanzi":"属相","pinyin":"shǔxiang","vi":"tuổi con giáp"},{"hanzi":"十二生肖","pinyin":"shí'èrshēngxiào","vi":"mười hai con giáp"},{"hanzi":"本命年","pinyin":"běnmìngnián","vi":"năm tuổi"},{"hanzi":"星座","pinyin":"xīngzuò","vi":"cung hoàng đạo"}]},{"id":"生性","hanzi":"生性","pinyin":"shēngxìng","meaning_vi":"bản tính trời sinh","explanation":"生 (sinh tồn/sinh động) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"他生性胆小。","pinyin":"Tā shēngxìng dǎnxiǎo.","vi":"Anh ấy bản tính nhút nhát."},{"type":"simple","zh":"这位生性孤僻的作家很少参加社交活动。","pinyin":"Zhè wèi shēngxìng gūpì de zuòjiā hěn shǎo cānjiā shèjiāo huódòng.","vi":"Vị nhà văn bản tính cô độc này hiếm khi tham gia hoạt động xã giao."},{"type":"compound","zh":"她生性乐观，所以再大的困难也压不垮她。","pinyin":"Tā shēngxìng lèguān, suǒyǐ zài dà de kùnnan yě yā bù kuǎ tā.","vi":"Cô ấy bản tính lạc quan nên khó khăn lớn đến mấy cũng không đè bẹp được cô."}],"related":[{"hanzi":"天性","pinyin":"tiānxìng","vi":"bản tính"},{"hanzi":"本性","pinyin":"běnxìng","vi":"bản chất"},{"hanzi":"性格","pinyin":"xìnggé","vi":"tính cách"},{"hanzi":"天生","pinyin":"tiānshēng","vi":"bẩm sinh"}]},{"id":"升值","hanzi":"升值","pinyin":"shēngzhí","meaning_vi":"tăng giá trị (tiền tệ/bất động sản)","explanation":"升 (tăng lên) + 值 (giá trị).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"📈","examples":[{"type":"basic","zh":"人民币又升值了。","pinyin":"Rénmínbì yòu shēngzhí le.","vi":"Nhân dân tệ lại tăng giá."},{"type":"simple","zh":"地铁修通后附近的房子明显升值了。","pinyin":"Dìtiě xiū tōng hòu fùjìn de fángzi míngxiǎn shēngzhí le.","vi":"Sau khi tàu điện ngầm thông tuyến, nhà cửa gần đó tăng giá rõ rệt."},{"type":"compound","zh":"只要不断学习新技能，你自己就会不断升值。","pinyin":"Zhǐyào búduàn xuéxí xīn jìnéng, nǐ zìjǐ jiù huì búduàn shēngzhí.","vi":"Chỉ cần không ngừng học kỹ năng mới, giá trị bản thân bạn sẽ không ngừng tăng."}],"related":[{"hanzi":"贬值","pinyin":"biǎnzhí","vi":"mất giá"},{"hanzi":"增值","pinyin":"zēngzhí","vi":"tăng giá trị"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"保值","pinyin":"bǎozhí","vi":"giữ giá"}]},{"id":"舍弃","hanzi":"舍弃","pinyin":"shěqì","meaning_vi":"vứt bỏ, từ bỏ","explanation":"舍 (từ bỏ/bố thí) + 弃 (vứt bỏ/từ bỏ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🗑️","examples":[{"type":"basic","zh":"他舍弃了高薪工作。","pinyin":"Tā shěqìle gāoxīn gōngzuò.","vi":"Anh ấy từ bỏ công việc lương cao."},{"type":"simple","zh":"搬家时她舍弃了大半的旧衣服。","pinyin":"Bānjiā shí tā shěqìle dàbàn de jiù yīfu.","vi":"Khi chuyển nhà cô ấy bỏ đi quá nửa quần áo cũ."},{"type":"compound","zh":"有时候只有舍弃一些东西，才能得到更重要的。","pinyin":"Yǒushíhou zhǐyǒu shěqì yìxiē dōngxi, cáinéng dédào gèng zhòngyào de.","vi":"Đôi khi chỉ có từ bỏ một số thứ mới có được điều quan trọng hơn."}],"related":[{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"抛弃","pinyin":"pāoqì","vi":"vứt bỏ"},{"hanzi":"取舍","pinyin":"qǔshě","vi":"lựa chọn lấy bỏ"},{"hanzi":"保留","pinyin":"bǎoliú","vi":"giữ lại"}],"traditional":"捨棄"},{"id":"审视","hanzi":"审视","pinyin":"shěnshì","meaning_vi":"xem xét kỹ lưỡng, đánh giá lại","explanation":"审 (thẩm tra/xét xử) + 视 (tầm nhìn/coi trọng).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"👀","examples":[{"type":"basic","zh":"我们要重新审视计划。","pinyin":"Wǒmen yào chóngxīn shěnshì jìhuà.","vi":"Chúng ta phải xem xét lại kế hoạch."},{"type":"simple","zh":"他站在镜子前仔细审视自己的穿着。","pinyin":"Tā zhàn zài jìngzi qián zǐxì shěnshì zìjǐ de chuānzhuó.","vi":"Anh ấy đứng trước gương xem xét kỹ trang phục của mình."},{"type":"compound","zh":"每次项目失败，她都会冷静地审视自己的决策。","pinyin":"Měi cì xiàngmù shībài, tā dōuhuì lěngjìng de shěnshì zìjǐ de juécè.","vi":"Mỗi lần dự án thất bại, cô ấy đều bình tĩnh xem xét lại quyết định của mình."}],"related":[{"hanzi":"审查","pinyin":"shěnchá","vi":"thẩm tra"},{"hanzi":"反思","pinyin":"fǎnsī","vi":"suy ngẫm lại"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"},{"hanzi":"重新审视","pinyin":"chóngxīnshěnshì","vi":"nhìn nhận lại"}],"traditional":"審視"},{"id":"审阅","hanzi":"审阅","pinyin":"shěnyuè","meaning_vi":"duyệt xem (bản thảo/văn kiện)","explanation":"审 (thẩm tra/xét xử) + 阅 (đọc/duyệt).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📑","examples":[{"type":"basic","zh":"请您审阅这份报告。","pinyin":"Qǐng nín shěnyuè zhè fèn bàogào.","vi":"Xin ông duyệt bản báo cáo này."},{"type":"simple","zh":"主编连夜审阅了明天要发的头版稿件。","pinyin":"Zhǔbiān liányè shěnyuèle míngtiān yào fā de tóubǎn gǎojiàn.","vi":"Tổng biên tập thức đêm duyệt bản thảo trang nhất sẽ đăng ngày mai."},{"type":"compound","zh":"合同经过律师审阅以后，我们才能签字。","pinyin":"Hétong jīngguò lǜshī shěnyuè yǐhòu, wǒmen cáinéng qiānzì.","vi":"Hợp đồng phải qua luật sư duyệt xong chúng ta mới ký được."}],"related":[{"hanzi":"审核","pinyin":"shěnhé","vi":"thẩm định"},{"hanzi":"批阅","pinyin":"pīyuè","vi":"duyệt đọc"},{"hanzi":"阅读","pinyin":"yuèdú","vi":"đọc"},{"hanzi":"审稿","pinyin":"shěngǎo","vi":"duyệt bản thảo"}],"traditional":"審閱"},{"id":"失传","hanzi":"失传","pinyin":"shīchuán","meaning_vi":"thất truyền (kỹ nghệ/bí quyết cổ)","explanation":"失 (mất đi/sai sót) + 传 (truyền bá/truyền thống).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"这门手艺失传了。","pinyin":"Zhè mén shǒuyì shīchuán le.","vi":"Nghề thủ công này đã thất truyền."},{"type":"simple","zh":"这位老人用十年时间复原了一种失传的织布技术。","pinyin":"Zhè wèi lǎorén yòng shí nián shíjiān fùyuánle yì zhǒng shīchuán de zhībù jìshù.","vi":"Ông cụ dùng mười năm để phục dựng một kỹ thuật dệt vải đã thất truyền."},{"type":"compound","zh":"如果没有年轻人愿意学，这种古老的戏曲就会失传。","pinyin":"Rúguǒ méiyǒu niánqīngrén yuànyì xué, zhè zhǒng gǔlǎo de xìqǔ jiù huì shīchuán.","vi":"Nếu không có người trẻ nào muốn học, loại hí khúc cổ này sẽ thất truyền."}],"related":[{"hanzi":"流传","pinyin":"liúchuán","vi":"lưu truyền"},{"hanzi":"传承","pinyin":"chuánchéng","vi":"kế thừa"},{"hanzi":"绝技","pinyin":"juéjì","vi":"tuyệt kỹ"},{"hanzi":"濒临失传","pinyin":"bīnlínshīchuán","vi":"sắp thất truyền"}],"traditional":"失傳"},{"id":"师范","hanzi":"师范","pinyin":"shīfàn","meaning_vi":"sư phạm","explanation":"师 (thầy giáo/sư phụ) + 范 (范).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","nghe-nghiep"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"她考上了师范大学。","pinyin":"Tā kǎoshàngle shīfàn dàxué.","vi":"Cô ấy đỗ vào trường đại học sư phạm."},{"type":"simple","zh":"他师范毕业后回到家乡小学当老师。","pinyin":"Tā shīfàn bìyè hòu huídào jiāxiāng xiǎoxué dāng lǎoshī.","vi":"Tốt nghiệp sư phạm xong, anh ấy về trường tiểu học quê nhà làm giáo viên."},{"type":"compound","zh":"因为师范生可以免学费，所以很多农村孩子选择了这个专业。","pinyin":"Yīnwèi shīfànshēng kě yǐmiǎn xuéfèi, suǒyǐ hěn duō nóngcūn háizi xuǎnzéle zhè ge zhuānyè.","vi":"Vì sinh viên sư phạm được miễn học phí nên nhiều con em nông thôn đã chọn ngành này."}],"related":[{"hanzi":"师范大学","pinyin":"shīfàndàxué","vi":"đại học sư phạm"},{"hanzi":"教师","pinyin":"jiàoshī","vi":"giáo viên"},{"hanzi":"教育","pinyin":"jiàoyù","vi":"giáo dục"},{"hanzi":"师范生","pinyin":"shīfànshēng","vi":"sinh viên sư phạm"}],"traditional":"師範"},{"id":"施工","hanzi":"施工","pinyin":"shīgōng","meaning_vi":"thi công (công trình)","explanation":"施 (thi hành/thực hiện) + 工 (工).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏗️","examples":[{"type":"basic","zh":"前方道路施工。","pinyin":"Qiánfāng dàolù shīgōng.","vi":"Phía trước đường đang thi công."},{"type":"simple","zh":"工人们冒着高温在大桥上连夜施工。","pinyin":"Gōngrénmen màozhe gāowēn zài Dàqiáo shang liányè shīgōng.","vi":"Công nhân đội nắng nóng thi công xuyên đêm trên cây cầu lớn."},{"type":"compound","zh":"楼上一施工，我们家就吵得没法休息。","pinyin":"Lóushàng yì shīgōng, wǒmen jiā jiù chǎo de méifǎ xiūxi.","vi":"Tầng trên hễ thi công là nhà chúng tôi ồn ào không nghỉ ngơi được."}],"related":[{"hanzi":"工地","pinyin":"gōngdì","vi":"công trường"},{"hanzi":"建筑","pinyin":"jiànzhù","vi":"kiến trúc"},{"hanzi":"工程","pinyin":"gōngchéng","vi":"công trình"},{"hanzi":"竣工","pinyin":"jùngōng","vi":"hoàn công"}]},{"id":"失衡","hanzi":"失衡","pinyin":"shīhéng","meaning_vi":"mất cân bằng","explanation":"失 (mất đi/sai sót) + 衡 (cân nhắc/cân bằng).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"⚖️","examples":[{"type":"basic","zh":"他的心态失衡了。","pinyin":"Tā de xīntài shīhéng le.","vi":"Tâm lý anh ấy mất cân bằng rồi."},{"type":"simple","zh":"长期熬夜容易导致身体内分泌失衡。","pinyin":"Chángqī áoyè róngyì dǎozhì shēntǐ nèifēnmì shīhéng.","vi":"Thức khuya lâu ngày dễ khiến nội tiết cơ thể mất cân bằng."},{"type":"compound","zh":"如果男女比例严重失衡，就会带来很多社会问题。","pinyin":"Rúguǒ nánnǚ bǐlì yánzhòng shīhéng, jiù huì dàilái hěn duō shèhuì wèntí.","vi":"Nếu tỷ lệ nam nữ mất cân bằng nghiêm trọng sẽ gây ra nhiều vấn đề xã hội."}],"related":[{"hanzi":"平衡","pinyin":"pínghéng","vi":"cân bằng"},{"hanzi":"失调","pinyin":"shītiáo","vi":"mất điều hòa"},{"hanzi":"不平衡","pinyin":"bùpínghéng","vi":"không cân bằng"},{"hanzi":"生态失衡","pinyin":"shēngtàishīhéng","vi":"mất cân bằng sinh thái"}]},{"id":"失控","hanzi":"失控","pinyin":"shīkòng","meaning_vi":"mất kiểm soát","explanation":"失 (mất đi/sai sót) + 控 (khống chế/kiểm soát).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"汽车突然失控了。","pinyin":"Qìchē tūrán shīkòng le.","vi":"Chiếc xe bỗng mất kiểm soát."},{"type":"simple","zh":"那位父亲在家长会上情绪失控大哭起来。","pinyin":"Nà wèi fùqīn zài jiāzhǎnghuì shang qíngxù shīkòng dàkū qǐlái.","vi":"Người cha đó mất kiểm soát cảm xúc và bật khóc lớn trong buổi họp phụ huynh."},{"type":"compound","zh":"火势一旦失控，就会蔓延到整片森林。","pinyin":"Huǒshì yídàn shīkòng, jiù huì mànyán dào zhěng piàn sēnlín.","vi":"Ngọn lửa một khi mất kiểm soát sẽ lan ra cả khu rừng."}],"related":[{"hanzi":"控制","pinyin":"kòngzhì","vi":"kiểm soát"},{"hanzi":"失去控制","pinyin":"shīqùkòngzhì","vi":"mất kiểm soát"},{"hanzi":"情绪失控","pinyin":"qíngxùshīkòng","vi":"mất kiểm soát cảm xúc"},{"hanzi":"局面","pinyin":"júmiàn","vi":"cục diện"}]},{"id":"失落","hanzi":"失落","pinyin":"shīluò","meaning_vi":"hụt hẫng, mất mát","explanation":"失 (mất đi/sai sót) + 落 (rơi rụng/thực hiện).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"落选后他很失落。","pinyin":"Luòxuǎn hòu tā hěn shīluò.","vi":"Sau khi trượt, anh ấy rất hụt hẫng."},{"type":"simple","zh":"退休第一天他心里有一种说不出的失落。","pinyin":"Tuìxiū dìyī tiān tā xīnli yǒu yì zhǒng shuōbuchū de shīluò.","vi":"Ngày đầu nghỉ hưu, trong lòng ông có một cảm giác hụt hẫng khó tả."},{"type":"compound","zh":"虽然没拿到冠军，但是她并没有感到失落。","pinyin":"Suīrán méi nádào guànjūn, dànshì tā bìng méiyǒu gǎndào shīluò.","vi":"Tuy không giành được chức vô địch nhưng cô ấy không hề cảm thấy hụt hẫng."}],"related":[{"hanzi":"失望","pinyin":"shīwàng","vi":"thất vọng"},{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"落寞","pinyin":"luòmò","vi":"cô đơn hụt hẫng"},{"hanzi":"失落感","pinyin":"shīluògǎn","vi":"cảm giác hụt hẫng"}]},{"id":"失灵","hanzi":"失灵","pinyin":"shīlíng","meaning_vi":"hỏng hóc, mất tác dụng (phanh/máy móc)","explanation":"失 (mất đi/sai sót) + 灵 (linh hoạt/linh hồn).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔧","examples":[{"type":"basic","zh":"刹车突然失灵了。","pinyin":"Shāchē tūrán shīlíng le.","vi":"Phanh đột nhiên mất tác dụng."},{"type":"simple","zh":"停电导致整条街的红绿灯全部失灵。","pinyin":"Tíngdiàn dǎozhì zhěngtiáo jiē de hónglǜdēng quánbù shīlíng.","vi":"Mất điện khiến toàn bộ đèn giao thông trên cả con phố ngừng hoạt động."},{"type":"compound","zh":"因为手机导航失灵了，所以我们在山里迷了路。","pinyin":"Yīnwèi shǒujī dǎoháng shīlíng le, suǒyǐ wǒmen zài shān li míle lù.","vi":"Vì định vị điện thoại bị hỏng nên chúng tôi lạc đường trong núi."}],"related":[{"hanzi":"故障","pinyin":"gùzhàng","vi":"sự cố hỏng hóc"},{"hanzi":"刹车","pinyin":"shāchē","vi":"phanh"},{"hanzi":"失效","pinyin":"shīxiào","vi":"mất hiệu lực"},{"hanzi":"灵敏","pinyin":"língmǐn","vi":"nhạy bén"}],"traditional":"失靈"},{"id":"失明","hanzi":"失明","pinyin":"shīmíng","meaning_vi":"mù lòa, mất thị lực","explanation":"失 (mất đi/sai sót) + 明 (sáng suốt/rõ ràng).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🕶️","examples":[{"type":"basic","zh":"他十岁时失明了。","pinyin":"Tā shí suìshí shīmíng le.","vi":"Năm mười tuổi anh ấy bị mù."},{"type":"simple","zh":"这位失明的钢琴家靠听觉记住了上百首曲子。","pinyin":"Zhè wèi shīmíng de gāngqínjiā kào tīngjué jìzhùle shàng bǎi shǒu qǔzi.","vi":"Nghệ sĩ dương cầm khiếm thị này nhờ thính giác mà nhớ được hơn trăm bản nhạc."},{"type":"compound","zh":"如果青光眼不及时治疗，就可能导致失明。","pinyin":"Rúguǒ qīngguāngyǎn bù jíshí zhìliáo, jiù kěnéng dǎozhì shīmíng.","vi":"Nếu bệnh tăng nhãn áp không được chữa kịp thời thì có thể dẫn đến mù lòa."}],"related":[{"hanzi":"盲人","pinyin":"mángrén","vi":"người mù"},{"hanzi":"视力","pinyin":"shìlì","vi":"thị lực"},{"hanzi":"失聪","pinyin":"shīcōng","vi":"điếc"},{"hanzi":"复明","pinyin":"fùmíng","vi":"sáng mắt lại"}]},{"id":"湿气","hanzi":"湿气","pinyin":"shīqì","meaning_vi":"khí ẩm, độ ẩm","explanation":"湿 (ẩm ướt) + 气 (khí phách/khí hậu).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","suc-khoe"],"image":"💧","examples":[{"type":"basic","zh":"屋里湿气很重。","pinyin":"Wū li shīqì hěn zhòng.","vi":"Trong nhà hơi ẩm rất nặng."},{"type":"simple","zh":"南方的梅雨季节到处都弥漫着湿气。","pinyin":"Nánfāng de méiyǔ jìjié dàochù dōu mímànzhe shīqì.","vi":"Mùa mưa phùn ở phương Nam khắp nơi đều tràn ngập hơi ẩm."},{"type":"compound","zh":"中医认为，体内湿气太重的话，人就容易疲倦。","pinyin":"Zhōngyī rènwéi, tǐnèi shīqì tài zhòng dehuà, rén jiù róngyì píjuàn.","vi":"Đông y cho rằng nếu thấp khí trong cơ thể quá nặng thì con người dễ mệt mỏi."}],"related":[{"hanzi":"潮湿","pinyin":"cháoshī","vi":"ẩm ướt"},{"hanzi":"湿度","pinyin":"shīdù","vi":"độ ẩm"},{"hanzi":"干燥","pinyin":"gānzào","vi":"khô ráo"},{"hanzi":"除湿","pinyin":"chúshī","vi":"hút ẩm"}],"traditional":"濕氣"},{"id":"失手","hanzi":"失手","pinyin":"shīshǒu","meaning_vi":"lỡ tay; sơ suất, thất bại ngoài ý muốn","explanation":"失 (mất đi/sai sót) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤦","examples":[{"type":"basic","zh":"我失手打碎了碗。","pinyin":"Wǒ shīshǒu dǎsuìle wǎn.","vi":"Tôi lỡ tay làm vỡ cái bát."},{"type":"simple","zh":"这位老练的魔术师今晚竟然在台上失手了。","pinyin":"Zhè wèi lǎoliàn de móshùshī jīnwǎn jìngrán zài tái shang shīshǒu le.","vi":"Ảo thuật gia lão luyện này tối nay lại bất ngờ diễn hỏng trên sân khấu."},{"type":"compound","zh":"他一紧张就容易失手，所以比赛前要先放松。","pinyin":"Tā yì jǐnzhāng jiù róngyì shīshǒu, suǒyǐ bǐsài qián yào xiān fàngsōng.","vi":"Anh ấy hễ căng thẳng là dễ lỡ tay, nên trước trận phải thả lỏng."}],"related":[{"hanzi":"失误","pinyin":"shīwù","vi":"sai sót"},{"hanzi":"不小心","pinyin":"bùxiǎoxīn","vi":"không cẩn thận"},{"hanzi":"手滑","pinyin":"shǒuhuá","vi":"trượt tay"},{"hanzi":"失足","pinyin":"shīzú","vi":"sa chân"}]},{"id":"失散","hanzi":"失散","pinyin":"shīsàn","meaning_vi":"thất lạc nhau (người thân)","explanation":"失 (mất đi/sai sót) + 散 (phân tán/tản văn).","hsk_level":"7-9","tags":["dong-tu","gia-dinh"],"image":"😢","examples":[{"type":"basic","zh":"他们在战乱中失散了。","pinyin":"Tāmen zài zhànluàn zhōng shīsàn le.","vi":"Họ thất lạc nhau trong chiến loạn."},{"type":"simple","zh":"失散五十年的兄妹终于在电视节目上重逢。","pinyin":"Shīsàn wǔshí nián de xiōngmèi zhōngyú zài diànshì jiémù shang chóngféng.","vi":"Hai anh em thất lạc năm mươi năm cuối cùng đã đoàn tụ trên chương trình truyền hình."},{"type":"compound","zh":"虽然和家人失散多年，但是她从来没有放弃寻找。","pinyin":"Suīrán hé jiārén shīsàn duōnián, dànshì tā cónglái méiyǒu fàngqì xúnzhǎo.","vi":"Tuy thất lạc gia đình nhiều năm nhưng cô ấy chưa bao giờ từ bỏ việc tìm kiếm."}],"related":[{"hanzi":"离散","pinyin":"lísàn","vi":"ly tán"},{"hanzi":"团聚","pinyin":"tuánjù","vi":"đoàn tụ"},{"hanzi":"走散","pinyin":"zǒusàn","vi":"đi lạc nhau"},{"hanzi":"重逢","pinyin":"chóngféng","vi":"gặp lại"}]},{"id":"失调","hanzi":"失调","pinyin":"shītiáo","meaning_vi":"mất điều hòa, rối loạn (nội tiết/cân bằng)","explanation":"失 (mất đi/sai sót) + 调 (điều chỉnh/hòa giải).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"她内分泌失调了。","pinyin":"Tā nèifēnmì shītiáo le.","vi":"Cô ấy bị rối loạn nội tiết."},{"type":"simple","zh":"长期饮食不规律导致他营养失调。","pinyin":"Chángqī yǐnshí bù guīlǜ dǎozhì tā yíngyǎng shītiáo.","vi":"Ăn uống thất thường lâu ngày khiến anh ấy bị rối loạn dinh dưỡng."},{"type":"compound","zh":"一旦供求关系失调，物价就会大幅波动。","pinyin":"Yídàn gōngqiúguānxì shītiáo, wùjià jiù huì dàfú bōdòng.","vi":"Một khi quan hệ cung cầu mất cân đối, giá cả sẽ biến động mạnh."}],"related":[{"hanzi":"失衡","pinyin":"shīhéng","vi":"mất cân bằng"},{"hanzi":"内分泌失调","pinyin":"nèifēnmì shītiáo","vi":"rối loạn nội tiết"},{"hanzi":"协调","pinyin":"xiétiáo","vi":"điều hòa"},{"hanzi":"紊乱","pinyin":"wěnluàn","vi":"rối loạn"}],"traditional":"失調"},{"id":"失业保险","hanzi":"失业保险","pinyin":"shīyèbǎoxiǎn","meaning_vi":"bảo hiểm thất nghiệp","explanation":"失业 (thất nghiệp) + 保险 (bảo hiểm) → bảo hiểm chi trả trợ cấp cho người lao động khi mất việc; một trong 五险 ở TQ.","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"💼","examples":[{"type":"basic","zh":"他领到了失业保险。","pinyin":"Tā lǐngdàole shīyèbǎoxiǎn.","vi":"Anh ấy đã nhận được bảo hiểm thất nghiệp."},{"type":"simple","zh":"公司每月替员工缴纳失业保险。","pinyin":"Gōngsī měiyuè tì yuángōng jiǎonà shīyèbǎoxiǎn.","vi":"Công ty hằng tháng đóng bảo hiểm thất nghiệp cho nhân viên."},{"type":"compound","zh":"只要缴满一年失业保险，被裁员后就能申请补助。","pinyin":"Zhǐyào jiǎo mǎn yì nián shīyèbǎoxiǎn, bèi cáiyuán hòu jiù néng shēnqǐng bǔzhù.","vi":"Chỉ cần đóng đủ một năm bảo hiểm thất nghiệp, sau khi bị cắt giảm là có thể xin trợ cấp."}],"related":[{"hanzi":"失业","pinyin":"shīyè","vi":"thất nghiệp"},{"hanzi":"社会保障","pinyin":"shèhuìbǎozhàng","vi":"an sinh xã hội"},{"hanzi":"医疗保险","pinyin":"yīliáobǎoxiǎn","vi":"bảo hiểm y tế"},{"hanzi":"养老保险","pinyin":"yǎnglǎobǎoxiǎn","vi":"bảo hiểm hưu trí"}],"traditional":"失業保險"},{"id":"施压","hanzi":"施压","pinyin":"shīyā","meaning_vi":"gây áp lực","explanation":"施 (thi hành/thực hiện) + 压 (áp lực/áp bức).","hsk_level":"7-9","tags":["dong-tu"],"image":"😤","examples":[{"type":"basic","zh":"别再给孩子施压了。","pinyin":"Bié zài gěi háizi shīyā le.","vi":"Đừng gây áp lực cho con nữa."},{"type":"simple","zh":"投资者纷纷向董事会施压要求更换总裁。","pinyin":"Tóuzīzhě fēnfēn xiàng dǒngshìhuì shīyā yāoqiú gēng huàn zǒngcái.","vi":"Các nhà đầu tư đồng loạt gây sức ép lên hội đồng quản trị đòi thay tổng giám đốc."},{"type":"compound","zh":"你越是对他施压，他就越不肯在谈判中让步。","pinyin":"Nǐ yuè shì duì tā shīyā, tā jiù yuè bùkěn zài tánpàn zhōng ràngbù.","vi":"Bạn càng gây áp lực, anh ta càng không chịu nhượng bộ trong đàm phán."}],"related":[{"hanzi":"压力","pinyin":"yālì","vi":"áp lực"},{"hanzi":"逼迫","pinyin":"bīpò","vi":"ép buộc"},{"hanzi":"强迫","pinyin":"qiǎngpò","vi":"cưỡng ép"},{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"}],"traditional":"施壓"},{"id":"失真","hanzi":"失真","pinyin":"shīzhēn","meaning_vi":"sai lệch so với thực tế, méo tiếng","explanation":"失 (mất đi/sai sót) + 真 (thật).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"📻","examples":[{"type":"basic","zh":"这张照片严重失真。","pinyin":"Zhè zhāng zhàopiàn yánzhòng shīzhēn.","vi":"Bức ảnh này bị sai lệch nghiêm trọng."},{"type":"simple","zh":"旧音箱放出来的声音有些失真。","pinyin":"Jiù yīnxiāng fàng chūlái de shēngyīn yǒuxiē shīzhēn.","vi":"Âm thanh phát ra từ chiếc loa cũ hơi bị méo."},{"type":"compound","zh":"消息一旦经过多次转述，就难免失真。","pinyin":"Xiāoxi yídàn jīngguò duōcì zhuǎnshù, jiù nánmiǎn shīzhēn.","vi":"Tin tức một khi qua nhiều lần thuật lại thì khó tránh khỏi sai lệch."}],"related":[{"hanzi":"逼真","pinyin":"bīzhēn","vi":"giống như thật"},{"hanzi":"变形","pinyin":"biànxíng","vi":"biến dạng"},{"hanzi":"真实","pinyin":"zhēnshí","vi":"chân thực"},{"hanzi":"歪曲","pinyin":"wāiqū","vi":"xuyên tạc"}]},{"id":"失足","hanzi":"失足","pinyin":"shīzú","meaning_vi":"trượt chân; sa ngã, lầm lỡ","explanation":"失 (mất đi/sai sót) + 足 (đầy đủ/chân).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"他不慎失足落水。","pinyin":"Tā búshèn shīzú luòshuǐ.","vi":"Anh ấy sơ ý trượt chân ngã xuống nước."},{"type":"simple","zh":"社区志愿者长期帮助失足青少年重返校园。","pinyin":"Shèqū zhìyuànzhě chángqī bāngzhù shīzú qīngshàonián chóngfǎn xiàoyuán.","vi":"Tình nguyện viên khu dân cư lâu nay giúp thanh thiếu niên lầm lỡ quay lại trường học."},{"type":"compound","zh":"一时失足并不可怕，只要肯改正就还有希望。","pinyin":"Yìshí shīzú bìngbù kěpà, zhǐyào kěn gǎizhèng jiù háiyǒu xīwàng.","vi":"Một lúc lầm lỡ không đáng sợ, chỉ cần chịu sửa đổi là vẫn còn hy vọng."}],"related":[{"hanzi":"堕落","pinyin":"duòluò","vi":"sa đọa"},{"hanzi":"失误","pinyin":"shīwù","vi":"sai sót"},{"hanzi":"一失足成千古恨","pinyin":"yì shīzú chéng qiāngǔ hèn","vi":"một lần lầm lỡ hận ngàn đời"},{"hanzi":"浪子回头","pinyin":"làngzǐhuítóu","vi":"kẻ lầm lạc quay đầu"}]},{"id":"师资","hanzi":"师资","pinyin":"shīzī","meaning_vi":"đội ngũ giáo viên","explanation":"师 (thầy giáo/sư phụ) + 资 (tài nguyên/tư bản).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"这所学校师资雄厚。","pinyin":"Zhè suǒ xuéxiào shīzī xiónghòu.","vi":"Trường này có đội ngũ giáo viên hùng hậu."},{"type":"simple","zh":"山区小学最缺的就是英语师资。","pinyin":"Shānqū xiǎoxué zuì quē de jiùshì Yīngyǔ shīzī.","vi":"Thứ mà trường tiểu học vùng núi thiếu nhất chính là giáo viên tiếng Anh."},{"type":"compound","zh":"因为师资力量不足，所以学校只好扩大每班人数。","pinyin":"Yīnwèi shīzī lìliàng bùzú, suǒyǐ xuéxiào zhǐhǎo kuòdà měi bān rénshù.","vi":"Vì đội ngũ giáo viên không đủ nên trường đành tăng sĩ số mỗi lớp."}],"related":[{"hanzi":"师资力量","pinyin":"shīzīlìliàng","vi":"đội ngũ giảng dạy"},{"hanzi":"教师","pinyin":"jiàoshī","vi":"giáo viên"},{"hanzi":"教学","pinyin":"jiàoxué","vi":"dạy học"},{"hanzi":"师生","pinyin":"shīshēng","vi":"thầy trò"}],"traditional":"師資"},{"id":"收复","hanzi":"收复","pinyin":"shōufù","meaning_vi":"thu hồi lại (lãnh thổ)","explanation":"收 (thu – lấy về) + 复 (phục – trở lại) → lấy lại lãnh thổ, đất đai đã mất. Thường đi với 失地, 领土.","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"军队收复了失地。","pinyin":"Jūnduì shōufùle shīdì.","vi":"Quân đội đã thu hồi vùng đất bị mất."},{"type":"simple","zh":"将军率领部队在三天内收复了这座城市。","pinyin":"Jiāngjūn shuàilǐng bùduì zài sān tiān nèi shōufùle zhè zuò chéngshì.","vi":"Vị tướng dẫn quân thu hồi thành phố này trong vòng ba ngày."},{"type":"compound","zh":"虽然城池被收复了，但是城里早已一片废墟。","pinyin":"Suīrán chéngchí bèi shōufù le, dànshì chéngli zǎoyǐ yípiàn fèixū.","vi":"Tuy thành trì đã được thu hồi nhưng trong thành sớm đã là một đống đổ nát."}],"related":[{"hanzi":"收回","pinyin":"shōuhuí","vi":"thu hồi"},{"hanzi":"夺回","pinyin":"duóhuí","vi":"giành lại"},{"hanzi":"失地","pinyin":"shīdì","vi":"đất bị mất"},{"hanzi":"领土","pinyin":"lǐngtǔ","vi":"lãnh thổ"}],"traditional":"收復"},{"id":"收官","hanzi":"收官","pinyin":"shōuguān","meaning_vi":"khép lại, kết thúc giai đoạn","explanation":"收 (nhận) + 官 (quan chức).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏁","examples":[{"type":"basic","zh":"本赛季完美收官。","pinyin":"Běn sàijì wánměi shōuguān.","vi":"Mùa giải này khép lại hoàn hảo."},{"type":"simple","zh":"这部热播剧昨晚正式收官。","pinyin":"Zhè bù rèbōjù zuówǎn zhèngshì shōuguān.","vi":"Bộ phim truyền hình ăn khách này đã chính thức khép lại tối qua."},{"type":"compound","zh":"只要最后一场赢球，球队就能以冠军身份收官。","pinyin":"Zhǐyào zuìhòu yì chǎng yíngqiú, qiúduì jiù néng yǐ guànjūn shēnfèn shōuguān.","vi":"Chỉ cần thắng trận cuối, đội bóng sẽ kết thúc mùa giải với tư cách nhà vô địch."}],"related":[{"hanzi":"收尾","pinyin":"shōuwěi","vi":"kết thúc"},{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"},{"hanzi":"开局","pinyin":"kāijú","vi":"khai cuộc"},{"hanzi":"圆满","pinyin":"yuánmǎn","vi":"viên mãn"}]},{"id":"收敛","hanzi":"收敛","pinyin":"shōuliǎn","meaning_vi":"thu lại, kiềm chế bớt","explanation":"收 (nhận) + 敛 (thu lại/kiềm chế).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧘","examples":[{"type":"basic","zh":"你说话收敛一点。","pinyin":"Nǐ shuōhuà shōuliǎn yìdiǎn.","vi":"Bạn ăn nói kiềm chế một chút."},{"type":"simple","zh":"看到老师进门他立刻收敛了笑容。","pinyin":"Kàndào lǎoshī jìnmén tā lìkè shōuliǎnle xiàoróng.","vi":"Thấy thầy giáo bước vào, cậu ấy lập tức thu lại nụ cười."},{"type":"compound","zh":"自从被警察警告以后，他的行为收敛了很多。","pinyin":"Zìcóng bèi jǐngchá jǐnggào yǐhòu, tā de xíngwéi shōuliǎnle hěn duō.","vi":"Từ khi bị cảnh sát cảnh cáo, hành vi của hắn đã kiềm chế đi nhiều."}],"related":[{"hanzi":"克制","pinyin":"kèzhì","vi":"kiềm chế"},{"hanzi":"收敛锋芒","pinyin":"shōuliǎnfēngmáng","vi":"che giấu tài năng"},{"hanzi":"放肆","pinyin":"fàngsì","vi":"càn rỡ"},{"hanzi":"节制","pinyin":"jiézhì","vi":"tiết chế"}],"traditional":"收斂"},{"id":"收视率","hanzi":"收视率","pinyin":"shōushìlǜ","meaning_vi":"tỷ suất người xem truyền hình (rating)","explanation":"收 (nhận) + 视 (tầm nhìn/coi trọng) + 率 (dẫn dắt/tỷ lệ).","hsk_level":"7-9","tags":["danh-tu","giai-tri","so-luong"],"image":"📺","examples":[{"type":"basic","zh":"这部剧收视率很高。","pinyin":"Zhè bù jù shōushìlǜ hěn gāo.","vi":"Bộ phim này có tỷ suất người xem rất cao."},{"type":"simple","zh":"春节联欢晚会的收视率每年都排第一。","pinyin":"Chūnjiéliánhuānwǎnhuì de shōushìlǜ měinián dōu pái dìyī.","vi":"Tỷ suất người xem của Gala Tết năm nào cũng đứng đầu."},{"type":"compound","zh":"如果收视率继续下滑，这档节目就会被停播。","pinyin":"Rúguǒ shōushìlǜ jìxù xiàhuá, zhè dàng jiémù jiù huì bèi tíng bō.","vi":"Nếu tỷ suất người xem tiếp tục giảm, chương trình này sẽ bị ngừng phát sóng."}],"related":[{"hanzi":"收视","pinyin":"shōushì","vi":"xem truyền hình"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"},{"hanzi":"点击率","pinyin":"diǎnjīlǜ","vi":"lượt nhấp"},{"hanzi":"收听率","pinyin":"shōutīnglǜ","vi":"tỷ lệ nghe đài"}],"traditional":"收視率"},{"id":"收效","hanzi":"收效","pinyin":"shōuxiào","meaning_vi":"thu được hiệu quả","explanation":"收 (nhận) + 效 (hiệu quả/hiệu suất).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📈","examples":[{"type":"basic","zh":"新政策收效明显。","pinyin":"Xīn zhèngcè shōuxiào míngxiǎn.","vi":"Chính sách mới thu được hiệu quả rõ rệt."},{"type":"simple","zh":"这种减肥方法坚持了两个月仍收效甚微。","pinyin":"Zhè zhǒng jiǎnféi fāngfǎ jiānchíle liǎng gèyuè réng shōuxiào shènwēi.","vi":"Phương pháp giảm cân này kiên trì hai tháng vẫn hiệu quả rất ít."},{"type":"compound","zh":"虽然措施刚实施一个月，但是已经开始收效。","pinyin":"Suīrán cuòshī gāng shíshī yí gèyuè, dànshì yǐjīng kāishǐ shōuxiào.","vi":"Tuy biện pháp mới thực hiện được một tháng nhưng đã bắt đầu có hiệu quả."}],"related":[{"hanzi":"成效","pinyin":"chéngxiào","vi":"hiệu quả"},{"hanzi":"效果","pinyin":"xiàoguǒ","vi":"kết quả"},{"hanzi":"收效甚微","pinyin":"shōuxiàoshènwēi","vi":"hiệu quả rất ít"},{"hanzi":"见效","pinyin":"jiànxiào","vi":"có hiệu quả"}]},{"id":"疏导","hanzi":"疏导","pinyin":"shūdǎo","meaning_vi":"khơi thông, phân luồng (giao thông/tâm lý)","explanation":"疏 (sơ suất/xa cách) + 导 (导).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚦","examples":[{"type":"basic","zh":"交警正在疏导交通。","pinyin":"Jiāojǐng zhèngzài shūdǎo jiāotōng.","vi":"Cảnh sát giao thông đang phân luồng giao thông."},{"type":"simple","zh":"心理老师耐心地疏导考试失利的学生。","pinyin":"Xīnlǐ lǎoshī nàixīn de shūdǎo kǎoshì shīlì de xuésheng.","vi":"Giáo viên tâm lý kiên nhẫn khơi gỡ cho học sinh thi trượt."},{"type":"compound","zh":"对孩子的不良情绪，与其压制，不如耐心疏导。","pinyin":"Duì háizi de bùliáng qíngxù, yǔqí yāzhì, bùrú nàixīn shūdǎo.","vi":"Với cảm xúc tiêu cực của trẻ, thay vì đè nén chi bằng kiên nhẫn khơi gỡ."}],"related":[{"hanzi":"疏通","pinyin":"shūtōng","vi":"khơi thông"},{"hanzi":"心理疏导","pinyin":"xīnlǐshūdǎo","vi":"tư vấn tâm lý"},{"hanzi":"交通","pinyin":"jiāotōng","vi":"giao thông"},{"hanzi":"引导","pinyin":"yǐndǎo","vi":"dẫn dắt"}],"traditional":"疏導"},{"id":"书画","hanzi":"书画","pinyin":"shūhuà","meaning_vi":"thư pháp và hội họa","explanation":"书 (thư – viết chữ, thư pháp) + 画 (họa – vẽ tranh) → thư pháp và hội họa nói chung. Ví dụ: 书画展 (triển lãm thư họa).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🖌️","examples":[{"type":"basic","zh":"他爱好书画。","pinyin":"Tā àihào shūhuà.","vi":"Anh ấy yêu thích thư họa."},{"type":"simple","zh":"博物馆正在展出明清两代的名家书画。","pinyin":"Bówùguǎn zhèngzài zhǎnchū Míngqīng liǎng dài de míngjiā shūhuà.","vi":"Bảo tàng đang trưng bày thư họa của các danh gia hai triều Minh Thanh."},{"type":"compound","zh":"爷爷退休以后，每天都在家里练习书画。","pinyin":"Yéye tuìxiū yǐhòu, měitiān dōu zài jiāli liànxí shūhuà.","vi":"Sau khi nghỉ hưu, ông nội ngày nào cũng luyện thư họa ở nhà."}],"related":[{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"字画","pinyin":"zìhuà","vi":"tranh chữ"},{"hanzi":"国画","pinyin":"guóhuà","vi":"quốc họa"}],"traditional":"書畫"},{"id":"舒缓","hanzi":"舒缓","pinyin":"shūhuǎn","meaning_vi":"êm dịu, làm dịu bớt (căng thẳng)","explanation":"舒 (thoải mái/duỗi) + 缓 (hòa hoãn/chậm).","hsk_level":"7-9","tags":["tinh-tu","dong-tu"],"image":"🌿","examples":[{"type":"basic","zh":"音乐节奏很舒缓。","pinyin":"Yīnyuè jiézòu hěn shūhuǎn.","vi":"Nhịp điệu âm nhạc rất êm dịu."},{"type":"simple","zh":"泡个热水澡能有效舒缓一天的疲劳。","pinyin":"Pào gè rèshuǐzǎo néng yǒuxiào shūhuǎn yì tiān de píláo.","vi":"Tắm nước nóng có thể làm dịu hiệu quả mệt mỏi cả ngày."},{"type":"compound","zh":"每当压力大的时候，她就去公园散步来舒缓心情。","pinyin":"Měidāng yālì dà de shíhou, tā jiù qù gōngyuán sànbù lái shūhuǎn xīnqíng.","vi":"Mỗi khi áp lực lớn, cô ấy lại ra công viên đi dạo để làm dịu tâm trạng."}],"related":[{"hanzi":"缓解","pinyin":"huǎnjiě","vi":"làm dịu"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"thư giãn"},{"hanzi":"舒缓压力","pinyin":"shūhuǎnyālì","vi":"giảm căng thẳng"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"}],"traditional":"舒緩"},{"id":"枢纽站","hanzi":"枢纽站","pinyin":"shūniǔzhàn","meaning_vi":"trạm trung chuyển đầu mối","explanation":"枢 (đầu mối/then chốt) + 纽 (then chốt/cúc áo) + 站 (đứng).","hsk_level":"7-9","tags":["danh-tu","giao-thong","dia-diem"],"image":"🚉","examples":[{"type":"basic","zh":"这里是交通枢纽站。","pinyin":"Zhèlǐ shì jiāotōng shūniǔzhàn.","vi":"Đây là trạm trung chuyển giao thông đầu mối."},{"type":"simple","zh":"新建的高铁枢纽站每天接待十万名旅客。","pinyin":"Xīnjiàn de gāotiě shūniǔzhàn měitiān jiēdài shí wànmíng lǚkè.","vi":"Trạm trung chuyển đường sắt cao tốc mới xây mỗi ngày đón một trăm nghìn hành khách."},{"type":"compound","zh":"因为这个枢纽站连接了三条地铁线，所以早高峰特别拥挤。","pinyin":"Yīnwèi zhè ge shūniǔzhàn liánjiēle sāntiáo dìtiě xiàn, suǒyǐ zǎogāofēng tèbié yōngjǐ.","vi":"Vì trạm đầu mối này nối ba tuyến tàu điện ngầm nên giờ cao điểm sáng rất đông."}],"related":[{"hanzi":"交通枢纽","pinyin":"jiāotōngshūniǔ","vi":"đầu mối giao thông"},{"hanzi":"中转站","pinyin":"zhōngzhuǎnzhàn","vi":"trạm trung chuyển"},{"hanzi":"车站","pinyin":"chēzhàn","vi":"nhà ga"},{"hanzi":"换乘","pinyin":"huànchéng","vi":"chuyển tuyến"}],"traditional":"樞紐站"},{"id":"抒情","hanzi":"抒情","pinyin":"shūqíng","meaning_vi":"trữ tình, bộc lộ tình cảm","explanation":"抒 (bộc lộ tình cảm) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎶","examples":[{"type":"basic","zh":"这是一首抒情诗。","pinyin":"Zhè shì yì shǒu shūqíngshī.","vi":"Đây là một bài thơ trữ tình."},{"type":"simple","zh":"作者借描写故乡的月亮来抒情。","pinyin":"Zuòzhě jiè miáoxiě gùxiāng de yuèliang lái shūqíng.","vi":"Tác giả mượn việc miêu tả vầng trăng quê hương để bộc lộ tình cảm."},{"type":"compound","zh":"他的歌既有摇滚的力量，又有抒情的温柔。","pinyin":"Tā de gē jìyǒu yáogǔn de lìliàng, yòu yǒu shūqíng de wēnróu.","vi":"Bài hát của anh ấy vừa có sức mạnh của nhạc rock vừa có sự dịu dàng trữ tình."}],"related":[{"hanzi":"抒情诗","pinyin":"shūqíngshī","vi":"thơ trữ tình"},{"hanzi":"抒发","pinyin":"shūfā","vi":"bày tỏ"},{"hanzi":"叙事","pinyin":"xùshì","vi":"tự sự"},{"hanzi":"感情","pinyin":"gǎnqíng","vi":"tình cảm"}]},{"id":"殊荣","hanzi":"殊荣","pinyin":"shūróng","meaning_vi":"vinh dự đặc biệt cao quý","explanation":"殊 (đặc biệt/khác biệt) + 荣 (vinh dự/phồn vinh).","hsk_level":"7-9","tags":["danh-tu"],"image":"🏆","examples":[{"type":"basic","zh":"这是莫大的殊荣。","pinyin":"Zhè shì mòdà de shūróng.","vi":"Đây là vinh dự vô cùng lớn lao."},{"type":"simple","zh":"这位老医生获得了全国劳动模范的殊荣。","pinyin":"Zhè wèi lǎo yīshēng huòdéle quánguó láodòng mófàn de shūróng.","vi":"Vị bác sĩ già đã nhận vinh dự đặc biệt là Chiến sĩ thi đua toàn quốc."},{"type":"compound","zh":"虽然获得了这项殊荣，但是她依然每天坚持训练。","pinyin":"Suīrán huòdéle zhè xiàng shūróng, dànshì tā yīrán měitiān jiānchí xùnliàn.","vi":"Tuy đã nhận vinh dự đặc biệt này nhưng cô ấy vẫn kiên trì luyện tập mỗi ngày."}],"related":[{"hanzi":"荣誉","pinyin":"róngyù","vi":"vinh dự"},{"hanzi":"荣获","pinyin":"rónghuò","vi":"vinh dự nhận được"},{"hanzi":"奖项","pinyin":"jiǎngxiàng","vi":"giải thưởng"},{"hanzi":"光荣","pinyin":"guāngróng","vi":"vẻ vang"}],"traditional":"殊榮"},{"id":"疏通","hanzi":"疏通","pinyin":"shūtōng","meaning_vi":"khơi thông; dàn xếp, hòa giải (quan hệ)","explanation":"疏 (sơ suất/xa cách) + 通 (thông suốt/phổ biến).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔧","examples":[{"type":"basic","zh":"下水道需要疏通。","pinyin":"Xiàshuǐdào xūyào shūtōng.","vi":"Cống thoát nước cần khơi thông."},{"type":"simple","zh":"工人们花了一整夜才疏通了堵塞的河道。","pinyin":"Gōngrénmen huāle yì zhěngyè cái shūtōngle dǔsè de hédào.","vi":"Công nhân mất cả đêm mới khơi thông được lòng sông bị tắc."},{"type":"compound","zh":"只要把双方的关系疏通好，这件事就好办了。","pinyin":"Zhǐyào bǎ shuāngfāng de guānxì shūtōng hǎo, zhè jiàn shì jiù hǎobàn le.","vi":"Chỉ cần hòa giải tốt quan hệ hai bên thì việc này sẽ dễ làm."}],"related":[{"hanzi":"疏导","pinyin":"shūdǎo","vi":"khơi thông"},{"hanzi":"畅通","pinyin":"chàngtōng","vi":"thông suốt"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"},{"hanzi":"调解","pinyin":"tiáojiě","vi":"hòa giải"}]},{"id":"书香","hanzi":"书香","pinyin":"shūxiāng","meaning_vi":"hương sách, gia đình có truyền thống hiếu học (书香门第)","explanation":"书 (sách) + 香 (thơm).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"她出身书香门第。","pinyin":"Tā chūshēn shūxiāng méndì.","vi":"Cô ấy xuất thân từ gia đình dòng dõi thư hương."},{"type":"simple","zh":"安静的图书馆里弥漫着淡淡的书香。","pinyin":"Ānjìng de túshūguǎn li mímànzhe dàndàn de shūxiāng.","vi":"Trong thư viện yên tĩnh thoang thoảng hương sách."},{"type":"compound","zh":"因为父母都是教师，所以他从小就在书香中长大。","pinyin":"Yīnwèi fùmǔ dōu shì jiàoshī, suǒyǐ tā cóngxiǎo jiù zài shūxiāng zhōng zhǎngdà.","vi":"Vì bố mẹ đều là giáo viên nên từ nhỏ anh ấy đã lớn lên trong hương sách."}],"related":[{"hanzi":"书香门第","pinyin":"shūxiāngméndì","vi":"gia đình học thức"},{"hanzi":"读书","pinyin":"dúshū","vi":"đọc sách"},{"hanzi":"书卷气","pinyin":"shūjuànqì","vi":"khí chất văn nhân"},{"hanzi":"家风","pinyin":"jiāfēng","vi":"gia phong"}],"traditional":"書香"},{"id":"输液","hanzi":"输液","pinyin":"shūyè","meaning_vi":"truyền dịch, truyền nước biển","explanation":"输 (vận chuyển/thua) + 液 (chất lỏng).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"他在医院输液。","pinyin":"Tā zài yīyuàn shūyè.","vi":"Anh ấy đang truyền dịch ở bệnh viện."},{"type":"simple","zh":"护士正在给发高烧的孩子输液。","pinyin":"Hùshi zhèngzài gěi fā gāoshāo de háizi shūyè.","vi":"Y tá đang truyền dịch cho đứa trẻ sốt cao."},{"type":"compound","zh":"医生说感冒不严重的话，就没有必要输液。","pinyin":"Yīshēng shuō gǎnmào bù yánzhòng dehuà, jiù méiyǒu bìyào shūyè.","vi":"Bác sĩ nói nếu cảm không nặng thì không cần truyền dịch."}],"related":[{"hanzi":"打针","pinyin":"dǎzhēn","vi":"tiêm"},{"hanzi":"点滴","pinyin":"diǎndī","vi":"truyền dịch"},{"hanzi":"吊瓶","pinyin":"diàopíng","vi":"chai truyền dịch"},{"hanzi":"住院","pinyin":"zhùyuàn","vi":"nằm viện"}],"traditional":"輸液"},{"id":"舒展","hanzi":"舒展","pinyin":"shūzhǎn","meaning_vi":"duỗi thẳng, thư giãn","explanation":"舒 (thoải mái/duỗi) + 展 (triển lãm/phát triển).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧘","examples":[{"type":"basic","zh":"荷叶舒展开来。","pinyin":"Héyè shūzhǎn kāi lái.","vi":"Lá sen xòe rộng ra."},{"type":"simple","zh":"听到好消息后奶奶紧皱的眉头终于舒展了。","pinyin":"Tīngdào hǎo xiāoxi hòu nǎinai jǐn zhòu de méitóu zhōngyú shūzhǎn le.","vi":"Nghe tin vui, đôi mày nhíu chặt của bà cuối cùng cũng giãn ra."},{"type":"compound","zh":"茶叶一泡进热水里，就慢慢舒展开了。","pinyin":"Cháyè yí pào jìn rèshuǐ li, jiù mànmàn shūzhǎn kāi le.","vi":"Lá trà vừa ngâm vào nước nóng là từ từ duỗi nở ra."}],"related":[{"hanzi":"伸展","pinyin":"shēnzhǎn","vi":"duỗi ra"},{"hanzi":"舒适","pinyin":"shūshì","vi":"dễ chịu"},{"hanzi":"舒畅","pinyin":"shūchàng","vi":"thoải mái"},{"hanzi":"蜷缩","pinyin":"quánsuō","vi":"co quắp"}]},{"id":"傻眼","hanzi":"傻眼","pinyin":"shǎyǎn","meaning_vi":"trố mắt kinh ngạc, đứng hình","explanation":"傻 (ngốc) + 眼 (ánh mắt/tầm nhìn).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😳","examples":[{"type":"basic","zh":"看到账单他傻眼了。","pinyin":"Kàndào zhàngdān tā shǎyǎn le.","vi":"Nhìn thấy hóa đơn, anh ấy đứng hình."},{"type":"simple","zh":"全班同学看到考试题目都傻眼了。","pinyin":"Quánbān tóngxué kàndào kǎoshì tímù dōu shǎyǎn le.","vi":"Cả lớp nhìn thấy đề thi đều chết lặng."},{"type":"compound","zh":"他一打开行李箱就傻眼了，因为里面全是别人的衣服。","pinyin":"Tā yì dǎkāi xínglixiāng jiù shǎyǎn le, yīnwèi lǐmiàn quán shì biérén de yīfu.","vi":"Anh ấy vừa mở vali đã đứng hình vì bên trong toàn là quần áo của người khác."}],"related":[{"hanzi":"发呆","pinyin":"fādāi","vi":"ngây người"},{"hanzi":"目瞪口呆","pinyin":"mùdèngkǒudāi","vi":"há hốc mồm"},{"hanzi":"惊呆","pinyin":"jīngdāi","vi":"sững sờ"},{"hanzi":"吃惊","pinyin":"chījīng","vi":"giật mình"}]},{"id":"闪光点","hanzi":"闪光点","pinyin":"shǎnguāngdiǎn","meaning_vi":"điểm sáng, ưu điểm nổi bật","explanation":"闪 (tỏa sáng/né tránh) + 光 (ánh sáng) + 点 (giờ (đồng hồ)).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"✨","examples":[{"type":"basic","zh":"每个人都有闪光点。","pinyin":"Měigèrén dōu yǒu shǎnguāngdiǎn.","vi":"Ai cũng có điểm sáng của riêng mình."},{"type":"simple","zh":"这份简历最大的闪光点是他的海外实习经历。","pinyin":"Zhè fèn jiǎnlì zuì dà de shǎnguāngdiǎn shì tā de hǎiwài shíxí jīnglì.","vi":"Điểm sáng lớn nhất của bản lý lịch này là kinh nghiệm thực tập ở nước ngoài."},{"type":"compound","zh":"这部电影虽然剧情平淡，但是配乐成了全片的闪光点。","pinyin":"Zhè bù diànyǐng suīrán jùqíng píngdàn, dànshì pèiyuè chéngle quán piàn de shǎnguāngdiǎn.","vi":"Bộ phim này tuy cốt truyện nhạt nhưng phần nhạc nền trở thành điểm sáng của cả phim."}],"related":[{"hanzi":"亮点","pinyin":"liàngdiǎn","vi":"điểm sáng"},{"hanzi":"优点","pinyin":"yōudiǎn","vi":"ưu điểm"},{"hanzi":"长处","pinyin":"chángchù","vi":"sở trường"},{"hanzi":"缺点","pinyin":"quēdiǎn","vi":"khuyết điểm"}],"traditional":"閃光點"},{"id":"赏析","hanzi":"赏析","pinyin":"shǎngxī","meaning_vi":"thưởng thức và phân tích (tác phẩm văn học)","explanation":"赏 (thưởng thức/ban thưởng) + 析 (phân tích).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"我们来赏析这首诗。","pinyin":"Wǒmen lái shǎngxī zhè shǒu shī.","vi":"Chúng ta cùng thưởng thức và phân tích bài thơ này."},{"type":"simple","zh":"语文老师带着学生逐句赏析李白的名篇。","pinyin":"Yǔwén lǎoshī dàizhe xuésheng zhú jù shǎngxī Lǐbái de míngpiān.","vi":"Giáo viên ngữ văn dẫn học sinh phân tích từng câu bài thơ nổi tiếng của Lý Bạch."},{"type":"compound","zh":"只有了解作者的生平，才能更好地赏析他的作品。","pinyin":"Zhǐyǒu liǎojiě zuòzhě de shēngpíng, cáinéng gèng hǎo de shǎngxī tā de zuòpǐn.","vi":"Chỉ khi hiểu cuộc đời tác giả mới có thể thưởng thức và phân tích tác phẩm tốt hơn."}],"related":[{"hanzi":"欣赏","pinyin":"xīnshǎng","vi":"thưởng thức"},{"hanzi":"分析","pinyin":"fēnxī","vi":"phân tích"},{"hanzi":"鉴赏","pinyin":"jiànshǎng","vi":"giám thưởng"},{"hanzi":"评析","pinyin":"píngxī","vi":"bình luận phân tích"}],"traditional":"賞析"},{"id":"史料","hanzi":"史料","pinyin":"shǐliào","meaning_vi":"sử liệu, tư liệu lịch sử","explanation":"史 (lịch sử) + 料 (料).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"这些史料很珍贵。","pinyin":"Zhèxiē shǐliào hěn zhēnguì.","vi":"Những sử liệu này rất quý giá."},{"type":"simple","zh":"他在档案馆里查阅了大量清代史料。","pinyin":"Tā zài dàng'ànguǎn li cháyuèle dàliàng Qīngdài shǐliào.","vi":"Ông ấy tra cứu lượng lớn sử liệu thời Thanh trong kho lưu trữ."},{"type":"compound","zh":"因为缺少可靠的史料，所以这段历史至今仍有争议。","pinyin":"Yīnwèi quēshǎo kěkào de shǐliào, suǒyǐ zhè duàn lìshǐ zhìjīn réng yǒuzhēngyì.","vi":"Vì thiếu sử liệu đáng tin cậy nên giai đoạn lịch sử này đến nay vẫn còn tranh cãi."}],"related":[{"hanzi":"史书","pinyin":"shǐshū","vi":"sách sử"},{"hanzi":"文献","pinyin":"wénxiàn","vi":"văn hiến tư liệu"},{"hanzi":"资料","pinyin":"zīliào","vi":"tư liệu"},{"hanzi":"档案","pinyin":"dàng'àn","vi":"hồ sơ lưu trữ"}]},{"id":"始料未及","hanzi":"始料未及","pinyin":"shǐliào-wèijí","meaning_vi":"không ngờ tới từ trước","explanation":"始 (bắt đầu) + 料 (料) + 未 (tương lai/chưa) + 及 (kịp thời/đạt tới).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😲","examples":[{"type":"basic","zh":"结果始料未及。","pinyin":"Jiéguǒ shǐliàowèijí.","vi":"Kết quả không ai ngờ tới."},{"type":"simple","zh":"这场暴雨带来的损失是所有人始料未及的。","pinyin":"Zhè chǎng bàoyǔ dàilái de sǔnshī shì suǒyǒurén shǐliàowèijí de.","vi":"Thiệt hại do trận mưa lớn này gây ra là điều không ai lường trước."},{"type":"compound","zh":"虽然做了充分准备，但是对手的变化仍让我们始料未及。","pinyin":"Suīrán zuòle chōngfèn zhǔnbèi, dànshì duìshǒu de biànhuà réng ràng wǒmen shǐliàowèijí.","vi":"Tuy đã chuẩn bị kỹ nhưng sự thay đổi của đối thủ vẫn khiến chúng tôi không ngờ tới."}],"related":[{"hanzi":"出乎意料","pinyin":"chūhūyìliào","vi":"ngoài dự đoán"},{"hanzi":"意想不到","pinyin":"yìxiǎngbúdào","vi":"không ngờ tới"},{"hanzi":"措手不及","pinyin":"cuòshǒubùjí","vi":"trở tay không kịp"},{"hanzi":"不出所料","pinyin":"bùchūsuǒliào","vi":"đúng như dự đoán"}]},{"id":"使命感","hanzi":"使命感","pinyin":"shǐmìnggǎn","meaning_vi":"tinh thần sứ mệnh","explanation":"使 (khiến cho) + 命 (mệnh lệnh/số phận) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cam-xuc"],"image":"🚩","examples":[{"type":"basic","zh":"他有强烈的使命感。","pinyin":"Tā yǒu qiángliè de shǐmìnggǎn.","vi":"Anh ấy có tinh thần sứ mệnh mạnh mẽ."},{"type":"simple","zh":"这些年轻医生带着使命感奔赴抗疫一线。","pinyin":"Zhèxiē niánqīng yīshēng dàizhe shǐmìnggǎn bēnfù kàngyì yíxiàn.","vi":"Những bác sĩ trẻ này mang tinh thần sứ mệnh lên đường ra tuyến đầu chống dịch."},{"type":"compound","zh":"正因为有使命感，她才在山区坚持教书二十年。","pinyin":"Zhèng yīnwèi yǒu shǐmìnggǎn, tā cái zài shānqū jiānchí jiāoshū èrshí nián.","vi":"Chính vì có tinh thần sứ mệnh nên cô ấy mới kiên trì dạy học ở vùng núi hai mươi năm."}],"related":[{"hanzi":"使命","pinyin":"shǐmìng","vi":"sứ mệnh"},{"hanzi":"责任感","pinyin":"zérèngǎn","vi":"tinh thần trách nhiệm"},{"hanzi":"荣誉感","pinyin":"róngyùgǎn","vi":"niềm vinh dự"},{"hanzi":"担当","pinyin":"dāndāng","vi":"gánh vác"}]},{"id":"史诗","hanzi":"史诗","pinyin":"shǐshī","meaning_vi":"sử thi, anh hùng ca","explanation":"史 (lịch sử) + 诗 (thơ).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"这是一部英雄史诗。","pinyin":"Zhè shì yí bù yīngxióng shǐshī.","vi":"Đây là một bản anh hùng ca."},{"type":"simple","zh":"这部电影用三个小时讲述了一段家族史诗。","pinyin":"Zhè bù diànyǐng yòng sān gè xiǎoshí jiǎngshùle yí duàn jiāzú shǐshī.","vi":"Bộ phim dùng ba tiếng để kể một thiên sử thi gia tộc."},{"type":"compound","zh":"格萨尔王的史诗不但篇幅极长，而且至今仍在民间传唱。","pinyin":"Gésà'ěr wáng de shǐshī búdàn piānfú jí cháng, érqiě zhìjīn réng zài mínjiān chuánchàng.","vi":"Sử thi vua Gesar không những rất dài mà đến nay vẫn được truyền xướng trong dân gian."}],"related":[{"hanzi":"史诗级","pinyin":"shǐshījí","vi":"tầm cỡ sử thi"},{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"},{"hanzi":"叙事诗","pinyin":"xùshìshī","vi":"thơ tự sự"},{"hanzi":"传说","pinyin":"chuánshuō","vi":"truyền thuyết"}],"traditional":"史詩"},{"id":"始终如一","hanzi":"始终如一","pinyin":"shǐzhōng-rúyī","meaning_vi":"trước sau như một","explanation":"始 (bắt đầu) + 终 (cuối cùng/suốt đời) + 如 (如) + 一 (số 1).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔄","examples":[{"type":"basic","zh":"他待人始终如一。","pinyin":"Tā dàirén shǐzhōngrúyī.","vi":"Anh ấy đối xử với người khác trước sau như một."},{"type":"simple","zh":"这家小店三十年来始终如一地坚持手工做面。","pinyin":"Zhè jiā xiǎodiàn sānshí niánlái shǐzhōngrúyí de jiānchí shǒugōng zuò miàn.","vi":"Quán nhỏ này ba mươi năm nay trước sau như một kiên trì làm mì thủ công."},{"type":"compound","zh":"无论贫穷还是富有，她对丈夫的爱都始终如一。","pinyin":"Wúlùn pínqióng háishì fùyǒu, tā duì zhàngfu de ài dōu shǐzhōngrúyī.","vi":"Dù nghèo hay giàu, tình yêu của cô ấy dành cho chồng vẫn trước sau như một."}],"related":[{"hanzi":"一如既往","pinyin":"yìrújìwǎng","vi":"trước sau như một"},{"hanzi":"始终","pinyin":"shǐzhōng","vi":"trước sau"},{"hanzi":"坚持不懈","pinyin":"jiānchíbúxiè","vi":"kiên trì bền bỉ"},{"hanzi":"反复无常","pinyin":"fǎnfùwúcháng","vi":"thất thường"}],"traditional":"始終如一"},{"id":"手笔","hanzi":"手笔","pinyin":"shǒubǐ","meaning_vi":"bút tích, tác phẩm tự tay viết vẽ; tầm cỡ, quy mô (cách chi tiêu, làm việc)","explanation":"手 (thủ pháp/tay nghề) + 笔 (bút/ngòi bút).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"✍️","examples":[{"type":"basic","zh":"这是大手笔投资。","pinyin":"Zhè shì dàshǒubǐ tóuzī.","vi":"Đây là khoản đầu tư quy mô lớn."},{"type":"simple","zh":"这幅山水画一看就是名家的手笔。","pinyin":"Zhè fú shānshuǐhuà yí kàn jiùshì míngjiā de shǒubǐ.","vi":"Bức tranh sơn thủy này nhìn là biết bút tích của danh gia."},{"type":"compound","zh":"这家公司一出手就是大手笔，一次收购了三家工厂。","pinyin":"Zhè jiā gōngsī yì chūshǒu jiùshì dàshǒubǐ, yí cì shōugòule sān jiā gōngchǎng.","vi":"Công ty này hễ ra tay là chơi lớn, một lần mua lại ba nhà máy."}],"related":[{"hanzi":"大手笔","pinyin":"dàshǒubǐ","vi":"chi tiêu lớn"},{"hanzi":"笔迹","pinyin":"bǐjì","vi":"nét chữ"},{"hanzi":"出手","pinyin":"chūshǒu","vi":"ra tay"},{"hanzi":"作品","pinyin":"zuòpǐn","vi":"tác phẩm"}],"traditional":"手筆"},{"id":"首创","hanzi":"首创","pinyin":"shǒuchuàng","meaning_vi":"sáng tạo đầu tiên, tiên phong","explanation":"首 (bài (lượng từ thơ/ca khúc)) + 创 (sáng tạo/sáng lập).","hsk_level":"7-9","tags":["dong-tu","danh-tu"],"image":"🚀","examples":[{"type":"basic","zh":"这是我国首创的技术。","pinyin":"Zhè shì wǒguó shǒuchuàng de jìshù.","vi":"Đây là công nghệ do nước ta sáng tạo đầu tiên."},{"type":"simple","zh":"这家医院首创了无痛胃镜检查服务。","pinyin":"Zhè jiā yīyuàn shǒuchuàngle wútòng wèijìng jiǎnchá fúwù.","vi":"Bệnh viện này tiên phong ra dịch vụ nội soi dạ dày không đau."},{"type":"compound","zh":"这种付款方式虽然是他们首创的，但是很快被同行模仿了。","pinyin":"Zhè zhǒng fùkuǎn fāngshì suīrán shì tāmen shǒuchuàng de, dànshì hěn kuài bèi tóngháng mófǎng le.","vi":"Cách thanh toán này tuy do họ sáng tạo đầu tiên nhưng nhanh chóng bị các đơn vị cùng ngành bắt chước."}],"related":[{"hanzi":"首次","pinyin":"shǒucì","vi":"lần đầu"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"sáng tạo"},{"hanzi":"开创","pinyin":"kāichuàng","vi":"khai sáng"},{"hanzi":"独创","pinyin":"dúchuàng","vi":"độc sáng"}],"traditional":"首創"},{"id":"手册","hanzi":"手册","pinyin":"shǒucè","meaning_vi":"sổ tay hướng dẫn","explanation":"手 (thủ pháp/tay nghề) + 册 (quyển/sổ).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","do-vat"],"image":"📘","examples":[{"type":"basic","zh":"请先看使用手册。","pinyin":"Qǐng xiān kàn shǐyòng shǒucè.","vi":"Vui lòng đọc sổ tay hướng dẫn trước."},{"type":"simple","zh":"每位新员工入职时都会领到一本员工手册。","pinyin":"Měi wèi xīn yuángōng rùzhí shí dōuhuì lǐngdào yì běn yuángōng shǒucè.","vi":"Mỗi nhân viên mới khi nhận việc đều được phát một cuốn sổ tay nhân viên."},{"type":"compound","zh":"如果机器出现故障，就按照手册上的步骤检查。","pinyin":"Rúguǒ jīqì chūxiàn gùzhàng, jiù ànzhào shǒucè shang de bùzhòu jiǎnchá.","vi":"Nếu máy gặp sự cố thì kiểm tra theo các bước trong sổ tay."}],"related":[{"hanzi":"说明书","pinyin":"shuōmíngshū","vi":"sách hướng dẫn"},{"hanzi":"指南","pinyin":"zhǐnán","vi":"chỉ nam"},{"hanzi":"员工手册","pinyin":"yuángōngshǒucè","vi":"sổ tay nhân viên"},{"hanzi":"使用手册","pinyin":"shǐyòngshǒucè","vi":"sổ tay sử dụng"}],"traditional":"手冊"},{"id":"首付","hanzi":"首付","pinyin":"shǒufù","meaning_vi":"tiền trả trước (khi mua nhà/trả góp)","explanation":"首 (đầu tiên) + 付 (trả).","hsk_level":"7-9","tags":["danh-tu","tien-te","nha-cua"],"image":"💵","examples":[{"type":"basic","zh":"首付要交三成。","pinyin":"Shǒufù yào jiāo sān chéng.","vi":"Tiền trả trước phải đóng ba mươi phần trăm."},{"type":"simple","zh":"他们夫妻攒了五年钱才凑够买房的首付。","pinyin":"Tāmen fūqī zǎnle wǔ nián qián cái còu gòu mǎifáng de shǒufù.","vi":"Vợ chồng họ dành dụm năm năm mới gom đủ tiền trả trước mua nhà."},{"type":"compound","zh":"只要付了首付，剩下的钱就可以分二十年还清。","pinyin":"Zhǐyào fùle shǒufù, shèngxià de qián jiù kěyǐ fēn èrshí nián huán qīng.","vi":"Chỉ cần trả tiền trước, số tiền còn lại có thể trả dần trong hai mươi năm."}],"related":[{"hanzi":"分期付款","pinyin":"fēnqīfùkuǎn","vi":"trả góp"},{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"vay tiền"},{"hanzi":"房贷","pinyin":"fángdài","vi":"vay mua nhà"},{"hanzi":"月供","pinyin":"yuègōng","vi":"trả góp hàng tháng"}]},{"id":"守法","hanzi":"守法","pinyin":"shǒufǎ","meaning_vi":"tuân thủ pháp luật","explanation":"守 (thủ – giữ) + 法 (pháp – pháp luật) → giữ đúng pháp luật, tuân thủ pháp luật. Cụm: 遵纪守法.","hsk_level":"7-9","tags":["dong-tu","phap-luat","xa-hoi"],"image":"✅","examples":[{"type":"basic","zh":"公民应当守法。","pinyin":"Gōngmín yīngdāng shǒufǎ.","vi":"Công dân phải tuân thủ pháp luật."},{"type":"simple","zh":"这家企业多次被评为守法经营的模范单位。","pinyin":"Zhè jiā qǐyè duōcì bèi píngwéi shǒufǎ jīngyíng de mófàn dānwèi.","vi":"Doanh nghiệp này nhiều lần được bình chọn là đơn vị kiểu mẫu kinh doanh đúng pháp luật."},{"type":"compound","zh":"只要大家都守法纳税，社会就会更加公平。","pinyin":"Zhǐyào dàjiā dōu shǒufǎ nàshuì, shèhuì jiù huì gèngjiā gōngpíng.","vi":"Chỉ cần mọi người đều tuân thủ pháp luật và nộp thuế, xã hội sẽ công bằng hơn."}],"related":[{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"},{"hanzi":"遵纪守法","pinyin":"zūnjìshǒufǎ","vi":"tuân thủ kỷ luật pháp luật"},{"hanzi":"法律","pinyin":"fǎlǜ","vi":"pháp luật"},{"hanzi":"公民","pinyin":"gōngmín","vi":"công dân"}]},{"id":"手工艺","hanzi":"手工艺","pinyin":"shǒugōngyì","meaning_vi":"thủ công mỹ nghệ","explanation":"手 (thủ pháp/tay nghề) + 工 (工) + 艺 (nghệ thuật).","hsk_level":"7-9","tags":["danh-tu","van-hoa","cong-viec"],"image":"🏺","examples":[{"type":"basic","zh":"她喜欢手工艺品。","pinyin":"Tā xǐhuan shǒu gōngyìpǐn.","vi":"Cô ấy thích đồ thủ công mỹ nghệ."},{"type":"simple","zh":"这个村子靠竹编手工艺吸引了大批游客。","pinyin":"Zhè ge cūnzi kào zhúbiān shǒugōngyì xīyǐnle dàpī yóukè.","vi":"Ngôi làng này nhờ nghề thủ công đan tre mà thu hút đông du khách."},{"type":"compound","zh":"传统手工艺虽然费时费力，但是每件作品都独一无二。","pinyin":"Chuántǒng shǒugōngyì suīrán fèishí fèilì, dànshì měi jiàn zuòpǐn dōu dúyìwú'èr.","vi":"Thủ công mỹ nghệ truyền thống tuy tốn thời gian công sức nhưng mỗi tác phẩm đều độc nhất vô nhị."}],"related":[{"hanzi":"手工","pinyin":"shǒugōng","vi":"thủ công"},{"hanzi":"工艺品","pinyin":"gōngyìpǐn","vi":"đồ mỹ nghệ"},{"hanzi":"手艺","pinyin":"shǒuyì","vi":"tay nghề"},{"hanzi":"民间艺术","pinyin":"mínjiānyìshù","vi":"nghệ thuật dân gian"}],"traditional":"手工藝"},{"id":"首届","hanzi":"首届","pinyin":"shǒujiè","meaning_vi":"khóa đầu tiên, lần thứ nhất tổ chức","explanation":"首 (bài (lượng từ thơ/ca khúc)) + 届 (khóa).","hsk_level":"7-9","tags":["danh-tu","the-thao","van-hoa"],"image":"1️⃣","examples":[{"type":"basic","zh":"首届论坛开幕了。","pinyin":"Shǒujiè lùntán kāimù le.","vi":"Diễn đàn lần thứ nhất đã khai mạc."},{"type":"simple","zh":"她是首届全国大学生诗歌比赛的冠军。","pinyin":"Tā shì shǒujiè quánguó dàxuéshēng shīgē bǐsài de guànjūn.","vi":"Cô ấy là quán quân cuộc thi thơ sinh viên toàn quốc lần đầu tiên."},{"type":"compound","zh":"首届电影节虽然规模不大，但是吸引了不少知名导演。","pinyin":"Shǒujiè diànyǐngjié suīrán guīmó búdà, dànshì xīyǐnle bùshǎo zhīmíng dǎoyǎn.","vi":"Liên hoan phim lần thứ nhất tuy quy mô không lớn nhưng đã thu hút không ít đạo diễn nổi tiếng."}],"related":[{"hanzi":"第一届","pinyin":"dìyījiè","vi":"khóa đầu tiên"},{"hanzi":"首次","pinyin":"shǒucì","vi":"lần đầu"},{"hanzi":"举办","pinyin":"jǔbàn","vi":"tổ chức"},{"hanzi":"本届","pinyin":"běnjiè","vi":"khóa này"}],"traditional":"首屆"},{"id":"守旧","hanzi":"守旧","pinyin":"shǒujiù","meaning_vi":"bảo thủ, giữ nếp cũ","explanation":"守 (tuân thủ/bảo vệ) + 旧 (cũ).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔒","examples":[{"type":"basic","zh":"爷爷的思想很守旧。","pinyin":"Yéye de sīxiǎng hěn shǒujiù.","vi":"Tư tưởng của ông nội rất bảo thủ."},{"type":"simple","zh":"这家老企业因为管理守旧而错过了互联网时代。","pinyin":"Zhè jiālǎo qǐyè yīnwèi guǎnlǐ shǒujiù ér cuòguòle Hùliánwǎng shídài.","vi":"Doanh nghiệp lâu đời này vì quản lý bảo thủ mà bỏ lỡ thời đại internet."},{"type":"compound","zh":"与其守旧不变，不如大胆尝试新的方法。","pinyin":"Yǔqí shǒujiù búbiàn, bùrú dàdǎn chángshì xīn de fāngfǎ.","vi":"Thay vì giữ nếp cũ không đổi, chi bằng mạnh dạn thử phương pháp mới."}],"related":[{"hanzi":"保守","pinyin":"bǎoshǒu","vi":"bảo thủ"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư lệ cũ"},{"hanzi":"创新","pinyin":"chuàngxīn","vi":"đổi mới"},{"hanzi":"顽固","pinyin":"wángù","vi":"ngoan cố"}],"traditional":"守舊"},{"id":"首脑","hanzi":"首脑","pinyin":"shǒunǎo","meaning_vi":"nguyên thủ quốc gia, lãnh đạo tối cao","explanation":"首 (bài (lượng từ thơ/ca khúc)) + 脑 (đầu óc).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"两国首脑会晤了。","pinyin":"Liǎngguó shǒunǎo huìwù le.","vi":"Nguyên thủ hai nước đã hội đàm."},{"type":"simple","zh":"二十国集团首脑峰会将在下个月举行。","pinyin":"Èrshí guó jítuán shǒunǎo fēnghuì jiāng zài xiàgèyuè jǔxíng.","vi":"Hội nghị thượng đỉnh nguyên thủ nhóm G20 sẽ được tổ chức vào tháng sau."},{"type":"compound","zh":"因为各国首脑都将出席，所以会场周边实行了交通管制。","pinyin":"Yīnwèi gèguó shǒunǎo dōu jiāng chūxí, suǒyǐ huìchǎng zhōubiān shíxíngle jiāotōng guǎnzhì.","vi":"Vì nguyên thủ các nước đều sẽ tham dự nên khu vực quanh hội trường được kiểm soát giao thông."}],"related":[{"hanzi":"元首","pinyin":"yuánshǒu","vi":"nguyên thủ"},{"hanzi":"领导人","pinyin":"lǐngdǎorén","vi":"lãnh đạo"},{"hanzi":"峰会","pinyin":"fēnghuì","vi":"hội nghị thượng đỉnh"},{"hanzi":"首脑会谈","pinyin":"shǒunǎohuìtán","vi":"hội đàm cấp cao"}],"traditional":"首腦"},{"id":"手头","hanzi":"手头","pinyin":"shǒutóu","meaning_vi":"trong tay (tiền bạc/công việc hiện có)","explanation":"手 (thủ pháp/tay nghề) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"💼","examples":[{"type":"basic","zh":"我手头有点紧。","pinyin":"Wǒ shǒutóu yǒudiǎn jǐn.","vi":"Tôi đang hơi kẹt tiền."},{"type":"simple","zh":"她放下手头的工作去机场接客户。","pinyin":"Tā fàngxià shǒutóu de gōngzuò qù jīchǎng jiē kèhù.","vi":"Cô ấy gác lại công việc đang làm để ra sân bay đón khách hàng."},{"type":"compound","zh":"等我忙完手头这个项目，就陪你去旅行。","pinyin":"Děng wǒ máng wán shǒutóu zhè ge xiàngmù, jiù péi nǐ qù lǚxíng.","vi":"Đợi anh làm xong dự án đang trong tay sẽ đi du lịch với em."}],"related":[{"hanzi":"手头紧","pinyin":"shǒutóujǐn","vi":"túng tiền"},{"hanzi":"手上","pinyin":"shǒushang","vi":"trên tay"},{"hanzi":"手头宽裕","pinyin":"shǒutóukuānyù","vi":"dư dả tiền"},{"hanzi":"现有","pinyin":"xiànyǒu","vi":"hiện có"}],"traditional":"手頭"},{"id":"首席","hanzi":"首席","pinyin":"shǒuxí","meaning_vi":"đứng đầu, trưởng (chức vụ cao nhất); ghế chủ tọa","explanation":"首 (bài (lượng từ thơ/ca khúc)) + 席 (chỗ ngồi/chủ tịch).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"他是首席执行官。","pinyin":"Tā shì shǒuxí zhíxíng guān.","vi":"Anh ấy là giám đốc điều hành."},{"type":"simple","zh":"她二十八岁就当上了乐团的首席小提琴手。","pinyin":"Tā èrshí bā suì jiù dāngshàngle yuètuán de shǒuxí xiǎotíqín shǒu.","vi":"Cô ấy hai mươi tám tuổi đã trở thành nghệ sĩ violin chính của dàn nhạc."},{"type":"compound","zh":"首席科学家一离职，整个研发项目就停了下来。","pinyin":"Shǒuxí kēxuéjiā yì lízhí, zhěnggè yánfā xiàngmù jiù tíngle xiàlái.","vi":"Nhà khoa học trưởng vừa nghỉ việc, cả dự án nghiên cứu đã ngừng lại."}],"related":[{"hanzi":"首席执行官","pinyin":"shǒuxí zhíxíng guān","vi":"giám đốc điều hành"},{"hanzi":"首席代表","pinyin":"shǒuxídàibiǎo","vi":"trưởng đại diện"},{"hanzi":"首席科学家","pinyin":"shǒuxí kēxuéjiā","vi":"nhà khoa học trưởng"},{"hanzi":"总裁","pinyin":"zǒngcái","vi":"tổng giám đốc"}]},{"id":"首映","hanzi":"首映","pinyin":"shǒuyìng","meaning_vi":"công chiếu lần đầu (phim điện ảnh)","explanation":"首 (bài (lượng từ thơ/ca khúc)) + 映 (phản ánh/chiếu rọi).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🎬","examples":[{"type":"basic","zh":"电影今晚首映。","pinyin":"Diànyǐng jīnwǎn shǒuyìng.","vi":"Bộ phim công chiếu lần đầu tối nay."},{"type":"simple","zh":"导演和主演都出席了在上海举行的首映礼。","pinyin":"Dǎoyǎn hé zhǔyǎn dōu chūxíle zài Shànghǎi jǔxíng de shǒuyìng lǐ.","vi":"Đạo diễn và diễn viên chính đều dự lễ công chiếu tại Thượng Hải."},{"type":"compound","zh":"首映的票一开售，就在五分钟内被抢光了。","pinyin":"Shǒuyìng de piào yì kāi shòu, jiù zài wǔ fēnzhōng nèi bèi qiǎng guāng le.","vi":"Vé buổi công chiếu vừa mở bán đã bị mua sạch trong năm phút."}],"related":[{"hanzi":"首映式","pinyin":"shǒuyìngshì","vi":"lễ ra mắt phim"},{"hanzi":"上映","pinyin":"shàngyìng","vi":"công chiếu"},{"hanzi":"电影","pinyin":"diànyǐng","vi":"phim điện ảnh"},{"hanzi":"票房","pinyin":"piàofáng","vi":"doanh thu phòng vé"}]},{"id":"手足","hanzi":"手足","pinyin":"shǒuzú","meaning_vi":"anh em ruột thịt; tay chân","explanation":"手 (thủ pháp/tay nghề) + 足 (đầy đủ/chân).","hsk_level":"7-9","tags":["danh-tu","gia-dinh","van-hoa"],"image":"👬","examples":[{"type":"basic","zh":"兄弟如手足。","pinyin":"Xiōngdì rú shǒuzú.","vi":"Anh em như thể tay chân."},{"type":"simple","zh":"这对双胞胎兄弟从小手足情深。","pinyin":"Zhè duì shuāngbāotāi xiōngdì cóngxiǎo shǒuzú qíng shēn.","vi":"Cặp anh em sinh đôi này từ nhỏ đã tình thâm ruột thịt."},{"type":"compound","zh":"虽然为了遗产吵过架，但是他们毕竟是手足。","pinyin":"Suīrán wèile yíchǎn chǎoguo jià, dànshì tāmen bìjìng shì shǒuzú.","vi":"Tuy từng cãi nhau vì gia tài nhưng dù sao họ cũng là anh em ruột thịt."}],"related":[{"hanzi":"兄弟","pinyin":"xiōngdì","vi":"anh em"},{"hanzi":"手足情深","pinyin":"shǒuzúqíngshēn","vi":"tình anh em sâu nặng"},{"hanzi":"骨肉","pinyin":"gǔròu","vi":"ruột thịt"},{"hanzi":"手足无措","pinyin":"shǒuzúwúcuò","vi":"luống cuống tay chân"}]},{"id":"属性","hanzi":"属性","pinyin":"shǔxìng","meaning_vi":"thuộc tính","explanation":"属 (thuộc về) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🏷️","examples":[{"type":"basic","zh":"这是文件的属性。","pinyin":"Zhè shì wénjiàn de shǔxìng.","vi":"Đây là thuộc tính của tệp."},{"type":"simple","zh":"右键点击图片就可以查看它的属性。","pinyin":"Yòu jiàn diǎnjī túpiàn jiù kěyǐ chákàn tā de shǔxìng.","vi":"Nhấp chuột phải vào ảnh là có thể xem thuộc tính của nó."},{"type":"compound","zh":"由于黄金具有金融属性，所以金价容易受市场情绪影响。","pinyin":"Yóuyú huángjīn jùyǒu jīnróng shǔxìng, suǒyǐ jīn jià róngyì shòu shìchǎng qíngxù yǐngxiǎng.","vi":"Do vàng có thuộc tính tài chính nên giá vàng dễ bị ảnh hưởng bởi tâm lý thị trường."}],"related":[{"hanzi":"特性","pinyin":"tèxìng","vi":"đặc tính"},{"hanzi":"性质","pinyin":"xìngzhì","vi":"tính chất"},{"hanzi":"特征","pinyin":"tèzhēng","vi":"đặc trưng"},{"hanzi":"属于","pinyin":"shǔyú","vi":"thuộc về"}],"traditional":"屬性"},{"id":"算法","hanzi":"算法","pinyin":"suànfǎ","meaning_vi":"thuật toán","explanation":"算 (tính toán) + 法 (phương pháp).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","khoa-hoc"],"image":"🧮","examples":[{"type":"basic","zh":"这个算法很高效。","pinyin":"Zhè ge suànfǎ hěn gāoxiào.","vi":"Thuật toán này rất hiệu quả."},{"type":"simple","zh":"短视频平台的算法总能猜到我爱看什么。","pinyin":"Duǎnshìpín píngtái de suànfǎ zǒngnéng cāi dào wǒ ài kàn shénme.","vi":"Thuật toán của nền tảng video ngắn luôn đoán được tôi thích xem gì."},{"type":"compound","zh":"如果算法存在偏见，就会给用户推送片面的信息。","pinyin":"Rúguǒ suànfǎ cúnzài piānjiàn, jiù huì gěi yònghù tuīsòng piànmiàn de xìnxī.","vi":"Nếu thuật toán tồn tại thiên kiến thì sẽ đẩy thông tin phiến diện cho người dùng."}],"related":[{"hanzi":"程序","pinyin":"chéngxù","vi":"chương trình"},{"hanzi":"编程","pinyin":"biānchéng","vi":"lập trình"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"}]},{"id":"算盘","hanzi":"算盘","pinyin":"suànpán","meaning_vi":"bàn tính gảy truyền thống","explanation":"算 (tính toán) + 盘 (tính toán/bàn cờ).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🧮","examples":[{"type":"basic","zh":"奶奶会打算盘。","pinyin":"Nǎinai huì dǎsuànpán.","vi":"Bà biết gảy bàn tính."},{"type":"simple","zh":"老会计用一把旧算盘算了一辈子账。","pinyin":"Lǎo kuàijì yòng yì bǎ jiù suànpán suànle yíbèizi zhàng.","vi":"Ông kế toán già dùng chiếc bàn tính cũ tính sổ cả đời."},{"type":"compound","zh":"虽然现在有了计算器，但是不少小学仍在教孩子打算盘。","pinyin":"Suīrán xiànzài yǒule jìsuànqì, dànshì bùshǎo xiǎoxué réng zài jiāo háizi dǎsuànpán.","vi":"Tuy bây giờ đã có máy tính cầm tay nhưng không ít trường tiểu học vẫn dạy trẻ gảy bàn tính."}],"related":[{"hanzi":"珠算","pinyin":"zhūsuàn","vi":"tính bằng bàn tính"},{"hanzi":"计算器","pinyin":"jìsuànqì","vi":"máy tính"},{"hanzi":"打算盘","pinyin":"dǎsuànpán","vi":"tính toán"},{"hanzi":"如意算盘","pinyin":"rúyìsuànpán","vi":"tính toán lợi mình"}],"traditional":"算盤"},{"id":"碎步","hanzi":"碎步","pinyin":"suìbù","meaning_vi":"bước chân nhỏ và nhanh","explanation":"碎 (vỡ vụn) + 步 (bước đi/tiến bộ).","hsk_level":"7-9","tags":["danh-tu"],"image":"👣","examples":[{"type":"basic","zh":"她迈着碎步走来。","pinyin":"Tā màizhe suìbù zǒu lái.","vi":"Cô ấy bước những bước nhỏ đi tới."},{"type":"simple","zh":"小女孩踩着碎步跑到妈妈身边。","pinyin":"Xiǎo nǚhái cǎizhe suìbù pǎo dào māma shēnbiān.","vi":"Cô bé bước chân nhỏ thoăn thoắt chạy đến bên mẹ."},{"type":"compound","zh":"因为地面结了冰，所以行人都只敢迈着碎步慢慢走。","pinyin":"Yīnwèi dìmiàn jiéle bīng, suǒyǐ xíngrén dōu zhǐ gǎn màizhe suìbù màn mànzǒu.","vi":"Vì mặt đất đóng băng nên người đi đường chỉ dám bước từng bước nhỏ chầm chậm."}],"related":[{"hanzi":"小碎步","pinyin":"xiǎosuìbù","vi":"bước nhỏ"},{"hanzi":"脚步","pinyin":"jiǎobù","vi":"bước chân"},{"hanzi":"大步","pinyin":"dàbù","vi":"bước dài"},{"hanzi":"步伐","pinyin":"bùfá","vi":"bước đi"}]},{"id":"碎片化","hanzi":"碎片化","pinyin":"suìpiànhuà","meaning_vi":"phân mảnh (thời gian/thông tin)","explanation":"碎 (vỡ vụn) + 片 (miếng) + 化 (化).","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🧩","examples":[{"type":"basic","zh":"信息越来越碎片化。","pinyin":"Xìnxī yuèláiyuè suìpiànhuà.","vi":"Thông tin ngày càng phân mảnh."},{"type":"simple","zh":"他利用通勤的碎片化时间背英语单词。","pinyin":"Tā lìyòng tōngqín de suìpiànhuà shíjiān bèi Yīngyǔ dāncí.","vi":"Anh ấy tận dụng thời gian vụn vặt khi đi làm để học thuộc từ tiếng Anh."},{"type":"compound","zh":"碎片化阅读虽然方便，但是很难形成系统的知识。","pinyin":"Suìpiànhuà yuèdú suīrán fāngbiàn, dànshì hěn nán xíngchéng xìtǒng de zhīshi.","vi":"Đọc phân mảnh tuy tiện lợi nhưng rất khó hình thành kiến thức có hệ thống."}],"related":[{"hanzi":"碎片","pinyin":"suìpiàn","vi":"mảnh vụn"},{"hanzi":"零散","pinyin":"língsǎn","vi":"rời rạc"},{"hanzi":"碎片时间","pinyin":"suìpiànshíjiān","vi":"thời gian vụn vặt"},{"hanzi":"系统化","pinyin":"xìtǒnghuà","vi":"hệ thống hóa"}]},{"id":"岁数","hanzi":"岁数","pinyin":"suìshu","meaning_vi":"tuổi tác","explanation":"岁 (năm tháng/tuổi) + 数 (đếm).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🎂","examples":[{"type":"basic","zh":"您多大岁数了？","pinyin":"Nín duōdà suìshu le?","vi":"Ông bao nhiêu tuổi rồi ạ?"},{"type":"simple","zh":"上了岁数的人更要注意保暖。","pinyin":"Shàngle suìshu de rén gèng yào zhùyì bǎonuǎn.","vi":"Người có tuổi càng phải chú ý giữ ấm."},{"type":"compound","zh":"爷爷虽然岁数大了，但是每天还坚持游泳。","pinyin":"Yéye suīrán suìshu dà le, dànshì měitiān hái jiānchí yóuyǒng.","vi":"Ông nội tuy đã lớn tuổi nhưng hằng ngày vẫn kiên trì bơi."}],"related":[{"hanzi":"年纪","pinyin":"niánjì","vi":"tuổi"},{"hanzi":"年龄","pinyin":"niánlíng","vi":"tuổi tác"},{"hanzi":"上岁数","pinyin":"shàngsuìshu","vi":"có tuổi"},{"hanzi":"周岁","pinyin":"zhōusuì","vi":"tuổi tròn"}],"traditional":"歲數"},{"id":"随和","hanzi":"随和","pinyin":"suíhé","meaning_vi":"hòa đồng, dễ tính","explanation":"随 (tùy ý/đi theo) + 和 (và).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"新领导很随和。","pinyin":"Xīn lǐngdǎo hěn suíhé.","vi":"Lãnh đạo mới rất dễ tính."},{"type":"simple","zh":"这位大明星私下里是个非常随和的人。","pinyin":"Zhè wèi dà míngxīng sīxià li shì gè fēicháng suíhé de rén.","vi":"Ngôi sao lớn này ngoài đời là người rất hòa đồng."},{"type":"compound","zh":"因为他为人随和，所以同事们都愿意跟他合作。","pinyin":"Yīnwèi tā wéirén suíhé, suǒyǐ tóngshìmen dōu yuànyì gēn tā hézuò.","vi":"Vì anh ấy tính tình dễ chịu nên đồng nghiệp đều muốn hợp tác với anh."}],"related":[{"hanzi":"平易近人","pinyin":"píngyìjìnrén","vi":"dễ gần"},{"hanzi":"好相处","pinyin":"hǎoxiāngchǔ","vi":"dễ chung sống"},{"hanzi":"随便","pinyin":"suíbiàn","vi":"tùy tiện"},{"hanzi":"固执","pinyin":"gùzhí","vi":"cố chấp"}],"traditional":"隨和"},{"id":"随机","hanzi":"随机","pinyin":"suíjī","meaning_vi":"ngẫu nhiên","explanation":"随 (tùy ý/đi theo) + 机 (cơ hội/máy móc).","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🎲","examples":[{"type":"basic","zh":"系统随机抽取号码。","pinyin":"Xìtǒng suíjī chōuqǔ hàomǎ.","vi":"Hệ thống rút số ngẫu nhiên."},{"type":"simple","zh":"研究人员把志愿者随机分成了两组。","pinyin":"Yánjiū rényuán bǎ zhìyuànzhě suíjī fēn chéngle liǎng zǔ.","vi":"Các nhà nghiên cứu chia ngẫu nhiên tình nguyện viên thành hai nhóm."},{"type":"compound","zh":"只要打开随机播放，每次听到的歌就都不一样。","pinyin":"Zhǐyào dǎkāi suíjī bōfàng, měi cì tīngdào de gē jiù dōu bù yíyàng.","vi":"Chỉ cần bật phát ngẫu nhiên, mỗi lần nghe bài hát đều khác nhau."}],"related":[{"hanzi":"随意","pinyin":"suíyì","vi":"tùy ý"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"},{"hanzi":"随机应变","pinyin":"suíjīyìngbiàn","vi":"tùy cơ ứng biến"},{"hanzi":"抽样","pinyin":"chōuyàng","vi":"lấy mẫu"}],"traditional":"隨機"},{"id":"酸雨","hanzi":"酸雨","pinyin":"suānyǔ","meaning_vi":"mưa axit","explanation":"酸 (toan – chua, axit) + 雨 (vũ – mưa) → mưa có tính axit do khí thải ô nhiễm (SO2, NOx), gây hại cây cối và công trình.","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","thien-nhien"],"image":"🌧️","examples":[{"type":"basic","zh":"酸雨腐蚀了石像。","pinyin":"Suānyǔ fǔshíle shíxiàng.","vi":"Mưa axit đã ăn mòn tượng đá."},{"type":"simple","zh":"工厂排放的废气是形成酸雨的主要原因。","pinyin":"Gōngchǎng páifàng de fèiqì shì xíngchéng suānyǔ de zhǔyào yuányīn.","vi":"Khí thải nhà máy là nguyên nhân chính hình thành mưa axit."},{"type":"compound","zh":"如果长期遭受酸雨，森林里的树木就会大片枯死。","pinyin":"Rúguǒ chángqī zāoshòu suānyǔ, sēnlín li de shùmù jiù huì dàpiàn kūsǐ.","vi":"Nếu bị mưa axit lâu dài, cây trong rừng sẽ chết khô hàng loạt."}],"related":[{"hanzi":"污染","pinyin":"wūrǎn","vi":"ô nhiễm"},{"hanzi":"大气污染","pinyin":"dàqìwūrǎn","vi":"ô nhiễm không khí"},{"hanzi":"雾霾","pinyin":"wùmái","vi":"sương mù ô nhiễm"},{"hanzi":"环境","pinyin":"huánjìng","vi":"môi trường"}]},{"id":"缩减","hanzi":"缩减","pinyin":"suōjiǎn","meaning_vi":"cắt giảm, thu hẹp","explanation":"缩 (thu nhỏ) + 减 (减).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"✂️","examples":[{"type":"basic","zh":"公司缩减了开支。","pinyin":"Gōngsī suōjiǎnle kāizhī.","vi":"Công ty đã cắt giảm chi tiêu."},{"type":"simple","zh":"受经济影响航空公司缩减了国际航班。","pinyin":"Shòu jīngjì yǐngxiǎng hángkōng gōngsī suōjiǎnle Guójì hángbān.","vi":"Chịu ảnh hưởng kinh tế, hãng hàng không đã cắt giảm chuyến bay quốc tế."},{"type":"compound","zh":"即使经费被缩减，我们也要保证实验按时完成。","pinyin":"Jíshǐ jīngfèi bèi suōjiǎn, wǒmen yě yào bǎozhèng shíyàn ànshí wánchéng.","vi":"Dù kinh phí bị cắt giảm, chúng tôi cũng phải đảm bảo thí nghiệm hoàn thành đúng hạn."}],"related":[{"hanzi":"削减","pinyin":"xuējiǎn","vi":"cắt giảm"},{"hanzi":"减少","pinyin":"jiǎnshǎo","vi":"giảm bớt"},{"hanzi":"压缩","pinyin":"yāsuō","vi":"nén, thu hẹp"},{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"}],"traditional":"縮減"},{"id":"缩小","hanzi":"缩小","pinyin":"suōxiǎo","meaning_vi":"thu nhỏ","explanation":"缩 (thu nhỏ) + 小 (nhỏ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔍","examples":[{"type":"basic","zh":"请把图片缩小。","pinyin":"Qǐng bǎ túpiàn suōxiǎo.","vi":"Vui lòng thu nhỏ hình ảnh."},{"type":"simple","zh":"这些年城乡之间的收入差距正在缩小。","pinyin":"Zhèxiē nián chéngxiāng zhījiān de shōurù chājù zhèngzài suōxiǎo.","vi":"Những năm gần đây chênh lệch thu nhập giữa thành thị và nông thôn đang thu hẹp."},{"type":"compound","zh":"警方一缩小搜索范围，就很快找到了嫌疑人。","pinyin":"Jǐngfāng yì suōxiǎo sōusuǒ fànwéi, jiù hěn kuài zhǎodàole xiányírén.","vi":"Cảnh sát vừa thu hẹp phạm vi tìm kiếm đã nhanh chóng tìm ra nghi phạm."}],"related":[{"hanzi":"放大","pinyin":"fàngdà","vi":"phóng to"},{"hanzi":"缩短","pinyin":"suōduǎn","vi":"rút ngắn"},{"hanzi":"扩大","pinyin":"kuòdà","vi":"mở rộng"},{"hanzi":"缩水","pinyin":"suōshuǐ","vi":"co lại"}],"traditional":"縮小"},{"id":"所长","hanzi":"所长","pinyin":"suǒcháng","meaning_vi":"sở trường, điểm mạnh","explanation":"所 (nơi chốn/sở hữu) + 长 (dài/trưởng thành).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"唱歌是她的所长。","pinyin":"Chànggē shì tā de suǒcháng.","vi":"Ca hát là sở trường của cô ấy."},{"type":"simple","zh":"新经理善于让每个员工发挥自己的所长。","pinyin":"Xīn jīnglǐ shànyú ràng měi gè yuángōng fāhuī zìjǐ de suǒcháng.","vi":"Giám đốc mới giỏi để mỗi nhân viên phát huy sở trường của mình."},{"type":"compound","zh":"与其勉强做不擅长的事，不如专心发挥所长。","pinyin":"Yǔqí miǎnqiǎng zuò bú shàncháng de shì, bùrú zhuānxīn fāhuī suǒcháng.","vi":"Thay vì gượng làm việc không giỏi, chi bằng chuyên tâm phát huy sở trường."}],"related":[{"hanzi":"长处","pinyin":"chángchù","vi":"sở trường"},{"hanzi":"特长","pinyin":"tècháng","vi":"sở trường đặc biệt"},{"hanzi":"专长","pinyin":"zhuāncháng","vi":"chuyên môn"},{"hanzi":"短处","pinyin":"duǎnchù","vi":"sở đoản"}],"traditional":"所長"},{"id":"所得","hanzi":"所得","pinyin":"suǒdé","meaning_vi":"thu nhập, điều thu hoạch được","explanation":"所 (nơi chốn/sở hữu) + 得 (phải).","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"💰","examples":[{"type":"basic","zh":"这是他的劳动所得。","pinyin":"Zhè shì tā de láodòng suǒdé.","vi":"Đây là thu nhập từ lao động của anh ấy."},{"type":"simple","zh":"她把比赛所得的奖金全部捐给了孤儿院。","pinyin":"Tā bǎ bǐsài suǒdé de jiǎngjīn quánbù juāngěile gū'éryuàn.","vi":"Cô ấy quyên toàn bộ tiền thưởng thi đấu cho trại trẻ mồ côi."},{"type":"compound","zh":"只要个人所得超过起征点，就必须依法缴纳个税。","pinyin":"Zhǐyào gèrén suǒdé chāoguò qǐzhēngdiǎn, jiù bìxū yīfǎ jiǎonà gèshuì.","vi":"Chỉ cần thu nhập cá nhân vượt mức khởi điểm chịu thuế thì phải nộp thuế thu nhập theo luật."}],"related":[{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"},{"hanzi":"所得税","pinyin":"suǒdéshuì","vi":"thuế thu nhập"},{"hanzi":"收获","pinyin":"shōuhuò","vi":"thu hoạch"},{"hanzi":"报酬","pinyin":"bàochou","vi":"thù lao"}]},{"id":"锁定","hanzi":"锁定","pinyin":"suǒdìng","meaning_vi":"khóa chặt, xác định chính xác mục tiêu","explanation":"锁 (khóa lại) + 定 (定).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🎯","examples":[{"type":"basic","zh":"屏幕自动锁定了。","pinyin":"Píngmù zìdòng suǒdìng le.","vi":"Màn hình đã tự động khóa."},{"type":"simple","zh":"警方通过监控录像锁定了偷车的嫌疑人。","pinyin":"Jǐngfāng tōngguò jiānkòng lùxiàng suǒdìngle tōu chē de xiányírén.","vi":"Cảnh sát thông qua camera giám sát đã xác định được nghi phạm trộm xe."},{"type":"compound","zh":"如果密码连续输错五次，账户就会被锁定。","pinyin":"Rúguǒ mìmǎ liánxù shū cuò wǔ cì, zhànghù jiù huì bèi suǒdìng.","vi":"Nếu nhập sai mật khẩu năm lần liên tiếp, tài khoản sẽ bị khóa."}],"related":[{"hanzi":"锁住","pinyin":"suǒzhù","vi":"khóa lại"},{"hanzi":"确定","pinyin":"quèdìng","vi":"xác định"},{"hanzi":"目标","pinyin":"mùbiāo","vi":"mục tiêu"},{"hanzi":"解锁","pinyin":"jiěsuǒ","vi":"mở khóa"}],"traditional":"鎖定"},{"id":"索赔","hanzi":"索赔","pinyin":"suǒpéi","meaning_vi":"đòi bồi thường","explanation":"索 (đòi) + 赔 (đền bù).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"💰","examples":[{"type":"basic","zh":"乘客向航空公司索赔。","pinyin":"Chéngkè xiàng hángkōng gōngsī suǒpéi.","vi":"Hành khách đòi hãng hàng không bồi thường."},{"type":"simple","zh":"那位车主因质量问题向厂家索赔十万元。","pinyin":"Nà wèi chē zhǔyīn zhìliàng wèntí xiàng chǎngjiā suǒpéi shíwàn yuán.","vi":"Chủ xe đó đòi nhà sản xuất bồi thường một trăm nghìn tệ vì vấn đề chất lượng."},{"type":"compound","zh":"如果快递在运输中损坏，你就可以申请索赔。","pinyin":"Rúguǒ kuàidì zài yùnshū zhōng sǔnhuài, nǐ jiù kěyǐ shēnqǐng suǒpéi.","vi":"Nếu bưu kiện bị hư hỏng trong quá trình vận chuyển, bạn có thể yêu cầu bồi thường."}],"related":[{"hanzi":"赔偿","pinyin":"péicháng","vi":"bồi thường"},{"hanzi":"理赔","pinyin":"lǐpéi","vi":"giải quyết bồi thường"},{"hanzi":"赔款","pinyin":"péikuǎn","vi":"tiền bồi thường"},{"hanzi":"维权","pinyin":"wéiquán","vi":"bảo vệ quyền lợi"}],"traditional":"索賠"},{"id":"索取","hanzi":"索取","pinyin":"suǒqǔ","meaning_vi":"đòi hỏi, yêu cầu cung cấp","explanation":"索 (tìm tòi/dây thừng) + 取 (lấy).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤲","examples":[{"type":"basic","zh":"可以免费索取样品。","pinyin":"Kěyǐ miǎnfèi suǒqǔ yàngpǐn.","vi":"Có thể yêu cầu mẫu thử miễn phí."},{"type":"simple","zh":"有些手机应用过度索取用户的个人信息。","pinyin":"Yǒuxiē shǒujī yìngyòng guòdù suǒqǔ yònghù de gèrén xìnxī.","vi":"Một số ứng dụng di động đòi hỏi quá mức thông tin cá nhân của người dùng."},{"type":"compound","zh":"真正的爱不是一味地索取，而是懂得付出。","pinyin":"Zhēnzhèng de ài bú shì yíwèi de suǒqǔ, érshì dǒngde fùchū.","vi":"Tình yêu thật sự không phải là chỉ biết đòi hỏi mà là biết cho đi."}],"related":[{"hanzi":"获取","pinyin":"huòqǔ","vi":"thu được"},{"hanzi":"要求","pinyin":"yāoqiú","vi":"yêu cầu"},{"hanzi":"奉献","pinyin":"fèngxiàn","vi":"cống hiến"},{"hanzi":"讨要","pinyin":"tǎoyào","vi":"đòi"}]},{"id":"所属","hanzi":"所属","pinyin":"suǒshǔ","meaning_vi":"trực thuộc, thuộc quyền quản lý của","explanation":"所 (nơi chốn/sở hữu) + 属 (thuộc về).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"🏢","examples":[{"type":"basic","zh":"请填写所属部门。","pinyin":"Qǐng tiánxiě suǒshǔ bùmén.","vi":"Vui lòng điền bộ phận trực thuộc."},{"type":"simple","zh":"该医院及其所属的三家诊所今天全部停诊。","pinyin":"Gāi yīyuàn jíqí suǒshǔ de sān jiā zhěnsuǒ jīntiān quánbù tíng zhěn.","vi":"Bệnh viện này cùng ba phòng khám trực thuộc hôm nay đều tạm ngừng khám."},{"type":"compound","zh":"一旦球员违反纪律，所属俱乐部就要承担连带责任。","pinyin":"Yídàn qiúyuán wéifǎn jìlǜ, suǒshǔ jùlèbù jiùyào chéngdān liándài zérèn.","vi":"Một khi cầu thủ vi phạm kỷ luật, câu lạc bộ chủ quản phải chịu trách nhiệm liên đới."}],"related":[{"hanzi":"附属","pinyin":"fùshǔ","vi":"phụ thuộc"},{"hanzi":"隶属","pinyin":"lìshǔ","vi":"trực thuộc"},{"hanzi":"下属","pinyin":"xiàshǔ","vi":"cấp dưới"},{"hanzi":"归属","pinyin":"guīshǔ","vi":"thuộc về"}],"traditional":"所屬"},{"id":"赛程","hanzi":"赛程","pinyin":"sàichéng","meaning_vi":"lịch thi đấu","explanation":"赛 (thi đấu) + 程 (quá trình/hành trình).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"📅","examples":[{"type":"basic","zh":"赛程已经公布了。","pinyin":"Sàichéng yǐjīng gōngbù le.","vi":"Lịch thi đấu đã được công bố."},{"type":"simple","zh":"世界杯的赛程安排得非常紧凑。","pinyin":"Shìjièbēi de sàichéng ānpái de fēicháng jǐncòu.","vi":"Lịch thi đấu World Cup được sắp xếp rất dày."},{"type":"compound","zh":"因为暴雨持续不停，所以组委会只好调整赛程。","pinyin":"Yīnwèi bàoyǔ chíxù bùtíng, suǒyǐ zǔwěihuì zhǐhǎo tiáozhěng sàichéng.","vi":"Vì mưa lớn kéo dài không ngớt nên ban tổ chức đành điều chỉnh lịch thi đấu."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"trận đấu"},{"hanzi":"日程","pinyin":"rìchéng","vi":"lịch trình"},{"hanzi":"赛季","pinyin":"sàijì","vi":"mùa giải"},{"hanzi":"赛事","pinyin":"sàishì","vi":"giải đấu"}],"traditional":"賽程"},{"id":"赛场","hanzi":"赛场","pinyin":"sàichǎng","meaning_vi":"sân thi đấu","explanation":"赛 (thi đấu) + 场 (địa điểm/trận đấu).","hsk_level":"7-9","tags":["danh-tu","the-thao","dia-diem"],"image":"🏟️","examples":[{"type":"basic","zh":"他重返赛场了。","pinyin":"Tā chóngfǎn sàichǎng le.","vi":"Anh ấy đã trở lại sân thi đấu."},{"type":"simple","zh":"比赛结束后观众们纷纷涌进赛场庆祝。","pinyin":"Bǐsài jiéshù hòu guānzhòngmen fēnfēn yǒngjìn sàichǎng qìngzhù.","vi":"Sau trận đấu khán giả ùa vào sân ăn mừng."},{"type":"compound","zh":"赛场上他们是对手，赛场下却是好朋友。","pinyin":"Sàichǎng shang tāmen shì duìshǒu, sàichǎng xià quèshì hǎopéngyou.","vi":"Trên sân họ là đối thủ, ngoài sân lại là bạn tốt."}],"related":[{"hanzi":"球场","pinyin":"qiúchǎng","vi":"sân bóng"},{"hanzi":"比赛","pinyin":"bǐsài","vi":"trận đấu"},{"hanzi":"运动员","pinyin":"yùndòngyuán","vi":"vận động viên"},{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"}],"traditional":"賽場"},{"id":"赛季","hanzi":"赛季","pinyin":"sàijì","meaning_vi":"mùa giải (thể thao)","explanation":"赛 (thi đấu) + 季 (季).","hsk_level":"7-9","tags":["danh-tu","the-thao","thoi-gian"],"image":"🏆","examples":[{"type":"basic","zh":"新赛季开始了。","pinyin":"Xīn sàijì kāishǐ le.","vi":"Mùa giải mới đã bắt đầu."},{"type":"simple","zh":"他在上个赛季一共打进了二十五个球。","pinyin":"Tā zài shànggè sàijì yígòng dǎjìnle èr shíwǔ gè qiú.","vi":"Mùa giải trước anh ấy ghi tổng cộng hai mươi lăm bàn."},{"type":"compound","zh":"由于膝盖受了重伤，所以他将缺席整个赛季。","pinyin":"Yóuyú xīgài shòule zhòngshāng, suǒyǐ tā jiāng quēxí zhěnggè sàijì.","vi":"Do đầu gối bị chấn thương nặng nên anh ấy sẽ vắng mặt cả mùa giải."}],"related":[{"hanzi":"赛程","pinyin":"sàichéng","vi":"lịch thi đấu"},{"hanzi":"联赛","pinyin":"liánsài","vi":"giải vô địch"},{"hanzi":"季后赛","pinyin":"jìhòusài","vi":"vòng playoff"},{"hanzi":"休赛期","pinyin":"xiūsàiqī","vi":"kỳ nghỉ giải"}],"traditional":"賽季"},{"id":"赛事","hanzi":"赛事","pinyin":"sàishì","meaning_vi":"giải đấu thể thao","explanation":"赛 (thi đấu) + 事 (sự nghiệp/sự kiện).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"⚽","examples":[{"type":"basic","zh":"这项赛事很受欢迎。","pinyin":"Zhè xiàng sàishì hěn shòuhuānyíng.","vi":"Giải đấu này rất được ưa chuộng."},{"type":"simple","zh":"这座城市今年将承办三项国际体育赛事。","pinyin":"Zhè zuò chéngshì jīnnián jiāng chéngbàn sānxiàng Guójì tǐyù sàishì.","vi":"Thành phố này năm nay sẽ đăng cai ba giải đấu thể thao quốc tế."},{"type":"compound","zh":"大型赛事不但能带动旅游，而且能提升城市知名度。","pinyin":"Dàxíng sàishì búdàn néng dàidòng lǚyóu, érqiě néng tíshēng chéngshì zhīmíngdù.","vi":"Các giải đấu lớn không những thúc đẩy du lịch mà còn nâng cao danh tiếng thành phố."}],"related":[{"hanzi":"比赛","pinyin":"bǐsài","vi":"trận đấu"},{"hanzi":"锦标赛","pinyin":"jǐnbiāosài","vi":"giải vô địch"},{"hanzi":"体育","pinyin":"tǐyù","vi":"thể thao"},{"hanzi":"赛场","pinyin":"sàichǎng","vi":"sân đấu"}],"traditional":"賽事"},{"id":"散落","hanzi":"散落","pinyin":"sànluò","meaning_vi":"rơi vãi, nằm rải rác","explanation":"散 (phân tán/tản văn) + 落 (rơi rụng/thực hiện).","hsk_level":"7-9","tags":["dong-tu"],"image":"🍂","examples":[{"type":"basic","zh":"文件散落一地。","pinyin":"Wénjiàn sànluò yí dì.","vi":"Giấy tờ rơi vãi khắp sàn."},{"type":"simple","zh":"小山村的几十户人家散落在半山腰上。","pinyin":"Xiǎo shāncūn de jǐ shí hù rénjiā sànluò zài bànshānyāo shang.","vi":"Mấy chục hộ dân của làng núi nhỏ nằm rải rác lưng chừng núi."},{"type":"compound","zh":"春风一吹，满树的樱花花瓣就散落在湖面上。","pinyin":"Chūnfēng yì chuī, mǎn shù de yīnghuā huābàn jiù sànluò zài húmiàn shang.","vi":"Gió xuân vừa thổi, cánh hoa anh đào đầy cây đã rơi rải rác trên mặt hồ."}],"related":[{"hanzi":"散布","pinyin":"sànbù","vi":"rải rác"},{"hanzi":"零散","pinyin":"língsǎn","vi":"lẻ tẻ"},{"hanzi":"分散","pinyin":"fēnsàn","vi":"phân tán"},{"hanzi":"集中","pinyin":"jízhōng","vi":"tập trung"}]},{"id":"丧失信心","hanzi":"丧失信心","pinyin":"sàngshīxìnxīn","meaning_vi":"mất hết niềm tin","explanation":"丧 (mất đi/tang lễ) + 失 (mất đi/sai sót) + 信 (niềm tin/uy tín) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"别对自己丧失信心。","pinyin":"Bié duì zìjǐ sàngshīxìnxīn.","vi":"Đừng mất niềm tin vào bản thân."},{"type":"simple","zh":"连续三次创业失败让他彻底丧失信心。","pinyin":"Liánxù sāncì chuàngyè shībài ràng tā chèdǐ sàngshīxìnxīn.","vi":"Ba lần khởi nghiệp thất bại liên tiếp khiến anh ấy hoàn toàn mất hết niềm tin."},{"type":"compound","zh":"即使暂时落后，我们也不能丧失信心。","pinyin":"Jíshǐ zànshí luòhòu, wǒmen yě bù néng sàngshīxìnxīn.","vi":"Dù tạm thời bị dẫn trước, chúng ta cũng không được mất niềm tin."}],"related":[{"hanzi":"丧失","pinyin":"sàngshī","vi":"đánh mất"},{"hanzi":"失去信心","pinyin":"shīqùxìnxīn","vi":"mất niềm tin"},{"hanzi":"灰心","pinyin":"huīxīn","vi":"nản lòng"},{"hanzi":"充满信心","pinyin":"chōngmǎnxìnxīn","vi":"đầy tự tin"}],"traditional":"喪失信心"},{"id":"色泽","hanzi":"色泽","pinyin":"sèzé","meaning_vi":"màu sắc và độ bóng","explanation":"色 (màu sắc/thần sắc) + 泽 (đầm lầy/ân huệ).","hsk_level":"7-9","tags":["danh-tu","an-uong"],"image":"✨","examples":[{"type":"basic","zh":"这块玉色泽温润。","pinyin":"Zhè kuài yù sèzé wēnrùn.","vi":"Miếng ngọc này màu sắc ấm áp óng ánh."},{"type":"simple","zh":"烤好的面包色泽金黄十分诱人。","pinyin":"Kǎo hǎo de miànbāo sèzé jīnhuáng shífēn yòurén.","vi":"Bánh mì nướng xong có màu vàng óng rất hấp dẫn."},{"type":"compound","zh":"如果水果的色泽过于鲜艳，就可能用了添加剂。","pinyin":"Rúguǒ shuǐguǒ de sèzé guòyú xiānyàn, jiù kěnéng yòngle tiānjiājì.","vi":"Nếu màu sắc trái cây quá rực rỡ thì có thể đã dùng chất phụ gia."}],"related":[{"hanzi":"色彩","pinyin":"sècǎi","vi":"sắc màu"},{"hanzi":"光泽","pinyin":"guāngzé","vi":"độ bóng"},{"hanzi":"颜色","pinyin":"yánsè","vi":"màu sắc"},{"hanzi":"鲜艳","pinyin":"xiānyàn","vi":"tươi sáng"}],"traditional":"色澤"},{"id":"四处","hanzi":"四处","pinyin":"sìchù","meaning_vi":"khắp nơi","explanation":"四 (số 4) + 处 (xử lý/chung sống).","hsk_level":"7-9","tags":["pho-tu"],"image":"🗺️","examples":[{"type":"basic","zh":"他四处找工作。","pinyin":"Tā sìchù zhǎogōngzuò.","vi":"Anh ấy đi khắp nơi tìm việc."},{"type":"simple","zh":"小狗走丢后主人四处张贴寻狗启事。","pinyin":"Xiǎogǒu zǒudiū hòu zhǔrén sìchù zhāngtiē xún gǒu qǐshì.","vi":"Sau khi chó con đi lạc, chủ dán thông báo tìm chó khắp nơi."},{"type":"compound","zh":"他一到新城市，就四处打听便宜的房子。","pinyin":"Tā yí dào xīn chéngshì, jiù sìchù dǎting piányi de fángzi.","vi":"Anh ấy vừa đến thành phố mới đã đi khắp nơi dò hỏi nhà giá rẻ."}],"related":[{"hanzi":"到处","pinyin":"dàochù","vi":"khắp nơi"},{"hanzi":"处处","pinyin":"chùchù","vi":"mọi nơi"},{"hanzi":"四面八方","pinyin":"sìmiànbāfāng","vi":"bốn phương tám hướng"},{"hanzi":"各地","pinyin":"gèdì","vi":"các nơi"}],"traditional":"四處"},{"id":"四大发明","hanzi":"四大发明","pinyin":"sìdàfāmíng","meaning_vi":"Tứ đại phát minh (la bàn, thuốc súng, giấy, in ấn)","explanation":"四大 (tứ đại – bốn lớn) + 发明 (phát minh) → bốn phát minh lớn của TQ cổ đại: giấy, la bàn, thuốc súng và kỹ thuật in.","hsk_level":"7-9","tags":["danh-tu","van-hoa","khoa-hoc"],"image":"🧭","examples":[{"type":"basic","zh":"印刷术是四大发明之一。","pinyin":"Yìnshuāshù shì sìdàfāmíng zhīyī.","vi":"Kỹ thuật in là một trong Tứ đại phát minh."},{"type":"simple","zh":"历史课上老师详细介绍了中国古代的四大发明。","pinyin":"Lìshǐ kè shang lǎoshī xiángxì jièshàole Zhōngguó gǔdài de sìdàfāmíng.","vi":"Trong giờ lịch sử, thầy giáo giới thiệu chi tiết Tứ đại phát minh của Trung Quốc cổ đại."},{"type":"compound","zh":"四大发明不但影响了中国，而且推动了世界文明的发展。","pinyin":"Sìdàfāmíng búdàn yǐngxiǎngle Zhōngguó, érqiě tuīdòngle shìjiè wénmíng de fāzhǎn.","vi":"Tứ đại phát minh không những ảnh hưởng đến Trung Quốc mà còn thúc đẩy sự phát triển văn minh thế giới."}],"related":[{"hanzi":"指南针","pinyin":"zhǐnánzhēn","vi":"la bàn"},{"hanzi":"火药","pinyin":"huǒyào","vi":"thuốc súng"},{"hanzi":"造纸术","pinyin":"zàozhǐshù","vi":"kỹ thuật làm giấy"},{"hanzi":"印刷术","pinyin":"yìnshuāshù","vi":"kỹ thuật in"}],"traditional":"四大發明"},{"id":"四大名著","hanzi":"四大名著","pinyin":"sìdàmíngzhù","meaning_vi":"Tứ đại danh tác (Tam Quốc, Thủy Hử, Tây Du Ký, Hồng Lâu Mộng)","explanation":"四大 (tứ đại – bốn lớn) + 名著 (danh trứ – tác phẩm nổi tiếng) → bốn tiểu thuyết cổ điển nổi tiếng nhất TQ: Tam Quốc, Thủy Hử, Tây Du Ký, Hồng Lâu Mộng.","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"我读过四大名著。","pinyin":"Wǒ dúguo sìdàmíngzhù.","vi":"Tôi đã đọc Tứ đại danh tác."},{"type":"simple","zh":"四大名著里我最喜欢的是《西游记》。","pinyin":"Sìdàmíngzhù li wǒ zuì xǐhuan de shì Xīyóujì.","vi":"Trong Tứ đại danh tác, tôi thích nhất Tây Du Ký."},{"type":"compound","zh":"虽然四大名著篇幅很长，但是改编的电视剧家喻户晓。","pinyin":"Suīrán sìdàmíngzhù piānfú hěn cháng, dànshì gǎibiān de diànshìjù jiāyùhùxiǎo.","vi":"Tuy Tứ đại danh tác rất dài nhưng các bộ phim truyền hình chuyển thể thì nhà nhà đều biết."}],"related":[{"hanzi":"三国演义","pinyin":"Sānguóyǎnyì","vi":"Tam Quốc Diễn Nghĩa"},{"hanzi":"水浒传","pinyin":"Shuǐhǔzhuàn","vi":"Thủy Hử"},{"hanzi":"西游记","pinyin":"Xīyóujì","vi":"Tây Du Ký"},{"hanzi":"红楼梦","pinyin":"Hónglóumèng","vi":"Hồng Lâu Mộng"}]},{"id":"四合院","hanzi":"四合院","pinyin":"sìhéyuàn","meaning_vi":"nhà tứ hợp viện (kiến trúc nhà cổ Bắc Kinh)","explanation":"四 (tứ – bốn) + 合 (hợp – khép lại) + 院 (viện – sân) → kiểu nhà truyền thống Bắc Kinh, bốn dãy nhà bao quanh một khoảng sân ở giữa.","hsk_level":"7-9","tags":["danh-tu","van-hoa","nha-cua"],"image":"🏡","examples":[{"type":"basic","zh":"他住在四合院里。","pinyin":"Tā zhùzài sìhéyuàn li.","vi":"Anh ấy sống trong một tứ hợp viện."},{"type":"simple","zh":"胡同深处有一座保存完好的清代四合院。","pinyin":"Hútòng shēnchù yǒu yí zuò bǎocún wánhǎo de Qīngdài sìhéyuàn.","vi":"Sâu trong ngõ có một tứ hợp viện thời Thanh được bảo tồn nguyên vẹn."},{"type":"compound","zh":"四合院虽然冬天有点冷，但是邻里关系特别亲近。","pinyin":"Sìhéyuàn suīrán dōngtiān yǒudiǎn lěng, dànshì línlǐ guānxì tèbié qīnjìn.","vi":"Tứ hợp viện tuy mùa đông hơi lạnh nhưng quan hệ hàng xóm rất gần gũi."}],"related":[{"hanzi":"胡同","pinyin":"hútòng","vi":"ngõ hẻm Bắc Kinh"},{"hanzi":"院子","pinyin":"yuànzi","vi":"sân nhà"},{"hanzi":"老北京","pinyin":"lǎoběijīng","vi":"Bắc Kinh xưa"},{"hanzi":"建筑","pinyin":"jiànzhù","vi":"kiến trúc"}]},{"id":"四季如春","hanzi":"四季如春","pinyin":"sìjì-rúchūn","meaning_vi":"bốn mùa như mùa xuân (khí hậu ôn hòa như Côn Minh)","explanation":"四 (số 4) + 季 (季) + 如 (如) + 春 (mùa xuân/thanh xuân).","hsk_level":"7-9","tags":["thanh-ngu","thoi-tiet"],"image":"🌸","examples":[{"type":"basic","zh":"昆明四季如春。","pinyin":"Kūnmíng sìjìrúchūn.","vi":"Côn Minh bốn mùa như xuân."},{"type":"simple","zh":"很多北方老人喜欢去四季如春的大理养老。","pinyin":"Hěn duō běifāng lǎorén xǐhuan qù sìjìrúchūn de dàlǐ yǎnglǎo.","vi":"Nhiều người già miền Bắc thích đến Đại Lý bốn mùa như xuân để dưỡng già."},{"type":"compound","zh":"因为这里四季如春，所以一年到头都开着鲜花。","pinyin":"Yīnwèi zhèlǐ sìjìrúchūn, suǒyǐ yìniándàotóu dōu kāizhe xiānhuā.","vi":"Vì nơi đây bốn mùa như xuân nên quanh năm đều có hoa tươi nở."}],"related":[{"hanzi":"春城","pinyin":"chūnchéng","vi":"thành phố mùa xuân"},{"hanzi":"昆明","pinyin":"Kūnmíng","vi":"Côn Minh"},{"hanzi":"气候宜人","pinyin":"qìhòuyírén","vi":"khí hậu dễ chịu"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"}]},{"id":"肆意","hanzi":"肆意","pinyin":"sìyì","meaning_vi":"tùy tiện, ngang nhiên, không kiêng nể gì","explanation":"肆 (ngang ngược/buông thả) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["pho-tu"],"image":"😤","examples":[{"type":"basic","zh":"他肆意挥霍钱财。","pinyin":"Tā sìyì huīhuò qiáncái.","vi":"Anh ta tùy tiện phung phí tiền của."},{"type":"simple","zh":"一些网友在评论区肆意攻击那位演员。","pinyin":"Yìxiē wǎngyǒu zài pínglùnqū sìyì gōngjī nà wèi yǎnyuán.","vi":"Một số cư dân mạng ngang nhiên công kích diễn viên đó trong phần bình luận."},{"type":"compound","zh":"如果任由企业肆意排污，河流就会被彻底毁掉。","pinyin":"Rúguǒ rènyóu qǐyè sìyì páiwū, héliú jiù huì bèi chèdǐ huǐdiào.","vi":"Nếu để doanh nghiệp tùy tiện xả thải, sông ngòi sẽ bị hủy hoại hoàn toàn."}],"related":[{"hanzi":"任意","pinyin":"rènyì","vi":"tùy ý"},{"hanzi":"随意","pinyin":"suíyì","vi":"tùy tiện"},{"hanzi":"放肆","pinyin":"fàngsì","vi":"càn rỡ"},{"hanzi":"肆无忌惮","pinyin":"sìwújìdàn","vi":"không kiêng nể gì"}]},{"id":"饲养员","hanzi":"饲养员","pinyin":"sìyǎngyuán","meaning_vi":"nhân viên chăm sóc động vật (sở thú)","explanation":"饲 (chăn nuôi) + 养 (nuôi dưỡng/tu dưỡng) + 员 (员).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","dong-vat"],"image":"🐼","examples":[{"type":"basic","zh":"饲养员在喂熊猫。","pinyin":"Sìyǎngyuán zài wèi xióngmāo.","vi":"Nhân viên chăm sóc đang cho gấu trúc ăn."},{"type":"simple","zh":"动物园的饲养员每天清晨给大象洗澡。","pinyin":"Dòngwùyuán de sìyǎngyuán měitiān qīngchén gěi dàxiàng xǐzǎo.","vi":"Nhân viên chăm sóc của sở thú mỗi sáng sớm tắm cho voi."},{"type":"compound","zh":"小猴子一看到饲养员，就高兴地跳了过来。","pinyin":"Xiǎo hóuzi yí kàndào sìyǎngyuán, jiù gāoxìng de tiàole guòlái.","vi":"Chú khỉ con vừa thấy người chăm sóc đã vui mừng nhảy tới."}],"related":[{"hanzi":"饲养","pinyin":"sìyǎng","vi":"chăn nuôi"},{"hanzi":"动物园","pinyin":"dòngwùyuán","vi":"vườn thú"},{"hanzi":"喂养","pinyin":"wèiyǎng","vi":"cho ăn nuôi"},{"hanzi":"饲料","pinyin":"sìliào","vi":"thức ăn chăn nuôi"}],"traditional":"飼養員"},{"id":"送别","hanzi":"送别","pinyin":"sòngbié","meaning_vi":"tiễn biệt","explanation":"送 (tặng) + 别 (khác biệt/từ biệt).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👋","examples":[{"type":"basic","zh":"大家到车站送别他。","pinyin":"Dàjiā dào chēzhàn sòngbié tā.","vi":"Mọi người ra ga tiễn biệt anh ấy."},{"type":"simple","zh":"全村人自发来到村口送别老支书。","pinyin":"Quán cūn rén zìfā láidào cūn kǒu sòngbié lǎo zhīshū.","vi":"Cả làng tự nguyện ra đầu làng tiễn biệt ông bí thư già."},{"type":"compound","zh":"虽然送别时没有流泪，但是她回家后哭了很久。","pinyin":"Suīrán sòngbié shí méiyǒu liúlèi, dànshì tā huíjiā hòu kūle hěn jiǔ.","vi":"Tuy lúc tiễn biệt không rơi nước mắt nhưng về nhà cô ấy khóc rất lâu."}],"related":[{"hanzi":"告别","pinyin":"gàobié","vi":"từ biệt"},{"hanzi":"送行","pinyin":"sòngxíng","vi":"tiễn đưa"},{"hanzi":"离别","pinyin":"líbié","vi":"ly biệt"},{"hanzi":"迎接","pinyin":"yíngjiē","vi":"đón tiếp"}],"traditional":"送別"},{"id":"送行","hanzi":"送行","pinyin":"sòngxíng","meaning_vi":"tiễn lên đường","explanation":"送 (tặng) + 行 (được).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧳","examples":[{"type":"basic","zh":"我去机场给你送行。","pinyin":"Wǒqù jīchǎng gěi nǐ sòngxíng.","vi":"Tôi ra sân bay tiễn bạn."},{"type":"simple","zh":"出国前一晚朋友们为他办了一场送行宴。","pinyin":"Chūguó qián yì wǎn péngyoumen wèi tā bànle yì chǎng sòngxíng yàn.","vi":"Tối trước khi xuất ngoại, bạn bè tổ chức một bữa tiệc tiễn anh ấy."},{"type":"compound","zh":"因为明早要上班，所以我没法去码头为你送行。","pinyin":"Yīnwèi míngzǎo yào shàngbān, suǒyǐ wǒ méifǎ qù mǎtóu wèi nǐ sòngxíng.","vi":"Vì sáng mai phải đi làm nên tôi không thể ra bến tàu tiễn bạn."}],"related":[{"hanzi":"送别","pinyin":"sòngbié","vi":"tiễn biệt"},{"hanzi":"饯行","pinyin":"jiànxíng","vi":"tiệc tiễn"},{"hanzi":"送机","pinyin":"sòngjī","vi":"tiễn ra sân bay"},{"hanzi":"接风","pinyin":"jiēfēng","vi":"tiệc đón"}]},{"id":"颂扬","hanzi":"颂扬","pinyin":"sòngyáng","meaning_vi":"ca ngợi, tán dương","explanation":"颂 (ca tụng) + 扬 (phát huy/tuyên dương).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🎶","examples":[{"type":"basic","zh":"人们颂扬他的功绩。","pinyin":"Rénmen sòngyáng tā de gōngjì.","vi":"Mọi người ca ngợi công lao của ông ấy."},{"type":"simple","zh":"这首民歌颂扬了母亲无私的爱。","pinyin":"Zhè shǒu míngē sòngyángle mǔqīn wúsī de ài.","vi":"Bài dân ca này ca ngợi tình yêu vô tư của người mẹ."},{"type":"compound","zh":"他虽然被媒体广泛颂扬，但是本人却十分低调。","pinyin":"Tā suīrán bèi méitǐ guǎngfàn sòngyáng, dànshì běnrén què shífēn dīdiào.","vi":"Ông ấy tuy được truyền thông ca ngợi rộng rãi nhưng bản thân lại rất khiêm tốn."}],"related":[{"hanzi":"赞扬","pinyin":"zànyáng","vi":"ca ngợi"},{"hanzi":"歌颂","pinyin":"gēsòng","vi":"ca tụng"},{"hanzi":"称颂","pinyin":"chēngsòng","vi":"tán tụng"},{"hanzi":"贬低","pinyin":"biǎndī","vi":"hạ thấp"}],"traditional":"頌揚"},{"id":"速成","hanzi":"速成","pinyin":"sùchéng","meaning_vi":"cấp tốc, học nhanh trong thời gian ngắn","explanation":"速 (nhanh chóng/tốc độ) + 成 (thành công/trưởng thành).","hsk_level":"7-9","tags":["tinh-tu","hoc-tap"],"image":"⚡","examples":[{"type":"basic","zh":"我报了速成班。","pinyin":"Wǒ bàole sùchéngbān.","vi":"Tôi đăng ký lớp cấp tốc."},{"type":"simple","zh":"他想靠一个月的速成课程通过驾照考试。","pinyin":"Tā xiǎng kào yí gèyuè de sùchéng kèchéng tōngguò jiàzhào kǎoshì.","vi":"Anh ấy muốn nhờ khóa cấp tốc một tháng để đỗ kỳ thi bằng lái."},{"type":"compound","zh":"学外语没有速成的捷径，只有坚持才能见效。","pinyin":"Xué wàiyǔ méiyǒu sùchéng de jiéjìng, zhǐyǒu jiānchí cáinéng jiànxiào.","vi":"Học ngoại ngữ không có đường tắt cấp tốc, chỉ có kiên trì mới thấy hiệu quả."}],"related":[{"hanzi":"速成班","pinyin":"sùchéngbān","vi":"lớp cấp tốc"},{"hanzi":"快速","pinyin":"kuàisù","vi":"nhanh chóng"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"},{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự từng bước"}]},{"id":"速冻","hanzi":"速冻","pinyin":"sùdòng","meaning_vi":"đông lạnh nhanh (thực phẩm)","explanation":"速 (nhanh chóng/tốc độ) + 冻 (đông cứng).","hsk_level":"7-9","tags":["tinh-tu","an-uong"],"image":"❄️","examples":[{"type":"basic","zh":"冰箱里有速冻饺子。","pinyin":"Bīngxiāng li yǒu sùdòng jiǎozi.","vi":"Trong tủ lạnh có sủi cảo đông lạnh."},{"type":"simple","zh":"加班回家后他煮了一袋速冻汤圆当夜宵。","pinyin":"Jiābān huíjiā hòu tā zhǔle yí dài sùdòng tāngyuán dāng yèxiāo.","vi":"Tan ca về nhà, anh ấy nấu một gói bánh trôi đông lạnh làm bữa khuya."},{"type":"compound","zh":"蔬菜经过速冻处理以后，营养就能保存得更久。","pinyin":"Shūcài jīngguò sùdòng chǔlǐ yǐhòu, yíngyǎng jiù néng bǎocún de gèng jiǔ.","vi":"Rau sau khi được cấp đông nhanh, dinh dưỡng có thể giữ được lâu hơn."}],"related":[{"hanzi":"冷冻","pinyin":"lěngdòng","vi":"đông lạnh"},{"hanzi":"速冻饺子","pinyin":"sùdòngjiǎozi","vi":"sủi cảo đông lạnh"},{"hanzi":"冷藏","pinyin":"lěngcáng","vi":"ướp lạnh"},{"hanzi":"解冻","pinyin":"jiědòng","vi":"rã đông"}],"traditional":"速凍"},{"id":"肃静","hanzi":"肃静","pinyin":"sùjìng","meaning_vi":"im lặng trang nghiêm","explanation":"肃 (nghiêm túc) + 静 (静).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤫","examples":[{"type":"basic","zh":"法庭内请保持肃静。","pinyin":"Fǎtíng nèi qǐng bǎochí sùjìng.","vi":"Trong phòng xử án xin giữ im lặng trang nghiêm."},{"type":"simple","zh":"追悼会开始时整个礼堂一片肃静。","pinyin":"Zhuīdàohuì kāishǐ shí zhěnggè lǐtáng yípiàn sùjìng.","vi":"Khi lễ truy điệu bắt đầu, cả hội trường im lặng trang nghiêm."},{"type":"compound","zh":"法官一敲法槌，全场就立刻肃静下来。","pinyin":"Fǎguān yì qiāo fǎchuí, quánchǎng jiù lìkè sùjìng xiàlái.","vi":"Thẩm phán vừa gõ búa, cả phòng lập tức im phăng phắc."}],"related":[{"hanzi":"安静","pinyin":"ānjìng","vi":"yên tĩnh"},{"hanzi":"肃穆","pinyin":"sùmù","vi":"trang nghiêm"},{"hanzi":"寂静","pinyin":"jìjìng","vi":"tĩnh mịch"},{"hanzi":"喧哗","pinyin":"xuānhuá","vi":"ồn ào"}],"traditional":"肅靜"},{"id":"素描","hanzi":"素描","pinyin":"sùmiáo","meaning_vi":"vẽ phác họa chì","explanation":"素 (tố chất/chay) + 描 (miêu tả).","hsk_level":"7-9","tags":["danh-tu","giai-tri","hoc-tap"],"image":"✏️","examples":[{"type":"basic","zh":"她在画素描。","pinyin":"Tā zài huà sùmiáo.","vi":"Cô ấy đang vẽ phác họa chì."},{"type":"simple","zh":"美术生每天要花四个小时练习人物素描。","pinyin":"Měishù shēng měitiān yào huā sì gè xiǎoshí liànxí rénwù sùmiáo.","vi":"Sinh viên mỹ thuật mỗi ngày phải dành bốn tiếng luyện vẽ chì chân dung."},{"type":"compound","zh":"如果素描基础打得不牢，就很难画好油画。","pinyin":"Rúguǒ sùmiáo jīchǔ dǎ de bù láo, jiù hěn nán huà hǎo yóuhuà.","vi":"Nếu nền tảng vẽ chì không vững thì rất khó vẽ tốt tranh sơn dầu."}],"related":[{"hanzi":"速写","pinyin":"sùxiě","vi":"ký họa nhanh"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"铅笔","pinyin":"qiānbǐ","vi":"bút chì"},{"hanzi":"油画","pinyin":"yóuhuà","vi":"tranh sơn dầu"}]},{"id":"肃穆","hanzi":"肃穆","pinyin":"sùmù","meaning_vi":"trang nghiêm thành kính","explanation":"肃 (nghiêm túc) + 穆 (trang nghiêm/hòa thuận).","hsk_level":"7-9","tags":["tinh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"烈士陵园庄严肃穆。","pinyin":"Lièshì língyuán zhuāngyán sùmù.","vi":"Nghĩa trang liệt sĩ trang nghiêm thành kính."},{"type":"simple","zh":"寺庙里的气氛肃穆得让人不敢大声说话。","pinyin":"Sìmiào li de qìfēn sùmù de ràng rén bù gǎn dàshēng shuōhuà.","vi":"Không khí trong chùa trang nghiêm đến mức khiến người ta không dám nói to."},{"type":"compound","zh":"升旗仪式一开始，广场上就变得肃穆起来。","pinyin":"Shēngqí yíshì yì kāishǐ, guǎngchǎng shang jiù biànde sùmù qǐlái.","vi":"Lễ thượng cờ vừa bắt đầu, quảng trường liền trở nên trang nghiêm."}],"related":[{"hanzi":"庄严","pinyin":"zhuāngyán","vi":"trang nghiêm"},{"hanzi":"庄重","pinyin":"zhuāngzhòng","vi":"trang trọng"},{"hanzi":"肃静","pinyin":"sùjìng","vi":"im lặng trang nghiêm"},{"hanzi":"严肃","pinyin":"yánsù","vi":"nghiêm túc"}],"traditional":"肅穆"},{"id":"诉求","hanzi":"诉求","pinyin":"sùqiú","meaning_vi":"nguyện vọng, yêu cầu kiến nghị","explanation":"诉 (tố tụng/kể lể) + 求 (求).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📢","examples":[{"type":"basic","zh":"员工提出了诉求。","pinyin":"Yuángōng tíchūle sùqiú.","vi":"Nhân viên đã đưa ra yêu cầu kiến nghị."},{"type":"simple","zh":"居民们的主要诉求是尽快修好小区电梯。","pinyin":"Jūmínmen de zhǔyào sùqiú shì jǐnkuài xiūhǎo xiǎoqū diàntī.","vi":"Nguyện vọng chính của cư dân là sửa thang máy khu nhà càng sớm càng tốt."},{"type":"compound","zh":"只有认真倾听消费者的诉求，品牌才能赢得口碑。","pinyin":"Zhǐyǒu rènzhēn qīngtīng xiāofèizhě de sùqiú, pǐnpái cáinéng yíngdé kǒubēi.","vi":"Chỉ khi lắng nghe kỹ nguyện vọng người tiêu dùng, thương hiệu mới giành được tiếng tốt."}],"related":[{"hanzi":"要求","pinyin":"yāoqiú","vi":"yêu cầu"},{"hanzi":"需求","pinyin":"xūqiú","vi":"nhu cầu"},{"hanzi":"愿望","pinyin":"yuànwàng","vi":"nguyện vọng"},{"hanzi":"利益诉求","pinyin":"lìyìsùqiú","vi":"yêu cầu lợi ích"}],"traditional":"訴求"},{"id":"诉说","hanzi":"诉说","pinyin":"sùshuō","meaning_vi":"kể lể, tâm sự","explanation":"诉 (tố tụng/kể lể) + 说 (nói).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"她向我诉说烦恼。","pinyin":"Tā xiàng wǒ sùshuō fánnǎo.","vi":"Cô ấy tâm sự với tôi những phiền muộn."},{"type":"simple","zh":"老人坐在门口向路人诉说当年的往事。","pinyin":"Lǎorén zuò zài ménkǒu xiàng lùrén sùshuō dāngnián de wǎngshì.","vi":"Ông cụ ngồi trước cửa kể cho người qua đường chuyện năm xưa."},{"type":"compound","zh":"每当心里难受，她就给远方的姐姐写信诉说。","pinyin":"Měidāng xīnli nánshòu, tā jiù gěi yuǎnfāng de jiějie xiěxìn sùshuō.","vi":"Mỗi khi trong lòng khó chịu, cô ấy lại viết thư tâm sự với chị gái ở phương xa."}],"related":[{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"讲述","pinyin":"jiǎngshù","vi":"kể lại"},{"hanzi":"述说","pinyin":"shùshuō","vi":"thuật lại"},{"hanzi":"诉苦","pinyin":"sùkǔ","vi":"kể khổ"}],"traditional":"訴說"},{"id":"素养","hanzi":"素养","pinyin":"sùyǎng","meaning_vi":"tố chất và sự tu dưỡng (văn hóa/nghệ thuật)","explanation":"素 (tố chất/chay) + 养 (nuôi dưỡng/tu dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"🎓","examples":[{"type":"basic","zh":"他的艺术素养很高。","pinyin":"Tā de yìshù sùyǎng hěn gāo.","vi":"Tố chất nghệ thuật của anh ấy rất cao."},{"type":"simple","zh":"这次培训旨在提高记者的职业素养。","pinyin":"Zhè cì péixùn zhǐzài tígāo jìzhě de zhíyè sùyǎng.","vi":"Khóa đào tạo này nhằm nâng cao tố chất nghề nghiệp của phóng viên."},{"type":"compound","zh":"一个人的素养不但体现在学历上，而且体现在细节中。","pinyin":"Yígèrén de sùyǎng búdàn tǐ xiànzài xuélì shang, érqiě tǐ xiànzài xìjié zhōng.","vi":"Tố chất của một người không chỉ thể hiện ở bằng cấp mà còn ở những chi tiết nhỏ."}],"related":[{"hanzi":"素质","pinyin":"sùzhì","vi":"tố chất"},{"hanzi":"修养","pinyin":"xiūyǎng","vi":"tu dưỡng"},{"hanzi":"涵养","pinyin":"hányǎng","vi":"hàm dưỡng"},{"hanzi":"文化素养","pinyin":"wénhuàsùyǎng","vi":"trình độ văn hóa"}],"traditional":"素養"},{"id":"素质教育","hanzi":"素质教育","pinyin":"sùzhìjiàoyù","meaning_vi":"giáo dục toàn diện phẩm chất và năng lực","explanation":"素 (tố chất/vốn dĩ) + 质 (chất lượng/bản chất) + 教 (dạy) + 育 (giáo dục/nuôi dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","xa-hoi"],"image":"🎓","examples":[{"type":"basic","zh":"学校推行素质教育。","pinyin":"Xuéxiào tuīxíng sùzhìjiàoyù.","vi":"Nhà trường thực hiện giáo dục toàn diện."},{"type":"simple","zh":"这所中学把体育和音乐纳入了素质教育课程。","pinyin":"Zhè suǒ zhōngxué bǎ tǐyù hé yīnyuè nàrùle sùzhìjiàoyù kèchéng.","vi":"Trường trung học này đưa thể dục và âm nhạc vào chương trình giáo dục toàn diện."},{"type":"compound","zh":"如果只看考试分数，素质教育就只能停留在口号上。","pinyin":"Rúguǒ zhǐ kàn kǎoshì fēnshù, sùzhìjiàoyù jiù zhǐnéng tíngliú zài kǒuhào shang.","vi":"Nếu chỉ nhìn điểm thi, giáo dục toàn diện sẽ chỉ dừng lại ở khẩu hiệu."}],"related":[{"hanzi":"应试教育","pinyin":"yìngshìjiàoyù","vi":"giáo dục chạy theo thi cử"},{"hanzi":"素质","pinyin":"sùzhì","vi":"tố chất"},{"hanzi":"全面发展","pinyin":"quánmiànfāzhǎn","vi":"phát triển toàn diện"},{"hanzi":"教育改革","pinyin":"jiàoyùgǎigé","vi":"cải cách giáo dục"}],"traditional":"素質教育"},{"id":"俗称","hanzi":"俗称","pinyin":"súchēng","meaning_vi":"dân gian gọi là, thường gọi là; tên gọi dân gian","explanation":"俗 (phong tục/thông tục) + 称 (khen ngợi/xưng hô).","hsk_level":"7-9","tags":["dong-tu","ngon-ngu"],"image":"🗣️","examples":[{"type":"basic","zh":"马铃薯俗称土豆。","pinyin":"Mǎlíngshǔ súchēng tǔdòu.","vi":"Mã linh thự dân gian gọi là khoai tây."},{"type":"simple","zh":"这种白色的小鸟在当地俗称“报喜鸟”。","pinyin":"Zhè zhǒng báisè de xiǎoniǎo zài dāngdì súchēng bàoxǐ niǎo.","vi":"Loài chim nhỏ màu trắng này ở địa phương dân gian gọi là \"chim báo hỷ\"."},{"type":"compound","zh":"红薯在北方俗称地瓜，在南方却有别的叫法。","pinyin":"Hóngshǔ zài běifāng súchēng dìguā, zài nánfāng què yǒu biéde jiàofǎ.","vi":"Khoai lang ở phương Bắc dân gian gọi là \"địa qua\", ở phương Nam lại có cách gọi khác."}],"related":[{"hanzi":"俗名","pinyin":"súmíng","vi":"tên dân gian"},{"hanzi":"简称","pinyin":"jiǎnchēng","vi":"tên gọi tắt"},{"hanzi":"学名","pinyin":"xuémíng","vi":"tên khoa học"},{"hanzi":"别称","pinyin":"biéchēng","vi":"tên gọi khác"}],"traditional":"俗稱"},{"id":"撒娇","hanzi":"撒娇","pinyin":"sājiāo","meaning_vi":"làm nũng, nhõng nhẽo","explanation":"撒 + 娇 (nũng nịu). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🥺","examples":[{"type":"basic","zh":"女儿向爸爸撒娇。","pinyin":"Nǚ'ér xiàng bàba sājiāo.","vi":"Con gái làm nũng với bố."},{"type":"simple","zh":"小猫总是蹭着主人的腿撒娇要吃的。","pinyin":"Xiǎomāo zǒngshì cèngzhe zhǔrén de tuǐ sājiāo yào chī de.","vi":"Con mèo nhỏ luôn cọ vào chân chủ làm nũng đòi ăn."},{"type":"compound","zh":"她一撒娇，男朋友就什么要求都答应了。","pinyin":"Tā yì sājiāo, nánpéngyou jiù shénme yāoqiú dōu dāying le.","vi":"Cô ấy hễ làm nũng là bạn trai đồng ý mọi yêu cầu."}],"related":[{"hanzi":"任性","pinyin":"rènxìng","vi":"bướng bỉnh"},{"hanzi":"可爱","pinyin":"kě'ài","vi":"đáng yêu"},{"hanzi":"卖萌","pinyin":"màiméng","vi":"làm dễ thương"},{"hanzi":"耍赖","pinyin":"shuǎlài","vi":"ăn vạ"}],"traditional":"撒嬌"},{"id":"撒手","hanzi":"撒手","pinyin":"sāshǒu","meaning_vi":"buông tay","explanation":"撒 (vãi/làm nũng) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["dong-tu"],"image":"👐","examples":[{"type":"basic","zh":"别撒手，抓紧绳子！","pinyin":"Bié sāshǒu, zhuājǐn shéngzi!","vi":"Đừng buông tay, nắm chặt dây!"},{"type":"simple","zh":"他把公司的事全部撒手交给了儿子。","pinyin":"Tā bǎ gōngsī de shì quánbù sāshǒu jiāogěile érzi.","vi":"Ông ấy buông tay giao toàn bộ việc công ty cho con trai."},{"type":"compound","zh":"刚学骑自行车时，爸爸在后面一撒手，我就摔倒了。","pinyin":"Gāng xué qí zìxíngchē shí, bàba zài hòumiàn yì sāshǒu, wǒ jiù shuāidǎo le.","vi":"Hồi mới tập đi xe đạp, bố ở phía sau vừa buông tay là tôi ngã."}],"related":[{"hanzi":"放手","pinyin":"fàngshǒu","vi":"buông tay"},{"hanzi":"松手","pinyin":"sōngshǒu","vi":"thả tay"},{"hanzi":"撒手不管","pinyin":"sāshǒubùguǎn","vi":"buông xuôi mặc kệ"},{"hanzi":"撒手人寰","pinyin":"sāshǒurénhuán","vi":"qua đời"}]},{"id":"三番五次","hanzi":"三番五次","pinyin":"sānfān-wǔcì","meaning_vi":"năm lần bảy lượt","explanation":"三 (số 3) + 番 (lần) + 五 (số 5) + 次 (thứ tự/lần lượt).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🔁","examples":[{"type":"basic","zh":"他三番五次迟到。","pinyin":"Tā sānfānwǔcì chídào.","vi":"Anh ấy năm lần bảy lượt đi muộn."},{"type":"simple","zh":"邻居三番五次上门投诉我们家的狗太吵。","pinyin":"Línjū sānfānwǔcì shàngmén tóusù wǒmen jiā de gǒu tài chǎo.","vi":"Hàng xóm năm lần bảy lượt đến phàn nàn chó nhà chúng tôi quá ồn."},{"type":"compound","zh":"虽然我三番五次提醒他，但是他还是忘了带钥匙。","pinyin":"Suīrán wǒ sānfānwǔcì tíxǐng tā, dànshì tā háishì wàngle dài yàoshi.","vi":"Tuy tôi đã nhắc năm lần bảy lượt nhưng anh ấy vẫn quên mang chìa khóa."}],"related":[{"hanzi":"一再","pinyin":"yízài","vi":"hết lần này đến lần khác"},{"hanzi":"屡次","pinyin":"lǚcì","vi":"nhiều lần"},{"hanzi":"反复","pinyin":"fǎnfù","vi":"lặp đi lặp lại"},{"hanzi":"再三","pinyin":"zàisān","vi":"nhiều lần"}]},{"id":"三思","hanzi":"三思","pinyin":"sānsī","meaning_vi":"suy nghĩ kỹ càng","explanation":"三 (số 3) + 思 (suy nghĩ/tư duy).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🤔","examples":[{"type":"basic","zh":"请三思而后行。","pinyin":"Qǐng sānsī'érhòuxíng.","vi":"Xin hãy suy nghĩ kỹ rồi hãy làm."},{"type":"simple","zh":"辞职这么大的事你最好再三思一下。","pinyin":"Cízhí zhème dà de shì nǐ zuìhǎo zài sānsī yíxià.","vi":"Chuyện nghỉ việc lớn như vậy bạn tốt nhất nên suy nghĩ kỹ thêm."},{"type":"compound","zh":"因为投资有风险，所以签合同前一定要三思。","pinyin":"Yīnwèi tóuzī yǒu fēngxiǎn, suǒyǐ qiānhétong qián yídìngyào sānsī.","vi":"Vì đầu tư có rủi ro nên trước khi ký hợp đồng nhất định phải suy nghĩ kỹ."}],"related":[{"hanzi":"三思而后行","pinyin":"sānsī érhòu xíng","vi":"nghĩ kỹ rồi hãy làm"},{"hanzi":"深思熟虑","pinyin":"shēnsīshúlǜ","vi":"suy nghĩ chín chắn"},{"hanzi":"考虑","pinyin":"kǎolǜ","vi":"cân nhắc"},{"hanzi":"冲动","pinyin":"chōngdòng","vi":"bốc đồng"}]},{"id":"思潮","hanzi":"思潮","pinyin":"sīcháo","meaning_vi":"trào lưu tư tưởng","explanation":"思 (suy nghĩ/tư duy) + 潮 (thủy triều/trào lưu).","hsk_level":"7-9","tags":["danh-tu","van-hoa","xa-hoi"],"image":"🌊","examples":[{"type":"basic","zh":"这是一种新思潮。","pinyin":"Zhè shì yì zhǒng xīn sīcháo.","vi":"Đây là một trào lưu tư tưởng mới."},{"type":"simple","zh":"五四运动时期各种西方思潮涌入中国。","pinyin":"Wǔsìyùndòng shíqī gèzhǒng Xīfāng sīcháo yǒngrù Zhōngguó.","vi":"Thời kỳ phong trào Ngũ Tứ, các trào lưu tư tưởng phương Tây tràn vào Trung Quốc."},{"type":"compound","zh":"随着社会的变化，新的文艺思潮也不断出现。","pinyin":"Suízhe shèhuì de biànhuà, xīn de wényì sīcháo yě búduàn chūxiàn.","vi":"Cùng với sự thay đổi của xã hội, các trào lưu tư tưởng văn nghệ mới cũng không ngừng xuất hiện."}],"related":[{"hanzi":"思想","pinyin":"sīxiǎng","vi":"tư tưởng"},{"hanzi":"潮流","pinyin":"cháoliú","vi":"trào lưu"},{"hanzi":"社会思潮","pinyin":"shèhuìsīcháo","vi":"trào lưu xã hội"},{"hanzi":"思绪","pinyin":"sīxù","vi":"dòng suy nghĩ"}]},{"id":"丝绸之路","hanzi":"丝绸之路","pinyin":"Sīchóuzhīlù","meaning_vi":"Con đường Tơ lụa","explanation":"丝绸 (ti trù – tơ lụa) + 之 (chi – của) + 路 (lộ – đường) → Con đường Tơ lụa, tuyến giao thương nối TQ với Trung Á, châu Âu, mở từ thời Hán (Trương Khiên đi sứ Tây Vực).","hsk_level":"7-9","tags":["danh-tu","van-hoa","dia-danh"],"image":"🐫","examples":[{"type":"basic","zh":"丝绸之路历史悠久。","pinyin":"Sīchóuzhīlù lìshǐ yōujiǔ.","vi":"Con đường Tơ lụa có lịch sử lâu đời."},{"type":"simple","zh":"古代商人沿着丝绸之路把茶叶运到西方。","pinyin":"Gǔdài shāngrén yánzhe Sīchóuzhīlù bǎ cháyè yùn dào Xīfāng.","vi":"Thương nhân thời cổ theo Con đường Tơ lụa chở chè sang phương Tây."},{"type":"compound","zh":"丝绸之路不但是贸易通道，而且是文化交流的桥梁。","pinyin":"Sīchóuzhīlù bú dànshì màoyì tōngdào, érqiě shì wénhuàjiāoliú de qiáoliáng.","vi":"Con đường Tơ lụa không chỉ là tuyến thương mại mà còn là cầu nối giao lưu văn hóa."}],"related":[{"hanzi":"一带一路","pinyin":"Yídàiyílù","vi":"Vành đai và Con đường"},{"hanzi":"丝绸","pinyin":"sīchóu","vi":"tơ lụa"},{"hanzi":"丝路","pinyin":"Sīlù","vi":"Con đường Tơ lụa"},{"hanzi":"张骞","pinyin":"Zhāngqiān","vi":"Trương Khiên"}],"traditional":"絲綢之路"},{"id":"司法权","hanzi":"司法权","pinyin":"sīfǎquán","meaning_vi":"quyền tư pháp","explanation":"司 (cơ quan/quản lý) + 法 (法) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["danh-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"法院行使司法权。","pinyin":"Fǎyuàn xíngshǐ sīfǎquán.","vi":"Tòa án thực thi quyền tư pháp."},{"type":"simple","zh":"宪法规定司法权独立于行政机关。","pinyin":"Xiànfǎ guīdìng sīfǎquán dúlì yú xíngzhèng jīguān.","vi":"Hiến pháp quy định quyền tư pháp độc lập với cơ quan hành chính."},{"type":"compound","zh":"如果司法权受到干预，公民的权利就难以保障。","pinyin":"Rúguǒ sīfǎquán shòudào gānyù, gōngmín de quánlì jiù nányǐ bǎozhàng.","vi":"Nếu quyền tư pháp bị can thiệp thì quyền lợi công dân khó được đảm bảo."}],"related":[{"hanzi":"立法权","pinyin":"lìfǎquán","vi":"quyền lập pháp"},{"hanzi":"行政权","pinyin":"xíngzhèngquán","vi":"quyền hành pháp"},{"hanzi":"司法","pinyin":"sīfǎ","vi":"tư pháp"},{"hanzi":"法院","pinyin":"fǎyuàn","vi":"tòa án"}],"traditional":"司法權"},{"id":"私家车","hanzi":"私家车","pinyin":"sījiāchē","meaning_vi":"xe ô tô cá nhân","explanation":"私 (riêng tư) + 家 (nhà) + 车 (xe cộ).","hsk_level":"7-9","tags":["danh-tu","giao-thong","do-vat"],"image":"🚗","examples":[{"type":"basic","zh":"他买了辆私家车。","pinyin":"Tā mǎile liàng sījiāchē.","vi":"Anh ấy đã mua một chiếc xe riêng."},{"type":"simple","zh":"节假日高速公路上挤满了出游的私家车。","pinyin":"Jiéjiàrì gāosùgōnglù shang jǐmǎnle chūyóu de sījiāchē.","vi":"Ngày lễ đường cao tốc chật kín xe riêng đi du lịch."},{"type":"compound","zh":"私家车越来越多，城市停车就越来越难。","pinyin":"Sījiāchē yuèláiyuè duō, chéngshì tíngchē jiù yuèláiyuè nán.","vi":"Xe riêng ngày càng nhiều, đỗ xe trong thành phố ngày càng khó."}],"related":[{"hanzi":"轿车","pinyin":"jiàochē","vi":"ô tô con"},{"hanzi":"公交车","pinyin":"gōngjiāochē","vi":"xe buýt"},{"hanzi":"车主","pinyin":"chēzhǔ","vi":"chủ xe"},{"hanzi":"驾照","pinyin":"jiàzhào","vi":"bằng lái xe"}],"traditional":"私家車"},{"id":"丝路","hanzi":"丝路","pinyin":"Sīlù","meaning_vi":"Con đường Tơ lụa (viết tắt)","explanation":"丝 (tơ lụa/mảy may) + 路 (路).","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🐫","examples":[{"type":"basic","zh":"他沿着丝路旅行。","pinyin":"Tā yánzhe Sīlù lǚxíng.","vi":"Anh ấy du lịch dọc theo Con đường Tơ lụa."},{"type":"simple","zh":"敦煌是古丝路上一颗耀眼的明珠。","pinyin":"Dūnhuáng shì gǔ Sīlù shang yì kē yàoyǎn de míngzhū.","vi":"Đôn Hoàng là viên ngọc sáng chói trên Con đường Tơ lụa cổ."},{"type":"compound","zh":"只要沿着丝路一路向西，就能看到无数古城遗址。","pinyin":"Zhǐyào yánzhe Sīlù yi lùxiàng xī, jiù néng kàndào wúshù gǔchéng yízhǐ.","vi":"Chỉ cần đi dọc Con đường Tơ lụa về phía tây là có thể thấy vô số di chỉ thành cổ."}],"related":[{"hanzi":"丝绸之路","pinyin":"Sīchóuzhīlù","vi":"Con đường Tơ lụa"},{"hanzi":"一带一路","pinyin":"Yídàiyílù","vi":"Vành đai và Con đường"},{"hanzi":"丝绸","pinyin":"sīchóu","vi":"tơ lụa"},{"hanzi":"沿线","pinyin":"yánxiàn","vi":"dọc tuyến"}],"traditional":"絲路"},{"id":"私下","hanzi":"私下","pinyin":"sīxià","meaning_vi":"riêng tư, bí mật (nói chuyện/thỏa thuận riêng)","explanation":"私 (riêng tư) + 下 (dưới).","hsk_level":"7-9","tags":["pho-tu","giao-tiep"],"image":"🤫","examples":[{"type":"basic","zh":"我们私下谈谈吧。","pinyin":"Wǒmen sīxià tántan ba.","vi":"Chúng ta nói chuyện riêng nhé."},{"type":"simple","zh":"两家公司私下达成了价格协议。","pinyin":"Liǎng jiāgōng sī sīxià dáchéngle jiàgé xiéyì.","vi":"Hai công ty đã ngầm đạt được thỏa thuận giá."},{"type":"compound","zh":"他在会上一句话也没说，私下却跟我抱怨了半天。","pinyin":"Tā zài huì shang yíjùhuà yě méi shuō, sīxià què gēn wǒ bàoyuànle bàn tiān.","vi":"Trong cuộc họp anh ấy không nói câu nào, nhưng riêng tư lại than phiền với tôi cả buổi."}],"related":[{"hanzi":"暗地里","pinyin":"àndìli","vi":"lén lút"},{"hanzi":"私底下","pinyin":"sīdǐxia","vi":"riêng tư"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"悄悄","pinyin":"qiāoqiāo","vi":"lặng lẽ"}]},{"id":"思绪","hanzi":"思绪","pinyin":"sīxù","meaning_vi":"dòng suy nghĩ, tâm tư","explanation":"思 (suy nghĩ/tư duy) + 绪 (绪).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"她的思绪很乱。","pinyin":"Tā de sīxù hěn luàn.","vi":"Dòng suy nghĩ của cô ấy rất rối."},{"type":"simple","zh":"一阵电话铃声打断了他的思绪。","pinyin":"Yízhèn diànhuà língshēng dǎduànle tā de sīxù.","vi":"Một hồi chuông điện thoại cắt ngang dòng suy nghĩ của anh ấy."},{"type":"compound","zh":"每当听到这首老歌，她的思绪就会回到大学时代。","pinyin":"Měidāng tīngdào zhè shǒu lǎogē, tā de sīxù jiù huì huídào dàxué shídài.","vi":"Mỗi khi nghe bài hát cũ này, tâm tư cô ấy lại trở về thời đại học."}],"related":[{"hanzi":"思路","pinyin":"sīlù","vi":"mạch suy nghĩ"},{"hanzi":"心绪","pinyin":"xīnxù","vi":"tâm trạng"},{"hanzi":"思念","pinyin":"sīniàn","vi":"nhớ nhung"},{"hanzi":"思绪万千","pinyin":"sīxùwànqiān","vi":"trăm mối suy tư"}],"traditional":"思緒"},{"id":"私营","hanzi":"私营","pinyin":"sīyíng","meaning_vi":"tư nhân kinh doanh","explanation":"私 (riêng tư) + 营 (kinh doanh/doanh trại).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"他在私营企业工作。","pinyin":"Tā zài sīyíng qǐyè gōngzuò.","vi":"Anh ấy làm việc ở doanh nghiệp tư nhân."},{"type":"simple","zh":"这个小镇的私营经济近年来发展迅速。","pinyin":"Zhè ge xiǎozhèn de sīyíng jīngjì jìnniánlái fāzhǎn xùnsù.","vi":"Kinh tế tư nhân của thị trấn này mấy năm gần đây phát triển nhanh."},{"type":"compound","zh":"私营医院虽然收费较高，但是服务往往更周到。","pinyin":"Sīyíng yīyuàn suīrán shōufèi jiào gāo, dànshì fúwù wǎngwǎng gèng zhōudào.","vi":"Bệnh viện tư tuy thu phí cao hơn nhưng dịch vụ thường chu đáo hơn."}],"related":[{"hanzi":"私营企业","pinyin":"sīyíngqǐyè","vi":"doanh nghiệp tư nhân"},{"hanzi":"国营","pinyin":"guóyíng","vi":"quốc doanh"},{"hanzi":"民营","pinyin":"mínyíng","vi":"dân doanh"},{"hanzi":"个体户","pinyin":"gètǐhù","vi":"hộ kinh doanh cá thể"}],"traditional":"私營"},{"id":"松懈","hanzi":"松懈","pinyin":"sōngxiè","meaning_vi":"lơ là, chểnh mảng","explanation":"松 (thư giãn/cây thông) + 懈 (懈).","hsk_level":"7-9","tags":["dong-tu","tinh-tu"],"image":"😴","examples":[{"type":"basic","zh":"学习不能松懈。","pinyin":"Xuéxí bù néng sōngxiè.","vi":"Học tập không được lơ là."},{"type":"simple","zh":"比赛最后五分钟球员们明显松懈了。","pinyin":"Bǐsài zuìhòu wǔ fēnzhōng qiúyuánmen míngxiǎn sōngxiè le.","vi":"Năm phút cuối trận các cầu thủ rõ ràng đã lơ là."},{"type":"compound","zh":"即使疫情好转，防控工作也不能松懈。","pinyin":"Jíshǐ yìqíng hǎozhuǎn, fángkòng gōngzuò yě bù néng sōngxiè.","vi":"Dù dịch bệnh đã chuyển biến tốt, công tác phòng chống cũng không được lơ là."}],"related":[{"hanzi":"懈怠","pinyin":"xièdài","vi":"lười nhác"},{"hanzi":"松散","pinyin":"sōngsǎn","vi":"lỏng lẻo"},{"hanzi":"放松","pinyin":"fàngsōng","vi":"thả lỏng"},{"hanzi":"紧张","pinyin":"jǐnzhāng","vi":"căng thẳng"}],"traditional":"鬆懈"},{"id":"搜救","hanzi":"搜救","pinyin":"sōujiù","meaning_vi":"tìm kiếm cứu nạn","explanation":"搜 (tìm kiếm) + 救 (cứu).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚁","examples":[{"type":"basic","zh":"搜救工作仍在进行。","pinyin":"Sōujiù gōngzuò réng zài jìnxíng.","vi":"Công tác tìm kiếm cứu nạn vẫn đang tiếp diễn."},{"type":"simple","zh":"救援队连续三天在山里搜救失踪的驴友。","pinyin":"Jiùyuánduì liánxù sān tiān zài shān li sōujiù shīzōng de lǘyǒu.","vi":"Đội cứu hộ liên tục ba ngày tìm kiếm cứu nạn người đi phượt mất tích trong núi."},{"type":"compound","zh":"因为海上风浪太大，所以搜救船只好暂时返航。","pinyin":"Yīnwèi hǎishàng fēnglàng tài dà, suǒyǐ sōujiù chuán zhǐhǎo zànshí fǎnháng.","vi":"Vì sóng gió trên biển quá lớn nên tàu tìm kiếm cứu nạn đành tạm thời quay về."}],"related":[{"hanzi":"搜索","pinyin":"sōusuǒ","vi":"tìm kiếm"},{"hanzi":"救援","pinyin":"jiùyuán","vi":"cứu viện"},{"hanzi":"营救","pinyin":"yíngjiù","vi":"giải cứu"},{"hanzi":"救援队","pinyin":"jiùyuánduì","vi":"đội cứu hộ"}]},{"id":"搜集","hanzi":"搜集","pinyin":"sōují","meaning_vi":"sưu tầm, thu thập","explanation":"搜 (tìm kiếm) + 集 (tập hợp).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🔍","examples":[{"type":"basic","zh":"他喜欢搜集邮票。","pinyin":"Tā xǐhuan sōují yóupiào.","vi":"Anh ấy thích sưu tầm tem."},{"type":"simple","zh":"记者花了半年时间搜集这起案件的证据。","pinyin":"Jìzhě huāle bàn nián shíjiān sōují zhè qǐ ànjiàn de zhèngjù.","vi":"Phóng viên mất nửa năm thu thập chứng cứ vụ án này."},{"type":"compound","zh":"只有搜集到足够的数据，我们才能得出可靠的结论。","pinyin":"Zhǐyǒu sōují dào zúgòu de shùjù, wǒmen cáinéng déchū kěkào de jiélùn.","vi":"Chỉ khi thu thập đủ dữ liệu, chúng ta mới có thể rút ra kết luận đáng tin cậy."}],"related":[{"hanzi":"收集","pinyin":"shōují","vi":"thu thập"},{"hanzi":"采集","pinyin":"cǎijí","vi":"thu thập"},{"hanzi":"收藏","pinyin":"shōucáng","vi":"sưu tầm"},{"hanzi":"资料","pinyin":"zīliào","vi":"tư liệu"}],"traditional":"蒐集"},{"id":"扫除","hanzi":"扫除","pinyin":"sǎochú","meaning_vi":"quét dọn, dọn vệ sinh; quét sạch, xóa bỏ (chướng ngại, nạn mù chữ)","explanation":"扫 (quét dọn) + 除 (loại trừ/ngoài ra).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧹","examples":[{"type":"basic","zh":"我们要扫除文盲。","pinyin":"Wǒmen yào sǎochú wénmáng.","vi":"Chúng ta phải xóa nạn mù chữ."},{"type":"simple","zh":"春节前每家每户都要进行一次大扫除。","pinyin":"Chūnjié qián měi jiā měi hù dōu yào jìnxíng yí cì dàsǎochú.","vi":"Trước Tết mỗi nhà đều phải tổng vệ sinh một lần."},{"type":"compound","zh":"只要扫除了技术障碍，这个项目就能顺利推进。","pinyin":"Zhǐyào sǎochúle jìshù zhàng'ài, zhè ge xiàngmù jiù néng shùnlì tuījìn.","vi":"Chỉ cần quét sạch trở ngại kỹ thuật, dự án này sẽ được đẩy mạnh thuận lợi."}],"related":[{"hanzi":"大扫除","pinyin":"dàsǎochú","vi":"tổng vệ sinh"},{"hanzi":"清除","pinyin":"qīngchú","vi":"loại bỏ"},{"hanzi":"扫除障碍","pinyin":"sǎochúzhàng'ài","vi":"dọn trở ngại"},{"hanzi":"扫盲","pinyin":"sǎománg","vi":"xóa mù chữ"}],"traditional":"掃除"},{"id":"扫兴","hanzi":"扫兴","pinyin":"sǎoxìng","meaning_vi":"mất hứng, cụt hứng","explanation":"扫 (quét dọn) + 兴 (hưng thịnh/hứng thú).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😒","examples":[{"type":"basic","zh":"下雨真扫兴。","pinyin":"Xiàyǔ zhēn sǎoxìng.","vi":"Trời mưa thật mất hứng."},{"type":"simple","zh":"他在派对上讲了个扫兴的冷笑话。","pinyin":"Tā zài pài duìshang jiǎngle gè sǎoxìng de lěngxiàohua.","vi":"Anh ấy kể một câu chuyện cười nhạt làm mất hứng ở bữa tiệc."},{"type":"compound","zh":"本来想去海边玩，结果台风来了，大家都很扫兴。","pinyin":"Běnlái xiǎng qù hǎibiān wán, jiéguǒ táifēng lái le, dàjiā dōu hěn sǎoxìng.","vi":"Vốn định ra biển chơi, kết quả bão đến, ai nấy đều cụt hứng."}],"related":[{"hanzi":"败兴","pinyin":"bàixìng","vi":"mất hứng"},{"hanzi":"失望","pinyin":"shīwàng","vi":"thất vọng"},{"hanzi":"尽兴","pinyin":"jìnxìng","vi":"vui hết mình"},{"hanzi":"兴致","pinyin":"xìngzhì","vi":"hứng thú"}],"traditional":"掃興"},{"id":"死板","hanzi":"死板","pinyin":"sǐbǎn","meaning_vi":"cứng nhắc máy móc","explanation":"死 (tử vong/kiên quyết) + 板 (板).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤖","examples":[{"type":"basic","zh":"他做事太死板了。","pinyin":"Tā zuòshì tài sǐbǎn le.","vi":"Anh ấy làm việc quá cứng nhắc."},{"type":"simple","zh":"这份工作的规定死板得让人喘不过气。","pinyin":"Zhè fèn gōngzuò de guīdìng sǐbǎn de ràng rén chuǎnbuguò qì.","vi":"Quy định của công việc này cứng nhắc đến ngạt thở."},{"type":"compound","zh":"教学方法如果太死板，学生就会失去学习兴趣。","pinyin":"Jiàoxué fāngfǎ rúguǒ tài sǐbǎn, xuésheng jiù huì shīqù xuéxí xìngqù.","vi":"Nếu phương pháp giảng dạy quá cứng nhắc, học sinh sẽ mất hứng thú học tập."}],"related":[{"hanzi":"呆板","pinyin":"dāibǎn","vi":"cứng nhắc"},{"hanzi":"僵化","pinyin":"jiānghuà","vi":"cứng đờ"},{"hanzi":"灵活","pinyin":"línghuó","vi":"linh hoạt"},{"hanzi":"机械","pinyin":"jīxiè","vi":"máy móc"}]},{"id":"死角","hanzi":"死角","pinyin":"sǐjiǎo","meaning_vi":"góc khuất, điểm mù","explanation":"死 (tử vong/kiên quyết) + 角 (角).","hsk_level":"7-9","tags":["danh-tu","dia-diem"],"image":"📐","examples":[{"type":"basic","zh":"这里是监控死角。","pinyin":"Zhèlǐ shì jiānkòng sǐjiǎo.","vi":"Đây là điểm mù của camera giám sát."},{"type":"simple","zh":"大货车的右侧存在很大的视线死角。","pinyin":"Dà huòchē de yòucè cúnzài hěn dà de shìxiàn sǐjiǎo.","vi":"Bên phải xe tải lớn có một điểm mù tầm nhìn rất lớn."},{"type":"compound","zh":"打扫卫生时不但要擦桌子，而且不能留下卫生死角。","pinyin":"Dǎsǎo wèishēng shí búdàn yào cā zhuōzi, érqiě bù néng liúxià wèishēng sǐjiǎo.","vi":"Khi dọn vệ sinh không những phải lau bàn mà còn không được bỏ sót góc khuất nào."}],"related":[{"hanzi":"盲区","pinyin":"mángqū","vi":"vùng mù"},{"hanzi":"角落","pinyin":"jiǎoluò","vi":"góc"},{"hanzi":"卫生死角","pinyin":"wèishēngsǐjiǎo","vi":"góc khuất vệ sinh"},{"hanzi":"漏洞","pinyin":"lòudòng","vi":"lỗ hổng"}]},{"id":"死心","hanzi":"死心","pinyin":"sǐxīn","meaning_vi":"từ bỏ hy vọng, hết hy vọng","explanation":"死 (tử vong/kiên quyết) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"你就死心吧。","pinyin":"Nǐ jiù sǐxīn ba.","vi":"Bạn từ bỏ hy vọng đi."},{"type":"simple","zh":"被拒绝了三次以后他终于对她死心了。","pinyin":"Bèi jùjuéle sāncì yǐhòu tā zhōngyú duì tā sǐxīn le.","vi":"Sau ba lần bị từ chối, anh ấy cuối cùng đã hết hy vọng với cô ấy."},{"type":"compound","zh":"即使医生说希望渺茫，母亲也始终没有死心。","pinyin":"Jíshǐ yīshēng shuō xīwàng miǎománg, mǔqīn yě shǐzhōng méiyǒu sǐxīn.","vi":"Dù bác sĩ nói hy vọng mong manh, người mẹ vẫn chưa bao giờ từ bỏ hy vọng."}],"related":[{"hanzi":"绝望","pinyin":"juéwàng","vi":"tuyệt vọng"},{"hanzi":"放弃","pinyin":"fàngqì","vi":"từ bỏ"},{"hanzi":"死心塌地","pinyin":"sǐxīntādì","vi":"một lòng một dạ"},{"hanzi":"不死心","pinyin":"bùsǐxīn","vi":"chưa chịu bỏ"}]},{"id":"损耗","hanzi":"损耗","pinyin":"sǔnhào","meaning_vi":"hao hụt, tổn hao","explanation":"损 (tổn thất) + 耗 (hao tổn/tiêu tốn).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"运输中有些损耗。","pinyin":"Yùnshū zhōng yǒuxiē sǔnhào.","vi":"Trong quá trình vận chuyển có chút hao hụt."},{"type":"simple","zh":"新鲜水果在长途运输中的损耗率很高。","pinyin":"Xīnxiān shuǐguǒ zài chángtú yùnshū zhōng de sǔnhào lǜ hěn gāo.","vi":"Tỷ lệ hao hụt của trái cây tươi khi vận chuyển đường dài rất cao."},{"type":"compound","zh":"如果电线太细，电能在传输中就会损耗得更多。","pinyin":"Rúguǒ diànxiàn tài xì, diànnéng zài chuánshū zhōng jiù huì sǔnhào de gèng duō.","vi":"Nếu dây điện quá nhỏ, điện năng sẽ hao tổn nhiều hơn trong quá trình truyền tải."}],"related":[{"hanzi":"消耗","pinyin":"xiāohào","vi":"tiêu hao"},{"hanzi":"损失","pinyin":"sǔnshī","vi":"tổn thất"},{"hanzi":"耗损","pinyin":"hàosǔn","vi":"hao tổn"},{"hanzi":"能耗","pinyin":"nénghào","vi":"năng lượng tiêu hao"}],"traditional":"損耗"},{"id":"损伤","hanzi":"损伤","pinyin":"sǔnshāng","meaning_vi":"tổn thương, hư hại","explanation":"损 (tổn thất) + 伤 (tổn thương).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🩹","examples":[{"type":"basic","zh":"他的韧带损伤了。","pinyin":"Tā de rèndài sǔnshāng le.","vi":"Dây chằng của anh ấy bị tổn thương."},{"type":"simple","zh":"长时间戴耳机会损伤听力。","pinyin":"Cháng shíjiān dài ěr jīhuì sǔnshāng tīnglì.","vi":"Đeo tai nghe lâu sẽ làm tổn thương thính lực."},{"type":"compound","zh":"批评孩子时要注意方式，否则会损伤他的自尊心。","pinyin":"Pīpíng háizi shí yào zhùyì fāngshì, fǒuzé huì sǔnshāng tā de zìzūnxīn.","vi":"Khi phê bình trẻ phải chú ý cách thức, nếu không sẽ làm tổn thương lòng tự trọng của trẻ."}],"related":[{"hanzi":"损害","pinyin":"sǔnhài","vi":"tổn hại"},{"hanzi":"受伤","pinyin":"shòushāng","vi":"bị thương"},{"hanzi":"伤害","pinyin":"shānghài","vi":"tổn thương"},{"hanzi":"损坏","pinyin":"sǔnhuài","vi":"hư hỏng"}],"traditional":"損傷"},{"id":"跳槽","hanzi":"跳槽","pinyin":"tiàocáo","meaning_vi":"nhảy việc, chuyển sang công ty khác","explanation":"跳 (nhảy) + 槽 (máng ăn). Động từ ly hợp khẩu ngữ.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"他又跳槽了。","pinyin":"Tā yòu tiàocáo le.","vi":"Anh ấy lại nhảy việc rồi."},{"type":"simple","zh":"她从一家银行跳槽到了互联网公司。","pinyin":"Tā cóng yìjiā yínháng tiàocáo dàole Hùliánwǎng gōngsī.","vi":"Cô ấy nhảy việc từ một ngân hàng sang công ty internet."},{"type":"compound","zh":"如果频繁跳槽，就很难在一个行业积累经验。","pinyin":"Rúguǒ pínfán tiàocáo, jiù hěn nán zài yí gè hángyè jīlěi jīngyàn.","vi":"Nếu nhảy việc thường xuyên thì rất khó tích lũy kinh nghiệm trong một ngành."}],"related":[{"hanzi":"换工作","pinyin":"huàngōngzuò","vi":"đổi việc"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"},{"hanzi":"离职","pinyin":"lízhí","vi":"nghỉ việc"},{"hanzi":"猎头","pinyin":"liètóu","vi":"săn đầu người"}]},{"id":"田地","hanzi":"田地","pinyin":"tiándì","meaning_vi":"ruộng đất, đồng ruộng; tình cảnh, nông nỗi (thường là xấu)","explanation":"田 (đồng ruộng) + 地 (地).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"🌾","examples":[{"type":"basic","zh":"农民在田地里干活。","pinyin":"Nóngmín zài tiándì li gànhuó.","vi":"Nông dân làm việc ngoài đồng ruộng."},{"type":"simple","zh":"他怎么会落到今天这个田地？","pinyin":"Tā zěnme huì luò dào jīntiān zhè ge tiándì?","vi":"Sao anh ta lại rơi vào tình cảnh như hôm nay?"},{"type":"compound","zh":"因为连日暴雨，所以村里的田地全被淹了。","pinyin":"Yīnwèi liánrì bàoyǔ, suǒyǐ cūnli de tiándì quán bèi yān le.","vi":"Vì mưa lớn nhiều ngày liền nên ruộng đất trong làng đều bị ngập."}],"related":[{"hanzi":"田野","pinyin":"tiányě","vi":"đồng ruộng"},{"hanzi":"农田","pinyin":"nóngtián","vi":"ruộng canh tác"},{"hanzi":"地步","pinyin":"dìbù","vi":"tình cảnh, mức độ"},{"hanzi":"土地","pinyin":"tǔdì","vi":"đất đai"}]},{"id":"甜蜜","hanzi":"甜蜜","pinyin":"tiánmì","meaning_vi":"ngọt ngào (tình yêu/cuộc sống)","explanation":"甜 (ngọt) + 蜜 (mật ngọt).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💑","examples":[{"type":"basic","zh":"他们笑得很甜蜜。","pinyin":"Tāmen xiào de hěn tiánmì.","vi":"Họ cười rất ngọt ngào."},{"type":"simple","zh":"这对新婚夫妇在海边度过了甜蜜的蜜月。","pinyin":"Zhè duì xīnhūn fūfù zài hǎibiān dùguòle tiánmì de mìyuè.","vi":"Đôi vợ chồng mới cưới này đã trải qua tuần trăng mật ngọt ngào bên bờ biển."},{"type":"compound","zh":"虽然日子过得清贫，但是他们的生活很甜蜜。","pinyin":"Suīrán rìzi guòde qīngpín, dànshì tāmen de shēnghuó hěn tiánmì.","vi":"Tuy cuộc sống thanh bần nhưng họ sống rất ngọt ngào."}],"related":[{"hanzi":"甜美","pinyin":"tiánměi","vi":"ngọt ngào"},{"hanzi":"幸福","pinyin":"xìngfú","vi":"hạnh phúc"},{"hanzi":"甜言蜜语","pinyin":"tiányánmìyǔ","vi":"lời đường mật"},{"hanzi":"苦涩","pinyin":"kǔsè","vi":"đắng chát"}]},{"id":"甜美","hanzi":"甜美","pinyin":"tiánměi","meaning_vi":"ngọt ngào êm ái (giọng hát/giấc ngủ/nụ cười)","explanation":"甜 (ngọt) + 美 (tươi đẹp/mỹ mãn).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🍯","examples":[{"type":"basic","zh":"她的嗓音很甜美。","pinyin":"Tā de sǎngyīn hěn tiánměi.","vi":"Giọng cô ấy rất ngọt ngào."},{"type":"simple","zh":"宝宝在妈妈怀里进入了甜美的梦乡。","pinyin":"Bǎobao zài māma huáili jìnrùle tiánměi de mèngxiāng.","vi":"Em bé chìm vào giấc mơ êm đềm trong lòng mẹ."},{"type":"compound","zh":"前台小姐不但笑容甜美，而且服务非常耐心。","pinyin":"Qiántái xiǎojiě búdàn xiàoróng tiánměi, érqiě fúwù fēicháng nàixīn.","vi":"Cô lễ tân không những có nụ cười ngọt ngào mà còn phục vụ rất kiên nhẫn."}],"related":[{"hanzi":"甜蜜","pinyin":"tiánmì","vi":"ngọt ngào"},{"hanzi":"甜甜","pinyin":"tiántián","vi":"ngọt ngào"},{"hanzi":"动听","pinyin":"dòngtīng","vi":"dễ nghe"},{"hanzi":"悦耳","pinyin":"yuè'ěr","vi":"êm tai"}]},{"id":"甜头","hanzi":"甜头","pinyin":"tiántou","meaning_vi":"món hời, lợi ích ban đầu","explanation":"甜 (ngọt) + 头 (đứng đầu/mạch lạc).","hsk_level":"7-9","tags":["danh-tu"],"image":"🍬","examples":[{"type":"basic","zh":"他尝到了甜头。","pinyin":"Tā cháng dàole tiántou.","vi":"Anh ấy đã nếm được vị ngọt của lợi ích."},{"type":"simple","zh":"果农们尝到了电商直播卖货的甜头。","pinyin":"Guǒnóngmen cháng dàole diànshāng zhíbō mài huò de tiántou.","vi":"Nông dân trồng cây ăn quả đã nếm được lợi ích của việc livestream bán hàng."},{"type":"compound","zh":"骗子先给你一点甜头，然后再骗走你更多的钱。","pinyin":"Piànzi xiān gěi nǐ yìdiǎn tiántou, ránhòu zài piàn zǒunǐ gèng duō de qián.","vi":"Kẻ lừa đảo trước cho bạn chút lợi nhỏ, sau đó lừa lấy nhiều tiền hơn."}],"related":[{"hanzi":"好处","pinyin":"hǎochù","vi":"lợi ích"},{"hanzi":"尝到甜头","pinyin":"chángdàotiántou","vi":"nếm được vị ngọt"},{"hanzi":"利益","pinyin":"lìyì","vi":"lợi ích"},{"hanzi":"苦头","pinyin":"kǔtou","vi":"nỗi khổ"}],"traditional":"甜頭"},{"id":"调控","hanzi":"调控","pinyin":"tiáokòng","meaning_vi":"điều tiết và kiểm soát","explanation":"调 (điều chỉnh/hòa giải) + 控 (khống chế/kiểm soát).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🎛️","examples":[{"type":"basic","zh":"政府调控房价。","pinyin":"Zhèngfǔ tiáokòng fángjià.","vi":"Chính phủ điều tiết giá nhà."},{"type":"simple","zh":"智能空调能根据室温自动调控风速。","pinyin":"Zhìnéng kōngtiáo néng gēnjù shìwēn zìdòng tiáokòng fēngsù.","vi":"Điều hòa thông minh có thể tự động điều chỉnh tốc độ gió theo nhiệt độ phòng."},{"type":"compound","zh":"如果市场调控不当，物价就可能大起大落。","pinyin":"Rúguǒ shìchǎng tiáokòng búdàng, wùjià jiù kěnéng dà qǐ dà luò.","vi":"Nếu điều tiết thị trường không thỏa đáng, giá cả có thể lên xuống thất thường."}],"related":[{"hanzi":"宏观调控","pinyin":"hóngguāntiáokòng","vi":"điều tiết vĩ mô"},{"hanzi":"调节","pinyin":"tiáojié","vi":"điều tiết"},{"hanzi":"控制","pinyin":"kòngzhì","vi":"kiểm soát"},{"hanzi":"监管","pinyin":"jiānguǎn","vi":"giám sát quản lý"}],"traditional":"調控"},{"id":"调侃","hanzi":"调侃","pinyin":"tiáokǎn","meaning_vi":"trêu đùa hài hước","explanation":"调 (điều chỉnh/hòa giải) + 侃 (nói chuyện tự tin).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😄","examples":[{"type":"basic","zh":"他爱调侃朋友。","pinyin":"Tā ài tiáokǎn péngyou.","vi":"Anh ấy thích trêu chọc bạn bè."},{"type":"simple","zh":"主持人用一句话调侃了自己的发型。","pinyin":"Zhǔchírén yòng yíjùhuà tiáokǎnle zìjǐ de fàxíng.","vi":"Người dẫn chương trình dùng một câu để tự trêu về kiểu tóc của mình."},{"type":"compound","zh":"虽然大家都在调侃他，但是他一点也不生气。","pinyin":"Suīrán dàjiā dōu zài tiáokǎn tā, dànshì tā yìdiǎn yě bù shēngqì.","vi":"Tuy mọi người đều trêu chọc anh ấy nhưng anh ấy chẳng hề giận."}],"related":[{"hanzi":"开玩笑","pinyin":"kāiwánxiào","vi":"đùa giỡn"},{"hanzi":"嘲讽","pinyin":"cháofěng","vi":"chế giễu"},{"hanzi":"幽默","pinyin":"yōumò","vi":"hài hước"},{"hanzi":"自嘲","pinyin":"zìcháo","vi":"tự giễu"}],"traditional":"調侃"},{"id":"调理","hanzi":"调理","pinyin":"tiáolǐ","meaning_vi":"điều dưỡng, chăm sóc bồi bổ (sức khỏe)","explanation":"调 (điều chỉnh/hòa giải) + 理 (lý luận/quản lý).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🌿","examples":[{"type":"basic","zh":"她在调理身体。","pinyin":"Tā zài tiáolǐ shēntǐ.","vi":"Cô ấy đang điều dưỡng cơ thể."},{"type":"simple","zh":"中医建议她喝三个月中药调理肠胃。","pinyin":"Zhōngyī jiànyì tā hē sān gèyuè zhōngyào tiáolǐ chángwèi.","vi":"Thầy thuốc Đông y khuyên cô ấy uống thuốc bắc ba tháng để điều dưỡng dạ dày."},{"type":"compound","zh":"只要坚持调理饮食和作息，你的皮肤就会好起来。","pinyin":"Zhǐyào jiānchí tiáolǐ yǐnshí hé zuòxī, nǐ de pífū jiù huì hǎoqǐlái.","vi":"Chỉ cần kiên trì điều chỉnh ăn uống và giờ giấc, da bạn sẽ tốt lên."}],"related":[{"hanzi":"调养","pinyin":"tiáoyǎng","vi":"điều dưỡng"},{"hanzi":"保养","pinyin":"bǎoyǎng","vi":"chăm sóc bảo dưỡng"},{"hanzi":"养生","pinyin":"yǎngshēng","vi":"dưỡng sinh"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"}],"traditional":"調理"},{"id":"调配","hanzi":"调配","pinyin":"tiáopèi","meaning_vi":"pha chế, pha trộn","explanation":"调 (điều chỉnh/hòa giải) + 配 (phối hợp/trang bị).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"他在调配鸡尾酒。","pinyin":"Tā zài tiáopèi jīwěijiǔ.","vi":"Anh ấy đang pha chế cocktail."},{"type":"simple","zh":"画家耐心地调配出了天空的那种淡蓝色。","pinyin":"Huàjiā nài xīnde tiáopèi chūle tiānkōng de nà zhǒng dànlánsè.","vi":"Họa sĩ kiên nhẫn pha ra được màu xanh nhạt của bầu trời."},{"type":"compound","zh":"如果饲料调配得不合理，鸡就容易生病。","pinyin":"Rúguǒ sìliào tiáopèi de bù hélǐ, jī jiù róngyì shēngbìng.","vi":"Nếu thức ăn chăn nuôi pha trộn không hợp lý, gà sẽ dễ bị bệnh."}],"related":[{"hanzi":"搭配","pinyin":"dāpèi","vi":"phối hợp"},{"hanzi":"调制","pinyin":"tiáozhì","vi":"pha chế"},{"hanzi":"配制","pinyin":"pèizhì","vi":"pha chế"},{"hanzi":"调剂","pinyin":"tiáojì","vi":"điều chỉnh"}],"traditional":"調配"},{"id":"调试","hanzi":"调试","pinyin":"tiáoshì","meaning_vi":"chạy thử và hiệu chỉnh (máy móc/phần mềm)","explanation":"调 (điều chỉnh/hòa giải) + 试 (thử).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔧","examples":[{"type":"basic","zh":"工程师在调试设备。","pinyin":"Gōngchéngshī zài tiáoshì shèbèi.","vi":"Kỹ sư đang chạy thử và hiệu chỉnh thiết bị."},{"type":"simple","zh":"演出前音响师反复调试了每一个麦克风。","pinyin":"Yǎnchū qián yīnxiǎng shī fǎnfù tiáoshìle měi yí gè màikèfēng.","vi":"Trước buổi diễn, kỹ thuật viên âm thanh hiệu chỉnh đi hiệu chỉnh lại từng chiếc micro."},{"type":"compound","zh":"新程序调试完以后，我们才能正式上线。","pinyin":"Xīn chéngxù tiáoshì wán yǐhòu, wǒmen cáinéng zhèngshì shàngxiàn.","vi":"Chương trình mới chạy thử xong chúng ta mới có thể chính thức đưa vào hoạt động."}],"related":[{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"测试","pinyin":"cèshì","vi":"kiểm thử"},{"hanzi":"安装","pinyin":"ānzhuāng","vi":"lắp đặt"},{"hanzi":"故障","pinyin":"gùzhàng","vi":"sự cố"}],"traditional":"調試"},{"id":"调养","hanzi":"调养","pinyin":"tiáoyǎng","meaning_vi":"dưỡng bệnh, nghỉ ngơi bồi bổ","explanation":"调 (điều chỉnh/hòa giải) + 养 (nuôi dưỡng/tu dưỡng).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"🏥","examples":[{"type":"basic","zh":"病后要好好调养。","pinyin":"Bìng hòu yào hǎohǎo tiáoyǎng.","vi":"Sau khi ốm phải tĩnh dưỡng cho tốt."},{"type":"simple","zh":"手术后他回到乡下老家调养了半年。","pinyin":"Shǒushù hòu tā huídào xiāngxià lǎojiā tiáoyǎngle bàn nián.","vi":"Sau phẫu thuật, anh ấy về quê dưỡng bệnh nửa năm."},{"type":"compound","zh":"产妇如果月子里调养得好，身体就恢复得快。","pinyin":"Chǎnfù rúguǒ yuèzi li tiáoyǎng de hǎo, shēntǐ jiù huīfù de kuài.","vi":"Sản phụ nếu tĩnh dưỡng tốt trong tháng ở cữ thì cơ thể sẽ hồi phục nhanh."}],"related":[{"hanzi":"休养","pinyin":"xiūyǎng","vi":"nghỉ dưỡng"},{"hanzi":"疗养","pinyin":"liáoyǎng","vi":"điều dưỡng"},{"hanzi":"调理","pinyin":"tiáolǐ","vi":"bồi bổ"},{"hanzi":"康复","pinyin":"kāngfù","vi":"hồi phục"}],"traditional":"調養"},{"id":"天赋","hanzi":"天赋","pinyin":"tiānfù","meaning_vi":"thiên phú, tài năng bẩm sinh","explanation":"天 (ngày) + 赋 (trao cho/thiên phú).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🧠","examples":[{"type":"basic","zh":"她很有音乐天赋。","pinyin":"Tā hěn yǒu yīnyuè tiānfù.","vi":"Cô ấy rất có thiên phú âm nhạc."},{"type":"simple","zh":"这个孩子在数学方面表现出惊人的天赋。","pinyin":"Zhè ge háizi zài shùxué fāngmiàn biǎoxiàn chū jīngrén de tiānfù.","vi":"Đứa trẻ này thể hiện năng khiếu đáng kinh ngạc về toán học."},{"type":"compound","zh":"即使有天赋，不努力的人也很难取得成功。","pinyin":"Jíshǐ yǒu tiānfù, bù nǔlì de rén yě hěn nán qǔdé chénggōng.","vi":"Dù có thiên phú, người không nỗ lực cũng khó thành công."}],"related":[{"hanzi":"天分","pinyin":"tiānfèn","vi":"thiên bẩm"},{"hanzi":"天才","pinyin":"tiāncái","vi":"thiên tài"},{"hanzi":"才华","pinyin":"cáihuá","vi":"tài hoa"},{"hanzi":"天资","pinyin":"tiānzī","vi":"tư chất trời cho"}],"traditional":"天賦"},{"id":"天分","hanzi":"天分","pinyin":"tiānfèn","meaning_vi":"thiên bẩm, năng khiếu trời phú","explanation":"天 (ngày) + 分 (phút).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"他画画很有天分。","pinyin":"Tā huàhuà hěn yǒu tiānfèn.","vi":"Anh ấy vẽ rất có năng khiếu."},{"type":"simple","zh":"教练一眼就看出了这个女孩的游泳天分。","pinyin":"Jiàoliàn yìyǎn jiù kànchūle zhè ge nǚhái de yóuyǒng tiānfèn.","vi":"Huấn luyện viên liếc mắt đã nhận ra năng khiếu bơi lội của cô bé này."},{"type":"compound","zh":"虽然他天分一般，但是凭着勤奋考上了音乐学院。","pinyin":"Suīrán tā tiānfèn yìbān, dànshì píngzhe qínfèn kǎoshàngle yīnyuè xuéyuàn.","vi":"Tuy năng khiếu bình thường nhưng nhờ chăm chỉ anh ấy đã đỗ học viện âm nhạc."}],"related":[{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"天资","pinyin":"tiānzī","vi":"tư chất trời cho"},{"hanzi":"悟性","pinyin":"wùxìng","vi":"khả năng lĩnh hội"},{"hanzi":"才能","pinyin":"cáinéng","vi":"tài năng"}]},{"id":"天然","hanzi":"天然","pinyin":"tiānrán","meaning_vi":"tự nhiên, vốn có (天然气 - khí thiên nhiên)","explanation":"天 (thiên – trời) + 然 (nhiên – như thế) → vốn có trong tự nhiên, không do con người tạo ra. Ví dụ: 天然气 (khí thiên nhiên), 天然资源.","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌿","examples":[{"type":"basic","zh":"这是天然矿泉水。","pinyin":"Zhè shì tiānrán kuàngquánshuǐ.","vi":"Đây là nước khoáng thiên nhiên."},{"type":"simple","zh":"这款面霜只使用天然植物成分。","pinyin":"Zhè kuǎn miànshuāng zhǐ shǐyòng tiānrán zhíwù chéngfèn.","vi":"Kem dưỡng da này chỉ dùng thành phần thực vật tự nhiên."},{"type":"compound","zh":"这座岛屿不但风景优美，而且是候鸟的天然栖息地。","pinyin":"Zhè zuò dǎoyǔ búdàn fēngjǐng yōuměi, érqiě shì hòuniǎo de tiānrán qīxīdì.","vi":"Hòn đảo này không chỉ phong cảnh đẹp mà còn là nơi cư trú tự nhiên của chim di cư."}],"related":[{"hanzi":"天然气","pinyin":"tiānránqì","vi":"khí thiên nhiên"},{"hanzi":"自然","pinyin":"zìrán","vi":"tự nhiên"},{"hanzi":"人工","pinyin":"réngōng","vi":"nhân tạo"},{"hanzi":"纯天然","pinyin":"chúntiānrán","vi":"hoàn toàn tự nhiên"}]},{"id":"天色","hanzi":"天色","pinyin":"tiānsè","meaning_vi":"sắc trời; giờ giấc trong ngày (trời sớm hay muộn)","explanation":"天 (ngày) + 色 (màu sắc/thần sắc).","hsk_level":"7-9","tags":["danh-tu","thoi-tiet","thoi-gian"],"image":"🌤️","examples":[{"type":"basic","zh":"天色渐渐暗了。","pinyin":"Tiānsè jiànjiàn àn le.","vi":"Trời dần tối."},{"type":"simple","zh":"看着阴沉的天色他决定带上雨伞出门。","pinyin":"Kànzhe yīnchén de tiānsè tā juédìng dàishàng yǔsǎn chūmén.","vi":"Nhìn sắc trời u ám, anh ấy quyết định mang ô ra ngoài."},{"type":"compound","zh":"天色已晚，如果再不下山，我们就会迷路。","pinyin":"Tiānsè yǐ wǎn, rúguǒ zài bú xiàshān, wǒmen jiù huì mílù.","vi":"Trời đã tối, nếu không xuống núi ngay thì chúng ta sẽ lạc đường."}],"related":[{"hanzi":"天空","pinyin":"tiānkōng","vi":"bầu trời"},{"hanzi":"天黑","pinyin":"tiānhēi","vi":"trời tối"},{"hanzi":"天亮","pinyin":"tiānliàng","vi":"trời sáng"},{"hanzi":"傍晚","pinyin":"bàngwǎn","vi":"chạng vạng"}]},{"id":"天坛","hanzi":"天坛","pinyin":"Tiāntán","meaning_vi":"Đàn Tế Trời (Thiên Đàn ở Bắc Kinh)","explanation":"天 (thiên – trời) + 坛 (đàn – đàn tế) → Thiên Đàn ở Bắc Kinh, nơi vua Minh, Thanh tế trời cầu mùa màng; di sản thế giới UNESCO.","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏛️","examples":[{"type":"basic","zh":"我们明天去天坛。","pinyin":"Wǒmen míngtiān qù Tiāntán.","vi":"Ngày mai chúng tôi đi Thiên Đàn."},{"type":"simple","zh":"清晨的天坛公园里有很多老人在打太极拳。","pinyin":"Qīngchén de Tiāntán gōngyuán lǐ yǒu hěn duō lǎorén zài dǎ tàijíquán.","vi":"Sáng sớm trong công viên Thiên Đàn có rất nhiều cụ già đang tập thái cực quyền."},{"type":"compound","zh":"虽然天坛离酒店有点远，但是我们还是决定坐地铁去看看。","pinyin":"Suīrán Tiāntán lí jiǔdiàn yǒudiǎn yuǎn, dànshì wǒmen háishì juédìng zuò dìtiě qù kànkan.","vi":"Tuy Thiên Đàn hơi xa khách sạn, nhưng chúng tôi vẫn quyết định đi tàu điện ngầm đến xem."}],"related":[{"hanzi":"故宫","pinyin":"gùgōng","vi":"Cố Cung"},{"hanzi":"颐和园","pinyin":"Yíhéyuán","vi":"Di Hòa Viên"},{"hanzi":"祭天","pinyin":"jìtiān","vi":"tế trời"},{"hanzi":"北京","pinyin":"Běijīng","vi":"Bắc Kinh"}],"traditional":"天壇"},{"id":"天体","hanzi":"天体","pinyin":"tiāntǐ","meaning_vi":"thiên thể","explanation":"天 (ngày) + 体 (thể hiện/hệ thống).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","thien-nhien"],"image":"🪐","examples":[{"type":"basic","zh":"月亮是离地球最近的天体。","pinyin":"Yuèliang shì lí dìqiú zuìjìn de tiāntǐ.","vi":"Mặt Trăng là thiên thể gần Trái Đất nhất."},{"type":"simple","zh":"天文台用望远镜观测遥远的天体。","pinyin":"Tiānwéntái yòng wàngyuǎnjìng guāncè yáoyuǎn de tiāntǐ.","vi":"Đài thiên văn dùng kính viễn vọng quan sát những thiên thể xa xôi."},{"type":"compound","zh":"只要天气晴朗，我们就能用肉眼看到不少明亮的天体。","pinyin":"Zhǐyào tiānqì qínglǎng, wǒmen jiù néng yòng ròuyǎn kàndào bùshǎo míngliàng de tiāntǐ.","vi":"Chỉ cần trời quang đãng, chúng ta có thể nhìn thấy khá nhiều thiên thể sáng bằng mắt thường."}],"related":[{"hanzi":"天文","pinyin":"tiānwén","vi":"thiên văn"},{"hanzi":"星球","pinyin":"xīngqiú","vi":"tinh cầu"},{"hanzi":"行星","pinyin":"xíngxīng","vi":"hành tinh"},{"hanzi":"恒星","pinyin":"héngxīng","vi":"hằng tinh"}],"traditional":"天體"},{"id":"天性","hanzi":"天性","pinyin":"tiānxìng","meaning_vi":"bản tính tự nhiên","explanation":"天 (ngày) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","dong-vat"],"image":"🐾","examples":[{"type":"basic","zh":"好奇是孩子的天性。","pinyin":"Hàoqí shì háizi de tiānxìng.","vi":"Tò mò là bản tính tự nhiên của trẻ con."},{"type":"simple","zh":"猫天性喜欢在高处观察周围的动静。","pinyin":"Māo tiānxìng xǐhuan zài gāochù guānchá zhōuwéi de dòngjing.","vi":"Mèo vốn tính thích ở chỗ cao quan sát động tĩnh xung quanh."},{"type":"compound","zh":"他天性乐观，所以即使失业了也没有整天唉声叹气。","pinyin":"Tā tiānxìng lèguān, suǒyǐ jíshǐ shīyèle yě méiyǒu zhěngtiān āi shēng tànqì.","vi":"Anh ấy bản tính lạc quan, nên dù mất việc cũng không suốt ngày than ngắn thở dài."}],"related":[{"hanzi":"本性","pinyin":"běnxìng","vi":"bản tính"},{"hanzi":"生性","pinyin":"shēngxìng","vi":"bản tính trời sinh"},{"hanzi":"天赋","pinyin":"tiānfù","vi":"thiên phú"},{"hanzi":"个性","pinyin":"gèxìng","vi":"cá tính"}]},{"id":"添置","hanzi":"添置","pinyin":"tiānzhì","meaning_vi":"mua sắm thêm (đồ đạc)","explanation":"添 (thêm vào) + 置 (bố trí/đặt để).","hsk_level":"7-9","tags":["dong-tu","mua-sam"],"image":"🛒","examples":[{"type":"basic","zh":"家里添置了一台洗碗机。","pinyin":"Jiālǐ tiānzhìle yì tái xǐwǎnjī.","vi":"Nhà tôi mới sắm thêm một chiếc máy rửa bát."},{"type":"simple","zh":"年底公司给每间办公室添置了新的空气净化器。","pinyin":"Niándǐ gōngsī gěi měi jiān bàngōngshì tiānzhìle xīn de kōngqì jìnghuàqì.","vi":"Cuối năm công ty sắm thêm máy lọc không khí mới cho mỗi phòng làm việc."},{"type":"compound","zh":"因为孩子快出生了，所以小两口忙着添置婴儿床和推车。","pinyin":"Yīnwèi háizi kuài chūshēng le, suǒyǐ xiǎoliǎngkǒu mángzhe tiānzhì yīng'érchuáng hé tuīchē.","vi":"Vì em bé sắp chào đời nên đôi vợ chồng trẻ tất bật sắm thêm nôi và xe đẩy."}],"related":[{"hanzi":"购置","pinyin":"gòuzhì","vi":"mua sắm"},{"hanzi":"添加","pinyin":"tiānjiā","vi":"thêm vào"},{"hanzi":"置办","pinyin":"zhìbàn","vi":"sắm sửa"},{"hanzi":"家具","pinyin":"jiājù","vi":"đồ gia dụng"}]},{"id":"天真无邪","hanzi":"天真无邪","pinyin":"tiānzhēn-wúxié","meaning_vi":"ngây thơ trong sáng vô tư","explanation":"天 (ngày) + 真 (thật) + 无 (vô tận/không có) + 邪 (邪).","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"😇","examples":[{"type":"basic","zh":"她的笑容天真无邪。","pinyin":"Tā de xiàoróng tiānzhēnwúxié.","vi":"Nụ cười của cô bé ngây thơ trong sáng."},{"type":"simple","zh":"照片里的小女孩睁着一双天真无邪的大眼睛。","pinyin":"Zhàopiàn lǐ de xiǎo nǚhái zhēngzhe yì shuāng tiānzhēnwúxié de dà yǎnjing.","vi":"Cô bé trong ảnh mở to đôi mắt ngây thơ trong sáng."},{"type":"compound","zh":"孩子们天真无邪地提出问题，大人们却不知道该怎么回答。","pinyin":"Háizimen tiānzhēnwúxié de tíchū wèntí, dà rénmen què bù zhīdào gāi zěnme huídá.","vi":"Lũ trẻ hồn nhiên vô tư đặt câu hỏi, còn người lớn lại không biết nên trả lời thế nào."}],"related":[{"hanzi":"天真烂漫","pinyin":"tiānzhēnlànmàn","vi":"ngây thơ hồn nhiên"},{"hanzi":"纯真","pinyin":"chúnzhēn","vi":"trong sáng"},{"hanzi":"单纯","pinyin":"dānchún","vi":"đơn thuần"},{"hanzi":"老谋深算","pinyin":"lǎomóushēnsuàn","vi":"mưu sâu kế hiểm"}],"traditional":"天真無邪"},{"id":"贴切","hanzi":"贴切","pinyin":"tiēqiè","meaning_vi":"sát nghĩa, dùng từ chuẩn xác","explanation":"贴 (chu đáo/dán) + 切 (cắt).","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"🎯","examples":[{"type":"basic","zh":"这个比喻很贴切。","pinyin":"Zhè ge bǐyù hěn tiēqiè.","vi":"Phép so sánh này rất sát."},{"type":"simple","zh":"老师认为这篇译文的用词相当贴切。","pinyin":"Lǎoshī rènwéi zhè piān yìwén de yòngcí xiāngdāng tiēqiè.","vi":"Thầy giáo cho rằng cách dùng từ trong bản dịch này khá chuẩn xác."},{"type":"compound","zh":"如果找不到贴切的词语，就宁可用简单的话说清楚。","pinyin":"Rúguǒ zhǎobúdào tiēqiè de cíyǔ, jiù nìngkě yòng jiǎndān de huàshuō qīngchu.","vi":"Nếu không tìm được từ ngữ thật chuẩn xác thì thà dùng lời đơn giản mà nói cho rõ."}],"related":[{"hanzi":"恰当","pinyin":"qiàdàng","vi":"thỏa đáng"},{"hanzi":"确切","pinyin":"quèqiè","vi":"xác đáng"},{"hanzi":"准确","pinyin":"zhǔnquè","vi":"chính xác"},{"hanzi":"生硬","pinyin":"shēngyìng","vi":"gượng gạo"}],"traditional":"貼切"},{"id":"贴身","hanzi":"贴身","pinyin":"tiēshēn","meaning_vi":"sát thân, cận vệ, mặc sát người","explanation":"贴 (chu đáo/dán) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["tinh-tu","trang-phuc"],"image":"👕","examples":[{"type":"basic","zh":"他有两名贴身保镖。","pinyin":"Tā yǒu liǎng míng tiēshēn bǎobiāo.","vi":"Ông ấy có hai vệ sĩ cận thân."},{"type":"simple","zh":"冬天她总喜欢穿一件贴身的羊毛衫。","pinyin":"Dōngtiān tā zǒng xǐhuan chuān yí jiàn tiēshēn de yángmáoshān.","vi":"Mùa đông cô ấy luôn thích mặc một chiếc áo len ôm sát người."},{"type":"compound","zh":"护照最好贴身放着，这样就不容易被小偷偷走。","pinyin":"Hùzhào zuìhǎo tiēshēn fàng zhe, zhèyàng jiù bù róngyì bèi xiǎo tōutōu zǒu.","vi":"Hộ chiếu tốt nhất nên để sát người, như vậy sẽ khó bị kẻ trộm lấy mất."}],"related":[{"hanzi":"贴身保镖","pinyin":"tiēshēnbǎobiāo","vi":"vệ sĩ riêng"},{"hanzi":"内衣","pinyin":"nèiyī","vi":"đồ lót"},{"hanzi":"随身","pinyin":"suíshēn","vi":"mang theo người"},{"hanzi":"紧身","pinyin":"jǐnshēn","vi":"bó sát"}],"traditional":"貼身"},{"id":"贴心","hanzi":"贴心","pinyin":"tiēxīn","meaning_vi":"tâm lý, chu đáo thấu hiểu lòng người","explanation":"贴 (chu đáo/dán) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"❤️","examples":[{"type":"basic","zh":"女儿真是妈妈的贴心小棉袄。","pinyin":"Nǚ'ér zhēn shì māma de tiēxīn xiǎomián'ǎo.","vi":"Con gái đúng là chiếc áo bông nhỏ ấm áp, hiểu lòng mẹ."},{"type":"simple","zh":"酒店在房间里贴心地准备了充电器和拖鞋。","pinyin":"Jiǔdiàn zài fángjiān lǐ tiēxīn de zhǔnbèile chōngdiànqì hé tuōxié.","vi":"Khách sạn chu đáo chuẩn bị sẵn sạc điện thoại và dép đi trong phòng."},{"type":"compound","zh":"他不但记得我的生日，而且贴心地订好了我最爱的餐厅。","pinyin":"Tā búdàn jìde wǒ de shēngrì, érqiě tiēxīn de dìng hǎole wǒ zuì ài de cāntīng.","vi":"Anh ấy không chỉ nhớ sinh nhật tôi mà còn chu đáo đặt sẵn nhà hàng tôi thích nhất."}],"related":[{"hanzi":"体贴","pinyin":"tǐtiē","vi":"chu đáo"},{"hanzi":"贴心人","pinyin":"tiēxīnrén","vi":"người tri kỷ"},{"hanzi":"暖心","pinyin":"nuǎnxīn","vi":"ấm lòng"},{"hanzi":"周到","pinyin":"zhōudào","vi":"chu đáo"}],"traditional":"貼心"},{"id":"铁饭碗","hanzi":"铁饭碗","pinyin":"tiěfànwǎn","meaning_vi":"bát cơm sắt (công việc biên chế ổn định suốt đời)","explanation":"铁 (sắt thép) + 饭 (饭) + 碗 (cái bát).","hsk_level":"7-9","tags":["danh-tu","cong-viec","van-hoa"],"image":"🍚","examples":[{"type":"basic","zh":"他辞掉了铁饭碗。","pinyin":"Tā cídiàole tiěfànwǎn.","vi":"Anh ấy đã bỏ cái bát cơm sắt của mình."},{"type":"simple","zh":"很多父母仍然希望孩子考公务员捧个铁饭碗。","pinyin":"Hěn duō fùmǔ réngrán xīwàng háizi kǎo gōngwùyuán pěng gè tiěfànwǎn.","vi":"Nhiều bố mẹ vẫn mong con thi công chức để có một bát cơm sắt."},{"type":"compound","zh":"虽然铁饭碗很稳定，但是他更想趁年轻出去闯一闯。","pinyin":"Suīrán tiěfànwǎn hěn wěndìng, dànshì tā gèng xiǎng chèn niánqīng chūqù chuǎng yi chuǎng.","vi":"Tuy bát cơm sắt rất ổn định, nhưng anh ấy muốn nhân lúc còn trẻ ra ngoài xông pha hơn."}],"related":[{"hanzi":"饭碗","pinyin":"fànwǎn","vi":"bát cơm, nghề"},{"hanzi":"公务员","pinyin":"gōngwùyuán","vi":"công chức"},{"hanzi":"编制","pinyin":"biānzhì","vi":"biên chế"},{"hanzi":"稳定","pinyin":"wěndìng","vi":"ổn định"}],"traditional":"鐵飯碗"},{"id":"铁面无私","hanzi":"铁面无私","pinyin":"tiěmiàn-wúsī","meaning_vi":"thiết diện vô tư, công minh nghiêm khắc không thiên vị","explanation":"铁 (sắt thép) + 面 (diện mạo/bề mặt) + 无 (vô tận/không có) + 私 (riêng tư).","hsk_level":"7-9","tags":["thanh-ngu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"这位法官铁面无私。","pinyin":"Zhè wèi fǎguān tiěmiànwúsī.","vi":"Vị thẩm phán này công minh nghiêm khắc, không thiên vị ai."},{"type":"simple","zh":"包公以铁面无私的形象流传了近千年。","pinyin":"Bāogōng yǐ tiěmiànwúsī de xíngxiàng liúchuánle jìn qiānnián.","vi":"Bao Công được lưu truyền gần nghìn năm với hình tượng thiết diện vô tư."},{"type":"compound","zh":"即使违规的是自己的亲戚，他也铁面无私地照章处罚。","pinyin":"Jíshǐ wéiguī de shì zìjǐ de qīnqi, tā yě tiěmiànwúsī de zhàozhāng chǔfá.","vi":"Dù người vi phạm là họ hàng của mình, ông ấy vẫn nghiêm minh xử phạt theo quy định."}],"related":[{"hanzi":"大公无私","pinyin":"dàgōngwúsī","vi":"chí công vô tư"},{"hanzi":"公正","pinyin":"gōngzhèng","vi":"công bằng"},{"hanzi":"严明","pinyin":"yánmíng","vi":"nghiêm minh"},{"hanzi":"徇私舞弊","pinyin":"xùnsīwǔbì","vi":"vì tư gian lận"}],"traditional":"鐵面無私"},{"id":"退场","hanzi":"退场","pinyin":"tuìchǎng","meaning_vi":"rời khỏi sân/hội trường","explanation":"退 (thoái hóa/rút lui) + 场 (địa điểm/trận đấu).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🚪","examples":[{"type":"basic","zh":"观众陆续退场了。","pinyin":"Guānzhòng lùxù tuìchǎng le.","vi":"Khán giả lần lượt rời khỏi hội trường."},{"type":"simple","zh":"那名球员因两张黄牌被裁判罚令退场。","pinyin":"Nà míng qiúyuán yīn liǎng zhāng huángpái bèi cáipàn fá lìng tuìchǎng.","vi":"Cầu thủ đó bị trọng tài truất quyền thi đấu vì hai thẻ vàng."},{"type":"compound","zh":"演出一结束，工作人员就引导观众从侧门有序退场。","pinyin":"Yǎnchū yì jiéshù, gōngzuò rényuán jiù yǐndǎo guānzhòng cóng cèmén yǒuxù tuìchǎng.","vi":"Buổi biểu diễn vừa kết thúc, nhân viên liền hướng dẫn khán giả ra về trật tự qua cửa bên."}],"related":[{"hanzi":"离场","pinyin":"líchǎng","vi":"rời sân"},{"hanzi":"入场","pinyin":"rùchǎng","vi":"vào sân"},{"hanzi":"出场","pinyin":"chūchǎng","vi":"ra sân"},{"hanzi":"散场","pinyin":"sànchǎng","vi":"tan buổi"}],"traditional":"退場"},{"id":"退路","hanzi":"退路","pinyin":"tuìlù","meaning_vi":"đường lui","explanation":"退 (thoái hóa/rút lui) + 路 (路).","hsk_level":"7-9","tags":["danh-tu"],"image":"↩️","examples":[{"type":"basic","zh":"他给自己留了退路。","pinyin":"Tā gěi zìjǐ liúle tuìlù.","vi":"Anh ấy đã chừa cho mình một đường lui."},{"type":"simple","zh":"敌军的退路已经被我方部队切断了。","pinyin":"Díjūn de tuìlù yǐjīng bèi wǒfāng bùduì qiēduàn le.","vi":"Đường rút lui của quân địch đã bị bộ đội ta cắt đứt."},{"type":"compound","zh":"既然已经辞职创业，我就没有退路，只能拼到底。","pinyin":"Jìrán yǐjīng cízhí chuàngyè, wǒ jiù méiyǒu tuìlù, zhǐnéng pīndàodǐ.","vi":"Đã nghỉ việc để khởi nghiệp rồi thì tôi không còn đường lui, chỉ có thể dốc sức đến cùng."}],"related":[{"hanzi":"后路","pinyin":"hòulù","vi":"đường lui"},{"hanzi":"出路","pinyin":"chūlù","vi":"lối thoát"},{"hanzi":"退步","pinyin":"tuìbù","vi":"thụt lùi"},{"hanzi":"背水一战","pinyin":"bèishuǐyízhàn","vi":"quyết chiến không đường lui"}]},{"id":"退却","hanzi":"退却","pinyin":"tuìquè","meaning_vi":"lùi bước, chùn bước","explanation":"退 (thoái hóa/rút lui) + 却 (lại).","hsk_level":"7-9","tags":["dong-tu"],"image":"⬅️","examples":[{"type":"basic","zh":"面对困难不能退却。","pinyin":"Miànduì kùnnan bù néng tuìquè.","vi":"Đối mặt với khó khăn thì không được chùn bước."},{"type":"simple","zh":"看到悬崖下的深谷，几个队员开始退却了。","pinyin":"Kàndào xuányá xià de shēngǔ, jǐ gè duìyuán kāishǐ tuìquè le.","vi":"Nhìn thấy hẻm sâu dưới vách đá, mấy thành viên trong đội bắt đầu chùn bước."},{"type":"compound","zh":"虽然对手实力强大，但是我们绝不会在比赛中退却。","pinyin":"Suīrán duìshǒu shílì qiángdà, dànshì wǒmen juébú huì zài bǐsài zhōng tuìquè.","vi":"Tuy đối thủ rất mạnh, nhưng chúng tôi tuyệt đối không lùi bước trong trận đấu."}],"related":[{"hanzi":"退缩","pinyin":"tuìsuō","vi":"rụt lùi"},{"hanzi":"后退","pinyin":"hòutuì","vi":"lùi lại"},{"hanzi":"前进","pinyin":"qiánjìn","vi":"tiến lên"},{"hanzi":"畏缩","pinyin":"wèisuō","vi":"co rúm sợ hãi"}],"traditional":"退卻"},{"id":"退让","hanzi":"退让","pinyin":"tuìràng","meaning_vi":"nhượng bộ, lùi bước","explanation":"退 (thoái hóa/rút lui) + 让 (bảo).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"双方都不肯退让。","pinyin":"Shuāngfāng dōu bùkěn tuìràng.","vi":"Cả hai bên đều không chịu nhượng bộ."},{"type":"simple","zh":"在价格问题上，供应商最终做出了一些退让。","pinyin":"Zài jiàgé wèntí shàng, gōngyìngshāng zuìzhōng zuòchūle yìxiē tuìràng.","vi":"Về vấn đề giá cả, nhà cung cấp cuối cùng đã nhượng bộ một chút."},{"type":"compound","zh":"如果你一味退让，对方就会得寸进尺。","pinyin":"Rúguǒ nǐ yíwèi tuìràng, duìfāng jiù huì décùnjìnchǐ.","vi":"Nếu bạn cứ nhượng bộ mãi, đối phương sẽ được đằng chân lân đằng đầu."}],"related":[{"hanzi":"让步","pinyin":"ràngbù","vi":"nhượng bộ"},{"hanzi":"妥协","pinyin":"tuǒxié","vi":"thỏa hiệp"},{"hanzi":"忍让","pinyin":"rěnràng","vi":"nhẫn nhịn"},{"hanzi":"坚持","pinyin":"jiānchí","vi":"kiên trì"}],"traditional":"退讓"},{"id":"退缩","hanzi":"退缩","pinyin":"tuìsuō","meaning_vi":"rụt rè lùi bước","explanation":"退 (thoái hóa/rút lui) + 缩 (thu nhỏ).","hsk_level":"7-9","tags":["dong-tu"],"image":"😨","examples":[{"type":"basic","zh":"遇到挑战他从不退缩。","pinyin":"Yùdào tiǎozhàn tā cóng bú tuìsuō.","vi":"Gặp thử thách anh ấy không bao giờ lùi bước."},{"type":"simple","zh":"第一次上台演讲时，她紧张得想往后退缩。","pinyin":"Dìyīcì shàngtái yǎnjiǎng shí, tā jǐnzhāng de xiǎng wǎng hòu tuìsuō.","vi":"Lần đầu lên bục diễn thuyết, cô ấy hồi hộp đến mức muốn rụt lùi lại."},{"type":"compound","zh":"一想到要独自面对面试官，他就有些退缩了。","pinyin":"Yì xiǎngdào yào dúzì miànduì miànshìguān, tā jiù yǒuxiē tuìsuō le.","vi":"Vừa nghĩ đến việc phải một mình đối diện người phỏng vấn, cậu ấy đã hơi chùn lại."}],"related":[{"hanzi":"畏缩","pinyin":"wèisuō","vi":"co rúm sợ hãi"},{"hanzi":"退却","pinyin":"tuìquè","vi":"lùi bước"},{"hanzi":"胆怯","pinyin":"dǎnqiè","vi":"nhút nhát"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"}],"traditional":"退縮"},{"id":"颓丧","hanzi":"颓丧","pinyin":"tuísàng","meaning_vi":"chán nản suy sụp","explanation":"颓 (suy sụp) + 丧 (mất đi/tang lễ).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"😞","examples":[{"type":"basic","zh":"他看起来很颓丧。","pinyin":"Tā kànqǐlái hěn tuísàng.","vi":"Trông anh ấy rất chán nản suy sụp."},{"type":"simple","zh":"落榜后的几天里，弟弟一直颓丧地躲在房间里。","pinyin":"Luòbǎng hòu de jǐtiān lǐ, dìdi yìzhí tuísàng de duǒ zài fángjiān lǐ.","vi":"Mấy ngày sau khi thi trượt, em trai cứ ủ rũ trốn trong phòng."},{"type":"compound","zh":"虽然项目失败了，但是大家没有颓丧，而是马上总结了教训。","pinyin":"Suīrán xiàngmù shībài le, dànshì dàjiā méiyǒu tuísàng, érshì mǎshàng zǒngjiéle jiàoxùn.","vi":"Tuy dự án thất bại, nhưng mọi người không suy sụp mà lập tức rút ra bài học."}],"related":[{"hanzi":"沮丧","pinyin":"jǔsàng","vi":"chán nản"},{"hanzi":"颓废","pinyin":"tuífèi","vi":"suy đồi"},{"hanzi":"消沉","pinyin":"xiāochén","vi":"sa sút tinh thần"},{"hanzi":"振作","pinyin":"zhènzuò","vi":"phấn chấn"}],"traditional":"頹喪"},{"id":"拓展","hanzi":"拓展","pinyin":"tuòzhǎn","meaning_vi":"mở rộng (thị trường/tầm nhìn)","explanation":"拓 (mở mang/khai phá) + 展 (triển lãm/phát triển).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"公司正在拓展海外市场。","pinyin":"Gōngsī zhèngzài tuòzhǎn hǎiwài shìchǎng.","vi":"Công ty đang mở rộng thị trường nước ngoài."},{"type":"simple","zh":"多读不同领域的书可以拓展我们的视野。","pinyin":"Duō dú bùtóng lǐngyù de shū kěyǐ tuòzhǎn wǒmen de shìyě.","vi":"Đọc nhiều sách thuộc các lĩnh vực khác nhau có thể mở rộng tầm nhìn của chúng ta."},{"type":"compound","zh":"只要产品质量过硬，我们就有信心把业务拓展到东南亚。","pinyin":"Zhǐyào chǎnpǐn zhìliàng guòyìng, wǒmen jiù yǒu xìnxīn bǎ yèwù tuòzhǎn dào Dōngnányà.","vi":"Chỉ cần chất lượng sản phẩm vững vàng, chúng tôi tự tin mở rộng kinh doanh sang Đông Nam Á."}],"related":[{"hanzi":"扩展","pinyin":"kuòzhǎn","vi":"mở rộng"},{"hanzi":"开拓","pinyin":"kāituò","vi":"khai phá"},{"hanzi":"拓宽","pinyin":"tuòkuān","vi":"mở rộng"},{"hanzi":"拓展训练","pinyin":"tuòzhǎnxùnliàn","vi":"huấn luyện kỹ năng"}]},{"id":"推崇","hanzi":"推崇","pinyin":"tuīchóng","meaning_vi":"sùng bái, đề cao","explanation":"推 (thúc đẩy/suy luận) + 崇 (tôn sùng/cao cả).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🌟","examples":[{"type":"basic","zh":"他非常推崇鲁迅。","pinyin":"Tā fēicháng tuīchóng Lǔxùn.","vi":"Anh ấy vô cùng đề cao Lỗ Tấn."},{"type":"simple","zh":"这种低糖饮食方式受到许多营养师的推崇。","pinyin":"Zhè zhǒng dītáng yǐnshí fāngshì shòudào xǔduō yíngyǎngshī de tuīchóng.","vi":"Cách ăn uống ít đường này được nhiều chuyên gia dinh dưỡng đề cao."},{"type":"compound","zh":"虽然这本书被很多人推崇，但是我读完后觉得一般。","pinyin":"Suīrán zhè běn shū bèi hěn duō rén tuīchóng, dànshì wǒ dú wán hòu juéde yìbān.","vi":"Tuy cuốn sách này được nhiều người tôn sùng, nhưng tôi đọc xong thấy bình thường."}],"related":[{"hanzi":"推崇备至","pinyin":"tuīchóngbèizhì","vi":"hết sức đề cao"},{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"尊崇","pinyin":"zūnchóng","vi":"tôn sùng"},{"hanzi":"贬低","pinyin":"biǎndī","vi":"hạ thấp"}]},{"id":"推断","hanzi":"推断","pinyin":"tuīduàn","meaning_vi":"suy đoán, phán đoán","explanation":"推 (thúc đẩy/suy luận) + 断 (đứt).","hsk_level":"7-9","tags":["dong-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"这个推断很合理。","pinyin":"Zhè ge tuīduàn hěn hélǐ.","vi":"Suy đoán này rất hợp lý."},{"type":"simple","zh":"警方根据脚印推断嫌疑人身高约一米八。","pinyin":"Jǐngfāng gēnjù jiǎoyìn tuīduàn xiányírén shēngāo yuē yì mǐ bā.","vi":"Cảnh sát dựa vào dấu chân suy đoán nghi phạm cao khoảng một mét tám."},{"type":"compound","zh":"既然地面是湿的，我们就可以推断昨晚下过雨。","pinyin":"Jìrán dìmiàn shì shī de, wǒmen jiù kěyǐ tuīduàn zuówǎn xiàguo yǔ.","vi":"Mặt đất đã ướt thì chúng ta có thể suy ra đêm qua trời đã mưa."}],"related":[{"hanzi":"推测","pinyin":"tuīcè","vi":"suy đoán"},{"hanzi":"推理","pinyin":"tuīlǐ","vi":"suy luận"},{"hanzi":"判断","pinyin":"pànduàn","vi":"phán đoán"},{"hanzi":"推论","pinyin":"tuīlùn","vi":"suy luận"}],"traditional":"推斷"},{"id":"推荐信","hanzi":"推荐信","pinyin":"tuījiànxìn","meaning_vi":"thư giới thiệu","explanation":"推 (thúc đẩy/suy luận) + 荐 (荐) + 信 (niềm tin/uy tín).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","cong-viec"],"image":"💌","examples":[{"type":"basic","zh":"教授给我写了推荐信。","pinyin":"Jiàoshòu gěi wǒ xiěle tuījiànxìn.","vi":"Giáo sư đã viết thư giới thiệu cho tôi."},{"type":"simple","zh":"申请这所大学需要提交两封推荐信。","pinyin":"Shēnqǐng zhè suǒ dàxué xūyào tíjiāo liǎng fēng tuījiànxìn.","vi":"Nộp đơn vào trường đại học này cần hai bức thư giới thiệu."},{"type":"compound","zh":"如果有前任老板的推荐信，你找新工作就会顺利得多。","pinyin":"Rúguǒ yǒu qiánrèn lǎobǎn de tuījiànxìn, nǐ zhǎo xīn gōngzuò jiù huì shùnlì de duō.","vi":"Nếu có thư giới thiệu của sếp cũ, bạn tìm việc mới sẽ thuận lợi hơn nhiều."}],"related":[{"hanzi":"推荐","pinyin":"tuījiàn","vi":"giới thiệu"},{"hanzi":"申请","pinyin":"shēnqǐng","vi":"xin, đăng ký"},{"hanzi":"简历","pinyin":"jiǎnlì","vi":"sơ yếu lý lịch"},{"hanzi":"求职信","pinyin":"qiúzhíxìn","vi":"thư xin việc"}],"traditional":"推薦信"},{"id":"推举","hanzi":"推举","pinyin":"tuījǔ","meaning_vi":"tiến cử, bầu chọn","explanation":"推 (thúc đẩy/suy luận) + 举 (cử chỉ/nêu ra).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🙋","examples":[{"type":"basic","zh":"大家推举他当班长。","pinyin":"Dàjiā tuījǔ tā dāng bānzhǎng.","vi":"Mọi người bầu cậu ấy làm lớp trưởng."},{"type":"simple","zh":"村民们一致推举老李担任新的村主任。","pinyin":"Cūnmínmen yízhì tuījǔ lǎo Lǐ dānrèn xīn de cūn zhǔrèn.","vi":"Dân làng nhất trí tiến cử ông Lý làm trưởng thôn mới."},{"type":"compound","zh":"因为她做事公正，所以同事们推举她做工会代表。","pinyin":"Yīnwèi tā zuòshì gōngzhèng, suǒyǐ tóngshìmen tuījǔ tā zuò gōnghuì dàibiǎo.","vi":"Vì cô ấy làm việc công bằng nên đồng nghiệp tiến cử cô làm đại diện công đoàn."}],"related":[{"hanzi":"推选","pinyin":"tuīxuǎn","vi":"bầu chọn"},{"hanzi":"选举","pinyin":"xuǎnjǔ","vi":"bầu cử"},{"hanzi":"推荐","pinyin":"tuījiàn","vi":"đề cử"},{"hanzi":"举荐","pinyin":"jǔjiàn","vi":"tiến cử"}],"traditional":"推舉"},{"id":"推拿","hanzi":"推拿","pinyin":"tuīná","meaning_vi":"xoa bóp bấm huyệt","explanation":"推 (đẩy) + 拿 (nắm/bóp).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","van-hoa"],"image":"💆","examples":[{"type":"basic","zh":"他去中医馆做推拿。","pinyin":"Tā qù zhōngyī guǎn zuò tuīná.","vi":"Anh ấy đến phòng khám Đông y để xoa bóp bấm huyệt."},{"type":"simple","zh":"推拿师傅在我酸痛的肩膀上按了半个小时。","pinyin":"Tuīná shīfu zài wǒ suāntòng de jiānbǎng shàng ànle bàn gè xiǎoshí.","vi":"Thầy xoa bóp ấn huyệt trên bờ vai đau nhức của tôi suốt nửa tiếng."},{"type":"compound","zh":"每次腰疼得厉害，他就去楼下的店里做一次推拿。","pinyin":"Měi cì yāo téng de lìhai, tā jiù qù lóuxià de diàn lǐ zuò yí cì tuīná.","vi":"Mỗi lần đau lưng dữ dội, ông ấy lại xuống tiệm dưới nhà xoa bóp bấm huyệt một lần."}],"related":[{"hanzi":"按摩","pinyin":"ànmó","vi":"xoa bóp"},{"hanzi":"针灸","pinyin":"zhēnjiǔ","vi":"châm cứu"},{"hanzi":"穴位","pinyin":"xuéwèi","vi":"huyệt vị"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"}]},{"id":"推算","hanzi":"推算","pinyin":"tuīsuàn","meaning_vi":"tính toán dự đoán","explanation":"推 (thúc đẩy/suy luận) + 算 (tính toán).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🧮","examples":[{"type":"basic","zh":"我推算了一下日期。","pinyin":"Wǒ tuī suànle yíxià rìqī.","vi":"Tôi đã tính thử ngày tháng."},{"type":"simple","zh":"古人通过观察月相来推算农历的日子。","pinyin":"Gǔrén tōngguò guānchá yuèxiàng lái tuīsuàn nónglì de rìzi.","vi":"Người xưa quan sát tuần trăng để tính ngày âm lịch."},{"type":"compound","zh":"按照目前的速度推算，我们下午三点就能到达山顶。","pinyin":"Ànzhào mùqián de sùdù tuīsuàn, wǒmen xiàwǔ sān diǎn jiù néng dàodá shāndǐng.","vi":"Tính theo tốc độ hiện tại thì ba giờ chiều chúng ta sẽ lên tới đỉnh núi."}],"related":[{"hanzi":"计算","pinyin":"jìsuàn","vi":"tính toán"},{"hanzi":"估算","pinyin":"gūsuàn","vi":"ước tính"},{"hanzi":"推测","pinyin":"tuīcè","vi":"suy đoán"},{"hanzi":"预测","pinyin":"yùcè","vi":"dự đoán"}]},{"id":"推移","hanzi":"推移","pinyin":"tuīyí","meaning_vi":"trôi qua (thời gian - 时间的推移)","explanation":"推 (thúc đẩy/suy luận) + 移 (di chuyển/thay đổi).","hsk_level":"7-9","tags":["dong-tu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"随着季节推移，天变冷了。","pinyin":"Suízhe jìjié tuīyí, tiān biàn lěng le.","vi":"Mùa chuyển dần, trời đã lạnh hơn."},{"type":"simple","zh":"随着时间的推移，这座小镇变得越来越热闹。","pinyin":"Suízhe shíjiān de tuīyí, zhè zuò xiǎozhèn biànde yuèláiyuè rènao.","vi":"Theo thời gian trôi qua, thị trấn nhỏ này ngày càng sầm uất."},{"type":"compound","zh":"虽然当初两人吵得很凶，但是随着岁月推移，他们早已和好如初。","pinyin":"Suīrán dāngchū liǎng rén chǎo de hěn xiōng, dànshì suízhe suìyuè tuīyí, tāmen zǎoyǐ héhǎo rúchū.","vi":"Tuy lúc đầu hai người cãi nhau rất dữ, nhưng năm tháng trôi qua họ đã làm lành như xưa."}],"related":[{"hanzi":"时间的推移","pinyin":"shíjiān de tuīyí","vi":"thời gian trôi qua"},{"hanzi":"流逝","pinyin":"liúshì","vi":"trôi đi"},{"hanzi":"变迁","pinyin":"biànqiān","vi":"biến đổi"},{"hanzi":"随着","pinyin":"suízhe","vi":"theo cùng"}]},{"id":"托付","hanzi":"托付","pinyin":"tuōfù","meaning_vi":"gửi gắm, ủy thác","explanation":"托 (ủy thác/nâng đỡ) + 付 (付).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"我把钥匙托付给邻居。","pinyin":"Wǒ bǎ yàoshi tuōfù gěi línjū.","vi":"Tôi gửi chìa khóa nhờ hàng xóm giữ."},{"type":"simple","zh":"临终前，老人把唯一的孙子托付给了老朋友。","pinyin":"Línzhōng qián, lǎorén bǎ wéiyī de sūnzi tuōfù gěile lǎopéngyou.","vi":"Trước lúc lâm chung, ông cụ gửi gắm đứa cháu duy nhất cho người bạn cũ."},{"type":"compound","zh":"既然你把这件事托付给我，我就一定会办好。","pinyin":"Jìrán nǐ bǎ zhè jiàn shì tuōfù gěi wǒ, wǒ jiù yídìng huì bànhǎo.","vi":"Bạn đã giao phó việc này cho tôi thì tôi nhất định sẽ làm cho tốt."}],"related":[{"hanzi":"委托","pinyin":"wěituō","vi":"ủy thác"},{"hanzi":"嘱托","pinyin":"zhǔtuō","vi":"dặn dò gửi gắm"},{"hanzi":"信任","pinyin":"xìnrèn","vi":"tín nhiệm"},{"hanzi":"托人","pinyin":"tuōrén","vi":"nhờ người"}],"traditional":"託付"},{"id":"脱节","hanzi":"脱节","pinyin":"tuōjié","meaning_vi":"lệch nhịp, xa rời thực tế","explanation":"脱 (thoát ly/tỏa sáng) + 节 (节).","hsk_level":"7-9","tags":["dong-tu"],"image":"🔌","examples":[{"type":"basic","zh":"理论和实践脱节了。","pinyin":"Lǐlùn hé shíjiàn tuōjié le.","vi":"Lý thuyết và thực tiễn đã tách rời nhau."},{"type":"simple","zh":"有些大学课程内容与市场需求严重脱节。","pinyin":"Yǒuxiē dàxué kèchéng nèiróng yǔ shìchǎng xūqiú yánzhòng tuōjié.","vi":"Nội dung một số môn học đại học xa rời nghiêm trọng nhu cầu thị trường."},{"type":"compound","zh":"如果管理层长期不下基层，决策就容易和实际脱节。","pinyin":"Rúguǒ guǎnlǐ céng chángqī búxià jīcéng, juécè jiù róngyì hé shíjì tuōjié.","vi":"Nếu cấp quản lý lâu ngày không xuống cơ sở, quyết sách sẽ dễ xa rời thực tế."}],"related":[{"hanzi":"脱离","pinyin":"tuōlí","vi":"thoát ly"},{"hanzi":"衔接","pinyin":"xiánjiē","vi":"nối tiếp"},{"hanzi":"与时代脱节","pinyin":"yǔ shídài tuōjié","vi":"lạc hậu với thời đại"},{"hanzi":"断层","pinyin":"duàncéng","vi":"đứt gãy"}],"traditional":"脫節"},{"id":"脱口","hanzi":"脱口","pinyin":"tuōkǒu","meaning_vi":"buột miệng","explanation":"脱 (thoát ly/tỏa sáng) + 口 (口).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"😮","examples":[{"type":"basic","zh":"他脱口而出一句英语。","pinyin":"Tā tuōkǒu'érchū yíjù Yīngyǔ.","vi":"Anh ấy buột miệng nói ra một câu tiếng Anh."},{"type":"simple","zh":"她一时生气，把心里话脱口说了出来。","pinyin":"Tā yìshí shēngqì, bǎ xīnlǐhuà tuōkǒu shuōle chūlái.","vi":"Trong lúc tức giận, cô ấy buột miệng nói hết lời trong lòng."},{"type":"compound","zh":"因为太熟悉这首诗，所以他脱口就背出了全文。","pinyin":"Yīnwèi tài shúxī zhè shǒu shī, suǒyǐ tā tuōkǒu jiù bèi chūle quánwén.","vi":"Vì quá thuộc bài thơ này nên cậu ấy đọc thuộc lòng cả bài ngay không cần nghĩ."}],"related":[{"hanzi":"脱口而出","pinyin":"tuōkǒu'érchū","vi":"buột miệng nói ra"},{"hanzi":"随口","pinyin":"suíkǒu","vi":"thuận miệng"},{"hanzi":"失言","pinyin":"shīyán","vi":"lỡ lời"},{"hanzi":"脱口秀","pinyin":"tuōkǒuxiù","vi":"talk show"}],"traditional":"脫口"},{"id":"脱贫","hanzi":"脱贫","pinyin":"tuōpín","meaning_vi":"thoát nghèo","explanation":"脱 (thoát ly/tỏa sáng) + 贫 (nghèo nàn/cằn cỗi).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🌱","examples":[{"type":"basic","zh":"这个村子已经脱贫了。","pinyin":"Zhè ge cūnzi yǐjīng tuōpín le.","vi":"Ngôi làng này đã thoát nghèo."},{"type":"simple","zh":"靠种植茶叶，山里的许多农户实现了脱贫。","pinyin":"Kào zhòngzhí cháyè, shān lǐ de xǔduō nónghù shíxiànle tuōpín.","vi":"Nhờ trồng chè, nhiều hộ nông dân vùng núi đã thoát nghèo."},{"type":"compound","zh":"只要找到适合当地的产业，贫困家庭就能尽快脱贫。","pinyin":"Zhǐyào zhǎodào shìhé dāngdì de chǎnyè, pínkùn jiātíng jiù néng jǐnkuài tuōpín.","vi":"Chỉ cần tìm được ngành nghề phù hợp với địa phương, các hộ nghèo sẽ sớm thoát nghèo."}],"related":[{"hanzi":"贫困","pinyin":"pínkùn","vi":"nghèo khó"},{"hanzi":"扶贫","pinyin":"fúpín","vi":"hỗ trợ xóa nghèo"},{"hanzi":"致富","pinyin":"zhìfù","vi":"làm giàu"},{"hanzi":"小康","pinyin":"xiǎokāng","vi":"khá giả"}],"traditional":"脫貧"},{"id":"脱贫攻坚","hanzi":"脱贫攻坚","pinyin":"tuōpíngōngjiān","meaning_vi":"xóa đói giảm nghèo","explanation":"脱 (cởi (quần áo/giày dép)) + 贫 (nghèo nàn/cằn cỗi) + 攻 (攻) + 坚 (kiên định/vững chắc).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🌱","examples":[{"type":"basic","zh":"脱贫攻坚取得了胜利。","pinyin":"Tuōpíngōngjiān qǔ déle shènglì.","vi":"Cuộc chiến xóa nghèo đã giành thắng lợi."},{"type":"simple","zh":"他在脱贫攻坚一线驻村工作了整整五年。","pinyin":"Tā zài tuōpíngōngjiān yíxiàn zhù cūn gōngzuòle zhěngzhěng wǔ nián.","vi":"Anh ấy bám thôn ở tuyến đầu xóa đói giảm nghèo tròn năm năm."},{"type":"compound","zh":"脱贫攻坚不但修通了山路，而且让孩子们有了新校舍。","pinyin":"Tuōpíngōngjiān búdàn xiū tōngle shānlù, érqiě ràng háizimen yǒule xīn xiàoshè.","vi":"Công cuộc xóa đói giảm nghèo không chỉ mở thông đường núi mà còn mang đến trường học mới cho các em nhỏ."}],"related":[{"hanzi":"扶贫","pinyin":"fúpín","vi":"hỗ trợ xóa nghèo"},{"hanzi":"精准扶贫","pinyin":"jīngzhǔnfúpín","vi":"xóa nghèo chính xác"},{"hanzi":"贫困户","pinyin":"pínkùnhù","vi":"hộ nghèo"},{"hanzi":"乡村振兴","pinyin":"xiāngcūnzhènxīng","vi":"chấn hưng nông thôn"}],"traditional":"脫貧攻堅"},{"id":"脱水","hanzi":"脱水","pinyin":"tuōshuǐ","meaning_vi":"mất nước (cơ thể), vắt khô nước","explanation":"脱 (thoát ly/tỏa sáng) + 水 (nước).","hsk_level":"7-9","tags":["dong-tu","suc-khoe"],"image":"💧","examples":[{"type":"basic","zh":"他跑完步有点脱水。","pinyin":"Tā pǎo wán bù yǒudiǎn tuōshuǐ.","vi":"Chạy bộ xong anh ấy hơi bị mất nước."},{"type":"simple","zh":"洗衣机正在给刚洗好的床单脱水。","pinyin":"Xǐyījī zhèngzài gěi gāng xǐ hǎo de chuángdān tuōshuǐ.","vi":"Máy giặt đang vắt khô tấm ga trải giường vừa giặt xong."},{"type":"compound","zh":"如果腹泻时不及时补充水分，人就很容易脱水。","pinyin":"Rúguǒ fùxiè shí bù jíshí bǔchōng shuǐfèn, rén jiù hěn róngyì tuōshuǐ.","vi":"Nếu bị tiêu chảy mà không kịp thời bù nước thì người ta rất dễ bị mất nước."}],"related":[{"hanzi":"缺水","pinyin":"quēshuǐ","vi":"thiếu nước"},{"hanzi":"补水","pinyin":"bǔshuǐ","vi":"bù nước"},{"hanzi":"甩干","pinyin":"shuǎigān","vi":"vắt khô"},{"hanzi":"中暑","pinyin":"zhòngshǔ","vi":"say nắng"}],"traditional":"脫水"},{"id":"脱身","hanzi":"脱身","pinyin":"tuōshēn","meaning_vi":"thoát thân, rảnh tay rời đi","explanation":"脱 (thoát ly/tỏa sáng) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["dong-tu"],"image":"🕊️","examples":[{"type":"basic","zh":"我忙得无法脱身。","pinyin":"Wǒ máng de wúfǎ tuōshēn.","vi":"Tôi bận đến mức không thể rút ra được."},{"type":"simple","zh":"会议一直开到晚上九点，经理才得以脱身。","pinyin":"Huìyì yìzhí kāi dào wǎnshang jiǔ diǎn, jīnglǐ cái déyǐ tuōshēn.","vi":"Cuộc họp kéo dài đến chín giờ tối, giám đốc mới thoát ra được."},{"type":"compound","zh":"一从饭局上脱身，他就打车赶回家陪孩子过生日。","pinyin":"Yì cóng fànjú shàng tuōshēn, tā jiù dǎchē gǎn huíjiā péi háizi guòshēngrì.","vi":"Vừa thoát ra khỏi bữa tiệc xã giao, anh ấy liền bắt taxi về nhà mừng sinh nhật con."}],"related":[{"hanzi":"摆脱","pinyin":"bǎituō","vi":"thoát khỏi"},{"hanzi":"抽身","pinyin":"chōushēn","vi":"rút thân"},{"hanzi":"逃脱","pinyin":"táotuō","vi":"trốn thoát"},{"hanzi":"分身乏术","pinyin":"fēnshēnfáshù","vi":"không thể phân thân"}],"traditional":"脫身"},{"id":"拖延症","hanzi":"拖延症","pinyin":"tuōyánzhèng","meaning_vi":"chứng trì hoãn","explanation":"拖 (trì hoãn/kéo dài) + 延 (kéo dài/lan tràn) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cong-viec"],"image":"🦥","examples":[{"type":"basic","zh":"我有严重的拖延症。","pinyin":"Wǒ yǒu yánzhòng de tuōyánzhèng.","vi":"Tôi mắc chứng trì hoãn nặng."},{"type":"simple","zh":"他的拖延症让论文一直拖到截止前一天才动笔。","pinyin":"Tā de tuōyánzhèng ràng lùnwén yìzhí tuō dào jiézhǐ qiányìtiān cái dòngbǐ.","vi":"Chứng trì hoãn khiến anh ấy để đến hôm trước hạn nộp mới bắt tay viết luận văn."},{"type":"compound","zh":"与其等着拖延症自己消失，不如现在就定个小目标。","pinyin":"Yǔqí děngzhe tuōyánzhèng zìjǐ xiāoshī, bùrú xiànzài jiù dìng gè xiǎo mùbiāo.","vi":"Thay vì chờ chứng trì hoãn tự biến mất, chi bằng đặt ngay một mục tiêu nhỏ."}],"related":[{"hanzi":"拖延","pinyin":"tuōyán","vi":"trì hoãn"},{"hanzi":"拖拉","pinyin":"tuōlā","vi":"lề mề"},{"hanzi":"磨蹭","pinyin":"móceng","vi":"chậm chạp"},{"hanzi":"效率","pinyin":"xiàolǜ","vi":"hiệu suất"}]},{"id":"脱颖","hanzi":"脱颖","pinyin":"tuōyǐng","meaning_vi":"tỏa sáng nổi bật","explanation":"脱 (thoát ly/tỏa sáng) + 颖 (颖).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"她在比赛中脱颖而出。","pinyin":"Tā zài bǐsài zhōng tuōyǐng'érchū.","vi":"Cô ấy nổi bật hẳn lên trong cuộc thi."},{"type":"simple","zh":"这款新手机凭借超长续航从众多产品中脱颖而出。","pinyin":"Zhè kuǎn xīnshǒu jī píngjiè chāo cháng xùháng cóng zhòngduō chǎnpǐn zhōng tuōyǐng'érchū.","vi":"Mẫu điện thoại mới này nổi bật giữa vô số sản phẩm nhờ thời lượng pin cực dài."},{"type":"compound","zh":"只要你的方案足够新颖，就一定能在评审中脱颖而出。","pinyin":"Zhǐyào nǐ de fāng'àn zúgòu xīnyǐng, jiù yídìng néng zài píngshěn zhōng tuōyǐng'érchū.","vi":"Chỉ cần phương án của bạn đủ mới mẻ, nhất định sẽ nổi bật trong vòng thẩm định."}],"related":[{"hanzi":"脱颖而出","pinyin":"tuōyǐng'érchū","vi":"nổi bật hẳn lên"},{"hanzi":"出众","pinyin":"chūzhòng","vi":"xuất chúng"},{"hanzi":"崭露头角","pinyin":"zhǎnlùtóujiǎo","vi":"bắt đầu lộ tài"},{"hanzi":"突出","pinyin":"tūchū","vi":"nổi bật"}],"traditional":"脫穎"},{"id":"椭圆形","hanzi":"椭圆形","pinyin":"tuǒyuánxíng","meaning_vi":"hình bầu dục, hình elip","explanation":"椭 (hình bầu dục) + 圆 (viên mãn/tròn) + 形 (hình thái/hình thành).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🥚","examples":[{"type":"basic","zh":"这张桌子是椭圆形的。","pinyin":"Zhè zhāng zhuōzi shì tuǒyuánxíng de.","vi":"Chiếc bàn này có hình bầu dục."},{"type":"simple","zh":"地球绕太阳运行的轨道其实是椭圆形的。","pinyin":"Dìqiú rào tàiyáng yùnxíng de guǐdào qíshí shì tuǒyuánxíng de.","vi":"Quỹ đạo Trái Đất quay quanh Mặt Trời thực ra có hình elip."},{"type":"compound","zh":"因为镜子是椭圆形的，所以挂在窄墙上显得很协调。","pinyin":"Yīnwèi jìngzi shì tuǒyuánxíng de, suǒyǐ guà zài zhǎi qiáng shàng xiǎnde hěn xiétiáo.","vi":"Vì chiếc gương hình bầu dục nên treo trên bức tường hẹp trông rất hài hòa."}],"related":[{"hanzi":"圆形","pinyin":"yuánxíng","vi":"hình tròn"},{"hanzi":"椭圆","pinyin":"tuǒyuán","vi":"hình elip"},{"hanzi":"长方形","pinyin":"chángfāngxíng","vi":"hình chữ nhật"},{"hanzi":"三角形","pinyin":"sānjiǎoxíng","vi":"hình tam giác"}],"traditional":"橢圓形"},{"id":"踏青","hanzi":"踏青","pinyin":"tàqīng","meaning_vi":"du xuân, dạo chơi đồng cỏ mùa xuân","explanation":"踏 (giẫm bước/thiết thực) + 青 (màu xanh (xanh lá/xanh da trời/đen)).","hsk_level":"7-9","tags":["dong-tu","van-hoa","du-lich"],"image":"🌱","examples":[{"type":"basic","zh":"周末我们去郊外踏青。","pinyin":"Zhōumò wǒmen qù jiāowài tàqīng.","vi":"Cuối tuần chúng tôi ra ngoại ô du xuân."},{"type":"simple","zh":"清明前后，很多家庭带着孩子到湖边踏青放风筝。","pinyin":"Qīngmíng qiánhòu, hěn duō jiātíng dàizhe háizi dào húbiān tàqīng fàngfēngzheng.","vi":"Khoảng tiết Thanh minh, nhiều gia đình đưa con ra bờ hồ dạo xuân, thả diều."},{"type":"compound","zh":"一到春暖花开的时候，公园里就挤满了踏青的游客。","pinyin":"Yí dào chūnnuǎnhuākāi de shíhou, gōngyuán lǐ jiù jǐmǎnle tàqīng de yóukè.","vi":"Cứ đến mùa xuân ấm áp hoa nở, công viên lại chật kín du khách đi du xuân."}],"related":[{"hanzi":"郊游","pinyin":"jiāoyóu","vi":"đi dã ngoại"},{"hanzi":"春游","pinyin":"chūnyóu","vi":"du xuân"},{"hanzi":"清明节","pinyin":"Qīngmíngjié","vi":"Tết Thanh minh"},{"hanzi":"赏花","pinyin":"shǎnghuā","vi":"ngắm hoa"}]},{"id":"太平洋","hanzi":"太平洋","pinyin":"Tàipíngyáng","meaning_vi":"Thái Bình Dương","explanation":"太 (quá) + 平 (bằng phẳng) + 洋 (đại dương/nước ngoài).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"太平洋是最大的海洋。","pinyin":"Tàipíngyáng shì zuì dà de hǎiyáng.","vi":"Thái Bình Dương là đại dương lớn nhất."},{"type":"simple","zh":"这艘货轮需要航行二十天才能横渡太平洋。","pinyin":"Zhè sōu huòlún xūyào hángxíng èrshí tiāncái néng héngdù Tàipíngyáng.","vi":"Con tàu hàng này phải đi hai mươi ngày mới vượt qua được Thái Bình Dương."},{"type":"compound","zh":"虽然太平洋的名字意为和平，但是那里常常发生台风。","pinyin":"Suīrán Tàipíngyáng de míngzi yì wéi hépíng, dànshì nàlǐ chángcháng fāshēng táifēng.","vi":"Tuy tên Thái Bình Dương mang nghĩa hòa bình, nhưng ở đó thường xuyên có bão."}],"related":[{"hanzi":"大西洋","pinyin":"Dàxīyáng","vi":"Đại Tây Dương"},{"hanzi":"印度洋","pinyin":"Yìndùyáng","vi":"Ấn Độ Dương"},{"hanzi":"海洋","pinyin":"hǎiyáng","vi":"đại dương"},{"hanzi":"北冰洋","pinyin":"Běibīngyáng","vi":"Bắc Băng Dương"}]},{"id":"泰山","hanzi":"泰山","pinyin":"Tàishān","meaning_vi":"núi Thái Sơn (Sơn Đông - đứng đầu Ngũ Nhạc)","explanation":"Danh sơn văn hóa lịch sử.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thien-nhien"],"image":"⛰️","examples":[{"type":"basic","zh":"我想去爬泰山。","pinyin":"Wǒ xiǎng qù pá Tàishān.","vi":"Tôi muốn đi leo núi Thái Sơn."},{"type":"simple","zh":"我们凌晨三点出发，赶在日出前登上了泰山。","pinyin":"Wǒmen língchén sān diǎn chūfā, gǎn zài rìchū qián dēngshàngle Tàishān.","vi":"Chúng tôi xuất phát lúc ba giờ sáng và kịp lên đỉnh Thái Sơn trước bình minh."},{"type":"compound","zh":"虽然泰山不算最高，但是它在中国文化中地位特殊。","pinyin":"Suīrán Tàishān búsuàn zuì gāo, dànshì tā zài Zhōngguó wénhuà zhōng dìwèi tèshū.","vi":"Tuy Thái Sơn không phải núi cao nhất, nhưng nó có vị trí đặc biệt trong văn hóa Trung Quốc."}],"related":[{"hanzi":"五岳","pinyin":"Wǔyuè","vi":"Ngũ Nhạc"},{"hanzi":"黄山","pinyin":"Huángshān","vi":"Hoàng Sơn"},{"hanzi":"登山","pinyin":"dēngshān","vi":"leo núi"},{"hanzi":"山东","pinyin":"Shāndōng","vi":"Sơn Đông"}]},{"id":"太阳能","hanzi":"太阳能","pinyin":"tàiyángnéng","meaning_vi":"năng lượng Mặt Trời","explanation":"太 (quá) + 阳 (阳) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"☀️","examples":[{"type":"basic","zh":"屋顶装了太阳能板。","pinyin":"Wūdǐng zhuāngle tàiyángnéng bǎn.","vi":"Trên mái nhà đã lắp tấm pin năng lượng mặt trời."},{"type":"simple","zh":"这辆小车完全依靠太阳能驱动。","pinyin":"Zhè liàng xiǎochē wánquán yīkào tàiyángnéng qūdòng.","vi":"Chiếc xe nhỏ này chạy hoàn toàn bằng năng lượng mặt trời."},{"type":"compound","zh":"既然这里日照充足，就应该多利用太阳能发电。","pinyin":"Jìrán zhèlǐ rìzhào chōngzú, jiù yīnggāi duō lìyòng tàiyángnéng fādiàn.","vi":"Nơi đây đã có nắng dồi dào thì nên tận dụng năng lượng mặt trời để phát điện."}],"related":[{"hanzi":"新能源","pinyin":"xīnnéngyuán","vi":"năng lượng mới"},{"hanzi":"风能","pinyin":"fēngnéng","vi":"năng lượng gió"},{"hanzi":"太阳能电池板","pinyin":"tàiyángnéng diànchí bǎn","vi":"tấm pin mặt trời"},{"hanzi":"清洁能源","pinyin":"qīngjiénéngyuán","vi":"năng lượng sạch"}],"traditional":"太陽能"},{"id":"太阳系","hanzi":"太阳系","pinyin":"tàiyángxì","meaning_vi":"Hệ Mặt Trời","explanation":"太 (quá) + 阳 (阳) + 系 (khoa (trong trường đại học)).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","thien-nhien"],"image":"☀️","examples":[{"type":"basic","zh":"太阳系有八大行星。","pinyin":"Tàiyángxì yǒu bā dà xíngxīng.","vi":"Hệ Mặt Trời có tám hành tinh lớn."},{"type":"simple","zh":"木星是太阳系里体积最大的行星。","pinyin":"Mùxīng shì tàiyángxì lǐ tǐjī zuì dà de xíngxīng.","vi":"Sao Mộc là hành tinh có thể tích lớn nhất trong Hệ Mặt Trời."},{"type":"compound","zh":"虽然人类已经探测到太阳系的边缘，但是仍有许多谜团。","pinyin":"Suīrán rénlèi yǐjīng tàncè dào tàiyángxì de biānyuán, dànshì réng yǒu xǔduō mítuán.","vi":"Tuy loài người đã thăm dò tới rìa Hệ Mặt Trời, nhưng vẫn còn nhiều bí ẩn."}],"related":[{"hanzi":"行星","pinyin":"xíngxīng","vi":"hành tinh"},{"hanzi":"地球","pinyin":"dìqiú","vi":"Trái Đất"},{"hanzi":"银河系","pinyin":"Yínhéxì","vi":"Ngân Hà"},{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"}],"traditional":"太陽系"},{"id":"探访","hanzi":"探访","pinyin":"tànfǎng","meaning_vi":"thăm hỏi, phỏng vấn tìm hiểu","explanation":"探 (thăm dò/khám phá) + 访 (访).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🔍","examples":[{"type":"basic","zh":"记者探访了这家孤儿院。","pinyin":"Jìzhě tànfǎngle zhè jiā gū'éryuàn.","vi":"Phóng viên đã đến tìm hiểu trại trẻ mồ côi này."},{"type":"simple","zh":"周末我们回老家探访了多年未见的老师。","pinyin":"Zhōumò wǒmen huílǎojiā tànfǎngle duōnián wèi jiàn de lǎoshī.","vi":"Cuối tuần chúng tôi về quê thăm thầy giáo đã nhiều năm không gặp."},{"type":"compound","zh":"一走进这座古村，探访者就会被精美的木雕吸引。","pinyin":"Yì zǒujìn zhè zuò gǔ cūn, tànfǎng zhě jiù huì bèi jīngměi de mù diāo xīyǐn.","vi":"Vừa bước vào ngôi làng cổ này, người đến thăm sẽ bị thu hút bởi những bức chạm gỗ tinh xảo."}],"related":[{"hanzi":"拜访","pinyin":"bàifǎng","vi":"thăm viếng"},{"hanzi":"探望","pinyin":"tànwàng","vi":"thăm hỏi"},{"hanzi":"采访","pinyin":"cǎifǎng","vi":"phỏng vấn"},{"hanzi":"走访","pinyin":"zǒufǎng","vi":"đi thăm hỏi"}],"traditional":"探訪"},{"id":"探究","hanzi":"探究","pinyin":"tànjiū","meaning_vi":"tìm tòi nghiên cứu","explanation":"探 (thăm dò/khám phá) + 究 (nghiên cứu/truy cứu).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"他喜欢探究原因。","pinyin":"Tā xǐhuan tànjiū yuányīn.","vi":"Cậu ấy thích tìm tòi nguyên nhân."},{"type":"simple","zh":"研究小组正在探究这种鸟迁徙路线变化的原因。","pinyin":"Yánjiū xiǎozǔ zhèngzài tànjiū zhè zhǒng niǎo qiānxǐ lùxiàn biànhuà de yuányīn.","vi":"Nhóm nghiên cứu đang tìm hiểu nguyên nhân thay đổi tuyến di cư của loài chim này."},{"type":"compound","zh":"老师不但讲解结论，而且鼓励学生自己动手探究。","pinyin":"Lǎoshī búdàn jiǎngjiě jiélùn, érqiě gǔlì xuésheng zìjǐ dòngshǒu tànjiū.","vi":"Thầy giáo không chỉ giảng kết luận mà còn khuyến khích học sinh tự tay tìm tòi nghiên cứu."}],"related":[{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"},{"hanzi":"研究","pinyin":"yánjiū","vi":"nghiên cứu"},{"hanzi":"追究","pinyin":"zhuījiū","vi":"truy cứu"},{"hanzi":"探讨","pinyin":"tàntǎo","vi":"thảo luận"}]},{"id":"碳排放","hanzi":"碳排放","pinyin":"tànpáifàng","meaning_vi":"phát thải cacbon","explanation":"碳 (cacbon) + 排 (bài xích/sắp xếp) + 放 (đặt).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","xa-hoi"],"image":"🏭","examples":[{"type":"basic","zh":"工厂要减少碳排放。","pinyin":"Gōngchǎng yào jiǎnshǎo tànpáifàng.","vi":"Nhà máy phải giảm phát thải cacbon."},{"type":"simple","zh":"骑自行车上班可以大大降低个人的碳排放。","pinyin":"Qí zìxíngchē shàngbān kěyǐ dàdà jiàngdī gèrén de tànpáifàng.","vi":"Đạp xe đi làm có thể giảm đáng kể lượng phát thải cacbon của mỗi người."},{"type":"compound","zh":"如果碳排放继续增加，全球气温就会进一步上升。","pinyin":"Rúguǒ tànpáifàng jìxù zēngjiā, quánqiú qìwēn jiù huì jìnyíbù shàngshēng.","vi":"Nếu phát thải cacbon tiếp tục tăng, nhiệt độ toàn cầu sẽ còn tăng thêm."}],"related":[{"hanzi":"二氧化碳","pinyin":"èryǎnghuàtàn","vi":"khí CO2"},{"hanzi":"碳中和","pinyin":"tànzhōnghé","vi":"trung hòa cacbon"},{"hanzi":"减排","pinyin":"jiǎnpái","vi":"giảm phát thải"},{"hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","vi":"hiệu ứng nhà kính"}]},{"id":"探索精神","hanzi":"探索精神","pinyin":"tànsuǒjīngshén","meaning_vi":"tinh thần khám phá","explanation":"探 (thăm dò/khám phá) + 索 (tìm tòi/dây thừng) + 精 (tinh hoa/tinh xảo) + 神 (thần kỳ/tinh thần).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🚀","examples":[{"type":"basic","zh":"科学需要探索精神。","pinyin":"Kēxué xūyào tànsuǒjīngshén.","vi":"Khoa học cần có tinh thần khám phá."},{"type":"simple","zh":"这位登山家用一生诠释了人类的探索精神。","pinyin":"Zhè wèi dēngshān jiāyòng yìshēng quánshìle rénlèi de tànsuǒjīngshén.","vi":"Nhà leo núi này đã dùng cả cuộc đời để thể hiện tinh thần khám phá của loài người."},{"type":"compound","zh":"孩子拆坏了闹钟，父母不但没骂他，反而夸他有探索精神。","pinyin":"Háizi chāi huàile nàozhōng, fùmǔ búdàn méi mà tā, fǎn'ér kuā tā yǒu tànsuǒjīngshén.","vi":"Đứa trẻ tháo hỏng đồng hồ báo thức, bố mẹ không những không mắng mà còn khen con có tinh thần khám phá."}],"related":[{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"},{"hanzi":"好奇心","pinyin":"hàoqíxīn","vi":"lòng hiếu kỳ"},{"hanzi":"创新精神","pinyin":"chuàngxīnjīngshén","vi":"tinh thần sáng tạo"},{"hanzi":"求知欲","pinyin":"qiúzhīyù","vi":"khát khao hiểu biết"}]},{"id":"叹息","hanzi":"叹息","pinyin":"tànxī","meaning_vi":"thở dài cảm thán","explanation":"叹 (cảm thán/thở dài) + 息 (tin tức/nghỉ ngơi).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"😮‍💨","examples":[{"type":"basic","zh":"她轻轻叹息了一声。","pinyin":"Tā qīngqīng tànxīle yìshēng.","vi":"Cô ấy khẽ thở dài một tiếng."},{"type":"simple","zh":"看着满地的落叶，老人发出一声长长的叹息。","pinyin":"Kànzhe mǎndì de luòyè, lǎorén fāchū yìshēng cháng cháng de tànxī.","vi":"Nhìn lá rụng đầy đất, ông lão buông một tiếng thở dài."},{"type":"compound","zh":"每次翻看旧照片，奶奶就忍不住叹息时光过得太快。","pinyin":"Měi cì fānkàn jiù zhàopiàn, nǎinai jiù rěnbúzhù tànxī shíguāng guòde tài kuài.","vi":"Mỗi lần giở xem ảnh cũ, bà lại không kìm được mà than thời gian trôi nhanh quá."}],"related":[{"hanzi":"叹气","pinyin":"tànqì","vi":"thở dài"},{"hanzi":"感叹","pinyin":"gǎntàn","vi":"cảm thán"},{"hanzi":"唉声叹气","pinyin":"āishēngtànqì","vi":"than ngắn thở dài"},{"hanzi":"惋惜","pinyin":"wǎnxī","vi":"tiếc nuối"}],"traditional":"嘆息"},{"id":"探险","hanzi":"探险","pinyin":"tànxiǎn","meaning_vi":"thám hiểm","explanation":"探 (thăm dò/khám phá) + 险 (nguy hiểm/bảo hiểm).","hsk_level":"7-9","tags":["dong-tu","du-lich"],"image":"🧭","examples":[{"type":"basic","zh":"他们去南极探险。","pinyin":"Tāmen qù nánjí tànxiǎn.","vi":"Họ đi thám hiểm Nam Cực."},{"type":"simple","zh":"一支探险队在沙漠深处发现了古城遗址。","pinyin":"Yì zhī tànxiǎn duì zài shāmò shēnchù fāxiànle gǔchéng yízhǐ.","vi":"Một đoàn thám hiểm đã phát hiện di chỉ thành cổ sâu trong sa mạc."},{"type":"compound","zh":"虽然去雨林探险很刺激，但是一定要做好安全准备。","pinyin":"Suīrán qù yǔlín tànxiǎn hěn cìjī, dànshì yídìngyào zuò hǎo ānquán zhǔnbèi.","vi":"Tuy đi thám hiểm rừng mưa rất kích thích, nhưng nhất định phải chuẩn bị an toàn kỹ càng."}],"related":[{"hanzi":"冒险","pinyin":"màoxiǎn","vi":"mạo hiểm"},{"hanzi":"探险家","pinyin":"tànxiǎnjiā","vi":"nhà thám hiểm"},{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"},{"hanzi":"考察","pinyin":"kǎochá","vi":"khảo sát"}],"traditional":"探險"},{"id":"碳中和","hanzi":"碳中和","pinyin":"tànzhōnghé","meaning_vi":"trung hòa cacbon","explanation":"碳 (cacbon) + 中 (giữa) + 和 (và).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","xa-hoi"],"image":"🌱","examples":[{"type":"basic","zh":"我国承诺实现碳中和。","pinyin":"Wǒguó chéngnuò shíxiàn tànzhōnghé.","vi":"Nước ta cam kết đạt trung hòa cacbon."},{"type":"simple","zh":"这家科技公司计划在二〇三〇年前达到碳中和。","pinyin":"Zhè jiā kē jì gōng sī jì huà zài èr líng sān líng nián qián dá dào tàn zhōng hé.","vi":"Công ty công nghệ này dự định đạt trung hòa cacbon trước năm 2030."},{"type":"compound","zh":"要实现碳中和，既要减少排放，又要多植树造林。","pinyin":"Yào shíxiàn tànzhōnghé, jì yào jiǎnshǎo páifàng, yòu yào duō zhíshùzàolín.","vi":"Muốn đạt trung hòa cacbon thì vừa phải giảm phát thải, vừa phải trồng thêm nhiều rừng."}],"related":[{"hanzi":"碳达峰","pinyin":"tàndáfēng","vi":"đỉnh phát thải cacbon"},{"hanzi":"碳排放","pinyin":"tànpáifàng","vi":"phát thải cacbon"},{"hanzi":"低碳","pinyin":"dītàn","vi":"ít cacbon"},{"hanzi":"环保","pinyin":"huánbǎo","vi":"bảo vệ môi trường"}]},{"id":"谈及","hanzi":"谈及","pinyin":"tánjí","meaning_vi":"nhắc tới, đề cập tới","explanation":"谈 (nói chuyện) + 及 (kịp thời/đạt tới).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"他很少谈及家人。","pinyin":"Tā hěn shǎo tánjí jiārén.","vi":"Anh ấy hiếm khi nhắc tới gia đình."},{"type":"simple","zh":"采访中，这位演员第一次谈及自己的童年。","pinyin":"Cǎifǎng zhōng, zhè wèi yǎnyuán dìyīcì tánjí zìjǐ de tóngnián.","vi":"Trong buổi phỏng vấn, nam diễn viên lần đầu nhắc tới thời thơ ấu của mình."},{"type":"compound","zh":"一谈及过去的失败，他就沉默下来，不愿多说。","pinyin":"Yì tánjí guòqù de shībài, tā jiù chénmò xiàlái, búyuàn duō shuō.","vi":"Hễ nhắc tới thất bại trước đây là anh ấy im lặng, không muốn nói nhiều."}],"related":[{"hanzi":"提及","pinyin":"tíjí","vi":"nhắc đến"},{"hanzi":"涉及","pinyin":"shèjí","vi":"liên quan"},{"hanzi":"谈到","pinyin":"tándào","vi":"nói đến"},{"hanzi":"提到","pinyin":"tídào","vi":"đề cập"}],"traditional":"談及"},{"id":"谈判桌","hanzi":"谈判桌","pinyin":"tánpànzhuō","meaning_vi":"bàn đàm phán","explanation":"谈 (nói chuyện) + 判 (phán quyết/xét xử) + 桌 (cái bàn).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"双方回到了谈判桌。","pinyin":"Shuāngfāng huídàole tánpànzhuō.","vi":"Hai bên đã quay lại bàn đàm phán."},{"type":"simple","zh":"在谈判桌上，她始终保持冷静和微笑。","pinyin":"Zài tánpànzhuō shàng, tā shǐzhōng bǎochí lěngjìng hé wēixiào.","vi":"Trên bàn đàm phán, cô ấy luôn giữ bình tĩnh và nụ cười."},{"type":"compound","zh":"与其在战场上流血，不如坐到谈判桌前解决分歧。","pinyin":"Yǔqí zài zhànchǎng shàng liúxuè, bùrú zuò dào tánpànzhuō qián jiějué fēnqí.","vi":"Thay vì đổ máu trên chiến trường, chi bằng ngồi vào bàn đàm phán giải quyết bất đồng."}],"related":[{"hanzi":"谈判","pinyin":"tánpàn","vi":"đàm phán"},{"hanzi":"会谈","pinyin":"huìtán","vi":"hội đàm"},{"hanzi":"协商","pinyin":"xiéshāng","vi":"hiệp thương"},{"hanzi":"签约","pinyin":"qiānyuē","vi":"ký hợp đồng"}],"traditional":"談判桌"},{"id":"糖尿病","hanzi":"糖尿病","pinyin":"tángniàobìng","meaning_vi":"bệnh tiểu đường","explanation":"糖 (đường) + 尿 (nước tiểu) + 病 (病).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"🩺","examples":[{"type":"basic","zh":"爷爷患有糖尿病。","pinyin":"Yéye huànyǒu tángniàobìng.","vi":"Ông nội bị bệnh tiểu đường."},{"type":"simple","zh":"糖尿病患者应该严格控制每天的糖分摄入。","pinyin":"Tángniàobìng huànzhě yīnggāi yángé kòngzhì měitiān de tángfèn shèrù.","vi":"Người bệnh tiểu đường nên kiểm soát chặt lượng đường nạp vào mỗi ngày."},{"type":"compound","zh":"如果长期暴饮暴食又不运动，就可能得糖尿病。","pinyin":"Rúguǒ chángqī bào yǐn bàoshí yòu bú yùndòng, jiù kěnéng dé tángniàobìng.","vi":"Nếu lâu dài ăn uống vô độ lại không vận động thì có thể mắc bệnh tiểu đường."}],"related":[{"hanzi":"血糖","pinyin":"xuètáng","vi":"đường huyết"},{"hanzi":"高血压","pinyin":"gāoxuèyā","vi":"huyết áp cao"},{"hanzi":"胰岛素","pinyin":"yídǎosù","vi":"insulin"},{"hanzi":"慢性病","pinyin":"mànxìngbìng","vi":"bệnh mãn tính"}]},{"id":"唐诗宋词","hanzi":"唐诗宋词","pinyin":"tángshīsòngcí","meaning_vi":"thơ Đường từ Tống (đỉnh cao thi ca cổ điển TQ)","explanation":"唐诗 (Đường thi – thơ đời Đường) + 宋词 (Tống từ – từ đời Tống) → hai thể loại đỉnh cao của văn học cổ điển TQ, thường nhắc cùng 元曲 (Nguyên khúc).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📜","examples":[{"type":"basic","zh":"她从小背唐诗宋词。","pinyin":"Tā cóngxiǎo bèi tángshīsòngcí.","vi":"Cô ấy học thuộc thơ Đường từ Tống từ nhỏ."},{"type":"simple","zh":"这本选集收录了三百多首经典的唐诗宋词。","pinyin":"Zhè běn xuǎnjí shōulùle sān bǎi duō shǒu jīngdiǎn de tángshīsòngcí.","vi":"Tuyển tập này thu thập hơn ba trăm bài thơ Đường, từ Tống kinh điển."},{"type":"compound","zh":"只要读懂了唐诗宋词，就能更深地体会汉语之美。","pinyin":"Zhǐyào dúdǒngle tángshīsòngcí, jiù néng gèng shēn de tǐhuì Hànyǔ zhī měi.","vi":"Chỉ cần đọc hiểu thơ Đường từ Tống là có thể cảm nhận sâu sắc hơn vẻ đẹp của tiếng Hán."}],"related":[{"hanzi":"唐诗","pinyin":"Tángshī","vi":"thơ Đường"},{"hanzi":"宋词","pinyin":"sòngcí","vi":"từ Tống"},{"hanzi":"李白","pinyin":"Lǐbái","vi":"Lý Bạch"},{"hanzi":"古诗","pinyin":"gǔshī","vi":"thơ cổ"}],"traditional":"唐詩宋詞"},{"id":"淘汰率","hanzi":"淘汰率","pinyin":"táotàilǜ","meaning_vi":"tỷ lệ đào thải","explanation":"淘 (đào thải/sàng lọc) + 汰 (汰) + 率 (dẫn dắt/tỷ lệ).","hsk_level":"7-9","tags":["danh-tu","cong-viec","so-luong"],"image":"📉","examples":[{"type":"basic","zh":"这场考试淘汰率很高。","pinyin":"Zhè chǎng kǎoshì táotàilǜ hěn gāo.","vi":"Kỳ thi này có tỷ lệ đào thải rất cao."},{"type":"simple","zh":"飞行员选拔的淘汰率常常超过百分之九十。","pinyin":"Fēixíngyuán xuǎnbá de táotàilǜ chángcháng chāoguò bǎifēnzhī jiǔshí.","vi":"Tỷ lệ đào thải khi tuyển chọn phi công thường vượt quá chín mươi phần trăm."},{"type":"compound","zh":"因为第一轮淘汰率太高，所以很多选手连面试都没进。","pinyin":"Yīnwèi dìyīlún táotàilǜ tài gāo, suǒyǐ hěn duō xuǎnshǒu lián miànshì dōu méi jìn.","vi":"Vì tỷ lệ đào thải vòng một quá cao nên nhiều thí sinh còn chưa vào được vòng phỏng vấn."}],"related":[{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"},{"hanzi":"录取率","pinyin":"lùqǔlǜ","vi":"tỷ lệ trúng tuyển"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"},{"hanzi":"优胜劣汰","pinyin":"yōushèngliètài","vi":"mạnh thắng yếu thua"}]},{"id":"特产","hanzi":"特产","pinyin":"tèchǎn","meaning_vi":"đặc sản địa phương","explanation":"特 (đặc biệt/đặc sắc) + 产 (sản xuất/tài sản).","hsk_level":"7-9","tags":["danh-tu","an-uong","du-lich"],"image":"🎁","examples":[{"type":"basic","zh":"这是我们家乡的特产。","pinyin":"Zhè shì wǒmen jiāxiāng de tèchǎn.","vi":"Đây là đặc sản quê tôi."},{"type":"simple","zh":"他从云南出差回来，带了一箱鲜花饼当特产。","pinyin":"Tā cóng Yúnnán chūchāi huílái, dàile yì xiāng xiānhuā bǐng dāng tèchǎn.","vi":"Anh ấy đi công tác Vân Nam về, mang theo một thùng bánh hoa tươi làm đặc sản."},{"type":"compound","zh":"每到一个新城市，她就会去菜市场找当地的特产尝尝。","pinyin":"Měi dào yí gè xīn chéngshì, tā jiù huì qù càishìchǎng zhǎo dāngdì de tèchǎn cháng chang.","vi":"Mỗi lần đến một thành phố mới, cô ấy lại ra chợ tìm đặc sản địa phương để nếm thử."}],"related":[{"hanzi":"土特产","pinyin":"tǔtèchǎn","vi":"thổ sản đặc sản"},{"hanzi":"名产","pinyin":"míngchǎn","vi":"sản vật nổi tiếng"},{"hanzi":"纪念品","pinyin":"jìniànpǐn","vi":"quà lưu niệm"},{"hanzi":"特色","pinyin":"tèsè","vi":"đặc sắc"}],"traditional":"特產"},{"id":"特辑","hanzi":"特辑","pinyin":"tèjí","meaning_vi":"số đặc biệt (báo chí/chương trình)","explanation":"特 (đặc biệt/đặc sắc) + 辑 (辑).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"📺","examples":[{"type":"basic","zh":"电视台播出了春节特辑。","pinyin":"Diànshìtái bōchūle Chūnjié tèjí.","vi":"Đài truyền hình đã phát chương trình đặc biệt dịp Tết."},{"type":"simple","zh":"这期节目特辑回顾了乐队成立十年来的经典演出。","pinyin":"Zhè qī jiémù tèjí huígùle yuèduì chénglì shí niánlái de jīngdiǎn yǎnchū.","vi":"Số đặc biệt kỳ này điểm lại những buổi diễn kinh điển trong mười năm thành lập ban nhạc."},{"type":"compound","zh":"因为这期特辑邀请了所有老成员，所以收视率特别高。","pinyin":"Yīnwèi zhè qī tèjí yāoqǐngle suǒyǒu lǎo chéngyuán, suǒyǐ shōushìlǜ tèbié gāo.","vi":"Vì số đặc biệt này mời được tất cả thành viên cũ nên tỷ suất người xem rất cao."}],"related":[{"hanzi":"专辑","pinyin":"zhuānjí","vi":"album chuyên đề"},{"hanzi":"特刊","pinyin":"tèkān","vi":"ấn phẩm đặc biệt"},{"hanzi":"专题","pinyin":"zhuāntí","vi":"chuyên đề"},{"hanzi":"节目","pinyin":"jiémù","vi":"chương trình"}],"traditional":"特輯"},{"id":"特快","hanzi":"特快","pinyin":"tèkuài","meaning_vi":"tàu tốc hành đặc biệt (viết tắt của 特快列车)","explanation":"特 (đặc biệt/đặc sắc) + 快 (nhanh).","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-viec"],"image":"⚡","examples":[{"type":"basic","zh":"我们坐特快去上海。","pinyin":"Wǒmen zuò tèkuài qù Shànghǎi.","vi":"Chúng tôi đi tàu tốc hành đặc biệt đến Thượng Hải."},{"type":"simple","zh":"这趟特快只在省会城市停靠。","pinyin":"Zhè tàng tèkuài zhǐ zài shěnghuì chéngshì tíngkào.","vi":"Chuyến tàu tốc hành này chỉ dừng ở các thành phố tỉnh lỵ."},{"type":"compound","zh":"如果你赶时间，就买张特快车票，能早到三个小时。","pinyin":"Rúguǒ nǐ gǎnshíjiān, jiù mǎi zhāng tèkuài chēpiào, néng zǎo dào sān gè xiǎoshí.","vi":"Nếu bạn vội thì mua vé tàu tốc hành, có thể đến sớm hơn ba tiếng."}],"related":[{"hanzi":"特快列车","pinyin":"tèkuàilièchē","vi":"tàu tốc hành"},{"hanzi":"快车","pinyin":"kuàichē","vi":"tàu nhanh"},{"hanzi":"慢车","pinyin":"mànchē","vi":"tàu chậm"},{"hanzi":"高铁","pinyin":"gāotiě","vi":"tàu cao tốc"}]},{"id":"特刊","hanzi":"特刊","pinyin":"tèkān","meaning_vi":"ấn phẩm đặc biệt","explanation":"特 (đặc biệt/đặc sắc) + 刊 (ấn phẩm/đăng báo).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"📰","examples":[{"type":"basic","zh":"报社出版了奥运特刊。","pinyin":"Bàoshè chūbǎnle Àoyùn tèkān.","vi":"Tòa báo đã xuất bản số đặc biệt về Thế vận hội."},{"type":"simple","zh":"校报为百年校庆专门推出了一期纪念特刊。","pinyin":"Xiào bào wèi bǎinián xiàoqìng zhuānmén tuīchūle yì qī jìniàn tèkān.","vi":"Báo trường đã ra riêng một số đặc san kỷ niệm trăm năm thành lập trường."},{"type":"compound","zh":"虽然这本特刊价格不低，但是一上架就被抢购一空。","pinyin":"Suīrán zhè běn tèkān jiàgé bù dī, dànshì yí shàngjià jiù bèi qiǎnggòu yìkōng.","vi":"Tuy cuốn đặc san này giá không rẻ, nhưng vừa lên kệ đã bị mua sạch."}],"related":[{"hanzi":"特辑","pinyin":"tèjí","vi":"số đặc biệt"},{"hanzi":"期刊","pinyin":"qīkān","vi":"tạp chí định kỳ"},{"hanzi":"增刊","pinyin":"zēngkān","vi":"số phụ"},{"hanzi":"杂志","pinyin":"zázhì","vi":"tạp chí"}]},{"id":"特区","hanzi":"特区","pinyin":"tèqū","meaning_vi":"đặc khu (kinh tế)","explanation":"特 (đặc biệt/đặc sắc) + 区 (区).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-diem"],"image":"🏙️","examples":[{"type":"basic","zh":"深圳是经济特区。","pinyin":"Shēnzhèn shì jīngjìtèqū.","vi":"Thâm Quyến là đặc khu kinh tế."},{"type":"simple","zh":"香港特区政府今天发布了新的旅游政策。","pinyin":"Xiānggǎng tèqū zhèngfǔ jīntiān fābùle xīn de lǚyóu zhèngcè.","vi":"Chính quyền Đặc khu Hồng Kông hôm nay công bố chính sách du lịch mới."},{"type":"compound","zh":"自从设立特区以后，这个小渔村就迅速发展成了大都市。","pinyin":"Zìcóng shèlì tèqū yǐhòu, zhè ge xiǎo yú cūn jiù xùnsùfāzhǎn chéngle dàdūshì.","vi":"Từ khi thành lập đặc khu, làng chài nhỏ này nhanh chóng phát triển thành đô thị lớn."}],"related":[{"hanzi":"经济特区","pinyin":"jīngjìtèqū","vi":"đặc khu kinh tế"},{"hanzi":"深圳","pinyin":"Shēnzhèn","vi":"Thâm Quyến"},{"hanzi":"特别行政区","pinyin":"tèbié xíngzhèngqū","vi":"đặc khu hành chính"},{"hanzi":"开发区","pinyin":"kāifāqū","vi":"khu phát triển"}],"traditional":"特區"},{"id":"特使","hanzi":"特使","pinyin":"tèshǐ","meaning_vi":"đặc phái viên","explanation":"特 (đặc biệt/đặc sắc) + 使 (khiến cho).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"👔","examples":[{"type":"basic","zh":"总统派出了特使。","pinyin":"Zǒngtǒng pàichūle tèshǐ.","vi":"Tổng thống đã cử đặc phái viên."},{"type":"simple","zh":"联合国特使抵达首都，与各方展开对话。","pinyin":"Liánhéguó tèshǐ dǐdá shǒudū, yǔ gèfāng zhǎnkāi duìhuà.","vi":"Đặc phái viên Liên Hợp Quốc đến thủ đô và bắt đầu đối thoại với các bên."},{"type":"compound","zh":"因为局势紧张，所以政府紧急派遣特使前往调解。","pinyin":"Yīnwèi júshì jǐnzhāng, suǒyǐ zhèngfǔ jǐnjí pàiqiǎn tèshǐ qiánwǎng tiáojiě.","vi":"Vì tình hình căng thẳng nên chính phủ khẩn cấp cử đặc phái viên đến hòa giải."}],"related":[{"hanzi":"大使","pinyin":"dàshǐ","vi":"đại sứ"},{"hanzi":"使者","pinyin":"shǐzhě","vi":"sứ giả"},{"hanzi":"外交官","pinyin":"wàijiāoguān","vi":"nhà ngoại giao"},{"hanzi":"特派员","pinyin":"tèpàiyuán","vi":"đặc phái viên"}]},{"id":"特写","hanzi":"特写","pinyin":"tèxiě","meaning_vi":"cận cảnh (nhiếp ảnh, điện ảnh); bài đặc tả, phóng sự ngắn","explanation":"特 (đặc biệt/đặc sắc) + 写 (viết).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"📷","examples":[{"type":"basic","zh":"摄影师拍了个特写。","pinyin":"Shèyǐngshī pāile gè tèxiě.","vi":"Nhiếp ảnh gia đã chụp một tấm cận cảnh."},{"type":"simple","zh":"电影最后一个镜头是女主角眼泪的特写。","pinyin":"Diànyǐng zuìhòu yí gè jìngtóu shì nǚzhǔjué yǎnlèi de tèxiě.","vi":"Cảnh quay cuối của bộ phim là cận cảnh giọt nước mắt của nữ chính."},{"type":"compound","zh":"他不但拍了全景，而且给每道菜都拍了特写。","pinyin":"Tā búdàn pāile quánjǐng, érqiě gěi měi dào cài dōu pāile tèxiě.","vi":"Anh ấy không chỉ chụp toàn cảnh mà còn chụp cận cảnh từng món ăn."}],"related":[{"hanzi":"特写镜头","pinyin":"tèxiějìngtóu","vi":"cảnh quay cận"},{"hanzi":"近景","pinyin":"jìnjǐng","vi":"cận cảnh"},{"hanzi":"远景","pinyin":"yuǎnjǐng","vi":"viễn cảnh"},{"hanzi":"报道","pinyin":"bàodào","vi":"đưa tin"}],"traditional":"特寫"},{"id":"特质","hanzi":"特质","pinyin":"tèzhì","meaning_vi":"đặc chất, phẩm chất riêng biệt","explanation":"特 (đặc biệt/đặc sắc) + 质 (chất lượng/bản chất).","hsk_level":"7-9","tags":["danh-tu"],"image":"💎","examples":[{"type":"basic","zh":"耐心是好老师的特质。","pinyin":"Nàixīn shì hǎo lǎoshī de tèzhì.","vi":"Kiên nhẫn là phẩm chất riêng của một giáo viên giỏi."},{"type":"simple","zh":"这种葡萄酒带有当地土壤独特的矿物特质。","pinyin":"Zhè zhǒng pútaojiǔ dàiyǒu dāngdì tǔrǎng dútè de kuàngwù tèzhì.","vi":"Loại rượu vang này mang đặc chất khoáng độc đáo của thổ nhưỡng địa phương."},{"type":"compound","zh":"虽然兄弟俩长得很像，但是性格特质完全不同。","pinyin":"Suīrán xiōngdì liǎ zhǎngde hěn xiàng, dànshì xìnggé tèzhì wánquán bùtóng.","vi":"Tuy hai anh em trông rất giống nhau, nhưng đặc điểm tính cách hoàn toàn khác biệt."}],"related":[{"hanzi":"特性","pinyin":"tèxìng","vi":"đặc tính"},{"hanzi":"特点","pinyin":"tèdiǎn","vi":"đặc điểm"},{"hanzi":"气质","pinyin":"qìzhì","vi":"khí chất"},{"hanzi":"品质","pinyin":"pǐnzhì","vi":"phẩm chất"}],"traditional":"特質"},{"id":"腾飞","hanzi":"腾飞","pinyin":"téngfēi","meaning_vi":"cất cánh bay cao (kinh tế/sự nghiệp)","explanation":"腾 (bay vọt/sôi sục) + 飞 (飞).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🚀","examples":[{"type":"basic","zh":"这座城市正在腾飞。","pinyin":"Zhè zuò chéngshì zhèngzài téngfēi.","vi":"Thành phố này đang cất cánh."},{"type":"simple","zh":"改革开放以后，沿海地区的经济迅速腾飞。","pinyin":"Gǎigékāifàng yǐhòu, yánhǎi dìqū de jīngjì xùnsù téngfēi.","vi":"Sau cải cách mở cửa, kinh tế vùng duyên hải nhanh chóng cất cánh."},{"type":"compound","zh":"一旦高铁开通，这个山区小城的旅游业就会腾飞。","pinyin":"Yídàn gāotiě kāitōng, zhè ge shānqū xiǎochéng de lǚyóuyè jiù huì téngfēi.","vi":"Một khi đường sắt cao tốc thông tuyến, du lịch của thị trấn miền núi này sẽ cất cánh."}],"related":[{"hanzi":"起飞","pinyin":"qǐfēi","vi":"cất cánh"},{"hanzi":"飞跃","pinyin":"fēiyuè","vi":"bay vọt"},{"hanzi":"崛起","pinyin":"juéqǐ","vi":"trỗi dậy"},{"hanzi":"经济腾飞","pinyin":"jīngjìténgfēi","vi":"kinh tế cất cánh"}],"traditional":"騰飛"},{"id":"誊写","hanzi":"誊写","pinyin":"téngxiě","meaning_vi":"chép lại sạch đẹp","explanation":"誊 (chép lại) + 写 (viết).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"请把作文誊写一遍。","pinyin":"Qǐng bǎ zuòwén téngxiě yíbiàn.","vi":"Hãy chép sạch lại bài văn một lượt."},{"type":"simple","zh":"他用毛笔把草稿工工整整地誊写在宣纸上。","pinyin":"Tāyòng máobǐ bǎ cǎogǎo gōng gōngzhěng zhěngde téngxiě zài xuānzhǐ shàng.","vi":"Anh ấy dùng bút lông chép lại bản nháp thật ngay ngắn lên giấy Tuyên."},{"type":"compound","zh":"因为原稿涂改太多，所以老师让我重新誊写一份。","pinyin":"Yīnwèi yuángǎo túgǎi tài duō, suǒyǐ lǎoshī ràng wǒ chóngxīn téngxiě yí fèn.","vi":"Vì bản gốc tẩy xóa quá nhiều nên thầy bảo tôi chép sạch lại một bản."}],"related":[{"hanzi":"抄写","pinyin":"chāoxiě","vi":"sao chép"},{"hanzi":"誊抄","pinyin":"téngchāo","vi":"chép lại"},{"hanzi":"草稿","pinyin":"cǎogǎo","vi":"bản nháp"},{"hanzi":"书写","pinyin":"shūxiě","vi":"viết"}],"traditional":"謄寫"},{"id":"提名","hanzi":"提名","pinyin":"tímíng","meaning_vi":"đề cử (giải thưởng/ứng cử viên)","explanation":"提 (xách) + 名 (danh tiếng/nổi tiếng).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🏆","examples":[{"type":"basic","zh":"她获得了最佳女主角提名。","pinyin":"Tā huòdéle zuì jiā nǚzhǔjué tímíng.","vi":"Cô ấy nhận được đề cử Nữ chính xuất sắc nhất."},{"type":"simple","zh":"这部纪录片被提名为今年最佳外语片。","pinyin":"Zhè bù jìlùpiàn bèi tímíng wéi jīnnián zuì jiā wàiyǔ piàn.","vi":"Bộ phim tài liệu này được đề cử Phim nói tiếng nước ngoài hay nhất năm nay."},{"type":"compound","zh":"虽然他三次被提名，但是一次奖也没拿到。","pinyin":"Suīrán tā sāncì bèi tímíng, dànshì yí cì jiǎng yě méi nádào.","vi":"Tuy anh ấy ba lần được đề cử, nhưng chưa lần nào đoạt giải."}],"related":[{"hanzi":"候选人","pinyin":"hòuxuǎnrén","vi":"ứng cử viên"},{"hanzi":"提名奖","pinyin":"tímíngjiǎng","vi":"giải đề cử"},{"hanzi":"入围","pinyin":"rùwéi","vi":"lọt vào vòng"},{"hanzi":"推荐","pinyin":"tuījiàn","vi":"đề cử"}]},{"id":"提神","hanzi":"提神","pinyin":"tíshén","meaning_vi":"giúp tỉnh táo tinh thần (cà phê/trà)","explanation":"提 (xách) + 神 (thần kỳ/tinh thần).","hsk_level":"7-9","tags":["dong-tu","do-uong"],"image":"☕","examples":[{"type":"basic","zh":"咖啡可以提神。","pinyin":"Kāfēi kěyǐ tíshén.","vi":"Cà phê giúp tỉnh táo."},{"type":"simple","zh":"开长途车时，他总是嚼口香糖来提神。","pinyin":"Kāi chángtúchē shí, tā zǒngshì jiáo kǒuxiāngtáng lái tíshén.","vi":"Khi lái xe đường dài, anh ấy luôn nhai kẹo cao su cho tỉnh táo."},{"type":"compound","zh":"下午犯困的时候，与其喝咖啡提神，不如出去走一走。","pinyin":"Xiàwǔ fànkùn de shíhou, yǔqí hē kāfēi tíshén, bùrú chūqù zǒu yi zǒu.","vi":"Lúc buồn ngủ buổi chiều, thay vì uống cà phê cho tỉnh, chi bằng ra ngoài đi dạo một chút."}],"related":[{"hanzi":"醒神","pinyin":"xǐngshén","vi":"tỉnh táo"},{"hanzi":"咖啡","pinyin":"kāfēi","vi":"cà phê"},{"hanzi":"浓茶","pinyin":"nóngchá","vi":"trà đặc"},{"hanzi":"犯困","pinyin":"fànkùn","vi":"buồn ngủ"}]},{"id":"提速","hanzi":"提速","pinyin":"tísù","meaning_vi":"tăng tốc","explanation":"提 (xách) + 速 (nhanh chóng/tốc độ).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"⚡","examples":[{"type":"basic","zh":"火车又提速了。","pinyin":"Huǒchē yòu tísù le.","vi":"Tàu hỏa lại được tăng tốc rồi."},{"type":"simple","zh":"网络运营商宣布下个月起全面提速。","pinyin":"Wǎngluò yùnyíngshāng xuānbù xiàgèyuè qǐ quánmiàn tísù.","vi":"Nhà mạng thông báo từ tháng sau sẽ tăng tốc độ toàn diện."},{"type":"compound","zh":"只要项目审批提速，工厂就能提前半年投产。","pinyin":"Zhǐyào xiàngmù shěnpī tísù, gōngchǎng jiù néng tíqián bàn nián tóuchǎn.","vi":"Chỉ cần việc phê duyệt dự án được đẩy nhanh, nhà máy có thể đi vào sản xuất sớm nửa năm."}],"related":[{"hanzi":"加速","pinyin":"jiāsù","vi":"tăng tốc"},{"hanzi":"减速","pinyin":"jiǎnsù","vi":"giảm tốc"},{"hanzi":"提速降费","pinyin":"tísùjiàngfèi","vi":"tăng tốc giảm phí"},{"hanzi":"速度","pinyin":"sùdù","vi":"tốc độ"}]},{"id":"提心吊胆","hanzi":"提心吊胆","pinyin":"tíxīn-diàodǎn","meaning_vi":"nơm nớp lo sợ","explanation":"提心吊胆: xách tim lên, treo mật lên (提 đề – xách, 吊 điếu – treo, 胆 đảm – mật) → lúc nào cũng nơm nớp lo sợ, không yên lòng.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"😰","examples":[{"type":"basic","zh":"她整夜提心吊胆。","pinyin":"Tā zhěngyè tíxīndiàodǎn.","vi":"Cô ấy nơm nớp lo sợ suốt đêm."},{"type":"simple","zh":"妈妈提心吊胆地等着儿子从国外打来的电话。","pinyin":"Māma tíxīndiàodǎn de děngzhe érzi cóng guówài dǎ lái de diànhuà.","vi":"Mẹ thấp thỏm chờ cuộc gọi của con trai từ nước ngoài."},{"type":"compound","zh":"自从家里被盗以后，她一听到门外有动静就提心吊胆。","pinyin":"Zìcóng jiālǐ bèi dào yǐhòu, tā yì tīngdào ménwài yǒu dòngjing jiù tíxīndiàodǎn.","vi":"Từ khi nhà bị trộm, hễ nghe ngoài cửa có động tĩnh là cô ấy lại nơm nớp lo sợ."}],"related":[{"hanzi":"担惊受怕","pinyin":"dānjīngshòupà","vi":"lo sợ hãi hùng"},{"hanzi":"忐忑不安","pinyin":"tǎntèbù'ān","vi":"thấp thỏm bất an"},{"hanzi":"胆战心惊","pinyin":"dǎnzhànxīnjīng","vi":"kinh hồn bạt vía"},{"hanzi":"泰然自若","pinyin":"tàiránzìruò","vi":"điềm nhiên tự tại"}],"traditional":"提心吊膽"},{"id":"停工","hanzi":"停工","pinyin":"tínggōng","meaning_vi":"ngừng việc, ngừng thi công/sản xuất","explanation":"停 (đình – dừng) + 工 (công – công việc) → ngừng làm việc, ngừng thi công, ngừng sản xuất. Ví dụ: 停工停产. Bãi công (đình công) thì dùng 罢工.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚧","examples":[{"type":"basic","zh":"工地暂时停工了。","pinyin":"Gōngdì zànshí tínggōng le.","vi":"Công trường tạm thời ngừng thi công."},{"type":"simple","zh":"这家工厂已经连续停工了两个星期。","pinyin":"Zhè jiā gōngchǎng yǐjīng liánxù tínggōngle liǎng gè xīngqī.","vi":"Nhà máy này đã ngừng sản xuất liên tục hai tuần."},{"type":"compound","zh":"如果原材料迟迟不到，生产线就只能停工待料。","pinyin":"Rúguǒ yuáncáiliào chíchí búdào, shēngchǎnxiàn jiù zhǐnéng tínggōng dài liào.","vi":"Nếu nguyên liệu mãi không về, dây chuyền sản xuất chỉ có thể ngừng chờ nguyên liệu."}],"related":[{"hanzi":"开工","pinyin":"kāigōng","vi":"khởi công"},{"hanzi":"停产","pinyin":"tíngchǎn","vi":"ngừng sản xuất"},{"hanzi":"复工","pinyin":"fùgōng","vi":"trở lại làm việc"},{"hanzi":"罢工","pinyin":"bàgōng","vi":"đình công"}]},{"id":"停课","hanzi":"停课","pinyin":"tíngkè","meaning_vi":"nghỉ học, tạm dừng lên lớp","explanation":"停 (dừng) + 课 (bài học).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🏫","examples":[{"type":"basic","zh":"明天学校停课。","pinyin":"Míngtiān xuéxiào tíngkè.","vi":"Ngày mai trường cho nghỉ học."},{"type":"simple","zh":"暴雪导致全市中小学停课两天。","pinyin":"Bàoxuě dǎozhì quánshì zhōngxiǎoxué tíngkè liǎng tiān.","vi":"Bão tuyết khiến các trường phổ thông toàn thành phố nghỉ học hai ngày."},{"type":"compound","zh":"一旦气象台发布红色预警，学校就会立即停课。","pinyin":"Yídàn qìxiàngtái fābù hóngsè yùjǐng, xuéxiào jiù huì lìjí tíngkè.","vi":"Một khi đài khí tượng phát cảnh báo đỏ, trường học sẽ lập tức cho nghỉ học."}],"related":[{"hanzi":"上课","pinyin":"shàngkè","vi":"lên lớp"},{"hanzi":"复课","pinyin":"fùkè","vi":"đi học lại"},{"hanzi":"放假","pinyin":"fàngjià","vi":"nghỉ lễ"},{"hanzi":"网课","pinyin":"wǎngkè","vi":"học trực tuyến"}],"traditional":"停課"},{"id":"停业","hanzi":"停业","pinyin":"tíngyè","meaning_vi":"ngừng kinh doanh, đóng cửa tiệm","explanation":"停 (dừng) + 业 (sự nghiệp/ngành nghề).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔒","examples":[{"type":"basic","zh":"这家餐厅停业装修。","pinyin":"Zhè jiā cāntīng tíngyè zhuāngxiū.","vi":"Nhà hàng này tạm nghỉ kinh doanh để sửa sang."},{"type":"simple","zh":"那家老书店因为房租上涨而被迫停业。","pinyin":"Nà jiālǎo shūdiàn yīnwèi fángzū shàngzhǎng ér bèipò tíngyè.","vi":"Hiệu sách cũ đó buộc phải đóng cửa vì tiền thuê nhà tăng."},{"type":"compound","zh":"如果卫生检查不合格，饭店就会被责令停业整顿。","pinyin":"Rúguǒ wèishēng jiǎnchá bù hégé, fàndiàn jiù huì bèi zélìng tíngyè zhěngdùn.","vi":"Nếu kiểm tra vệ sinh không đạt, nhà hàng sẽ bị buộc ngừng kinh doanh để chấn chỉnh."}],"related":[{"hanzi":"营业","pinyin":"yíngyè","vi":"kinh doanh"},{"hanzi":"歇业","pinyin":"xiēyè","vi":"nghỉ kinh doanh"},{"hanzi":"关门","pinyin":"guānmén","vi":"đóng cửa"},{"hanzi":"开业","pinyin":"kāiyè","vi":"khai trương"}],"traditional":"停業"},{"id":"痛心","hanzi":"痛心","pinyin":"tòngxīn","meaning_vi":"đau lòng xót xa","explanation":"痛 (đau xót/quyết tâm) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["tinh-tu","cam-xuc"],"image":"💔","examples":[{"type":"basic","zh":"这个消息令人痛心。","pinyin":"Zhè ge xiāoxi lìngrén tòngxīn.","vi":"Tin này khiến người ta đau lòng."},{"type":"simple","zh":"看到森林被大火烧毁，村民们感到非常痛心。","pinyin":"Kàndào sēnlín bèi dàhuǒ shāohuǐ, cūnmínmen gǎndào fēicháng tòngxīn.","vi":"Thấy khu rừng bị lửa thiêu rụi, dân làng vô cùng xót xa."},{"type":"compound","zh":"父母最痛心的不是孩子考砸了，而是他撒了谎。","pinyin":"Fùmǔ zuì tòngxīn de bú shì háizi kǎozá le, érshì tā sāle huǎng.","vi":"Điều khiến bố mẹ đau lòng nhất không phải con thi hỏng, mà là con đã nói dối."}],"related":[{"hanzi":"伤心","pinyin":"shāngxīn","vi":"đau lòng"},{"hanzi":"心痛","pinyin":"xīntòng","vi":"đau lòng"},{"hanzi":"痛心疾首","pinyin":"tòngxīnjíshǒu","vi":"đau đớn căm giận"},{"hanzi":"惋惜","pinyin":"wǎnxī","vi":"tiếc nuối"}]},{"id":"透亮","hanzi":"透亮","pinyin":"tòuliàng","meaning_vi":"trong suốt sáng sủa","explanation":"透 (thấu đáo/tiết lộ) + 亮 (sáng).","hsk_level":"7-9","tags":["tinh-tu"],"image":"☀️","examples":[{"type":"basic","zh":"窗户擦得很透亮。","pinyin":"Chuānghu cā de hěn tòuliàng.","vi":"Cửa sổ được lau sáng bóng trong suốt."},{"type":"simple","zh":"雨后的湖水像玻璃一样透亮。","pinyin":"Yǔ hòu de húshuǐ xiàng bōli yíyàng tòuliàng.","vi":"Nước hồ sau mưa trong vắt như thủy tinh."},{"type":"compound","zh":"他这么一解释，我心里就透亮了，再也不纠结了。","pinyin":"Tā zhème yì jiěshì, wǒ xīnlǐ jiù tòuliàng le, zài yě bù jiū jiéle.","vi":"Anh ấy vừa giải thích như vậy, lòng tôi liền sáng tỏ, không còn băn khoăn nữa."}],"related":[{"hanzi":"透明","pinyin":"tòumíng","vi":"trong suốt"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"},{"hanzi":"晶莹","pinyin":"jīngyíng","vi":"óng ánh"},{"hanzi":"浑浊","pinyin":"húnzhuó","vi":"đục ngầu"}]},{"id":"透明度","hanzi":"透明度","pinyin":"tòumíngdù","meaning_vi":"độ minh bạch, độ trong suốt","explanation":"透 (thấu đáo/tiết lộ) + 明 (sáng suốt/rõ ràng) + 度 (度).","hsk_level":"7-9","tags":["danh-tu","cong-viec","khoa-hoc"],"image":"💎","examples":[{"type":"basic","zh":"政府要提高透明度。","pinyin":"Zhèngfǔ yào tígāo tòumíngdù.","vi":"Chính phủ cần nâng cao độ minh bạch."},{"type":"simple","zh":"这款新型玻璃的透明度比普通玻璃更高。","pinyin":"Zhè kuǎn xīnxíng bōli de tòumíngdù bǐ pǔtōng bōli gèng gāo.","vi":"Loại kính mới này có độ trong suốt cao hơn kính thường."},{"type":"compound","zh":"只要财务透明度够高，投资者就会更放心。","pinyin":"Zhǐyào cáiwù tòumíngdù gòu gāo, tóuzīzhě jiù huì gèng fàngxīn.","vi":"Chỉ cần tài chính đủ minh bạch, nhà đầu tư sẽ yên tâm hơn."}],"related":[{"hanzi":"透明","pinyin":"tòumíng","vi":"trong suốt, minh bạch"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"},{"hanzi":"信息公开","pinyin":"xìnxīgōngkāi","vi":"công khai thông tin"},{"hanzi":"暗箱操作","pinyin":"ànxiāngcāozuò","vi":"làm khuất tất"}]},{"id":"透明化","hanzi":"透明化","pinyin":"tòumínghuà","meaning_vi":"minh bạch hóa","explanation":"透 (thấu đáo/tiết lộ) + 明 (sáng suốt/rõ ràng) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"💎","examples":[{"type":"basic","zh":"收费标准应该透明化。","pinyin":"Shōufèi biāozhǔn yīnggāi tòumínghuà.","vi":"Mức thu phí cần được minh bạch hóa."},{"type":"simple","zh":"新规要求物业公司推进各项收费的透明化。","pinyin":"Xīnguī yāoqiú wùyè gōngsī tuījìn gè xiàng shōufèi de tòumínghuà.","vi":"Quy định mới yêu cầu công ty quản lý tòa nhà minh bạch hóa các khoản thu phí."},{"type":"compound","zh":"如果招标过程透明化，暗箱操作就很难发生。","pinyin":"Rúguǒ zhāobiāo guòchéng tòumínghuà, ànxiāngcāozuò jiù hěn nán fāshēng.","vi":"Nếu quá trình đấu thầu được minh bạch hóa thì rất khó xảy ra chuyện mờ ám."}],"related":[{"hanzi":"透明度","pinyin":"tòumíngdù","vi":"độ minh bạch"},{"hanzi":"公开化","pinyin":"gōngkāihuà","vi":"công khai hóa"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"quy chuẩn hóa"},{"hanzi":"公开","pinyin":"gōngkāi","vi":"công khai"}]},{"id":"透支","hanzi":"透支","pinyin":"tòuzhī","meaning_vi":"thấu chi, chi vượt (tiền); làm cạn kiệt, vắt kiệt (sức lực)","explanation":"透 + 支 (chi trả).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💳","examples":[{"type":"basic","zh":"他的信用卡透支了。","pinyin":"Tā de xìnyòngkǎ tòuzhī le.","vi":"Thẻ tín dụng của anh ấy đã bị thấu chi."},{"type":"simple","zh":"连续加班一个月，他的身体已经严重透支。","pinyin":"Liánxù jiābān yí gèyuè, tā de shēntǐ yǐjīng yánzhòng tòuzhī.","vi":"Tăng ca liên tục một tháng, cơ thể anh ấy đã kiệt sức nghiêm trọng."},{"type":"compound","zh":"如果你总是提前透支工资，月底就会过得很紧张。","pinyin":"Rúguǒ nǐ zǒngshì tíqián tòuzhī gōngzī, yuèdǐ jiù huì guòde hěn jǐnzhāng.","vi":"Nếu bạn luôn tiêu trước tiền lương, cuối tháng sẽ sống rất chật vật."}],"related":[{"hanzi":"信用卡","pinyin":"xìnyòngkǎ","vi":"thẻ tín dụng"},{"hanzi":"超支","pinyin":"chāozhī","vi":"chi vượt mức"},{"hanzi":"透支体力","pinyin":"tòuzhītǐlì","vi":"vắt kiệt sức"},{"hanzi":"欠款","pinyin":"qiànkuǎn","vi":"khoản nợ"}]},{"id":"同等","hanzi":"同等","pinyin":"tóngděng","meaning_vi":"ngang bằng, tương đương","explanation":"同 (đồng lòng/đồng bào) + 等 (đợi).","hsk_level":"7-9","tags":["tinh-tu"],"image":"⚖️","examples":[{"type":"basic","zh":"两者同等重要。","pinyin":"Liǎngzhě tóngděng zhòngyào.","vi":"Cả hai quan trọng ngang nhau."},{"type":"simple","zh":"新员工和老员工享受同等的带薪假期。","pinyin":"Xīn yuángōng hé lǎo yuángōng xiǎngshòu tóngděng de dàixīn jiàqī.","vi":"Nhân viên mới và nhân viên cũ được hưởng ngày nghỉ có lương như nhau."},{"type":"compound","zh":"只要学历同等，有工作经验的人就会被优先录用。","pinyin":"Zhǐyào xuélì tóngděng, yǒu gōngzuò jīngyàn de rén jiù huì bèi yōuxiān lùyòng.","vi":"Chỉ cần trình độ học vấn tương đương, người có kinh nghiệm làm việc sẽ được ưu tiên tuyển."}],"related":[{"hanzi":"相等","pinyin":"xiāngděng","vi":"bằng nhau"},{"hanzi":"同样","pinyin":"tóngyàng","vi":"như nhau"},{"hanzi":"平等","pinyin":"píngděng","vi":"bình đẳng"},{"hanzi":"同等学力","pinyin":"tóngděngxuélì","vi":"trình độ tương đương"}]},{"id":"同类","hanzi":"同类","pinyin":"tónglèi","meaning_vi":"cùng loại","explanation":"同 (đồng lòng/đồng bào) + 类 (loại hình/tương tự).","hsk_level":"7-9","tags":["danh-tu"],"image":"👯","examples":[{"type":"basic","zh":"这是同类产品中最便宜的。","pinyin":"Zhè shì tónglèi chǎnpǐn zhōng zuì piányi de.","vi":"Đây là cái rẻ nhất trong các sản phẩm cùng loại."},{"type":"simple","zh":"狼会发出嚎叫来召唤附近的同类。","pinyin":"Láng huì fāchū háojiào lái zhàohuàn fùjìn de tónglèi.","vi":"Sói tru lên để gọi đồng loại ở gần đó."},{"type":"compound","zh":"虽然价格比同类商品高一些，但是它的售后服务好得多。","pinyin":"Suīrán jiàgé bǐ tónglèi shāngpǐn gāo yìxiē, dànshì tā de shòuhòufúwù hǎo de duō.","vi":"Tuy giá cao hơn hàng cùng loại một chút, nhưng dịch vụ hậu mãi của nó tốt hơn nhiều."}],"related":[{"hanzi":"同行","pinyin":"tóngháng","vi":"cùng ngành"},{"hanzi":"同种","pinyin":"tóngzhǒng","vi":"cùng giống"},{"hanzi":"同类产品","pinyin":"tónglèichǎnpǐn","vi":"sản phẩm cùng loại"},{"hanzi":"异类","pinyin":"yìlèi","vi":"khác loại"}],"traditional":"同類"},{"id":"同龄人","hanzi":"同龄人","pinyin":"tónglíngrén","meaning_vi":"người cùng trang lứa","explanation":"同 (đồng lòng/đồng bào) + 龄 (龄) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👫","examples":[{"type":"basic","zh":"他比同龄人成熟。","pinyin":"Tā bǐ tónglíngrén chéngshú.","vi":"Cậu ấy chín chắn hơn bạn cùng trang lứa."},{"type":"simple","zh":"退休后，外公常去公园和同龄人下棋聊天。","pinyin":"Tuìxiū hòu, wàigōng cháng qù gōngyuán hé tónglíngrén xiàqí liáotiān.","vi":"Sau khi nghỉ hưu, ông ngoại thường ra công viên đánh cờ, trò chuyện với người cùng lứa."},{"type":"compound","zh":"看到同龄人都结婚了，她却一点也不着急。","pinyin":"Kàndào tónglíngrén dōu jiéhūn le, tā què yìdiǎn yě bù zháojí.","vi":"Thấy bạn cùng trang lứa đều đã lập gia đình, cô ấy lại chẳng sốt ruột chút nào."}],"related":[{"hanzi":"同龄","pinyin":"tónglíng","vi":"cùng tuổi"},{"hanzi":"同辈","pinyin":"tóngbèi","vi":"cùng thế hệ"},{"hanzi":"同学","pinyin":"tóngxué","vi":"bạn học"},{"hanzi":"年轻人","pinyin":"niánqīngrén","vi":"người trẻ"}],"traditional":"同齡人"},{"id":"同盟","hanzi":"同盟","pinyin":"tóngméng","meaning_vi":"đồng minh","explanation":"同 (đồng lòng/đồng bào) + 盟 (liên minh).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🤝","examples":[{"type":"basic","zh":"两国结成了同盟。","pinyin":"Liǎngguó jié chéngle tóngméng.","vi":"Hai nước đã kết thành đồng minh."},{"type":"simple","zh":"几个小国组成军事同盟来共同防御外敌。","pinyin":"Jǐ gè xiǎo guó zǔchéng jūnshì tóngméng lái gòngtóng fángyù wài dí.","vi":"Mấy nước nhỏ lập liên minh quân sự để cùng chống ngoại xâm."},{"type":"compound","zh":"虽然两家公司是竞争对手，但是在这件事上结成了同盟。","pinyin":"Suīrán liǎng jiā gōngsī shì jìngzhēng duìshǒu, dànshì zài zhè jiàn shì shàng jié chéngle tóngméng.","vi":"Tuy hai công ty là đối thủ cạnh tranh, nhưng trong việc này họ đã trở thành đồng minh."}],"related":[{"hanzi":"联盟","pinyin":"liánméng","vi":"liên minh"},{"hanzi":"盟友","pinyin":"méngyǒu","vi":"đồng minh"},{"hanzi":"结盟","pinyin":"jiéméng","vi":"kết đồng minh"},{"hanzi":"敌人","pinyin":"dírén","vi":"kẻ thù"}]},{"id":"铜牌","hanzi":"铜牌","pinyin":"tóngpái","meaning_vi":"huy chương đồng","explanation":"铜 (đồng – kim loại đồng) + 牌 (bài – tấm thẻ, huy chương) → huy chương đồng, giải ba. Cùng nhóm: 金牌, 银牌.","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🥉","examples":[{"type":"basic","zh":"她拿到了一枚铜牌。","pinyin":"Tā nádàole yìméi tóngpái.","vi":"Cô ấy giành được một huy chương đồng."},{"type":"simple","zh":"中国选手在男子跳远比赛中获得铜牌。","pinyin":"Zhōngguó xuǎnshǒu zài nánzǐ tiàoyuǎn bǐsài zhōng huòdé tóngpái.","vi":"Vận động viên Trung Quốc giành huy chương đồng nội dung nhảy xa nam."},{"type":"compound","zh":"虽然只得了铜牌，但是这已经是他个人的最好成绩了。","pinyin":"Suīrán zhǐ déle tóngpái, dànshì zhè yǐjīng shì tā gèrén de zuìhǎo chéngjì le.","vi":"Tuy chỉ giành huy chương đồng, nhưng đó đã là thành tích tốt nhất của cá nhân anh ấy."}],"related":[{"hanzi":"金牌","pinyin":"jīnpái","vi":"huy chương vàng"},{"hanzi":"银牌","pinyin":"yínpái","vi":"huy chương bạc"},{"hanzi":"奖牌","pinyin":"jiǎngpái","vi":"huy chương"},{"hanzi":"季军","pinyin":"jìjūn","vi":"hạng ba"}],"traditional":"銅牌"},{"id":"同情心","hanzi":"同情心","pinyin":"tóngqíngxīn","meaning_vi":"lòng trắc ẩn, sự đồng cảm","explanation":"同 (đồng lòng/đồng bào) + 情 (tình cảm/tình hình) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","con-nguoi"],"image":"💖","examples":[{"type":"basic","zh":"他很有同情心。","pinyin":"Tā hěn yǒu tóngqíngxīn.","vi":"Anh ấy rất giàu lòng trắc ẩn."},{"type":"simple","zh":"这部电影激发了观众对流浪动物的同情心。","pinyin":"Zhè bù diànyǐng jīfāle guānzhòng duì liúlàng dòngwù de tóngqíngxīn.","vi":"Bộ phim này khơi dậy lòng trắc ẩn của khán giả với động vật lang thang."},{"type":"compound","zh":"骗子正是利用人们的同情心，才骗走了那么多善款。","pinyin":"Piànzi zhèngshì lìyòng rénmen de tóngqíngxīn, cái piànzǒule nàme duō shànkuǎn.","vi":"Chính vì lợi dụng lòng trắc ẩn của mọi người mà kẻ lừa đảo mới lừa được nhiều tiền từ thiện đến thế."}],"related":[{"hanzi":"同情","pinyin":"tóngqíng","vi":"thông cảm"},{"hanzi":"怜悯","pinyin":"liánmǐn","vi":"thương xót"},{"hanzi":"爱心","pinyin":"àixīn","vi":"lòng yêu thương"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh nhạt"}]},{"id":"同日而语","hanzi":"同日而语","pinyin":"tóngrì-éryǔ","meaning_vi":"đánh đồng ngang nhau (thường dùng phủ định: 不可同日而语)","explanation":"同 (đồng lòng/đồng bào) + 日 (ngày) + 而 (mà) + 语 (ngôn ngữ/lời nói).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"两者不可同日而语。","pinyin":"Liǎngzhě bùkě tóngrì'éryǔ.","vi":"Hai thứ không thể đánh đồng với nhau."},{"type":"simple","zh":"如今的手机性能已经和十年前不可同日而语。","pinyin":"Rújīn de shǒujī xìngnéng yǐjīng hé shí niánqián bùkě tóngrì'éryǔ.","vi":"Hiệu năng điện thoại ngày nay đã không thể so sánh với mười năm trước."},{"type":"compound","zh":"虽然都是小吃店，但是这家的口味和路边摊不能同日而语。","pinyin":"Suīrán dōu shì xiǎochīdiàn, dànshì zhè jiā de kǒuwèi hé lùbiāntān bù néng tóngrì'éryǔ.","vi":"Tuy đều là quán ăn vặt, nhưng hương vị quán này không thể đánh đồng với hàng rong ven đường."}],"related":[{"hanzi":"相提并论","pinyin":"xiāngtíbìnglùn","vi":"đánh đồng"},{"hanzi":"不可同日而语","pinyin":"bùkě tóngrì'éryǔ","vi":"không thể đánh đồng"},{"hanzi":"等量齐观","pinyin":"děngliàngqíguān","vi":"coi như nhau"},{"hanzi":"天壤之别","pinyin":"tiānrǎngzhībié","vi":"khác nhau một trời một vực"}],"traditional":"同日而語"},{"id":"同义词","hanzi":"同义词","pinyin":"tóngyìcí","meaning_vi":"từ đồng nghĩa","explanation":"同 (đồng lòng/đồng bào) + 义 (chính nghĩa/ý nghĩa) + 词 (词).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"👯","examples":[{"type":"basic","zh":"美丽和漂亮是同义词。","pinyin":"Měilì hé piàoliang shì tóngyìcí.","vi":"Mỹ lệ và xinh đẹp là từ đồng nghĩa."},{"type":"simple","zh":"这本词典列出了每个常用词的同义词和反义词。","pinyin":"Zhè běn cídiǎn lièchūle měi gè cháng yòngcí de tóngyìcí hé fǎnyìcí.","vi":"Cuốn từ điển này liệt kê từ đồng nghĩa và trái nghĩa của mỗi từ thông dụng."},{"type":"compound","zh":"虽然这两个词是同义词，但是用法上还有细微的差别。","pinyin":"Suīrán zhè liǎng gè cí shì tóngyìcí, dànshì yòngfǎ shàng háiyǒu xìwēi de chābié.","vi":"Tuy hai từ này là từ đồng nghĩa, nhưng về cách dùng vẫn có khác biệt nhỏ."}],"related":[{"hanzi":"反义词","pinyin":"fǎnyìcí","vi":"từ trái nghĩa"},{"hanzi":"近义词","pinyin":"jìnyìcí","vi":"từ gần nghĩa"},{"hanzi":"词汇","pinyin":"cíhuì","vi":"từ vựng"},{"hanzi":"多义词","pinyin":"duōyìcí","vi":"từ đa nghĩa"}],"traditional":"同義詞"},{"id":"投奔","hanzi":"投奔","pinyin":"tóubèn","meaning_vi":"tìm đến nương tựa","explanation":"投 (đầu tư/bỏ phiếu) + 奔 (chạy nhanh/bôn ba).","hsk_level":"7-9","tags":["dong-tu"],"image":"🏃","examples":[{"type":"basic","zh":"他去城里投奔舅舅。","pinyin":"Tā qù chénglǐ tóubèn jiùjiu.","vi":"Anh ấy lên thành phố nương nhờ cậu."},{"type":"simple","zh":"战乱时，许多难民翻山越岭投奔邻国的亲戚。","pinyin":"Zhànluàn shí, xǔduō nànmín fān shān yuè lǐng tóubèn Línguó de qīnqi.","vi":"Thời loạn lạc, nhiều người tị nạn vượt núi băng đèo tìm đến họ hàng ở nước láng giềng nương tựa."},{"type":"compound","zh":"因为在老家找不到工作，所以他只好去深圳投奔同学。","pinyin":"Yīnwèi zài lǎojiā zhǎobúdào gōngzuò, suǒyǐ tā zhǐhǎo qù Shēnzhèn tóubèn tóngxué.","vi":"Vì ở quê không tìm được việc nên anh ấy đành lên Thâm Quyến nương nhờ bạn học."}],"related":[{"hanzi":"投靠","pinyin":"tóukào","vi":"nương nhờ"},{"hanzi":"依靠","pinyin":"yīkào","vi":"dựa vào"},{"hanzi":"寄人篱下","pinyin":"jìrénlíxià","vi":"ăn nhờ ở đậu"},{"hanzi":"收留","pinyin":"shōuliú","vi":"cưu mang"}]},{"id":"头等","hanzi":"头等","pinyin":"tóuděng","meaning_vi":"hạng nhất, hàng đầu (头等舱 - khoang hạng nhất)","explanation":"头 (đứng đầu/mạch lạc) + 等 (đợi).","hsk_level":"7-9","tags":["tinh-tu","giao-thong"],"image":"🥇","examples":[{"type":"basic","zh":"这是头等大事。","pinyin":"Zhè shì tóuděng dàshì.","vi":"Đây là việc lớn hàng đầu."},{"type":"simple","zh":"老板给我们订了飞往伦敦的头等舱机票。","pinyin":"Lǎobǎn gěi wǒmen dìngle fēiwǎng Lúndūn de tóuděngcāng jīpiào.","vi":"Sếp đặt cho chúng tôi vé khoang hạng nhất bay đi London."},{"type":"compound","zh":"既然安全是头等大事，就不能为了赶工期而省掉检查。","pinyin":"Jìrán ānquán shì tóuděng dàshì, jiù bù néng wèile gǎn gōngqī ér shěng diào jiǎnchá.","vi":"Đã coi an toàn là việc hàng đầu thì không thể vì kịp tiến độ mà bỏ qua kiểm tra."}],"related":[{"hanzi":"头等舱","pinyin":"tóuděngcāng","vi":"khoang hạng nhất"},{"hanzi":"经济舱","pinyin":"jīngjìcāng","vi":"khoang phổ thông"},{"hanzi":"一流","pinyin":"yìliú","vi":"hạng nhất"},{"hanzi":"头等大事","pinyin":"tóuděngdàshì","vi":"việc lớn hàng đầu"}],"traditional":"頭等"},{"id":"投稿","hanzi":"投稿","pinyin":"tóugǎo","meaning_vi":"gửi bài đăng báo/tạp chí","explanation":"投 (đầu tư/bỏ phiếu) + 稿 (bản thảo).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"✉️","examples":[{"type":"basic","zh":"他常给杂志投稿。","pinyin":"Tā cháng gěi zázhì tóugǎo.","vi":"Anh ấy thường gửi bài cho tạp chí."},{"type":"simple","zh":"她把自己的旅行散文投稿到了一家文学刊物。","pinyin":"Tā bǎ zìjǐ de lǚxíng sǎnwén tóugǎo dàole yìjiā wénxué kānwù.","vi":"Cô ấy gửi bài tản văn du lịch của mình đến một tạp chí văn học."},{"type":"compound","zh":"虽然投稿被退回了五次，但是他依然坚持写作。","pinyin":"Suīrán tóugǎo bèi tuìhuíle wǔ cì, dànshì tā yīrán jiānchí xiězuò.","vi":"Tuy bài gửi bị trả lại năm lần, nhưng anh ấy vẫn kiên trì viết."}],"related":[{"hanzi":"稿件","pinyin":"gǎojiàn","vi":"bản thảo"},{"hanzi":"编辑","pinyin":"biānjí","vi":"biên tập viên"},{"hanzi":"发表","pinyin":"fābiǎo","vi":"đăng tải"},{"hanzi":"稿费","pinyin":"gǎofèi","vi":"nhuận bút"}]},{"id":"头脑","hanzi":"头脑","pinyin":"tóunǎo","meaning_vi":"đầu óc, tư duy","explanation":"头 (đứng đầu/mạch lạc) + 脑 (đầu óc).","hsk_level":"7-9","tags":["danh-tu","nhan-thuc"],"image":"🧠","examples":[{"type":"basic","zh":"他很有商业头脑。","pinyin":"Tā hěn yǒu shāngyè tóunǎo.","vi":"Anh ấy rất có đầu óc kinh doanh."},{"type":"simple","zh":"遇到突发情况时，她总能保持清醒的头脑。","pinyin":"Yùdào tūfā qíngkuàng shí, tā zǒngnéng bǎochí qīngxǐng de tóunǎo.","vi":"Khi gặp tình huống bất ngờ, cô ấy luôn giữ được đầu óc tỉnh táo."},{"type":"compound","zh":"一听说股票要大涨，他就头脑发热，把积蓄全投了进去。","pinyin":"Yì tīngshuō gǔpiào yào dà zhǎng, tā jiù tóunǎo fārè, bǎ jīxù quán tóule jìnqù.","vi":"Vừa nghe nói cổ phiếu sắp tăng mạnh, anh ta liền nóng đầu, dồn hết tiền tiết kiệm vào."}],"related":[{"hanzi":"大脑","pinyin":"dànǎo","vi":"não bộ"},{"hanzi":"头脑清醒","pinyin":"tóunǎoqīngxǐng","vi":"đầu óc tỉnh táo"},{"hanzi":"思维","pinyin":"sīwéi","vi":"tư duy"},{"hanzi":"没头脑","pinyin":"méitóunǎo","vi":"không có đầu óc"}],"traditional":"頭腦"},{"id":"投身","hanzi":"投身","pinyin":"tóushēn","meaning_vi":"dấn thân vào (sự nghiệp/nghiên cứu)","explanation":"投 (đầu tư/bỏ phiếu) + 身 (thân phận/tự thân).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"他投身于教育事业。","pinyin":"Tā tóushēn yú jiàoyù shìyè.","vi":"Ông ấy dấn thân vào sự nghiệp giáo dục."},{"type":"simple","zh":"大学毕业后，她毅然投身到乡村医疗工作中。","pinyin":"Dàxué bìyè hòu, tā yìrán tóushēn dào xiāngcūn yīliáo gōngzuò zhōng.","vi":"Tốt nghiệp đại học, cô ấy kiên quyết dấn thân vào công tác y tế nông thôn."},{"type":"compound","zh":"虽然投身科研收入不高，但是他从来没有后悔过。","pinyin":"Suīrán tóushēn kēyán shōurù bù gāo, dànshì tā cónglái méiyǒu hòuhuǐ guo.","vi":"Tuy dấn thân vào nghiên cứu khoa học thu nhập không cao, nhưng anh ấy chưa bao giờ hối hận."}],"related":[{"hanzi":"投入","pinyin":"tóurù","vi":"dồn vào"},{"hanzi":"献身","pinyin":"xiànshēn","vi":"hiến thân"},{"hanzi":"致力于","pinyin":"zhìlìyú","vi":"dốc sức vào"},{"hanzi":"从事","pinyin":"cóngshì","vi":"làm nghề"}]},{"id":"投诉率","hanzi":"投诉率","pinyin":"tóusùlǜ","meaning_vi":"tỷ lệ khiếu nại","explanation":"投 (đầu tư/bỏ phiếu) + 诉 (tố tụng/kể lể) + 率 (dẫn dắt/tỷ lệ).","hsk_level":"7-9","tags":["danh-tu","cong-viec","so-luong"],"image":"📞","examples":[{"type":"basic","zh":"本月投诉率下降了。","pinyin":"Běnyuè tóusùlǜ xiàjiàng le.","vi":"Tỷ lệ khiếu nại tháng này đã giảm."},{"type":"simple","zh":"这家航空公司的投诉率在行业中排名最低。","pinyin":"Zhè jiā hángkōng gōngsī de tóusùlǜ zài hángyè zhōng páimíng zuì dī.","vi":"Hãng hàng không này có tỷ lệ khiếu nại thấp nhất ngành."},{"type":"compound","zh":"自从改进了客服流程，门店的投诉率就明显降低了。","pinyin":"Zìcóng gǎijìnle kèfú liúchéng, méndiàn de tóusùlǜ jiù míngxiǎn jiàngdī le.","vi":"Từ khi cải tiến quy trình chăm sóc khách hàng, tỷ lệ khiếu nại của cửa hàng giảm rõ rệt."}],"related":[{"hanzi":"投诉","pinyin":"tóusù","vi":"khiếu nại"},{"hanzi":"满意度","pinyin":"mǎnyìdù","vi":"mức độ hài lòng"},{"hanzi":"客服","pinyin":"kèfú","vi":"chăm sóc khách hàng"},{"hanzi":"好评率","pinyin":"hǎopínglǜ","vi":"tỷ lệ đánh giá tốt"}],"traditional":"投訴率"},{"id":"头衔","hanzi":"头衔","pinyin":"tóuxián","meaning_vi":"chức danh, học hàm/danh hiệu","explanation":"头 (đứng đầu/mạch lạc) + 衔 (nối tiếp/chức hàm).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👑","examples":[{"type":"basic","zh":"他有很多头衔。","pinyin":"Tā yǒu hěn duō tóuxián.","vi":"Ông ấy có rất nhiều danh hiệu."},{"type":"simple","zh":"名片上印着教授、院长等一长串头衔。","pinyin":"Míngpiàn shàng yìnzhe jiàoshòu, yuànzhǎng děng yì cháng chuàn tóuxián.","vi":"Trên danh thiếp in một loạt chức danh như giáo sư, viện trưởng."},{"type":"compound","zh":"与其追求响亮的头衔，不如踏踏实实提升自己的能力。","pinyin":"Yǔqí zhuīqiú xiǎngliàng de tóuxián, bùrú tā tāshí shí tíshēng zìjǐ de nénglì.","vi":"Thay vì chạy theo những danh hiệu kêu vang, chi bằng chăm chỉ nâng cao năng lực bản thân."}],"related":[{"hanzi":"职称","pinyin":"zhíchēng","vi":"chức danh nghề nghiệp"},{"hanzi":"称号","pinyin":"chēnghào","vi":"danh hiệu"},{"hanzi":"学位","pinyin":"xuéwèi","vi":"học vị"},{"hanzi":"职位","pinyin":"zhíwèi","vi":"chức vị"}],"traditional":"頭銜"},{"id":"徒步","hanzi":"徒步","pinyin":"túbù","meaning_vi":"đi bộ, đi bộ đường dài","explanation":"徒 (uổng công/đồ đệ) + 步 (bước đi/tiến bộ).","hsk_level":"7-9","tags":["dong-tu","du-lich","the-thao"],"image":"🥾","examples":[{"type":"basic","zh":"我们徒步穿越了峡谷。","pinyin":"Wǒmen túbù chuānyuèle xiágǔ.","vi":"Chúng tôi đi bộ băng qua hẻm núi."},{"type":"simple","zh":"他花了一个月时间徒步走完了整条古道。","pinyin":"Tā huāle yí gèyuè shíjiān túbù zǒu wánle zhěngtiáo gǔdào.","vi":"Anh ấy mất một tháng để đi bộ hết cả con đường cổ."},{"type":"compound","zh":"如果你打算去高原徒步，就要提前适应海拔。","pinyin":"Rúguǒ nǐ dǎsuàn qù gāoyuán túbù, jiùyào tíqián shìyìng hǎibá.","vi":"Nếu bạn định đi trekking trên cao nguyên thì phải thích nghi với độ cao từ trước."}],"related":[{"hanzi":"步行","pinyin":"bùxíng","vi":"đi bộ"},{"hanzi":"徒步旅行","pinyin":"túbùlǚxíng","vi":"du lịch đi bộ"},{"hanzi":"登山","pinyin":"dēngshān","vi":"leo núi"},{"hanzi":"远足","pinyin":"yuǎnzú","vi":"đi bộ đường dài"}]},{"id":"图画","hanzi":"图画","pinyin":"túhuà","meaning_vi":"tranh vẽ","explanation":"图 (mưu đồ/bản đồ) + 画 (画).","hsk_level":"7-9","tags":["danh-tu","giai-tri"],"image":"🎨","examples":[{"type":"basic","zh":"墙上挂着一幅图画。","pinyin":"Qiáng shàng guàzhe yì fú túhuà.","vi":"Trên tường treo một bức tranh."},{"type":"simple","zh":"这本绘本用彩色图画讲述了小熊过冬的故事。","pinyin":"Zhè běn huìběn yòng cǎisè túhuà jiǎngshùle xiǎo Xióng guòdōng de gùshi.","vi":"Cuốn truyện tranh này dùng tranh màu kể câu chuyện chú gấu nhỏ qua mùa đông."},{"type":"compound","zh":"因为弟弟还不认字，所以他只看书里的图画。","pinyin":"Yīnwèi dìdi hái bú rènzì, suǒyǐ tā zhǐ kànshū lǐ de túhuà.","vi":"Vì em trai chưa biết chữ nên nó chỉ xem tranh trong sách."}],"related":[{"hanzi":"图片","pinyin":"túpiàn","vi":"hình ảnh"},{"hanzi":"画儿","pinyin":"huàr","vi":"tranh"},{"hanzi":"绘画","pinyin":"huìhuà","vi":"hội họa"},{"hanzi":"插图","pinyin":"chātú","vi":"tranh minh họa"}],"traditional":"圖畫"},{"id":"徒手","hanzi":"徒手","pinyin":"túshǒu","meaning_vi":"tay không","explanation":"徒 (uổng công/đồ đệ) + 手 (thủ pháp/tay nghề).","hsk_level":"7-9","tags":["pho-tu","the-thao"],"image":"✊","examples":[{"type":"basic","zh":"他徒手抓住了鱼。","pinyin":"Tā túshǒu zhuāzhùle yú.","vi":"Anh ấy bắt được cá bằng tay không."},{"type":"simple","zh":"那位攀岩高手不带任何保护徒手爬上了悬崖。","pinyin":"Nà wèi pānyán gāoshǒu búdài rènhé bǎohù túshǒu páshàngle xuányá.","vi":"Tay leo núi cừ khôi đó leo tay không lên vách đá mà không có bất kỳ đồ bảo hộ nào."},{"type":"compound","zh":"即使没有工具，他也能徒手把坏掉的水管拧紧。","pinyin":"Jíshǐ méiyǒu gōngjù, tā yě néng túshǒu bǎ huàidiào de shuǐguǎn nǐngjǐn.","vi":"Dù không có dụng cụ, anh ấy vẫn có thể vặn chặt ống nước hỏng bằng tay không."}],"related":[{"hanzi":"空手","pinyin":"kōngshǒu","vi":"tay không"},{"hanzi":"赤手空拳","pinyin":"chìshǒukōngquán","vi":"tay không tấc sắt"},{"hanzi":"徒手攀岩","pinyin":"túshǒupānyán","vi":"leo vách tay không"},{"hanzi":"工具","pinyin":"gōngjù","vi":"công cụ"}]},{"id":"图腾","hanzi":"图腾","pinyin":"túténg","meaning_vi":"vật tổ (totem)","explanation":"图 (mưu đồ/bản đồ) + 腾 (bay vọt/sôi sục).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🗿","examples":[{"type":"basic","zh":"龙是中华民族的图腾。","pinyin":"Lóng shì Zhōnghuámínzú de túténg.","vi":"Rồng là vật tổ của dân tộc Trung Hoa."},{"type":"simple","zh":"部落门口立着一根雕刻着鹰头的图腾柱。","pinyin":"Bùluò ménkǒu lìzhe yìgēn diāokèzhe yīng tóu de túténg zhù.","vi":"Trước cổng bộ lạc dựng một cột vật tổ chạm hình đầu chim ưng."},{"type":"compound","zh":"虽然这些图腾看起来很神秘，但是每个图案都有具体含义。","pinyin":"Suīrán zhèxiē túténg kànqǐlái hěn shénmì, dànshì měi gè tú'àn dōu yǒu jùtǐ hányì.","vi":"Tuy những vật tổ này trông rất thần bí, nhưng mỗi họa tiết đều có ý nghĩa cụ thể."}],"related":[{"hanzi":"崇拜","pinyin":"chóngbài","vi":"sùng bái"},{"hanzi":"部落","pinyin":"bùluò","vi":"bộ lạc"},{"hanzi":"象征","pinyin":"xiàngzhēng","vi":"biểu tượng"},{"hanzi":"龙","pinyin":"lóng","vi":"rồng"}],"traditional":"圖騰"},{"id":"图形","hanzi":"图形","pinyin":"túxíng","meaning_vi":"đồ họa, hình vẽ","explanation":"图 (mưu đồ/bản đồ) + 形 (hình thái/hình thành).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","hoc-tap"],"image":"📐","examples":[{"type":"basic","zh":"请画一个对称图形。","pinyin":"Qǐng huà yí gè duìchèn túxíng.","vi":"Hãy vẽ một hình đối xứng."},{"type":"simple","zh":"这款软件可以把数据自动转换成直观的图形。","pinyin":"Zhè kuǎn ruǎnjiàn kěyǐ bǎ shùjù zìdòng zhuǎn huànchéng zhíguān de túxíng.","vi":"Phần mềm này có thể tự động chuyển dữ liệu thành đồ họa trực quan."},{"type":"compound","zh":"如果电脑显卡太旧，复杂的三维图形就会显示得很慢。","pinyin":"Rúguǒ diànnǎo xiǎnkǎ tài jiù, fùzá de sānwéi túxíng jiù huì xiǎnshì de hěn màn.","vi":"Nếu card đồ họa của máy tính quá cũ, hình ảnh ba chiều phức tạp sẽ hiển thị rất chậm."}],"related":[{"hanzi":"图案","pinyin":"tú'àn","vi":"hoa văn"},{"hanzi":"图表","pinyin":"túbiǎo","vi":"biểu đồ"},{"hanzi":"形状","pinyin":"xíngzhuàng","vi":"hình dạng"},{"hanzi":"几何图形","pinyin":"jǐhétúxíng","vi":"hình hình học"}],"traditional":"圖形"},{"id":"贪官","hanzi":"贪官","pinyin":"tānguān","meaning_vi":"quan tham","explanation":"贪 (tham lam) + 官 (quan chức).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","phap-luat"],"image":"⚠️","examples":[{"type":"basic","zh":"那个贪官被抓了。","pinyin":"Nà ge tānguān bèi zhuā le.","vi":"Tên quan tham đó đã bị bắt."},{"type":"simple","zh":"老百姓最痛恨的就是收受贿赂的贪官。","pinyin":"Lǎobǎixìng zuì tònghèn de jiùshì shōushòu huìlù de tānguān.","vi":"Điều dân chúng căm ghét nhất chính là những quan tham nhận hối lộ."},{"type":"compound","zh":"只要发现贪官，检察机关就会依法严惩。","pinyin":"Zhǐyào fāxiàn tānguān, jiǎnchá jīguān jiù huì yīfǎ yánchéng.","vi":"Hễ phát hiện quan tham, cơ quan kiểm sát sẽ trừng trị nghiêm theo pháp luật."}],"related":[{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"腐败","pinyin":"fǔbài","vi":"hủ bại tham nhũng"},{"hanzi":"清官","pinyin":"qīngguān","vi":"quan thanh liêm"},{"hanzi":"反腐","pinyin":"fǎnfǔ","vi":"chống tham nhũng"}],"traditional":"貪官"},{"id":"贪图","hanzi":"贪图","pinyin":"tāntú","meaning_vi":"tham lam mưu cầu (hưởng thụ/lợi nhỏ)","explanation":"贪 (tham lam) + 图 (mưu đồ/bản đồ).","hsk_level":"7-9","tags":["dong-tu"],"image":"🤑","examples":[{"type":"basic","zh":"别贪图小便宜。","pinyin":"Bié tāntú xiǎopiányi.","vi":"Đừng ham lợi nhỏ."},{"type":"simple","zh":"他为了贪图安逸而放弃了出国深造的机会。","pinyin":"Tā wèile tāntú ānyì ér fàngqìle chūguó shēnzào de jīhuì.","vi":"Vì ham an nhàn mà anh ấy đã bỏ lỡ cơ hội ra nước ngoài học lên."},{"type":"compound","zh":"如果贪图便宜买假货，最后吃亏的还是自己。","pinyin":"Rúguǒ tāntú piányi mǎi jiǎhuò, zuìhòu chīkuī de háishì zìjǐ.","vi":"Nếu ham rẻ mà mua hàng giả thì cuối cùng người chịu thiệt vẫn là mình."}],"related":[{"hanzi":"贪心","pinyin":"tānxīn","vi":"tham lam"},{"hanzi":"贪图享受","pinyin":"tāntúxiǎngshòu","vi":"ham hưởng thụ"},{"hanzi":"贪便宜","pinyin":"tānpiányi","vi":"ham rẻ"},{"hanzi":"图","pinyin":"tú","vi":"mưu cầu"}],"traditional":"貪圖"},{"id":"掏钱","hanzi":"掏钱","pinyin":"tāoqián","meaning_vi":"móc tiền trả","explanation":"掏 (móc túi/đào) + 钱 (钱).","hsk_level":"7-9","tags":["dong-tu","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"这顿饭我掏钱。","pinyin":"Zhè dùn fàn wǒ tāoqián.","vi":"Bữa này để tôi trả tiền."},{"type":"simple","zh":"他从口袋里掏钱给路边的老人买了碗面。","pinyin":"Tā cóng kǒudài lǐ tāoqián gěi lùbiān de lǎorén mǎile wǎn miàn.","vi":"Anh ấy móc tiền trong túi mua cho cụ già bên đường một bát mì."},{"type":"compound","zh":"一说到要掏钱，刚才还很热情的几个人就都不吭声了。","pinyin":"Yì shuōdào yào tāoqián, gāngcái hái hěn rèqíng de jǐ gè rén jiù dōu bù kēngshēng le.","vi":"Vừa nhắc đến chuyện phải bỏ tiền ra, mấy người vừa nãy còn hăng hái liền im bặt."}],"related":[{"hanzi":"付钱","pinyin":"fùqián","vi":"trả tiền"},{"hanzi":"出钱","pinyin":"chūqián","vi":"bỏ tiền"},{"hanzi":"掏腰包","pinyin":"tāoyāobāo","vi":"móc hầu bao"},{"hanzi":"买单","pinyin":"mǎidān","vi":"thanh toán"}],"traditional":"掏錢"},{"id":"剔除","hanzi":"剔除","pinyin":"tīchú","meaning_vi":"loại bỏ, gạt bỏ","explanation":"剔 (lọc bỏ/khêu) + 除 (loại trừ/ngoài ra).","hsk_level":"7-9","tags":["dong-tu"],"image":"✂️","examples":[{"type":"basic","zh":"请剔除无效数据。","pinyin":"Qǐng tīchú wúxiào shùjù.","vi":"Hãy loại bỏ dữ liệu không hợp lệ."},{"type":"simple","zh":"妈妈把米里的小石子一粒一粒剔除干净。","pinyin":"Māma bǎ mǐ lǐ de xiǎo shízǐ yí lì yi lì tīchú gānjìng.","vi":"Mẹ nhặt sạch từng hạt sạn nhỏ trong gạo."},{"type":"compound","zh":"只要剔除这几个异常样本，实验结果就很稳定了。","pinyin":"Zhǐyào tīchú zhè jǐ gè yìcháng yàngběn, shíyàn jiéguǒ jiù hěn wěndìng le.","vi":"Chỉ cần loại bỏ mấy mẫu bất thường này, kết quả thí nghiệm sẽ rất ổn định."}],"related":[{"hanzi":"去除","pinyin":"qùchú","vi":"loại bỏ"},{"hanzi":"排除","pinyin":"páichú","vi":"loại trừ"},{"hanzi":"淘汰","pinyin":"táotài","vi":"đào thải"},{"hanzi":"保留","pinyin":"bǎoliú","vi":"giữ lại"}]},{"id":"听觉","hanzi":"听觉","pinyin":"tīngjué","meaning_vi":"thính giác","explanation":"听 (nghe) + 觉 (giác ngộ/cảm nhận).","hsk_level":"7-9","tags":["danh-tu","co-the","khoa-hoc"],"image":"👂","examples":[{"type":"basic","zh":"狗的听觉非常灵敏。","pinyin":"Gǒu de tīngjué fēicháng língmǐn.","vi":"Thính giác của chó vô cùng nhạy bén."},{"type":"simple","zh":"长期戴耳机听大音量音乐会损伤听觉。","pinyin":"Chángqī dài ěrjī tīng dà yīnliàng yīnyuèhuì sǔnshāng tīngjué.","vi":"Đeo tai nghe nghe nhạc to trong thời gian dài sẽ làm tổn thương thính giác."},{"type":"compound","zh":"虽然他失去了视力，但是听觉变得格外敏锐。","pinyin":"Suīrán tā shīqùle shìlì, dànshì tīngjué biànde géwài mǐnruì.","vi":"Tuy mất thị lực, nhưng thính giác của anh ấy trở nên đặc biệt nhạy bén."}],"related":[{"hanzi":"视觉","pinyin":"shìjué","vi":"thị giác"},{"hanzi":"嗅觉","pinyin":"xiùjué","vi":"khứu giác"},{"hanzi":"味觉","pinyin":"wèijué","vi":"vị giác"},{"hanzi":"耳朵","pinyin":"ěrduo","vi":"tai"}],"traditional":"聽覺"},{"id":"听取","hanzi":"听取","pinyin":"tīngqǔ","meaning_vi":"lắng nghe tiếp thu (ý kiến)","explanation":"听 (nghe) + 取 (lấy).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"👂","examples":[{"type":"basic","zh":"领导听取了汇报。","pinyin":"Lǐngdǎo tīngqǔle huìbào.","vi":"Lãnh đạo đã nghe báo cáo."},{"type":"simple","zh":"设计师认真听取了客户对样品的修改意见。","pinyin":"Shèjìshī rènzhēn tīngqǔle kèhù duì yàngpǐn de xiūgǎi yìjiàn.","vi":"Nhà thiết kế chăm chú lắng nghe ý kiến chỉnh sửa mẫu của khách hàng."},{"type":"compound","zh":"如果不听取居民的意见，这个改造方案就很难推行。","pinyin":"Rúguǒ bù tīngqǔ jūmín de yìjiàn, zhè ge gǎizào fāng'àn jiù hěn nán tuīxíng.","vi":"Nếu không lắng nghe ý kiến cư dân, phương án cải tạo này sẽ rất khó triển khai."}],"related":[{"hanzi":"听从","pinyin":"tīngcóng","vi":"nghe theo"},{"hanzi":"采纳","pinyin":"cǎinà","vi":"tiếp thu"},{"hanzi":"征求意见","pinyin":"zhēngqiúyìjiàn","vi":"trưng cầu ý kiến"},{"hanzi":"倾听","pinyin":"qīngtīng","vi":"lắng nghe"}],"traditional":"聽取"},{"id":"听众","hanzi":"听众","pinyin":"tīngzhòng","meaning_vi":"thính giả","explanation":"听 (nghe) + 众 (quần chúng/đông đảo).","hsk_level":"7-9","tags":["danh-tu","giai-tri","con-nguoi"],"image":"🎧","examples":[{"type":"basic","zh":"听众热烈鼓掌。","pinyin":"Tīngzhòng rèliè gǔzhǎng.","vi":"Thính giả vỗ tay nhiệt liệt."},{"type":"simple","zh":"这档深夜电台节目拥有大批忠实的听众。","pinyin":"Zhè dàng shēnyè diàntái jiémù yōngyǒu dàpī zhōngshí de tīngzhòng.","vi":"Chương trình phát thanh đêm khuya này có rất đông thính giả trung thành."},{"type":"compound","zh":"演讲者一讲到自己的亲身经历，听众就安静了下来。","pinyin":"Yǎnjiǎng zhě yì jiǎngdào zìjǐ de qīnshēn jīnglì, tīngzhòng jiù ānjìngle xiàlái.","vi":"Diễn giả vừa kể đến trải nghiệm của bản thân, thính giả liền im lặng lắng nghe."}],"related":[{"hanzi":"观众","pinyin":"guānzhòng","vi":"khán giả"},{"hanzi":"读者","pinyin":"dúzhě","vi":"độc giả"},{"hanzi":"广播","pinyin":"guǎngbō","vi":"phát thanh"},{"hanzi":"听讲","pinyin":"tīngjiǎng","vi":"nghe giảng"}],"traditional":"聽眾"},{"id":"通畅","hanzi":"通畅","pinyin":"tōngchàng","meaning_vi":"thông suốt (đường sá/hô hấp)","explanation":"通 (thông suốt/phổ biến) + 畅 (thông suốt/thoải mái).","hsk_level":"7-9","tags":["tinh-tu","giao-thong"],"image":"🛣️","examples":[{"type":"basic","zh":"今天道路很通畅。","pinyin":"Jīntiān dàolù hěn tōngchàng.","vi":"Hôm nay đường sá rất thông suốt."},{"type":"simple","zh":"交警在路口疏导车辆，保证了主干道的通畅。","pinyin":"Jiāojǐng zài lùkǒu shūdǎo chēliàng, bǎozhèngle zhǔgàndào de tōngchàng.","vi":"Cảnh sát giao thông phân luồng xe ở giao lộ, bảo đảm trục đường chính thông suốt."},{"type":"compound","zh":"只要保持呼吸道通畅，病人就暂时没有生命危险。","pinyin":"Zhǐyào bǎochí hūxīdào tōngchàng, bìngrén jiù zànshí méiyǒu shēngmìng wēixiǎn.","vi":"Chỉ cần giữ đường thở thông thoáng, bệnh nhân tạm thời sẽ không nguy hiểm tính mạng."}],"related":[{"hanzi":"畅通","pinyin":"chàngtōng","vi":"thông suốt"},{"hanzi":"顺畅","pinyin":"shùnchàng","vi":"trôi chảy"},{"hanzi":"堵塞","pinyin":"dǔsè","vi":"tắc nghẽn"},{"hanzi":"呼吸","pinyin":"hūxī","vi":"hô hấp"}],"traditional":"通暢"},{"id":"通货紧缩","hanzi":"通货紧缩","pinyin":"tōnghuòjǐnsuō","meaning_vi":"giảm phát","explanation":"通货 (tiền tệ) + 紧缩 (co hẹp). Đối nghĩa với 通货膨胀 (lạm phát).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"📉","examples":[{"type":"basic","zh":"该国出现了通货紧缩。","pinyin":"Gāi guó chūxiànle tōnghuòjǐnsuō.","vi":"Nước đó đã xuất hiện giảm phát."},{"type":"simple","zh":"持续的通货紧缩让企业不敢扩大投资。","pinyin":"Chíxù de tōnghuòjǐnsuō ràng qǐyè bù gǎn kuòdà tóuzī.","vi":"Giảm phát kéo dài khiến doanh nghiệp không dám mở rộng đầu tư."},{"type":"compound","zh":"一旦陷入通货紧缩，消费者就会推迟购物，等待降价。","pinyin":"Yídàn xiànrù tōnghuòjǐnsuō, xiāofèizhě jiù huì tuīchí gòuwù, děngdài jiàngjià.","vi":"Một khi rơi vào giảm phát, người tiêu dùng sẽ hoãn mua sắm để chờ giảm giá."}],"related":[{"hanzi":"通货膨胀","pinyin":"tōnghuòpéngzhàng","vi":"lạm phát"},{"hanzi":"物价","pinyin":"wùjià","vi":"vật giá"},{"hanzi":"经济衰退","pinyin":"jīngjìshuāituì","vi":"suy thoái kinh tế"},{"hanzi":"货币","pinyin":"huòbì","vi":"tiền tệ"}],"traditional":"通貨緊縮"},{"id":"通缉","hanzi":"通缉","pinyin":"tōngjī","meaning_vi":"truy nã","explanation":"通 (thông suốt/phổ biến) + 缉 (truy bắt).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚨","examples":[{"type":"basic","zh":"警方通缉了逃犯。","pinyin":"Jǐngfāng tōngjīle táofàn.","vi":"Cảnh sát đã truy nã kẻ đào tẩu."},{"type":"simple","zh":"这名诈骗嫌疑人已被公安部列为网上通缉对象。","pinyin":"Zhè míng zhàpiàn xiányírén yǐ bèi Gōng'ānbù lièwéi wǎngshàng tōngjī duìxiàng.","vi":"Nghi phạm lừa đảo này đã bị Bộ Công an đưa vào danh sách truy nã trên mạng."},{"type":"compound","zh":"虽然他被通缉了三年，但是最终还是主动投案自首了。","pinyin":"Suīrán tā bèi tōngjīle sān nián, dànshì zuìzhōng háishì zhǔdòng tóu'àn zìshǒu le.","vi":"Tuy bị truy nã suốt ba năm, nhưng cuối cùng hắn vẫn ra đầu thú."}],"related":[{"hanzi":"通缉犯","pinyin":"tōngjīfàn","vi":"tội phạm bị truy nã"},{"hanzi":"逮捕","pinyin":"dàibǔ","vi":"bắt giữ"},{"hanzi":"追捕","pinyin":"zhuībǔ","vi":"truy bắt"},{"hanzi":"逃犯","pinyin":"táofàn","vi":"kẻ đào tẩu"}],"traditional":"通緝"},{"id":"通顺","hanzi":"通顺","pinyin":"tōngshùn","meaning_vi":"trôi chảy mạch lạc (câu văn)","explanation":"通 (thông suốt/phổ biến) + 顺 (thuận lợi/thuận theo).","hsk_level":"7-9","tags":["tinh-tu","ngon-ngu"],"image":"✍️","examples":[{"type":"basic","zh":"这句话不太通顺。","pinyin":"Zhè jù huà bú tài tōngshùn.","vi":"Câu này không được trôi chảy lắm."},{"type":"simple","zh":"编辑帮我把译稿改得更加通顺自然。","pinyin":"Biānjí bāng wǒ bǎ yì gǎo gǎi de gèngjiā tōngshùn zìrán.","vi":"Biên tập viên giúp tôi sửa bản dịch cho mạch lạc, tự nhiên hơn."},{"type":"compound","zh":"只要语句通顺、观点明确，这篇作文就能得高分。","pinyin":"Zhǐyào yǔjù tōngshùn, guāndiǎn míngquè, zhè piān zuòwén jiù néng dé gāofēn.","vi":"Chỉ cần câu chữ trôi chảy, quan điểm rõ ràng, bài văn này sẽ được điểm cao."}],"related":[{"hanzi":"流畅","pinyin":"liúchàng","vi":"trôi chảy"},{"hanzi":"通畅","pinyin":"tōngchàng","vi":"thông suốt"},{"hanzi":"语句","pinyin":"yǔjù","vi":"câu chữ"},{"hanzi":"别扭","pinyin":"bièniu","vi":"trúc trắc"}],"traditional":"通順"},{"id":"通往","hanzi":"通往","pinyin":"tōngwǎng","meaning_vi":"dẫn tới (con đường)","explanation":"通 (thông suốt/phổ biến) + 往 (quá khứ/hướng tới).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🛤️","examples":[{"type":"basic","zh":"这条路通往山顶。","pinyin":"Zhè tiáo lù tōngwǎng shāndǐng.","vi":"Con đường này dẫn lên đỉnh núi."},{"type":"simple","zh":"一座石桥是通往小岛的唯一通道。","pinyin":"Yí zuò shí qiáo shì tōngwǎng xiǎodǎo de wéiyī tōngdào.","vi":"Một cây cầu đá là lối đi duy nhất dẫn ra hòn đảo nhỏ."},{"type":"compound","zh":"虽然通往成功的路不止一条，但是每条都需要汗水。","pinyin":"Suīrán tōngwǎng chénggōng de lù bùzhǐ yì tiáo, dànshì měi tiáo dōu xūyào hànshuǐ.","vi":"Tuy con đường dẫn tới thành công không chỉ có một, nhưng con đường nào cũng cần mồ hôi."}],"related":[{"hanzi":"通向","pinyin":"tōngxiàng","vi":"dẫn tới"},{"hanzi":"前往","pinyin":"qiánwǎng","vi":"đi đến"},{"hanzi":"通达","pinyin":"tōngdá","vi":"thông suốt tới"},{"hanzi":"道路","pinyin":"dàolù","vi":"con đường"}]},{"id":"偷懒","hanzi":"偷懒","pinyin":"tōulǎn","meaning_vi":"lười biếng trốn việc","explanation":"偷 (lén lút/trộm) + 懒 (lười).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🦥","examples":[{"type":"basic","zh":"干活别偷懒。","pinyin":"Gànhuó bié tōulǎn.","vi":"Làm việc đừng lười biếng."},{"type":"simple","zh":"趁老板出差，几个员工躲在茶水间偷懒聊天。","pinyin":"Chèn lǎobǎn chūchāi, jǐ gè yuángōng duǒ zài cháshuǐ jiān tōulǎn liáotiān.","vi":"Nhân lúc sếp đi công tác, mấy nhân viên trốn vào phòng pha trà lười việc tán gẫu."},{"type":"compound","zh":"如果平时练琴偷懒，比赛时就会手忙脚乱。","pinyin":"Rúguǒ píngshí liàn qín tōulǎn, bǐsài shí jiù huì shǒumángjiǎoluàn.","vi":"Nếu ngày thường lười tập đàn thì lúc thi sẽ luống cuống tay chân."}],"related":[{"hanzi":"懒惰","pinyin":"lǎnduò","vi":"lười biếng"},{"hanzi":"摸鱼","pinyin":"mōyú","vi":"lười việc"},{"hanzi":"勤快","pinyin":"qínkuai","vi":"siêng năng"},{"hanzi":"偷工减料","pinyin":"tōugōngjiǎnliào","vi":"ăn bớt nguyên liệu"}],"traditional":"偷懶"},{"id":"偷税漏税","hanzi":"偷税漏税","pinyin":"tōushuì-lòushuì","meaning_vi":"trốn thuế lậu thuế","explanation":"偷税 + 漏税. Thành ngữ pháp luật.","hsk_level":"7-9","tags":["thanh-ngu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"偷税漏税是违法的。","pinyin":"Tōushuìlòushuì shì wéifǎ de.","vi":"Trốn thuế lậu thuế là phạm pháp."},{"type":"simple","zh":"这家公司因长期偷税漏税被处以巨额罚款。","pinyin":"Zhè jiā gōngsī yīn chángqī tōushuìlòushuì bèi chǔ yǐ jù'é fákuǎn.","vi":"Công ty này bị phạt một khoản tiền khổng lồ vì trốn thuế lậu thuế trong thời gian dài."},{"type":"compound","zh":"一旦被查出偷税漏税，企业不但要补缴税款，而且要承担刑事责任。","pinyin":"Yídàn bèi cháchū tōushuìlòushuì, qǐyè búdàn yào bǔ jiǎo shuìkuǎn, érqiě yào chéngdān xíngshì zérèn.","vi":"Một khi bị phát hiện trốn thuế, doanh nghiệp không chỉ phải nộp bù tiền thuế mà còn phải chịu trách nhiệm hình sự."}],"related":[{"hanzi":"逃税","pinyin":"táoshuì","vi":"trốn thuế"},{"hanzi":"纳税","pinyin":"nàshuì","vi":"nộp thuế"},{"hanzi":"税务局","pinyin":"Shuìwùjú","vi":"cục thuế"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"}],"traditional":"偷稅漏稅"},{"id":"突变","hanzi":"突变","pinyin":"tūbiàn","meaning_vi":"đột biến","explanation":"突 (đột phá/nổi bật) + 变 (biến đổi/biến cố).","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🧬","examples":[{"type":"basic","zh":"天气突变了。","pinyin":"Tiānqì tūbiàn le.","vi":"Thời tiết thay đổi đột ngột."},{"type":"simple","zh":"科学家发现这种病毒的基因发生了突变。","pinyin":"Kēxuéjiā fāxiàn zhè zhǒng bìngdú de jīyīn fāshēngle tūbiàn.","vi":"Các nhà khoa học phát hiện gen của loại virus này đã đột biến."},{"type":"compound","zh":"因为局势突变，所以原定的访问计划被迫取消。","pinyin":"Yīnwèi júshì tūbiàn, suǒyǐ yuándìng de fǎngwèn jìhuà bèipò qǔxiāo.","vi":"Vì tình hình thay đổi đột ngột nên kế hoạch thăm viếng dự kiến buộc phải hủy."}],"related":[{"hanzi":"基因突变","pinyin":"jīyīntūbiàn","vi":"đột biến gen"},{"hanzi":"剧变","pinyin":"jùbiàn","vi":"biến đổi mạnh"},{"hanzi":"变异","pinyin":"biànyì","vi":"biến dị"},{"hanzi":"渐变","pinyin":"jiànbiàn","vi":"biến đổi dần"}],"traditional":"突變"},{"id":"突破口","hanzi":"突破口","pinyin":"tūpòkǒu","meaning_vi":"khâu đột phá, điểm đột phá","explanation":"突 (đột phá/nổi bật) + 破 (rách) + 口 (口).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"💥","examples":[{"type":"basic","zh":"我们找到了突破口。","pinyin":"Wǒmen zhǎodàole tūpòkǒu.","vi":"Chúng tôi đã tìm ra điểm đột phá."},{"type":"simple","zh":"警方把那张出租车发票作为破案的突破口。","pinyin":"Jǐngfāng bǎ nà zhāng chūzūchē fāpiào zuòwéi pò'àn de tūpòkǒu.","vi":"Cảnh sát lấy tờ hóa đơn taxi đó làm điểm đột phá để phá án."},{"type":"compound","zh":"只要找准突破口，这个技术难题就能迎刃而解。","pinyin":"Zhǐyào zhǎo zhǔn tūpòkǒu, zhè ge jìshù nántí jiù néng yíngrèn'érjiě.","vi":"Chỉ cần tìm đúng điểm đột phá, bài toán kỹ thuật này sẽ được giải quyết dễ dàng."}],"related":[{"hanzi":"突破","pinyin":"tūpò","vi":"đột phá"},{"hanzi":"切入点","pinyin":"qiērùdiǎn","vi":"điểm tiếp cận"},{"hanzi":"关键","pinyin":"guānjiàn","vi":"mấu chốt"},{"hanzi":"瓶颈","pinyin":"píngjǐng","vi":"nút thắt cổ chai"}]},{"id":"吞并","hanzi":"吞并","pinyin":"tūnbìng","meaning_vi":"thôn tính, sáp nhập","explanation":"吞 (nuốt/thôn tính) + 并 (sáp nhập/song song).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🏢","examples":[{"type":"basic","zh":"大公司吞并了小公司。","pinyin":"Dàgōngsī tūnbìngle xiǎo gōngsī.","vi":"Công ty lớn đã thôn tính công ty nhỏ."},{"type":"simple","zh":"秦国先后吞并了六国，统一了天下。","pinyin":"Qínguó xiānhòu tūnbìngle liù guó, tǒngyīle tiānxià.","vi":"Nước Tần lần lượt thôn tính sáu nước, thống nhất thiên hạ."},{"type":"compound","zh":"如果被竞争对手吞并，这个老品牌就会彻底消失。","pinyin":"Rúguǒ bèi jìngzhēng duìshǒu tūnbìng, zhè ge lǎo pǐnpái jiù huì chèdǐ xiāoshī.","vi":"Nếu bị đối thủ cạnh tranh thôn tính, thương hiệu lâu đời này sẽ biến mất hoàn toàn."}],"related":[{"hanzi":"兼并","pinyin":"jiānbìng","vi":"sáp nhập"},{"hanzi":"并购","pinyin":"bìnggòu","vi":"mua bán sáp nhập"},{"hanzi":"吞噬","pinyin":"tūnshì","vi":"nuốt chửng"},{"hanzi":"侵占","pinyin":"qīnzhàn","vi":"xâm chiếm"}],"traditional":"吞併"},{"id":"吞没","hanzi":"吞没","pinyin":"tūnmò","meaning_vi":"nhấn chìm, nuốt chửng; biển thủ, chiếm đoạt (của công)","explanation":"吞 (nuốt/thôn tính) + 没 (không).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌊","examples":[{"type":"basic","zh":"大浪吞没了小船。","pinyin":"Dàlàng tūnmòle xiǎochuán.","vi":"Con sóng lớn nuốt chửng chiếc thuyền nhỏ."},{"type":"simple","zh":"一场洪水吞没了河边的大片农田。","pinyin":"Yì chǎng hóngshuǐ tūnmòle hébiān de dàpiàn nóngtián.","vi":"Một trận lũ đã nhấn chìm cả vùng ruộng ven sông."},{"type":"compound","zh":"那名会计不但吞没了公款，而且伪造了账目。","pinyin":"Nà míng kuàijì búdàn tūnmòle gōngkuǎn, érqiě wěizàole zhàngmù.","vi":"Kế toán đó không chỉ biển thủ công quỹ mà còn làm giả sổ sách."}],"related":[{"hanzi":"淹没","pinyin":"yānmò","vi":"nhấn chìm"},{"hanzi":"侵吞","pinyin":"qīntūn","vi":"biển thủ"},{"hanzi":"吞噬","pinyin":"tūnshì","vi":"nuốt chửng"},{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"}],"traditional":"吞沒"},{"id":"坦诚","hanzi":"坦诚","pinyin":"tǎnchéng","meaning_vi":"thẳng thắn chân thành","explanation":"坦 (thẳng thắn/bằng phẳng) + 诚 (chân thành/thành thực).","hsk_level":"7-9","tags":["tinh-tu","giao-tiep"],"image":"❤️","examples":[{"type":"basic","zh":"我们坦诚地谈了谈。","pinyin":"Wǒmen tǎnchéng de tánle tán.","vi":"Chúng tôi đã nói chuyện thẳng thắn với nhau."},{"type":"simple","zh":"面试时她坦诚地承认了自己经验不足。","pinyin":"Miànshì shí tā tǎnchéng de chéngrènle zìjǐ jīngyàn bùzú.","vi":"Khi phỏng vấn, cô ấy thẳng thắn thừa nhận mình còn thiếu kinh nghiệm."},{"type":"compound","zh":"只要彼此坦诚相待，再大的误会也能解开。","pinyin":"Zhǐyào bǐcǐ tǎnchéng xiāngdài, zài dà de wùhuì yě néng jiěkāi.","vi":"Chỉ cần đối xử chân thành thẳng thắn với nhau, hiểu lầm lớn đến đâu cũng gỡ được."}],"related":[{"hanzi":"坦率","pinyin":"tǎnshuài","vi":"thẳng thắn"},{"hanzi":"真诚","pinyin":"zhēnchéng","vi":"chân thành"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thú thật"},{"hanzi":"虚伪","pinyin":"xūwěi","vi":"giả dối"}],"traditional":"坦誠"},{"id":"坦言","hanzi":"坦言","pinyin":"tǎnyán","meaning_vi":"thẳng thắn chia sẻ","explanation":"坦 (thẳng thắn/bằng phẳng) + 言 (ngôn luận/lời nói).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"他坦言自己很紧张。","pinyin":"Tā tǎnyán zìjǐ hěn jǐnzhāng.","vi":"Anh ấy thẳng thắn nói rằng mình rất căng thẳng."},{"type":"simple","zh":"这位导演在发布会上坦言影片的结局留有遗憾。","pinyin":"Zhè wèi dǎoyǎn zài fābùhuì shàng tǎnyán yǐngpiàn de jiéjú liúyǒu yíhàn.","vi":"Đạo diễn thẳng thắn chia sẻ tại buổi họp báo rằng cái kết của phim vẫn còn tiếc nuối."},{"type":"compound","zh":"虽然拿了冠军，但是她坦言比赛中犯了不少错误。","pinyin":"Suīrán nále guànjūn, dànshì tā tǎnyán bǐsài zhōng fànle bùshǎo cuòwù.","vi":"Tuy giành chức vô địch, nhưng cô ấy thẳng thắn thừa nhận đã mắc khá nhiều lỗi trong trận đấu."}],"related":[{"hanzi":"直言","pinyin":"zhíyán","vi":"nói thẳng"},{"hanzi":"坦白","pinyin":"tǎnbái","vi":"thú thật"},{"hanzi":"表示","pinyin":"biǎoshì","vi":"bày tỏ"},{"hanzi":"坦诚","pinyin":"tǎnchéng","vi":"thẳng thắn"}]},{"id":"躺平","hanzi":"躺平","pinyin":"tǎngpíng","meaning_vi":"nằm thẳng (từ chối áp lực cạnh tranh quá mức)","explanation":"躺 (nằm) + 平 (phẳng).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🛌","examples":[{"type":"basic","zh":"他决定躺平了。","pinyin":"Tā juédìng tǎngpíng le.","vi":"Anh ấy quyết định buông xuôi, sống kiểu nằm thẳng."},{"type":"simple","zh":"一些年轻人选择躺平来对抗过度的竞争压力。","pinyin":"Yìxiē niánqīngrén xuǎnzé tǎngpíng lái duìkàng guòdù de jìngzhēng yālì.","vi":"Một số người trẻ chọn lối sống nằm thẳng để chống lại áp lực cạnh tranh quá mức."},{"type":"compound","zh":"与其在焦虑中躺平，不如换个自己真正喜欢的方向。","pinyin":"Yǔqí zài jiāolǜ zhōng tǎngpíng, bùrú huàn gè zìjǐ zhēnzhèng xǐhuan de fāngxiàng.","vi":"Thay vì buông xuôi trong lo âu, chi bằng đổi sang hướng đi mình thật sự yêu thích."}],"related":[{"hanzi":"内卷","pinyin":"nèijuǎn","vi":"cạnh tranh nội bộ khốc liệt"},{"hanzi":"佛系","pinyin":"fóxì","vi":"sống an nhiên"},{"hanzi":"摆烂","pinyin":"bǎilàn","vi":"buông xuôi"},{"hanzi":"奋斗","pinyin":"fèndòu","vi":"phấn đấu"}]},{"id":"体察","hanzi":"体察","pinyin":"tǐchá","meaning_vi":"thấu hiểu, quan sát cảm nhận sâu sắc","explanation":"体 (thể hiện/hệ thống) + 察 (quan sát/xem xét).","hsk_level":"7-9","tags":["dong-tu"],"image":"👀","examples":[{"type":"basic","zh":"领导要体察民情。","pinyin":"Lǐngdǎo yào tǐchá mínqíng.","vi":"Lãnh đạo cần thấu hiểu tình hình dân chúng."},{"type":"simple","zh":"好医生总能体察到病人没说出口的担忧。","pinyin":"Hǎo yīshēng zǒngnéng tǐchá dào bìngrén méi shuō chūkǒu de dānyōu.","vi":"Bác sĩ giỏi luôn cảm nhận được nỗi lo bệnh nhân chưa nói ra."},{"type":"compound","zh":"只有深入基层，干部才能真正体察百姓的疾苦。","pinyin":"Zhǐyǒu shēnrù jīcéng, gànbù cáinéng zhēnzhèng tǐchá bǎixìng de jíkǔ.","vi":"Chỉ khi đi sâu xuống cơ sở, cán bộ mới thực sự thấu hiểu nỗi khổ của dân."}],"related":[{"hanzi":"体会","pinyin":"tǐhuì","vi":"thấm thía"},{"hanzi":"体谅","pinyin":"tǐliàng","vi":"thông cảm"},{"hanzi":"体察民情","pinyin":"tǐchámínqíng","vi":"thấu hiểu dân tình"},{"hanzi":"观察","pinyin":"guānchá","vi":"quan sát"}],"traditional":"體察"},{"id":"体检报告","hanzi":"体检报告","pinyin":"tǐjiǎnbàogào","meaning_vi":"báo cáo khám sức khỏe tổng quát","explanation":"体 (thể hiện/hệ thống) + 检 (kiểm tra) + 报 (报) + 告 (告).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"📋","examples":[{"type":"basic","zh":"体检报告出来了。","pinyin":"Tǐjiǎnbàogào chūlái le.","vi":"Kết quả khám sức khỏe đã có rồi."},{"type":"simple","zh":"公司要求新员工入职前提交体检报告。","pinyin":"Gōngsī yāoqiú xīn yuángōng rùzhí qiántí jiāo tǐjiǎnbàogào.","vi":"Công ty yêu cầu nhân viên mới nộp báo cáo khám sức khỏe trước khi nhận việc."},{"type":"compound","zh":"虽然体检报告一切正常，但是他还是觉得浑身没劲。","pinyin":"Suīrán tǐjiǎnbàogào yíqiè zhèngcháng, dànshì tā háishì juéde húnshēn méijìn.","vi":"Tuy báo cáo khám sức khỏe mọi thứ đều bình thường, nhưng anh ấy vẫn thấy cả người uể oải."}],"related":[{"hanzi":"体检","pinyin":"tǐjiǎn","vi":"khám sức khỏe"},{"hanzi":"化验","pinyin":"huàyàn","vi":"xét nghiệm"},{"hanzi":"指标","pinyin":"zhǐbiāo","vi":"chỉ số"},{"hanzi":"医院","pinyin":"yīyuàn","vi":"bệnh viện"}],"traditional":"體檢報告"},{"id":"体力劳动","hanzi":"体力劳动","pinyin":"tǐlìláodòng","meaning_vi":"lao động chân tay","explanation":"体 (thể hiện/hệ thống) + 力 (sức mạnh/nỗ lực) + 劳 (lao động/vất vả) + 动 (动).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"👷","examples":[{"type":"basic","zh":"他从事体力劳动。","pinyin":"Tā cóngshì tǐlìláodòng.","vi":"Anh ấy làm lao động chân tay."},{"type":"simple","zh":"搬运工每天要进行十个小时的体力劳动。","pinyin":"Bānyùngōng měitiān yào jìnxíng shí gè xiǎoshí de tǐlìláodòng.","vi":"Công nhân bốc vác mỗi ngày phải lao động chân tay mười tiếng."},{"type":"compound","zh":"虽然体力劳动很辛苦，但是他觉得比坐办公室踏实。","pinyin":"Suīrán tǐlìláodòng hěn xīnkǔ, dànshì tā juéde bǐ zuò bàngōngshì tāshi.","vi":"Tuy lao động chân tay rất vất vả, nhưng anh ấy thấy yên tâm hơn ngồi văn phòng."}],"related":[{"hanzi":"脑力劳动","pinyin":"nǎolìláodòng","vi":"lao động trí óc"},{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"劳动力","pinyin":"láodònglì","vi":"sức lao động"},{"hanzi":"苦力","pinyin":"kǔlì","vi":"cu li"}],"traditional":"體力勞動"},{"id":"体能","hanzi":"体能","pinyin":"tǐnéng","meaning_vi":"thể lực","explanation":"体 (thể hiện/hệ thống) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["danh-tu","the-thao","suc-khoe"],"image":"💪","examples":[{"type":"basic","zh":"运动员在练体能。","pinyin":"Yùndòngyuán zài liàn tǐnéng.","vi":"Vận động viên đang tập thể lực."},{"type":"simple","zh":"消防员每周都要参加严格的体能测试。","pinyin":"Xiāofángyuán měizhōu dōu yào cānjiā yángé de tǐnéng cèshì.","vi":"Lính cứu hỏa mỗi tuần đều phải tham gia kiểm tra thể lực nghiêm ngặt."},{"type":"compound","zh":"如果体能跟不上，下半场就很难守住比分。","pinyin":"Rúguǒ tǐnéng gēnbúshàng, xiàbànchǎng jiù hěn nán shǒuzhù bǐfēn.","vi":"Nếu thể lực không theo kịp thì hiệp hai sẽ rất khó giữ được tỉ số."}],"related":[{"hanzi":"体力","pinyin":"tǐlì","vi":"thể lực"},{"hanzi":"体质","pinyin":"tǐzhì","vi":"thể chất"},{"hanzi":"体能训练","pinyin":"tǐnéngxùnliàn","vi":"huấn luyện thể lực"},{"hanzi":"耐力","pinyin":"nàilì","vi":"sức bền"}],"traditional":"體能"},{"id":"体液","hanzi":"体液","pinyin":"tǐyè","meaning_vi":"dịch cơ thể","explanation":"体 (thể hiện/hệ thống) + 液 (chất lỏng).","hsk_level":"7-9","tags":["danh-tu","co-the","suc-khoe"],"image":"💧","examples":[{"type":"basic","zh":"汗水是一种体液。","pinyin":"Hànshuǐ shì yì zhǒng tǐyè.","vi":"Mồ hôi là một loại dịch cơ thể."},{"type":"simple","zh":"这种病毒主要通过血液和体液传播。","pinyin":"Zhè zhǒng bìngdú zhǔyào tōngguò xuèyè hé tǐyè chuánbō.","vi":"Loại virus này chủ yếu lây qua máu và dịch cơ thể."},{"type":"compound","zh":"因为大量出汗会流失体液，所以马拉松途中要不断补水。","pinyin":"Yīnwèi dàliàng chūhàn huì liúshī tǐyè, suǒyǐ mǎlāsōng túzhōng yào búduàn bǔshuǐ.","vi":"Vì ra nhiều mồ hôi sẽ mất dịch cơ thể nên trong lúc chạy marathon phải liên tục bù nước."}],"related":[{"hanzi":"血液","pinyin":"xuèyè","vi":"máu"},{"hanzi":"汗液","pinyin":"hànyè","vi":"mồ hôi"},{"hanzi":"唾液","pinyin":"tuòyè","vi":"nước bọt"},{"hanzi":"细胞","pinyin":"xìbāo","vi":"tế bào"}],"traditional":"體液"},{"id":"体制","hanzi":"体制","pinyin":"tǐzhì","meaning_vi":"thể chế","explanation":"体 (thể hiện/hệ thống) + 制 (chế độ/kiềm chế).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"教育体制需要改革。","pinyin":"Jiàoyù tǐzhì xūyào gǎigé.","vi":"Thể chế giáo dục cần được cải cách."},{"type":"simple","zh":"他在体制内工作了二十年后决定下海经商。","pinyin":"Tā zài tǐzhì nèi gōngzuòle èrshí nián hòu juédìng xiàhǎi jīngshāng.","vi":"Sau hai mươi năm làm việc trong biên chế nhà nước, ông ấy quyết định ra ngoài kinh doanh."},{"type":"compound","zh":"如果管理体制不改，再多的资金投入也难见成效。","pinyin":"Rúguǒ guǎnlǐ tǐzhì bù gǎi, zài duō de zījīn tóurù yě nán jiàn chéngxiào.","vi":"Nếu thể chế quản lý không thay đổi thì đổ bao nhiêu vốn vào cũng khó thấy hiệu quả."}],"related":[{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"},{"hanzi":"体系","pinyin":"tǐxì","vi":"hệ thống"},{"hanzi":"体制改革","pinyin":"tǐzhìgǎigé","vi":"cải cách thể chế"},{"hanzi":"机制","pinyin":"jīzhì","vi":"cơ chế"}],"traditional":"體制"},{"id":"统筹协调","hanzi":"统筹协调","pinyin":"tǒngchóuxiétiáo","meaning_vi":"điều phối tổng thể","explanation":"统 (thống nhất/hệ thống) + 筹 (trù bị/tính toán) + 协 (hiệp thương/hỗ trợ) + 调 (điều chỉnh/hòa giải).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"这事需要统筹协调。","pinyin":"Zhè shì xūyào tǒngchóuxiétiáo.","vi":"Việc này cần điều phối tổng thể."},{"type":"simple","zh":"市政府成立专班统筹协调各部门的救灾工作。","pinyin":"Shìzhèngfǔ chénglì zhuān bān tǒngchóuxiétiáo gè bùmén de jiùzāi gōngzuò.","vi":"Chính quyền thành phố lập tổ chuyên trách điều phối công tác cứu trợ của các ban ngành."},{"type":"compound","zh":"只要有人统筹协调，几个团队就不会重复劳动。","pinyin":"Zhǐyào yǒurén tǒngchóuxiétiáo, jǐ gè tuánduì jiù bú huì chóngfù láodòng.","vi":"Chỉ cần có người điều phối tổng thể, các nhóm sẽ không làm trùng việc nhau."}],"related":[{"hanzi":"统筹","pinyin":"tǒngchóu","vi":"trù tính tổng thể"},{"hanzi":"协调","pinyin":"xiétiáo","vi":"phối hợp"},{"hanzi":"统筹兼顾","pinyin":"tǒngchóujiāngù","vi":"tính toán toàn diện"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"}],"traditional":"統籌協調"},{"id":"统计局","hanzi":"统计局","pinyin":"tǒngjìjú","meaning_vi":"Cục Thống kê","explanation":"统 (thống nhất/hệ thống) + 计 (kế hoạch/tính toán) + 局 (cục diện/cơ quan).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"📊","examples":[{"type":"basic","zh":"统计局发布了数据。","pinyin":"Tǒngjìjú fābùle shùjù.","vi":"Cục Thống kê đã công bố số liệu."},{"type":"simple","zh":"国家统计局每月公布一次居民消费价格指数。","pinyin":"Guójiātǒngjìjú měiyuè gōngbù yí cì jūmín xiāofèi jiàgé zhǐshù.","vi":"Tổng cục Thống kê quốc gia mỗi tháng công bố chỉ số giá tiêu dùng một lần."},{"type":"compound","zh":"根据统计局的数据，虽然出口下降，但是内需明显回升。","pinyin":"Gēnjù tǒngjìjú de shùjù, suīrán chūkǒu xiàjiàng, dànshì nèixū míngxiǎn huíshēng.","vi":"Theo số liệu của Cục Thống kê, tuy xuất khẩu giảm nhưng nhu cầu trong nước phục hồi rõ rệt."}],"related":[{"hanzi":"统计","pinyin":"tǒngjì","vi":"thống kê"},{"hanzi":"数据","pinyin":"shùjù","vi":"dữ liệu"},{"hanzi":"国家统计局","pinyin":"Guójiā Tǒngjìjú","vi":"Tổng cục Thống kê"},{"hanzi":"普查","pinyin":"pǔchá","vi":"tổng điều tra"}],"traditional":"統計局"},{"id":"统帅","hanzi":"统帅","pinyin":"tǒngshuài","meaning_vi":"thống soái, tổng tư lệnh","explanation":"统 (thống nhất/hệ thống) + 帅 (đẹp trai/soái).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","con-nguoi"],"image":"🎖️","examples":[{"type":"basic","zh":"他是三军统帅。","pinyin":"Tā shì sānjūn tǒngshuài.","vi":"Ông ấy là thống soái tam quân."},{"type":"simple","zh":"拿破仑是历史上最有名的军事统帅之一。","pinyin":"Nápòlún shì lìshǐshàng zuì yǒumíng de jūnshì tǒngshuài zhīyī.","vi":"Napoleon là một trong những thống soái quân sự nổi tiếng nhất lịch sử."},{"type":"compound","zh":"既然他是全军统帅，就必须为这次失利承担责任。","pinyin":"Jìrán tā shì quánjūn tǒngshuài, jiù bìxū wèi zhè cì shīlì chéngdān zérèn.","vi":"Ông ấy đã là tổng tư lệnh toàn quân thì phải chịu trách nhiệm về thất bại lần này."}],"related":[{"hanzi":"元帅","pinyin":"yuánshuài","vi":"nguyên soái"},{"hanzi":"将军","pinyin":"jiāngjūn","vi":"tướng quân"},{"hanzi":"指挥","pinyin":"zhǐhuī","vi":"chỉ huy"},{"hanzi":"统领","pinyin":"tǒnglǐng","vi":"thống lĩnh"}],"traditional":"統帥"},{"id":"统一战线","hanzi":"统一战线","pinyin":"tǒngyīzhànxiàn","meaning_vi":"mặt trận thống nhất","explanation":"统 (thống nhất/hệ thống) + 一 (số 1) + 战 (chiến đấu/chiến lược) + 线 (manh mối/đường nét).","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🚩","examples":[{"type":"basic","zh":"他们结成了统一战线。","pinyin":"Tāmen jié chéngle tǒngyīzhànxiàn.","vi":"Họ đã lập thành mặt trận thống nhất."},{"type":"simple","zh":"抗日战争时期，各党派建立了民族统一战线。","pinyin":"Kàngrìzhànzhēng shíqī, gè dǎngpài jiànlìle mínzú tǒngyīzhànxiàn.","vi":"Thời kỳ kháng chiến chống Nhật, các đảng phái đã lập mặt trận thống nhất dân tộc."},{"type":"compound","zh":"面对共同的对手，几家小企业不但放下了分歧，而且结成了统一战线。","pinyin":"Miànduì gòngtóng de duìshǒu, jǐ jiā xiǎoqǐyè búdàn fàngxiàle fēnqí, érqiě jié chéngle tǒngyīzhànxiàn.","vi":"Trước đối thủ chung, mấy doanh nghiệp nhỏ không chỉ gác lại bất đồng mà còn lập thành mặt trận thống nhất."}],"related":[{"hanzi":"统一","pinyin":"tǒngyī","vi":"thống nhất"},{"hanzi":"战线","pinyin":"zhànxiàn","vi":"mặt trận"},{"hanzi":"联盟","pinyin":"liánméng","vi":"liên minh"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"}],"traditional":"統一戰線"},{"id":"吐露","hanzi":"吐露","pinyin":"tǔlù","meaning_vi":"bộc lộ, thổ lộ (tâm sự/sự thật)","explanation":"吐 (thốt ra/nhổ) + 露 (tiết lộ/sương mù).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"💬","examples":[{"type":"basic","zh":"她终于吐露了心声。","pinyin":"Tā zhōngyú tǔlùle xīnshēng.","vi":"Cuối cùng cô ấy đã thổ lộ nỗi lòng."},{"type":"simple","zh":"喝醉以后，他向老朋友吐露了埋藏多年的秘密。","pinyin":"Hēzuì yǐhòu, tā xiàng lǎopéngyou tǔlùle máicáng duōnián de mìmì.","vi":"Sau khi say, anh ấy thổ lộ với bạn cũ bí mật chôn giấu nhiều năm."},{"type":"compound","zh":"虽然他一直不愿吐露真相，但是证据已经说明了一切。","pinyin":"Suīrán tā yìzhí búyuàn tǔlù zhēnxiàng, dànshì zhèngjù yǐjīng shuōmíngle yíqiè.","vi":"Tuy hắn mãi không chịu khai ra sự thật, nhưng chứng cứ đã nói lên tất cả."}],"related":[{"hanzi":"倾诉","pinyin":"qīngsù","vi":"giãi bày"},{"hanzi":"透露","pinyin":"tòulù","vi":"tiết lộ"},{"hanzi":"表露","pinyin":"biǎolù","vi":"biểu lộ"},{"hanzi":"隐瞒","pinyin":"yǐnmán","vi":"giấu giếm"}]},{"id":"土特产","hanzi":"土特产","pinyin":"tǔtèchǎn","meaning_vi":"đặc sản địa phương","explanation":"土 (đất đai/bản địa) + 特 (đặc biệt/đặc sắc) + 产 (sản xuất/tài sản).","hsk_level":"7-9","tags":["danh-tu","an-uong","du-lich"],"image":"🎁","examples":[{"type":"basic","zh":"这些都是土特产。","pinyin":"Zhèxiē dōu shì tǔtèchǎn.","vi":"Những thứ này đều là đặc sản địa phương."},{"type":"simple","zh":"车站旁的小店专门卖各地的土特产。","pinyin":"Chēzhàn páng de xiǎodiàn zhuānmén mài gèdì de tǔtèchǎn.","vi":"Tiệm nhỏ cạnh nhà ga chuyên bán đặc sản các vùng."},{"type":"compound","zh":"每次回老家，妈妈就给我塞满一箱土特产。","pinyin":"Měi cì huílǎojiā, māma jiù gěi wǒ sāimǎn yì xiāng tǔtèchǎn.","vi":"Mỗi lần về quê, mẹ lại nhét cho tôi đầy một thùng đặc sản."}],"related":[{"hanzi":"特产","pinyin":"tèchǎn","vi":"đặc sản"},{"hanzi":"农产品","pinyin":"nóngchǎnpǐn","vi":"nông sản"},{"hanzi":"纪念品","pinyin":"jìniànpǐn","vi":"quà lưu niệm"},{"hanzi":"家乡","pinyin":"jiāxiāng","vi":"quê hương"}],"traditional":"土特產"},{"id":"外观","hanzi":"外观","pinyin":"wàiguān","meaning_vi":"ngoại quan, vẻ bề ngoài","explanation":"外 (ngoại – bên ngoài) + 观 (quan – nhìn, vẻ) → hình dáng bên ngoài của đồ vật, công trình. Ví dụ: 外观设计 (thiết kế kiểu dáng).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"📱","examples":[{"type":"basic","zh":"这辆车外观很漂亮。","pinyin":"Zhè liàng chē wàiguān hěn piàoliang.","vi":"Chiếc xe này có ngoại hình rất đẹp."},{"type":"simple","zh":"这座老楼的外观保留了上世纪三十年代的风格。","pinyin":"Zhè zuò lǎo lóu de wàiguān bǎoliúle shàng shìjì sānshí niándài de fēnggé.","vi":"Vẻ ngoài của tòa nhà cũ này vẫn giữ phong cách thập niên ba mươi thế kỷ trước."},{"type":"compound","zh":"虽然这款手机外观普通，但是拍照功能非常强大。","pinyin":"Suīrán zhè kuǎn shǒujī wàiguān pǔtōng, dànshì pāizhào gōngnéng fēicháng qiángdà.","vi":"Tuy mẫu điện thoại này bề ngoài bình thường, nhưng chức năng chụp ảnh rất mạnh."}],"related":[{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"},{"hanzi":"外形","pinyin":"wàixíng","vi":"hình dáng ngoài"},{"hanzi":"内在","pinyin":"nèizài","vi":"bên trong"},{"hanzi":"造型","pinyin":"zàoxíng","vi":"tạo hình"}],"traditional":"外觀"},{"id":"外汇","hanzi":"外汇","pinyin":"wàihuì","meaning_vi":"ngoại hối, ngoại tệ","explanation":"外 (ngoài) + 汇 (tổng hợp/chuyển tiền).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"💱","examples":[{"type":"basic","zh":"他去银行兑换外汇。","pinyin":"Tā qù yínháng duìhuàn wàihuì.","vi":"Anh ấy ra ngân hàng đổi ngoại tệ."},{"type":"simple","zh":"这个国家的外汇储备连续三个月增加。","pinyin":"Zhè ge guójiā de wàihuìchǔbèi liánxù sān gèyuè zēngjiā.","vi":"Dự trữ ngoại hối của nước này tăng ba tháng liên tiếp."},{"type":"compound","zh":"因为外汇管制很严，所以他每年只能换五万美元。","pinyin":"Yīnwèi wàihuì guǎnzhì hěn yán, suǒyǐ tā měinián zhǐnéng huàn wǔ wàn měiyuán.","vi":"Vì quản lý ngoại hối rất chặt nên mỗi năm anh ấy chỉ được đổi năm mươi nghìn đô la Mỹ."}],"related":[{"hanzi":"外币","pinyin":"wàibì","vi":"ngoại tệ"},{"hanzi":"汇率","pinyin":"huìlǜ","vi":"tỷ giá"},{"hanzi":"外汇储备","pinyin":"wàihuìchǔbèi","vi":"dự trữ ngoại hối"},{"hanzi":"兑换","pinyin":"duìhuàn","vi":"đổi tiền"}],"traditional":"外匯"},{"id":"外行话","hanzi":"外行话","pinyin":"wàihánghuà","meaning_vi":"lời nói của người không chuyên","explanation":"外 (ngoài) + 行 (được) + 话 (话).","hsk_level":"7-9","tags":["danh-tu","giao-tiep"],"image":"🗣️","examples":[{"type":"basic","zh":"别说外行话了。","pinyin":"Biéshuō wàihánghuà le.","vi":"Đừng nói lời ngoại đạo nữa."},{"type":"simple","zh":"他那几句外行话惹得在场的工程师们哈哈大笑。","pinyin":"Tā nà jǐ jù wàihánghuà rě de zài chǎng de gōngchéngshīmen hāhā dàxiào.","vi":"Mấy câu nói ngoại đạo của anh ta khiến các kỹ sư có mặt cười phá lên."},{"type":"compound","zh":"如果不懂装懂，你一开口就会说出外行话。","pinyin":"Rúguǒ bù dǒng zhuāng dǒng, nǐ yì kāikǒu jiù huì shuōchū wàihánghuà.","vi":"Nếu không hiểu mà làm ra vẻ hiểu, vừa mở miệng bạn sẽ lộ ra lời ngoại đạo."}],"related":[{"hanzi":"外行","pinyin":"wàiháng","vi":"người ngoài nghề"},{"hanzi":"内行","pinyin":"nèiháng","vi":"người trong nghề"},{"hanzi":"门外汉","pinyin":"ménwàihàn","vi":"người ngoại đạo"},{"hanzi":"行话","pinyin":"hánghuà","vi":"tiếng lóng nghề"}],"traditional":"外行話"},{"id":"外交辞令","hanzi":"外交辞令","pinyin":"wàijiāocílìng","meaning_vi":"lời lẽ ngoại giao khéo léo","explanation":"外 (ngoài) + 交 (giao) + 辞 (từ chức/lời lẽ) + 令 (mệnh lệnh/khiến cho).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","giao-tiep"],"image":"👔","examples":[{"type":"basic","zh":"这只是外交辞令。","pinyin":"Zhè zhǐshì wàijiāocílìng.","vi":"Đây chỉ là lời lẽ ngoại giao."},{"type":"simple","zh":"发言人用一句外交辞令回避了记者的提问。","pinyin":"Fāyánrén yòng yíjù wàijiāocílìng huíbìle jìzhě de tíwèn.","vi":"Người phát ngôn dùng một câu ngoại giao khéo léo để né câu hỏi của phóng viên."},{"type":"compound","zh":"虽然声明里满是外交辞令，但是不满的态度显而易见。","pinyin":"Suīrán shēngmíng lǐ mǎnshì wàijiāocílìng, dànshì bùmǎn de tàidù xiǎn'éryìjiàn.","vi":"Tuy tuyên bố đầy lời lẽ ngoại giao, nhưng thái độ bất mãn thì ai cũng thấy rõ."}],"related":[{"hanzi":"外交","pinyin":"wàijiāo","vi":"ngoại giao"},{"hanzi":"客套话","pinyin":"kètàohuà","vi":"lời khách sáo"},{"hanzi":"委婉","pinyin":"wěiwǎn","vi":"uyển chuyển"},{"hanzi":"官话","pinyin":"guānhuà","vi":"lời quan cách"}],"traditional":"外交辭令"},{"id":"外交官","hanzi":"外交官","pinyin":"wàijiāoguān","meaning_vi":"nhà ngoại giao","explanation":"外交 + 官 (quan chức).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","xa-hoi"],"image":"👔","examples":[{"type":"basic","zh":"她的父亲是外交官。","pinyin":"Tā de fùqīn shì wàijiāoguān.","vi":"Bố cô ấy là nhà ngoại giao."},{"type":"simple","zh":"这位资深外交官曾在五个国家担任大使。","pinyin":"Zhè wèi zīshēn wàijiāoguān céng zài wǔ gè guójiā dānrèn dàshǐ.","vi":"Nhà ngoại giao kỳ cựu này từng làm đại sứ ở năm nước."},{"type":"compound","zh":"要成为一名外交官，不但要精通外语，而且要熟悉国际法。","pinyin":"Yào chéngwéi yì míng wàijiāoguān, búdàn yào jīngtōng wàiyǔ, érqiě yào shúxī guójìfǎ.","vi":"Muốn trở thành nhà ngoại giao, không chỉ phải thông thạo ngoại ngữ mà còn phải am hiểu luật quốc tế."}],"related":[{"hanzi":"大使","pinyin":"dàshǐ","vi":"đại sứ"},{"hanzi":"领事","pinyin":"lǐngshì","vi":"lãnh sự"},{"hanzi":"外交部","pinyin":"Wàijiāobù","vi":"Bộ Ngoại giao"},{"hanzi":"使馆","pinyin":"shǐguǎn","vi":"sứ quán"}]},{"id":"外流","hanzi":"外流","pinyin":"wàiliú","meaning_vi":"chảy ra ngoài (nhân tài/vốn)","explanation":"外 (ngoài) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"📉","examples":[{"type":"basic","zh":"人才外流很严重。","pinyin":"Réncái wàiliú hěn yánzhòng.","vi":"Chảy máu chất xám rất nghiêm trọng."},{"type":"simple","zh":"小县城的年轻劳动力大量外流到沿海城市。","pinyin":"Xiǎo xiànchéng de niánqīng láodònglì dàliàng wàiliú dào yánhǎi chéngshì.","vi":"Lao động trẻ ở huyện nhỏ ồ ạt đổ ra các thành phố ven biển."},{"type":"compound","zh":"如果待遇一直上不去，技术骨干就会不断外流。","pinyin":"Rúguǒ dàiyù yìzhí shàng bú qù, jìshù gǔgàn jiù huì búduàn wàiliú.","vi":"Nếu đãi ngộ mãi không tăng, nhân lực kỹ thuật nòng cốt sẽ liên tục bỏ đi."}],"related":[{"hanzi":"人才外流","pinyin":"réncáiwàiliú","vi":"chảy máu chất xám"},{"hanzi":"流失","pinyin":"liúshī","vi":"thất thoát"},{"hanzi":"外迁","pinyin":"wàiqiān","vi":"di cư ra ngoài"},{"hanzi":"回流","pinyin":"huíliú","vi":"quay về"}]},{"id":"外貌","hanzi":"外貌","pinyin":"wàimào","meaning_vi":"ngoại hình, diện mạo","explanation":"外 (ngoài) + 貌 (diện mạo).","hsk_level":"7-9","tags":["danh-tu","con-nguoi"],"image":"👤","examples":[{"type":"basic","zh":"别以外貌取人。","pinyin":"Bié yǐ wàimào qǔ rén.","vi":"Đừng đánh giá người qua ngoại hình."},{"type":"simple","zh":"十年过去了，他的外貌几乎没有什么变化。","pinyin":"Shí nián guòqù le, tā de wàimào jīhū méiyǒu shénme biànhuà.","vi":"Mười năm trôi qua, diện mạo của anh ấy hầu như không thay đổi."},{"type":"compound","zh":"虽然她外貌平平，但是一开口就让人印象深刻。","pinyin":"Suīrán tā wàimào píngpíng, dànshì yì kāikǒu jiù ràng rén yìnxiàng shēnkè.","vi":"Tuy ngoại hình bình thường, nhưng cô ấy vừa mở lời đã khiến người ta ấn tượng sâu sắc."}],"related":[{"hanzi":"容貌","pinyin":"róngmào","vi":"dung mạo"},{"hanzi":"长相","pinyin":"zhǎngxiàng","vi":"diện mạo"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"},{"hanzi":"相貌","pinyin":"xiàngmào","vi":"tướng mạo"}]},{"id":"外贸","hanzi":"外贸","pinyin":"wàimào","meaning_vi":"ngoại thương","explanation":"外 (ngoài) + 贸 (thương mại).","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"🚢","examples":[{"type":"basic","zh":"她在外贸公司上班。","pinyin":"Tā zài wàimào gōngsī shàngbān.","vi":"Cô ấy làm việc ở công ty ngoại thương."},{"type":"simple","zh":"今年前三季度，这个港口城市的外贸总额创下新高。","pinyin":"Jīn niánqián sān jìdù, zhè ge gǎngkǒu chéngshì de wàimào zǒng'é chuàngxià xīngāo.","vi":"Ba quý đầu năm nay, tổng kim ngạch ngoại thương của thành phố cảng này lập kỷ lục mới."},{"type":"compound","zh":"因为人民币汇率波动，所以外贸企业的利润受到影响。","pinyin":"Yīnwèi rénmínbì huìlǜbōdòng, suǒyǐ wàimào qǐyè de lìrùn shòudào yǐngxiǎng.","vi":"Vì tỷ giá đồng nhân dân tệ biến động nên lợi nhuận của doanh nghiệp ngoại thương bị ảnh hưởng."}],"related":[{"hanzi":"对外贸易","pinyin":"duìwàimàoyì","vi":"ngoại thương"},{"hanzi":"进出口","pinyin":"jìnchūkǒu","vi":"xuất nhập khẩu"},{"hanzi":"内贸","pinyin":"nèimào","vi":"nội thương"},{"hanzi":"海关","pinyin":"hǎiguān","vi":"hải quan"}],"traditional":"外貿"},{"id":"外企","hanzi":"外企","pinyin":"wàiqǐ","meaning_vi":"doanh nghiệp nước ngoài","explanation":"外 (ngoài) + 企 (doanh nghiệp/mưu toan).","hsk_level":"7-9","tags":["danh-tu","cong-viec","dia-diem"],"image":"🏢","examples":[{"type":"basic","zh":"他在一家外企工作。","pinyin":"Tā zài yìjiā wàiqǐ gōngzuò.","vi":"Anh ấy làm việc cho một doanh nghiệp nước ngoài."},{"type":"simple","zh":"这家外企为员工提供每年两次的海外培训。","pinyin":"Zhè jiā wàiqǐ wèi yuángōng tígōng měinián liǎng cì de hǎiwài péixùn.","vi":"Doanh nghiệp nước ngoài này cho nhân viên đi đào tạo ở nước ngoài hai lần mỗi năm."},{"type":"compound","zh":"虽然外企工资高，但是他更看重国企的稳定。","pinyin":"Suīrán wàiqǐ gōngzī gāo, dànshì tā gèng kànzhòng guóqǐ de wěndìng.","vi":"Tuy doanh nghiệp nước ngoài lương cao, nhưng anh ấy coi trọng sự ổn định của doanh nghiệp nhà nước hơn."}],"related":[{"hanzi":"外资企业","pinyin":"wàizīqǐyè","vi":"doanh nghiệp vốn ngoại"},{"hanzi":"国企","pinyin":"guóqǐ","vi":"doanh nghiệp nhà nước"},{"hanzi":"私企","pinyin":"sīqǐ","vi":"doanh nghiệp tư nhân"},{"hanzi":"跨国公司","pinyin":"kuàguógōngsī","vi":"công ty đa quốc gia"}]},{"id":"外在","hanzi":"外在","pinyin":"wàizài","meaning_vi":"bên ngoài","explanation":"外 (ngoài) + 在 (ở).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🪞","examples":[{"type":"basic","zh":"外在美并不重要。","pinyin":"Wàizàiměi bìngbú zhòngyào.","vi":"Vẻ đẹp bên ngoài không quan trọng lắm."},{"type":"simple","zh":"市场波动等外在因素影响了公司的业绩。","pinyin":"Shìchǎng bōdòng děng wàizài yīnsù yǐngxiǎngle gōngsī de yèjì.","vi":"Các yếu tố bên ngoài như biến động thị trường đã ảnh hưởng đến kết quả kinh doanh của công ty."},{"type":"compound","zh":"与其在意外在的评价，不如专注于内心的成长。","pinyin":"Yǔqí zàiyì wàizài de píngjià, bùrú zhuānzhù yú nèixīn de chéngzhǎng.","vi":"Thay vì bận tâm đến đánh giá bên ngoài, chi bằng tập trung vào sự trưởng thành bên trong."}],"related":[{"hanzi":"内在","pinyin":"nèizài","vi":"bên trong"},{"hanzi":"外表","pinyin":"wàibiǎo","vi":"bề ngoài"},{"hanzi":"外在美","pinyin":"wàizàiměi","vi":"vẻ đẹp bên ngoài"},{"hanzi":"表面","pinyin":"biǎomiàn","vi":"bề mặt"}]},{"id":"万变不离其宗","hanzi":"万变不离其宗","pinyin":"wàn biàn bù lí qí zōng","meaning_vi":"vạn biến không rời bản chất gốc","explanation":"万 (vạn vật/tuyệt đối) + 变 (biến đổi/biến cố) + 不 (không/bất) + 离 (cách (khoảng cách)) + 其 (其) + 宗 (tôn chỉ/tông phái).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"☯️","examples":[{"type":"basic","zh":"方法再多，万变不离其宗。","pinyin":"Fāngfǎ zài duō, wànbiànbùlíqízōng.","vi":"Cách làm dù nhiều đến đâu cũng không rời bản chất gốc."},{"type":"simple","zh":"老师说数学题的解法万变不离其宗。","pinyin":"Lǎoshī shuō shùxué tí de jiěfǎ wànbiànbùlíqízōng.","vi":"Thầy nói cách giải toán dù biến hóa thế nào cũng không rời nguyên lý gốc."},{"type":"compound","zh":"虽然时装潮流年年在变，但是剪裁的原则万变不离其宗。","pinyin":"Suīrán shízhuāng cháoliú niánnián zài biàn, dànshì jiǎncái de yuánzé wànbiànbùlíqízōng.","vi":"Tuy xu hướng thời trang năm nào cũng thay đổi, nhưng nguyên tắc cắt may vẫn vạn biến bất ly kỳ tông."}],"related":[{"hanzi":"本质","pinyin":"běnzhì","vi":"bản chất"},{"hanzi":"根本","pinyin":"gēnběn","vi":"căn bản"},{"hanzi":"千变万化","pinyin":"qiānbiànwànhuà","vi":"thiên biến vạn hóa"},{"hanzi":"换汤不换药","pinyin":"huàn tāng bú huàn yào","vi":"bình mới rượu cũ"}],"traditional":"萬變不離其宗"},{"id":"万家灯火","hanzi":"万家灯火","pinyin":"wànjiā-dēnghuǒ","meaning_vi":"ánh đèn muôn nhà (cảnh đêm thành phố ấm áp)","explanation":"万 (vạn vật/tuyệt đối) + 家 (nhà) + 灯 (cái đèn) + 火 (火).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌃","examples":[{"type":"basic","zh":"夜幕下万家灯火。","pinyin":"Yèmù xià wànjiādēnghuǒ.","vi":"Dưới màn đêm, đèn muôn nhà sáng rực."},{"type":"simple","zh":"我站在阳台上望着远处的万家灯火。","pinyin":"Wǒ zhàn zài yángtái shàng wàngzhe yuǎnchù de wànjiādēnghuǒ.","vi":"Tôi đứng trên ban công ngắm ánh đèn muôn nhà phía xa."},{"type":"compound","zh":"每当万家灯火亮起，在外漂泊的他就格外想家。","pinyin":"Měidāng wànjiādēnghuǒ liàng qǐ, zài wài piāobó de tā jiù géwài xiǎngjiā.","vi":"Mỗi khi đèn muôn nhà bừng sáng, anh ấy lưu lạc nơi xa lại đặc biệt nhớ nhà."}],"related":[{"hanzi":"灯火通明","pinyin":"dēnghuǒtōngmíng","vi":"đèn đuốc sáng trưng"},{"hanzi":"夜景","pinyin":"yèjǐng","vi":"cảnh đêm"},{"hanzi":"灯光","pinyin":"dēngguāng","vi":"ánh đèn"},{"hanzi":"团圆","pinyin":"tuányuán","vi":"đoàn viên"}],"traditional":"萬家燈火"},{"id":"万能","hanzi":"万能","pinyin":"wànnéng","meaning_vi":"vạn năng, đa năng","explanation":"万 (vạn vật/tuyệt đối) + 能 (có thể (năng lực/điều kiện)).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🛠️","examples":[{"type":"basic","zh":"钱不是万能的。","pinyin":"Qián bú shì wànnéng de.","vi":"Tiền không phải là vạn năng."},{"type":"simple","zh":"这把万能钥匙可以打开酒店所有的房门。","pinyin":"Zhè bǎ wànnéng yàoshi kěyǐ dǎkāi jiǔdiàn suǒyǒu de fángmén.","vi":"Chiếc chìa khóa vạn năng này có thể mở tất cả các phòng trong khách sạn."},{"type":"compound","zh":"虽然网络不是万能的，但是没有网络确实寸步难行。","pinyin":"Suīrán wǎngluò bú shì wànnéng de, dànshì méiyǒu wǎngluò quèshí cùnbùnánxíng.","vi":"Tuy mạng internet không phải vạn năng, nhưng không có mạng thì quả thật khó mà làm gì được."}],"related":[{"hanzi":"全能","pinyin":"quánnéng","vi":"toàn năng"},{"hanzi":"万能钥匙","pinyin":"wànnéngyàoshi","vi":"chìa khóa vạn năng"},{"hanzi":"多功能","pinyin":"duōgōngnéng","vi":"đa chức năng"},{"hanzi":"无所不能","pinyin":"wúsuǒbùnéng","vi":"không gì không làm được"}],"traditional":"萬能"},{"id":"万人空巷","hanzi":"万人空巷","pinyin":"wànrén-kōngxiàng","meaning_vi":"cả phố đổ ra xem (sự kiện cực kỳ thu hút)","explanation":"万 (vạn vật/tuyệt đối) + 人 (người) + 空 (trống rỗng/không gian) + 巷 (ngõ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👥","examples":[{"type":"basic","zh":"比赛那天万人空巷。","pinyin":"Bǐsài nà tiān wànrénkōngxiàng.","vi":"Hôm thi đấu, cả thành phố đổ ra xem."},{"type":"simple","zh":"冠军队凯旋的游行引得全城万人空巷。","pinyin":"Guàn jūnduì kǎixuán de yóuxíng yǐnde quánchéng wànrénkōngxiàng.","vi":"Cuộc diễu hành mừng đội vô địch trở về khiến cả thành phố đổ ra đường."},{"type":"compound","zh":"因为今晚有烟花表演，所以全城万人空巷，江边挤满了人。","pinyin":"Yīnwèi jīnwǎn yǒu yānhuā biǎoyǎn, suǒyǐ quánchéng wànrénkōngxiàng, jiāngbiān jǐmǎnle rén.","vi":"Vì tối nay có bắn pháo hoa nên cả thành phố đổ ra đường, bờ sông chật kín người."}],"related":[{"hanzi":"人山人海","pinyin":"rénshānrénhǎi","vi":"biển người"},{"hanzi":"轰动","pinyin":"hōngdòng","vi":"chấn động"},{"hanzi":"盛况空前","pinyin":"shèngkuàngkōngqián","vi":"cảnh tượng chưa từng có"},{"hanzi":"冷冷清清","pinyin":"lěnglěngqīngqīng","vi":"vắng vẻ"}],"traditional":"萬人空巷"},{"id":"万事俱备","hanzi":"万事俱备","pinyin":"wànshì-jùbèi","meaning_vi":"mọi việc đã sẵn sàng","explanation":"万 (vạn vật/tuyệt đối) + 事 (sự nghiệp/sự kiện) + 俱 (俱) + 备 (chuẩn bị/đầy đủ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✅","examples":[{"type":"basic","zh":"现在万事俱备了。","pinyin":"Xiànzài wànshìjùbèi le.","vi":"Giờ thì mọi việc đã sẵn sàng."},{"type":"simple","zh":"登山队员们检查完装备后宣布万事俱备。","pinyin":"Dēngshān duìyuánmen jiǎnchá wán zhuāngbèi hòu xuānbù wànshìjùbèi.","vi":"Các thành viên đội leo núi kiểm tra xong trang bị rồi tuyên bố mọi thứ đã sẵn sàng."},{"type":"compound","zh":"既然万事俱备，我们明天一早就出发吧。","pinyin":"Jìrán wànshìjùbèi, wǒmen míngtiān yìzǎo jiù chūfā ba.","vi":"Mọi việc đã sẵn sàng rồi thì sáng sớm mai chúng ta xuất phát nhé."}],"related":[{"hanzi":"万事俱备只欠东风","pinyin":"wànshìjùbèi zhǐ qiàn dōngfēng","vi":"mọi thứ đủ chỉ thiếu gió đông"},{"hanzi":"准备就绪","pinyin":"zhǔnbèijiùxù","vi":"đã sẵn sàng"},{"hanzi":"齐全","pinyin":"qíquán","vi":"đầy đủ"},{"hanzi":"有备无患","pinyin":"yǒubèiwúhuàn","vi":"có chuẩn bị thì không lo"}],"traditional":"萬事俱備"},{"id":"旺","hanzi":"旺","pinyin":"wàng","meaning_vi":"cháy rực, cháy to; thịnh vượng, đông đúc, phát đạt","explanation":"旺 (thịnh vượng/rực cháy).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🔥","examples":[{"type":"basic","zh":"炉火烧得正旺。","pinyin":"Lúhuǒ shāo de zhèng wàng.","vi":"Lửa lò đang cháy rực."},{"type":"simple","zh":"这家新开的火锅店生意特别旺。","pinyin":"Zhè jiā xīn kāi de huǒguōdiàn shēngyi tèbié wàng.","vi":"Quán lẩu mới mở này làm ăn đặc biệt phát đạt."},{"type":"compound","zh":"因为春节前人气旺，所以商场把促销活动提前了一周。","pinyin":"Yīnwèi Chūnjié qián rénqì wàng, suǒyǐ shāngchǎng bǎ cùxiāo huódòng tíqiánle yìzhōu.","vi":"Vì trước Tết lượng khách đông đúc nên trung tâm thương mại đẩy chương trình khuyến mãi lên sớm một tuần."}],"related":[{"hanzi":"兴旺","pinyin":"xīngwàng","vi":"thịnh vượng"},{"hanzi":"旺盛","pinyin":"wàngshèng","vi":"dồi dào"},{"hanzi":"火旺","pinyin":"huǒwàng","vi":"lửa cháy mạnh"},{"hanzi":"旺季","pinyin":"wàngjì","vi":"mùa cao điểm"}]},{"id":"旺季","hanzi":"旺季","pinyin":"wàngjì","meaning_vi":"mùa cao điểm (du lịch/kinh doanh)","explanation":"旺 (vượng – thịnh, đông đúc) + 季 (quý – mùa) → mùa cao điểm, mùa đắt hàng. Trái nghĩa: 淡季 (mùa thấp điểm).","hsk_level":"7-9","tags":["danh-tu","cong-viec","du-lich"],"image":"📈","examples":[{"type":"basic","zh":"七月是旅游旺季。","pinyin":"Qīyuè shì lǚyóu wàngjì.","vi":"Tháng Bảy là mùa cao điểm du lịch."},{"type":"simple","zh":"旺季期间海边酒店的房价几乎翻了一倍。","pinyin":"Wàngjì qījiān hǎibiān jiǔdiàn de fángjià jīhū fānle yí bèi.","vi":"Vào mùa cao điểm, giá phòng khách sạn ven biển gần như tăng gấp đôi."},{"type":"compound","zh":"如果你在旺季出行，就最好提前一个月订票。","pinyin":"Rúguǒ nǐ zài wàngjì chūxíng, jiù zuìhǎo tíqián yí gèyuè dìngpiào.","vi":"Nếu bạn đi du lịch vào mùa cao điểm thì tốt nhất nên đặt vé trước một tháng."}],"related":[{"hanzi":"淡季","pinyin":"dànjì","vi":"mùa thấp điểm"},{"hanzi":"高峰期","pinyin":"gāofēngqī","vi":"thời kỳ cao điểm"},{"hanzi":"旅游旺季","pinyin":"lǚyóuwàngjì","vi":"mùa du lịch cao điểm"},{"hanzi":"黄金周","pinyin":"huángjīnzhōu","vi":"tuần lễ vàng"}]},{"id":"忘却","hanzi":"忘却","pinyin":"wàngquè","meaning_vi":"quên lãng","explanation":"忘 (quên) + 却 (lại).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"历史不容忘却。","pinyin":"Lìshǐ bùróng wàngquè.","vi":"Lịch sử không được phép lãng quên."},{"type":"simple","zh":"那段艰苦的岁月他始终无法忘却。","pinyin":"Nà duàn jiānkǔ de suìyuè tā shǐzhōng wúfǎ wàngquè.","vi":"Những năm tháng gian khổ ấy ông ấy mãi không thể quên."},{"type":"compound","zh":"一听到这首老歌，她就忘却了工作的烦恼。","pinyin":"Yì tīngdào zhè shǒu lǎogē, tā jiù wàngquèle gōngzuò de fánnǎo.","vi":"Vừa nghe bài hát cũ này, cô ấy liền quên hết phiền muộn công việc."}],"related":[{"hanzi":"遗忘","pinyin":"yíwàng","vi":"quên lãng"},{"hanzi":"忘记","pinyin":"wàngjì","vi":"quên"},{"hanzi":"铭记","pinyin":"míngjì","vi":"ghi nhớ"},{"hanzi":"记忆","pinyin":"jìyì","vi":"ký ức"}],"traditional":"忘卻"},{"id":"忘我","hanzi":"忘我","pinyin":"wàngwǒ","meaning_vi":"quên mình (làm việc hăng say quên bản thân)","explanation":"忘 (quên) + 我 (tôi).","hsk_level":"7-9","tags":["tinh-tu","cong-viec"],"image":"🔥","examples":[{"type":"basic","zh":"他忘我地工作着。","pinyin":"Tā wàngwǒ de gōngzuò zhe.","vi":"Anh ấy làm việc quên mình."},{"type":"simple","zh":"舞台上的钢琴家完全沉浸在忘我的演奏中。","pinyin":"Wǔtái shàng de gāngqínjiā wánquán chénjìn zài wàngwǒ de yǎnzòu zhōng.","vi":"Nghệ sĩ dương cầm trên sân khấu hoàn toàn đắm chìm trong tiếng đàn quên mình."},{"type":"compound","zh":"因为她忘我地投入研究，所以常常忘了吃饭。","pinyin":"Yīnwèi tā wàngwǒ de tóurù yánjiū, suǒyǐ chángcháng wàngle chīfàn.","vi":"Vì cô ấy say mê nghiên cứu quên cả bản thân nên thường quên cả ăn cơm."}],"related":[{"hanzi":"废寝忘食","pinyin":"fèiqǐnwàngshí","vi":"quên ăn quên ngủ"},{"hanzi":"全神贯注","pinyin":"quánshénguànzhù","vi":"tập trung cao độ"},{"hanzi":"投入","pinyin":"tóurù","vi":"dồn hết"},{"hanzi":"无私","pinyin":"wúsī","vi":"vô tư"}]},{"id":"望洋兴叹","hanzi":"望洋兴叹","pinyin":"wàngyáng-xīngtàn","meaning_vi":"đứng trước biển lớn than thở (bất lực vì sức mình có hạn)","explanation":"望 (triển vọng/danh vọng) + 洋 (đại dương/nước ngoài) + 兴 (hưng thịnh/hứng thú) + 叹 (cảm thán/thở dài).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🌊","examples":[{"type":"basic","zh":"看着房价，他只能望洋兴叹。","pinyin":"Kànzhe fángjià, tā zhǐnéng wàngyángxīngtàn.","vi":"Nhìn giá nhà, anh ấy chỉ biết than thở bất lực."},{"type":"simple","zh":"面对昂贵的学费，许多家庭只能望洋兴叹。","pinyin":"Miànduì ángguì de xuéfèi, xǔduō jiātíng zhǐnéng wàngyángxīngtàn.","vi":"Trước mức học phí đắt đỏ, nhiều gia đình chỉ biết than thở bất lực."},{"type":"compound","zh":"如果不提前储备技术，我们就只能对新市场望洋兴叹。","pinyin":"Rúguǒ bù tíqián chǔbèi jìshù, wǒmen jiù zhǐnéng duì xīn shìchǎng wàngyángxīngtàn.","vi":"Nếu không chuẩn bị công nghệ từ trước, chúng ta chỉ có thể đứng nhìn thị trường mới mà than thở."}],"related":[{"hanzi":"无能为力","pinyin":"wúnéngwéilì","vi":"bất lực"},{"hanzi":"力不从心","pinyin":"lìbùcóngxīn","vi":"lực bất tòng tâm"},{"hanzi":"束手无策","pinyin":"shùshǒuwúcè","vi":"bó tay"},{"hanzi":"无可奈何","pinyin":"wúkěnàihé","vi":"không biết làm sao"}],"traditional":"望洋興嘆"},{"id":"望而却步","hanzi":"望而却步","pinyin":"wàng'ér-quèbù","meaning_vi":"nhìn thấy đã chùn bước (vì quá khó/nguy hiểm)","explanation":"望 (triển vọng/danh vọng) + 而 (mà) + 却 (lại) + 步 (bước đi/tiến bộ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😨","examples":[{"type":"basic","zh":"高价让人望而却步。","pinyin":"Gāojià ràng rén wàng'érquèbù.","vi":"Giá cao khiến người ta vừa nhìn đã chùn bước."},{"type":"simple","zh":"复杂的申请手续让不少创业者望而却步。","pinyin":"Fùzá de shēnqǐng shǒuxù ràng bùshǎo chuàngyèzhě wàng'érquèbù.","vi":"Thủ tục đăng ký phức tạp khiến không ít người khởi nghiệp chùn bước."},{"type":"compound","zh":"虽然这条登山路线风景绝美，但是陡峭的崖壁让很多人望而却步。","pinyin":"Suīrán zhè tiáo dēngshān lùxiàn fēngjǐng juéměi, dànshì dǒuqiào de yábì ràng hěn duō rén wàng'érquèbù.","vi":"Tuy cung đường leo núi này phong cảnh tuyệt đẹp, nhưng vách đá dựng đứng khiến nhiều người vừa nhìn đã nản."}],"related":[{"hanzi":"望而生畏","pinyin":"wàng'érshēngwèi","vi":"nhìn đã sợ"},{"hanzi":"退缩","pinyin":"tuìsuō","vi":"lùi bước"},{"hanzi":"知难而退","pinyin":"zhīnán'értuì","vi":"biết khó mà lui"},{"hanzi":"迎难而上","pinyin":"yíngnán'érshàng","vi":"đón khó mà tiến"}],"traditional":"望而卻步"},{"id":"完结","hanzi":"完结","pinyin":"wánjié","meaning_vi":"kết thúc trọn vẹn (bộ truyện/phim)","explanation":"完 (hoàn thiện/nguyên vẹn) + 结 (kết hợp/kết tinh).","hsk_level":"7-9","tags":["dong-tu","giai-tri"],"image":"🏁","examples":[{"type":"basic","zh":"这部动画完结了。","pinyin":"Zhè bù dònghuà wánjié le.","vi":"Bộ phim hoạt hình này đã kết thúc."},{"type":"simple","zh":"这部连载了十年的漫画终于在上个月完结。","pinyin":"Zhè bù liánzǎile shí nián de mànhuà zhōngyú zài shànggèyuè wánjié.","vi":"Bộ truyện tranh đăng dài kỳ mười năm này cuối cùng đã kết thúc vào tháng trước."},{"type":"compound","zh":"等这部剧完结以后，我就一口气从头看到尾。","pinyin":"Děng zhè bù jù wánjié yǐhòu, wǒ jiù yìkǒuqì cóngtóu kàndào wěi.","vi":"Đợi bộ phim này chiếu hết, tôi sẽ xem một mạch từ đầu đến cuối."}],"related":[{"hanzi":"完毕","pinyin":"wánbì","vi":"hoàn tất"},{"hanzi":"结束","pinyin":"jiéshù","vi":"kết thúc"},{"hanzi":"大结局","pinyin":"dàjiéjú","vi":"đại kết cục"},{"hanzi":"连载","pinyin":"liánzǎi","vi":"đăng nhiều kỳ"}],"traditional":"完結"},{"id":"完美无缺","hanzi":"完美无缺","pinyin":"wánměi-wúquē","meaning_vi":"hoàn mỹ không tì vết","explanation":"完 (hoàn thiện/nguyên vẹn) + 美 (tươi đẹp/mỹ mãn) + 无 (vô tận/không có) + 缺 (thiếu hụt/khiếm khuyết).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"世上没有完美无缺的人。","pinyin":"Shìshàng méiyǒu wánměiwúquē de rén.","vi":"Trên đời không có ai hoàn mỹ không tì vết."},{"type":"simple","zh":"评委认为她这套自由体操动作完美无缺。","pinyin":"Píngwěi rènwéi tā zhè tào zìyóu tǐcāo dòngzuò wánměiwúquē.","vi":"Ban giám khảo cho rằng bài thể dục tự do của cô ấy hoàn hảo không tì vết."},{"type":"compound","zh":"即使计划看起来完美无缺，执行时也难免出现意外。","pinyin":"Jíshǐ jìhuà kànqǐlái wánměiwúquē, zhíxíng shí yě nánmiǎn chūxiàn yìwài.","vi":"Dù kế hoạch trông hoàn hảo không tì vết, khi thực hiện vẫn khó tránh khỏi sự cố."}],"related":[{"hanzi":"十全十美","pinyin":"shíquánshíměi","vi":"thập toàn thập mỹ"},{"hanzi":"完美","pinyin":"wánměi","vi":"hoàn mỹ"},{"hanzi":"无懈可击","pinyin":"wúxièkějī","vi":"không chê vào đâu"},{"hanzi":"美中不足","pinyin":"měizhōngbùzú","vi":"đẹp nhưng chưa trọn"}],"traditional":"完美無缺"},{"id":"位居","hanzi":"位居","pinyin":"wèijū","meaning_vi":"xếp ở vị trí (thứ hạng)","explanation":"位 (vị trí/địa vị) + 居 (cư trú).","hsk_level":"7-9","tags":["dong-tu","the-thao"],"image":"🏅","examples":[{"type":"basic","zh":"我校排名位居第一。","pinyin":"Wǒ xiào páimíng wèijū dìyī.","vi":"Trường chúng tôi xếp hạng thứ nhất."},{"type":"simple","zh":"这家公司的销售额连续三年位居行业榜首。","pinyin":"Zhè jiā gōngsī de xiāoshòu'é liánxù sān nián wèijū hángyè bǎngshǒu.","vi":"Doanh số của công ty này ba năm liền đứng đầu ngành."},{"type":"compound","zh":"虽然中国队目前位居第二，但是与第一名只差一分。","pinyin":"Suīrán Zhōngguó duì mùqián wèijū dì'èr, dànshì yǔ dìyīmíng zhǐ chà yì fēn.","vi":"Tuy đội Trung Quốc hiện xếp thứ hai, nhưng chỉ kém đội đầu bảng một điểm."}],"related":[{"hanzi":"位列","pinyin":"wèiliè","vi":"xếp ở vị trí"},{"hanzi":"排名","pinyin":"páimíng","vi":"xếp hạng"},{"hanzi":"名列前茅","pinyin":"mínglièqiánmáo","vi":"đứng hàng đầu"},{"hanzi":"首位","pinyin":"shǒuwèi","vi":"vị trí đầu"}]},{"id":"未免","hanzi":"未免","pinyin":"wèimiǎn","meaning_vi":"có phần, thật là hơi (quá) (đánh giá không tán thành một cách nhẹ nhàng)","explanation":"未 (vị – chưa) + 免 (miễn – tránh) → \"chưa tránh khỏi\", dùng để nhận xét nhẹ nhàng rằng việc gì đó hơi quá. Ví dụ: 这样做未免太急了.","hsk_level":"7-9","tags":["pho-tu"],"image":"🤔","examples":[{"type":"basic","zh":"这未免太贵了。","pinyin":"Zhè wèimiǎn tài guì le.","vi":"Cái này có hơi đắt quá rồi."},{"type":"simple","zh":"你为这点小事发这么大的火未免太冲动了。","pinyin":"Nǐ wèi zhè diǎn xiǎoshì fā zhème dà de huǒ wèimiǎn tài chōngdòng le.","vi":"Vì chuyện nhỏ thế này mà bạn nổi giận lớn như vậy thì hơi bốc đồng quá."},{"type":"compound","zh":"既然大家都同意了，你再反对就未免有点不近人情。","pinyin":"Jìrán dàjiā dōu tóngyì le, nǐ zài fǎnduì jiù wèimiǎn yǒudiǎn bú jìn rénqíng.","vi":"Mọi người đều đã đồng ý rồi, bạn còn phản đối thì có phần hơi thiếu tình người."}],"related":[{"hanzi":"不免","pinyin":"bùmiǎn","vi":"khó tránh"},{"hanzi":"难免","pinyin":"nánmiǎn","vi":"khó tránh khỏi"},{"hanzi":"有点儿","pinyin":"yǒudiǎnr","vi":"hơi"},{"hanzi":"过于","pinyin":"guòyú","vi":"quá mức"}]},{"id":"为期不远","hanzi":"为期不远","pinyin":"wéiqī-bùyuǎn","meaning_vi":"không còn xa nữa (sắp diễn ra)","explanation":"为 (vì) + 期 (期) + 不 (không/bất) + 远 (xa).","hsk_level":"7-9","tags":["thanh-ngu","thoi-gian"],"image":"⏳","examples":[{"type":"basic","zh":"胜利已为期不远。","pinyin":"Shènglì yǐ wéiqībùyuǎn.","vi":"Thắng lợi không còn xa nữa."},{"type":"simple","zh":"两国领导人会晤的日子已经为期不远了。","pinyin":"Liǎngguó lǐngdǎorén huìwù de rìzi yǐjīng wéiqībùyuǎn le.","vi":"Ngày lãnh đạo hai nước hội đàm đã không còn xa."},{"type":"compound","zh":"只要试验数据继续向好，新药上市就为期不远了。","pinyin":"Zhǐyào shìyàn shùjù jìxù xiàng hǎo, xīn yào shàngshì jiù wéiqībùyuǎn le.","vi":"Chỉ cần dữ liệu thử nghiệm tiếp tục khả quan, thuốc mới sẽ sớm được tung ra thị trường."}],"related":[{"hanzi":"指日可待","pinyin":"zhǐrìkědài","vi":"sắp thành hiện thực"},{"hanzi":"即将","pinyin":"jíjiāng","vi":"sắp sửa"},{"hanzi":"为期","pinyin":"wéiqī","vi":"thời hạn"},{"hanzi":"遥遥无期","pinyin":"yáoyáowúqī","vi":"xa vời vô hạn"}],"traditional":"為期不遠"},{"id":"为首","hanzi":"为首","pinyin":"wéishǒu","meaning_vi":"đứng đầu, cầm đầu","explanation":"为 (vì) + 首 (bài (lượng từ thơ/ca khúc)).","hsk_level":"7-9","tags":["dong-tu"],"image":"👑","examples":[{"type":"basic","zh":"以他为首的团队获奖了。","pinyin":"Yǐ tā wéishǒu de tuánduì huòjiǎng le.","vi":"Nhóm do anh ấy đứng đầu đã đoạt giải."},{"type":"simple","zh":"以王教授为首的专家组昨天抵达了灾区。","pinyin":"Yǐ Wáng jiàoshòu wéishǒu de zhuānjiā zǔ zuótiān dǐdále zāiqū.","vi":"Tổ chuyên gia do giáo sư Vương dẫn đầu đã đến vùng thiên tai hôm qua."},{"type":"compound","zh":"因为以他为首的几个人带头闹事，所以整场会议被迫中断。","pinyin":"Yīnwèi yǐ tā wéishǒu de jǐ gè rén dàitóu nàoshì, suǒyǐ zhěng chǎng huìyì bèipò zhōngduàn.","vi":"Vì mấy người do hắn cầm đầu gây rối nên cả cuộc họp buộc phải gián đoạn."}],"related":[{"hanzi":"带头","pinyin":"dàitóu","vi":"dẫn đầu"},{"hanzi":"领头","pinyin":"lǐngtóu","vi":"cầm đầu"},{"hanzi":"首领","pinyin":"shǒulǐng","vi":"thủ lĩnh"},{"hanzi":"领导","pinyin":"lǐngdǎo","vi":"lãnh đạo"}],"traditional":"為首"},{"id":"未知数","hanzi":"未知数","pinyin":"wèizhīshù","meaning_vi":"ẩn số (toán học); điều chưa biết, chưa rõ","explanation":"未 (tương lai/chưa) + 知 (tri thức/tri giác) + 数 (đếm).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"❓","examples":[{"type":"basic","zh":"结果还是个未知数。","pinyin":"Jiéguǒ háishì gè wèizhīshù.","vi":"Kết quả vẫn còn là một ẩn số."},{"type":"simple","zh":"请先求出这个方程中的未知数。","pinyin":"Qǐng xiān qiú chū zhè ge fāngchéng zhōng de wèizhīshù.","vi":"Hãy tìm ẩn số trong phương trình này trước."},{"type":"compound","zh":"虽然项目已经启动，但是能否盈利仍是个未知数。","pinyin":"Suīrán xiàngmù yǐjīng qǐdòng, dànshì néngfǒu yínglì réng shì gè wèizhīshù.","vi":"Tuy dự án đã khởi động, nhưng có lãi hay không vẫn là một ẩn số."}],"related":[{"hanzi":"未知","pinyin":"wèizhī","vi":"chưa biết"},{"hanzi":"方程","pinyin":"fāngchéng","vi":"phương trình"},{"hanzi":"变数","pinyin":"biànshù","vi":"biến số"},{"hanzi":"悬念","pinyin":"xuánniàn","vi":"điều chưa rõ"}],"traditional":"未知數"},{"id":"问卷调查","hanzi":"问卷调查","pinyin":"wènjuàndiàochá","meaning_vi":"khảo sát bằng bảng hỏi","explanation":"问 (hỏi) + 卷 (cuộn) + 调 (điều chỉnh/hòa giải) + 查 (tra).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"我们做了问卷调查。","pinyin":"Wǒmen zuòle wènjuàndiàochá.","vi":"Chúng tôi đã làm một cuộc khảo sát bằng bảng hỏi."},{"type":"simple","zh":"学校通过问卷调查了解学生对食堂的满意度。","pinyin":"Xuéxiào tōngguò wènjuàndiàochá liǎojiě xuésheng duì shítáng de mǎnyìdù.","vi":"Nhà trường khảo sát bằng bảng hỏi để tìm hiểu mức độ hài lòng của học sinh với nhà ăn."},{"type":"compound","zh":"如果问卷调查的样本太少，结论就不够可靠。","pinyin":"Rúguǒ wènjuàndiàochá de yàngběn tài shǎo, jiélùn jiù búgòu kěkào.","vi":"Nếu mẫu khảo sát bảng hỏi quá ít thì kết luận sẽ không đủ tin cậy."}],"related":[{"hanzi":"问卷","pinyin":"wènjuàn","vi":"bảng hỏi"},{"hanzi":"调查","pinyin":"diàochá","vi":"điều tra"},{"hanzi":"填写","pinyin":"tiánxiě","vi":"điền"},{"hanzi":"抽样调查","pinyin":"chōuyàngdiàochá","vi":"điều tra chọn mẫu"}],"traditional":"問卷調查"},{"id":"问心无愧","hanzi":"问心无愧","pinyin":"wènxīn-wúkuì","meaning_vi":"lòng không hổ thẹn với lương tâm","explanation":"问 (vấn đề/hỏi thăm) + 心 (tâm lý/tâm huyết) + 无 (vô tận/không có) + 愧 (xấu hổ/hổ thẹn).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"我对此问心无愧。","pinyin":"Wǒ duì cǐ wènxīnwúkuì.","vi":"Về chuyện này tôi không hổ thẹn với lương tâm."},{"type":"simple","zh":"这位老医生行医五十年始终问心无愧。","pinyin":"Zhè wèi lǎo yīshēng xíngyī wǔshí nián shǐzhōng wènxīnwúkuì.","vi":"Vị bác sĩ già này hành nghề năm mươi năm, trước sau luôn thanh thản với lương tâm."},{"type":"compound","zh":"只要你尽了全力，即使输了也问心无愧。","pinyin":"Zhǐyào nǐ jìnle quánlì, jíshǐ shūle yě wènxīnwúkuì.","vi":"Chỉ cần bạn đã dốc hết sức thì dù thua cũng không hổ thẹn với lòng."}],"related":[{"hanzi":"心安理得","pinyin":"xīn'ānlǐdé","vi":"yên tâm thanh thản"},{"hanzi":"光明磊落","pinyin":"guāngmínglěiluò","vi":"quang minh lỗi lạc"},{"hanzi":"良心","pinyin":"liángxīn","vi":"lương tâm"},{"hanzi":"于心有愧","pinyin":"yúxīnyǒukuì","vi":"thấy áy náy"}],"traditional":"問心無愧"},{"id":"违法","hanzi":"违法","pinyin":"wéifǎ","meaning_vi":"vi phạm pháp luật","explanation":"违 (làm trái) + 法.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚫","examples":[{"type":"basic","zh":"酒后驾车是违法的。","pinyin":"Jiǔhòu jiàchē shì wéifǎ de.","vi":"Lái xe sau khi uống rượu là vi phạm pháp luật."},{"type":"simple","zh":"这家网站因违法收集用户信息被下架。","pinyin":"Zhè jiā wǎngzhàn yīn wéifǎ shōují yònghù xìnxī bèi xiàjià.","vi":"Trang web này bị gỡ xuống vì thu thập thông tin người dùng trái phép."},{"type":"compound","zh":"即使是为了救急，私自挪用公款也属于违法行为。","pinyin":"Jíshǐ shì wèile jiùjí, sīzì nuóyòng gōngkuǎn yě shǔyú wéifǎ xíngwéi.","vi":"Dù là để cứu gấp, tự ý dùng công quỹ vẫn là hành vi vi phạm pháp luật."}],"related":[{"hanzi":"犯法","pinyin":"fànfǎ","vi":"phạm pháp"},{"hanzi":"守法","pinyin":"shǒufǎ","vi":"tuân thủ pháp luật"},{"hanzi":"违法行为","pinyin":"wéifǎxíngwéi","vi":"hành vi phạm pháp"},{"hanzi":"合法","pinyin":"héfǎ","vi":"hợp pháp"}],"traditional":"違法"},{"id":"围观","hanzi":"围观","pinyin":"wéiguān","meaning_vi":"vây quanh xem","explanation":"围 (vây quanh/phạm vi) + 观 (观).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👀","examples":[{"type":"basic","zh":"路人纷纷围观。","pinyin":"Lùrén fēnfēn wéiguān.","vi":"Người qua đường xúm lại vây xem."},{"type":"simple","zh":"一只迷路的小鹿引来几十名市民围观拍照。","pinyin":"Yì zhī mílù de xiǎo lù yǐn lái jǐ shí míng shìmín wéiguān pāizhào.","vi":"Một chú nai con lạc đường thu hút mấy chục người dân vây quanh chụp ảnh."},{"type":"compound","zh":"与其站在旁边围观，不如帮忙打个急救电话。","pinyin":"Yǔqí zhàn zài pángbiān wéiguān, bùrú bāngmáng dǎ gè jíjiù diànhuà.","vi":"Thay vì đứng bên cạnh vây xem, chi bằng giúp gọi một cuộc điện thoại cấp cứu."}],"related":[{"hanzi":"看热闹","pinyin":"kànrènao","vi":"xem náo nhiệt"},{"hanzi":"旁观","pinyin":"pángguān","vi":"đứng xem"},{"hanzi":"围观群众","pinyin":"wéiguānqúnzhòng","vi":"đám đông hiếu kỳ"},{"hanzi":"吃瓜群众","pinyin":"chīguāqúnzhòng","vi":"dân hóng chuyện"}],"traditional":"圍觀"},{"id":"违纪","hanzi":"违纪","pinyin":"wéijì","meaning_vi":"vi phạm kỷ luật","explanation":"违 (vi phạm/làm trái) + 纪 (kỷ luật/kỷ niệm).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚫","examples":[{"type":"basic","zh":"他因违纪被处分。","pinyin":"Tā yīn wéijì bèi chǔfèn.","vi":"Anh ấy bị kỷ luật vì vi phạm quy định."},{"type":"simple","zh":"这名官员因严重违纪被开除了党籍。","pinyin":"Zhè míng guānyuán yīn yánzhòng wéijì bèi kāichúle dǎngjí.","vi":"Quan chức này bị khai trừ đảng vì vi phạm kỷ luật nghiêm trọng."},{"type":"compound","zh":"如果考试时带手机进考场，就会被认定为违纪。","pinyin":"Rúguǒ kǎoshì shí dài shǒujī jìn kǎochǎng, jiù huì bèi rèn dìngwéi wéijì.","vi":"Nếu mang điện thoại vào phòng thi thì sẽ bị coi là vi phạm quy chế."}],"related":[{"hanzi":"纪律","pinyin":"jìlǜ","vi":"kỷ luật"},{"hanzi":"违规","pinyin":"wéiguī","vi":"vi phạm quy định"},{"hanzi":"处分","pinyin":"chǔfèn","vi":"kỷ luật xử phạt"},{"hanzi":"违法","pinyin":"wéifǎ","vi":"phạm pháp"}],"traditional":"違紀"},{"id":"维权","hanzi":"维权","pinyin":"wéiquán","meaning_vi":"bảo vệ quyền lợi hợp pháp","explanation":"维 (duy trì/tư duy) + 权 (quyền lực/cân nhắc).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"消费者要学会维权。","pinyin":"Xiāofèizhě yào xuéhuì wéiquán.","vi":"Người tiêu dùng phải biết bảo vệ quyền lợi của mình."},{"type":"simple","zh":"几十名业主联合起来向开发商维权。","pinyin":"Jǐ shí míng yèzhǔ liánhé qǐlái xiàng kāifāshāng wéiquán.","vi":"Mấy chục chủ hộ liên kết lại đòi quyền lợi từ chủ đầu tư."},{"type":"compound","zh":"只要保留好购物凭证，买到假货时就能依法维权。","pinyin":"Zhǐyào bǎoliú hǎo gòuwù píngzhèng, mǎi dào jiǎhuò shí jiù néng yīfǎ wéiquán.","vi":"Chỉ cần giữ kỹ chứng từ mua hàng, khi mua phải hàng giả bạn có thể bảo vệ quyền lợi theo pháp luật."}],"related":[{"hanzi":"权益","pinyin":"quányì","vi":"quyền lợi"},{"hanzi":"消费者","pinyin":"xiāofèizhě","vi":"người tiêu dùng"},{"hanzi":"投诉","pinyin":"tóusù","vi":"khiếu nại"},{"hanzi":"维护","pinyin":"wéihù","vi":"bảo vệ"}],"traditional":"維權"},{"id":"围棋","hanzi":"围棋","pinyin":"wéiqí","meaning_vi":"cờ vây","explanation":"围 (vây quanh/phạm vi) + 棋 (棋).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"⚫","examples":[{"type":"basic","zh":"爷爷教我下围棋。","pinyin":"Yéye jiāo wǒ xià wéiqí.","vi":"Ông nội dạy tôi chơi cờ vây."},{"type":"simple","zh":"人工智能在围棋比赛中击败了世界冠军。","pinyin":"Réngōngzhìnéng zài wéiqí bǐsài zhōng jībàile shìjiè guànjūn.","vi":"Trí tuệ nhân tạo đã đánh bại nhà vô địch thế giới trong trận đấu cờ vây."},{"type":"compound","zh":"虽然围棋规则很简单，但是要下好却需要多年苦练。","pinyin":"Suīrán wéiqí guīzé hěn jiǎndān, dànshì yào xià hǎo què xūyào duōnián kǔliàn.","vi":"Tuy luật cờ vây rất đơn giản, nhưng muốn chơi giỏi thì phải khổ luyện nhiều năm."}],"related":[{"hanzi":"象棋","pinyin":"xiàngqí","vi":"cờ tướng"},{"hanzi":"棋盘","pinyin":"qípán","vi":"bàn cờ"},{"hanzi":"下棋","pinyin":"xiàqí","vi":"chơi cờ"},{"hanzi":"国际象棋","pinyin":"guójìxiàngqí","vi":"cờ vua"}],"traditional":"圍棋"},{"id":"违心","hanzi":"违心","pinyin":"wéixīn","meaning_vi":"trái với lương tâm/ý muốn","explanation":"违 (vi phạm/làm trái) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"😔","examples":[{"type":"basic","zh":"我不想说违心的话。","pinyin":"Wǒ bù xiǎng shuō wéixīn dehuà.","vi":"Tôi không muốn nói những lời trái lòng."},{"type":"simple","zh":"他违心地在那份不合理的合同上签了字。","pinyin":"Tā wéixīn de zài nà fèn bùhé lǐ de hétong shàng qiānle zì.","vi":"Anh ấy trái với lòng mình mà ký vào bản hợp đồng bất hợp lý đó."},{"type":"compound","zh":"与其违心地讨好别人，不如坦然做真实的自己。","pinyin":"Yǔqí wéixīn de tǎohǎo biérén, bùrú tǎnrán zuò zhēnshí de zìjǐ.","vi":"Thay vì trái lòng lấy lòng người khác, chi bằng thản nhiên sống thật với chính mình."}],"related":[{"hanzi":"违背","pinyin":"wéibèi","vi":"làm trái"},{"hanzi":"言不由衷","pinyin":"yánbùyóuzhōng","vi":"nói không thật lòng"},{"hanzi":"真心","pinyin":"zhēnxīn","vi":"thật lòng"},{"hanzi":"昧良心","pinyin":"mèiliángxīn","vi":"trái lương tâm"}],"traditional":"違心"},{"id":"违约","hanzi":"违约","pinyin":"wéiyuē","meaning_vi":"vi phạm hợp đồng","explanation":"违 (vi phạm/làm trái) + 约 (ràng buộc/hiệp ước).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"📜","examples":[{"type":"basic","zh":"对方违约了。","pinyin":"Duìfāng wéiyuē le.","vi":"Bên kia đã vi phạm hợp đồng."},{"type":"simple","zh":"这家供应商因未按时交货而构成违约。","pinyin":"Zhè jiā gōngyìngshāng yīn wèi ànshí jiāohuò ér gòuchéng wéiyuē.","vi":"Nhà cung cấp này vi phạm hợp đồng vì không giao hàng đúng hạn."},{"type":"compound","zh":"如果租客提前退房，就算违约，押金不予退还。","pinyin":"Rúguǒ zūkè tíqián tuìfáng, jiùsuàn wéiyuē, yājīn bùyǔ tuìhuán.","vi":"Nếu người thuê trả phòng trước hạn thì coi như vi phạm hợp đồng, tiền cọc không được hoàn lại."}],"related":[{"hanzi":"履约","pinyin":"lǚyuē","vi":"thực hiện hợp đồng"},{"hanzi":"合同","pinyin":"hétong","vi":"hợp đồng"},{"hanzi":"违约金","pinyin":"wéiyuējīn","vi":"tiền phạt vi phạm"},{"hanzi":"毁约","pinyin":"huǐyuē","vi":"hủy hợp đồng"}],"traditional":"違約"},{"id":"违约金","hanzi":"违约金","pinyin":"wéiyuējīn","meaning_vi":"tiền phạt vi phạm hợp đồng","explanation":"违约 (vi phạm giao ước) + 金 (tiền).","hsk_level":"7-9","tags":["danh-tu","phap-luat","tien-te"],"image":"💸","examples":[{"type":"basic","zh":"他付了违约金。","pinyin":"Tā fùle wéiyuējīn.","vi":"Anh ấy đã trả tiền phạt vi phạm hợp đồng."},{"type":"simple","zh":"合同规定延期交房要按日支付违约金。","pinyin":"Hétong guīdìng yánqī jiāo fáng yào ànrì zhīfù wéiyuējīn.","vi":"Hợp đồng quy định giao nhà chậm phải trả tiền phạt vi phạm theo ngày."},{"type":"compound","zh":"虽然违约金高达十万元，但是球队还是决定提前解约。","pinyin":"Suīrán wéiyuējīn gāodá shíwàn yuán, dànshì qiúduì háishì juédìng tíqián jiěyuē.","vi":"Tuy tiền phạt vi phạm hợp đồng lên tới một trăm nghìn tệ, nhưng đội bóng vẫn quyết định chấm dứt hợp đồng sớm."}],"related":[{"hanzi":"违约","pinyin":"wéiyuē","vi":"vi phạm hợp đồng"},{"hanzi":"赔偿金","pinyin":"péichángjīn","vi":"tiền bồi thường"},{"hanzi":"罚款","pinyin":"fákuǎn","vi":"tiền phạt"},{"hanzi":"定金","pinyin":"dìngjīn","vi":"tiền đặt cọc"}],"traditional":"違約金"},{"id":"唯一性","hanzi":"唯一性","pinyin":"wéiyīxìng","meaning_vi":"tính duy nhất","explanation":"唯 (duy nhất) + 一 (số 1) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"1️⃣","examples":[{"type":"basic","zh":"身份证号具有唯一性。","pinyin":"Shēnfènzhèng hào jùyǒu wéiyīxìng.","vi":"Số chứng minh nhân dân có tính duy nhất."},{"type":"simple","zh":"数据库要求每个用户名都必须保证唯一性。","pinyin":"Shùjùkù yāoqiú měi gè yònghùmíng dōu bìxū bǎozhèng wéiyīxìng.","vi":"Cơ sở dữ liệu yêu cầu mỗi tên người dùng đều phải bảo đảm tính duy nhất."},{"type":"compound","zh":"因为指纹具有唯一性，所以它常被用来识别身份。","pinyin":"Yīnwèi zhǐwén jùyǒu wéiyīxìng, suǒyǐ tā cháng bèi yònglái shíbié shēnfèn.","vi":"Vì vân tay có tính duy nhất nên nó thường được dùng để nhận dạng danh tính."}],"related":[{"hanzi":"唯一","pinyin":"wéiyī","vi":"duy nhất"},{"hanzi":"独特性","pinyin":"dútèxìng","vi":"tính độc đáo"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"多样性","pinyin":"duōyàngxìng","vi":"tính đa dạng"}]},{"id":"违章","hanzi":"违章","pinyin":"wéizhāng","meaning_vi":"vi phạm luật giao thông / quy định","explanation":"违 (vi phạm/làm trái) + 章 (chương trình/điều lệ).","hsk_level":"7-9","tags":["dong-tu","giao-thong"],"image":"🚔","examples":[{"type":"basic","zh":"他开车违章了。","pinyin":"Tā kāichē wéizhāng le.","vi":"Anh ấy lái xe vi phạm luật giao thông."},{"type":"simple","zh":"这辆车一年内被拍到十几次违章停车。","pinyin":"Zhè liàng chē yì niánnèi bèi pāi dào shíjǐ cì wéizhāng tíngchē.","vi":"Chiếc xe này trong một năm bị camera ghi lại hơn mười lần đỗ xe sai quy định."},{"type":"compound","zh":"如果违章建筑不及时拆除，就会影响消防通道。","pinyin":"Rúguǒ wéizhāng jiànzhù bù jíshí chāichú, jiù huì yǐngxiǎng xiāofáng tōngdào.","vi":"Nếu công trình xây dựng trái phép không được phá dỡ kịp thời sẽ ảnh hưởng đến lối thoát hiểm."}],"related":[{"hanzi":"违章停车","pinyin":"wéizhāngtíngchē","vi":"đỗ xe trái phép"},{"hanzi":"交通规则","pinyin":"jiāotōngguīzé","vi":"luật giao thông"},{"hanzi":"罚单","pinyin":"fádān","vi":"biên lai phạt"},{"hanzi":"违规","pinyin":"wéiguī","vi":"vi phạm quy định"}],"traditional":"違章"},{"id":"文采","hanzi":"文采","pinyin":"wéncǎi","meaning_vi":"tài hoa văn chương","explanation":"文 (văn hóa/văn minh) + 采 (thu thập/phong thái).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"她的文章很有文采。","pinyin":"Tā de wénzhāng hěn yǒu wéncǎi.","vi":"Bài viết của cô ấy rất có tài hoa văn chương."},{"type":"simple","zh":"这位年轻作家的散文以细腻的文采著称。","pinyin":"Zhè wèi niánqīng zuòjiā de sǎnwén yǐ xìnì de wéncǎi zhùchēng.","vi":"Tản văn của nhà văn trẻ này nổi tiếng với lối văn tinh tế."},{"type":"compound","zh":"虽然他文采不算出众，但是写的故事真实感人。","pinyin":"Suīrán tā wéncǎi búsuàn chūzhòng, dànshì xiě de gùshi zhēnshí gǎnrén.","vi":"Tuy văn chương của anh ấy không xuất sắc, nhưng những câu chuyện anh viết chân thực cảm động."}],"related":[{"hanzi":"才华","pinyin":"cáihuá","vi":"tài hoa"},{"hanzi":"文笔","pinyin":"wénbǐ","vi":"văn phong"},{"hanzi":"文采飞扬","pinyin":"wéncǎifēiyáng","vi":"văn chương bay bổng"},{"hanzi":"口才","pinyin":"kǒucái","vi":"tài ăn nói"}]},{"id":"文房四宝","hanzi":"文房四宝","pinyin":"wénfángsìbǎo","meaning_vi":"văn phòng tứ bảo (bút, mực, giấy, nghiên)","explanation":"文房 (văn phòng – phòng đọc sách) + 四宝 (tứ bảo – bốn báu vật) → bốn vật dụng của người đọc sách xưa: bút, mực, giấy, nghiên.","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"🖌️","examples":[{"type":"basic","zh":"他收藏文房四宝。","pinyin":"Tā shōucáng wénfángsìbǎo.","vi":"Ông ấy sưu tầm văn phòng tứ bảo."},{"type":"simple","zh":"爷爷的书桌上整齐地摆放着文房四宝。","pinyin":"Yéye de shūzhuō shàng zhěngqí de bǎifàngzhe wénfángsìbǎo.","vi":"Trên bàn sách của ông bày ngay ngắn bút, mực, giấy, nghiên."},{"type":"compound","zh":"要想学好书法，不但要备齐文房四宝，而且要每天临帖。","pinyin":"Yào xiǎng xuéhǎo shūfǎ, búdàn yào bèi qí wénfángsìbǎo, érqiě yào měitiān líntiè.","vi":"Muốn học giỏi thư pháp, không chỉ phải sắm đủ văn phòng tứ bảo mà còn phải tập chép mẫu chữ mỗi ngày."}],"related":[{"hanzi":"笔墨纸砚","pinyin":"bǐmòzhǐyàn","vi":"bút mực giấy nghiên"},{"hanzi":"毛笔","pinyin":"máobǐ","vi":"bút lông"},{"hanzi":"宣纸","pinyin":"xuānzhǐ","vi":"giấy Tuyên"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"}],"traditional":"文房四寶"},{"id":"文风","hanzi":"文风","pinyin":"wénfēng","meaning_vi":"phong cách viết văn","explanation":"文 (văn hóa/văn minh) + 风 (风).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"📝","examples":[{"type":"basic","zh":"他的文风很朴实。","pinyin":"Tā de wénfēng hěn pǔshí.","vi":"Văn phong của anh ấy rất mộc mạc."},{"type":"simple","zh":"这位作家后期的文风变得越来越简洁冷峻。","pinyin":"Zhè wèi zuòjiā hòuqī de wénfēng biànde yuèláiyuè jiǎnjié lěngjùn.","vi":"Văn phong giai đoạn sau của nhà văn này ngày càng ngắn gọn, lạnh lùng."},{"type":"compound","zh":"因为模仿了太多名家，所以他一直没有形成自己的文风。","pinyin":"Yīnwèi mófǎngle tài duō míngjiā, suǒyǐ tā yìzhí méiyǒu xíngchéng zìjǐ de wénfēng.","vi":"Vì bắt chước quá nhiều tác giả nổi tiếng nên anh ấy mãi chưa hình thành văn phong riêng."}],"related":[{"hanzi":"文笔","pinyin":"wénbǐ","vi":"văn phong"},{"hanzi":"风格","pinyin":"fēnggé","vi":"phong cách"},{"hanzi":"文体","pinyin":"wéntǐ","vi":"thể văn"},{"hanzi":"笔调","pinyin":"bǐdiào","vi":"giọng văn"}],"traditional":"文風"},{"id":"文化差异","hanzi":"文化差异","pinyin":"wénhuàchāyì","meaning_vi":"khác biệt văn hóa","explanation":"文 (văn hóa/văn minh) + 化 (化) + 差 (差) + 异 (khác biệt/bất thường).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🔀","examples":[{"type":"basic","zh":"两国存在文化差异。","pinyin":"Liǎngguó cúnzài wénhuàchāyì.","vi":"Giữa hai nước tồn tại khác biệt văn hóa."},{"type":"simple","zh":"留学第一年，她深刻感受到了中西方的文化差异。","pinyin":"Liúxué dìyī nián, tā shēnkè gǎn shòudàole zhōng Xīfāng de wénhuàchāyì.","vi":"Năm đầu du học, cô ấy cảm nhận sâu sắc khác biệt văn hóa Đông Tây."},{"type":"compound","zh":"如果不了解文化差异，商务谈判中就容易产生误会。","pinyin":"Rúguǒ bù liǎojiě wénhuàchāyì, shāngwù tánpàn zhōng jiù róngyì chǎnshēng wùhuì.","vi":"Nếu không hiểu khác biệt văn hóa thì trong đàm phán thương mại rất dễ nảy sinh hiểu lầm."}],"related":[{"hanzi":"文化冲击","pinyin":"wénhuàchōngjī","vi":"sốc văn hóa"},{"hanzi":"跨文化","pinyin":"kuàwénhuà","vi":"liên văn hóa"},{"hanzi":"差异","pinyin":"chāyì","vi":"khác biệt"},{"hanzi":"风俗习惯","pinyin":"fēngsúxíguàn","vi":"phong tục tập quán"}],"traditional":"文化差異"},{"id":"文化底蕴","hanzi":"文化底蕴","pinyin":"wénhuàdǐyùn","meaning_vi":"nền tảng chiều sâu văn hóa","explanation":"文 (văn hóa/văn minh) + 化 (化) + 底 (đáy) + 蕴 (ẩn chứa/nội hàm).","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏛️","examples":[{"type":"basic","zh":"这座古城文化底蕴深厚。","pinyin":"Zhè zuò gǔchéng wénhuàdǐyùn shēnhòu.","vi":"Tòa cổ thành này có bề dày văn hóa sâu sắc."},{"type":"simple","zh":"苏州园林处处体现着江南深厚的文化底蕴。","pinyin":"Sūzhōu yuánlín chùchù tǐxiànzhe Jiāngnán shēnhòu de wénhuàdǐyùn.","vi":"Vườn cảnh Tô Châu ở đâu cũng thể hiện bề dày văn hóa sâu sắc của vùng Giang Nam."},{"type":"compound","zh":"虽然这个小镇不大，但是文化底蕴丰富，出过好几位状元。","pinyin":"Suīrán zhè ge xiǎozhèn búdà, dànshì wénhuàdǐyùn fēngfù, chūguo hǎojǐ wèi zhuàngyuán.","vi":"Tuy thị trấn này không lớn, nhưng có nền tảng văn hóa phong phú, từng sản sinh mấy vị trạng nguyên."}],"related":[{"hanzi":"底蕴","pinyin":"dǐyùn","vi":"nền tảng sâu xa"},{"hanzi":"历史悠久","pinyin":"lìshǐyōujiǔ","vi":"lịch sử lâu đời"},{"hanzi":"文化遗产","pinyin":"wénhuàyíchǎn","vi":"di sản văn hóa"},{"hanzi":"内涵","pinyin":"nèihán","vi":"nội hàm"}],"traditional":"文化底蘊"},{"id":"纹路","hanzi":"纹路","pinyin":"wénlù","meaning_vi":"đường vân (gỗ/da/tay)","explanation":"纹 (hoa văn/vân tay) + 路 (路).","hsk_level":"7-9","tags":["danh-tu"],"image":"🌀","examples":[{"type":"basic","zh":"木头的纹路很美。","pinyin":"Mùtou de wénlù hěn měi.","vi":"Vân gỗ rất đẹp."},{"type":"simple","zh":"老人粗糙的手掌上布满了深深的纹路。","pinyin":"Lǎorén cūcāo de shǒuzhǎng shàng bùmǎnle shēnshēn de wénlù.","vi":"Bàn tay thô ráp của cụ già đầy những đường vân sâu."},{"type":"compound","zh":"只要仔细观察树桩的纹路，就能大致判断树的年龄。","pinyin":"Zhǐyào zǐxì guānchá shùzhuāng de wénlù, jiù néng dàzhì pànduàn shù de niánlíng.","vi":"Chỉ cần quan sát kỹ vân trên gốc cây là có thể đoán được tuổi của cây."}],"related":[{"hanzi":"花纹","pinyin":"huāwén","vi":"hoa văn"},{"hanzi":"指纹","pinyin":"zhǐwén","vi":"vân tay"},{"hanzi":"木纹","pinyin":"mùwén","vi":"vân gỗ"},{"hanzi":"皱纹","pinyin":"zhòuwén","vi":"nếp nhăn"}],"traditional":"紋路"},{"id":"闻名","hanzi":"闻名","pinyin":"wénmíng","meaning_vi":"nổi tiếng","explanation":"闻 (nghe thấy/nổi tiếng) + 名 (danh tiếng/nổi tiếng).","hsk_level":"7-9","tags":["dong-tu"],"image":"🌟","examples":[{"type":"basic","zh":"杭州以西湖闻名。","pinyin":"Hángzhōu yǐ Xīhú wénmíng.","vi":"Hàng Châu nổi tiếng với Tây Hồ."},{"type":"simple","zh":"这个小镇因出产优质瓷器而闻名全国。","pinyin":"Zhè ge xiǎozhèn yīn chūchǎn yōuzhì cíqì ér wénmíng quánguó.","vi":"Thị trấn này nổi tiếng cả nước nhờ sản xuất đồ sứ chất lượng cao."},{"type":"compound","zh":"虽然这家面馆闻名已久，但是价格一直很实惠。","pinyin":"Suīrán zhè jiā miànguǎn wénmíng yǐjiǔ, dànshì jiàgé yìzhí hěn shíhuì.","vi":"Tuy quán mì này nổi tiếng đã lâu, nhưng giá cả vẫn luôn phải chăng."}],"related":[{"hanzi":"著名","pinyin":"zhùmíng","vi":"nổi tiếng"},{"hanzi":"闻名世界","pinyin":"wénmíngshìjiè","vi":"nổi tiếng thế giới"},{"hanzi":"出名","pinyin":"chūmíng","vi":"nổi danh"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"vô danh"}],"traditional":"聞名"},{"id":"文人","hanzi":"文人","pinyin":"wénrén","meaning_vi":"văn nhân, nhà văn trí thức","explanation":"文 (văn hóa/văn minh) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","van-hoa","con-nguoi"],"image":"🖋️","examples":[{"type":"basic","zh":"他是一位文人。","pinyin":"Tā shì yí wèi wénrén.","vi":"Ông ấy là một văn nhân."},{"type":"simple","zh":"古代文人常在月下饮酒赋诗。","pinyin":"Gǔdài wénrén cháng zài yuè xià yǐnjiǔ fùshī.","vi":"Văn nhân thời xưa thường uống rượu làm thơ dưới trăng."},{"type":"compound","zh":"因为这里风景秀丽，所以历代文人都喜欢来此游览题诗。","pinyin":"Yīnwèi zhèlǐ fēngjǐng xiùlì, suǒyǐ lìdài wénrén dōu xǐhuan lái cǐ yóulǎn tíshī.","vi":"Vì phong cảnh nơi đây tươi đẹp nên văn nhân các đời đều thích đến đây du ngoạn đề thơ."}],"related":[{"hanzi":"文学家","pinyin":"wénxuéjiā","vi":"nhà văn học"},{"hanzi":"作家","pinyin":"zuòjiā","vi":"nhà văn"},{"hanzi":"诗人","pinyin":"shīrén","vi":"nhà thơ"},{"hanzi":"知识分子","pinyin":"zhīshifènzǐ","vi":"trí thức"}]},{"id":"闻所未闻","hanzi":"闻所未闻","pinyin":"wénsuǒ-wèiwén","meaning_vi":"chưa từng nghe thấy bao giờ","explanation":"闻 (nghe thấy/nổi tiếng) + 所 (nơi chốn/sở hữu) + 未 (tương lai/chưa) + 闻 (nghe thấy/nổi tiếng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"😲","examples":[{"type":"basic","zh":"这事我闻所未闻。","pinyin":"Zhè shì wǒ wénsuǒwèiwén.","vi":"Chuyện này tôi chưa từng nghe bao giờ."},{"type":"simple","zh":"导游给我们讲了许多闻所未闻的当地传说。","pinyin":"Dǎoyóu gěi wǒmen jiǎngle xǔduō wénsuǒwèiwén de dāngdì chuánshuō.","vi":"Hướng dẫn viên kể cho chúng tôi nhiều truyền thuyết địa phương chưa từng nghe."},{"type":"compound","zh":"虽然我在这行干了二十年，但是这种骗局真是闻所未闻。","pinyin":"Suīrán wǒ zài zhè háng gànle èrshí nián, dànshì zhè zhǒng piànjú zhēn shì wénsuǒwèiwén.","vi":"Tuy tôi đã làm nghề này hai mươi năm, nhưng kiểu lừa đảo này đúng là chưa từng nghe thấy."}],"related":[{"hanzi":"前所未有","pinyin":"qiánsuǒwèiyǒu","vi":"chưa từng có"},{"hanzi":"见所未见","pinyin":"jiànsuǒwèijiàn","vi":"chưa từng thấy"},{"hanzi":"罕见","pinyin":"hǎnjiàn","vi":"hiếm thấy"},{"hanzi":"司空见惯","pinyin":"sīkōngjiànguàn","vi":"quá quen thuộc"}],"traditional":"聞所未聞"},{"id":"文言文","hanzi":"文言文","pinyin":"wényánwén","meaning_vi":"văn ngôn (tiếng Hán cổ điển)","explanation":"文 (văn hóa/văn minh) + 言 (ngôn luận/lời nói) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","van-hoa"],"image":"📜","examples":[{"type":"basic","zh":"我读不懂文言文。","pinyin":"Wǒ dú bù dǒng wényánwén.","vi":"Tôi đọc không hiểu văn ngôn."},{"type":"simple","zh":"语文课本里收录了好几篇经典的文言文。","pinyin":"Yǔwén kèběn lǐ shōulùle hǎojǐ piān jīngdiǎn de wényánwén.","vi":"Sách giáo khoa ngữ văn có mấy bài văn ngôn kinh điển."},{"type":"compound","zh":"虽然文言文很难读懂，但是它的语言十分精练。","pinyin":"Suīrán wényánwén hěn nán dúdǒng, dànshì tā de yǔyán shífēn jīngliàn.","vi":"Tuy văn ngôn rất khó hiểu, nhưng ngôn ngữ của nó vô cùng súc tích."}],"related":[{"hanzi":"白话文","pinyin":"báihuàwén","vi":"văn bạch thoại"},{"hanzi":"古文","pinyin":"gǔwén","vi":"cổ văn"},{"hanzi":"古汉语","pinyin":"gǔhànyǔ","vi":"Hán ngữ cổ"},{"hanzi":"翻译","pinyin":"fānyì","vi":"dịch"}]},{"id":"文艺复兴","hanzi":"文艺复兴","pinyin":"Wényìfùxīng","meaning_vi":"thời kỳ Phục hưng","explanation":"文 (văn hóa/văn minh) + 艺 (nghệ thuật) + 复 (复) + 兴 (hưng thịnh/hứng thú).","hsk_level":"7-9","tags":["danh-tu","van-hoa","hoc-tap"],"image":"🎨","examples":[{"type":"basic","zh":"他研究文艺复兴。","pinyin":"Tā yánjiū Wényìfùxīng.","vi":"Anh ấy nghiên cứu thời kỳ Phục hưng."},{"type":"simple","zh":"达芬奇是文艺复兴时期最伟大的艺术家之一。","pinyin":"Dáfēnqí shì Wényìfùxīng shíqī zuì wěidà de yìshùjiā zhīyī.","vi":"Leonardo da Vinci là một trong những nghệ sĩ vĩ đại nhất thời Phục hưng."},{"type":"compound","zh":"因为文艺复兴重新发现了古典文化，所以欧洲艺术迎来了巨大变革。","pinyin":"Yīnwèi Wényìfùxīng chóngxīn fāxiànle gǔdiǎn wénhuà, suǒyǐ Ōuzhōu yìshù yíngláile jùdà biàngé.","vi":"Vì thời Phục hưng tái khám phá văn hóa cổ điển nên nghệ thuật châu Âu đón nhận biến chuyển lớn."}],"related":[{"hanzi":"欧洲","pinyin":"Ōuzhōu","vi":"châu Âu"},{"hanzi":"中世纪","pinyin":"zhōngshìjì","vi":"thời Trung cổ"},{"hanzi":"启蒙运动","pinyin":"qǐméngyùndòng","vi":"phong trào Khai sáng"},{"hanzi":"达芬奇","pinyin":"dáfēnqí","vi":"Da Vinci"}],"traditional":"文藝復興"},{"id":"物产","hanzi":"物产","pinyin":"wùchǎn","meaning_vi":"sản vật, tài nguyên","explanation":"物 (vật chất/sự vật) + 产 (sản xuất/tài sản).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"这里物产丰富。","pinyin":"Zhèlǐ wùchǎn fēngfù.","vi":"Nơi đây sản vật phong phú."},{"type":"simple","zh":"云南以种类繁多的物产吸引了大批商人。","pinyin":"Yúnnán yǐ zhǒnglèi fánduō de wùchǎn xīyǐnle dàpī shāngrén.","vi":"Vân Nam thu hút đông đảo thương nhân nhờ sản vật đa dạng."},{"type":"compound","zh":"因为这片土地物产富饶，所以自古就是兵家必争之地。","pinyin":"Yīnwèi zhè piàn tǔdì wùchǎn fùráo, suǒyǐ zìgǔ jiùshì bīngjiā bì zhēng zhī dì.","vi":"Vì vùng đất này sản vật trù phú nên từ xưa đã là nơi binh gia tranh giành."}],"related":[{"hanzi":"物产丰富","pinyin":"wùchǎnfēngfù","vi":"sản vật phong phú"},{"hanzi":"资源","pinyin":"zīyuán","vi":"tài nguyên"},{"hanzi":"特产","pinyin":"tèchǎn","vi":"đặc sản"},{"hanzi":"地大物博","pinyin":"dìdàwùbó","vi":"đất rộng của nhiều"}],"traditional":"物產"},{"id":"误导","hanzi":"误导","pinyin":"wùdǎo","meaning_vi":"dẫn dắt sai lệch, gây hiểu lầm","explanation":"误 (sai lầm/hiểu lầm) + 导 (导).","hsk_level":"7-9","tags":["dong-tu"],"image":"🧭","examples":[{"type":"basic","zh":"这个广告误导了顾客。","pinyin":"Zhè ge guǎnggào wùdǎole gùkè.","vi":"Quảng cáo này đã gây hiểu lầm cho khách hàng."},{"type":"simple","zh":"网上一些不实的养生文章误导了不少老人。","pinyin":"Wǎngshàng yìxiē bùshí de yǎngshēng wénzhāng wùdǎole bùshǎo lǎorén.","vi":"Một số bài viết dưỡng sinh sai sự thật trên mạng đã dẫn dắt sai không ít người già."},{"type":"compound","zh":"如果媒体只报道片面的信息，就会误导公众的判断。","pinyin":"Rúguǒ méitǐ zhǐ bàodào piànmiàn de xìnxī, jiù huì wùdǎo gōngzhòng de pànduàn.","vi":"Nếu truyền thông chỉ đưa tin phiến diện thì sẽ làm sai lệch nhận định của công chúng."}],"related":[{"hanzi":"误解","pinyin":"wùjiě","vi":"hiểu lầm"},{"hanzi":"误会","pinyin":"wùhuì","vi":"hiểu nhầm"},{"hanzi":"引导","pinyin":"yǐndǎo","vi":"dẫn dắt"},{"hanzi":"虚假宣传","pinyin":"xūjiǎxuānchuán","vi":"quảng cáo sai sự thật"}],"traditional":"誤導"},{"id":"物归原主","hanzi":"物归原主","pinyin":"wùguī-yuánzhǔ","meaning_vi":"trả lại đồ cho chủ cũ","explanation":"物 (vật chất/sự vật) + 归 (归) + 原 (nguyên lý/nguyên tắc) + 主 (chủ động/chủ quyền).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤝","examples":[{"type":"basic","zh":"钱包终于物归原主。","pinyin":"Qiánbāo zhōngyú wùguīyuánzhǔ.","vi":"Chiếc ví cuối cùng đã về với chủ cũ."},{"type":"simple","zh":"出租车司机把乘客遗落的电脑物归原主了。","pinyin":"Chūzūchē sījī bǎ chéngkè yíluò de diànnǎo wùguīyuánzhǔ le.","vi":"Tài xế taxi đã trả lại chiếc máy tính hành khách để quên cho chủ của nó."},{"type":"compound","zh":"只要能联系上失主，我们就会尽快让手机物归原主。","pinyin":"Zhǐyào néng liánxì shàng shīzhǔ, wǒmen jiù huì jǐnkuài ràng shǒujī wùguīyuánzhǔ.","vi":"Chỉ cần liên lạc được với người đánh mất, chúng tôi sẽ sớm trả chiếc điện thoại về cho chủ."}],"related":[{"hanzi":"归还","pinyin":"guīhuán","vi":"trả lại"},{"hanzi":"失主","pinyin":"shīzhǔ","vi":"người mất đồ"},{"hanzi":"失物招领","pinyin":"shīwùzhāolǐng","vi":"nhận đồ thất lạc"},{"hanzi":"拾金不昧","pinyin":"shíjīnbúmèi","vi":"nhặt được của rơi trả lại"}],"traditional":"物歸原主"},{"id":"物价","hanzi":"物价","pinyin":"wùjià","meaning_vi":"vật giá, giá cả hàng hóa","explanation":"物 (vật chất/sự vật) + 价 (价).","hsk_level":"7-9","tags":["danh-tu","tien-te","mua-sam"],"image":"🏷️","examples":[{"type":"basic","zh":"最近物价涨了。","pinyin":"Zuìjìn wùjià zhǎng le.","vi":"Dạo này vật giá tăng rồi."},{"type":"simple","zh":"这座城市的物价比我老家高出将近一倍。","pinyin":"Zhè zuò chéngshì de wùjià bǐ wǒ lǎojiā gāochū jiāngjìn yí bèi.","vi":"Vật giá ở thành phố này cao gần gấp đôi quê tôi."},{"type":"compound","zh":"虽然工资涨了一点，但是物价涨得更快。","pinyin":"Suīrán gōngzī zhǎngle yìdiǎn, dànshì wùjià zhǎng de gèng kuài.","vi":"Tuy lương có tăng một chút, nhưng vật giá còn tăng nhanh hơn."}],"related":[{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"物价上涨","pinyin":"wùjiàshàngzhǎng","vi":"vật giá tăng"},{"hanzi":"通货膨胀","pinyin":"tōnghuòpéngzhàng","vi":"lạm phát"},{"hanzi":"消费","pinyin":"xiāofèi","vi":"tiêu dùng"}],"traditional":"物價"},{"id":"物极必反","hanzi":"物极必反","pinyin":"wùjí-bìfǎn","meaning_vi":"vật cực tất phản (cái gì quá mức cũng đảo ngược lại)","explanation":"物 (vật chất/sự vật) + 极 (cực đoan/tột cùng) + 必 (tất yếu/chắc chắn) + 反 (反).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"☯️","examples":[{"type":"basic","zh":"凡事物极必反。","pinyin":"Fánshì wùjíbìfǎn.","vi":"Việc gì quá mức cũng sẽ đảo ngược."},{"type":"simple","zh":"老中医提醒我们进补也要懂得物极必反的道理。","pinyin":"Lǎo zhōngyī tíxǐng wǒmen jìnbǔ yě yào dǒngde wùjíbìfǎn de dàolǐ.","vi":"Ông thầy thuốc Đông y nhắc chúng tôi bồi bổ cũng phải hiểu đạo lý vật cực tất phản."},{"type":"compound","zh":"如果对孩子管得太严，物极必反，他反而会更叛逆。","pinyin":"Rúguǒ duì háizi guǎn de tài yán, wùjíbìfǎn, tā fǎn'ér huì gèng pànnì.","vi":"Nếu quản con quá nghiêm, quá mức sẽ phản tác dụng, con ngược lại càng nổi loạn hơn."}],"related":[{"hanzi":"乐极生悲","pinyin":"lèjíshēngbēi","vi":"vui quá hóa buồn"},{"hanzi":"适可而止","pinyin":"shìkě'érzhǐ","vi":"biết điểm dừng"},{"hanzi":"过犹不及","pinyin":"guòyóubùjí","vi":"quá cũng như không đủ"},{"hanzi":"盛极而衰","pinyin":"shèngjí'érshuāi","vi":"thịnh cực rồi suy"}],"traditional":"物極必反"},{"id":"物尽其用","hanzi":"物尽其用","pinyin":"wùjìn-qíyòng","meaning_vi":"tận dụng tối đa công dụng của đồ vật","explanation":"物 (vật chất/sự vật) + 尽 (hết sức/tận cùng) + 其 (其) + 用 (vận dụng/công dụng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"♻️","examples":[{"type":"basic","zh":"我们要物尽其用。","pinyin":"Wǒmen yào wùjìnqíyòng.","vi":"Chúng ta phải tận dụng tối đa đồ vật."},{"type":"simple","zh":"奶奶用旧衣服做成抹布来物尽其用。","pinyin":"Nǎinai yòng jiù yīfu zuò chéng mābù lái wùjìnqíyòng.","vi":"Bà dùng quần áo cũ làm giẻ lau để tận dụng hết công dụng."},{"type":"compound","zh":"与其把旧家具扔掉，不如捐给需要的人，让它物尽其用。","pinyin":"Yǔqí bǎ jiù jiājù rēngdiào, bùrú juāngěi xūyào de rén, ràng tā wùjìnqíyòng.","vi":"Thay vì vứt đồ nội thất cũ, chi bằng tặng cho người cần để nó được dùng hết giá trị."}],"related":[{"hanzi":"人尽其才","pinyin":"rénjìnqícái","vi":"người dùng hết tài"},{"hanzi":"充分利用","pinyin":"chōngfènlìyòng","vi":"tận dụng triệt để"},{"hanzi":"节约","pinyin":"jiéyuē","vi":"tiết kiệm"},{"hanzi":"浪费","pinyin":"làngfèi","vi":"lãng phí"}],"traditional":"物盡其用"},{"id":"物联网","hanzi":"物联网","pinyin":"Wùliánwǎng","meaning_vi":"Internet vạn vật (IoT)","explanation":"物 (vật thể) + 联网 (kết nối mạng).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🌐","examples":[{"type":"basic","zh":"物联网发展很快。","pinyin":"Wùliánwǎng fāzhǎn hěn kuài.","vi":"Internet vạn vật phát triển rất nhanh."},{"type":"simple","zh":"借助物联网技术，农民在手机上就能给大棚浇水。","pinyin":"Jièzhù Wùliánwǎng jìshù, nóngmín zài shǒujī shàng jiù néng gěi dàpéng jiāoshuǐ.","vi":"Nhờ công nghệ IoT, nông dân có thể tưới nước cho nhà kính ngay trên điện thoại."},{"type":"compound","zh":"一旦家电都接入物联网，回家前就能提前打开空调。","pinyin":"Yídàn jiādiàn dōu jiērù Wùliánwǎng, huíjiā qián jiù néng tíqián dǎkāi kōngtiáo.","vi":"Một khi đồ điện gia dụng đều kết nối IoT, trước khi về nhà bạn có thể bật điều hòa sẵn."}],"related":[{"hanzi":"互联网","pinyin":"Hùliánwǎng","vi":"internet"},{"hanzi":"智能家居","pinyin":"zhìnéngjiājū","vi":"nhà thông minh"},{"hanzi":"传感器","pinyin":"chuángǎnqì","vi":"cảm biến"},{"hanzi":"大数据","pinyin":"dàshùjù","vi":"dữ liệu lớn"}],"traditional":"物聯網"},{"id":"物流","hanzi":"物流","pinyin":"wùliú","meaning_vi":"logistics, vận chuyển giao nhận hàng hóa","explanation":"物 (vật chất/sự vật) + 流 (lưu truyền/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","cong-viec","giao-thong"],"image":"🚚","examples":[{"type":"basic","zh":"物流信息更新了。","pinyin":"Wùliú xìnxī gēngxīn le.","vi":"Thông tin vận chuyển đã được cập nhật."},{"type":"simple","zh":"这家物流公司承诺偏远地区三天内送达。","pinyin":"Zhè jiā wùliú gōngsī chéngnuò piānyuǎn dìqū sān tiān nèi sòngdá.","vi":"Công ty logistics này cam kết giao hàng vùng xa trong ba ngày."},{"type":"compound","zh":"因为双十一订单暴增，所以物流比平时慢了好几天。","pinyin":"Yīnwèi Shuāngshíyī dìngdān bào zēng, suǒyǐ wùliú bǐ píngshí mànle hǎo jǐtiān.","vi":"Vì đơn hàng ngày 11/11 tăng vọt nên vận chuyển chậm hơn bình thường mấy ngày."}],"related":[{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"},{"hanzi":"仓储","pinyin":"cāngchǔ","vi":"kho bãi"},{"hanzi":"运输","pinyin":"yùnshū","vi":"vận chuyển"},{"hanzi":"配送","pinyin":"pèisòng","vi":"giao hàng"}]},{"id":"悟性","hanzi":"悟性","pinyin":"wùxìng","meaning_vi":"tố chất lĩnh hội nhanh, ngộ tính","explanation":"悟 (giác ngộ/thấu hiểu) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","nhan-thuc"],"image":"💡","examples":[{"type":"basic","zh":"这孩子悟性很高。","pinyin":"Zhè háizi wùxìng hěn gāo.","vi":"Đứa trẻ này ngộ tính rất cao."},{"type":"simple","zh":"师父说他学武的悟性超过了所有师兄。","pinyin":"Shīfu shuō tā xué wǔ de wùxìng chāoguòle suǒyǒu shīxiōng.","vi":"Sư phụ nói khả năng lĩnh hội võ công của cậu ấy vượt tất cả sư huynh."},{"type":"compound","zh":"虽然她悟性不错，但是缺乏持之以恒的毅力。","pinyin":"Suīrán tā wùxìng búcuò, dànshì quēfá chízhīyǐhéng de yìlì.","vi":"Tuy cô ấy tiếp thu nhanh, nhưng lại thiếu nghị lực bền bỉ."}],"related":[{"hanzi":"领悟","pinyin":"lǐngwù","vi":"lĩnh hội"},{"hanzi":"天分","pinyin":"tiānfèn","vi":"thiên bẩm"},{"hanzi":"理解力","pinyin":"lǐjiělì","vi":"khả năng hiểu"},{"hanzi":"开窍","pinyin":"kāiqiào","vi":"thông suốt hiểu ra"}]},{"id":"物业费","hanzi":"物业费","pinyin":"wùyèfèi","meaning_vi":"phí quản lý chung cư","explanation":"物业 (vật nghiệp – bất động sản, ban quản lý tòa nhà) + 费 (phí) → phí dịch vụ quản lý khu dân cư, chung cư (vệ sinh, bảo vệ, bảo trì).","hsk_level":"7-9","tags":["danh-tu","nha-cua","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"该交物业费了。","pinyin":"Gāi jiāo wùyèfèi le.","vi":"Đến lúc nộp phí quản lý rồi."},{"type":"simple","zh":"这个小区的物业费每平方米每月三块钱。","pinyin":"Zhè ge xiǎoqū de wùyèfèi měi píngfāngmǐ měiyuè sān kuài qián.","vi":"Phí quản lý của khu chung cư này là ba tệ mỗi mét vuông mỗi tháng."},{"type":"compound","zh":"如果物业服务一直这么差，业主们就拒绝交物业费。","pinyin":"Rúguǒ wùyè fúwù yìzhí zhème chà, yèzhǔmen jiù jùjué jiāo wùyèfèi.","vi":"Nếu dịch vụ quản lý cứ tệ như vậy, các chủ hộ sẽ từ chối nộp phí quản lý."}],"related":[{"hanzi":"物业","pinyin":"wùyè","vi":"ban quản lý tòa nhà"},{"hanzi":"水电费","pinyin":"shuǐdiànfèi","vi":"tiền điện nước"},{"hanzi":"停车费","pinyin":"tíngchēfèi","vi":"phí đỗ xe"},{"hanzi":"小区","pinyin":"xiǎoqū","vi":"khu dân cư"}],"traditional":"物業費"},{"id":"物种","hanzi":"物种","pinyin":"wùzhǒng","meaning_vi":"loài sinh vật","explanation":"物 (vật chất/sự vật) + 种 (chủng loại/hạt giống).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🦋","examples":[{"type":"basic","zh":"大熊猫是珍稀物种。","pinyin":"Dàxióngmāo shì zhēnxī wùzhǒng.","vi":"Gấu trúc lớn là loài quý hiếm."},{"type":"simple","zh":"科学家在雨林里发现了一个新的蛙类物种。","pinyin":"Kēxuéjiā zài yǔlín lǐ fāxiànle yí gè xīn de wā lèi wùzhǒng.","vi":"Các nhà khoa học đã phát hiện một loài ếch mới trong rừng mưa."},{"type":"compound","zh":"如果栖息地继续被破坏，更多物种就会走向灭绝。","pinyin":"Rúguǒ qīxīdì jìxù bèi pòhuài, gèng duō wùzhǒng jiù huì zǒuxiàng mièjué.","vi":"Nếu môi trường sống tiếp tục bị phá hoại, sẽ có thêm nhiều loài đi đến tuyệt chủng."}],"related":[{"hanzi":"生物","pinyin":"shēngwù","vi":"sinh vật"},{"hanzi":"濒危物种","pinyin":"bīnwēiwùzhǒng","vi":"loài nguy cấp"},{"hanzi":"生物多样性","pinyin":"shēngwù duōyàngxìng","vi":"đa dạng sinh học"},{"hanzi":"灭绝","pinyin":"mièjué","vi":"tuyệt chủng"}],"traditional":"物種"},{"id":"无偿献血","hanzi":"无偿献血","pinyin":"wúchángxiànxuè","meaning_vi":"hiến máu nhân đạo","explanation":"无 (vô tận/không có) + 偿 (bồi thường/đền đáp) + 献 (cống hiến) + 血 (máu/tâm huyết).","hsk_level":"7-9","tags":["dong-tu","xa-hoi","suc-khoe"],"image":"🩸","examples":[{"type":"basic","zh":"他每年无偿献血。","pinyin":"Tā měinián wúchángxiànxuè.","vi":"Năm nào anh ấy cũng hiến máu nhân đạo."},{"type":"simple","zh":"大学生们在校园里排队参加无偿献血活动。","pinyin":"Dàxuéshēngmen zài xiàoyuán lǐ páiduì cānjiā wúchángxiànxuè huódòng.","vi":"Sinh viên xếp hàng trong khuôn viên trường tham gia hiến máu nhân đạo."},{"type":"compound","zh":"只要身体健康、年满十八岁，就可以参加无偿献血。","pinyin":"Zhǐyào shēntǐ jiànkāng, niánmǎn shíbā suì, jiù kěyǐ cānjiā wúchángxiànxuè.","vi":"Chỉ cần khỏe mạnh và đủ mười tám tuổi là có thể tham gia hiến máu nhân đạo."}],"related":[{"hanzi":"献血","pinyin":"xiànxuè","vi":"hiến máu"},{"hanzi":"血型","pinyin":"xuèxíng","vi":"nhóm máu"},{"hanzi":"无偿","pinyin":"wúcháng","vi":"không công"},{"hanzi":"公益","pinyin":"gōngyì","vi":"công ích"}],"traditional":"無償獻血"},{"id":"无从","hanzi":"无从","pinyin":"wúcóng","meaning_vi":"không biết bắt đầu từ đâu, không có cách nào","explanation":"无 (vô tận/không có) + 从 (tuân theo/từ).","hsk_level":"7-9","tags":["pho-tu"],"image":"🤷","examples":[{"type":"basic","zh":"我无从下手。","pinyin":"Wǒ wúcóng xiàshǒu.","vi":"Tôi không biết bắt đầu từ đâu."},{"type":"simple","zh":"这批古籍的作者是谁已经无从考证。","pinyin":"Zhè pī gǔjí de zuòzhě shì shéi yǐjīng wúcóng kǎozhèng.","vi":"Tác giả của số sách cổ này là ai thì đã không có cách nào khảo chứng."},{"type":"compound","zh":"因为现场没有监控，所以警方一时无从查起。","pinyin":"Yīnwèi xiànchǎng méiyǒu jiānkòng, suǒyǐ jǐngfāng yìshí wúcóng chá qǐ.","vi":"Vì hiện trường không có camera nên cảnh sát tạm thời không biết điều tra từ đâu."}],"related":[{"hanzi":"无从下手","pinyin":"wúcóngxiàshǒu","vi":"không biết bắt tay từ đâu"},{"hanzi":"无法","pinyin":"wúfǎ","vi":"không thể"},{"hanzi":"无从知晓","pinyin":"wúcóngzhīxiǎo","vi":"không cách nào biết"},{"hanzi":"无路可走","pinyin":"wúlùkězǒu","vi":"không đường đi"}],"traditional":"無從"},{"id":"无独有偶","hanzi":"无独有偶","pinyin":"wúdú-yǒu'ǒu","meaning_vi":"không chỉ có một mà có đôi (trùng hợp thú vị)","explanation":"无 (vô tận/không có) + 独 (独) + 有 (có) + 偶 (ngẫu nhiên/thần tượng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👯","examples":[{"type":"basic","zh":"无独有偶，他也迟到了。","pinyin":"Wúdúyǒu'ǒu, tā yě chídào le.","vi":"Thật trùng hợp, anh ấy cũng đến muộn."},{"type":"simple","zh":"无独有偶，邻市上周也发生了类似的事故。","pinyin":"Wúdúyǒu'ǒu, lín shì shàngzhōu yě fāshēngle lèi sìde shìgù.","vi":"Không chỉ một mà có đôi, tuần trước thành phố bên cạnh cũng xảy ra sự cố tương tự."},{"type":"compound","zh":"我刚买了这本书，无独有偶，同桌竟然也送了我一本。","pinyin":"Wǒ gāng mǎile zhè běn shū, wúdúyǒu'ǒu, tóngzhuō jìngrán yě sòngle wǒ yì běn.","vi":"Tôi vừa mua cuốn sách này, trùng hợp thay, bạn cùng bàn lại cũng tặng tôi một cuốn."}],"related":[{"hanzi":"巧合","pinyin":"qiǎohé","vi":"trùng hợp"},{"hanzi":"不谋而合","pinyin":"bùmóu'érhé","vi":"không hẹn mà gặp"},{"hanzi":"如出一辙","pinyin":"rúchūyìzhé","vi":"giống hệt nhau"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"}],"traditional":"無獨有偶"},{"id":"无故","hanzi":"无故","pinyin":"wúgù","meaning_vi":"vô cớ, không lý do","explanation":"无 (vô tận/không có) + 故 (故).","hsk_level":"7-9","tags":["pho-tu"],"image":"❓","examples":[{"type":"basic","zh":"他无故缺勤三天。","pinyin":"Tā wúgù quēqín sān tiān.","vi":"Anh ấy vô cớ vắng mặt ba ngày."},{"type":"simple","zh":"这名员工因无故旷工被公司解除了合同。","pinyin":"Zhè míng yuángōng yīn wúgù kuànggōng bèi gōngsī jiěchúle hétong.","vi":"Nhân viên này bị công ty chấm dứt hợp đồng vì tự ý bỏ việc không lý do."},{"type":"compound","zh":"如果房东无故涨租，租客就有权拒绝。","pinyin":"Rúguǒ fángdōng wúgù zhǎng zū, zūkè jiù yǒuquán jùjué.","vi":"Nếu chủ nhà vô cớ tăng tiền thuê, người thuê có quyền từ chối."}],"related":[{"hanzi":"无缘无故","pinyin":"wúyuánwúgù","vi":"vô duyên vô cớ"},{"hanzi":"平白无故","pinyin":"píngbáiwúgù","vi":"tự dưng vô cớ"},{"hanzi":"借口","pinyin":"jièkǒu","vi":"cái cớ"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"}],"traditional":"無故"},{"id":"无辜","hanzi":"无辜","pinyin":"wúgū","meaning_vi":"vô tội, ngây thơ bị liên lụy","explanation":"无 (vô tận/không có) + 辜 (phụ lòng/tội lỗi).","hsk_level":"7-9","tags":["tinh-tu","phap-luat"],"image":"🥺","examples":[{"type":"basic","zh":"他是无辜的。","pinyin":"Tā shì wúgū de.","vi":"Anh ấy vô tội."},{"type":"simple","zh":"这场战争夺走了成千上万无辜平民的生命。","pinyin":"Zhè chǎng zhànzhēng duózǒule chéngqiānshàngwàn wúgū píngmín de shēngmìng.","vi":"Cuộc chiến này đã cướp đi sinh mạng của hàng vạn thường dân vô tội."},{"type":"compound","zh":"小狗打碎了花瓶，却一脸无辜地看着主人。","pinyin":"Xiǎogǒu dǎsuìle huāpíng, què yì liǎn wúgū de kànzhe zhǔrén.","vi":"Chú chó con làm vỡ bình hoa, vậy mà lại nhìn chủ với vẻ mặt ngây thơ vô tội."}],"related":[{"hanzi":"冤枉","pinyin":"yuānwang","vi":"oan uổng"},{"hanzi":"清白","pinyin":"qīngbái","vi":"trong sạch"},{"hanzi":"受害者","pinyin":"shòuhàizhě","vi":"nạn nhân"},{"hanzi":"罪魁祸首","pinyin":"zuìkuíhuòshǒu","vi":"kẻ đầu sỏ"}],"traditional":"無辜"},{"id":"无害","hanzi":"无害","pinyin":"wúhài","meaning_vi":"vô hại","explanation":"无 (vô tận/không có) + 害 (害).","hsk_level":"7-9","tags":["tinh-tu"],"image":"✅","examples":[{"type":"basic","zh":"这种蛇对人无害。","pinyin":"Zhè zhǒng shé duì rén wúhài.","vi":"Loài rắn này vô hại với con người."},{"type":"simple","zh":"这款儿童颜料采用了无毒无害的天然原料。","pinyin":"Zhè kuǎn értóng yánliào cǎiyòngle wúdú wúhài de tiānrán yuánliào.","vi":"Loại màu vẽ cho trẻ em này dùng nguyên liệu tự nhiên không độc, vô hại."},{"type":"compound","zh":"虽然这种添加剂少量无害，但是长期大量摄入仍有风险。","pinyin":"Suīrán zhè zhǒng tiānjiājì shǎoliàng wúhài, dànshì chángqī dàliàng shèrù réng yǒu fēngxiǎn.","vi":"Tuy chất phụ gia này với lượng nhỏ thì vô hại, nhưng dùng nhiều lâu dài vẫn có rủi ro."}],"related":[{"hanzi":"有害","pinyin":"yǒuhài","vi":"có hại"},{"hanzi":"无毒","pinyin":"wúdú","vi":"không độc"},{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"},{"hanzi":"无害化","pinyin":"wúhàihuà","vi":"xử lý vô hại"}],"traditional":"無害"},{"id":"无价之宝","hanzi":"无价之宝","pinyin":"wújià-zhībǎo","meaning_vi":"báu vật vô giá","explanation":"无 (vô tận/không có) + 价 (价) + 之 (của (trợ từ văn viết)) + 宝 (宝).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"💎","examples":[{"type":"basic","zh":"健康是无价之宝。","pinyin":"Jiànkāng shì wújiàzhībǎo.","vi":"Sức khỏe là báu vật vô giá."},{"type":"simple","zh":"这幅宋代古画被博物馆视为无价之宝。","pinyin":"Zhè fú Sòngdài gǔ huà bèi bówùguǎn shìwéi wújiàzhībǎo.","vi":"Bức tranh cổ đời Tống này được bảo tàng coi là báu vật vô giá."},{"type":"compound","zh":"虽然这本旧相册不值钱，但是对奶奶来说是无价之宝。","pinyin":"Suīrán zhè běn jiù xiàngcè bù zhíqián, dànshì duì nǎinai lái shuō shì wújiàzhībǎo.","vi":"Tuy cuốn album cũ này không đáng tiền, nhưng với bà nó là báu vật vô giá."}],"related":[{"hanzi":"宝贝","pinyin":"bǎobèi","vi":"bảo bối"},{"hanzi":"珍宝","pinyin":"zhēnbǎo","vi":"báu vật"},{"hanzi":"价值连城","pinyin":"jiàzhíliánchéng","vi":"giá trị liên thành"},{"hanzi":"一文不值","pinyin":"yìwénbùzhí","vi":"không đáng một xu"}],"traditional":"無價之寶"},{"id":"无拘无束","hanzi":"无拘无束","pinyin":"wújū-wúshù","meaning_vi":"tự do tự tại không gò bó","explanation":"无 (vô tận/không có) + 拘 (tạm giữ/gò bó) + 无 (vô tận/không có) + 束 (trói buộc/bó).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕊️","examples":[{"type":"basic","zh":"孩子们无拘无束地玩。","pinyin":"Háizimen wújūwúshù de wán.","vi":"Lũ trẻ vui chơi tự do thoải mái."},{"type":"simple","zh":"退休后，他过上了无拘无束的田园生活。","pinyin":"Tuìxiū hòu, tāguò shàngle wújūwúshù de tiányuán shēnghuó.","vi":"Sau khi nghỉ hưu, ông ấy sống cuộc sống điền viên tự do tự tại."},{"type":"compound","zh":"一到草原上，孩子们就无拘无束地奔跑起来。","pinyin":"Yí dào cǎoyuán shàng, háizimen jiù wújūwúshù de bēnpǎo qǐlái.","vi":"Vừa đến thảo nguyên, lũ trẻ liền chạy nhảy thỏa thích không gò bó."}],"related":[{"hanzi":"自由自在","pinyin":"zìyóuzìzài","vi":"tự do tự tại"},{"hanzi":"无忧无虑","pinyin":"wúyōuwúlǜ","vi":"vô lo vô nghĩ"},{"hanzi":"拘束","pinyin":"jūshù","vi":"gò bó"},{"hanzi":"随心所欲","pinyin":"suíxīnsuǒyù","vi":"tùy ý muốn"}],"traditional":"無拘無束"},{"id":"无可厚非","hanzi":"无可厚非","pinyin":"wúkě-hòufēi","meaning_vi":"không có gì đáng trách, có thể thông cảm được","explanation":"无 (vô tận/không có) + 可 (可) + 厚 (厚) + 非 (không).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👌","examples":[{"type":"basic","zh":"他的做法无可厚非。","pinyin":"Tā de zuòfǎ wúkěhòufēi.","vi":"Cách làm của anh ấy không có gì đáng trách."},{"type":"simple","zh":"年轻人追求更高的薪水本来就无可厚非。","pinyin":"Niánqīngrén zhuīqiú gèng gāo de xīnshuǐ běnlái jiù wúkěhòufēi.","vi":"Người trẻ theo đuổi mức lương cao hơn vốn là chuyện có thể thông cảm."},{"type":"compound","zh":"虽然他为家人着想无可厚非，但是不该因此违反规定。","pinyin":"Suīrán tā wèi jiārén zhuóxiǎng wúkěhòufēi, dànshì bùgāi yīncǐ wéifǎn guīdìng.","vi":"Tuy anh ấy nghĩ cho gia đình là điều dễ hiểu, nhưng không nên vì thế mà vi phạm quy định."}],"related":[{"hanzi":"情有可原","pinyin":"qíngyǒukěyuán","vi":"có thể thông cảm"},{"hanzi":"理所当然","pinyin":"lǐsuǒdāngrán","vi":"lẽ đương nhiên"},{"hanzi":"无可指责","pinyin":"wúkězhǐzé","vi":"không thể chỉ trích"},{"hanzi":"罪不可赦","pinyin":"zuìbùkěshè","vi":"tội không thể tha"}],"traditional":"無可厚非"},{"id":"无孔不入","hanzi":"无孔不入","pinyin":"wúkǒng-búrù","meaning_vi":"len lỏi khắp mọi ngóc ngách","explanation":"无 (vô tận/không có) + 孔 (cái lỗ) + 不 (không/bất) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐜","examples":[{"type":"basic","zh":"广告真是无孔不入。","pinyin":"Guǎnggào zhēn shì wúkǒngbúrù.","vi":"Quảng cáo đúng là len lỏi khắp nơi."},{"type":"simple","zh":"网络诈骗分子无孔不入地寻找着下手的机会。","pinyin":"Wǎngluòzhàpiàn fènzǐ wúkǒngbúrù de xún zhǎozhe xiàshǒu de jīhuì.","vi":"Bọn lừa đảo qua mạng len lỏi mọi ngóc ngách để tìm cơ hội ra tay."},{"type":"compound","zh":"一到梅雨季节，潮气就无孔不入，衣柜里都发霉了。","pinyin":"Yí dào méiyǔ jìjié, cháoqì jiù wúkǒngbúrù, yīguì lǐ dōu fāméi le.","vi":"Cứ đến mùa mưa phùn, hơi ẩm len lỏi khắp nơi, đến tủ quần áo cũng mốc."}],"related":[{"hanzi":"见缝插针","pinyin":"jiànfèngchāzhēn","vi":"tận dụng mọi kẽ hở"},{"hanzi":"无处不在","pinyin":"wúchùbúzài","vi":"ở đâu cũng có"},{"hanzi":"渗透","pinyin":"shèntòu","vi":"thâm nhập"},{"hanzi":"钻空子","pinyin":"zuānkòngzi","vi":"lách kẽ hở"}],"traditional":"無孔不入"},{"id":"无穷","hanzi":"无穷","pinyin":"wúqióng","meaning_vi":"vô cùng, vô tận","explanation":"无 (vô tận/không có) + 穷 (nghèo).","hsk_level":"7-9","tags":["tinh-tu"],"image":"♾️","examples":[{"type":"basic","zh":"宇宙奥秘无穷。","pinyin":"Yǔzhòu àomìwúqióng.","vi":"Bí ẩn của vũ trụ là vô tận."},{"type":"simple","zh":"这本小说带给我无穷的想象空间。","pinyin":"Zhè běn xiǎoshuō dàigěi wǒ wúqióng de xiǎngxiàng kōngjiān.","vi":"Cuốn tiểu thuyết này mang đến cho tôi không gian tưởng tượng vô tận."},{"type":"compound","zh":"如果不及时处理这个隐患，将来就会后患无穷。","pinyin":"Rúguǒ bù jíshí chǔlǐ zhè ge yǐnhuàn, jiānglái jiù huì hòuhuàn wúqióng.","vi":"Nếu không kịp thời xử lý mối nguy tiềm ẩn này, sau này sẽ để lại hậu họa khôn lường."}],"related":[{"hanzi":"无尽","pinyin":"wújìn","vi":"vô tận"},{"hanzi":"无限","pinyin":"wúxiàn","vi":"vô hạn"},{"hanzi":"无穷无尽","pinyin":"wúqióngwújìn","vi":"vô cùng vô tận"},{"hanzi":"有限","pinyin":"yǒuxiàn","vi":"có hạn"}],"traditional":"無窮"},{"id":"无人驾驶","hanzi":"无人驾驶","pinyin":"wúrénjiàshǐ","meaning_vi":"không người lái, tự lái","explanation":"无人 (vô nhân – không người) + 驾驶 (giá sử – lái, điều khiển) → không cần người lái, tự lái. Ví dụ: 无人驾驶汽车 (xe tự lái).","hsk_level":"7-9","tags":["tinh-tu","giao-thong","cong-nghe"],"image":"🤖","examples":[{"type":"basic","zh":"我坐过无人驾驶汽车。","pinyin":"Wǒ zuòguo wúrénjiàshǐ qìchē.","vi":"Tôi đã từng đi xe tự lái."},{"type":"simple","zh":"这座城市已经开通了无人驾驶出租车服务。","pinyin":"Zhè zuò chéngshì yǐjīng kāitōngle wúrénjiàshǐ chūzūchē fúwù.","vi":"Thành phố này đã đưa vào hoạt động dịch vụ taxi tự lái."},{"type":"compound","zh":"虽然无人驾驶技术进步很快，但是法律法规还不够完善。","pinyin":"Suīrán wúrénjiàshǐ jìshù jìnbù hěn kuài, dànshì fǎlǜ fǎguī hái búgòu wánshàn.","vi":"Tuy công nghệ lái tự động tiến bộ rất nhanh, nhưng luật pháp vẫn chưa hoàn thiện."}],"related":[{"hanzi":"自动驾驶","pinyin":"zìdòngjiàshǐ","vi":"lái tự động"},{"hanzi":"无人机","pinyin":"wúrénjī","vi":"máy bay không người lái"},{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"},{"hanzi":"新能源汽车","pinyin":"xīnnéngyuán qìchē","vi":"xe năng lượng mới"}],"traditional":"無人駕駛"},{"id":"无人区","hanzi":"无人区","pinyin":"wúrénqū","meaning_vi":"vùng không người ở","explanation":"无 (vô tận/không có) + 人 (người) + 区 (区).","hsk_level":"7-9","tags":["danh-tu","dia-diem","thien-nhien"],"image":"🏜️","examples":[{"type":"basic","zh":"这里是一片无人区。","pinyin":"Zhèlǐ shì yípiàn wúrénqū.","vi":"Đây là một vùng không người ở."},{"type":"simple","zh":"科考队在沙漠无人区里走了整整三天。","pinyin":"Kēkǎoduì zài shāmò wúrénqū lǐ zǒule zhěngzhěng sān tiān.","vi":"Đoàn khảo sát khoa học đã đi suốt ba ngày trong vùng sa mạc không người ở."},{"type":"compound","zh":"因为无人区没有手机信号，所以出发前我们带了卫星电话。","pinyin":"Yīnwèi wúrénqū méiyǒu shǒujī xìnhào, suǒyǐ chūfā qián wǒmen dàile wèixīng diànhuà.","vi":"Vì vùng không người ở không có sóng điện thoại nên trước khi xuất phát chúng tôi đã mang theo điện thoại vệ tinh."}],"related":[{"hanzi":"荒野","pinyin":"huāngyě","vi":"hoang dã"},{"hanzi":"人烟稀少","pinyin":"rényānxīshǎo","vi":"thưa thớt người"},{"hanzi":"沙漠","pinyin":"shāmò","vi":"sa mạc"},{"hanzi":"探险","pinyin":"tànxiǎn","vi":"thám hiểm"}],"traditional":"無人區"},{"id":"无声无息","hanzi":"无声无息","pinyin":"wúshēng-wúxī","meaning_vi":"lặng lẽ không tiếng động","explanation":"无 (vô tận/không có) + 声 (thanh thế/tuyên bố) + 无 (vô tận/không có) + 息 (tin tức/nghỉ ngơi).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🤫","examples":[{"type":"basic","zh":"雪无声无息地下着。","pinyin":"Xuě wúshēngwúxī dexià zhe.","vi":"Tuyết lặng lẽ rơi không một tiếng động."},{"type":"simple","zh":"那只猫无声无息地跳上了书架。","pinyin":"Nà zhī māo wúshēngwúxī de tiào shàngle shūjià.","vi":"Con mèo ấy lặng lẽ nhảy lên giá sách không một tiếng động."},{"type":"compound","zh":"他虽然无声无息地离开了公司，但是同事们一直记得他。","pinyin":"Tā suīrán wúshēngwúxī de líkāile gōngsī, dànshì tóngshìmen yìzhí jìde tā.","vi":"Tuy anh ấy lặng lẽ rời công ty, nhưng đồng nghiệp vẫn luôn nhớ đến anh."}],"related":[{"hanzi":"悄无声息","pinyin":"qiǎowúshēngxī","vi":"lặng lẽ không tiếng"},{"hanzi":"默默无闻","pinyin":"mòmòwúwén","vi":"âm thầm vô danh"},{"hanzi":"静悄悄","pinyin":"jìngqiāoqiāo","vi":"lặng lẽ"},{"hanzi":"大张旗鼓","pinyin":"dàzhāngqígǔ","vi":"rầm rộ khua chiêng"}],"traditional":"無聲無息"},{"id":"无所不知","hanzi":"无所不知","pinyin":"wúsuǒ-bùzhī","meaning_vi":"biết tuốt mọi thứ","explanation":"无 (vô tận/không có) + 所 (nơi chốn/sở hữu) + 不 (không/bất) + 知 (tri thức/tri giác).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧠","examples":[{"type":"basic","zh":"爷爷好像无所不知。","pinyin":"Yéye hǎoxiàng wúsuǒbùzhī.","vi":"Ông nội dường như cái gì cũng biết."},{"type":"simple","zh":"孩子们把百科全书当成无所不知的老师。","pinyin":"Háizimen bǎ bǎikēquánshū dàngchéng wúsuǒbùzhī de lǎoshī.","vi":"Bọn trẻ coi bộ bách khoa toàn thư như một người thầy biết tuốt mọi thứ."},{"type":"compound","zh":"即使网络看起来无所不知，我们也要学会判断信息的真假。","pinyin":"Jíshǐ wǎngluò kànqǐlái wúsuǒbùzhī, wǒmen yě yào xuéhuì pànduàn xìnxī de zhēnjiǎ.","vi":"Dù mạng Internet có vẻ biết tuốt mọi thứ, chúng ta vẫn phải học cách phân biệt thông tin thật giả."}],"related":[{"hanzi":"无所不能","pinyin":"wúsuǒbùnéng","vi":"không gì không làm được"},{"hanzi":"博学","pinyin":"bóxué","vi":"học rộng"},{"hanzi":"万事通","pinyin":"wànshìtōng","vi":"người biết tuốt"},{"hanzi":"一无所知","pinyin":"yìwúsuǒzhī","vi":"chẳng biết gì"}],"traditional":"無所不知"},{"id":"无所事事","hanzi":"无所事事","pinyin":"wúsuǒ-shìshì","meaning_vi":"nhàn rỗi vô công rồi nghề","explanation":"无 (vô tận/không có) + 所 (nơi chốn/sở hữu) + 事 (sự nghiệp/sự kiện) + 事 (sự nghiệp/sự kiện).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦥","examples":[{"type":"basic","zh":"他整天无所事事。","pinyin":"Tā zhěngtiān wúsuǒshìshì.","vi":"Anh ta suốt ngày nhàn rỗi chẳng làm gì."},{"type":"simple","zh":"暑假里弟弟无所事事地躺在沙发上玩手机。","pinyin":"Shǔjià lǐ dìdi wúsuǒshìshì de tǎng zài shāfā shang wán shǒujī.","vi":"Kỳ nghỉ hè, em trai nằm dài trên sofa chơi điện thoại, chẳng có việc gì làm."},{"type":"compound","zh":"与其在家无所事事，不如去图书馆做志愿者。","pinyin":"Yǔqí zài jiā wúsuǒshìshì, bùrú qù túshūguǎn zuò zhìyuànzhě.","vi":"Thay vì ở nhà nhàn rỗi không làm gì, chi bằng đến thư viện làm tình nguyện viên."}],"related":[{"hanzi":"游手好闲","pinyin":"yóushǒuhàoxián","vi":"lêu lổng ăn không ngồi rồi"},{"hanzi":"闲着","pinyin":"xiánzhe","vi":"rảnh rỗi"},{"hanzi":"百无聊赖","pinyin":"bǎiwúliáolài","vi":"buồn chán vô vị"},{"hanzi":"忙忙碌碌","pinyin":"mángmánglùlù","vi":"bận rộn"}],"traditional":"無所事事"},{"id":"无所畏惧","hanzi":"无所畏惧","pinyin":"wúsuǒ-wèijù","meaning_vi":"không hề sợ hãi","explanation":"无 (vô tận/không có) + 所 (nơi chốn/sở hữu) + 畏 (sợ hãi) + 惧 (sợ hãi).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"她面对困难无所畏惧。","pinyin":"Tā miànduì kùnnan wúsuǒwèijù.","vi":"Cô ấy không hề sợ hãi trước khó khăn."},{"type":"simple","zh":"消防员无所畏惧地冲进了着火的大楼。","pinyin":"Xiāofángyuán wúsuǒwèijù de chōngjìnle zháohuǒ de dàlóu.","vi":"Lính cứu hỏa không chút sợ hãi lao vào tòa nhà đang cháy."},{"type":"compound","zh":"只要心中有信念，年轻人就能无所畏惧地追求梦想。","pinyin":"Zhǐyào xīnzhōng yǒu xìnniàn, niánqīngrén jiù néng wúsuǒwèijù de zhuīqiú mèngxiǎng.","vi":"Chỉ cần trong lòng có niềm tin, người trẻ có thể theo đuổi ước mơ mà không hề sợ hãi."}],"related":[{"hanzi":"无畏","pinyin":"wúwèi","vi":"không sợ"},{"hanzi":"勇敢","pinyin":"yǒnggǎn","vi":"dũng cảm"},{"hanzi":"大无畏","pinyin":"dàwúwèi","vi":"đại vô úy"},{"hanzi":"胆小如鼠","pinyin":"dǎnxiǎorúshǔ","vi":"nhát như chuột"}],"traditional":"無所畏懼"},{"id":"无私奉献","hanzi":"无私奉献","pinyin":"wúsī-fèngxiàn","meaning_vi":"cống hiến vô tư không vụ lợi","explanation":"无 (vô tận/không có) + 私 (riêng tư) + 奉 (cống hiến/dâng) + 献 (cống hiến).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"💖","examples":[{"type":"basic","zh":"感谢老师的无私奉献。","pinyin":"Gǎnxiè lǎoshī de wúsīfèngxiàn.","vi":"Cảm ơn sự cống hiến vô tư của thầy cô."},{"type":"simple","zh":"这位乡村医生在山区无私奉献了三十年。","pinyin":"Zhè wèi xiāngcūn yīshēng zài shānqū wúsīfèngxiànle sānshí nián.","vi":"Vị bác sĩ nông thôn này đã cống hiến vô tư suốt ba mươi năm ở vùng núi."},{"type":"compound","zh":"他不但无私奉献自己的时间，而且捐出了全部积蓄。","pinyin":"Tā búdàn wúsīfèngxiàn zìjǐ de shíjiān, érqiě juān chūle quánbù jīxù.","vi":"Ông ấy không chỉ cống hiến thời gian một cách vô tư mà còn quyên góp toàn bộ tiền tiết kiệm."}],"related":[{"hanzi":"奉献","pinyin":"fèngxiàn","vi":"cống hiến"},{"hanzi":"无私","pinyin":"wúsī","vi":"vô tư"},{"hanzi":"大公无私","pinyin":"dàgōngwúsī","vi":"chí công vô tư"},{"hanzi":"自私自利","pinyin":"zìsīzìlì","vi":"ích kỷ vụ lợi"}],"traditional":"無私奉獻"},{"id":"无条件","hanzi":"无条件","pinyin":"wútiáojiàn","meaning_vi":"vô điều kiện","explanation":"无 (vô tận/không có) + 条 (điều khoản/mạch lạc) + 件 (件).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"💯","examples":[{"type":"basic","zh":"父母无条件地爱我。","pinyin":"Fùmǔ wútiáojiàn de ài wǒ.","vi":"Bố mẹ yêu tôi vô điều kiện."},{"type":"simple","zh":"这家商店承诺七天内无条件退货。","pinyin":"Zhè jiā shāngdiàn chéngnuò qī tiān nèi wútiáojiàn tuìhuò.","vi":"Cửa hàng này cam kết đổi trả vô điều kiện trong bảy ngày."},{"type":"compound","zh":"我虽然信任你，但是不会无条件地支持每个决定。","pinyin":"Wǒ suīrán xìnrèn nǐ, dànshì bú huì wútiáojiàn de zhīchí měi gè juédìng.","vi":"Tuy tôi tin bạn, nhưng tôi sẽ không ủng hộ vô điều kiện mọi quyết định."}],"related":[{"hanzi":"有条件","pinyin":"yǒutiáojiàn","vi":"có điều kiện"},{"hanzi":"条件","pinyin":"tiáojiàn","vi":"điều kiện"},{"hanzi":"无条件投降","pinyin":"wútiáojiàn tóuxiáng","vi":"đầu hàng vô điều kiện"},{"hanzi":"绝对","pinyin":"juéduì","vi":"tuyệt đối"}],"traditional":"無條件"},{"id":"无线网络","hanzi":"无线网络","pinyin":"wúxiànwǎngluò","meaning_vi":"mạng không dây (Wi-Fi)","explanation":"无线 (vô tuyến – không dây) + 网络 (võng lạc – mạng) → mạng không dây như Wi-Fi. Khẩu ngữ hay nói 无线网 hoặc WiFi.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📶","examples":[{"type":"basic","zh":"酒店有免费无线网络。","pinyin":"Jiǔdiàn yǒu miǎnfèi wúxiànwǎngluò.","vi":"Khách sạn có mạng không dây miễn phí."},{"type":"simple","zh":"咖啡馆的无线网络密码写在小黑板上。","pinyin":"Kāfēiguǎn de wúxiànwǎngluò mìmǎ xiě zài xiǎo hēibǎn shang.","vi":"Mật khẩu mạng không dây của quán cà phê được viết trên tấm bảng đen nhỏ."},{"type":"compound","zh":"一旦无线网络断了，大家就只能用手机流量开会。","pinyin":"Yídàn wúxiànwǎngluò duàn le, dàjiā jiù zhǐnéng yòng shǒujī liúliàng kāihuì.","vi":"Một khi mạng không dây bị mất, mọi người chỉ có thể dùng dữ liệu di động để họp."}],"related":[{"hanzi":"无线","pinyin":"wúxiàn","vi":"không dây"},{"hanzi":"宽带","pinyin":"kuāndài","vi":"băng thông rộng"},{"hanzi":"路由器","pinyin":"lùyóuqì","vi":"bộ định tuyến"},{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"}],"traditional":"無線網絡"},{"id":"无休止","hanzi":"无休止","pinyin":"wúxiūzhǐ","meaning_vi":"không ngừng nghỉ","explanation":"无 (vô tận/không có) + 休 (nghỉ ngơi/thư giãn) + 止 (ngăn chặn/dừng lại).","hsk_level":"7-9","tags":["tinh-tu","pho-tu"],"image":"🔁","examples":[{"type":"basic","zh":"争吵无休止地继续着。","pinyin":"Zhēngchǎo wúxiūzhǐ de jìxù zhe.","vi":"Cuộc cãi vã cứ tiếp diễn không ngừng."},{"type":"simple","zh":"邻居家无休止的装修噪音让我睡不着。","pinyin":"Lín jūjiā wúxiūzhǐ de zhuāngxiū zàoyīn ràng wǒ shuìbùzháo.","vi":"Tiếng ồn sửa nhà không dứt của nhà hàng xóm khiến tôi không ngủ được."},{"type":"compound","zh":"如果会议无休止地拖下去，项目就会错过截止日期。","pinyin":"Rúguǒ huìyì wúxiūzhǐ de tuō xiàqù, xiàngmù jiù huì cuòguò jiézhǐ rìqī.","vi":"Nếu cuộc họp cứ kéo dài không dứt, dự án sẽ lỡ hạn chót."}],"related":[{"hanzi":"无止境","pinyin":"wúzhǐjìng","vi":"không có điểm dừng"},{"hanzi":"没完没了","pinyin":"méiwánméiliǎo","vi":"không dứt"},{"hanzi":"永无止境","pinyin":"yǒngwúzhǐjìng","vi":"mãi không ngừng"},{"hanzi":"不停","pinyin":"bùtíng","vi":"không ngừng"}],"traditional":"無休止"},{"id":"无形","hanzi":"无形","pinyin":"wúxíng","meaning_vi":"vô hình (tài sản vô hình - 无形资产)","explanation":"无 (vô tận/không có) + 形 (hình thái/hình thành).","hsk_level":"7-9","tags":["tinh-tu"],"image":"👻","examples":[{"type":"basic","zh":"品牌是无形资产。","pinyin":"Pǐnpái shì wúxíng zīchǎn.","vi":"Thương hiệu là tài sản vô hình."},{"type":"simple","zh":"父母的期望给了他一种无形的压力。","pinyin":"Fùmǔ de qīwàng gěile tā yì zhǒng wúxíng de yālì.","vi":"Kỳ vọng của bố mẹ tạo cho cậu ấy một áp lực vô hình."},{"type":"compound","zh":"好习惯虽然是无形的，但是会在无形中改变一个人。","pinyin":"Hǎo xíguàn suīrán shì wúxíng de, dànshì huì zài wúxíngzhōng gǎibiàn yígèrén.","vi":"Thói quen tốt tuy vô hình, nhưng sẽ âm thầm thay đổi một con người."}],"related":[{"hanzi":"有形","pinyin":"yǒuxíng","vi":"hữu hình"},{"hanzi":"无形资产","pinyin":"wúxíngzīchǎn","vi":"tài sản vô hình"},{"hanzi":"无形中","pinyin":"wúxíngzhōng","vi":"một cách vô hình"},{"hanzi":"看不见","pinyin":"kànbújiàn","vi":"không nhìn thấy"}],"traditional":"無形"},{"id":"无意","hanzi":"无意","pinyin":"wúyì","meaning_vi":"vô tình, không cố ý","explanation":"无 (vô tận/không có) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["pho-tu","tinh-tu"],"image":"🙈","examples":[{"type":"basic","zh":"我无意中看到了答案。","pinyin":"Wǒ wúyìzhōng kàndàole dá'àn.","vi":"Tôi vô tình nhìn thấy đáp án."},{"type":"simple","zh":"他无意间说的一句话伤害了朋友。","pinyin":"Tā wúyìjiān shuō de yíjùhuà shānghàile péngyou.","vi":"Một câu nói vô tình của anh ấy đã làm tổn thương bạn bè."},{"type":"compound","zh":"我本来无意打扰你，可是这件事实在太急了。","pinyin":"Wǒ běnlái wúyì dǎrǎo nǐ, kěshì zhè jiàn shì shízài tài jí le.","vi":"Tôi vốn không có ý làm phiền bạn, nhưng việc này thật sự quá gấp."}],"related":[{"hanzi":"无心","pinyin":"wúxīn","vi":"vô tình"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"},{"hanzi":"有意","pinyin":"yǒuyì","vi":"cố ý"},{"hanzi":"无意中","pinyin":"wúyìzhōng","vi":"vô tình"}],"traditional":"無意"},{"id":"无与伦比","hanzi":"无与伦比","pinyin":"wúyǔ-lúnbǐ","meaning_vi":"tuyệt vời không gì sánh bằng","explanation":"无 (vô tận/không có) + 与 (và) + 伦 (伦) + 比 (so sánh/tỷ lệ).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"👑","examples":[{"type":"basic","zh":"这里的风景无与伦比。","pinyin":"Zhèlǐ de fēngjǐng wúyǔlúnbǐ.","vi":"Phong cảnh nơi đây đẹp không gì sánh bằng."},{"type":"simple","zh":"她在决赛中展现了无与伦比的技巧。","pinyin":"Tā zài juésài zhōng zhǎnxiànle wúyǔlúnbǐ de jìqiǎo.","vi":"Cô ấy đã thể hiện kỹ thuật không ai sánh bằng trong trận chung kết."},{"type":"compound","zh":"虽然门票很贵，但是那场音乐会的效果无与伦比。","pinyin":"Suīrán ménpiào hěn guì, dànshì nà chǎng yīnyuèhuì de xiàoguǒ wúyǔlúnbǐ.","vi":"Tuy vé rất đắt, nhưng hiệu quả của buổi hòa nhạc đó thì không gì sánh bằng."}],"related":[{"hanzi":"举世无双","pinyin":"jǔshìwúshuāng","vi":"có một không hai"},{"hanzi":"独一无二","pinyin":"dúyìwú'èr","vi":"độc nhất vô nhị"},{"hanzi":"绝无仅有","pinyin":"juéwújǐnyǒu","vi":"hiếm có"},{"hanzi":"平淡无奇","pinyin":"píngdànwúqí","vi":"bình thường tẻ nhạt"}],"traditional":"無與倫比"},{"id":"无足轻重","hanzi":"无足轻重","pinyin":"wúzú-qīngzhòng","meaning_vi":"không quan trọng, không đáng kể","explanation":"无 (vô tận/không có) + 足 (đầy đủ/chân) + 轻 (nhẹ) + 重 (nặng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🪶","examples":[{"type":"basic","zh":"这点小错无足轻重。","pinyin":"Zhè diǎn xiǎo cuò wúzúqīngzhòng.","vi":"Lỗi nhỏ này không đáng kể."},{"type":"simple","zh":"他在公司里只是个无足轻重的小职员。","pinyin":"Tā zài gōngsī lǐ zhǐshì gè wúzúqīngzhòng de xiǎo zhíyuán.","vi":"Ở công ty, anh ấy chỉ là một nhân viên nhỏ không quan trọng."},{"type":"compound","zh":"有些细节虽然看似无足轻重，却往往决定了谈判的成败。","pinyin":"Yǒuxiē xìjié suīrán kànsì wúzúqīngzhòng, què wǎngwǎng juédìngle tánpàn de chéngbài.","vi":"Có những chi tiết tuy tưởng chừng không đáng kể, nhưng lại thường quyết định thành bại của cuộc đàm phán."}],"related":[{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"nhỏ nhặt không đáng kể"},{"hanzi":"举足轻重","pinyin":"jǔzúqīngzhòng","vi":"có vai trò quyết định"},{"hanzi":"无关紧要","pinyin":"wúguānjǐnyào","vi":"không quan trọng"},{"hanzi":"至关重要","pinyin":"zhìguānzhòngyào","vi":"cực kỳ quan trọng"}],"traditional":"無足輕重"},{"id":"挖掘机","hanzi":"挖掘机","pinyin":"wājuéjī","meaning_vi":"máy xúc","explanation":"挖 (khai quật/đào) + 掘 (掘) + 机 (cơ hội/máy móc).","hsk_level":"7-9","tags":["danh-tu","cong-viec","do-vat"],"image":"🚜","examples":[{"type":"basic","zh":"工地上停着挖掘机。","pinyin":"Gōngdì shang tíngzhe wājuéjī.","vi":"Trên công trường có máy xúc đang đậu."},{"type":"simple","zh":"小男孩站在路边看挖掘机挖土。","pinyin":"Xiǎo nánhái zhàn zài lùbiān kàn wājuéjī wā tǔ.","vi":"Cậu bé đứng bên đường xem máy xúc đào đất."},{"type":"compound","zh":"因为山路被泥石流堵住了，所以救援队调来了两台挖掘机。","pinyin":"Yīnwèi shānlù bèi níshíliú dǔzhù le, suǒyǐ jiùyuánduì diào láile liǎng tái wājuéjī.","vi":"Vì đường núi bị lũ bùn đá chặn nên đội cứu hộ đã điều đến hai chiếc máy xúc."}],"related":[{"hanzi":"挖掘","pinyin":"wājué","vi":"đào bới"},{"hanzi":"推土机","pinyin":"tuītǔjī","vi":"máy ủi"},{"hanzi":"起重机","pinyin":"qǐzhòngjī","vi":"cần cẩu"},{"hanzi":"工地","pinyin":"gōngdì","vi":"công trường"}],"traditional":"挖掘機"},{"id":"湾区","hanzi":"湾区","pinyin":"Wānqū","meaning_vi":"vùng vịnh (Vùng Vịnh Lớn Quảng Đông - Hồng Kông - Ma Cao)","explanation":"湾 (vịnh biển) + 区 (区).","hsk_level":"7-9","tags":["danh-tu","dia-danh","xa-hoi"],"image":"🌉","examples":[{"type":"basic","zh":"他在湾区工作。","pinyin":"Tā zài Wānqū gōngzuò.","vi":"Anh ấy làm việc ở vùng vịnh."},{"type":"simple","zh":"粤港澳大湾区的交通越来越方便了。","pinyin":"Yuègǎng'àodàwānqū de jiāotōng yuèláiyuè fāngbiàn le.","vi":"Giao thông ở Vùng Vịnh Lớn Quảng Đông - Hồng Kông - Ma Cao ngày càng thuận tiện."},{"type":"compound","zh":"既然港珠澳大桥已经通车，湾区城市之间的往来就更紧密了。","pinyin":"Jìrán Gǎngzhū'àodàqiáo yǐjīng tōngchē, Wānqū chéngshì zhījiān de wǎnglái jiù gèng jǐnmì le.","vi":"Vì cầu Hồng Kông - Chu Hải - Ma Cao đã thông xe, sự qua lại giữa các thành phố trong vùng vịnh càng chặt chẽ hơn."}],"related":[{"hanzi":"粤港澳大湾区","pinyin":"Yuè Gǎng'ào Dàwānqū","vi":"Vùng Vịnh Lớn"},{"hanzi":"港湾","pinyin":"gǎngwān","vi":"vịnh cảng"},{"hanzi":"海湾","pinyin":"hǎiwān","vi":"vịnh biển"},{"hanzi":"深圳","pinyin":"Shēnzhèn","vi":"Thâm Quyến"}],"traditional":"灣區"},{"id":"微薄","hanzi":"微薄","pinyin":"wēibó","meaning_vi":"ít ỏi, nhỏ bé (thu nhập/sức lực)","explanation":"微 (vi mô/nhỏ bé) + 薄 (mỏng manh/bạc bẽo).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🤏","examples":[{"type":"basic","zh":"他的收入很微薄。","pinyin":"Tā de shōurù hěn wēibó.","vi":"Thu nhập của anh ấy rất ít ỏi."},{"type":"simple","zh":"我愿意为灾区尽一份微薄之力。","pinyin":"Wǒ yuànyì wèi zāiqū jìn yí fèn wēibó zhī lì.","vi":"Tôi sẵn lòng góp một phần sức lực nhỏ bé cho vùng bị thiên tai."},{"type":"compound","zh":"虽然工资微薄，但是她每个月都寄钱给老家的父母。","pinyin":"Suīrán gōngzī wēibó, dànshì tā měi gèyuè dōu jì qián gěi lǎojiā de fùmǔ.","vi":"Tuy lương ít ỏi, nhưng tháng nào cô ấy cũng gửi tiền về cho bố mẹ ở quê."}],"related":[{"hanzi":"微小","pinyin":"wēixiǎo","vi":"nhỏ bé"},{"hanzi":"微不足道","pinyin":"wēibùzúdào","vi":"nhỏ nhặt"},{"hanzi":"丰厚","pinyin":"fēnghòu","vi":"dồi dào"},{"hanzi":"收入微薄","pinyin":"shōurùwēibó","vi":"thu nhập ít ỏi"}]},{"id":"微观经济","hanzi":"微观经济","pinyin":"wēiguānjīngjì","meaning_vi":"kinh tế vi mô","explanation":"微观 (vi mô) + 经济 (kinh tế).","hsk_level":"7-9","tags":["danh-tu","cong-viec","hoc-tap"],"image":"🔬","examples":[{"type":"basic","zh":"我选修了微观经济。","pinyin":"Wǒ xuǎnxiūle wēiguānjīngjì.","vi":"Tôi đã chọn học môn kinh tế vi mô."},{"type":"simple","zh":"教授用超市定价的例子讲解微观经济。","pinyin":"Jiàoshòu yòng chāoshì dìngjià de lìzi jiǎngjiě wēiguānjīngjì.","vi":"Giáo sư dùng ví dụ định giá ở siêu thị để giảng giải kinh tế vi mô."},{"type":"compound","zh":"要想看懂企业的定价策略，就得先学好微观经济。","pinyin":"Yào xiǎng kàndǒng qǐyè de dìngjià cèlüè, jiù děi xiān xuéhǎo wēiguānjīngjì.","vi":"Muốn hiểu chiến lược định giá của doanh nghiệp thì trước hết phải học tốt kinh tế vi mô."}],"related":[{"hanzi":"宏观经济","pinyin":"hóngguānjīngjì","vi":"kinh tế vĩ mô"},{"hanzi":"经济学","pinyin":"jīngjìxué","vi":"kinh tế học"},{"hanzi":"供求","pinyin":"gōngqiú","vi":"cung cầu"},{"hanzi":"市场","pinyin":"shìchǎng","vi":"thị trường"}],"traditional":"微觀經濟"},{"id":"危及","hanzi":"危及","pinyin":"wēijí","meaning_vi":"đe dọa tới, gây nguy hiểm cho","explanation":"危 (khủng hoảng/nguy cơ) + 及 (kịp thời/đạt tới).","hsk_level":"7-9","tags":["dong-tu"],"image":"⚠️","examples":[{"type":"basic","zh":"酒驾会危及生命。","pinyin":"Jiǔjià huì wēijí shēngmìng.","vi":"Lái xe khi say rượu có thể đe dọa tính mạng."},{"type":"simple","zh":"这场洪水已经危及下游村庄的安全。","pinyin":"Zhè chǎng hóngshuǐ yǐjīng wēijí xiàyóu cūnzhuāng de ānquán.","vi":"Trận lũ này đã đe dọa đến sự an toàn của các làng ở hạ lưu."},{"type":"compound","zh":"如果大坝出现裂缝，就可能危及几十万人的生命。","pinyin":"Rúguǒ dàbà chūxiàn lièfèng, jiù kěnéng wēijí jǐ shí wànrén de shēngmìng.","vi":"Nếu đập xuất hiện vết nứt, có thể đe dọa tính mạng của hàng trăm nghìn người."}],"related":[{"hanzi":"危害","pinyin":"wēihài","vi":"gây hại"},{"hanzi":"威胁","pinyin":"wēixié","vi":"đe dọa"},{"hanzi":"危及生命","pinyin":"wēijíshēngmìng","vi":"đe dọa tính mạng"},{"hanzi":"危险","pinyin":"wēixiǎn","vi":"nguy hiểm"}]},{"id":"危机感","hanzi":"危机感","pinyin":"wēijīgǎn","meaning_vi":"ý thức cảnh giác trước nguy cơ","explanation":"危 (khủng hoảng/nguy cơ) + 机 (cơ hội/máy móc) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","cong-viec"],"image":"🚨","examples":[{"type":"basic","zh":"公司缺乏危机感。","pinyin":"Gōngsī quēfá wēijīgǎn.","vi":"Công ty thiếu ý thức về nguy cơ."},{"type":"simple","zh":"新同事的加入让老员工有了危机感。","pinyin":"Xīn tóngshì de jiārù ràng lǎo yuángōng yǒule wēijīgǎn.","vi":"Sự gia nhập của đồng nghiệp mới khiến nhân viên cũ cảm thấy có nguy cơ."},{"type":"compound","zh":"一个人一旦失去危机感，就很容易停止进步。","pinyin":"Yígèrén yídàn shīqù wēijīgǎn, jiù hěn róngyì tíngzhǐ jìnbù.","vi":"Một người một khi mất đi ý thức cảnh giác trước nguy cơ thì rất dễ ngừng tiến bộ."}],"related":[{"hanzi":"危机","pinyin":"wēijī","vi":"khủng hoảng"},{"hanzi":"忧患意识","pinyin":"yōuhuànyìshí","vi":"ý thức lo xa"},{"hanzi":"紧迫感","pinyin":"jǐnpògǎn","vi":"cảm giác cấp bách"},{"hanzi":"安全感","pinyin":"ānquángǎn","vi":"cảm giác an toàn"}],"traditional":"危機感"},{"id":"微调","hanzi":"微调","pinyin":"wēitiáo","meaning_vi":"điều chỉnh nhẹ (vi chỉnh)","explanation":"微 (vi mô/nhỏ bé) + 调 (điều chỉnh/hòa giải).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🎛️","examples":[{"type":"basic","zh":"价格只是微调。","pinyin":"Jiàgé zhǐshì wēitiáo.","vi":"Giá chỉ điều chỉnh nhẹ thôi."},{"type":"simple","zh":"设计师对海报的颜色做了一些微调。","pinyin":"Shèjìshī duì hǎibào de yánsè zuòle yìxiē wēitiáo.","vi":"Nhà thiết kế đã điều chỉnh nhẹ màu sắc của tấm áp phích."},{"type":"compound","zh":"方案整体没有问题，只要微调几个数字就可以提交了。","pinyin":"Fāng'àn zhěngtǐ méiyǒu wèntí, zhǐyào wēitiáo jǐ gè shùzì jiù kěyǐ tíjiāo le.","vi":"Phương án nhìn chung không có vấn đề, chỉ cần điều chỉnh nhẹ vài con số là có thể nộp."}],"related":[{"hanzi":"调整","pinyin":"tiáozhěng","vi":"điều chỉnh"},{"hanzi":"微小","pinyin":"wēixiǎo","vi":"nhỏ bé"},{"hanzi":"大调整","pinyin":"dàtiáozhěng","vi":"điều chỉnh lớn"},{"hanzi":"修正","pinyin":"xiūzhèng","vi":"sửa đổi"}],"traditional":"微調"},{"id":"微笑服务","hanzi":"微笑服务","pinyin":"wēixiàofúwù","meaning_vi":"dịch vụ nụ cười thân thiện","explanation":"微 (vi mô/nhỏ bé) + 笑 (cười) + 服 (服) + 务 (nhiệm vụ/thiết thực).","hsk_level":"7-9","tags":["danh-tu","cong-viec","giao-tiep"],"image":"😊","examples":[{"type":"basic","zh":"银行推行微笑服务。","pinyin":"Yínháng tuīxíng wēixiàofúwù.","vi":"Ngân hàng áp dụng dịch vụ nụ cười."},{"type":"simple","zh":"这家餐厅的微笑服务给顾客留下了好印象。","pinyin":"Zhè jiā cāntīng de wēixiàofúwù gěi gùkè liúxiàle hǎo yìnxiàng.","vi":"Dịch vụ nụ cười của nhà hàng này đã để lại ấn tượng tốt cho khách hàng."},{"type":"compound","zh":"微笑服务不但能让乘客心情愉快，而且能减少投诉。","pinyin":"Wēixiàofúwù búdàn néng ràng chéngkè xīnqíng yúkuài, érqiě néng jiǎnshǎo tóusù.","vi":"Dịch vụ nụ cười không những khiến hành khách vui vẻ mà còn giảm bớt khiếu nại."}],"related":[{"hanzi":"服务态度","pinyin":"fúwùtàidù","vi":"thái độ phục vụ"},{"hanzi":"微笑","pinyin":"wēixiào","vi":"mỉm cười"},{"hanzi":"热情","pinyin":"rèqíng","vi":"nhiệt tình"},{"hanzi":"顾客","pinyin":"gùkè","vi":"khách hàng"}],"traditional":"微笑服務"},{"id":"微型","hanzi":"微型","pinyin":"wēixíng","meaning_vi":"siêu nhỏ, cỡ nhỏ (micro)","explanation":"微 (vi mô/nhỏ bé) + 型 (mô hình/kiểu dáng).","hsk_level":"7-9","tags":["tinh-tu","cong-nghe"],"image":"🔬","examples":[{"type":"basic","zh":"这是一台微型相机。","pinyin":"Zhè shì yì tái wēixíng xiàngjī.","vi":"Đây là một chiếc máy ảnh siêu nhỏ."},{"type":"simple","zh":"医生用微型摄像头检查病人的胃部。","pinyin":"Yīshēng yòng wēixíng shèxiàngtóu jiǎnchá bìngrén de wèi bù.","vi":"Bác sĩ dùng camera siêu nhỏ để kiểm tra dạ dày bệnh nhân."},{"type":"compound","zh":"因为城市房价太高，所以不少年轻人住进了微型公寓。","pinyin":"Yīnwèi chéngshì fángjià tài gāo, suǒyǐ bùshǎo niánqīngrén zhù jìnle wēixíng gōngyù.","vi":"Vì giá nhà ở thành phố quá cao nên không ít người trẻ đã chuyển vào ở căn hộ siêu nhỏ."}],"related":[{"hanzi":"小型","pinyin":"xiǎoxíng","vi":"cỡ nhỏ"},{"hanzi":"大型","pinyin":"dàxíng","vi":"cỡ lớn"},{"hanzi":"微型企业","pinyin":"wēixíngqǐyè","vi":"doanh nghiệp siêu nhỏ"},{"hanzi":"迷你","pinyin":"mínǐ","vi":"mini"}]},{"id":"温泉","hanzi":"温泉","pinyin":"wēnquán","meaning_vi":"suối nước nóng","explanation":"温 (ôn hòa/ấm áp) + 泉 (suối nước).","hsk_level":"7-9","tags":["danh-tu","du-lich","thien-nhien"],"image":"♨️","examples":[{"type":"basic","zh":"冬天适合泡温泉。","pinyin":"Dōngtiān shìhé pàowēnquán.","vi":"Mùa đông thích hợp để ngâm suối nước nóng."},{"type":"simple","zh":"我们在山脚下的温泉旅馆住了一晚。","pinyin":"Wǒmen zài shān jiǎoxià de wēnquán lǚguǎn zhùle yì wǎn.","vi":"Chúng tôi đã ở một đêm tại nhà trọ suối nước nóng dưới chân núi."},{"type":"compound","zh":"一泡进温泉，爸爸就舒服得闭上了眼睛。","pinyin":"Yí pào jìn wēnquán, bàba jiù shūfu de bìshàngle yǎnjing.","vi":"Vừa ngâm mình vào suối nước nóng, bố đã khoan khoái nhắm mắt lại."}],"related":[{"hanzi":"泡温泉","pinyin":"pàowēnquán","vi":"ngâm suối nước nóng"},{"hanzi":"泉水","pinyin":"quánshuǐ","vi":"nước suối"},{"hanzi":"度假村","pinyin":"dùjiàcūn","vi":"khu nghỉ dưỡng"},{"hanzi":"水疗","pinyin":"shuǐliáo","vi":"thủy liệu pháp"}],"traditional":"溫泉"},{"id":"温情","hanzi":"温情","pinyin":"wēnqíng","meaning_vi":"tình cảm ấm áp","explanation":"温 (ôn hòa/ấm áp) + 情 (tình cảm/tình hình).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"❤️","examples":[{"type":"basic","zh":"这部电影充满温情。","pinyin":"Zhè bù diànyǐng chōngmǎn wēnqíng.","vi":"Bộ phim này tràn đầy tình cảm ấm áp."},{"type":"simple","zh":"邻居送来的一碗热汤让我感受到了温情。","pinyin":"Línjū sòng lái de yì wǎn rè tāng ràng wǒ gǎn shòudàole wēnqíng.","vi":"Bát canh nóng hàng xóm mang sang khiến tôi cảm nhận được tình người ấm áp."},{"type":"compound","zh":"城市虽然节奏很快，但是街头的小事里依然藏着温情。","pinyin":"Chéngshì suīrán jiézòu hěn kuài, dànshì jiētóu de xiǎoshì lǐ yīrán cángzhe wēnqíng.","vi":"Thành phố tuy nhịp sống nhanh, nhưng trong những chuyện nhỏ trên phố vẫn ẩn chứa tình cảm ấm áp."}],"related":[{"hanzi":"温暖","pinyin":"wēnnuǎn","vi":"ấm áp"},{"hanzi":"温馨","pinyin":"wēnxīn","vi":"ấm cúng"},{"hanzi":"亲情","pinyin":"qīnqíng","vi":"tình thân"},{"hanzi":"冷漠","pinyin":"lěngmò","vi":"lạnh nhạt"}],"traditional":"溫情"},{"id":"温室效应","hanzi":"温室效应","pinyin":"wēnshìxiàoyìng","meaning_vi":"hiệu ứng nhà kính","explanation":"温 (ôn hòa/ấm áp) + 室 (室) + 效 (hiệu quả/hiệu suất) + 应 (ứng phó/phản ứng).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🌡️","examples":[{"type":"basic","zh":"温室效应越来越严重。","pinyin":"Wēnshìxiàoyìng yuèláiyuè yánzhòng.","vi":"Hiệu ứng nhà kính ngày càng nghiêm trọng."},{"type":"simple","zh":"老师用一个玻璃罩做实验演示温室效应。","pinyin":"Lǎoshī yòng yí gè bōlizhào zuò shíyàn yǎnshì wēnshìxiàoyìng.","vi":"Thầy giáo dùng một chiếc chụp thủy tinh làm thí nghiệm minh họa hiệu ứng nhà kính."},{"type":"compound","zh":"如果二氧化碳排放继续增加，温室效应就会让冰川加速融化。","pinyin":"Rúguǒ èryǎnghuàtàn páifàng jìxù zēngjiā, wēnshìxiàoyìng jiù huì ràng bīngchuān jiāsù rónghuà.","vi":"Nếu lượng khí thải carbon dioxide tiếp tục tăng, hiệu ứng nhà kính sẽ khiến băng hà tan nhanh hơn."}],"related":[{"hanzi":"温室气体","pinyin":"wēnshìqìtǐ","vi":"khí nhà kính"},{"hanzi":"全球变暖","pinyin":"quánqiúbiànnuǎn","vi":"nóng lên toàn cầu"},{"hanzi":"碳排放","pinyin":"tànpáifàng","vi":"phát thải cacbon"},{"hanzi":"气候变化","pinyin":"qìhòubiànhuà","vi":"biến đổi khí hậu"}],"traditional":"溫室效應"},{"id":"温文尔雅","hanzi":"温文尔雅","pinyin":"wēnwén-ěryǎ","meaning_vi":"nho nhã lịch thiệp","explanation":"温 (ôn hòa/ấm áp) + 文 (văn hóa/văn minh) + 尔 (như vậy/bạn) + 雅 (tao nhã/văn nhã).","hsk_level":"7-9","tags":["thanh-ngu","con-nguoi"],"image":"🤓","examples":[{"type":"basic","zh":"他总是温文尔雅。","pinyin":"Tā zǒngshì wēnwén'ěryǎ.","vi":"Anh ấy lúc nào cũng nho nhã lịch thiệp."},{"type":"simple","zh":"这位温文尔雅的教授很受学生欢迎。","pinyin":"Zhè wèi wēnwén'ěryǎ de jiàoshòu hěn shòu xuéshēng huānyíng.","vi":"Vị giáo sư nho nhã lịch thiệp này rất được sinh viên yêu mến."},{"type":"compound","zh":"他平时温文尔雅，可是一谈到不公平的事就会激动起来。","pinyin":"Tā píngshí wēnwén'ěryǎ, kěshì yì tándào bù gōngpíng de shì jiù huì jīdòng qǐlái.","vi":"Bình thường anh ấy rất nho nhã lịch thiệp, nhưng hễ nói đến chuyện bất công là lại kích động."}],"related":[{"hanzi":"彬彬有礼","pinyin":"bīnbīnyǒulǐ","vi":"lịch sự nhã nhặn"},{"hanzi":"斯文","pinyin":"sīwen","vi":"nho nhã"},{"hanzi":"文质彬彬","pinyin":"wénzhìbīnbīn","vi":"văn nhã lịch thiệp"},{"hanzi":"粗鲁","pinyin":"cūlǔ","vi":"thô lỗ"}],"traditional":"溫文爾雅"},{"id":"伪劣","hanzi":"伪劣","pinyin":"wěiliè","meaning_vi":"giả mạo kém chất lượng (假冒伪劣商品)","explanation":"伪 (giả mạo/ngụy trang) + 劣 (kém cỏi/xấu xa).","hsk_level":"7-9","tags":["tinh-tu","mua-sam"],"image":"🚫","examples":[{"type":"basic","zh":"警方查获伪劣商品。","pinyin":"Jǐngfāng cháhuò wěiliè shāngpǐn.","vi":"Cảnh sát thu giữ hàng giả kém chất lượng."},{"type":"simple","zh":"消费者要警惕网上销售的假冒伪劣产品。","pinyin":"Xiāofèizhě yào jǐngtì wǎngshàng xiāoshòu de jiǎmàowěiliè chǎnpǐn.","vi":"Người tiêu dùng cần cảnh giác với hàng giả, hàng kém chất lượng bán trên mạng."},{"type":"compound","zh":"一旦发现伪劣化妆品，就应该立即向市场监管部门举报。","pinyin":"Yídàn fāxiàn wěiliè huàzhuāngpǐn, jiù yīnggāi lìjí xiàng shìchǎng jiānguǎn bùmén jǔbào.","vi":"Một khi phát hiện mỹ phẩm giả kém chất lượng, cần lập tức tố giác với cơ quan quản lý thị trường."}],"related":[{"hanzi":"假冒伪劣","pinyin":"jiǎmàowěiliè","vi":"hàng giả kém chất lượng"},{"hanzi":"假货","pinyin":"jiǎhuò","vi":"hàng giả"},{"hanzi":"劣质","pinyin":"lièzhì","vi":"kém chất lượng"},{"hanzi":"正品","pinyin":"zhèngpǐn","vi":"hàng chính hãng"}],"traditional":"偽劣"},{"id":"伟人","hanzi":"伟人","pinyin":"wěirén","meaning_vi":"vĩ nhân","explanation":"伟 (vĩ đại/hùng vĩ) + 人 (người).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","van-hoa"],"image":"👑","examples":[{"type":"basic","zh":"他是一位伟人。","pinyin":"Tā shì yí wèi wěirén.","vi":"Ông ấy là một vĩ nhân."},{"type":"simple","zh":"博物馆里陈列着这位伟人的手稿。","pinyin":"Bówùguǎn lǐ chénlièzhe zhè wèi wěirén de shǒugǎo.","vi":"Trong bảo tàng trưng bày bản thảo viết tay của vị vĩ nhân này."},{"type":"compound","zh":"伟人虽然受人敬仰，但是他们也有普通人的烦恼。","pinyin":"Wěirén suīrán shòu rén jìngyǎng, dànshì tāmen yě yǒu pǔtōngrén de fánnǎo.","vi":"Vĩ nhân tuy được người đời kính ngưỡng, nhưng họ cũng có những phiền muộn của người bình thường."}],"related":[{"hanzi":"伟大","pinyin":"wěidà","vi":"vĩ đại"},{"hanzi":"名人","pinyin":"míngrén","vi":"người nổi tiếng"},{"hanzi":"英雄","pinyin":"yīngxióng","vi":"anh hùng"},{"hanzi":"凡人","pinyin":"fánrén","vi":"người thường"}],"traditional":"偉人"},{"id":"尾随","hanzi":"尾随","pinyin":"wěisuí","meaning_vi":"bám đuôi theo dõi","explanation":"尾 (hồi kết/đuôi) + 随 (tùy ý/đi theo).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🕵️","examples":[{"type":"basic","zh":"有人在尾随她。","pinyin":"Yǒurén zài wěisuí tā.","vi":"Có người đang bám đuôi cô ấy."},{"type":"simple","zh":"小偷尾随老人进了电梯。","pinyin":"Xiǎotōu wěisuí lǎorén jìnle diàntī.","vi":"Tên trộm bám theo ông cụ vào thang máy."},{"type":"compound","zh":"如果发现有陌生人尾随，你就马上走到人多的地方。","pinyin":"Rúguǒ fāxiàn yǒu mòshēngrén wěisuí, nǐ jiù mǎshàng zǒu dào rén duō de dìfang.","vi":"Nếu phát hiện có người lạ bám theo, bạn hãy lập tức đi đến chỗ đông người."}],"related":[{"hanzi":"跟踪","pinyin":"gēnzōng","vi":"theo dõi"},{"hanzi":"跟随","pinyin":"gēnsuí","vi":"đi theo"},{"hanzi":"盯梢","pinyin":"dīngshāo","vi":"bám đuôi"},{"hanzi":"跟踪狂","pinyin":"gēnzōngkuáng","vi":"kẻ đeo bám"}],"traditional":"尾隨"},{"id":"委托","hanzi":"委托","pinyin":"wěituō","meaning_vi":"ủy thác, nhờ cậy","explanation":"委 (ủy thác/ấm ức) + 托 (ủy thác/nâng đỡ).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"我委托律师处理。","pinyin":"Wǒ wěituō lǜshī chǔlǐ.","vi":"Tôi ủy thác cho luật sư xử lý."},{"type":"simple","zh":"王阿姨委托邻居帮她照顾家里的花。","pinyin":"Wáng āyí wěituō línjū bāng tā zhàogù jiālǐ de huā.","vi":"Dì Vương nhờ hàng xóm chăm sóc hộ hoa trong nhà."},{"type":"compound","zh":"因为我下周出差，所以委托同事替我参加培训。","pinyin":"Yīnwèi wǒ xiàzhōu chūchāi, suǒyǐ wěituō tóngshì tì wǒ cānjiā péixùn.","vi":"Vì tuần sau tôi đi công tác nên đã nhờ đồng nghiệp tham gia khóa đào tạo thay."}],"related":[{"hanzi":"托付","pinyin":"tuōfù","vi":"gửi gắm"},{"hanzi":"委托人","pinyin":"wěituōrén","vi":"người ủy thác"},{"hanzi":"代理","pinyin":"dàilǐ","vi":"đại lý"},{"hanzi":"授权","pinyin":"shòuquán","vi":"ủy quyền"}],"traditional":"委託"},{"id":"委员","hanzi":"委员","pinyin":"wěiyuán","meaning_vi":"ủy viên","explanation":"委 (ủy thác/ấm ức) + 员 (员).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"她当选为委员。","pinyin":"Tā dāngxuǎn wéi wěiyuán.","vi":"Bà ấy được bầu làm ủy viên."},{"type":"simple","zh":"几位委员在会上对新方案提出了疑问。","pinyin":"Jǐ wèi wěiyuán zài huì shang duì xīn fāng'àn tíchūle yíwèn.","vi":"Vài ủy viên đã nêu thắc mắc về phương án mới tại cuộc họp."},{"type":"compound","zh":"只要超过半数委员同意，这项提案就能通过。","pinyin":"Zhǐyào chāoguò bànshù wěiyuán tóngyì, zhè xiàng tí'àn jiù néng tōngguò.","vi":"Chỉ cần hơn một nửa số ủy viên đồng ý, đề xuất này sẽ được thông qua."}],"related":[{"hanzi":"委员会","pinyin":"wěiyuánhuì","vi":"ủy ban"},{"hanzi":"常委","pinyin":"chángwěi","vi":"ủy viên thường vụ"},{"hanzi":"代表","pinyin":"dàibiǎo","vi":"đại biểu"},{"hanzi":"成员","pinyin":"chéngyuán","vi":"thành viên"}],"traditional":"委員"},{"id":"稳健","hanzi":"稳健","pinyin":"wěnjiàn","meaning_vi":"vững vàng ổn định (bước đi/kinh tế)","explanation":"稳 (ổn định/vững vàng) + 健 (健).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🛡️","examples":[{"type":"basic","zh":"他走路很稳健。","pinyin":"Tā zǒulù hěn wěnjiàn.","vi":"Ông ấy đi đứng rất vững vàng."},{"type":"simple","zh":"这家公司一向采取稳健的投资策略。","pinyin":"Zhè jiā gōngsī yíxiàng cǎiqǔ wěnjiàn de tóuzī cèlüè.","vi":"Công ty này luôn áp dụng chiến lược đầu tư thận trọng, ổn định."},{"type":"compound","zh":"虽然市场波动很大，但是他的基金表现一直很稳健。","pinyin":"Suīrán shìchǎng bōdòng hěn dà, dànshì tā de jījīn biǎoxiàn yìzhí hěn wěnjiàn.","vi":"Tuy thị trường biến động mạnh, nhưng quỹ của anh ấy vẫn luôn hoạt động ổn định."}],"related":[{"hanzi":"稳重","pinyin":"wěnzhòng","vi":"chín chắn"},{"hanzi":"稳定","pinyin":"wěndìng","vi":"ổn định"},{"hanzi":"稳步","pinyin":"wěnbù","vi":"vững bước"},{"hanzi":"冒进","pinyin":"màojìn","vi":"liều lĩnh"}],"traditional":"穩健"},{"id":"稳重","hanzi":"稳重","pinyin":"wěnzhòng","meaning_vi":"chín chắn điềm đạm","explanation":"稳 (ổn định/vững vàng) + 重 (nặng).","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"🧘","examples":[{"type":"basic","zh":"哥哥性格稳重。","pinyin":"Gēge xìnggé wěnzhòng.","vi":"Anh trai có tính cách chín chắn điềm đạm."},{"type":"simple","zh":"面试官觉得这个年轻人说话很稳重。","pinyin":"Miànshìguān juéde zhè ge niánqīngrén shuōhuà hěn wěnzhòng.","vi":"Người phỏng vấn thấy chàng trai trẻ này nói năng rất chín chắn."},{"type":"compound","zh":"他虽然才二十五岁，但是做事比很多老员工还稳重。","pinyin":"Tā suīrán cái èr shíwǔ suì, dànshì zuòshì bǐ hěn duō lǎo yuángōng hái wěnzhòng.","vi":"Tuy mới hai mươi lăm tuổi, nhưng cậu ấy làm việc còn chín chắn hơn nhiều nhân viên lâu năm."}],"related":[{"hanzi":"沉稳","pinyin":"chénwěn","vi":"điềm tĩnh"},{"hanzi":"成熟","pinyin":"chéngshú","vi":"chín chắn"},{"hanzi":"老成","pinyin":"lǎochéng","vi":"từng trải"},{"hanzi":"轻浮","pinyin":"qīngfú","vi":"nông nổi"}],"traditional":"穩重"},{"id":"瓦片","hanzi":"瓦片","pinyin":"wǎpiàn","meaning_vi":"viên ngói","explanation":"瓦 (ngói/tan rã) + 片 (miếng).","hsk_level":"7-9","tags":["danh-tu","nha-cua","do-vat"],"image":"🏠","examples":[{"type":"basic","zh":"屋顶掉了几块瓦片。","pinyin":"Wūdǐng diàole jǐ kuài wǎpiàn.","vi":"Mái nhà rơi mất mấy viên ngói."},{"type":"simple","zh":"工人们正在给老房子换新的瓦片。","pinyin":"Gōngrénmen zhèngzài gěi lǎo fángzi huànxīn de wǎpiàn.","vi":"Các công nhân đang thay ngói mới cho ngôi nhà cũ."},{"type":"compound","zh":"台风一来，屋顶上的瓦片就被吹得哗哗作响。","pinyin":"Táifēng yìlái, wūdǐng shang de wǎpiàn jiù bèi chuī de huāhuā zuò xiǎng.","vi":"Bão vừa đến, ngói trên mái nhà đã bị gió thổi kêu lách cách."}],"related":[{"hanzi":"瓦","pinyin":"wǎ","vi":"ngói"},{"hanzi":"砖瓦","pinyin":"zhuānwǎ","vi":"gạch ngói"},{"hanzi":"屋顶","pinyin":"wūdǐng","vi":"mái nhà"},{"hanzi":"砖头","pinyin":"zhuāntóu","vi":"viên gạch"}]},{"id":"挽留","hanzi":"挽留","pinyin":"wǎnliú","meaning_vi":"giữ chân, níu kéo ở lại","explanation":"挽 (cứu vãn/vãn hồi) + 留 (ở lại).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"老板极力挽留他。","pinyin":"Lǎobǎn jílì wǎnliú tā.","vi":"Ông chủ ra sức giữ chân anh ấy."},{"type":"simple","zh":"主人热情地挽留客人吃晚饭。","pinyin":"Zhǔrén rèqíng de wǎnliú kèrén chī wǎnfàn.","vi":"Chủ nhà nhiệt tình giữ khách ở lại ăn tối."},{"type":"compound","zh":"尽管公司开出了高薪挽留，她还是决定出国读书。","pinyin":"Jǐnguǎn gōngsī kāi chūle gāoxīn wǎnliú, tā háishì juédìng chūguó dúshū.","vi":"Dù công ty đưa ra mức lương cao để giữ chân, cô ấy vẫn quyết định ra nước ngoài du học."}],"related":[{"hanzi":"留下","pinyin":"liúxià","vi":"ở lại"},{"hanzi":"挽回","pinyin":"wǎnhuí","vi":"cứu vãn"},{"hanzi":"劝说","pinyin":"quànshuō","vi":"khuyên nhủ"},{"hanzi":"辞职","pinyin":"cízhí","vi":"từ chức"}]},{"id":"网购","hanzi":"网购","pinyin":"wǎnggòu","meaning_vi":"mua sắm trực tuyến (online shopping)","explanation":"网 (mạng lưới) + 购 (购).","hsk_level":"7-9","tags":["dong-tu","mua-sam","cong-nghe"],"image":"🛒","examples":[{"type":"basic","zh":"妈妈也爱上了网购。","pinyin":"Māma yě àishàngle wǎnggòu.","vi":"Mẹ cũng đã mê mua sắm trực tuyến."},{"type":"simple","zh":"我昨天网购的台灯今天下午就到了。","pinyin":"Wǒ zuótiān wǎnggòu de táidēng jīntiān xiàwǔ jiù dào le.","vi":"Chiếc đèn bàn tôi mua online hôm qua đã giao tới vào chiều nay."},{"type":"compound","zh":"网购虽然方便，但是有时收到的东西跟图片不一样。","pinyin":"Wǎnggòu suīrán fāngbiàn, dànshì yǒushí shōudào de dōngxi gēn túpiàn bù yíyàng.","vi":"Mua sắm online tuy tiện lợi, nhưng đôi khi hàng nhận được không giống như ảnh."}],"related":[{"hanzi":"网店","pinyin":"wǎngdiàn","vi":"cửa hàng online"},{"hanzi":"电商","pinyin":"diànshāng","vi":"thương mại điện tử"},{"hanzi":"快递","pinyin":"kuàidì","vi":"chuyển phát nhanh"},{"hanzi":"购物车","pinyin":"gòuwùchē","vi":"giỏ hàng"}],"traditional":"網購"},{"id":"网红","hanzi":"网红","pinyin":"wǎnghóng","meaning_vi":"người nổi tiếng trên mạng (KOL/Influencer)","explanation":"网络 (mạng) + 红 (nổi tiếng).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","con-nguoi"],"image":"🌟","examples":[{"type":"basic","zh":"她是个美食网红。","pinyin":"Tā shì gè měishí wǎnghóng.","vi":"Cô ấy là một người nổi tiếng trên mạng về ẩm thực."},{"type":"simple","zh":"这家网红奶茶店门口每天都排长队。","pinyin":"Zhè jiā wǎnghóng nǎichá diàn ménkǒu měitiān dōu pái chángduì.","vi":"Trước cửa tiệm trà sữa nổi tiếng trên mạng này ngày nào cũng xếp hàng dài."},{"type":"compound","zh":"很多年轻人想当网红，可是真正能坚持下来的人很少。","pinyin":"Hěn duō niánqīngrén xiǎng dāng wǎnghóng, kěshì zhēnzhèng néng jiānchí xiàlái de rén hěn shǎo.","vi":"Nhiều bạn trẻ muốn trở thành người nổi tiếng trên mạng, nhưng người thực sự kiên trì được thì rất ít."}],"related":[{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"粉丝","pinyin":"fěnsī","vi":"người hâm mộ"},{"hanzi":"博主","pinyin":"bózhǔ","vi":"blogger"},{"hanzi":"走红","pinyin":"zǒuhóng","vi":"nổi tiếng"}],"traditional":"網紅"},{"id":"网络安全","hanzi":"网络安全","pinyin":"wǎngluò'ānquán","meaning_vi":"an ninh mạng","explanation":"网络 (võng lạc – mạng) + 安全 (an toàn) → an ninh mạng, bảo vệ hệ thống và dữ liệu khỏi tấn công. Ví dụ: 网络安全法.","hsk_level":"7-9","tags":["danh-tu","cong-nghe","phap-luat"],"image":"🔒","examples":[{"type":"basic","zh":"网络安全不容忽视。","pinyin":"Wǎngluò'ānquán bùróng hūshì.","vi":"An ninh mạng không thể xem nhẹ."},{"type":"simple","zh":"公司每年都给员工开展网络安全培训。","pinyin":"Gōngsī měinián dōu gěi yuángōng kāizhǎn wǎngluò'ānquán péixùn.","vi":"Năm nào công ty cũng tổ chức đào tạo về an ninh mạng cho nhân viên."},{"type":"compound","zh":"如果随便点击陌生链接，你的网络安全就会受到威胁。","pinyin":"Rúguǒ suíbiàn diǎnjī mòshēng liànjiē, nǐ de wǎngluò'ānquán jiù huì shòudào wēixié.","vi":"Nếu tùy tiện bấm vào đường link lạ, an ninh mạng của bạn sẽ bị đe dọa."}],"related":[{"hanzi":"黑客","pinyin":"hēikè","vi":"hacker"},{"hanzi":"病毒","pinyin":"bìngdú","vi":"vi-rút"},{"hanzi":"信息安全","pinyin":"xìnxī'ānquán","vi":"an toàn thông tin"},{"hanzi":"防火墙","pinyin":"fánghuǒqiáng","vi":"tường lửa"}],"traditional":"網絡安全"},{"id":"网罗人才","hanzi":"网罗人才","pinyin":"wǎngluóréncái","meaning_vi":"chiêu mộ nhân tài","explanation":"网 (mạng lưới) + 罗 (thu gom/la bàn) + 人 (người) + 才 (tài năng).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🌟","examples":[{"type":"basic","zh":"他们重金网罗人才。","pinyin":"Tāmen zhòngjīn wǎngluóréncái.","vi":"Họ bỏ ra số tiền lớn để chiêu mộ nhân tài."},{"type":"simple","zh":"这家科技公司到各大高校网罗人才。","pinyin":"Zhè jiā kējì gōngsī dào gè dà gāoxiào wǎngluóréncái.","vi":"Công ty công nghệ này đến các trường đại học lớn để chiêu mộ nhân tài."},{"type":"compound","zh":"为了网罗人才，市政府不但提供住房补贴，而且简化了落户手续。","pinyin":"Wèile wǎngluóréncái, shìzhèngfǔ búdàn tígōng zhùfáng bǔtiē, érqiě jiǎnhuàle luòhù shǒuxù.","vi":"Để chiêu mộ nhân tài, chính quyền thành phố không chỉ hỗ trợ nhà ở mà còn đơn giản hóa thủ tục nhập hộ khẩu."}],"related":[{"hanzi":"招聘","pinyin":"zhāopìn","vi":"tuyển dụng"},{"hanzi":"人才","pinyin":"réncái","vi":"nhân tài"},{"hanzi":"猎头","pinyin":"liètóu","vi":"săn đầu người"},{"hanzi":"招兵买马","pinyin":"zhāobīngmǎimǎ","vi":"chiêu binh mãi mã"}],"traditional":"網羅人才"},{"id":"往来","hanzi":"往来","pinyin":"wǎnglái","meaning_vi":"qua lại giao thiệp, giao thương","explanation":"往 (quá khứ/hướng tới) + 来 (đến).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤝","examples":[{"type":"basic","zh":"两国贸易往来频繁。","pinyin":"Liǎngguó màoyì wǎnglái pínfán.","vi":"Giao thương giữa hai nước diễn ra thường xuyên."},{"type":"simple","zh":"毕业以后我和他就没有什么往来了。","pinyin":"Bìyè yǐhòu wǒ hé tā jiù méiyǒu shénme wǎnglái le.","vi":"Sau khi tốt nghiệp, tôi và cậu ấy hầu như không còn qua lại gì nữa."},{"type":"compound","zh":"因为两家公司业务往来密切，所以老板们经常一起吃饭。","pinyin":"Yīnwèi liǎng jiā gōngsī yèwù wǎnglái mìqiè, suǒyǐ lǎobǎnmen jīngcháng yìqǐ chīfàn.","vi":"Vì hai công ty có quan hệ làm ăn mật thiết nên các ông chủ thường xuyên ăn cơm cùng nhau."}],"related":[{"hanzi":"来往","pinyin":"láiwǎng","vi":"qua lại"},{"hanzi":"交往","pinyin":"jiāowǎng","vi":"giao tiếp"},{"hanzi":"贸易往来","pinyin":"màoyìwǎnglái","vi":"giao thương"},{"hanzi":"互访","pinyin":"hùfǎng","vi":"thăm lẫn nhau"}],"traditional":"往來"},{"id":"网民","hanzi":"网民","pinyin":"wǎngmín","meaning_vi":"cư dân mạng (netizen)","explanation":"网 (mạng) + 民 (người dân).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","con-nguoi"],"image":"💻","examples":[{"type":"basic","zh":"网民纷纷留言点赞。","pinyin":"Wǎngmín fēnfēn liúyán diǎnzàn.","vi":"Cư dân mạng đua nhau để lại bình luận và thả like."},{"type":"simple","zh":"这段救人视频感动了无数网民。","pinyin":"Zhè duàn jiùrén shìpín gǎndòngle wúshù wǎngmín.","vi":"Đoạn video cứu người này đã làm xúc động vô số cư dân mạng."},{"type":"compound","zh":"消息一发布，网民们就在评论区吵了起来。","pinyin":"Xiāoxi yì fābù, wǎngmínmen jiù zài pínglùnqū chǎole qǐlái.","vi":"Tin vừa được đăng, cư dân mạng đã cãi nhau ầm ĩ trong phần bình luận."}],"related":[{"hanzi":"网友","pinyin":"wǎngyǒu","vi":"bạn mạng"},{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"},{"hanzi":"社交媒体","pinyin":"shèjiāoméitǐ","vi":"mạng xã hội"}],"traditional":"網民"},{"id":"往年","hanzi":"往年","pinyin":"wǎngnián","meaning_vi":"những năm trước","explanation":"往 (quá khứ/hướng tới) + 年 (năm).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"今年比往年冷。","pinyin":"Jīnnián bǐ wǎngnián lěng.","vi":"Năm nay lạnh hơn những năm trước."},{"type":"simple","zh":"往年这个时候，果园里早就挂满了苹果。","pinyin":"Wǎngnián zhè ge shíhou, guǒyuán lǐ zǎojiù guà mǎnle píngguǒ.","vi":"Những năm trước vào thời điểm này, vườn cây đã treo đầy táo từ lâu."},{"type":"compound","zh":"往年春节我们都回老家，可是今年因为工作忙只能留在上海。","pinyin":"Wǎngnián Chūnjié wǒmen dōu huílǎojiā, kěshì jīnnián yīnwèi gōngzuò máng zhǐnéng liú zài Shànghǎi.","vi":"Những năm trước Tết chúng tôi đều về quê, nhưng năm nay vì bận việc nên chỉ có thể ở lại Thượng Hải."}],"related":[{"hanzi":"去年","pinyin":"qùnián","vi":"năm ngoái"},{"hanzi":"今年","pinyin":"jīnnián","vi":"năm nay"},{"hanzi":"历年","pinyin":"lìnián","vi":"các năm qua"},{"hanzi":"同期","pinyin":"tóngqī","vi":"cùng kỳ"}]},{"id":"网速","hanzi":"网速","pinyin":"wǎngsù","meaning_vi":"tốc độ mạng Internet","explanation":"网 (mạng lưới) + 速 (nhanh chóng/tốc độ).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📶","examples":[{"type":"basic","zh":"这里网速太慢了。","pinyin":"Zhèlǐ wǎngsù tài màn le.","vi":"Tốc độ mạng ở đây chậm quá."},{"type":"simple","zh":"换了新路由器以后，家里的网速快多了。","pinyin":"Huànle xīn lùyóuqì yǐhòu, jiālǐ de wǎngsù kuài duō le.","vi":"Sau khi thay bộ định tuyến mới, tốc độ mạng ở nhà nhanh hơn nhiều."},{"type":"compound","zh":"只要网速稳定，我们就可以在家开视频会议。","pinyin":"Zhǐyào wǎngsù wěndìng, wǒmen jiù kěyǐ zài jiā kāi shìpínhuìyì.","vi":"Chỉ cần tốc độ mạng ổn định, chúng ta có thể họp video ở nhà."}],"related":[{"hanzi":"网络","pinyin":"wǎngluò","vi":"mạng"},{"hanzi":"宽带","pinyin":"kuāndài","vi":"băng thông rộng"},{"hanzi":"信号","pinyin":"xìnhào","vi":"tín hiệu"},{"hanzi":"卡顿","pinyin":"kǎdùn","vi":"giật lag"}],"traditional":"網速"},{"id":"五花八门","hanzi":"五花八门","pinyin":"wǔhuā-bāmén","meaning_vi":"muôn hình vạn trạng, đủ mọi chủng loại","explanation":"五 (ngũ sắc/năm) + 花 (tiêu (tiền/thời gian)) + 八 (số 8) + 门 (门).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🎪","examples":[{"type":"basic","zh":"商品五花八门。","pinyin":"Shāngpǐn wǔhuābāmén.","vi":"Hàng hóa đủ loại muôn hình vạn trạng."},{"type":"simple","zh":"夜市上卖的小吃真是五花八门。","pinyin":"Yèshì shang mài de xiǎochī zhēn shì wǔhuābāmén.","vi":"Đồ ăn vặt bán ở chợ đêm thật đủ mọi chủng loại."},{"type":"compound","zh":"网上的减肥方法虽然五花八门，但是真正有效的并不多。","pinyin":"Wǎngshàng de jiǎnféi fāngfǎ suīrán wǔhuābāmén, dànshì zhēnzhèng yǒuxiào de bìngbù duō.","vi":"Các phương pháp giảm cân trên mạng tuy muôn hình vạn trạng, nhưng thực sự hiệu quả thì chẳng nhiều."}],"related":[{"hanzi":"各式各样","pinyin":"gèshìgèyàng","vi":"đủ loại"},{"hanzi":"形形色色","pinyin":"xíngxíngsèsè","vi":"muôn hình muôn vẻ"},{"hanzi":"千奇百怪","pinyin":"qiānqíbǎiguài","vi":"kỳ lạ đủ kiểu"},{"hanzi":"单一","pinyin":"dānyī","vi":"đơn nhất"}],"traditional":"五花八門"},{"id":"舞龙舞狮","hanzi":"舞龙舞狮","pinyin":"wǔlóngwǔshī","meaning_vi":"múa lân múa rồng","explanation":"舞 (vũ – múa) + 龙 (long – rồng) + 舞 + 狮 (sư – sư tử) → múa rồng và múa lân (sư tử), hoạt động truyền thống dịp Tết, lễ hội.","hsk_level":"7-9","tags":["dong-tu","van-hoa","giai-tri"],"image":"🦁","examples":[{"type":"basic","zh":"街上在舞龙舞狮。","pinyin":"Jiēshang zài wǔlóngwǔshī.","vi":"Trên phố đang múa lân múa rồng."},{"type":"simple","zh":"春节庙会上的舞龙舞狮吸引了很多游客。","pinyin":"Chūnjié miàohuì shang de wǔlóngwǔshī xīyǐnle hěn duō yóukè.","vi":"Màn múa lân múa rồng ở hội chùa dịp Tết thu hút rất nhiều du khách."},{"type":"compound","zh":"锣鼓一响，舞龙舞狮的队伍就从巷子里走了出来。","pinyin":"Luógǔ yì xiǎng, wǔlóngwǔshī de duìwu jiù cóng xiàngzi lǐ zǒule chūlái.","vi":"Tiếng chiêng trống vừa vang lên, đoàn múa lân múa rồng đã từ trong ngõ đi ra."}],"related":[{"hanzi":"舞狮","pinyin":"wǔshī","vi":"múa lân"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"},{"hanzi":"元宵节","pinyin":"Yuánxiāojié","vi":"Tết Nguyên Tiêu"},{"hanzi":"锣鼓","pinyin":"luógǔ","vi":"chiêng trống"}],"traditional":"舞龍舞獅"},{"id":"舞台剧","hanzi":"舞台剧","pinyin":"wǔtáijù","meaning_vi":"kịch sân khấu","explanation":"舞 (múa/cổ vũ) + 台 (chiếc) + 剧 (kịch/dữ dội).","hsk_level":"7-9","tags":["danh-tu","giai-tri","van-hoa"],"image":"🎭","examples":[{"type":"basic","zh":"我们去看舞台剧吧。","pinyin":"Wǒmen qù kàn wǔtáijù ba.","vi":"Chúng ta đi xem kịch sân khấu nhé."},{"type":"simple","zh":"这部小说被改编成了一部舞台剧。","pinyin":"Zhè bù xiǎoshuō bèi gǎibiān chéngle yí bù wǔtáijù.","vi":"Cuốn tiểu thuyết này đã được chuyển thể thành một vở kịch sân khấu."},{"type":"compound","zh":"与其在家看电视剧，不如去剧院看一场舞台剧。","pinyin":"Yǔqí zài jiā kàn diànshìjù, bùrú qù jùyuàn kàn yì chǎng wǔtáijù.","vi":"Thay vì ở nhà xem phim truyền hình, chi bằng đến nhà hát xem một vở kịch sân khấu."}],"related":[{"hanzi":"话剧","pinyin":"huàjù","vi":"kịch nói"},{"hanzi":"舞台","pinyin":"wǔtái","vi":"sân khấu"},{"hanzi":"演员","pinyin":"yǎnyuán","vi":"diễn viên"},{"hanzi":"音乐剧","pinyin":"yīnyuèjù","vi":"nhạc kịch"}],"traditional":"舞台劇"},{"id":"武侠小说","hanzi":"武侠小说","pinyin":"wǔxiáxiǎoshuō","meaning_vi":"tiểu thuyết kiếm hiệp","explanation":"武侠 (võ hiệp – hiệp khách giỏi võ) + 小说 (tiểu thuyết) → tiểu thuyết kiếm hiệp. Tác giả tiêu biểu: Kim Dung, Cổ Long.","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"⚔️","examples":[{"type":"basic","zh":"他爱看武侠小说。","pinyin":"Tā ài kàn wǔxiáxiǎoshuō.","vi":"Anh ấy thích đọc tiểu thuyết kiếm hiệp."},{"type":"simple","zh":"金庸的武侠小说影响了好几代读者。","pinyin":"Jīnyōng de wǔxiáxiǎoshuō yǐngxiǎngle hǎojǐ dài dúzhě.","vi":"Tiểu thuyết kiếm hiệp của Kim Dung đã ảnh hưởng đến nhiều thế hệ độc giả."},{"type":"compound","zh":"小时候我一拿起武侠小说，就舍不得放下。","pinyin":"Xiǎoshíhou wǒ yì náqǐ wǔxiáxiǎoshuō, jiù shěbude fàngxià.","vi":"Hồi nhỏ, hễ cầm cuốn tiểu thuyết kiếm hiệp lên là tôi không nỡ đặt xuống."}],"related":[{"hanzi":"金庸","pinyin":"Jīnyōng","vi":"Kim Dung"},{"hanzi":"武侠","pinyin":"wǔxiá","vi":"võ hiệp"},{"hanzi":"江湖","pinyin":"jiānghú","vi":"giang hồ"},{"hanzi":"言情小说","pinyin":"yánqíngxiǎoshuō","vi":"tiểu thuyết ngôn tình"}],"traditional":"武俠小說"},{"id":"系统化","hanzi":"系统化","pinyin":"xìtǒnghuà","meaning_vi":"hệ thống hóa","explanation":"系 (khoa (trong trường đại học)) + 统 (thống nhất/hệ thống) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"🗂️","examples":[{"type":"basic","zh":"知识需要系统化。","pinyin":"Zhīshi xūyào xìtǒnghuà.","vi":"Kiến thức cần được hệ thống hóa."},{"type":"simple","zh":"她把零散的笔记系统化地整理成了一本书。","pinyin":"Tā bǎ língsǎn de bǐjì xìtǒnghuà de zhěnglǐ chéngle yì běn shū.","vi":"Cô ấy đã hệ thống hóa những ghi chép rời rạc thành một cuốn sách."},{"type":"compound","zh":"只有把管理流程系统化，公司才能快速扩张。","pinyin":"Zhǐyǒu bǎ guǎnlǐ liúchéng xìtǒnghuà, gōngsī cáinéng kuàisù kuòzhāng.","vi":"Chỉ khi hệ thống hóa quy trình quản lý, công ty mới có thể mở rộng nhanh chóng."}],"related":[{"hanzi":"系统","pinyin":"xìtǒng","vi":"hệ thống"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"quy chuẩn hóa"},{"hanzi":"条理","pinyin":"tiáolǐ","vi":"mạch lạc"},{"hanzi":"碎片化","pinyin":"suìpiànhuà","vi":"phân mảnh"}],"traditional":"系統化"},{"id":"下旬","hanzi":"下旬","pinyin":"xiàxún","meaning_vi":"hạ tuần (10 ngày cuối tháng)","explanation":"下 (dưới) + 旬 (tuần (10 ngày)/tuổi).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"考试在本月下旬。","pinyin":"Kǎoshì zài běnyuè xiàxún.","vi":"Kỳ thi diễn ra vào hạ tuần tháng này."},{"type":"simple","zh":"新校区预计九月下旬正式投入使用。","pinyin":"Xīn xiàoqū yùjì Jiǔyuè xiàxún zhèngshì tóurù shǐyòng.","vi":"Cơ sở mới dự kiến chính thức đưa vào sử dụng vào hạ tuần tháng Chín."},{"type":"compound","zh":"如果十月下旬还不降温，今年的枫叶就会红得比较晚。","pinyin":"Rúguǒ Shíyuè xiàxún hái bú jiàngwēn, jīnnián de fēngyè jiù huì hóng de bǐjiào wǎn.","vi":"Nếu đến hạ tuần tháng Mười trời vẫn chưa trở lạnh, lá phong năm nay sẽ đỏ muộn hơn."}],"related":[{"hanzi":"上旬","pinyin":"shàngxún","vi":"thượng tuần"},{"hanzi":"中旬","pinyin":"zhōngxún","vi":"trung tuần"},{"hanzi":"月底","pinyin":"yuèdǐ","vi":"cuối tháng"},{"hanzi":"月初","pinyin":"yuèchū","vi":"đầu tháng"}]},{"id":"下意识","hanzi":"下意识","pinyin":"xiàyìshí","meaning_vi":"vô thức, phản xạ tự nhiên","explanation":"下 (dưới) + 意 (ý thức/ý nghĩa) + 识 (kiến thức/nhận biết).","hsk_level":"7-9","tags":["pho-tu","nhan-thuc"],"image":"⚡","examples":[{"type":"basic","zh":"我下意识地后退。","pinyin":"Wǒ xiàyìshí de hòutuì.","vi":"Tôi theo phản xạ lùi lại."},{"type":"simple","zh":"听到自己的名字，他下意识地抬起了头。","pinyin":"Tīngdào zìjǐ de míngzi, tā xiàyìshí de táiqǐle tóu.","vi":"Nghe thấy tên mình, anh ấy bất giác ngẩng đầu lên."},{"type":"compound","zh":"每次一紧张，她就会下意识地咬指甲。","pinyin":"Měi cì yì jǐnzhāng, tā jiù huì xiàyìshí de yǎo zhǐjia.","vi":"Mỗi lần căng thẳng là cô ấy lại vô thức cắn móng tay."}],"related":[{"hanzi":"潜意识","pinyin":"qiányìshí","vi":"tiềm thức"},{"hanzi":"本能","pinyin":"běnnéng","vi":"bản năng"},{"hanzi":"不由自主","pinyin":"bùyóuzìzhǔ","vi":"không tự chủ được"},{"hanzi":"有意识","pinyin":"yǒuyìshí","vi":"có ý thức"}],"traditional":"下意識"},{"id":"下游","hanzi":"下游","pinyin":"xiàyóu","meaning_vi":"hạ lưu, khâu cuối chuỗi cung ứng","explanation":"下 (dưới) + 游 (du ngoạn/dòng chảy).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","cong-viec"],"image":"🌊","examples":[{"type":"basic","zh":"长江下游很富庶。","pinyin":"Chángjiāng xiàyóu hěn fùshù.","vi":"Vùng hạ lưu sông Trường Giang rất trù phú."},{"type":"simple","zh":"工厂的污水流到了下游的稻田里。","pinyin":"Gōngchǎng de wū shuǐliú dàole xiàyóu de dàotián lǐ.","vi":"Nước thải của nhà máy đã chảy xuống ruộng lúa ở hạ lưu."},{"type":"compound","zh":"一旦芯片供应短缺，下游的手机厂商就会被迫减产。","pinyin":"Yídàn xīnpiàn gōngyìng duǎnquē, xiàyóu de shǒujī chǎngshāng jiù huì bèipò jiǎnchǎn.","vi":"Một khi nguồn cung chip thiếu hụt, các hãng điện thoại ở khâu cuối chuỗi cung ứng sẽ buộc phải giảm sản lượng."}],"related":[{"hanzi":"上游","pinyin":"shàngyóu","vi":"thượng lưu"},{"hanzi":"中游","pinyin":"zhōngyóu","vi":"trung lưu"},{"hanzi":"产业链","pinyin":"chǎnyèliàn","vi":"chuỗi sản xuất"},{"hanzi":"河流","pinyin":"héliú","vi":"sông ngòi"}]},{"id":"现代化","hanzi":"现代化","pinyin":"xiàndàihuà","meaning_vi":"hiện đại hóa","explanation":"现 (hiện thực/hiện trường) + 代 (代) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏙️","examples":[{"type":"basic","zh":"这座城市很现代化。","pinyin":"Zhè zuò chéngshì hěn xiàndàihuà.","vi":"Thành phố này rất hiện đại."},{"type":"simple","zh":"村里的小学建起了现代化的多媒体教室。","pinyin":"Cūnlǐ de xiǎoxué jiàn qǐle xiàndàihuà de duōméitǐ jiàoshì.","vi":"Trường tiểu học trong làng đã xây phòng học đa phương tiện hiện đại."},{"type":"compound","zh":"农业不但要实现现代化，而且要保护好生态环境。","pinyin":"Nóngyè búdàn yào shíxiàn xiàndàihuà, érqiě yào bǎohù hǎo shēngtài huánjìng.","vi":"Nông nghiệp không chỉ phải hiện đại hóa mà còn phải bảo vệ tốt môi trường sinh thái."}],"related":[{"hanzi":"现代","pinyin":"xiàndài","vi":"hiện đại"},{"hanzi":"工业化","pinyin":"gōngyèhuà","vi":"công nghiệp hóa"},{"hanzi":"传统","pinyin":"chuántǒng","vi":"truyền thống"},{"hanzi":"城市化","pinyin":"chéngshìhuà","vi":"đô thị hóa"}],"traditional":"現代化"},{"id":"现金流","hanzi":"现金流","pinyin":"xiànjīnliú","meaning_vi":"dòng tiền (Cash flow)","explanation":"现金 (tiền mặt) + 流 (dòng chảy).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"💸","examples":[{"type":"basic","zh":"公司现金流紧张。","pinyin":"Gōngsī xiànjīnliú jǐnzhāng.","vi":"Dòng tiền của công ty đang eo hẹp."},{"type":"simple","zh":"这家小餐馆靠外卖订单维持现金流。","pinyin":"Zhè jiā xiǎo cānguǎn kào wàimài dìngdān wéichí xiànjīnliú.","vi":"Nhà hàng nhỏ này dựa vào đơn giao đồ ăn để duy trì dòng tiền."},{"type":"compound","zh":"即使账面上有利润，现金流断了企业也会倒闭。","pinyin":"Jíshǐ zhàngmiàn shang yǒu lìrùn, xiànjīnliú duànle qǐyè yě huì dǎobì.","vi":"Dù trên sổ sách có lãi, nếu dòng tiền bị đứt thì doanh nghiệp vẫn sẽ phá sản."}],"related":[{"hanzi":"现金","pinyin":"xiànjīn","vi":"tiền mặt"},{"hanzi":"资金","pinyin":"zījīn","vi":"vốn"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"财务报表","pinyin":"cáiwùbàobiǎo","vi":"báo cáo tài chính"}],"traditional":"現金流"},{"id":"相声","hanzi":"相声","pinyin":"xiàngsheng","meaning_vi":"tấu hài đối đáp (nghệ thuật ngôn ngữ truyền thống TQ)","explanation":"相 + 声 (âm thanh).","hsk_level":"7-9","tags":["danh-tu","van-hoa","giai-tri"],"image":"🎤","examples":[{"type":"basic","zh":"爷爷爱听相声。","pinyin":"Yéye ài tīng xiàngsheng.","vi":"Ông nội thích nghe tấu hài đối đáp."},{"type":"simple","zh":"两位演员在茶馆里说了一段传统相声。","pinyin":"Liǎng wèi yǎnyuán zài cháguǎn lǐ shuōle yí duàn chuántǒng xiàngsheng.","vi":"Hai diễn viên đã diễn một tiết mục tấu hài truyền thống trong quán trà."},{"type":"compound","zh":"我虽然听不懂所有的笑点，但是还是觉得这段相声很有意思。","pinyin":"Wǒ suīrán tīngbùdǒng suǒyǒu de xiàodiǎn, dànshì háishì juéde zhè duàn xiàngsheng hěn yǒuyìsi.","vi":"Tuy không hiểu hết các điểm gây cười, tôi vẫn thấy tiết mục tấu hài này rất thú vị."}],"related":[{"hanzi":"小品","pinyin":"xiǎopǐn","vi":"tiểu phẩm"},{"hanzi":"曲艺","pinyin":"qǔyì","vi":"nghệ thuật khúc nghệ"},{"hanzi":"脱口秀","pinyin":"tuōkǒuxiù","vi":"talk show"},{"hanzi":"幽默","pinyin":"yōumò","vi":"hài hước"}],"traditional":"相聲"},{"id":"像素","hanzi":"像素","pinyin":"xiàngsù","meaning_vi":"điểm ảnh (pixel)","explanation":"像 (hình ảnh) + 素 (yếu tố).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📷","examples":[{"type":"basic","zh":"这张照片像素很低。","pinyin":"Zhè zhāng zhàopiàn xiàngsù hěn dī.","vi":"Bức ảnh này có độ phân giải rất thấp."},{"type":"simple","zh":"新手机的摄像头有五千万像素。","pinyin":"Xīnshǒu jī de shèxiàngtóu yǒu wǔ qiānwàn xiàngsù.","vi":"Camera của chiếc điện thoại mới có năm mươi triệu điểm ảnh."},{"type":"compound","zh":"因为图片像素太低，所以打印出来以后全是马赛克。","pinyin":"Yīnwèi túpiàn xiàngsù tài dī, suǒyǐ dǎyìn chūlái yǐhòu quán shì mǎsàikè.","vi":"Vì ảnh có số điểm ảnh quá thấp nên sau khi in ra toàn bị vỡ hạt."}],"related":[{"hanzi":"分辨率","pinyin":"fēnbiànlǜ","vi":"độ phân giải"},{"hanzi":"摄像头","pinyin":"shèxiàngtóu","vi":"camera"},{"hanzi":"清晰度","pinyin":"qīngxīdù","vi":"độ nét"},{"hanzi":"图像","pinyin":"túxiàng","vi":"hình ảnh"}]},{"id":"象形字","hanzi":"象形字","pinyin":"xiàngxíngzì","meaning_vi":"chữ tượng hình","explanation":"象 (hiện tượng/tượng trưng) + 形 (hình thái/hình thành) + 字 (chữ).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","van-hoa"],"image":"🈷️","examples":[{"type":"basic","zh":"山字是象形字。","pinyin":"Shān zì shì xiàngxíngzì.","vi":"Chữ 'sơn' (núi) là chữ tượng hình."},{"type":"simple","zh":"老师在黑板上画出了几个象形字的演变过程。","pinyin":"Lǎoshī zài hēibǎn shang huà chūle jǐ gè xiàngxíngzì de yǎnbiàn guòchéng.","vi":"Cô giáo vẽ lên bảng quá trình diễn biến của mấy chữ tượng hình."},{"type":"compound","zh":"只要了解象形字的来源，记汉字就容易多了。","pinyin":"Zhǐyào liǎojiě xiàngxíngzì de láiyuán, jì hànzì jiù róngyì duō le.","vi":"Chỉ cần hiểu nguồn gốc của chữ tượng hình, việc nhớ chữ Hán sẽ dễ hơn nhiều."}],"related":[{"hanzi":"象形文字","pinyin":"xiàngxíngwénzì","vi":"văn tự tượng hình"},{"hanzi":"甲骨文","pinyin":"jiǎgǔwén","vi":"giáp cốt văn"},{"hanzi":"形声字","pinyin":"xíngshēngzì","vi":"chữ hình thanh"},{"hanzi":"会意字","pinyin":"huìyìzì","vi":"chữ hội ý"}]},{"id":"向心力","hanzi":"向心力","pinyin":"xiàngxīnlì","meaning_vi":"lực hướng tâm, sự đoàn kết quy tụ","explanation":"向 (hướng về) + 心 (tâm lý/tâm huyết) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","xa-hoi"],"image":"🎯","examples":[{"type":"basic","zh":"团队需要向心力。","pinyin":"Tuánduì xūyào xiàngxīnlì.","vi":"Đội nhóm cần có sức gắn kết."},{"type":"simple","zh":"物理老师用转动的水桶解释向心力。","pinyin":"Wùlǐ lǎoshī yòng zhuàndòng de shuǐtǒng jiěshì xiàngxīnlì.","vi":"Thầy vật lý dùng xô nước quay tròn để giải thích lực hướng tâm."},{"type":"compound","zh":"只要领导以身作则，团队就会有很强的向心力。","pinyin":"Zhǐyào lǐngdǎo yǐshēnzuòzé, tuánduì jiù huì yǒu hěn qiáng de xiàngxīnlì.","vi":"Chỉ cần lãnh đạo làm gương, đội nhóm sẽ có sức gắn kết rất mạnh."}],"related":[{"hanzi":"凝聚力","pinyin":"níngjùlì","vi":"sức gắn kết"},{"hanzi":"离心力","pinyin":"líxīnlì","vi":"lực ly tâm"},{"hanzi":"团结","pinyin":"tuánjié","vi":"đoàn kết"},{"hanzi":"号召力","pinyin":"hàozhàolì","vi":"sức hiệu triệu"}]},{"id":"协同合作","hanzi":"协同合作","pinyin":"xiétónghézuò","meaning_vi":"hợp tác hiệp đồng","explanation":"协 (hiệp thương/hỗ trợ) + 同 (đồng lòng/đồng bào) + 合 (合) + 作 (tác phẩm/tác phong).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔗","examples":[{"type":"basic","zh":"各部门协同合作。","pinyin":"Gè bùmén xiétónghézuò.","vi":"Các phòng ban hợp tác hiệp đồng."},{"type":"simple","zh":"医生和护士协同合作完成了这台手术。","pinyin":"Yīshēng hé hùshi xiétónghézuò wánchéngle zhè tái shǒushù.","vi":"Bác sĩ và y tá phối hợp nhịp nhàng để hoàn thành ca phẫu thuật này."},{"type":"compound","zh":"如果设计和开发不能协同合作，产品就很难按时上线。","pinyin":"Rúguǒ shèjì hé kāifā bù néng xiétónghézuò, chǎnpǐn jiù hěn nán ànshí shàngxiàn.","vi":"Nếu bộ phận thiết kế và phát triển không thể phối hợp với nhau, sản phẩm sẽ khó ra mắt đúng hạn."}],"related":[{"hanzi":"协作","pinyin":"xiézuò","vi":"hiệp tác"},{"hanzi":"团队合作","pinyin":"tuánduìhézuò","vi":"làm việc nhóm"},{"hanzi":"配合","pinyin":"pèihé","vi":"phối hợp"},{"hanzi":"各自为政","pinyin":"gèzìwéizhèng","vi":"ai lo phần nấy"}],"traditional":"協同合作"},{"id":"乡村振兴","hanzi":"乡村振兴","pinyin":"xiāngcūnzhènxīng","meaning_vi":"chấn hưng nông thôn","explanation":"乡 (quê hương) + 村 (村) + 振 (phấn chấn/chấn hưng) + 兴 (hưng thịnh/hứng thú).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-diem"],"image":"🌾","examples":[{"type":"basic","zh":"乡村振兴需要人才。","pinyin":"Xiāngcūnzhènxīng xūyào réncái.","vi":"Chấn hưng nông thôn cần có nhân tài."},{"type":"simple","zh":"大学毕业后，他回到老家投身乡村振兴。","pinyin":"Dàxué bìyè hòu, tā huídào lǎojiā tóushēn xiāngcūnzhènxīng.","vi":"Sau khi tốt nghiệp đại học, anh ấy trở về quê dấn thân vào công cuộc chấn hưng nông thôn."},{"type":"compound","zh":"既然有了电商平台，乡村振兴就多了一条新路子。","pinyin":"Jìrán yǒule diànshāngpíngtái, xiāngcūnzhènxīng jiù duōle yì tiáo xīn lùzi.","vi":"Khi đã có nền tảng thương mại điện tử, công cuộc chấn hưng nông thôn có thêm một con đường mới."}],"related":[{"hanzi":"农村","pinyin":"nóngcūn","vi":"nông thôn"},{"hanzi":"脱贫攻坚","pinyin":"tuōpíngōngjiān","vi":"xóa đói giảm nghèo"},{"hanzi":"三农","pinyin":"sānnóng","vi":"tam nông"},{"hanzi":"城镇化","pinyin":"chéngzhènhuà","vi":"đô thị hóa"}],"traditional":"鄉村振興"},{"id":"消费升级","hanzi":"消费升级","pinyin":"xiāofèishēngjí","meaning_vi":"nâng cấp tiêu dùng","explanation":"消费 (tiêu phí – tiêu dùng) + 升级 (thăng cấp – nâng cấp) → xu hướng người tiêu dùng chuyển sang hàng hóa, dịch vụ chất lượng cao hơn. Trái: 消费降级.","hsk_level":"7-9","tags":["danh-tu","mua-sam","xa-hoi"],"image":"🛍️","examples":[{"type":"basic","zh":"消费升级正在加速。","pinyin":"Xiāofèishēngjí zhèngzài jiāsù.","vi":"Nâng cấp tiêu dùng đang tăng tốc."},{"type":"simple","zh":"随着消费升级，越来越多的人愿意为健康食品买单。","pinyin":"Suízhe xiāofèishēngjí, yuèláiyuè duō de rén yuànyì wèi jiànkāng shípǐn mǎidān.","vi":"Cùng với việc nâng cấp tiêu dùng, ngày càng nhiều người sẵn lòng chi tiền cho thực phẩm lành mạnh."},{"type":"compound","zh":"因为出现了消费升级，所以国产品牌也开始走高端路线。","pinyin":"Yīnwèi chūxiànle xiāofèishēngjí, suǒyǐ guóchǎn pǐnpái yě kāishǐ zǒu gāoduān lùxiàn.","vi":"Vì xu hướng nâng cấp tiêu dùng xuất hiện nên các thương hiệu nội địa cũng bắt đầu đi theo dòng cao cấp."}],"related":[{"hanzi":"消费","pinyin":"xiāofèi","vi":"tiêu dùng"},{"hanzi":"消费者","pinyin":"xiāofèizhě","vi":"người tiêu dùng"},{"hanzi":"品质","pinyin":"pǐnzhì","vi":"chất lượng"},{"hanzi":"降级","pinyin":"jiàngjí","vi":"hạ cấp"}],"traditional":"消費升級"},{"id":"潇洒","hanzi":"潇洒","pinyin":"xiāosǎ","meaning_vi":"phong độ, phóng khoáng; ung dung, thảnh thơi","explanation":"潇 (tiêu – thanh thoát) + 洒 (sái – phóng khoáng) → phong thái tự nhiên, phóng khoáng, không gò bó; khen người có phong độ. Ví dụ: 潇洒的样子, 活得潇洒.","hsk_level":"7-9","tags":["tinh-tu"],"image":"😎","examples":[{"type":"basic","zh":"他穿风衣很潇洒。","pinyin":"Tā chuān fēngyī hěn xiāosǎ.","vi":"Anh ấy mặc áo khoác gió trông rất phong độ."},{"type":"simple","zh":"退休后，张叔叔潇洒地去环游世界了。","pinyin":"Tuìxiū hòu, Zhāng shūshu xiāosǎ de qù huányóu shìjiè le.","vi":"Sau khi nghỉ hưu, chú Trương thảnh thơi đi du lịch vòng quanh thế giới."},{"type":"compound","zh":"她虽然输了比赛，但是潇洒地向对手挥手祝贺。","pinyin":"Tā suīrán shūle bǐsài, dànshì xiāosǎ de xiàng duìshǒu huīshǒu zhùhè.","vi":"Tuy thua trận, cô ấy vẫn ung dung vẫy tay chúc mừng đối thủ."}],"related":[{"hanzi":"洒脱","pinyin":"sǎtuō","vi":"phóng khoáng"},{"hanzi":"帅气","pinyin":"shuàiqi","vi":"đẹp trai phong độ"},{"hanzi":"风度翩翩","pinyin":"fēngdùpiānpiān","vi":"phong độ hào hoa"},{"hanzi":"拘谨","pinyin":"jūjǐn","vi":"gò bó"}],"traditional":"瀟灑"},{"id":"消炎药","hanzi":"消炎药","pinyin":"xiāoyányào","meaning_vi":"thuốc chống viêm","explanation":"消 (tiêu dùng/xóa bỏ) + 炎 (nóng bức/viêm) + 药 (thuốc).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"医生开了消炎药。","pinyin":"Yīshēng kāile xiāoyányào.","vi":"Bác sĩ đã kê thuốc chống viêm."},{"type":"simple","zh":"牙疼的时候，他吃了两片消炎药。","pinyin":"Yá téng de shíhou, tā chīle liǎng piàn xiāoyányào.","vi":"Khi bị đau răng, anh ấy đã uống hai viên thuốc chống viêm."},{"type":"compound","zh":"即使伤口好多了，你也要按时把消炎药吃完。","pinyin":"Jíshǐ shāngkǒu hǎoduō le, nǐ yě yào ànshí bǎ xiāoyányào chīwán.","vi":"Dù vết thương đã đỡ nhiều, bạn vẫn phải uống hết thuốc chống viêm đúng giờ."}],"related":[{"hanzi":"消炎","pinyin":"xiāoyán","vi":"chống viêm"},{"hanzi":"抗生素","pinyin":"kàngshēngsù","vi":"kháng sinh"},{"hanzi":"发炎","pinyin":"fāyán","vi":"viêm"},{"hanzi":"止痛药","pinyin":"zhǐtòngyào","vi":"thuốc giảm đau"}],"traditional":"消炎藥"},{"id":"修辞手法","hanzi":"修辞手法","pinyin":"xiūcíshǒufǎ","meaning_vi":"biện pháp tu từ","explanation":"修 (tu dưỡng/sửa chữa) + 辞 (辞) + 手 (thủ pháp/tay nghề) + 法 (法).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"✍️","examples":[{"type":"basic","zh":"这句用了修辞手法。","pinyin":"Zhè jù yòngle xiūcíshǒufǎ.","vi":"Câu này có dùng biện pháp tu từ."},{"type":"simple","zh":"语文老师让我们找出课文里的修辞手法。","pinyin":"Yǔwén lǎoshī ràng wǒmen zhǎochū kèwén lǐ de xiūcíshǒufǎ.","vi":"Cô giáo ngữ văn bảo chúng tôi tìm ra các biện pháp tu từ trong bài khóa."},{"type":"compound","zh":"如果恰当地运用修辞手法，文章就会更加生动。","pinyin":"Rúguǒ qià dàngde yùnyòng xiūcíshǒufǎ, wénzhāng jiù huì gèngjiā shēngdòng.","vi":"Nếu vận dụng biện pháp tu từ một cách thích hợp, bài văn sẽ sinh động hơn."}],"related":[{"hanzi":"比喻","pinyin":"bǐyù","vi":"so sánh ẩn dụ"},{"hanzi":"拟人","pinyin":"nǐrén","vi":"nhân hóa"},{"hanzi":"夸张","pinyin":"kuāzhāng","vi":"phóng đại"},{"hanzi":"排比","pinyin":"páibǐ","vi":"điệp cấu trúc"}],"traditional":"修辭手法"},{"id":"学费","hanzi":"学费","pinyin":"xuéfèi","meaning_vi":"học phí","explanation":"学 (học) + 费 (phí) → tiền học phải đóng cho trường. Thường đi với 交, 缴; cụm 交学费 còn có nghĩa bóng \"trả giá để lấy kinh nghiệm\".","hsk_level":"7-9","tags":["danh-tu","hoc-tap","tien-te"],"image":"🏫","examples":[{"type":"basic","zh":"学费又涨了。","pinyin":"Xuéfèi yòu zhǎng le.","vi":"Học phí lại tăng rồi."},{"type":"simple","zh":"她暑假打工攒够了下学期的学费。","pinyin":"Tā shǔjià dǎgōng zǎn gòule xià xuéqī de xuéfèi.","vi":"Cô ấy đi làm thêm kỳ nghỉ hè và đã dành dụm đủ học phí cho học kỳ sau."},{"type":"compound","zh":"因为家里付不起学费，所以他申请了助学贷款。","pinyin":"Yīnwèi jiālǐ fùbùqǐ xuéfèi, suǒyǐ tā shēnqǐngle zhùxué dàikuǎn.","vi":"Vì gia đình không đủ tiền đóng học phí nên cậu ấy đã xin vay vốn sinh viên."}],"related":[{"hanzi":"学杂费","pinyin":"xuézáfèi","vi":"học phí và phụ phí"},{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","vi":"học bổng"},{"hanzi":"助学金","pinyin":"zhùxuéjīn","vi":"trợ cấp học tập"},{"hanzi":"生活费","pinyin":"shēnghuófèi","vi":"sinh hoạt phí"}],"traditional":"學費"},{"id":"学术界","hanzi":"学术界","pinyin":"xuéshùjiè","meaning_vi":"giới học thuật","explanation":"学 (học thuật/học thuyết) + 术 (术) + 界 (ranh giới/giới hạn).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"学术界对此有争议。","pinyin":"Xuéshùjiè duì cǐ yǒuzhēngyì.","vi":"Giới học thuật có tranh luận về điều này."},{"type":"simple","zh":"这篇论文在学术界引起了不小的反响。","pinyin":"Zhè piān lùnwén zài xuéshùjiè yǐnqǐle bù xiǎo de fǎnxiǎng.","vi":"Bài luận văn này đã gây tiếng vang không nhỏ trong giới học thuật."},{"type":"compound","zh":"他虽然离开了学术界，但是依然关注最新的研究成果。","pinyin":"Tā suīrán líkāile xuéshùjiè, dànshì yīrán guānzhù zuì xīn de yánjiū chéngguǒ.","vi":"Tuy đã rời giới học thuật, ông ấy vẫn theo dõi những thành quả nghiên cứu mới nhất."}],"related":[{"hanzi":"学术","pinyin":"xuéshù","vi":"học thuật"},{"hanzi":"学者","pinyin":"xuézhě","vi":"học giả"},{"hanzi":"科研","pinyin":"kēyán","vi":"nghiên cứu khoa học"},{"hanzi":"论文","pinyin":"lùnwén","vi":"luận văn"}],"traditional":"學術界"},{"id":"穴位","hanzi":"穴位","pinyin":"xuéwèi","meaning_vi":"huyệt đạo, huyệt vị","explanation":"穴 + 位 (vị trí).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","co-the"],"image":"🩺","examples":[{"type":"basic","zh":"按这个穴位能止痛。","pinyin":"Àn zhè ge xuéwèi néng zhǐtòng.","vi":"Bấm huyệt này có thể giảm đau."},{"type":"simple","zh":"中医师在我手腕上找到了一个穴位。","pinyin":"Zhōngyī shī zài wǒ shǒuwàn shang zhǎodàole yí gè xuéwèi.","vi":"Thầy thuốc Đông y đã tìm thấy một huyệt đạo trên cổ tay tôi."},{"type":"compound","zh":"只要每天按摩足底的穴位，睡眠质量就会有所改善。","pinyin":"Zhǐyào měitiān ànmó zú dǐ de xuéwèi, shuìmián zhìliàng jiù huì yǒusuǒ gǎishàn.","vi":"Chỉ cần mỗi ngày xoa bóp các huyệt ở lòng bàn chân, chất lượng giấc ngủ sẽ được cải thiện phần nào."}],"related":[{"hanzi":"针灸","pinyin":"zhēnjiǔ","vi":"châm cứu"},{"hanzi":"推拿","pinyin":"tuīná","vi":"xoa bóp bấm huyệt"},{"hanzi":"经络","pinyin":"jīngluò","vi":"kinh lạc"},{"hanzi":"按摩","pinyin":"ànmó","vi":"xoa bóp"}]},{"id":"学以致用","hanzi":"学以致用","pinyin":"xuéyǐ-zhìyòng","meaning_vi":"học đi đôi với hành, vận dụng kiến thức đã học","explanation":"学 (học thuật/học thuyết) + 以 (lấy) + 致 (dẫn đến/tinh tế) + 用 (vận dụng/công dụng).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🛠️","examples":[{"type":"basic","zh":"读书要学以致用。","pinyin":"Dúshū yào xuéyǐzhìyòng.","vi":"Học phải đi đôi với hành."},{"type":"simple","zh":"实习让我们有机会学以致用。","pinyin":"Shíxí ràng wǒmen yǒujī huì xuéyǐzhìyòng.","vi":"Thực tập giúp chúng tôi có cơ hội vận dụng kiến thức đã học."},{"type":"compound","zh":"只有学以致用，书本上的知识才能真正变成自己的本领。","pinyin":"Zhǐyǒu xuéyǐzhìyòng, shūběn shang de zhīshi cáinéng zhēnzhèng biànchéng zìjǐ de běnlǐng.","vi":"Chỉ khi vận dụng điều đã học vào thực tế, kiến thức trong sách mới thực sự trở thành năng lực của mình."}],"related":[{"hanzi":"理论联系实际","pinyin":"lǐlùn liánxì shíjì","vi":"lý luận gắn thực tiễn"},{"hanzi":"实践","pinyin":"shíjiàn","vi":"thực tiễn"},{"hanzi":"活学活用","pinyin":"huóxuéhuóyòng","vi":"học linh hoạt dùng linh hoạt"},{"hanzi":"纸上谈兵","pinyin":"zhǐshàngtánbīng","vi":"bàn binh trên giấy"}],"traditional":"學以致用"},{"id":"宣纸","hanzi":"宣纸","pinyin":"xuānzhǐ","meaning_vi":"giấy Tuyên (giấy vẽ tranh thủy mặc và viết thư pháp)","explanation":"宣 (Tuyên – vùng Tuyên Châu, An Huy) + 纸 (chỉ – giấy) → giấy Tuyên, dùng viết thư pháp, vẽ tranh thủy mặc; một trong 文房四宝.","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"📜","examples":[{"type":"basic","zh":"他在宣纸上写字。","pinyin":"Tā zài xuānzhǐ shang xiězì.","vi":"Ông ấy viết chữ trên giấy Tuyên."},{"type":"simple","zh":"书法老师送给我一刀上好的宣纸。","pinyin":"Shūfǎ lǎoshī sònggěi wǒ yì dāo shànghǎo de xuānzhǐ.","vi":"Thầy thư pháp tặng tôi một xấp giấy Tuyên loại tốt."},{"type":"compound","zh":"宣纸一沾上水，墨迹就会慢慢晕开。","pinyin":"Xuānzhǐ yì zhān shàngshuǐ, mòjì jiù huì mànmàn yùn kāi.","vi":"Giấy Tuyên hễ dính nước là vết mực sẽ từ từ loang ra."}],"related":[{"hanzi":"文房四宝","pinyin":"wénfángsìbǎo","vi":"văn phòng tứ bảo"},{"hanzi":"毛笔","pinyin":"máobǐ","vi":"bút lông"},{"hanzi":"书法","pinyin":"shūfǎ","vi":"thư pháp"},{"hanzi":"砚台","pinyin":"yàntai","vi":"nghiên mực"}],"traditional":"宣紙"},{"id":"细化","hanzi":"细化","pinyin":"xìhuà","meaning_vi":"cụ thể hóa, chia nhỏ chi tiết","explanation":"细 (chi tiết/tỉ mỉ) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🔍","examples":[{"type":"basic","zh":"方案还要再细化。","pinyin":"Fāng'àn hái yào zài xìhuà.","vi":"Phương án vẫn cần cụ thể hóa thêm."},{"type":"simple","zh":"经理把年度目标细化到了每个月。","pinyin":"Jīnglǐ bǎ niándù mùbiāo xìhuà dàole měi gèyuè.","vi":"Giám đốc đã chia nhỏ mục tiêu năm ra cho từng tháng."},{"type":"compound","zh":"如果不把任务细化到每个人，项目进度就很难控制。","pinyin":"Rúguǒ bù bǎ rènwu xìhuà dào měigèrén, xiàngmù jìndù jiù hěn nán kòngzhì.","vi":"Nếu không chia nhỏ nhiệm vụ cho từng người, tiến độ dự án sẽ khó kiểm soát."}],"related":[{"hanzi":"具体化","pinyin":"jùtǐhuà","vi":"cụ thể hóa"},{"hanzi":"细节","pinyin":"xìjié","vi":"chi tiết"},{"hanzi":"量化","pinyin":"liànghuà","vi":"lượng hóa"},{"hanzi":"笼统","pinyin":"lǒngtǒng","vi":"chung chung"}],"traditional":"細化"},{"id":"信息化","hanzi":"信息化","pinyin":"xìnxīhuà","meaning_vi":"tin học hóa, số hóa thông tin","explanation":"信 (niềm tin/uy tín) + 息 (tin tức/nghỉ ngơi) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"💻","examples":[{"type":"basic","zh":"医院实现了信息化。","pinyin":"Yīyuàn shíxiànle xìnxīhuà.","vi":"Bệnh viện đã tin học hóa."},{"type":"simple","zh":"信息化管理让图书馆的借书速度快了很多。","pinyin":"Xìnxīhuà guǎnlǐ ràng túshūguǎn de jièshū sùdù kuàile hěn duō.","vi":"Quản lý bằng công nghệ thông tin giúp việc mượn sách ở thư viện nhanh hơn nhiều."},{"type":"compound","zh":"学校虽然推进了信息化，可是一些老教师还不太会用电脑。","pinyin":"Xuéxiào suīrán tuījìnle xìnxīhuà, kěshì yìxiē lǎo jiàoshī hái bú tài huì yòng diànnǎo.","vi":"Tuy trường học đã đẩy mạnh tin học hóa, nhưng một số giáo viên lớn tuổi vẫn chưa thạo dùng máy tính."}],"related":[{"hanzi":"数字化","pinyin":"shùzìhuà","vi":"số hóa"},{"hanzi":"信息技术","pinyin":"xìnxījìshù","vi":"công nghệ thông tin"},{"hanzi":"智能化","pinyin":"zhìnénghuà","vi":"thông minh hóa"},{"hanzi":"网络化","pinyin":"wǎngluòhuà","vi":"mạng hóa"}]},{"id":"幸福感","hanzi":"幸福感","pinyin":"xìngfúgǎn","meaning_vi":"cảm giác hạnh phúc","explanation":"幸 (may mắn/hạnh phúc) + 福 (福) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🥰","examples":[{"type":"basic","zh":"她的幸福感很强。","pinyin":"Tā de xìngfúgǎn hěn qiáng.","vi":"Cảm giác hạnh phúc của cô ấy rất rõ rệt."},{"type":"simple","zh":"周末和家人一起做饭给我带来满满的幸福感。","pinyin":"Zhōumò hé jiārén yìqǐ zuòfàn gěi wǒ dàilái mǎnmǎn de xìngfúgǎn.","vi":"Cuối tuần nấu ăn cùng gia đình mang lại cho tôi cảm giác hạnh phúc tràn đầy."},{"type":"compound","zh":"收入虽然不算高，但是小城生活的幸福感一点也不低。","pinyin":"Shōurù suīrán búsuàn gāo, dànshì xiǎochéng shēnghuó de xìngfúgǎn yìdiǎn yě bù dī.","vi":"Thu nhập tuy không cao, nhưng cảm giác hạnh phúc khi sống ở thành phố nhỏ chẳng thấp chút nào."}],"related":[{"hanzi":"幸福","pinyin":"xìngfú","vi":"hạnh phúc"},{"hanzi":"满足感","pinyin":"mǎnzúgǎn","vi":"cảm giác thỏa mãn"},{"hanzi":"获得感","pinyin":"huòdégǎn","vi":"cảm giác được hưởng"},{"hanzi":"安全感","pinyin":"ānquángǎn","vi":"cảm giác an toàn"}]},{"id":"性价比","hanzi":"性价比","pinyin":"xìngjiàbǐ","meaning_vi":"tỷ lệ hiệu năng trên giá thành (đáng đồng tiền)","explanation":"性 (tính – tính năng) + 价 (giá – giá cả) + 比 (tỷ – tỷ lệ) → tỷ lệ giữa chất lượng và giá tiền. Cụm: 性价比高 (đáng tiền, rẻ mà tốt).","hsk_level":"7-9","tags":["danh-tu","mua-sam"],"image":"💰","examples":[{"type":"basic","zh":"这款耳机性价比高。","pinyin":"Zhè kuǎn ěrjī xìngjiàbǐ gāo.","vi":"Chiếc tai nghe này rất đáng đồng tiền."},{"type":"simple","zh":"学生买电脑时最看重的就是性价比。","pinyin":"Xuéshēng mǎi diànnǎo shí zuì kànzhòng de jiùshì xìngjiàbǐ.","vi":"Khi mua máy tính, điều sinh viên coi trọng nhất chính là hiệu năng so với giá."},{"type":"compound","zh":"与其买昂贵的名牌，不如选一款性价比高的国产手机。","pinyin":"Yǔqí mǎi ángguì de míngpái, bùrú xuǎn yì kuǎn xìngjiàbǐ gāo de guóchǎn shǒujī.","vi":"Thay vì mua hàng hiệu đắt tiền, chi bằng chọn một chiếc điện thoại nội địa đáng đồng tiền."}],"related":[{"hanzi":"划算","pinyin":"huásuàn","vi":"đáng tiền"},{"hanzi":"物美价廉","pinyin":"wùměijiàlián","vi":"hàng tốt giá rẻ"},{"hanzi":"价格","pinyin":"jiàgé","vi":"giá cả"},{"hanzi":"实惠","pinyin":"shíhuì","vi":"thực tế có lợi"}],"traditional":"性價比"},{"id":"形近字","hanzi":"形近字","pinyin":"xíngjìnzì","meaning_vi":"chữ có hình dạng gần giống nhau","explanation":"形 (hình thái/hình thành) + 近 (gần) + 字 (chữ).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"🈷️","examples":[{"type":"basic","zh":"己和已是形近字。","pinyin":"Jǐ hé yǐ shì xíngjìnzì.","vi":"Chữ 己 (mình) và chữ 已 (đã) là chữ có hình dạng gần giống nhau."},{"type":"simple","zh":"小学生常常把形近字写混。","pinyin":"Xiǎoxuéshēng chángcháng bǎ xíngjìnzì xiě hùn.","vi":"Học sinh tiểu học thường viết lẫn lộn các chữ có hình dạng gần giống nhau."},{"type":"compound","zh":"只要仔细比较形近字的笔画，就不容易写错了。","pinyin":"Zhǐyào zǐxì bǐjiào xíngjìnzì de bǐhuà, jiù bù róngyì xiě cuò le.","vi":"Chỉ cần so sánh kỹ nét bút của các chữ gần giống nhau thì sẽ khó viết sai."}],"related":[{"hanzi":"同音字","pinyin":"tóngyīnzì","vi":"chữ đồng âm"},{"hanzi":"错别字","pinyin":"cuòbiézì","vi":"chữ viết sai"},{"hanzi":"偏旁","pinyin":"piānpáng","vi":"bộ thủ"},{"hanzi":"汉字","pinyin":"hànzì","vi":"chữ Hán"}]},{"id":"循环经济","hanzi":"循环经济","pinyin":"xúnhuánjīngjì","meaning_vi":"kinh tế tuần hoàn","explanation":"循环 (tuần hoàn) + 经济.","hsk_level":"7-9","tags":["danh-tu","thien-nhien","cong-viec"],"image":"🔄","examples":[{"type":"basic","zh":"我们要发展循环经济。","pinyin":"Wǒmen yào fāzhǎn xúnhuánjīngjì.","vi":"Chúng ta phải phát triển kinh tế tuần hoàn."},{"type":"simple","zh":"这座工业园区把循环经济做得有声有色。","pinyin":"Zhè zuò gōngyèyuánqū bǎ xúnhuánjīngjì zuò de yǒushēngyǒusè.","vi":"Khu công nghiệp này làm kinh tế tuần hoàn rất bài bản và hiệu quả."},{"type":"compound","zh":"发展循环经济既能减少垃圾，又能为企业节省成本。","pinyin":"Fāzhǎn xúnhuánjīngjì jì néng jiǎnshǎo lājī, yòu néng wèi qǐyè jiéshěng chéngběn.","vi":"Phát triển kinh tế tuần hoàn vừa giảm được rác thải, vừa giúp doanh nghiệp tiết kiệm chi phí."}],"related":[{"hanzi":"循环利用","pinyin":"xúnhuánlìyòng","vi":"tái sử dụng"},{"hanzi":"回收","pinyin":"huíshōu","vi":"thu hồi tái chế"},{"hanzi":"可持续发展","pinyin":"kěchíxù fāzhǎn","vi":"phát triển bền vững"},{"hanzi":"低碳经济","pinyin":"dītànjīngjì","vi":"kinh tế ít cacbon"}],"traditional":"循環經濟"},{"id":"西半球","hanzi":"西半球","pinyin":"Xībànqiú","meaning_vi":"bán cầu Tây","explanation":"西 (hướng Tây) + 半 (một nửa) + 球 (球).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"美洲位于西半球。","pinyin":"Měizhōu wèiyú Xībànqiú.","vi":"Châu Mỹ nằm ở bán cầu Tây."},{"type":"simple","zh":"地理老师在地球仪上指出了西半球的位置。","pinyin":"Dìlǐ lǎoshī zài dìqiúyí shang zhǐchūle Xībànqiú de wèizhì.","vi":"Thầy địa lý chỉ ra vị trí bán cầu Tây trên quả địa cầu."},{"type":"compound","zh":"因为巴西在西半球，所以跟中国差了十一个小时。","pinyin":"Yīnwèi Bāxī zài Xībànqiú, suǒyǐ gēn Zhōngguó chàle shíyī gè xiǎoshí.","vi":"Vì Brazil nằm ở bán cầu Tây nên lệch giờ với Trung Quốc mười một tiếng."}],"related":[{"hanzi":"东半球","pinyin":"Dōngbànqiú","vi":"bán cầu Đông"},{"hanzi":"北半球","pinyin":"Běibànqiú","vi":"bán cầu Bắc"},{"hanzi":"南半球","pinyin":"Nánbànqiú","vi":"bán cầu Nam"},{"hanzi":"美洲","pinyin":"Měizhōu","vi":"châu Mỹ"}]},{"id":"西湖","hanzi":"西湖","pinyin":"Xīhú","meaning_vi":"Tây Hồ (Hàng Châu)","explanation":"Địa danh nổi tiếng với câu 'Trên có thiên đàng, dưới có Tô Hàng'.","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏞️","examples":[{"type":"basic","zh":"西湖的春天很美。","pinyin":"Xīhú de chūntiān hěn měi.","vi":"Mùa xuân ở Tây Hồ rất đẹp."},{"type":"simple","zh":"我们租了一条小船在西湖上慢慢游览。","pinyin":"Wǒmen zūle yì tiáo xiǎochuán zài Xīhú shang mànmàn yóulǎn.","vi":"Chúng tôi thuê một chiếc thuyền nhỏ thong thả dạo chơi trên Tây Hồ."},{"type":"compound","zh":"如果你秋天去杭州，就一定要在西湖边尝尝桂花糕。","pinyin":"Rúguǒ nǐ qiūtiān qù Hángzhōu, jiù yídìngyào zài Xīhú biān cháng chang guìhuāgāo.","vi":"Nếu bạn đến Hàng Châu vào mùa thu, nhất định phải nếm thử bánh hoa quế bên Tây Hồ."}],"related":[{"hanzi":"杭州","pinyin":"Hángzhōu","vi":"Hàng Châu"},{"hanzi":"断桥","pinyin":"Duànqiáo","vi":"Đoạn Kiều"},{"hanzi":"雷峰塔","pinyin":"Léifēngtǎ","vi":"tháp Lôi Phong"},{"hanzi":"湖泊","pinyin":"húpō","vi":"hồ"}]},{"id":"心理健康","hanzi":"心理健康","pinyin":"xīnlǐjiànkāng","meaning_vi":"sức khỏe tinh thần","explanation":"心 (tâm lý/tâm huyết) + 理 (lý luận/quản lý) + 健 (健) + 康 (康).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cam-xuc"],"image":"🧠","examples":[{"type":"basic","zh":"心理健康很重要。","pinyin":"Xīnlǐjiànkāng hěn zhòngyào.","vi":"Sức khỏe tinh thần rất quan trọng."},{"type":"simple","zh":"学校每周开设一节心理健康课。","pinyin":"Xuéxiào měizhōu kāishè yì jié xīnlǐjiànkāng kè.","vi":"Mỗi tuần nhà trường mở một tiết học về sức khỏe tinh thần."},{"type":"compound","zh":"父母不但要关心孩子的成绩，而且要重视他们的心理健康。","pinyin":"Fùmǔ búdàn yào guānxīn háizi de chéngjì, érqiě yào zhòngshì tāmen de xīnlǐjiànkāng.","vi":"Cha mẹ không chỉ phải quan tâm đến điểm số của con mà còn phải coi trọng sức khỏe tinh thần của chúng."}],"related":[{"hanzi":"心理咨询","pinyin":"xīnlǐzīxún","vi":"tư vấn tâm lý"},{"hanzi":"抑郁症","pinyin":"yìyùzhèng","vi":"trầm cảm"},{"hanzi":"焦虑","pinyin":"jiāolǜ","vi":"lo âu"},{"hanzi":"身心健康","pinyin":"shēnxīnjiànkāng","vi":"sức khỏe thể chất tinh thần"}]},{"id":"心理咨询","hanzi":"心理咨询","pinyin":"xīnlǐzīxún","meaning_vi":"tư vấn tâm lý","explanation":"心 (tâm lý/tâm huyết) + 理 (lý luận/quản lý) + 咨 (tư vấn/hỏi) + 询 (hỏi thăm).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","giao-tiep"],"image":"💬","examples":[{"type":"basic","zh":"她去做心理咨询了。","pinyin":"Tā qù zuò xīnlǐzīxún le.","vi":"Cô ấy đã đi tư vấn tâm lý."},{"type":"simple","zh":"学校的心理咨询室每天下午向学生开放。","pinyin":"Xuéxiào de xīnlǐzīxún shì měitiān xiàwǔ xiàng xuéshēng kāifàng.","vi":"Phòng tư vấn tâm lý của trường mở cửa cho học sinh vào mỗi buổi chiều."},{"type":"compound","zh":"如果压力大到睡不着觉，就应该及时寻求心理咨询。","pinyin":"Rúguǒ yālì dà dào shuìbùzháo jiào, jiù yīnggāi jíshí xúnqiú xīnlǐzīxún.","vi":"Nếu áp lực lớn đến mức mất ngủ, bạn nên kịp thời tìm đến tư vấn tâm lý."}],"related":[{"hanzi":"心理医生","pinyin":"xīnlǐyīshēng","vi":"bác sĩ tâm lý"},{"hanzi":"咨询师","pinyin":"zīxúnshī","vi":"chuyên viên tư vấn"},{"hanzi":"心理健康","pinyin":"xīnlǐjiànkāng","vi":"sức khỏe tinh thần"},{"hanzi":"心理疏导","pinyin":"xīnlǐshūdǎo","vi":"khai thông tâm lý"}],"traditional":"心理諮詢"},{"id":"新能源","hanzi":"新能源","pinyin":"xīnnéngyuán","meaning_vi":"năng lượng mới, năng lượng tái tạo","explanation":"新 (mới) + 能 (có thể (năng lực/điều kiện)) + 源 (nguồn gốc).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","khoa-hoc"],"image":"🔋","examples":[{"type":"basic","zh":"风能是一种新能源。","pinyin":"Fēngnéng shì yì zhǒng xīnnéngyuán.","vi":"Năng lượng gió là một loại năng lượng mới."},{"type":"simple","zh":"这片戈壁上建起了大型新能源基地。","pinyin":"Zhè piàn Gēbì shang jiàn qǐle dàxíng xīnnéngyuán jīdì.","vi":"Trên vùng sa mạc đá này đã xây dựng một căn cứ năng lượng mới quy mô lớn."},{"type":"compound","zh":"虽然新能源发展很快，但是煤炭在短期内还无法被取代。","pinyin":"Suīrán xīnnéngyuán fāzhǎn hěn kuài, dànshì méitàn zài duǎnqī nèi hái wúfǎ bèi qǔdài.","vi":"Tuy năng lượng mới phát triển rất nhanh, nhưng than đá trong ngắn hạn vẫn chưa thể bị thay thế."}],"related":[{"hanzi":"太阳能","pinyin":"tàiyángnéng","vi":"năng lượng mặt trời"},{"hanzi":"风能","pinyin":"fēngnéng","vi":"năng lượng gió"},{"hanzi":"清洁能源","pinyin":"qīngjiénéngyuán","vi":"năng lượng sạch"},{"hanzi":"化石能源","pinyin":"huàshínéngyuán","vi":"năng lượng hóa thạch"}]},{"id":"新能源汽车","hanzi":"新能源汽车","pinyin":"xīnnéngyuán qìchē","meaning_vi":"xe ô tô năng lượng mới (xe điện)","explanation":"新能源 (tân năng nguyên – năng lượng mới) + 汽车 (khí xa – ô tô) → ô tô chạy bằng năng lượng mới như điện, hybrid, hydro thay cho xăng dầu.","hsk_level":"7-9","tags":["danh-tu","giao-thong","cong-nghe"],"image":"🚗","examples":[{"type":"basic","zh":"他买了新能源汽车。","pinyin":"Tā mǎile xīnnéngyuánqìchē.","vi":"Anh ấy đã mua xe năng lượng mới."},{"type":"simple","zh":"小区停车场新装了十个新能源汽车充电桩。","pinyin":"Xiǎoqū tíngchēchǎng xīn zhuāngle shí gè xīnnéngyuánqìchē chōngdiànzhuāng.","vi":"Bãi đỗ xe của khu dân cư mới lắp mười trụ sạc cho xe năng lượng mới."},{"type":"compound","zh":"新能源汽车既省油钱，又不用摇号上牌。","pinyin":"Xīnnéngyuánqìchē jì shěng yóu qián, yòu bú yòng yáohào shàngpái.","vi":"Xe năng lượng mới vừa tiết kiệm tiền xăng, vừa không phải bốc thăm để đăng ký biển số."}],"related":[{"hanzi":"电动汽车","pinyin":"diàndòngqìchē","vi":"ô tô điện"},{"hanzi":"充电桩","pinyin":"chōngdiànzhuāng","vi":"trụ sạc"},{"hanzi":"燃油车","pinyin":"rányóuchē","vi":"xe chạy xăng"},{"hanzi":"电池","pinyin":"diànchí","vi":"pin"}],"traditional":"新能源汽車"},{"id":"芯片","hanzi":"芯片","pinyin":"xīnpiàn","meaning_vi":"con chip điện tử, vi mạch","explanation":"芯 (lõi/chip) + 片 (miếng).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","do-vat"],"image":"🔌","examples":[{"type":"basic","zh":"这颗芯片很先进。","pinyin":"Zhè kē xīnpiàn hěn xiānjìn.","vi":"Con chip này rất tiên tiến."},{"type":"simple","zh":"工程师们花了五年时间研发这款芯片。","pinyin":"Gōngchéngshīmen huāle wǔ nián shíjiān yánfā zhè kuǎn xīnpiàn.","vi":"Các kỹ sư đã mất năm năm để nghiên cứu phát triển con chip này."},{"type":"compound","zh":"因为缺少高端芯片，所以这款手机推迟了半年才上市。","pinyin":"Yīnwèi quēshǎo gāoduān xīnpiàn, suǒyǐ zhè kuǎn shǒujī tuīchíle bàn nián cái shàngshì.","vi":"Vì thiếu chip cao cấp nên chiếc điện thoại này phải lùi lại nửa năm mới ra mắt."}],"related":[{"hanzi":"半导体","pinyin":"bàndǎotǐ","vi":"chất bán dẫn"},{"hanzi":"集成电路","pinyin":"jíchéngdiànlù","vi":"mạch tích hợp"},{"hanzi":"处理器","pinyin":"chǔlǐqì","vi":"bộ xử lý"},{"hanzi":"科技","pinyin":"kējì","vi":"khoa học công nghệ"}]},{"id":"新闻发布会","hanzi":"新闻发布会","pinyin":"xīnwén fābùhuì","meaning_vi":"cuộc họp báo","explanation":"新闻 (tân văn – tin tức) + 发布 (phát bố – công bố) + 会 (hội – cuộc họp) → cuộc họp công bố tin tức với báo giới, họp báo. Đi với 召开, 举行.","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🎙️","examples":[{"type":"basic","zh":"下午有新闻发布会。","pinyin":"Xiàwǔ yǒu xīnwénfābùhuì.","vi":"Chiều nay có cuộc họp báo."},{"type":"simple","zh":"发言人在新闻发布会上回答了记者的提问。","pinyin":"Fāyánrén zài xīnwénfābùhuì shang huídále jìzhě de tíwèn.","vi":"Người phát ngôn đã trả lời câu hỏi của phóng viên tại cuộc họp báo."},{"type":"compound","zh":"新闻发布会一结束，记者们就围住了公司总裁。","pinyin":"Xīnwénfābùhuì yì jiéshù, jìzhěmen jiù wéizhùle gōngsī zǒngcái.","vi":"Cuộc họp báo vừa kết thúc, các phóng viên đã vây lấy tổng giám đốc công ty."}],"related":[{"hanzi":"记者会","pinyin":"jìzhěhuì","vi":"họp báo"},{"hanzi":"发言人","pinyin":"fāyánrén","vi":"người phát ngôn"},{"hanzi":"记者","pinyin":"jìzhě","vi":"phóng viên"},{"hanzi":"发布","pinyin":"fābù","vi":"công bố"}],"traditional":"新聞發佈會"},{"id":"新鲜感","hanzi":"新鲜感","pinyin":"xīnxiāngǎn","meaning_vi":"cảm giác mới mẻ","explanation":"新 (mới) + 鲜 (tươi sáng/hiếm) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"✨","examples":[{"type":"basic","zh":"新鲜感很快就没了。","pinyin":"Xīnxiāngǎn hěn kuài jiù méile.","vi":"Cảm giác mới mẻ nhanh chóng biến mất."},{"type":"simple","zh":"换个城市生活能给人带来不少新鲜感。","pinyin":"Huàn gè chéngshì shēnghuó néng gěi rén dàilái bùshǎo xīnxiāngǎn.","vi":"Đổi sang sống ở thành phố khác có thể mang lại cho người ta không ít cảm giác mới mẻ."},{"type":"compound","zh":"即使新鲜感消失了，两个人也能靠彼此理解走下去。","pinyin":"Jíshǐ xīnxiāngǎn xiāoshī le, liǎng gè rén yě néng kào bǐcǐ lǐjiě zǒu xiàqù.","vi":"Dù cảm giác mới mẻ đã qua đi, hai người vẫn có thể bước tiếp nhờ thấu hiểu nhau."}],"related":[{"hanzi":"新鲜","pinyin":"xīnxiān","vi":"mới mẻ"},{"hanzi":"好奇心","pinyin":"hàoqíxīn","vi":"lòng hiếu kỳ"},{"hanzi":"新奇","pinyin":"xīnqí","vi":"mới lạ"},{"hanzi":"厌倦","pinyin":"yànjuàn","vi":"chán ngán"}],"traditional":"新鮮感"},{"id":"心血管","hanzi":"心血管","pinyin":"xīnxuèguǎn","meaning_vi":"tim mạch","explanation":"心 (tâm lý/tâm huyết) + 血 (máu/tâm huyết) + 管 (管).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","co-the"],"image":"🫀","examples":[{"type":"basic","zh":"他有心血管疾病。","pinyin":"Tā yǒuxīn xuèguǎn jíbìng.","vi":"Ông ấy mắc bệnh tim mạch."},{"type":"simple","zh":"医生建议爸爸每年做一次心血管检查。","pinyin":"Yīshēng jiànyì bàba měinián zuò yí cì xīnxuèguǎn jiǎnchá.","vi":"Bác sĩ khuyên bố mỗi năm kiểm tra tim mạch một lần."},{"type":"compound","zh":"如果长期吃得太咸，心血管就会承受很大压力。","pinyin":"Rúguǒ chángqī chī de tài xián, xīnxuèguǎn jiù huì chéngshòu hěn dà yālì.","vi":"Nếu ăn quá mặn trong thời gian dài, tim mạch sẽ phải chịu áp lực rất lớn."}],"related":[{"hanzi":"心脏病","pinyin":"xīnzàngbìng","vi":"bệnh tim"},{"hanzi":"高血压","pinyin":"gāoxuèyā","vi":"huyết áp cao"},{"hanzi":"血管","pinyin":"xuèguǎn","vi":"mạch máu"},{"hanzi":"心脏","pinyin":"xīnzàng","vi":"tim"}]},{"id":"虚拟货币","hanzi":"虚拟货币","pinyin":"xūnǐhuòbì","meaning_vi":"tiền ảo, tiền mã hóa","explanation":"虚拟 (ảo) + 货币 (tiền tệ).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","tien-te"],"image":"🪙","examples":[{"type":"basic","zh":"他投资过虚拟货币。","pinyin":"Tā tóuzīguo xūnǐhuòbì.","vi":"Anh ấy từng đầu tư tiền ảo."},{"type":"simple","zh":"警方提醒市民警惕以虚拟货币为名的诈骗。","pinyin":"Jǐngfāng tíxǐng shìmín jǐngtì yǐ xūnǐhuòbì wéi míng de zhàpiàn.","vi":"Cảnh sát nhắc nhở người dân cảnh giác với các vụ lừa đảo núp bóng tiền ảo."},{"type":"compound","zh":"因为虚拟货币价格波动太大，所以很多人一夜之间亏光了积蓄。","pinyin":"Yīnwèi xūnǐhuòbì jiàgé bōdòng tài dà, suǒyǐ hěn duō rén yí yè zhījiān kuī guāngle jīxù.","vi":"Vì giá tiền ảo biến động quá lớn nên nhiều người đã mất sạch tiền tiết kiệm chỉ sau một đêm."}],"related":[{"hanzi":"比特币","pinyin":"bǐtèbì","vi":"Bitcoin"},{"hanzi":"区块链","pinyin":"qūkuàiliàn","vi":"chuỗi khối"},{"hanzi":"数字货币","pinyin":"shùzìhuòbì","vi":"tiền kỹ thuật số"},{"hanzi":"货币","pinyin":"huòbì","vi":"tiền tệ"}],"traditional":"虛擬貨幣"},{"id":"虚拟现实","hanzi":"虚拟现实","pinyin":"xūnǐxiànshí","meaning_vi":"thực tế ảo (VR)","explanation":"虚 (khiêm tốn/hư ảo) + 拟 (soạn thảo/mô phỏng) + 现 (hiện thực/hiện trường) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"🥽","examples":[{"type":"basic","zh":"我体验了虚拟现实。","pinyin":"Wǒ tǐyànle xūnǐxiànshí.","vi":"Tôi đã trải nghiệm thực tế ảo."},{"type":"simple","zh":"博物馆用虚拟现实技术重现了古城的样子。","pinyin":"Bówùguǎn yòng xūnǐxiànshí jìshù chóngxiànle gǔchéng de yàngzi.","vi":"Bảo tàng dùng công nghệ thực tế ảo để tái hiện diện mạo của tòa cổ thành."},{"type":"compound","zh":"一戴上虚拟现实眼镜，孩子们就仿佛走进了海底世界。","pinyin":"Yí dàishàng xūnǐxiànshí yǎnjìng, háizimen jiù fǎngfú zǒujìnle hǎidǐ shìjiè.","vi":"Vừa đeo kính thực tế ảo lên, bọn trẻ như bước vào thế giới đáy biển."}],"related":[{"hanzi":"增强现实","pinyin":"zēngqiángxiànshí","vi":"thực tế tăng cường"},{"hanzi":"元宇宙","pinyin":"yuányǔzhòu","vi":"vũ trụ ảo"},{"hanzi":"虚拟","pinyin":"xūnǐ","vi":"ảo"},{"hanzi":"现实","pinyin":"xiànshí","vi":"hiện thực"}],"traditional":"虛擬現實"},{"id":"虚荣心","hanzi":"虚荣心","pinyin":"xūróngxīn","meaning_vi":"tính hư vinh, sĩ diện hão","explanation":"虚 (khiêm tốn/hư ảo) + 荣 (vinh dự/phồn vinh) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","con-nguoi"],"image":"🎭","examples":[{"type":"basic","zh":"他的虚荣心很强。","pinyin":"Tā de xūróngxīn hěn qiáng.","vi":"Anh ta rất sĩ diện hão."},{"type":"simple","zh":"为了满足虚荣心，她刷信用卡买了名牌包。","pinyin":"Wèile mǎnzú xūróngxīn, tā shuā xìnyòngkǎ mǎile míngpái bāo.","vi":"Để thỏa mãn lòng hư vinh, cô ấy đã quẹt thẻ tín dụng mua túi hàng hiệu."},{"type":"compound","zh":"如果被虚荣心牵着走，人就容易陷入攀比的怪圈。","pinyin":"Rúguǒ bèi xūróngxīn qiānzhe zǒu, rén jiù róngyì xiànrù pānbǐ de guàiquān.","vi":"Nếu để lòng hư vinh dắt mũi, con người dễ rơi vào vòng luẩn quẩn so bì."}],"related":[{"hanzi":"虚荣","pinyin":"xūróng","vi":"hư vinh"},{"hanzi":"爱面子","pinyin":"àimiànzi","vi":"sĩ diện"},{"hanzi":"攀比","pinyin":"pānbǐ","vi":"so bì"},{"hanzi":"自尊心","pinyin":"zìzūnxīn","vi":"lòng tự trọng"}],"traditional":"虛榮心"},{"id":"洗钱","hanzi":"洗钱","pinyin":"xǐqián","meaning_vi":"rửa tiền","explanation":"洗 (rửa) + 钱 (tiền). Động từ ly hợp.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🚨","examples":[{"type":"basic","zh":"他涉嫌洗钱。","pinyin":"Tā shèxián xǐqián.","vi":"Hắn bị tình nghi rửa tiền."},{"type":"simple","zh":"犯罪团伙通过空壳公司洗钱。","pinyin":"Fànzuì tuánhuǒ tōngguò kōngké gōngsī xǐqián.","vi":"Băng nhóm tội phạm rửa tiền thông qua các công ty ma."},{"type":"compound","zh":"银行一旦发现可疑转账，就会怀疑有人在洗钱。","pinyin":"Yínháng yídàn fāxiàn kěyí zhuǎnzhàng, jiù huì huáiyí yǒurén zài xǐqián.","vi":"Một khi ngân hàng phát hiện giao dịch chuyển khoản đáng ngờ, họ sẽ nghi ngờ có người đang rửa tiền."}],"related":[{"hanzi":"贪污","pinyin":"tānwū","vi":"tham ô"},{"hanzi":"诈骗","pinyin":"zhàpiàn","vi":"lừa đảo"},{"hanzi":"走私","pinyin":"zǒusī","vi":"buôn lậu"},{"hanzi":"非法","pinyin":"fēifǎ","vi":"phi pháp"}],"traditional":"洗錢"},{"id":"元宵节","hanzi":"元宵节","pinyin":"Yuánxiāojié","meaning_vi":"Tết Nguyên Tiêu (Rằm tháng Giêng)","explanation":"元宵 (bánh trôi tàu) + 节.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"🏮","examples":[{"type":"basic","zh":"元宵节要吃汤圆。","pinyin":"Yuánxiāojié yào chī tāngyuán.","vi":"Tết Nguyên Tiêu phải ăn bánh trôi."},{"type":"simple","zh":"元宵节晚上，街上挂满了五颜六色的花灯。","pinyin":"Yuánxiāojié wǎnshang, jiēshang guà mǎnle wǔyánliùsè de huādēng.","vi":"Tối Tết Nguyên Tiêu, đường phố treo đầy đèn lồng rực rỡ sắc màu."},{"type":"compound","zh":"元宵节一过，春节的气氛就慢慢淡了。","pinyin":"Yuánxiāojié yí guò, Chūnjié de qìfēn jiù mànmàn dàn le.","vi":"Tết Nguyên Tiêu vừa qua, không khí Tết dần dần nhạt đi."}],"related":[{"hanzi":"汤圆","pinyin":"tāngyuán","vi":"bánh trôi"},{"hanzi":"灯笼","pinyin":"dēnglong","vi":"đèn lồng"},{"hanzi":"猜灯谜","pinyin":"cāidēngmí","vi":"đoán câu đố đèn"},{"hanzi":"春节","pinyin":"Chūnjié","vi":"Tết Nguyên đán"}],"traditional":"元宵節"},{"id":"亚健康","hanzi":"亚健康","pinyin":"yàjiànkāng","meaning_vi":"tình trạng giả khỏe mạnh (suy nhược nhẹ)","explanation":"亚 (châu Á/á quân) + 健 (健) + 康 (康).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"😴","examples":[{"type":"basic","zh":"很多白领处于亚健康。","pinyin":"Hěn duō báilǐng chǔyú yàjiànkāng.","vi":"Nhiều nhân viên văn phòng đang ở trạng thái giả khỏe mạnh."},{"type":"simple","zh":"长期熬夜让他陷入了亚健康状态。","pinyin":"Chángqī áoyè ràng tā xiànrùle yàjiànkāng zhuàngtài.","vi":"Thức khuya kéo dài khiến anh ấy rơi vào trạng thái suy nhược nhẹ."},{"type":"compound","zh":"只要坚持锻炼和规律作息，亚健康状态就能逐渐改善。","pinyin":"Zhǐyào jiānchí duànliàn hé guīlǜ zuòxī, yàjiànkāng zhuàngtài jiù néng zhújiàn gǎishàn.","vi":"Chỉ cần kiên trì tập luyện và sinh hoạt điều độ, tình trạng suy nhược nhẹ sẽ dần được cải thiện."}],"related":[{"hanzi":"健康","pinyin":"jiànkāng","vi":"sức khỏe"},{"hanzi":"疲劳","pinyin":"píláo","vi":"mệt mỏi"},{"hanzi":"失眠","pinyin":"shīmián","vi":"mất ngủ"},{"hanzi":"养生","pinyin":"yǎngshēng","vi":"dưỡng sinh"}],"traditional":"亞健康"},{"id":"砚台","hanzi":"砚台","pinyin":"yàntai","meaning_vi":"nghiên mài mực","explanation":"砚 (nghiễn – nghiên) + 台 (đài – bệ) → nghiên mực, dụng cụ bằng đá để mài mực; một trong 文房四宝.","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🪨","examples":[{"type":"basic","zh":"桌上放着一方砚台。","pinyin":"Zhuō shang fàngzhe yìfāng yàntai.","vi":"Trên bàn đặt một chiếc nghiên mực."},{"type":"simple","zh":"爷爷每天早上都用这块旧砚台磨墨。","pinyin":"Yéye měitiān zǎo Shangdōu yòng zhè kuài jiù yàntai mó mò.","vi":"Sáng nào ông nội cũng dùng chiếc nghiên cũ này để mài mực."},{"type":"compound","zh":"这方砚台虽然不大，但是已经有三百多年的历史了。","pinyin":"Zhè fāng yàntai suīrán búdà, dànshì yǐjīng yǒu sān bǎi duōnián de lìshǐ le.","vi":"Chiếc nghiên mực này tuy không lớn, nhưng đã có lịch sử hơn ba trăm năm."}],"related":[{"hanzi":"文房四宝","pinyin":"wénfángsìbǎo","vi":"văn phòng tứ bảo"},{"hanzi":"墨","pinyin":"mò","vi":"mực"},{"hanzi":"毛笔","pinyin":"máobǐ","vi":"bút lông"},{"hanzi":"宣纸","pinyin":"xuānzhǐ","vi":"giấy Tuyên"}],"traditional":"硯台"},{"id":"疫苗接种","hanzi":"疫苗接种","pinyin":"yìmiáojiēzhòng","meaning_vi":"tiêm chủng vắc-xin","explanation":"疫 (dịch bệnh/miễn dịch) + 苗 (苗) + 接 (接) + 种 (chủng loại/hạt giống).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💉","examples":[{"type":"basic","zh":"疫苗接种已经开始。","pinyin":"Yìmiáojiēzhòng yǐjīng kāishǐ.","vi":"Việc tiêm chủng vắc-xin đã bắt đầu."},{"type":"simple","zh":"社区医院周末也为老人提供疫苗接种服务。","pinyin":"Shèqū yīyuàn zhōumò yě wèi lǎorén tígōng yìmiáojiēzhòng fúwù.","vi":"Bệnh viện phường cuối tuần cũng cung cấp dịch vụ tiêm chủng vắc-xin cho người cao tuổi."},{"type":"compound","zh":"因为按时完成了疫苗接种，所以孩子很少生这类病。","pinyin":"Yīnwèi ànshí wánchéngle yìmiáojiēzhòng, suǒyǐ háizi hěn shǎo shēng zhèlèi bìng.","vi":"Vì đã tiêm chủng vắc-xin đúng lịch nên đứa trẻ rất ít khi mắc loại bệnh này."}],"related":[{"hanzi":"疫苗","pinyin":"yìmiáo","vi":"vắc-xin"},{"hanzi":"接种","pinyin":"jiēzhòng","vi":"tiêm chủng"},{"hanzi":"打疫苗","pinyin":"dǎyìmiáo","vi":"tiêm vắc-xin"},{"hanzi":"免疫","pinyin":"miǎnyì","vi":"miễn dịch"}],"traditional":"疫苗接種"},{"id":"义务教育","hanzi":"义务教育","pinyin":"yìwùjiàoyù","meaning_vi":"giáo dục phổ cập bắt buộc","explanation":"义 (chính nghĩa/ý nghĩa) + 务 (nhiệm vụ/thiết thực) + 教 (dạy) + 育 (giáo dục/nuôi dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","xa-hoi"],"image":"🏫","examples":[{"type":"basic","zh":"义务教育是免费的。","pinyin":"Yìwùjiàoyù shì miǎnfèi de.","vi":"Giáo dục bắt buộc là miễn phí."},{"type":"simple","zh":"中国实行九年制义务教育。","pinyin":"Zhōngguó shíxíng jiǔ nián zhì yìwùjiàoyù.","vi":"Trung Quốc thực hiện chế độ giáo dục bắt buộc chín năm."},{"type":"compound","zh":"即使家庭条件再困难，孩子也有权接受义务教育。","pinyin":"Jíshǐ jiātíng tiáojiàn zài kùnnan, háizi yě yǒuquán jiēshòu yìwùjiàoyù.","vi":"Dù hoàn cảnh gia đình khó khăn đến đâu, trẻ em vẫn có quyền được hưởng giáo dục bắt buộc."}],"related":[{"hanzi":"九年义务教育","pinyin":"jiǔ nián yìwùjiàoyù","vi":"giáo dục bắt buộc chín năm"},{"hanzi":"小学","pinyin":"xiǎoxué","vi":"tiểu học"},{"hanzi":"初中","pinyin":"chūzhōng","vi":"trung học cơ sở"},{"hanzi":"教育","pinyin":"jiàoyù","vi":"giáo dục"}],"traditional":"義務教育"},{"id":"抑郁症","hanzi":"抑郁症","pinyin":"yìyùzhèng","meaning_vi":"bệnh trầm cảm","explanation":"抑 (抑) + 郁 (u uất/tươi tốt) + 症 (triệu chứng/bệnh).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cam-xuc"],"image":"😔","examples":[{"type":"basic","zh":"她患上了抑郁症。","pinyin":"Tā huànshàngle yìyùzhèng.","vi":"Cô ấy đã mắc bệnh trầm cảm."},{"type":"simple","zh":"那位歌手公开讲述了自己战胜抑郁症的经历。","pinyin":"Nà wèi gēshǒu gōngkāi jiǎngshùle zìjǐ zhànshèng yìyùzhèng de jīnglì.","vi":"Ca sĩ đó đã công khai kể lại trải nghiệm chiến thắng bệnh trầm cảm của mình."},{"type":"compound","zh":"抑郁症不是心情不好那么简单，而是需要专业治疗的疾病。","pinyin":"Yìyùzhèng bú shì xīnqíng bù hǎo nàme jiǎndān, érshì xūyào zhuānyè zhìliáo de jíbìng.","vi":"Trầm cảm không đơn giản là tâm trạng không tốt, mà là căn bệnh cần điều trị chuyên môn."}],"related":[{"hanzi":"抑郁","pinyin":"yìyù","vi":"u uất"},{"hanzi":"焦虑症","pinyin":"jiāolǜzhèng","vi":"chứng lo âu"},{"hanzi":"心理健康","pinyin":"xīnlǐjiànkāng","vi":"sức khỏe tinh thần"},{"hanzi":"心理咨询","pinyin":"xīnlǐzīxún","vi":"tư vấn tâm lý"}],"traditional":"抑鬱症"},{"id":"印度洋","hanzi":"印度洋","pinyin":"Yìndùyáng","meaning_vi":"Ấn Độ Dương","explanation":"印 (ấn tượng/in ấn) + 度 (度) + 洋 (đại dương/nước ngoài).","hsk_level":"7-9","tags":["danh-tu","dia-danh","thien-nhien"],"image":"🌊","examples":[{"type":"basic","zh":"印度洋一望无际。","pinyin":"Yìndùyáng yí wàng wújì.","vi":"Ấn Độ Dương mênh mông bát ngát."},{"type":"simple","zh":"这艘货轮正穿过印度洋驶向非洲。","pinyin":"Zhè sōu huòlún zhèng chuānguò Yìndùyáng shǐxiàng Fēizhōu.","vi":"Chiếc tàu chở hàng này đang băng qua Ấn Độ Dương hướng về châu Phi."},{"type":"compound","zh":"每到季风季节，印度洋上的风浪就特别大。","pinyin":"Měi dào jìfēng jìjié, Yìndùyáng shang de fēnglàng jiù tèbié dà.","vi":"Cứ đến mùa gió mùa, sóng gió trên Ấn Độ Dương lại đặc biệt lớn."}],"related":[{"hanzi":"太平洋","pinyin":"Tàipíngyáng","vi":"Thái Bình Dương"},{"hanzi":"大西洋","pinyin":"Dàxīyáng","vi":"Đại Tây Dương"},{"hanzi":"北冰洋","pinyin":"Běibīngyáng","vi":"Bắc Băng Dương"},{"hanzi":"印度","pinyin":"Yìndù","vi":"Ấn Độ"}]},{"id":"印刷术","hanzi":"印刷术","pinyin":"yìnshuāshù","meaning_vi":"kỹ thuật in ấn","explanation":"印刷 (ấn loát – in ấn) + 术 (thuật – kỹ thuật) → kỹ thuật in; một trong 四大发明, gồm in khắc gỗ và in chữ rời của Tất Thăng.","hsk_level":"7-9","tags":["danh-tu","van-hoa","khoa-hoc"],"image":"🖨️","examples":[{"type":"basic","zh":"印刷术改变了世界。","pinyin":"Yìnshuāshù gǎibiànle shìjiè.","vi":"Kỹ thuật in ấn đã thay đổi thế giới."},{"type":"simple","zh":"毕昇发明的活字印刷术比欧洲早了几百年。","pinyin":"Bìshēng fāmíng de huózì yìnshuāshù bǐ Ōuzhōu zǎole jǐ bǎinián.","vi":"Kỹ thuật in chữ rời do Tất Thăng phát minh sớm hơn châu Âu vài trăm năm."},{"type":"compound","zh":"因为有了印刷术，所以书籍不再是贵族的专利。","pinyin":"Yīnwèi yǒule yìnshuāshù, suǒyǐ shūjí bú zài shì guìzú de zhuānlì.","vi":"Nhờ có kỹ thuật in ấn, sách vở không còn là đặc quyền của giới quý tộc."}],"related":[{"hanzi":"活字印刷","pinyin":"huózìyìnshuā","vi":"in chữ rời"},{"hanzi":"四大发明","pinyin":"sìdàfāmíng","vi":"tứ đại phát minh"},{"hanzi":"造纸术","pinyin":"zàozhǐshù","vi":"kỹ thuật làm giấy"},{"hanzi":"毕昇","pinyin":"Bìshēng","vi":"Tất Thăng"}],"traditional":"印刷術"},{"id":"应试教育","hanzi":"应试教育","pinyin":"yìngshìjiàoyù","meaning_vi":"giáo dục nặng về thi cử","explanation":"应 (ứng phó/phản ứng) + 试 (thử) + 教 (dạy) + 育 (giáo dục/nuôi dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","xa-hoi"],"image":"📝","examples":[{"type":"basic","zh":"他反对应试教育。","pinyin":"Tā fǎnduì yìngshìjiàoyù.","vi":"Ông ấy phản đối nền giáo dục nặng về thi cử."},{"type":"simple","zh":"在应试教育下，学生每天都要做大量的习题。","pinyin":"Zài yìngshìjiàoyù xià, xuéshēng měitiān dōu yào zuò dàliàng de xítí.","vi":"Dưới nền giáo dục nặng về thi cử, học sinh mỗi ngày đều phải làm rất nhiều bài tập."},{"type":"compound","zh":"应试教育虽然能提高分数，但是容易忽视学生的创造力。","pinyin":"Yìngshìjiàoyù suīrán néng tígāo fēnshù, dànshì róngyì hūshì xuéshēng de chuàngzàolì.","vi":"Giáo dục nặng về thi cử tuy có thể nâng cao điểm số, nhưng dễ xem nhẹ khả năng sáng tạo của học sinh."}],"related":[{"hanzi":"素质教育","pinyin":"sùzhìjiàoyù","vi":"giáo dục toàn diện"},{"hanzi":"高考","pinyin":"gāokǎo","vi":"thi đại học"},{"hanzi":"考试","pinyin":"kǎoshì","vi":"thi cử"},{"hanzi":"题海战术","pinyin":"tíhǎizhànshù","vi":"luyện đề ồ ạt"}],"traditional":"應試教育"},{"id":"硬实力","hanzi":"硬实力","pinyin":"yìngshílì","meaning_vi":"sức mạnh cứng (kinh tế/quân sự)","explanation":"硬 (cứng rắn/phần cứng) + 实 (thực tế/thực chất) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cong-viec"],"image":"🏰","examples":[{"type":"basic","zh":"硬实力是基础。","pinyin":"Yìngshílì shì jīchǔ.","vi":"Sức mạnh cứng là nền tảng."},{"type":"simple","zh":"这家企业靠核心技术打造了自己的硬实力。","pinyin":"Zhè jiā qǐyè kào héxīnjìshù dǎzàole zìjǐ de yìngshílì.","vi":"Doanh nghiệp này dựa vào công nghệ lõi để xây dựng sức mạnh cứng của mình."},{"type":"compound","zh":"一个国家既要有硬实力，又要有文化软实力。","pinyin":"Yí gè guójiā jì yàoyǒu yìngshílì, yòu yàoyǒu wénhuà ruǎnshílì.","vi":"Một quốc gia vừa cần có sức mạnh cứng, vừa cần có sức mạnh mềm về văn hóa."}],"related":[{"hanzi":"软实力","pinyin":"ruǎnshílì","vi":"sức mạnh mềm"},{"hanzi":"综合国力","pinyin":"zōnghéguólì","vi":"sức mạnh tổng hợp"},{"hanzi":"军事","pinyin":"jūnshì","vi":"quân sự"},{"hanzi":"经济实力","pinyin":"jīngjìshílì","vi":"thực lực kinh tế"}],"traditional":"硬實力"},{"id":"移动支付","hanzi":"移动支付","pinyin":"yídòngzhīfù","meaning_vi":"thanh toán di động","explanation":"移动 + 支付 (chi trả).","hsk_level":"7-9","tags":["danh-tu","cong-nghe","tien-te"],"image":"📱","examples":[{"type":"basic","zh":"现在流行移动支付。","pinyin":"Xiànzài liúxíng yídòngzhīfù.","vi":"Bây giờ thanh toán di động rất phổ biến."},{"type":"simple","zh":"菜市场的小摊也都贴上了移动支付的二维码。","pinyin":"Càishìchǎng de xiǎotān yě dōu tiē shàngle yídòngzhīfù de èrwéimǎ.","vi":"Các sạp hàng nhỏ ở chợ cũng đều dán mã QR thanh toán di động."},{"type":"compound","zh":"有了移动支付，出门即使不带钱包也能买东西。","pinyin":"Yǒule yídòngzhīfù, chūmén jíshǐ búdài qiánbāo yě néng mǎidōngxi.","vi":"Có thanh toán di động, ra ngoài dù không mang ví vẫn có thể mua đồ."}],"related":[{"hanzi":"微信支付","pinyin":"wēixìnzhīfù","vi":"thanh toán WeChat"},{"hanzi":"支付宝","pinyin":"Zhīfùbǎo","vi":"Alipay"},{"hanzi":"扫码","pinyin":"sǎomǎ","vi":"quét mã"},{"hanzi":"现金","pinyin":"xiànjīn","vi":"tiền mặt"}],"traditional":"移動支付"},{"id":"颐和园","hanzi":"颐和园","pinyin":"Yíhéyuán","meaning_vi":"Di Hòa Viên (cung điện mùa hè ở Bắc Kinh)","explanation":"Địa danh du lịch nổi tiếng.","hsk_level":"7-9","tags":["danh-tu","van-hoa","du-lich"],"image":"🏞️","examples":[{"type":"basic","zh":"颐和园风景如画。","pinyin":"Yíhéyuán fēngjǐng rúhuà.","vi":"Phong cảnh Di Hòa Viên đẹp như tranh."},{"type":"simple","zh":"我们沿着颐和园的长廊慢慢走到了昆明湖边。","pinyin":"Wǒmen yánzhe Yíhéyuán de chángláng màn mànzǒu dàole Kūnmíng húbiān.","vi":"Chúng tôi men theo hành lang dài của Di Hòa Viên, thong thả đi đến bên hồ Côn Minh."},{"type":"compound","zh":"如果冬天去颐和园，就能看到人们在昆明湖上滑冰。","pinyin":"Rúguǒ dōngtiān qù Yíhéyuán, jiù néng kàndào rénmen zài Kūnmínghú shang huábīng.","vi":"Nếu đến Di Hòa Viên vào mùa đông, bạn có thể thấy mọi người trượt băng trên hồ Côn Minh."}],"related":[{"hanzi":"圆明园","pinyin":"Yuánmíngyuán","vi":"Viên Minh Viên"},{"hanzi":"故宫","pinyin":"gùgōng","vi":"Cố Cung"},{"hanzi":"天坛","pinyin":"Tiāntán","vi":"Thiên Đàn"},{"hanzi":"皇家园林","pinyin":"huángjiāyuánlín","vi":"vườn thượng uyển"}],"traditional":"頤和園"},{"id":"仪式感","hanzi":"仪式感","pinyin":"yíshìgǎn","meaning_vi":"tính nghi thức, sự trân trọng khoảnh khắc","explanation":"仪 (nghi thức/thiết bị) + 式 (式) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","van-hoa","cam-xuc"],"image":"🕯️","examples":[{"type":"basic","zh":"生活需要仪式感。","pinyin":"Shēnghuó xūyào yíshìgǎn.","vi":"Cuộc sống cần có tính nghi thức."},{"type":"simple","zh":"妈妈用一桌精致的晚餐给结婚纪念日增添了仪式感。","pinyin":"Māma yòng yì zhuō jīngzhì de wǎncān gěi jiéhūn jìniànrì zēngtiānle yíshìgǎn.","vi":"Mẹ dùng một bữa tối tinh tế để thêm phần trang trọng cho ngày kỷ niệm cưới."},{"type":"compound","zh":"虽然只是一顿简单的早餐，但是摆好餐具就有了仪式感。","pinyin":"Suīrán zhǐshì yí dùn jiǎndān de zǎocān, dànshì bǎi hǎo cānjù jiù yǒule yíshìgǎn.","vi":"Tuy chỉ là bữa sáng đơn giản, nhưng bày biện bát đĩa gọn gàng là đã có cảm giác trân trọng khoảnh khắc."}],"related":[{"hanzi":"仪式","pinyin":"yíshì","vi":"nghi thức"},{"hanzi":"纪念日","pinyin":"jìniànrì","vi":"ngày kỷ niệm"},{"hanzi":"生活情趣","pinyin":"shēnghuóqíngqù","vi":"thú vị cuộc sống"},{"hanzi":"浪漫","pinyin":"làngmàn","vi":"lãng mạn"}],"traditional":"儀式感"},{"id":"银河系","hanzi":"银河系","pinyin":"Yínhéxì","meaning_vi":"dải Ngân Hà","explanation":"银 (bạc/ngân hàng) + 河 (sông) + 系 (khoa (trong trường đại học)).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","thien-nhien"],"image":"🌌","examples":[{"type":"basic","zh":"地球在银河系里。","pinyin":"Dìqiú zài Yínhéxì lǐ.","vi":"Trái Đất nằm trong dải Ngân Hà."},{"type":"simple","zh":"在没有光污染的草原上能看清银河系。","pinyin":"Zài méiyǒu guāngwūrǎn de cǎoyuán shang néng kànqīng Yínhéxì.","vi":"Trên thảo nguyên không có ô nhiễm ánh sáng, có thể nhìn rõ dải Ngân Hà."},{"type":"compound","zh":"银河系虽然很大，但是在宇宙中只是一个普通的星系。","pinyin":"Yínhéxì suīrán hěn dà, dànshì zài yǔzhòu zhōng zhǐshì yí gè pǔtōng de xīngxì.","vi":"Dải Ngân Hà tuy rất lớn, nhưng trong vũ trụ chỉ là một thiên hà bình thường."}],"related":[{"hanzi":"太阳系","pinyin":"tàiyángxì","vi":"Hệ Mặt Trời"},{"hanzi":"宇宙","pinyin":"yǔzhòu","vi":"vũ trụ"},{"hanzi":"星系","pinyin":"xīngxì","vi":"thiên hà"},{"hanzi":"银河","pinyin":"Yínhé","vi":"sông Ngân"}],"traditional":"銀河系"},{"id":"银牌","hanzi":"银牌","pinyin":"yínpái","meaning_vi":"huy chương bạc","explanation":"银 (bạc/ngân hàng) + 牌 (牌).","hsk_level":"7-9","tags":["danh-tu","the-thao"],"image":"🥈","examples":[{"type":"basic","zh":"她获得了银牌。","pinyin":"Tā huòdéle yínpái.","vi":"Cô ấy đã giành huy chương bạc."},{"type":"simple","zh":"他在游泳比赛中为学校拿到了一枚银牌。","pinyin":"Tā zài yóuyǒng bǐsài zhōng wèi xuéxiào nádàole yìméi yínpái.","vi":"Cậu ấy đã giành một tấm huy chương bạc cho trường trong cuộc thi bơi."},{"type":"compound","zh":"虽然只差零点一秒就是金牌，但是他对这枚银牌很满意。","pinyin":"Suīrán zhǐ chà língdiǎn yì miǎo jiùshì jīnpái, dànshì tā duì zhè méi yínpái hěn mǎnyì.","vi":"Tuy chỉ kém 0,1 giây là giành huy chương vàng, nhưng anh ấy rất hài lòng với tấm huy chương bạc này."}],"related":[{"hanzi":"金牌","pinyin":"jīnpái","vi":"huy chương vàng"},{"hanzi":"铜牌","pinyin":"tóngpái","vi":"huy chương đồng"},{"hanzi":"亚军","pinyin":"yàjūn","vi":"á quân"},{"hanzi":"奖牌","pinyin":"jiǎngpái","vi":"huy chương"}],"traditional":"銀牌"},{"id":"迎难而上","hanzi":"迎难而上","pinyin":"yíngnán-érshàng","meaning_vi":"đón đầu khó khăn mà tiến lên","explanation":"迎 (nghênh đón) + 难 (khó) + 而 (mà) + 上 (trên).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🦁","examples":[{"type":"basic","zh":"我们要迎难而上。","pinyin":"Wǒmen yào yíngnán'érshàng.","vi":"Chúng ta phải đối mặt khó khăn mà tiến lên."},{"type":"simple","zh":"面对技术瓶颈，研发团队选择了迎难而上。","pinyin":"Miànduì jìshù píngjǐng, yánfā tuánduì xuǎnzéle yíngnán'érshàng.","vi":"Đối mặt với nút thắt kỹ thuật, đội nghiên cứu đã chọn cách vượt khó tiến lên."},{"type":"compound","zh":"与其遇到问题就退缩，不如迎难而上试一试。","pinyin":"Yǔqí yùdào wèntí jiù tuìsuō, bùrú yíngnán'érshàng shìyishì.","vi":"Thay vì gặp vấn đề là chùn bước, chi bằng đối mặt khó khăn mà thử một lần."}],"related":[{"hanzi":"知难而进","pinyin":"zhīnán'érjìn","vi":"biết khó vẫn tiến"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"},{"hanzi":"知难而退","pinyin":"zhīnán'értuì","vi":"biết khó mà lui"},{"hanzi":"望而却步","pinyin":"wàng'érquèbù","vi":"nhìn đã chùn bước"}],"traditional":"迎難而上"},{"id":"营商环境","hanzi":"营商环境","pinyin":"yíngshānghuánjìng","meaning_vi":"môi trường kinh doanh","explanation":"营商 (doanh thương – kinh doanh) + 环境 (hoàn cảnh – môi trường) → môi trường kinh doanh (thủ tục, pháp lý, thị trường). Thường đi với 优化.","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🏙️","examples":[{"type":"basic","zh":"当地营商环境很好。","pinyin":"Dāngdì yíngshānghuánjìng hěn hǎo.","vi":"Môi trường kinh doanh ở địa phương rất tốt."},{"type":"simple","zh":"市政府通过简化审批来改善营商环境。","pinyin":"Shìzhèngfǔ tōngguò jiǎnhuà shěnpī lái gǎishàn yíngshānghuánjìng.","vi":"Chính quyền thành phố cải thiện môi trường kinh doanh bằng cách đơn giản hóa thủ tục phê duyệt."},{"type":"compound","zh":"只要营商环境公平透明，外国投资者就愿意长期留下来。","pinyin":"Zhǐyào yíngshānghuánjìng gōngpíng tòumíng, wàiguó tóuzīzhě jiù yuànyì chángqī liú xiàlái.","vi":"Chỉ cần môi trường kinh doanh công bằng minh bạch, nhà đầu tư nước ngoài sẽ sẵn lòng ở lại lâu dài."}],"related":[{"hanzi":"投资环境","pinyin":"tóuzīhuánjìng","vi":"môi trường đầu tư"},{"hanzi":"招商引资","pinyin":"zhāoshāngyǐnzī","vi":"thu hút đầu tư"},{"hanzi":"优化","pinyin":"yōuhuà","vi":"tối ưu hóa"},{"hanzi":"政策","pinyin":"zhèngcè","vi":"chính sách"}],"traditional":"營商環境"},{"id":"营业额","hanzi":"营业额","pinyin":"yíngyè'é","meaning_vi":"doanh thu","explanation":"营业 + 额 (con số).","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"💰","examples":[{"type":"basic","zh":"本月营业额下降了。","pinyin":"Běnyuè yíngyè'é xiàjiàng le.","vi":"Doanh thu tháng này đã giảm."},{"type":"simple","zh":"这家火锅店国庆期间的营业额翻了一番。","pinyin":"Zhè jiā huǒguōdiàn Guóqìng qījiān de yíngyè'é fānle yìfān.","vi":"Doanh thu của quán lẩu này trong dịp Quốc khánh đã tăng gấp đôi."},{"type":"compound","zh":"因为附近开了地铁站，所以小店的营业额明显上涨。","pinyin":"Yīnwèi fùjìn kāile dìtiězhàn, suǒyǐ xiǎodiàn de yíngyè'é míngxiǎn shàngzhǎng.","vi":"Vì gần đó mở ga tàu điện ngầm nên doanh thu của cửa hàng nhỏ tăng rõ rệt."}],"related":[{"hanzi":"销售额","pinyin":"xiāoshòu'é","vi":"doanh số"},{"hanzi":"利润","pinyin":"lìrùn","vi":"lợi nhuận"},{"hanzi":"营业","pinyin":"yíngyè","vi":"kinh doanh"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"}],"traditional":"營業額"},{"id":"运载火箭","hanzi":"运载火箭","pinyin":"yùnzàihuǒjiàn","meaning_vi":"tên lửa đẩy","explanation":"运 (vận dụng/vận hành) + 载 (ghi chép/chuyên chở) + 火 (火) + 箭 (mũi tên).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc","cong-nghe"],"image":"🚀","examples":[{"type":"basic","zh":"运载火箭发射成功。","pinyin":"Yùnzàihuǒjiàn fāshè chénggōng.","vi":"Tên lửa đẩy được phóng thành công."},{"type":"simple","zh":"这枚运载火箭把三颗卫星送入了太空。","pinyin":"Zhè méi yùnzàihuǒjiàn bǎ sān kē wèixīng sòng rùle tàikōng.","vi":"Tên lửa đẩy này đã đưa ba vệ tinh vào không gian."},{"type":"compound","zh":"如果天气条件不理想，运载火箭的发射就要推迟。","pinyin":"Rúguǒ tiānqì tiáojiàn bù lǐxiǎng, yùnzàihuǒjiàn de fāshè jiùyào tuīchí.","vi":"Nếu điều kiện thời tiết không lý tưởng, việc phóng tên lửa đẩy sẽ phải hoãn lại."}],"related":[{"hanzi":"火箭","pinyin":"huǒjiàn","vi":"tên lửa"},{"hanzi":"发射","pinyin":"fāshè","vi":"phóng"},{"hanzi":"卫星","pinyin":"wèixīng","vi":"vệ tinh"},{"hanzi":"航天","pinyin":"hángtiān","vi":"hàng không vũ trụ"}],"traditional":"運載火箭"},{"id":"舆论导向","hanzi":"舆论导向","pinyin":"yúlùndǎoxiàng","meaning_vi":"định hướng dư luận","explanation":"舆论 (dư luận) + 导向 (đạo hướng – định hướng) → việc định hướng dư luận xã hội theo một hướng nhất định, thường nói về vai trò báo chí.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📰","examples":[{"type":"basic","zh":"媒体影响舆论导向。","pinyin":"Méitǐ yǐngxiǎng yúlùndǎoxiàng.","vi":"Truyền thông ảnh hưởng đến định hướng dư luận."},{"type":"simple","zh":"编辑在发稿前必须注意正确的舆论导向。","pinyin":"Biānjí zài fāgǎo qián bìxū zhùyì zhèngquè de yúlùndǎoxiàng.","vi":"Biên tập viên phải chú ý định hướng dư luận đúng đắn trước khi đăng bài."},{"type":"compound","zh":"一旦舆论导向出现偏差，谣言就会迅速扩散。","pinyin":"Yídàn yúlùndǎoxiàng chūxiàn piānchā, yáoyán jiù huì xùnsù kuòsàn.","vi":"Một khi định hướng dư luận bị lệch lạc, tin đồn sẽ lan truyền nhanh chóng."}],"related":[{"hanzi":"舆论","pinyin":"yúlùn","vi":"dư luận"},{"hanzi":"媒体","pinyin":"méitǐ","vi":"truyền thông"},{"hanzi":"引导","pinyin":"yǐndǎo","vi":"dẫn dắt"},{"hanzi":"宣传","pinyin":"xuānchuán","vi":"tuyên truyền"}],"traditional":"輿論導向"},{"id":"云计算","hanzi":"云计算","pinyin":"yúnjìsuàn","meaning_vi":"điện toán đám mây (Cloud computing)","explanation":"云 (đám mây) + 计算 (tính toán).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"☁️","examples":[{"type":"basic","zh":"公司用云计算存储数据。","pinyin":"Gōngsī yòng yúnjìsuàn cúnchǔ shùjù.","vi":"Công ty dùng điện toán đám mây để lưu trữ dữ liệu."},{"type":"simple","zh":"这家初创企业租用云计算服务来节省成本。","pinyin":"Zhè jiā chūchuàng qǐyè zūyòng yúnjìsuàn fúwù lái jiéshěng chéngběn.","vi":"Công ty khởi nghiệp này thuê dịch vụ điện toán đám mây để tiết kiệm chi phí."},{"type":"compound","zh":"因为采用了云计算，所以小团队也能处理海量数据。","pinyin":"Yīnwèi cǎiyòngle yúnjìsuàn, suǒyǐ xiǎo tuánduì yě néng chǔlǐ hǎiliàng shùjù.","vi":"Vì đã áp dụng điện toán đám mây nên đội nhỏ cũng có thể xử lý lượng dữ liệu khổng lồ."}],"related":[{"hanzi":"大数据","pinyin":"dàshùjù","vi":"dữ liệu lớn"},{"hanzi":"服务器","pinyin":"fúwùqì","vi":"máy chủ"},{"hanzi":"云存储","pinyin":"yúncúnchǔ","vi":"lưu trữ đám mây"},{"hanzi":"人工智能","pinyin":"réngōngzhìnéng","vi":"trí tuệ nhân tạo"}],"traditional":"雲計算"},{"id":"压榨","hanzi":"压榨","pinyin":"yāzhà","meaning_vi":"vắt kiệt, bóc lột","explanation":"压 (áp – đè ép) + 榨 (trá – ép lấy nước) → ép lấy nước; nghĩa bóng là bóc lột, vắt kiệt sức người. Ví dụ: 压榨甘蔗, 压榨工人.","hsk_level":"7-9","tags":["dong-tu"],"image":"🍋","examples":[{"type":"basic","zh":"老板压榨员工。","pinyin":"Lǎobǎn yāzhà yuángōng.","vi":"Ông chủ bóc lột nhân viên."},{"type":"simple","zh":"这家黑心工厂长期压榨外来打工者。","pinyin":"Zhè jiā hēixīn gōngchǎng chángqī yāzhà wàilái dǎgōng zhě.","vi":"Nhà máy bất lương này bóc lột lao động nhập cư trong thời gian dài."},{"type":"compound","zh":"如果企业一味压榨员工，人才就会接连流失。","pinyin":"Rúguǒ qǐyè yíwèi yāzhà yuángōng, réncái jiù huì jiēlián liúshī.","vi":"Nếu doanh nghiệp chỉ biết vắt kiệt nhân viên, nhân tài sẽ lần lượt ra đi."}],"related":[{"hanzi":"剥削","pinyin":"bōxuē","vi":"bóc lột"},{"hanzi":"榨取","pinyin":"zhàqǔ","vi":"vắt kiệt"},{"hanzi":"压迫","pinyin":"yāpò","vi":"áp bức"},{"hanzi":"榨汁","pinyin":"zhàzhī","vi":"ép nước"}],"traditional":"壓榨"},{"id":"妖魔化","hanzi":"妖魔化","pinyin":"yāomóhuà","meaning_vi":"ma quỷ hóa, bôi đen","explanation":"妖 (yêu quái/ma quỷ) + 魔 (ma quỷ/ảo thuật) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"👹","examples":[{"type":"basic","zh":"不要妖魔化游戏。","pinyin":"Bú yào yāomóhuà yóuxì.","vi":"Đừng ma quỷ hóa trò chơi điện tử."},{"type":"simple","zh":"有些报道故意把外卖骑手妖魔化了。","pinyin":"Yǒuxiē bàodào gùyì bǎ wàimài qíshǒu yāomóhuà le.","vi":"Một số bài báo cố tình bôi đen hình ảnh người giao đồ ăn."},{"type":"compound","zh":"我们虽然要警惕人工智能的风险，但是也不能把它妖魔化。","pinyin":"Wǒmen suīrán yào jǐngtì réngōngzhìnéng de fēngxiǎn, dànshì yě bù néng bǎ tā yāomóhuà.","vi":"Tuy chúng ta cần cảnh giác với rủi ro của trí tuệ nhân tạo, nhưng cũng không thể ma quỷ hóa nó."}],"related":[{"hanzi":"丑化","pinyin":"chǒuhuà","vi":"bôi xấu"},{"hanzi":"抹黑","pinyin":"mǒhēi","vi":"bôi nhọ"},{"hanzi":"美化","pinyin":"měihuà","vi":"tô đẹp"},{"hanzi":"神化","pinyin":"shénhuà","vi":"thần thánh hóa"}]},{"id":"医疗保险","hanzi":"医疗保险","pinyin":"yīliáobǎoxiǎn","meaning_vi":"bảo hiểm y tế","explanation":"医疗 (y liệu – chữa bệnh) + 保险 (bảo hiểm) → bảo hiểm y tế chi trả chi phí khám chữa bệnh. Gọi tắt 医保.","hsk_level":"7-9","tags":["danh-tu","suc-khoe","tien-te"],"image":"🏥","examples":[{"type":"basic","zh":"我买了医疗保险。","pinyin":"Wǒ mǎile yīliáobǎoxiǎn.","vi":"Tôi đã mua bảo hiểm y tế."},{"type":"simple","zh":"这次住院的大部分费用都由医疗保险报销。","pinyin":"Zhè cì zhùyuàn de dàbùfen fèiyòng dōu yóu yīliáobǎoxiǎn bàoxiāo.","vi":"Phần lớn chi phí lần nằm viện này đều được bảo hiểm y tế chi trả."},{"type":"compound","zh":"如果没有医疗保险，一场大病就可能拖垮一个家庭。","pinyin":"Rúguǒ méiyǒu yīliáobǎoxiǎn, yì chǎng dàbìng jiù kěnéng tuōkuǎ yí gè jiātíng.","vi":"Nếu không có bảo hiểm y tế, một trận ốm nặng có thể làm suy sụp cả một gia đình."}],"related":[{"hanzi":"医保","pinyin":"yībǎo","vi":"bảo hiểm y tế"},{"hanzi":"养老保险","pinyin":"yǎnglǎobǎoxiǎn","vi":"bảo hiểm hưu trí"},{"hanzi":"社会保障","pinyin":"shèhuìbǎozhàng","vi":"an sinh xã hội"},{"hanzi":"报销","pinyin":"bàoxiāo","vi":"thanh toán chi phí"}],"traditional":"醫療保險"},{"id":"一体化","hanzi":"一体化","pinyin":"yìtǐhuà","meaning_vi":"nhất thể hóa, hội nhập","explanation":"一 (số 1) + 体 (thể hiện/hệ thống) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🔗","examples":[{"type":"basic","zh":"区域一体化加快了。","pinyin":"Qūyù yìtǐhuà jiākuài le.","vi":"Quá trình nhất thể hóa khu vực đã được đẩy nhanh."},{"type":"simple","zh":"长三角的交通一体化让通勤变得更方便。","pinyin":"Chángsānjiǎo de jiāotōng yìtǐhuà ràng tōngqín biànde gèng fāngbiàn.","vi":"Nhất thể hóa giao thông vùng châu thổ Trường Giang giúp việc đi lại hằng ngày thuận tiện hơn."},{"type":"compound","zh":"只要实现城乡一体化，农村孩子就能享受同样的教育资源。","pinyin":"Zhǐyào shíxiàn chéngxiāng yìtǐhuà, nóngcūn háizi jiù néng xiǎngshòu tóngyàng de jiàoyù zīyuán.","vi":"Chỉ cần thực hiện nhất thể hóa thành thị và nông thôn, trẻ em nông thôn sẽ được hưởng nguồn lực giáo dục như nhau."}],"related":[{"hanzi":"一体","pinyin":"yìtǐ","vi":"một khối"},{"hanzi":"经济一体化","pinyin":"jīngjì yìtǐhuà","vi":"nhất thể hóa kinh tế"},{"hanzi":"融合","pinyin":"rónghé","vi":"hòa hợp"},{"hanzi":"全球化","pinyin":"quánqiúhuà","vi":"toàn cầu hóa"}],"traditional":"一體化"},{"id":"因材施教","hanzi":"因材施教","pinyin":"yīncái-shījiào","meaning_vi":"dạy học tùy theo năng lực từng học sinh","explanation":"因 (nguyên nhân/nhân tố) + 材 (材) + 施 (thi hành/thực hiện) + 教 (dạy).","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"好老师因材施教。","pinyin":"Hǎo lǎoshī yīncáishījiào.","vi":"Giáo viên giỏi dạy học tùy theo năng lực từng học sinh."},{"type":"simple","zh":"孔子很早就提出了因材施教的教育思想。","pinyin":"Kǒngzǐ hěn zǎojiù tíchūle yīncáishījiào de jiàoyù sīxiǎng.","vi":"Khổng Tử từ rất sớm đã đề xuất tư tưởng giáo dục dạy học tùy theo năng lực từng người."},{"type":"compound","zh":"因为每个孩子的性格都不同，所以家长也要因材施教。","pinyin":"Yīnwèi měi gè háizi de xìnggé dōu bùtóng, suǒyǐ jiāzhǎng yě yào yīncáishījiào.","vi":"Vì tính cách mỗi đứa trẻ đều khác nhau nên cha mẹ cũng cần dạy dỗ tùy theo từng con."}],"related":[{"hanzi":"教育","pinyin":"jiàoyù","vi":"giáo dục"},{"hanzi":"个性化","pinyin":"gèxìnghuà","vi":"cá nhân hóa"},{"hanzi":"循循善诱","pinyin":"xúnxúnshànyòu","vi":"dẫn dắt từng bước"},{"hanzi":"一刀切","pinyin":"yìdāoqiē","vi":"cào bằng"}]},{"id":"优化","hanzi":"优化","pinyin":"yōuhuà","meaning_vi":"tối ưu hóa","explanation":"优 (ưu thế/ưu tú) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"⚡","examples":[{"type":"basic","zh":"我们优化了流程。","pinyin":"Wǒmen yōuhuàle liúchéng.","vi":"Chúng tôi đã tối ưu hóa quy trình."},{"type":"simple","zh":"程序员优化了代码，让网页加载快了一倍。","pinyin":"Chéngxùyuán yōuhuàle dàimǎ, ràng wǎngyè jiāzài kuàile yí bèi.","vi":"Lập trình viên đã tối ưu hóa mã nguồn, giúp trang web tải nhanh gấp đôi."},{"type":"compound","zh":"如果不优化库存管理，仓库里的货就会越积越多。","pinyin":"Rúguǒ bù yōuhuà kùcún guǎnlǐ, cāngkù lǐ de huò jiù huì yuè jī yuè duō.","vi":"Nếu không tối ưu hóa quản lý tồn kho, hàng trong kho sẽ ngày càng chất đống."}],"related":[{"hanzi":"改善","pinyin":"gǎishàn","vi":"cải thiện"},{"hanzi":"完善","pinyin":"wánshàn","vi":"hoàn thiện"},{"hanzi":"改进","pinyin":"gǎijìn","vi":"cải tiến"},{"hanzi":"最优","pinyin":"zuìyōu","vi":"tối ưu"}],"traditional":"優化"},{"id":"养老保险","hanzi":"养老保险","pinyin":"yǎnglǎobǎoxiǎn","meaning_vi":"bảo hiểm hưu trí","explanation":"养老 (dưỡng lão – nuôi người già, hưu trí) + 保险 (bảo hiểm) → bảo hiểm hưu trí, chi trả lương hưu khi về già; một trong 五险.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","tien-te"],"image":"👴","examples":[{"type":"basic","zh":"他每月交养老保险。","pinyin":"Tā měiyuè jiāo yǎnglǎobǎoxiǎn.","vi":"Mỗi tháng anh ấy đóng bảo hiểm hưu trí."},{"type":"simple","zh":"自由职业者也可以自己缴纳养老保险。","pinyin":"Zìyóu zhíyè zhě yě kěyǐ zìjǐ jiǎonà yǎnglǎobǎoxiǎn.","vi":"Người làm nghề tự do cũng có thể tự đóng bảo hiểm hưu trí."},{"type":"compound","zh":"只要连续缴纳十五年养老保险，退休后就能按月领钱。","pinyin":"Zhǐyào liánxù jiǎonà shíwǔ nián yǎnglǎobǎoxiǎn, tuìxiū hòu jiù néng ànyuè lǐng qián.","vi":"Chỉ cần đóng bảo hiểm hưu trí liên tục mười lăm năm, sau khi nghỉ hưu sẽ được nhận tiền hằng tháng."}],"related":[{"hanzi":"养老金","pinyin":"yǎnglǎojīn","vi":"lương hưu"},{"hanzi":"退休","pinyin":"tuìxiū","vi":"nghỉ hưu"},{"hanzi":"医疗保险","pinyin":"yīliáobǎoxiǎn","vi":"bảo hiểm y tế"},{"hanzi":"社保","pinyin":"shèbǎo","vi":"bảo hiểm xã hội"}],"traditional":"養老保險"},{"id":"养生","hanzi":"养生","pinyin":"yǎngshēng","meaning_vi":"dưỡng sinh, chăm sóc sức khỏe","explanation":"养 (nuôi dưỡng) + 生 (sự sống).","hsk_level":"7-9","tags":["dong-tu","suc-khoe","van-hoa"],"image":"🧘","examples":[{"type":"basic","zh":"奶奶很注重养生。","pinyin":"Nǎinai hěn zhùzhòng yǎngshēng.","vi":"Bà nội rất chú trọng dưỡng sinh."},{"type":"simple","zh":"年轻人也开始用保温杯泡枸杞养生了。","pinyin":"Niánqīngrén yě kāishǐ yòng bǎowēnbēi pào gǒuqǐ yǎngshēng le.","vi":"Giới trẻ cũng bắt đầu ngâm kỷ tử trong bình giữ nhiệt để dưỡng sinh."},{"type":"compound","zh":"即使养生知识再丰富，经常熬夜也没有用。","pinyin":"Jíshǐ yǎngshēng zhīshi zài fēngfù, jīngcháng áoyè yě méiyǒu yòng.","vi":"Dù kiến thức dưỡng sinh có phong phú đến đâu, thường xuyên thức khuya thì cũng vô ích."}],"related":[{"hanzi":"保健","pinyin":"bǎojiàn","vi":"bảo vệ sức khỏe"},{"hanzi":"食疗","pinyin":"shíliáo","vi":"ẩm thực trị liệu"},{"hanzi":"锻炼","pinyin":"duànliàn","vi":"rèn luyện"},{"hanzi":"长寿","pinyin":"chángshòu","vi":"sống lâu"}],"traditional":"養生"},{"id":"以人为本","hanzi":"以人为本","pinyin":"yǐrén-wéiběn","meaning_vi":"lấy con người làm gốc","explanation":"以 (lấy) + 人 (người) + 为 (vì) + 本 (quyển).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"👤","examples":[{"type":"basic","zh":"设计要以人为本。","pinyin":"Shèjì yào yǐrénwéiběn.","vi":"Thiết kế phải lấy con người làm gốc."},{"type":"simple","zh":"这座新医院处处体现了以人为本的理念。","pinyin":"Zhè zuò xīn yīyuàn chùchù tǐxiànle yǐrénwéiběn de lǐniàn.","vi":"Bệnh viện mới này thể hiện ở mọi nơi triết lý lấy con người làm gốc."},{"type":"compound","zh":"只有坚持以人为本，城市规划才能真正方便市民。","pinyin":"Zhǐyǒu jiānchí yǐrénwéiběn, chéngshì guīhuà cáinéng zhēnzhèng fāngbiàn shìmín.","vi":"Chỉ khi kiên trì lấy con người làm gốc, quy hoạch đô thị mới thực sự thuận tiện cho người dân."}],"related":[{"hanzi":"人性化","pinyin":"rénxìnghuà","vi":"nhân văn hóa"},{"hanzi":"民本","pinyin":"mínběn","vi":"lấy dân làm gốc"},{"hanzi":"人文关怀","pinyin":"rénwénguānhuái","vi":"quan tâm nhân văn"},{"hanzi":"关爱","pinyin":"guān'ài","vi":"quan tâm yêu thương"}],"traditional":"以人為本"},{"id":"引力","hanzi":"引力","pinyin":"yǐnlì","meaning_vi":"lực hấp dẫn, trọng lực","explanation":"引 (dẫn dắt/thu hút) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🌍","examples":[{"type":"basic","zh":"月球的引力很小。","pinyin":"Yuèqiú de yǐnlì hěn xiǎo.","vi":"Lực hấp dẫn của Mặt Trăng rất nhỏ."},{"type":"simple","zh":"牛顿从掉落的苹果中想到了万有引力。","pinyin":"Niúdùn cóng diàoluò de píngguǒ zhōng xiǎngdàole wànyǒu yǐnlì.","vi":"Newton từ quả táo rơi xuống đã nghĩ ra định luật vạn vật hấp dẫn."},{"type":"compound","zh":"因为月球引力的作用，所以海水每天都会涨潮和落潮。","pinyin":"Yīnwèi yuèqiú yǐnlì de zuòyòng, suǒyǐ hǎishuǐ měitiān dōuhuì zhǎngcháo hé luòcháo.","vi":"Do tác động của lực hấp dẫn Mặt Trăng nên nước biển mỗi ngày đều lên xuống thủy triều."}],"related":[{"hanzi":"万有引力","pinyin":"wànyǒuyǐnlì","vi":"lực vạn vật hấp dẫn"},{"hanzi":"重力","pinyin":"zhònglì","vi":"trọng lực"},{"hanzi":"吸引力","pinyin":"xīyǐnlì","vi":"sức hút"},{"hanzi":"牛顿","pinyin":"niúdùn","vi":"Newton"}]},{"id":"引申义","hanzi":"引申义","pinyin":"yǐnshēnyì","meaning_vi":"nghĩa mở rộng, nghĩa bóng","explanation":"引 (dẫn dắt/thu hút) + 申 (khai báo/trình bày) + 义 (chính nghĩa/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","ngon-ngu","hoc-tap"],"image":"💡","examples":[{"type":"basic","zh":"这个词有引申义。","pinyin":"Zhè ge cí yǒu yǐnshēnyì.","vi":"Từ này có nghĩa mở rộng."},{"type":"simple","zh":"字典里列出了这个字的本义和引申义。","pinyin":"Zìdiǎn lǐ lièchūle zhè ge zì de běnyì hé yǐnshēnyì.","vi":"Từ điển liệt kê nghĩa gốc và nghĩa mở rộng của chữ này."},{"type":"compound","zh":"如果只记本义而忽略引申义，读古文时就容易误解。","pinyin":"Rúguǒ zhǐ jì běnyì ér hūlüè yǐnshēnyì, dú gǔwén shí jiù róngyì wùjiě.","vi":"Nếu chỉ nhớ nghĩa gốc mà bỏ qua nghĩa mở rộng, khi đọc cổ văn sẽ dễ hiểu sai."}],"related":[{"hanzi":"本义","pinyin":"běnyì","vi":"nghĩa gốc"},{"hanzi":"比喻义","pinyin":"bǐyùyì","vi":"nghĩa ẩn dụ"},{"hanzi":"字面意思","pinyin":"zìmiànyìsi","vi":"nghĩa đen"},{"hanzi":"含义","pinyin":"hányì","vi":"hàm nghĩa"}],"traditional":"引申義"},{"id":"引言","hanzi":"引言","pinyin":"yǐnyán","meaning_vi":"lời mở đầu, dẫn nhập","explanation":"引 (dẫn dắt/thu hút) + 言 (ngôn luận/lời nói).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📖","examples":[{"type":"basic","zh":"请先读一下引言。","pinyin":"Qǐng xiān dú yíxià yǐnyán.","vi":"Hãy đọc phần mở đầu trước."},{"type":"simple","zh":"作者在引言中说明了写这本书的原因。","pinyin":"Zuòzhě zài yǐnyán zhōng shuōmíngle xiě zhè běn shū de yuányīn.","vi":"Tác giả đã nói rõ lý do viết cuốn sách này trong lời mở đầu."},{"type":"compound","zh":"引言虽然只有一页，但是把整篇论文的思路讲得很清楚。","pinyin":"Yǐnyán suīrán zhǐyǒu yí yè, dànshì bǎ zhěng piān lùnwén de sīlù jiǎng de hěn qīngchu.","vi":"Lời dẫn nhập tuy chỉ có một trang, nhưng đã trình bày rất rõ hướng đi của toàn bộ luận văn."}],"related":[{"hanzi":"前言","pinyin":"qiányán","vi":"lời nói đầu"},{"hanzi":"序言","pinyin":"xùyán","vi":"lời tựa"},{"hanzi":"正文","pinyin":"zhèngwén","vi":"nội dung chính"},{"hanzi":"结语","pinyin":"jiéyǔ","vi":"lời kết"}]},{"id":"宇航员","hanzi":"宇航员","pinyin":"yǔhángyuán","meaning_vi":"phi hành gia","explanation":"宇 (vũ trụ/nhà cửa) + 航 (航) + 员 (员).","hsk_level":"7-9","tags":["danh-tu","nghe-nghiep","khoa-hoc"],"image":"👨‍🚀","examples":[{"type":"basic","zh":"他梦想当宇航员。","pinyin":"Tā mèngxiǎng dāng yǔhángyuán.","vi":"Cậu ấy mơ ước trở thành phi hành gia."},{"type":"simple","zh":"三名宇航员在空间站里工作了半年。","pinyin":"Sān míng yǔhángyuán zài kōngjiānzhàn lǐ gōngzuòle bàn nián.","vi":"Ba phi hành gia đã làm việc nửa năm trong trạm vũ trụ."},{"type":"compound","zh":"宇航员一回到地面，就被抬上了担架接受检查。","pinyin":"Yǔhángyuán yì huídào dìmiàn, jiù bèi tái shàngle dānjià jiēshòu jiǎnchá.","vi":"Phi hành gia vừa trở về mặt đất đã được khiêng lên cáng để kiểm tra sức khỏe."}],"related":[{"hanzi":"航天员","pinyin":"hángtiānyuán","vi":"phi hành gia"},{"hanzi":"太空","pinyin":"tàikōng","vi":"vũ trụ"},{"hanzi":"飞船","pinyin":"fēichuán","vi":"tàu vũ trụ"},{"hanzi":"空间站","pinyin":"kōngjiānzhàn","vi":"trạm vũ trụ"}],"traditional":"宇航員"},{"id":"与时俱进","hanzi":"与时俱进","pinyin":"yǔshí-jùjìn","meaning_vi":"tiến cùng thời đại, không ngừng đổi mới","explanation":"与 (và) + 时 (thời đại/thời cơ) + 俱 (俱) + 进 (vào).","hsk_level":"7-9","tags":["thanh-ngu","xa-hoi"],"image":"🚀","examples":[{"type":"basic","zh":"观念要与时俱进。","pinyin":"Guānniàn yào yǔshíjùjìn.","vi":"Quan niệm phải tiến cùng thời đại."},{"type":"simple","zh":"这本老字典每隔几年就会与时俱进地修订一次。","pinyin":"Zhè běn lǎo zìdiǎn měigé jǐ nián jiù huì yǔshíjùjìn de xiūdìng yí cì.","vi":"Cuốn từ điển lâu đời này cứ vài năm lại được hiệu đính để bắt kịp thời đại."},{"type":"compound","zh":"老字号如果不与时俱进，就会慢慢被年轻顾客遗忘。","pinyin":"Lǎozìhào rúguǒ bù yǔshíjùjìn, jiù huì mànmàn bèi niánqīng gùkè yíwàng.","vi":"Các thương hiệu lâu đời nếu không đổi mới theo thời đại sẽ dần bị khách hàng trẻ lãng quên."}],"related":[{"hanzi":"开拓创新","pinyin":"kāituòchuàngxīn","vi":"khai phá đổi mới"},{"hanzi":"紧跟时代","pinyin":"jǐngēnshídài","vi":"theo sát thời đại"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư lệ cũ"},{"hanzi":"故步自封","pinyin":"gùbùzìfēng","vi":"dậm chân tại chỗ"}],"traditional":"與時俱進"},{"id":"专利权","hanzi":"专利权","pinyin":"zhuānlìquán","meaning_vi":"quyền sáng chế","explanation":"专利 (chuyên lợi – bằng sáng chế) + 权 (quyền) → quyền độc quyền khai thác một sáng chế trong thời hạn nhất định. Đi với 申请, 侵犯.","hsk_level":"7-9","tags":["danh-tu","phap-luat","khoa-hoc"],"image":"⚙️","examples":[{"type":"basic","zh":"他拥有这项专利权。","pinyin":"Tā yōngyǒu zhè xiàng zhuānlìquán.","vi":"Ông ấy sở hữu quyền sáng chế này."},{"type":"simple","zh":"两家手机公司因为专利权问题打起了官司。","pinyin":"Liǎng jiā shǒujī gōngsī yīnwèi zhuānlìquán wèntí dǎ qǐle guānsi.","vi":"Hai công ty điện thoại đã kiện nhau vì vấn đề quyền sáng chế."},{"type":"compound","zh":"一旦专利权到期，其他厂家就可以生产同样的药品。","pinyin":"Yídàn zhuānlìquán dàoqī, qítā chǎngjiā jiù kěyǐ shēngchǎn tóngyàng de yàopǐn.","vi":"Một khi quyền sáng chế hết hạn, các nhà sản xuất khác có thể sản xuất loại thuốc tương tự."}],"related":[{"hanzi":"专利","pinyin":"zhuānlì","vi":"bằng sáng chế"},{"hanzi":"知识产权","pinyin":"zhīshichǎnquán","vi":"sở hữu trí tuệ"},{"hanzi":"著作权","pinyin":"zhùzuòquán","vi":"quyền tác giả"},{"hanzi":"商标权","pinyin":"shāngbiāoquán","vi":"quyền nhãn hiệu"}],"traditional":"專利權"},{"id":"专业化","hanzi":"专业化","pinyin":"zhuānyèhuà","meaning_vi":"chuyên nghiệp hóa","explanation":"专 (chuyên môn/chuyên gia) + 业 (sự nghiệp/ngành nghề) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"👔","examples":[{"type":"basic","zh":"服务越来越专业化。","pinyin":"Fúwù yuèláiyuè zhuānyèhuà.","vi":"Dịch vụ ngày càng chuyên nghiệp hóa."},{"type":"simple","zh":"这支球队走上了专业化的管理道路。","pinyin":"Zhè zhī qiúduì zǒushàngle zhuānyèhuà de guǎnlǐ dàolù.","vi":"Đội bóng này đã đi theo con đường quản lý chuyên nghiệp hóa."},{"type":"compound","zh":"因为家政行业越来越专业化，所以保姆也需要持证上岗。","pinyin":"Yīnwèi jiāzhèng hángyè yuèláiyuè zhuānyèhuà, suǒyǐ bǎomǔ yě xūyào chí zhèng shànggǎng.","vi":"Vì ngành giúp việc gia đình ngày càng chuyên nghiệp hóa nên người giúp việc cũng cần có chứng chỉ mới được làm."}],"related":[{"hanzi":"专业","pinyin":"zhuānyè","vi":"chuyên nghiệp"},{"hanzi":"职业化","pinyin":"zhíyèhuà","vi":"chuyên nghiệp hóa"},{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"quy chuẩn hóa"},{"hanzi":"分工","pinyin":"fēngōng","vi":"phân công"}],"traditional":"專業化"},{"id":"追溯","hanzi":"追溯","pinyin":"zhuīsù","meaning_vi":"truy nguyên, ngược dòng tìm về nguồn gốc","explanation":"追 (theo đuổi/truy cứu) + 溯 (truy nguyên/ngược dòng).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"⏪","examples":[{"type":"basic","zh":"这个传统可以追溯到唐朝。","pinyin":"Zhè ge chuántǒng kěyǐ zhuīsù dào Tángcháo.","vi":"Truyền thống này có thể truy nguyên về thời nhà Đường."},{"type":"simple","zh":"通过扫码，顾客可以追溯牛奶的产地。","pinyin":"Tōngguò sǎomǎ, gùkè kěyǐ zhuīsù niúnǎi de chǎndì.","vi":"Bằng cách quét mã, khách hàng có thể truy xuất nguồn gốc sữa."},{"type":"compound","zh":"如果追溯这个姓氏的来源，就会发现它和一个古国有关。","pinyin":"Rúguǒ zhuīsù zhè ge xìngshì de láiyuán, jiù huì fāxiàn tā hé yí gè gǔguó yǒuguān.","vi":"Nếu truy nguyên nguồn gốc của dòng họ này, sẽ phát hiện nó có liên quan đến một nước cổ."}],"related":[{"hanzi":"追根溯源","pinyin":"zhuīgēnsùyuán","vi":"truy tìm gốc rễ"},{"hanzi":"溯源","pinyin":"sùyuán","vi":"truy nguồn"},{"hanzi":"起源","pinyin":"qǐyuán","vi":"khởi nguồn"},{"hanzi":"回顾","pinyin":"huígù","vi":"nhìn lại"}]},{"id":"转发","hanzi":"转发","pinyin":"zhuǎnfā","meaning_vi":"chia sẻ lại bài viết (share/repost)","explanation":"转 (chuyển) + 发 (gửi).","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🔁","examples":[{"type":"basic","zh":"请帮我转发一下。","pinyin":"Qǐng bāng wǒ zhuǎnfā yíxià.","vi":"Làm ơn chia sẻ lại giúp tôi."},{"type":"simple","zh":"这条寻人启事被网友转发了十万多次。","pinyin":"Zhè tiáo xún rén qǐshì bèi wǎngyǒu zhuǎnfāle shíwàn duōcì.","vi":"Thông báo tìm người này đã được cư dân mạng chia sẻ lại hơn một trăm nghìn lần."},{"type":"compound","zh":"如果没有核实真假，就不要随便转发网上的消息。","pinyin":"Rúguǒ méiyǒu héshí zhēnjiǎ, jiù bú yào suíbiàn zhuǎnfā wǎngshàng de xiāoxi.","vi":"Nếu chưa xác minh thật giả thì đừng tùy tiện chia sẻ lại tin tức trên mạng."}],"related":[{"hanzi":"转载","pinyin":"zhuǎnzǎi","vi":"đăng lại"},{"hanzi":"分享","pinyin":"fēnxiǎng","vi":"chia sẻ"},{"hanzi":"点赞","pinyin":"diǎnzàn","vi":"thả tim"},{"hanzi":"评论","pinyin":"pínglùn","vi":"bình luận"}],"traditional":"轉發"},{"id":"转型升级","hanzi":"转型升级","pinyin":"zhuǎnxíngshēngjí","meaning_vi":"chuyển đổi mô hình và nâng cấp","explanation":"转型 (chuyển hình – chuyển đổi mô hình) + 升级 (thăng cấp – nâng cấp) → chuyển đổi cơ cấu và nâng cấp ngành nghề, doanh nghiệp lên trình độ cao hơn.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🚀","examples":[{"type":"basic","zh":"工厂正在转型升级。","pinyin":"Gōngchǎng zhèngzài zhuǎnxíngshēngjí.","vi":"Nhà máy đang chuyển đổi và nâng cấp."},{"type":"simple","zh":"这家老纺织厂通过引进机器人完成了转型升级。","pinyin":"Zhè jiālǎo fǎngzhīchǎng tōngguò yǐnjìn jīqìrén wánchéngle zhuǎnxíngshēngjí.","vi":"Nhà máy dệt lâu đời này đã hoàn thành chuyển đổi nâng cấp nhờ đưa robot vào."},{"type":"compound","zh":"传统书店如果不转型升级，就很难和网店竞争。","pinyin":"Chuántǒng shūdiàn rúguǒ bù zhuǎnxíngshēngjí, jiù hěn nán hé wǎngdiàn jìngzhēng.","vi":"Hiệu sách truyền thống nếu không chuyển đổi và nâng cấp thì rất khó cạnh tranh với cửa hàng trực tuyến."}],"related":[{"hanzi":"转型","pinyin":"zhuǎnxíng","vi":"chuyển đổi"},{"hanzi":"产业升级","pinyin":"chǎnyèshēngjí","vi":"nâng cấp ngành"},{"hanzi":"数字化转型","pinyin":"shùzìhuà zhuǎnxíng","vi":"chuyển đổi số"},{"hanzi":"结构调整","pinyin":"jiégòutiáozhěng","vi":"điều chỉnh cơ cấu"}],"traditional":"轉型升級"},{"id":"照会","hanzi":"照会","pinyin":"zhàohuì","meaning_vi":"công hàm ngoại giao","explanation":"照 (chiếu – thông báo) + 会 (hội – gặp, cho biết) → công hàm ngoại giao trao đổi giữa các chính phủ; cũng dùng làm động từ: gửi công hàm.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"📜","examples":[{"type":"basic","zh":"外交部发出了照会。","pinyin":"Wàijiāobù fāchūle zhàohuì.","vi":"Bộ Ngoại giao đã gửi công hàm."},{"type":"simple","zh":"大使馆向对方递交了一份正式照会。","pinyin":"Dàshǐguǎn xiàng duìfāng dìjiāole yí fèn zhèngshì zhàohuì.","vi":"Đại sứ quán đã trao cho phía bên kia một công hàm chính thức."},{"type":"compound","zh":"因为对方渔船多次越界，所以外交部提出了抗议照会。","pinyin":"Yīnwèi duìfāng yúchuán duōcì yuèjiè, suǒyǐ Wàijiāobù tíchūle kàngyì zhàohuì.","vi":"Vì tàu cá phía bên kia nhiều lần vượt ranh giới nên Bộ Ngoại giao đã gửi công hàm phản đối."}],"related":[{"hanzi":"外交","pinyin":"wàijiāo","vi":"ngoại giao"},{"hanzi":"公函","pinyin":"gōnghán","vi":"công văn"},{"hanzi":"大使馆","pinyin":"dàshǐguǎn","vi":"đại sứ quán"},{"hanzi":"抗议","pinyin":"kàngyì","vi":"phản đối"}],"traditional":"照會"},{"id":"正能量","hanzi":"正能量","pinyin":"zhèngnéngliàng","meaning_vi":"năng lượng tích cực","explanation":"正 (tích cực) + 能量 (năng lượng).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","cam-xuc"],"image":"☀️","examples":[{"type":"basic","zh":"他浑身充满正能量。","pinyin":"Tā húnshēn chōngmǎn zhèngnéngliàng.","vi":"Anh ấy tràn đầy năng lượng tích cực."},{"type":"simple","zh":"这个视频记录了外卖小哥救人的正能量故事。","pinyin":"Zhè ge shìpín jìlùle wàimài xiǎogē jiùrén de zhèngnéngliàng gùshi.","vi":"Video này ghi lại câu chuyện tích cực về anh giao đồ ăn cứu người."},{"type":"compound","zh":"只要多和乐观的人在一起，你就会被他们的正能量感染。","pinyin":"Zhǐyào duō hé lèguān de rén zài yìqǐ, nǐ jiù huì bèi tāmen de zhèngnéngliàng gǎnrǎn.","vi":"Chỉ cần ở bên những người lạc quan nhiều hơn, bạn sẽ được năng lượng tích cực của họ lan tỏa."}],"related":[{"hanzi":"负能量","pinyin":"fùnéngliàng","vi":"năng lượng tiêu cực"},{"hanzi":"积极","pinyin":"jījí","vi":"tích cực"},{"hanzi":"乐观","pinyin":"lèguān","vi":"lạc quan"},{"hanzi":"传递","pinyin":"chuándì","vi":"lan truyền"}]},{"id":"正文","hanzi":"正文","pinyin":"zhèngwén","meaning_vi":"nội dung chính (văn bản)","explanation":"正 (chính nghĩa/chính quy) + 文 (văn hóa/văn minh).","hsk_level":"7-9","tags":["danh-tu","hoc-tap"],"image":"📄","examples":[{"type":"basic","zh":"正文从第三页开始。","pinyin":"Zhèngwén cóng dì sān yè kāishǐ.","vi":"Phần nội dung chính bắt đầu từ trang ba."},{"type":"simple","zh":"邮件正文里附上了会议的详细安排。","pinyin":"Yóujiàn zhèngwén lǐ fùshàngle huìyì de xiángxì ānpái.","vi":"Trong nội dung chính của email có kèm lịch trình chi tiết của cuộc họp."},{"type":"compound","zh":"标题虽然很吸引人，但是正文的内容却非常空洞。","pinyin":"Biāotí suīrán hěn xīyǐnrén, dànshì zhèngwén de nèiróng què fēicháng kōngdòng.","vi":"Tiêu đề tuy rất hấp dẫn, nhưng nội dung phần chính lại vô cùng rỗng tuếch."}],"related":[{"hanzi":"标题","pinyin":"biāotí","vi":"tiêu đề"},{"hanzi":"附录","pinyin":"fùlù","vi":"phụ lục"},{"hanzi":"摘要","pinyin":"zhāiyào","vi":"tóm tắt"},{"hanzi":"引言","pinyin":"yǐnyán","vi":"lời mở đầu"}]},{"id":"质变","hanzi":"质变","pinyin":"zhìbiàn","meaning_vi":"biến đổi về chất (triết học)","explanation":"质 (chất lượng/bản chất) + 变 (变).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"✨","examples":[{"type":"basic","zh":"量变引起质变。","pinyin":"Liàngbiàn yǐnqǐ zhìbiàn.","vi":"Biến đổi về lượng dẫn đến biến đổi về chất."},{"type":"simple","zh":"坚持练习三年后，他的钢琴水平发生了质变。","pinyin":"Jiānchí liànxí sān nián hòu, tā de gāngqín shuǐpíng fāshēngle zhìbiàn.","vi":"Sau ba năm kiên trì luyện tập, trình độ piano của cậu ấy đã có bước nhảy vọt về chất."},{"type":"compound","zh":"只要量的积累足够多，就一定会引起质变。","pinyin":"Zhǐyào liàng de jīlěi zúgòu duō, jiù yídìng huì yǐnqǐ zhìbiàn.","vi":"Chỉ cần sự tích lũy về lượng đủ nhiều, nhất định sẽ dẫn đến biến đổi về chất."}],"related":[{"hanzi":"量变","pinyin":"liàngbiàn","vi":"biến đổi về lượng"},{"hanzi":"飞跃","pinyin":"fēiyuè","vi":"bước nhảy vọt"},{"hanzi":"变化","pinyin":"biànhuà","vi":"thay đổi"},{"hanzi":"量变引起质变","pinyin":"liàngbiàn yǐnqǐ zhìbiàn","vi":"lượng đổi chất đổi"}],"traditional":"質變"},{"id":"制度化","hanzi":"制度化","pinyin":"zhìdùhuà","meaning_vi":"thể chế hóa","explanation":"制 (chế độ/kiềm chế) + 度 (度) + 化 (化).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🏛️","examples":[{"type":"basic","zh":"管理要制度化。","pinyin":"Guǎnlǐ yào zhìdùhuà.","vi":"Quản lý cần được thể chế hóa."},{"type":"simple","zh":"公司把每周的安全检查制度化了。","pinyin":"Gōngsī bǎ měizhōu de ānquán jiǎnchá zhìdùhuà le.","vi":"Công ty đã thể chế hóa việc kiểm tra an toàn hằng tuần."},{"type":"compound","zh":"如果奖惩办法不制度化，员工就会觉得不公平。","pinyin":"Rúguǒ jiǎngchéng bànfǎ bú zhìdùhuà, yuángōng jiù huì juéde bù gōngpíng.","vi":"Nếu cách thưởng phạt không được thể chế hóa, nhân viên sẽ cảm thấy không công bằng."}],"related":[{"hanzi":"规范化","pinyin":"guīfànhuà","vi":"quy chuẩn hóa"},{"hanzi":"制度","pinyin":"zhìdù","vi":"chế độ"},{"hanzi":"法制化","pinyin":"fǎzhìhuà","vi":"pháp chế hóa"},{"hanzi":"标准化","pinyin":"biāozhǔnhuà","vi":"tiêu chuẩn hóa"}]},{"id":"智能化","hanzi":"智能化","pinyin":"zhìnénghuà","meaning_vi":"thông minh hóa","explanation":"智能 (trí tuệ thông minh) + 化.","hsk_level":"7-9","tags":["dong-tu","cong-nghe"],"image":"🧠","examples":[{"type":"basic","zh":"家电越来越智能化。","pinyin":"Jiādiàn yuèláiyuè zhìnénghuà.","vi":"Đồ điện gia dụng ngày càng thông minh hóa."},{"type":"simple","zh":"这座智能化仓库几乎不需要人工搬运。","pinyin":"Zhè zuò zhìnénghuà cāngkù jīhūbù xūyào réngōng bānyùn.","vi":"Nhà kho thông minh này hầu như không cần người khuân vác."},{"type":"compound","zh":"农业一旦实现智能化，农民用手机就能给庄稼浇水。","pinyin":"Nóngyè yídàn shíxiàn zhìnénghuà, nóng mínyòng shǒujī jiù néng gěi zhuāngjia jiāoshuǐ.","vi":"Một khi nông nghiệp được thông minh hóa, nông dân chỉ cần dùng điện thoại là có thể tưới nước cho cây trồng."}],"related":[{"hanzi":"智能","pinyin":"zhìnéng","vi":"thông minh"},{"hanzi":"自动化","pinyin":"zìdònghuà","vi":"tự động hóa"},{"hanzi":"信息化","pinyin":"xìnxīhuà","vi":"tin học hóa"},{"hanzi":"数字化","pinyin":"shùzìhuà","vi":"số hóa"}]},{"id":"制造业","hanzi":"制造业","pinyin":"zhìzàoyè","meaning_vi":"ngành sản xuất chế tạo","explanation":"制 (chế độ/kiềm chế) + 造 (sáng tạo/chế tạo) + 业 (sự nghiệp/ngành nghề).","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"🏭","examples":[{"type":"basic","zh":"这里制造业很发达。","pinyin":"Zhèlǐ zhìzàoyè hěn fādá.","vi":"Ngành sản xuất chế tạo ở đây rất phát triển."},{"type":"simple","zh":"越南的制造业吸引了不少外国工厂。","pinyin":"Yuènán de zhìzàoyè xīyǐnle bùshǎo wàiguó gōngchǎng.","vi":"Ngành sản xuất chế tạo của Việt Nam đã thu hút không ít nhà máy nước ngoài."},{"type":"compound","zh":"制造业虽然提供了大量岗位，但是很多年轻人更想去做直播。","pinyin":"Zhìzàoyè suīrán tígōngle dàliàng gǎngwèi, dànshì hěn duō niánqīngrén gèng xiǎng qù zuò zhíbō.","vi":"Ngành sản xuất tuy tạo ra rất nhiều việc làm, nhưng nhiều người trẻ lại muốn đi làm livestream hơn."}],"related":[{"hanzi":"服务业","pinyin":"fúwùyè","vi":"ngành dịch vụ"},{"hanzi":"工业","pinyin":"gōngyè","vi":"công nghiệp"},{"hanzi":"工厂","pinyin":"gōngchǎng","vi":"nhà máy"},{"hanzi":"实体经济","pinyin":"shítǐjīngjì","vi":"kinh tế thực"}],"traditional":"製造業"},{"id":"直播带货","hanzi":"直播带货","pinyin":"zhíbōdàihuò","meaning_vi":"livestream bán hàng","explanation":"直播 (trực bá – phát trực tiếp) + 带货 (đái hóa – kéo hàng, bán hàng) → bán hàng qua livestream, hình thức thương mại điện tử rất phổ biến ở TQ.","hsk_level":"7-9","tags":["dong-tu","cong-nghe","mua-sam"],"image":"🛍️","examples":[{"type":"basic","zh":"她靠直播带货赚钱。","pinyin":"Tā kào zhíbōdàihuò zhuànqián.","vi":"Cô ấy kiếm tiền bằng livestream bán hàng."},{"type":"simple","zh":"县长亲自走进直播间直播带货卖苹果。","pinyin":"Xiànzhǎng qīnzì zǒujìn zhíbōjiān zhíbōdàihuò mài píngguǒ.","vi":"Huyện trưởng đích thân vào phòng livestream để bán táo."},{"type":"compound","zh":"直播带货不但让农产品卖得更快，而且帮农民省掉了中间商。","pinyin":"Zhíbōdàihuò búdàn ràng nóngchǎnpǐn mài de gèng kuài, érqiě bāng nóngmín shěng diàole zhōngjiānshāng.","vi":"Livestream bán hàng không chỉ giúp nông sản bán nhanh hơn mà còn giúp nông dân bỏ qua khâu trung gian."}],"related":[{"hanzi":"直播","pinyin":"zhíbō","vi":"phát trực tiếp"},{"hanzi":"主播","pinyin":"zhǔbō","vi":"người dẫn livestream"},{"hanzi":"网红","pinyin":"wǎnghóng","vi":"người nổi tiếng mạng"},{"hanzi":"电商","pinyin":"diànshāng","vi":"thương mại điện tử"}],"traditional":"直播帶貨"},{"id":"执法","hanzi":"执法","pinyin":"zhífǎ","meaning_vi":"chấp pháp, thi hành pháp luật","explanation":"执 (thực thi) + 法.","hsk_level":"7-9","tags":["dong-tu","phap-luat","xa-hoi"],"image":"👮","examples":[{"type":"basic","zh":"警察正在执法。","pinyin":"Jǐngchá zhèngzài zhífǎ.","vi":"Cảnh sát đang thi hành pháp luật."},{"type":"simple","zh":"交警在路口严格执法，查处闯红灯的司机。","pinyin":"Jiāojǐng zài lùkǒu yángé zhífǎ, cháchǔ chuǎnghóngdēng de sījī.","vi":"Cảnh sát giao thông nghiêm khắc thi hành pháp luật tại giao lộ, xử lý tài xế vượt đèn đỏ."},{"type":"compound","zh":"如果执法人员自己都不守法，群众就不会信服。","pinyin":"Rúguǒ zhífǎ rényuán zìjǐ dōu bù shǒufǎ, qúnzhòng jiù bú huì xìnfú.","vi":"Nếu chính người thi hành pháp luật cũng không tuân thủ pháp luật, quần chúng sẽ không tin phục."}],"related":[{"hanzi":"执法人员","pinyin":"zhífǎrényuán","vi":"nhân viên chấp pháp"},{"hanzi":"司法","pinyin":"sīfǎ","vi":"tư pháp"},{"hanzi":"依法","pinyin":"yīfǎ","vi":"theo pháp luật"},{"hanzi":"执法如山","pinyin":"zhífǎrúshān","vi":"chấp pháp nghiêm minh"}],"traditional":"執法"},{"id":"植树造林","hanzi":"植树造林","pinyin":"zhíshùzàolín","meaning_vi":"trồng cây gây rừng","explanation":"植 (trồng trọt/thực vật) + 树 (xây dựng/cây cối) + 造 (sáng tạo/chế tạo) + 林 (rừng cây).","hsk_level":"7-9","tags":["dong-tu","thien-nhien"],"image":"🌲","examples":[{"type":"basic","zh":"春天适合植树造林。","pinyin":"Chūntiān shìhé zhíshùzàolín.","vi":"Mùa xuân thích hợp để trồng cây gây rừng."},{"type":"simple","zh":"当地村民在荒山上坚持植树造林几十年。","pinyin":"Dāngdì cūnmín zài huāngshān shang jiānchí zhíshùzàolín jǐ shí nián.","vi":"Người dân địa phương đã kiên trì trồng cây gây rừng trên đồi trọc suốt mấy chục năm."},{"type":"compound","zh":"因为几代人坚持植树造林，所以这片沙漠变成了绿洲。","pinyin":"Yīnwèi jǐdàirén jiānchí zhíshùzàolín, suǒyǐ zhè piàn shāmò biàn chéngle lǜzhōu.","vi":"Vì nhiều thế hệ kiên trì trồng cây gây rừng nên vùng sa mạc này đã trở thành ốc đảo."}],"related":[{"hanzi":"植树节","pinyin":"Zhíshùjié","vi":"ngày trồng cây"},{"hanzi":"绿化","pinyin":"lǜhuà","vi":"phủ xanh"},{"hanzi":"森林","pinyin":"sēnlín","vi":"rừng"},{"hanzi":"乱砍滥伐","pinyin":"luànkǎnlànfá","vi":"chặt phá bừa bãi"}],"traditional":"植樹造林"},{"id":"职业病","hanzi":"职业病","pinyin":"zhíyèbìng","meaning_vi":"bệnh nghề nghiệp","explanation":"职 (chức vụ/nghề nghiệp) + 业 (sự nghiệp/ngành nghề) + 病 (病).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","cong-viec"],"image":"💼","examples":[{"type":"basic","zh":"颈椎病是他的职业病。","pinyin":"Jǐngzhuībìng shì tā de zhíyèbìng.","vi":"Bệnh đốt sống cổ là bệnh nghề nghiệp của anh ấy."},{"type":"simple","zh":"老师们常见的职业病是嗓子发炎。","pinyin":"Lǎoshīmen chángjiàn de zhíyèbìng shì sǎngzi fāyán.","vi":"Bệnh nghề nghiệp thường gặp của giáo viên là viêm họng."},{"type":"compound","zh":"因为长期对着电脑工作，所以他得了干眼症这种职业病。","pinyin":"Yīnwèi chángqī duìzhe diànnǎo gōngzuò, suǒyǐ tā déle gānyǎnzhèng zhè zhǒng zhíyèbìng.","vi":"Vì làm việc trước máy tính trong thời gian dài nên anh ấy mắc bệnh khô mắt, một loại bệnh nghề nghiệp."}],"related":[{"hanzi":"职业","pinyin":"zhíyè","vi":"nghề nghiệp"},{"hanzi":"颈椎病","pinyin":"jǐngzhuībìng","vi":"bệnh đốt sống cổ"},{"hanzi":"工伤","pinyin":"gōngshāng","vi":"tai nạn lao động"},{"hanzi":"劳动保护","pinyin":"láodòngbǎohù","vi":"bảo hộ lao động"}],"traditional":"職業病"},{"id":"职业教育","hanzi":"职业教育","pinyin":"zhíyèjiàoyù","meaning_vi":"giáo dục nghề nghiệp","explanation":"职 (chức vụ/nghề nghiệp) + 业 (sự nghiệp/ngành nghề) + 教 (dạy) + 育 (giáo dục/nuôi dưỡng).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","cong-viec"],"image":"🛠️","examples":[{"type":"basic","zh":"职业教育很受重视。","pinyin":"Zhíyèjiàoyù hěn shòu zhòngshì.","vi":"Giáo dục nghề nghiệp rất được coi trọng."},{"type":"simple","zh":"他在职业教育学校学会了汽车维修。","pinyin":"Tā zài zhíyèjiàoyù xuéxiào xuéhuìle qìchē wéixiū.","vi":"Cậu ấy đã học được nghề sửa ô tô ở trường giáo dục nghề nghiệp."},{"type":"compound","zh":"职业教育既能教会学生技能，又能帮他们尽快找到工作。","pinyin":"Zhíyèjiàoyù jì néng jiāohuì xuéshēng jìnéng, yòu néng bāng tāmen jǐnkuài zhǎodào gōngzuò.","vi":"Giáo dục nghề nghiệp vừa dạy cho học sinh kỹ năng, vừa giúp các em nhanh chóng tìm được việc làm."}],"related":[{"hanzi":"职业学校","pinyin":"zhíyèxuéxiào","vi":"trường nghề"},{"hanzi":"技能","pinyin":"jìnéng","vi":"kỹ năng"},{"hanzi":"培训","pinyin":"péixùn","vi":"đào tạo"},{"hanzi":"高等教育","pinyin":"gāoděngjiàoyù","vi":"giáo dục đại học"}],"traditional":"職業教育"},{"id":"仲裁","hanzi":"仲裁","pinyin":"zhòngcái","meaning_vi":"trọng tài (giải quyết tranh chấp thương mại/lao động)","explanation":"仲 + 裁 (phán xét).","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"⚖️","examples":[{"type":"basic","zh":"双方申请了仲裁。","pinyin":"Shuāngfāng shēnqǐngle zhòngcái.","vi":"Hai bên đã nộp đơn yêu cầu trọng tài."},{"type":"simple","zh":"劳动仲裁委员会裁定公司补发工资。","pinyin":"Láodòng zhòngcái wěiyuánhuì cáidìng gōngsī bǔfā gōngzī.","vi":"Hội đồng trọng tài lao động phán quyết công ty phải trả bù tiền lương."},{"type":"compound","zh":"如果双方协商不成，就只能把合同纠纷提交仲裁。","pinyin":"Rúguǒ shuāngfāng xiéshāng bùchéng, jiù zhǐnéng bǎ hétong jiūfēn tíjiāo zhòngcái.","vi":"Nếu hai bên thương lượng không thành, chỉ có thể đưa tranh chấp hợp đồng ra trọng tài."}],"related":[{"hanzi":"调解","pinyin":"tiáojiě","vi":"hòa giải"},{"hanzi":"诉讼","pinyin":"sùsòng","vi":"tố tụng"},{"hanzi":"纠纷","pinyin":"jiūfēn","vi":"tranh chấp"},{"hanzi":"裁决","pinyin":"cáijué","vi":"phán quyết"}]},{"id":"重逢","hanzi":"重逢","pinyin":"chóngféng","meaning_vi":"tái ngộ, gặp lại sau thời gian dài","explanation":"重 (nặng) + 逢 (gặp).","hsk_level":"7-9","tags":["dong-tu","giao-tiep"],"image":"🤗","examples":[{"type":"basic","zh":"老同学终于重逢了。","pinyin":"Lǎo tóngxué zhōngyú chóngféng le.","vi":"Những người bạn học cũ cuối cùng đã gặp lại nhau."},{"type":"simple","zh":"失散多年的姐妹在机场重逢时抱头痛哭。","pinyin":"Shīsàn duōnián de jiěmèi zài jīchǎng chóngféng shí bàotóu tòngkū.","vi":"Hai chị em thất lạc nhiều năm ôm nhau khóc nức nở khi gặp lại ở sân bay."},{"type":"compound","zh":"虽然分别了二十年，但是重逢那一刻我们一眼就认出了对方。","pinyin":"Suīrán fēnbiéle èrshí nián, dànshì chóngféng nà yíkè wǒmen yìyǎn jiù rènchūle duìfāng.","vi":"Tuy đã xa cách hai mươi năm, nhưng khoảnh khắc gặp lại chúng tôi nhận ra nhau ngay lập tức."}],"related":[{"hanzi":"久别重逢","pinyin":"jiǔbiéchóngféng","vi":"gặp lại sau bao năm"},{"hanzi":"相逢","pinyin":"xiāngféng","vi":"gặp nhau"},{"hanzi":"团聚","pinyin":"tuánjù","vi":"đoàn tụ"},{"hanzi":"离别","pinyin":"líbié","vi":"ly biệt"}]},{"id":"助学金","hanzi":"助学金","pinyin":"zhùxuéjīn","meaning_vi":"trợ cấp học tập (cho sinh viên khó khăn)","explanation":"助学 (trợ học – giúp việc học) + 金 (kim – tiền) → tiền trợ cấp cho học sinh, sinh viên có hoàn cảnh khó khăn. Phân biệt 奖学金 (học bổng thành tích).","hsk_level":"7-9","tags":["danh-tu","hoc-tap","tien-te"],"image":"🤝","examples":[{"type":"basic","zh":"她申请了助学金。","pinyin":"Tā shēnqǐngle zhùxuéjīn.","vi":"Cô ấy đã nộp đơn xin trợ cấp học tập."},{"type":"simple","zh":"这笔助学金帮他交了一年的住宿费。","pinyin":"Zhè bǐ zhùxuéjīn bāng tā jiāole yì nián de zhùsùfèi.","vi":"Khoản trợ cấp học tập này đã giúp cậu ấy đóng tiền ký túc xá một năm."},{"type":"compound","zh":"只要家庭经济困难并且成绩合格，学生就可以申请助学金。","pinyin":"Zhǐyào jiātíng jīngjì kùnnan bìngqiě chéngjì hégé, xuéshēng jiù kěyǐ shēnqǐng zhùxuéjīn.","vi":"Chỉ cần gia đình khó khăn về kinh tế và học lực đạt yêu cầu, sinh viên có thể xin trợ cấp học tập."}],"related":[{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","vi":"học bổng"},{"hanzi":"助学贷款","pinyin":"zhùxuédàikuǎn","vi":"khoản vay học tập"},{"hanzi":"学费","pinyin":"xuéfèi","vi":"học phí"},{"hanzi":"资助","pinyin":"zīzhù","vi":"tài trợ"}],"traditional":"助學金"},{"id":"著作权","hanzi":"著作权","pinyin":"zhùzuòquán","meaning_vi":"quyền tác giả, bản quyền","explanation":"著作 (trứ tác – tác phẩm) + 权 (quyền) → quyền tác giả đối với tác phẩm văn học, nghệ thuật, khoa học; tương đương 版权.","hsk_level":"7-9","tags":["danh-tu","phap-luat","van-hoa"],"image":"📚","examples":[{"type":"basic","zh":"他侵犯了著作权。","pinyin":"Tā qīnfànle zhùzuòquán.","vi":"Anh ta đã xâm phạm quyền tác giả."},{"type":"simple","zh":"出版社花高价买下了这部小说的著作权。","pinyin":"Chūbǎnshè huā gāojià mǎixiàle zhè bù xiǎoshuō de zhùzuòquán.","vi":"Nhà xuất bản đã bỏ giá cao mua bản quyền tác giả của cuốn tiểu thuyết này."},{"type":"compound","zh":"即使只是在视频里用了几秒钟音乐，也可能涉及著作权问题。","pinyin":"Jíshǐ zhǐshì zài shìpín lǐ yòngle jǐ miǎozhōng yīnyuè, yě kěnéng shèjí zhùzuòquán wèntí.","vi":"Dù chỉ dùng vài giây nhạc trong video, cũng có thể liên quan đến vấn đề bản quyền."}],"related":[{"hanzi":"版权","pinyin":"bǎnquán","vi":"bản quyền"},{"hanzi":"知识产权","pinyin":"zhīshichǎnquán","vi":"sở hữu trí tuệ"},{"hanzi":"盗版","pinyin":"dàobǎn","vi":"lậu, vi phạm bản quyền"},{"hanzi":"专利权","pinyin":"zhuānlìquán","vi":"quyền sáng chế"}],"traditional":"著作權"},{"id":"招商引资","hanzi":"招商引资","pinyin":"zhāoshāngyǐnzī","meaning_vi":"thu hút đầu tư thương mại","explanation":"招商 + 引资. Thành ngữ kinh tế.","hsk_level":"7-9","tags":["dong-tu","cong-viec"],"image":"🤝","examples":[{"type":"basic","zh":"县里忙着招商引资。","pinyin":"Xiàn lǐ mángzhe zhāoshāngyǐnzī.","vi":"Huyện đang bận rộn thu hút đầu tư."},{"type":"simple","zh":"市长带队去深圳招商引资。","pinyin":"Shìzhǎng dàiduì qù Shēnzhèn zhāoshāngyǐnzī.","vi":"Thị trưởng dẫn đoàn đến Thâm Quyến để thu hút đầu tư."},{"type":"compound","zh":"只要交通和配套设施跟上了，招商引资就会容易很多。","pinyin":"Zhǐyào jiāotōng hé pèitào shèshī gēnshàng le, zhāoshāngyǐnzī jiù huì róngyì hěn duō.","vi":"Chỉ cần giao thông và cơ sở hạ tầng đi kèm theo kịp, việc thu hút đầu tư sẽ dễ dàng hơn nhiều."}],"related":[{"hanzi":"投资","pinyin":"tóuzī","vi":"đầu tư"},{"hanzi":"外资","pinyin":"wàizī","vi":"vốn nước ngoài"},{"hanzi":"营商环境","pinyin":"yíngshānghuánjìng","vi":"môi trường kinh doanh"},{"hanzi":"开发区","pinyin":"kāifāqū","vi":"khu phát triển"}],"traditional":"招商引資"},{"id":"朝思暮想","hanzi":"朝思暮想","pinyin":"zhāosī-mùxiǎng","meaning_vi":"ngày nhớ đêm mong","explanation":"朝思 (sáng nghĩ) + 暮想 (tối nhớ). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","cam-xuc"],"image":"💭","examples":[{"type":"basic","zh":"这是我朝思暮想的家乡。","pinyin":"Zhè shì wǒ zhāosīmùxiǎng de jiāxiāng.","vi":"Đây là quê hương mà tôi ngày nhớ đêm mong."},{"type":"simple","zh":"他终于买到了朝思暮想的那把吉他。","pinyin":"Tā zhōngyú mǎi dàole zhāosīmùxiǎng de nà bǎ jítā.","vi":"Cuối cùng cậu ấy đã mua được cây đàn guitar mà cậu ngày nhớ đêm mong."},{"type":"compound","zh":"母亲朝思暮想的儿子一进家门，她就哭了出来。","pinyin":"Mǔqīn zhāosīmùxiǎng de érzi yí jìn jiāmén, tā jiù kūle chūlái.","vi":"Đứa con trai mà người mẹ ngày nhớ đêm mong vừa bước vào nhà, bà đã bật khóc."}],"related":[{"hanzi":"日思夜想","pinyin":"rìsīyèxiǎng","vi":"ngày nhớ đêm mong"},{"hanzi":"思念","pinyin":"sīniàn","vi":"nhớ nhung"},{"hanzi":"魂牵梦萦","pinyin":"húnqiānmèngyíng","vi":"nhớ nhung da diết"},{"hanzi":"牵挂","pinyin":"qiānguà","vi":"vương vấn"}]},{"id":"针灸","hanzi":"针灸","pinyin":"zhēnjiǔ","meaning_vi":"châm cứu","explanation":"针 (kim châm) + 灸 (cứu ngải).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","van-hoa"],"image":"💉","examples":[{"type":"basic","zh":"我试过针灸治疗。","pinyin":"Wǒ shìguo zhēnjiǔ zhìliáo.","vi":"Tôi đã từng thử điều trị bằng châm cứu."},{"type":"simple","zh":"医生用针灸帮他缓解了多年的腰痛。","pinyin":"Yīshēng yòng zhēnjiǔ bāng tā huǎnjiěle duōnián de yāo tòng.","vi":"Bác sĩ dùng châm cứu giúp ông ấy giảm cơn đau lưng nhiều năm."},{"type":"compound","zh":"虽然第一次针灸时很紧张，但是她发现其实并不疼。","pinyin":"Suīrán dìyīcì zhēnjiǔ shí hěn jǐnzhāng, dànshì tā fāxiàn qíshí bìngbù téng.","vi":"Tuy lần đầu châm cứu rất căng thẳng, nhưng cô ấy phát hiện thực ra chẳng hề đau."}],"related":[{"hanzi":"穴位","pinyin":"xuéwèi","vi":"huyệt vị"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"},{"hanzi":"推拿","pinyin":"tuīná","vi":"xoa bóp bấm huyệt"},{"hanzi":"拔罐","pinyin":"báguàn","vi":"giác hơi"}],"traditional":"針灸"},{"id":"真抓实干","hanzi":"真抓实干","pinyin":"zhēnzhuā-shígàn","meaning_vi":"bắt tay làm thật hiệu quả thực chất","explanation":"真 (thật) + 抓 (nắm bắt) + 实 (thực tế/thực chất) + 干 (干).","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"💪","examples":[{"type":"basic","zh":"干部要真抓实干。","pinyin":"Gànbù yào zhēn zhuā shígàn.","vi":"Cán bộ phải bắt tay làm thật, làm thực chất."},{"type":"simple","zh":"新来的村长靠真抓实干赢得了村民的信任。","pinyin":"Xīn lái de cūnzhǎng kào zhēn zhuā shígàn yíng déle cūnmín de xìnrèn.","vi":"Trưởng thôn mới đến đã giành được lòng tin của dân làng nhờ làm việc thực chất."},{"type":"compound","zh":"只有真抓实干，纸上的计划才能变成现实。","pinyin":"Zhǐyǒu zhēn zhuā shígàn, zhǐ shang de jìhuà cáinéng biànchéng xiànshí.","vi":"Chỉ có bắt tay làm thật, kế hoạch trên giấy mới trở thành hiện thực."}],"related":[{"hanzi":"实干","pinyin":"shígàn","vi":"làm thực chất"},{"hanzi":"脚踏实地","pinyin":"jiǎotàshídì","vi":"chân đạp đất thực"},{"hanzi":"雷厉风行","pinyin":"léilìfēngxíng","vi":"nhanh gọn quyết liệt"},{"hanzi":"弄虚作假","pinyin":"nòngxūzuòjiǎ","vi":"làm giả dối"}],"traditional":"真抓實幹"},{"id":"知难而进","hanzi":"知难而进","pinyin":"zhīnán-érjìn","meaning_vi":"biết khó vẫn tiến lên","explanation":"知难而进: biết (知) khó khăn (难) mà (而) vẫn tiến lên (进) → không sợ gian khó, dũng cảm vượt qua. Trái nghĩa với 知难而退.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🧗","examples":[{"type":"basic","zh":"他总是知难而进。","pinyin":"Tā zǒngshì zhīnán'érjìn.","vi":"Anh ấy luôn biết khó vẫn tiến lên."},{"type":"simple","zh":"这群科研人员在极地知难而进地完成了考察。","pinyin":"Zhè qún kēyán rényuán zài jídì zhīnán'érjìn de wánchéngle kǎochá.","vi":"Nhóm nhà nghiên cứu này đã biết khó vẫn tiến, hoàn thành chuyến khảo sát ở vùng cực."},{"type":"compound","zh":"即使明知前路艰险，登山队员们也知难而进。","pinyin":"Jíshǐ míngzhī qiánlù jiānxiǎn, dēngshān duìyuánmen yě zhīnán'érjìn.","vi":"Dù biết rõ con đường phía trước gian nguy, các thành viên đoàn leo núi vẫn biết khó mà tiến."}],"related":[{"hanzi":"迎难而上","pinyin":"yíngnán'érshàng","vi":"đón khó mà tiến"},{"hanzi":"知难而退","pinyin":"zhīnán'értuì","vi":"biết khó mà lui"},{"hanzi":"勇往直前","pinyin":"yǒngwǎngzhíqián","vi":"dũng cảm tiến lên"},{"hanzi":"百折不挠","pinyin":"bǎizhébùnáo","vi":"kiên cường bất khuất"}],"traditional":"知難而進"},{"id":"知识产权","hanzi":"知识产权","pinyin":"zhīshichǎnquán","meaning_vi":"quyền sở hữu trí tuệ","explanation":"知识 (tri thức) + 产权 (sản quyền – quyền sở hữu tài sản) → quyền sở hữu trí tuệ, gồm 专利权, 商标权, 著作权.","hsk_level":"7-9","tags":["danh-tu","phap-luat","cong-viec"],"image":"💡","examples":[{"type":"basic","zh":"要尊重知识产权。","pinyin":"Yào zūnzhòng zhīshichǎnquán.","vi":"Phải tôn trọng quyền sở hữu trí tuệ."},{"type":"simple","zh":"这位设计师为自己的原创图案申请了知识产权保护。","pinyin":"Zhè wèi shèjìshī wèi zìjǐ de yuánchuàng tú'àn shēnqǐngle zhīshichǎnquán bǎohù.","vi":"Nhà thiết kế này đã đăng ký bảo hộ quyền sở hữu trí tuệ cho họa tiết sáng tạo của mình."},{"type":"compound","zh":"如果不保护知识产权，就没有人愿意花钱搞研发了。","pinyin":"Rúguǒ bù bǎohù zhīshichǎnquán, jiù méiyǒu rén yuànyì huāqián gǎo yánfā le.","vi":"Nếu không bảo vệ quyền sở hữu trí tuệ thì sẽ chẳng ai muốn bỏ tiền làm nghiên cứu phát triển nữa."}],"related":[{"hanzi":"专利","pinyin":"zhuānlì","vi":"bằng sáng chế"},{"hanzi":"商标","pinyin":"shāngbiāo","vi":"nhãn hiệu"},{"hanzi":"版权","pinyin":"bǎnquán","vi":"bản quyền"},{"hanzi":"侵权","pinyin":"qīnquán","vi":"xâm phạm quyền"}],"traditional":"知識產權"},{"id":"中等收入","hanzi":"中等收入","pinyin":"zhōngděngshōurù","meaning_vi":"thu nhập trung bình","explanation":"中 (giữa) + 等 (đợi) + 收 (nhận) + 入 (nhập vào/sâu sắc).","hsk_level":"7-9","tags":["danh-tu","tien-te","xa-hoi"],"image":"📊","examples":[{"type":"basic","zh":"他家属于中等收入。","pinyin":"Tā jiā shǔyú zhōngděngshōurù.","vi":"Nhà anh ấy thuộc mức thu nhập trung bình."},{"type":"simple","zh":"中等收入家庭最关心的是房贷和孩子教育。","pinyin":"Zhōngděngshōurù jiātíng zuì guānxīn de shì fángdài hé háizi jiàoyù.","vi":"Điều các gia đình thu nhập trung bình quan tâm nhất là khoản vay mua nhà và việc học của con."},{"type":"compound","zh":"如果中等收入群体不断扩大，国内消费市场就会更有活力。","pinyin":"Rúguǒ zhōngděngshōurù qúntǐ búduàn kuòdà, guónèi xiāofèi shìchǎng jiù huì gèng yǒuhuólì.","vi":"Nếu nhóm người thu nhập trung bình không ngừng mở rộng, thị trường tiêu dùng trong nước sẽ càng sôi động."}],"related":[{"hanzi":"高收入","pinyin":"gāoshōurù","vi":"thu nhập cao"},{"hanzi":"低收入","pinyin":"dīshōurù","vi":"thu nhập thấp"},{"hanzi":"中产阶级","pinyin":"zhōngchǎnjiējí","vi":"tầng lớp trung lưu"},{"hanzi":"收入","pinyin":"shōurù","vi":"thu nhập"}]},{"id":"中国结","hanzi":"中国结","pinyin":"zhōngguójié","meaning_vi":"nút thắt cát tường Trung Hoa","explanation":"中国 + 结 (nút thắt).","hsk_level":"7-9","tags":["danh-tu","van-hoa","do-vat"],"image":"🧧","examples":[{"type":"basic","zh":"门上挂着中国结。","pinyin":"Mén shang guàzhe zhōngguójié.","vi":"Trên cửa treo một chiếc nút thắt Trung Hoa."},{"type":"simple","zh":"奶奶用红绳给我编了一个小小的中国结。","pinyin":"Nǎinai yòng hóngshéng gěi wǒ biānle yí gè xiǎoxiǎo de zhōngguójié.","vi":"Bà nội dùng sợi dây đỏ thắt cho tôi một chiếc nút thắt Trung Hoa nho nhỏ."},{"type":"compound","zh":"每到春节，商场里就挂满了大大小小的中国结。","pinyin":"Měi dào Chūnjié, shāngchǎng lǐ jiù guà mǎnle dàdà xiǎoxiǎo de zhōngguójié.","vi":"Cứ đến Tết, trung tâm thương mại lại treo đầy những chiếc nút thắt Trung Hoa lớn nhỏ."}],"related":[{"hanzi":"红绳","pinyin":"hóngshéng","vi":"dây đỏ"},{"hanzi":"吉祥","pinyin":"jíxiáng","vi":"cát tường"},{"hanzi":"手工艺","pinyin":"shǒugōngyì","vi":"thủ công mỹ nghệ"},{"hanzi":"剪纸","pinyin":"jiǎnzhǐ","vi":"cắt giấy"}],"traditional":"中國結"},{"id":"中华文明","hanzi":"中华文明","pinyin":"zhōnghuáwénmíng","meaning_vi":"nền văn minh Trung Hoa","explanation":"中华 (Trung Hoa) + 文明 (văn minh) → nền văn minh Trung Hoa, một trong những nền văn minh cổ nhất thế giới, kéo dài liên tục hàng nghìn năm.","hsk_level":"7-9","tags":["danh-tu","van-hoa"],"image":"🏯","examples":[{"type":"basic","zh":"中华文明历史悠久。","pinyin":"Zhōnghuáwénmíng lìshǐ yōujiǔ.","vi":"Nền văn minh Trung Hoa có lịch sử lâu đời."},{"type":"simple","zh":"这座博物馆展示了中华文明五千年的发展历程。","pinyin":"Zhè zuò bówùguǎn zhǎnshìle zhōnghuáwénmíng wǔqiānnián de fāzhǎn lìchéng.","vi":"Bảo tàng này trưng bày quá trình phát triển năm nghìn năm của nền văn minh Trung Hoa."},{"type":"compound","zh":"因为汉字一直延续使用，所以中华文明的文献保存得比较完整。","pinyin":"Yīnwèi hànzì yìzhí yánxù shǐyòng, suǒyǐ zhōnghuáwénmíng de wénxiàn bǎocún de bǐjiào wánzhěng.","vi":"Vì chữ Hán được sử dụng liên tục nên văn hiến của nền văn minh Trung Hoa được lưu giữ khá đầy đủ."}],"related":[{"hanzi":"中华民族","pinyin":"Zhōnghuámínzú","vi":"dân tộc Trung Hoa"},{"hanzi":"传统文化","pinyin":"chuántǒngwénhuà","vi":"văn hóa truyền thống"},{"hanzi":"黄河","pinyin":"Huánghé","vi":"Hoàng Hà"},{"hanzi":"五千年","pinyin":"wǔqiānnián","vi":"năm nghìn năm"}],"traditional":"中華文明"},{"id":"终身学习","hanzi":"终身学习","pinyin":"zhōngshēnxuéxí","meaning_vi":"học tập suốt đời","explanation":"终 (cuối cùng/suốt đời) + 身 (thân phận/tự thân) + 学 (học thuật/học thuyết) + 习 (thói quen/học tập).","hsk_level":"7-9","tags":["dong-tu","hoc-tap"],"image":"📚","examples":[{"type":"basic","zh":"我们要终身学习。","pinyin":"Wǒmen yào zhōngshēnxuéxí.","vi":"Chúng ta phải học tập suốt đời."},{"type":"simple","zh":"七十岁的外婆用实际行动诠释了终身学习。","pinyin":"Qīshí suì de wàipó yòng shíjì xíngdòng quánshìle zhōngshēnxuéxí.","vi":"Bà ngoại bảy mươi tuổi đã dùng hành động thực tế để minh chứng cho việc học tập suốt đời."},{"type":"compound","zh":"既然技术更新得这么快，终身学习就成了每个人的必修课。","pinyin":"Jìrán jìshù gēngxīn de zhème kuài, zhōngshēnxuéxí jiù chéngle měigèrén de bìxiūkè.","vi":"Công nghệ đã đổi mới nhanh như vậy thì học tập suốt đời trở thành môn học bắt buộc của mỗi người."}],"related":[{"hanzi":"终身","pinyin":"zhōngshēn","vi":"suốt đời"},{"hanzi":"活到老学到老","pinyin":"huó dào lǎo xuédào lǎo","vi":"học đến già"},{"hanzi":"自学","pinyin":"zìxué","vi":"tự học"},{"hanzi":"继续教育","pinyin":"jìxùjiàoyù","vi":"giáo dục thường xuyên"}],"traditional":"終身學習"},{"id":"中旬","hanzi":"中旬","pinyin":"zhōngxún","meaning_vi":"trung tuần (10 ngày giữa tháng)","explanation":"中 (giữa) + 旬 (tuần (10 ngày)/tuổi).","hsk_level":"7-9","tags":["danh-tu","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"下月中旬放假。","pinyin":"Xiàyuè zhōngxún fàngjià.","vi":"Trung tuần tháng sau được nghỉ."},{"type":"simple","zh":"我们计划在五月中旬去云南旅行。","pinyin":"Wǒmen jìhuà zài Wǔyuè zhōngxún qù Yúnnán lǚxíng.","vi":"Chúng tôi dự định đi du lịch Vân Nam vào trung tuần tháng Năm."},{"type":"compound","zh":"如果中旬还收不到货款，我们就只能暂停发货了。","pinyin":"Rúguǒ zhōngxún hái shōu búdào huòkuǎn, wǒmen jiù zhǐnéng zàntíng fāhuò le.","vi":"Nếu đến trung tuần mà vẫn chưa nhận được tiền hàng, chúng tôi chỉ có thể tạm dừng giao hàng."}],"related":[{"hanzi":"上旬","pinyin":"shàngxún","vi":"thượng tuần"},{"hanzi":"下旬","pinyin":"xiàxún","vi":"hạ tuần"},{"hanzi":"月中","pinyin":"yuèzhōng","vi":"giữa tháng"},{"hanzi":"月底","pinyin":"yuèdǐ","vi":"cuối tháng"}]},{"id":"中药","hanzi":"中药","pinyin":"zhōngyào","meaning_vi":"thuốc Đông y, thuốc Bắc","explanation":"中 (Trung – Trung Quốc) + 药 (dược – thuốc) → thuốc Đông y, thuốc Bắc làm từ thảo mộc, khoáng vật. Đối lập: 西药 (thuốc Tây).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","van-hoa"],"image":"🌿","examples":[{"type":"basic","zh":"这碗中药很苦。","pinyin":"Zhè wǎn zhōngyào hěn kǔ.","vi":"Bát thuốc Bắc này rất đắng."},{"type":"simple","zh":"妈妈每天晚上都在厨房里熬中药。","pinyin":"Māma měitiān wǎnshang dōu zài chúfáng lǐ áo zhōngyào.","vi":"Tối nào mẹ cũng sắc thuốc Bắc trong bếp."},{"type":"compound","zh":"中药虽然见效比较慢，但是对调理身体很有帮助。","pinyin":"Zhōngyào suīrán jiànxiào bǐjiào màn, dànshì duì tiáolǐ shēntǐ hěn yǒubāngzhù.","vi":"Thuốc Bắc tuy có tác dụng khá chậm, nhưng rất có ích cho việc điều dưỡng cơ thể."}],"related":[{"hanzi":"西药","pinyin":"xīyào","vi":"thuốc Tây"},{"hanzi":"草药","pinyin":"cǎoyào","vi":"thảo dược"},{"hanzi":"中医","pinyin":"zhōngyī","vi":"Đông y"},{"hanzi":"药方","pinyin":"yàofāng","vi":"đơn thuốc"}],"traditional":"中藥"},{"id":"中医","hanzi":"中医","pinyin":"zhōngyī","meaning_vi":"Đông y, y học cổ truyền Trung Hoa","explanation":"中 + 医 (y học). Đối ứng với 西医 (Tây y).","hsk_level":"7-9","tags":["danh-tu","suc-khoe","van-hoa"],"image":"🌿","examples":[{"type":"basic","zh":"他是一位老中医。","pinyin":"Tā shì yí wèi lǎo zhōngyī.","vi":"Ông ấy là một thầy thuốc Đông y lâu năm."},{"type":"simple","zh":"中医通过把脉来判断病人的身体状况。","pinyin":"Zhōngyī tōngguò bǎ mài lái pànduàn bìngrén de shēntǐ zhuàngkuàng.","vi":"Đông y chẩn đoán tình trạng sức khỏe bệnh nhân bằng cách bắt mạch."},{"type":"compound","zh":"很多外国留学生不但对中医感兴趣，而且专门来中国学习。","pinyin":"Hěn duō wàiguó liúxuéshēng búdàn duì zhōngyī gǎnxìngqù, érqiě zhuānmén lái Zhōngguó xuéxí.","vi":"Nhiều du học sinh nước ngoài không chỉ có hứng thú với Đông y mà còn đặc biệt sang Trung Quốc để học."}],"related":[{"hanzi":"西医","pinyin":"xīyī","vi":"Tây y"},{"hanzi":"中药","pinyin":"zhōngyào","vi":"thuốc Bắc"},{"hanzi":"针灸","pinyin":"zhēnjiǔ","vi":"châm cứu"},{"hanzi":"把脉","pinyin":"bǎmài","vi":"bắt mạch"}],"traditional":"中醫"},{"id":"止痛药","hanzi":"止痛药","pinyin":"zhǐtòngyào","meaning_vi":"thuốc giảm đau","explanation":"止 (ngăn chặn/dừng lại) + 痛 (đau xót/quyết tâm) + 药 (thuốc).","hsk_level":"7-9","tags":["danh-tu","suc-khoe"],"image":"💊","examples":[{"type":"basic","zh":"他吃了止痛药。","pinyin":"Tā chīle zhǐtòngyào.","vi":"Anh ấy đã uống thuốc giảm đau."},{"type":"simple","zh":"她的包里总是备着一盒止痛药。","pinyin":"Tā de bāo lǐ zǒngshì bèizhe yì hé zhǐtòngyào.","vi":"Trong túi cô ấy lúc nào cũng có sẵn một hộp thuốc giảm đau."},{"type":"compound","zh":"止痛药虽然能暂时缓解头痛，但是不能解决根本问题。","pinyin":"Zhǐtòngyào suīrán néng zànshí huǎnjiě tóutòng, dànshì bù néng jiějué gēnběn wèntí.","vi":"Thuốc giảm đau tuy có thể tạm thời làm dịu cơn đau đầu, nhưng không giải quyết được vấn đề gốc rễ."}],"related":[{"hanzi":"止痛","pinyin":"zhǐtòng","vi":"giảm đau"},{"hanzi":"消炎药","pinyin":"xiāoyányào","vi":"thuốc chống viêm"},{"hanzi":"退烧药","pinyin":"tuìshāoyào","vi":"thuốc hạ sốt"},{"hanzi":"头痛","pinyin":"tóutòng","vi":"đau đầu"}],"traditional":"止痛藥"},{"id":"主权国家","hanzi":"主权国家","pinyin":"Zhǔquánguójiā","meaning_vi":"quốc gia có chủ quyền","explanation":"主权 (chủ quyền) + 国家 (quốc gia) → quốc gia độc lập, có toàn quyền quyết định công việc đối nội và đối ngoại.","hsk_level":"7-9","tags":["danh-tu","xa-hoi","dia-danh"],"image":"🌍","examples":[{"type":"basic","zh":"这是一个主权国家。","pinyin":"Zhè shì yí gè Zhǔquánguójiā.","vi":"Đây là một quốc gia có chủ quyền."},{"type":"simple","zh":"联合国的成员都是主权国家。","pinyin":"Liánhéguó de chéngyuán dōu shì Zhǔquánguójiā.","vi":"Các thành viên Liên Hợp Quốc đều là quốc gia có chủ quyền."},{"type":"compound","zh":"既然是主权国家，它就有权自主决定自己的外交政策。","pinyin":"Jìrán shì Zhǔquánguójiā, tā jiù yǒuquán zìzhǔ juédìng zìjǐ de wàijiāo zhèngcè.","vi":"Đã là quốc gia có chủ quyền thì nước đó có quyền tự quyết định chính sách ngoại giao của mình."}],"related":[{"hanzi":"主权","pinyin":"zhǔquán","vi":"chủ quyền"},{"hanzi":"领土完整","pinyin":"lǐngtǔwánzhěng","vi":"toàn vẹn lãnh thổ"},{"hanzi":"独立","pinyin":"dúlì","vi":"độc lập"},{"hanzi":"国家","pinyin":"guójiā","vi":"quốc gia"}],"traditional":"主權國家"},{"id":"最低工资","hanzi":"最低工资","pinyin":"zuìdīgōngzī","meaning_vi":"mức lương tối thiểu","explanation":"最低 (tối đê – thấp nhất) + 工资 (công tư – tiền lương) → mức lương thấp nhất người lao động được hưởng theo luật. Cụm: 最低工资标准.","hsk_level":"7-9","tags":["danh-tu","cong-viec","tien-te"],"image":"💵","examples":[{"type":"basic","zh":"最低工资又提高了。","pinyin":"Zuì dī gōngzī yòu tígāo le.","vi":"Mức lương tối thiểu lại được nâng lên."},{"type":"simple","zh":"这家餐厅付给员工的薪水低于最低工资标准。","pinyin":"Zhè jiā cāntīng fùgěi yuángōng de xīnshuǐ dīyú zuì dī gōngzī biāozhǔn.","vi":"Tiền lương nhà hàng này trả cho nhân viên thấp hơn mức lương tối thiểu."},{"type":"compound","zh":"如果最低工资涨得太快，一些小企业就会承受不了。","pinyin":"Rúguǒ zuì dī gōngzī zhǎng de tài kuài, yìxiē xiǎoqǐyè jiù huì chéngshòu bùliǎo.","vi":"Nếu mức lương tối thiểu tăng quá nhanh, một số doanh nghiệp nhỏ sẽ không chịu nổi."}],"related":[{"hanzi":"工资","pinyin":"gōngzī","vi":"tiền lương"},{"hanzi":"最低生活保障","pinyin":"zuì dī shēnghuó bǎozhàng","vi":"trợ cấp mức sống tối thiểu"},{"hanzi":"薪水","pinyin":"xīnshui","vi":"lương"},{"hanzi":"加薪","pinyin":"jiāxīn","vi":"tăng lương"}],"traditional":"最低工資"},{"id":"造纸术","hanzi":"造纸术","pinyin":"zàozhǐshù","meaning_vi":"kỹ thuật làm giấy","explanation":"造纸 + 术 (kỹ thuật).","hsk_level":"7-9","tags":["danh-tu","van-hoa","khoa-hoc"],"image":"📜","examples":[{"type":"basic","zh":"蔡伦改进了造纸术。","pinyin":"Càilún gǎijìnle zàozhǐshù.","vi":"Thái Luân đã cải tiến kỹ thuật làm giấy."},{"type":"simple","zh":"孩子们在博物馆里亲手体验了古代造纸术。","pinyin":"Háizimen zài bówùguǎn lǐ qīnshǒu tǐyànle gǔdài zàozhǐshù.","vi":"Bọn trẻ đã tự tay trải nghiệm kỹ thuật làm giấy cổ đại trong bảo tàng."},{"type":"compound","zh":"自从造纸术传到欧洲，书籍的成本就大大降低了。","pinyin":"Zìcóng zàozhǐshù chuán dào Ōuzhōu, shūjí de chéngběn jiù dàdà jiàngdī le.","vi":"Từ khi kỹ thuật làm giấy truyền sang châu Âu, giá thành sách vở đã giảm đi đáng kể."}],"related":[{"hanzi":"四大发明","pinyin":"sìdàfāmíng","vi":"tứ đại phát minh"},{"hanzi":"蔡伦","pinyin":"Càilún","vi":"Thái Luân"},{"hanzi":"印刷术","pinyin":"yìnshuāshù","vi":"kỹ thuật in"},{"hanzi":"纸张","pinyin":"zhǐzhāng","vi":"giấy"}],"traditional":"造紙術"},{"id":"杂费","hanzi":"杂费","pinyin":"záfèi","meaning_vi":"phụ phí, các khoản phí lặt vặt","explanation":"杂 (lặt vặt) + 费.","hsk_level":"7-9","tags":["danh-tu","tien-te"],"image":"🧾","examples":[{"type":"basic","zh":"杂费另外收取。","pinyin":"Záfèi lìngwài shōuqǔ.","vi":"Phụ phí được thu riêng."},{"type":"simple","zh":"房东每个月还要额外收一百块杂费。","pinyin":"Fángdōng měi gèyuè hái yào éwài shōu yī bǎi kuài záfèi.","vi":"Mỗi tháng chủ nhà còn thu thêm một trăm tệ phụ phí."},{"type":"compound","zh":"学费虽然不贵，但是加上各种杂费就不便宜了。","pinyin":"Xuéfèi suīrán bú guì, dànshì jiāshàng gèzhǒng záfèi jiù bù piányi le.","vi":"Học phí tuy không đắt, nhưng cộng thêm các khoản phí lặt vặt thì không hề rẻ."}],"related":[{"hanzi":"学杂费","pinyin":"xuézáfèi","vi":"học phí và phụ phí"},{"hanzi":"手续费","pinyin":"shǒuxùfèi","vi":"phí thủ tục"},{"hanzi":"费用","pinyin":"fèiyong","vi":"chi phí"},{"hanzi":"学费","pinyin":"xuéfèi","vi":"học phí"}],"traditional":"雜費"},{"id":"责任感","hanzi":"责任感","pinyin":"zérèngǎn","meaning_vi":"tinh thần trách nhiệm","explanation":"责 (trách nhiệm/trách móc) + 任 (nhiệm vụ/bổ nhiệm) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","con-nguoi","cong-viec"],"image":"⚖️","examples":[{"type":"basic","zh":"他很有责任感。","pinyin":"Tā hěn yǒu zérèngǎn.","vi":"Anh ấy rất có tinh thần trách nhiệm."},{"type":"simple","zh":"养宠物可以培养孩子的责任感。","pinyin":"Yǎng chǒngwù kěyǐ péiyǎng háizi de zérèngǎn.","vi":"Nuôi thú cưng có thể bồi dưỡng tinh thần trách nhiệm cho trẻ."},{"type":"compound","zh":"正是因为有强烈的责任感，所以她每天最后一个离开办公室。","pinyin":"Zhèngshì yīnwèi yǒu qiángliè de zérèngǎn, suǒyǐ tā měitiān zuìhòu yí gè líkāi bàngōngshì.","vi":"Chính vì có tinh thần trách nhiệm cao nên ngày nào cô ấy cũng là người cuối cùng rời văn phòng."}],"related":[{"hanzi":"责任心","pinyin":"zérènxīn","vi":"tinh thần trách nhiệm"},{"hanzi":"使命感","pinyin":"shǐmìnggǎn","vi":"tinh thần sứ mệnh"},{"hanzi":"担当","pinyin":"dāndāng","vi":"gánh vác"},{"hanzi":"不负责任","pinyin":"búfùzérèn","vi":"vô trách nhiệm"}],"traditional":"責任感"},{"id":"自动化","hanzi":"自动化","pinyin":"zìdònghuà","meaning_vi":"tự động hóa","explanation":"自动 (tự động) + 化 (hóa – biến thành) → quá trình làm cho máy móc, dây chuyền tự vận hành, không cần con người điều khiển trực tiếp.","hsk_level":"7-9","tags":["dong-tu","cong-nghe","cong-viec"],"image":"🤖","examples":[{"type":"basic","zh":"生产线已经自动化了。","pinyin":"Shēngchǎnxiàn yǐjīng zìdònghuà le.","vi":"Dây chuyền sản xuất đã được tự động hóa."},{"type":"simple","zh":"会计用自动化软件几分钟就做完了月报。","pinyin":"Kuàijì yòng zìdònghuà ruǎnjiàn jǐ fēnzhōng jiù zuò wánle yuèbào.","vi":"Kế toán dùng phần mềm tự động hóa chỉ mất vài phút là làm xong báo cáo tháng."},{"type":"compound","zh":"自动化虽然提高了效率，但是也让一些工人失去了岗位。","pinyin":"Zìdònghuà suīrán tígāole xiàolǜ, dànshì yě ràng yìxiē gōngrén shīqùle gǎngwèi.","vi":"Tự động hóa tuy nâng cao hiệu suất, nhưng cũng khiến một số công nhân mất việc."}],"related":[{"hanzi":"自动","pinyin":"zìdòng","vi":"tự động"},{"hanzi":"智能化","pinyin":"zhìnénghuà","vi":"thông minh hóa"},{"hanzi":"机器人","pinyin":"jīqìrén","vi":"người máy"},{"hanzi":"手动","pinyin":"shǒudòng","vi":"thủ công"}],"traditional":"自動化"},{"id":"自媒体","hanzi":"自媒体","pinyin":"zìméitǐ","meaning_vi":"truyền thông cá nhân (YouTuber/TikToker/Blogger)","explanation":"自 (tự thân) + 媒体.","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📱","examples":[{"type":"basic","zh":"他在做自媒体。","pinyin":"Tā zài zuò zìméitǐ.","vi":"Anh ấy đang làm truyền thông cá nhân."},{"type":"simple","zh":"她辞职后开了一个分享旅行经验的自媒体账号。","pinyin":"Tā cízhí hòu kāile yí gè fēnxiǎng lǚxíng jīngyàn de zìméitǐ zhànghào.","vi":"Sau khi nghỉ việc, cô ấy mở một kênh truyền thông cá nhân chia sẻ kinh nghiệm du lịch."},{"type":"compound","zh":"自媒体虽然门槛低，但是想做出影响力并不容易。","pinyin":"Zìméitǐ suīrán ménkǎn dī, dànshì xiǎng zuòchū yǐngxiǎnglì bìngbù róngyì.","vi":"Truyền thông cá nhân tuy dễ bắt đầu, nhưng muốn tạo được sức ảnh hưởng thì chẳng hề dễ."}],"related":[{"hanzi":"博主","pinyin":"bózhǔ","vi":"blogger"},{"hanzi":"短视频","pinyin":"duǎnshìpín","vi":"video ngắn"},{"hanzi":"网红","pinyin":"wǎnghóng","vi":"người nổi tiếng mạng"},{"hanzi":"传统媒体","pinyin":"chuántǒngméitǐ","vi":"truyền thông truyền thống"}],"traditional":"自媒體"},{"id":"自然保护区","hanzi":"自然保护区","pinyin":"zìrán bǎohùqū","meaning_vi":"khu bảo tồn thiên nhiên","explanation":"自 (tự chủ/tự hào) + 然 (然) + 保 (保) + 护 (护) + 区 (区).","hsk_level":"7-9","tags":["danh-tu","thien-nhien","dia-diem"],"image":"🐼","examples":[{"type":"basic","zh":"这里是自然保护区。","pinyin":"Zhèlǐ shì zìránbǎohùqū.","vi":"Đây là khu bảo tồn thiên nhiên."},{"type":"simple","zh":"大熊猫在卧龙自然保护区里自由生活。","pinyin":"Dàxióngmāo zài Wòlóngzìránbǎohùqū lǐ zìyóu shēnghuó.","vi":"Gấu trúc sống tự do trong khu bảo tồn thiên nhiên Ngọa Long."},{"type":"compound","zh":"游客一旦进入自然保护区，就不能随便采摘植物。","pinyin":"Yóukè yídàn jìnrù zìránbǎohùqū, jiù bù néng suíbiàn cǎizhāi zhíwù.","vi":"Du khách một khi đã vào khu bảo tồn thiên nhiên thì không được tùy tiện hái cây cỏ."}],"related":[{"hanzi":"国家公园","pinyin":"guójiāgōngyuán","vi":"vườn quốc gia"},{"hanzi":"野生动物","pinyin":"yěshēngdòngwù","vi":"động vật hoang dã"},{"hanzi":"生态","pinyin":"shēngtài","vi":"sinh thái"},{"hanzi":"保护","pinyin":"bǎohù","vi":"bảo vệ"}],"traditional":"自然保護區"},{"id":"自然灾害","hanzi":"自然灾害","pinyin":"zìránzāihài","meaning_vi":"thiên tai","explanation":"自 (tự chủ/tự hào) + 然 (然) + 灾 (thiên tai/thảm họa) + 害 (害).","hsk_level":"7-9","tags":["danh-tu","thien-nhien"],"image":"⛈️","examples":[{"type":"basic","zh":"自然灾害难以预测。","pinyin":"Zìránzāihài nányǐ yùcè.","vi":"Thiên tai khó dự đoán."},{"type":"simple","zh":"这个山区每年夏天都会遭受洪涝等自然灾害。","pinyin":"Zhè ge shānqū měinián xiàtiān dōuhuì zāoshòu hónglào děng zìránzāihài.","vi":"Vùng núi này mùa hè năm nào cũng gặp thiên tai như lũ lụt."},{"type":"compound","zh":"只要提前做好预警，自然灾害造成的损失就能大大减少。","pinyin":"Zhǐyào tíqián zuò hǎo yùjǐng, zìránzāihài zàochéng de sǔnshī jiù néng dàdà jiǎnshǎo.","vi":"Chỉ cần cảnh báo sớm, thiệt hại do thiên tai gây ra có thể giảm đi rất nhiều."}],"related":[{"hanzi":"地震","pinyin":"dìzhèn","vi":"động đất"},{"hanzi":"洪水","pinyin":"hóngshuǐ","vi":"lũ lụt"},{"hanzi":"台风","pinyin":"táifēng","vi":"bão"},{"hanzi":"干旱","pinyin":"gānhàn","vi":"hạn hán"}],"traditional":"自然災害"},{"id":"自我调节","hanzi":"自我调节","pinyin":"zìwǒtiáojié","meaning_vi":"tự điều chỉnh tâm lý","explanation":"自 (tự chủ/tự hào) + 我 (tôi) + 调 (điều chỉnh/hòa giải) + 节 (节).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🧘","examples":[{"type":"basic","zh":"她善于自我调节。","pinyin":"Tā shànyú zìwǒtiáojié.","vi":"Cô ấy giỏi tự điều chỉnh tâm lý."},{"type":"simple","zh":"考前焦虑时，他用深呼吸来自我调节。","pinyin":"Kǎo qián jiāolǜ shí, tāyòng shēnhūxī lái zìwǒtiáojié.","vi":"Khi lo lắng trước kỳ thi, cậu ấy dùng cách hít thở sâu để tự điều chỉnh."},{"type":"compound","zh":"如果学不会自我调节，工作压力就会慢慢压垮一个人。","pinyin":"Rúguǒ xué bú huì zìwǒtiáojié, gōngzuò yālì jiù huì mànmàn yākuǎ yígèrén.","vi":"Nếu không học được cách tự điều chỉnh, áp lực công việc sẽ dần dần đè bẹp một con người."}],"related":[{"hanzi":"调节","pinyin":"tiáojié","vi":"điều tiết"},{"hanzi":"情绪管理","pinyin":"qíngxùguǎnlǐ","vi":"quản lý cảm xúc"},{"hanzi":"自我控制","pinyin":"zìwǒkòngzhì","vi":"tự kiểm soát"},{"hanzi":"减压","pinyin":"jiǎnyā","vi":"giảm áp lực"}],"traditional":"自我調節"},{"id":"自由贸易区","hanzi":"自由贸易区","pinyin":"zìyóu màoyì qū","meaning_vi":"khu vực mậu dịch tự do (FTA)","explanation":"自由 (tự do) + 贸易 (mậu dịch – buôn bán) + 区 (khu) → khu vực mậu dịch tự do, nơi giảm hoặc miễn thuế quan. Gọi tắt 自贸区.","hsk_level":"7-9","tags":["danh-tu","cong-viec","dia-diem"],"image":"🌐","examples":[{"type":"basic","zh":"这里设立了自由贸易区。","pinyin":"Zhèlǐ shèlìle zìyóumàoyìqū.","vi":"Nơi đây đã thành lập khu vực mậu dịch tự do."},{"type":"simple","zh":"很多外国企业在海南自由贸易区设立了办事处。","pinyin":"Hěn duō wàiguó qǐyè zài Hǎinán zìyóumàoyìqū shèlìle bànshìchù.","vi":"Nhiều doanh nghiệp nước ngoài đã đặt văn phòng đại diện tại khu thương mại tự do Hải Nam."},{"type":"compound","zh":"因为自由贸易区内进口商品免关税，所以价格比外面便宜。","pinyin":"Yīnwèi zìyóumàoyìqū nèi jìnkǒu shāngpǐn miǎn guānshuì, suǒyǐ jiàgé bǐ wàimiàn piányi.","vi":"Vì hàng nhập khẩu trong khu thương mại tự do được miễn thuế quan nên giá rẻ hơn bên ngoài."}],"related":[{"hanzi":"自贸区","pinyin":"zìmàoqū","vi":"khu thương mại tự do"},{"hanzi":"关税","pinyin":"guānshuì","vi":"thuế quan"},{"hanzi":"贸易","pinyin":"màoyì","vi":"thương mại"},{"hanzi":"保税区","pinyin":"bǎoshuìqū","vi":"khu ngoại quan"}],"traditional":"自由貿易區"},{"id":"自尊心","hanzi":"自尊心","pinyin":"zìzūnxīn","meaning_vi":"lòng tự trọng","explanation":"自 (tự chủ/tự hào) + 尊 (tôn nghiêm/tôn trọng) + 心 (tâm lý/tâm huyết).","hsk_level":"7-9","tags":["danh-tu","cam-xuc","con-nguoi"],"image":"👑","examples":[{"type":"basic","zh":"别伤害孩子的自尊心。","pinyin":"Bié shānghài háizi de zìzūnxīn.","vi":"Đừng làm tổn thương lòng tự trọng của trẻ."},{"type":"simple","zh":"老师当众批评他，让他的自尊心受到了打击。","pinyin":"Lǎoshī dāngzhòng pīpíng tā, ràng tā de zìzūnxīn shòudàole dǎjī.","vi":"Thầy giáo phê bình cậu trước mặt mọi người khiến lòng tự trọng của cậu bị tổn thương."},{"type":"compound","zh":"因为自尊心太强，所以他宁可饿着也不愿向朋友借钱。","pinyin":"Yīnwèi zìzūnxīn tài qiáng, suǒyǐ tā nìngkě èzhe yě búyuàn xiàng péngyou jièqián.","vi":"Vì lòng tự trọng quá cao nên anh ấy thà chịu đói chứ không muốn vay tiền bạn bè."}],"related":[{"hanzi":"自尊","pinyin":"zìzūn","vi":"tự trọng"},{"hanzi":"自信心","pinyin":"zìxìnxīn","vi":"lòng tự tin"},{"hanzi":"虚荣心","pinyin":"xūróngxīn","vi":"tính hư vinh"},{"hanzi":"面子","pinyin":"miànzi","vi":"thể diện"}]},{"id":"增强现实","hanzi":"增强现实","pinyin":"zēngqiángxiànshí","meaning_vi":"thực tế tăng cường (AR)","explanation":"增 (tăng thêm) + 强 (cường đại/nhấn mạnh) + 现 (hiện thực/hiện trường) + 实 (thực tế/thực chất).","hsk_level":"7-9","tags":["danh-tu","cong-nghe"],"image":"📱","examples":[{"type":"basic","zh":"这款游戏用了增强现实。","pinyin":"Zhè kuǎn yóuxì yòngle zēngqiángxiànshí.","vi":"Trò chơi này sử dụng thực tế tăng cường."},{"type":"simple","zh":"这本儿童绘本加入了增强现实互动内容。","pinyin":"Zhè běn értóng huìběn jiārùle zēngqiángxiànshí hùdòng nèiróng.","vi":"Cuốn sách tranh thiếu nhi này đã thêm nội dung tương tác thực tế tăng cường."},{"type":"compound","zh":"只要打开增强现实功能，你就能看到沙发摆在自家客厅里的样子。","pinyin":"Zhǐyào dǎkāi zēngqiángxiànshí gōngnéng, nǐ jiù néng kàndào shāfā bǎi zài zìjiā kètīng lǐ de yàngzi.","vi":"Chỉ cần bật tính năng thực tế tăng cường, bạn sẽ thấy chiếc sofa đặt trong phòng khách nhà mình trông thế nào."}],"related":[{"hanzi":"虚拟现实","pinyin":"xūnǐxiànshí","vi":"thực tế ảo"},{"hanzi":"元宇宙","pinyin":"yuányǔzhòu","vi":"vũ trụ ảo"},{"hanzi":"智能眼镜","pinyin":"zhìnéngyǎnjìng","vi":"kính thông minh"},{"hanzi":"科技","pinyin":"kējì","vi":"khoa học công nghệ"}],"traditional":"增強現實"},{"id":"资产负债表","hanzi":"资产负债表","pinyin":"zīchǎn fùzhài biǎo","meaning_vi":"bảng cân đối kế toán","explanation":"资产 (tư sản – tài sản) + 负债 (phụ trái – nợ phải trả) + 表 (biểu – bảng) → bảng cân đối kế toán, phản ánh tài sản, nợ và vốn chủ sở hữu.","hsk_level":"7-9","tags":["danh-tu","tien-te","cong-viec"],"image":"📑","examples":[{"type":"basic","zh":"请看资产负债表。","pinyin":"Qǐngkàn zīchǎnfùzhàibiǎo.","vi":"Mời xem bảng cân đối kế toán."},{"type":"simple","zh":"会计正在核对年底的资产负债表。","pinyin":"Kuàijì zhèngzài héduì niándǐ de zīchǎnfùzhàibiǎo.","vi":"Kế toán đang đối chiếu bảng cân đối kế toán cuối năm."},{"type":"compound","zh":"只要看懂资产负债表，你就能大致判断一家公司的财务状况。","pinyin":"Zhǐyào kàndǒng zīchǎnfùzhàibiǎo, nǐ jiù néng dàzhì pànduàn yìjiā gōngsī de cáiwù zhuàngkuàng.","vi":"Chỉ cần đọc hiểu bảng cân đối kế toán, bạn có thể đánh giá sơ bộ tình hình tài chính của một công ty."}],"related":[{"hanzi":"资产","pinyin":"zīchǎn","vi":"tài sản"},{"hanzi":"负债","pinyin":"fùzhài","vi":"nợ phải trả"},{"hanzi":"利润表","pinyin":"lìrùnbiǎo","vi":"báo cáo lãi lỗ"},{"hanzi":"会计","pinyin":"kuàijì","vi":"kế toán"}],"traditional":"資產負債表"},{"id":"尊师重道","hanzi":"尊师重道","pinyin":"zūnshī-zhòngdào","meaning_vi":"tôn sư trọng đạo","explanation":"尊师 + 重道. Thành ngữ giáo dục.","hsk_level":"7-9","tags":["thanh-ngu","hoc-tap"],"image":"🧑‍🏫","examples":[{"type":"basic","zh":"学生要尊师重道。","pinyin":"Xuéshēng yào zūnshīzhòngdào.","vi":"Học trò phải tôn sư trọng đạo."},{"type":"simple","zh":"尊师重道是中华民族的传统美德。","pinyin":"Zūnshīzhòngdào shì Zhōnghuámínzú de chuántǒng měidé.","vi":"Tôn sư trọng đạo là truyền thống tốt đẹp của dân tộc Trung Hoa."},{"type":"compound","zh":"因为这个村子一向尊师重道，所以老师在村里很受尊敬。","pinyin":"Yīnwèi zhè ge cūnzi yíxiàng zūnshīzhòngdào, suǒyǐ lǎoshī zài cūnlǐ hěn shòu zūnjìng.","vi":"Vì ngôi làng này xưa nay luôn tôn sư trọng đạo nên thầy giáo rất được kính trọng trong làng."}],"related":[{"hanzi":"尊敬","pinyin":"zūnjìng","vi":"tôn kính"},{"hanzi":"教师节","pinyin":"Jiàoshījié","vi":"ngày nhà giáo"},{"hanzi":"一日为师终身为父","pinyin":"yī rì wéishī zhōngshēn wéifù","vi":"một ngày làm thầy cả đời làm cha"},{"hanzi":"饮水思源","pinyin":"yǐnshuǐsīyuán","vi":"uống nước nhớ nguồn"}],"traditional":"尊師重道"},{"id":"爱憎分明","hanzi":"爱憎分明","pinyin":"àizēng-fēnmíng","meaning_vi":"yêu ghét rõ ràng, rạch ròi","explanation":"爱 (yêu) + 憎 (ghét) + 分明 (rõ ràng).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"⚖️","examples":[{"type":"basic","zh":"她为人爱憎分明。","pinyin":"Tā wéirén àizēngfēnmíng.","vi":"Cô ấy là người yêu ghét rạch ròi."},{"type":"simple","zh":"小说里的这位侠客爱憎分明，深受读者喜爱。","pinyin":"Xiǎoshuō lǐ de zhè wèi xiákè àizēngfēnmíng, shēnshòu dúzhě xǐ'ài.","vi":"Vị hiệp khách trong tiểu thuyết này yêu ghét rõ ràng, được độc giả rất yêu thích."},{"type":"compound","zh":"爷爷虽然脾气很好，但是对是非问题一向爱憎分明。","pinyin":"Yéye suīrán píqi hěn hǎo, dànshì duì shìfēi wèntí yíxiàng àizēngfēnmíng.","vi":"Ông nội tuy tính tình hiền hòa, nhưng trước chuyện đúng sai luôn yêu ghét rạch ròi."}],"related":[{"hanzi":"是非分明","pinyin":"shìfēifēnmíng","vi":"phân rõ phải trái"},{"hanzi":"黑白分明","pinyin":"hēibáifēnmíng","vi":"trắng đen rõ ràng"},{"hanzi":"疾恶如仇","pinyin":"jí'èrúchóu","vi":"ghét cái ác như thù"},{"hanzi":"是非不分","pinyin":"shìfēibùfēn","vi":"không phân phải trái"}],"traditional":"愛憎分明"},{"id":"按部就班","hanzi":"按部就班","pinyin":"ànbù-jiùbān","meaning_vi":"tuần tự từng bước theo đúng quy trình","explanation":"按部就班: theo đúng bộ phận, vào đúng hàng ban (部 bộ, 班 ban – thứ tự, vị trí) → làm việc theo trình tự từng bước; đôi khi hàm ý rập khuôn, thiếu linh hoạt.","hsk_level":"7-9","tags":["thanh-ngu","cong-viec"],"image":"📋","examples":[{"type":"basic","zh":"一切按部就班进行。","pinyin":"Yíqiè ànbùjiùbān jìnxíng.","vi":"Mọi việc diễn ra tuần tự theo đúng quy trình."},{"type":"simple","zh":"装修队按部就班地完成了水电和墙面工程。","pinyin":"Zhuāngxiū duì ànbùjiùbān de wánchéngle shuǐdiàn hé qiángmiàn gōngchéng.","vi":"Đội thi công đã lần lượt hoàn thành hạng mục điện nước và tường theo đúng trình tự."},{"type":"compound","zh":"遇到突发情况时，如果还按部就班，就会错过最佳时机。","pinyin":"Yùdào tūfā qíngkuàng shí, rúguǒ hái ànbùjiùbān, jiù huì cuòguò zuì jiā shíjī.","vi":"Khi gặp tình huống bất ngờ, nếu vẫn cứ làm tuần tự theo lối cũ thì sẽ bỏ lỡ thời cơ tốt nhất."}],"related":[{"hanzi":"循序渐进","pinyin":"xúnxùjiànjìn","vi":"tuần tự từng bước"},{"hanzi":"有条不紊","pinyin":"yǒutiáobùwěn","vi":"ngăn nắp trật tự"},{"hanzi":"一步一个脚印","pinyin":"yí bù yí gè jiǎoyìn","vi":"từng bước vững chắc"},{"hanzi":"急于求成","pinyin":"jíyúqiúchéng","vi":"nóng vội"}]},{"id":"暗淡","hanzi":"暗淡","pinyin":"àndàn","meaning_vi":"ảm đạm, mờ nhạt, thiếu sức sống","explanation":"暗 (tối) + 淡 (nhạt).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌫️","examples":[{"type":"basic","zh":"灯光很暗淡。","pinyin":"Dēngguāng hěn àndàn.","vi":"Ánh đèn rất mờ nhạt."},{"type":"simple","zh":"失业后他觉得自己的前途一片暗淡。","pinyin":"Shīyè hòu tā juéde zìjǐ de qiántú yípiàn àndàn.","vi":"Sau khi thất nghiệp, anh ấy cảm thấy tương lai của mình thật ảm đạm."},{"type":"compound","zh":"那颗星星虽然看起来暗淡，但是其实比太阳还大。","pinyin":"Nà kē xīngxing suīrán kànqǐlái àndàn, dànshì qíshí bǐ tàiyáng hái dà.","vi":"Ngôi sao đó tuy trông mờ nhạt, nhưng thực ra còn lớn hơn cả Mặt Trời."}],"related":[{"hanzi":"黯淡","pinyin":"àndàn","vi":"ảm đạm"},{"hanzi":"昏暗","pinyin":"hūn'àn","vi":"tối tăm"},{"hanzi":"明亮","pinyin":"míngliàng","vi":"sáng sủa"},{"hanzi":"灰暗","pinyin":"huī'àn","vi":"u ám"}]},{"id":"暗渡陈仓","hanzi":"暗渡陈仓","pinyin":"àndù-chéncāng","meaning_vi":"ám độ Trần Thương (ngấm ngầm hành động bí mật)","explanation":"Binh pháp / Thành ngữ lịch sử.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"♟️","examples":[{"type":"basic","zh":"他们暗渡陈仓。","pinyin":"Tāmen àndùchéncāng.","vi":"Bọn họ ngấm ngầm hành động."},{"type":"simple","zh":"他用暗渡陈仓的办法悄悄转移了公司资产。","pinyin":"Tāyòng àndùchéncāng de bànfǎ qiāoqiāo zhuǎnyíle gōngsī zīchǎn.","vi":"Hắn dùng kế 'ám độ Trần Thương' lặng lẽ tẩu tán tài sản công ty."},{"type":"compound","zh":"对手虽然表面上同意和解，但是背后一直在暗渡陈仓。","pinyin":"Duìshǒu suīrán biǎomiànshang tóngyì héjiě, dànshì bèihòu yìzhí zài àndùchéncāng.","vi":"Đối thủ tuy bề ngoài đồng ý hòa giải, nhưng sau lưng vẫn luôn ngấm ngầm hành động."}],"related":[{"hanzi":"声东击西","pinyin":"shēngdōngjīxī","vi":"dương đông kích tây"},{"hanzi":"三十六计","pinyin":"sānshíliùjì","vi":"ba mươi sáu kế"},{"hanzi":"明修栈道","pinyin":"míngxiūzhàndào","vi":"công khai sửa đường sạn"},{"hanzi":"偷偷摸摸","pinyin":"tōutōumōmō","vi":"lén lút"}],"traditional":"暗渡陳倉"},{"id":"暗箭伤人","hanzi":"暗箭伤人","pinyin":"ànjiàn-shāngrén","meaning_vi":"bắn tên ngầm hại người, hãm hại sau lưng","explanation":"暗箭伤人: bắn tên lén để hại người (暗 ám – ngầm, 箭 tiễn – mũi tên) → ngấm ngầm hãm hại người khác sau lưng. Liên quan: 明枪易躲，暗箭难防.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🏹","examples":[{"type":"basic","zh":"他喜欢暗箭伤人。","pinyin":"Tā xǐhuan ànjiànshāngrén.","vi":"Hắn thích ngấm ngầm hãm hại người khác."},{"type":"simple","zh":"我最看不起在背后暗箭伤人的小人。","pinyin":"Wǒ zuì kànbùqǐ zài bèihòu ànjiànshāngrén de xiǎorén.","vi":"Tôi khinh nhất loại tiểu nhân hãm hại người khác sau lưng."},{"type":"compound","zh":"如果你对我有意见，就当面说，不要暗箭伤人。","pinyin":"Rúguǒ nǐ duì wǒ yǒu yìjiàn, jiù dāngmiàn shuō, bú yào ànjiànshāngrén.","vi":"Nếu anh có ý kiến gì với tôi thì cứ nói thẳng, đừng ngấm ngầm hại người."}],"related":[{"hanzi":"背后捅刀","pinyin":"bèihòutǒngdāo","vi":"đâm sau lưng"},{"hanzi":"明枪易躲暗箭难防","pinyin":"míng qiāng yì duǒ ànjiàn nán fáng","vi":"giáo đâm dễ tránh tên ngầm khó phòng"},{"hanzi":"陷害","pinyin":"xiànhài","vi":"hãm hại"},{"hanzi":"光明正大","pinyin":"guāngmíngzhèngdà","vi":"quang minh chính đại"}],"traditional":"暗箭傷人"},{"id":"按揭","hanzi":"按揭","pinyin":"ànjiē","meaning_vi":"vay thế chấp mua nhà/xe (trả góp ngân hàng)","explanation":"Từ phiên âm tiếng Anh 'mortgage'.","hsk_level":"7-9","tags":["danh-tu","tien-te","nha-cua"],"image":"🏠","examples":[{"type":"basic","zh":"他们按揭买了房。","pinyin":"Tāmen ànjiē mǎile fáng.","vi":"Họ đã mua nhà trả góp qua ngân hàng."},{"type":"simple","zh":"这套公寓的按揭还要再还二十年。","pinyin":"Zhè tào gōngyù de ànjiē hái yào zài huán èrshí nián.","vi":"Khoản vay thế chấp căn hộ này còn phải trả thêm hai mươi năm nữa."},{"type":"compound","zh":"虽然每月按揭压力不小，但是有了自己的家心里很踏实。","pinyin":"Suīrán měiyuè ànjiē yālì bù xiǎo, dànshì yǒule zìjǐ de jiā xīnlǐ hěn tāshi.","vi":"Tuy áp lực trả góp mỗi tháng không nhỏ, nhưng có được ngôi nhà của riêng mình nên trong lòng rất yên tâm."}],"related":[{"hanzi":"贷款","pinyin":"dàikuǎn","vi":"vay tiền"},{"hanzi":"房贷","pinyin":"fángdài","vi":"vay mua nhà"},{"hanzi":"首付","pinyin":"shǒufù","vi":"tiền trả trước"},{"hanzi":"月供","pinyin":"yuègōng","vi":"trả góp hàng tháng"}]},{"id":"按图索骥","hanzi":"按图索骥","pinyin":"àntú-suǒjì","meaning_vi":"tìm ngựa theo tranh (làm việc máy móc theo khuôn mẫu)","explanation":"Điển tích cổ. Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🐎","examples":[{"type":"basic","zh":"做事不能按图索骥。","pinyin":"Zuòshì bù néng àntúsuǒjì.","vi":"Làm việc không thể rập khuôn máy móc."},{"type":"simple","zh":"我们拿着旧地图按图索骥找到了那家老店。","pinyin":"Wǒmen názhe jiù dìtú àntúsuǒjì zhǎodàole nà jiālǎo diàn.","vi":"Chúng tôi cầm tấm bản đồ cũ lần theo chỉ dẫn và tìm được cửa tiệm lâu đời đó."},{"type":"compound","zh":"如果只会按图索骥地照搬教材，就解决不了实际问题。","pinyin":"Rúguǒ zhǐ huì àntúsuǒjì de zhàobān jiàocái, jiù jiějué bùliǎo shíjì wèntí.","vi":"Nếu chỉ biết rập khuôn máy móc theo giáo trình thì không giải quyết được vấn đề thực tế."}],"related":[{"hanzi":"照本宣科","pinyin":"zhàoběnxuānkē","vi":"đọc nguyên văn sách"},{"hanzi":"生搬硬套","pinyin":"shēngbānyìngtào","vi":"rập khuôn máy móc"},{"hanzi":"墨守成规","pinyin":"mòshǒuchéngguī","vi":"khư khư lệ cũ"},{"hanzi":"灵活变通","pinyin":"línghuóbiàntōng","vi":"linh hoạt biến hóa"}],"traditional":"按圖索驥"},{"id":"暗箱操作","hanzi":"暗箱操作","pinyin":"ànxiāngcāozuò","meaning_vi":"thao túng ngầm, thiếu minh bạch","explanation":"暗箱 (hộp tối) + 操作 (thao tác).","hsk_level":"7-9","tags":["danh-tu","cong-viec","xa-hoi"],"image":"🕵️","examples":[{"type":"basic","zh":"招标存在暗箱操作。","pinyin":"Zhāobiāo cúnzài ànxiāngcāozuò.","vi":"Việc đấu thầu có sự thao túng ngầm."},{"type":"simple","zh":"记者揭露了这次选拔中的暗箱操作。","pinyin":"Jìzhě jiēlùle zhè cì xuǎnbá zhōng de ànxiāngcāozuò.","vi":"Phóng viên đã vạch trần sự thao túng ngầm trong đợt tuyển chọn lần này."},{"type":"compound","zh":"只要整个过程公开透明，暗箱操作就没有空间。","pinyin":"Zhǐyào zhěnggè guòchéng gōngkāi tòumíng, ànxiāngcāozuò jiù méiyǒu kōngjiān.","vi":"Chỉ cần toàn bộ quy trình công khai minh bạch, việc thao túng ngầm sẽ không có đất sống."}],"related":[{"hanzi":"黑幕","pinyin":"hēimù","vi":"màn đen khuất tất"},{"hanzi":"内幕","pinyin":"nèimù","vi":"nội tình"},{"hanzi":"透明度","pinyin":"tòumíngdù","vi":"độ minh bạch"},{"hanzi":"公开透明","pinyin":"gōngkāitòumíng","vi":"công khai minh bạch"}]},{"id":"盎然","hanzi":"盎然","pinyin":"àngrán","meaning_vi":"tràn đầy, dạt dào (sức sống/hứng thú)","explanation":"Cụm: 生机盎然 (tràn đầy sức sống).","hsk_level":"7-9","tags":["tinh-tu"],"image":"🌱","examples":[{"type":"basic","zh":"校园里春意盎然。","pinyin":"Xiàoyuán lǐ chūnyì àngrán.","vi":"Khuôn viên trường tràn đầy sắc xuân."},{"type":"simple","zh":"孩子们兴趣盎然地观察着水缸里的小蝌蚪。","pinyin":"Háizimen xìngqù àngrán de guāncházhe shuǐgāng lǐ de xiǎo kēdǒu.","vi":"Bọn trẻ hứng thú dạt dào quan sát những chú nòng nọc trong chum nước."},{"type":"compound","zh":"一场春雨过后，山坡上就变得绿意盎然。","pinyin":"Yì chǎng chūnyǔ guòhòu, shānpō shang jiù biànde lǜ yì àngrán.","vi":"Sau một trận mưa xuân, sườn đồi đã trở nên xanh tươi tràn đầy sức sống."}],"related":[{"hanzi":"生机盎然","pinyin":"shēngjī'àngrán","vi":"tràn đầy sức sống"},{"hanzi":"兴趣盎然","pinyin":"xìngqù'àngrán","vi":"đầy hứng thú"},{"hanzi":"春意盎然","pinyin":"chūnyì'àngrán","vi":"ngập tràn sắc xuân"},{"hanzi":"浓厚","pinyin":"nónghòu","vi":"nồng hậu"}]},{"id":"奥秘无穷","hanzi":"奥秘无穷","pinyin":"àomìwúqióng","meaning_vi":"bí ẩn vô tận","explanation":"奥秘 (huyền bí) + 无穷 (vô tận).","hsk_level":"7-9","tags":["tinh-tu","khoa-hoc"],"image":"🌌","examples":[{"type":"basic","zh":"宇宙奥秘无穷。","pinyin":"Yǔzhòu àomìwúqióng.","vi":"Vũ trụ bí ẩn vô tận."},{"type":"simple","zh":"深海世界奥秘无穷，吸引着无数科学家。","pinyin":"Shēnhǎi shìjiè àomìwúqióng, xīyǐnzhe wúshù kēxuéjiā.","vi":"Thế giới biển sâu bí ẩn vô tận, thu hút vô số nhà khoa học."},{"type":"compound","zh":"人体虽然看似普通，但是其实奥秘无穷。","pinyin":"Réntǐ suīrán kànsì pǔtōng, dànshì qíshí àomìwúqióng.","vi":"Cơ thể con người tuy trông bình thường, nhưng thực ra ẩn chứa vô vàn bí ẩn."}],"related":[{"hanzi":"奥秘","pinyin":"àomì","vi":"bí ẩn"},{"hanzi":"神秘","pinyin":"shénmì","vi":"thần bí"},{"hanzi":"无穷","pinyin":"wúqióng","vi":"vô tận"},{"hanzi":"探索","pinyin":"tànsuǒ","vi":"khám phá"}],"traditional":"奧秘無窮"},{"id":"皑皑","hanzi":"皑皑","pinyin":"ái'ái","meaning_vi":"trắng xóa (tuyết trắng)","explanation":"Lặp lại chữ 皑. Cụm: 白雪皑皑.","hsk_level":"7-9","tags":["tinh-tu","thoi-tiet"],"image":"❄️","examples":[{"type":"basic","zh":"山顶白雪皑皑。","pinyin":"Shāndǐng báixuě ái'ái.","vi":"Đỉnh núi tuyết trắng xóa."},{"type":"simple","zh":"我们坐缆车俯瞰皑皑的雪原。","pinyin":"Wǒmen zuò lǎnchē fǔkàn ái'ái de xuěyuán.","vi":"Chúng tôi ngồi cáp treo ngắm nhìn cánh đồng tuyết trắng xóa bên dưới."},{"type":"compound","zh":"一到冬天，长白山上就是一片白雪皑皑的景象。","pinyin":"Yí dào dōngtiān, Chángbáishān shang jiùshì yípiàn báixuě ái'ái de jǐngxiàng.","vi":"Cứ đến mùa đông, núi Trường Bạch lại là một cảnh tượng tuyết phủ trắng xóa."}],"related":[{"hanzi":"白雪皑皑","pinyin":"báixuě'ái'ái","vi":"tuyết trắng xóa"},{"hanzi":"洁白","pinyin":"jiébái","vi":"trắng tinh"},{"hanzi":"雪白","pinyin":"xuěbái","vi":"trắng như tuyết"},{"hanzi":"银装素裹","pinyin":"yínzhuāngsùguǒ","vi":"phủ một màu bạc"}],"traditional":"皚皚"},{"id":"遨游","hanzi":"遨游","pinyin":"áoyóu","meaning_vi":"du ngoạn, bay lượn tự do (vũ trụ/biển cả)","explanation":"遨 (dạo chơi) + 游 (bơi/du lịch). Cụm: 遨游太空.","hsk_level":"7-9","tags":["dong-tu","khoa-hoc"],"image":"🚀","examples":[{"type":"basic","zh":"雄鹰在天空遨游。","pinyin":"Xióngyīng zài tiānkōng áoyóu.","vi":"Chim ưng bay lượn tự do trên bầu trời."},{"type":"simple","zh":"爱读书的人可以在知识的海洋里自由遨游。","pinyin":"Ài dúshū de rén kěyǐ zài zhīshi de hǎiyáng lǐ zìyóu áoyóu.","vi":"Người thích đọc sách có thể tự do du ngoạn trong biển tri thức."},{"type":"compound","zh":"如果有一天能遨游太空，我一定要拍下地球的样子。","pinyin":"Rúguǒ yǒu yì tiān néng áoyóu tàikōng, wǒ yídìngyào pāi xià dìqiú de yàngzi.","vi":"Nếu một ngày nào đó được du hành vũ trụ, tôi nhất định sẽ chụp lại hình ảnh Trái Đất."}],"related":[{"hanzi":"翱翔","pinyin":"áoxiáng","vi":"bay lượn"},{"hanzi":"畅游","pinyin":"chàngyóu","vi":"tha hồ du ngoạn"},{"hanzi":"遨游太空","pinyin":"áoyóutàikōng","vi":"du hành vũ trụ"},{"hanzi":"漫游","pinyin":"mànyóu","vi":"đi dạo chơi"}],"traditional":"遨遊"},{"id":"恶势力","hanzi":"恶势力","pinyin":"èshìlì","meaning_vi":"thế lực xấu xa","explanation":"恶 (恶) + 势 (thế lực/xu thế) + 力 (sức mạnh/nỗ lực).","hsk_level":"7-9","tags":["danh-tu","xa-hoi","phap-luat"],"image":"🦹","examples":[{"type":"basic","zh":"警方打击恶势力。","pinyin":"Jǐngfāng dǎjī èshìlì.","vi":"Cảnh sát trấn áp các thế lực xấu xa."},{"type":"simple","zh":"这个村子曾经被一伙恶势力控制了多年。","pinyin":"Zhè ge cūnzi céngjīng bèi yì huǒ èshìlì kòngzhìle duōnián.","vi":"Ngôi làng này từng bị một băng nhóm thế lực đen tối khống chế nhiều năm."},{"type":"compound","zh":"只要群众敢于举报，恶势力就无处藏身。","pinyin":"Zhǐyào qúnzhòng gǎnyú jǔbào, èshìlì jiù wúchù cángshēn.","vi":"Chỉ cần quần chúng dám tố giác, thế lực xấu xa sẽ không có chỗ ẩn thân."}],"related":[{"hanzi":"黑社会","pinyin":"hēishèhuì","vi":"xã hội đen"},{"hanzi":"扫黑除恶","pinyin":"sǎohēichú'è","vi":"trấn áp tội phạm"},{"hanzi":"邪恶","pinyin":"xié'è","vi":"tà ác"},{"hanzi":"正义","pinyin":"zhèngyì","vi":"chính nghĩa"}],"traditional":"惡勢力"},{"id":"恶性竞争","hanzi":"恶性竞争","pinyin":"èxìngjìngzhēng","meaning_vi":"cạnh tranh không lành mạnh","explanation":"恶性 (ác tính – có tính chất xấu) + 竞争 (cạnh tranh) → cạnh tranh không lành mạnh như phá giá, chèn ép, gây hại cho cả thị trường.","hsk_level":"7-9","tags":["danh-tu","cong-viec"],"image":"⚔️","examples":[{"type":"basic","zh":"行业恶性竞争严重。","pinyin":"Hángyè èxìngjìngzhēng yánzhòng.","vi":"Cạnh tranh không lành mạnh trong ngành rất nghiêm trọng."},{"type":"simple","zh":"几家外卖平台陷入了疯狂补贴的恶性竞争。","pinyin":"Jǐ jiā wàimài píngtái xiànrùle fēngkuáng bǔtiē de èxìngjìngzhēng.","vi":"Vài nền tảng giao đồ ăn đã sa vào cuộc cạnh tranh không lành mạnh bằng trợ giá điên cuồng."},{"type":"compound","zh":"恶性竞争不但压低了利润，而且拉低了产品质量。","pinyin":"Èxìngjìngzhēng búdàn yādīle lìrùn, érqiě lā dīle chǎnpǐn zhìliàng.","vi":"Cạnh tranh không lành mạnh không chỉ làm giảm lợi nhuận mà còn kéo chất lượng sản phẩm đi xuống."}],"related":[{"hanzi":"良性竞争","pinyin":"liángxìngjìngzhēng","vi":"cạnh tranh lành mạnh"},{"hanzi":"价格战","pinyin":"jiàgézhàn","vi":"cuộc chiến giá cả"},{"hanzi":"内卷","pinyin":"nèijuǎn","vi":"cạnh tranh nội bộ khốc liệt"},{"hanzi":"竞争","pinyin":"jìngzhēng","vi":"cạnh tranh"}],"traditional":"惡性競爭"},{"id":"恶性循环","hanzi":"恶性循环","pinyin":"èxìngxúnhuán","meaning_vi":"vòng luẩn quẩn tiêu cực","explanation":"恶性 (ác tính – xấu) + 循环 (tuần hoàn – vòng lặp) → vòng luẩn quẩn, mỗi vòng lại tệ hơn. Trái nghĩa: 良性循环.","hsk_level":"7-9","tags":["danh-tu","xa-hoi"],"image":"🔄","examples":[{"type":"basic","zh":"这是个恶性循环。","pinyin":"Zhè shì gè èxìngxúnhuán.","vi":"Đây là một vòng luẩn quẩn."},{"type":"simple","zh":"熬夜和失眠让他陷入了恶性循环。","pinyin":"Áoyè hé shīmián ràng tā xiànrùle èxìngxúnhuán.","vi":"Thức khuya và mất ngủ khiến anh ấy rơi vào vòng luẩn quẩn."},{"type":"compound","zh":"一旦形成恶性循环，问题就会越来越难解决。","pinyin":"Yídàn xíngchéng èxìngxúnhuán, wèntí jiù huì yuèláiyuè nán jiějué.","vi":"Một khi đã rơi vào vòng luẩn quẩn, vấn đề sẽ ngày càng khó giải quyết."}],"related":[{"hanzi":"良性循环","pinyin":"liángxìngxúnhuán","vi":"vòng tuần hoàn tích cực"},{"hanzi":"循环","pinyin":"xúnhuán","vi":"tuần hoàn"},{"hanzi":"恶化","pinyin":"èhuà","vi":"xấu đi"},{"hanzi":"怪圈","pinyin":"guàiquān","vi":"vòng luẩn quẩn"}],"traditional":"惡性循環"},{"id":"恶意","hanzi":"恶意","pinyin":"èyì","meaning_vi":"ác ý","explanation":"恶 (恶) + 意 (ý thức/ý nghĩa).","hsk_level":"7-9","tags":["danh-tu","tinh-tu"],"image":"😠","examples":[{"type":"basic","zh":"他没有恶意。","pinyin":"Tā méiyǒu èyì.","vi":"Anh ấy không có ác ý."},{"type":"simple","zh":"有人在网上恶意散布明星的隐私。","pinyin":"Yǒurén zài wǎngshàng èyì sànbù míngxīng de yǐnsī.","vi":"Có kẻ ác ý phát tán thông tin riêng tư của người nổi tiếng trên mạng."},{"type":"compound","zh":"他的话虽然不好听，但是并没有恶意。","pinyin":"Tā dehuà suīrán bù hǎotīng, dànshì bìng méiyǒu èyì.","vi":"Lời anh ấy nói tuy khó nghe, nhưng không hề có ác ý."}],"related":[{"hanzi":"善意","pinyin":"shànyì","vi":"thiện ý"},{"hanzi":"敌意","pinyin":"díyì","vi":"thù địch"},{"hanzi":"恶意中伤","pinyin":"èyìzhòngshāng","vi":"ác ý vu khống"},{"hanzi":"故意","pinyin":"gùyì","vi":"cố ý"}],"traditional":"惡意"},{"id":"二十四节气","hanzi":"二十四节气","pinyin":"èr shísì jiéqì","meaning_vi":"24 tiết khí trong năm","explanation":"Di sản văn hóa phi vật thể.","hsk_level":"7-9","tags":["danh-tu","van-hoa","thoi-gian"],"image":"📅","examples":[{"type":"basic","zh":"二十四节气很有用。","pinyin":"Èrshísìjiéqì hěn yǒuyòng.","vi":"Hai mươi bốn tiết khí rất hữu ích."},{"type":"simple","zh":"农民按照二十四节气安排播种和收割。","pinyin":"Nóngmín ànzhào èrshísìjiéqì ānpái bōzhǒng hé shōugē.","vi":"Nông dân sắp xếp gieo trồng và thu hoạch theo hai mươi bốn tiết khí."},{"type":"compound","zh":"二十四节气不但指导农业生产，而且影响着人们的饮食习惯。","pinyin":"Èrshísìjiéqì búdàn zhǐdǎo nóngyè shēngchǎn, érqiě yǐngxiǎngzhe rénmen de yǐnshí xíguàn.","vi":"Hai mươi bốn tiết khí không chỉ hướng dẫn sản xuất nông nghiệp mà còn ảnh hưởng đến thói quen ăn uống của con người."}],"related":[{"hanzi":"节气","pinyin":"jiéqi","vi":"tiết khí"},{"hanzi":"立春","pinyin":"Lìchūn","vi":"Lập Xuân"},{"hanzi":"冬至","pinyin":"Dōngzhì","vi":"Đông Chí"},{"hanzi":"农历","pinyin":"nónglì","vi":"âm lịch"}],"traditional":"二十四節氣"},{"id":"哀悼","hanzi":"哀悼","pinyin":"āidào","meaning_vi":"tưởng niệm, thương tiếc (người đã khuất)","explanation":"哀 (bi thương) + 悼 (tưởng nhớ).","hsk_level":"7-9","tags":["dong-tu","van-hoa"],"image":"🕯️","examples":[{"type":"basic","zh":"全国降半旗哀悼。","pinyin":"Quánguó jiàngbànqí āidào.","vi":"Cả nước treo cờ rủ để tưởng niệm."},{"type":"simple","zh":"人们在广场上点起蜡烛哀悼遇难者。","pinyin":"Rénmen zài guǎngchǎng shang diǎn qǐ làzhú āidào yùnànzhě.","vi":"Mọi người thắp nến trên quảng trường để tưởng niệm các nạn nhân."},{"type":"compound","zh":"因为老校长不幸去世，所以全校师生默哀三分钟表示哀悼。","pinyin":"Yīnwèi lǎo xiàozhǎng búxìng qùshì, suǒyǐ quán xiào shīshēng mò'āi sān fēnzhōng biǎoshì āidào.","vi":"Vì thầy hiệu trưởng cũ không may qua đời nên toàn thể thầy trò mặc niệm ba phút để tỏ lòng thương tiếc."}],"related":[{"hanzi":"悼念","pinyin":"dàoniàn","vi":"tưởng niệm"},{"hanzi":"默哀","pinyin":"mò'āi","vi":"mặc niệm"},{"hanzi":"追悼会","pinyin":"zhuīdàohuì","vi":"lễ truy điệu"},{"hanzi":"缅怀","pinyin":"miǎnhuái","vi":"tưởng nhớ"}]},{"id":"哀求","hanzi":"哀求","pinyin":"āiqiú","meaning_vi":"van xin, khẩn cầu thảm thiết","explanation":"哀 (bi ai) + 求 (cầu xin).","hsk_level":"7-9","tags":["dong-tu","cam-xuc"],"image":"🙏","examples":[{"type":"basic","zh":"他苦苦哀求妈妈。","pinyin":"Tā kǔkǔ āiqiú māma.","vi":"Cậu bé khổ sở van xin mẹ."},{"type":"simple","zh":"小女孩哀求爸爸不要把小狗送走。","pinyin":"Xiǎo nǚhái āiqiú bàba bú yào bǎ xiǎogǒu sòngzǒu.","vi":"Cô bé van xin bố đừng đem chú chó con đi cho."},{"type":"compound","zh":"尽管他再三哀求，房东还是坚持让他月底搬走。","pinyin":"Jǐnguǎn tā zàisān āiqiú, fángdōng háishì jiānchí ràng tā yuèdǐ bānzǒu.","vi":"Dù anh ấy năn nỉ hết lần này đến lần khác, chủ nhà vẫn kiên quyết bắt anh dọn đi vào cuối tháng."}],"related":[{"hanzi":"恳求","pinyin":"kěnqiú","vi":"khẩn cầu"},{"hanzi":"乞求","pinyin":"qǐqiú","vi":"cầu xin"},{"hanzi":"央求","pinyin":"yāngqiú","vi":"nài nỉ"},{"hanzi":"苦苦哀求","pinyin":"kǔkǔ'āiqiú","vi":"khẩn khoản van xin"}]},{"id":"安分守己","hanzi":"安分守己","pinyin":"ānfèn-shǒujǐ","meaning_vi":"an phận thủ thường, sống đúng bổn phận","explanation":"安分守己: yên với phận mình, giữ lấy bản thân (安 an, 分 phận, 守 thủ, 己 kỷ) → sống đúng bổn phận, tuân thủ quy củ, không làm điều trái phép.","hsk_level":"7-9","tags":["thanh-ngu"],"image":"🕊️","examples":[{"type":"basic","zh":"他一向安分守己。","pinyin":"Tā yíxiàng ānfènshǒujǐ.","vi":"Anh ấy xưa nay luôn an phận thủ thường."},{"type":"simple","zh":"这位安分守己的老实人从来没跟人吵过架。","pinyin":"Zhè wèi ānfènshǒujǐ de lǎoshirén cónglái méi gēn rén chǎoguo jià.","vi":"Người thật thà an phận này chưa bao giờ cãi nhau với ai."},{"type":"compound","zh":"他虽然一辈子安分守己，但是晚年还是被骗走了积蓄。","pinyin":"Tā suīrán yíbèizi ānfènshǒujǐ, dànshì wǎnnián háishì bèi piànzǒule jīxù.","vi":"Tuy cả đời sống an phận thủ thường, nhưng về già ông ấy vẫn bị lừa mất tiền tiết kiệm."}],"related":[{"hanzi":"循规蹈矩","pinyin":"xúnguīdǎojǔ","vi":"tuân thủ phép tắc"},{"hanzi":"本分","pinyin":"běnfèn","vi":"bổn phận"},{"hanzi":"老实","pinyin":"lǎoshi","vi":"thật thà"},{"hanzi":"胡作非为","pinyin":"húzuòfēiwéi","vi":"làm càn"}]},{"id":"安抚人心","hanzi":"安抚人心","pinyin":"ānfǔrénxīn","meaning_vi":"trấn an lòng người","explanation":"安抚 (xoa dịu) + 人心 (lòng người).","hsk_level":"7-9","tags":["dong-tu","xa-hoi"],"image":"🤗","examples":[{"type":"basic","zh":"政府出面安抚人心。","pinyin":"Zhèngfǔ chūmiàn ānfǔrénxīn.","vi":"Chính quyền đứng ra trấn an lòng người."},{"type":"simple","zh":"市长在电视上发表讲话安抚人心。","pinyin":"Shìzhǎng zài diànshì shang fābiǎo jiǎnghuà ānfǔrénxīn.","vi":"Thị trưởng phát biểu trên truyền hình để trấn an lòng người."},{"type":"compound","zh":"地震发生后，只有尽快公布真实信息，才能安抚人心。","pinyin":"Dìzhèn fāshēng hòu, zhǐyǒu jǐnkuài gōngbù zhēnshí xìnxī, cáinéng ānfǔrénxīn.","vi":"Sau động đất, chỉ có công bố thông tin chân thực sớm nhất mới có thể trấn an lòng người."}],"related":[{"hanzi":"安抚","pinyin":"ānfǔ","vi":"vỗ về trấn an"},{"hanzi":"稳定人心","pinyin":"wěndìngrénxīn","vi":"ổn định lòng người"},{"hanzi":"安慰","pinyin":"ānwèi","vi":"an ủi"},{"hanzi":"人心惶惶","pinyin":"rénxīnhuánghuáng","vi":"lòng người hoang mang"}],"traditional":"安撫人心"},{"id":"安全感","hanzi":"安全感","pinyin":"ānquángǎn","meaning_vi":"cảm giác an toàn","explanation":"安 (安) + 全 (toàn diện/đầy đủ) + 感 (感).","hsk_level":"7-9","tags":["danh-tu","cam-xuc"],"image":"🛡️","examples":[{"type":"basic","zh":"他给我安全感。","pinyin":"Tā gěi wǒ ānquángǎn.","vi":"Anh ấy cho tôi cảm giác an toàn."},{"type":"simple","zh":"小婴儿抱着妈妈的衣服才有安全感。","pinyin":"Xiǎo yīng'ér bàozhe māma de yīfu cái yǒu ānquángǎn.","vi":"Em bé phải ôm áo của mẹ mới có cảm giác an toàn."},{"type":"compound","zh":"因为小时候经常搬家，所以她一直缺乏安全感。","pinyin":"Yīnwèi xiǎoshíhou jīngcháng bānjiā, suǒyǐ tā yìzhí quēfá ānquángǎn.","vi":"Vì hồi nhỏ thường xuyên chuyển nhà nên cô ấy luôn thiếu cảm giác an toàn."}],"related":[{"hanzi":"安全","pinyin":"ānquán","vi":"an toàn"},{"hanzi":"归属感","pinyin":"guīshǔgǎn","vi":"cảm giác thuộc về"},{"hanzi":"信任","pinyin":"xìnrèn","vi":"tín nhiệm"},{"hanzi":"不安","pinyin":"bù'ān","vi":"bất an"}]},{"id":"安土重迁","hanzi":"安土重迁","pinyin":"āntǔ-zhòngqiān","meaning_vi":"gắn bó với quê cũ, ngại di dời","explanation":"安土 + 重迁 (ngại di chuyển). Thành ngữ.","hsk_level":"7-9","tags":["thanh-ngu","van-hoa"],"image":"🏡","examples":[{"type":"basic","zh":"老人大多安土重迁。","pinyin":"Lǎorén dàduō āntǔzhòngqiān.","vi":"Người già phần lớn gắn bó với quê cũ, ngại dời đi."},{"type":"simple","zh":"安土重迁的观念在农村依然很普遍。","pinyin":"Āntǔzhòngqiān de guānniàn zài nóngcūn yīrán hěn pǔbiàn.","vi":"Quan niệm gắn bó quê cha đất tổ, ngại di dời vẫn còn rất phổ biến ở nông thôn."},{"type":"compound","zh":"爷爷安土重迁，即使儿女在城里买了房，他也不肯搬过去。","pinyin":"Yéye āntǔzhòngqiān, jíshǐ érnǚ zài chénglǐ mǎile fáng, tā yě bùkěn bān guòqù.","vi":"Ông nội vốn gắn bó với quê cũ, dù con cái đã mua nhà trên thành phố, ông cũng không chịu chuyển lên."}],"related":[{"hanzi":"故土难离","pinyin":"gùtǔnánlí","vi":"khó rời quê cũ"},{"hanzi":"落叶归根","pinyin":"luòyèguīgēn","vi":"lá rụng về cội"},{"hanzi":"背井离乡","pinyin":"bèijǐnglíxiāng","vi":"tha hương"},{"hanzi":"乡土","pinyin":"xiāngtǔ","vi":"quê hương"}],"traditional":"安土重遷"},{"id":"耳目一新","hanzi":"耳目一新","pinyin":"ěrmù-yìxīn","meaning_vi":"cảm thấy mới mẻ thú vị (tai mắt đổi mới)","explanation":"耳 (耳) + 目 (mục tiêu/ánh mắt) + 一 (số 1) + 新 (mới).","hsk_level":"7-9","tags":["thanh-ngu"],"image":"✨","examples":[{"type":"basic","zh":"新设计让人耳目一新。","pinyin":"Xīn shèjì ràng rén ěrmùyìxīn.","vi":"Thiết kế mới khiến người ta cảm thấy mới mẻ."},{"type":"simple","zh":"重新装修后的图书馆让读者耳目一新。","pinyin":"Chóngxīn zhuāngxiū hòu de túshūguǎn ràng dúzhě ěrmùyìxīn.","vi":"Thư viện sau khi được sửa sang lại khiến độc giả có cảm giác hoàn toàn mới mẻ."},{"type":"compound","zh":"这部电影一上映，就以耳目一新的叙事方式赢得了好评。","pinyin":"Zhè bù diànyǐng yí shàngyìng, jiù yǐ ěrmùyìxīn de xùshì fāngshì yíng déle hǎopíng.","vi":"Bộ phim này vừa công chiếu đã giành được nhiều lời khen nhờ cách kể chuyện mới lạ."}],"related":[{"hanzi":"焕然一新","pinyin":"huànrányìxīn","vi":"đổi mới hoàn toàn"},{"hanzi":"面目一新","pinyin":"miànmùyìxīn","vi":"diện mạo mới"},{"hanzi":"新颖","pinyin":"xīnyǐng","vi":"mới lạ"},{"hanzi":"老生常谈","pinyin":"lǎoshēngchángtán","vi":"chuyện cũ rích"}]},{"id":"殴打","hanzi":"殴打","pinyin":"ōudǎ","meaning_vi":"đánh đập","explanation":"殴 (ẩu – đánh, ẩu đả) + 打 (đả – đánh) → đánh đập người khác, thường dùng trong văn bản pháp lý, tin tức. Ví dụ: 遭到殴打.","hsk_level":"7-9","tags":["dong-tu","phap-luat"],"image":"🥊","examples":[{"type":"basic","zh":"他被人殴打了。","pinyin":"Tā bèi rén ōudǎ le.","vi":"Anh ấy bị người ta đánh đập."},{"type":"simple","zh":"两名男子因在酒吧殴打服务员被警方拘留。","pinyin":"Liǎng míng nánzǐ yīn zài jiǔbā ōudǎ fúwùyuán bèi jǐngfāng jūliú.","vi":"Hai người đàn ông bị cảnh sát tạm giữ vì đánh đập nhân viên phục vụ ở quán bar."},{"type":"compound","zh":"即使对方先骂人，你也不能动手殴打他。","pinyin":"Jíshǐ duìfāng xiān màrén, nǐ yě bù néng dòngshǒu ōudǎ tā.","vi":"Dù đối phương chửi trước, bạn cũng không được ra tay đánh người ta."}],"related":[{"hanzi":"打架","pinyin":"dǎjià","vi":"đánh nhau"},{"hanzi":"斗殴","pinyin":"dòu'ōu","vi":"ẩu đả"},{"hanzi":"暴力","pinyin":"bàolì","vi":"bạo lực"},{"hanzi":"拳打脚踢","pinyin":"quándǎjiǎotī","vi":"đấm đá"}],"traditional":"毆打"},{"id":"蔼然","hanzi":"蔼然","pinyin":"ǎirán","meaning_vi":"hòa nhã, ôn hòa","explanation":"蔼 (hiền hòa) + 然.","hsk_level":"7-9","tags":["tinh-tu","con-nguoi"],"image":"😊","examples":[{"type":"basic","zh":"老人蔼然一笑。","pinyin":"Lǎorén ǎirán yí xiào.","vi":"Ông cụ mỉm cười hiền hòa."},{"type":"simple","zh":"老校长蔼然可亲地和新生们握手。","pinyin":"Lǎo xiàozhǎng ǎirán kěqīn dehé xīnshēngmen wòshǒu.","vi":"Thầy hiệu trưởng già hòa nhã, thân thiện bắt tay các tân sinh viên."},{"type":"compound","zh":"他虽然地位很高，但是对待下属总是蔼然可亲。","pinyin":"Tā suīrán dìwèi hěn gāo, dànshì duìdài xiàshǔ zǒngshì ǎirán kěqīn.","vi":"Tuy địa vị rất cao, nhưng ông ấy đối xử với cấp dưới luôn hòa nhã dễ gần."}],"related":[{"hanzi":"和蔼","pinyin":"hé'ǎi","vi":"hòa nhã"},{"hanzi":"和蔼可亲","pinyin":"hé'ǎikěqīn","vi":"hiền hòa dễ gần"},{"hanzi":"慈祥","pinyin":"cíxiáng","vi":"hiền từ"},{"hanzi":"温和","pinyin":"wēnhé","vi":"ôn hòa"}],"traditional":"藹然"},{"id":"偶然性","hanzi":"偶然性","pinyin":"ǒuránxìng","meaning_vi":"tính ngẫu nhiên","explanation":"偶 (ngẫu nhiên/thần tượng) + 然 (然) + 性 (tính chất/tính cách).","hsk_level":"7-9","tags":["danh-tu","khoa-hoc"],"image":"🎲","examples":[{"type":"basic","zh":"这件事有偶然性。","pinyin":"Zhè jiàn shì yǒu ǒuránxìng.","vi":"Việc này mang tính ngẫu nhiên."},{"type":"simple","zh":"很多科学发现都带有一定的偶然性。","pinyin":"Hěn duō kēxué fāxiàn dōu dàiyǒu yídìng de ǒuránxìng.","vi":"Nhiều phát hiện khoa học đều mang tính ngẫu nhiên nhất định."},{"type":"compound","zh":"一次成功虽然有偶然性，但是连续成功就靠真本事了。","pinyin":"Yí cì chénggōng suīrán yǒu ǒuránxìng, dànshì liánxù chénggōng jiù kào zhēn běnshi le.","vi":"Một lần thành công tuy có tính ngẫu nhiên, nhưng thành công liên tiếp thì phải dựa vào thực lực."}],"related":[{"hanzi":"必然性","pinyin":"bìránxìng","vi":"tính tất yếu"},{"hanzi":"偶然","pinyin":"ǒurán","vi":"ngẫu nhiên"},{"hanzi":"巧合","pinyin":"qiǎohé","vi":"trùng hợp"},{"hanzi":"随机","pinyin":"suíjī","vi":"ngẫu nhiên"}]}];
